INSERT INTO characters (char, data) VALUES ('惫', '{"9000": "3001.0", "Chữ Trung Quốc": "惫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 夂 | Số nét | 12 | nét | 夂 | tri | biểu nghĩa | bước chân chậm, chậm chạp | 思 | tư | biểu âm | suy nghĩ (cho âm bèi) | 惫 (phồn thể 憊) = 夂 (Tri, biểu nghĩa: bước chân chậm, chậm chạp) + 思 (Tư, biểu âm); chữ hình thanh. Bộ tri gợi sự kiệt sức, bước đi nặng nề; 思 cho âm bèi/bài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bại\": bước chân chậm (夂) vì đầu óc đang suy nghĩ quá nhiều (思) — hình ảnh người 疲惫 (bì bại), thân mệt tâm rã. | Gương Hán-Việt | ''bại'' trong ''bại lộ'' ý nghĩa mệt mỏi, tiêu hao; 疲惫 (bì bại — kiệt sức) | Mở khoá kiến thức | Biết 惫 mở khoá: 疲惫 (kiệt sức, mệt mỏi), 疲惫不堪 (kiệt sức đến mức không chịu nổi)", "Tự nguyên_Xie": "惫 (phồn thể 憊) là chữ hình thanh tương đối muộn: bộ 夂 (bước chân chậm) biểu nghĩa trạng thái mệt mỏi, kiệt sức; 思 biểu âm. Wiktionary không có mô tả glyph-origin chi tiết ngoài pronunciation và definition. Nghĩa cốt lõi là ''mệt mỏi, kiệt sức'' (fatigue). Chưa có nguồn học thuật chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỏi mệt", "Hạng Tần Suất (Jun Da)": "3001.0", "Tần Suất % (Jun Da)": "99.1842345103", "GavinGrover_Once (Chiết tự trực tiếp)": "夂 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夂思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "夂", "Unihan_Simplified (Chữ Giản thể)": "惫", "Unihan_Traditional (Chữ Phồn thể)": "憊", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ chỉ trạng thái mệt mỏi, thường kết hợp với phó từ chỉ mức độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摹', '{"9000": "3002.0", "Chữ Trung Quốc": "摹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 摹 | mô | tượng hình | mô phỏng, bắt chước | 摹 gồm 莫 (mạc — biểu âm) + 手 (thủ — tay, biểu nghĩa). Tay (手) làm theo mẫu (莫) — gợi nghĩa dùng tay bắt chước, mô phỏng. Wiktionary không cung cấp phân tích chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mô\": tay (手) theo sát mẫu (莫) từng nét — 摹 (mô) là mô phỏng, sao chép từng chi tiết như luyện thư pháp. | Gương Hán-Việt | \"mô\" xuất hiện trong \"mô phỏng\" (摹仿 — bắt chước), \"lâm mô\" (临摹 — sao chép thư pháp). | Mở khoá kiến thức | Biết 摹 (mô) là nắm được 临摹 (lâm mô — sao chép thư pháp), 摹仿 (mô phỏng — bắt chước), 描摹 (miêu mô — mô tả).", "Tự nguyên_Xie": "摹 có {{Han etym}} nhưng không có phân tích cụ thể trên Wiktionary. Theo cấu trúc, đây là hình thanh: 莫 (biểu âm) + 手 (tay, biểu nghĩa). Nghĩa là mô phỏng, bắt chước bằng tay; đặc biệt dùng trong nghệ thuật thư pháp (mô luyện chữ). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mô phỏng, bắt chước", "Hạng Tần Suất (Jun Da)": "3002.0", "Tần Suất % (Jun Da)": "99.1852055496", "GavinGrover_Once (Chiết tự trực tiếp)": "莫 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱莫手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "摹", "Unihan_Traditional (Chữ Phồn thể)": "摹", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động sao chép hoặc mô phỏng theo một hình mẫu có sẵn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踱', '{"9000": "3003.0", "Chữ Trung Quốc": "踱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 踱 | đạc | tượng hình | đi thong thả, đi dạo | 踱 gồm 足 (túc — chân, biểu nghĩa) + 度 (độ — biểu âm). Chân (足) bước từng bước đo lường (度) — gợi dáng đi thong thả, đếm từng bước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạc\": chân (足) bước từng bước như đo đạc (度) — 踱 (đạc) là kiểu đi thong thả từ tốn, bách bộ không vội vàng. | Gương Hán-Việt | \"đạc\" ít gặp trong tiếng Việt hiện đại; 踱步 (đạc bộ — đi bách bộ) là cụm phổ biến nhất. | Mở khoá kiến thức | Biết 踱 (đạc) là nhận ra 踱步 (đạc bộ — đi bách bộ, đi tản bộ), 踱来踱去 (đạc lai đạc khứ — đi qua đi lại).", "Tự nguyên_Xie": "踱 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết. Theo cấu trúc: 足 (chân, biểu nghĩa) + 度 (biểu âm). Nghĩa là đi bách bộ, đi thong thả, đi tản bộ chậm rãi. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi bách bộ, đi thong thả, đi dạo, đi tản bộ", "Hạng Tần Suất (Jun Da)": "3003.0", "Tần Suất % (Jun Da)": "99.1861760721", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 度", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊度", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "度", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踱", "Unihan_Traditional (Chữ Phồn thể)": "踱", "Pinyin_Xie": "duó", "Âm Hán Việt_Xie": "đạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đi lại chậm rãi, thường đi kèm bổ ngữ xu hướng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肘', '{"9000": "3004.0", "Chữ Trung Quốc": "肘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 寸 | thốn | biểu âm | 肘 = 肉/月 (Nhục — thịt/cơ thể, biểu nghĩa) + 寸 (Thốn, biểu âm); chữ hình thanh. Ban đầu viết như 寸 là tượng hình cái khuỷu. Sau thêm 肉 để phân biệt. Gợi vị trí khuỷu tay trên cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩu\": thịt (肉) ở vị trí \"tấc\" (寸) — 肘 (chẩu) là khuỷu tay, điểm gập của cánh tay, quan trọng như mọi \"tấc\" đất. | Gương Hán-Việt | \"chẩu\" ít gặp riêng lẻ; 掣肘 (chế chẩu — bị cản trở, kéo khuỷu tay) là thành ngữ quan trọng. | Mở khoá kiến thức | Biết 肘 (chẩu) là nhận ra 肘子 (chẩu tử — chân giò), 掣肘 (chế chẩu — cản trở, không cho tự do hành động).", "Tự nguyên_Xie": "Theo Wiktionary, 肘 là hình thanh: 肉 (thịt/cơ thể, biểu nghĩa) + 寸 (thốn, biểu âm). Ban đầu, chữ này được viết là 寸, là tượng hình tay (又) với nét vạch chỉ vị trí khuỷu tay. Do hình dạng quá giống 寸 (tấc), sau thêm 肉 để phân biệt. Nghĩa là khuỷu tay. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuỷu tay", "Hạng Tần Suất (Jun Da)": "3004.0", "Tần Suất % (Jun Da)": "99.1871460778", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 寸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月寸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肘", "Unihan_Traditional (Chữ Phồn thể)": "肘", "Pinyin_Xie": "zhǒu", "Âm Hán Việt_Xie": "trửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận khuỷu tay trên cơ thể người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熔', '{"9000": "3005.0", "Chữ Trung Quốc": "熔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 火 | hoả | biểu nghĩa | lửa | 容 | dung | biểu âm | 熔 = 火 (Hoả — lửa, biểu nghĩa) + 容 (Dung, biểu âm); chữ hình thanh. Lửa (火) làm nóng chảy vật rắn — gợi nghĩa nung chảy, nấu chảy kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dong\": lửa (火) dung hóa (容) tất cả — 熔 (dong) là nung chảy, hòa tan kim loại cứng trong sức nóng. | Gương Hán-Việt | \"dong\" ít gặp riêng lẻ; 熔化 (dong hóa — nóng chảy) là cụm cơ bản nhất. | Mở khoá kiến thức | Biết 熔 (dong) là nhận ra 熔化 (dong hóa — nóng chảy), 熔点 (dong điểm — điểm nóng chảy), 熔炉 (dong lô — lò nấu chảy).", "Tự nguyên_Xie": "Theo Wiktionary, 熔 là hình thanh: 火 (lửa, biểu nghĩa) + 容 (dung, biểu âm). Nghĩa là nung chảy, làm nóng đến mức chảy ra; dùng chủ yếu trong luyện kim (熔化 — nóng chảy, 熔点 — điểm nóng chảy). Chưa có hình ảnh giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "456.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (140) Dung (322)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hỏa (số 86 - ngọn lửa) và chữ Dung (số 132 - bao dung) . Dùng ngọn lửa (Hỏa) có sức nóng nung chảy, hòa tan, bao dung (Dung) các vật cứng gọi là nung chảy (dung). Giải thích sự chuyển ý: Chữ Dung (bao dung) chỉ âm, chữ Hỏa (lửa) chỉ ý. Quá trình chất rắn bị nung nóng (Hỏa) chuyển sang trạng thái lỏng (Dung).", "Nghĩa Tiếng Việt_Xie": "nóng chảy; chảy", "Hạng Tần Suất (Jun Da)": "3005.0", "Tần Suất % (Jun Da)": "99.1881140163", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "熔", "Unihan_Traditional (Chữ Phồn thể)": "熔", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ quá trình kim loại hoặc chất rắn bị nóng chảy dưới nhiệt độ cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挚', '{"9000": "3006.0", "Chữ Trung Quốc": "挚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 执 | chấp | biểu nghĩa | nắm giữ, thực hành | 手 | thủ | biểu nghĩa | tay | 挚 là giản thể của 摯. Phồn thể 摯 gồm 執 (Chấp, ''nắm chặt'') ở trên + 手 (Thủ, tay) ở dưới; hội ý: hai tay nắm chặt lấy — biểu thị sự chân thành, tha thiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chí\": nắm chặt (执) bằng đôi tay (手) — người chí thành là người nắm chặt tình bạn, không bao giờ buông tay. | Gương Hán-Việt | ''chí'' trong ''chân chí'' (thành thật từ tận trong lòng), 真挚 (chân chí — chân thành) | Mở khoá kiến thức | Biết 挚 mở khoá: 真挚 (chân thành), 诚挚 (thành tâm), 挚友 (bạn thân thiết)", "Tự nguyên_Xie": "Giáp cốt văn | Lục thư thông | 挚 (phồn thể 摯) được giản thể hoá từ 摯: 執→执 ở trên, 手 (tay) ở dưới. Phồn thể là hội ý: hành động nắm giữ bằng tay (執) + tay (手) — gợi ý nắm chặt tình cảm, không buông. Giáp cốt văn xác nhận cấu trúc gốc của 摯. Nghĩa gốc là ''nắm chặt''; nghĩa phổ biến là ''chân thành, tha thiết''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân thành", "Hạng Tần Suất (Jun Da)": "3006.0", "Tần Suất % (Jun Da)": "99.1890819549", "GavinGrover_Once (Chiết tự trực tiếp)": "执 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱执手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "挚", "Unihan_Traditional (Chữ Phồn thể)": "摯", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị tình cảm chân thành, thường làm định ngữ tu sức cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氯', '{"9000": "3007.0", "Chữ Trung Quốc": "氯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 12 | nét | 气 | khí | biểu nghĩa | khí, hơi | 彔 | lục | biểu âm | 氯 = 气 (Khí — khí, hơi, biểu nghĩa) + 彔 (Lục, biểu âm; cũng là dạng rút gọn của 綠/xanh lục, gợi màu sắc); chữ hình thanh. Khí (气) + âm 彔 (lục) — đặt tên cho nguyên tố clo có màu vàng lục.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": khí (气) màu lục (彔=綠) — 氯 (lục) là clo, loại khí vàng lục có mùi hắc, dùng trong hóa chất tẩy trắng. | Gương Hán-Việt | \"lục\" ở đây là âm hóa học (clo), khác 綠 (lục — màu xanh); 氯气 (lục khí — khí clo) là từ cơ bản. | Mở khoá kiến thức | Biết 氯 (lục) là nhận ra 氯气 (lục khí — khí clo), 氯化钠 (lục hóa na — natri clorua/muối ăn), 氯化物 (lục hóa vật — chloride).", "Tự nguyên_Xie": "Theo Wiktionary, 氯 là hình thanh: 气 (khí, biểu nghĩa) + 彔 (biểu âm, cũng là dạng rút gọn của 綠 — xanh lục, gợi màu sắc của clo). Đây là chữ Hán được đặt để phiên âm và mô tả nguyên tố clo (Cl), vốn là khí có màu vàng lục, được tổng hợp vào thế kỷ 19. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố clo (ký hiệu: Cl)", "Hạng Tần Suất (Jun Da)": "3007.0", "Tần Suất % (Jun Da)": "99.1900493766", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氯", "Unihan_Traditional (Chữ Phồn thể)": "氯", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ nguyên tố hóa học clo trong các hợp chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凛', '{"9000": "3008.0", "Chữ Trung Quốc": "凛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 15 | nét | 凛 | lẫm | tượng hình | giá rét, nghiêm nghị | 凛 (phồn thể: 凜) gồm 冫(băng — nước đá, biểu nghĩa) + 禀 (bẩm — biểu âm). Băng giá (冫) kết hợp âm 禀 — gợi cái lạnh cắt da, và từ đó gợi vẻ nghiêm nghị, oai nghiêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẫm\": băng (冫) giá lạnh khiến người ta run lẫm lẫm — 凛 (lẫm) là lạnh cắt da hoặc vẻ nghiêm nghị khiến người khác kính sợ. | Gương Hán-Việt | \"lẫm\" xuất hiện trong \"lẫm liệt\" (凛冽 — lạnh buốt giá), \"lẫm nhiên\" (凛然 — nghiêm nghị oai vệ). | Mở khoá kiến thức | Biết 凛 (lẫm) là nắm được 凛冽 (lẫm liệt — lạnh cắt da), 凛然 (lẫm nhiên — nghiêm nghị), 凛凛 (lẫm lẫm — rét lạnh/oai phong).", "Tự nguyên_Xie": "Tiểu triện | 凛 (phồn thể 凜) có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết. Theo cấu trúc: 冫 (băng giá, biểu nghĩa) + 禀 (biểu âm). Nghĩa là giá rét thấu xương; mở rộng sang nghiêm nghị, oai nghiêm (凛然 — nghiêm nghị, 凛冽 — lạnh cắt da). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giá rét; nghiêm nghị", "Hạng Tần Suất (Jun Da)": "3008.0", "Tần Suất % (Jun Da)": "99.1910157649", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 禀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫禀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "凛", "Unihan_Traditional (Chữ Phồn thể)": "凜", "Pinyin_Xie": "lǐn", "Âm Hán Việt_Xie": "lẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để tả khí hậu lạnh giá hoặc thái độ nghiêm nghị. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绎', '{"9000": "3009.0", "Chữ Trung Quốc": "绎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 纟 | mịch | biểu nghĩa | sợi tơ | 𠬤 | dịch | biểu âm | (cho âm yì) | 绎 là giản thể của 繹: 糸→纟(Mịch, biểu nghĩa: sợi tơ) + 睪→𠬤 (biểu âm); chữ hình thanh. Bộ mịch gợi ý ''gỡ mối chỉ, theo dõi sợi dây''; 𠬤 cho âm yì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": gỡ sợi tơ (纟) từng mối một — như nhà diễn 绎 học diễn giải từng luận điểm theo trình tự logic. | Gương Hán-Việt | ''dịch'' trong ''diễn dịch'' (演绎 — suy luận từ tổng quát đến cụ thể), 络绎不绝 (liên tục không ngừng) | Mở khoá kiến thức | Biết 绎 mở khoá: 演绎 (diễn dịch), 络绎不绝 (liên tục không ngừng), 寻绎 (truy tìm, lần theo mối)", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 绎 (phồn thể 繹) là giản thể hoá: 糸→纟 và 睪→𠬤. Phồn thể 繹 là chữ hình thanh: 糸(sợi tơ) biểu nghĩa hành động gỡ mối chỉ, theo đuôi; 睪 biểu âm. Nghĩa gốc là ''rút chỉ ra từ kén tằm, tháo mối''. Từ đó mở rộng sang ''diễn dịch, theo dấu, liên tiếp'' (络绎不绝). Tiểu triện và Lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỡ mối nợ; liền", "Hạng Tần Suất (Jun Da)": "3009.0", "Tần Suất % (Jun Da)": "99.1919821531", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "绎", "Unihan_Traditional (Chữ Phồn thể)": "繹", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ với nghĩa tìm tòi, suy diễn hoặc làm tính từ chỉ sự liên tục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庶', '{"9000": "3010.0", "Chữ Trung Quốc": "庶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 石 | thạch | biểu âm | đá | 火 | hoả | biểu nghĩa | lửa | 庶 = 石 (Thạch — đá, biểu âm theo một thuyết) + 火 (Hoả — lửa, biểu nghĩa). Tuy nhiên, 《Shuowen》 phân tích là 广 (mái nhà) + 炗 (ánh sáng). Wiktionary ghi ls=psc: 石 (biểu âm) + 火 (biểu nghĩa); trong tiểu triện, 石 bị biến dạng. Nghĩa gốc: nhiều người (đám đông) quây quần quanh lửa sưởi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thứ\": nhiều người (庶民 thứ dân) quanh đống lửa (火) — 庶 (thứ) là đông đảo, bình thường; \"thứ\" trong \"thứ dân, thứ dự\" đứng sau chứ không phải trưởng. | Gương Hán-Việt | \"thứ\" xuất hiện trong \"thứ dân\" (庶民 — người thường), \"thứ tử\" (庶子 — con thứ/con ngoài giá thú), \"thứ vụ\" (庶务 — công việc thường ngày). | Mở khoá kiến thức | Biết 庶 (thứ) là nắm được 庶民 (thứ dân — người thường dân), 庶子 (thứ tử — con thứ/con ngoài giá thú), 庶几 (thứ cơ — gần như, hầu như).", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, 庶 là hình thanh với bộ phận 石 (biểu âm) + 火 (lửa, biểu nghĩa). Trong tiểu triện, 石 bị biến dạng thành một dạng khác. Shuowen Jiezi phân tích khác: 广 (mái nhà) + 炗 (ánh sáng). Nghĩa gốc liên quan đến đông đảo, nhiều; mở rộng sang \"庶民\" (thứ dân), \"chi thứ\" (nhánh phụ trong gia tộc), con ngoài giá thú. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều; chi thứ (trong dòng họ), con thứ", "Hạng Tần Suất (Jun Da)": "3010.0", "Tần Suất % (Jun Da)": "99.1929449238", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "庶", "Unihan_Traditional (Chữ Phồn thể)": "庶", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Phó từ | 副词 | Chữ này làm tính từ chỉ số nhiều hoặc danh từ chỉ dòng thứ trong gia tộc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脯', '{"9000": "3011.0", "Chữ Trung Quốc": "脯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 11 | nét | ⺼ | nhục | biểu nghĩa | thịt, cơ thể | 甫 | phủ | biểu âm | 脯 = ⺼ (Nhục — thịt, biểu nghĩa) + 甫 (Phủ, biểu âm); chữ hình thanh. Thịt (⺼) làm khô — gợi nghĩa thịt phơi khô, thịt bảo quản.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phố\": thịt (⺼) được phơi sấy như âm Phủ (甫) — 脯 (phố) là thịt khô, quả sấy khô — loại thực phẩm bảo quản lâu dài. | Gương Hán-Việt | \"phố\" ít gặp trong tiếng Việt hiện đại; 肉脯 (nhục phố — thịt phơi khô), 果脯 (quả phố — mứt sấy) là các từ quan trọng. | Mở khoá kiến thức | Biết 脯 (phố) là nhận ra 果脯 (quả phố — mứt/quả sấy khô), 肉脯 (nhục phố — thịt phơi khô), 胸脯 (hung phố — ngực).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 脯 là hình thanh: ⺼ (nhục — thịt, biểu nghĩa) + 甫 (phủ, biểu âm). Có hai cách đọc: pú (ngực, vú — phần thân trên) và fǔ (thịt khô, quả phơi khô). Nghĩa thông dụng là thịt phơi khô bảo quản hoặc quả sấy khô. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt khô; quả phơi khô", "Hạng Tần Suất (Jun Da)": "3011.0", "Tần Suất % (Jun Da)": "99.1939061441", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脯", "Unihan_Traditional (Chữ Phồn thể)": "脯", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "phù, bô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại thịt hoặc hoa quả sấy khô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迭', '{"9000": "3012.0", "Chữ Trung Quốc": "迭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 辶 | xước | biểu nghĩa | di chuyển, bước đi | 失 | thất | biểu âm | 迭 = 辶 (Xước — di chuyển, bước đi, biểu nghĩa) + 失 (Thất, biểu âm); chữ hình thanh. Bước đi (辶) lặp đi lặp lại, thay nhau — gợi nghĩa luân phiên, thay phiên nhau.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điệt\": bước chân (辶) thay đổi (失→thất) liên tục — 迭 (điệt) là luân phiên nhau, lần lượt thay đổi. | Gương Hán-Việt | \"điệt\" xuất hiện trong \"điệt đại\" (迭代 — thế hệ kế tiếp/lặp đi lặp lại), \"giao điệt\" (交迭 — thay phiên nhau). | Mở khoá kiến thức | Biết 迭 (điệt) là nắm được 迭代 (điệt đại — lặp đi lặp lại, iteration trong IT), 交迭 (giao điệt — thay phiên), 迭起 (điệt khởi — liên tiếp xảy ra).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 迭 là hình thanh: 辶 (di chuyển, biểu nghĩa) + 失 (thất, biểu âm). Nghĩa là thay phiên nhau, lần lượt; cũng có nghĩa lấn áp, xâm lấn. Hình ảnh người nọ thay người kia bước đi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thay phiên, lần lượt; xân lấn", "Hạng Tần Suất (Jun Da)": "3012.0", "Tần Suất % (Jun Da)": "99.1948668477", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迭", "Unihan_Traditional (Chữ Phồn thể)": "迭", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Chữ này làm phó từ đứng trước động từ để chỉ hành động xảy ra liên tiếp. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睦', '{"9000": "3013.0", "Chữ Trung Quốc": "睦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 坴 | lục | biểu âm | (cho âm mù) | 睦 = 目 (Mục, biểu nghĩa: mắt) + 坴 (Lục, biểu âm); chữ hình thanh. Bộ mục gợi ánh mắt thân thiện, nhìn nhau hoà hảo; 坴 cho âm mù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mục\": đôi mắt (目) nhìn nhau trực diện mà không có thù hằn — biểu tượng của sự hoà 睦 (mục) trong gia đình, xóm giềng. | Gương Hán-Việt | ''mục'' trong ''hoà mục'' (hài hoà thân thiện), 和睦 (hoà mục — hoà thuận) | Mở khoá kiến thức | Biết 睦 mở khoá: 和睦 (hoà thuận), 睦邻 (láng giềng hoà hảo), 敦睦 (thắt chặt tình đoàn kết)", "Tự nguyên_Xie": "睦 là chữ hình thanh: 目 (mắt) biểu nghĩa nhìn nhau hoà hảo, thân thiện; 坴 biểu âm với âm mù. Nghĩa cốt lõi là ''hoà kính, thân thiện, đoàn kết''. Chưa có nguồn học thuật chi tiết về glyph-origin cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoà kính, tin, thân", "Hạng Tần Suất (Jun Da)": "3013.0", "Tần Suất % (Jun Da)": "99.1958275512", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 坴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目坴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睦", "Unihan_Traditional (Chữ Phồn thể)": "睦", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp với các từ chỉ quan hệ gia đình, hàng xóm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窍', '{"9000": "3014.0", "Chữ Trung Quốc": "窍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 10 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hốc | 巧 | xảo | biểu âm | khéo léo (cho âm qiào) | 窍 là giản thể của 竅: 穴 (Huyệt, biểu nghĩa: lỗ, hốc) + 巧/敫→巧 (biểu âm); chữ hình thanh. Bộ huyệt chỉ lỗ hổng tự nhiên trên cơ thể; 巧 cho âm qiào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếu\": hang (穴) khéo léo (巧) đục vào đúng chỗ — người có thiên khiếu là người tìm được đúng cái lỗ bí mật để mở ra tri thức. | Gương Hán-Việt | ''khiếu'' trong ''thiên khiếu'' (năng khiếu trời phú), 七窍 (bảy khiếu — hai mắt, hai tai, hai lỗ mũi, miệng) | Mở khoá kiến thức | Biết 窍 mở khoá: 窍门 (mẹo, bí quyết), 诀窍 (bí quyết), 七窍 (bảy lỗ hổng của cơ thể)", "Tự nguyên_Xie": "Tiểu triện | 窍 (phồn thể 竅) là giản thể hoá: bộ 穴 (lỗ hốc) + 敫 rút thành 巧 biểu âm. Nghĩa gốc là ''lỗ, hốc trên cơ thể''. Từ nghĩa ''lỗ'' mở rộng sang ''cửa ngõ của tri thức, bí quyết'' (窍门). Tiểu triện xác nhận cấu trúc. Cụm 七窍 (bảy khiếu) là thuật ngữ y học cổ điển Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lỗ, hốc", "Hạng Tần Suất (Jun Da)": "3014.0", "Tần Suất % (Jun Da)": "99.1967867044", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 巧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴巧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窍", "Unihan_Traditional (Chữ Phồn thể)": "竅", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "khiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các lỗ trên cơ thể hoặc ẩn dụ cho mấu chốt vấn đề. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粥', '{"9000": "3015.0", "Chữ Trung Quốc": "粥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 弓 | cung | biểu nghĩa | cung tên (hai cánh bên) | 米 | mễ | biểu nghĩa | gạo, lúa | 粥 là dạng rút gọn của 鬻 — chữ tượng hình và hội ý ban đầu: gạo (米) nằm giữa hai bên cong vòng (弓弓) như hơi bốc ra từ nồi cháo đang sôi. Đây là hội ý: gạo được nấu thành cháo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\": gạo (米) nằm giữa hai cánh cung (弓弓) — hình ảnh nồi cháo sôi với hơi bốc lên hai bên, gợi bữa sáng thanh đạm. | Gương Hán-Việt | ''dục'' ít dùng trong tiếng Việt; biến thể ''chúc'' gặp trong ''cháo chúc'' (từ cổ); nghĩa cháo | Mở khoá kiến thức | Biết 粥 mở khoá: 喝粥 (uống cháo), 一锅粥 (một mớ hỗn độn), 米粥 (cháo gạo)", "Tự nguyên_Xie": "Theo Wiktionary, 粥 là dạng rút gọn của 鬻 — chữ gốc cho nghĩa ''cháo''. Ban đầu là hội ý: hình gạo (米) giữa hai hình cong (như làn hơi hoặc thành nồi). Nghĩa nguyên thủy ''cháo'' hiện bảo tồn trong 薄粥. Chưa có nguồn học thuật chi tiết về glyph-origin cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháo loãng", "Hạng Tần Suất (Jun Da)": "3015.0", "Tần Suất % (Jun Da)": "99.1977448241", "GavinGrover_Once (Chiết tự trực tiếp)": "弜 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弜米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "粥", "Unihan_Traditional (Chữ Phồn thể)": "粥", "Pinyin_Xie": "zhōu", "Âm Hán Việt_Xie": "chúc, dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ món cháo hoặc làm động từ với nghĩa gả bán, nuôi nấng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhōu | / | cháo | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống | New HSK | New HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庵', '{"9000": "3016.0", "Chữ Trung Quốc": "庵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 11 | nét | 广 | nghiễm | biểu nghĩa | mái nhà, chái nhà nhỏ | 奄 | yểm | biểu âm | 庵 = 广 (Nghiễm — mái nhà/chái nhỏ, biểu nghĩa) + 奄 (Yểm, biểu âm); chữ hình thanh. Mái nhà nhỏ (广) gợi hình ảnh chái am — nơi ở hoặc nơi thờ tự nhỏ bé, tĩnh lặng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": mái nhà nhỏ (广) với tiếng yểm (奄) lặng lẽ — 庵 (am) là cái am, ngôi nhà tranh nhỏ tĩnh lặng dành cho tu hành. | Gương Hán-Việt | \"am\" xuất hiện trong tiếng Việt qua \"am\" (庵 — ngôi am nhỏ), \"thảo am\" (草庵 — am cỏ tranh). | Mở khoá kiến thức | Biết 庵 (am) là nhận ra 尼姑庵 (ni cô am — chùa ni), 草庵 (thảo am — am cỏ), 庵堂 (am đường — ngôi am).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 庵 là hình thanh: 广 (mái nhà, biểu nghĩa) + 奄 (yểm, biểu âm). Nghĩa gốc là ngôi nhà tranh nhỏ; sau mở rộng sang nhà nhỏ để tu hành hoặc thờ Phật (am thất, tu viện nhỏ), đặc biệt của ni cô. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái am (nhà tranh nhỏ); nhà nhỏ để thờ Phật", "Hạng Tần Suất (Jun Da)": "3016.0", "Tần Suất % (Jun Da)": "99.1987013934", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "广", "Unihan_Simplified (Chữ Giản thể)": "庵", "Unihan_Traditional (Chữ Phồn thể)": "庵", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ nơi tu hành nhỏ hoặc am thờ tự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沧', '{"9000": "3017.0", "Chữ Trung Quốc": "沧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 仓 | thương | biểu âm | kho lúa (cho âm cāng) | 沧 = 氵(Thuỷ, biểu nghĩa: nước) + 仓 (Thương, biểu âm); chữ hình thanh. Phồn thể 滄 dùng 倉 thay 仓. Bộ thuỷ chỉ biển rộng; 仓 cho âm cāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": nước (氵) màu xanh thẫm như biển ''thương'' — thương hải mênh mông, trải bao thăng trầm dâu bể. | Gương Hán-Việt | ''thương'' trong ''thương hải'' (biển xanh), 沧桑 (thương tang — thăng trầm dâu bể) | Mở khoá kiến thức | Biết 沧 mở khoá: 沧桑 (thăng trầm), 饱经沧桑 (trải qua nhiều gian truân), 沧海 (biển rộng)", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 沧 (phồn thể 滄) là chữ hình thanh: 氵(水, nước) biểu nghĩa; 倉/仓 biểu âm với âm cāng. Nghĩa gốc là ''xanh biếc, tối xanh của nước''; từ đó chỉ ''biển cả mênh mông''. Bạch thư và tiểu triện xác nhận cấu trúc. Thành ngữ 沧海桑田 (biển biến thành ruộng dâu) là nguồn gốc của 沧桑 (thăng trầm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rét lạnh; biển khơi, mênh mông; chất lượng", "Hạng Tần Suất (Jun Da)": "3017.0", "Tần Suất % (Jun Da)": "99.1996564123", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沧", "Unihan_Traditional (Chữ Phồn thể)": "滄", "Pinyin_Xie": "cāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng trong văn cổ để tả biển khơi hoặc sự lạnh lẽo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怠', '{"9000": "3018.0", "Chữ Trung Quốc": "怠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 台 | đài | biểu âm | đài, bục (cho âm dài) | 心 | tâm | biểu nghĩa | tâm, lòng | 怠 = 台 (Đài, biểu âm) + 心 (Tâm, biểu nghĩa: tâm trạng, trạng thái tinh thần); chữ hình thanh. 台 cho âm dài; bộ tâm chỉ trạng thái tâm lý lười biếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": tâm trạng (心) muốn ngồi lên đài (台) mà không chịu làm việc — người ''giải đãi'' cứ mơ ngồi trên đài cao mà không bước xuống thực tế. | Gương Hán-Việt | ''đãi'' trong ''giải đãi'' (lười biếng), ''đãi mạn'' (怠慢 — thờ ơ lạnh nhạt) | Mở khoá kiến thức | Biết 怠 mở khoá: 怠慢 (thờ ơ, thiếu chu đáo), 懈怠 (lười nhác), 怠工 (phá hoại, làm chậm trễ cố ý)", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 怠 là chữ hình thanh: 台 biểu âm với âm dài; 心 (tâm) biểu nghĩa trạng thái tâm lý. Nghĩa gốc là ''lười biếng, xao nhãng''. Mở rộng sang ''vô lễ, thờ ơ'' (怠慢) và ''mệt mỏi'' (văn cổ). Kim văn, tiểu triện và Lục thư thông xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lười biếng", "Hạng Tần Suất (Jun Da)": "3018.0", "Tần Suất % (Jun Da)": "99.2006109144", "GavinGrover_Once (Chiết tự trực tiếp)": "台 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱台心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "怠", "Unihan_Traditional (Chữ Phồn thể)": "怠", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ chỉ thái độ lười nhác hoặc làm động từ chỉ sự thờ ơ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沁', '{"9000": "3019.0", "Chữ Trung Quốc": "沁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thủy | biểu nghĩa | nước | 心 | tâm | biểu âm | 沁 = 氵 (Thủy — nước, biểu nghĩa) + 心 (Tâm, biểu âm); chữ hình thanh. Nước (氵) ngấm từ từ vào, gợi nghĩa thấm, ngấm vào trong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩm\": nước (氵) thấm vào từng tế bào như lọt vào tâm (心) — 沁 (khẩm) là thấm sâu vào tâm can, như \"沁人心脾\" (mát lòng thơm phổi). | Gương Hán-Việt | \"khẩm\" ít gặp trong tiếng Việt; từ \"thấm\" trong tiếng Việt được cho là bắt nguồn từ chữ 沁 này. | Mở khoá kiến thức | Biết 沁 (khẩm) là nhận ra 沁人心脾 (khẩm nhân tâm tỳ — mát lòng thơm phổi), 沁涼 (khẩm lương — mát lạnh dễ chịu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 沁 là hình thanh: 氵 (nước, biểu nghĩa) + 心 (tâm, biểu âm). Nghĩa là ngấm vào nước, thấm vào; cũng là tên sông Thấm (沁水). Hậu duệ tiếng Việt: thấm (沁 → thấm theo Wiktionary descendants). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "408.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (306) Tâm (148)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 76 - nước) và chữ Tâm (số 148 - lòng) . Nước (Thủy) ngấm dần vào sâu trong tận đáy lòng (Tâm) gọi là thấm thía. Giải thích sự chuyển ý: Chữ Tâm (tấm lòng) chỉ âm, chữ Thủy (nước) chỉ ý. Chất lỏng, nước (Thủy) ngấm vào, rỉ ra (Thấm). *(Biến âm Hán Việt: Tâm -> Thấm)*", "Nghĩa Tiếng Việt_Xie": "thấm nước; sông Thấm", "Hạng Tần Suất (Jun Da)": "3019.0", "Tần Suất % (Jun Da)": "99.2015654166", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沁", "Unihan_Traditional (Chữ Phồn thể)": "沁", "Pinyin_Xie": "qìn", "Âm Hán Việt_Xie": "thấm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ biểu thị sự thấm vào hoặc làm tính từ trong từ ghép chỉ sự mát mẻ, sảng khoái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奕', '{"9000": "3020.0", "Chữ Trung Quốc": "奕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 9 | nét | 亦 | diệc | biểu âm | 大 | đại | biểu nghĩa | to lớn, vĩ đại | 奕 = 亦 (Diệc, biểu âm) + 大 (Đại — to lớn, biểu nghĩa); chữ hình thanh. To lớn (大) với âm Diệc (亦) — gợi vẻ hùng tráng, đẹp đẽ vượt trội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": to lớn (大) với âm dịch (亦) — 奕 (dịch) là vẻ hùng tráng rực rỡ, tư thế hiên ngang như \"thần thái phong dịch\" (神采奕奕 — rạng rỡ đầy sức sống). | Gương Hán-Việt | \"dịch\" ít gặp riêng lẻ; 奕 xuất hiện trong thành ngữ 神采奕奕 (thần thái dịch dịch — rạng rỡ đầy sức sống). | Mở khoá kiến thức | Biết 奕 (dịch) là nhận ra 神采奕奕 (thần thái dịch dịch — rạng rỡ tươi tắn), 奕世 (dịch thế — đời đời), 奕棋 (dịch kỳ — đánh cờ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 奕 là hình thanh: 亦 (biểu âm) + 大 (to lớn, biểu nghĩa). Nghĩa gốc là to lớn, đẹp đẽ, rực rỡ; cũng có nghĩa nhiều lần, kế tiếp nhau (奕世 — đời đời). Trong tiếng Hán hiện đại còn dùng để chỉ trò cờ vây (下奕). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn", "Hạng Tần Suất (Jun Da)": "3020.0", "Tần Suất % (Jun Da)": "99.2025199187", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奕", "Unihan_Traditional (Chữ Phồn thể)": "奕", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ bổ nghĩa cho danh từ để chỉ sự to lớn, vẻ vang hoặc dùng trong tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咙', '{"9000": "3021.0", "Chữ Trung Quốc": "咙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, khoang miệng | 龙 | long | biểu âm | rồng (cho âm lóng) | 咙 là giản thể của 嚨: 口 (Khẩu, biểu nghĩa: miệng, cổ họng) + 龙/龍 (Long, biểu âm); chữ hình thanh. Bộ khẩu chỉ khoang miệng-họng; 龙 cho âm lóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": miệng (口) rộng như cổ rồng (龙) — họng là ống dẫn âm thanh, rộng và vang như tiếng rồng hú. | Gương Hán-Việt | ''lung'' trong ''hầu lung'' (họng), 喉咙 (hầu lung — cổ họng) | Mở khoá kiến thức | Biết 咙 mở khoá: 喉咙 (cổ họng), 喉咙痛 (đau họng)", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 咙 (phồn thể 嚨) là giản thể hoá của 嚨: 龍→龙. Chữ hình thanh: 口 (miệng) biểu nghĩa khoang họng; 龍/龙 biểu âm với âm lóng. Nghĩa cốt lõi là ''cổ họng'', gần như chỉ dùng trong từ 喉咙. Giáp cốt văn ghi nhận hình thức sơ khai. Chữ tạo muộn hơn so với nhiều chữ bộ khẩu khác. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ họng", "Hạng Tần Suất (Jun Da)": "3021.0", "Tần Suất % (Jun Da)": "99.2034733873", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咙", "Unihan_Traditional (Chữ Phồn thể)": "嚨", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp với chữ khác tạo thành danh từ chỉ bộ phận cổ họng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氨', '{"9000": "3022.0", "Chữ Trung Quốc": "氨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 10 | nét | 气 | khí | biểu nghĩa | khí, hơi | 安 | an | biểu âm | 氨 = 气 (Khí — khí, hơi, biểu nghĩa) + 安 (An, biểu âm); chữ hình thanh. Khí (气) + âm An (安) — đặt tên cho amonia (NH3), khí có mùi khai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"an\": khí (气) mang âm An (安) — 氨 (an) là amonia, loại khí có mùi không hề \"an\" (yên) chút nào! | Gương Hán-Việt | \"an\" ở đây là âm hóa học (ammonia), khác 安 (an — bình an); 氨气 (an khí — khí amonia) là từ cơ bản. | Mở khoá kiến thức | Biết 氨 (an) là nhận ra 氨气 (an khí — khí amonia), 氨水 (an thủy — nước amoniac), 氨基酸 (an cơ toan — amino acid).", "Tự nguyên_Xie": "Theo Wiktionary, 氨 là hình thanh: 气 (khí, biểu nghĩa) + 安 (an, biểu âm). Đây là chữ Hán đặt để phiên âm nguyên tố amonia (NH3) trong hóa học. Âm 安 gợi âm \"am\" trong ammonia. Chữ tạo muộn phục vụ khoa học. Chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khí amôniac (công thức hoá học: NH3)", "Hạng Tần Suất (Jun Da)": "3022.0", "Tần Suất % (Jun Da)": "99.2044258223", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氨", "Unihan_Traditional (Chữ Phồn thể)": "氨", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "an", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ khí amoniac hoặc các hợp chất liên quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矗', '{"9000": "3023.0", "Chữ Trung Quốc": "矗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 24 | nét | 矗 | súc | tượng hình | vươn thẳng lên, sừng sững | 矗 là chữ ghép ba lần 直 (trực — thẳng). {{zh-etym-triple|直|straight}} — ba chữ \"thẳng\" chồng lên nhau biểu nghĩa vật gì đó vươn thẳng vượt trội, sừng sững. Đây là chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": ba chữ Trực (直直直) — 矗 (súc) là sừng sững, vươn thẳng như ba cột tháp thẳng đứng hiên ngang. | Gương Hán-Việt | \"súc\" ít gặp trong tiếng Việt; 矗立 (súc lập — sừng sững) là cụm phổ biến nhất. | Mở khoá kiến thức | Biết 矗 (súc) là nhận ra 矗立 (súc lập — sừng sững, đứng thẳng oai nghiêm).", "Tự nguyên_Xie": "Theo Wiktionary, 矗 là chữ ghép ba lần chữ 直 (thẳng), tạo thành kiểu \"cường điệu bằng số\": ba cái thẳng đứng = vươn thẳng lên cao sừng sững. Chưa có hình ảnh giáp cốt/kim văn riêng. Chữ tạo muộn, không thấy dữ liệu cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vời vợi, sừng sững", "Hạng Tần Suất (Jun Da)": "3023.0", "Tần Suất % (Jun Da)": "99.2053782573", "GavinGrover_Once (Chiết tự trực tiếp)": "直", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴直", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "矗", "Unihan_Traditional (Chữ Phồn thể)": "矗", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái cao sừng sững của các công trình kiến trúc hoặc núi non. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盔', '{"9000": "3024.0", "Chữ Trung Quốc": "盔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 11 | nét | 盔 | khôi | tượng hình | mũ trụ, mũ bảo hiểm | 盔 gồm 灰 (khôi — tro, biểu âm) + 皿 (mãnh — bát chén/đồ đựng, biểu nghĩa). Đồ đựng hình bán cầu (皿) với âm khôi (灰) — gợi hình dạng mũ trụ úp lên đầu như cái bát lớn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": cái bát (皿) lớn màu tro (灰) úp lên đầu — 盔 (khôi) là mũ trụ chiến binh, hình bán cầu như cái bát đội lên. | Gương Hán-Việt | \"khôi\" xuất hiện trong \"đầu khôi\" (头盔 — mũ bảo hiểm), \"thép khôi\" (钢盔 — mũ sắt chiến trận). | Mở khoá kiến thức | Biết 盔 (khôi) là nhận ra 头盔 (đầu khôi — mũ bảo hiểm), 钢盔 (thép khôi — mũ sắt), 盔甲 (khôi giáp — giáp trụ).", "Tự nguyên_Xie": "盔 có {{Han etym}} nhưng Wiktionary không cung cấp phân tích chi tiết. Theo cấu trúc: 灰 (tro/khôi, biểu âm) + 皿 (đồ đựng, biểu nghĩa). Nghĩa là mũ trụ (mũ chiến đấu), bát (bát lớn), và nồi bánh (锅盔). Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũ trụ", "Hạng Tần Suất (Jun Da)": "3024.0", "Tần Suất % (Jun Da)": "99.2063301755", "GavinGrover_Once (Chiết tự trực tiếp)": "灰 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱灰皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盔", "Unihan_Traditional (Chữ Phồn thể)": "盔", "Pinyin_Xie": "kuī", "Âm Hán Việt_Xie": "khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại mũ bảo vệ đầu như mũ giáp thời xưa hoặc mũ bảo hiểm ngày nay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拇', '{"9000": "3025.0", "Chữ Trung Quốc": "拇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 母 | mẫu | biểu âm | mẹ (cho âm) | 拇 = 扌(Thủ, biểu nghĩa: tay) + 母 (Mẫu, biểu âm). Chữ hình thanh — 扌 chỉ bộ phận tay, 母 cho âm đọc mǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫu\": bàn tay (扌) có ngón CÁI to nhất — như người MẸ (母) đứng đầu các ngón. | Gương Hán-Việt | 拇指 (mẫu chỉ — ngón cái) | Mở khoá kiến thức | Biết 拇 (mẫu) mở khoá: 拇指 (ngón cái), 大拇指 (ngón tay cái).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 扌(手 — tay) là phần biểu nghĩa chỉ ngón tay; 母 (mẹ) là phần biểu âm. Tiểu triện đã có bộ tay bên trái. Nghĩa gốc: ngón tay cái — ngón to nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngón tay cái, ngón chân cái", "Hạng Tần Suất (Jun Da)": "3025.0", "Tần Suất % (Jun Da)": "99.2072805434", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 母", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌母", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "母", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拇", "Unihan_Traditional (Chữ Phồn thể)": "拇", "Pinyin_Xie": "mǔ", "Âm Hán Việt_Xie": "mẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các từ chỉ ngón tay hoặc ngón chân để làm danh từ chỉ ngón cái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沛', '{"9000": "3026.0", "Chữ Trung Quốc": "沛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 巿 | phất | biểu âm | tấm thẻ bài (cho âm pèi) | 沛 = 氵(Thuỷ, biểu nghĩa: nước) + 巿 (Phất, biểu âm); chữ hình thanh. Bộ thuỷ chỉ nước dồi dào; 巿 cho âm pèi. Đại triện và tiểu triện xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": nước (氵) chảy dào dạt như thẻ bài (巿) bạc — hình ảnh sức lực 充沛 (sung mãn), tràn đầy không dứt. | Gương Hán-Việt | ''bái'' ít dùng độc lập; gặp trong 充沛 (sung mãn, dồi dào) và 沛公 (tước hiệu Lưu Bang) | Mở khoá kiến thức | Biết 沛 mở khoá: 充沛 (dồi dào, sung mãn), 精力充沛 (tràn đầy sinh lực), 沛然 (ào ạt, dồi dào)", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 沛 là chữ hình thanh: 氵(水, nước) biểu nghĩa; 巿 biểu âm với âm pèi. Nghĩa gốc theo văn cổ là ''dồi dào, tràn đầy'' (của nước). Mở rộng sang ''mạnh mẽ, ào ạt'' (沛然) và ''đầm lầy'' (bãi đất hoang). Tên địa danh 沛县 (quê hương Lưu Bang) cũng dùng chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụn, đổ nát; bãi cỏ, bãi đất hoang", "Hạng Tần Suất (Jun Da)": "3026.0", "Tần Suất % (Jun Da)": "99.2082283273", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 巿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵巿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沛", "Unihan_Traditional (Chữ Phồn thể)": "沛", "Pinyin_Xie": "pèi", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ để miêu tả sự dồi dào của nước, năng lượng hoặc tinh thần. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榻', '{"9000": "3027.0", "Chữ Trung Quốc": "榻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | gỗ | 𦐇 | biểu âm | cho âm tà | 榻 = 木 (Mộc, biểu nghĩa: gỗ) + 𦐇 (biểu âm). Chữ hình thanh — 木 chỉ vật bằng gỗ, 𦐇 cho âm đọc tà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháp\": tấm GỖ (木) dài thấp sát đất — cái giường thấp để nằm nghỉ. | Gương Hán-Việt | 下榻 (hạ tháp — nghỉ ngơi, trú ngụ) | Mở khoá kiến thức | Biết 榻 (tháp) mở khoá: 下榻 (hạ tháp), 卧榻 (ngọa tháp — giường nằm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 木 (gỗ) là phần biểu nghĩa; 𦐇 là phần biểu âm. Tiểu triện và lục thư thông đều ghi dạng này. Nghĩa gốc: cái giường hẹp dài bằng gỗ để nằm hay ngồi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái giường hẹp mà dài", "Hạng Tần Suất (Jun Da)": "3027.0", "Tần Suất % (Jun Da)": "99.2091750777", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榻", "Unihan_Traditional (Chữ Phồn thể)": "榻", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loại giường thấp hoặc sập gỗ dùng để nằm nghỉ hoặc tiếp khách thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揣', '{"9000": "3028.0", "Chữ Trung Quốc": "揣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 耑 | đoan | biểu âm | cho âm chuāi | 揣 = 扌(Thủ, biểu nghĩa: tay) + 耑 (Đoan, biểu âm). Chữ hình thanh — 扌 chỉ hành động tay, 耑 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sủy\": dùng TAY (扌) sờ mó ước lượng — từ đó mở rộng sang nghĩa suy đoán, thăm dò. | Gương Hán-Việt | 揣摩 (sủy ma — suy đoán, thăm dò) | Mở khoá kiến thức | Biết 揣 (sủy) mở khoá: 揣摩 (suy đoán tâm ý), 揣测 (ước đoán).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 手/扌 (tay) là phần biểu nghĩa; 耑 là phần biểu âm. Nghĩa gốc: dùng tay đo lường; sau mở rộng sang suy đoán, thăm dò. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đo, lường, thăm dò", "Hạng Tần Suất (Jun Da)": "3028.0", "Tần Suất % (Jun Da)": "99.2101202777", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揣", "Unihan_Traditional (Chữ Phồn thể)": "揣", "Pinyin_Xie": "chuāi", "Âm Hán Việt_Xie": "sủy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thể hiện hành động suy đoán tâm lý người khác hoặc cất giấu đồ vật vào trong túi áo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chuāi | / | giấu hoặc mang trong quần áo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崭', '{"9000": "3029.0", "Chữ Trung Quốc": "崭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi | 斩 | trảm | biểu âm | chặt đứt (cho âm zhǎn) | 崭 là giản thể của 嶄: 山 (Sơn, biểu nghĩa: núi) + 斩/斬 (Trảm, biểu âm); chữ hình thanh. Bộ sơn chỉ địa hình nhô cao; 斩 cho âm zhǎn. Không có nguồn học thuật chi tiết về glyph-origin cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": núi (山) bị chặt đứt (斩) phần đỉnh — tạo ra vách đá dựng thẳng đứng, nhô cao 崭然, hoàn toàn mới. | Gương Hán-Việt | ''sàm'' trong ''sàm xuất'' (nhô lên cao vút); 崭新 (sàm tân — hoàn toàn mới) | Mở khoá kiến thức | Biết 崭 mở khoá: 崭新 (mới tinh, hoàn toàn mới), 崭露头角 (bộc lộ tài năng)", "Tự nguyên_Xie": "崭 (phồn thể 嶄) là chữ hình thanh: 山 (núi) biểu nghĩa địa hình cao ngất; 嶄/斬 biểu âm với âm zhǎn. Nghĩa gốc là ''cao ngất, chót vót''. Mở rộng sang ''hoàn toàn mới, nổi bật'' (崭新, 崭露头角). Wiktionary không có mô tả glyph-origin cổ đại; chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao ngất", "Hạng Tần Suất (Jun Da)": "3029.0", "Tần Suất % (Jun Da)": "99.2110644442", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 斩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山斩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崭", "Unihan_Traditional (Chữ Phồn thể)": "嶃", "Pinyin_Xie": "zhǎn", "Âm Hán Việt_Xie": "tiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ chỉ sự cao lớn hoặc làm phó từ bổ nghĩa cho tính từ khác để chỉ mức độ cao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞘', '{"9000": "3030.0", "Chữ Trung Quốc": "鞘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 16 | nét | 革 | cách | biểu nghĩa | da thuộc | 肖 | tiêu | biểu âm | cho âm qiào | 鞘 = 革 (Cách, biểu nghĩa: da thuộc) + 肖 (Tiêu, biểu âm). Chữ hình thanh — 革 chỉ vật liệu da, 肖 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": lớp DA (革) bọc ngoài lưỡi kiếm — cái bao kiếm bằng da bảo vệ. | Gương Hán-Việt | 刀鞘 (đao tiêu — bao đựng dao) | Mở khoá kiến thức | Biết 鞘 (tiêu) mở khoá: 刀鞘 (bao dao), 剑鞘 (bao kiếm).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 革 (da thuộc) là phần biểu nghĩa; 肖 là phần biểu âm. Nghĩa gốc: bao đựng dao kiếm bằng da. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bao đựng dao", "Hạng Tần Suất (Jun Da)": "3030.0", "Tần Suất % (Jun Da)": "99.212007577", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞘", "Unihan_Traditional (Chữ Phồn thể)": "鞘", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "sao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận vỏ bọc bên ngoài của các loại vũ khí sắc bén như kiếm hoặc dao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞠', '{"9000": "3031.0", "Chữ Trung Quốc": "鞠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 17 | nét | 革 | cách | biểu nghĩa | da thuộc | 匊 | cúc | biểu âm | hai tay bụm lại (cho âm jū) | 鞠 = 革 (Cách, biểu nghĩa: da thuộc) + 匊 (Cúc, biểu âm); chữ hình thanh, theo Wiktionary gốc là 𥲩+米 biểu âm và 革 biểu nghĩa. Bộ cách chỉ chất liệu da; 匊 cho âm jū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cúc\": da thuộc (革) được bụm lại thành hình tròn (匊) — quả bóng da cổ đại, và khi cúi đầu 鞠躬, lưng cong tròn như quả bóng. | Gương Hán-Việt | ''cúc'' trong ''cúc cung'' (鞠躬 — cúi đầu kính cẩn), 蹴鞠 (túc cúc — bóng da cổ đại) | Mở khoá kiến thức | Biết 鞠 mở khoá: 鞠躬 (cúi chào), 鞠躬尽瘁 (tận tuỵ hết mình), 蹴鞠 (bóng đá cổ đại Trung Quốc)", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 鞠 là chữ hình thanh: thành phần biểu âm gốc là ⿰革勹 + 米 (hạt millet — nhân bên trong quả bóng da nhồi gạo). Nghĩa gốc là ''quả bóng da'' (dùng trong trò chơi cổ đại 蹴鞠). Mở rộng sang ''cong, khom xuống'' (鞠躬 — cúi đầu) và ''nuôi dưỡng''. Đại triện và tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1594.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Cách (177) Cúc (1256)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Cách (số 177 - da thú/ 革 /chỉ ý) ở bên trái chữ Cúc (số 1256 - vốc bằng tay/ 匊 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cúc (匊) chỉ âm, bộ Cách chỉ ý. Cúc là quả bóng khâu bằng da thú dùng để đá thời xưa (đạp cúc - môn bóng đá thời phong kiến).", "Nghĩa Tiếng Việt_Xie": "quả bóng da; nuôi nấng; cong, khom", "Hạng Tần Suất (Jun Da)": "3031.0", "Tần Suất % (Jun Da)": "99.2129486428", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 匊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革匊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞠", "Unihan_Traditional (Chữ Phồn thể)": "鞠", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "cúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường dùng làm động từ trong các từ ghép như cúc cung hoặc cúc dục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垦', '{"9000": "3032.0", "Chữ Trung Quốc": "垦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 貇 | biểu âm | cho âm kěn | 土 | thổ | biểu nghĩa | đất | 垦 = 貇 (biểu âm, cho âm kěn) + 土 (Thổ, biểu nghĩa: đất). Chữ hình thanh — 土 chỉ đất đai, 貇 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẩn\": vỡ ĐẤT (土) hoang — khai KHẨN ruộng mới từ đất bỏ hoang. | Gương Hán-Việt | 开垦 (khai khẩn — vỡ đất hoang) | Mở khoá kiến thức | Biết 垦 (khẩn) mở khoá: 开垦 (khai khẩn), 垦荒 (khẩn hoang), 垦区 (khu khai hoang).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 土 (đất) là phần biểu nghĩa; 貇 là phần biểu âm. Tiểu triện và lục thư thông đều ghi cấu trúc này. Nghĩa gốc: khai khẩn đất hoang, vỡ đất để canh tác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khai khẩn, vỡ đất hoang", "Hạng Tần Suất (Jun Da)": "3032.0", "Tần Suất % (Jun Da)": "99.2138886749", "GavinGrover_Once (Chiết tự trực tiếp)": "艮 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艮土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艮", "Unihan_Simplified (Chữ Giản thể)": "垦", "Unihan_Traditional (Chữ Phồn thể)": "墾", "Pinyin_Xie": "kěn", "Âm Hán Việt_Xie": "khẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đất đai để diễn tả hoạt động khai hoang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洽', '{"9000": "3033.0", "Chữ Trung Quốc": "洽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | thuỷ | biểu nghĩa | nước | 合 | cáp | biểu âm | hợp lại (cho âm qià) | 洽 = 氵(Thuỷ, biểu nghĩa: nước) + 合 (Cáp, biểu âm); chữ hình thanh. Bộ thuỷ gợi sự thấm đẫm, hoà quyện; 合 cho âm qià và gợi ý nghĩa ''hoà hợp''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệp\": nước (氵) thấm vào hoà hợp (合) — như hai bên bàn đàm phán, mọi thứ 融洽, trơn tru như nước chảy. | Gương Hán-Việt | ''hiệp'' trong ''hoà hiệp'' (融洽 — hoà hợp), 洽谈 (hiệp đàm — đàm phán, bàn bạc) | Mở khoá kiến thức | Biết 洽 mở khoá: 融洽 (hoà hợp, ăn ý), 洽谈 (đàm phán, thương lượng), 洽商 (thảo luận kinh doanh)", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 洽 là chữ hình thanh: 水/氵(nước) biểu nghĩa; 合 biểu âm với âm qià. Nghĩa gốc liên quan đến sông Hợp (địa danh); mở rộng sang ''thấm đẫm, hoà quyện'' và ''bàn bạc, hiệp thương''. Đại triện và tiểu triện xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Hợp", "Hạng Tần Suất (Jun Da)": "3033.0", "Tần Suất % (Jun Da)": "99.2148235392", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洽", "Unihan_Traditional (Chữ Phồn thể)": "洽", "Pinyin_Xie": "qià", "Âm Hán Việt_Xie": "hiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với các từ khác để tạo thành tính từ chỉ sự hòa hợp hoặc động từ chỉ sự bàn bạc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唾', '{"9000": "3034.0", "Chữ Trung Quốc": "唾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 垂 | thuỳ | biểu âm | rủ xuống, thả xuống (cho âm tuò) | 唾 = 口 (Khẩu, biểu nghĩa: miệng) + 垂 (Thuỳ, biểu âm); chữ hình thanh. Bộ khẩu chỉ hành động từ miệng; 垂 cho âm tuò và gợi ý hình ảnh nước rủ xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoá\": miệng (口) để chất lỏng rủ xuống (垂) — hình ảnh nước bọt chảy, hay cử chỉ ''thoá mạ'' (phỉ nhổ) kẻ bị khinh. | Gương Hán-Việt | ''thoá'' trong ''khinh thoá'' (khinh thường, nhổ vào), 唾骂 (chửi rủa, phỉ nhổ) | Mở khoá kiến thức | Biết 唾 mở khoá: 唾沫 (nước bọt), 唾液 (nước bọt, nước miếng), 唾骂 (phỉ nhổ chửi rủa)", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 唾 là chữ hình thanh: 口 (miệng) biểu nghĩa hành động phun ra từ miệng; 垂 biểu âm với âm tuò và gợi hình ảnh chất lỏng rủ xuống. Nghĩa gốc là ''nước bọt''; mở rộng sang ''nhổ, phỉ nhổ'' (khinh thường). Đại triện và tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước bọt; phỉ nhổ", "Hạng Tần Suất (Jun Da)": "3034.0", "Tần Suất % (Jun Da)": "99.2157584035", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唾", "Unihan_Traditional (Chữ Phồn thể)": "唾", "Pinyin_Xie": "tuò", "Âm Hán Việt_Xie": "thoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động khinh bỉ, phỉ nhổ hoặc làm danh từ chỉ nước bọt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橱', '{"9000": "3035.0", "Chữ Trung Quốc": "橱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | gỗ | 厨 | trù | biểu âm | nhà bếp (cho âm chú) | 橱 = 木 (Mộc, biểu nghĩa: gỗ) + 厨 (Trù, biểu âm). Chữ hình thanh — 木 chỉ đồ gỗ, 厨 cho âm đọc chú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": cái TỦ GỖ (木) trong nhà bếp (厨) để cất thức ăn. | Gương Hán-Việt | 书橱 (thư trù — tủ sách); 橱窗 (trù song — tủ kính) | Mở khoá kiến thức | Biết 橱 (trù) mở khoá: 书橱 (tủ sách), 橱窗 (tủ kính), 衣橱 (tủ quần áo).", "Tự nguyên_Xie": "Chữ hình thanh. 木 (gỗ) là phần biểu nghĩa; 厨 (bếp) là phần biểu âm. Chưa có nguồn học thuật rõ ràng từ Wiktionary. Nghĩa gốc: cái tủ/rương gỗ đựng đồ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tủ, cái rương", "Hạng Tần Suất (Jun Da)": "3035.0", "Tần Suất % (Jun Da)": "99.2166917175", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 厨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木厨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橱", "Unihan_Traditional (Chữ Phồn thể)": "櫥", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm yếu tố cấu tạo từ chỉ các loại tủ đựng đồ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('仕', '{"9000": "3036.0", "Chữ Trung Quốc": "仕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 5 | nét | ⺅ | nhân | biểu nghĩa | người | 士 | sĩ | biểu âm | kẻ sĩ, học trò | 仕 = ⺅(Nhân, biểu nghĩa: người) + 士 (Sĩ, biểu âm kiêm hội ý). Chữ hình thanh kiêm hội ý — 亻 chỉ con người, 士 (người có học) vừa cho âm vừa gợi nghĩa quan chức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sĩ\": kẻ SĨ (士) có học — con NGƯỜI (亻) ra làm quan phụng sự. | Gương Hán-Việt | 出仕 (xuất sĩ — ra làm quan); 仕途 (sĩ đồ — hoạn lộ) | Mở khoá kiến thức | Biết 仕 (sĩ) mở khoá: 出仕 (ra làm quan), 仕途 (hoạn lộ), 仕女 (tranh mỹ nữ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh kiêm hội ý. 人/亻 (người) là phần biểu nghĩa; 士 (học trò, kẻ sĩ) vừa biểu âm vừa gợi nghĩa — người có học vấn ra làm quan. Kim văn và tiểu triện đều ghi cấu trúc này. Nghĩa gốc: làm quan, phụng sự triều đình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "học trò; quan", "Hạng Tần Suất (Jun Da)": "3036.0", "Tần Suất % (Jun Da)": "99.2176245146", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 士", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻士", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "士", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "仕", "Unihan_Traditional (Chữ Phồn thể)": "仕", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "sĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ việc ra làm quan hoặc danh từ chỉ tầng lớp quan lại thời xưa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜘', '{"9000": "3037.0", "Chữ Trung Quốc": "蜘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu bọ | 知 | tri | biểu âm | biết (cho âm zhī) | 蜘 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 知 (Tri, biểu âm). Chữ hình thanh — 虫 chỉ loài côn trùng, 知 cho âm đọc zhī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tri\": con SÂU BỌ (虫) BIẾT (知) giăng tơ — con nhện tinh khôn. | Gương Hán-Việt | 蜘蛛 (tri chu — con nhện) | Mở khoá kiến thức | Biết 蜘 (tri) mở khoá: 蜘蛛 (nhện), 蜘蛛网 (mạng nhện).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh. 虫 (sâu bọ) là phần biểu nghĩa; 知 là phần biểu âm. Hình thái nguyên thủy là 鼅鼄 (rút gọn thành 蜘蛛). Lục thư thông ghi hình phái sinh muộn. Nghĩa: dùng trong từ ghép 蜘蛛 (nhện). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tri chu 蜘蛛,鼅鼄)", "Hạng Tần Suất (Jun Da)": "3037.0", "Tần Suất % (Jun Da)": "99.218556795", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 知", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫知", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "知", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜘", "Unihan_Traditional (Chữ Phồn thể)": "蜘", "Pinyin_Xie": "zhī", "Âm Hán Việt_Xie": "tri", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong từ ghép liên kết tri chu để chỉ con nhện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痰', '{"9000": "3038.0", "Chữ Trung Quốc": "痰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 炎 | viêm | biểu âm | viêm nhiễm (cho âm tán) | 痰 = 疒 (Nạch, biểu nghĩa: bệnh) + 炎 (Viêm, biểu âm). Chữ hình thanh — 疒 chỉ bệnh, 炎 cho âm đọc tán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đờm\": chất nhầy bệnh (疒) do VIÊM (炎) đường họng — đờm trong cổ. | Gương Hán-Việt | 化痰 (hóa đờm — tiêu đờm) | Mở khoá kiến thức | Biết 痰 (đờm) mở khoá: 化痰 (tiêu đờm), 痰盂 (bình nhổ), 咳痰 (ho có đờm).", "Tự nguyên_Xie": "Chữ hình thanh. 疒 (bệnh) là phần biểu nghĩa; 炎 (viêm nhiễm) là phần biểu âm. Nghĩa gốc: đờm — chất nhầy sinh ra do bệnh đường hô hấp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đờm (trong họng)", "Hạng Tần Suất (Jun Da)": "3038.0", "Tần Suất % (Jun Da)": "99.2194823572", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痰", "Unihan_Traditional (Chữ Phồn thể)": "痰", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ chỉ hành động khạc hoặc nhổ đờm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ vựng Hán 痰 (tán). Hán-Việt: đờm. | / | tán | / | đờm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nội dung II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袜', '{"9000": "3039.0", "Chữ Trung Quốc": "袜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衤 | y | biểu nghĩa | vải / áo — vật bằng vải | 末 | mạt | biểu âm | gợi âm ''wà'' | 袜 (giản thể của 襪) = 衤 (Y, vải) + 末 (Mạt, biểu âm). Chữ hình thanh: vật bằng vải đeo ở ''mạt'' — phần cuối (bàn chân) — nghĩa ''cái tất, vớ''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Vạt'': miếng vải (衤) bao phần cuối/ngọn (末) của chân — đó là ''vạt'', là cái tất. | Gương Hán-Việt | ''Vạt'' (Hán-Việt cổ); trong tiếng Việt 袜 dịch ''tất, vớ''. | Mở khoá kiến thức | Biết 袜 mở khóa 袜子 (vạt tử / tất), cách dùng cho phụ kiện đi chân.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 襪 là chữ hình thanh: 衣 (衤) biểu nghĩa, 蔑 biểu âm. Bản giản thể 袜 dùng 末 thay 蔑 cho gọn. Nghĩa ''tất, vớ''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái tất (đi vào chân); áo lót của đàn bà", "Hạng Tần Suất (Jun Da)": "3039.0", "Tần Suất % (Jun Da)": "99.2204074026", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 末", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤末", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "末", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袜", "Unihan_Traditional (Chữ Phồn thể)": "襪", "Pinyin_Xie": "wà", "Âm Hán Việt_Xie": "miệt, vạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau lượng từ chỉ đôi hoặc chiếc để chỉ tất chân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峙', '{"9000": "3040.0", "Chữ Trung Quốc": "峙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 山 | sơn | biểu nghĩa | núi | 寺 | tự | biểu âm | chùa (cho âm zhì) | 峙 = 山 (Sơn, biểu nghĩa: núi) + 寺 (Tự, biểu âm). Chữ hình thanh — 山 chỉ núi non, 寺 cho âm đọc zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": NÚI (山) đứng vững như ngôi CHÙA (寺) — sừng sững uy nghi, không lay chuyển. | Gương Hán-Việt | 对峙 (đối trĩ — đối đầu) | Mở khoá kiến thức | Biết 峙 (trĩ) mở khoá: 对峙 (đối đầu), 耸峙 (sừng sững).", "Tự nguyên_Xie": "Chữ hình thanh. 山 (núi) là phần biểu nghĩa; 寺 là phần biểu âm. Nghĩa gốc: đứng vững sừng sững, đặc biệt của núi non. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sừng sững; đứng sừng sững", "Hạng Tần Suất (Jun Da)": "3040.0", "Tần Suất % (Jun Da)": "99.2213293473", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 寺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峙", "Unihan_Traditional (Chữ Phồn thể)": "峙", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong các từ ghép chỉ sự đối lập, đứng sừng sững đối diện nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柬', '{"9000": "3041.0", "Chữ Trung Quốc": "柬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 柬 | giản | tượng hình | chữ tự lập: hình bó vật trong túi buộc với hai dấu điểm chỉ nội dung được chọn lọc | 柬 là chữ hội ý tự lập: theo Wiktionary, gốc là hình 束 (bó buộc) + 八 (hai điểm/nét) — hai nét 八 đánh dấu nội dung bên trong túi buộc, gợi ý hành động chọn lựa, kén chọn. Nghĩa gốc là ''kén chọn, lựa chọn''; sau chuyển sang ''thư thiệp'' (vật được chọn trao).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\": túi buộc (束) với hai dấu (八) đánh dấu thứ được chọn — từ hành động kén chọn đến tấm thiệp 请柬 trang trọng gửi người được mời. | Gương Hán-Việt | ''giản'' trong ''thiệp giản'' (thiệp mời), 请柬 (thỉnh giản — thiệp mời chính thức) | Mở khoá kiến thức | Biết 柬 mở khoá: 请柬 (thiệp mời), 柬埔寨 (Campuchia), 投柬 (bỏ phiếu)", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 柬 là hội ý: 束 (túi buộc) + 八 (hai điểm đánh dấu nội dung). Nghĩa gốc là ''kén chọn, chọn lựa'' — nghĩa này sau chuyển sang 揀. Hai nét bên trong nhấn mạnh nội dung được chọn lọc trong túi. Tương đồng cấu trúc với 東, 熏, 鹵. Kim văn và bạch thư xác nhận. Nghĩa ''thư thiệp'' là nghĩa phái sinh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kén chọn; thư, thiếp, thiệp", "Hạng Tần Suất (Jun Da)": "3041.0", "Tần Suất % (Jun Da)": "99.2222450905", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "柬", "Unihan_Traditional (Chữ Phồn thể)": "柬", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại thiệp mời, thư từ hoặc làm động từ mang nghĩa lựa chọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝉', '{"9000": "3042.0", "Chữ Trung Quốc": "蝉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu bọ | 单 | đan | biểu âm | đơn (cho âm chán) | 蝉 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 单 (Đan, biểu âm). Chữ hình thanh, giản thể của 蟬 — 虫 chỉ loài côn trùng, 单 cho âm đọc chán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiền\": con SÂU BỌ (虫) ĐƠN CHIẾC (单) mà tiếng kêu vang trời — con ve sầu kêu thiền thiền. | Gương Hán-Việt | 蝉鸣 (thiền minh — tiếng ve kêu); 寒蝉 (hàn thiền — ve mùa lạnh, ý lặng im) | Mở khoá kiến thức | Biết 蝉 (thiền) mở khoá: 蝉鸣 (tiếng ve), 金蝉脱壳 (ve vàng lột xác — thoát thân).", "Tự nguyên_Xie": "Chữ hình thanh (giản thể của 蟬). 虫 (sâu bọ) là phần biểu nghĩa; 单 là phần biểu âm. Nghĩa gốc: con ve sầu — loài côn trùng kêu vang mùa hè. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ve sầu", "Hạng Tần Suất (Jun Da)": "3042.0", "Tần Suất % (Jun Da)": "99.223160317", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝉", "Unihan_Traditional (Chữ Phồn thể)": "蟬", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "thuyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm yếu tố cấu tạo từ chỉ các sự vật liên quan đến ve sầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟹', '{"9000": "3043.0", "Chữ Trung Quốc": "蟹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 解 | giải | biểu âm | tháo gỡ (cho âm xiè) | 虫 | trùng | biểu nghĩa | sâu bọ | 蟹 = 解 (Giải, biểu âm) + 虫 (Trùng, biểu nghĩa: sâu bọ). Chữ hình thanh — 虫 chỉ loài động vật nhỏ, 解 cho âm đọc xiè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giải\": con SÂU BỌ (虫) THÁO GỠ (解) càng — con cua với đôi càng có thể giải thoát. | Gương Hán-Việt | 螃蟹 (bàng giải — con cua); 河蟹 (hà giải — cua sông) | Mở khoá kiến thức | Biết 蟹 (giải) mở khoá: 螃蟹 (con cua), 河蟹 (cua sông), 蟹黄 (gạch cua).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 虫 (sâu bọ/động vật) là phần biểu nghĩa; 解 là phần biểu âm. Hình thái nguyên thủy viết là 蠏. Tiểu triện ghi cấu trúc này. Nghĩa gốc: con cua. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cua", "Hạng Tần Suất (Jun Da)": "3043.0", "Tần Suất % (Jun Da)": "99.2240755435", "GavinGrover_Once (Chiết tự trực tiếp)": "解 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱解虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "解", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟹", "Unihan_Traditional (Chữ Phồn thể)": "蟹", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "giải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con cua, thường kết hợp để tạo danh từ ghép như hải giải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谏', '{"9000": "3044.0", "Chữ Trung Quốc": "谏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 柬 | giản | biểu âm | thiệp (cho âm jiàn) | 谏 = 讠(Ngôn, biểu nghĩa: lời nói) + 柬 (Giản, biểu âm). Giản thể của 諫 — 讠 chỉ hành động nói, 柬 cho âm đọc jiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gián\": dùng LỜI (讠) thẳng thắn khuyên can — can GIÁN bề trên. | Gương Hán-Việt | 谏言 (gián ngôn — lời can gián); 进谏 (tiến gián — dâng lời can) | Mở khoá kiến thức | Biết 谏 (gián) mở khoá: 谏言 (lời can gián), 进谏 (dâng lời can), 忠谏 (trung gián).", "Tự nguyên_Xie": "Kim văn | Đại triện | Chữ hình thanh (giản thể của 諫). 言/讠 (lời nói) là phần biểu nghĩa; 柬 là phần biểu âm. Kim văn và đại triện đã có dạng cổ. Nghĩa gốc: dùng lời nói thẳng để can gián, khuyên răn bề trên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "can ngăn, can gián", "Hạng Tần Suất (Jun Da)": "3044.0", "Tần Suất % (Jun Da)": "99.2249897364", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 柬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠柬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谏", "Unihan_Traditional (Chữ Phồn thể)": "諫", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "gián", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc can ngăn hoàng đế hoặc cấp trên, thường đi kèm tân ngữ chỉ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹃', '{"9000": "3045.0", "Chữ Trung Quốc": "鹃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 12 | nét | 鸟 | điểu | biểu nghĩa | chim | 口 | khẩu | biểu âm | miệng (cho âm juān) | 鹃 = 鸟 (Điểu, biểu nghĩa: chim) + 口 (Khẩu, biểu âm). Giản thể của 鵑 — 鸟 chỉ loài chim, 口 cho âm đọc juān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyên\": con CHIM (鸟) cất TIẾNG (口) kêu ai oán — chim cuốc kêu rỉ rả. | Gương Hán-Việt | 杜鹃 (đỗ quyên — chim cuốc, hoa đỗ quyên) | Mở khoá kiến thức | Biết 鹃 (quyên) mở khoá: 杜鹃 (chim cuốc/hoa đỗ quyên), 子规 (tên khác của chim cuốc).", "Tự nguyên_Xie": "Chữ hình thanh (giản thể của 鵑). 鸟 (chim) là phần biểu nghĩa. Chưa có nguồn Wiktionary rõ cho dạng gốc phức tạp. Dùng trong từ ghép 杜鹃 (đỗ quyên — chim cuốc/hoa đỗ quyên). Nghĩa gốc: loài chim cuốc kêu ai oán. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chim cuốc", "Hạng Tần Suất (Jun Da)": "3045.0", "Tần Suất % (Jun Da)": "99.2259034125", "GavinGrover_Once (Chiết tự trực tiếp)": "肙 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰肙鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹃", "Unihan_Traditional (Chữ Phồn thể)": "鵑", "Pinyin_Xie": "juān", "Âm Hán Việt_Xie": "quyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim quyên, thường xuất hiện trong các từ ghép như đỗ quyên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擎', '{"9000": "3046.0", "Chữ Trung Quốc": "擎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 敬 | kính | biểu âm | kính trọng (cho âm qíng) | 手 | thủ | biểu nghĩa | tay | 擎 = 敬 (Kính, biểu âm) + 手 (Thủ, biểu nghĩa: tay); chữ hình thanh. Bộ thủ ở dưới chỉ hành động nâng bằng tay; 敬 cho âm qíng. Cấu trúc tương tự các chữ ''tay đặt dưới'' khác như 拿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kình\": đôi tay (手) kính cẩn (敬) nâng lên — như người lính 擎旗 (nâng cờ) hay cột trụ 擎天 một mình chống đỡ cả bầu trời. | Gương Hán-Việt | ''kình'' trong ''nhất trụ kình thiên'' (一柱擎天 — một cột chống trời), 引擎 (dẫn kình — động cơ) | Mở khoá kiến thức | Biết 擎 mở khoá: 引擎 (động cơ), 擎天 (chống đỡ bầu trời), 一柱擎天 (một mình gánh vác tất cả)", "Tự nguyên_Xie": "擎 là chữ hình thanh: 手 (tay) biểu nghĩa hành động nâng, đỡ; 敬 biểu âm với âm qíng. Wiktionary chỉ ghi định nghĩa và phát âm, không có mô tả glyph-origin cổ đại. Nghĩa gốc là ''chống đỡ, nâng lên''. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "939.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Kính (838) Thủ (064)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Kính (số 838 - kính trọng/chỉ âm) ở trên bộ Thủ (số 064 - cái tay). Dùng tay dâng lên với lòng thành kính. Giải thích sự chuyển ý: Đây là chữ Hình thanh (hoặc Hội ý). Chữ Kính chỉ âm, bộ Thủ chỉ ý. Kình là dùng tay dâng lên cao (kình thiên).", "Nghĩa Tiếng Việt_Xie": "giơ lên", "Hạng Tần Suất (Jun Da)": "3046.0", "Tần Suất % (Jun Da)": "99.2268170886", "GavinGrover_Once (Chiết tự trực tiếp)": "敬 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敬手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "擎", "Unihan_Traditional (Chữ Phồn thể)": "擎", "Pinyin_Xie": "qíng", "Âm Hán Việt_Xie": "kình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nâng hoặc đỡ vật gì đó bằng tay hướng lên trên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皓', '{"9000": "3047.0", "Chữ Trung Quốc": "皓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 12 | nét | 白 | bạch | biểu nghĩa | trắng | 告 | cáo | biểu âm | thông báo (cho âm hào) | 皓 = 白 (Bạch, biểu nghĩa: trắng) + 告 (Cáo, biểu âm). Chữ hình thanh — 白 chỉ màu trắng sáng, 告 cho âm đọc hào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạo\": TRẮNG (白) sáng RẠNG RỠ — hạo như ánh trăng rằm chiếu sáng đêm đen. | Gương Hán-Việt | 皓月 (hạo nguyệt — trăng sáng trắng); 皓首 (hạo thủ — đầu bạc) | Mở khoá kiến thức | Biết 皓 (hạo) mở khoá: 皓月 (trăng sáng), 皓首 (đầu bạc), 洁白皓齿 (răng trắng tinh).", "Tự nguyên_Xie": "Chữ hình thanh. 白 (trắng) là phần biểu nghĩa; 告 là phần biểu âm. Nghĩa gốc: trắng sáng, rực rỡ — dùng cho ánh trăng, răng trắng, tóc bạc trắng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trắng; sạch sẽ", "Hạng Tần Suất (Jun Da)": "3047.0", "Tần Suất % (Jun Da)": "99.227730248", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皓", "Unihan_Traditional (Chữ Phồn thể)": "皓", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả vẻ trắng sáng hoặc sạch sẽ, thường bổ nghĩa cho danh từ như hạo nguyệt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朕', '{"9000": "3048.0", "Chữ Trung Quốc": "朕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 月 | Số nét | 10 | nét | 朕 | trẫm | tượng hình | ta (ngôi xưng của hoàng đế) | 朕 là chữ tượng hình cổ. Giáp cốt văn và kim văn vẽ hình con thuyền (舟) bên cạnh hai bàn tay cầm mái chèo. Bản giản thể hóa thành 月 + hai vạch. Nghĩa gốc: đại từ ngôi thứ nhất, sau dành riêng cho hoàng đế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trẫm\": TA đây (朕) — chỉ hoàng đế mới được dùng từ này để tự xưng, mọi người khác phải tránh. | Gương Hán-Việt | 朕 (trẫm — ta, cách hoàng đế tự xưng) | Mở khoá kiến thức | Biết 朕 (trẫm) mở khoá: ngữ cảnh lịch sử xưng hô cung đình, xuất hiện nhiều trong tiểu thuyết cổ trang.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Chữ tượng hình. Giáp cốt văn vẽ con thuyền (舟) bên hai bàn tay cầm mái chèo — hình ảnh người chèo thuyền xưng ''ta''. Giản thể hóa thành 月 (biến thể từ 舟). Nghĩa gốc: đại từ ngôi thứ nhất; từ thời Tần Thủy Hoàng dành riêng cho hoàng đế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ta đây (tự xưng)", "Hạng Tần Suất (Jun Da)": "3048.0", "Tần Suất % (Jun Da)": "99.2286428905", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 关", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月关", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "关", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "朕", "Unihan_Traditional (Chữ Phồn thể)": "朕", "Pinyin_Xie": "zhèn", "Âm Hán Việt_Xie": "trẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này làm đại từ nhân xưng ngôi thứ nhất, chỉ dùng cho hoàng đế tự xưng trong thời phong kiến. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疤', '{"9000": "3049.0", "Chữ Trung Quốc": "疤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 9 | nét | 疒 | nạch | biểu nghĩa | bệnh tật, bệnh hoạn | 巴 | ba | biểu âm | mong ngóng (cho âm bā) | 疤 = 疒 (Nạch, biểu nghĩa: bệnh tật, vết thương) + 巴 (Ba, biểu âm); chữ hình thanh. Bộ nạch chỉ vết thương trên cơ thể; 巴 cho âm bā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": bệnh tật (疒) để lại dấu vết trông ngóng mãi (巴) không tan — vết sẹo là ký ức của vết thương xưa không thể xoá. | Gương Hán-Việt | ''ba'' trong ''thương ba'' (vết thương để lại sẹo), 疤痕 (ba ngân — vết sẹo) | Mở khoá kiến thức | Biết 疤 mở khoá: 疤痕 (vết sẹo), 留疤 (để lại sẹo), 揭疤 (bóc sẹo — chỉ trích vào nỗi đau cũ)", "Tự nguyên_Xie": "疤 là chữ hình thanh: 疒 (bệnh tật) biểu nghĩa vết thương trên da; 巴 biểu âm với âm bā. Nghĩa gốc và duy nhất là ''vết sẹo'' — mô tả lớp da còn lại sau khi vết thương lành. Chưa có nguồn học thuật về glyph-origin cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết sẹo; vết sần, tỳ vết", "Hạng Tần Suất (Jun Da)": "3049.0", "Tần Suất % (Jun Da)": "99.2295550163", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疤", "Unihan_Traditional (Chữ Phồn thể)": "疤", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ vết sẹo hoặc tỳ vết trên cơ thể, thường đứng sau các động từ như lưu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bā | / | sẹo | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Cơ thể và ngoại hình II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禺', '{"9000": "3050.0", "Chữ Trung Quốc": "禺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禸 | Số nét | 9 | nét | 甶 | tượng hình | đầu quỷ | 禸 | tượng hình | dẫm trên | 禺 = 甶 (đầu quỷ, hội ý) + 禸 (dẫm trên, hội ý). Theo Thuyết Văn, chữ hội ý — mô tả loài khỉ/con vật kỳ lạ. Cấu trúc không rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngung\": chữ cổ mô tả vùng đất hay loài khỉ kỳ lạ — xuất hiện trong địa danh 禺山 (núi Ngung). | Gương Hán-Việt | 禺强 (Ngung Cường — thần biển/gió trong thần thoại Trung Hoa) | Mở khoá kiến thức | Biết 禺 (ngung) mở khoá: 禺强 (thần Ngung Cường), 禺山 (núi Ngung).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ không rõ nguồn gốc. Thuyết Văn cho là hội ý: 甶 (đầu quỷ) + 禸 (dẫm trên) — mô tả một loài khỉ. Đại triện và tiểu triện ghi lại hình thái này. Dùng trong địa danh và tên riêng, nghĩa thực tế hạn chế. Chưa có nguồn học thuật rõ ràng. | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1460.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Điền (097) Nhựu (202)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Điền (số 097/ 田) lọt vào giữa chữ Nhựu (số 202 - vết chân thú/ 禸). (Thực tế phía trên là bộ Quỷ 甶 - đầu ma quỷ). Giải thích sự chuyển ý: Đây là chữ Tượng hình. Ngu là một loài thú giống con khỉ, con vượn lông có màu vàng.", "Nghĩa Tiếng Việt_Xie": "đất Ngu; vùng đất 10 dặm bằng 1 ngu", "Hạng Tần Suất (Jun Da)": "3050.0", "Tần Suất % (Jun Da)": "99.2304630078", "GavinGrover_Once (Chiết tự trực tiếp)": "甲 + 禸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱甲禸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禸", "Unihan_Simplified (Chữ Giản thể)": "禺", "Unihan_Traditional (Chữ Phồn thể)": "禺", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ngu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ địa danh cổ hoặc loài vượn đuôi dài, ít khi đứng độc lập trong văn bạch thoại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铲', '{"9000": "3051.0", "Chữ Trung Quốc": "铲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại | 产 | sản | biểu âm | sản xuất (cho âm chǎn) | 铲 = 钅(Kim, biểu nghĩa: kim loại) + 产 (Sản, biểu âm). Giản thể của 鏟 — 钅 chỉ vật bằng kim loại, 产 cho âm đọc chǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sản\": công cụ KIM LOẠI (钅) để XÚC (产gợi âm) — cái xẻng, cái nạo. | Gương Hán-Việt | 铁铲 (thiết sản — xẻng sắt); 铲除 (sản trừ — trừ tận gốc) | Mở khoá kiến thức | Biết 铲 (sản) mở khoá: 铲子 (cái xẻng), 铲除 (diệt trừ tận gốc), 铁铲 (xẻng sắt).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (giản thể của 鏟). 金/钅 (kim loại) là phần biểu nghĩa; 産/产 là phần biểu âm. Tiểu triện ghi dạng truyền thống 鏟. Nghĩa gốc: cái nạo/xẻng kim loại để xúc đất hoặc gọt bằng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nạo bằng sắt, cái xẻng; gọt, nạo, xúc, xới", "Hạng Tần Suất (Jun Da)": "3051.0", "Tần Suất % (Jun Da)": "99.2313704824", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 产", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅产", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "产", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铲", "Unihan_Traditional (Chữ Phồn thể)": "剷", "Pinyin_Xie": "chǎn", "Âm Hán Việt_Xie": "sản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này vừa làm danh từ chỉ cái xẻng vừa làm động từ chỉ hành động xúc hoặc san phẳng đất cát. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chǎn | / | xẻng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酶', '{"9000": "3052.0", "Chữ Trung Quốc": "酶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酉 | dậu | biểu nghĩa | rượu, lên men | 每 | mỗi | biểu âm | mỗi (cho âm méi) | 酶 = 酉 (Dậu, biểu nghĩa: rượu/lên men) + 每 (Mỗi, biểu âm). Chữ hình thanh — 酉 chỉ quá trình lên men, 每 cho âm đọc méi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"môi\": chất LÊN MEN (酉) trong sinh học — enzyme như ''MỖI'' (每) phân tử đều xúc tác. | Gương Hán-Việt | 酶 (môi — enzyme); 酵素 (hiếu tố — tên gọi khác của enzyme) | Mở khoá kiến thức | Biết 酶 (môi) mở khoá: 消化酶 (men tiêu hóa), 酶反应 (phản ứng enzyme).", "Tự nguyên_Xie": "Chữ hình thanh. 酉 (rượu, lên men) là phần biểu nghĩa; 每 là phần biểu âm. Chữ tạo muộn để chỉ khái niệm khoa học hiện đại — enzyme (men xúc tác sinh hóa). Nghĩa: enzyme, men vi sinh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men, enzime", "Hạng Tần Suất (Jun Da)": "3052.0", "Tần Suất % (Jun Da)": "99.2322774404", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酶", "Unihan_Traditional (Chữ Phồn thể)": "酶", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "môi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại men hoặc enzym trong hóa sinh, thường kết hợp với các danh từ khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钝', '{"9000": "3053.0", "Chữ Trung Quốc": "钝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钅 | kim | biểu nghĩa | kim loại | 屯 | đồn | biểu âm | đóng quân (cho âm dùn) | 钝 = 钅(Kim, biểu nghĩa: kim loại) + 屯 (Đồn, biểu âm); chữ hình thanh. Phồn thể 鈍 dùng 金 thay 钅. Bộ kim chỉ chất liệu dao kéo; 屯 cho âm dùn. Hình ảnh: lưỡi kim loại bị tù, không sắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độn\": kim loại (钅) mà đóng đồn (屯) tại chỗ không sắc nét — lưỡi dao độn, tâm trí cũng ''ngu độn'' không bén nhọn. | Gương Hán-Việt | ''độn'' trong ''ngu độn'' (chậm hiểu), 愚钝 (ngu độn), 迟钝 (chậm chạp, đần độn) | Mở khoá kiến thức | Biết 钝 mở khoá: 迟钝 (chậm chạp, đần độn), 愚钝 (ngu ngốc), 钝器 (vật tù, đồ vật không sắc)", "Tự nguyên_Xie": "钝 (phồn thể 鈍) là chữ hình thanh: 金/钅(kim loại) biểu nghĩa; 屯 biểu âm với âm dùn. Nghĩa gốc là ''lưỡi dao kim loại bị tù, không sắc''. Mở rộng sang nghĩa bóng: ''chậm hiểu, đần độn''. Chưa có nguồn học thuật về glyph-origin cổ đại; chưa có nguồn học thuật xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùn, nhụt (không sắc)", "Hạng Tần Suất (Jun Da)": "3053.0", "Tần Suất % (Jun Da)": "99.2331828479", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钝", "Unihan_Traditional (Chữ Phồn thể)": "鈍", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả lưỡi dao cùn hoặc đầu óc chậm chạp, thường đứng sau phó từ chỉ mức độ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氓', '{"9000": "3054.0", "Chữ Trung Quốc": "氓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 氏 | Số nét | 8 | nét | 亡 | vong | biểu âm | mất, chạy trốn (cho âm máng) | 民 | dân | biểu nghĩa | dân chúng, người dân | 氓 = 亡 (Vong, biểu âm) + 民 (Dân, biểu nghĩa: người dân); chữ hình thanh. 亡 cho âm máng; bộ dân chỉ tầng lớp thường dân, dân lưu lạc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"manh\": kẻ dân (民) chạy trốn mất (亡) khỏi quê hương — người ''lưu manh'' gốc là kẻ lưu lạc không nơi chốn, sau thành côn đồ. | Gương Hán-Việt | ''manh'' trong ''lưu manh'' (流氓 — kẻ côn đồ, vô lại), 流氓罪 (tội côn đồ) | Mở khoá kiến thức | Biết 氓 mở khoá: 流氓 (kẻ côn đồ, đầu gấu), 流氓罪 (tội côn đồ), 氓隶 (dân lao dịch cổ xưa)", "Tự nguyên_Xie": "Tiểu triện | 氓 là chữ hình thanh: 民 (dân) biểu nghĩa người dân; 亡 biểu âm với âm máng. Nghĩa gốc là ''dân lưu vong, dân nơi khác đến''. Từ hình ảnh người dân lưu lạc không có chỗ ở ổn định, mở rộng sang nghĩa tiêu cực ''kẻ vô lại, côn đồ'' (lưu manh). Tiểu triện xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dân thường", "Hạng Tần Suất (Jun Da)": "3054.0", "Tần Suất % (Jun Da)": "99.2340856715", "GavinGrover_Once (Chiết tự trực tiếp)": "亡 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亡民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亡", "Unihan_Simplified (Chữ Giản thể)": "氓", "Unihan_Traditional (Chữ Phồn thể)": "氓", "Pinyin_Xie": "máng", "Âm Hán Việt_Xie": "manh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ người dân thời cổ hoặc kẻ vô lại trong tiếng Trung hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匣', '{"9000": "3055.0", "Chữ Trung Quốc": "匣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 7 | nét | 匚 | phương | biểu nghĩa | hộp, thùng | 甲 | giáp | biểu âm | giáp, số một (cho âm xiá) | 匣 = 匚 (Phương, biểu nghĩa: hộp/thùng) + 甲 (Giáp, biểu âm). Chữ hình thanh — 匚 chỉ đồ vật dạng hộp, 甲 cho âm đọc xiá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộp\": cái HỘP (匚) đựng đồ quý hạng NHẤT (甲) — cái hộp/rương nhỏ. | Gương Hán-Việt | 匣子 (hộp tử — cái hộp nhỏ); 首饰匣 (thủ sức hộp — hộp đựng trang sức) | Mở khoá kiến thức | Biết 匣 (hộp) mở khoá: 匣子 (cái hộp), 首饰匣 (hộp trang sức), 木匣 (hộp gỗ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 匚 (hộp) là phần biểu nghĩa; 甲 là phần biểu âm. Tiểu triện ghi cấu trúc này. Nghĩa gốc: cái hộp nhỏ bằng gỗ hoặc kim loại để đựng đồ quý. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hộp", "Hạng Tần Suất (Jun Da)": "3055.0", "Tần Suất % (Jun Da)": "99.2349884952", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匣", "Unihan_Traditional (Chữ Phồn thể)": "匣", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm hậu tố chỉ các loại hộp nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弧', '{"9000": "3056.0", "Chữ Trung Quốc": "弧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 8 | nét | 弓 | cung | biểu nghĩa | cung gỗ | 瓜 | qua | biểu âm | dưa (cho âm hú) | 弧 = 弓 (Cung, biểu nghĩa: cung gỗ) + 瓜 (Qua, biểu âm). Chữ hình thanh — 弓 chỉ hình dạng cong như cung, 瓜 cho âm đọc hú.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": cái CUNG (弓) uốn cong như quả DƯA (瓜) — đường cong hình cung. | Gương Hán-Việt | 弧线 (hồ tuyến — đường cung); 括弧 (quát hồ — ngoặc đơn) | Mở khoá kiến thức | Biết 弧 (hồ) mở khoá: 弧线 (đường cung), 括弧 (ngoặc đơn), 弧形 (hình cung).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 弓 (cung gỗ) là phần biểu nghĩa — đường cong như cung; 瓜 là phần biểu âm. Tiểu triện ghi dạng này. Nghĩa gốc: cái cung gỗ; mở rộng sang mọi đường cong hoặc cung tròn trong toán học. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cung gỗ", "Hạng Tần Suất (Jun Da)": "3056.0", "Tần Suất % (Jun Da)": "99.2358887349", "GavinGrover_Once (Chiết tự trực tiếp)": "弓 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弧", "Unihan_Traditional (Chữ Phồn thể)": "弧", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ hình vòng cung hoặc các cấu trúc có dạng cong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峨', '{"9000": "3057.0", "Chữ Trung Quốc": "峨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 10 | nét | 山 | sơn | biểu nghĩa | núi | 我 | ngã | biểu âm | ta (cho âm é) | 峨 = 山 (Sơn, biểu nghĩa: núi) + 我 (Ngã, biểu âm). Chữ hình thanh — 山 chỉ núi non, 我 cho âm đọc é.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": NÚI (山) cao như TA (我) đứng cao vút — núi NGA Mi hùng vĩ. | Gương Hán-Việt | 峨眉 (nga mi — Nga Mi — tên núi thiêng ở Tứ Xuyên) | Mở khoá kiến thức | Biết 峨 (nga) mở khoá: 峨眉山 (Nga Mi Sơn), 峨眉月 (trăng Nga Mi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 山 (núi) là phần biểu nghĩa; 我 (ta) là phần biểu âm. Tiểu triện và lục thư thông ghi dạng này. Nghĩa gốc: núi cao, đặc biệt dùng cho tên núi 峨眉山 (Nga Mi Sơn) ở Tứ Xuyên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn; (tên núi)", "Hạng Tần Suất (Jun Da)": "3057.0", "Tần Suất % (Jun Da)": "99.236787941", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峨", "Unihan_Traditional (Chữ Phồn thể)": "峨", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ núi non để tả vẻ cao lớn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锥', '{"9000": "3058.0", "Chữ Trung Quốc": "锥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 隹 | chuy | biểu âm | chim đuôi ngắn (cho âm zhuī) | 锥 = 钅(Kim, biểu nghĩa: kim loại) + 隹 (Chuy, biểu âm). Giản thể của 錐 — 钅 chỉ vật bằng kim loại nhọn, 隹 cho âm đọc zhuī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chùy\": công cụ KIM LOẠI (钅) nhọn như CHIM (隹) mổ — cái dùi, đầu nhọn. | Gương Hán-Việt | 圆锥 (viên chùy — hình nón); 锥形 (chùy hình — hình nón) | Mở khoá kiến thức | Biết 锥 (chùy) mở khoá: 圆锥 (hình nón), 锥形 (hình nón/chóp), 锥体 (khối nón).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (giản thể của 錐). 金/钅 (kim loại) là phần biểu nghĩa; 隹 là phần biểu âm. Tiểu triện ghi dạng truyền thống 錐. Nghĩa gốc: cái dùi/mũi khoan nhọn bằng kim loại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dùi; cái dùi", "Hạng Tần Suất (Jun Da)": "3058.0", "Tần Suất % (Jun Da)": "99.2376861136", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锥", "Unihan_Traditional (Chữ Phồn thể)": "錐", "Pinyin_Xie": "zhuī", "Âm Hán Việt_Xie": "chùy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái dùi hoặc động từ mang nghĩa chọc, đâm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揪', '{"9000": "3059.0", "Chữ Trung Quốc": "揪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 秋 | thu | biểu âm | mùa thu (cho âm jiū) | 揪 = 扌(Thủ, biểu nghĩa: tay) + 秋 (Thu, biểu âm). Chữ hình thanh — 扌 chỉ hành động tay, 秋 cho âm đọc jiū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tựu\": dùng TAY (扌) TÚM lấy như gió MÙA THU (秋) cuốn lá — nắm chặt, kéo mạnh. | Gương Hán-Việt | 揪心 (tựu tâm — thắt lòng, lo lắng cồn cào) | Mở khoá kiến thức | Biết 揪 (tựu) mở khoá: 揪心 (thắt lòng), 揪住 (túm lấy), 揪耳朵 (kéo tai).", "Tự nguyên_Xie": "Chữ hình thanh. 手/扌 (tay) là phần biểu nghĩa; 秋 (mùa thu) là phần biểu âm. Chưa có nguồn Wiktionary cụ thể. Nghĩa gốc: nắm chặt, túm, kéo mạnh bằng tay. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "níu, xoắn lại", "Hạng Tần Suất (Jun Da)": "3059.0", "Tần Suất % (Jun Da)": "99.2385827358", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 秋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌秋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揪", "Unihan_Traditional (Chữ Phồn thể)": "揪", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "thu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ tóc, tai hoặc vạt áo để tả hành động túm chặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiū | / | nắm chặt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杠', '{"9000": "3060.0", "Chữ Trung Quốc": "杠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 工 | công | biểu âm | công việc (cho âm gāng) | 杠 = 木 (Mộc, biểu nghĩa: gỗ) + 工 (Công, biểu âm); chữ hình thanh. Bộ mộc chỉ chất liệu gỗ làm cán, đòn; 工 cho âm gāng. Kim văn và tiểu triện xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giang\": gỗ (木) thẳng như thước thợ (工) — cây đòn gỗ thẳng làm 杠杆 (đòn bẩy) hay xà thể dục. | Gương Hán-Việt | ''giang'' trong ''khu giang'' (cây đòn, cán cờ), 杠杆 (giang can — đòn bẩy) | Mở khoá kiến thức | Biết 杠 mở khoá: 杠杆 (đòn bẩy), 杠铃 (tạ đòn), 单杠 (xà đơn), 双杠 (xà kép)", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 杠 là chữ hình thanh: 木 (gỗ) biểu nghĩa cán, gậy bằng gỗ; 工 biểu âm với âm gāng. Nghĩa gốc là ''cái cầu nhỏ bắc bằng gỗ'' hoặc ''cán cờ gỗ''. Mở rộng sang ''thanh ngang, đòn bẩy, xà''. Kim văn và tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cán cờ; cái cầu nhỏ", "Hạng Tần Suất (Jun Da)": "3060.0", "Tần Suất % (Jun Da)": "99.2394778076", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杠", "Unihan_Traditional (Chữ Phồn thể)": "杠", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "cống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ thanh xà thể thao hoặc đòn bẩy trong cơ học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吭', '{"9000": "3061.0", "Chữ Trung Quốc": "吭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 亢 | kháng | biểu âm | cao (cho âm kēng) | 吭 = 口 (Khẩu, biểu nghĩa: miệng) + 亢 (Kháng, biểu âm). Chữ hình thanh — 口 chỉ âm thanh phát ra từ miệng/cổ họng, 亢 cho âm đọc kēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháng\": cái MIỆNG (口) KHÁNG cự — cổ họng phát ra tiếng kêu kháng. | Gương Hán-Việt | 一声不吭 (nhất thanh bất kháng — không hé một lời) | Mở khoá kiến thức | Biết 吭 (kháng) mở khoá: 吭声 (lên tiếng), 一声不吭 (câm như hến).", "Tự nguyên_Xie": "Chữ hình thanh. 口 (miệng) là phần biểu nghĩa; 亢 là phần biểu âm. Nghĩa gốc: cổ họng; cũng có nghĩa phát ra âm thanh. Thường dùng trong thành ngữ 一声不吭 (không hé răng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cổ họng", "Hạng Tần Suất (Jun Da)": "3061.0", "Tần Suất % (Jun Da)": "99.2403723627", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吭", "Unihan_Traditional (Chữ Phồn thể)": "吭", "Pinyin_Xie": "kēng", "Âm Hán Việt_Xie": "khang, hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong cấu trúc phủ định để chỉ việc không hé răng nửa lời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崛', '{"9000": "3062.0", "Chữ Trung Quốc": "崛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 11 | nét | 山 | sơn | biểu nghĩa | núi | 屈 | khuất | biểu âm | cúi (cho âm jué) | 崛 = 山 (Sơn, biểu nghĩa: núi) + 屈 (Khuất, biểu âm). Chữ hình thanh — 山 chỉ sự nổi lên của núi, 屈 cho âm đọc jué.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": NÚI (山) TRỖI DẬY (屈khuất ngược lại) — vươn lên đột ngột, quật khởi. | Gương Hán-Việt | 崛起 (quật khởi — trỗi dậy, vươn lên mạnh mẽ) | Mở khoá kiến thức | Biết 崛 (quật) mở khoá: 崛起 (trỗi dậy), từ thường gặp khi nói về sự phát triển của quốc gia.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 山 (núi) là phần biểu nghĩa; 屈 là phần biểu âm. Tiểu triện ghi dạng này. Nghĩa gốc: núi nổi lên đột ngột; mở rộng sang nghĩa trỗi dậy, vươn lên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một mình trồi lên, trỗi dậy", "Hạng Tần Suất (Jun Da)": "3062.0", "Tần Suất % (Jun Da)": "99.2412669178", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崛", "Unihan_Traditional (Chữ Phồn thể)": "崛", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ kết hợp với khởi để chỉ sự trỗi dậy của một thế lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诬', '{"9000": "3063.0", "Chữ Trung Quốc": "诬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 讠 | biểu nghĩa | lời nói, ngôn ngữ (bộ ngôn giản thể) | 巫 | vu | biểu âm | thầy phù thuỷ (cho âm wū) | 诬 là giản thể của 誣: 訁→讠(Ngôn, biểu nghĩa: lời nói) + 巫 (Vu, biểu âm); chữ hình thanh. Bộ ngôn chỉ lời nói; 巫 cho âm wū. Hình ảnh: lời nói như phù chú của thầy phù thuỷ — bịa đặt, không có thật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": lời nói (讠) của kẻ phù thuỷ (巫) — lời bịa đặt như phép phù mà không có thật, chính là ''vu cáo'' trong tiếng Việt. | Gương Hán-Việt | ''vu'' trong ''vu cáo'' (诬告 — vu khống, cáo gian), 诬陷 (vu hãm — vu cáo hãm hại) | Mở khoá kiến thức | Biết 诬 mở khoá: 诬陷 (vu cáo, hãm hại), 诬告 (vu khống), 诬蔑 (vu khống bôi nhọ)", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 诬 (phồn thể 誣) là giản thể hoá của 誣: 訁→讠. Chữ hình thanh: 訁/讠(lời nói) biểu nghĩa; 巫 biểu âm với âm wū. Nghĩa cốt lõi là ''nói sai sự thật, vu cáo, vu khống''. Tiểu triện và Lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xằng bậy (không mà nói có)", "Hạng Tần Suất (Jun Da)": "3063.0", "Tần Suất % (Jun Da)": "99.2421583721", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 巫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠巫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诬", "Unihan_Traditional (Chữ Phồn thể)": "誣", "Pinyin_Xie": "wū", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ người để biểu thị hành vi vu oan. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冉', '{"9000": "3064.0", "Chữ Trung Quốc": "冉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冂 | Số nét | 5 | nét | 冉 | nhiễm | tượng hình | tóc rủ xuống hoặc vành mai rùa | 冉 là chữ tượng hình/chỉ sự. Theo Thuyết Văn (lục thư tiêu chỉ sự — liushu p), có thể là hình tóc rủ xuống (dạng nguyên thủy của 髯 — râu) hoặc vành mai rùa. Hình thái không rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiễm\": hình tóc rủ xuống CHẬM RÃI — 冉冉 (nhiễm nhiễm) nghĩa là từ từ, nhẹ nhàng. | Gương Hán-Việt | 冉冉 (nhiễm nhiễm — chậm rãi, nhẹ nhàng); họ Nhiễm trong lịch sử | Mở khoá kiến thức | Biết 冉 (nhiễm) mở khoá: 冉冉升起 (từ từ mọc lên), 冉有 (Nhiễm Hữu — học trò Khổng Tử).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ tượng hình hoặc chỉ sự, không rõ nguồn gốc. Có thể mô tả tóc rủ xuống (dạng cổ của 髯 — râu) hoặc vành mai rùa. Kim văn và tiểu triện lưu giữ hình thái đơn giản. Nghĩa dùng nhiều nhất: họ Nhiễm (tên riêng) và trạng từ 冉冉 (nhiễm nhiễm — chậm rãi, nhẹ nhàng). | Theo Wiktionary · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1599.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Quynh (014) Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thổ (số 032 - đất/ 土) nằm lồng trong bộ Quynh (số 014 - vùng biên giới/ 冂). Giải thích sự chuyển ý: Nhiễm là sự vật từ từ, dần dần hiển lộ ra (nhiễm nhiễm). Cũng mang nghĩa là rủ xuống mềm mại.", "Nghĩa Tiếng Việt_Xie": "họ Nhiễm; yếu ớt", "Hạng Tần Suất (Jun Da)": "3064.0", "Tần Suất % (Jun Da)": "99.2430493097", "GavinGrover_Once (Chiết tự trực tiếp)": "冂 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: lock", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "冂土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "土", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冂", "Unihan_Simplified (Chữ Giản thể)": "冉", "Unihan_Traditional (Chữ Phồn thể)": "冄", "Pinyin_Xie": "rǎn", "Âm Hán Việt_Xie": "nhiễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường dùng làm phó từ dưới dạng láy để miêu tả trạng thái chuyển động chậm rãi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抒', '{"9000": "3065.0", "Chữ Trung Quốc": "抒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 扌 | thủ | biểu nghĩa | tay | 予 | dư | biểu âm | cho, trao (cho âm shū) | 抒 = 扌(Thủ, biểu nghĩa: tay) + 予 (Dư, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động dùng tay; 予 cho âm shū. Tiểu triện xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\": bàn tay (扌) trao cho (予) ra ngoài — như nhà thơ trữ tình 抒情, dùng tay cầm bút tuôn ra cảm xúc. | Gương Hán-Việt | ''trữ'' trong ''trữ tình'' (抒情 — bày tỏ cảm xúc), ''các trữ kỷ kiến'' (各抒己见) | Mở khoá kiến thức | Biết 抒 mở khoá: 抒情 (trữ tình, bày tỏ cảm xúc), 各抒己见 (mỗi người nêu ý kiến), 抒发 (bộc lộ, giải toả)", "Tự nguyên_Xie": "Tiểu triện | 抒 là chữ hình thanh: 扌(手, tay) biểu nghĩa; 予 biểu âm với âm shū. Nghĩa gốc là ''múc, kéo ra'' (như kéo nước từ giếng). Mở rộng sang ''tuôn ra, bày tỏ'' (cảm xúc, ý kiến). Nghĩa hiện đại chủ yếu là ''bày tỏ, diễn đạt'' trong ngữ cảnh cảm xúc/ý kiến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thảo ra, tuôn ra; cởi ra", "Hạng Tần Suất (Jun Da)": "3065.0", "Tần Suất % (Jun Da)": "99.2439402473", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 予", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌予", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "予", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抒", "Unihan_Traditional (Chữ Phồn thể)": "抒", "Pinyin_Xie": "shū", "Âm Hán Việt_Xie": "trữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các danh từ chỉ cảm xúc để diễn tả sự bộc lộ tâm tư. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('庚', '{"9000": "3066.0", "Chữ Trung Quốc": "庚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 8 | nét | 庚 | canh | tượng hình | can thứ 7 trong thập thiên can | 庚 là chữ tượng hình cổ. Kim văn khắc trên đồng dạng huy hiệu tộc 庚 của thị tộc thời Thương. Hình thái gốc không rõ nghĩa đen. Nghĩa chính: Can Canh (thứ 7 trong thập thiên can), dùng trong lịch can chi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": CANH (庚) là can thứ 7 trong thập thiên can — nhớ qua vần Ca-nh, đền-trả, canh-tân. | Gương Hán-Việt | 庚午 (canh ngọ — năm Can Canh Chi Ngọ); 庚子 (canh tý) | Mở khoá kiến thức | Biết 庚 (canh) mở khoá: các năm can chi có chữ 庚 (庚子, 庚午, 庚辰...), 年庚 (tuổi, năm sinh).", "Tự nguyên_Xie": "Giáp cốt văn | Chữ tượng hình. Kim văn ghi hình huy hiệu tộc 庚 của thị tộc Thương. Nghĩa gốc không hoàn toàn rõ. Trong hệ can chi, Canh (庚) là can thứ 7, thuộc Kim, tương ứng với số 7. Giáp cốt văn đã có chữ này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đền trả; Canh (ngôi thứ 7 thuộc hàng Can)", "Hạng Tần Suất (Jun Da)": "3066.0", "Tần Suất % (Jun Da)": "99.2448286009", "GavinGrover_Once (Chiết tự trực tiếp)": "广 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴广", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "庚", "Unihan_Traditional (Chữ Phồn thể)": "庚", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ vị trí thứ bảy trong Thiên Can hoặc dùng trong từ ghép chỉ tuổi tác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悍', '{"9000": "3067.0", "Chữ Trung Quốc": "悍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 忄 | tâm | biểu nghĩa | tâm, tính tình | 旱 | hạn | biểu âm | khô hạn (cho âm hàn) | 悍 = 忄(Tâm, biểu nghĩa: tính tình) + 旱 (Hạn, biểu âm). Chữ hình thanh — 忄 chỉ tâm tính, 旱 cho âm đọc hàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãn\": TÂM (忄) CỨNG như đất HẠN HÁN (旱) — hung hãn, dữ tợn không nao núng. | Gương Hán-Việt | 凶悍 (hung hãn — hung tợn dữ dằn); 悍妇 (hãn phụ — người đàn bà hung ác) | Mở khoá kiến thức | Biết 悍 (hãn) mở khoá: 凶悍 (hung hãn), 强悍 (cường hãn — mạnh mẽ hung dữ), 悍然 (hãn nhiên — ngang ngược).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 心/忄 (tâm, tính tình) là phần biểu nghĩa; 旱 là phần biểu âm. Chưa có nguồn Wiktionary cụ thể. Nghĩa gốc: dũng mãnh, hung hãn, dữ tợn — tâm tính cứng như đất khô. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hung mạnh, dữ tợn", "Hạng Tần Suất (Jun Da)": "3067.0", "Tần Suất % (Jun Da)": "99.2457148874", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悍", "Unihan_Traditional (Chữ Phồn thể)": "悍", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm định ngữ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả tính cách hung hãn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靡', '{"9000": "3068.0", "Chữ Trung Quốc": "靡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 非 | Số nét | 19 | nét | 麻 | ma | biểu âm | gai dầu (cho âm mǐ) | 非 | phi | biểu nghĩa | sai, tản ra | 靡 = 麻 (Ma, biểu âm) + 非 (Phi, biểu nghĩa). Chữ hình thanh — 非 gợi nghĩa tản ra/phân tán, 麻 cho âm đọc mǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\": TẢN RA (非) như sợi GAI DẦU (麻) — phân tán, lãng phí, đổ rạp xuống. | Gương Hán-Việt | 靡靡之音 (mị mị chi âm — âm nhạc ủy mị); 所向披靡 (sở hướng phi mị — không gì cản được) | Mở khoá kiến thức | Biết 靡 (mị) mở khoá: 所向披靡 (không gì cản), 靡靡之音 (âm nhạc ủy mị), 披靡 (tan tác).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 非 (sai/tản ra) là phần biểu nghĩa; 麻 là phần biểu âm. Tiểu triện và lục thư thông ghi dạng này. Nghĩa gốc: phân tán, tan rã; mở rộng sang lãng phí, đổ ngã, hoặc vắng vẻ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lãng phí; hoang phí; giạt", "Hạng Tần Suất (Jun Da)": "3068.0", "Tần Suất % (Jun Da)": "99.2466011739", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "靡", "Unihan_Traditional (Chữ Phồn thể)": "靡", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mĩ, mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng trong văn viết cổ làm động từ chỉ sự lãng phí hoặc tính từ chỉ sự xa hoa, suy yếu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晦', '{"9000": "3069.0", "Chữ Trung Quốc": "晦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 11 | nét | 日 | nhật | biểu nghĩa | mặt trời | 每 | mỗi | biểu âm | mỗi (cho âm huì) | 晦 = 日 (Nhật, biểu nghĩa: mặt trời) + 每 (Mỗi, biểu âm). Chữ hình thanh — 日 chỉ ánh sáng mặt trời, 每 cho âm đọc huì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": MẶT TRỜI (日) khuất mỗi ngày — ngày HỐI tối tăm cuối tháng, u ám, bí ẩn. | Gương Hán-Việt | 晦气 (hối khí — xui xẻo); 晦涩 (hối sắc — khó hiểu, tối nghĩa) | Mở khoá kiến thức | Biết 晦 (hối) mở khoá: 晦气 (xui xẻo), 晦涩 (tối nghĩa), 晦暗 (u ám).", "Tự nguyên_Xie": "Bạch thư | Chữ hình thanh. 日 (mặt trời) là phần biểu nghĩa — ngày tối không thấy mặt trời; 每 là phần biểu âm. Bạch thư (silk script) đã có dạng chữ này. Nghĩa gốc: ngày hối — ngày cuối tháng âm lịch (không trăng, tối tăm); mở rộng sang tối tăm, u ám, khó hiểu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày hối (ngày cuối cùng của tháng âm lịch)", "Hạng Tần Suất (Jun Da)": "3069.0", "Tần Suất % (Jun Da)": "99.2474869437", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晦", "Unihan_Traditional (Chữ Phồn thể)": "晦", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ ngày cuối tháng hoặc làm tính từ bổ nghĩa cho danh từ để chỉ sự tối tăm, mờ mịt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('醋', '{"9000": "3070.0", "Chữ Trung Quốc": "醋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 15 | nét | 酉 | dậu | biểu nghĩa | rượu, đồ lên men | 昔 | tích | biểu âm | xưa (gần âm cù) | 醋 = 酉 (Dậu, biểu nghĩa: rượu/đồ lên men) + 昔 (Tích, biểu âm); chữ hình thanh. Sản phẩm lên men từ rượu, gốc nghĩa ''giấm''. Mở rộng sang nghĩa ''ghen tuông'' trong tiếng Trung hiện đại (ăn giấm = ghen).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thố\": 酉 (rượu) + 昔 (xưa) — rượu để lâu hoá giấm, đúng nghĩa ''giấm, ghen'' trong 醋, 吃醋 (ăn giấm = ghen). | Gương Hán-Việt | ''thố'' trong ''thố giấm'' (giấm chua) — gần với ''tủ'' (tủ giấm) trong tiếng Việt | Mở khoá kiến thức | Nắm 醋 mở khoá từ HSK 5 và khẩu ngữ: 醋, 吃醋, 醋意.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 醋 là hình thanh: 酉 (rượu, biểu nghĩa — bộ liên quan tới đồ lên men) + 昔 (Tích, biểu âm). Nghĩa gốc ''giấm'' (sản phẩm lên men tiếp từ rượu). Trong tiếng Trung khẩu ngữ, 吃醋 (ăn giấm) = ghen tuông — liên quan tới câu chuyện vua Đường ban giấm cho vợ Phòng Huyền Linh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giấm; ghen tuông", "Hạng Tần Suất (Jun Da)": "3070.0", "Tần Suất % (Jun Da)": "99.2483716798", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 昔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉昔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "醋", "Unihan_Traditional (Chữ Phồn thể)": "醋", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "thố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ giấm ăn hoặc dùng ẩn dụ làm tân ngữ cho động từ chỉ sự ghen tuông trong tình cảm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Từ đơn | Từ vựng HSK 5: giấm | / | cù | / | giấm | Xuất hiện trong lộ trình | HSK | HSK 5 | · | Gia đình | New HSK | New HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壕', '{"9000": "3071.0", "Chữ Trung Quốc": "壕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 17 | nét | 土 | thổ | biểu nghĩa | đất | 豪 | hào | biểu âm | hào kiệt (cho âm háo) | 壕 = 土 (Thổ, biểu nghĩa: đất) + 豪 (Hào, biểu âm). Chữ hình thanh — 土 chỉ vật làm bằng đất, 豪 cho âm đọc háo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": rãnh ĐẤT (土) bao quanh thành của NGƯỜI HÀO KIỆT (豪) — cái hào phòng thủ. | Gương Hán-Việt | 壕沟 (hào câu — rãnh chiến; hào); 战壕 (chiến hào — hào chiến đấu) | Mở khoá kiến thức | Biết 壕 (hào) mở khoá: 战壕 (chiến hào), 壕沟 (rãnh/hào đào), 护城河 (hào nước bảo vệ thành).", "Tự nguyên_Xie": "Chữ hình thanh. 土 (đất) là phần biểu nghĩa; 豪 là phần biểu âm. Nghĩa gốc: hào — rãnh đào trong đất bao quanh thành trì để phòng thủ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hào xây quanh thành", "Hạng Tần Suất (Jun Da)": "3071.0", "Tần Suất % (Jun Da)": "99.2492548656", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 豪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土豪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "壕", "Unihan_Traditional (Chữ Phồn thể)": "壕", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ phương vị hoặc làm tân ngữ cho động từ đào, đắp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锯', '{"9000": "3072.0", "Chữ Trung Quốc": "锯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 居 | cư | biểu âm | ở (cho âm jù) | 锯 = 钅(Kim, biểu nghĩa: kim loại) + 居 (Cư, biểu âm). Giản thể của 鋸 — 钅 chỉ công cụ kim loại, 居 cho âm đọc jù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cứ\": công cụ KIM LOẠI (钅) CƯ (居) vĩnh viễn trong xưởng — cái cưa không bao giờ rời. | Gương Hán-Việt | 锯子 (cứ tử — cái cưa); 电锯 (điện cứ — cưa điện) | Mở khoá kiến thức | Biết 锯 (cứ) mở khoá: 锯子 (cái cưa), 电锯 (cưa điện), 钢锯 (cưa thép).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (giản thể của 鋸). 金/钅 (kim loại) là phần biểu nghĩa; 居 là phần biểu âm. Tiểu triện ghi dạng truyền thống 鋸. Nghĩa gốc: cái cưa kim loại dùng để xẻ gỗ hoặc kim loại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cưa; cái cưa", "Hạng Tần Suất (Jun Da)": "3072.0", "Tần Suất % (Jun Da)": "99.2501380514", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锯", "Unihan_Traditional (Chữ Phồn thể)": "鋸", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ công cụ hoặc làm động từ đứng trước danh từ chỉ vật liệu cần cắt xẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jù | / | cưa | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Xây dựng và cải tạo", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('夭', '{"9000": "3073.0", "Chữ Trung Quốc": "夭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 4 | nét | 夭 | yểu | tượng hình | hình người nghiêng người về phía trước — trẻ trung, năng động | 夭 là chữ chỉ sự (liushu i). Giáp cốt văn và bạch thư vẽ hình người nghiêng về phía trước — tư thế chạy, trẻ trung. Cũng là bộ phận trên của chữ 走 (chạy). Nghĩa gốc: trẻ trung, tươi tắn; sau chuyển sang chết yểu (chết lúc còn trẻ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yểu\": người trẻ nghiêng mình chạy — trẻ YỂU MỆnh, chết sớm khi đang tươi tắn. | Gương Hán-Việt | 夭折 (yểu chiết — chết yểu, đứt gãy non); 夭亡 (yểu vong — chết non) | Mở khoá kiến thức | Biết 夭 (yểu) mở khoá: 夭折 (chết yểu, đứt gánh), 夭亡 (chết non), 天夭 (thiên yểu — chết sớm).", "Tự nguyên_Xie": "Giáp cốt văn | Bạch thư | Chữ chỉ sự (tượng hình). Giáp cốt văn vẽ người nghiêng mình về phía trước — hình ảnh năng động, trẻ trung. Bạch thư giữ hình thái gần gốc. Nghĩa gốc: trẻ trung, tươi mơn mởn; nghĩa phái sinh: chết yểu (chết sớm). Cũng là thành phần trên của chữ 走. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "19.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đại (17)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Đại (chữ số 17) + nét phẩy trên đầu. Ngụ ý cái đầu đã bị chém lìa khỏi cổ, tất phải chết non.", "Nghĩa Tiếng Việt_Xie": "rờn rờn, mơn mởn; tai vạ", "Hạng Tần Suất (Jun Da)": "3073.0", "Tần Suất % (Jun Da)": "99.2510212372", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒ + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇒大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "夭", "Unihan_Traditional (Chữ Phồn thể)": "夭", "Pinyin_Xie": "yāo", "Âm Hán Việt_Xie": "yểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả vẻ mơn mởn hoặc làm động từ chỉ việc qua đời khi còn quá trẻ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咦', '{"9000": "3074.0", "Chữ Trung Quốc": "咦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 夷 | di | biểu âm | người Di (cho âm yí) | 咦 = 口 (Khẩu, biểu nghĩa: miệng) + 夷 (Di, biểu âm). Chữ hình thanh — 口 chỉ âm thanh phát ra từ miệng, 夷 cho âm đọc yí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": MIỆNG (口) phát âm kinh ngạc — \"ồ!\", \"ê!\", \"ôi sao!\" — thán từ bất ngờ. | Gương Hán-Việt | 咦 (di — ồ, ôi, thán từ ngạc nhiên) | Mở khoá kiến thức | Biết 咦 (di) mở khoá: thán từ ngạc nhiên trong văn nói tiếng Trung hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 口 (miệng) là phần biểu nghĩa; 夷 là phần biểu âm. Tiểu triện ghi dạng này. Nghĩa gốc: thán từ biểu thị ngạc nhiên (ôi, ồ, ê!). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gào; ôi dào, ôi chao, ồ (thán từ)", "Hạng Tần Suất (Jun Da)": "3074.0", "Tần Suất % (Jun Da)": "99.2519018391", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咦", "Unihan_Traditional (Chữ Phồn thể)": "咦", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng độc lập ở đầu câu để biểu thị sự ngạc nhiên hoặc nghi vấn trước một sự việc. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侈', '{"9000": "3075.0", "Chữ Trung Quốc": "侈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 多 | đa | biểu âm | nhiều (cho âm chǐ) | 侈 = 亻(Nhân, biểu nghĩa: người) + 多 (Đa, biểu âm); chữ hình thanh. Bộ nhân chỉ hành vi của người; 多 cho âm chǐ và gợi ý ''quá nhiều, thái quá''. Tiểu triện và Lục thư thông xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xỉ\": người (亻) cứ muốn nhiều (多) hơn mức cần — hình ảnh kẻ ''xa xỉ'', mua hàng hiệu mãi không dừng. | Gương Hán-Việt | ''xỉ'' trong ''xa xỉ'' (奢侈 — hoang phí), ''xỉ mạn'' (phóng túng) | Mở khoá kiến thức | Biết 侈 mở khoá: 奢侈 (xa hoa, hoang phí), 奢侈品 (hàng xa xỉ), 侈靡 (xa xỉ phung phí)", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 侈 là chữ hình thanh: 亻(人, người) biểu nghĩa; 多 biểu âm với âm chǐ. 多 cũng gợi ý nghĩa ''quá mức, thái quá''. Nghĩa gốc là ''hành vi con người quá mức, phóng túng, hoang phí''. Chủ yếu dùng trong từ 奢侈 (xa xỉ). Tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "104.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Đa (103)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhân đứng (số 12) và chữ Đa (số 103) . Người mà tiêu xài nhiều là kẻ hoang phí, không biết tiết kiệm. Giải thích sự chuyển ý: Chữ Đa (nhiều) chỉ âm, chữ Nhân (người) chỉ ý. Người mà tiêu xài quá nhiều (đa) của cải vật chất thì gọi là kẻ xa xỉ (Xỉ). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Đa và chữ Xỉ có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Đa và Xỉ).*", "Nghĩa Tiếng Việt_Xie": "phí phạm, phí của", "Hạng Tần Suất (Jun Da)": "3075.0", "Tần Suất % (Jun Da)": "99.2527819241", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侈", "Unihan_Traditional (Chữ Phồn thể)": "侈", "Pinyin_Xie": "chǐ", "Âm Hán Việt_Xie": "xỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với các từ khác tạo thành từ ghép chỉ sự hoang phí hoặc làm vị ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婢', '{"9000": "3076.0", "Chữ Trung Quốc": "婢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 卑 | ti | biểu âm | thấp hèn (cho âm bì) | 婢 = 女 (Nữ, biểu nghĩa: phụ nữ) + 卑 (Ti, biểu âm kiêm hội ý). Chữ hình thanh kiêm hội ý — 女 chỉ phụ nữ, 卑 (thấp hèn) vừa cho âm vừa gợi thân phận thấp kém.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tì\": người PHỤ NỮ (女) THẤP HÈN (卑) — tì nữ, con hầu, nữ nô lệ. | Gương Hán-Việt | 婢女 (tì nữ — tớ gái, hầu nữ); 奴婢 (nô tì — nô lệ) | Mở khoá kiến thức | Biết 婢 (tì) mở khoá: 婢女 (tớ gái), 奴婢 (nô tì), 侍婢 (hầu thiếp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh kiêm hội ý. 女 (phụ nữ) là phần biểu nghĩa; 卑 (thấp hèn) vừa là phần biểu âm vừa gợi nghĩa — người phụ nữ có thân phận thấp kém. Tiểu triện và lục thư thông ghi dạng này. Nghĩa gốc: tớ gái, nữ nô, hầu nữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tớ gái; hầu gái; nữ nô; con sen; con ở; nô tì", "Hạng Tần Suất (Jun Da)": "3076.0", "Tần Suất % (Jun Da)": "99.2536594253", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婢", "Unihan_Traditional (Chữ Phồn thể)": "婢", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ người, đóng vai trò làm chủ ngữ hoặc tân ngữ trong các ngữ cảnh cổ trang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猾', '{"9000": "3077.0", "Chữ Trung Quốc": "猾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 12 | nét | 犭 | khuyển | biểu nghĩa | chó, thú vật | 骨 | cốt | biểu âm | xương — cho âm cốt/hoạt | 猾 = 犭(Khuyển, biểu nghĩa: thú) + 骨 (Cốt, biểu âm). Wiktionary không ghi ls code chi tiết. Cấu trúc gợi ý hình thanh: bộ khuyển chỉ thú vật (gian xảo như con thú); 骨 cho âm huá (gần hoạt). Gian xảo như thú dữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạt\": thú (犭-Khuyển) xương (骨-Cốt) — con thú ranh ma linh hoạt lắt léo. Hoạt = xảo quyệt linh hoạt. | Gương Hán-Việt | hoạt trong ''hoạt động, linh hoạt'' — cùng âm; 猾 thiên nghĩa tiêu cực: xảo quyệt | Mở khoá kiến thức | Biết 猾 mở khoá: 狡猾 (giảo hoạt – xảo quyệt), 猾吏 (hoạt lại – quan xảo quyệt).", "Tự nguyên_Xie": "猾 gồm 犭(khuyển – chó/thú) và 骨 (cốt – xương). Wiktionary không có glyphOrigin chi tiết. Cấu trúc gợi ý thú (犭) xảo quyệt như kẻ chỉ còn da bọc xương (骨) — ranh ma. Nghĩa là gian xảo, xảo quyệt. Từ thông dụng: 狡猾 (giảo hoạt – xảo quyệt). Chưa có nguồn học thuật đầy đủ. Chưa có nguồn học thuật đầy đủ về glyphOrigin. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm loạn; giảo hoạt", "Hạng Tần Suất (Jun Da)": "3077.0", "Tần Suất % (Jun Da)": "99.2545364097", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 骨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭骨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "骨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猾", "Unihan_Traditional (Chữ Phồn thể)": "猾", "Pinyin_Xie": "huá", "Âm Hán Việt_Xie": "hoạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm vị ngữ hoặc định ngữ để miêu tả tính cách gian xảo, dối trá của con người hoặc động vật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徘', '{"9000": "3078.0", "Chữ Trung Quốc": "徘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 11 | nét | 彳 | xích | biểu nghĩa | bước đi, di chuyển | 非 | phi | biểu âm | không phải (cho âm pái) | 徘 = 彳(Xích, biểu nghĩa: bước đi) + 非 (Phi, biểu âm); chữ hình thanh. Bộ xích chỉ bước chân; 非 cho âm pái. Gần như chỉ dùng trong từ kép 徘徊.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bồi\": bước chân (彳) cứ đi không phải hướng nào (非) — người ''bồi hồi'' cứ bước đi nhưng không đến đâu, lòng lưu luyến mãi. | Gương Hán-Việt | ''bồi'' trong ''bồi hồi'' (徘徊 — đi lại do dự, lưu luyến), cặp đôi với 徊 | Mở khoá kiến thức | Biết 徘 mở khoá: 徘徊 (bồi hồi, đi lại không dứt được)", "Tự nguyên_Xie": "徘 là chữ hình thanh: 彳(bước đi) biểu nghĩa; 非 biểu âm với âm pái. Theo Wiktionary, 徘 gần như chỉ xuất hiện trong 徘徊 (đi lại do dự, đi tới đi lui không thoát ra được). Wiktionary không có mô tả glyph-origin cổ đại chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "do dự", "Hạng Tần Suất (Jun Da)": "3078.0", "Tần Suất % (Jun Da)": "99.2554123605", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徘", "Unihan_Traditional (Chữ Phồn thể)": "徘", "Pinyin_Xie": "pái", "Âm Hán Việt_Xie": "bồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ hồi tạo thành từ ghép chỉ trạng thái đi đi lại lại hoặc phân vân chưa quyết định. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硝', '{"9000": "3079.0", "Chữ Trung Quốc": "硝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 12 | nét | 石 | thạch | biểu nghĩa | đá | 肖 | tiêu | biểu âm | giống (cho âm xiāo) | 硝 = 石 (Thạch, biểu nghĩa: đá/khoáng) + 肖 (Tiêu, biểu âm). Chữ hình thanh — 石 chỉ khoáng chất, 肖 cho âm đọc xiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": KHOÁNG CHẤT (石) trong suốt như BÓNG (肖) — diêm tiêu, đá tiêu dùng làm thuốc súng. | Gương Hán-Việt | 硝石 (tiêu thạch — diêm tiêu); 硝烟 (tiêu yên — khói thuốc súng) | Mở khoá kiến thức | Biết 硝 (tiêu) mở khoá: 硝石 (diêm tiêu), 硝烟 (khói súng), 火硝 (hỏa tiêu — thuốc súng).", "Tự nguyên_Xie": "Chữ hình thanh. 石 (đá/khoáng chất) là phần biểu nghĩa; 肖 là phần biểu âm. Tiểu triện ghi dạng này. Nghĩa gốc: diêm tiêu (KNO₃ — kali nitrat), khoáng chất trong suốt dùng làm thuốc súng; sau mở rộng sang thuộc da. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá tiêu (trong suốt, đốt cháy, dùng làm thuốc pháo)", "Hạng Tần Suất (Jun Da)": "3079.0", "Tần Suất % (Jun Da)": "99.2562883113", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硝", "Unihan_Traditional (Chữ Phồn thể)": "硝", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ các loại muối khoáng hoặc hóa chất liên quan đến diêm tiêu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煽', '{"9000": "3080.0", "Chữ Trung Quốc": "煽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 14 | nét | 火 | hỏa | biểu nghĩa | lửa | 扇 | phiến | biểu âm | cái quạt (cho âm shān) | 煽 = 火 (Hỏa, biểu nghĩa: lửa) + 扇 (Phiến, biểu âm). Chữ hình thanh — 火 chỉ lửa, 扇 cho âm đọc shān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiến\": dùng QUẠT (扇) thổi LỬA (火) — cổ động, kích động như quạt lửa bùng cháy. | Gương Hán-Việt | 煽动 (phiến động — kích động, xúi giục) | Mở khoá kiến thức | Biết 煽 (phiến) mở khoá: 煽动 (kích động), 煽风点火 (quạt gió châm lửa — xúi giục).", "Tự nguyên_Xie": "Chữ hình thanh. 火 (lửa) là phần biểu nghĩa; 扇 (cái quạt) là phần biểu âm. Nghĩa gốc: quạt cho lửa cháy bùng; mở rộng sang kích động, xúi giục. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quạt cho lửa cháy; giúp kẻ ác", "Hạng Tần Suất (Jun Da)": "3080.0", "Tần Suất % (Jun Da)": "99.2571637453", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 扇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火扇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煽", "Unihan_Traditional (Chữ Phồn thể)": "煽", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "phiến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong các từ ghép mang nghĩa kích động hoặc cổ súy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皂', '{"9000": "3081.0", "Chữ Trung Quốc": "皂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 7 | nét | 皂 | tạo | tượng hình | biến thể của 早 (sớm/quả sồi), nghĩa gốc là quả sồi/acorn | 皂 là chữ tượng hình/chỉ sự. Wiktionary ghi: ''Variant form of 皁, in turn a variant form of 早 retaining its original sense acorn.'' Cấu trúc 白+七 hiện tại là dạng biến thể thứ cấp. Không thể phân loại hình thanh hay hội ý theo cơ chế nguyên thủy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tạo\": tạo ra từ quả sồi đen — 肥皂 (phì tạo) là xà phòng. Tạo = xà phòng/đen. | Gương Hán-Việt | tạo trong ''tạo tác, tạo ra'' — cùng âm; 皂 chỉ màu đen và xà phòng, không liên quan tạo ra | Mở khoá kiến thức | Biết 皂 mở khoá: 肥皂 (phì tạo – xà phòng), 皂白 (tạo bạch – đen trắng/phải trái), 肥皂剧 (phì tạo kịch – phim soap opera).", "Tự nguyên_Xie": "皂 là biến thể của 皁, vốn là biến thể của 早 (táo – sớm). Wiktionary ghi rõ: ''variant form of 皁, in turn a variant form of 早 retaining its original sense acorn (quả sồi).'' Quả sồi có màu đen khi chín — từ đó 皂 có nghĩa ''màu đen''. Sau đó dùng trong 肥皂 (féi zào – xà phòng) vì xà phòng thời xưa làm từ mỡ động vật và tro thực vật (có màu đen hoặc xám). Nghĩa gốc ''quả sồi'' không còn dùng độc lập. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đen", "Hạng Tần Suất (Jun Da)": "3081.0", "Tần Suất % (Jun Da)": "99.258037629", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 七", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱白七", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "七", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皂", "Unihan_Traditional (Chữ Phồn thể)": "皂", "Pinyin_Xie": "zào", "Âm Hán Việt_Xie": "tạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ bánh xà phòng hoặc làm tính từ chỉ màu đen trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舵', '{"9000": "3082.0", "Chữ Trung Quốc": "舵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舟 | chu | biểu nghĩa | thuyền | 它 | tha | biểu âm | nó (cho âm duò) | 舵 = 舟 (Chu, biểu nghĩa: thuyền) + 它 (Tha, biểu âm). Chữ hình thanh — 舟 chỉ thuyền bè, 它 cho âm đọc duò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": phần sau con THUYỀN (舟) điều khiển NÓ (它) — bánh lái thuyền. | Gương Hán-Việt | 舵手 (đà thủ — người lái thuyền); 掌舵 (chưởng đà — cầm lái, lãnh đạo) | Mở khoá kiến thức | Biết 舵 (đà) mở khoá: 舵手 (người lái), 掌舵 (cầm bánh lái), 方向舵 (bánh lái hướng).", "Tự nguyên_Xie": "Chữ hình thanh. 舟 (thuyền) là phần biểu nghĩa; 它 là phần biểu âm. Nghĩa gốc: bánh lái thuyền — thiết bị điều khiển hướng đi của thuyền. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "762.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chu (694) Tha (761)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Chu (số 694 - con thuyền) ở bên trái chữ Tha (số 761 - chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tha chỉ âm, bộ Chu chỉ ý. Đà là cái bánh lái của con thuyền.", "Nghĩa Tiếng Việt_Xie": "bánh lái thuyền", "Hạng Tần Suất (Jun Da)": "3082.0", "Tần Suất % (Jun Da)": "99.2589104791", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 它", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟它", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "它", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舵", "Unihan_Traditional (Chữ Phồn thể)": "舵", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng sau động từ điều khiển hoặc kết hợp thành từ ghép chỉ bộ phận lái. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗦', '{"9000": "3083.0", "Chữ Trung Quốc": "嗦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng | 索 | sách | biểu âm | tìm kiếm, dây thừng (cho âm suo) | 嗦 = 口 (Khẩu, biểu nghĩa: miệng) + 索 (Sách, biểu âm); chữ hình thanh. Bộ khẩu chỉ âm thanh từ miệng; 索 cho âm suo. Gần như chỉ dùng trong 哆嗦 (run rẩy) và 啰嗦 (lắm lời). Không có nguồn học thuật về glyph-origin cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sách\": miệng (口) run cầm cập như kéo dây sách (索) — hình ảnh người đang 哆嗦 (run run) vì lạnh hay sợ. | Gương Hán-Việt | ''sách'' trong ''đa sách'' (哆嗦 — run rẩy), ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 嗦 mở khoá: 哆嗦 (run rẩy, bị lạnh hoặc sợ), 啰嗦 (lắm lời, dài dòng)", "Tự nguyên_Xie": "嗦 là chữ hình thanh: 口 (miệng) biểu nghĩa; 索 biểu âm với âm suo. Wiktionary không có glyph-origin cho 嗦. Chữ tạo muộn, chưa thấy giáp cốt/kim văn. Gần như chỉ dùng trong 哆嗦 (run rẩy) — âm thanh răng va vào nhau khi lạnh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: sỉ sách 哆嗦)", "Hạng Tần Suất (Jun Da)": "3083.0", "Tần Suất % (Jun Da)": "99.2597833292", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 索", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口索", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "索", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗦", "Unihan_Traditional (Chữ Phồn thể)": "嗦", "Pinyin_Xie": "suo", "Âm Hán Việt_Xie": "sách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Trợ từ | 助词 | Chữ này chủ yếu làm động từ trong từ láy chỉ sự run rẩy hoặc làm trợ từ ngữ khí cuối câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狈', '{"9000": "3084.0", "Chữ Trung Quốc": "狈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 7 | nét | 犭 | khuyển | biểu nghĩa | chó, loài thú | 贝 | bối | biểu âm | vỏ sò (cho âm bèi) | 狈 = 犭(Khuyển, biểu nghĩa: loài chó, thú) + 贝/貝 (Bối, biểu âm); chữ hình thanh. Phồn thể 狽 dùng 貝 thay 贝. Bộ khuyển chỉ loài thú huyền thoại; 贝 cho âm bèi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": thú (犭) có vỏ sò (贝) đặc biệt — con 狈 huyền thoại chân ngắn phải dựa vào 狼, giống kẻ bẽ bàng 狼狈 không tự đứng vững được. | Gương Hán-Việt | ''bái'' trong ''lang bái'' (狼狈 — bẽ bàng, khốn đốn), 狼狈不堪 (thất thểu khốn cùng) | Mở khoá kiến thức | Biết 狈 mở khoá: 狼狈 (khốn đốn, bẽ bàng), 狼狈不堪 (thất thểu không chịu nổi), 狼狈为奸 (cấu kết với nhau làm ác)", "Tự nguyên_Xie": "狈 (phồn thể 狽) là chữ hình thanh: 犬/犭(chó) biểu nghĩa loài thú; 貝/贝 biểu âm với âm bèi. Theo Wiktionary, 狈 chỉ một loài thú huyền thoại giống chó sói nhưng chân trước ngắn, chân sau dài — phải dựa vào 狼 để đi lại. Từ hình ảnh hai thú phụ thuộc nhau, 狼狈 có nghĩa ''khốn đốn, bẽ bàng'' và ''câu kết với nhau''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống chó sói", "Hạng Tần Suất (Jun Da)": "3084.0", "Tần Suất % (Jun Da)": "99.2606556625", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狈", "Unihan_Traditional (Chữ Phồn thể)": "狽", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ con vật huyền thoại hoặc làm tính từ trong từ ghép chỉ sự chật vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靴', '{"9000": "3085.0", "Chữ Trung Quốc": "靴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 革 | cách | biểu nghĩa | da thuộc | 化 | hóa | biểu âm | biến hóa (cho âm xuē) | 靴 = 革 (Cách, biểu nghĩa: da thuộc) + 化 (Hóa, biểu âm). Chữ hình thanh — 革 chỉ vật liệu da, 化 cho âm đọc xuē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": DA (革) BIẾN HÓA (化) thành ủng cao cổ — đôi giày da bảo vệ. | Gương Hán-Việt | 靴子 (hoa tử — đôi ủng); 马靴 (mã hoa — ủng cưỡi ngựa) | Mở khoá kiến thức | Biết 靴 (hoa) mở khoá: 靴子 (đôi ủng), 马靴 (ủng cưỡi ngựa), 长靴 (ủng cao cổ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 革 (da thuộc) là phần biểu nghĩa; 化 là phần biểu âm. Tiểu triện ghi dạng này. Nghĩa gốc: ủng da — loại giày cao cổ làm bằng da. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giày ủng", "Hạng Tần Suất (Jun Da)": "3085.0", "Tần Suất % (Jun Da)": "99.2615279958", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 化", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革化", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "化", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靴", "Unihan_Traditional (Chữ Phồn thể)": "靴", "Pinyin_Xie": "xuē", "Âm Hán Việt_Xie": "ngoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại giày có cổ cao và thường đứng sau các từ chỉ chất liệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捂', '{"9000": "3086.0", "Chữ Trung Quốc": "捂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 吾 | ngô | biểu âm | tôi, ta | 捂 = 扌(Thủ, biểu nghĩa: tay) + 吾 (Ngô, biểu âm); chữ hình thanh. Phần 扌 chỉ hành động dùng tay, phần 吾 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": hình dung bàn tay (扌) của \"ta\" (吾) ụp xuống che kín — nghĩa chính là che, đậy, giấu. | Gương Hán-Việt | Chữ 捂 đọc Hán-Việt là \"ngô\", dùng trong 捂住 (che lại) — hiếm gặp trong từ Hán-Việt thuần túy tiếng Việt. | Mở khoá kiến thức | Biết 捂 mở khoá nhóm từ chỉ hành động che giấu bằng tay: 捂住 (che kín), 捂脸 (ôm mặt), 捂紧 (ôm chặt).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 扌(tay) chỉ nghĩa — dùng tay che, ép, giữ lại; 吾 (ngô) cho âm. Chữ xuất hiện khá muộn, chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "úp úp mở mở; che giấu; lẩn tránh", "Hạng Tần Suất (Jun Da)": "3086.0", "Tần Suất % (Jun Da)": "99.2623998123", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捂", "Unihan_Traditional (Chữ Phồn thể)": "捂", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "ngộ, ô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đi kèm tân ngữ chỉ bộ phận cơ thể hoặc sự vật bị che đậy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | wǔ | / | che đậy | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疮', '{"9000": "3087.0", "Chữ Trung Quốc": "疮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 9 | nét | 疒 | nạch | biểu nghĩa | bộ chỉ bệnh, tật | 仓 | thương | biểu âm | kho lương | 疮 = 疒(Nạch, biểu nghĩa: bệnh tật) + 仓 (Thương, biểu âm); chữ hình thanh. Bộ 疒 chỉ loại bệnh ngoài da, 仓 (thương) cho âm gốc của dạng phồn thể 瘡.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sang\": bộ bệnh (疒) ghép với kho (仓) — tưởng tượng \"kho\" chứa đầy vết thương (sang thương), nghĩa: mụn nhọt, vết loét. | Gương Hán-Việt | Chữ 疮 đọc Hán-Việt là \"sang\", xuất hiện trong \"sang thương\" (vết thương), \"sang lở\" (lở loét) trong tiếng Việt cổ. | Mở khoá kiến thức | Biết 疮 mở khoá từ y học cổ: 创伤 (thương tích), 疮口 (miệng vết thương), 溃疡/疮疡 (loét).", "Tự nguyên_Xie": "Chữ hình thanh, dạng phồn thể là 瘡. Bộ 疒 (bệnh) chỉ nghĩa — vết thương, loét ngoài da; 倉 (kho) cho âm đọc chuāng. Chưa có giáp cốt văn hay kim văn rõ ràng, chữ tạo muộn hơn để chỉ vết thương da thịt. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị thương", "Hạng Tần Suất (Jun Da)": "3087.0", "Tần Suất % (Jun Da)": "99.2632685281", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疮", "Unihan_Traditional (Chữ Phồn thể)": "瘡", "Pinyin_Xie": "chuāng", "Âm Hán Việt_Xie": "sang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại bệnh ngoài da hoặc vết thương trên cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('郝', '{"9000": "3088.0", "Chữ Trung Quốc": "郝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 9 | nét | 赤 | xích | biểu âm | màu đỏ | 邑 | ấp | biểu nghĩa | thị trấn, vùng đất | 郝 = 赤 (Xích, biểu âm) + 邑/阝 (Ấp, biểu nghĩa: thị trấn, địa danh); chữ hình thanh. Phần 邑 (viết tắt là 阝 bên phải) chỉ đây là địa danh hay họ người; 赤 cho âm hǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hác\": làng ấp (邑) nơi người \"đỏ\" (赤) sinh sống — địa danh cổ ở Sơn Tây, nay là họ Hác (郝) phổ biến ở Trung Quốc. | Gương Hán-Việt | Chữ 郝 đọc Hán-Việt là \"hác\", thường gặp trong họ người: họ Hác (郝姓). | Mở khoá kiến thức | Biết 郝 nhận ra họ Hác trong tên người Trung Quốc: 郝柏村 (Hao Pei-tsun).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh (psc): 赤 (xích, đỏ) cho âm; 邑 (ấp) chỉ nghĩa — địa danh tại tỉnh Sơn Tây cổ đại, sau trở thành họ người. Chỉ thấy trong tiểu triện và Lục thư thông, chưa có giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất); họ Hác", "Hạng Tần Suất (Jun Da)": "3088.0", "Tần Suất % (Jun Da)": "99.2641372439", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "郝", "Unihan_Traditional (Chữ Phồn thể)": "郝", "Pinyin_Xie": "hǎo", "Âm Hán Việt_Xie": "hác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng dùng làm họ của người hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苛', '{"9000": "3089.0", "Chữ Trung Quốc": "苛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 可 | khả | biểu âm | có thể, được | 苛 = 艹(Thảo, biểu nghĩa: cỏ/thực vật) + 可 (Khả, biểu âm); chữ hình thanh. Ban đầu chỉ một loại cỏ nhỏ rậm rạp, về sau mang nghĩa trừu tượng là khắt khe, hà khắc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ha\": cỏ (艹) mà \"khả\" (可) — cỏ dại mọc lan không ai ngăn được, như người hà khắc không biết nới tay. Gợi nhớ: 苛 = hà khắc. | Gương Hán-Việt | Chữ 苛 đọc Hán-Việt là \"ha\", dùng trong 苛刻 (hà khắc), 苛政 (hà chính/chính sách hà khắc) trong văn ngôn tiếng Việt. | Mở khoá kiến thức | Biết 苛 mở khoá: 苛刻 (hà khắc), 苛求 (đòi hỏi quá mức), 苛政猛于虎 (hà chính còn dữ hơn hổ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh (psc): bộ 艹 (cỏ) chỉ đây là tên thực vật; 可 (khả) cho âm kē. Nghĩa gốc là một loại cỏ dại nhỏ mọc dày, sau mở rộng thành \"tỉ mỉ quá mức, khắt khe\". Thấy trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khắt khe", "Hạng Tần Suất (Jun Da)": "3089.0", "Tần Suất % (Jun Da)": "99.2650049262", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苛", "Unihan_Traditional (Chữ Phồn thể)": "苛", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ bổ nghĩa cho danh từ hoặc làm động từ trong các từ ghép chỉ sự hà khắc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秽', '{"9000": "3090.0", "Chữ Trung Quốc": "秽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 禾 | hòa | biểu nghĩa | lúa, ngũ cốc | 歲 | tuế | biểu âm | năm (tuổi), tuế | 秽 = 禾 (Hòa, biểu nghĩa: lúa/ngũ cốc) + 歲 (Tuế, biểu âm); chữ hình thanh. Dạng phồn thể là 穢. Nghĩa gốc: ruộng lúa bị cỏ dại xâm lấn (uế tạp), sau mở rộng thành bẩn thỉu, dâm ô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uế\": ruộng lúa (禾) mà bị năm tháng (歲) làm cho tàn lụi, cỏ dại mọc đầy — uế tạp, ô uế. Nhớ: 秽 = ô uế. | Gương Hán-Việt | Chữ 秽 đọc Hán-Việt là \"uế\", dùng trong 污秽 (ô uế), 淫秽 (dâm uế) — rất quen trong văn phong trang trọng tiếng Việt. | Mở khoá kiến thức | Biết 秽 mở khoá: 污秽 (ô uế), 淫秽 (dâm uế), 秽语 (lời tục tĩu), 自惭形秽 (tự thấy xấu hổ khi so sánh).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh (psc): bộ 禾 (lúa) chỉ nghĩa gốc — ruộng lúa bị cỏ dại làm ô nhiễm; 歲 (tuế) cho âm huì/wèi. Dạng phồn thể 穢, thấy trong Lục thư thông. Nghĩa mở rộng sang \"bẩn thỉu, tục tĩu\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ xấu, cỏ dại; bẩn thỉu", "Hạng Tần Suất (Jun Da)": "3090.0", "Tần Suất % (Jun Da)": "99.265871058", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 岁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾岁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秽", "Unihan_Traditional (Chữ Phồn thể)": "穢", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "uế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự dơ bẩn hoặc làm danh từ chỉ chất thải, đồ bẩn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茜', '{"9000": "3091.0", "Chữ Trung Quốc": "茜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 西 | tây | biểu âm | phía tây | 茜 = 艹(Thảo, biểu nghĩa: cỏ/thực vật) + 西 (Tây, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài thực vật; 西 (tây) cho âm qiàn/xī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tây\": cỏ (艹) mang âm \"tây\" (西) — cây cỏ đỏ phương Tây, chuyên dùng để nhuộm vải thành màu son. Nhớ: 茜 = cây nhuộm đỏ. | Gương Hán-Việt | Chữ 茜 đọc Hán-Việt là \"tây\", ít dùng trong tiếng Việt hiện đại; âm qiàn gặp trong tên riêng (như Thiến 茜). | Mở khoá kiến thức | Biết 茜 nhận ra tên riêng phổ biến người Hoa: 茜茜 (Tiểu Tây), 陈茜 (Trần Thiến); cũng là màu đỏ son đặc trưng.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (psc): bộ 艹 (cỏ) chỉ thực vật; 西 (tây) cho âm đọc. Nghĩa: cây thiến thảo (茜草), dùng làm thuốc nhuộm màu đỏ son từ thời cổ đại. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thiến (dùng để nhuộm đỏ); màu đỏ", "Hạng Tần Suất (Jun Da)": "3091.0", "Tần Suất % (Jun Da)": "99.2667366731", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 西", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹西", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "西", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茜", "Unihan_Traditional (Chữ Phồn thể)": "茜", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "thiến, tây", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ loài cỏ nhuộm hoặc tính từ chỉ màu đỏ sẫm trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搓', '{"9000": "3092.0", "Chữ Trung Quốc": "搓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 差 | sai | biểu âm | chênh lệch, sai (gợi âm cuō) | 搓 = 扌 (Thủ, biểu nghĩa: tay) + 差 (Sai, biểu âm); chữ hình thanh. Bộ thủ cho biết hành động liên quan đến bàn tay; 差 gợi âm cuō.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tha\": tay (扌) xoa qua lại — hình ảnh chà xát bàn tay khi rửa. | Gương Hán-Việt | Ít dùng trong từ Hán-Việt hiện đại; gốc âm ''tha'' thấy trong một số tài liệu cổ. | Mở khoá kiến thức | Biết 搓 (tha) giúp nhận ra nhóm chữ tay-thủ chỉ hành động vật lý: xoa, chà, bóp.", "Tự nguyên_Xie": "搓 là chữ hình thanh: 扌 (tay) biểu nghĩa, 差 biểu âm. Chữ mô tả động tác xát hai tay vào nhau hoặc lăn vật gì đó giữa hai lòng bàn tay. Wiktionary chỉ ghi nhận cấu trúc hình thanh cơ bản, không có nguồn giáp cốt hay kim văn cụ thể. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xát tay", "Hạng Tần Suất (Jun Da)": "3092.0", "Tần Suất % (Jun Da)": "99.2676012547", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搓", "Unihan_Traditional (Chữ Phồn thể)": "搓", "Pinyin_Xie": "cuō", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động vò quần áo hoặc xoa tay. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cuō | / | chà xát | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芸', '{"9000": "3093.0", "Chữ Trung Quốc": "芸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 芸 | vân | tượng hình | chữ tự thân là bộ thảo (艹) + vân (云), chỉ loài cỏ thơm | 芸 = 艹(Thảo) + 云 (Vân); chữ hình thanh (suy từ cấu trúc). Bộ 艹 chỉ thực vật; 云 (vân/mây) gợi âm đọc yún. Chưa có glyph origin rõ ràng từ Wiktionary — nguồn phân tích từ cấu trúc chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vân\": cỏ (艹) tỏa hương như mây (云) — cây vân hương thơm ngát, xưa kẹp vào sách để trừ mối mọt. Nhớ: 芸 = vân hương, tài năng. | Gương Hán-Việt | Chữ 芸 đọc Hán-Việt là \"vân\", dùng trong tên riêng (Vân) và văn ngôn: 芸芸众生 (vân vân chúng sinh — muôn loài chúng sinh). | Mở khoá kiến thức | Biết 芸 mở khoá: 芸芸众生 (muôn loài), 芸香 (cây vân hương), nhận ra chữ trong tên riêng phổ biến.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Cấu trúc gồm bộ 艹 (cỏ) và 云 (vân/mây). Nghĩa gốc chỉ cây vân hương (芸香), một loại thảo mộc thơm dùng để đuổi sâu bọ trong sách vở cổ đại. Sau được dùng rộng hơn với nghĩa: nghệ thuật, tài năng (艺). Chưa có nguồn học thuật rõ ràng cho etymology đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gieo, rắc", "Hạng Tần Suất (Jun Da)": "3093.0", "Tần Suất % (Jun Da)": "99.2684648026", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芸", "Unihan_Traditional (Chữ Phồn thể)": "芸", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "vân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ một loại cỏ thơm hoặc động từ làm cỏ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酱', '{"9000": "3094.0", "Chữ Trung Quốc": "酱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 丬 | hình thể | mảnh vỡ của 將, thành phần hình thể | 夕 | tịch | hình thể | buổi tối, thành phần hình thể | 酉 | dậu | biểu nghĩa | bình rượu/lên men — chỉ thực phẩm lên men | 酱 (giản thể của 醬) = 将 rút gọn (⿰丬夕, biểu âm) + 酉 (Dậu, biểu nghĩa: lên men). Wiktionary ghi: {{Han simp|醬|f=將|t=⿰丬夕}}. Bộ dậu (酉) biểu nghĩa thực phẩm/đồ uống lên men; phần trên là biến thể âm của 將. Tương là thực phẩm lên men.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\": bình lên men (酉-Dậu) — tương đậu, nước tương. Tương trong tiếng Việt chính là 酱 (jiàng). Dậu = bình lên men. | Gương Hán-Việt | tương trong ''nước tương, tương ớt'' — tiếng Việt dùng trực tiếp; 酱油 = nước tương | Mở khoá kiến thức | Biết 酱 mở khoá: 酱油 (tương du – nước tương), 果酱 (quả tương – mứt quả), 豆瓣酱 (đậu biện tương – tương đậu cay).", "Tự nguyên_Xie": "酱 là chữ giản thể của 醬. Wiktionary ghi: {{Han simp|醬|f=將|t=⿰丬夕}}. Chữ truyền thống 醬 gồm 將 (biểu âm) + 酉 (dậu, biểu nghĩa: bình lên men). Nghĩa là tương, nước sốt đặc làm từ đậu hoặc ngũ cốc lên men. Âm jiàng gần với 將 (jiāng). Bộ 酉 xuất hiện trong các chữ liên quan rượu và lên men: 酒, 醒, 醉, 酸. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "các món đồ ăn dầm nát", "Hạng Tần Suất (Jun Da)": "3094.0", "Tần Suất % (Jun Da)": "99.2693268002", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 酉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "酱", "Unihan_Traditional (Chữ Phồn thể)": "醬", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "tương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ các loại nước sốt hoặc động từ với nghĩa muối, ướp thức ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | jiàng | / | nước sốt | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赁', '{"9000": "3095.0", "Chữ Trung Quốc": "赁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 任 | nhâm | biểu âm | gánh vác, đảm nhận (gợi âm lìn) | 贝 | bối | biểu nghĩa | tiền, tài sản | 赁 = 任 (Nhâm, biểu âm) + 贝 (Bối, biểu nghĩa: tài sản, tiền bạc); chữ hình thanh. Bối chỉ quan hệ tài chính; 任 gợi âm lìn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẫm\": tiền (贝) trao tay để nhâm (任) nhiệm — thuê người gánh việc, trả tiền theo hợp đồng. | Gương Hán-Việt | 赁 ít xuất hiện độc lập; thường thấy trong 租赁 (tổ lẫm = thuê mướn). | Mở khoá kiến thức | Biết 赁 (lẫm) mở khóa nhóm từ thuê mướn: 租赁 (thuê), 赁屋 (thuê nhà).", "Tự nguyên_Xie": "Kim văn | 赁 là dạng giản thể của 賃. Theo Wiktionary, 赁 {{Han simp|賃}} — chữ phồn thể 賃 gồm 任 (biểu âm) và 貝 (biểu nghĩa: tiền, của cải), là chữ hình thanh chỉ việc thuê mướn có trả tiền. Kim văn ghi lại hình ảnh giao dịch tài chính liên quan đến thuê lao động hoặc vật dụng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm thuê, thuê mướn", "Hạng Tần Suất (Jun Da)": "3095.0", "Tần Suất % (Jun Da)": "99.2701887978", "GavinGrover_Once (Chiết tự trực tiếp)": "任 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱任贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "任", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赁", "Unihan_Traditional (Chữ Phồn thể)": "賃", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "nhẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ nhà cửa, xe cộ để biểu thị hành động thuê mướn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檐', '{"9000": "3096.0", "Chữ Trung Quốc": "檐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 詹 | chiêm | biểu âm | nói nhiều | 檐 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 詹 (Chiêm, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là kết cấu gỗ; 詹 (chiêm) cho âm yán. Nghĩa: mái hiên, phần gỗ nhô ra của mái nhà.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diêm\": gỗ (木) mà nhiều lời (詹) — mái hiên gỗ nhô ra rộng, như người hay nói, che phủ tất cả. Nhớ: 檐 = mái hiên, diềm mái. | Gương Hán-Việt | Chữ 檐 đọc Hán-Việt là \"diêm\", vay mượn vào tiếng Việt thành \"thềm\" (phần hiên trước nhà): \"ngồi trên thềm\". | Mở khoá kiến thức | Biết 檐 mở khoá: 屋檐 (mái hiên), 飞檐 (mái cong vút — kiến trúc cổ), 帽檐 (vành mũ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 木 (gỗ) chỉ vật liệu và kết cấu kiến trúc; 詹 (chiêm) cho âm yán. Tiểu triện đã có dạng này. Tiếng Việt vay mượn thành \"thềm\" (檐→thềm: phần hiên nhà). Chữ tạo để chỉ mái hiên gỗ trong kiến trúc cổ Trung Quốc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1232.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Chiêm (1116)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/chỉ ý) ở bên trái chữ Chiêm (số 1116 - nói nhiều/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Chiêm chỉ âm, bộ Mộc chỉ ý. Thiềm là mái hiên, phần mái nhà đua ra ngoài bằng gỗ, hành lang.", "Nghĩa Tiếng Việt_Xie": "mái hiên, mái nhà; vành mũ, diềm mũ", "Hạng Tần Suất (Jun Da)": "3096.0", "Tần Suất % (Jun Da)": "99.2710502787", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檐", "Unihan_Traditional (Chữ Phồn thể)": "檐", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "thiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ vị trí hoặc kết hợp thành từ ghép như mái hiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饷', '{"9000": "3097.0", "Chữ Trung Quốc": "饷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn (dạng viết tắt của 食) | 向 | hướng | biểu âm | hướng về | 饷 = 饣(Thực, biểu nghĩa: ăn/thức ăn) + 向 (Hướng, biểu âm); chữ hình thanh. Dạng phồn thể là 餉. Bộ 饣 chỉ liên quan đến lương thực, ăn uống; 向 (hướng) cho âm xiǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hướng\": ăn (饣) theo hướng (向) — quân lương hướng về phía quân sĩ. Nhớ: 饷 = quân lương, tiền lương lính. | Gương Hán-Việt | Chữ 饷 đọc Hán-Việt là \"hướng\", dùng trong 兵饷 (lương bổng binh lính), 发饷 (phát lương) trong văn học cổ. | Mở khoá kiến thức | Biết 饷 mở khoá: 饷银 (lương bạc), 发饷 (phát lương), 犒饷 (khao thưởng quân sĩ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh, dạng giản thể của 餉: bộ 食 (ăn) chỉ nghĩa — lương thực, thức ăn cung cấp cho quân đội; 向 (hướng) cho âm xiǎng. Nghĩa chính: tiền lương hoặc lương thực phát cho lính, sau mở rộng thành \"đãi ăn\". Tiểu triện đã có dạng phồn thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thết đãi; tiền quân lương; một lát, một lúc", "Hạng Tần Suất (Jun Da)": "3097.0", "Tần Suất % (Jun Da)": "99.2719102091", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 向", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣向", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "向", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饷", "Unihan_Traditional (Chữ Phồn thể)": "餉", "Pinyin_Xie": "xiǎng", "Âm Hán Việt_Xie": "hướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ lương bổng của binh lính hoặc động từ mang nghĩa cho ăn, thết đãi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕉', '{"9000": "3098.0", "Chữ Trung Quốc": "蕉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艹 | thảo | biểu nghĩa | bộ Thảo — cây cỏ | 焦 | tiêu | biểu âm | cháy, mượn âm | 蕉 = 艹 (bộ Thảo, cây cỏ, biểu nghĩa) + 焦 (Tiêu, biểu âm); chữ hình thanh. Bộ Thảo gắn với ''cây chuối'', 焦 chỉ cho âm đọc; không liên quan đến nghĩa ''cháy''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\" = (cây) chuối. Nhớ: bộ Thảo 艹 (cây) + 焦 mượn âm — cây có lá to xanh, đó là ''tiêu'' (chuối tiêu). | Gương Hán-Việt | ''Tiêu'' trong chuối tiêu, ba tiêu (tên cây chuối lớn); phân biệt với ''tiêu'' (hạt tiêu - 椒) và ''tiêu'' (tiêu cực - 消). | Mở khoá kiến thức | Biết 蕉 mở khoá 香蕉 (hương tiêu - chuối), 芭蕉 (ba tiêu - chuối tiêu lớn).", "Tự nguyên_Xie": "Theo Wiktionary, 蕉 là chữ hình thanh ghép 艸 (cỏ, cây, viết thành 艹 khi làm bộ thủ, biểu nghĩa) với 焦 (biểu âm). Nghĩa chính là ''cây chuối'' (chuối tiêu). Phần 焦 chỉ mượn âm, không liên quan đến nghĩa ''cháy'' của chữ đó. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây chuối", "Hạng Tần Suất (Jun Da)": "3098.0", "Tần Suất % (Jun Da)": "99.2727696228", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕉", "Unihan_Traditional (Chữ Phồn thể)": "蕉", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các từ khác để chỉ các loại chuối hoặc bộ phận của cây chuối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铀', '{"9000": "3099.0", "Chữ Trung Quốc": "铀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钅 | kim | biểu nghĩa | kim loại (dạng viết tắt của 金) | 由 | do | biểu âm | từ, do, nguyên nhân | 铀 = 钅(Kim, biểu nghĩa: kim loại) + 由 (Do, biểu âm); chữ hình thanh. Dạng phồn thể là 鈾. Bộ 钅 chỉ đây là nguyên tố kim loại; 由 (do) cho âm yóu. Chữ tạo muộn để phiên âm uranium (urani).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"do\": kim loại (钅) có nguồn gốc từ (由) — uranium, nguyên tố có nguồn phóng xạ đặc biệt. Nhớ: 铀 = urani (U). | Gương Hán-Việt | Chữ 铀 đọc Hán-Việt là \"do\", dùng trong khoa học: 铀矿 (mỏ urani), 铀元素 (nguyên tố uranium). | Mở khoá kiến thức | Biết 铀 nhận ra nguyên tố hóa học U trong tiếng Trung: 铀矿 (mỏ urani), 核铀 (urani hạt nhân), nhóm chữ kim loại 钅.", "Tự nguyên_Xie": "Chữ hình thanh (psc) tạo muộn để phiên âm tên nguyên tố uranium: bộ 金 (kim loại) chỉ đây là kim loại; 由 (do) cho âm yóu gần với \"u\" trong uranium. Chữ không có giáp cốt/kim văn — chữ tạo muộn thời hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố uran, U", "Hạng Tần Suất (Jun Da)": "3099.0", "Tần Suất % (Jun Da)": "99.2736280029", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 由", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅由", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "由", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铀", "Unihan_Traditional (Chữ Phồn thể)": "鈾", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "do", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ trong các thuật ngữ vật lý hạt nhân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苔', '{"9000": "3100.0", "Chữ Trung Quốc": "苔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 台 | đài | biểu âm | đài, bệ, sân khấu | 苔 = 艹(Thảo, biểu nghĩa: thực vật) + 台 (Đài, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loại thực vật nhỏ mọc thấp; 台 (đài) cho âm tái/tāi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đài\": cỏ (艹) mọc như trên bệ đài (台) — rêu mọc phủ kín bậc đá ẩm ướt, như tấm thảm xanh trên bệ đình. Nhớ: 苔 = rêu. | Gương Hán-Việt | Chữ 苔 đọc Hán-Việt là \"đài\", ít dùng trong tiếng Việt hiện đại; gặp trong thơ văn cổ: \"rêu phong\" (苔藓) của các công trình cổ. | Mở khoá kiến thức | Biết 苔 mở khoá: 苔藓 (rêu/địa y), 青苔 (rêu xanh), 苔地 (nền phủ rêu).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 艹 (cỏ) chỉ loài thực vật không có rễ mạch dẫn; 台 (đài) cho âm tái. Nghĩa: rêu (苔藓), loại thực vật mọc trên đá ẩm ướt. Chưa thấy trong giáp cốt văn, chữ tạo muộn hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rêu", "Hạng Tần Suất (Jun Da)": "3100.0", "Tần Suất % (Jun Da)": "99.2744858662", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苔", "Unihan_Traditional (Chữ Phồn thể)": "苔", "Pinyin_Xie": "tái", "Âm Hán Việt_Xie": "đài", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài rêu bám trên đá hoặc mặt đất ẩm ướt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赦', '{"9000": "3101.0", "Chữ Trung Quốc": "赦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 赤 | Số nét | 11 | nét | 赤 | xích | biểu âm | màu đỏ | 攵 | phốc | biểu nghĩa | hành động dùng tay/gậy (bộ 攴) | 赦 = 赤 (Xích, biểu âm) + 攵 (Phốc, biểu nghĩa: hành động); chữ hình thanh. Theo Wiktionary: dạng kim văn ban đầu là 𢼜 = 亦 (biểu âm) + 攴 (tay cầm gậy, biểu nghĩa). Sau này phần âm đổi thành 赤. Nghĩa: tha tội, xá tội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xá\": cây gậy (攵) buông xuống trước màu đỏ (赤) — nhà vua mặc long bào đỏ hạ gậy hình, ban ân xá cho tội nhân. Nhớ: 赦 = xá tội, ân xá. | Gương Hán-Việt | Chữ 赦 đọc Hán-Việt là \"xá\", dùng trong 大赦 (đại xá), 赦免 (xá miễn), 赦令 (chiếu xá) — quen trong văn học và lịch sử Việt Nam. | Mở khoá kiến thức | Biết 赦 mở khoá: 大赦 (đại xá — ân xá toàn quốc), 赦免 (tha tội), 赦令 (chiếu xá), 特赦 (đặc xá).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh có lịch sử phức tạp: trong kim văn, dạng gốc là 𢼜, gồm 亦 (biểu âm) + 攴 (tay cầm gậy, chỉ hành động trừng phạt hoặc tha thứ). Về sau phần biểu âm bị thay bằng 赤 (xích). Kim văn và tiểu triện đã có dạng này. Nghĩa: tha thứ, xá miễn tội lỗi — hành động nhà vua ban ân xá. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tha tội", "Hạng Tần Suất (Jun Da)": "3101.0", "Tần Suất % (Jun Da)": "99.2753432128", "GavinGrover_Once (Chiết tự trực tiếp)": "赤 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰赤⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "赤", "Unihan_Simplified (Chữ Giản thể)": "赦", "Unihan_Traditional (Chữ Phồn thể)": "赦", "Pinyin_Xie": "shè", "Âm Hán Việt_Xie": "xá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ tội lỗi hoặc người được tha bổng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缎', '{"9000": "3102.0", "Chữ Trung Quốc": "缎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | tơ lụa (dạng viết tắt của 糸) | 段 | đoạn | biểu âm | đoạn, khúc | 缎 = 纟(Mịch, biểu nghĩa: tơ lụa) + 段 (Đoạn, biểu âm); chữ hình thanh. Dạng phồn thể là 緞. Bộ 纟 chỉ đây là vải sợi tơ; 段 (đoạn) cho âm duàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoạn\": tơ (纟) từng đoạn (段) dệt mịn — vải đoạn, lụa bóng căng từng khúc một. Nhớ: 缎 = vải đoạn, lụa trơn bóng. | Gương Hán-Việt | Chữ 缎 đọc Hán-Việt là \"đoạn\", vay mượn vào tiếng Việt thành \"đoạn\" trong \"vải đoạn\" — loại lụa bóng dùng may áo dài. | Mở khoá kiến thức | Biết 缎 mở khoá: 缎子 (vải đoạn), 绸缎 (lụa đoạn), 锦缎 (gấm đoạn) — nhóm từ vải vóc cao cấp.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh, dạng giản thể của 緞: bộ 糸 (tơ) chỉ loại vải dệt từ tơ; 段 (đoạn) cho âm duàn. Tiểu triện đã có dạng phồn thể. Nghĩa: vải đoạn — loại lụa dày, bóng mịn, dùng may lễ phục. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải đoạn, vải lụa trơn", "Hạng Tần Suất (Jun Da)": "3102.0", "Tần Suất % (Jun Da)": "99.2762000425", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 段", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟段", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "段", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缎", "Unihan_Traditional (Chữ Phồn thể)": "緞", "Pinyin_Xie": "duàn", "Âm Hán Việt_Xie": "đoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ chất liệu vải lụa mịn màng hoặc làm định ngữ bổ nghĩa cho trang phục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舷', '{"9000": "3103.0", "Chữ Trung Quốc": "舷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舟 | Số nét | 11 | nét | 舟 | chu | biểu nghĩa | thuyền, thuyền nhỏ | 玄 | huyền | biểu âm | huyền diệu, đen sâu thẳm | 舷 = 舟 (Chu, biểu nghĩa: thuyền) + 玄 (Huyền, biểu âm); chữ hình thanh. Bộ 舟 chỉ bộ phận của tàu thuyền; 玄 (huyền) cho âm xián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyền\": thuyền (舟) chứa điều huyền bí (玄) — mạn thuyền sâu thẳm, phân chia hai thế giới trên và dưới nước. Nhớ: 舷 = mạn thuyền (左舷/右舷). | Gương Hán-Việt | Chữ 舷 đọc Hán-Việt là \"huyền\", ít dùng đơn lẻ; gặp trong 舷窗 (cửa sổ mạn), 左舷 (mạn trái) trong văn học hàng hải. | Mở khoá kiến thức | Biết 舷 mở khoá: 左舷 (mạn trái), 右舷 (mạn phải), 舷窗 (cửa sổ tròn trên tàu), 舷梯 (cầu thang tàu).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 舟 (thuyền) chỉ bộ phận của tàu; 玄 (huyền) cho âm xián. Nghĩa: mạn thuyền — hai bên thành của tàu thuyền (mạn trái: 左舷, mạn phải: 右舷). Chữ tạo để chỉ cấu trúc tàu thuyền. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mạn thuyền", "Hạng Tần Suất (Jun Da)": "3103.0", "Tần Suất % (Jun Da)": "99.2770548051", "GavinGrover_Once (Chiết tự trực tiếp)": "舟 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舟玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舟", "Unihan_Simplified (Chữ Giản thể)": "舷", "Unihan_Traditional (Chữ Phồn thể)": "舷", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "huyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ phương hướng để xác định vị trí trên tàu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筷', '{"9000": "3104.0", "Chữ Trung Quốc": "筷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 13 | nét | 竹 | trúc | biểu nghĩa | tre | 快 | khoái | biểu âm | nhanh | 筷 = 竹 (Trúc, biểu nghĩa: tre) + 快 (Khoái, biểu âm). Chữ hình thanh tạo muộn: cây đũa làm bằng tre, ăn nhanh — đặc biệt tránh từ kiêng 箸 (đồng âm với 住 ''dừng'') nên người Giang Nam đời Minh dùng 筷 (''khoái'' — nhanh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Khoái'' (筷) nghĩa là ''cây đũa''. Nhớ: 竹 (tre) ở trên + 快 (nhanh) ở dưới — đũa tre giúp ăn nhanh, đó là ''khoái''. | Gương Hán-Việt | Chữ 筷 (Khoái) đặc biệt: cùng âm Hán-Việt ''khoái'' với 快 (nhanh, vui) nhưng nghĩa khác hẳn — là cây đũa. Ít gặp trong từ Hán-Việt văn ngữ; quen với ''đũa'' trong sinh hoạt. | Mở khoá kiến thức | Hiểu 筷 nhớ luôn cụm 筷子 (đũa) — vật dụng hằng ngày trong văn hoá Đông Á.", "Tự nguyên_Xie": "Theo Wiktionary, 筷 là chữ tạo muộn (Minh-Thanh): {{Han compound|竹|快|c1=s|c2=p|ls=psc}} — 竹 (tre) biểu nghĩa, 快 (nhanh) biểu âm. Người dân Giang Nam đời Minh kiêng dùng 箸 (zhù — đũa) vì đồng âm với 住 (zhù — dừng) trên thuyền; họ đổi sang gọi ''khoái nhi'' (快儿 — vật nhanh), sau thêm bộ 竹 thành 筷子. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1813.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (118) Khoái (1684)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 118 - cây tre trúc/ 竹 /chỉ ý) ở trên chữ Khoái (số 1684 - nhanh nhẹn/ 快 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khoái chỉ âm, bộ Trúc chỉ ý. Khoái là đũa (thường làm bằng tre trúc) dùng để gắp thức ăn cho nhanh (khoái tử - đôi đũa).", "Nghĩa Tiếng Việt_Xie": "cây đũa", "Hạng Tần Suất (Jun Da)": "3104.0", "Tần Suất % (Jun Da)": "99.2779085342", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 快", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮快", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "快", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筷", "Unihan_Traditional (Chữ Phồn thể)": "筷", "Pinyin_Xie": "kuài", "Âm Hán Việt_Xie": "khoái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đôi đũa và thường đi kèm với lượng từ chỉ đôi hoặc chiếc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('朔', '{"9000": "3105.0", "Chữ Trung Quốc": "朔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 月 | Số nét | 10 | nét | 屰 | nghịch | biểu âm | ngược, trái chiều (biểu âm) | 月 | nguyệt | biểu nghĩa | mặt trăng, tháng | 朔 = 屰 (Nghịch, biểu âm) + 月 (Nguyệt, biểu nghĩa: mặt trăng); chữ hình thanh. Bộ 月 chỉ liên quan đến chu kỳ mặt trăng; 屰 (nghịch, ngược) cho âm shuò.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sóc\": mặt trăng (月) đi ngược (屰) — ngày mùng một, trăng lẩn khuất, đi ngược chiều mặt trời. Nhớ: 朔 = ngày sóc (mùng 1 âm lịch), phương Bắc. | Gương Hán-Việt | Chữ 朔 đọc Hán-Việt là \"sóc\", dùng trong lịch pháp cổ: 朔望 (sóc vọng — mùng 1 và rằm), 朔日 (ngày sóc). | Mở khoá kiến thức | Biết 朔 mở khoá lịch pháp cổ Trung Hoa: 朔望 (sóc vọng), 朔日 (ngày sóc), 朔方 (phương Bắc), 塑风 (gió bắc).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 月 (mặt trăng) chỉ chu kỳ âm lịch; 屰 (ngược chiều) cho âm shuò. Nghĩa: ngày mùng một âm lịch — thời điểm mặt trăng \"quay lưng\" (trăng non không thấy). Cũng nghĩa phương Bắc trong ngũ hành. Chưa thấy giáp cốt văn rõ ràng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày đầu tiên của chu kỳ trăng, ngày mùng 1; phương Bắc", "Hạng Tần Suất (Jun Da)": "3105.0", "Tần Suất % (Jun Da)": "99.2787586457", "GavinGrover_Once (Chiết tự trực tiếp)": "屰 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰屰月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "朔", "Unihan_Traditional (Chữ Phồn thể)": "朔", "Pinyin_Xie": "shuò", "Âm Hán Việt_Xie": "sóc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ thời gian đầu tháng âm lịch hoặc chỉ phương hướng trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婪', '{"9000": "3106.0", "Chữ Trung Quốc": "婪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 林 | lâm | biểu âm | rừng (gợi âm lán) | 女 | nữ | biểu nghĩa | phụ nữ (bộ chỉ sắc thái nhân tính) | 婪 = 林 (Lâm, biểu âm) + 女 (Nữ, biểu nghĩa); chữ hình thanh. Theo Wiktionary, chữ có liên tưởng cổ: lòng tham của những kẻ quyền lực muốn chiếm đoạt nhiều thứ như rừng cây vô tận. 女 làm phần nghĩa, 林 gợi âm lán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lam\": người (女) đứng giữa rừng (林) mà vẫn muốn nhiều hơn — lòng tham không đáy. | Gương Hán-Việt | 婪 xuất hiện trong 贪婪 (tham lam) — từ Hán-Việt phổ biến trong tiếng Việt. | Mở khoá kiến thức | Biết 婪 (lam) giúp đọc ngay 贪婪 (tham lam) — tính từ chỉ sự thèm khát, ích kỷ.", "Tự nguyên_Xie": "婪 là chữ hình thanh: 林 (rừng cây) biểu âm, 女 biểu nghĩa. Wiktionary ghi chú: tương truyền chữ này phản ánh quan niệm cổ rằng những kẻ tham lam (như vua chúa xưa) muốn sở hữu nhiều thứ như một khu rừng bất tận. Tuy nhiên đây là chú thích dân gian, không phải phân tích ngữ văn học nghiêm túc. Ý nghĩa chính: tham lam, thèm khát. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "373.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nữ (60) Lâm (109)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lâm (số 109 - rừng núi, biến âm) chỉ âm, chữ Nữ (số 86) chỉ ý. Lam là lòng tham, ham muốn nhiều thứ không phải của mình. Giải thích sự chuyển ý: Chữ Lâm (rừng núi) chỉ âm, chữ Nữ (phụ nữ) chỉ ý. Lòng tham của người đàn bà (Nữ) sâu thẳm và âm u như khu rừng (Lâm) không đáy (Lam). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Lâm và chữ Lam có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Lâm và Lam).*", "Nghĩa Tiếng Việt_Xie": "tham lam", "Hạng Tần Suất (Jun Da)": "3106.0", "Tần Suất % (Jun Da)": "99.2796072069", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱林女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婪", "Unihan_Traditional (Chữ Phồn thể)": "婪", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép để chỉ tính tham lam. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('紊', '{"9000": "3107.0", "Chữ Trung Quốc": "紊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 10 | nét | 文 | văn | biểu âm | văn tự, hoa văn (gợi âm wěn) | 糸 | mịch | biểu nghĩa | sợi tơ, chỉ | 紊 = 文 (Văn, biểu âm) + 糸 (Mịch, biểu nghĩa: sợi tơ); chữ hình thanh. 糸 chỉ sợi chỉ rối loạn; 文 gợi âm wěn. Hình ảnh: những sợi tơ (糸) bị rối tung, mất trật tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vặn\": sợi tơ (糸) bị vặn xoắn rối loạn — 紊 nghĩa là hỗn loạn. | Gương Hán-Việt | 紊 xuất hiện trong 紊乱 (vặn loạn = hỗn loạn) và thành ngữ 有条不紊 (có trật tự, ngăn nắp). | Mở khoá kiến thức | Biết 紊 (vặn) giúp đọc ngay 紊乱 (hỗn loạn) và thành ngữ 有条不紊 (đâu vào đấy, có trật tự).", "Tự nguyên_Xie": "Tiểu triện | 紊 là chữ hình thanh: 糸 (sợi tơ) biểu nghĩa, 文 biểu âm. Wiktionary xác nhận cấu trúc này rõ ràng. Tiểu triện (seal script) đã ghi lại hình dạng gần với chữ hiện đại. Nghĩa gốc: những sợi tơ rối — từ đó mở rộng sang nghĩa hỗn loạn, mất trật tự nói chung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rối; loạn; rối ren; hỗn loạn; bối rối; rối loạn", "Hạng Tần Suất (Jun Da)": "3107.0", "Tần Suất % (Jun Da)": "99.2804542178", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱文糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "糸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "紊", "Unihan_Traditional (Chữ Phồn thể)": "紊", "Pinyin_Xie": "wěn", "Âm Hán Việt_Xie": "vấn, vặn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái hỗn loạn hoặc động từ làm mất trật tự. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('厮', '{"9000": "3108.0", "Chữ Trung Quốc": "厮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 厂 | Số nét | 14 | nét | 厂 | hán | biểu nghĩa | mái hiên, bờ vách (bộ chỉ nơi chốn) | 斯 | tư | biểu âm | này, đây; tao nhã | 厮 = 厂 (Hán, biểu nghĩa: mái/nơi chốn) + 斯 (Tư, biểu âm); chữ hình thanh. Là dạng giản thể/biến thể của 廝. Bộ 厂 chỉ nơi người hầu làm việc; 斯 (tư) cho âm sī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": dưới mái (厂) là kẻ \"tư\" (斯) hầu hạ — người hầu chặt củi, kẻ địa vị thấp. Nhớ: 厮 = kẻ hầu, đứa (nói khinh). | Gương Hán-Việt | Chữ 厮 đọc Hán-Việt là \"tư\", dùng trong văn học cổ điển: 厮杀 (đánh giết nhau), 厮混 (lăn lộn cùng), 小厮 (tiểu tư — đứa hầu nhỏ). | Mở khoá kiến thức | Biết 厮 mở khoá ngữ cảnh văn học võ hiệp: 厮杀 (chém giết), 厮混 (qua lại với), 小厮 (đứa hầu), 这厮 (thằng này).", "Tự nguyên_Xie": "Chữ hình thanh (psc), biến thể của 廝: bộ 厂 (mái hiên/nơi làm việc) chỉ người hầu hạ; 斯 (tư) cho âm sī. Nghĩa gốc: kẻ hầu chặt củi, người hầu địa vị thấp. Sau mở rộng thành \"thằng này\", \"đứa\" (khinh thường). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ chặt củi", "Hạng Tần Suất (Jun Da)": "3108.0", "Tần Suất % (Jun Da)": "99.2812996782", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 斯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴厂斯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "厮", "Unihan_Traditional (Chữ Phồn thể)": "厮", "Pinyin_Xie": "sī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Làm danh từ chỉ người hầu hạ hoặc làm phó từ biểu thị hành động tương tác qua lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婿', '{"9000": "3109.0", "Chữ Trung Quốc": "婿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 女 | nữ | biểu nghĩa | phụ nữ, con gái | 胥 | tư | biểu âm | đều, cùng nhau; quan hầu | 婿 = 女 (Nữ, biểu nghĩa: phụ nữ/gia đình người nữ) + 胥 (Tư, biểu âm); chữ hình thanh. Bộ 女 chỉ quan hệ thông qua con gái; 胥 (tư) cho âm xù. Theo Wiktionary: dạng Tần gốc từ 士+咠, sau hợp nhất thành 胥.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tế\": người nữ (女) đón về cùng (胥) nhà — chàng rể gia nhập gia đình nhà vợ. Nhớ: 婿 = con rể, phu tế. | Gương Hán-Việt | Chữ 婿 đọc Hán-Việt là \"tế\", dùng trong \"phu tế\" (夫婿 — chồng, phu quân), 女婿 (con rể) — quen trong văn học cổ điển Việt Nam. | Mở khoá kiến thức | Biết 婿 mở khoá: 女婿 (con rể), 夫婿 (phu tế — chồng trong văn thơ), 乘龙快婿 (rể quý như rồng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (psc): bộ 女 chỉ quan hệ hôn nhân qua phía con gái; 胥 cho âm xù. Tư liệu Tần cho thấy dạng gốc là ⿰士咠 (sĩ+咠), sau thành phần biểu âm hợp nhất vào 胥. Tiểu triện đã có dạng 婿. Nghĩa: con rể, chồng của con gái. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con rể", "Hạng Tần Suất (Jun Da)": "3109.0", "Tần Suất % (Jun Da)": "99.2821446219", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 胥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女胥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婿", "Unihan_Traditional (Chữ Phồn thể)": "壻", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ quan hệ thân tộc trong gia đình. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寥', '{"9000": "3110.0", "Chữ Trung Quốc": "寥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 14 | nét | 宀 | miên | biểu nghĩa | mái nhà, che phủ | 翏 | liệu | biểu âm | (thành phần âm: lông vũ + người) | 寥 = 宀 (Miên, biểu nghĩa: mái che/không gian) + 翏 (Liệu, biểu âm); chữ hình thanh. Bộ 宀 gợi không gian trống rỗng có mái; 翏 cho âm liáo. Wiktionary không có glyph-origin cụ thể — phân tích từ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\": dưới mái (宀) chỉ còn lông bay (翏) — ngôi nhà trống vắng, chỉ còn vài chiếc lông vũ bay lơ lửng. Nhớ: 寥 = liêu, thưa thớt, cô quạnh. | Gương Hán-Việt | Chữ 寥 đọc Hán-Việt là \"liêu\", dùng trong 寂寥 (tịch liêu — vắng vẻ cô đơn), 寥寥 (liêu liêu — thưa thớt). | Mở khoá kiến thức | Biết 寥 mở khoá: 寂寥 (tịch liêu), 寥寥无几 (thưa thớt không đáng kể), 寥若晨星 (ít như sao buổi sáng).", "Tự nguyên_Xie": "Cấu trúc gồm 宀 (mái che) và 翏 (lông vũ + người, gợi sự nhẹ nhàng bay đi). Nghĩa: trống vắng, ít ỏi, cô quạnh. Tiểu triện chưa có dạng rõ ràng. Chưa có nguồn học thuật đầy đủ cho etymology của chữ này. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỗ hư không", "Hạng Tần Suất (Jun Da)": "3110.0", "Tần Suất % (Jun Da)": "99.2829885321", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寥", "Unihan_Traditional (Chữ Phồn thể)": "寥", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả không gian vắng lặng hoặc số lượng ít ỏi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('兢', '{"9000": "3111.0", "Chữ Trung Quốc": "兢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 14 | nét | 克 | khắc | biểu nghĩa | khắc phục, vượt qua (x2 — nhân đôi tạo nghĩa thận trọng) | 克 | khắc | biểu nghĩa | khắc phục, vượt qua (lặp lại) | 兢 = 克 + 克 (Khắc + Khắc, hội ý); chữ hội ý. Hai chữ 克 (khắc phục) đặt cạnh nhau diễn đạt trạng thái luôn tự kiểm soát, thận trọng, nơm nớp lo lắng. Wiktionary chỉ ghi {{Han etym}} mà không phân tích cụ thể; cấu trúc được suy từ IDS ⿰克克.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"căng\": hai lần khắc (克克) — người luôn tự kỷ luật, cảnh giác từng bước, căng thẳng như đi trên đá. | Gương Hán-Việt | 兢 xuất hiện trong 兢兢业业 (căng căng nghiệp nghiệp = cần cù, thận trọng trong công việc). | Mở khoá kiến thức | Biết 兢 (căng) mở khóa thành ngữ 兢兢业业 — mô tả người làm việc tận tâm, cẩn thận.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | 兢 gồm hai chữ 克 (khắc) ghép lại theo kiểu hội ý — nhân đôi ý nghĩa ''kiềm chế, vượt qua khó khăn'' để diễn đạt sự thận trọng, nơm nớp. Giáp cốt văn, kim văn và tiểu triện đều ghi lại hình dạng chữ, cho thấy đây là chữ có lịch sử lâu đời. Wiktionary không cung cấp phân tích chi tiết hơn; cấu trúc hội ý được suy luận từ thành phần IDS. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nơm nớp", "Hạng Tần Suất (Jun Da)": "3111.0", "Tần Suất % (Jun Da)": "99.2838319254", "GavinGrover_Once (Chiết tự trực tiếp)": "克", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴克", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "兢", "Unihan_Traditional (Chữ Phồn thể)": "兢", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "căng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong các từ láy để miêu tả thái độ vô cùng cẩn trọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糙', '{"9000": "3112.0", "Chữ Trung Quốc": "糙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 16 | nét | 米 | mễ | biểu nghĩa | gạo | 造 | tạo | biểu âm | tạo ra (gần âm cāo) | 糙 = 米 (Mễ, biểu nghĩa: gạo) + 造 (Tạo, biểu âm); chữ hình thanh. Gạo chưa xát kỹ còn vỏ trấu, gốc nghĩa ''gạo lứt, gạo thô''. Mở rộng sang ''thô ráp, không tinh xảo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tháo\": 米 (gạo) + 造 (Tạo) — gạo mới làm còn thô chưa xát, đúng nghĩa ''thô ráp'' trong 粗糙 (thô ráp), 糙米 (gạo lứt). | Gương Hán-Việt | ''tháo'' (âm Hán-Việt ít gặp cho chữ này) | Mở khoá kiến thức | Nắm 糙 mở khoá từ HSK 7: 粗糙, 糙米.", "Tự nguyên_Xie": "Theo Wiktionary, 糙 là hình thanh: 米 (gạo, biểu nghĩa) + 造 (Tạo, biểu âm). Nghĩa gốc ''gạo chưa xát kỹ, gạo lứt'' (糙米). Mở rộng sang nghĩa ''thô ráp, xù xì, không tinh xảo'' (粗糙) và ''thô lỗ'' về thái độ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo xay", "Hạng Tần Suất (Jun Da)": "3112.0", "Tần Suất % (Jun Da)": "99.2846748019", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 造", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米造", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "造", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "糙", "Unihan_Traditional (Chữ Phồn thể)": "糙", "Pinyin_Xie": "cāo", "Âm Hán Việt_Xie": "tháo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả bề mặt vật chất hoặc tính chất của công việc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卦', '{"9000": "3113.0", "Chữ Trung Quốc": "卦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卜 | Số nét | 8 | nét | 圭 | khuê | biểu âm | thanh ngọc hình tam giác dùng trong lễ nghi | 卜 | bốc | biểu nghĩa | bói, xem bói | 卦 = 圭 (Khuê, biểu âm) + 卜 (Bốc, biểu nghĩa: bói toán); chữ hình thanh. Theo Wiktionary: phần 圭 vừa là biểu âm vừa gợi lễ nghi (cặp ngọc khuê nghi lễ); 卜 chỉ bói toán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quái\": ngọc lễ (圭) dùng để bói (卜) — mỗi quẻ là một hexagram trong Kinh Dịch, dùng ngọc khuê trong lễ bói. Nhớ: 卦 = quẻ bói, quái trong Kinh Dịch. | Gương Hán-Việt | Chữ 卦 đọc Hán-Việt là \"quái\", dùng phổ biến trong tiếng Việt: Bát Quái (八卦), quẻ bói (卦象), đổi quẻ (变卦). | Mở khoá kiến thức | Biết 卦 mở khoá: 八卦 (Bát Quái), 算卦 (xem quẻ), 变卦 (đổi quẻ — thay đổi quyết định), 卦象 (quái tượng).", "Tự nguyên_Xie": "Chữ hình thanh (psc): 圭 (khuê — ngọc lễ nghi) cho âm guà và gợi bối cảnh nghi lễ bói toán; 卜 (bốc) chỉ hành động bói. Theo Wiktionary: phần biểu âm 圭 đại diện cho cặp ngọc khuê dùng trong nghi lễ. Hệ thống bói toán hexagram (Kinh Dịch). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "995.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khuê (875) Bốc (025)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Khuê (số 875 - ngọc khuê/chỉ âm) ở bên trái bộ Bốc (số 025 - xem bói). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khuê chỉ âm, bộ Bốc chỉ ý. Quái là quẻ bói (bát quái).", "Nghĩa Tiếng Việt_Xie": "quẻ trong Kinh Dịch", "Hạng Tần Suất (Jun Da)": "3113.0", "Tần Suất % (Jun Da)": "99.2855161281", "GavinGrover_Once (Chiết tự trực tiếp)": "圭 + 卜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰圭卜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卜", "Unihan_Simplified (Chữ Giản thể)": "卦", "Unihan_Traditional (Chữ Phồn thể)": "卦", "Pinyin_Xie": "guà", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các động từ hành động liên quan đến bói toán. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槐', '{"9000": "3114.0", "Chữ Trung Quốc": "槐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 鬼 | quỷ | biểu âm | ma quỷ, hồn ma | 槐 = 木 (Mộc, biểu nghĩa: cây) + 鬼 (Quỷ, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là tên loài cây; 鬼 (quỷ) cho âm huái (gần với guǐ). Wiktionary không có glyph-origin rõ ràng — phân tích từ cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hòe\": cây (木) có hồn ma (鬼) trú ngụ — cây hòe cổ thụ trong truyền thuyết Trung Quốc được cho là nơi ma quỷ ẩn náu. Nhớ: 槐 = cây hòe (槐树). | Gương Hán-Việt | Chữ 槐 đọc Hán-Việt là \"hòe\", vay mượn vào tiếng Việt thành \"cây hòe\" (槐树) — loài cây quen thuộc trong thơ văn Việt-Trung. | Mở khoá kiến thức | Biết 槐 mở khoá: 槐树 (cây hòe), 槐花 (hoa hòe), 三槐 (tam hòe — tượng trưng tam công triều đình).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Cấu trúc hình thanh: bộ 木 (cây) chỉ loài thực vật; 鬼 (quỷ) cho âm huái. Nghĩa: cây hòe (Styphnolobium japonicum), còn gọi cây hoè Nhật Bản. Tiểu triện đã có dạng này. Chưa có nguồn học thuật đầy đủ về nguồn gốc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hoè", "Hạng Tần Suất (Jun Da)": "3114.0", "Tần Suất % (Jun Da)": "99.2863569376", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槐", "Unihan_Traditional (Chữ Phồn thể)": "槐", "Pinyin_Xie": "huái", "Âm Hán Việt_Xie": "hoè", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài cây hòe hoặc các bộ phận của cây này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扒', '{"9000": "3115.0", "Chữ Trung Quốc": "扒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 5 | nét | 扌 | thủ | biểu nghĩa | tay | 八 | bát | biểu âm | tám (gợi âm bā) | 扒 = 扌 (Thủ, biểu nghĩa: tay) + 八 (Bát, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động bằng tay; 八 gợi âm bā. Chữ có nhiều âm đọc (bā, pá) với nhiều nghĩa: bám víu, cào bới, móc túi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\": bàn tay (扌) xòe tám ngón (八) để cào bới, móc lấy — 扒 là động tác dùng tay cào, bám. | Gương Hán-Việt | 扒 ít dùng trong từ Hán-Việt; âm bái xuất hiện trong một số từ điển cổ. | Mở khoá kiến thức | Biết 扒 (bái/bát) giúp nhận ra nhóm chữ hành động bằng tay: cào (扒), bám víu, lột vỏ.", "Tự nguyên_Xie": "扒 là chữ hình thanh: 手/扌 (tay) biểu nghĩa, 八 biểu âm. Wiktionary xác nhận cấu trúc này ({{Han compound|手|八|t1=hand|ls=psc|c1=s|c2=p}}). Chữ đa âm: đọc bā (bám, cào, lột) hoặc pá (móc túi, ăn chậm). Không có hình thức giáp cốt hay kim văn được ghi nhận riêng cho chữ này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vin, bíu, vịn; đào, cào, móc ra, bới ra; bóc, lột", "Hạng Tần Suất (Jun Da)": "3115.0", "Tần Suất % (Jun Da)": "99.2871956798", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 八", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌八", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "八", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扒", "Unihan_Traditional (Chữ Phồn thể)": "扒", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ hành động cào, bới hoặc lột vỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bā | / | đào | / | bā | / | cào | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp | HSK | HSK 6 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('裴', '{"9000": "3116.0", "Chữ Trung Quốc": "裴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 非 | phi | biểu âm | không phải, sai | 衣 | y | biểu nghĩa | áo, quần áo | 裴 = 非 (Phi, biểu âm) + 衣 (Y, biểu nghĩa: áo quần); chữ hình thanh. Bộ 衣 (viết theo cấu trúc 非+衣) chỉ liên quan đến vải vóc trang phục; 非 (phi) cho âm péi. Nghĩa: tà áo thướt tha; họ Bùi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bùi\": áo (衣) tung bay như phi (非) — tà áo rộng thướt tha như không biết bó buộc. Ghi nhớ: 裴 = họ Bùi trong tiếng Việt. | Gương Hán-Việt | Chữ 裴 đọc Hán-Việt là \"bùi\", vay mượn trực tiếp vào tiếng Việt thành họ Bùi — một trong những họ phổ biến người Việt gốc Hoa. | Mở khoá kiến thức | Biết 裴 nhận ra họ Bùi trong cả tiếng Trung lẫn tiếng Việt: 裴艳玲 (Bùi Diễm Linh), 裴秀 (Bùi Tú — nhà bản đồ học).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh (psc): bộ 衣 (áo) chỉ nghĩa — tà áo bay tung; 非 (phi) cho âm péi. Tiểu triện đã có dạng này. Nghĩa chính: dáng áo thướt tha, bay bay; phổ biến nhất là họ người: họ Bùi (裴), vay mượn vào tiếng Việt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Bùi", "Hạng Tần Suất (Jun Da)": "3116.0", "Tần Suất % (Jun Da)": "99.2880339053", "GavinGrover_Once (Chiết tự trực tiếp)": "非 + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱非衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "衣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "非", "Unihan_Simplified (Chữ Giản thể)": "裴", "Unihan_Traditional (Chữ Phồn thể)": "裴", "Pinyin_Xie": "péi", "Âm Hán Việt_Xie": "bùi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ họ người hoặc làm tính từ mô tả dáng đi lững lờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祀', '{"9000": "3117.0", "Chữ Trung Quốc": "祀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 7 | nét | 礻 | kỳ | biểu nghĩa | thần linh, tế lễ (dạng viết tắt của 示) | 巳 | tỵ | biểu âm | chi Tỵ (địa chi thứ 6) | 祀 = 礻(Kỳ/Thị, biểu nghĩa: thần linh/tế lễ) + 巳 (Tỵ, biểu âm); chữ hình thanh. Bộ 示/礻 chỉ hoạt động tín ngưỡng, tế lễ; 巳 (tỵ) cho âm sì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tự\": bàn thờ (礻) dưới năm Tỵ (巳) — cúng tế theo lịch can chi, mỗi năm (tỵ) đều có lễ tế. Nhớ: 祀 = tế lễ, cúng tổ. | Gương Hán-Việt | Chữ 祀 đọc Hán-Việt là \"tự\", dùng trong 祭祀 (tế tự — cúng tế), 祀典 (tự điển — điển lễ tế tự) trong văn học cổ và tín ngưỡng dân gian Việt Nam. | Mở khoá kiến thức | Biết 祀 mở khoá: 祭祀 (tế tự), 祀典 (lễ điển tế tự), 郊祀 (giao tự — tế lễ ngoài trời).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 示 (thần linh/lễ nghi) chỉ hành động tế tự; 巳 (tỵ) cho âm sì. Nghĩa: tế lễ, cúng tổ tiên; nghĩa cổ là \"năm\" (thời Thương). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cúng tế; năm", "Hạng Tần Suất (Jun Da)": "3117.0", "Tần Suất % (Jun Da)": "99.288871614", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 巳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻巳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祀", "Unihan_Traditional (Chữ Phồn thể)": "祀", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc cúng tế thần linh tổ tiên hoặc làm danh từ chỉ nghi lễ cúng bái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埔', '{"9000": "3118.0", "Chữ Trung Quốc": "埔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 10 | nét | 土 | thổ | biểu nghĩa | đất, thổ nhưỡng | 甫 | phủ | biểu âm | mới bắt đầu; tên đệm tôn kính | 埔 = 土 (Thổ, biểu nghĩa: đất) + 甫 (Phủ, biểu âm); chữ hình thanh. Bộ 土 chỉ đây là địa hình/địa danh; 甫 (phủ) cho âm bù/pǔ. Nghĩa: bãi đất rộng, bến cảng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phố\": đất (土) mà mới bắt đầu (甫) khai thác — bãi đất khai hoang, bến phố mới hình thành. Nhớ: 埔 = phố, bến (trong địa danh Hoàng Phố, Chợ Lớn). | Gương Hán-Việt | Chữ 埔 đọc Hán-Việt là \"phố\", vay mượn vào tiếng Việt thành \"phố\" — đơn vị dân cư thương mại, phổ biến nhất trong \"phố phường\", \"phố xá\". | Mở khoá kiến thức | Biết 埔 nhận ra địa danh quan trọng: 黄埔 (Hoàng Phố), 大埔 (Đại Phố), là chữ cốt lõi trong nhóm địa danh Hoa Nam.", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 土 (đất) chỉ địa hình; 甫 (phủ) cho âm bù. Nghĩa: bãi đất, khu đất rộng mở — dùng phổ biến trong địa danh vùng Hoa Nam và Đông Nam Á: Hoàng Phố (黄埔), Macao (澳門), Phố Đông (浦东 — biến thể). Chữ tạo để chỉ địa danh phương ngữ Quảng Đông. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "3118.0", "Tần Suất % (Jun Da)": "99.2897077724", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埔", "Unihan_Traditional (Chữ Phồn thể)": "埔", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "phố, bộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh để chỉ vùng đất bằng phẳng ven sông hoặc bến cảng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('絮', '{"9000": "3119.0", "Chữ Trung Quốc": "絮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 如 | như | biểu âm | như, giống như | 糸 | mịch | biểu nghĩa | tơ, sợi | 絮 = 如 (Như, biểu âm) + 糸 (Mịch, biểu nghĩa: tơ/sợi); chữ hình thanh. Bộ 糸 chỉ chất liệu sợi bông tơ; 如 (như) cho âm xù. Nghĩa: sợi bông thô, bông nhồi áo; hoa nhẹ bay như bông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhứ\": sợi tơ (糸) nhẹ như (如) bông bay — bông liễu trắng bay khắp như tơ, nói nhiều cũng như bông bay không dứt. Nhớ: 絮 = bông, hoa nhẹ bay; nói dai. | Gương Hán-Việt | Chữ 絮 đọc Hán-Việt là \"nhứ\", ít gặp đơn lẻ trong tiếng Việt hiện đại; gặp trong 絮叨 (nhứ đao — nói dai dòng), 柳絮 (liễu nhứ — bông liễu). | Mở khoá kiến thức | Biết 絮 mở khoá: 柳絮 (bông liễu), 絮叨 (nói dai dòng), 棉絮 (bông nhồi áo), 絮絮叨叨 (nói mãi không thôi).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 糸 (tơ/sợi) chỉ chất liệu sợi xơ bông; 如 (như) cho âm xù. Nghĩa gốc: bông vải thô dùng nhồi áo bông mùa đông. Mở rộng sang hoa nhẹ bay (柳絮 — bông liễu), và nói dai dòng (絮叨). Chữ tạo từ thời Hán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợi bông; may (áo); hoa nhẹ như bông và bay được", "Hạng Tần Suất (Jun Da)": "3119.0", "Tần Suất % (Jun Da)": "99.2905434139", "GavinGrover_Once (Chiết tự trực tiếp)": "如 + 糸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱如糸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "糸", "Unihan_Simplified (Chữ Giản thể)": "絮", "Unihan_Traditional (Chữ Phồn thể)": "絮", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "nhứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường làm danh từ chỉ bông sợi hoặc làm động từ, tính từ chỉ sự lải nhải, dông dài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芭', '{"9000": "3120.0", "Chữ Trung Quốc": "芭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 巴 | ba | biểu âm | Ba (nước cổ Trung Quốc); dán, bám | 芭 = 艹(Thảo, biểu nghĩa: thực vật) + 巴 (Ba, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài thực vật; 巴 (ba) cho âm bā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": cỏ (艹) mang âm ba (巴) — cây ba tiêu (chuối lá lớn) hay múa ba lê, âm \"ba\" (bā) vang lên nhẹ nhàng. Nhớ: 芭 = ba tiêu (chuối), ba lê. | Gương Hán-Việt | Chữ 芭 đọc Hán-Việt là \"ba\", vay mượn vào tiếng Việt trong \"ba tiêu\" (芭蕉 — cây chuối hoa đỏ), \"ba lê\" (芭蕾 — múa ballet). | Mở khoá kiến thức | Biết 芭 mở khoá: 芭蕉 (ba tiêu — cây chuối), 芭蕾 (ba lê — ballet), 芭蕾舞 (múa ba lê).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 艹 (cỏ) chỉ thực vật; 巴 (ba) cho âm bā. Nghĩa: cây chuối, cây ba tiêu (芭蕉); một loài cỏ thơm. Chủ yếu dùng trong 芭蕉 (ba tiêu — cây chuối lá lớn), 芭蕾 (ba lê — phiên âm ballet). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ba tiêu 芭蕉)", "Hạng Tần Suất (Jun Da)": "3120.0", "Tần Suất % (Jun Da)": "99.2913780219", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芭", "Unihan_Traditional (Chữ Phồn thể)": "芭", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép để chỉ các loại cây thảo mộc như chuối cảnh hoặc cỏ thơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屉', '{"9000": "3121.0", "Chữ Trung Quốc": "屉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 8 | nét | 尸 | thi | biểu nghĩa | thân người nằm, mái che → vật dụng có mặt phẳng | 世 | thế | biểu âm | thế hệ; cho âm ''thè/tì'' | 屉 là dạng giản thể của 屜. Cấu trúc: 尸 (thi) biểu nghĩa — bộ thể hiện vật có hình dáng dẹt, nằm ngang; 世 (thế) biểu âm. Chữ chỉ các vật phẳng dẹt có thể kéo ra kéo vào như ngăn kéo, khay, lồng chưng. Vì lsCodes không có trong nguồn, phân tích dựa vào cấu trúc thị giác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": bộ 尸 (vật dẹt, không gian) + 世 biểu âm → ngăn kéo dẹt như một ''thế giới nhỏ'' giấu sau mặt tủ. Chưa có nguồn học thuật. | Gương Hán-Việt | thế trong 抽屉 (chōu ti — ngăn kéo); ít dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 屉 (Thế) hầu như chỉ dùng trong 抽屉 (ngăn kéo) ở HSK 5.", "Tự nguyên_Xie": "屉 (dạng phồn thể 屜) có nguồn Wiktionary không cung cấp thông tin chi tiết về glyph origin ngoài mã {{Han etym}}. Cấu trúc: 尸 + 世. Bộ 尸 (thi) trong nhiều chữ như 居, 层, 展 chỉ không gian sinh hoạt hay vật dụng dẹt; 世 nhiều khả năng đóng vai biểu âm. Chưa có nguồn học thuật xác nhận trực tiếp cho 屜. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngăn kéo; hộc tủ; lồng chưng; cái vỉ; giát giường; giát ghế", "Hạng Tần Suất (Jun Da)": "3121.0", "Tần Suất % (Jun Da)": "99.2922110796", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 世", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸世", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "世", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屉", "Unihan_Traditional (Chữ Phồn thể)": "屜", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các vật dụng có dạng ngăn hộc kéo ra vào hoặc khay lót. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痪', '{"9000": "3122.0", "Chữ Trung Quốc": "痪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 12 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 奂 | hoán | biểu âm | rực rỡ (gợi âm huàn) | 痪 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 奂 (Hoán, biểu âm); chữ hình thanh. Bộ 疒 chỉ loại bệnh; 奂 gợi âm huàn. Chữ giản thể của 瘓.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\": bệnh (疒) tấn công khắp người — hoán đổi sức sống thành tê liệt. | Gương Hán-Việt | 痪 không dùng độc lập; thường thấy trong 瘫痪 (thán hoán = liệt). | Mở khoá kiến thức | Biết 痪 (hoán) giúp đọc ngay 瘫痪 — từ y tế quan trọng: liệt, tê bại.", "Tự nguyên_Xie": "痪 là dạng giản thể của 瘓. Wiktionary ghi nhận 瘓 = 疒 (biểu nghĩa: bệnh) + 奐 (biểu âm); chữ hình thanh. 痪 chỉ xuất hiện trong 瘫痪 (liệt, tê bại). Nguyên nghĩa chỉ trạng thái tê liệt các chi do bệnh thần kinh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tê dại", "Hạng Tần Suất (Jun Da)": "3122.0", "Tần Suất % (Jun Da)": "99.2930436204", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 奂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒奂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痪", "Unihan_Traditional (Chữ Phồn thể)": "瘓", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường kết hợp với chữ khác làm danh từ chỉ bệnh bại liệt hoặc tính từ chỉ trạng thái mất cảm giác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霄', '{"9000": "3123.0", "Chữ Trung Quốc": "霄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 15 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 肖 | tiêu | biểu âm | giống, tiêu điều | 霄 = 雨 (Vũ, biểu nghĩa: mưa/bầu trời) + 肖 (Tiêu, biểu âm); chữ hình thanh. Bộ 雨 chỉ hiện tượng khí tượng, bầu trời; 肖 (tiêu) cho âm xiāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bầu trời mưa (雨) nghe tiêu (肖) điều — bầu trời cao vút, từng đám mây tiêu tan. Nhớ: 霄 = tầng trời cao, cửu tiêu. | Gương Hán-Việt | Chữ 霄 đọc Hán-Việt là \"tiêu\", dùng trong \"cửu tiêu\" (九霄 — chín tầng trời), \"vân tiêu\" (云霄 — mây trời cao) trong thơ văn cổ Việt Nam. | Mở khoá kiến thức | Biết 霄 mở khoá: 九霄 (cửu tiêu), 云霄 (vân tiêu), 响彻云霄 (vang vọng bầu trời), 九霄云外 (ngoài chín tầng mây).", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh (psc): bộ 雨 (mưa/trời) chỉ tầng cao của bầu trời; 肖 (tiêu) cho âm xiāo. Nghĩa gốc: tầng mây cao nhất, bầu trời. Đại triện đã có dạng này. Thành ngữ phổ biến: 九霄云外 (chín tầng mây), 响彻云霄 (vang vọng cả bầu trời). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoảng trời trống; mây", "Hạng Tần Suất (Jun Da)": "3123.0", "Tần Suất % (Jun Da)": "99.2938761613", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霄", "Unihan_Traditional (Chữ Phồn thể)": "霄", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ khoảng không gian bao la trên cao hoặc các tầng mây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绽', '{"9000": "3124.0", "Chữ Trung Quốc": "绽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi (dạng viết tắt của 糸) | 定 | định | biểu âm | định, quyết định | 绽 = 纟(Mịch, biểu nghĩa: tơ/sợi vải) + 定 (Định, biểu âm); chữ hình thanh. Dạng phồn thể là 綻. Bộ 纟 chỉ vải sợi; 定 (định) cho âm zhàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thán\": sợi vải (纟) không định (定) được chỗ — đường chỉ bung tung, như hoa bung nở không kìm lại được. Nhớ: 绽 = bung ra, nở rộ (绽放). | Gương Hán-Việt | Chữ 绽 đọc Hán-Việt là \"thán\", ít dùng đơn lẻ trong tiếng Việt; gặp trong 绽放 (thán phóng — nở rộ) khi học văn học Trung Quốc. | Mở khoá kiến thức | Biết 绽 mở khoá: 绽放 (nở bung), 破绽 (sơ hở, điểm yếu — đường may hở), 绽裂 (vỡ nứt).", "Tự nguyên_Xie": "Chữ hình thanh, dạng giản thể của 綻: bộ 糸 (tơ/vải) chỉ đường may sợi vải; 定 (định) cho âm zhàn. Nghĩa gốc: đường may bị rách toác, sợi chỉ bung ra. Mở rộng sang nghĩa hoa nở bung (绽放 — nở rộ). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường khâu áo", "Hạng Tần Suất (Jun Da)": "3124.0", "Tần Suất % (Jun Da)": "99.294706635", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绽", "Unihan_Traditional (Chữ Phồn thể)": "綻", "Pinyin_Xie": "zhàn", "Âm Hán Việt_Xie": "trán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ trạng thái nứt nẻ của đường may hoặc hoa bắt đầu hé nở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('宵', '{"9000": "3125.0", "Chữ Trung Quốc": "宵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 10 | nét | 宀 | miên | biểu nghĩa | mái nhà, che phủ (ý: không gian tối) | 肖 | tiêu | biểu âm | giống, nhỏ (gợi âm xiāo) | 宵 = 宀 (Miên, biểu nghĩa: mái nhà) + 肖 (Tiêu, biểu âm); chữ hình thanh. Mái nhà (宀) gợi không gian bóng tối che phủ; 肖 gợi âm xiāo. Kim văn và bạch thư đã ghi lại hình dạng chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": mái nhà (宀) che phủ như màn đêm tiêu điều — 宵 là đêm tối. | Gương Hán-Việt | 宵 xuất hiện trong 通宵 (thông tiêu = suốt đêm), 元宵节 (Tết Nguyên Tiêu). | Mở khoá kiến thức | Biết 宵 (tiêu) giúp đọc 通宵 (thâu đêm) và 元宵节 (Tết Nguyên Tiêu, rằm tháng Giêng).", "Tự nguyên_Xie": "Kim văn | Bạch thư | 宵 là chữ hình thanh: 宀 (mái nhà, không gian tối) biểu nghĩa, 肖 biểu âm. Wiktionary xác nhận ({{Han compound|ls=psc|宀|肖|c1=s|c2=p|t1=roof}}). Kim văn cho thấy chữ đã có hình thức ổn định từ thời cổ. Nghĩa gốc: đêm tối, buổi tối — thời gian mái nhà che khuất ánh sáng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đêm; nhỏ bé", "Hạng Tần Suất (Jun Da)": "3125.0", "Tần Suất % (Jun Da)": "99.2955355583", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "宵", "Unihan_Traditional (Chữ Phồn thể)": "宵", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ thời gian ban đêm hoặc dùng trong các từ ghép liên quan đến buổi tối. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邑', '{"9000": "3126.0", "Chữ Trung Quốc": "邑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 囗 | vi | biểu nghĩa | vòng bao quanh, tường thành | 卪 | tiết | biểu nghĩa | người quỳ gối (hội ý) | 邑 = 囗 (Vi, biểu nghĩa: tường thành/vòng vây) + 卪 (Tiết, người quỳ gối); chữ hội ý (ic). Theo Wiktionary: 囗 là vòng thành phố, 卪 là người quỳ bên trong — hình ảnh vùng đất có người định cư trong tường thành. Lưu ý: phần dưới không liên quan đến 巴.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ấp\": tường vây (囗) bảo vệ người dân quỳ gối (卪) bên trong — đây là ấp, vùng đất nhỏ có người ở. Nhớ: 邑 = ấp, thị ấp; khi đứng bên phải thành bộ 阝. | Gương Hán-Việt | Chữ 邑 đọc Hán-Việt là \"ấp\", vay mượn vào tiếng Việt thành \"ấp\" — đơn vị hành chính nhỏ dưới xã, quen thuộc trong địa danh miền Nam. | Mở khoá kiến thức | Biết 邑 mở khoá: nhận ra bộ 阝 (bên phải) trong rất nhiều chữ chỉ địa danh: 那 (na), 都 (đô), 郑 (trịnh), 邦 (bang) — tất cả đều liên quan đến vùng đất.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Chữ hội ý (ic): 囗 (vòng tường thành) + 卪 (người quỳ gối — cư dân). Hình ảnh: người dân định cư trong tường thành, tạo thành vùng đất/ấp. Kim văn, đại triện, tiểu triện đều có dạng rõ ràng. Nghĩa: vùng đất nhỏ, thị trấn, ấp — bộ này khi đứng bên phải chữ khác thành 阝 (phải). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "944.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (030) Tiết (026)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Khẩu (số 030 - miệng/cửa ngõ) ở trên bộ Tiết (số 026 - cái thẻ). Ông quan cầm cái thẻ tre (Tiết) để cai trị dân chúng (Khẩu) trong thành ấp. Giải thích sự chuyển ý: Đây là chữ Hội ý. Ấp là nơi cư trú (thành ấp, thôn ấp).", "Nghĩa Tiếng Việt_Xie": "vùng đất nhỏ", "Hạng Tần Suất (Jun Da)": "3126.0", "Tần Suất % (Jun Da)": "99.2963644817", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱口巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "邑", "Unihan_Traditional (Chữ Phồn thể)": "邑", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ đơn vị hành chính thời xưa hoặc vùng đất phong của chư hầu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霖', '{"9000": "3127.0", "Chữ Trung Quốc": "霖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 16 | nét | 雨 | vũ | biểu nghĩa | mưa | 林 | lâm | biểu âm | rừng, rậm rạp | 霖 = 雨 (Vũ, biểu nghĩa: mưa) + 林 (Lâm, biểu âm); chữ hình thanh. Bộ 雨 chỉ hiện tượng mưa; 林 (lâm) cho âm lín. Nghĩa: mưa dầm dề kéo dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâm\": mưa (雨) dày như rừng (林) — mưa dầm rậm rạp như rừng cây, dai dẳng không tạnh. Nhớ: 霖 = mưa dầm (甘霖 — mưa lành). | Gương Hán-Việt | Chữ 霖 đọc Hán-Việt là \"lâm\", gặp trong \"cam lâm\" (甘霖 — mưa lành, mưa may) trong thơ văn cổ Việt Nam. | Mở khoá kiến thức | Biết 霖 mở khoá: 甘霖 (cam lâm — mưa lành), 霖雨 (mưa dầm), 春霖 (mưa xuân dầm dề).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: bộ 雨 (mưa) chỉ hiện tượng khí tượng; 林 (lâm/rừng) cho âm lín. Nghĩa: mưa dầm kéo dài — như cây rừng (林) dày đặc, mưa dày đặc không dứt. Giáp cốt văn và tiểu triện đều có dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưa dầm", "Hạng Tần Suất (Jun Da)": "3127.0", "Tần Suất % (Jun Da)": "99.2971923715", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 林", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨林", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霖", "Unihan_Traditional (Chữ Phồn thể)": "霖", "Pinyin_Xie": "lín", "Âm Hán Việt_Xie": "lâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ những trận mưa kéo dài nhiều ngày liên tục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岔', '{"9000": "3128.0", "Chữ Trung Quốc": "岔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 分 | phân | biểu nghĩa | chia, tách ra | 山 | sơn | biểu nghĩa | núi, địa hình | 岔 = 分 (Phân, biểu nghĩa: chia, tách) + 山 (Sơn, biểu nghĩa: núi, địa hình); chữ hội ý. 分 (chia tách) + 山 (địa hình) → nơi trên địa hình mà đường phân nhánh, ngã ba. Wiktionary xác nhận ls=ic (hội ý).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xoá\": núi (山) bị phân (分) cắt — tạo ra ngã ba, chỗ rẽ trên đường. | Gương Hán-Việt | 岔 ít dùng trong từ Hán-Việt thuần; âm xoá thấy trong từ điển Hán-Việt cổ. | Mở khoá kiến thức | Biết 岔 (xoá) giúp đọc các từ như 岔路 (đường rẽ), 打岔 (ngắt lời), 出岔子 (xảy ra trục trặc).", "Tự nguyên_Xie": "岔 là chữ hội ý: 分 (chia tách) và 山 (núi, địa hình) kết hợp diễn đạt ý nghĩa ''chỗ đường phân nhánh trên địa hình''. Wiktionary ghi nhận rõ: {{Han compound|分|山|ls=ic|t1=split; division|t2=mountain}}. Không có hình thức giáp cốt hay kim văn được ghi nhận riêng; chữ có thể được tạo muộn hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã ba, chỗ rẽ, chỗ ngoặt", "Hạng Tần Suất (Jun Da)": "3128.0", "Tần Suất % (Jun Da)": "99.2980187109", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱分山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岔", "Unihan_Traditional (Chữ Phồn thể)": "岔", "Pinyin_Xie": "chà", "Âm Hán Việt_Xie": "xoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ chỗ rẽ hoặc làm động từ chỉ việc rẽ sang hướng khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chà | / | ngã ba | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sự chuyển động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饵', '{"9000": "3129.0", "Chữ Trung Quốc": "饵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn (dạng viết tắt của 食) | 耳 | nhĩ | biểu âm | tai | 饵 = 饣(Thực, biểu nghĩa: ăn/thức ăn) + 耳 (Nhĩ, biểu âm); chữ hình thanh. Dạng phồn thể là 餌. Bộ 食 chỉ thức ăn; 耳 (nhĩ) cho âm ěr.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": thức ăn (饣) nghe từ tai (耳) — mồi câu thơm ngon lọt vào tai cá, khiến cá cắn câu. Nhớ: 饵 = mồi câu, thức ăn dụ. | Gương Hán-Việt | Chữ 饵 đọc Hán-Việt là \"nhị\", ít dùng đơn lẻ trong tiếng Việt; gặp trong 诱饵 (dụ nhị — mồi nhử) khi học văn học hay chiến lược. | Mở khoá kiến thức | Biết 饵 mở khoá: 诱饵 (mồi nhử), 饵料 (thức mồi/thức câu), 上钩受饵 (cắn câu).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (psc): bộ 食 (ăn) chỉ thức ăn dùng để dụ; 耳 (nhĩ) cho âm ěr. Nghĩa gốc: bánh bột dùng để cúng hoặc ăn; mở rộng sang mồi câu cá, và nghĩa bóng: dùng lợi ích để dụ dỗ (诱饵). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bột; mồi câu cá", "Hạng Tần Suất (Jun Da)": "3129.0", "Tần Suất % (Jun Da)": "99.2988435", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饵", "Unihan_Traditional (Chữ Phồn thể)": "餌", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ để chỉ mồi nhử hoặc thức ăn dụ động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茄', '{"9000": "3130.0", "Chữ Trung Quốc": "茄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 加 | gia | biểu âm | thêm vào, gia thêm | 茄 = 艹(Thảo, biểu nghĩa: thực vật) + 加 (Gia, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là loài thực vật; 加 (gia) cho âm jiā/qié.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"già\": cỏ (艹) được gia (加) thêm giá trị — cây cà trồng thêm vào vườn rau, quả cà thêm vị cho bữa ăn. Nhớ: 茄 = cây cà (番茄/cà chua, 茄子/cà tím). | Gương Hán-Việt | Chữ 茄 đọc Hán-Việt là \"già\", vay mượn vào tiếng Việt qua \"cà\" — cây cà (茄子 → cà tím, 番茄 → cà chua) là từ gốc Hán-Việt. | Mở khoá kiến thức | Biết 茄 mở khoá: 番茄 (cà chua), 茄子 (cà tím), 雪茄 (xì gà — cigar, phiên âm).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (psc): bộ 艹 (cỏ) chỉ thực vật; 加 (gia) cho âm jiā. Nghĩa chính: cây cà, cà tím (茄子); cuống sen (莲茄). Tiểu triện đã có dạng này. Lưu ý: khi đọc qié (trong 番茄, 茄子) nghĩa là cây cà; khi đọc jiā là họ tên và thuật ngữ khác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cà; cuống sen, giò sen", "Hạng Tần Suất (Jun Da)": "3130.0", "Tần Suất % (Jun Da)": "99.2996682891", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茄", "Unihan_Traditional (Chữ Phồn thể)": "茄", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại cây họ cà hoặc bộ phận của hoa sen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韧', '{"9000": "3131.0", "Chữ Trung Quốc": "韧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 7 | nét | 韦 | vi | biểu nghĩa | da thuộc, da mềm dẻo | 刃 | nhận | biểu âm | lưỡi dao (gợi âm rèn) | 韧 = 韦 (Vi, biểu nghĩa: da thuộc) + 刃 (Nhận, biểu âm); chữ hình thanh. Bộ vi chỉ vật liệu mềm dẻo dai; 刃 gợi âm rèn. Chữ giản thể của 韌.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhận\": da thuộc (韦) dai như lưỡi dao (刃) — 韧 là mềm dẻo mà không dễ gãy. | Gương Hán-Việt | 韧 xuất hiện trong 坚韧 (kiên nhận = bền bỉ) và 韧性 (nhận tính = độ dai, tính dẻo dai). | Mở khoá kiến thức | Biết 韧 (nhận) giúp đọc 坚韧 (bền bỉ, kiên cường) và 韧性 (độ dẻo dai) — quan trọng trong văn mô tả tính cách.", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | 韧 là dạng giản thể của 韌. Wiktionary xác nhận 韌 = 韋 (da thuộc, biểu nghĩa) + 刃 (lưỡi dao, biểu âm); chữ hình thanh. Bạch thư và tiểu triện đã ghi lại hình dạng chữ. Nghĩa gốc: da thuộc (韋) có đặc tính mềm mà không dễ đứt — từ đó mở rộng sang nghĩa bền bỉ, dai. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mềm mà dai", "Hạng Tần Suất (Jun Da)": "3131.0", "Tần Suất % (Jun Da)": "99.3004915278", "GavinGrover_Once (Chiết tự trực tiếp)": "韦 + 刃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韦刃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韦", "Unihan_Simplified (Chữ Giản thể)": "韧", "Unihan_Traditional (Chữ Phồn thể)": "靭", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Dùng làm tính từ làm vị ngữ hoặc bổ nghĩa cho danh từ để chỉ tính chất dai bền. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琪', '{"9000": "3132.0", "Chữ Trung Quốc": "琪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | vua; bộ ngọc (王=玉 khi đứng bên trái) | 其 | kỳ | biểu âm | đó, ấy (đại từ) | 琪 = 王/玉 (Ngọc, biểu nghĩa: ngọc đá quý) + 其 (Kỳ, biểu âm); chữ hình thanh. Bộ 王 đứng bên trái tượng trưng cho ngọc (玉); 其 (kỳ) cho âm qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": ngọc (玉/王) kỳ diệu (其) — viên ngọc kỳ lạ, quý giá phi thường. Nhớ: 琪 = ngọc kỳ, đẹp như ngọc (thường dùng trong tên). | Gương Hán-Việt | Chữ 琪 đọc Hán-Việt là \"kỳ\", phổ biến trong tên người: Thị Kỳ, Hồng Kỳ; cũng gặp trong 琪花瑶草 (hoa ngọc cỏ ngọc — cảnh tiên đẹp). | Mở khoá kiến thức | Biết 琪 mở khoá nhóm tên riêng mang ngọc: 琳 (lâm ngọc), 琦 (ngọc đẹp), 琪 (ngọc kỳ) — tất cả đều bộ 王/玉.", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 玉 (ngọc) chỉ loại đá quý đẹp; 其 (kỳ) cho âm qí. Nghĩa: loại ngọc quý, ngọc kỳ — dùng tả vẻ đẹp rực rỡ. Chủ yếu dùng trong tên riêng và thơ văn cổ. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc kỳ", "Hạng Tần Suất (Jun Da)": "3132.0", "Tần Suất % (Jun Da)": "99.3013142497", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琪", "Unihan_Traditional (Chữ Phồn thể)": "琪", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn chương hoặc dùng để đặt tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邹', '{"9000": "3133.0", "Chữ Trung Quốc": "邹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 刍 | sô | biểu âm | cỏ cắt (thức ăn gia súc) | 邑 | ấp | biểu nghĩa | thị trấn, vùng đất | 邹 = 刍 (Sô, biểu âm) + 邑/阝 (Ấp, biểu nghĩa: địa danh); chữ hình thanh. Dạng phồn thể là 鄒. Bộ 邑 (阝 bên phải) chỉ đây là địa danh; 刍 (sô) cho âm zōu. Nghĩa: nước Trâu thời Chu; họ Trâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâu\": ấp (邑) nơi cắt cỏ nuôi gia súc (刍) — nước Trâu xưa là vùng đất chăn nuôi trù phú, quê của Mạnh Tử. Nhớ: 邹 = nước Trâu, họ Trâu. | Gương Hán-Việt | Chữ 邹 đọc Hán-Việt là \"trâu\", vay mượn vào tiếng Việt thành họ Trâu — một trong những họ gốc Hoa ở Việt Nam. | Mở khoá kiến thức | Biết 邹 nhận ra địa danh lịch sử: 邹城 (Trâu Thành — quê Mạnh Tử), họ Trâu trong cộng đồng Hoa kiều.", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh (psc): bộ 邑 (ấp/địa danh) chỉ quốc gia/địa danh; 刍 (cỏ cắt) cho âm zōu. Dạng phồn thể 鄒. Nghĩa: nước Trâu (邹国) thời Chu — quê hương Mạnh Tử. Sau trở thành họ người phổ biến. Đại triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Trâu đời nhà Chu (nay thuộc tỉnh Sơn Đông của Trung Quốc); họ Trâu", "Hạng Tần Suất (Jun Da)": "3133.0", "Tần Suất % (Jun Da)": "99.3021364549", "GavinGrover_Once (Chiết tự trực tiếp)": "刍 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刍阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邹", "Unihan_Traditional (Chữ Phồn thể)": "鄒", "Pinyin_Xie": "zōu", "Âm Hán Việt_Xie": "trâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ riêng chỉ tên nước thời Chu hoặc họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑚', '{"9000": "3134.0", "Chữ Trung Quốc": "瑚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 王 | vương | biểu nghĩa | bộ ngọc (王=玉 khi đứng bên trái) | 胡 | hồ | biểu âm | hồ (người ngoại tộc); sao vậy | 瑚 = 王/玉 (Ngọc, biểu nghĩa: ngọc/đồ quý) + 胡 (Hồ, biểu âm); chữ hình thanh. Bộ 玉 chỉ vật liệu quý; 胡 (hồ) cho âm hú. Nghĩa: chủ yếu dùng trong 珊瑚 (san hô).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": ngọc (玉/王) của người Hồ (胡) phương xa — san hô quý từ biển sâu, như ngọc quý của các nước xa xôi. Nhớ: 瑚 = san hô (珊瑚). | Gương Hán-Việt | Chữ 瑚 đọc Hán-Việt là \"hồ\", chủ yếu dùng trong 珊瑚 (san hô) — từ được vay mượn vào tiếng Việt với nghĩa giống hệt. | Mở khoá kiến thức | Biết 瑚 mở khoá: 珊瑚 (san hô), 珊瑚礁 (rạn san hô), 瑚璉 (bình ngọc quý trong lễ nghi — ví với người tài).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 玉 (ngọc/vật quý) chỉ đây là vật liệu quý từ biển; 胡 (hồ) cho âm hú. Nghĩa: dùng trong 珊瑚 (san hô — coral) — vật liệu từ đại dương đẹp như ngọc. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: san hô 珊瑚)", "Hạng Tần Suất (Jun Da)": "3134.0", "Tần Suất % (Jun Da)": "99.3029581432", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑚", "Unihan_Traditional (Chữ Phồn thể)": "瑚", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ ghép trong từ san hô hoặc chỉ đồ thờ cúng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憋', '{"9000": "3135.0", "Chữ Trung Quốc": "憋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 敝 | tệ | biểu âm | rách nát, xấu (gợi âm biē) | 心 | tâm | biểu nghĩa | tim, tâm trí, cảm xúc | 憋 = 敝 (Tệ, biểu âm) + 心 (Tâm, biểu nghĩa: cảm xúc, tâm trí); chữ hình thanh. Tâm chỉ cảm xúc bên trong; 敝 gợi âm biē. Hình ảnh: cảm xúc bị nén chặt trong lòng không thoát ra được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biệt\": tâm (心) tệ (敝) nát vì nhịn — 憋 là trạng thái nén chặt cảm xúc không thở được. | Gương Hán-Việt | 憋 ít dùng trong từ Hán-Việt thuần; âm biệt xuất hiện trong từ điển cổ. | Mở khoá kiến thức | Biết 憋 (biệt) giúp đọc 憋气 (nín thở, ấm ức), 憋屈 (bị oan, bực dọc).", "Tự nguyên_Xie": "憋 là chữ hình thanh: 心 (tâm, cảm xúc) biểu nghĩa, 敝 biểu âm. Wiktionary xác nhận: {{Han compound|敝|心|t2=heart|ls=psc|c1=p|c2=s}}. Nghĩa gốc: nén chặt cảm xúc bên trong — từ đó phát triển sang các nghĩa: nghẹt thở, nhịn, bực dọc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhịn, nín, kiềm chế; bí, bế tắc; bực dọc", "Hạng Tần Suất (Jun Da)": "3135.0", "Tần Suất % (Jun Da)": "99.303778798", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "憋", "Unihan_Traditional (Chữ Phồn thể)": "憋", "Pinyin_Xie": "biē", "Âm Hán Việt_Xie": "biệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ hành động kìm nén hơi thở, cảm xúc hoặc làm tính từ chỉ sự bực dọc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | biē | / | kìm nén | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Cảm xúc và cảm xúc 1 | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殆', '{"9000": "3136.0", "Chữ Trung Quốc": "殆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 9 | nét | 歹 | tồi | biểu nghĩa | xương người chết, điều xấu, tàn tệ | 台 | đài | biểu âm | đài, bệ | 殆 = 歹 (Tồi, biểu nghĩa: cái xấu/nguy hiểm) + 台 (Đài, biểu âm); chữ hình thanh. Bộ 歹 (xương người chết) chỉ sự nguy hiểm, cái xấu; 台 (đài) cho âm dài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đãi\": xương chết (歹) trên bệ đài (台) — ngồi trên đài mà như đứng giữa cái chết, trạng thái nguy khốn, đãi ngộ tử thần. Nhớ: 殆 = nguy hiểm; gần như (văn ngôn). | Gương Hán-Việt | Chữ 殆 đọc Hán-Việt là \"đãi\", dùng trong văn ngôn và thành ngữ: 百战不殆 (bách chiến bất đãi — trăm trận không thua), 危殆 (nguy đãi — nguy khốn). | Mở khoá kiến thức | Biết 殆 mở khoá: 百战不殆 (trăm trận không thua), 危殆 (nguy khốn), 殆尽 (gần hết — kiệt cùng), 知止不殆 (biết dừng không gặp nguy).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 歹 (xương chết/điều xấu) chỉ trạng thái nguy khốn; 台 (đài) cho âm dài. Nghĩa: trong vòng nguy hiểm, gần chết; mỏi mệt kiệt sức; có lẽ, gần như (phó từ văn ngôn). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguy khốn; mỏi mệt", "Hạng Tần Suất (Jun Da)": "3136.0", "Tần Suất % (Jun Da)": "99.3045994528", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殆", "Unihan_Traditional (Chữ Phồn thể)": "殆", "Pinyin_Xie": "dài", "Âm Hán Việt_Xie": "đãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Làm tính từ chỉ sự nguy khốn hoặc làm phó từ đứng trước động từ để chỉ sự gần như. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噜', '{"9000": "3137.0", "Chữ Trung Quốc": "噜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 鲁 | lỗ | biểu âm | cùn, thô bạo; nước Lỗ | 噜 = 口 (Khẩu, biểu nghĩa: miệng/lời nói) + 鲁 (Lỗ, biểu âm); chữ hình thanh. Dạng phồn thể là 嚕. Bộ 口 chỉ âm thanh miệng; 鲁 (lỗ) cho âm lū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": miệng (口) nói thô lỗ (鲁) — lầu bầu không ngừng, nói nhiều như người thô lỗ không biết kiệm lời. Nhớ: 噜 = nói lắm, lầu bầu. | Gương Hán-Việt | Chữ 噜 đọc Hán-Việt là \"lỗ\", ít dùng đơn lẻ trong tiếng Việt; gặp trong 噜噜 (lầu bầu) hay tên nhân vật hoạt hình (Garfield tiếng Trung: 噜噜米). | Mở khoá kiến thức | Biết 噜 mở khoá: 噜苏 (lắm lời, rườm rà), 絮絮噜噜 (nói dai dòng không ngừng).", "Tự nguyên_Xie": "Chữ hình thanh (psc): bộ 口 (miệng) chỉ âm thanh miệng phát ra; 魯 (lỗ) cho âm lū. Nghĩa: tiếng ục ục (nói lầu bầu), nói nhiều không ngừng. Chủ yếu dùng trong 噜噜 (lầu bầu), 噜苏 (lắm lời). Chữ tạo muộn để chỉ tiếng nói nặng nề. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói lắm, nói nhiều", "Hạng Tần Suất (Jun Da)": "3137.0", "Tần Suất % (Jun Da)": "99.3054195908", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 鲁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口鲁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噜", "Unihan_Traditional (Chữ Phồn thể)": "嚕", "Pinyin_Xie": "lū", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường dùng làm động từ chỉ việc nói lẩm bẩm hoặc làm từ tượng thanh mô phỏng tiếng ngáy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忒', '{"9000": "3138.0", "Chữ Trung Quốc": "忒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 弋 | dặc | biểu âm | cọc, cột buộc; săn bắn | 心 | tâm | biểu nghĩa | tim, lòng, tâm trí | 忒 = 弋 (Dặc, biểu âm) + 心 (Tâm, biểu nghĩa: tâm trí); chữ hình thanh. Bộ 心 chỉ trạng thái tâm lý; 弋 (dặc) cho âm tè. Nghĩa: biến đổi thất thường; sai lầm; quá mức (thái quá).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thắc\": tâm (心) mắc vào cọc (弋) — lòng người bị cọc kéo sang trái kéo sang phải, biến đổi thất thường, mắc sai lầm. Nhớ: 忒 = biến đổi, quá (thái quá). | Gương Hán-Việt | Chữ 忒 đọc Hán-Việt là \"thắc\", rất hiếm trong tiếng Việt hiện đại; gặp trong văn ngôn hoặc từ điển Hán-Việt cổ. | Mở khoá kiến thức | Biết 忒 nhận ra phó từ Bắc Kinh: 忒大 (quá to), 忒贵 (quá đắt) — thường gặp trong văn học phương ngữ.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh (psc): bộ 心 (tâm) chỉ trạng thái tâm lý không ổn định; 弋 (dặc) cho âm tè. Nghĩa: biến đổi bất thường, sai lầm; phó từ \"quá, thái quá\" trong phương ngữ Bắc Kinh (忒大/忒贵). Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến đổi; sai lầm", "Hạng Tần Suất (Jun Da)": "3138.0", "Tần Suất % (Jun Da)": "99.3062355945", "GavinGrover_Once (Chiết tự trực tiếp)": "弋 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弋心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弋", "Unihan_Simplified (Chữ Giản thể)": "忒", "Unihan_Traditional (Chữ Phồn thể)": "忒", "Pinyin_Xie": "tè", "Âm Hán Việt_Xie": "thắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Trong khẩu ngữ thường dùng làm phó từ đứng trước tính từ để biểu thị mức độ quá. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忿', '{"9000": "3139.0", "Chữ Trung Quốc": "忿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 分 | phân | biểu âm | chia, phân chia | 心 | tâm | biểu nghĩa | tim, lòng, tâm trí | 忿 = 分 (Phân, biểu âm) + 心 (Tâm, biểu nghĩa: tâm trí/cảm xúc); chữ hình thanh. Bộ 心 chỉ cảm xúc; 分 (phân) cho âm fèn. Nghĩa: tức giận bùng phát.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẫn\": tâm (心) bị phân (分) tách — cảm xúc bị chia cắt, giận dữ bùng lên khi lòng bị tổn thương. Nhớ: 忿 = phẫn, tức giận bùng phát. | Gương Hán-Việt | Chữ 忿 đọc Hán-Việt là \"phẫn\", dùng trong 忿恨 (phẫn hận), 忿忿不平 (phẫn phẫn bất bình — tức giận không bằng lòng) trong văn học cổ điển. | Mở khoá kiến thức | Biết 忿 mở khoá: 忿恨 (phẫn hận), 忿忿不平 (bất bình uất ức), 悲忿 (bi phẫn). Phân biệt với 愤 (phẫn nộ sâu hơn).", "Tự nguyên_Xie": "Bạch thư | Chữ hình thanh: bộ 心 (tâm/cảm xúc) chỉ trạng thái cảm xúc; 分 (phân) cho âm fèn. Wiktionary không có glyph-origin rõ ràng. Nghĩa: cơn giận bùng lên đột ngột, tức giận ngắn nhưng mạnh. Bạch thư đã có dạng này. Phân biệt với 愤 (phẫn — phẫn nộ kéo dài hơn). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "378.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Phân (326)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Phân (số 29 - chia cắt) ở trên chữ Tâm (số 148) . Bị chia cắt (phân) tình cảm trong lòng (tâm) sinh ra tức giận, bất bình (phẫn). Giải thích sự chuyển ý: Chữ Phân (chia cắt) chỉ âm, chữ Tâm (lòng) chỉ ý. Trong lòng (Tâm) bực tức, có sự mâu thuẫn rạn nứt (Phân) gọi là phẫn nộ (Phẫn). *(Biến âm Hán Việt: Phân -> Phẫn)*", "Nghĩa Tiếng Việt_Xie": "tức giận, cáu", "Hạng Tần Suất (Jun Da)": "3139.0", "Tần Suất % (Jun Da)": "99.3070510815", "GavinGrover_Once (Chiết tự trực tiếp)": "分 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱分心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "忿", "Unihan_Traditional (Chữ Phồn thể)": "忿", "Pinyin_Xie": "fèn", "Âm Hán Việt_Xie": "phẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm tính từ biểu thị trạng thái tức giận hoặc kết hợp thành danh từ như phẫn nộ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衅', '{"9000": "3140.0", "Chữ Trung Quốc": "衅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 血 | Số nét | 11 | nét | 血 | huyết | biểu nghĩa | máu (nghi lễ hiến máu) | 半 | bán | biểu âm | nửa (gợi âm xìn) | 衅 = 血 (Huyết, biểu nghĩa: máu) + 半 (Bán, biểu âm); chữ hình thanh. Bộ huyết chỉ nghi lễ dùng máu tế thần; 半 gợi âm xìn. Chữ giản thể của 釁; đại triện và tiểu triện đã ghi lại hình dạng phức tạp hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hấn\": máu (血) bôi lên đồ tế — một chút rạn nứt thành xung đột, gây hấn. | Gương Hán-Việt | 衅 xuất hiện trong 挑衅 (khiêu hấn = khiêu khích). | Mở khoá kiến thức | Biết 衅 (hấn) mở khóa từ 挑衅 (khiêu khích, gây sự) — quan trọng trong văn chính trị và tranh luận.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 衅 là dạng giản thể của 釁. Wiktionary ghi chữ có nghĩa gốc là nghi lễ bôi máu lên đồ tế khí (blood rite) — một nghi lễ thiêng liêng trong văn hóa Trung Hoa cổ đại. Từ nghĩa ''rạn nứt, kẽ hở'' của đồ tế khí, chữ phát triển sang nghĩa ''tranh chấp, gây sự''. Hình thức phồn thể 釁 có cấu trúc phức tạp hơn, không phân tích được rõ theo hình thanh hay hội ý đơn thuần. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy máu súc vật bôi vào đồ thờ cúng; lấy phấn sáp thơm xoa vào người; cãi nhau, xung đột, phân tranh", "Hạng Tần Suất (Jun Da)": "3140.0", "Tần Suất % (Jun Da)": "99.3078665684", "GavinGrover_Once (Chiết tự trực tiếp)": "血 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰血半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "血", "Unihan_Simplified (Chữ Giản thể)": "衅", "Unihan_Traditional (Chữ Phồn thể)": "釁", "Pinyin_Xie": "xìn", "Âm Hán Việt_Xie": "hấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ sự hiềm khích hoặc làm động từ trong từ ghép chỉ hành vi gây hấn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淳', '{"9000": "3141.0", "Chữ Trung Quốc": "淳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước (dạng viết tắt của 水) | 享 | hưởng | biểu âm | hưởng thụ, thụ hưởng | 淳 = 氵(Thủy, biểu nghĩa: nước) + 享 (Hưởng, biểu âm, đại diện cho 𦎧); chữ hình thanh. Bộ 氵 chỉ chất lỏng/sự trong lành; 享/𦎧 cho âm chún. Wiktionary ghi phần âm thực là 𦎧 (hiếm), về hình thức ngày nay như 享.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuần\": nước (氵) trong như được hưởng (享) thụ thiên nhiên — nước thuần khiết, người thuần hậu chất phác, không pha tạp. Nhớ: 淳 = thuần, thuần hậu. | Gương Hán-Việt | Chữ 淳 đọc Hán-Việt là \"thuần\", dùng trong 淳朴 (thuần phác), 淳厚 (thuần hậu) — rất quen trong văn học Hán-Việt và tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 淳 mở khoá: 淳朴 (thuần phác — chất phác mộc mạc), 淳厚 (thuần hậu), 淳风 (thuần phong — phong tục tốt đẹp), 民淳俗厚.", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh (psc): bộ 水 (nước) chỉ sự trong sạch, thuần khiết; 𦎧 (nay giống 享, hưởng) cho âm chún. Nghĩa: thuần khiết, trong lành, mộc mạc chân thật; cũng nghĩa tưới thấm (nghĩa cổ). Lục thư thông đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuần, trong sạch, mộc mạc; tưới, thấm", "Hạng Tần Suất (Jun Da)": "3141.0", "Tần Suất % (Jun Da)": "99.3086815386", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 享", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵享", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "享", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淳", "Unihan_Traditional (Chữ Phồn thể)": "淳", "Pinyin_Xie": "chún", "Âm Hán Việt_Xie": "thuần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để miêu tả tính cách, phong tục giản dị. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悖', '{"9000": "3142.0", "Chữ Trung Quốc": "悖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 忄 | tâm | biểu nghĩa | tâm trí (dạng viết tắt của 心) | 孛 | bội | biểu âm | sao chổi; mọc um tùm | 悖 = 忄(Tâm, biểu nghĩa: tâm trí/đạo lý) + 孛 (Bội, biểu âm); chữ hình thanh. Bộ 忄 chỉ trạng thái lý trí/đạo đức; 孛 (bội) cho âm bèi. Nghĩa: trái lẽ, mâu thuẫn, ngược đạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": tâm (忄) đi như sao chổi (孛) ngược chiều — người trái lẽ, tâm tư ngược với đạo lý, như sao chổi bay ngược trời. Nhớ: 悖 = bội lý, mâu thuẫn. | Gương Hán-Việt | Chữ 悖 đọc Hán-Việt là \"bội\", dùng trong 悖论 (bội luận — nghịch lý), 悖逆 (bội nghịch — phản nghịch), 并行不悖 (song hành không mâu thuẫn) — quen trong văn ngôn và triết học. | Mở khoá kiến thức | Biết 悖 mở khoá: 悖论 (nghịch lý/paradox), 并行不悖 (song song không mâu thuẫn), 悖逆 (bội nghịch), 悖德 (vi phạm đạo đức).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Chữ hình thanh (psc): bộ 心 (tâm) chỉ lý trí, đạo lý; 孛 (bội/sao chổi đi ngược) cho âm bèi. Nghĩa: đi ngược lại lẽ thường, mâu thuẫn, phản nghịch. Giáp cốt văn, tiểu triện, Lục thư thông đều có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trái lẽ", "Hạng Tần Suất (Jun Da)": "3142.0", "Tần Suất % (Jun Da)": "99.309495992", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 孛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄孛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悖", "Unihan_Traditional (Chữ Phồn thể)": "悖", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước tân ngữ để chỉ hành vi đi ngược lại đạo lý hoặc lẽ phải. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髦', '{"9000": "3143.0", "Chữ Trung Quốc": "髦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 14 | nét | 髟 | tiêu | biểu nghĩa | tóc dài, bờm (bộ chỉ tóc) | 毛 | mao | biểu âm | lông, tóc; cho âm ''máo'' | 髦 là chữ hình thanh (suy luận từ cấu trúc, lsCodes không có trong nguồn): 髟 (tiêu, bộ tóc dài) biểu nghĩa chỉ mái tóc, bờm; 毛 (mao, lông tóc) biểu âm cho âm ''máo''. Nghĩa gốc là bờm ngựa, tóc rũ của trẻ nhỏ; mở rộng sang ''người xuất sắc'', rồi 時髦 (thời mao → thời trang).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mao\": bộ tóc (髟) + 毛 biểu âm → bờm ngựa dài, tóc trẻ nhỏ buông rũ; ngày nay 時髦 có nghĩa là thời trang, bắt kịp xu hướng. | Gương Hán-Việt | mao ít dùng độc lập; chủ yếu qua 时髦 (thời mao → thời trang) | Mở khoá kiến thức | Biết 髦 (Mao) mở khoá: 时髦 (thời trang), 赶时髦 (chạy theo mốt).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary cung cấp phát âm và định nghĩa cho 髦 nhưng không có thông tin cụ thể về glyph origin. Cấu trúc: 髟 (bộ tóc dài) + 毛 (lông tóc) — hình ảnh mái tóc hoặc bờm ngựa buông xuống. Tiểu triện lưu dấu hình này. Nghĩa văn ngôn: bờm ngựa, tóc rũ của trẻ, người kiệt xuất. Hiện đại chủ yếu qua 時髦 (thời trang, sành điệu). Chưa có nguồn học thuật xác nhận cụ thể glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờm ngựa; kén chọn", "Hạng Tần Suất (Jun Da)": "3143.0", "Tần Suất % (Jun Da)": "99.3103099286", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 毛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟毛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "髦", "Unihan_Traditional (Chữ Phồn thể)": "髦", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "mao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ trong từ ghép để chỉ sự hợp thời trang, hiện đại. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孜', '{"9000": "3144.0", "Chữ Trung Quốc": "孜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 7 | nét | 子 | tử | biểu âm | con, đứa trẻ | 攵 | phộc | biểu nghĩa | hành động, đánh nhẹ | 孜 = 子 (Tử, biểu âm) + 攵 (Phộc, biểu nghĩa: hành động). Chữ hình thanh — 攵 gợi ý hành động chăm chỉ không ngừng; 子 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": chữ 孜 gồm 子 (đứa trẻ) + 攵 (tay đánh nhẹ) — hình ảnh đứa trẻ bị thúc học, cần mẫn không nghỉ. | Gương Hán-Việt | 孜孜 (tư tư) — cần mẫn, siêng năng | Mở khoá kiến thức | Biết 孜 mở khoá cụm 孜孜不倦 (tư tư bất quyện) — làm việc không biết mệt.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 孜 là chữ hình thanh: 攵 (phộc, hành động) biểu nghĩa sự cần mẫn không ngơi; 子 (tử) biểu âm. Nghĩa gốc dùng trong 孜孜 (zīzī): chăm chỉ, cần mẫn không mệt mỏi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm không mệt mỏi", "Hạng Tần Suất (Jun Da)": "3144.0", "Tần Suất % (Jun Da)": "99.3111228316", "GavinGrover_Once (Chiết tự trực tiếp)": "子 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰子⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "⺙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "子", "Unihan_Simplified (Chữ Giản thể)": "孜", "Unihan_Traditional (Chữ Phồn thể)": "孜", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường dùng lặp lại thành tư tư làm phó từ bổ nghĩa cho động từ học tập, làm việc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粤', '{"9000": "3145.0", "Chữ Trung Quốc": "粤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 12 | nét | 粤 | việt | tượng hình | vùng Lưỡng Quảng, người Bách Việt | 粤 là chữ hội ý phức tạp — Thuyết Văn giải thích là kết hợp 宷 + 亏, song nguồn gốc thực tế liên quan đến 雩 (cầu mưa) được biến thể thêm nét để chỉ vùng đất phương Nam của người Việt cổ. Chữ tượng hình muộn, nghĩa địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"việt\": 粤 là tên gọi đất Việt cổ — vùng Lưỡng Quảng ngày nay. Người Việt Nam và người Quảng Đông cùng chung gốc Bách Việt. | Gương Hán-Việt | Việt (粤) — tên cổ của vùng Quảng Đông, Quảng Tây | Mở khoá kiến thức | Biết 粤 mở khoá 粤语 (Việt ngữ — tiếng Quảng Đông) và 粤菜 (Việt thái — ẩm thực Quảng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Lệ thư | Theo Wiktionary, 粤 là dạng chuyên biệt hoá từ 雩 (yú, cầu mưa), được sửa đổi thêm bộ 雨 (Chi, 2010). Thuyết Văn giải thích là hội ý 宷 + 亏. Dùng làm tên gọi vùng Lưỡng Quảng (Quảng Đông, Quảng Tây) và người Bách Việt cổ. Đây là chữ Việt cổ nhất còn lưu hành. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vùng Lưỡng Quảng; người Bách Việt; bèn, nên", "Hạng Tần Suất (Jun Da)": "3145.0", "Tần Suất % (Jun Da)": "99.3119352178", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 丂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "粤", "Unihan_Traditional (Chữ Phồn thể)": "粵", "Pinyin_Xie": "yuè", "Âm Hán Việt_Xie": "việt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng hoặc định ngữ để chỉ những gì thuộc về bang Quảng Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隘', '{"9000": "3146.0", "Chữ Trung Quốc": "隘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 12 | nét | 阝 | phụ | biểu nghĩa | đồi núi, địa hình cao (bộ phụ bên trái) | 益 | ích | biểu âm | lợi ích (gợi âm ài) | 隘 = 阝 (Phụ, biểu nghĩa: địa hình đồi núi) + 益 (Ích, biểu âm); chữ hình thanh. Bộ phụ (阜) chỉ địa hình hiểm trở; 益 gợi âm ài. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ải\": núi (阝) bao vây tứ phía — 隘 là chỗ hẹp, cửa ải hiểm yếu. | Gương Hán-Việt | 隘 xuất hiện trong 狭隘 (hiệp ải = hẹp hòi) — dùng cả nghĩa địa lý lẫn tính cách. | Mở khoá kiến thức | Biết 隘 (ải) giúp đọc 狭隘 (hẹp hòi, thiếu độ lượng) và 关隘 (ải, cửa ải).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 隘 là chữ hình thanh: 阜/阝 (đồi núi, địa hình) biểu nghĩa, 益 biểu âm. Wiktionary xác nhận: {{Han compound|阜|alt1=阝|益|ls=psc|c1=s|c2=p}}. Nghĩa gốc: chỗ địa hình hẹp, khó qua — từ đó có nghĩa ải, cửa ải (yếu địa) và mở rộng sang nghĩa hẹp hòi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chật hẹp; nơi hiểm trở", "Hạng Tần Suất (Jun Da)": "3146.0", "Tần Suất % (Jun Da)": "99.3127465705", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 益", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝益", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "益", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隘", "Unihan_Traditional (Chữ Phồn thể)": "隘", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ chỉ sự nhỏ hẹp hoặc danh từ chỉ lối đi hiểm trở ở biên giới. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('濒', '{"9000": "3147.0", "Chữ Trung Quốc": "濒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 16 | nét | 氵 | thuỷ | biểu nghĩa | nước | 频 | tần | biểu âm | thường xuyên (gợi âm bīn) | 濒 = 氵 (Thuỷ, biểu nghĩa: nước) + 频 (Tần, biểu âm); chữ hình thanh. Bộ thuỷ gợi vùng đất gần nước; 频 gợi âm bīn. Chữ giản thể của 瀕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tần\": nước (氵) luôn ở bên — tần suất tiếp xúc với ranh giới nguy hiểm; 濒 nghĩa là gần kề, sắp đến. | Gương Hán-Việt | 濒 xuất hiện trong 濒临 (tần lâm = gần kề, bên bờ vực). | Mở khoá kiến thức | Biết 濒 (tần) mở khóa 濒临 (bên bờ vực, sắp...) và 濒危 (nguy cấp, gần tuyệt chủng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 濒 là dạng giản thể của 瀕. Wiktionary ghi {{Han simp|瀕|f=頻|t=频}} — chữ phồn thể 瀕 gồm 水 (biểu nghĩa: nước) và 頻 (biểu âm). Kim văn ghi lại hình dạng phồn thể với nhiều biến thể. Nghĩa gốc: đất gần mép nước, bờ nước; từ đó mở rộng sang nghĩa ''sắp, gần kề'' (như gần chết, gần nguy hiểm). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gần, bên cạnh; sắp, chuẩn bị; đất gần nước", "Hạng Tần Suất (Jun Da)": "3147.0", "Tần Suất % (Jun Da)": "99.3135574063", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 频", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵频", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "频", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "濒", "Unihan_Traditional (Chữ Phồn thể)": "瀕", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Giới từ | 介词 | Thường làm động từ đi kèm tân ngữ để chỉ trạng thái cận kề một ranh giới hoặc nguy cơ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铮', '{"9000": "3148.0", "Chữ Trung Quốc": "铮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại | 争 | tranh | biểu âm | tranh giành | 铮 = 钅 (Kim, biểu nghĩa: kim loại) + 争 (Tranh, biểu âm). Chữ hình thanh — 钅 cho biết đây là âm thanh kim loại; 争 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": 铮 = kim loại (钅) + tranh (争) — tiếng chiêng vang lên như tranh giành sự chú ý. | Gương Hán-Việt | tranh (铮) — trong 铮铮有声 (tranh tranh hữu thanh) | Mở khoá kiến thức | Biết 铮 mở khoá 铮铮 (tiếng kim loại reng reng) và 铮亮 (sáng bóng như kim loại đánh bóng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 铮 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 爭 (tranh) biểu âm. Nghĩa gốc: tiếng kêu lanh lảnh của nhạc cụ kim loại hoặc chiêng nhỏ. Còn dùng trong 铮铮 (zhēngzhēng) mô tả tiếng kim loại vang. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng chim kêu lanh lảnh", "Hạng Tần Suất (Jun Da)": "3148.0", "Tần Suất % (Jun Da)": "99.3143661751", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铮", "Unihan_Traditional (Chữ Phồn thể)": "錚", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng làm từ tượng thanh mô tả tiếng kim loại va chạm hoặc làm tính từ chỉ sự cứng cỏi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('畸', '{"9000": "3149.0", "Chữ Trung Quốc": "畸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 13 | nét | 田 | điền | biểu nghĩa | ruộng đất | 奇 | kỳ | biểu âm | lạ, kỳ dị | 畸 = 田 (Điền, biểu nghĩa: ruộng) + 奇 (Kỳ, biểu âm). Chữ hình thanh — 田 gợi mảnh đất lẻ, không đều; 奇 cho âm đọc. Nghĩa gốc: mảnh ruộng thừa, lẻ tẻ, sau mở rộng sang nghĩa dị dạng, lệch chuẩn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 畸 = ruộng (田) + kỳ lạ (奇) — mảnh ruộng hình dáng kỳ lạ, lệch chuẩn, dị dạng. | Gương Hán-Việt | kỳ hình (畸形) — dị dạng, dị hình | Mở khoá kiến thức | Biết 畸 mở khoá 畸形 (kỳ hình — dị dạng) và 畸变 (biến dạng bất thường).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 畸 chưa có giải thích cấu trúc rõ ràng trong wikitext. Dựa vào thành phần: 田 (điền, ruộng) + 奇 (kỳ, lạ) gợi ý mảnh ruộng lẻ, không đều. Từ đây mở rộng nghĩa: lệch, dị thường. Không có chứng liệu giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thiên về; lệch về; khác thường; dị dạng; dị thường; lạ thường", "Hạng Tần Suất (Jun Da)": "3149.0", "Tần Suất % (Jun Da)": "99.3151733935", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "畸", "Unihan_Traditional (Chữ Phồn thể)": "畸", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để chỉ trạng thái phát triển không bình thường hoặc mất cân đối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剔', '{"9000": "3150.0", "Chữ Trung Quốc": "剔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 10 | nét | 易 | dịch | biểu âm | thay đổi, dịch chuyển (gợi âm tī) | 刂 | đao | biểu nghĩa | dao | 剔 = 易 (Dịch, biểu âm) + 刂 (Đao, biểu nghĩa: dao); chữ hình thanh. Bộ đao chỉ hành động cắt, gỡ bằng dao; 易 gợi âm tī. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": dao (刂) tách dịch chuyển (易) từng phần — 剔 là gỡ, chọn lọc cẩn thận. | Gương Hán-Việt | 剔 xuất hiện trong 挑剔 (khiêu dịch = kén chọn, khó tính) và 剔除 (dịch trừ = loại bỏ). | Mở khoá kiến thức | Biết 剔 (dịch) giúp đọc 挑剔 (kén chọn, cầu kỳ) và 剔除 (loại bỏ, sàng lọc).", "Tự nguyên_Xie": "Tiểu triện | 剔 là chữ hình thanh: 刀/刂 (dao) biểu nghĩa, 易 biểu âm. Wiktionary xác nhận: {{Han compound|易|刀|ls=psc|c1=p|c2=s|t2=knife}}. Nghĩa gốc: dùng dao nhọn gỡ thịt khỏi xương — từ đó mở rộng sang nghĩa chọn lọc, loại bỏ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỡ, xé; chọn và nhặt ra", "Hạng Tần Suất (Jun Da)": "3150.0", "Tần Suất % (Jun Da)": "99.3159790615", "GavinGrover_Once (Chiết tự trực tiếp)": "易 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰易刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "易", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剔", "Unihan_Traditional (Chữ Phồn thể)": "剔", "Pinyin_Xie": "tī", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ xương thịt hoặc dùng trong cụm động bổ để chỉ việc loại bỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坞', '{"9000": "3151.0", "Chữ Trung Quốc": "坞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 乌 | ô | biểu âm | con quạ, đen | 坞 = 土 (Thổ, biểu nghĩa: đất) + 乌 (Ô, biểu âm). Chữ hình thanh — 土 cho biết đây là công trình đất; 乌 cho âm đọc. Nghĩa gốc: lũy đất phòng thủ, bến tàu đắp đất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ô\": 坞 = đất (土) + ô (乌) — lũy đất đen như quạ, dùng để phòng thủ hay neo thuyền. | Gương Hán-Việt | ô (坞) — trong 船坞 (thuyền ô — xưởng đóng tàu, bến tàu) | Mở khoá kiến thức | Biết 坞 mở khoá 船坞 (chuán wù — ụ tàu, bến tàu) và 山坞 (thung lũng núi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 坞 là chữ hình thanh: 土 (thổ, đất) biểu nghĩa, 烏 (ô) biểu âm. Nghĩa gốc: công sự đắp bằng đất để phòng thủ. Mở rộng sang nghĩa bến thuyền (船坞) và thung lũng nhỏ có núi vây quanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lô cốt phòng giặc cướp; núi trong nước", "Hạng Tần Suất (Jun Da)": "3151.0", "Tần Suất % (Jun Da)": "99.3167847295", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 乌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土乌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坞", "Unihan_Traditional (Chữ Phồn thể)": "塢", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "ổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau để chỉ bến tàu hoặc khu đất trũng có bờ bao quanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篱', '{"9000": "3152.0", "Chữ Trung Quốc": "篱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 离 | ly | biểu âm | xa cách | 篱 = 竹 (Trúc, biểu nghĩa: tre) + 离 (Ly, biểu âm). Chữ hình thanh — 竹 cho biết hàng rào làm bằng tre; 离 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ly\": 篱 = tre (竹) + ly (离) — hàng rào tre ngăn cách, giống như sự chia ly phân cách không gian. | Gương Hán-Việt | ly (篱) — trong 篱笆 (ly ba — hàng rào) | Mở khoá kiến thức | Biết 篱 mở khoá 篱笆 (lí ba — hàng rào) và 樊篱 (phàn lý — rào cản, giới hạn).", "Tự nguyên_Xie": "Theo Wiktionary, 篱 là chữ hình thanh: 竹 (trúc, tre) biểu nghĩa, 離 (ly) biểu âm. Nghĩa gốc: hàng rào, bờ giậu làm bằng tre hoặc gỗ để phân cách khu vực. Thường gặp trong thơ cổ điển Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàng rào, bờ giậu", "Hạng Tần Suất (Jun Da)": "3152.0", "Tần Suất % (Jun Da)": "99.3175898807", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "篱", "Unihan_Traditional (Chữ Phồn thể)": "籬", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu như tre, gỗ để tạo thành từ ghép chỉ hàng rào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淀', '{"9000": "3153.0", "Chữ Trung Quốc": "淀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 定 | định | biểu âm | ổn định (gợi âm diàn) | 淀 = 氵 (Thuỷ, biểu nghĩa: nước) + 定 (Định, biểu âm); chữ hình thanh. Bộ thuỷ chỉ liên quan đến nước; 定 gợi âm diàn. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điến\": nước (氵) đứng yên (定) — cặn lắng xuống, 淀 là kết tủa, trầm tích. | Gương Hán-Việt | 淀 xuất hiện trong 沉淀 (trầm điến = kết tủa, trầm tích) và 淀粉 (điến phấn = tinh bột). | Mở khoá kiến thức | Biết 淀 (điến) giúp đọc 沉淀 (kết tủa, tích lũy lâu dài) và 淀粉 (tinh bột) — dùng nhiều trong khoa học và nấu ăn.", "Tự nguyên_Xie": "Tiểu triện | 淀 là chữ hình thanh: 水/氵 (nước) biểu nghĩa, 定 biểu âm. Wiktionary xác nhận: {{Han compound|水|定|c1=s|c2=p|t1=water|ls=psc}}. Nghĩa gốc: vùng nước nông, đầm lầy nông; từ đó phát triển sang nghĩa lắng xuống, kết tủa (như cặn lắng xuống đáy nước). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước nông", "Hạng Tần Suất (Jun Da)": "3153.0", "Tần Suất % (Jun Da)": "99.3183945152", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 定", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵定", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "定", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淀", "Unihan_Traditional (Chữ Phồn thể)": "淀", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm động từ chỉ sự lắng đọng hóa học hoặc danh từ chỉ vùng nước nông, đầm lầy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓦', '{"9000": "3154.0", "Chữ Trung Quốc": "蓦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 13 | nét | 莫 | mạc | biểu âm | chẳng, không ai | 马 | mã | biểu nghĩa | ngựa | 蓦 = 莫 (Mạc, biểu âm) + 马 (Mã, biểu nghĩa: ngựa). Chữ hình thanh — 马 gợi hành động phóng ngựa bất ngờ; 莫 cho âm đọc. Nghĩa gốc: cưỡi lên ngựa, sau mở rộng sang nghĩa đột ngột.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": 蓦 = ngựa (马) + mạc (莫) — bỗng nhiên phi ngựa, nhanh không kịp nhận ra. | Gương Hán-Việt | mạc (蓦) — trong 蓦然 (mạc nhiên — bỗng nhiên) | Mở khoá kiến thức | Biết 蓦 mở khoá 蓦然 (mò rán — bỗng nhiên, đột nhiên) — cụm rất thơ.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蓦 là chữ hình thanh: 馬 (mã, ngựa) biểu nghĩa, 莫 (mạc) biểu âm. Nghĩa gốc: leo lên ngựa. Nghĩa phái sinh: bỗng nhiên, đột ngột — như cú nhảy lên lưng ngựa không báo trước. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỗng nhiên; lên ngựa; siêu việt", "Hạng Tần Suất (Jun Da)": "3154.0", "Tần Suất % (Jun Da)": "99.3191981161", "GavinGrover_Once (Chiết tự trực tiếp)": "莫 + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱莫马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "蓦", "Unihan_Traditional (Chữ Phồn thể)": "驀", "Pinyin_Xie": "mò", "Âm Hán Việt_Xie": "mạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước động từ để biểu thị hành động xảy ra một cách đột ngột. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唬', '{"9000": "3155.0", "Chữ Trung Quốc": "唬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 虎 | hổ | biểu âm | hổ, cọp | 唬 = 口 (Khẩu, biểu nghĩa: miệng) + 虎 (Hổ, biểu âm). Chữ hình thanh — 口 gợi hành động nói, dọa nạt bằng lời; 虎 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hỗ\": 唬 = miệng (口) + hổ (虎) — mở miệng như hổ gầm để dọa nạt người khác. | Gương Hán-Việt | hỗ (唬) — trong 吓唬 (hách hỗ — dọa nạt) | Mở khoá kiến thức | Biết 唬 mở khoá 吓唬 (xià hu — dọa nạt) và 唬人 (hù người, nói phét).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 唬 là chữ hình thanh: 口 (khẩu, miệng) biểu nghĩa, 虎 (hổ) biểu âm. Nghĩa gốc: dọa nạt, hù dọa bằng lời nói — tiếng nói như tiếng hổ gầm khiến người sợ hãi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "doạ nạt, đe doạ", "Hạng Tần Suất (Jun Da)": "3155.0", "Tần Suất % (Jun Da)": "99.3200012002", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 虎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口虎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唬", "Unihan_Traditional (Chữ Phồn thể)": "唬", "Pinyin_Xie": "hǔ", "Âm Hán Việt_Xie": "hổ, hách, hào, hao, quách, hạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ người để biểu thị hành vi hù dọa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锣', '{"9000": "3156.0", "Chữ Trung Quốc": "锣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 钅 | kim | biểu nghĩa | kim loại | 罗 | la | biểu âm | mạng lưới, họ La | 锣 = 钅 (Kim, biểu nghĩa: kim loại) + 罗 (La, biểu âm). Chữ hình thanh — 钅 cho biết đây là nhạc cụ kim loại; 罗 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": 锣 = kim loại (钅) + la (罗) — thanh la là tấm kim loại kêu la to khi gõ. | Gương Hán-Việt | la (锣) — trong 锣鼓 (la cổ — chiêng trống) | Mở khoá kiến thức | Biết 锣 mở khoá 锣鼓 (luó gǔ — chiêng trống) và 开锣 (khai la — khai màn, mở đầu).", "Tự nguyên_Xie": "Theo Wiktionary, 锣 là chữ hình thanh: 金 (kim loại) biểu nghĩa, 罗 (la) biểu âm. Nghĩa gốc: chiếc thanh la — nhạc cụ gõ bằng đồng, dùng trong lễ hội, quân đội và kịch truyền thống. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái thanh la", "Hạng Tần Suất (Jun Da)": "3156.0", "Tần Suất % (Jun Da)": "99.3208032507", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 罗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅罗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锣", "Unihan_Traditional (Chữ Phồn thể)": "鑼", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nhạc cụ gõ, thường kết hợp với động từ đánh hoặc gõ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汀', '{"9000": "3157.0", "Chữ Trung Quốc": "汀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 5 | nét | 氵 | thủy | biểu nghĩa | nước | 丁 | đinh | biểu âm | đinh, người tráng đinh | 汀 = 氵 (Thủy, biểu nghĩa: nước) + 丁 (Đinh, biểu âm). Chữ hình thanh — 氵 cho biết đây là địa hình ven nước; 丁 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": 汀 = nước (氵) + đinh (丁) — bãi cát đinh hình nằm bên dòng nước, phẳng lặng. | Gương Hán-Việt | đinh (汀) — trong 沙汀 (sa đinh — bãi cát ven sông) | Mở khoá kiến thức | Biết 汀 mở khoá 沙汀 (shā tīng — bãi cát), 绿汀 (lục đinh — bờ cỏ xanh ven nước).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 汀 là chữ hình thanh: 水 (thủy, nước) biểu nghĩa, 丁 (đinh) biểu âm. Nghĩa gốc: bãi cát hay đất bằng phẳng ven sông, ven biển — nơi nước lui để lộ ra nền đất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bãi sông; châu Đinh (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "3157.0", "Tần Suất % (Jun Da)": "99.3216053012", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汀", "Unihan_Traditional (Chữ Phồn thể)": "汀", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong địa danh hoặc thơ ca để chỉ bãi đất bồi ven sông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('趾', '{"9000": "3158.0", "Chữ Trung Quốc": "趾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 𧾷 | túc | biểu nghĩa | bàn chân | 止 | chỉ | biểu âm | dừng lại, bàn chân | 趾 = 足 (Túc, biểu nghĩa: bàn chân) + 止 (Chỉ, biểu âm và biểu nghĩa phụ: bàn chân, dừng lại). Chữ vừa hình thanh vừa hội ý — 止 vốn là hình vẽ bàn chân cổ; 足 gia tăng nghĩa chân. Nghĩa gốc: ngón chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chỉ\": 趾 = bàn chân (足) + chỉ (止) — ngón chân là nơi bàn chân dừng lại, điểm cuối cùng của chân. | Gương Hán-Việt | chỉ (趾) — trong 手足胼胝 (tay chân chai cứng) và 趾高气扬 | Mở khoá kiến thức | Biết 趾 mở khoá 趾高气扬 (zhǐ gāo qì yáng — vênh vang, ngạo mạn) và 足趾 (ngón chân).", "Tự nguyên_Xie": "Theo Wiktionary, 趾 kết hợp 足 (túc, chân) và 止 (chỉ), cả hai đều liên quan đến bàn chân. 止 vốn là hình vẽ bàn chân trong chữ giáp cốt. Việc thêm 足 nhấn mạnh nghĩa chân, phân biệt với chỉ (止) dùng trong các nghĩa khác. Nghĩa gốc: ngón chân, dấu chân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân; ngón chân; dấu vết", "Hạng Tần Suất (Jun Da)": "3158.0", "Tần Suất % (Jun Da)": "99.3224073518", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 止", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊止", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "止", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "趾", "Unihan_Traditional (Chữ Phồn thể)": "趾", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận cơ thể, thường kết hợp với các từ chỉ ngón để tạo từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缉', '{"9000": "3159.0", "Chữ Trung Quốc": "缉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 纟 | mịch | biểu nghĩa | sợi chỉ, tơ lụa | 咠 | thấp | biểu âm | thì thầm (gợi âm jī) | 缉 = 纟 (Mịch, biểu nghĩa: sợi chỉ) + 咠 (Thấp, biểu âm); chữ hình thanh. Bộ mịch chỉ sợi chỉ, may vá; 咠 gợi âm jī. Chữ giản thể của 緝. Lục thư thông đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tập\": sợi chỉ (纟) kết nối từng mảnh — 缉 là chắp nối manh mối, truy nã. | Gương Hán-Việt | 缉 xuất hiện trong 通缉 (thông tập = truy nã toàn quốc). | Mở khoá kiến thức | Biết 缉 (tập) giúp đọc 通缉 (truy nã) và 缉拿 (bắt giữ tội phạm).", "Tự nguyên_Xie": "Lục thư thông | 缉 là dạng giản thể của 緝. Wiktionary ghi {{Han simp|緝|f=糹|t=纟}}, sau đó dẫn đến {{zh-see|緝}}. Chữ phồn thể 緝 gồm 糸 (biểu nghĩa: sợi chỉ) và 咠 (biểu âm). Nghĩa gốc: khâu sợi chỉ dày, chắp nối — từ đó mở rộng sang nghĩa lùng bắt (chắp nối manh mối để truy bắt tội phạm). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chắp sợi, bện dây thừng; viền mép, viền gấu; chắp nối; lùng bắt", "Hạng Tần Suất (Jun Da)": "3159.0", "Tần Suất % (Jun Da)": "99.3232078519", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缉", "Unihan_Traditional (Chữ Phồn thể)": "緝", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ tội phạm hoặc kẻ đào tẩu để chỉ hoạt động truy bắt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫦', '{"9000": "3160.0", "Chữ Trung Quốc": "嫦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 常 | thường | biểu âm | thường, bình thường | 嫦 = 女 (Nữ, biểu nghĩa: phụ nữ) + 常 (Thường, biểu âm). Chữ hình thanh — 女 cho biết đây là tên riêng của một nữ thần; 常 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thường\": 嫦 = nữ (女) + thường (常) — nàng Hằng Nga, người phụ nữ thường trú trên cung trăng. | Gương Hán-Việt | Hằng Nga (嫦娥) — nữ thần mặt trăng | Mở khoá kiến thức | Biết 嫦 mở khoá 嫦娥 (Cháng''é — Hằng Nga) và 嫦娥奔月 (Hằng Nga bay lên cung trăng).", "Tự nguyên_Xie": "Theo Wiktionary, 嫦 là chữ hình thanh: 女 (nữ) biểu nghĩa, 常 (thường) biểu âm. Chữ này chỉ dùng trong tên riêng 嫦娥 (Hằng Nga) — nữ thần mặt trăng trong thần thoại Trung Quốc, vợ của Hậu Nghệ, uống thuốc trường sinh và bay lên cung trăng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thường nga 嫦娥)", "Hạng Tần Suất (Jun Da)": "3160.0", "Tần Suất % (Jun Da)": "99.3240083521", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 常", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女常", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "常", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫦", "Unihan_Traditional (Chữ Phồn thể)": "嫦", "Pinyin_Xie": "cháng", "Âm Hán Việt_Xie": "thường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng làm danh từ riêng trong tên gọi Hằng Nga để chỉ vị tiên nữ trên mặt trăng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斟', '{"9000": "3161.0", "Chữ Trung Quốc": "斟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 斗 | Số nét | 13 | nét | 甚 | thậm | biểu âm | rất, quá (gợi âm zhēn) | 斗 | đẩu | biểu nghĩa | gáo múc, đấu đong lường | 斟 = 甚 (Thậm, biểu âm) + 斗 (Đẩu, biểu nghĩa: gáo múc, đồ đong đo); chữ hình thanh. Bộ đẩu chỉ dụng cụ rót; 甚 gợi âm zhēn. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"châm\": gáo (斗) rót từng chút một — 斟 là rót rượu cẩn thận, xem xét kỹ. | Gương Hán-Việt | 斟 xuất hiện trong 斟酌 (châm chước = cân nhắc, xem xét kỹ). | Mở khoá kiến thức | Biết 斟 (châm) giúp đọc 斟酌 (cân nhắc, xem xét) — cụm từ dùng nhiều trong văn viết trang trọng.", "Tự nguyên_Xie": "Tiểu triện | 斟 là chữ hình thanh: 斗 (gáo múc, dụng cụ rót) biểu nghĩa, 甚 biểu âm. Wiktionary xác nhận: {{Han compound|甚|斗|ls=psc|c1=p|c2=s|t2=dipper; cup}}. Nghĩa gốc: rót rượu hay trà vào chén — động tác cẩn thận, đo lường. Từ đó mở rộng sang nghĩa cân nhắc kỹ lưỡng (斟酌). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rót, chắt (nước)", "Hạng Tần Suất (Jun Da)": "3161.0", "Tần Suất % (Jun Da)": "99.3248078187", "GavinGrover_Once (Chiết tự trực tiếp)": "甚 + 斗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甚斗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "斗", "Unihan_Simplified (Chữ Giản thể)": "斟", "Unihan_Traditional (Chữ Phồn thể)": "斟", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "châm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các danh từ chỉ đồ uống như trà, rượu để chỉ hành động rót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞍', '{"9000": "3162.0", "Chữ Trung Quốc": "鞍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 15 | nét | 革 | cách | biểu nghĩa | da thuộc | 安 | an | biểu âm | bình yên | 鞍 = 革 (Cách, biểu nghĩa: da thuộc) + 安 (An, biểu âm). Chữ hình thanh — 革 cho biết vật làm bằng da; 安 cho âm đọc. Nghĩa gốc: yên ngựa — vật bằng da đặt lên lưng ngựa để cưỡi cho an toàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"an\": 鞍 = da (革) + an (安) — yên ngựa bằng da, giúp người cưỡi ngồi an toàn, an ổn. | Gương Hán-Việt | an (鞍) — trong 鞍马 (an mã — ngựa và yên cương) | Mở khoá kiến thức | Biết 鞍 mở khoá 鞍马 (ān mǎ — ngựa yên cương) và 鞍鞯 (yên và bộ đồ ngựa).", "Tự nguyên_Xie": "Theo Wiktionary, 鞍 là chữ hình thanh: 革 (cách, da thuộc) biểu nghĩa, 安 (an) biểu âm và gợi ý nghĩa: yên ngựa giúp người cưỡi ngồi an ổn. Nghĩa gốc: yên cương ngựa làm bằng da. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên cương ngựa", "Hạng Tần Suất (Jun Da)": "3162.0", "Tần Suất % (Jun Da)": "99.3256062518", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞍", "Unihan_Traditional (Chữ Phồn thể)": "鞌", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "an", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ vật dụng đặt trên lưng ngựa, thường đi kèm với lượng từ hoặc động từ đặt lên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扳', '{"9000": "3163.0", "Chữ Trung Quốc": "扳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 扌 | thủ | biểu nghĩa | tay | 反 | phản | biểu âm | ngược lại, lật | 扳 = 扌 (Thủ, biểu nghĩa: tay) + 反 (Phản, biểu âm). Chữ hình thanh — 扌 cho biết đây là hành động của tay; 反 cho âm đọc và gợi ý hành động lật, kéo ngược.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phản\": 扳 = tay (扌) + phản (反) — dùng tay bẻ ngược, lật lại hay kéo về phía mình. | Gương Hán-Việt | phản (扳) — trong 扳平 (phản bình — gỡ hòa) | Mở khoá kiến thức | Biết 扳 mở khoá 扳平 (bān píng — gỡ hòa) và 扳手 (bān shǒu — cờ lê, mỏ lết).", "Tự nguyên_Xie": "Wiktionary không có giải thích cấu trúc rõ ràng cho 扳. Dựa vào thành phần: 扌 (thủ, tay) + 反 (phản, lật ngược) gợi ý hành động dùng tay kéo, nắm, lật. Nghĩa gốc: kéo, bám, nắm chặt để lật hay giữ lại. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vin, vịn, bám, kéo, nắm chặt; lật mặt", "Hạng Tần Suất (Jun Da)": "3163.0", "Tần Suất % (Jun Da)": "99.3264021009", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "扳", "Unihan_Traditional (Chữ Phồn thể)": "扳", "Pinyin_Xie": "bān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đồ vật cần vặn hoặc bẻ như tay lái, công tắc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bān | / | kéo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拴', '{"9000": "3164.0", "Chữ Trung Quốc": "拴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 全 | toàn | biểu âm | toàn bộ, hoàn toàn | 拴 = 扌 (Thủ, biểu nghĩa: tay) + 全 (Toàn, biểu âm). Chữ hình thanh — 扌 cho biết hành động của tay; 全 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": 拴 = tay (扌) + toàn (全) — dùng tay buộc chặt toàn bộ, không cho thoát. | Gương Hán-Việt | thuyên (拴) — trong 拴住 (thuyên trú — buộc chặt, giữ lại) | Mở khoá kiến thức | Biết 拴 mở khoá 拴住 (shuān zhù — buộc chặt) và 拴绳 (buộc dây).", "Tự nguyên_Xie": "Theo Wiktionary, 拴 là chữ hình thanh: 手 (thủ, tay) biểu nghĩa, 全 (toàn) biểu âm. Nghĩa gốc: buộc chặt bằng dây, trói lại — hành động dùng tay và dây để giữ chắc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kén chọn; buộc, trói", "Hạng Tần Suất (Jun Da)": "3164.0", "Tần Suất % (Jun Da)": "99.3271963996", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拴", "Unihan_Traditional (Chữ Phồn thể)": "拴", "Pinyin_Xie": "shuān", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ mang tân ngữ chỉ con vật hoặc đồ vật cần buộc chặt vào một điểm cố định. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shuān | / | cột | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诅', '{"9000": "3165.0", "Chữ Trung Quốc": "诅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 且 | thả | biểu âm | hơn nữa, tạm thời | 诅 = 讠 (Ngôn, biểu nghĩa: lời nói) + 且 (Thả, biểu âm). Chữ hình thanh — 讠 cho biết đây là hành động lời nói; 且 cho âm đọc. Nghĩa gốc: nguyền rủa, chửi bới bằng lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trớ\": 诅 = lời nói (讠) + thả (且) — lời nguyền rủa thô tục, nói ra để hại người. | Gương Hán-Việt | trớ (诅) — trong 诅咒 (trớ chú — nguyền rủa) | Mở khoá kiến thức | Biết 诅 mở khoá 诅咒 (zǔ zhòu — nguyền rủa, lời thề độc).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không có giải thích cấu trúc rõ ràng cho 诅. Dựa vào thành phần: 言 (ngôn, lời nói) + 且 (thả) là chữ hình thanh. Nghĩa gốc: nguyền rủa, thề độc, cầu cho ai gặp điều xấu. Thường gặp trong 诅咒 (nguyền rủa). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rủa, chửi", "Hạng Tần Suất (Jun Da)": "3165.0", "Tần Suất % (Jun Da)": "99.3279896648", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诅", "Unihan_Traditional (Chữ Phồn thể)": "詛", "Pinyin_Xie": "zǔ", "Âm Hán Việt_Xie": "trớ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với các từ khác tạo thành động từ ghép như trớ chú, nguyền trớ để chỉ hành vi nguyền rủa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谟', '{"9000": "3166.0", "Chữ Trung Quốc": "谟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 莫 | mạc | biểu âm | chẳng, không | 谟 = 讠 (Ngôn, biểu nghĩa: lời nói) + 莫 (Mạc, biểu âm). Chữ hình thanh — 讠 cho biết đây là lĩnh vực ngôn luận, mưu kế; 莫 cho âm đọc. Nghĩa gốc: mưu kế đã được bàn tính, kế sách định sẵn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mô\": 谟 = lời nói (讠) + mạc (莫) — mưu kế lớn không ai so bì được, kế sách bí ẩn như đêm tối. | Gương Hán-Việt | mô (谟) — trong 宏谟 (hoành mô — mưu lược lớn) | Mở khoá kiến thức | Biết 谟 mở khoá 宏谟 (hóng mó — mưu lược vĩ đại) — từ văn ngôn cổ điển.", "Tự nguyên_Xie": "Đại triện | Wiktionary không có giải thích cấu trúc rõ ràng cho 谟. Dựa vào thành phần: 言 (ngôn) + 莫 (mạc) là chữ hình thanh. Nghĩa gốc: mưu đồ, kế sách được tính trước. Thường dùng trong văn ngôn cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mưu đã định sẵn; tiến hành", "Hạng Tần Suất (Jun Da)": "3166.0", "Tần Suất % (Jun Da)": "99.3287824132", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谟", "Unihan_Traditional (Chữ Phồn thể)": "謨", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong văn viết cổ hoặc kết hợp thành từ ghép chỉ mưu lược, kế sách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呃', '{"9000": "3167.0", "Chữ Trung Quốc": "呃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 厄 | ách | biểu âm | tai nạn, khó khăn | 呃 = 口 (Khẩu, biểu nghĩa: miệng) + 厄 (Ách, biểu âm). Chữ hình thanh — 口 cho biết đây là âm thanh phát ra từ miệng; 厄 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ách\": 呃 = miệng (口) + ách (厄) — tiếng nấc ách ách bất ngờ, như ách tai nạn nhỏ không báo trước. | Gương Hán-Việt | ách (呃) — tiếng nấc, tiếng ợ | Mở khoá kiến thức | Biết 呃 mở khoá các từ mô phỏng âm thanh phát ra từ miệng trong văn nói thường ngày.", "Tự nguyên_Xie": "Theo Wiktionary, 呃 là chữ hình thanh: 口 (khẩu, miệng) biểu nghĩa, 厄 (ách) biểu âm. Nghĩa gốc: tiếng nấc, tiếng ợ hơi — âm thanh không tự chủ phát ra từ miệng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấc", "Hạng Tần Suất (Jun Da)": "3167.0", "Tần Suất % (Jun Da)": "99.329574128", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 厄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口厄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呃", "Unihan_Traditional (Chữ Phồn thể)": "呃", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Trợ từ | 助词 | Danh từ | 名词 | Thường dùng làm từ mô phỏng âm thanh nấc hoặc làm trợ từ ngữ khí ở cuối câu. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懦', '{"9000": "3168.0", "Chữ Trung Quốc": "懦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 17 | nét | 忄 | tâm | biểu nghĩa | tâm, tấm lòng | 需 | nhu | biểu âm | cần, nhu cầu | 懦 = 忄 (Tâm, biểu nghĩa: tấm lòng, tâm tính) + 需 (Nhu, biểu âm). Chữ hình thanh — 忄 cho biết đây là trạng thái tâm lý; 需 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": 懦 = tâm (忄) + nhu (需) — tâm hồn quá nhu mì, yếu đuối đến mức hèn nhát. | Gương Hán-Việt | nhu (懦) — trong 懦弱 (nhu nhược — yếu đuối, hèn nhát) | Mở khoá kiến thức | Biết 懦 mở khoá 懦弱 (nuò ruò — yếu đuối, nhút nhát) và 懦夫 (kẻ hèn nhát).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 懦 là chữ hình thanh: 心 (tâm) biểu nghĩa, 需 (nhu) biểu âm. Nghĩa gốc: nhút nhát, hèn yếu về tinh thần — người có tâm hồn yếu đuối, không dám đương đầu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ, nhút nhát", "Hạng Tần Suất (Jun Da)": "3168.0", "Tần Suất % (Jun Da)": "99.3303653261", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懦", "Unihan_Traditional (Chữ Phồn thể)": "懦", "Pinyin_Xie": "nuò", "Âm Hán Việt_Xie": "nọa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ chỉ người hoặc kết hợp thành từ ghép như nhu nhược, hèn nhát. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逞', '{"9000": "3169.0", "Chữ Trung Quốc": "逞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 辶 | sước | biểu nghĩa | đi lại | 呈 | trình | biểu âm | trình bày, dâng lên | 逞 = 辶 (Sước, biểu nghĩa: hành động, đi lại) + 呈 (Trình, biểu âm). Chữ hình thanh — 辶 gợi hành động xúc tiến, thực hiện; 呈 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sính\": 逞 = đi lại (辶) + trình (呈) — chạy ra phô trương, trình diễn sức mạnh một cách phóng túng. | Gương Hán-Việt | sính (逞) — trong 逞强 (sính cường — khoe mẽ sức mạnh) | Mở khoá kiến thức | Biết 逞 mở khoá 逞强 (chěng qiáng — khoe mẽ), 逞能 (phô trương tài năng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 逞 là chữ hình thanh: 辵 (sước, hành động) biểu nghĩa, 呈 (trình) biểu âm. Nghĩa gốc: tỏ ra, phô bày, thực hiện được điều mình muốn — thường hàm ý khoe khoang hoặc lạm dụng sức mạnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sướng; tỏ ra, tỏ vẻ", "Hạng Tần Suất (Jun Da)": "3169.0", "Tần Suất % (Jun Da)": "99.3311560073", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 呈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶呈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逞", "Unihan_Traditional (Chữ Phồn thể)": "逞", "Pinyin_Xie": "chěng", "Âm Hán Việt_Xie": "sính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ hành vi khoe khoang hoặc thể hiện uy thế một cách tiêu cực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犁', '{"9000": "3170.0", "Chữ Trung Quốc": "犁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 11 | nét | 利 | lợi | biểu âm | lợi ích, sắc bén | 牛 | ngưu | biểu nghĩa | trâu, bò | 犁 = 利 (Lợi, biểu âm) + 牛 (Ngưu, biểu nghĩa: trâu bò). Chữ hình thanh — 牛 cho biết đây liên quan đến trâu bò; 利 cho âm đọc và gợi ý sự sắc bén của lưỡi cày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lê\": 犁 = trâu (牛) + lợi (利) — cái cày sắc bén do trâu kéo để cày đất. Lê đất cho mùa vụ. | Gương Hán-Việt | lê (犁) — trong 犁田 (lê điền — cày ruộng) | Mở khoá kiến thức | Biết 犁 mở khoá 犁田 (lí tián — cày ruộng) và 铁犁 (tiế lê — cày sắt).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 犁 là chữ hình thanh: 利 (lợi) biểu âm, 牛 (ngưu, trâu bò) biểu nghĩa. Nghĩa gốc: cái cày — nông cụ do trâu kéo để xới đất. Lưỡi cày sắc bén (利) kéo bởi trâu (牛). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cày ruộng", "Hạng Tần Suất (Jun Da)": "3170.0", "Tần Suất % (Jun Da)": "99.3319466886", "GavinGrover_Once (Chiết tự trực tiếp)": "利 + 牛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱利牛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犁", "Unihan_Traditional (Chữ Phồn thể)": "犁", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "lê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Vừa làm danh từ chỉ công cụ làm đất, vừa làm động từ chỉ hành động cày ruộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忏', '{"9000": "3171.0", "Chữ Trung Quốc": "忏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 6 | nét | 忄 | tâm | biểu nghĩa | tâm, tấm lòng | 千 | thiên | biểu âm | nghìn, ngàn | 忏 = 忄 (Tâm, biểu nghĩa: tấm lòng) + 千 (Thiên, biểu âm). Chữ hình thanh — 忄 cho biết đây là trạng thái nội tâm; 千 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sám\": 忏 = tâm (忄) + thiên (千) — ngàn lần ăn năn trong lòng, sám hối tội lỗi. | Gương Hán-Việt | sám hối (忏悔) — ăn năn, hối lỗi | Mở khoá kiến thức | Biết 忏 mở khoá 忏悔 (chàn huǐ — sám hối) và 忏罪 (ăn năn tội lỗi).", "Tự nguyên_Xie": "Theo Wiktionary, 忏 là chữ hình thanh: 心 (tâm) biểu nghĩa, 千 (thiên) biểu âm. Nghĩa gốc: ăn năn, sám hối — cảm giác hối hận trong lòng về điều đã làm sai. Cũng dùng trong 忏悔 (sám hối) của Phật giáo. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn năn", "Hạng Tần Suất (Jun Da)": "3171.0", "Tần Suất % (Jun Da)": "99.3327373698", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 千", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄千", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "千", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忏", "Unihan_Traditional (Chữ Phồn thể)": "懺", "Pinyin_Xie": "chàn", "Âm Hán Việt_Xie": "sám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ hối để tạo thành động từ sám hối trong ngữ cảnh tôn giáo hoặc đạo đức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拧', '{"9000": "3172.0", "Chữ Trung Quốc": "拧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 宁 | trữ | biểu âm | yên tĩnh (gợi âm níng/nǐng) | 拧 = 扌 (Thủ, biểu nghĩa: tay) + 宁 (Trữ, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động bằng tay; 宁 gợi âm níng/nǐng. Chữ giản thể của 擰.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ninh\": tay (扌) vặn xoắn cho đến khi ninh chặt — 拧 là vắt, xoắn, vặn chặt. | Gương Hán-Việt | 拧 ít dùng trong từ Hán-Việt thuần; âm ninh thấy trong từ điển cổ. | Mở khoá kiến thức | Biết 拧 (ninh) giúp nhận ra hành động vặn, vắt bằng tay — như vắt khăn (拧毛巾) hay vặn nắp.", "Tự nguyên_Xie": "拧 là chữ hình thanh theo cấu trúc: 手/扌 (tay) biểu nghĩa, 宁 biểu âm. Wiktionary ghi nguồn gốc từ góc độ Nôm (Vi-Nom form), không phân tích từ nguyên Hán đầy đủ. Chữ đa âm: níng (vặn chặt), nǐng (vặn, vắt), nìng (sai, cứng đầu). Nghĩa gốc: dùng tay vặn xoắn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vắt, treo lên; sai lầm", "Hạng Tần Suất (Jun Da)": "3172.0", "Tần Suất % (Jun Da)": "99.3335275343", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拧", "Unihan_Traditional (Chữ Phồn thể)": "擰", "Pinyin_Xie": "níng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Làm động từ chỉ hành động vặn, xoắn vật thể hoặc làm tính từ chỉ tính cách bướng bỉnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | nǐng | / | vắt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亥', '{"9000": "3173.0", "Chữ Trung Quốc": "亥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 6 | nét | 亥 | hợi | tượng hình | chi Hợi, hình vẽ cổ không rõ — gốc từ hình con vật hoặc rễ cây | 亥 là chữ tượng hình cổ — hình dạng gốc không hoàn toàn rõ ràng. Một số học giả đề xuất mô tả rễ cây dưới đất; số khác cho là hình con thú gần với 豕 (lợn). Là chi thứ 12 trong thập nhị địa chi, ứng với con lợn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hợi\": 亥 là chi Hợi — con lợn trong thập nhị địa chi. Giờ Hợi là 21-23 giờ đêm, lúc lợn ngủ ngon. | Gương Hán-Việt | Hợi (亥) — chi thứ 12, ứng với lợn trong thập nhị địa chi | Mở khoá kiến thức | Biết 亥 mở khoá 亥时 (giờ Hợi — 21-23h), 壬亥 (Nhâm Hợi), 甲子亥 trong hệ can chi.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 亥 là chữ tượng hình (liushu: p). Hình dạng gốc không chắc chắn: có thể là hình rễ cây dưới đất (dạng gốc của 荄), hoặc hình con vật tương tự 豕 (lợn). Dùng làm chi thứ 12 trong thập nhị địa chi, ứng với giờ Hợi (21-23h) và năm Hợi (lợn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "986.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Là hình vẽ mô phỏng một con lợn (heo) được vẽ đứng. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Hợi là con lợn. Hợi cũng được dùng để chỉ tên địa chi (chi Hợi, giờ Hợi).", "Nghĩa Tiếng Việt_Xie": "Hợi (ngôi thứ 12 hàng Chi)", "Hạng Tần Suất (Jun Da)": "3173.0", "Tần Suất % (Jun Da)": "99.334317182", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 人", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴人", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亥", "Unihan_Traditional (Chữ Phồn thể)": "亥", "Pinyin_Xie": "hài", "Âm Hán Việt_Xie": "hợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ địa chi thứ mười hai, thường dùng trong cách tính thời gian cổ hoặc tuổi tác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佟', '{"9000": "3174.0", "Chữ Trung Quốc": "佟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | nhân | biểu nghĩa | người | 冬 | đông | biểu âm | mùa đông | 佟 = 亻 (Nhân, biểu nghĩa: người) + 冬 (Đông, biểu âm). Chữ hình thanh — 亻 cho biết đây là họ người; 冬 cho âm đọc. Chữ chủ yếu dùng làm họ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": 佟 = người (亻) + đông (冬) — họ người phương Bắc, vùng giá lạnh mùa đông. | Gương Hán-Việt | Đồng (佟) — họ Đồng, họ tộc Mãn Châu | Mở khoá kiến thức | Biết 佟 mở khoá họ tộc Mãn Châu như 佟佳氏 (Đồng Giai thị) trong lịch sử nhà Thanh.", "Tự nguyên_Xie": "Theo Wiktionary, 佟 là chữ hình thanh: 人 (nhân, người) biểu nghĩa, 冬 (đông) biểu âm. Chữ này chủ yếu dùng làm họ người — họ Đồng (Tóng) — một họ tộc thiểu số ở Đông Bắc Trung Quốc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Đồng", "Hạng Tần Suất (Jun Da)": "3174.0", "Tần Suất % (Jun Da)": "99.3351068297", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 冬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻冬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佟", "Unihan_Traditional (Chữ Phồn thể)": "佟", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng để chỉ họ của người Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叱', '{"9000": "3175.0", "Chữ Trung Quốc": "叱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 𠤎 | biểu âm | dạng cổ của 七 | 叱 = 口 (Khẩu, biểu nghĩa: miệng) + 七 (biểu âm, dạng cổ). Chữ hình thanh — 口 cho biết đây là hành động dùng miệng; 七/𠤎 cho âm đọc. Nghĩa gốc: quát tháo, mắng mỏ to tiếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sất\": 叱 = miệng (口) + bảy (七) — quát lên bảy tiếng liền, la hét không ngừng. | Gương Hán-Việt | sất (叱) — trong 叱咤 (sất tra — quát tháo uy phong) | Mở khoá kiến thức | Biết 叱 mở khoá 叱咤风云 (chì zhà fēng yún — uy phong lẫm liệt, hô phong hoán vũ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 叱 là chữ hình thanh: 口 (khẩu, miệng) biểu nghĩa, 七 (dạng cổ 𠤎) biểu âm. Nghĩa gốc: quát, hét, mắng to — âm thanh phát ra mạnh từ miệng để la rầy hoặc chỉ huy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quát, thét", "Hạng Tần Suất (Jun Da)": "3175.0", "Tần Suất % (Jun Da)": "99.3358964774", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 匕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口匕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叱", "Unihan_Traditional (Chữ Phồn thể)": "叱", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ hoặc kết hợp thành từ ghép như sất trách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舜', '{"9000": "3176.0", "Chữ Trung Quốc": "舜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舛 | Số nét | 12 | nét | 舜 | thuấn | tượng hình | vua Thuấn, hình vẽ phức tạp gồm爫冖舛 | 舜 là chữ cổ phức tạp — bao gồm 爫 (爪, bàn tay), 冖 (che phủ) và 舛 (hai bàn chân ngược chiều). Cấu trúc tượng hình tổng hợp không rõ ràng; dùng chủ yếu làm tên vua Thuấn, một trong ngũ đế thời tiền sử Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuấn\": 舜 là tên vua Thuấn — vị minh quân thời thượng cổ, kế vị vua Nghiêu theo truyền thuyết Trung Hoa. | Gương Hán-Việt | Nghiêu Thuấn (尧舜) — hai vua thánh hiền thời thượng cổ | Mở khoá kiến thức | Biết 舜 mở khoá 尧舜 (Nghiêu Thuấn — hai thánh vương), 舜帝 (vua Thuấn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 舜 không có giải thích cấu trúc rõ ràng. Chữ phức tạp gồm 爫 + 冖 + 舛. Dùng làm tên vua Thuấn (shùn) — một trong ngũ đế thời thượng cổ, người kế vị vua Nghiêu, nổi tiếng về đức hạnh và trị nước. Cũng chỉ loại hoa 木槿 (mộc cẩn). chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vua Thuấn (đời nhà Ngu)", "Hạng Tần Suất (Jun Da)": "3176.0", "Tần Suất % (Jun Da)": "99.3366856083", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "舜", "Unihan_Traditional (Chữ Phồn thể)": "舜", "Pinyin_Xie": "shùn", "Âm Hán Việt_Xie": "thuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu dùng làm danh từ riêng chỉ vua Thuấn hoặc dùng trong tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绊', '{"9000": "3177.0", "Chữ Trung Quốc": "绊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 8 | nét | 纟 | mịch | biểu nghĩa | sợi tơ, dây | 半 | bán | biểu âm | nửa | 绊 = 纟 (Mịch, biểu nghĩa: sợi dây, tơ) + 半 (Bán, biểu âm). Chữ hình thanh — 纟 cho biết đây là thứ dây cột, ràng buộc; 半 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bán\": 绊 = dây (纟) + bán (半) — dây buộc chân khiến chỉ đi được nửa bước, vấp ngã. | Gương Hán-Việt | bán (绊) — trong 绊倒 (bán đảo — vấp ngã) | Mở khoá kiến thức | Biết 绊 mở khoá 绊倒 (bàn dǎo — vấp ngã) và 羁绊 (羁绊 — ràng buộc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 绊 là chữ hình thanh: 糸 (mịch, sợi dây) biểu nghĩa, 半 (bán) biểu âm. Nghĩa gốc: dây cùm chân; ràng buộc bằng dây. Mở rộng: vướng chân, vấp phải; chướng ngại vật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cùm lại, giữ lại; vướng, vấp; vật cản trở, chướng ngại vật", "Hạng Tần Suất (Jun Da)": "3177.0", "Tần Suất % (Jun Da)": "99.3374737056", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绊", "Unihan_Traditional (Chữ Phồn thể)": "絆", "Pinyin_Xie": "bàn", "Âm Hán Việt_Xie": "bán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ biểu thị sự vướng víu, cản trở hoặc làm danh từ chỉ sự ràng buộc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龚', '{"9000": "3178.0", "Chữ Trung Quốc": "龚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 龍 | Số nét | 11 | nét | 龙 | long | biểu nghĩa | rồng | 共 | cộng | biểu âm | cùng nhau | 龚 = 龙 (Long, gợi ý danh tiếng cao quý) + 共 (Cộng, biểu âm). Chữ hình thanh — cấu trúc gợi ý người họ Cung gắn với hình tượng rồng; 共 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cung\": 龚 = rồng (龙) + cộng (共) — họ Cung, mang trong mình tinh thần rồng cùng mọi người. | Gương Hán-Việt | Cung (龚) — họ Cung, một họ Trung Quốc | Mở khoá kiến thức | Biết 龚 mở khoá họ Cung (龚姓) trong lịch sử và văn học Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary không có giải thích cấu trúc rõ ràng cho 龚. Dựa vào thành phần: 龙 (long, rồng) + 共 (cộng). Chủ yếu dùng làm họ người — họ Cung (Gōng). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn cổ điển. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Cung", "Hạng Tần Suất (Jun Da)": "3178.0", "Tần Suất % (Jun Da)": "99.3382618029", "GavinGrover_Once (Chiết tự trực tiếp)": "龙 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龙共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "龙", "Unihan_Simplified (Chữ Giản thể)": "龚", "Unihan_Traditional (Chữ Phồn thể)": "龔", "Pinyin_Xie": "gōng", "Âm Hán Việt_Xie": "cung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Trong tiếng Trung hiện đại, chữ này chủ yếu dùng làm danh từ chỉ họ người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腮', '{"9000": "3179.0", "Chữ Trung Quốc": "腮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 13 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục) | 思 | tư | biểu âm | suy nghĩ, nhớ | 腮 = 月 (Bộ nhục 肉, biểu nghĩa: thịt, phần cơ thể) + 思 (Tư, biểu âm). Chữ hình thanh — 月 (bộ nhục) cho biết đây là bộ phận cơ thể; 思 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": 腮 = thịt (月) + tư (思) — má phình ra khi ngậm thứ gì, trông như đang suy tư phồng má. | Gương Hán-Việt | tư (腮) — trong 腮帮子 (tư bàng tử — má, gò má) | Mở khoá kiến thức | Biết 腮 mở khoá 腮帮子 (sāi bāng zi — má, gò má) và 鱼腮 (mang cá).", "Tự nguyên_Xie": "Wiktionary không có giải thích cấu trúc rõ ràng cho 腮. Dựa vào thành phần: 肉 (nhục, thịt/cơ thể) + 思 (tư) là chữ hình thanh. Nghĩa gốc: phần dưới má — vùng thịt hai bên hàm. Cũng dùng chỉ mang cá (鱼腮). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phần dưới má", "Hạng Tần Suất (Jun Da)": "3179.0", "Tần Suất % (Jun Da)": "99.3390483499", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腮", "Unihan_Traditional (Chữ Phồn thể)": "腮", "Pinyin_Xie": "sāi", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận má trên mặt người hoặc mang của loài cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | sāi | / | má | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Cơ thể và ngoại hình II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邸', '{"9000": "3180.0", "Chữ Trung Quốc": "邸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 氐 | đê | biểu âm | tộc Đê, gốc, nền | 阝 | ấp | biểu nghĩa | làng xã, đất đai | 邸 = 氐 (Đê, biểu âm) + 阝 (Ấp, biểu nghĩa: đất đai, làng xóm). Chữ hình thanh — 阝 (bộ ấp bên phải) cho biết đây là địa danh hay nơi chốn; 氐 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"để\": 邸 = ấp (阝) + đê (氐) — dinh thự tọa lạc trong đất làng, nơi quan lại dừng chân hay ở. | Gương Hán-Việt | để (邸) — trong 官邸 (quan để — dinh thự, tư dinh quan chức) | Mở khoá kiến thức | Biết 邸 mở khoá 官邸 (guān dǐ — dinh thự quan chức) và 邸报 (để báo — công báo triều đình cổ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 邸 là chữ hình thanh: 邑 (ấp, làng xóm) biểu nghĩa, 氐 (đê) biểu âm. Nghĩa gốc: nhà trọ nơi sứ thần chư hầu ở khi về triều kiến. Mở rộng: dinh thự của quan lại, nhà quan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà cho sứ các nước chư hầu đến chầu ở; bức bình phong", "Hạng Tần Suất (Jun Da)": "3180.0", "Tần Suất % (Jun Da)": "99.3398343801", "GavinGrover_Once (Chiết tự trực tiếp)": "氐 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氐阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邸", "Unihan_Traditional (Chữ Phồn thể)": "邸", "Pinyin_Xie": "dǐ", "Âm Hán Việt_Xie": "để", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên người hoặc chức danh để chỉ dinh thự, nơi ở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椒', '{"9000": "3181.0", "Chữ Trung Quốc": "椒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 叔 | thúc | biểu âm | chú (vai vế); cho âm ''jiāo'' | 椒 là chữ hình thanh (suy luận từ cấu trúc, lsCodes không có trong nguồn): 木 (mộc, cây) biểu nghĩa — chỉ loài thực vật; 叔 (thúc) biểu âm cho âm ''jiāo''. Chữ chỉ cây hoa tiêu (tiêu Tứ Xuyên), sau mở rộng chỉ các loại gia vị tương tự như ớt, hồ tiêu. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn — chỉ lưu dạng Lục thư thông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": cây (木) có vị cay nồng — 椒 là tổng gọi các loại gia vị cay: hoa tiêu, ớt (辣椒), hồ tiêu (胡椒). | Gương Hán-Việt | tiêu trong ''hồ tiêu'' (胡椒), ''ớt'' (辣椒); ít dùng độc lập | Mở khoá kiến thức | Biết 椒 (Tiêu) mở khoá: ớt (辣椒), hồ tiêu (胡椒), hoa tiêu (花椒), ớt xanh (青椒).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary cung cấp phát âm và định nghĩa chi tiết cho 椒 nhưng không có glyph origin rõ ràng. Cấu trúc: 木 (cây) + 叔 (biểu âm). Chỉ lưu dấu trong Lục thư thông (chữ tạo muộn thời Minh, chưa thấy trong giáp cốt/kim văn). Nghĩa gốc: cây hoa tiêu (花椒, Sichuan pepper); mở rộng sang ớt (辣椒), hồ tiêu (胡椒). Chưa có nguồn học thuật xác nhận glyph origin. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt tiêu, hồ tiêu", "Hạng Tần Suất (Jun Da)": "3181.0", "Tần Suất % (Jun Da)": "99.3406188599", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 叔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木叔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椒", "Unihan_Traditional (Chữ Phồn thể)": "椒", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loại gia vị có vị cay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔚', '{"9000": "3182.0", "Chữ Trung Quốc": "蔚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 尉 | uý | biểu âm | quan võ (gợi âm wèi) | 蔚 = 艹 (Thảo, biểu nghĩa: cỏ cây) + 尉 (Uý, biểu âm); chữ hình thanh. Bộ thảo chỉ thực vật xanh tươi; 尉 gợi âm wèi. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uất\": cỏ (艹) xanh uất (尉 gợi âm) — 蔚 là rậm rạp, xanh tốt, phong phú. | Gương Hán-Việt | 蔚 xuất hiện trong 蔚蓝 (uất lam = màu xanh biển) và 蔚然成风 (trở thành phong trào rộng rãi). | Mở khoá kiến thức | Biết 蔚 (uất) giúp đọc 蔚蓝 (xanh biển, azure) và thành ngữ 蔚然成风 (trở nên phổ biến, thành phong trào).", "Tự nguyên_Xie": "Tiểu triện | 蔚 là chữ hình thanh: 艸/艹 (cỏ, thực vật) biểu nghĩa, 尉 biểu âm. Wiktionary xác nhận: {{Han compound|艸|尉|ls=psc|c1=s|c2=p|t1=grass}}. Nghĩa gốc: một loại cỏ xanh tốt; từ đó mở rộng sang nghĩa xanh tươi, rậm rạp, hưng thịnh (蔚然成风 = phong trào nở rộ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ uý; xanh tốt; hưng thịnh; màu sẫm", "Hạng Tần Suất (Jun Da)": "3182.0", "Tần Suất % (Jun Da)": "99.3414033397", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 尉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹尉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔚", "Unihan_Traditional (Chữ Phồn thể)": "蔚", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "uý, uất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm danh từ chỉ một loại cỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湛', '{"9000": "3183.0", "Chữ Trung Quốc": "湛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thủy | biểu nghĩa | nước | 甚 | thậm | biểu âm | rất, vô cùng | 湛 = 氵 (Thủy, biểu nghĩa: nước) + 甚 (Thậm, biểu âm). Chữ hình thanh — 氵 cho biết liên quan đến nước; 甚 cho âm đọc. Nghĩa gốc: nước sâu, trong vắt, tĩnh lặng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trạm\": 湛 = nước (氵) + thậm (甚) — nước vô cùng sâu và trong, tĩnh lặng như tâm hồn uyên thâm. | Gương Hán-Việt | trạm (湛) — trong 精湛 (tinh trạm — tinh thông, điêu luyện) | Mở khoá kiến thức | Biết 湛 mở khoá 精湛 (jīng zhàn — tinh thông, tuyệt vời) và 湛蓝 (xanh biếc, trong vắt).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary, 湛 là chữ hình thanh: 水 (thủy, nước) biểu nghĩa, 甚 (thậm) biểu âm. Nghĩa gốc: nước sâu và trong; tĩnh, trong sáng. Mở rộng: tinh thông, uyên thâm (湛深). Cũng là họ người. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu; trong, sạch", "Hạng Tần Suất (Jun Da)": "3183.0", "Tần Suất % (Jun Da)": "99.3421857524", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 甚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵甚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湛", "Unihan_Traditional (Chữ Phồn thể)": "湛", "Pinyin_Xie": "zhàn", "Âm Hán Việt_Xie": "trạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả trạng thái trong xanh của nước hoặc sự tinh thâm của kỹ nghệ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狩', '{"9000": "3184.0", "Chữ Trung Quốc": "狩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 9 | nét | 犭 | khuyển | biểu nghĩa | chó, thú vật | 守 | thủ | biểu âm | giữ gìn, bảo vệ | 狩 = 犭 (Khuyển, biểu nghĩa: chó/thú) + 守 (Thủ, biểu âm). Chữ hình thanh — 犭 gợi cảnh săn bắt thú vật; 守 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thú\": 狩 = chó (犭) + thủ (守) — đoàn thú vật được giữ lại để săn theo nghi lễ mùa đông. | Gương Hán-Việt | thú (狩) — trong 狩猎 (thú liệp — săn bắt) | Mở khoá kiến thức | Biết 狩 mở khoá 狩猎 (shòu liè — săn bắt, săn thú) và 围猎/狩猎季节 (mùa săn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 狩 là chữ hình thanh: 犬 (khuyển, chó) biểu nghĩa, 守 (thủ) biểu âm. Nghĩa gốc: lễ đi săn vào mùa đông — cuộc săn bắt theo nghi lễ của vua chúa phong kiến thực hiện vào cuối năm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ đi săn vào mùa đông", "Hạng Tần Suất (Jun Da)": "3184.0", "Tần Suất % (Jun Da)": "99.3429681651", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 守", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭守", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "守", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狩", "Unihan_Traditional (Chữ Phồn thể)": "狩", "Pinyin_Xie": "shòu", "Âm Hán Việt_Xie": "thú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc kết hợp thành từ ghép như tuần thú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眶', '{"9000": "3185.0", "Chữ Trung Quốc": "眶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 匡 | khuông | biểu âm | cái giỏ, khuôn khổ (gợi âm kuàng) | 眶 = 目 (Mục, biểu nghĩa: mắt) + 匡 (Khuông, biểu âm); chữ hình thanh. Bộ mục chỉ bộ phận mắt; 匡 gợi âm kuàng. Wiktionary chỉ cung cấp phát âm, không phân tích từ nguyên chi tiết hơn; cấu trúc hình thanh được xác nhận qua IDS ⿰目匡.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuông\": mắt (目) trong cái khuông (匡) — 眶 là hốc mắt, vành mắt bao quanh. | Gương Hán-Việt | 眶 xuất hiện trong 热泪盈眶 (nước mắt đẫm tràn vành mắt) và 眼眶 (hốc mắt). | Mở khoá kiến thức | Biết 眶 (khuông) giúp đọc 眼眶 (hốc mắt) và thành ngữ 热泪盈眶 — diễn tả cảm xúc dâng trào.", "Tự nguyên_Xie": "眶 là chữ hình thanh: 目 (mắt) biểu nghĩa, 匡 biểu âm. Wiktionary không cung cấp phân tích glyph-origin chi tiết (chỉ ghi {{Han etym}}). Nghĩa gốc: hốc mắt, vành mắt — phần xương bao quanh nhãn cầu. Không có hình thức giáp cốt hay kim văn được ghi nhận riêng; chưa có nguồn học thuật cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vành mắt", "Hạng Tần Suất (Jun Da)": "3185.0", "Tần Suất % (Jun Da)": "99.3437490275", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 匡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目匡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眶", "Unihan_Traditional (Chữ Phồn thể)": "眶", "Pinyin_Xie": "kuàng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với nhãn hoặc lệ để chỉ vùng quanh mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栈', '{"9000": "3186.0", "Chữ Trung Quốc": "栈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 戋 | tiên | biểu âm | nhỏ bé | 栈 = 木 (Mộc, biểu nghĩa: gỗ) + 戋 (Tiên, biểu âm). Chữ hình thanh — 木 cho biết đây là công trình gỗ; 戋 cho âm đọc. Nghĩa gốc: kho chứa hàng bằng gỗ; sàn gỗ bắc qua núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sạn\": 栈 = gỗ (木) + tiên (戋) — sàn gỗ nhỏ bắc qua núi, bước trên đó như đi trên giàn sạn. | Gương Hán-Việt | sạn (栈) — trong 栈道 (sạn đạo — đường gỗ trên vách núi) | Mở khoá kiến thức | Biết 栈 mở khoá 栈道 (zhàn dào — đường gỗ qua núi) và 旅栈 (lữ sạn — quán trọ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 栈 là chữ hình thanh: 木 (mộc, gỗ) biểu nghĩa, 戔 (tiên) biểu âm. Nghĩa gốc: kho trữ hàng bằng gỗ; cầu gỗ bắc trên vách núi hiểm trở (栈道). Mở rộng: quán trọ (旅栈), giàn gỗ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà kho; quán trọ", "Hạng Tần Suất (Jun Da)": "3186.0", "Tần Suất % (Jun Da)": "99.3445278227", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 戋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木戋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栈", "Unihan_Traditional (Chữ Phồn thể)": "棧", "Pinyin_Xie": "zhàn", "Âm Hán Việt_Xie": "sạn, xiễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ nơi lưu trú, kho chứa hàng hóa hoặc lối đi hẹp ven núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薇', '{"9000": "3187.0", "Chữ Trung Quốc": "薇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 微 | vi | biểu âm | nhỏ bé, vi | 薇 = 艹 (Thảo, biểu nghĩa: thực vật) + 微 (Vi, biểu âm). Chữ hình thanh — 艹 cho biết đây là loài cây cỏ; 微 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vi\": 薇 = cỏ (艹) + vi (微) — cây vi nhỏ bé nhưng mảnh mai, đẹp như tên người thanh tú. | Gương Hán-Việt | vi (薇) — trong 蔷薇 (tường vi — hoa hồng leo) | Mở khoá kiến thức | Biết 薇 mở khoá 蔷薇 (qiáng wēi — hoa tường vi, hồng leo) và 薇甘菊 (loài cỏ dại xâm lấn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 薇 là chữ hình thanh: 艸 (thảo, cỏ) biểu nghĩa, 微 (vi) biểu âm. Nghĩa gốc: cây rau vi (Osmunda regalis) — loài dương xỉ hoàng gia. Cũng chỉ loài cây hoa hồng leo (薔薇, qiáng wēi). Dùng nhiều làm tên người. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau vi", "Hạng Tần Suất (Jun Da)": "3187.0", "Tần Suất % (Jun Da)": "99.3453050675", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 微", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹微", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "微", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薇", "Unihan_Traditional (Chữ Phồn thể)": "薇", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "vy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ để chỉ các loài thực vật như rau vi hoặc hoa tường vi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肮', '{"9000": "3188.0", "Chữ Trung Quốc": "肮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục) | 亢 | kháng | biểu âm | cao ngạo, vượt mức | 肮 = 月 (Bộ nhục 肉, biểu nghĩa: cơ thể) + 亢 (Kháng, biểu âm). Chữ hình thanh — 月 (bộ nhục) gợi nghĩa bẩn thỉu thể chất; 亢 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàng\": 肮 = thịt (月) + kháng (亢) — thân thể dơ bẩn, ô uế không kháng nổi. | Gương Hán-Việt | hàng (肮) — trong 肮脏 (hàng tạng — dơ bẩn) | Mở khoá kiến thức | Biết 肮 mở khoá 肮脏 (āng zāng — dơ bẩn, nhơ nhuốc) — từ thông dụng trong khẩu ngữ.", "Tự nguyên_Xie": "Wiktionary không có giải thích cấu trúc rõ ràng cho 肮. Dựa vào thành phần: 肉 (nhục) + 亢 (kháng). Thường dùng trong 肮脏 (āng zāng — dơ bẩn, ô uế). Nghĩa gốc có thể liên quan đến thể chất ô nhiễm. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dơ bẩn", "Hạng Tần Suất (Jun Da)": "3188.0", "Tần Suất % (Jun Da)": "99.3460797284", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 亢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月亢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肮", "Unihan_Traditional (Chữ Phồn thể)": "骯", "Pinyin_Xie": "āng", "Âm Hán Việt_Xie": "khang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường kết hợp với chữ khác tạo thành tính từ chỉ sự bẩn thỉu, không sạch sẽ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瀑', '{"9000": "3189.0", "Chữ Trung Quốc": "瀑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 18 | nét | 氵 | thuỷ | biểu nghĩa | nước | 暴 | bạo | biểu âm | dữ dội (gợi âm pù) | 瀑 = 氵 (Thuỷ, biểu nghĩa: nước) + 暴 (Bạo, biểu âm); chữ hình thanh. Bộ thuỷ chỉ nước chảy xiết; 暴 gợi âm pù. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạo\": nước (氵) đổ bạo liệt (暴) — 瀑 là thác nước cuồn cuộn. | Gương Hán-Việt | 瀑 xuất hiện trong 瀑布 (bộc bố = thác nước) — từ phổ biến trong du lịch và địa lý. | Mở khoá kiến thức | Biết 瀑 (bạo/bộc) giúp đọc ngay 瀑布 (thác nước) — từ quan trọng khi nói về thiên nhiên.", "Tự nguyên_Xie": "Tiểu triện | 瀑 là chữ hình thanh: 水/氵 (nước) biểu nghĩa, 暴 biểu âm. Wiktionary xác nhận: {{Han compound|水|alt1=氵|暴|ls=psc|c1=s|t1=water|c2=p}} — waterfall. Phiên bản cổ hơn là 𤄗, sau đó được cách điệu thành 瀑. Nghĩa gốc: thác nước — dòng nước đổ mạnh (bạo) xuống vách đá. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thác nước", "Hạng Tần Suất (Jun Da)": "3189.0", "Tần Suất % (Jun Da)": "99.3468533558", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 暴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵暴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "暴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "瀑", "Unihan_Traditional (Chữ Phồn thể)": "瀑", "Pinyin_Xie": "pù", "Âm Hán Việt_Xie": "bộc, bạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường đứng trước hoặc sau các từ khác để chỉ thác nước chảy mạnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渣', '{"9000": "3190.0", "Chữ Trung Quốc": "渣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước | 查 | tra | biểu âm | kiểm tra (gợi âm zhā) | 渣 = 氵 (Thuỷ, biểu nghĩa: nước) + 查 (Tra, biểu âm); chữ hình thanh. Bộ thuỷ gợi cặn lắng trong chất lỏng; 查 gợi âm zhā. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": nước (氵) tra lọc để lại phần cặn — 渣 là bã, cặn bã còn sót. | Gương Hán-Việt | 渣 ít dùng trong từ Hán-Việt thuần; âm tra thấy trong một số tài liệu cổ. | Mở khoá kiến thức | Biết 渣 (tra) giúp đọc 渣子 (cặn bã), 豆渣 (bã đậu), 矿渣 (xỉ quặng).", "Tự nguyên_Xie": "渣 là chữ hình thanh: 水/氵 (nước) biểu nghĩa, 查 biểu âm. Wiktionary xác nhận: {{Han compound|水|alt1=氵|查|ls=psc|c1=s|c2=p}}. Nghĩa gốc: cặn, bã — phần không tan còn lại sau khi lọc chất lỏng. Từ đó mở rộng sang nghĩa bã bèo, rác rưởi, vô dụng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cặn bã", "Hạng Tần Suất (Jun Da)": "3190.0", "Tần Suất % (Jun Da)": "99.3476259496", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渣", "Unihan_Traditional (Chữ Phồn thể)": "渣", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần chất thải còn lại sau khi đã lọc hoặc ép lấy nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhā | / | bã | / | zhā | / | vụn bánh | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褂', '{"9000": "3191.0", "Chữ Trung Quốc": "褂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衤 | y | biểu nghĩa | áo, quần áo | 卦 | quái | biểu âm | quẻ bói | 褂 = 衤 (Y, biểu nghĩa: quần áo) + 卦 (Quái, biểu âm). Chữ hình thanh — 衤 cho biết đây là loại trang phục; 卦 cho âm đọc. Nghĩa gốc: áo khoác mặc ngoài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quái\": 褂 = áo (衤) + quái (卦) — áo khoác ngoài, kỳ lạ như quẻ bói, phủ lên cả người. | Gương Hán-Việt | quái (褂) — trong 长褂 (trường quái — áo dài khoác ngoài) | Mở khoá kiến thức | Biết 褂 mở khoá 长褂 (cháng guà — áo dài), 马褂 (mǎ guà — áo mã quái kiểu Mãn Thanh).", "Tự nguyên_Xie": "Theo Wiktionary, 褂 là chữ hình thanh: 衣 (y, quần áo) biểu nghĩa, 卦 (quái) biểu âm. Nghĩa gốc: áo ngắn mặc bên ngoài, áo khoác — trang phục truyền thống Trung Quốc mặc phủ lên áo bên trong. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo mặc ngoài", "Hạng Tần Suất (Jun Da)": "3191.0", "Tần Suất % (Jun Da)": "99.3483975098", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 卦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤卦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褂", "Unihan_Traditional (Chữ Phồn thể)": "褂", "Pinyin_Xie": "guà", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại áo mặc khoác bên ngoài thời xưa hoặc áo đơn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叽', '{"9000": "3192.0", "Chữ Trung Quốc": "叽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 几 | cơ | biểu âm | vài, mấy | 叽 = 口 (Khẩu, biểu nghĩa: miệng) + 几 (Cơ, biểu âm). Chữ hình thanh — 口 cho biết đây là âm thanh từ miệng; 几 cho âm đọc. Nghĩa gốc: ăn chút ít; sụt sịt, than thở nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cơ\": 叽 = miệng (口) + cơ (几) — miệng kêu cơ cơ vài tiếng nhỏ, như chim ríu rít. | Gương Hán-Việt | cơ (叽) — trong 叽叽喳喳 (cơ cơ tra tra — ríu rít, lao xao) | Mở khoá kiến thức | Biết 叽 mở khoá 叽叽喳喳 (jī jī zhā zhā — ríu rít, nói ồn ào) và 叽叽 (tiếng chim kêu).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Wiktionary không có giải thích cấu trúc rõ ràng cho 叽. Dựa vào thành phần: 口 (khẩu) + 几 (cơ) là chữ hình thanh. Nghĩa gốc: ăn chút ít, sụt sịt. Trong khẩu ngữ hiện đại thường dùng trong 叽叽喳喳 (tiếng chim hót ríu rít, tiếng người nói ồn ào). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn một chút; than thở, sùi sụt", "Hạng Tần Suất (Jun Da)": "3192.0", "Tần Suất % (Jun Da)": "99.3491685532", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叽", "Unihan_Traditional (Chữ Phồn thể)": "嘰", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "cơ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này thường dùng làm từ tượng thanh mô phỏng tiếng chim kêu hoặc tiếng bàn tán xôn xao. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臀', '{"9000": "3193.0", "Chữ Trung Quốc": "臀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 殿 | điện | biểu âm | cung điện, phía sau | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục) | 臀 = 殿 (Điện, biểu âm) + 月 (Bộ nhục 肉, biểu nghĩa: thịt, bộ phận cơ thể). Chữ hình thanh — 月 (bộ nhục) cho biết đây là bộ phận cơ thể; 殿 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồn\": 臀 = thịt (月) + điện (殿) — phần thịt phía sau như cung điện tọa lạc ở hậu cung. | Gương Hán-Việt | đồn (臀) — trong 臀部 (đồn bộ — phần mông) | Mở khoá kiến thức | Biết 臀 mở khoá 臀部 (tún bù — phần mông) và 翘臀 (mông cong, mông đẹp).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 臀 là chữ hình thanh: 殿 (điện) biểu âm, 肉 (nhục, thịt) biểu nghĩa. Nghĩa gốc: phần mông — bộ phận phía sau hông người. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hông, phần hông; trôn, đáy", "Hạng Tần Suất (Jun Da)": "3193.0", "Tần Suất % (Jun Da)": "99.3499380462", "GavinGrover_Once (Chiết tự trực tiếp)": "殿 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱殿月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "殿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臀", "Unihan_Traditional (Chữ Phồn thể)": "臀", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mông của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妞', '{"9000": "3194.0", "Chữ Trung Quốc": "妞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người phụ nữ, bé gái | 丑 | sửu | biểu âm | chi Sửu, xấu xí | 妞 = 女 (Nữ, biểu nghĩa: bé gái) + 丑 (Sửu, biểu âm). Chữ hình thanh — 女 cho biết đây là từ chỉ bé gái; 丑 cho âm đọc. Nghĩa gốc: bé gái, cô bé — từ khẩu ngữ thân mật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nữu\": 妞 = nữ (女) + sửu (丑) — cô bé dễ thương dù cái tên nghe có vẻ xấu xí (丑), vẫn là bé gái cưng của gia đình. | Gương Hán-Việt | nữu (妞) — từ khẩu ngữ chỉ bé gái thân mật | Mở khoá kiến thức | Biết 妞 mở khoá cách gọi thân mật 小妞 (xiǎo niū — cô bé, bé gái) trong tiếng Trung khẩu ngữ.", "Tự nguyên_Xie": "Wiktionary không có giải thích cấu trúc rõ ràng cho 妞. Dựa vào thành phần: 女 (nữ) + 丑 (sửu) là chữ hình thanh. Nghĩa gốc: bé gái, đứa bé gái — từ khẩu ngữ miền Bắc Trung Quốc dùng thân mật. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngươi; đứa bé gái", "Hạng Tần Suất (Jun Da)": "3194.0", "Tần Suất % (Jun Da)": "99.3507065057", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 丑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女丑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妞", "Unihan_Traditional (Chữ Phồn thể)": "妞", "Pinyin_Xie": "niū", "Âm Hán Việt_Xie": "nữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ khẩu ngữ dùng để gọi hoặc chỉ những bé gái, cô gái trẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巍', '{"9000": "3195.0", "Chữ Trung Quốc": "巍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 20 | nét | 山 | sơn | biểu nghĩa | núi | 魏 | nguỵ | biểu âm | họ Ngụy, nước Ngụy | 巍 = 山 (Sơn, biểu nghĩa: núi) + 魏 (Nguỵ, biểu âm). Chữ hình thanh — 山 cho biết đây liên quan đến núi non, sự hùng vĩ; 魏 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguy\": 巍 = núi (山) + nguỵ (魏) — núi cao nguy nga sừng sững, hùng vĩ như cường quốc Ngụy. | Gương Hán-Việt | nguy (巍) — trong 巍峨 (nguy nga — cao lớn hùng vĩ) | Mở khoá kiến thức | Biết 巍 mở khoá 巍峨 (wēi é — nguy nga, hùng vĩ) và 巍然 (nguy nhiên — sừng sững, vững chắc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không có giải thích cấu trúc rõ ràng cho 巍. Dựa vào thành phần: 山 (sơn, núi) + 魏 (nguỵ) là chữ hình thanh. Nghĩa gốc: cao lớn sừng sững như núi — dùng để mô tả độ hùng vĩ, cao lớn của núi non hoặc công trình. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn sừng sững", "Hạng Tần Suất (Jun Da)": "3195.0", "Tần Suất % (Jun Da)": "99.3514739317", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 魏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山魏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "魏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "巍", "Unihan_Traditional (Chữ Phồn thể)": "巍", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "nguy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ cao lớn, uy nghiêm của núi non hoặc công trình. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唔', '{"9000": "3196.0", "Chữ Trung Quốc": "唔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 吾 | ngô | biểu âm | ta, tôi | 唔 = 口 (Khẩu, biểu nghĩa: miệng) + 吾 (Ngô, biểu âm); cấu trúc hình thanh. Chữ dùng chủ yếu trong tiếng Quảng Đông để chỉ sự phủ định hoặc ngôi thứ nhất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": miệng (口) phát âm giống 吾 (ngô) — chữ miệng nói \"không\" hoặc \"tôi\" theo giọng Quảng Đông. | Gương Hán-Việt | \"Ngô\" ít dùng trong từ Hán-Việt thuần; thường gặp trong tên riêng như 吳 Ngô. | Mở khoá kiến thức | Biết 唔 (ngô) giúp nhận ra âm khẩu ngữ Quảng Đông trong văn học Hoa ngữ.", "Tự nguyên_Xie": "唔 là chữ hình thanh ghép 口 (miệng — biểu nghĩa) với 吾 (Ngô — biểu âm). Chữ tạo muộn, không thấy trong giáp cốt hay kim văn; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng đọc sách ê a; tôi, ta; không", "Hạng Tần Suất (Jun Da)": "3196.0", "Tần Suất % (Jun Da)": "99.3522392905", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唔", "Unihan_Traditional (Chữ Phồn thể)": "唔", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Chữ này thường dùng làm từ tượng thanh biểu thị tiếng lầm bầm hoặc tiếng ừ à đồng ý. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疚', '{"9000": "3197.0", "Chữ Trung Quốc": "疚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疒 | biểu nghĩa | bộ bệnh | 久 | cửu | biểu âm | lâu dài | 疚 gồm bộ 疒 (bộ bệnh — biểu nghĩa) và 久 (Cửu, biểu âm). Cấu trúc hình thanh. Ý nghĩa: bệnh dai dẳng, nỗi đau lâu ngày chuyển sang nghĩa hối hận, xấu hổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cựu\": bộ bệnh (疒) gặp 久 (cửu — lâu) — nỗi đau cũ dai dẳng không dứt, sinh ra cắn rứt lương tâm. | Gương Hán-Việt | \"Cựu\" trong từ Hán-Việt: 內疚 (nội cựu — cắn rứt nội tâm). | Mở khoá kiến thức | Biết 疚 (cựu) mở khoá nhóm từ chỉ cảm giác tội lỗi: 内疚、愧疚.", "Tự nguyên_Xie": "Lục thư thông | 疚 là chữ hình thanh: bộ 疒 (bệnh) kết hợp với 久 (lâu dài) gợi âm. Nghĩa gốc là bệnh mãn tính, về sau mở rộng sang ý nghĩa hối tiếc, cắn rứt lương tâm. Chỉ thấy ở Lục thư thông, chưa có giáp cốt/kim văn rõ ràng. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điều thẹn", "Hạng Tần Suất (Jun Da)": "3197.0", "Tần Suất % (Jun Da)": "99.3530041325", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 久", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒久", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "久", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疚", "Unihan_Traditional (Chữ Phồn thể)": "疚", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cứu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ thể hiện cảm giác áy náy, đau lòng hoặc hối hận trong lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲤', '{"9000": "3198.0", "Chữ Trung Quốc": "鲤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 鱼 | ngư | biểu nghĩa | cá | 里 | lý | biểu âm | làng, dặm | 鲤 = 鱼 (Ngư, biểu nghĩa: cá) + 里 (Lý, biểu âm); chữ hình thanh. Dạng giản thể của 鯉, thay 魚 bằng 鱼.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lý\": cá (鱼/ngư) mang họ Lý (里) — cá chép 鲤 đồng âm với chữ Lý, biểu tượng may mắn. | Gương Hán-Việt | \"Lý\" trong từ Hán-Việt: 鯉魚 (lý ngư — cá chép). | Mở khoá kiến thức | Biết 鲤 (lý) nhận ra họ cá trong từ 鲤鱼, liên hệ với biểu tượng văn hóa vượt vũ môn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鲤 là dạng giản thể của 鯉, ghép 魚/鱼 (cá — biểu nghĩa) với 里 (Lý — biểu âm). Cá chép (鯉魚) là loài cá nước ngọt gắn liền với văn hóa Trung Hoa, biểu tượng của may mắn và thịnh vượng. Truyền thuyết cá chép vượt vũ môn (鯉魚跳龍門) nổi tiếng khắp Đông Á. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá chép", "Hạng Tần Suất (Jun Da)": "3198.0", "Tần Suất % (Jun Da)": "99.3537684577", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 里", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼里", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "里", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲤", "Unihan_Traditional (Chữ Phồn thể)": "鯉", "Pinyin_Xie": "lǐ", "Âm Hán Việt_Xie": "lí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cá chép hoặc dùng trong các tên gọi liên quan đến loài cá này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戎', '{"9000": "3199.0", "Chữ Trung Quốc": "戎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 6 | nét | 戈 | qua | biểu nghĩa | giáo, vũ khí | 𠂇 | biểu nghĩa | tay cầm khiên | 戎 = 戈 (Qua, giáo/vũ khí) + 𠂇 (tay cầm khiên); chữ hội ý. Hai thành phần đều mang nghĩa vũ trang → binh khí, quân sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": giáo (戈/qua) cộng tay cầm khiên — người lính Nhung mang đủ vũ khí chiến trường. | Gương Hán-Việt | \"Nhung\" trong từ Hán-Việt: 戎馬 (nhung mã — ngựa chiến), 戎衣 (nhung y — quân phục). | Mở khoá kiến thức | Biết 戎 (nhung) mở khoá nhóm từ quân sự cổ điển: 戎马、兵戎、从戎.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 戎 là chữ hội ý ghép 甲 (khiên — biểu nghĩa) với 戈 (Qua, giáo/vũ khí — biểu nghĩa), tượng trưng cho trang bị vũ trang. Nghĩa gốc là vũ khí, quân sự; sau mở rộng chỉ các tộc phía Tây Trung Quốc (Tây Nhung). Thấy trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "738.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Qua (537) Thập (007)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thập (số 007 - mười/cái khiên) ở dưới chữ Qua (số 537 - giáo mác). Tay cầm binh khí xông ra trận mạc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Nhung là binh khí, chiến tranh (nhung phục).", "Nghĩa Tiếng Việt_Xie": "đồ binh khí; rợ (chỉ những tộc phía Tây Trung Quốc)", "Hạng Tần Suất (Jun Da)": "3199.0", "Tần Suất % (Jun Da)": "99.3545327829", "GavinGrover_Once (Chiết tự trực tiếp)": "戈 + 𠂇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戈𠂇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戎", "Unihan_Traditional (Chữ Phồn thể)": "戎", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ chỉ quân đội, binh khí hoặc làm tính từ bổ nghĩa cho danh từ liên quan đến quân sự. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肇', '{"9000": "3200.0", "Chữ Trung Quốc": "肇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 14 | nét | 户 | hộ | biểu nghĩa | cửa, nhà | 攵 | biểu nghĩa | bộ phốc, hành động | 聿 | duật | biểu âm | bút lông | 肇 = 肁 (biểu âm, gốc từ 聿) + 攴/攵 (bộ phốc, hành động — biểu nghĩa); chữ hình thanh. Nghĩa: bắt đầu, khởi sự (một hành động).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệu\": bút (聿) cộng hành động (攵) — dùng bút để mở đầu, \"triệu\" nghĩa là khởi xướng. | Gương Hán-Việt | \"Triệu\" trong từ Hán-Việt: 肇事 (triệu sự — gây tai nạn), 肇始 (triệu thủy — bắt đầu). | Mở khoá kiến thức | Biết 肇 (triệu) nhận ra từ pháp lý 肇事逃逸 (gây tai nạn bỏ trốn) trong báo chí Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 肇 là chữ hình thanh: 肁 (biểu âm, gốc từ 聿/bút) kết hợp với 攴 (hành động). Nghĩa gốc là khởi đầu, bắt đầu; cũng dùng với nghĩa gây ra (tai nạn). Thấy trong kim văn, tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt đầu, phát sinh; sửa cho ngay; mưu loạn", "Hạng Tần Suất (Jun Da)": "3200.0", "Tần Suất % (Jun Da)": "99.3552965913", "GavinGrover_Once (Chiết tự trực tiếp)": "𢼄 + 聿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𢼄聿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𢼄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "聿", "Unihan_Simplified (Chữ Giản thể)": "肇", "Unihan_Traditional (Chữ Phồn thể)": "肇", "Pinyin_Xie": "zhào", "Âm Hán Việt_Xie": "triệu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ để chỉ hành vi khơi mào hoặc gây ra sự việc, tai nạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笃', '{"9000": "3201.0", "Chữ Trung Quốc": "笃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 竹 | trúc | biểu nghĩa | tre, bộ trúc | 马 | mã | biểu âm | ngựa | 笃 = 竹 (Trúc, bộ tre — có thuyết coi là biểu nghĩa: gõ trúc vào ngựa) + 马 (Mã, biểu âm); dạng giản thể của 篤. Cấu trúc hình thanh, âm gốc từ 馬/马.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đốc\": tre (竹/trúc) gõ vào ngựa (马/mã) — người cưỡi ngựa đốc thúc không ngừng, tượng trưng sự dốc lòng tận tụy. | Gương Hán-Việt | \"Đốc\" trong từ Hán-Việt: 笃实 (đốc thực — thành thật), 笃信 (đốc tín — tin tưởng vững chắc). | Mở khoá kiến thức | Biết 笃 (đốc) mở khoá nhóm từ chỉ sự chân thành: 笃实、笃信、笃行、笃学.", "Tự nguyên_Xie": "Tiểu triện | 笃 là dạng giản thể của 篤. Theo Wiktionary, 篤 ghép 竹 (tre) với 馬 (ngựa), ban đầu có thể chỉ tiếng vó ngựa đều đặn (âm gõ tre vào ngựa). Về sau nghĩa mở rộng thành chuyên tâm, dốc lòng, trung thành. Chỉ thấy rõ từ tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dốc sức, dốc lòng", "Hạng Tần Suất (Jun Da)": "3201.0", "Tần Suất % (Jun Da)": "99.3560578158", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 马", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "马", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笃", "Unihan_Traditional (Chữ Phồn thể)": "篤", "Pinyin_Xie": "dǔ", "Âm Hán Việt_Xie": "đốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường làm tính từ chỉ sự thành khẩn, sâu sắc hoặc làm phó từ bổ nghĩa cho động từ thể hiện sự dốc lòng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辙', '{"9000": "3202.0", "Chữ Trung Quốc": "辙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 16 | nét | 车 | xa | biểu nghĩa | xe | 育 | dục | biểu âm (rút gọn từ 徹) | phần biểu âm rút gọn | 攵 | phộc | biểu âm (rút gọn từ 徹) | phần biểu âm rút gọn | 辙 = 车 (Xa, biểu nghĩa: xe) + 育+攵 (phần biểu âm rút gọn của 徹); chữ hình thanh. Wiktionary xác nhận: 車 biểu nghĩa, 徹 biểu âm rút gọn (ls=psc). Chữ giản thể của 轍; tiểu triện và lục thư thông đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệt\": xe (车) để lại dấu triệt để — vết bánh xe in sâu vào đất; 辙 là dấu vết, con đường đã đi. | Gương Hán-Việt | 辙 xuất hiện trong 重蹈覆辙 (trùng đạo phúc triệt = lặp lại vết xe đổ) và 没辙 (hết cách). | Mở khoá kiến thức | Biết 辙 (triệt) giúp đọc 重蹈覆辙 (lặp lại sai lầm) và 没辙 (bí, hết cách) — cả hai rất thông dụng.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 辙 là dạng giản thể của 轍. Wiktionary xác nhận 轍 = 車 (xe, biểu nghĩa) + 徹 rút gọn (biểu âm); chữ hình thanh, nghĩa là vết bánh xe trên đất. Từ vết bánh xe, mở rộng sang nghĩa: con đường, phương pháp, vần thơ (trong thơ Trung Hoa). Thành ngữ nổi tiếng: 重蹈覆辙 (lặp lại sai lầm cũ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết bánh xe", "Hạng Tần Suất (Jun Da)": "3202.0", "Tần Suất % (Jun Da)": "99.3568154228", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "辙", "Unihan_Traditional (Chữ Phồn thể)": "轍", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "triệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ hoặc kết hợp với danh từ khác để chỉ vết xe hay phương pháp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娴', '{"9000": "3203.0", "Chữ Trung Quốc": "娴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 闲 | nhàn | biểu âm | nhàn nhã, rảnh rỗi | 娴 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 闲 (Nhàn, biểu âm); chữ hình thanh. Nghĩa: thanh lịch, nền nã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhàn\": người phụ nữ (女/nữ) mang vẻ nhàn nhã (闲/nhàn) — thanh lịch, ung dung tao nhã. | Gương Hán-Việt | \"Nhàn\" trong từ Hán-Việt: 娴熟 (nhàn thục — thành thạo), 娴雅 (nhàn nhã — thanh lịch). | Mở khoá kiến thức | Biết 娴 (nhàn) nhận ra nhóm từ tả phong cách phụ nữ: 娴熟、娴雅、娴静.", "Tự nguyên_Xie": "Tiểu triện | 娴 ghép 女 (người phụ nữ — biểu nghĩa) với 闲 (nhàn nhã — biểu âm). Không có glyph origin Wiktionary chi tiết; cấu tạo rõ ràng từ thành phần. Nghĩa: người phụ nữ thanh lịch, nền nã, thuần thục. Chưa có nguồn học thuật chi tiết; chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nhàn nhã 嫻雅)", "Hạng Tần Suất (Jun Da)": "3203.0", "Tần Suất % (Jun Da)": "99.3575730298", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 闲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女闲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娴", "Unihan_Traditional (Chữ Phồn thể)": "嫺", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "nhàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả sự trang nhã, thành thạo. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阮', '{"9000": "3204.0", "Chữ Trung Quốc": "阮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 6 | nét | 阝 | biểu nghĩa | bộ phụ (đất đai, địa danh) | 元 | nguyên | biểu âm | đầu, gốc | 阮 = 阝 (bộ phụ, biểu nghĩa: địa danh) + 元 (Nguyên, biểu âm); chữ hình thanh. Ban đầu là tên nước cổ, sau thành họ người Việt và Trung Quốc phổ biến.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguyễn\": bộ đất (阝) cộng 元 (nguyên, gốc rễ) — Nguyễn là họ gốc rễ của người Việt, phổ biến nhất cả nước. | Gương Hán-Việt | \"Nguyễn\" trong tiếng Việt: họ Nguyễn chiếm ~40% dân số; 阮朝 (Nguyễn triều — triều Nguyễn). | Mở khoá kiến thức | Biết 阮 (nguyễn) là họ người Việt phổ biến nhất, cũng là tên nhạc cụ dây cổ Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 阮 là chữ hình thanh: bộ 阝 (địa danh) kết hợp với 元 (nguyên — biểu âm). Nguyên là tên một nước nhỏ thời Chu. Thấy trong tiểu triện và Lục thư thông. Trong văn hóa Việt Nam, 阮/Nguyễn là họ phổ biến nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Nguyễn; họ Nguyễn", "Hạng Tần Suất (Jun Da)": "3204.0", "Tần Suất % (Jun Da)": "99.35833012", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 元", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝元", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "元", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阮", "Unihan_Traditional (Chữ Phồn thể)": "阮", "Pinyin_Xie": "ruǎn", "Âm Hán Việt_Xie": "nguyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ họ người hoặc tên một loại nhạc cụ truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('札', '{"9000": "3205.0", "Chữ Trung Quốc": "札", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 5 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 乚 | biểu âm | nét cong (gợi âm) | 札 = 木 (Mộc, biểu nghĩa: gỗ) + 乚 (biểu âm); chữ hình thanh. Nghĩa gốc: mảnh gỗ mỏng để viết (thẻ tre/gỗ thời cổ), sau mở rộng thành công văn, thư từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": gỗ (木/mộc) mỏng như nét cong (乚) — mảnh thẻ gỗ để viết công văn, \"trát\" lệnh của quan. | Gương Hán-Việt | \"Trát\" trong từ Hán-Việt: 公札 (công trát — công văn), 手札 (thủ trát — thư viết tay). | Mở khoá kiến thức | Biết 札 (trát) nhận ra từ 手札 (thư tay), 书札 (thư từ), và thuật ngữ hành chính cổ điển.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 札 là chữ hình thanh: 木 (gỗ — biểu nghĩa) kết hợp với 乙/乚 (biểu âm), tượng trưng cho mảnh gỗ mỏng dùng làm thẻ viết. Thấy trong đại triện và tiểu triện. Từ nghĩa gốc là thẻ gỗ, mở rộng sang công văn, thư tín, thư pháp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thẻ tre để viết; công văn", "Hạng Tần Suất (Jun Da)": "3205.0", "Tần Suất % (Jun Da)": "99.3590872103", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "札", "Unihan_Traditional (Chữ Phồn thể)": "札", "Pinyin_Xie": "zhá", "Âm Hán Việt_Xie": "trát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ hành chính hoặc kết hợp thành từ ghép chỉ thư từ, giấy tờ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懊', '{"9000": "3206.0", "Chữ Trung Quốc": "懊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 忄 | biểu nghĩa | bộ tâm (tình cảm, nội tâm) | 奥 | ảo | biểu âm | sâu kín, uyên thâm | 懊 = 忄 (bộ tâm, biểu nghĩa: tâm trạng) + 奥 (Ảo, biểu âm); chữ hình thanh. Nghĩa: tâm trạng đau đớn sâu kín, hối hận, phiền muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": lòng (忄) chứa điều sâu kín áo nghĩa (奥/ảo) — nỗi hối hận cất sâu trong tâm can. | Gương Hán-Việt | \"Áo\" trong từ Hán-Việt: 懊悔 (áo hối — hối hận), 懊恼 (áo não — phiền muộn). | Mở khoá kiến thức | Biết 懊 (áo) mở khoá nhóm từ cảm xúc tiêu cực: 懊悔、懊恼、懊丧.", "Tự nguyên_Xie": "Theo Wiktionary, 懊 là chữ hình thanh: 忄 (tâm — biểu nghĩa) kết hợp với 奥 (ảo — biểu âm). Nghĩa gốc chỉ cảm giác đau buồn sâu sắc trong lòng, hối hận. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hối hận, tiếc nuối; buồn rầu", "Hạng Tần Suất (Jun Da)": "3206.0", "Tần Suất % (Jun Da)": "99.3598427501", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 奥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄奥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懊", "Unihan_Traditional (Chữ Phồn thể)": "懊", "Pinyin_Xie": "ào", "Âm Hán Việt_Xie": "áo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ biểu thị tâm trạng bực dọc, hối hận hoặc kết hợp thành từ ghép biểu thị cảm xúc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焘', '{"9000": "3207.0", "Chữ Trung Quốc": "焘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 寿 | thọ | biểu âm | trường thọ | 灬 | biểu nghĩa | bộ hỏa (lửa) | 焘 = 壽/寿 (Thọ, biểu âm) + 火/灬 (bộ hỏa, biểu nghĩa: lửa, ánh sáng); chữ hình thanh. Nghĩa: ánh sáng bao phủ khắp nơi, che chắn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đảo\": lửa (灬/hỏa) ấm áp của người trường thọ (寿/thọ) — ánh sáng che chở bao trùm. | Gương Hán-Việt | \"Đảo\" ít gặp; 焘 thường dùng trong tên người: 天焘 (Thiên Đảo — trời che chở). | Mở khoá kiến thức | Biết 焘 (đảo) nhận ra chữ dùng nhiều trong tên người Trung Quốc mang ý nghĩa bảo hộ, che chở.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 焘 là chữ hình thanh: 壽 (thọ — biểu âm) kết hợp với 火/灬 (lửa — biểu nghĩa). Nghĩa gốc chỉ ánh mặt trời chiếu rọi vạn vật, bao trùm khắp nơi. Thấy trong tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "che trùm lên", "Hạng Tần Suất (Jun Da)": "3207.0", "Tần Suất % (Jun Da)": "99.3605977732", "GavinGrover_Once (Chiết tự trực tiếp)": "寿 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱寿灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "焘", "Unihan_Traditional (Chữ Phồn thể)": "燾", "Pinyin_Xie": "dào", "Âm Hán Việt_Xie": "đào, đảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ để chỉ sự che chở, bao bọc của trời đất hoặc vua chúa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恤', '{"9000": "3208.0", "Chữ Trung Quốc": "恤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 忄 | biểu nghĩa | bộ tâm (tình cảm) | 血 | huyết | biểu âm | máu | 恤 = 忄 (bộ tâm, biểu nghĩa: tình cảm) + 血 (Huyết, biểu âm); chữ hình thanh. Nghĩa: xót thương, cứu giúp người khó khăn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuất\": lòng (忄) cảm thương như máu (血/huyết) chảy — xót thương, trợ cấp người hoạn nạn. | Gương Hán-Việt | \"Tuất\" trong từ Hán-Việt: 抚恤 (phủ tuất — tiền trợ cấp tử tuất), 体恤 (thể tuất — thông cảm). | Mở khoá kiến thức | Biết 恤 (tuất) mở khoá từ 抚恤金 (tiền tử tuất) và 体恤 (thông cảm, thể hiện sự quan tâm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 恤 là chữ hình thanh: 忄 (tâm — biểu nghĩa) kết hợp với 血 (huyết/máu — biểu âm). Nghĩa gốc là thương xót, trợ cấp cho người nghèo khó. Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "156.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Huyết (100)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tâm (số 148) và chữ Huyết (số 100) . Con người có tấm lòng yêu thương những người có chung dòng máu. Giải thích sự chuyển ý: Chữ Huyết (máu) chỉ âm, chữ Tâm (lòng) chỉ ý. Lòng (Tâm) đau xót tột cùng như rỉ máu (Huyết) khi thấy cảnh thương tâm, gọi là thương xót (Tuất). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Huyết và chữ Tuất có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Huyết và Tuất).*", "Nghĩa Tiếng Việt_Xie": "thương xót", "Hạng Tần Suất (Jun Da)": "3208.0", "Tần Suất % (Jun Da)": "99.3613517627", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 血", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄血", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "血", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恤", "Unihan_Traditional (Chữ Phồn thể)": "䘏", "Pinyin_Xie": "xù", "Âm Hán Việt_Xie": "tuất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ mang tân ngữ chỉ đối tượng được cứu trợ hoặc làm danh từ trong từ ghép chỉ sự cứu tế. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疹', '{"9000": "3209.0", "Chữ Trung Quốc": "疹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疒 | biểu nghĩa | bộ bệnh | 人 | nhân | biểu nghĩa | người | 彡 | biểu nghĩa | nét vạch (gợi hình nốt ban) | 疹 gồm bộ 疒 (bệnh) là phần biểu nghĩa chính; phần còn lại gợi hình nốt ban nổi lên da. Cấu trúc thiên về tượng hình trong ngữ cảnh bệnh da.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chẩn\": bộ bệnh (疒) với nốt chấm li ti (彡) — các nốt ban \"chẩn\" nổi khắp người khi bị sởi. | Gương Hán-Việt | \"Chẩn\" trong từ Hán-Việt: 麻疹 (ma chẩn — bệnh sởi), 湿疹 (thấp chẩn — chàm da). | Mở khoá kiến thức | Biết 疹 (chẩn) nhận ra nhóm từ bệnh da: 麻疹、湿疹、荨麻疹、水痘疹.", "Tự nguyên_Xie": "Tiểu triện | 疹 thuộc bộ 疒 (bệnh), chỉ các nốt ban, phát ban trên da — đặc trưng của bệnh sởi và các bệnh da liễu. Wiktionary không cung cấp phân tích hình thanh/hội ý chi tiết; cấu tạo rõ ràng từ bộ bệnh. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh lên sởi", "Hạng Tần Suất (Jun Da)": "3209.0", "Tần Suất % (Jun Da)": "99.3621052355", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 㐱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒㐱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㐱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疹", "Unihan_Traditional (Chữ Phồn thể)": "疹", "Pinyin_Xie": "zhěn", "Âm Hán Việt_Xie": "chẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ y học hoặc kết hợp với danh từ khác để chỉ các loại bệnh phát ban. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潇', '{"9000": "3210.0", "Chữ Trung Quốc": "潇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thuỷ | biểu nghĩa | nước | 萧 | tiêu | biểu âm | hoang vắng, tiêu điều (gợi âm xiāo) | 潇 = 氵 (Thuỷ, biểu nghĩa: nước) + 萧 (Tiêu, biểu âm); chữ hình thanh. Bộ thuỷ chỉ nước sâu trong; 萧 gợi âm xiāo. Chữ giản thể của 瀟; tiểu triện đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": nước (氵) chảy tiêu sái (萧) — 潇 gợi vẻ phong lưu, thanh thoát không vướng bận. | Gương Hán-Việt | 潇 xuất hiện trong 潇洒 (tiêu sái = phong lưu, thanh thoát) và 瀟湘 (tên địa danh nổi tiếng). | Mở khoá kiến thức | Biết 潇 (tiêu) giúp đọc 潇洒 (thanh thoát, phong lưu) — từ mô tả phong thái tự nhiên, không câu nệ.", "Tự nguyên_Xie": "Tiểu triện | 潇 là dạng giản thể của 瀟. Wiktionary xác nhận 瀟 = 水 (biểu nghĩa: nước) + 蕭 (biểu âm); chữ hình thanh. Nghĩa gốc: nước sâu và trong — chỉ sông Tiêu (瀟水) ở Hồ Nam. Từ đó phát triển nghĩa: thanh thoát, phóng khoáng (潇洒 = tiêu sái). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Tiêu; mưa lất phất", "Hạng Tần Suất (Jun Da)": "3210.0", "Tần Suất % (Jun Da)": "99.3628581914", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 萧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵萧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "萧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潇", "Unihan_Traditional (Chữ Phồn thể)": "瀟", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả cảnh mưa gió nhẹ nhàng hoặc dùng làm danh từ riêng chỉ sông Tiêu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铝', '{"9000": "3211.0", "Chữ Trung Quốc": "铝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | biểu nghĩa | bộ kim (kim loại) | 吕 | lữ | biểu âm | họ Lữ, nốt nhạc | 铝 = 钅 (bộ kim, biểu nghĩa: kim loại) + 吕 (Lữ, biểu âm); chữ hình thanh. Dạng giản thể của 鋁 — tên kim loại nhôm trong tiếng Trung hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lữ\": kim loại (钅) nhẹ như họ Lữ (吕) — nhôm (铝) là kim loại nhẹ, âm Lữ gợi tên. | Gương Hán-Việt | \"Lữ\" trong từ Hán-Việt: 铝合金 (lữ hợp kim — hợp kim nhôm). | Mở khoá kiến thức | Biết 铝 (lữ) nhận ra tên nguyên tố nhôm trong từ vựng khoa học tiếng Trung.", "Tự nguyên_Xie": "Theo Wiktionary, 铝/鋁 là chữ hình thanh ghép 金/钅 (kim loại — biểu nghĩa) với 呂/吕 (lữ — biểu âm). Ban đầu chỉ thỏi kim loại nhỏ; trong thời hiện đại được dùng chỉ nguyên tố nhôm (Al). Không có hình ảnh giáp cốt/kim văn — chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhôm, Al", "Hạng Tần Suất (Jun Da)": "3211.0", "Tần Suất % (Jun Da)": "99.3636090802", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 吕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅吕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铝", "Unihan_Traditional (Chữ Phồn thể)": "鋁", "Pinyin_Xie": "lǚ", "Âm Hán Việt_Xie": "lữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ kim loại nhôm, thường kết hợp với các danh từ khác để chỉ đồ vật làm bằng nhôm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lǚ | / | nhôm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涤', '{"9000": "3212.0", "Chữ Trung Quốc": "涤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | biểu nghĩa | bộ thủy (nước) | 条 | điều | biểu âm | nhánh, điều khoản | 涤 = 氵 (bộ thủy, biểu nghĩa: nước) + 条 (Điều, biểu âm); chữ hình thanh. Dạng giản thể của 滌. Nghĩa: rửa sạch, gột rửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": nước (氵/thủy) chảy như điều điều (条/điều) — dòng nước gột rửa từng điều bẩn. | Gương Hán-Việt | \"Địch\" trong từ Hán-Việt: 洗涤 (tẩy địch — giặt rửa), 涤荡 (địch đãng — quét sạch). | Mở khoá kiến thức | Biết 涤 (địch) nhận ra từ 洗涤剂 (chất tẩy rửa) và 涤纶 (polyester — vải sợi tổng hợp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 涤/滌 là chữ hình thanh ghép 水/氵 (nước — biểu nghĩa) với 條 (điều — biểu âm). Nghĩa gốc là rửa sạch, gột rửa; nghĩa mở rộng là quét sạch, loại bỏ. Thấy trong tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rửa sạch; quét; cái nhà nuôi các con vật", "Hạng Tần Suất (Jun Da)": "3212.0", "Tần Suất % (Jun Da)": "99.3643594522", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 条", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵条", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "条", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涤", "Unihan_Traditional (Chữ Phồn thể)": "滌", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các âm tiết khác để tạo từ ghép chỉ hoạt động tẩy rửa, làm sạch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恃', '{"9000": "3213.0", "Chữ Trung Quốc": "恃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 忄 | biểu nghĩa | bộ tâm (tâm trạng) | 寺 | tự | biểu âm | chùa, nơi làm việc | 恃 = 忄 (bộ tâm, biểu nghĩa: tâm lý) + 寺 (Tự, biểu âm); chữ hình thanh. Nghĩa: dựa vào, ỷ lại, trông cậy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": lòng (忄) dựa vào chùa (寺/tự) — ỷ lại, trông cậy như người bám vào nơi nương tựa. | Gương Hán-Việt | \"Thị\" trong từ Hán-Việt: 有恃无恐 (hữu thị vô khủng — có chỗ dựa nên không sợ). | Mở khoá kiến thức | Biết 恃 (thị) nhận ra thành ngữ 有恃无恐 và từ 恃强凌弱 (ỷ mạnh hiếp yếu).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 恃 là chữ hình thanh: 忄 (tâm — biểu nghĩa) kết hợp với 寺 (tự — biểu âm). Nghĩa gốc: dựa vào, ỷ lại. Thấy trong kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trông cậy, nhờ cậy", "Hạng Tần Suất (Jun Da)": "3213.0", "Tần Suất % (Jun Da)": "99.3651062067", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 寺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恃", "Unihan_Traditional (Chữ Phồn thể)": "恃", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ phía sau để chỉ việc dựa dẫm vào thế lực hoặc tài năng của bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喽', '{"9000": "3214.0", "Chữ Trung Quốc": "喽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng | 米 | mễ | biểu nghĩa | gạo | 女 | nữ | biểu âm | người phụ nữ | 喽 = 口 (Khẩu, biểu nghĩa: miệng) + 娄 (biểu âm, gốc từ nữ+mễ); chữ hình thanh. Chữ tạo muộn dùng làm trợ từ ngữ khí hoặc chỉ đồ đệ (喽啰).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lâu\": miệng (口) nói ê a \"lâu la\" — chỉ đám tay chân, đồ đệ kẻ xấu (喽啰). | Gương Hán-Việt | \"Lâu\" trong từ Hán-Việt: 喽啰 (lâu la — tay chân, đồ đệ). | Mở khoá kiến thức | Biết 喽 (lâu) nhận ra từ 喽啰 thường xuất hiện trong tiểu thuyết võ hiệp chỉ bộ hạ cấp thấp.", "Tự nguyên_Xie": "喽 thuộc bộ 口 (miệng), dạng giản thể của 嘍. Wiktionary chỉ ghi {{Han etym}} không có phân tích chi tiết. Dùng chủ yếu làm trợ từ ngữ khí cuối câu (口ngữ) hoặc trong từ 喽啰 (lâu la — tay chân, đồ đệ). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lâu la 嘍羅,喽啰)", "Hạng Tần Suất (Jun Da)": "3214.0", "Tần Suất % (Jun Da)": "99.3658529613", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喽", "Unihan_Traditional (Chữ Phồn thể)": "嘍", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Danh từ | 名词 | Chữ này thường đứng cuối câu làm trợ từ ngữ khí hoặc kết hợp thành từ ghép chỉ kẻ dưới quyền. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砌', '{"9000": "3215.0", "Chữ Trung Quốc": "砌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 9 | nét | 石 | thạch | biểu nghĩa | đá | 切 | tiếp | biểu âm | cắt, sát | 砌 = 石 (Thạch, biểu nghĩa: đá) + 切 (biểu âm, âm qiē/qiè); chữ hình thanh. Nghĩa: xây bằng gạch đá, bậc thềm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": đá (石/thạch) cắt gọn (切) — xây thềm bằng đá \"thế\" chắc chắn vững bền. | Gương Hán-Việt | \"Thế\" trong từ Hán-Việt: 砌石 (thế thạch — xây đá), 堆砌 (đôi thế — đắp xây, chất đống). | Mở khoá kiến thức | Biết 砌 (thế) nhận ra 堆砌 (chất đống, viết lách rối rắm) và 砌墙 (xây tường).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 砌 là chữ hình thanh: 石 (đá — biểu nghĩa) kết hợp với 切 (biểu âm). Nghĩa gốc: bậc thềm đá; sau mở rộng thành xây xếp bằng gạch đá. Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thềm; xếp, đặt", "Hạng Tần Suất (Jun Da)": "3215.0", "Tần Suất % (Jun Da)": "99.3665981654", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 切", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石切", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "切", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砌", "Unihan_Traditional (Chữ Phồn thể)": "砌", "Pinyin_Xie": "qì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động xây hoặc lát tường, bậc thềm bằng gạch đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遁', '{"9000": "3216.0", "Chữ Trung Quốc": "遁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 辶 | biểu nghĩa | bộ sước (đi, di chuyển) | 盾 | thuẫn | biểu âm | lá chắn | 遁 = 辶 (bộ sước, biểu nghĩa: đi, di chuyển) + 盾 (Thuẫn, biểu âm); chữ hình thanh. Nghĩa: lẻn trốn, bỏ trốn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độn\": đi (辶) nấp sau khiên (盾/thuẫn) — lẻn trốn như che chắn rồi \"độn\" biến. | Gương Hán-Việt | \"Độn\" trong từ Hán-Việt: 遁走 (độn tẩu — bỏ trốn), 遁世 (độn thế — ở ẩn lánh đời). | Mở khoá kiến thức | Biết 遁 (độn) mở khoá từ 逃遁、遁走 và thành ngữ cổ điển về ẩn sĩ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 遁 là chữ hình thanh: 辵/辶 (đi — biểu nghĩa) kết hợp với 盾 (thuẫn/khiên — biểu âm). Nghĩa gốc: bỏ trốn, lánh nạn, ẩn náu. Thấy trong tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1581.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Xước (162) Thuẫn (1580)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Xước (số 162 - bước đi/ 辶 /chỉ ý) bao quanh chữ Thuẫn (số 1580 - cái mộc/ 盾 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thuẫn chỉ âm, bộ Xước chỉ ý. Độn là chạy trốn, lẩn trốn, lánh đi không để cho ai thấy (độn thổ, tẩu độn).", "Nghĩa Tiếng Việt_Xie": "lẻn trốn đi", "Hạng Tần Suất (Jun Da)": "3216.0", "Tần Suất % (Jun Da)": "99.3673402689", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 盾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶盾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "盾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遁", "Unihan_Traditional (Chữ Phồn thể)": "遁", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động lẩn trốn hoặc rút lui khỏi một nơi nào đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楞', '{"9000": "3217.0", "Chữ Trung Quốc": "楞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 罒 | biểu nghĩa | bốn góc (biến thể 四) | 方 | phương | biểu nghĩa | vuông, phương hướng | 楞 = 木 (Mộc) + 四 (bốn) + 方 (Phương, vuông); chữ hội ý. Theo Wiktionary: \"bốn góc vuông của gỗ\" → cạnh, góc. Chữ xuất hiện muộn, thấy trong lệ thư.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": gỗ (木/mộc) bốn góc vuông (四方) — các cạnh sắc bén, \"lăng\" như góc cạnh cứng đầu. | Gương Hán-Việt | \"Lăng\" ít dùng thuần Hán-Việt; dạng phổ biến là 棱 (lăng — cạnh, góc). | Mở khoá kiến thức | Biết 楞 (lăng) nhận ra nghĩa ngây ngốc (发楞 — đứng ngẩn) và góc cạnh (棱角).", "Tự nguyên_Xie": "Theo Wiktionary, 楞 là chữ hội ý: 四 (bốn) + 方 (vuông) + 木 (gỗ) — \"bốn góc vuông của gỗ\", tức cạnh/góc. Chữ tạo muộn, lần đầu thấy trong lệ thư, chưa có giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "góc, cạnh", "Hạng Tần Suất (Jun Da)": "3217.0", "Tần Suất % (Jun Da)": "99.3680823723", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "楞", "Unihan_Traditional (Chữ Phồn thể)": "楞", "Pinyin_Xie": "léng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm danh từ chỉ góc cạnh hoặc làm tính từ chỉ trạng thái sững sờ, ngây người ra. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阱', '{"9000": "3218.0", "Chữ Trung Quốc": "阱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 6 | nét | 阝 | phụ | biểu nghĩa | gò đất, địa hình cao (bộ phụ bên trái) | 井 | tỉnh | biểu âm | cái giếng (gợi âm jǐng) | 阱 = 阝 (Phụ, biểu nghĩa: địa hình) + 井 (Tỉnh, biểu âm); chữ hình thanh kiêm hội ý. Wiktionary ghi ls=psc và ls2=ic — vừa hình thanh vừa có ý vị hội ý: 阜 (địa hình đất) + 井 (giếng) → hố đào dưới đất như giếng để bẫy thú. Giáp cốt văn và tiểu triện đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉnh\": hố đất (阝) như cái giếng (井) — 阱 là cái bẫy hố hiểm trở. | Gương Hán-Việt | 阱 xuất hiện trong 陷阱 (hãm tỉnh = cái bẫy, bẫy sập). | Mở khoá kiến thức | Biết 阱 (tỉnh) giúp đọc 陷阱 (bẫy, cạm bẫy) — từ dùng cả nghĩa đen lẫn nghĩa bóng.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 阱 là chữ hình thanh kiêm hội ý: 阜/阝 (địa hình) biểu nghĩa, 井 vừa biểu âm vừa gợi ý (giếng = hố sâu). Wiktionary ghi rõ: {{Han compound|阜|井|c1=s|c2=p|alt1=阝|t1=mound|t2=well|ls=psc|ls2=ic}}. Nghĩa gốc: cái bẫy hố — hố đào xuống đất giống giếng để bẫy thú hoặc người. Giáp cốt văn đã ghi lại hình thức sơ khai của chữ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hố làm bẫy", "Hạng Tần Suất (Jun Da)": "3218.0", "Tần Suất % (Jun Da)": "99.3688229254", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 井", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝井", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "井", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阱", "Unihan_Traditional (Chữ Phồn thể)": "穽", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "tỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái bẫy đào dưới đất, thường dùng trong từ ghép để chỉ cạm bẫy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咎', '{"9000": "3219.0", "Chữ Trung Quốc": "咎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 处 | xử | biểu nghĩa | nơi chốn, xử lý | 口 | khẩu | biểu nghĩa | miệng | 咎 ban đầu là hội ý: 夊 (bàn chân) + 人 (người) — người vấp chân, phạm lỗi. Sau thêm 口 (miệng) thành dạng hiện đại. Chữ hội ý chỉ lỗi lầm, tội lỗi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cữu\": người (人) vấp ngã miệng (口) kêu — mắc lỗi rồi bị \"cữu\" trách. | Gương Hán-Việt | \"Cữu\" trong từ Hán-Việt: 咎由自取 (cữu do tự thủ — tự chuốc lấy lỗi). | Mở khoá kiến thức | Biết 咎 (cữu) nhận ra thành ngữ 咎由自取 và từ 归咎 (quy cữu — đổ lỗi).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 咎 ban đầu là chữ hội ý ghép 夊 (bàn chân) với 人 (người), tượng hình người vấp chân — phạm lỗi. Về sau 口 được thêm vào, tạo dạng 咎 hiện đại (hội ý với 各/人+口). Nghĩa: lỗi lầm, tội lỗi, đổ lỗi. Thấy từ kim văn, bạch thư, tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xấu, lỗi", "Hạng Tần Suất (Jun Da)": "3219.0", "Tần Suất % (Jun Da)": "99.369562445", "GavinGrover_Once (Chiết tự trực tiếp)": "处 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱处口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "处", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咎", "Unihan_Traditional (Chữ Phồn thể)": "咎", "Pinyin_Xie": "jiù", "Âm Hán Việt_Xie": "cữu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ sai lầm hoặc làm động từ mang nghĩa quy trách nhiệm, đổ lỗi cho ai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('洼', '{"9000": "3220.0", "Chữ Trung Quốc": "洼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 氵 | biểu nghĩa | bộ thủy (nước) | 土 | thổ | biểu nghĩa | đất | 洼 = 氵 (bộ thủy, biểu nghĩa: nước) + 土 (Thổ, biểu nghĩa: đất); cấu trúc gợi hội ý — chỗ trũng nơi nước đọng trên đất. Không có glyph origin chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": nước (氵) đọng trên đất (土) — chỗ trũng \"oa\" như cái lõm hứng nước. | Gương Hán-Việt | \"Oa\" trong từ Hán-Việt: 水洼 (thủy oa — vũng nước), 洼地 (oa địa — vùng trũng). | Mở khoá kiến thức | Biết 洼 (oa) nhận ra từ 水洼 (vũng nước) và địa danh như 洼地 (vùng đất trũng).", "Tự nguyên_Xie": "Tiểu triện | 洼 gồm bộ 氵 (nước) và 土 (đất), gợi ý vũng nước trên đất trũng. Không có phân tích glyph origin Wiktionary; cấu trúc hội ý về mặt trực quan. Nghĩa: trũng thấp, vũng nước, chỗ lõm. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trũng, lõm, hõm xuống; vũng (nước)", "Hạng Tần Suất (Jun Da)": "3220.0", "Tần Suất % (Jun Da)": "99.3703014477", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "洼", "Unihan_Traditional (Chữ Phồn thể)": "洼", "Pinyin_Xie": "wā", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ địa hình thấp lõm hoặc làm danh từ chỉ vũng nước, đầm lầy. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炳', '{"9000": "3221.0", "Chữ Trung Quốc": "炳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hoả | biểu nghĩa | lửa | 丙 | bính | biểu âm | can thứ ba (thiên can) | 炳 = 火 (Hoả, biểu nghĩa: lửa, ánh sáng) + 丙 (Bính, biểu âm); chữ hình thanh. Nghĩa: sáng chói, lộng lẫy, rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": lửa (火/hoả) sáng như can Bính (丙) — ánh sáng \"bính\" lộng lẫy rực rỡ. | Gương Hán-Việt | \"Bính\" trong từ Hán-Việt: 炳烛 (bính chúc — đốt đuốc sáng), 彪炳 (bưu bính — lẫy lừng, hiển hách). | Mở khoá kiến thức | Biết 炳 (bính) nhận ra thành ngữ 彪炳千古 (hiển hách muôn đời) và từ 炳然 (rõ ràng rực rỡ).", "Tự nguyên_Xie": "Tiểu triện | 炳 là chữ hình thanh: 火 (lửa/ánh sáng — biểu nghĩa) kết hợp với 丙 (thiên can thứ ba — biểu âm). Nghĩa gốc chỉ ánh sáng rực rỡ; chuyển nghĩa thành hiển hách, rõ ràng, lộng lẫy. Wiktionary không cung cấp phân tích chi tiết; thấy từ tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng chói; tỏ rõ", "Hạng Tần Suất (Jun Da)": "3221.0", "Tần Suất % (Jun Da)": "99.3710399337", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 丙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火丙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炳", "Unihan_Traditional (Chữ Phồn thể)": "炳", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bỉnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ bổ nghĩa cho danh từ để miêu tả sự vẻ vang, sáng rõ hoặc nổi bật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噬', '{"9000": "3222.0", "Chữ Trung Quốc": "噬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 口 | khẩu | biểu nghĩa | miệng | 竹 | trúc | biểu nghĩa | tre | 巫 | vu | biểu âm | thầy bùa | 噬 = 口 (Khẩu, biểu nghĩa: miệng) + 筮 (biểu âm, gồm 竹+巫); chữ hình thanh. Nghĩa: cắn, gặm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phệ\": miệng (口) mở to như thầy bùa (巫/vu) hú — \"phệ\" nghĩa là cắn, gặm mạnh. | Gương Hán-Việt | \"Phệ\" trong từ Hán-Việt: 噬脐莫及 (phệ tề mạc cập — hối hận không kịp). | Mở khoá kiến thức | Biết 噬 (phệ) nhận ra thành ngữ 噬脐莫及 (hối hận muộn màng) và từ 反噬 (phản cắn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 噬 là chữ hình thanh: 口 (miệng — biểu nghĩa) kết hợp với 筮 (chiêm bói — biểu âm). Nghĩa gốc: cắn, gặm. Thấy từ tiểu triện và Lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắn", "Hạng Tần Suất (Jun Da)": "3222.0", "Tần Suất % (Jun Da)": "99.3717732518", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 筮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口筮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "筮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噬", "Unihan_Traditional (Chữ Phồn thể)": "噬", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "phệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động cắn hoặc nuốt chửng, thường dùng trong văn viết cổ hoặc từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枫', '{"9000": "3223.0", "Chữ Trung Quốc": "枫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 风 | phong | biểu âm | gió | 枫 = 木 (Mộc, biểu nghĩa: cây) + 风 (Phong, biểu âm); chữ hình thanh. Dạng giản thể của 楓. Nghĩa: cây phong, cây lá đỏ mùa thu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": cây (木/mộc) rung trong gió (风/phong) — lá cây phong đỏ rực bay trong gió thu. | Gương Hán-Việt | \"Phong\" trong từ Hán-Việt: 枫叶 (phong diệp — lá phong), 枫树 (phong thụ — cây phong). | Mở khoá kiến thức | Biết 枫 (phong) nhận ra biểu tượng lá phong đỏ trên quốc kỳ Canada và thơ ca Đường Thi.", "Tự nguyên_Xie": "Tiểu triện | 枫 là dạng giản thể của 楓, ghép 木 (cây — biểu nghĩa) với 風/风 (gió — biểu âm). Cây phong (枫树) nổi tiếng với lá đỏ rực mùa thu. Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây phong", "Hạng Tần Suất (Jun Da)": "3223.0", "Tần Suất % (Jun Da)": "99.3725060531", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 风", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木风", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "风", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枫", "Unihan_Traditional (Chữ Phồn thể)": "楓", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây phong hoặc lá phong, thường kết hợp thành các từ ghép như phong diệp, phong lâm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拷', '{"9000": "3224.0", "Chữ Trung Quốc": "拷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | biểu nghĩa | bộ thủ (tay) | 考 | khảo | biểu âm | tra xét, kiểm tra | 拷 = 扌 (bộ thủ, biểu nghĩa: tay, hành động) + 考 (Khảo, biểu âm); chữ hình thanh. Nghĩa: đánh tra tấn, tra khảo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khảo\": tay (扌) tra khảo (考/khảo) — đánh đòn để hỏi tội, \"khảo\" tra tấn. | Gương Hán-Việt | \"Khảo\" trong từ Hán-Việt: 拷打 (khảo đả — đánh tra tấn), 拷问 (khảo vấn — tra tấn hỏi cung). | Mở khoá kiến thức | Biết 拷 (khảo) nhận ra từ 拷打、严刑拷打 trong văn học lịch sử và tin tức pháp lý.", "Tự nguyên_Xie": "Theo Wiktionary, 拷 là chữ hình thanh thay thế dạng cổ 考: 扌 (tay — biểu nghĩa) kết hợp với 考 (tra xét — biểu âm). Nghĩa: đánh đòn tra tấn, thẩm vấn bằng bạo lực. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh tra khảo, tra tấn", "Hạng Tần Suất (Jun Da)": "3224.0", "Tần Suất % (Jun Da)": "99.3732388544", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 考", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌考", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "考", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拷", "Unihan_Traditional (Chữ Phồn thể)": "拷", "Pinyin_Xie": "kǎo", "Âm Hán Việt_Xie": "khảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tra tấn dã man để lấy khẩu cung, thường dùng trong từ ghép như khảo vấn, khảo đả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哆', '{"9000": "3225.0", "Chữ Trung Quốc": "哆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 多 | đa | biểu âm | nhiều (gợi âm duō) | 哆 = 口 (Khẩu, biểu nghĩa: miệng) + 多 (Đa, biểu âm); chữ hình thanh. Bộ khẩu chỉ miệng run rẩy, tiếng phát ra; 多 gợi âm duō. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đá\": miệng (口) rung lên đa đa — 哆 diễn tả cơ thể run rẩy, lập cập. | Gương Hán-Việt | 哆 ít dùng trong từ Hán-Việt thuần; âm đá/đớ thấy trong từ điển cổ. | Mở khoá kiến thức | Biết 哆 (đá) giúp đọc 哆嗦 (run rẩy) và 打哆嗦 (rùng mình, run vì lạnh hay sợ).", "Tự nguyên_Xie": "Tiểu triện | 哆 là chữ hình thanh: 口 (miệng) biểu nghĩa, 多 biểu âm. Wiktionary chỉ cung cấp phát âm và định nghĩa, không phân tích từ nguyên chi tiết (không có glyphOrigin rõ ràng). Nghĩa chính trong tiếng Trung hiện đại: dùng trong 哆嗦 (run rẩy). Chữ tạo muộn, chưa thấy phân tích giáp cốt/kim văn cụ thể. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "run lẩy bẩy; run lập cập", "Hạng Tần Suất (Jun Da)": "3225.0", "Tần Suất % (Jun Da)": "99.3739711389", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 多", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口多", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "多", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哆", "Unihan_Traditional (Chữ Phồn thể)": "哆", "Pinyin_Xie": "duō", "Âm Hán Việt_Xie": "đa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị trạng thái run rẩy do lạnh hoặc sợ hãi, thường đi kèm trong từ láy như đa sách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矶', '{"9000": "3226.0", "Chữ Trung Quốc": "矶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 7 | nét | 石 | thạch | biểu nghĩa | đá | 几 | cơ | biểu âm | bàn nhỏ, vài | 矶 = 石 (Thạch, biểu nghĩa: đá) + 几 (Cơ, biểu âm); chữ hình thanh. Dạng giản thể của 磯. Nghĩa: bãi đá nhô ra sông/biển, doi đá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ky\": đá (石/thạch) ít ỏi (几/cơ) nhô ra — doi đá \"ky\" lởm chởm bên bờ sông. | Gương Hán-Việt | \"Ky\" ít dùng trong từ Hán-Việt; 矶 chủ yếu xuất hiện trong địa danh như 燕子矶 (Yến Tử Ky). | Mở khoá kiến thức | Biết 矶 (ky) nhận ra địa danh ven sông/biển Trung Quốc như 燕子矶、采石矶.", "Tự nguyên_Xie": "Tiểu triện | 矶 là dạng giản thể của 磯, ghép 石 (đá — biểu nghĩa) với 幾/几 (biểu âm). Nghĩa: bãi đá, doi đá nhô ra mặt nước. Không có glyph origin chi tiết từ Wiktionary; thấy từ tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòn đá ngăn nước", "Hạng Tần Suất (Jun Da)": "3226.0", "Tần Suất % (Jun Da)": "99.3747034235", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "矶", "Unihan_Traditional (Chữ Phồn thể)": "磯", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tảng đá nhô ra ở ven sông hoặc bờ biển để cản sóng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苇', '{"9000": "3227.0", "Chữ Trung Quốc": "苇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 十 | thập | biểu nghĩa | nét thập (bộ thảo) | 丨 | biểu nghĩa | nét thẳng đứng | 韦 | vi | biểu âm | da thuộc | 苇 = 艹 (bộ thảo, biểu nghĩa: cỏ, thực vật) + 韦 (Vi, biểu âm); chữ hình thanh. Dạng giản thể của 葦. Nghĩa: lau sậy, cây sậy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vĩ\": cỏ (艹) rung theo tiếng Vi (韦/vi) — bụi lau sậy \"vĩ\" rào rạt ven sông. | Gương Hán-Việt | \"Vĩ\" trong từ Hán-Việt: 芦苇 (lô vĩ — lau sậy), 苇席 (vĩ tịch — chiếu lau). | Mở khoá kiến thức | Biết 苇 (vĩ) nhận ra từ 芦苇 (lau sậy) trong thơ ca và mô tả thiên nhiên.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 苇 là dạng giản thể của 葦, ghép 艹 (cỏ, thực vật — biểu nghĩa) với 韋/韦 (vi — biểu âm). Nghĩa: cây lau sậy mọc ven nước. Thấy từ tiểu triện và Lục thư thông. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lau sậy", "Hạng Tần Suất (Jun Da)": "3227.0", "Tần Suất % (Jun Da)": "99.3754351912", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 韦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹韦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "韦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苇", "Unihan_Traditional (Chữ Phồn thể)": "葦", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây lau sậy, thường dùng trong các từ ghép như vĩ đường, vĩ tịch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翩', '{"9000": "3228.0", "Chữ Trung Quốc": "翩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 15 | nét | 扁 | thiên | biểu âm | dẹt, biển hiệu | 羽 | vu | biểu nghĩa | lông vũ, đôi cánh | 翩 = 扁 (Thiên, biểu âm) + 羽 (Vu, biểu nghĩa: lông vũ, cánh); chữ hình thanh. Nghĩa: bay lượn nhẹ nhàng, phong lưu tao nhã.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\": cánh (羽/vu) phẩy phiên như biển (扁/thiên) bay — cánh chim lượn \"phiên\" tao nhã. | Gương Hán-Việt | \"Phiên\" trong từ Hán-Việt: 翩翩 (phiên phiên — phong lưu tao nhã), 翩翩起舞 (phiên phiên khởi vũ — múa lượn uyển chuyển). | Mở khoá kiến thức | Biết 翩 (phiên) nhận ra từ 翩翩君子 (chàng trai tao nhã) và 浮想联翩 (suy nghĩ liên miên).", "Tự nguyên_Xie": "Tiểu triện | 翩 là chữ hình thanh: 羽 (lông vũ — biểu nghĩa) kết hợp với 扁 (thiên — biểu âm). Nghĩa: bay lượn uyển chuyển, dáng vẻ phong lưu. Wiktionary không có phân tích chi tiết; thấy từ tiểu triện. | Suy từ bộ phận cấu thành · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hớn hở vui mừng; bóng bẩy, phong lưu văn nhã; bay vùn vụt", "Hạng Tần Suất (Jun Da)": "3228.0", "Tần Suất % (Jun Da)": "99.3761659254", "GavinGrover_Once (Chiết tự trực tiếp)": "扁 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扁羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翩", "Unihan_Traditional (Chữ Phồn thể)": "翩", "Pinyin_Xie": "piān", "Âm Hán Việt_Xie": "phiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả dáng bay lượn nhẹ nhàng hoặc phong thái thanh thoát, thường dùng trong từ ghép như phiên phiên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窒', '{"9000": "3229.0", "Chữ Trung Quốc": "窒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 11 | nét | 穴 | huyệt | biểu nghĩa | hang, lỗ hổng | 至 | chí | biểu âm | đến, cực điểm | 窒 = 穴 (Huyệt, biểu nghĩa: hang hốc, chỗ bít kín) + 至 (Chí, biểu âm); chữ hình thanh. Nghĩa: bít kín, tắc nghẽn, ngột ngạt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trất\": hang (穴/huyệt) bít kín đến tận cùng (至/chí) — không khí \"trất\" tắc, ngột ngạt. | Gương Hán-Việt | \"Trất\" trong từ Hán-Việt: 窒息 (trất tức — ngạt thở), 窒碍 (trất ngại — cản trở). | Mở khoá kiến thức | Biết 窒 (trất) nhận ra từ y tế 窒息 (ngạt thở) và từ 窒碍难行 (cản trở khó đi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 窒 là chữ hình thanh: 穴 (hang, lỗ hổng — biểu nghĩa) kết hợp với 至 (đến — biểu âm). Nghĩa gốc: bít kín, không thể qua được; mở rộng thành ngột ngạt, tắc thở. Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tắc nghẽn, trở ngại", "Hạng Tần Suất (Jun Da)": "3229.0", "Tần Suất % (Jun Da)": "99.3768961428", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 至", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴至", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "至", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窒", "Unihan_Traditional (Chữ Phồn thể)": "窒", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự tắc nghẽn hoặc ngột ngạt không thông, thường kết hợp thành từ ghép như trất tức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侬', '{"9000": "3230.0", "Chữ Trung Quốc": "侬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | biểu nghĩa | bộ nhân (người) | 农 | nông | biểu âm | nông nghiệp, nông dân | 侬 = 亻 (bộ nhân, biểu nghĩa: người) + 农 (Nông, biểu âm); chữ hình thanh. Dạng giản thể của 儂. Nghĩa: tôi, ta (ngôi thứ nhất trong tiếng Ngô/Thượng Hải).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nông\": người (亻) nông dân (农/nông) — \"nông\" là cách người Thượng Hải nói \"tôi\". | Gương Hán-Việt | \"Nông\" trong từ Hán-Việt: 侬 dùng trong thơ cổ và văn học Thượng Hải chỉ \"ta, tôi\". | Mở khoá kiến thức | Biết 侬 (nông) nhận ra đại từ ngôi thứ nhất trong tiếng Ngô và thơ ca Nam Triều.", "Tự nguyên_Xie": "侬 là dạng giản thể của 儂, ghép 亻 (người — biểu nghĩa) với 農/农 (nông — biểu âm). Dùng làm đại từ ngôi thứ nhất hoặc thứ hai trong tiếng Ngô (Thượng Hải, Tô Châu). Chữ tạo muộn; không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(từ khiếm xưng của phụ nữ)", "Hạng Tần Suất (Jun Da)": "3230.0", "Tần Suất % (Jun Da)": "99.3776258434", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 农", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻农", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "农", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侬", "Unihan_Traditional (Chữ Phồn thể)": "儂", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Danh từ | 名词 | Chữ này làm đại từ nhân xưng ngôi thứ nhất hoặc thứ ba trong văn thơ cổ và phương ngôn miền Nam Trung Quốc. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靶', '{"9000": "3231.0", "Chữ Trung Quốc": "靶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 革 | cách | biểu nghĩa | da thuộc | 巴 | ba | biểu âm | dính sát, trông ngóng | 靶 = 革 (Cách, biểu nghĩa: da thuộc) + 巴 (Ba, biểu âm); chữ hình thanh. Nghĩa: bia bắn (làm từ da), mục tiêu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bả\": da (革/cách) ba (巴) màu vòng tròn — tấm bia \"bả\" để nhắm bắn. | Gương Hán-Việt | \"Bả\" trong từ Hán-Việt: 靶子 (bả tử — bia bắn), 射靶 (xạ bả — bắn bia). | Mở khoá kiến thức | Biết 靶 (bả) nhận ra từ 靶子、打靶场 (trường bắn) trong thể thao và quân sự.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 靶 là chữ hình thanh: 革 (da thuộc — biểu nghĩa) kết hợp với 巴 (ba — biểu âm). Nghĩa gốc: dây cương ngựa (làm từ da); sau mở rộng thành bia bắn và mục tiêu. Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương ngựa; cái bia để bắn", "Hạng Tần Suất (Jun Da)": "3231.0", "Tần Suất % (Jun Da)": "99.3783550272", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靶", "Unihan_Traditional (Chữ Phồn thể)": "靶", "Pinyin_Xie": "bǎ", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái bia để tập bắn hoặc mục tiêu nhắm tới, thường dùng trong từ ghép như bả tử, bả trường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胰', '{"9000": "3232.0", "Chữ Trung Quốc": "胰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | bộ nhục (thịt, cơ thể) | 夷 | di | biểu âm | bằng phẳng, man di | 胰 = 月/肉 (bộ nhục, biểu nghĩa: cơ quan cơ thể) + 夷 (Di, biểu âm); chữ hình thanh. Nghĩa: tuyến tụy (cơ quan tiêu hóa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": thịt (月/nhục) bằng phẳng (夷/di) — tuyến tụy \"di\" nằm dẹt sau dạ dày. | Gương Hán-Việt | \"Di\" trong từ Hán-Việt: 胰腺 (di tuyến — tuyến tụy), 胰岛素 (di đảo tố — insulin). | Mở khoá kiến thức | Biết 胰 (di) nhận ra từ y học 胰腺炎 (viêm tụy), 胰岛素 (insulin), 胰腺癌 (ung thư tụy).", "Tự nguyên_Xie": "胰 là chữ hình thanh: 月/肉 (thịt/cơ quan — biểu nghĩa) kết hợp với 夷 (di — biểu âm). Nghĩa chỉ tuyến tụy (pancreas) và trong phương ngữ Quan Thoại/Khách Gia còn có nghĩa là xà phòng. Wiktionary ghi nhận nhưng không có phân tích glyph origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thịt thăn", "Hạng Tần Suất (Jun Da)": "3232.0", "Tần Suất % (Jun Da)": "99.3790842111", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 夷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月夷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胰", "Unihan_Traditional (Chữ Phồn thể)": "胰", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tuyến tụy trong cơ thể động vật hoặc con người, thường dùng trong từ ghép như di tuyến, di đảo tố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芜', '{"9000": "3233.0", "Chữ Trung Quốc": "芜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 十 | thập | biểu nghĩa | bộ thảo (cỏ) | 丨 | biểu nghĩa | nét sổ | 无 | vô | biểu âm | không có | 芜 = 艹 (bộ thảo, biểu nghĩa: cỏ, thực vật) + 无 (Vô, biểu âm); chữ hình thanh. Nghĩa: cỏ dại mọc um tùm, bỏ hoang, tạp nham.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vu\": cỏ (艹) mọc tràn lan không có (无/vô) ai quản — đất \"vu\" bỏ hoang cỏ dại um tùm. | Gương Hán-Việt | \"Vu\" trong từ Hán-Việt: 荒芜 (hoang vu — bỏ hoang), 芜杂 (vu tạp — rối rắm tạp nham). | Mở khoá kiến thức | Biết 芜 (vu) nhận ra từ 荒芜 (bỏ hoang), 芜湖 (Vu Hồ — thành phố An Huy) và 芜杂 (văn phong rối rắm).", "Tự nguyên_Xie": "Tiểu triện | 芜 là chữ hình thanh: 艹 (cỏ — biểu nghĩa) kết hợp với 无 (vô — biểu âm). Nghĩa gốc: ruộng đất bỏ hoang mọc đầy cỏ dại; mở rộng thành lộn xộn, tạp nham (văn phong rối). Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏ hoang; tạp nhạp, lộn xộn", "Hạng Tần Suất (Jun Da)": "3233.0", "Tần Suất % (Jun Da)": "99.3798123613", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 无", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹无", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "无", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芜", "Unihan_Traditional (Chữ Phồn thể)": "蕪", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "vu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả đất đai bỏ hoang cỏ mọc um tùm hoặc văn chương rườm rà, hỗn tạp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辫', '{"9000": "3234.0", "Chữ Trung Quốc": "辫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辛 | Số nét | 17 | nét | 辛 | tân | biểu nghĩa | cay (bộ tân, gợi ý kết nối chắc) | 纟 | mịch | biểu nghĩa | sợi chỉ, tơ lụa | 辛 | tân | biểu nghĩa | cay (lặp lại, kẹp chặt sợi) | 辫 = 辛 + 纟 + 辛 (Tân + Mịch + Tân); chữ hội ý. Hai chữ 辛 kẹp sợi tơ 纟 ở giữa — hình ảnh tết bím: hai tay (辛) kẹp chắc sợi chỉ/tóc (纟) và tết lại. Wiktionary chỉ ghi {{Han etym}} cho phồn thể 辮; cấu trúc được suy từ IDS ⿲辛纟辛. Tiểu triện đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biện\": sợi tơ (纟) bị kẹp biện chứng giữa hai cạnh (辛辛) — 辫 là bím tóc tết chặt. | Gương Hán-Việt | 辫 xuất hiện trong 辫子 (biện tử = bím tóc, đuôi sam). | Mở khoá kiến thức | Biết 辫 (biện) giúp đọc 辫子 (bím tóc) và 发辫 (tóc tết bím) — từ dùng trong mô tả ngoại hình.", "Tự nguyên_Xie": "Tiểu triện | 辫 là dạng giản thể của 辮. Wiktionary chỉ ghi {{Han etym}} cho 辮, không có phân tích chi tiết. Cấu trúc IDS ⿲辛纟辛 cho thấy sợi tơ (纟) được kẹp giữa hai thành phần 辛 — hình tượng của việc tết bím tóc. Tiểu triện đã ghi lại hình dạng chữ. Chưa có nguồn học thuật phân tích đầy đủ từ nguyên. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đan, bện, tết; bím tóc, đuôi sam; túm, bó, mớ; chuôi, cán", "Hạng Tần Suất (Jun Da)": "3234.0", "Tần Suất % (Jun Da)": "99.3805399948", "GavinGrover_Once (Chiết tự trực tiếp)": "辡 + 纟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辡纟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "辫", "Unihan_Traditional (Chữ Phồn thể)": "辮", "Pinyin_Xie": "biàn", "Âm Hán Việt_Xie": "biện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ bím tóc hoặc làm động từ chỉ hành động tết, bện tóc và dây thừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚎', '{"9000": "3235.0", "Chữ Trung Quốc": "嚎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 17 | nét | 口 | khẩu | biểu nghĩa | miệng | 豪 | hào | biểu âm | hào kiệt, lông nhím | 嚎 = 口 (Khẩu, biểu nghĩa: miệng) + 豪 (Hào, biểu âm); chữ hình thanh. Nghĩa: gào khóc, hú to.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": miệng (口) mở hào phóng như hào kiệt (豪/hào) — tiếng gào \"hào\" vang trời. | Gương Hán-Việt | \"Hào\" trong từ Hán-Việt: 嚎哭 (hào khốc — gào khóc), 狼嚎 (lang hào — sói hú). | Mở khoá kiến thức | Biết 嚎 (hào) nhận ra từ 嚎啕大哭 (khóc nức nở) và từ 狼嚎鬼叫 (sói hú ma kêu).", "Tự nguyên_Xie": "Theo Wiktionary, 嚎 là chữ hình thanh: 口 (miệng — biểu nghĩa) kết hợp với 豪 (hào — biểu âm). Nghĩa: khóc to, gào thét, hú. Chữ tạo muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khóc to, gào khóc", "Hạng Tần Suất (Jun Da)": "3235.0", "Tần Suất % (Jun Da)": "99.3812676283", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 豪", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口豪", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豪", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚎", "Unihan_Traditional (Chữ Phồn thể)": "嚎", "Pinyin_Xie": "háo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động khóc lóc thảm thiết hoặc tiếng thú vật hú vang. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妾', '{"9000": "3236.0", "Chữ Trung Quốc": "妾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 8 | nét | 立 | lập | biểu nghĩa | đứng, lập | 女 | nữ | biểu nghĩa | người phụ nữ | 妾 = 立 (Lập) + 女 (Nữ); chữ hội ý theo Wiktionary — có thể là hình tượng người phụ nữ đội mũ hoặc có dấu hiệu phục tùng trên đầu. Nghĩa: vợ lẽ; đại từ khiêm tốn của phụ nữ (tôi — thiếp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiếp\": người nữ (女) đứng hầu (立) — vợ lẽ \"thiếp\" đứng hầu bên chính thất. | Gương Hán-Việt | \"Thiếp\" trong từ Hán-Việt: 妾身 (thiếp thân — tiện thiếp — cách phụ nữ tự xưng khiêm tốn), 妻妾 (thê thiếp — vợ lẽ). | Mở khoá kiến thức | Biết 妾 (thiếp) nhận ra cách xưng hô cổ điển của phụ nữ trong văn học và chế độ hôn nhân cổ Trung Quốc.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 妾 có nguồn gốc không rõ ràng. Có thể là tượng hình người phụ nữ đội mũ (biểu tượng phục tùng), đồng gốc với 女 kết hợp 辛 trên đỉnh; dạng hiện đại 立+女. Thấy từ giáp cốt văn, kim văn, đại triện, tiểu triện. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1798.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tân (117) Nữ (038)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tân viết giảm nét (số 117 - khắc khổ, cay đắng/ 辛) nằm trên bộ Nữ (số 038 - phụ nữ/ 女). (Cách viết cổ là chữ Tân đầy đủ nằm trên chữ Nữ). Giải thích sự chuyển ý: Thiếp vốn chỉ những người phụ nữ mang tội đang phải chịu hình phạt khổ sai (tân 辛 - vị cay đắng, cũng là hình cái dao xăm mặt). Về sau được dùng để chỉ người vợ bé, vợ lẽ, hầu gái (thê thiếp).", "Nghĩa Tiếng Việt_Xie": "vợ lẽ, nàng hầu; (tiếng xưng hô của con gái)", "Hạng Tần Suất (Jun Da)": "3236.0", "Tần Suất % (Jun Da)": "99.3819952617", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 女", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱立女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "女", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "妾", "Unihan_Traditional (Chữ Phồn thể)": "妾", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "thiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Đại từ | 代词 | Làm danh từ chỉ người vợ lẽ hoặc làm đại từ nhân xưng ngôi thứ nhất của phụ nữ thời phong kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幌', '{"9000": "3237.0", "Chữ Trung Quốc": "幌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 13 | nét | 巾 | can | biểu nghĩa | vải, khăn | 晃 | hoảng | biểu âm | lắc lư, lóe sáng | 幌 = 巾 (Can, biểu nghĩa: vải) + 晃 (Hoảng, biểu âm); chữ hình thanh. Nghĩa: tấm màn dũng, biển hiệu bằng vải treo trước cửa hàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoảng\": vải (巾/can) lay hoảng (晃/hoảng) trước gió — tấm màn hiệu \"hoảng\" treo trước cửa hàng. | Gương Hán-Việt | \"Hoảng\" trong từ Hán-Việt: 幌子 (hoảng tử — biển hiệu, chiêu bài), ý nghĩa hay dùng theo nghĩa bóng. | Mở khoá kiến thức | Biết 幌 (hoảng) nhận ra từ 幌子 dùng theo nghĩa bóng: vỏ bọc, chiêu bài giả dối.", "Tự nguyên_Xie": "幌 là chữ hình thanh: 巾 (vải, khăn — biểu nghĩa) kết hợp với 晃 (hoảng — biểu âm). Nghĩa gốc: tấm vải treo trước cửa tiệm làm dấu hiệu (tương tự biển hiệu cổ). Wiktionary không có glyph origin chi tiết; chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái màn dũng", "Hạng Tần Suất (Jun Da)": "3237.0", "Tần Suất % (Jun Da)": "99.3827203113", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 晃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾晃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "晃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幌", "Unihan_Traditional (Chữ Phồn thể)": "幌", "Pinyin_Xie": "huǎng", "Âm Hán Việt_Xie": "hoảng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại màn che hoặc biển hiệu, cờ hiệu treo trước cửa hàng thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踉', '{"9000": "3238.0", "Chữ Trung Quốc": "踉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | nét phụ | 止 | chỉ | biểu nghĩa | bộ túc (chân, đi) | 良 | lương | biểu âm | tốt lành | 踉 = 足/⻊ (bộ túc, biểu nghĩa: chân, đi bộ) + 良 (Lương, biểu âm); chữ hình thanh. Nghĩa: bước đi loạng choạng, khập khiễng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lương\": chân (足) bước không lành (良/lương) — đi \"lương\" loạng choạng khập khiễng. | Gương Hán-Việt | \"Lương\" trong từ Hán-Việt: 踉蹌 (lương sương — đi loạng choạng, khập khiễng). | Mở khoá kiến thức | Biết 踉 (lương) nhận ra từ 踉蹌 chỉ dáng đi loạng choạng trong văn học mô tả.", "Tự nguyên_Xie": "踉 là chữ hình thanh: 足/⻊ (chân — biểu nghĩa) kết hợp với 良 (lương — biểu âm). Nghĩa: bước đi không vững, loạng choạng. Thường thấy trong từ 踉蹌 (lương sương). Wiktionary không có phân tích glyph origin chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân đi loăng quăng", "Hạng Tần Suất (Jun Da)": "3238.0", "Tần Suất % (Jun Da)": "99.3834453608", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踉", "Unihan_Traditional (Chữ Phồn thể)": "踉", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lượng, lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với chữ khác tạo thành từ ghép để tả dáng đi không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佃', '{"9000": "3239.0", "Chữ Trung Quốc": "佃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 亻 | biểu nghĩa | bộ nhân (người) | 田 | điền | biểu âm | ruộng đồng | 佃 = 亻 (bộ nhân, biểu nghĩa: người) + 田 (Điền, biểu âm); chữ hình thanh. Nghĩa: tá điền — người thuê ruộng để canh tác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": người (亻) làm ruộng (田/điền) — tá điền, người thuê \"điền\" canh tác. | Gương Hán-Việt | \"Điền\" trong từ Hán-Việt: 佃农 (điền nông — tá điền), 佃户 (điền hộ — hộ tá điền). | Mở khoá kiến thức | Biết 佃 (điền) nhận ra từ 佃农、佃户 trong lịch sử phong kiến và cải cách ruộng đất.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 佃 là chữ hình thanh: 亻 (người — biểu nghĩa) kết hợp với 田 (ruộng — biểu âm). Nghĩa: tá điền, người thuê đất canh tác. Thấy từ kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm ruộng", "Hạng Tần Suất (Jun Da)": "3239.0", "Tần Suất % (Jun Da)": "99.3841693768", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 田", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻田", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "田", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佃", "Unihan_Traditional (Chữ Phồn thể)": "佃", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ việc thuê ruộng cày cấy hoặc làm danh từ trong từ ghép chỉ người tá điền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葫', '{"9000": "3240.0", "Chữ Trung Quốc": "葫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 十 | thập | biểu nghĩa | bộ thảo (cỏ, thực vật) | 丨 | biểu nghĩa | nét sổ | 胡 | hồ | biểu âm | người nước ngoài, râu | 葫 = 艹 (bộ thảo, biểu nghĩa: thực vật) + 胡 (Hồ, biểu âm); chữ hình thanh. Nghĩa: quả bầu (葫蘆 hồ lô).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồ\": cây (艹) của người Hồ (胡/hồ) — quả bầu \"hồ\" lô từ phương Tây du nhập vào Trung Quốc. | Gương Hán-Việt | \"Hồ\" trong từ Hán-Việt: 葫蘆 (hồ lô — quả bầu), 糖葫芦 (đường hồ lô — kẹo hồ lô). | Mở khoá kiến thức | Biết 葫 (hồ) nhận ra từ 葫蘆 (quả bầu) và 糖葫芦 (kẹo que hồ lô — đặc sản Bắc Kinh).", "Tự nguyên_Xie": "Theo Wiktionary, 葫 là chữ hình thanh: 艹 (thực vật — biểu nghĩa) kết hợp với 胡 (hồ — biểu âm). Nghĩa: cây bầu, quả bầu (葫蘆). Thấy từ tiểu triện. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bầu đựng nước làm từ quả bầu khô", "Hạng Tần Suất (Jun Da)": "3240.0", "Tần Suất % (Jun Da)": "99.3848923592", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 胡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹胡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葫", "Unihan_Traditional (Chữ Phồn thể)": "葫", "Pinyin_Xie": "hú", "Âm Hán Việt_Xie": "hồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ, thường kết hợp với chữ lô thành hồ lô để chỉ quả bầu hoặc bình đựng rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皖', '{"9000": "3241.0", "Chữ Trung Quốc": "皖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 12 | nét | 白 | bạch | biểu nghĩa | trắng, sáng (âm phần) | 完 | hoàn | biểu âm | hoàn toàn (cho âm wǎn/hoãn) | 皖 = 白 (Bạch, biểu nghĩa: sáng rõ) + 完 (Hoàn, biểu âm); chữ hình thanh — 完 cho âm tương tự wǎn, 白 gợi ý nghĩa địa danh sáng rõ. Đây là chữ tạo muộn dùng chỉ tỉnh An Huy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoãn\": 白 (sáng) + 完 (hoàn chỉnh) — vùng đất An Huy sáng rõ và trọn vẹn như ý nghĩa địa danh của nó. | Gương Hán-Việt | 皖 trong 皖南 (Hoãn Nam — miền nam An Huy) | Mở khoá kiến thức | Biết 皖 (hoãn) giúp nhận ra ký hiệu viết tắt tỉnh An Huy trong văn bản địa lý Trung Quốc.", "Tự nguyên_Xie": "皖 là chữ hình thanh: 白 (bạch) biểu nghĩa, 完 (hoàn) biểu âm gần với wǎn. Chữ xuất hiện muộn trong văn tự Hán, chủ yếu dùng làm tên đất (địa danh tỉnh An Huy, Trung Quốc). Chưa có nguồn học thuật chi tiết từ Wiktionary về nguồn gốc cổ tự. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "3241.0", "Tần Suất % (Jun Da)": "99.3856137912", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 完", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白完", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "完", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皖", "Unihan_Traditional (Chữ Phồn thể)": "皖", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ riêng chỉ tỉnh An Huy hoặc làm tính từ mang nghĩa tươi sáng, đẹp đẽ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拽', '{"9000": "3242.0", "Chữ Trung Quốc": "拽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 曳 | duệ | biểu âm | kéo lê (gợi âm zhuāi) | 拽 = 扌 (Thủ, biểu nghĩa: tay) + 曳 (Duệ, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động bằng tay; 曳 gợi âm zhuāi đồng thời mang nghĩa kéo lê — chữ có thể vừa hình thanh vừa hội ý. Wiktionary ghi nhận chữ là dị thể của 曳.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duệ\": tay (扌) kéo duệ lê — 拽 là lôi, kéo mạnh bằng tay. | Gương Hán-Việt | 拽 ít dùng trong từ Hán-Việt thuần; âm duệ thấy trong từ điển cổ. | Mở khoá kiến thức | Biết 拽 (duệ) giúp đọc 拖拽 (kéo lê) và 生拉硬拽 (kéo lôi bằng vũ lực).", "Tự nguyên_Xie": "拽 là chữ hình thanh với bộ 手/扌 (tay) biểu nghĩa và 曳 biểu âm. Wiktionary mô tả 拽 như dị thể của 曳 (kéo lê). Chữ đa âm: zhuāi (ném), zhuài (kéo), zhuǎi (ra vẻ ta đây). Không có hình thức giáp cốt hay kim văn; chữ có thể tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ném; lôi, kéo, túm", "Hạng Tần Suất (Jun Da)": "3242.0", "Tần Suất % (Jun Da)": "99.3863352233", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 曳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌曳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拽", "Unihan_Traditional (Chữ Phồn thể)": "拽", "Pinyin_Xie": "zhuāi", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động dùng lực để kéo, lôi hoặc ném một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhuāi | / | kéo, lôi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III | HSK | HSK 6 | · | Sự chuyển động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滤', '{"9000": "3243.0", "Chữ Trung Quốc": "滤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thuỷ | biểu nghĩa | nước | 虑 | lự | biểu âm | lo lắng (gợi âm lǜ) | 滤 = 氵 (Thuỷ, biểu nghĩa: nước) + 虑 (Lự, biểu âm); chữ hình thanh. Bộ thuỷ chỉ hành động liên quan đến chất lỏng; 虑 gợi âm lǜ. Chữ giản thể của 濾.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lự\": nước (氵) qua bộ lọc suy xét (虑) — 滤 là lọc sạch, loại tạp chất. | Gương Hán-Việt | 滤 xuất hiện trong 过滤 (quá lự = lọc) và 滤纸 (lự chỉ = giấy lọc). | Mở khoá kiến thức | Biết 滤 (lự) giúp đọc 过滤 (lọc, sàng lọc) — dùng cả trong kỹ thuật lẫn nghĩa bóng như lọc thông tin.", "Tự nguyên_Xie": "滤 là dạng giản thể của 濾. Wiktionary xác nhận 濾 = 水 (biểu nghĩa: nước) + 慮 (biểu âm); chữ hình thanh: {{Han compound|水|慮|t1=water|c1=s|c2=p|ls=psc}}. Nghĩa gốc: lọc chất lỏng qua vật liệu để giữ lại cặn — hành động ''suy nghĩ kỹ (慮)'' về dòng chảy của nước. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lọc", "Hạng Tần Suất (Jun Da)": "3243.0", "Tần Suất % (Jun Da)": "99.3870556218", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 虑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵虑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滤", "Unihan_Traditional (Chữ Phồn thể)": "濾", "Pinyin_Xie": "lǜ", "Âm Hán Việt_Xie": "lự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước danh từ chỉ chất lỏng để biểu thị hành động lọc sạch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睬', '{"9000": "3244.0", "Chữ Trung Quốc": "睬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 采 | thái | biểu âm | hái, màu sắc (gợi âm cǎi) | 睬 = 目 (Mục, biểu nghĩa: mắt) + 采 (Thái, biểu âm); chữ hình thanh. Bộ mục chỉ hành động dùng mắt chú ý; 采 gợi âm cǎi. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thải\": mắt (目) hái (采) — dùng mắt chú ý lấy thông tin; 睬 là để ý, đáp lại. | Gương Hán-Việt | 睬 ít dùng trong từ Hán-Việt thuần; thường gặp qua 理睬 (lý thải = để ý, chú ý). | Mở khoá kiến thức | Biết 睬 (thải) giúp đọc 理睬 (để ý, hồi đáp) và 不理不睬 (làm ngơ hoàn toàn).", "Tự nguyên_Xie": "睬 là chữ hình thanh: 目 (mắt) biểu nghĩa, 采 biểu âm. Wiktionary xác nhận: {{Han compound|目|采|ls=psc|c1=s|c2=p|t1=eye}}. Nghĩa gốc: dùng mắt chú ý đến, để ý — thường dùng ở dạng phủ định: 不睬 (không thèm để ý), 不理睬 (bỏ qua). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đáp lại, ngó đến, hỏi qua, ừ hử; hiểu rõ ràng", "Hạng Tần Suất (Jun Da)": "3244.0", "Tần Suất % (Jun Da)": "99.3877749867", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 采", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目采", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "采", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睬", "Unihan_Traditional (Chữ Phồn thể)": "倸", "Pinyin_Xie": "cǎi", "Âm Hán Việt_Xie": "thải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thường dùng trong câu phủ định để biểu thị thái độ thờ ơ, không thèm để ý tới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俞', '{"9000": "3245.0", "Chữ Trung Quốc": "俞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亼 | tập | biểu nghĩa | gom lại, tụ tập | 月 | nguyệt | biểu nghĩa | thịt/cơ thể (月 khi ở dưới) | 刂 | biểu nghĩa | dao (bộ đao) | 俞 trong giáp cốt và kim văn gồm 凡 (phàn, cái mâm) và hình dạng nguyên thủy của 鈴 (linh, cái chuông) — gợi âm thanh đồng thuận. Chữ hội ý: không dùng công thức hình thanh thông thường. Chữ hiện đại 亼+月+刂 là dạng biến thể sau này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": 俞 (du) — âm vang của tiếng chuông 鈴 đáp lại lời, như một lời vâng thuận. | Gương Hán-Việt | 俞 trong 俞允 (du duẫn — phê chuẩn, chấp thuận) | Mở khoá kiến thức | Biết 俞 (du) giúp nhận ra 榆 (du — cây du) và 愉 (du — vui vẻ) cùng họ âm du.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo nghiên cứu của Zhang (2021), 俞 trong giáp cốt và kim văn gồm 凡 (phàn, cái mâm) và hình nguyên thủy của 鈴 (linh, chuông nhỏ) — có thể tượng trưng cho âm thanh đồng ý, tán thành. Chữ không liên quan đến 前 hay 刖 dù hình dạng hiện đại tương tự. Nghĩa gốc: đồng ý, vâng lời; về sau dùng làm họ người. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phải, vâng (lời đáp lại)", "Hạng Tần Suất (Jun Da)": "3245.0", "Tần Suất % (Jun Da)": "99.3884922844", "GavinGrover_Once (Chiết tự trực tiếp)": "亼 + 刖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亼刖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亼", "Unihan_Simplified (Chữ Giản thể)": "俞", "Unihan_Traditional (Chữ Phồn thể)": "俞", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ biểu thị sự đồng ý của bề trên thời xưa hoặc dùng làm họ của người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匕', '{"9000": "3246.0", "Chữ Trung Quốc": "匕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匕 | Số nét | 2 | nét | 匕 | tỷ | tượng hình | cái thìa/muôi — hình vẽ chiếc thìa úp | 匕 là chữ tượng hình độc lập — hình vẽ chiếc thìa hoặc dao găm trong văn tự cổ. Chỉ có 2 nét: 乚 (móc) và 丿 (phẩy), tạo thành hình dáng vật dụng. Không liên quan đến 老 (lão) dù hình dáng tương tự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỷ\": 匕 — hai nét ⺚+丿 phác thảo chiếc thìa cổ xưa, đơn giản mà sắc bén như dao găm. | Gương Hán-Việt | 匕 trong 匕首 (tỷ thủ — dao găm ngắn) | Mở khoá kiến thức | Biết 匕 (tỷ) giúp nhận ra 匙 (thị — thìa), 化 (hóa) đều có bộ 匕 biến thể.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | 匕 là chữ tượng hình (象形): hình vẽ chiếc thìa/muôi từ thời giáp cốt văn. Wiktionary xác nhận đây là chữ thuần tượng hình, không liên quan đến 老 (trong đó hình 匕 biểu thị cây gậy người già), cũng không liên quan đến 眞 (trong đó biểu thị dao) hay 比 (trong đó biểu thị người). Nghĩa gốc: thìa ăn; về sau mở rộng sang dao găm (匕首 — bí thủ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "46.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dáng cái thìa (muỗng) để múc thức ăn.", "Nghĩa Tiếng Việt_Xie": "cái thìa, cái muôi; dao găm", "Hạng Tần Suất (Jun Da)": "3246.0", "Tần Suất % (Jun Da)": "99.3892095822", "GavinGrover_Once (Chiết tự trực tiếp)": "乚 + ㇒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴乚㇒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乚", "Unihan_Simplified (Chữ Giản thể)": "匕", "Unihan_Traditional (Chữ Phồn thể)": "匕", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "chuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ dụng cụ múc thức ăn thời xưa hoặc kết hợp thành từ chỉ dao găm ngắn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谤', '{"9000": "3247.0", "Chữ Trung Quốc": "谤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 12 | nét | 讠 | biểu nghĩa | lời nói (bộ ngôn giản thể) | 旁 | bàng | biểu âm | bên cạnh (gợi âm bàng) | 谤 = 讠 (Ngôn, biểu nghĩa: lời nói) + 旁 (Bàng, biểu âm); chữ hình thanh. Bộ ngôn chỉ lời nói; 旁 gợi âm bàng. Chữ giản thể của 謗; tiểu triện đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"báng\": lời nói (讠) từ kẻ ở bên cạnh (旁) — 谤 là nói xấu sau lưng, vu khống. | Gương Hán-Việt | 谤 xuất hiện trong 诽谤 (phỉ báng = vu khống, bôi nhọ). | Mở khoá kiến thức | Biết 谤 (báng) giúp đọc 诽谤 (vu khống) và 毁谤 (bôi nhọ, hủy hoại danh dự).", "Tự nguyên_Xie": "Tiểu triện | 谤 là dạng giản thể của 謗. Wiktionary xác nhận 謗 = 言 (biểu nghĩa: lời nói) + 旁 (biểu âm); chữ hình thanh: {{Han compound|言|旁|t1=speech; words|c1=s|c2=p|ls=psc}}. Nghĩa gốc cổ: chỉ trích công khai (không nhất thiết xấu xa). Nghĩa hiện đại: vu khống, nói xấu, phỉ báng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói xấu, bêu rếu", "Hạng Tần Suất (Jun Da)": "3247.0", "Tần Suất % (Jun Da)": "99.3899263632", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谤", "Unihan_Traditional (Chữ Phồn thể)": "謗", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "báng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ mang tân ngữ để chỉ hành vi nói xấu người khác hoặc làm danh từ trong từ ghép chỉ lời đồn thổi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗤', '{"9000": "3248.0", "Chữ Trung Quốc": "嗤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng (hành động phát âm, cười) | 蚩 | si | biểu âm | ngu ngốc (cho âm chī/si) | 嗤 = 口 (Khẩu, biểu nghĩa: miệng) + 蚩 (Si, biểu âm); chữ hình thanh. 口 chỉ hành động phát ra tiếng cười nhạo, 蚩 cho âm chī gần với si.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": 口 (miệng) + 蚩 (si, ngốc) — miệng cất tiếng cười nhạo kẻ ngốc. | Gương Hán-Việt | 嗤 trong 嗤笑 (si tiếu — cười nhạo), 嗤之以鼻 (si chi dĩ tỵ — khinh thường) | Mở khoá kiến thức | Biết 嗤 (si) giúp nhớ thành ngữ 嗤之以鼻 — thái độ khinh khi thường gặp trong văn học.", "Tự nguyên_Xie": "嗤 là chữ hình thanh: 口 (khẩu — miệng) biểu nghĩa hành động cười nhạo bằng miệng; 蚩 (si) biểu âm cho chī. Nghĩa: cười nhạo, giễu cợt, khinh thường. Hay gặp trong 嗤之以鼻 (si chi dĩ tỵ — cười khẩy bằng mũi, tức khinh thường). Chưa có ghi chép cổ tự chi tiết. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giễu cợt; cười khúc khích", "Hạng Tần Suất (Jun Da)": "3248.0", "Tần Suất % (Jun Da)": "99.3906431442", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 蚩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口蚩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗤", "Unihan_Traditional (Chữ Phồn thể)": "嗤", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "xuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ hoặc kết hợp trong các từ ghép để biểu thị thái độ cười cợt, khinh miệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捍', '{"9000": "3249.0", "Chữ Trung Quốc": "捍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 旱 | hạn | biểu âm | hạn hán (gợi âm hàn) | 捍 = 扌 (Thủ, biểu nghĩa: tay) + 旱 (Hạn, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động bảo vệ bằng tay; 旱 gợi âm hàn. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãn\": tay (扌) dang ra hãn chặn — 捍 là bảo vệ, ngăn chặn bằng sức mạnh. | Gương Hán-Việt | 捍 xuất hiện trong 捍卫 (hãn vệ = bảo vệ, giữ gìn). | Mở khoá kiến thức | Biết 捍 (hãn) giúp đọc 捍卫 (bảo vệ, bảo vệ) — dùng nhiều trong văn chính trị, quân sự.", "Tự nguyên_Xie": "捍 là chữ hình thanh: 手/扌 (tay) biểu nghĩa, 旱 biểu âm. Wiktionary xác nhận: {{Han compound|手|alt1=扌|旱|ls=psc|c1=s|t1=hand|c2=p}}. Nghĩa gốc: dùng tay ngăn chặn, bảo vệ. Từ đó mở rộng: bảo vệ, giữ gìn (捍卫), kháng cự. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giữ gìn", "Hạng Tần Suất (Jun Da)": "3249.0", "Tần Suất % (Jun Da)": "99.3913588916", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 旱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌旱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捍", "Unihan_Traditional (Chữ Phồn thể)": "扞", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng cần bảo vệ như lãnh thổ, chủ quyền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孵', '{"9000": "3250.0", "Chữ Trung Quốc": "孵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 14 | nét | 卵 | noãn | biểu nghĩa | trứng | 孚 | phu | biểu âm | tin tưởng, ấp ủ (cho âm fū/phu) | 孵 = 卵 (Noãn, biểu nghĩa: trứng) + 孚 (Phu, biểu âm); chữ hình thanh. 卵 chỉ đối tượng là trứng, 孚 cho âm fū gần với phu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": 卵 (trứng) + 孚 (phu, ấp ủ) — con chim ấp trứng, chờ ngày nở. | Gương Hán-Việt | 孵 trong 孵化 (phu hóa — ấp nở, ươm tạo) | Mở khoá kiến thức | Biết 孵 (phu) giúp nhận từ 孵化器 (lò ấp trứng) và ẩn dụ 孵化中心 (trung tâm ươm tạo khởi nghiệp).", "Tự nguyên_Xie": "孵 là chữ hình thanh: 卵 (noãn — trứng) biểu nghĩa hành động dùng với trứng; 孚 (phu) biểu âm cho fū. Nghĩa: ấp trứng (để nở ra). 孵化 (phu hóa) là từ thường gặp chỉ quá trình ấp nở trứng hoặc ươm mầm ý tưởng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1503.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Noãn (1223) Phu (748)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Noãn (số 1223 - trứng/ 卵 /chỉ ý) ở bên trái chữ Phu (số 748 - ấp/tin tưởng/ 孚 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Phu vốn là chim gà ấp trứng (ấp phu, phu hóa).", "Nghĩa Tiếng Việt_Xie": "ấp trứng", "Hạng Tần Suất (Jun Da)": "3250.0", "Tần Suất % (Jun Da)": "99.3920736054", "GavinGrover_Once (Chiết tự trực tiếp)": "卵 + 孚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰卵孚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "卵", "Unihan_Simplified (Chữ Giản thể)": "孵", "Unihan_Traditional (Chữ Phồn thể)": "孵", "Pinyin_Xie": "fū", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ trứng hoặc kết hợp thành từ ghép chỉ quá trình ấp nở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倪', '{"9000": "3251.0", "Chữ Trung Quốc": "倪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 兒 | nhi | biểu âm | đứa trẻ (cho âm ní/nghê) | 倪 = 亻 (Nhân, biểu nghĩa: người) + 兒 (Nhi, biểu âm); chữ hình thanh. 亻 chỉ đây là chữ liên quan đến người, 兒 cho âm ní gần với nghê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghê\": 亻 (người) + 兒 (nhi, trẻ con) — người trẻ, bé nhỏ, ranh giới khởi đầu của đời người. | Gương Hán-Việt | 倪 trong 端倪 (đoan nghê — manh mối, đầu mối) | Mở khoá kiến thức | Biết 倪 (nghê) giúp nhận từ 端倪 (đoan nghê — manh mối) thường gặp trong văn học và báo chí.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 倪 là chữ hình thanh: 亻 (nhân — người) biểu nghĩa, 兒 (nhi — đứa trẻ) biểu âm cho ní. Nghĩa gốc: trẻ nhỏ, bờ cõi; về sau chủ yếu dùng làm họ người (họ Nghê). Trong văn ngôn có nghĩa là ranh giới, phân chia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trẻ con; chia cõi", "Hạng Tần Suất (Jun Da)": "3251.0", "Tần Suất % (Jun Da)": "99.3927867689", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倪", "Unihan_Traditional (Chữ Phồn thể)": "倪", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn ngôn để chỉ trẻ nhỏ, manh mối hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘾', '{"9000": "3252.0", "Chữ Trung Quốc": "瘾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 隐 | ẩn | biểu âm | ẩn nấp (gợi âm yǐn) | 瘾 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 隐 (Ẩn, biểu âm); chữ hình thanh. Bộ nạch chỉ trạng thái bệnh lý; 隐 gợi âm yǐn. Chữ giản thể của 癮.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ẩn\": bệnh (疒) ẩn (隐) sâu bên trong — 瘾 là nghiện, sự thèm khát không dứt được. | Gương Hán-Việt | 瘾 xuất hiện trong 上瘾 (thượng ẩn = nghiện) và 过瘾 (quá ẩn = thỏa mãn cơn thèm). | Mở khoá kiến thức | Biết 瘾 (ẩn) giúp đọc 上瘾 (nghiện), 过瘾 (thỏa cơn thèm), 戒瘾 (cai nghiện) — nhóm từ quan trọng về sức khỏe.", "Tự nguyên_Xie": "瘾 là dạng giản thể của 癮. Wiktionary xác nhận 癮 = 疒 (biểu nghĩa: bệnh) + 隱 (biểu âm); chữ hình thanh: {{Han compound|疒|隱|ls=psc|c1=s|c2=p}}. Nghĩa gốc: sự thèm muốn khó cưỡng, như một căn bệnh ẩn trong cơ thể — từ đó có nghĩa nghiện ngập, thèm thuồng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắc nghiện", "Hạng Tần Suất (Jun Da)": "3252.0", "Tần Suất % (Jun Da)": "99.3934994156", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 隐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒隐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘾", "Unihan_Traditional (Chữ Phồn thể)": "癮", "Pinyin_Xie": "yǐn", "Âm Hán Việt_Xie": "ẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ như có, cai hoặc nghiện để chỉ cơn thèm khát một thứ gì đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | yǐn | / | nghiện | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Giải trí và thói quen tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敝', '{"9000": "3253.0", "Chữ Trung Quốc": "敝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 11 | nét | 巾 | cân | biểu nghĩa | vải, khăn | 攴 | phộc | biểu nghĩa | tay cầm gậy đánh | 敝 = 巾 (Cân, biểu nghĩa: tấm vải) + 攴 (Phộc, biểu nghĩa: tay cầm gậy đập); chữ hội ý. Hình ảnh tay cầm gậy đập vào tấm vải rách nát — gợi nghĩa hư nát, tàn tệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tệ\": 巾 (vải) bị 攴 (gậy) đập rách — của tôi (khiêm), tất cả đều tệ xấu cả. | Gương Hán-Việt | 敝 trong 敝人 (tệ nhân — kẻ hèn mọn này), 弊端 (tệ đoan — tệ nạn) | Mở khoá kiến thức | Biết 敝 (tệ) giúp nhận ngữ pháp khiêm tốn trong văn phong lịch sự: 敝校, 敝公司, 敝处.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 敝 là chữ hội ý: 巾 (cân — vải) và 攴 (phộc — tay cầm gậy đánh) kết hợp tạo hình ảnh đập vải cho đến rách nát. Nghĩa gốc: rách nát, tàn tệ. Về sau dùng theo nghĩa khiêm tốn trong xưng hô như 敝人 (tệ nhân — kẻ tầm thường này, tức bản thân nói khiêm), 敝处 (tệ xứ — nơi tôi ở, nói khiêm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1478.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phác (104) Cân (069)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Phác (số 104 - đánh khẽ/ 攵), bộ Cân (số 069 - tấm vải/ 巾) và 4 dấu chấm nhỏ (tấm vải bị rách nát văng ra thành nhiều mảnh). Giải thích sự chuyển ý: Đây là chữ Hội ý. Tệ là tấm vải bị rách nát, cũ kỹ tồi tàn. Từ đó chỉ sự yếu kém, mệt mỏi, suy sụp (tồi tệ, tệ hại, tệ bạc, tệ nạn). (Chữ này cũng là đại từ nhân xưng khiêm tốn: tệ xá, tệ quốc).", "Nghĩa Tiếng Việt_Xie": "rách nát, xấu; của tôi (ý khiêm tốn)", "Hạng Tần Suất (Jun Da)": "3253.0", "Tần Suất % (Jun Da)": "99.3942115455", "GavinGrover_Once (Chiết tự trực tiếp)": "㡀 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰㡀⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㡀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "敝", "Unihan_Traditional (Chữ Phồn thể)": "敝", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Đại từ | 代词 | Thường làm tính từ chỉ sự rách nát hoặc làm đại từ nhân xưng tự xưng một cách khiêm tốn như tệ xá, tệ nhân. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匡', '{"9000": "3254.0", "Chữ Trung Quốc": "匡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 6 | nét | 匚 | biểu nghĩa | cái rổ hình vuông (bộ phương hộp) | 王 | vương | biểu âm | vua (cho âm kuāng/khuông) | 匡 = 匚 (biểu nghĩa: rổ vuông bằng tre) + 王 (Vương, biểu âm); kết hợp hình thanh. Hình ảnh gốc là rổ tre hình vuông; về sau nghĩa mở rộng sang ''chỉnh sửa, khuôn phép''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuôn\": 匚 (rổ vuông) + 王 (vua, âm) — vua dùng khuôn phép vuông vức để chỉnh đốn thiên hạ. | Gương Hán-Việt | 匡 trong 匡正 (khuôn chính — sửa cho đúng), 匡扶 (khuôn phù — phù trợ, dìu dắt) | Mở khoá kiến thức | Biết 匡 (khuông) giúp nhận từ 匡正 (sửa chính), 匡扶汉室 (câu quen trong Tam Quốc — phù trợ nhà Hán).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 匡 gốc là hình ảnh cái rổ hình vuông bằng tre (hay trúc), có thể dùng để đựng thóc gạo. 匚 là bộ chỉ hộp/rổ, 王 cho âm kuāng gần khuông. Từ hình ảnh cái rổ vuông vức, nghĩa mở rộng sang ''chỉnh đốn, khuôn phép, sửa lại cho ngay''. Chưa có cổ tự chi tiết từ Wiktionary. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1421.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phương (1420) Vương (110)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Phương (số 1420 - cái khung/ 匚 /chỉ ý) bao bên ngoài chữ Vương (số 110 - vua/ 王 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Vương chỉ âm, bộ Phương chỉ ý. Khuông là đưa cho vào khuôn khổ để sửa sang lại, uốn nắn. Mở rộng ra là trợ giúp, cứu giúp (khuông phò).", "Nghĩa Tiếng Việt_Xie": "sửa lại, chỉnh lại", "Hạng Tần Suất (Jun Da)": "3254.0", "Tần Suất % (Jun Da)": "99.3949236754", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 王", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "王", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匡", "Unihan_Traditional (Chữ Phồn thể)": "匡", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong văn viết với nghĩa sửa chữa sai lầm hoặc phò tá, giúp đỡ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磋', '{"9000": "3255.0", "Chữ Trung Quốc": "磋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 14 | nét | 石 | thạch | biểu nghĩa | đá | 差 | sai | biểu âm | sai lệch (gợi âm cuō) | 磋 = 石 (Thạch, biểu nghĩa: đá) + 差 (Sai, biểu âm); chữ hình thanh. Bộ thạch gợi hành động mài giũa; 差 gợi âm cuō. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tha\": đá (石) mài sai đi mài lại — 磋 là mài giũa, trao đổi để hoàn thiện. | Gương Hán-Việt | 磋 xuất hiện trong 磋商 (tha thương = thương thảo) và 切磋 (thiết tha = cùng nhau học hỏi, mài giũa). | Mở khoá kiến thức | Biết 磋 (tha) giúp đọc 磋商 (thương thảo chính thức) và thành ngữ 切磋琢磨 (cùng mài giũa học vấn).", "Tự nguyên_Xie": "磋 là chữ hình thanh: 石 (đá) biểu nghĩa, 差 biểu âm. Wiktionary xác nhận: {{Han compound|石|差|ls=psc|c1=s|t1=stone|c2=p}}. Nghĩa gốc theo nghĩa đen: mài đá cho bóng. Nghĩa mở rộng: trao đổi, thảo luận để cùng mài giũa ý kiến — như 磋商 (thương thảo, tham khảo lẫn nhau). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mài cho bóng", "Hạng Tần Suất (Jun Da)": "3255.0", "Tần Suất % (Jun Da)": "99.3956352886", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磋", "Unihan_Traditional (Chữ Phồn thể)": "磋", "Pinyin_Xie": "cuō", "Âm Hán Việt_Xie": "tha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp trong các từ ghép chỉ việc cùng nhau thảo luận, nghiên cứu kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绫', '{"9000": "3256.0", "Chữ Trung Quốc": "绫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 纟 | biểu nghĩa | sợi tơ, vải lụa (bộ mịch) | 夌 | lăng | biểu âm | vượt qua (cho âm líng/lăng) | 绫 = 纟 (biểu nghĩa: tơ lụa) + 夌 (Lăng, biểu âm); chữ hình thanh. 纟 chỉ chất liệu là tơ, 夌 cho âm líng gần với lăng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lăng\": 纟 (tơ) + 夌 (lăng, vượt trội) — lụa lăng vượt trội hơn các loại vải thường. | Gương Hán-Việt | 绫 trong 绫罗绸缎 (lăng la trù đoạn — các loại tơ lụa quý) | Mở khoá kiến thức | Biết 绫 (lăng) giúp nhận từ 绫罗绸缎 — thành ngữ chỉ vải vóc sang trọng trong văn học cổ.", "Tự nguyên_Xie": "Tiểu triện | 绫 là chữ hình thanh: 纟 (mịch — tơ sợi) biểu nghĩa loại vải dệt từ tơ; 夌 (lăng) biểu âm cho líng. Nghĩa: lụa mỏng, vải gấm dệt trơn một màu — loại vải quý thời phong kiến. Phồn thể là 綾. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa mỏng", "Hạng Tần Suất (Jun Da)": "3256.0", "Tần Suất % (Jun Da)": "99.3963469017", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 夌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟夌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绫", "Unihan_Traditional (Chữ Phồn thể)": "綾", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "lăng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ chỉ tơ lụa, vải vóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淆', '{"9000": "3257.0", "Chữ Trung Quốc": "淆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thuỷ | biểu nghĩa | nước | 肴 | hào | biểu âm | thức ăn ngon (gợi âm xiáo) | 淆 = 氵 (Thuỷ, biểu nghĩa: nước) + 肴 (Hào, biểu âm); chữ hình thanh. Bộ thuỷ gợi sự pha trộn lộn; 肴 gợi âm xiáo. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": nước (氵) lẫn vào đồ ăn (肴) — 淆 là lẫn lộn, hỗn tạp không phân biệt được. | Gương Hán-Việt | 淆 xuất hiện trong 混淆 (hỗn hào = lẫn lộn, làm mờ ranh giới). | Mở khoá kiến thức | Biết 淆 (hào) giúp đọc 混淆 (lẫn lộn, làm rối) và 混淆视听 (làm mờ sự thật, gây nhiễu thông tin).", "Tự nguyên_Xie": "Tiểu triện | 淆 là chữ hình thanh: 水/氵 (nước) biểu nghĩa, 肴 biểu âm. Wiktionary xác nhận: {{Han compound|水|肴|ls=psc|c1=s|c2=p}}. Nghĩa gốc: nước lẫn lộn, hỗn tạp — như nước trộn với nhiều thứ lại. Từ đó mở rộng sang nghĩa lẫn lộn, rối loạn (混淆). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lẫn lộn, rối loạn, hỗn tạp", "Hạng Tần Suất (Jun Da)": "3257.0", "Tần Suất % (Jun Da)": "99.3970574813", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 肴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵肴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淆", "Unihan_Traditional (Chữ Phồn thể)": "殽", "Pinyin_Xie": "xiáo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ hoặc tính từ trong các từ ghép chỉ sự nhầm lẫn, làm xáo trộn ranh giới giữa các sự vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('尧', '{"9000": "3258.0", "Chữ Trung Quốc": "尧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 儿 | Số nét | 6 | nét | 垚 | biểu âm | đất cao chồng chất (cho âm yáo/nghiêu) | 兀 | ngột | biểu nghĩa | cao, vươn lên trơ trọi | 尧 = 垚 (biểu âm: đất cao chồng chất) + 兀 (Ngột, biểu nghĩa: cao, vươn lên); chữ hội ý kiêm hình thanh. 兀 gợi ý cao vút, 垚 cho âm yáo gần nghiêu. Trong giáp cốt văn, hình ảnh đất xếp chồng lên rất cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiêu\": đất (垚) xếp cao trên đầu người (兀) — vua Nghiêu cao cả, đức hạnh cao vời. | Gương Hán-Việt | 尧 trong 尧舜 (Nghiêu Thuấn — hai vị vua thánh), 唐尧 (Đường Nghiêu — danh hiệu vua Nghiêu) | Mở khoá kiến thức | Biết 尧 (nghiêu) giúp nhận điển tích 尧舜禹 (Nghiêu Thuấn Vũ) — ba vị vua thánh trong lịch sử và thành ngữ Hán Việt.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 尧 là chữ hội ý kiêm hình thanh: 垚 (đất xếp chồng — rất cao) biểu âm cho yáo, 兀 (ngột — cao trơ trọi) biểu nghĩa. Trong giáp cốt văn, hình ảnh ba tảng đất xếp chồng trên người tạo hình ''cao vút''. Phồn thể: 堯. Nghĩa: cao; dùng chủ yếu làm tên vua Nghiêu (Đế Nghiêu) — một trong ngũ đế của Trung Quốc cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vua Nghiêu; họ Nghiêu; cao", "Hạng Tần Suất (Jun Da)": "3258.0", "Tần Suất % (Jun Da)": "99.3977680608", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 兀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱兀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "尧", "Unihan_Traditional (Chữ Phồn thể)": "堯", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "nghiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ riêng chỉ vị vua huyền thoại thời cổ đại Trung Quốc hoặc làm tính từ chỉ sự cao lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕊', '{"9000": "3259.0", "Chữ Trung Quốc": "蕊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật (bộ thảo) | 惢 | biểu âm | ba trái tim (cho âm ruǐ/nhị) | 蕊 = 艸 (Thảo, biểu nghĩa: cỏ/thực vật) + 惢 (biểu âm: ba tâm chồng nhau); chữ hình thanh. 艸 chỉ đây là bộ phận của thực vật, 惢 cho âm ruǐ gần nhị.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": 艸 (cỏ hoa) bao quanh 惢 (ba tâm) — nhị hoa như ba trái tim rung động giữa bông hoa. | Gương Hán-Việt | 蕊 trong 花蕊 (hoa nhị — nhị hoa), 雌蕊 (thư nhị — nhụy cái) | Mở khoá kiến thức | Biết 蕊 (nhị) giúp nhận từ 花蕊 (nhị hoa), 雄蕊 (nhị đực), 雌蕊 (nhụy cái) trong sinh học thực vật.", "Tự nguyên_Xie": "Tiểu triện | 蕊 là chữ hình thanh: 艸 (thảo — thực vật) biểu nghĩa; 惢 (ba tâm 心 chồng nhau) biểu âm cho ruǐ. Nghĩa: nhị hoa (stamen/pistil) — bộ phận sinh sản của hoa. Phồn thể là 蕊. Hình ảnh ba trái tim (惢) dưới cây cỏ gợi nhiều nhị hoa dày đặc trong lòng đóa hoa. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "280.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Tâm (148)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 276) và ba chữ Tâm (số 148) . Nhụy hoa là phần trung tâm (tâm) quan trọng nhất của bông hoa (thảo).", "Nghĩa Tiếng Việt_Xie": "nhị hoa", "Hạng Tần Suất (Jun Da)": "3259.0", "Tần Suất % (Jun Da)": "99.3984776068", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 惢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹惢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕊", "Unihan_Traditional (Chữ Phồn thể)": "橤", "Pinyin_Xie": "ruǐ", "Âm Hán Việt_Xie": "nhụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ nhị hoa hoặc phần non của cây cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烘', '{"9000": "3260.0", "Chữ Trung Quốc": "烘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 火 | hoả | biểu nghĩa | lửa | 共 | cộng | biểu âm | cùng nhau (gợi âm hōng) | 烘 = 火 (Hoả, biểu nghĩa: lửa) + 共 (Cộng, biểu âm); chữ hình thanh. Bộ hoả chỉ nhiệt, lửa; 共 gợi âm hōng. Wiktionary chỉ ghi {{Han etym}}, không có phân tích chi tiết; cấu trúc được xác nhận qua IDS ⿰火共.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hồng\": lửa (火) đỏ hồng hào sấy cùng (共) — 烘 là hơ lửa, sấy khô, làm nóng. | Gương Hán-Việt | 烘 xuất hiện trong 烘干 (hồng can = sấy khô), 烘托 (hồng thác = làm nổi bật) và 暖烘烘 (ấm áp). | Mở khoá kiến thức | Biết 烘 (hồng) giúp đọc 烘干 (sấy khô), 烘焙 (nướng bánh) và 烘托 (làm nổi bật bằng nền).", "Tự nguyên_Xie": "烘 là chữ hình thanh: 火 (lửa) biểu nghĩa, 共 biểu âm. Wiktionary chỉ ghi {{Han etym}} — không có phân tích glyphOrigin chi tiết. Nghĩa gốc: hơ lửa, sấy khô bằng nhiệt. Từ đó mở rộng: nướng, sấy (烘干), làm nổi bật (烘托). Chưa có nguồn học thuật đầy đủ về từ nguyên. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nóng đỏ; đốt, sấy, hơ lửa", "Hạng Tần Suất (Jun Da)": "3260.0", "Tần Suất % (Jun Da)": "99.3991861192", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 共", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火共", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "共", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烘", "Unihan_Traditional (Chữ Phồn thể)": "烘", "Pinyin_Xie": "hōng", "Âm Hán Việt_Xie": "hồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thể hiện hành động dùng lửa hoặc nhiệt để làm khô, sưởi ấm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hōng | / | sấy | / | hōng | / | nướng | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璋', '{"9000": "3261.0", "Chữ Trung Quốc": "璋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 玉 | ngọc | biểu nghĩa | ngọc bích (bộ vương biến thể) | 章 | chương | biểu âm | bài văn, chương đoạn (cho âm zhāng/chương) | 璋 = 王 (biểu nghĩa: ngọc — bộ 玉 biến thể) + 章 (Chương, biểu âm); chữ hình thanh. 王 (ngọc) chỉ chất liệu, 章 cho âm zhāng chính xác là chương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\": 王 (ngọc) + 章 (chương, bài) — viên ngọc chương, quý như một áng văn chương. | Gương Hán-Việt | 璋 trong 弄璋 (lộng chương — sinh con trai, điển cố cổ) | Mở khoá kiến thức | Biết 璋 (chương) giúp nhận điển cố 弄璋之喜 (mừng sinh con trai) và 弄瓦之喜 (mừng sinh con gái) trong thư tín cổ.", "Tự nguyên_Xie": "璋 là chữ hình thanh: bộ 王 (玉 — ngọc) biểu nghĩa; 章 (chương) biểu âm cho zhāng. Nghĩa: tấm ngọc bích hình bán nguyệt dùng trong lễ nghi cung đình thời cổ đại Trung Hoa. Phồn thể cũng là 璋. 璋 là vật lễ nghi quan trọng — các quý tộc dùng trong tế lễ và đón tiếp. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viên ngọc", "Hạng Tần Suất (Jun Da)": "3261.0", "Tần Suất % (Jun Da)": "99.3998946316", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璋", "Unihan_Traditional (Chữ Phồn thể)": "璋", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại ngọc quý hình nửa ngọc khuê thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亢', '{"9000": "3262.0", "Chữ Trung Quốc": "亢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 4 | nét | 亢 | cang | tượng hình | cổ họng vươn cao — hình người đứng thẳng cổ cao | 亢 là chữ tượng hình độc lập — hình ảnh người đứng thẳng với cổ vươn cao. Không có Wiktionary anchor chi tiết nhưng nguồn gốc liên quan đến hình ảnh cổ họng/yết hầu. Chữ độc lập, cũng là bộ thủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cang\": 亢 — người ngẩng cổ kiêu ngạo, cao cang không chịu cúi đầu. | Gương Hán-Việt | 亢 trong 亢奋 (cang phấn — hưng phấn quá mức), 亢龙 (cang long — rồng bay quá cao) | Mở khoá kiến thức | Biết 亢 (cang) giúp nhận từ 亢奋 (hưng phấn thái quá) và thành ngữ 亢龙有悔 (rồng bay cao tất hối hận) từ Kinh Dịch.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | 亢 là chữ tượng hình: hình người đứng thẳng với cổ vươn cao (yết hầu). Nghĩa gốc: cổ họng, yết hầu; mở rộng sang cao, kiêu ngạo, quá mức. Chưa có ghi chép cổ tự chi tiết từ Wiktionary. Hay gặp trong y học cổ truyền: 亢盛 (cang thịnh — cực thịnh, quá mức), và thiên văn: 亢宿 (Cang Tú — một trong 28 tinh tú). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1833.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đầu (008) Kỷ (016)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Đầu (số 008 - phần đầu, trên cùng/ 亠) ở trên chữ Kỷ (số 016 - cái bàn nhỏ/ 几). Giải thích sự chuyển ý: Đầu là phần trên cùng, vượt lên trên cái kỷ (cái bàn). Kháng mang ý nghĩa là cao ngạo, cao quá, quá mức (cao kháng, kháng hạn - đại hạn).", "Nghĩa Tiếng Việt_Xie": "cao; kiêu ngạo", "Hạng Tần Suất (Jun Da)": "3262.0", "Tần Suất % (Jun Da)": "99.4006010769", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亠", "Unihan_Simplified (Chữ Giản thể)": "亢", "Unihan_Traditional (Chữ Phồn thể)": "亢", "Pinyin_Xie": "kàng", "Âm Hán Việt_Xie": "kháng, cang, cương, hàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ để miêu tả trạng thái cao vút, kiêu ngạo hoặc hưng phấn quá mức. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轧', '{"9000": "3263.0", "Chữ Trung Quốc": "轧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 5 | nét | 车 | xa | biểu nghĩa | xe (bộ xa) | 乙 | ất | biểu âm | thiên can thứ hai (cho âm yà/át) | 轧 = 车 (Xa, biểu nghĩa: xe) + 乙 (Ất, biểu âm); chữ hình thanh. 车 chỉ hành động liên quan đến xe, 乙 cho âm yà gần át. Phồn thể 軋.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"át\": 车 (xe) + 乙 (ất) — bánh xe lăn át qua, nghiền nát mọi thứ trên đường. | Gương Hán-Việt | 轧 trong 倾轧 (khuynh át — nội đấu, chèn ép), 轧钢 (át cương — cán thép) | Mở khoá kiến thức | Biết 轧 (át) giúp nhận từ 倾轧 (đấu đá nội bộ) và 轧钢厂 (nhà máy cán thép) trong văn bản kinh tế.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 轧 là chữ hình thanh: 車 (xa — xe) biểu nghĩa; 乙 (ất) biểu âm cho yà. Nghĩa gốc: bánh xe nghiền, đè bẹp; mở rộng sang nghiền, ép, lăn qua. Phồn thể là 軋. Hay gặp trong 轧钢 (át cương — cán thép), 倾轧 (khuynh át — tranh giành, chèn ép). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghiến, nghiền, đè bẹp", "Hạng Tần Suất (Jun Da)": "3263.0", "Tần Suất % (Jun Da)": "99.4013075222", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轧", "Unihan_Traditional (Chữ Phồn thể)": "軋", "Pinyin_Xie": "yà", "Âm Hán Việt_Xie": "yết, loát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đè, nghiến lên bằng bánh xe hoặc chèn ép nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赂', '{"9000": "3264.0", "Chữ Trung Quốc": "赂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 贝 | bối | biểu nghĩa | tiền, tài sản | 各 | các | biểu âm | mỗi người (gợi âm lù) | 赂 = 贝 (Bối, biểu nghĩa: tiền bạc, của cải) + 各 (Các, biểu âm); chữ hình thanh. Bộ bối chỉ giao dịch tài chính; 各 gợi âm lù. Chữ giản thể của 賂; tiểu triện đã ghi lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\": tiền (贝) lộ ra trao từng người (各) — 赂 là hối lộ, đút lót. | Gương Hán-Việt | 赂 xuất hiện trong 贿赂 (hối lộ = đút lót) — từ pháp lý quan trọng. | Mở khoá kiến thức | Biết 赂 (lộ) giúp đọc 贿赂 (hối lộ, tham nhũng) — từ dùng nhiều trong văn pháp luật và tin tức.", "Tự nguyên_Xie": "Tiểu triện | 赂 là dạng giản thể của 賂. Wiktionary xác nhận 賂 = 貝 (biểu nghĩa: tiền, của cải) + 各 (biểu âm); chữ hình thanh: {{Han compound|貝|各|ls=psc|c1=s|c2=p|t1=shell; money}}. Nghĩa gốc cổ: trao tặng quà vật phẩm; nghĩa hiện đại: hối lộ — trao tiền để mua chuộc người có quyền lực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đem của đút lót", "Hạng Tần Suất (Jun Da)": "3264.0", "Tần Suất % (Jun Da)": "99.4020113836", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赂", "Unihan_Traditional (Chữ Phồn thể)": "賂", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành vi hối lộ hoặc làm danh từ chỉ của cải đem đút lót. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝗', '{"9000": "3265.0", "Chữ Trung Quốc": "蝗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 皇 | hoàng | biểu âm | hoàng đế (cho âm huáng/hoàng) | 蝗 = 虫 (Trùng, biểu nghĩa: côn trùng) + 皇 (Hoàng, biểu âm); chữ hình thanh. 虫 chỉ đây là loài côn trùng, 皇 cho âm huáng chính xác là hoàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": 虫 (trùng) + 皇 (hoàng) — con trùng hoàng — châu chấu sa, như hoàng đế của sâu bọ, tàn phá mùa màng. | Gương Hán-Việt | 蝗 trong 蝗虫 (hoàng trùng — châu chấu sa), 蝗灾 (hoàng tai — nạn châu chấu) | Mở khoá kiến thức | Biết 蝗 (hoàng) giúp nhận từ 蝗虫 (châu chấu), 蝗灾 (thiên tai châu chấu) trong báo và lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 蝗 là chữ hình thanh: 虫 (trùng — côn trùng) biểu nghĩa; 皇 (hoàng — hoàng đế) biểu âm cho huáng. Nghĩa: châu chấu, cào cào; đặc biệt là châu chấu sa (蝗虫) gây nạn đói lịch sử. Tên dân gian 蝗 — con trùng như ''hoàng đế'' của sâu bọ vì sức tàn phá khủng khiếp. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mã hoàng 馬蝗)", "Hạng Tần Suất (Jun Da)": "3265.0", "Tần Suất % (Jun Da)": "99.4027142113", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 皇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫皇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝗", "Unihan_Traditional (Chữ Phồn thể)": "蝗", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ loài côn trùng phá hoại mùa màng như châu chấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榆', '{"9000": "3266.0", "Chữ Trung Quốc": "榆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 俞 | du | biểu âm | đồng ý (cho âm yú/du) | 榆 = 木 (Mộc, biểu nghĩa: cây) + 俞 (Du, biểu âm); chữ hình thanh. 木 chỉ đây là loài cây, 俞 cho âm yú chính xác là du.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": 木 (cây) + 俞 (du, đồng ý) — cây du lặng lẽ gật đầu đồng ý trước gió. | Gương Hán-Việt | 榆 trong 桑榆 (tang du — dâu và du; ẩn dụ hoàng hôn tuổi già) | Mở khoá kiến thức | Biết 榆 (du) giúp nhận thành ngữ 桑榆暮景 (tuổi già về chiều) và 榆木脑袋 (đầu óc cứng nhắc).", "Tự nguyên_Xie": "Tiểu triện | 榆 là chữ hình thanh: 木 (mộc — cây) biểu nghĩa; 俞 (du) biểu âm cho yú. Nghĩa: cây du (elm) — loài cây thân gỗ cứng. Hay gặp trong thành ngữ 桑榆暮景 (tang du mộ cảnh — ánh sáng cuối ngày phản chiếu trên cây dâu và cây du, ẩn dụ tuổi già) và 榆木疙瘩 (du mộc — đầu óc cứng như gỗ du, ám chỉ người cứng đầu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây du", "Hạng Tần Suất (Jun Da)": "3266.0", "Tần Suất % (Jun Da)": "99.4034170391", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榆", "Unihan_Traditional (Chữ Phồn thể)": "榆", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài cây du, một loại cây thân gỗ rụng lá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骏', '{"9000": "3267.0", "Chữ Trung Quốc": "骏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 10 | nét | 马 | mã | biểu nghĩa | ngựa | 夋 | tuấn | biểu âm | bước đi cao (cho âm jùn/tuấn) | 骏 = 马 (Mã, biểu nghĩa: ngựa) + 夋 (biểu âm: bước đi cao); chữ hình thanh. 马 chỉ đây là loài ngựa, phần còn lại cho âm jùn gần tuấn. Phồn thể 駿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\": 马 (ngựa) + phần âm jùn — con tuấn mã phi nhanh, tài năng như ngựa hay. | Gương Hán-Việt | 骏 trong 骏马 (tuấn mã — ngựa hay), 骏才 (tuấn tài — nhân tài xuất sắc) | Mở khoá kiến thức | Biết 骏 (tuấn) giúp nhận từ 骏马 (ngựa giỏi), và phân biệt với 俊 (俊 — đẹp trai) dù đồng âm.", "Tự nguyên_Xie": "Tiểu triện | 骏 là chữ hình thanh: 馬 (mã — ngựa) biểu nghĩa; phần âm cho jùn. Nghĩa gốc: ngựa hay, tuấn mã. Mở rộng sang ''tài giỏi, xuất sắc''. Phồn thể là 駿. Hay gặp trong 骏马 (tuấn mã — ngựa hay), 俊秀 và 骏 thường nhầm do cùng âm jùn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa hay", "Hạng Tần Suất (Jun Da)": "3267.0", "Tần Suất % (Jun Da)": "99.4041188333", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骏", "Unihan_Traditional (Chữ Phồn thể)": "駿", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ ngựa tốt hoặc làm tính từ chỉ sự nhanh nhẹn, tài giỏi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诛', '{"9000": "3268.0", "Chữ Trung Quốc": "诛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | ngôn | biểu nghĩa | lời nói (bộ ngôn biến thể) | 朱 | chu | biểu âm | đỏ, màu son (cho âm zhū/tru) | 诛 = 讠 (Ngôn, biểu nghĩa: lời nói/hành động tuyên phán) + 朱 (Chu, biểu âm); chữ hình thanh. 讠 chỉ hành động tuyên bố trừng trị, 朱 cho âm zhū gần tru. Phồn thể 誅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tru\": 讠(lời phán) + 朱 (đỏ máu) — lời phán tuyên án đỏ máu — tru diệt kẻ có tội. | Gương Hán-Việt | 诛 trong 诛杀 (tru sát — giết chết), 诛心 (tru tâm — kết tội ý đồ), 天诛地灭 (thiên tru địa diệt) | Mở khoá kiến thức | Biết 诛 (tru) giúp nhận thành ngữ 天诛地灭 và từ pháp lý 诛灭九族 trong tiểu thuyết lịch sử.", "Tự nguyên_Xie": "Tiểu triện | 诛 là chữ hình thanh: 讠(言 — lời nói) biểu nghĩa — nghĩa gốc là ''lên án bằng lời, kết tội''; 朱 (chu) biểu âm cho zhū. Nghĩa mở rộng: tử hình, giết kẻ có tội theo lệnh nhà nước, trừng phạt. Phồn thể 誅. Hay gặp trong 诛杀 (tru sát — giết chết), 天诛地灭 (thiên tru địa diệt — trời đất cùng trừng phạt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết kẻ có tội; phát cỏ", "Hạng Tần Suất (Jun Da)": "3268.0", "Tần Suất % (Jun Da)": "99.4048206275", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诛", "Unihan_Traditional (Chữ Phồn thể)": "誅", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "tru", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị việc giết kẻ có tội hoặc tiêu diệt, trừ khử. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('勺', '{"9000": "3269.0", "Chữ Trung Quốc": "勺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 勹 | Số nét | 3 | nét | 勹 | bao | biểu hình | hình bao quanh, lòng muỗng | 丶 | chủ | biểu hình | chấm — biểu thị vật trong lòng muỗng | 勺 = 勹 (Bao, lòng muỗng) + 丶 (chấm, vật trong lòng); chữ tượng ý (liushu=i) — vẽ rượu/chất lỏng trong cái muỗng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thược\" (cũng đọc ''chước''): 勹 (lòng) + 丶 (chấm) — chất lỏng trong lòng muỗng, ấy là ''thược''; nhớ 勺子 (cái muỗng). | Gương Hán-Việt | ''thược'' trong ''thược dược'' (loài hoa, gốc khác); nghĩa thông dụng = ''muỗng, muôi'' | Mở khoá kiến thức | Biết 勺 là mở 勺子, 汤勺 — nhóm danh từ dụng cụ ăn uống HSK 4-6.", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 勺 là chữ tượng ý: 勹 (cái muỗng/lòng muỗng) + 丶 (vật trong lòng, gợi ''rượu hoặc chất lỏng''). Nghĩa: cái muỗng, cái muôi; cũng là đơn vị đo cổ (= 1/100 thăng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "976.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bao (020) Chủ (003)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Dấu chấm (chữ Chủ số 003) nằm ở trong bộ Bao (số 020 - bao bọc). Biểu thị có vật được chứa đựng ở trong lòng. Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Thược là cái thìa, cái muỗng dùng để múc (đong chất lỏng).", "Nghĩa Tiếng Việt_Xie": "múc lấy; cái muôi múc canh; chước (đơn vị đo, bằng 1/100 của thăng)", "Hạng Tần Suất (Jun Da)": "3269.0", "Tần Suất % (Jun Da)": "99.405521905", "GavinGrover_Once (Chiết tự trực tiếp)": "勹 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴勹丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "勹", "Unihan_Simplified (Chữ Giản thể)": "勺", "Unihan_Traditional (Chữ Phồn thể)": "勺", "Pinyin_Xie": "sháo", "Âm Hán Việt_Xie": "thược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này làm danh từ chỉ cái muôi múc canh hoặc làm lượng từ đo lường dung tích cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | sháo | / | muỗng | Xuất hiện trong lộ trình | New HSK | New HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梵', '{"9000": "3270.0", "Chữ Trung Quốc": "梵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 林 | lâm | biểu nghĩa | rừng cây (hai cây 木) | 凡 | phàm | biểu âm | tầm thường (cho âm fàn/phạm) | 梵 = 林 (Lâm, biểu nghĩa: rừng cây) + 凡 (Phàm, biểu âm); chữ hình thanh. 林 gợi nghĩa tươi tốt um tùm (nghĩa gốc), 凡 cho âm fàn gần phạm. Nghĩa gốc là ''cây cối tươi tốt'', về sau mượn âm để phiên âm Sanskrit ''Brahman''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phạm\": 林 (rừng) + 凡 (phàm) — rừng thiêng Phạm thiên, nơi tiếng Sanskrit vang vọng. | Gương Hán-Việt | 梵 trong 梵文 (phạm văn — chữ Sanskrit), 梵语 (phạm ngữ — tiếng Sanskrit) | Mở khoá kiến thức | Biết 梵 (phạm) giúp nhận từ 梵文 (tiếng Phạn), 梵天 (Phạm thiên — Brahma), 梵宫 (chùa chiền) trong văn Phật giáo.", "Tự nguyên_Xie": "Tiểu triện | 梵 là chữ hình thanh: 林 (lâm — rừng) biểu nghĩa gợi sự xanh tươi; 凡 (phàm) biểu âm cho fàn. Nghĩa gốc: cây cối xanh tươi. Chữ được dùng để phiên âm Sanskrit ''Brahman'' (Phạm thiên, Phạm ngữ), vì vậy trong tiếng Trung hiện đại 梵 chủ yếu liên quan đến Phật giáo, Sanskrit. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nết làm cho thanh tịnh", "Hạng Tần Suất (Jun Da)": "3270.0", "Tần Suất % (Jun Da)": "99.4062221488", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 凡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱林凡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "凡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "林", "Unihan_Simplified (Chữ Giản thể)": "梵", "Unihan_Traditional (Chữ Phồn thể)": "梵", "Pinyin_Xie": "fàn", "Âm Hán Việt_Xie": "phạm, phạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự thanh tịnh hoặc làm danh từ liên quan đến Phật giáo và tiếng Phạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炽', '{"9000": "3271.0", "Chữ Trung Quốc": "炽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hỏa | biểu nghĩa | lửa | 只 | chỉ | biểu âm | chỉ, duy nhất (cho âm chì/sí) | 炽 = 火 (Hỏa, biểu nghĩa: lửa) + 只 (Chỉ, biểu âm giản lược); chữ hình thanh giản thể. Phồn thể 熾 = 火 + 戠 (phức tạp hơn). 火 chỉ lửa rực rỡ, phần âm cho chì gần sí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sí\": 火 (lửa) cháy sí — ngọn lửa bùng cháy sí sả, mãnh liệt không tắt. | Gương Hán-Việt | 炽 trong 炽热 (sí nhiệt — nóng rực), 炽烈 (sí liệt — mãnh liệt) | Mở khoá kiến thức | Biết 炽 (sí) giúp nhận từ 炽热 (nóng bỏng, nhiệt tình) và 炽烈 (mãnh liệt) thường dùng trong văn học lãng mạn.", "Tự nguyên_Xie": "Tiểu triện | 炽 (giản thể) từ phồn thể 熾: 火 (hỏa — lửa) biểu nghĩa; 戠 biểu âm cho chì. Nghĩa: lửa cháy rực, bừng bừng. Mở rộng sang ''mạnh mẽ, hưng thịnh''. Hay gặp trong 炽热 (sí nhiệt — nóng bỏng, nhiệt tình mãnh liệt), 炽烈 (sí liệt — mãnh liệt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lửa cháy mạnh", "Hạng Tần Suất (Jun Da)": "3271.0", "Tần Suất % (Jun Da)": "99.4069218759", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 只", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火只", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "只", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炽", "Unihan_Traditional (Chữ Phồn thể)": "熾", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả ngọn lửa cháy dữ dội hoặc khí thế bừng bừng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笠', '{"9000": "3272.0", "Chữ Trung Quốc": "笠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre, trúc (bộ trúc) | 立 | lập | biểu âm | đứng thẳng (cho âm lì/lợp) | 笠 = 竹 (Trúc, biểu nghĩa: tre) + 立 (Lập, biểu âm); chữ hình thanh. 竹 chỉ chất liệu là tre, 立 cho âm lì gần lợp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lợp\": 竹 (tre) + 立 (đứng) — tấm tre đứng lợp thành chiếc nón đầu. | Gương Hán-Việt | 笠 trong 草笠 (thảo lợp — nón cỏ), 斗笠 (đấu lợp — nón lá rộng vành) | Mở khoá kiến thức | Biết 笠 (lợp) giúp nhận từ 斗笠 (nón lá) và hình ảnh 披蓑戴笠 (áo tơi nón lá) trong thơ cổ.", "Tự nguyên_Xie": "Tiểu triện | 笠 là chữ hình thanh: 竹 (trúc — tre) biểu nghĩa; 立 (lập — đứng) biểu âm cho lì. Nghĩa: cái nón lá đan bằng tre hoặc cỏ, đội đầu che mưa nắng. Cũng chỉ lồng bàn bằng tre. Hình ảnh thân thuộc trong đời sống nông dân. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1545.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (118) Lập (112)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 118 - cây tre/ 竹 /chỉ ý) ở trên bộ Lập (số 112 - đứng/ 立 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Bộ Lập chỉ âm, bộ Trúc chỉ ý. Lạp là cái nón dùng đội trên đầu che nắng che mưa, được đan bằng lá tre lá trúc (nón lạp).", "Nghĩa Tiếng Việt_Xie": "cái nón; cái lồng bàn", "Hạng Tần Suất (Jun Da)": "3272.0", "Tần Suất % (Jun Da)": "99.407621603", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笠", "Unihan_Traditional (Chữ Phồn thể)": "笠", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loại nón lá hoặc mũ đan bằng tre nứa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颌', '{"9000": "3273.0", "Chữ Trung Quốc": "颌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 12 | nét | 合 | hợp | biểu âm | kết hợp (cho âm hé/hạp) | 页 | hiệt | biểu nghĩa | đầu (bộ hiệt, đầu người) | 颌 = 合 (Hợp, biểu âm) + 页 (Hiệt, biểu nghĩa: đầu người); chữ hình thanh. 页 chỉ đây liên quan đến bộ phận trên đầu/mặt, 合 cho âm hé gần hạp. Phồn thể 頜.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạp\": 合 (hợp, khép lại) + 页 (đầu) — hai hàm khép hạp lại để nhai. | Gương Hán-Việt | 颌 trong 上颌 (thượng hạp — hàm trên), 下颌 (hạ hạp — hàm dưới), 颌骨 (hạp cốt — xương hàm) | Mở khoá kiến thức | Biết 颌 (hạp) giúp nhận từ chuyên ngành y khoa và nha khoa: 下颌关节 (khớp hàm), 颌骨 (xương hàm).", "Tự nguyên_Xie": "颌 là chữ hình thanh: 頁 (hiệt — đầu người) biểu nghĩa; 合 (hợp) biểu âm cho hé. Nghĩa: hàm, xương hàm (jaw) — xương vùng miệng. 上颌 (thượng hạp — hàm trên), 下颌 (hạ hạp — hàm dưới). Phồn thể 頜. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miệng, mồm, hàm", "Hạng Tần Suất (Jun Da)": "3273.0", "Tần Suất % (Jun Da)": "99.4083208133", "GavinGrover_Once (Chiết tự trực tiếp)": "合 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰合页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颌", "Unihan_Traditional (Chữ Phồn thể)": "頜", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạp, cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương hàm ở mặt của người hoặc động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闸', '{"9000": "3274.0", "Chữ Trung Quốc": "闸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 8 | nét | 门 | môn | biểu nghĩa | cửa, cổng (bộ môn) | 甲 | giáp | biểu âm | áo giáp, đứng đầu (cho âm zhá/trát) | 闸 = 门 (Môn, biểu nghĩa: cửa) + 甲 (Giáp, biểu âm); chữ hình thanh. 门 chỉ đây là loại cửa/van, 甲 cho âm zhá gần trát. Phồn thể 閘.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trát\": 门 (cửa) + 甲 (giáp — vững chắc) — cửa giáp trát, đập nước kiên cố ngăn dòng chảy. | Gương Hán-Việt | 闸 trong 水闸 (thủy trát — cống nước), 闸门 (trát môn — cửa van) | Mở khoá kiến thức | Biết 闸 (trát) giúp nhận từ 水闸 (cống nước), 闸口 (cửa cống) trong công trình thủy lợi.", "Tự nguyên_Xie": "闸 là chữ hình thanh: 門 (môn — cửa) biểu nghĩa; 甲 (giáp) biểu âm cho zhá. Nghĩa: cái đập/cửa cống ngăn nước, cái cổng chắn. Hay gặp trong 水闸 (thủy trát — cống nước), 闸门 (trát môn — cửa cống/van). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đập ngăn nước", "Hạng Tần Suất (Jun Da)": "3274.0", "Tần Suất % (Jun Da)": "99.4090195068", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闸", "Unihan_Traditional (Chữ Phồn thể)": "牐", "Pinyin_Xie": "zhá", "Âm Hán Việt_Xie": "áp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ thiết bị đóng ngắt dòng nước hoặc dòng điện. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhá | / | phanh | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狒', '{"9000": "3275.0", "Chữ Trung Quốc": "狒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 犭 | khuyển | biểu nghĩa | chó, thú vật (bộ khuyển biến thể) | 弗 | phất | biểu âm | không, phủ định (cho âm fèi/phí) | 狒 = 犭 (Khuyển, biểu nghĩa: thú vật) + 弗 (Phất, biểu âm); chữ hình thanh. 犭 chỉ đây là loài thú, 弗 cho âm fèi gần phí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phí\": 犭 (thú) + 弗 (phất, không/lạ) — con thú lạ phí phí từ châu Phi, khỉ đầu chó. | Gương Hán-Việt | 狒 trong 狒狒 (phí phí — baboon, khỉ đầu chó) | Mở khoá kiến thức | Biết 狒 (phí) giúp nhận từ 狒狒 (baboon) và phân biệt với 猩猩 (tinh tinh — chimpanzee) trong sách động vật.", "Tự nguyên_Xie": "狒 là chữ hình thanh: 犭(犬 — chó/thú) biểu nghĩa; 弗 (phất) biểu âm cho fèi. Nghĩa: con khỉ đầu chó (baboon) — loài linh trưởng lớn ở châu Phi. Thường gặp dưới dạng 狒狒 (phí phí — baboon). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống khỉ dữ ở châu Phi", "Hạng Tần Suất (Jun Da)": "3275.0", "Tần Suất % (Jun Da)": "99.4097166499", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狒", "Unihan_Traditional (Chữ Phồn thể)": "狒", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và hầu như chỉ xuất hiện trong từ ghép chỉ loài khỉ đầu chó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樊', '{"9000": "3276.0", "Chữ Trung Quốc": "樊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 棥 | phàn | biểu âm | hàng rào (cho âm fán/phàn) | 𠬜 | biểu nghĩa | hai bàn tay (gợi hành động quây quanh) | 樊 = 棥 (Phàn, biểu âm: hàng rào gỗ) + 𠬜 (biểu nghĩa: hai bàn tay quây giữ); chữ hội ý kiêm hình thanh. 棥 cho âm fán gần phàn, hình ảnh hai tay giữ chặt hàng rào gợi nghĩa giam cầm, ràng buộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phàn\": hai tay (𠬜) giữ 棥 (hàng rào) — cái lồng phàn giam chặt, không thoát được. | Gương Hán-Việt | 樊 trong 樊笼 (phàn lung — lồng chim, ràng buộc), 樊篱 (phàn ly — hàng rào, giới hạn) | Mở khoá kiến thức | Biết 樊 (phàn) giúp nhận từ 樊笼 (lồng cũi, ràng buộc) và 冲破樊笼 (phá vỡ ràng buộc) trong văn chương.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 樊 là chữ hội ý kiêm hình thanh: 棥 (phàn — hàng rào gỗ) biểu âm cho fán, 𠬜 (hai bàn tay) biểu nghĩa hành động giữ chặt. 棥 có thể mô tả hàng rào; khi kết hợp với hai bàn tay tạo nghĩa ''cái lồng, chuồng nhốt''. Nghĩa gốc: lồng chim, chuồng thú; mở rộng sang ''ràng buộc, giam cầm''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái lồng chim; cái phên quây vườn rau; quây quanh", "Hạng Tần Suất (Jun Da)": "3276.0", "Tần Suất % (Jun Da)": "99.4104122427", "GavinGrover_Once (Chiết tự trực tiếp)": "棥 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱棥大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "棥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "樊", "Unihan_Traditional (Chữ Phồn thể)": "樊", "Pinyin_Xie": "fán", "Âm Hán Việt_Xie": "phiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ lồng cùi hoặc hàng rào tre gỗ ngăn cách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镕', '{"9000": "3277.0", "Chữ Trung Quốc": "镕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 金 | kim | biểu nghĩa | kim loại (bộ kim biến thể 钅) | 容 | dung | biểu âm | chứa đựng (cho âm róng/dung) | 镕 = 钅 (Kim, biểu nghĩa: kim loại) + 容 (Dung, biểu âm); chữ hình thanh. 钅 chỉ đây liên quan đến kim loại, 容 cho âm róng chính xác là dung. Phồn thể 鎔.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dung\": 钅 (kim loại) + 容 (dung, chứa) — khuôn dung chứa kim loại nóng chảy rồi đúc hình. | Gương Hán-Việt | 镕 trong 熔镕 (dung — nấu chảy), 镕炉 (dung lô — lò luyện kim) | Mở khoá kiến thức | Biết 镕 (dung) giúp nhận từ 镕炉 (lò luyện kim) và ẩn dụ 大熔炉 (nồi luyện vàng — chỉ môi trường tôi luyện).", "Tự nguyên_Xie": "Tiểu triện | 镕 là chữ hình thanh: 金 (kim — kim loại) biểu nghĩa; 容 (dung — chứa đựng) biểu âm cho róng. Nghĩa: khuôn đúc kim loại; nấu chảy kim loại. Hay gặp dưới nghĩa ẩn dụ 熔铸 (dung chú — đúc kết, tổng hợp). Phồn thể 鎔. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuôn bằng kim loại", "Hạng Tần Suất (Jun Da)": "3277.0", "Tần Suất % (Jun Da)": "99.4111057684", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 容", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅容", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "容", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镕", "Unihan_Traditional (Chữ Phồn thể)": "鎔", "Pinyin_Xie": "róng", "Âm Hán Việt_Xie": "dung, dong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ việc làm nóng chảy kim loại để đúc đồ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垢', '{"9000": "3278.0", "Chữ Trung Quốc": "垢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 土 | thổ | biểu nghĩa | đất, bụi (bộ thổ) | 后 | hậu | biểu âm | sau, hoàng hậu (cho âm gòu/cáu) | 垢 = 土 (Thổ, biểu nghĩa: đất, bụi bẩn) + 后 (Hậu, biểu âm); chữ hình thanh. 土 gợi ý bụi đất bám vào, 后 cho âm gòu gần cáu. Phồn thể cũng là 垢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáu\": 土 (đất bẩn) + 后 (hậu, bám theo) — cáu bẩn bám theo sau không chịu đi. | Gương Hán-Việt | 垢 trong 污垢 (ô cáu — bụi bẩn), 藏垢纳污 (tàng cáu nạp ô — chứa chấp ô uế) | Mở khoá kiến thức | Biết 垢 (cáu) giúp nhận từ 污垢 (cáu bẩn) và thành ngữ 含垢忍辱 (cam chịu nhục nhã) trong văn ngôn.", "Tự nguyên_Xie": "Tiểu triện | 垢 là chữ hình thanh: 土 (thổ — đất) biểu nghĩa gợi bụi bẩn, cặn bã; 后 (hậu) biểu âm cho gòu. Nghĩa: cáu bẩn, vết nhơ; ô nhục. Hay gặp trong 污垢 (ô cáu — bụi bẩn), 含垢忍辱 (hàm cáu nhẫn nhục — chịu đựng ô nhục). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1431.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032) Hậu (1430)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thổ (số 032 - đất/ 土 /chỉ ý) ở bên trái chữ Hậu (số 1430/ 后 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hậu chỉ âm, bộ Thổ chỉ ý. Cấu là bụi đất, bụi bặm dính vào người, cáu bẩn (cấu bẩn). Mở rộng ra là sự nhơ nhuốc, dơ dáy.", "Nghĩa Tiếng Việt_Xie": "cáu bẩn, nhơ nhuốc", "Hạng Tần Suất (Jun Da)": "3278.0", "Tần Suất % (Jun Da)": "99.4117987772", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 后", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土后", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "后", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垢", "Unihan_Traditional (Chữ Phồn thể)": "垢", "Pinyin_Xie": "gòu", "Âm Hán Việt_Xie": "cấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ vết bẩn bám lâu ngày hoặc làm tính từ chỉ sự dơ bẩn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘟', '{"9000": "3279.0", "Chữ Trung Quốc": "瘟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | nạch | biểu nghĩa | bệnh tật (bộ nạch) | 温 | ôn | biểu âm | ấm áp, ôn hòa (cho âm wēn/ôn) | 瘟 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 温 (Ôn, biểu âm); chữ hình thanh. 疒 chỉ đây là loại bệnh, 温 cho âm wēn chính xác là ôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ôn\": 疒 (bệnh) + 温 (ôn ấm) — bệnh ôn dịch lây qua không khí ấm ẩm, lây nhanh như hơi ấm lan tỏa. | Gương Hán-Việt | 瘟 trong 瘟疫 (ôn dịch — dịch bệnh), 瘟神 (ôn thần — thần dịch bệnh) | Mở khoá kiến thức | Biết 瘟 (ôn) giúp nhận từ 瘟疫 (dịch bệnh), 猪瘟 (dịch tả lợn) và 鸡瘟 (dịch gà) thường gặp trong tin tức.", "Tự nguyên_Xie": "瘟 là chữ hình thanh: 疒 (nạch — bệnh tật) biểu nghĩa; 温 (ôn — ấm) biểu âm cho wēn. Nghĩa: bệnh ôn dịch, dịch bệnh lây lan. Chưa có cổ tự chi tiết từ Wiktionary. Hay gặp trong 瘟疫 (ôn dịch — dịch bệnh), 猪瘟 (trư ôn — dịch tả lợn). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh ôn dịch, bệnh truyền nhiễm", "Hạng Tần Suất (Jun Da)": "3279.0", "Tần Suất % (Jun Da)": "99.4124917861", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 昷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒昷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘟", "Unihan_Traditional (Chữ Phồn thể)": "瘟", "Pinyin_Xie": "wēn", "Âm Hán Việt_Xie": "ôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại bệnh dịch truyền nhiễm nguy hiểm ở người và gia súc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缪', '{"9000": "3280.0", "Chữ Trung Quốc": "缪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 14 | nét | 纟 | mịch | biểu nghĩa | sợi tơ (bộ mịch biến thể) | 翏 | biểu âm | tiếng chim bay (cho âm móu/mậu) | 缪 = 纟 (Mịch, biểu nghĩa: sợi tơ/dây) + 翏 (biểu âm); chữ hình thanh. 纟 gợi nghĩa quấn, đan xen; phần âm cho móu gần mậu. Phồn thể 繆.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": 纟 (sợi) quấn 翏 (âm mậu) — sợi chỉ mậu quấn rối, cũng như lỗi lầm mậu thuẫn làm rối mọi việc. | Gương Hán-Việt | 缪 trong 绸缪 (trù mậu — chuẩn bị chu đáo), 未雨绸缪 (vị vũ trù mậu — lo trước khi mưa) | Mở khoá kiến thức | Biết 缪 (mậu) giúp nhận thành ngữ 未雨绸缪 (chuẩn bị từ trước) — thường dùng trong văn phong kinh doanh và lập kế hoạch.", "Tự nguyên_Xie": "Tiểu triện | 缪 là chữ hình thanh: 纟(糸 — sợi tơ) biểu nghĩa gợi sự quấn quít, đan xen; phần âm biểu âm cho móu. Đây là chữ đa âm: nghĩa 1 (móu): đan xen, quấn vào nhau; nghĩa 2 (miù): sai lầm; nghĩa 3 (liǎo): họ Mưu. Phồn thể 繆. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đan xen vào nhau", "Hạng Tần Suất (Jun Da)": "3280.0", "Tần Suất % (Jun Da)": "99.413184795", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 翏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟翏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缪", "Unihan_Traditional (Chữ Phồn thể)": "繆", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu, mục, cù, mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm động từ trong từ ghép chỉ sự gắn kết chặt chẽ hoặc sai lệch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菇', '{"9000": "3281.0", "Chữ Trung Quốc": "菇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật (bộ thảo) | 姑 | cô | biểu âm | cô gái, cô dì (cho âm gū/cô) | 菇 = 艸 (Thảo, biểu nghĩa: thực vật) + 姑 (Cô, biểu âm); chữ hình thanh. 艸 chỉ đây là loài thực vật, 姑 cho âm gū chính xác là cô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": 艸 (cây) + 姑 (cô gái) — cô nấm xinh xắn mọc từ đất, cô đơn một mình. | Gương Hán-Việt | 菇 trong 蘑菇 (ma cô — nấm), 香菇 (hương cô — nấm hương) | Mở khoá kiến thức | Biết 菇 (cô) giúp nhận các loại nấm: 蘑菇 (nấm mỡ), 香菇 (nấm hương), 金针菇 (nấm kim châm), 茶树菇 (nấm trà).", "Tự nguyên_Xie": "菇 là chữ hình thanh: 艸 (thảo — thực vật) biểu nghĩa; 姑 (cô) biểu âm cho gū. Nghĩa: nấm ăn được (mushroom). Thường gặp trong 蘑菇 (ma cô — nấm), 香菇 (hương cô — nấm hương), 木耳菇. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cô tô 菇苏)", "Hạng Tần Suất (Jun Da)": "3281.0", "Tần Suất % (Jun Da)": "99.4138767702", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 姑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹姑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "姑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菇", "Unihan_Traditional (Chữ Phồn thể)": "菇", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chung các loại nấm hóa gỗ hoặc nấm ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琦', '{"9000": "3282.0", "Chữ Trung Quốc": "琦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 王 | vương | biểu nghĩa | ngọc (bộ ngọc biến thể) | 奇 | kỳ | biểu âm | lạ kỳ, phi thường (cho âm qí/kỳ) | 琦 = 王 (biểu nghĩa: ngọc — bộ 玉 biến thể) + 奇 (Kỳ, biểu âm); chữ hình thanh. 王 (ngọc) chỉ chất liệu quý, 奇 cho âm qí chính xác là kỳ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": 王 (ngọc) + 奇 (kỳ lạ) — viên ngọc kỳ bảo, phi thường và quý giá. | Gương Hán-Việt | 琦 trong 琦玮 (kỳ vĩ — ngọc quý, xuất sắc); thường dùng làm tên người | Mở khoá kiến thức | Biết 琦 (kỳ) giúp nhận họ tên người Trung Quốc chứa 琦 — chữ tên nam phổ biến gợi tài năng phi thường.", "Tự nguyên_Xie": "Tiểu triện | 琦 là chữ hình thanh: 王 (玉 — ngọc) biểu nghĩa; 奇 (kỳ — lạ kỳ) biểu âm cho qí. Nghĩa: ngọc đẹp, phi thường, quý báu. Chủ yếu dùng làm tên người (tên đẹp). Gợi ý vừa quý như ngọc vừa phi thường như chữ 奇. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc đẹp; phi phàm; đẹp đẽ", "Hạng Tần Suất (Jun Da)": "3282.0", "Tần Suất % (Jun Da)": "99.4145682288", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琦", "Unihan_Traditional (Chữ Phồn thể)": "琦", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ miêu tả vẻ đẹp của ngọc hoặc những điều phi thường, quý giá. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剃', '{"9000": "3283.0", "Chữ Trung Quốc": "剃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 9 | nét | 弟 | đệ | biểu âm | em trai (cho âm tì/thế) | 刂 | biểu nghĩa | dao (bộ đao biến thể) | 剃 = 弟 (Đệ, biểu âm: em trai) + 刂 (biểu nghĩa: dao); chữ hình thanh. 刂 chỉ hành động dùng dao, 弟 cho âm tì gần thế. Chưa có cổ tự chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thế\": 刂 (dao) + 弟 (đệ) — dao cạo thế đầu cho tiểu đệ đi tu. | Gương Hán-Việt | 剃 trong 剃头 (thế đầu — cạo đầu), 剃发 (thế phát — cạo tóc) | Mở khoá kiến thức | Biết 剃 (thế) giúp nhận từ 剃头 (cạo đầu), 剃须刀 (dao cạo râu) và 剃度 (thế độ — xuất gia cạo đầu).", "Tự nguyên_Xie": "Tiểu triện | 剃 là chữ hình thanh: 刂 (刀 — dao) biểu nghĩa hành động cắt bằng dao; 弟 (đệ — em trai) biểu âm cho tì. Nghĩa: cạo đầu, cắt tóc. Hay gặp trong 剃头 (thế đầu — cạo đầu), 剃须 (thế tu — cạo râu). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cắt tóc, cạo trọc", "Hạng Tần Suất (Jun Da)": "3283.0", "Tần Suất % (Jun Da)": "99.4152591705", "GavinGrover_Once (Chiết tự trực tiếp)": "弟 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弟刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剃", "Unihan_Traditional (Chữ Phồn thể)": "剃", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "thế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận cơ thể như đầu, râu để biểu thị hành động cạo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tì | / | cạo | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Vẻ bề ngoài", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迸', '{"9000": "3284.0", "Chữ Trung Quốc": "迸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 9 | nét | 辶 | sước | biểu nghĩa | bước đi, chuyển động | 并 | tinh | biểu âm | hợp nhau (gợi âm bèng) | 迸 = 辶 (Sước, biểu nghĩa: chuyển động) + 并 (Tinh, biểu âm); chữ hình thanh. Bộ sước chỉ sự di chuyển, bùng phát; 并 gợi âm bèng. Tiểu triện và lục thư thông đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": bước chân (辶) bung bính ra tứ phía — 迸 là phun tóe, bùng phát đột ngột. | Gương Hán-Việt | 迸 xuất hiện trong 迸发 (bính phát = bùng phát) và 迸溅 (bính tiễn = bắn tóe). | Mở khoá kiến thức | Biết 迸 (bính) giúp đọc 迸发 (bùng phát mạnh mẽ) — dùng nhiều khi mô tả cảm xúc, năng lượng trào ra.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 迸 là chữ hình thanh: 辵/辶 (bước đi, chuyển động) biểu nghĩa, 并 biểu âm. Wiktionary xác nhận: {{Han compound|辵|并|ls=psc|c1=s|c2=p|t1=walk}}. Nghĩa gốc: bung ra, bắn tóe — chuyển động đột ngột mạnh mẽ. Từ đó mở rộng: bùng phát (迸发), bắn tóe (迸溅). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chạy tán loạn; bắn toé ra; bật ra, thốt ra", "Hạng Tần Suất (Jun Da)": "3284.0", "Tần Suất % (Jun Da)": "99.4159459779", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 并", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶并", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "并", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迸", "Unihan_Traditional (Chữ Phồn thể)": "迸", "Pinyin_Xie": "bèng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ biểu thị hành động chất lỏng hoặc tia lửa bắn mạnh ra ngoài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溺', '{"9000": "3285.0", "Chữ Trung Quốc": "溺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thủy | biểu nghĩa | nước (bộ thủy biến thể) | 弱 | nhược | biểu âm | yếu đuối (cho âm nì/nịch) | 溺 = 氵 (Thủy, biểu nghĩa: nước) + 弱 (Nhược, biểu âm); chữ hình thanh. 氵 chỉ đây liên quan đến nước, 弱 cho âm nì gần nịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nịch\": 氵 (nước) + 弱 (nhược, yếu) — người yếu nịch chìm trong nước, cũng chìm đắm trong tình yêu nịch ái. | Gương Hán-Việt | 溺 trong 溺水 (nịch thủy — chết đuối), 溺爱 (nịch ái — cưng chiều quá mức) | Mở khoá kiến thức | Biết 溺 (nịch) giúp nhận từ 溺水 (chết đuối), 溺爱 (chiều chuộng thái quá) — từ quan trọng trong an toàn và giáo dục.", "Tự nguyên_Xie": "Tiểu triện | 溺 là chữ hình thanh: 氵 (thủy — nước) biểu nghĩa; 弱 (nhược — yếu) biểu âm cho nì. Nghĩa gốc: chìm đuối trong nước, chết đuối. Mở rộng sang ''say mê, đắm chìm vào''. Hay gặp trong 溺水 (nịch thủy — chết đuối), 溺爱 (nịch ái — cưng chiều quá mức). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết đuối, chìm đắm; say mê", "Hạng Tần Suất (Jun Da)": "3285.0", "Tần Suất % (Jun Da)": "99.4166327854", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 弱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵弱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溺", "Unihan_Traditional (Chữ Phồn thể)": "溺", "Pinyin_Xie": "nì", "Âm Hán Việt_Xie": "nịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ để chỉ việc chìm đắm trong nước hoặc say mê quá độ một thói quen xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炫', '{"9000": "3286.0", "Chữ Trung Quốc": "炫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 9 | nét | 火 | hoả | biểu nghĩa | lửa, ánh sáng | 玄 | huyền | biểu âm | huyền bí, sâu thẳm (gợi âm xuàn) | 炫 = 火 (Hoả, biểu nghĩa: lửa, ánh sáng) + 玄 (Huyền, biểu âm); chữ hình thanh. Bộ hoả gợi sự rực rỡ, chói lòa; 玄 gợi âm xuàn. Tiểu triện đã ghi lại hình dạng chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": lửa (火) huyền ảo (玄) chói lòa — 炫 là rực rỡ, phô trương, khoe khoang. | Gương Hán-Việt | 炫 xuất hiện trong 炫耀 (huyễn diệu = khoe khoang) và 炫目 (huyễn mục = chói mắt, rực rỡ). | Mở khoá kiến thức | Biết 炫 (huyễn) giúp đọc 炫耀 (khoe khoang, phô trương) — dùng nhiều trong mô tả hành vi.", "Tự nguyên_Xie": "Tiểu triện | 炫 là chữ hình thanh: 火 (lửa, ánh sáng) biểu nghĩa, 玄 biểu âm. Wiktionary xác nhận: {{Han compound|火|玄|ls=psc|c1=s|c2=p}}. Nghĩa gốc: ánh sáng chói lòa — từ đó mở rộng sang nghĩa khoe khoang, phô trương (炫耀). Trong tiếng lóng hiện đại: 炫 = ngầu, ấn tượng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ", "Hạng Tần Suất (Jun Da)": "3286.0", "Tần Suất % (Jun Da)": "99.4173195928", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 玄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火玄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炫", "Unihan_Traditional (Chữ Phồn thể)": "炫", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ để biểu thị hành động khoe khoang của cải hoặc tài năng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惚', '{"9000": "3287.0", "Chữ Trung Quốc": "惚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tâm, tình cảm (bộ tâm biến thể) | 忽 | hốt | biểu âm | chợt, đột nhiên (cho âm hū/hốt) | 惚 = 忄 (Tâm, biểu nghĩa: tâm trí) + 忽 (Hốt, biểu âm); chữ hình thanh. 忄 chỉ đây liên quan đến trạng thái tinh thần, 忽 cho âm hū chính xác là hốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hốt\": 忄 (tâm) + 忽 (hốt, đột nhiên) — tâm hốt nhiên rối loạn, mơ hồ như trong giấc mơ. | Gương Hán-Việt | 惚 trong 恍惚 (hoảng hốt — mơ hồ, ngây ngất), 迷迷惚惚 (mê mê hốt hốt — mơ màng) | Mở khoá kiến thức | Biết 惚 (hốt) giúp nhận từ 恍惚 (mơ hồ, hoảng hốt) — thường dùng khi miêu tả trạng thái tinh thần không tỉnh.", "Tự nguyên_Xie": "惚 là chữ hình thanh: 忄 (tâm — tâm trí) biểu nghĩa trạng thái tinh thần; 忽 (hốt — đột nhiên) biểu âm cho hū. Nghĩa: hoảng hốt, mơ hồ, mộng mị. Chủ yếu gặp trong từ láy 恍惚 (hoảng hốt — mơ mang, không tỉnh táo), 迷惚. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoảng hốt; hốt hoảng", "Hạng Tần Suất (Jun Da)": "3287.0", "Tần Suất % (Jun Da)": "99.4180053667", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 忽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄忽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惚", "Unihan_Traditional (Chữ Phồn thể)": "惚", "Pinyin_Xie": "hū", "Âm Hán Việt_Xie": "hốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ hoảng thành từ ghép hoảng hốt để làm vị ngữ hoặc trạng ngữ trong câu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗨', '{"9000": "3288.0", "Chữ Trung Quốc": "嗨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 口 | khẩu | biểu nghĩa | miệng, lời cảm thán | 海 | hải | biểu âm | biển (gợi âm hāi) | 嗨 = 口 (Khẩu, biểu nghĩa: miệng, lời thốt ra) + 海 (Hải, biểu âm); chữ hình thanh. Bộ khẩu chỉ tiếng than, tiếng cảm thán; 海 gợi âm hāi. Wiktionary xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hải\": miệng (口) cất tiếng hải hà — 嗨 là tiếng cảm thán chào hỏi vui vẻ. | Gương Hán-Việt | 嗨 ít dùng trong từ Hán-Việt thuần; chủ yếu dùng như tiếng cảm thán hoặc phiên âm ''Hi''. | Mở khoá kiến thức | Biết 嗨 (hải) giúp nhận ra tiếng chào thân mật trong tiếng Trung hiện đại — tương đương ''Hi'' hay ''Này''.", "Tự nguyên_Xie": "嗨 là chữ hình thanh: 口 (miệng) biểu nghĩa, 海 biểu âm. Wiktionary xác nhận: {{Han compound|口|海|ls=psc|c1=s|c2=p|t1=mouth; speech}}. Chữ tạo muộn, dùng để phiên âm các tiếng cảm thán hoặc tiếng vay mượn (như ''Hi'' trong tiếng Anh). Chưa thấy trong giáp cốt hay kim văn; chữ tạo muộn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hải yêu 嗨喲,嗨哟)", "Hạng Tần Suất (Jun Da)": "3288.0", "Tần Suất % (Jun Da)": "99.4186906238", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 海", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口海", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "海", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗨", "Unihan_Traditional (Chữ Phồn thể)": "嗨", "Pinyin_Xie": "hāi", "Âm Hán Việt_Xie": "hải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Từ tượng thanh | 象声词 | Thường đứng đầu câu làm thán từ để biểu thị sự chào hỏi thân mật hoặc tiếng thở dài. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | hēi | / | chào | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các từ chức năng và bổ trợ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陨', '{"9000": "3289.0", "Chữ Trung Quốc": "陨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 9 | nét | 阝 | phụ | biểu nghĩa | gò đất, bờ cao (bộ phụ biến thể) | 员 | viên | biểu âm | thành viên (cho âm yǔn/vẫn) | 陨 = 阝 (Phụ, biểu nghĩa: gò đất/bờ cao → rơi xuống) + 员 (Viên, biểu âm); chữ hình thanh. 阝 gợi hướng rơi xuống đất, 员 cho âm yǔn gần vẫn. Phồn thể 隕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẫn\": 阝 (bờ cao) + 员 (viên) — thiên thạch vẫn rơi từ trên cao xuống đất. | Gương Hán-Việt | 陨 trong 陨石 (vẫn thạch — thiên thạch), 陨落 (vẫn lạc — qua đời, rơi xuống) | Mở khoá kiến thức | Biết 陨 (vẫn) giúp nhận từ 陨石 (thiên thạch), 陨落 (từ trần) thường dùng trong văn tưởng niệm và thiên văn học.", "Tự nguyên_Xie": "陨 là chữ hình thanh: 阜 (phụ — gò đất, bờ cao) biểu nghĩa hướng rơi xuống; 員 (viên) biểu âm cho yǔn. Nghĩa: rơi xuống (từ trên cao); đặc biệt chỉ thiên thạch rơi. Phồn thể 隕. Hay gặp trong 陨石 (vẫn thạch — thiên thạch), 陨落 (vẫn lạc — rơi xuống, từ trần). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rơi xuống, rớt xuống", "Hạng Tần Suất (Jun Da)": "3289.0", "Tần Suất % (Jun Da)": "99.4193748473", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 员", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝员", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "员", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陨", "Unihan_Traditional (Chữ Phồn thể)": "隕", "Pinyin_Xie": "yǔn", "Âm Hán Việt_Xie": "vẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với các danh từ chỉ thiên thạch hoặc nhân vật quan trọng để chỉ sự rơi rụng, qua đời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赃', '{"9000": "3290.0", "Chữ Trung Quốc": "赃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 10 | nét | 贝 | bối | biểu nghĩa | tiền, của cải (bộ bối — vỏ ốc xưa dùng làm tiền) | 臧 | tang | biểu âm | tốt lành (cho âm zāng/tang) | 赃 = 贝 (Bối, biểu nghĩa: tiền/của cải) + 臧 (Tang, biểu âm); chữ hình thanh. 贝 chỉ đây liên quan đến tiền bạc/tài sản, 臧 cho âm zāng chính xác là tang. Phồn thể 贓.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tang\": 贝 (tiền) + 臧 (tang) — tiền tang của ăn trộm, tài sản bất chính. | Gương Hán-Việt | 赃 trong 赃物 (tang vật — tang vật), 贪赃 (tham tang — tham nhũng) | Mở khoá kiến thức | Biết 赃 (tang) giúp nhận từ pháp lý 赃物 (tang vật), 赃款 (tiền bẩn), 贪赃枉法 trong tin tức chống tham nhũng.", "Tự nguyên_Xie": "赃 là chữ hình thanh: 貝 (bối — tiền/của cải) biểu nghĩa; 臧 (tang) biểu âm cho zāng. Nghĩa: tang vật, của ăn trộm, tài sản tham nhũng. Hay gặp trong 赃物 (tang vật), 赃款 (tang khoản — tiền bẩn), 贪赃枉法 (tham tang uổng pháp — tham nhũng vi phạm pháp luật). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "của ăn trộm; tang vật", "Hạng Tần Suất (Jun Da)": "3290.0", "Tần Suất % (Jun Da)": "99.4200575205", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 庄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝庄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赃", "Unihan_Traditional (Chữ Phồn thể)": "贓", "Pinyin_Xie": "zāng", "Âm Hán Việt_Xie": "tang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau động từ như thu giữ, giấu giếm để chỉ tang vật của vụ án. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羁', '{"9000": "3291.0", "Chữ Trung Quốc": "羁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 17 | nét | 罒 | võng | biểu nghĩa | lưới, mạng (bộ võng biến thể) | 革 | cách | biểu nghĩa | da thuộc | 马 | mã | biểu nghĩa | ngựa | 羁 = 罒 (Võng — lưới/mạng) + 革 (Cách — da) + 马 (Mã — ngựa); chữ hội ý. Ba bộ phận kết hợp: lưới da buộc ngựa — cái hàm thiếc, dây cương. Nghĩa: dây cương, kiềm chế, ràng buộc. Phồn thể 羈.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ky\": lưới (罒) + da (革) + ngựa (马) — dây cương ky buộc ngựa, như mọi ràng buộc trong cuộc đời. | Gương Hán-Việt | 羁 trong 羁绊 (ky bán — ràng buộc), 羁旅 (ky lữ — tha hương), 无拘无羁 (vô cương vô ky — tự do tự tại) | Mở khoá kiến thức | Biết 羁 (ky) giúp nhận từ 羁绊 (ràng buộc — dùng nhiều trong văn học lãng mạn) và 羁旅之苦 (nỗi khổ tha hương).", "Tự nguyên_Xie": "Tiểu triện | 羁 (phồn thể 羈) là chữ hội ý: bao gồm 罒 (lưới/mạng), 革 (da thuộc) và 馬 (ngựa) — hình ảnh dây da (cương ngựa) buộc ngựa lại. Nghĩa gốc: hàm thiếc, dây cương ngựa; mở rộng sang ''giam cầm, kiềm chế, ràng buộc''. Hay gặp trong 羁绊 (ky bán — ràng buộc), 羁旅 (ky lữ — tha hương nơi đất khách). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giữ gìn, duy trì, kiềm chế", "Hạng Tần Suất (Jun Da)": "3291.0", "Tần Suất % (Jun Da)": "99.4207396768", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "羁", "Unihan_Traditional (Chữ Phồn thể)": "羈", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "ki", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong văn viết để biểu thị sự trói buộc, hạn chế tự do hoặc giữ lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臻', '{"9000": "3292.0", "Chữ Trung Quốc": "臻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 至 | Số nét | 16 | nét | 至 | chí | biểu nghĩa | đến nơi, đạt đến (bộ chí) | 秦 | tần | biểu âm | nhà Tần (cho âm zhēn/trăn) | 臻 = 至 (Chí, biểu nghĩa: đến, đạt đến) + 秦 (Tần, biểu âm gần); chữ hình thanh. 至 chỉ hành động đến nơi hoặc đạt đến; phần âm cho zhēn gần trăn. Chưa có cổ tự chi tiết từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trăn\": 至 (chí — đến nơi) hướng về mức hoàn hảo — trăn trở cho đến khi đạt đỉnh. | Gương Hán-Việt | 臻 trong 日臻完善 (nhật trăn hoàn thiện — ngày càng hoàn thiện), 臻于至善 (trăn vu chí thiện — đạt đỉnh tối thiện) | Mở khoá kiến thức | Biết 臻 (trăn) giúp nhận thành ngữ 日臻完善 (ngày càng hoàn thiện hơn) — thường dùng trong báo cáo doanh nghiệp và văn phong trang trọng.", "Tự nguyên_Xie": "Tiểu triện | 臻 là chữ hình thanh: 至 (chí — đến nơi) biểu nghĩa đạt đến mức độ nào đó; phần còn lại biểu âm cho zhēn. Nghĩa: đến, đạt đến (mức độ cao); đặc biệt trong ngữ cảnh ''đạt đến mức hoàn hảo''. Hay gặp trong 臻于至善 (trăn vu chí thiện — đạt đến mức tối thiện), 日臻完善 (nhật trăn hoàn thiện — ngày càng hoàn thiện). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đến, kịp thời", "Hạng Tần Suất (Jun Da)": "3292.0", "Tần Suất % (Jun Da)": "99.4214207996", "GavinGrover_Once (Chiết tự trực tiếp)": "至 + 秦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰至秦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "至", "Unihan_Simplified (Chữ Giản thể)": "臻", "Unihan_Traditional (Chữ Phồn thể)": "臻", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trăn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc thành ngữ để chỉ việc đạt đến một trạng thái hoàn mỹ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘀', '{"9000": "3293.0", "Chữ Trung Quốc": "嘀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng (âm thanh phát ra) | 啇 | đích | biểu âm | (cho âm dī/đích) | 嘀 = 口 (Khẩu, biểu nghĩa: âm thanh phát ra từ miệng) + 啇 (Đích, biểu âm); chữ hình thanh. 口 chỉ đây là từ tượng thanh, 啇 cho âm dī gần đích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đích\": 口 (miệng) + 啇 (đích) — âm đích đích tí tách, tiếng đồng hồ hay mưa rơi. | Gương Hán-Việt | 嘀 trong 嘀嗒 (đích đáp — tích tắc), 嘀咕 (đích cốc — thầm thì) | Mở khoá kiến thức | Biết 嘀 (đích) giúp nhận từ 嘀嗒 (tiếng tích tắc đồng hồ) và 嘀咕 (lầm bầm than thở) trong văn học đời thường.", "Tự nguyên_Xie": "嘀 là chữ hình thanh: 口 (khẩu — miệng) biểu nghĩa âm thanh; 啇 biểu âm cho dī. Nghĩa chính: tí tách, tích tắc (từ tượng thanh). Đa âm: 嘀嗒 (dī dā — tích tắc), 嘀咕 (dī gu — thầm thì, lầm bầm). Nghĩa thứ hai (dí): hay gặp trong 嘀嗒 (dídā — tích tắc đồng hồ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tí tách; tích tắc (từ tượng thanh)", "Hạng Tần Suất (Jun Da)": "3293.0", "Tần Suất % (Jun Da)": "99.4221019225", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 啇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘀", "Unihan_Traditional (Chữ Phồn thể)": "嘀", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "đê, đích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng lặp lại hoặc kết hợp với chữ khác để mô tả tiếng nói thầm hoặc tiếng kêu tích tắc. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膳', '{"9000": "3294.0", "Chữ Trung Quốc": "膳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 16 | nét | ⺼ | nhục | biểu nghĩa | thịt, cơ thể (bộ nhục biến thể) | 善 | thiện | biểu âm | tốt lành (cho âm shàn/thiện) | 膳 = ⺼ (Nhục, biểu nghĩa: thịt/thức ăn) + 善 (Thiện, biểu âm); chữ hình thanh. ⺼ chỉ đây liên quan đến thức ăn, 善 cho âm shàn chính xác là thiện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": ⺼ (thịt ngon) + 善 (thiện, tốt) — bữa ăn thiện vị, ngon lành và tốt cho sức khỏe. | Gương Hán-Việt | 膳 trong 膳食 (thiện thực — bữa ăn dinh dưỡng), 御膳 (ngự thiện — cỗ vua) | Mở khoá kiến thức | Biết 膳 (thiện) giúp nhận từ 膳食 (chế độ ăn), 御膳房 (bếp hoàng cung) thường gặp trong dinh dưỡng học và tiểu thuyết cung đình.", "Tự nguyên_Xie": "Tiểu triện | 膳 là chữ hình thanh: ⺼ (肉 — thịt/thức ăn) biểu nghĩa; 善 (thiện — tốt lành) biểu âm cho shàn. Nghĩa: bữa ăn cỗ bàn, cơm nước (nghĩa trang trọng). Hay gặp trong 膳食 (thiện thực — bữa ăn, dinh dưỡng), 用膳 (dụng thiện — dùng bữa), 御膳 (ngự thiện — bữa ăn của vua). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỗ ăn", "Hạng Tần Suất (Jun Da)": "3294.0", "Tần Suất % (Jun Da)": "99.4227814949", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 善", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月善", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膳", "Unihan_Traditional (Chữ Phồn thể)": "膳", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ thức ăn hoặc bữa ăn trong các từ ghép mang sắc thái trang trọng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赣', '{"9000": "3295.0", "Chữ Trung Quốc": "赣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 21 | nét | 章 | chuong | bieu nghia | do ngoc trang tri | 丮 | (cam giu) | bieu nghia | cam, giu | 赣 gom 章 (Chuong, do ngoc) va 丮 (cam giu); chu hoi y goc — hinh anh nguoi cam ngoc de ban tang. Ve sau them 貝 (boi, tien) tao thanh phu Cong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cam\": tinh Giang Tay cua Trung Quoc, ten song Cam — 章 (ngoc) cam trong tay 丮, ban tang nhu dong song hao phong. | Gương Hán-Việt | Cam trong Cam Giang (song Cam, Giang Tay) | Mở khoá kiến thức | Biet 赣 mo khoa dia danh Giang Tay: 赣州 (Cam Chau), 赣江 (Cam Giang).", "Tự nguyên_Xie": "Tieu trieu | Trong van kim (dong), chu von la hoi y: 章 (do ngoc) + 丮 (cam giu) voi nghia goc la cam ngoc ban tang. Thanh phan 丮 bien dang thanh 欠 roi 夂. Bo 貝 (tien) them vao sau. Thuyet Van giai thich theo hinh thanh (竷+貝) nhung khong duoc van tu co hau thuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Cám (hợp của sông Chương và sông Cống)", "Hạng Tần Suất (Jun Da)": "3295.0", "Tần Suất % (Jun Da)": "99.423459517", "GavinGrover_Once (Chiết tự trực tiếp)": "章 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "赣", "Unihan_Traditional (Chữ Phồn thể)": "灨", "Pinyin_Xie": "gàn", "Âm Hán Việt_Xie": "cám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ riêng để chỉ sông Cám hoặc viết tắt cho tỉnh Giang Tây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踌', '{"9000": "3296.0", "Chữ Trung Quốc": "踌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 足 | tuc | bieu nghia | chan, buoc chan | 踌 (gian the cua 躊) la chu hinh thanh: bo 足 (tuc, chan) cho nghia buoc chan do du. Chu chi dung trong tu ghep 踌躇 (do du, tru tru).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tru\": doi chan (足) dung lai khong dam buoc — 踌躇 (tru tru) la do du, chan chu. | Gương Hán-Việt | Tru trong tru tru (踌躇 — do du) | Mở khoá kiến thức | Biet 踌 mo khoa tu 踌躇 (do du, luong lu), 踌躇满志 (tu man).", "Tự nguyên_Xie": "Luc thu thong | Chu tao muon, chua thay trong giap cot/kim van. 踌 (phon the: 躊) hau nhu chi xuat hien trong tu 踌躇 (chochu) — nghia do du, chan chu. Khong co glyph origin hoc thuat ro rang. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trì trù 踟躊)", "Hạng Tần Suất (Jun Da)": "3296.0", "Tần Suất % (Jun Da)": "99.4241365055", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 寿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊寿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踌", "Unihan_Traditional (Chữ Phồn thể)": "躊", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với chữ khác tạo thành từ láy như trù trừ để làm động từ hoặc tính từ trong câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殉', '{"9000": "3297.0", "Chữ Trung Quốc": "殉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 10 | nét | 歹 | toi | bieu nghia | xuong tan, chet choc | 旬 | tuan | bieu am | muoi ngay (bieu am) | 殉 la chu hinh thanh: bo 歹 (toi, xuong tan — bieu y chet) + 旬 (tuan, bieu am). Cau truc psc dien hinh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuẫn\": 歹 (xuong chet) + 旬 (bieu am) — tuan nan la hi sinh mang song vi nhiem vu. | Gương Hán-Việt | Tuan trong tuan nan (殉难 — hi sinh), tuan tang (殉葬 — chon theo) | Mở khoá kiến thức | Biet 殉 mo khoa: 殉职 (tuan chuc — hi sinh vi nhiem vu), 殉国 (tuan quoc — chet vi nuoc).", "Tự nguyên_Xie": "殉 la chu hinh thanh gom 歹 (bo xuong tan, chi cai chet) lam thanh phan bieu nghia va 旬 (muoi ngay) lam thanh phan bieu am. Nghia goc: bi chon song theo nguoi chet; mo rong sang chet vi su nghiep, tuan tiet. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chết theo người khác", "Hạng Tần Suất (Jun Da)": "3297.0", "Tần Suất % (Jun Da)": "99.4248134941", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殉", "Unihan_Traditional (Chữ Phồn thể)": "殉", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tuẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ mục đích hoặc đối tượng mà người đó hy sinh vì họ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桔', '{"9000": "3298.0", "Chữ Trung Quốc": "桔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | cây gỗ | 吉 | cát | biểu âm | tốt lành (gần âm jú) | 桔 = 木 (Mộc, biểu nghĩa: cây) + 吉 (Cát, biểu âm); chữ hình thanh. Tên một loài cây (cát cánh, hoặc trong dụng pháp phổ biến hiện đại = quýt/quất). Cũng là dị thể quy ước của 橘 trong khẩu ngữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kết\": 木 (cây) + 吉 (tốt lành) — cây quả ngọt cát tường, đúng nghĩa ''quýt, cát cánh'' trong 桔子 (quả quýt). | Gương Hán-Việt | ''kết'' trong ''kết quả'' — gần với ''quất'' trong tiếng Việt (cùng họ) | Mở khoá kiến thức | Nắm 桔 mở khoá từ HSK 5: 桔子, và liên hệ 橘 (quýt phồn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 桔 là hình thanh: 木 (cây, biểu nghĩa) + 吉 (Cát, biểu âm). Nghĩa gốc chỉ một loài cây (桔梗 — cát cánh, dược liệu). Trong tiếng Trung khẩu ngữ hiện đại, 桔 thường được dùng đồng nghĩa với 橘 (quýt) trong 桔子 (quả quýt) — đặc biệt phổ biến ở miền Nam. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quả quít, quả cam; (xem: kết cánh 桔梗); (xem: kết cao 桔槔)", "Hạng Tần Suất (Jun Da)": "3298.0", "Tần Suất % (Jun Da)": "99.4254899658", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桔", "Unihan_Traditional (Chữ Phồn thể)": "桔", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "kết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ các loại cây quả. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞿', '{"9000": "3299.0", "Chữ Trung Quốc": "瞿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 18 | nét | 䀠 | (hai mat) | bieu am | hai mat nhin | 隹 | chuy | bieu nghia | chim duoi ngan | 瞿 la chu hinh thanh: 䀠 (hai mat, bieu am) + 隹 (chuy, chim — bieu nghia). Hinh anh doi mat to tron nhin nhu chim bi giat minh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cu\": doi mat (䀠) tron tung nhu con chim (隹) giat minh — 瞿然 la dang ve so hai, ngo ngac. | Gương Hán-Việt | Cu trong ho Cu (瞿 — ho nguoi Trung Quoc), 瞿塘峡 (Cu Duong Hiep) | Mở khoá kiến thức | Biet 瞿 mo khoa: 瞿然 (kinh hai), 瞿塘峡 (Cu Duong Hiep — mot trong ba hem nui Tam Hiep).", "Tự nguyên_Xie": "Tieu trieu | 瞿 gom 䀠 (hai mat) lam bieu am va 隹 (chim duoi ngan) lam bieu nghia. Nghia goc: kinh hai, sung sot — nhu chim giat minh mo to mat. Cung dung lam ho nguoi va ten binh khi co. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1576.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (109) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai bộ Mục (số 109 - con mắt/ 目) ở trên bộ Truy (số 034 - con chim/ 隹). Hình ảnh hai con mắt chim mở to thao láo. Giải thích sự chuyển ý: Đây là chữ Tượng hình kiêm Hội ý. Cù là mở to mắt ngó nhìn quanh quất, ngắm nhìn kinh ngạc.", "Nghĩa Tiếng Việt_Xie": "thấy mà giật mình, ngơ ngác", "Hạng Tần Suất (Jun Da)": "3299.0", "Tần Suất % (Jun Da)": "99.4261664375", "GavinGrover_Once (Chiết tự trực tiếp)": "䀠 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱䀠隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䀠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "瞿", "Unihan_Traditional (Chữ Phồn thể)": "瞿", "Pinyin_Xie": "qú", "Âm Hán Việt_Xie": "cù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ họ người hoặc làm động từ, tính từ trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闽', '{"9000": "3300.0", "Chữ Trung Quốc": "闽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 门 | mon | bieu nghia | cong, cua | 虫 | trung | bieu nghia | loai trung (trong phon the 閩) | 闽 (gian the cua 閩) gom 門 (mon, cong) bao ngoai va 虫 (trung, loai ran/trung) ben trong — hoi y chi vung dat phia Nam co nhieu loai bo sat, tuc tinh Phuc Kien ngay nay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": 門 (cong) chua 虫 (loai trung ran ret) — vung Man Viet (Phuc Kien) ngay xua la dat rung nui nhieu loai doc. | Gương Hán-Việt | Man trong Man Viet (toc nguoi co), Man Nam (tieng Hokkien), Man Giang (song Man) | Mở khoá kiến thức | Biet 闽 mo khoa: 闽南话 (tieng Man Nam/Hokkien), 闽江 (Man Giang), 闽粤 (Man Viet).", "Tự nguyên_Xie": "Tieu trieu | Luc thu thong | 闽 la gian the cua 閩. Chu phon the 閩 gom 門 bao ngoai + 虫 ben trong — nghia goc chi mot bo toc co vung Dong Nam Trung Quoc (nay la Phuc Kien), sau dung lam ten vung. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Mân", "Hạng Tần Suất (Jun Da)": "3300.0", "Tần Suất % (Jun Da)": "99.4268418757", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闽", "Unihan_Traditional (Chữ Phồn thể)": "閩", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng để chỉ vùng đất hoặc tiếng nói của tỉnh Phúc Kiến. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豚', '{"9000": "3301.0", "Chữ Trung Quốc": "豚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 11 | nét | 肉 | nhuc | bieu nghia | thit | 豕 | thi | bieu nghia | lon | 豚 la chu hoi y: 肉 (nhuc, thit) + 豕 (thi, lon) — ghep lai chi con lon con, lon nen gia dinh. Cau truc ic ro rang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"don\": 肉 (thit) + 豕 (lon) — con lon con beo mun, thit ngon. | Gương Hán-Việt | Don trong don ton (豚孙 — chau trai, khiem ton tu xung), ha don (河豚 — ca noc) | Mở khoá kiến thức | Biet 豚 mo khoa: 河豚 (ca noc — ca doc), 豚鼠 (chuot lang — guinea pig).", "Tự nguyên_Xie": "Giap cot | Dai trieu | 豚 la chu hoi y gom 肉 (thit) va 豕 (lon) — nghia goc la con lon con, lon nen. Mo rong sang ca voc, ca heo (trong ten loai dong vat nhu 河豚 — ca noc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con lợn con", "Hạng Tần Suất (Jun Da)": "3301.0", "Tần Suất % (Jun Da)": "99.4275162803", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 豕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月豕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "豚", "Unihan_Traditional (Chữ Phồn thể)": "豚", "Pinyin_Xie": "tún", "Âm Hán Việt_Xie": "đồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm thành phần cấu tạo từ chỉ các loài động vật giống heo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掺', '{"9000": "3302.0", "Chữ Trung Quốc": "掺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 手 | thu | bieu nghia | tay | 參 | tham | bieu am | bieu am (tham) | 掺 la chu hinh thanh: bo 手 (thu, tay — gian the 扌) lam bieu nghia va 參 (tham) lam bieu am. Tay tron lan, pha tron.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tham\": ban tay (扌) pha tron (參 bieu am) — tham tap la tron lan, pha tron cac thu vat vao nhau. | Gương Hán-Việt | Tham trong tham tap (掺杂 — tron tap), tham jia (掺假 — pha hang gia) | Mở khoá kiến thức | Biet 掺 mo khoa: 掺杂 (tron tap), 掺假 (pha hang gia), 掺入 (tron vao).", "Tự nguyên_Xie": "掺 la chu hinh thanh gom 手 (扌, tay) lam bieu nghia va 參 lam bieu am. Nghia goc: tron lan, pha tap vat khac vao. Ve sau dung rong: pha tron, co tap chat. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trộn, hoà, nhào, quấy", "Hạng Tần Suất (Jun Da)": "3302.0", "Tần Suất % (Jun Da)": "99.4281896513", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 参", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌参", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "参", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掺", "Unihan_Traditional (Chữ Phồn thể)": "摻", "Pinyin_Xie": "càn", "Âm Hán Việt_Xie": "sam, tham, sảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ vật bị trộn lẫn hoặc đi kèm bổ ngữ kết quả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chān | / | trộn với | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沌', '{"9000": "3303.0", "Chữ Trung Quốc": "沌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | (thuy) | bieu nghia | nuoc | 屯 | don | bieu am | tich tu (bieu am) | 沌 la chu hinh thanh: bo 氵 (thuy, nuoc — bieu nghia) + 屯 (don, bieu am). Chi nuoc chay rối loan, trang thai hon don, mo ho.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xon\": nuoc (氵) roi loan (屯 bieu am) — hon xon, lao xao nhu nuoc vua khuay. | Gương Hán-Việt | Xon trong hon xon (混沌 — xon xao, hon don), trang thai tien khai thien | Mở khoá kiến thức | Biet 沌 mo khoa: 混沌 (hon don — trang thai nguyen so, tien khai thien), 渾沌 (bien the).", "Tự nguyên_Xie": "沌 la chu hinh thanh gom 氵 (nuoc) lam bieu nghia va 屯 lam bieu am. Nghia goc: trang thai nuoc chay lon xon, mo ho, hoa loan. Thuong gap trong tu hop am 混沌 (hon don — trang thai nguyen so, hoa loan). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hỗn độn 渾敦)", "Hạng Tần Suất (Jun Da)": "3303.0", "Tần Suất % (Jun Da)": "99.4288630224", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沌", "Unihan_Traditional (Chữ Phồn thể)": "沌", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "độn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ hỗn để tạo thành tính từ miêu tả trạng thái chưa phân định của vũ trụ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惰', '{"9000": "3304.0", "Chữ Trung Quốc": "惰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | tim, tâm trí | 隋 | tùy | biểu âm | (rút gọn thành ⿱左月, cho âm) | 惰 = 忄(Tâm, biểu nghĩa: tâm trí, cảm xúc) + 隋 (Tùy, biểu âm, rút gọn); chữ hình thanh. Phần tâm chỉ trạng thái tinh thần lười biếng, phần Tùy cho âm gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoạ\": tâm trí (忄) sa xuống như bị Tùy (隋) kéo — đoạ lạc thành lười biếng, không chịu gắng sức. | Gương Hán-Việt | \"đoạ\" trong \"đoạ lạc\" (sa đoạ, trụy lạc) | Mở khoá kiến thức | Biết 惰 mở khoá các từ như 懒惰 (lười biếng), 惰性 (tính lười, quán tính), 怠惰 (lười nhác).", "Tự nguyên_Xie": "Tiểu triện | 惰 là chữ hình thanh: bộ 忄(tâm) biểu nghĩa — liên quan đến tâm trí; 隋 (Tùy) cho âm. Theo Wiktionary, chữ này ghép từ 心 (tâm) và 隋 (rút bớt), phần âm dẫn đến âm đọc duò. Nghĩa gốc là trạng thái tâm trí buông thả, lười nhác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1096.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (061) Đọa (1095)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Tâm (số 061 - trái tim/ 忄) ở bên trái chữ Đọa (số 1095 - thịt thừa/viết giảm nét bỏ bộ 阝/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Đọa chỉ âm, bộ Tâm chỉ ý. Nọa là tâm lý lười biếng, không chịu làm việc (lười nọa, lười biếng).", "Nghĩa Tiếng Việt_Xie": "ngây ngô, dốt", "Hạng Tần Suất (Jun Da)": "3304.0", "Tần Suất % (Jun Da)": "99.4295358766", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "惰", "Unihan_Traditional (Chữ Phồn thể)": "惰", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "nọa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc đứng sau phó từ chỉ mức độ để miêu tả tính cách. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喳', '{"9000": "3305.0", "Chữ Trung Quốc": "喳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khau | bieu nghia | mieng | 查 | tra | bieu am | tra xet (bieu am) | 喳 la chu hinh thanh: bo 口 (khau, mieng — bieu nghia) + 查 (tra, bieu am). Chi tieng chim ket, tieng xi xao, tieng da thua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": mieng (口) xi xao nhu tra xet (查) — 喳喳 la tieng chim ket, tieng ri ram. | Gương Hán-Việt | Tra trong tra tra (喳喳 — tieng chim ket, xi xao) | Mở khoá kiến thức | Biet 喳 mo khoa: 叽叽喳喳 (tieng chim ket, on ao), 喳 (da, thua — tieng dap trong truyen co dien).", "Tự nguyên_Xie": "喳 la chu hinh thanh gom 口 (mieng) lam bieu nghia va 查 lam bieu am. Khong co glyph origin chi tiet trong Wiktionary. Nghia: tieng chim ket, xi xao; da, thua (tieng dap trong cac truyen Trung Quoc co dien). Chu tao muon, chua co nguon hoc thuat. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xì xào, thì thầm; khe khẽ, se sẽ; chim kêu ríu rít; vâng, dạ", "Hạng Tần Suất (Jun Da)": "3305.0", "Tần Suất % (Jun Da)": "99.4302087309", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 查", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口查", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "查", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喳", "Unihan_Traditional (Chữ Phồn thể)": "喳", "Pinyin_Xie": "zhā", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thán từ | 叹词 | Thường dùng làm từ tượng thanh mô tả âm thanh hoặc thán từ biểu thị sự đồng ý, vâng lời. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椭', '{"9000": "3306.0", "Chữ Trung Quốc": "椭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 陏 | tuỳ | biểu âm | (cho âm gần tuǒ) | 椭 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 陏 (Tuỳ, biểu âm); nhiều khả năng là chữ hình thanh. Bộ Mộc gợi ý ban đầu dùng để chỉ hình dạng của khúc gỗ tròn dài; 陏 cho âm gần tuǒ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoả\": cây gỗ (木) được đẽo thành hình bầu dục — thoả mãn đường cong ellipse tự nhiên. | Gương Hán-Việt | \"thoả\" ít dùng độc lập; xuất hiện trong \"thoả hiệp\" (妥協) — khác chữ nhưng đồng âm | Mở khoá kiến thức | Biết 椭 mở khoá từ 椭圆 (hình bầu dục, elip) — từ toán học và khoa học cơ bản.", "Tự nguyên_Xie": "椭 (phồn thể 橢) là chữ dùng để chỉ hình bầu dục, hình elip. Cấu trúc gồm 木 (mộc) biểu nghĩa và 陏 (tuỳ) biểu âm. Wiktionary không ghi rõ nguồn gốc chi tiết hơn. Nghĩa hiện đại chủ yếu dùng trong toán học để chỉ hình ellipse. Chưa có nguồn học thuật xác nhận thêm về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dài nhọn, hình bầu dục, hình êlíp", "Hạng Tần Suất (Jun Da)": "3306.0", "Tần Suất % (Jun Da)": "99.4308810683", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 陏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木陏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "陏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椭", "Unihan_Traditional (Chữ Phồn thể)": "橢", "Pinyin_Xie": "tuǒ", "Âm Hán Việt_Xie": "thoả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ định ngữ đứng trước danh từ để miêu tả hình dáng của vật thể. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咪', '{"9000": "3307.0", "Chữ Trung Quốc": "咪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khau | bieu nghia | mieng, loi noi | 米 | mieu | bieu am | gao (bieu am) | 咪 la chu hinh thanh: bo 口 (khau, mieng — bieu nghia) + 米 (mieu, gao — bieu am). Chi tieng meo, tieng goi meo, hoac micro (phien am).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"my\": mieng (口) phat ra tieng mieu (米 bieu am) — tieng goi meo nho nhe. | Gương Hán-Việt | My trong tieu my (小咪 — meo nho), miao mi (喵咪 — tieng keu meo) | Mở khoá kiến thức | Biet 咪 mo khoa: 猫咪 (meo nho than mat), 咪咪 (tieng meo keu), 话筒/咪 (micro tieng Quang).", "Tự nguyên_Xie": "咪 la chu hinh thanh gom 口 (mieng) lam bieu nghia va 米 (gao) lam bieu am. Nghia goc: tieng meo keu; tieng goi meo. Ngay nay con dung de phien am micro hoac goi meo than mat. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng gọi mèo", "Hạng Tần Suất (Jun Da)": "3307.0", "Tần Suất % (Jun Da)": "99.4315518554", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咪", "Unihan_Traditional (Chữ Phồn thể)": "咪", "Pinyin_Xie": "mī", "Âm Hán Việt_Xie": "mễ, mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Chữ này thường dùng làm từ mô phỏng âm thanh tiếng mèo kêu hoặc dùng trong tên gọi thân mật. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霎', '{"9000": "3308.0", "Chữ Trung Quốc": "霎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 16 | nét | 霎 | sap | tuong hinh | chu doc lap — mua nho, thoi gian ngan ngui | 霎 la chu doc lap, khong co cau truc phan tich ro rang tu Wiktionary. Chu chi mua nho thoang qua, hoac khoang thoi gian rat ngan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sap\": mua sap roi xuong trong mot thoang roi tan ngay — 霎时 la trong tuc thi, nhanh nhu chop. | Gương Hán-Việt | Sap trong sap thoi (霎时 — trong mot thoang, tuc thi) | Mở khoá kiến thức | Biet 霎 mo khoa: 霎时 (trong thoang, tuc thi), 霎那 (trong khonh khac).", "Tự nguyên_Xie": "Tieu trieu | 霎 khong co glyph origin chi tiet tu Wiktionary. Chu lien quan den hien tuong mua nho thoang qua va y tuong thoi gian ngan ngui. Nghia: mua nho, mua phun; trong mot cai — mot thoang (霎时 la tuc thi). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngắn ngủi; mưa nhỏ", "Hạng Tần Suất (Jun Da)": "3308.0", "Tần Suất % (Jun Da)": "99.432221609", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 妾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨妾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "妾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霎", "Unihan_Traditional (Chữ Phồn thể)": "霎", "Pinyin_Xie": "shà", "Âm Hán Việt_Xie": "siếp, sáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Thường kết hợp thành từ ghép chỉ thời gian cực ngắn để làm trạng ngữ trong câu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侃', '{"9000": "3309.0", "Chữ Trung Quốc": "侃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 口 | khẩu | biểu nghĩa | miệng | 儿 | nhân | biểu nghĩa | người (dạng biến thể) | 侃 là chữ hội ý (theo Wiktionary): 亻(Nhân, người) + 口 (Khẩu, miệng) + 儿 (Nhân). Nhiều cách giải thích khác nhau, nhưng chủ yếu thiên về hội ý — người nói thẳng thắn, giọng cứng rõ. Không có ls=psc trong nguồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khản\": người (亻) mở miệng (口) nói rõ ràng, thẳng thắn — Khản khản là giọng chắc, không lèo nhèo. | Gương Hán-Việt | \"khản\" ít dùng độc lập trong tiếng Việt; xuất hiện trong \"điều khản\" (调侃 — trêu chọc) | Mở khoá kiến thức | Biết 侃 mở khoá 调侃 (trêu đùa, chọc ghẹo), 侃侃而谈 (nói chuyện lưu loát tự nhiên), 侃大山 (tán phét).", "Tự nguyên_Xie": "Kim văn | 侃 được Wiktionary ghi là có nhiều cách giải thích, nhưng đa số cho là chữ hội ý (hội ý). Tổ hợp người (亻/亻) + miệng (口) + chân (儿) gợi hình ảnh người đứng thẳng nói thẳng thắn. Nghĩa cổ là ngay thẳng, cứng cỏi; nghĩa hiện đại phổ biến là nói chuyện thoải mái (侃大山 = tán phét). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cứng thẳng", "Hạng Tần Suất (Jun Da)": "3309.0", "Tần Suất % (Jun Da)": "99.4328908457", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "侃", "Unihan_Traditional (Chữ Phồn thể)": "侃", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "khản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Trong tiếng Trung hiện đại chữ này thường dùng làm động từ với nghĩa là tán gẫu hoặc nói chuyện phiếm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猝', '{"9000": "3310.0", "Chữ Trung Quốc": "猝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 猝 | tot | tuong hinh | dot ngot, voi vang | 猝 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. Chu chi su dot ngot, bat ngo, voi vang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tot\": cat ngat, tot — 猝死 la chet dot ngot khong bao truoc. | Gương Hán-Việt | Tot trong tot tu (猝死 — chet dot tu), tot nhien (猝然 — dot nhien) | Mở khoá kiến thức | Biet 猝 mo khoa: 猝死 (chet dot tu), 猝然 (dot nhien), 猝不及防 (bat chot khong kip phong thu).", "Tự nguyên_Xie": "猝 khong co glyph origin chi tiet tu Wiktionary. Nghia co ban: dot ngot, bat ngo; voi vang. Thuong gap trong tu 猝然 (dot nhien), 猝死 (chet dot tu). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vội vàng", "Hạng Tần Suất (Jun Da)": "3310.0", "Tần Suất % (Jun Da)": "99.4335590489", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猝", "Unihan_Traditional (Chữ Phồn thể)": "猝", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "thốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường đứng trước động từ để làm trạng ngữ chỉ một hành động hay sự việc xảy ra quá đột ngột. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窖', '{"9000": "3311.0", "Chữ Trung Quốc": "窖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 12 | nét | 穴 | huyet | bieu nghia | hang, hoc dat | 告 | cao | bieu am | bao cao (bieu am) | 窖 la chu hinh thanh: bo 穴 (huyet, hang hoc — bieu nghia) + 告 (cao, bieu am). Chi ham dat du tru thuc pham.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": hang dat (穴) de giao tru (cao bieu am) — ham ruou, kho ngam giao thuc pham. | Gương Hán-Việt | Giao trong dia giao (地窖 — ham dat), tuu giao (酒窖 — ham ruou) | Mở khoá kiến thức | Biet 窖 mo khoa: 地窖 (ham dat), 酒窖 (ham ruou), 冰窖 (kho da).", "Tự nguyên_Xie": "Tieu trieu | 窖 la chu hinh thanh gom 穴 (hang, hoc dat) lam bieu nghia va 告 lam bieu am. Nghia goc: ham dat de chua tru thuc pham, ham ruou, kho lanh ngam duoi dat. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hầm; hố; cất vào hầm; đưa vào hầm", "Hạng Tần Suất (Jun Da)": "3311.0", "Tần Suất % (Jun Da)": "99.4342267353", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窖", "Unihan_Traditional (Chữ Phồn thể)": "窖", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "giáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Dùng làm danh từ chỉ hầm đất hoặc làm động từ khi nói về việc lưu trữ lương thực dưới hầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戮', '{"9000": "3312.0", "Chữ Trung Quốc": "戮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 15 | nét | 翏 | (lieu) | bieu am | bieu am | 戈 | qua | bieu nghia | giao, binh khi | 戮 la chu hinh thanh: bo 戈 (qua, giao binh khi — bieu nghia) + 翏 (bieu am). Chi hanh dong giet chet bang vu khi, phanh thay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luc\": giao (戈) gia xuong — 杀戮 la tham sat; 戮力 la gop luc dong long. | Gương Hán-Việt | Luc trong sat luc (杀戮 — tham sat), luc luc (戮力 — gop suc dong long) | Mở khoá kiến thức | Biet 戮 mo khoa: 杀戮 (tham sat), 戮力 (gop suc), 残戮 (tan sat).", "Tự nguyên_Xie": "Tieu trieu | 戮 la chu hinh thanh gom 翏 lam bieu am va 戈 (giao, vu khi chien) lam bieu nghia. Nghia goc: giet chet roi phanh thay; lam nhuc. Mo rong: toan luc (cho luc 戮力 — gop suc). Co the lien quan den goc tu Sino-Tibetan, co the lien quan 劉 (sat). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giết rồi phanh thây; làm nhục", "Hạng Tần Suất (Jun Da)": "3312.0", "Tần Suất % (Jun Da)": "99.4348944217", "GavinGrover_Once (Chiết tự trực tiếp)": "翏 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰翏戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戮", "Unihan_Traditional (Chữ Phồn thể)": "剹", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường kết hợp với các động từ khác để tạo thành từ ghép chỉ hành vi giết chóc hoặc đồng lòng hiệp lực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祠', '{"9000": "3313.0", "Chữ Trung Quốc": "祠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 9 | nét | 礻 | (thi) | bieu nghia | than linh, te le | 司 | ti | bieu am | quan ly (bieu am) | 祠 la chu hinh thanh: bo 礻 (thi, than linh/te le — bieu nghia) + 司 (ti, bieu am). Chi mieu tho than hoac nha tho ho toc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tu\": 礻 (te than) + 司 (quan ly, bieu am) — tu mieu la noi tho cung than linh va to tien. | Gương Hán-Việt | Tu trong tu mieu (祠庙 — mieu tho), gia tu (家祠 — nha tho ho toc) | Mở khoá kiến thức | Biet 祠 mo khoa: 祠堂 (tu duong — nha tho ho toc), 宗祠 (tong tu — nha tho dong toc).", "Tự nguyên_Xie": "Tieu trieu | 祠 la chu hinh thanh gom 礻 (bo than, lien quan den te le) lam bieu nghia va 司 lam bieu am. Nghia goc: mieu tho than, nha tho ho toc; cung te. Mo rong sang dong tu: te, cung le. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miếu thờ thần, nhà thờ; cúng tế", "Hạng Tần Suất (Jun Da)": "3313.0", "Tần Suất % (Jun Da)": "99.4355615913", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 司", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻司", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "司", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祠", "Unihan_Traditional (Chữ Phồn thể)": "祠", "Pinyin_Xie": "cí", "Âm Hán Việt_Xie": "từ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ nơi thờ cúng tổ tiên và thần linh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞩', '{"9000": "3314.0", "Chữ Trung Quốc": "瞩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 目 | mục | biểu nghĩa | mắt | 属 | thuộc | biểu âm | (cho âm zhǔ) | 瞩 = 目 (Mục, biểu nghĩa: mắt) + 属 (Thuộc, biểu âm); chữ hình thanh. Bộ mục chỉ hoạt động nhìn; 属 cho âm zhǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chúc\": đôi mắt (目) thuộc (属) về một điểm — chúc mục, nhìn chăm chú không rời. | Gương Hán-Việt | \"chúc\" trong \"chúc mục\" (瞩目 — được chú ý), \"cao chiêm viễn chúc\" (nhìn xa trông rộng) | Mở khoá kiến thức | Biết 瞩 mở khoá 瞩目 (được chú ý), 举世瞩目 (cả thế giới chú ý), 高瞻远瞩 (nhìn xa trông rộng).", "Tự nguyên_Xie": "瞩 (phồn thể 矚) là chữ hình thanh: 目 (mục — mắt) biểu nghĩa; 属 (thuộc) biểu âm cho âm zhǔ. Wiktionary liệt kê nghĩa là nhìn chăm chú, tập trung ánh mắt vào. Chữ dùng chủ yếu trong văn viết, thường gặp trong thành ngữ 举世瞩目 (cả thế giới chú ý). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn kỹ, ngắm", "Hạng Tần Suất (Jun Da)": "3314.0", "Tần Suất % (Jun Da)": "99.4362251434", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 属", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目属", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "属", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞩", "Unihan_Traditional (Chữ Phồn thể)": "矚", "Pinyin_Xie": "zhǔ", "Âm Hán Việt_Xie": "chúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết và kết hợp với các từ chỉ tầm nhìn hoặc sự chú ý của mọi người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('菁', '{"9000": "3315.0", "Chữ Trung Quốc": "菁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艸 | thau | bieu nghia | co cay | 青 | thanh | bieu am | xanh (bieu am) | 菁 la chu hinh thanh: bo 艸 (thau, co cay — bieu nghia) + 青 (thanh, bieu am). Chi hoa co, mau sac tuoi tot cua co.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": co (艸) xanh (青) tinh khoi — 菁华 la tinh hoa, tinh tuy dep nhat. | Gương Hán-Việt | Tinh trong tinh hoa (菁华 — tinh tuy), mau tinh (茂菁 — tuoi tot um tum) | Mở khoá kiến thức | Biet 菁 mo khoa: 菁华 (tinh hoa, tinh tuy), 芜菁 (vu tinh — cu cai turnip).", "Tự nguyên_Xie": "Tieu trieu | 菁 la chu hinh thanh gom 艸 (co cay) lam bieu nghia va 青 (xanh) lam bieu am. Nghia goc: hoa co, hoa he, hoa cai; co xanh tuoi tot. Ngay nay hay dung trong ten ghep nhu 菁华 (tinh hoa) va 芜菁 (turnip). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: vu tinh 蕪菁,芜菁); hoa cỏ; rậm rạp tốt tươi", "Hạng Tần Suất (Jun Da)": "3315.0", "Tần Suất % (Jun Da)": "99.4368886955", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 青", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹青", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "青", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "菁", "Unihan_Traditional (Chữ Phồn thể)": "菁", "Pinyin_Xie": "jīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng trong văn chương để chỉ sự tươi tốt của cỏ cây hoặc ẩn dụ cho phần tinh túy nhất của sự vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躇', '{"9000": "3316.0", "Chữ Trung Quốc": "躇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 足 | tuc | bieu nghia | chan, buoc chan | 著 | trac | bieu am | bieu am | 躇 la chu hinh thanh: bo 足 (tuc, chan — bieu nghia) + 著 (trac, bieu am). Chi buoc chan do du, tro lai, di lui toi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\": chan (足) buoc di lui toi (著 bieu am) — 踌躇 (tru chu) la do du khong dam buoc toi. | Gương Hán-Việt | Chu trong tru chu (踌躇 — do du), tri tru (踟躇 — bien the cua do du) | Mở khoá kiến thức | Biet 躇 mo khoa: 踌躇 (do du), 踟躇 (bien the).", "Tự nguyên_Xie": "躇 la chu hinh thanh gom 足 (chan) lam bieu nghia va 著 lam bieu am. Nghia: di lui di toi, do du. Hau nhu chi dung trong 踌躇 (do du) va 踟躇 (bien the). | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "do dự; chần chừ", "Hạng Tần Suất (Jun Da)": "3316.0", "Tần Suất % (Jun Da)": "99.4375517308", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 著", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊著", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "著", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躇", "Unihan_Traditional (Chữ Phồn thể)": "躇", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "trừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Hầu như chỉ xuất hiện trong từ ghép trù trừ để diễn tả trạng thái do dự không quyết đoán trước một việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佬', '{"9000": "3317.0", "Chữ Trung Quốc": "佬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhan | bieu nghia | nguoi | 老 | lao | bieu am | gia (bieu am) | 佬 la chu hinh thanh: bo 亻 (nhan, nguoi — bieu nghia) + 老 (lao, gia — bieu am). Chi dan ong, ga, ten (thuong dung trong khau ngu, khong trang trong).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": nguoi (亻) gia lao (老 bieu am) — lo lao, ga lao, ten dan ong kieu thong tuc. | Gương Hán-Việt | Lao trong dai lao (大佬 — dai ca, thu linh), lao ngoai (佬外 — nguoi nuoc ngoai, tieng Quang) | Mở khoá kiến thức | Biet 佬 mo khoa: 大佬 (dai ca, thu linh), 老外 kieu noi the hien, 墨佬 (tay mo, nguoi do).", "Tự nguyên_Xie": "佬 la chu hinh thanh gom 亻 (nguoi) lam bieu nghia va 老 (gia) lam bieu am. Nghia: ga, ten, han, lo (khau ngu noi ve dan ong, co ve suong sa hoac miệt thi tuong ngu canh). Thuong gap trong tieng Quang va tieng dia phuong. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gã, lão, thằng cha, tên, hắn", "Hạng Tần Suất (Jun Da)": "3317.0", "Tần Suất % (Jun Da)": "99.4382147662", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 老", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻老", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "老", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佬", "Unihan_Traditional (Chữ Phồn thể)": "佬", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "lão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm hậu tố trong khẩu ngữ để chỉ một nhóm người hoặc một người đàn ông cụ thể với sắc thái bình dân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肋', '{"9000": "3318.0", "Chữ Trung Quốc": "肋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 6 | nét | 肉 | nhuc | bieu nghia | thit, phan co the | 力 | luc | bieu am | suc manh (bieu am) | 肋 la chu hinh thanh: bo 肉 (nhuc, thit/co the, viet tat la 月 — bieu nghia) + 力 (luc, bieu am). Chi xuong suon.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lac\": thit (月/肉) manh nhu luc (力 bieu am) — xuong suon bao ve tim phoi. | Gương Hán-Việt | Lac trong lac xuong (肋骨 — xuong suon), lac xuyen (肋痛 — dau suon) | Mở khoá kiến thức | Biet 肋 mo khoa: 肋骨 (xuong suon), 排骨 (suon heo), 肋膜 (mang suon).", "Tự nguyên_Xie": "Tieu trieu | 肋 la chu hinh thanh gom 肉 (月, phan co the) lam bieu nghia va 力 (suc, bieu am). Nghia goc: xuong suon, phan xuong hai ben long nguc. Xuong suon (肋骨) la cau truc nang do long nguc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương sườn", "Hạng Tần Suất (Jun Da)": "3318.0", "Tần Suất % (Jun Da)": "99.4388772847", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "力", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肋", "Unihan_Traditional (Chữ Phồn thể)": "肋", "Pinyin_Xie": "lē", "Âm Hán Việt_Xie": "lặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bộ phận xương sườn hoặc vùng mạn sườn của cơ thể người và động vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咄', '{"9000": "3319.0", "Chữ Trung Quốc": "咄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khau | bieu nghia | mieng, am thanh | 出 | xuat | bieu am | ra, thoat (bieu am) | 咄 la chu hinh thanh: bo 口 (khau, mieng — bieu nghia) + 出 (xuat, bieu am). Chi tieng than, tieng quát tháo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xot\": mieng (口) thot ra (出 bieu am) tieng than — 咄咄 la tieng ta than, giat minh kinh ngac. | Gương Hán-Việt | Xot trong xot xa (咄嗟 — than tho), xot turc (咄咄 — tieng ta than) | Mở khoá kiến thức | Biet 咄 mo khoa: 咄咄怪事 (chuyen ky la khon ta), 咄嗟 (than tho, trach cu).", "Tự nguyên_Xie": "Tieu trieu | 咄 la chu phuong ngu, am thanh — mieng (口) phat ra am tu (出 bieu am). Nghia: than tho, quát tháo; tieng the; oi chao (than tu). Thuong gap trong 咄咄怪事 (ky la qua suc) va tieng than ''oi chao''. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôi chao, than ôi (thán từ); tiếng quát tháo", "Hạng Tần Suất (Jun Da)": "3319.0", "Tần Suất % (Jun Da)": "99.4395398033", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 出", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口出", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咄", "Unihan_Traditional (Chữ Phồn thể)": "咄", "Pinyin_Xie": "duō", "Âm Hán Việt_Xie": "đốt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Động từ | 动词 | Chữ này thường dùng làm thán từ biểu thị sự kinh ngạc hoặc động từ chỉ hành động quát mắng. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忡', '{"9000": "3320.0", "Chữ Trung Quốc": "忡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忡 | sung | tuong hinh | lo lang, bun rang | 忡 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. Chu chi trang thai lo lang, bun rang, bat an.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sung\": 忡忡 la trang thai lo lang, nhu long nang triu (忧心忡忡 — lo lang muon phien). | Gương Hán-Việt | Sung trong uu tam sung sung (忧心忡忡 — lo lang muon phien, day long uu tu) | Mở khoá kiến thức | Biet 忡 mo khoa: 忧心忡忡 (lo lang muon phien), 忡忡 (bat an, bun rang).", "Tự nguyên_Xie": "Tieu trieu | 忡 khong co glyph origin chi tiet tu Wiktionary. Nghia: lo lang, bat an, bun rang. Thuong gap trong 忡忡 (lo lang, muon phien) va thanh ngu 忧心忡忡 (long tran day noi lo). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng", "Hạng Tần Suất (Jun Da)": "3320.0", "Tần Suất % (Jun Da)": "99.4401976707", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 中", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄中", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忡", "Unihan_Traditional (Chữ Phồn thể)": "忡", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "xung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ miêu tả trạng thái lo âu, thường dùng trong từ ghép như sung sung. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雍', '{"9000": "3321.0", "Chữ Trung Quốc": "雍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 13 | nét | 雍 | ung | tuong hinh | bien the cua 雝 — hoa hop, yen tinh | 雍 la bien the cua 雝. Theo Wiktionary, thanh phan phonetic 邕 bien dang thanh 玄 trong cac van tu tien Tan vi hinh dang giong nhau. Chu chi su hoa hop, yen tinh, thanh than.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ung\": ung dung — 雍容 la dang dap ung dung, thanh than quy phai. | Gương Hán-Việt | Ung trong ung dung (雍容 — ung dung, tu te), Ung Chinh (雍正 — ten vua Thanh trieu) | Mở khoá kiến thức | Biet 雍 mo khoa: 雍容 (ung dung, quy phai), 雍和 (hoa hop, yen thuan), 雍正 (ten vua Thanh).", "Tự nguyên_Xie": "Tieu trieu | 雍 la bien the cua 雝. Thanh phan bieu am 邕 (yong — vay quanh, hoa) bien dang thanh 玄 trong van tu tien Tan. Nghia: hoa hop, yen thuan; thanh than, hieu thuan. Cung dung lam ten dia danh (Chau Ung, mot trong chiu Chau thoi co). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "châu Ung (Trung Quốc)", "Hạng Tần Suất (Jun Da)": "3321.0", "Tần Suất % (Jun Da)": "99.4408550214", "GavinGrover_Once (Chiết tự trực tiếp)": "亠 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "雍", "Unihan_Traditional (Chữ Phồn thể)": "雍", "Pinyin_Xie": "yōng", "Âm Hán Việt_Xie": "ung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự hòa nhã hoặc làm danh từ chỉ tên đất đai thời cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('忱', '{"9000": "3322.0", "Chữ Trung Quốc": "忱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忱 | tham | tuong hinh | long thanh, chan that | 忱 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. Chu chi long than thanh, chan that, tinh cam that su.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tham\": tham long that su — 热忱 la nhiet tham, long nhiet tinh chan that. | Gương Hán-Việt | Tham trong nhiet tham (热忱 — nhiet tinh, han say), xa tham (谢忱 — biet on thanh that) | Mở khoá kiến thức | Biet 忱 mo khoa: 热忱 (nhiet tinh, han say), 谢忱 (cam on thanh that), 丹忱 (long dan thanh, trung thanh).", "Tự nguyên_Xie": "Tieu trieu | 忱 khong co glyph origin chi tiet tu Wiktionary. Nghia: long than thanh, chan that; tinh cam thuc. Thuong gap trong 热忱 (nhiet tam — nhiet tinh, han say) va 谢忱 (xa tam — bieu to long biet on). | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thực, đúng", "Hạng Tần Suất (Jun Da)": "3322.0", "Tần Suất % (Jun Da)": "99.441510305", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "忱", "Unihan_Traditional (Chữ Phồn thể)": "忱", "Pinyin_Xie": "chén", "Âm Hán Việt_Xie": "thầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ tấm lòng thành hoặc tính từ chỉ sự chân thành. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕾', '{"9000": "3323.0", "Chữ Trung Quốc": "蕾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 雷 | lôi | biểu âm | (cho âm lěi) | 蕾 = 艹 (Thảo, biểu nghĩa: thực vật) + 雷 (Lôi, biểu âm); chữ hình thanh. Bộ thảo chỉ thuộc thực vật; 雷 cho âm lěi gần với lôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": cỏ cây (艹) ẩn chứa sức mạnh như sấm lôi (雷) — nụ hoa cuộn tròn, sắp bùng nở. | Gương Hán-Việt | \"lôi\" trong \"bội lôi\" (蓓蕾 — nụ hoa); \"lôi\" còn trong 雷 (sấm) | Mở khoá kiến thức | Biết 蕾 mở khoá 蓓蕾 (nụ hoa), 花蕾 (nụ hoa), 芭蕾 (ballet — phiên âm), 味蕾 (gai vị giác).", "Tự nguyên_Xie": "蕾 là chữ hình thanh: bộ 艹 (thảo) biểu nghĩa, chỉ thuộc về thực vật; 雷 (lôi — sấm) cho âm. Wiktionary xếp âm đọc là lěi, nghĩa là nụ hoa chưa nở. Không có ghi chú về nguồn gốc cổ đại chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bội lôi 蓓蕾)", "Hạng Tần Suất (Jun Da)": "3323.0", "Tần Suất % (Jun Da)": "99.4421655885", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 雷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹雷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕾", "Unihan_Traditional (Chữ Phồn thể)": "蕾", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nụ hoa, thường kết hợp thành từ ghép như hoa lôi, bội lôi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跄', '{"9000": "3324.0", "Chữ Trung Quốc": "跄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 11 | nét | 跄 | thuong | tuong hinh | di lao dao | 跄 la chu doc lap (gian the cua 蹌/踉蹌). Khong co phan tich cau truc ro rang tu Wiktionary. Chi dang di lao dao, choang vang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuong\": 踉跄 la dang di lao dao, choang choang, nhu nguoi say ruou. | Gương Hán-Việt | Thuong trong luong thuong (踉跄 — lao dao, choang vang) | Mở khoá kiến thức | Biet 跄 mo khoa: 踉跄 (lao dao, choang vang), 踉踉跄跄 (di lao dao khap noi).", "Tự nguyên_Xie": "跄 khong co glyph origin chi tiet tu Wiktionary. Nghia: di lao dao, di choang, buoc chon vun. Thuong gap trong 踉踉跄跄 (di lao dao khong vung) va 趋跄 (di nhanh, di oai ve — nghia co). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đi lảo đảo", "Hạng Tần Suất (Jun Da)": "3324.0", "Tần Suất % (Jun Da)": "99.4428193217", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跄", "Unihan_Traditional (Chữ Phồn thể)": "蹌", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ dáng đi không vững, thường dùng trong từ ghép thương lượng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('硅', '{"9000": "3325.0", "Chữ Trung Quốc": "硅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 11 | nét | 硅 | quy | tuong hinh | nguyen to silic, Si | 硅 la chu tao muon (hau ky tu — 後起字) de ghi ten nguyen to hoa hoc Silicon (Si). Khong co phan tich cau truc hay glyph origin tu Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quy\": Silicon (硅) la nen tang cua chip may tinh — quy gia nhu ngoc quy trong nen cong nghiep hien dai. | Gương Hán-Việt | Quy trong silicon (硅 — Si), quy goc (硅基 — silicon-based) | Mở khoá kiến thức | Biet 硅 mo khoa: 硅谷 (Silicon Valley — Thung Lung Silicon), 硅芯片 (silicon chip), 二氧化硅 (SiO2 — silica).", "Tự nguyên_Xie": "硅 la chu tao muon, khong co glyph origin hoc thuat. Chu duoc tao ra de phien am va dich nguyen to Silicon (Si). Nghia: nguyen to 14 trong bang tuan hoan, thieu so chu yeu trong vo Trai Dat, nen tang cua cong nghiep ban dan tu (silicon chip). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc khuê; nguyên tố silic, Si", "Hạng Tần Suất (Jun Da)": "3325.0", "Tần Suất % (Jun Da)": "99.4434725381", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "硅", "Unihan_Traditional (Chữ Phồn thể)": "硅", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học silic trong khoa học hiện đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伎', '{"9000": "3326.0", "Chữ Trung Quốc": "伎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 人 | nhan | bieu nghia | nguoi | 支 | chi | bieu am | nhanh, do (bieu am) | 伎 la chu hinh thanh: bo 亻 (nhan, nguoi — bieu nghia) + 支 (chi, bieu am). Chi ky nang, thi thuat; ca nu, vu nu thoi xua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ki\": nguoi (亻) co ky thuat (支 bieu am) — 伎俩 la muu meo, tro thu doan. | Gương Hán-Việt | Ki trong ki luong (伎俩 — muu meo, tro thu doan) | Mở khoá kiến thức | Biet 伎 mo khoa: 伎俩 (muu meo, thu doan), 伎艺 (ky thuat bieu dien).", "Tự nguyên_Xie": "Tieu trieu | 伎 la chu hinh thanh gom 人 (亻, nguoi) lam bieu nghia va 支 lam bieu am. Nghia goc: ky nang, ban linh; ve sau chi ca nu, vu nu bieu dien thoi co. Co lien quan den 技 (ky nang). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kỹ năng; bản lĩnh; ca nhi; vũ nữ (thời xưa)", "Hạng Tần Suất (Jun Da)": "3326.0", "Tần Suất % (Jun Da)": "99.4441257545", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伎", "Unihan_Traditional (Chữ Phồn thể)": "伎", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tài năng, bản lĩnh hoặc người làm nghề ca hát thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炊', '{"9000": "3327.0", "Chữ Trung Quốc": "炊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu nghĩa | lửa | 欠 | khiếm | biểu âm | (rút từ 吹, cho âm chuī) | 炊 = 火 (Hoả, biểu nghĩa: lửa) + 欠 (rút gọn từ 吹/Xuy, biểu âm); chữ hình thanh. Lửa là yếu tố nghĩa, phần âm cho âm chuī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuy\": lửa (火) và hơi thở (欠/吹) — xuy phong thổi lửa, nấu cơm chín. | Gương Hán-Việt | \"xuy\" trong \"dã xuy\" (野炊 — nấu ăn ngoài trời), \"xuy yên\" (khói bếp) | Mở khoá kiến thức | Biết 炊 mở khoá 野炊 (cắm trại nấu ăn ngoài trời), 炊烟 (khói bếp), 炊具 (dụng cụ nấu ăn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 炊 là chữ hình thanh: 火 (hoả — lửa) biểu nghĩa; 吹 (xuy — thổi, rút gọn thành 欠) cho âm chuī. Theo Wiktionary, nghĩa gốc là nấu chín bằng lửa, thường là nấu cơm hoặc thổi lửa nấu ăn. Hình ảnh thổi lửa để nấu ăn là nguồn gốc của chữ này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nấu chín", "Hạng Tần Suất (Jun Da)": "3327.0", "Tần Suất % (Jun Da)": "99.4447779374", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炊", "Unihan_Traditional (Chữ Phồn thể)": "炊", "Pinyin_Xie": "chuī", "Âm Hán Việt_Xie": "xuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc đun nấu, thường đi kèm với các danh từ chỉ thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钊', '{"9000": "3328.0", "Chữ Trung Quốc": "钊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 7 | nét | 钊 | trieu | tuong hinh | dong vien, khuyen khich; ten nguoi | 钊 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. Chu chu yeu dung lam ten nguoi hoac trong cac tu chua co nghia hien dai pho bien.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trieu\": 钊 thuong gap trong ten nguoi nhu Li Zhao, Wang Zhao — goi len y khuyen khich, dong vien. | Gương Hán-Việt | Trieu trong Li Trieu (李钊 — ten nguoi, nhu Li Dazhao — Ly Dai Trieu) | Mở khoá kiến thức | Biet 钊 mo khoa: ten nguoi nhu 李大钊 (Ly Dai Trieu — co nhan Trung Quoc), 钊励 (khuyen khich).", "Tự nguyên_Xie": "Tieu trieu | 钊 khong co glyph origin chi tiet tu Wiktionary. Nghia: dong vien, khuyen khich (nghia co); chu yeu ngay nay dung lam ten nguoi. Co the la chu tao muon hoac chu phuong ngu. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyến khích, động viên", "Hạng Tần Suất (Jun Da)": "3328.0", "Tần Suất % (Jun Da)": "99.4454296034", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钊", "Unihan_Traditional (Chữ Phồn thể)": "釗", "Pinyin_Xie": "zhāo", "Âm Hán Việt_Xie": "chiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ mang nghĩa khuyến khích, cổ vũ hoặc mài cho sắc bén. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝠', '{"9000": "3329.0", "Chữ Trung Quốc": "蝠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 虫 | trung | bieu nghia | loai trung, con vat | 畐 | (phuc) | bieu am | bieu am phuc | 蝠 la chu hinh thanh: bo 虫 (trung, loai con vat — bieu nghia) + 畐 (phuc, bieu am). Chi con doi. Con doi am phat tuong dong voi 福 (phuc) trong tieng Trung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phuc\": con trung (虫) bay dem (畐 bieu am) — 蝙蝠 (bien phuc) la con doi, bien tuong cho 福 phuc khi. | Gương Hán-Việt | Phuc trong bien phuc (蝙蝠 — con doi), wu phuc (五蝠 — ngu phuc, bien tuong may man) | Mở khoá kiến thức | Biet 蝠 mo khoa: 蝙蝠 (con doi), 蝙蝠侠 (Batman), 五蝠临门 (ngu phuc mon — bieu tuong may man).", "Tự nguyên_Xie": "Tieu trieu | 蝠 la chu hinh thanh gom 虫 (con vat) lam bieu nghia va 畐 lam bieu am. Nghia: con doi (Chiroptera). Con doi trong van hoa Trung Quoc la bieu tuong may man vi am 蝠 (fu) dong am voi 福 (fu — phuc). Co the co tien than la chu tuong hinh con doi trong giap cot. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: biển bức 蝙蝠)", "Hạng Tần Suất (Jun Da)": "3329.0", "Tần Suất % (Jun Da)": "99.4460802359", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 畐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫畐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝠", "Unihan_Traditional (Chữ Phồn thể)": "蝠", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "bức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con dơi, hầu như luôn xuất hiện trong từ ghép biển bức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屎', '{"9000": "3330.0", "Chữ Trung Quốc": "屎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 尸 | Số nét | 9 | nét | 尸 | thi | bieu nghia | co the nguoi | 米 | mieu | bieu nghia | hat, bien the cua ba cham bieu hien chat thai | 屎 la chu hoi y: 尸 (thi, co the nguoi) + 米 (bien the cua cac diem nho trong giap cot, bieu hien chat thai ra khoi co the). Chinh la chu tuong hinh/hoi y cua giap cot.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": 尸 (nguoi cuoi) + cac diem (chat thai) — phuc thi, si co nghia chat thai. | Gương Hán-Việt | Si trong si co (屎壳 — vo cung trung phan), nguu si (牛屎 — phan bo) | Mở khoá kiến thức | Biet 屎 mo khoa: 屎壳郎 (bun dai — co cung trung lan phan), 狗屎 (phan cho), 一团糟/狗屎运 (van may phi ly).", "Tự nguyên_Xie": "Tieu trieu | Trong giap cot, 米 o day ban dau la ba, bon, hoac nam cham nho (小/少) bieu hien chat thai. Hinh tuong: nguoi cuoi xuong (尸) tiet chat thai (cac diem). Thuyet Van phan tich la hinh thanh (尸 bieu am + 米 bieu nghia) nhung goc giap cot cho thay la hoi y/tuong hinh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phân, cứt", "Hạng Tần Suất (Jun Da)": "3330.0", "Tần Suất % (Jun Da)": "99.4467298348", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴尸米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "屎", "Unihan_Traditional (Chữ Phồn thể)": "屎", "Pinyin_Xie": "shǐ", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chất thải bài tiết hoặc chất bẩn bám ở các cơ quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拭', '{"9000": "3331.0", "Chữ Trung Quốc": "拭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | ⺘ | (thu) | bieu nghia | tay (gian the cua 手) | 式 | thuc | bieu am | kieu mau (bieu am) | 拭 la chu hinh thanh: bo 扌 (thu, tay — bieu nghia) + 式 (thuc, bieu am). Chi hanh dong lau, chua, lam sach bang tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ri\": tay (扌) lau sach theo kieu (式 bieu am) — 拭目以待 la lap tay che mat cho doi ket qua. | Gương Hán-Việt | Ri trong ri moc (拭目 — lau mat, trong doi), ri le (拭泪 — lau nuoc mat) | Mở khoá kiến thức | Biet 拭 mo khoa: 拭目以待 (lat mat cho doi), 拭去 (lau di), 拭泪 (lau nuoc mat).", "Tự nguyên_Xie": "Tieu trieu | 拭 la chu hinh thanh gom 扌 (tay) lam bieu nghia va 式 lam bieu am. Nghia goc: lau, chua sach bang tay hoac khan. Thuong dung trong van chu trang trong nhu 拭目以待 (cho doi den nong long, lat mat xem). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "601.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Thức (600)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủ (số 064 - cái tay) ở bên trái chữ Thức (số 600 - phép tắc). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Thức (quy củ) chỉ âm, bộ Thủ (tay) chỉ ý. Dùng tay lau chùi theo đúng phép tắc, quy củ gọi là Thức (lau chùi).", "Nghĩa Tiếng Việt_Xie": "lau chùi", "Hạng Tần Suất (Jun Da)": "3331.0", "Tần Suất % (Jun Da)": "99.4473794337", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 式", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌式", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "式", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拭", "Unihan_Traditional (Chữ Phồn thể)": "拭", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật cần lau chùi như nước mắt hoặc bụi bẩn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谛', '{"9000": "3332.0", "Chữ Trung Quốc": "谛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngon | bieu nghia | loi noi, ngon ngu | 帝 | de | bieu am | vua (bieu am) | 谛 la chu hinh thanh: bo 言 (ngon, loi noi — bieu nghia) + 帝 (de, bieu am). Chi su xet ky, lan nghe ky; chan ly, co so.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"de\": loi noi (言) cua vua de (帝 bieu am) — dang de (谛听) la lang nghe can than, lang nghe cap den su that. | Gương Hán-Việt | De trong de nghe (谛听 — lang nghe cap den), tu de (四谛 — bon chan ly Phat giao) | Mở khoá kiến thức | Biet 谛 mo khoa: 谛听 (lang nghe cap den), 真谛 (chan de — chan ly sau sac), 四谛 (tu de — Phat giao).", "Tự nguyên_Xie": "Tieu trieu | 谛 la chu hinh thanh gom 言 (loi noi) lam bieu nghia va 帝 lam bieu am. Nghia goc: xet ky, lang nghe cap den; chan ly, ban chat. Trong Phat giao: 谛 la sat-de (chan ly) nhu Tu de (四谛 — bon chan ly). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xét kỹ", "Hạng Tần Suất (Jun Da)": "3332.0", "Tần Suất % (Jun Da)": "99.4480290327", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 帝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠帝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "帝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谛", "Unihan_Traditional (Chữ Phồn thể)": "諦", "Pinyin_Xie": "dì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong triết học, Phật giáo hoặc làm động từ với nghĩa quan sát kỹ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褪', '{"9000": "3333.0", "Chữ Trung Quốc": "褪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 14 | nét | 衣 | y | bieu nghia | quan ao | 退 | thoai | bieu am | lui (bieu am) | 褪 la chu hinh thanh: bo 衤 (y, quan ao — bieu nghia) + 退 (thoai, lui — bieu am). Chi hanh dong coi ao ra; mau phai, cay ta, suy dan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoai\": quan ao (衤) thoai lui (退 bieu am) — mau ao phai thoai, hoa ta cap, su kien lan lui. | Gương Hán-Việt | Thoai trong thoai sac (褪色 — phai mau), thoai dao (褪掉 — coi ra, lột ra) | Mở khoá kiến thức | Biet 褪 mo khoa: 褪色 (phai mau), 褪去 (coi ra, tan di), 褪掉 (lột bỏ).", "Tự nguyên_Xie": "褪 la chu hinh thanh gom 衣 (衤, quan ao) lam bieu nghia va 退 (lui) lam bieu am. Nghia: coi ao ra; mau phai (褪色 — phai mau); cay hoa ta cap; suy giam dan. La 後起字 — chu tao muon. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cởi áo ra; hoa tàn; suy kém dần; đi giật lùi", "Hạng Tần Suất (Jun Da)": "3333.0", "Tần Suất % (Jun Da)": "99.4486781148", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 退", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤退", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "退", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褪", "Unihan_Traditional (Chữ Phồn thể)": "褪", "Pinyin_Xie": "tuì", "Âm Hán Việt_Xie": "thoái, thối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ quần áo hoặc màu sắc để biểu thị sự cởi bỏ hoặc phai nhạt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丞', '{"9000": "3334.0", "Chữ Trung Quốc": "丞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 一 | Số nét | 6 | nét | 卩 | (tiep) | bieu nghia | nguoi cong cuoi | 廾 | trap | bieu nghia | hai tay | 凵 | (ham) | bieu nghia | hoc, cai ho | 丞 la chu hoi y: 卩 (nguoi cong cuoi/nguoi te) + 廾 (hai tay) + 凵 (cai ho) — hinh tuong nguoi dung hai tay vu len keo nguoi khac ra khoi ho. Nghia goc: cuu giup, to tro.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thua\": hai tay (廾) keo nguoi (卩) ra khoi ho (凵) — thua tuong la nguoi do tro, giup suc nha vua. | Gương Hán-Việt | Thua trong thua tuong (丞相 — chuc thua tuong, giup vua tri quoc) | Mở khoá kiến thức | Biet 丞 mo khoa: 丞相 (thua tuong — chuc quan cao nhat giup vua), 县丞 (huyen thua — pho huyen truong).", "Tự nguyên_Xie": "Tieu trieu | 丞 la chu hoi y theo Wiktionary: 卩 (nguoi te, cong cuoi) + 廾 (hai tay) + 凵 (cai ho/lo dat) — hinh anh nguoi dung hai tay keo mot nguoi dang roi xuong ho. Nghia goc: cuu giup, do do. Mo rong sang chuc quan: thua tuong (丞相). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giúp đỡ", "Hạng Tần Suất (Jun Da)": "3334.0", "Tần Suất % (Jun Da)": "99.4493261633", "GavinGrover_Once (Chiết tự trực tiếp)": "氶 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱氶一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "丞", "Unihan_Traditional (Chữ Phồn thể)": "丞", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "thừa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ chức vụ phụ tá thời phong kiến hoặc làm động từ trợ giúp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卉', '{"9000": "3335.0", "Chữ Trung Quốc": "卉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 5 | nét | 卉 | huy | tuong hinh | co cay (chu doc lap) | 卉 la chu doc lap, la chu goc chi co cay noi chung. Wiktionary chi co tieu thuan khong co glyph origin chi tiet.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": huy tinh — 花卉 (hoa huy) la hoa co, thao moc; biet chu nay mo khoa the gioi thuc vat. | Gương Hán-Việt | Huy trong hoa huy (花卉 — hoa co, thao moc), bach huy (百卉 — tram loai co hoa) | Mở khoá kiến thức | Biet 卉 mo khoa: 花卉 (hoa co, thao moc), 百卉 (tram loai co), 奇花异卉 (nhieu loai hoa la co la).", "Tự nguyên_Xie": "Tieu trieu | 卉 khong co glyph origin chi tiet tu Wiktionary. La chu co, chi cac loai co cay, thao moc. Ngay nay hay dung trong tu ghep 花卉 (hoa huy — hoa va co, thao moc). La tu vung trong van chuong. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "282.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình ảnh ba ngọn cỏ mọc lên để chỉ ý rằng có rất nhiều cây cỏ (cây cỏ nói chung).", "Nghĩa Tiếng Việt_Xie": "chỉ các thứ cỏ", "Hạng Tần Suất (Jun Da)": "3335.0", "Tần Suất % (Jun Da)": "99.4499736951", "GavinGrover_Once (Chiết tự trực tiếp)": "十 + 艹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱十艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "卉", "Unihan_Traditional (Chữ Phồn thể)": "卉", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "huỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các danh từ khác tạo thành từ ghép chỉ các loại thực vật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隧', '{"9000": "3336.0", "Chữ Trung Quốc": "隧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 14 | nét | 阝 | phụ | biểu nghĩa | gò đất, địa hình | 遂 | toại | biểu âm | (cho âm suì) | 隧 = 阝(Phụ, biểu nghĩa: địa hình, gò đất) + 遂 (Toại, biểu âm); chữ hình thanh. Bộ phụ (阝bên trái) chỉ địa thế; 遂 cho âm suì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toại\": địa hình (阝) dẫn theo đường toại (遂) — đường hầm xuyên lòng đất, dẫn thẳng đến đích. | Gương Hán-Việt | \"toại\" trong \"toại đạo\" (隧道 — đường hầm) | Mở khoá kiến thức | Biết 隧 mở khoá 隧道 (đường hầm, tunnel), 隧洞 (hầm xuyên núi).", "Tự nguyên_Xie": "隧 là chữ hình thanh: bộ 阝(phụ — gò đất, địa hình) biểu nghĩa, chỉ một thứ đào vào lòng đất; 遂 (toại) cho âm. Nghĩa gốc là đường hầm đào dưới đất, ban đầu chỉ đường dẫn vào lăng mộ. Wiktionary ghi nghĩa là tunnel, underground passageway. Chưa có nguồn cổ đại chi tiết hơn trong anchor. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đường hầm", "Hạng Tần Suất (Jun Da)": "3336.0", "Tần Suất % (Jun Da)": "99.4506207101", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 遂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝遂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隧", "Unihan_Traditional (Chữ Phồn thể)": "隧", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "toại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ địa hình để tạo thành danh từ ghép chỉ đường hầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茸', '{"9000": "3337.0", "Chữ Trung Quốc": "茸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | thau | bieu nghia | co cay | 聰 | thong | bieu am | bieu am (viet tat cua Thong) | 茸 la chu hinh thanh: bo 艸 (thau, co cay — bieu nghia) + 聰 (thong, viet tat/bien the — bieu am) theo Thuyet Van. Chi long to, nhung mat; sung non cua huou.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhung\": co (艸) mem min nhung nhung — 鹿茸 (nhung huou) la sung non mem cua huou, rat quy. | Gương Hán-Việt | Nhung trong nhung huou (鹿茸 — sung non huou quang vinh), nhung nhung (茸茸 — to mem, day dac) | Mở khoá kiến thức | Biet 茸 mo khoa: 鹿茸 (nhung huou — duoc lieu quy), 茸茸 (to, mem, day dac), 绒茸 (nhung mo).", "Tự nguyên_Xie": "Tieu trieu | 茸 la chu hinh thanh theo Thuyet Van: 艸 (co cay) lam bieu nghia va 聰 viet tat lam bieu am. Nghia goc: co to, la moc day; mo rong sang sung non (nhung huou 鹿茸 — sung huou chua truong thanh, duoc lieubao gia), long to, min. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sừng mới nhú của con hươu", "Hạng Tần Suất (Jun Da)": "3337.0", "Tần Suất % (Jun Da)": "99.4512651412", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茸", "Unihan_Traditional (Chữ Phồn thể)": "茸", "Pinyin_Xie": "rōng", "Âm Hán Việt_Xie": "nhung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ lộc nhung hoặc làm tính từ mô tả trạng thái mềm mại của lông cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钳', '{"9000": "3338.0", "Chữ Trung Quốc": "钳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钳 | kiem | tuong hinh | cai kim, cung cum (doc lap) | 钳 la chu doc lap theo goc khai thac tu Wiktionary. Khong co phan tich cau truc ro rang. Chi cai kim kep, cung cap; hanh dong kep lai, cum vao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiem\": 钳子 (kim kep) kep chat nhu cang cua — kiet kiem, cam cum. | Gương Hán-Việt | Kiem trong kiem tu (钳子 — cai kim kep), kiem xa (钳夹 — kep chat) | Mở khoá kiến thức | Biet 钳 mo khoa: 钳子 (kim kep — dung cu), 钳制 (kiem che — kiem soat, can tro).", "Tự nguyên_Xie": "钳 khong co glyph origin chi tiet tu Wiktionary. Nghia: cai kim kep, cang cua dong vat (cua, tom); cung, cum, kep lai. Chu tao muon, chua xac minh duoc van tu co. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kìm; giữ, kìm; cùm chân", "Hạng Tần Suất (Jun Da)": "3338.0", "Tần Suất % (Jun Da)": "99.4519075051", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钳", "Unihan_Traditional (Chữ Phồn thể)": "鉗", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ công cụ kẹp hoặc làm động từ biểu thị hành động kẹp chặt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啃', '{"9000": "3339.0", "Chữ Trung Quốc": "啃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 肯 | khẳng | biểu âm | (cho âm kěn) | 啃 = 口 (Khẩu, biểu nghĩa: miệng) + 肯 (Khẳng, biểu âm); chữ hình thanh. Miệng là bộ phận thực hiện hành động gặm; 肯 cho âm kěn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khẳng\": miệng (口) khẳng định từng chút — khẳng nhấm, gặm kiên nhẫn từng phần. | Gương Hán-Việt | \"khẳng\" ít dùng độc lập; 肯 (khẳng) nghĩa là chịu, đồng ý | Mở khoá kiến thức | Biết 啃 mở khoá cách dùng ẩn dụ: 啃书 (chúi đầu vào sách), 啃老 (dựa vào bố mẹ), 硬骨头好啃 (xương cứng khó gặm — việc khó).", "Tự nguyên_Xie": "啃 là chữ hình thanh: 口 (khẩu — miệng) biểu nghĩa, chỉ hành động liên quan đến miệng; 肯 (khẳng) cho âm kěn. Nghĩa là gặm, nhấm từng chút một bằng răng, như gặm xương hay gặm sách (ẩn dụ học tập chăm chỉ). Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gặm, nhấm", "Hạng Tần Suất (Jun Da)": "3339.0", "Tần Suất % (Jun Da)": "99.4525493522", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 肯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口肯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啃", "Unihan_Traditional (Chữ Phồn thể)": "啃", "Pinyin_Xie": "kěn", "Âm Hán Việt_Xie": "khẳng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ thức ăn cứng hoặc nghĩa bóng là nghiên cứu tài liệu khó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kěn | / | gặm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II | HSK | HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('伢', '{"9000": "3340.0", "Chữ Trung Quốc": "伢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 6 | nét | 伢 | nha | tuong hinh | tre con (chu doc lap phuong ngu) | 伢 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. La tu phuong ngu (Hue Ngu, Cam Ngu) chi tre con, em be.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nha\": 伢 la tieng phuong ngu chi tre con nha (nhan) — em be, con tre. | Gương Hán-Việt | Nha trong tieu nha (小伢 — em be, tre con — phuong ngu Hue Ngu) | Mở khoá kiến thức | Biet 伢 mo khoa: 小伢儿 (em be, tre con — phuong ngu), 伢子 (con trai nho).", "Tự nguyên_Xie": "伢 khong co glyph origin hoc thuat. La chu phuong ngu cac vung Giang To, An Huy, Hue Ngu chi tre con, em be. Khong co nguon van tu co. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trẻ con; trẻ em", "Hạng Tần Suất (Jun Da)": "3340.0", "Tần Suất % (Jun Da)": "99.4531911994", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 牙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻牙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "伢", "Unihan_Traditional (Chữ Phồn thể)": "伢", "Pinyin_Xie": "yá", "Âm Hán Việt_Xie": "nha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong khẩu ngữ hoặc phương ngôn để chỉ trẻ con. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闺', '{"9000": "3341.0", "Chữ Trung Quốc": "闺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 門 | mon | bieu nghia | cua, cong | 圭 | que | bieu am | ngoc bai nhon hai dau (bieu am) | 闺 la chu hinh thanh (va co the la hoi y): 門 (mon, cua — bieu nghia) + 圭 (que, ngoc bai — bieu am). Cua cong tron tren vuong duoi, hinh dang giong ngoc bai 圭. Chi can phong con gai, khue phong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khue\": cua (門) hinh ngoc bai (圭 bieu am) — khue phong la can phong the nu, khuong khue tuc la trinh nu. | Gương Hán-Việt | Khue trong khue nu (闺女 — con gai, co gai), khue phong (闺房 — phong the nu) | Mở khoá kiến thức | Biet 闺 mo khoa: 闺女 (con gai, co gai), 闺房 (phong the nu), 闺蜜 (ban gai than thiet), 深闺 (trong khue phong — bi dat, noi sam).", "Tự nguyên_Xie": "Tieu trieu | 闺 (phon the: 閨) la chu hinh thanh: 門 (cua) lam bieu nghia va 圭 (ngoc bai nhon) lam bieu am. Nghia goc: cua cong tron (nho) trong cung cam; mo rong sang khue phong (can phong cua tieu thu, phu nu quy toc). Cau truc cung co the la hoi y — cua co hinh dang giong 圭. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa tò vò (cửa trên tròn dưới vuông); khuê phòng (chỗ con gái ở)", "Hạng Tần Suất (Jun Da)": "3341.0", "Tần Suất % (Jun Da)": "99.4538299458", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 圭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门圭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闺", "Unihan_Traditional (Chữ Phồn thể)": "閨", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với các danh từ khác để chỉ những thứ liên quan đến phụ nữ chưa chồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('舔', '{"9000": "3342.0", "Chữ Trung Quốc": "舔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 舌 | Số nét | 14 | nét | 舌 | thiệt | biểu nghĩa | lưỡi | 忝 | thiểm | biểu âm | (cho âm tiǎn) | 舔 = 舌 (Thiệt, biểu nghĩa: lưỡi) + 忝 (Thiểm, biểu âm); chữ hình thanh. Lưỡi là cơ quan thực hiện hành động liếm; 忝 cho âm tiǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiểm\": lưỡi (舌) thiểm qua — thiểm lướt nhẹ, hành động liếm thoáng qua. | Gương Hán-Việt | \"thiểm\" ít dùng độc lập; 忝 (thiểm) có nghĩa xấu hổ, nhục nhã | Mở khoá kiến thức | Biết 舔 mở khoá 舔食 (liếm thức ăn), 舔伤口 (liếm vết thương — ẩn dụ xoa dịu tổn thương).", "Tự nguyên_Xie": "舔 là chữ hình thanh: 舌 (thiệt — lưỡi) biểu nghĩa, chỉ rõ hành động dùng lưỡi; 忝 (thiểm) cho âm tiǎn. Nghĩa là liếm, dùng lưỡi để lấy hoặc nếm. Wiktionary xác nhận cấu trúc hình thanh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếm", "Hạng Tần Suất (Jun Da)": "3342.0", "Tần Suất % (Jun Da)": "99.4544686922", "GavinGrover_Once (Chiết tự trực tiếp)": "舌 + 忝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰舌忝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "忝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "舌", "Unihan_Simplified (Chữ Giản thể)": "舔", "Unihan_Traditional (Chữ Phồn thể)": "舔", "Pinyin_Xie": "tiǎn", "Âm Hán Việt_Xie": "thiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận cơ thể hoặc đồ ăn để biểu thị hành động liếm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹬', '{"9000": "3343.0", "Chữ Trung Quốc": "蹬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 𧾷 | biểu nghĩa | chân (bộ túc biến thể, gồm 口+止) | 登 | đăng | biểu âm | (cho âm dēng) | 蹬 = 足(biến thể 𧾷, biểu nghĩa: chân) + 登 (Đăng, biểu âm); chữ hình thanh. Bộ túc chỉ hành động liên quan đến chân; 登 cho âm dēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đặng\": chân (足) đặng lên như leo (登) — đặng một bước, đạp lên phía trước. | Gương Hán-Việt | \"đặng\" trong \"đặng lên\" (đạp, bước lên); 登 (đăng) trong 登山 (leo núi) | Mở khoá kiến thức | Biết 蹬 mở khoá 蹬自行车 (đạp xe đạp), 蹬腿 (duỗi chân, đạp chân), 刁蹬 (khó tính, phức tạp).", "Tự nguyên_Xie": "Tiểu triện | 蹬 là chữ hình thanh: bộ 足 (biến thể 𧾷 — chân) biểu nghĩa, chỉ hành động của chân; 登 (đăng) cho âm. Nghĩa là đạp, giẫm lên, hoặc mang (giày). Wiktionary dẫn ví dụ cổ từ Hồng lâu mộng về hành động đứng tựa vào bậc cửa. Cũng dùng nghĩa đạp xe. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bước vào", "Hạng Tần Suất (Jun Da)": "3343.0", "Tần Suất % (Jun Da)": "99.4551058883", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹬", "Unihan_Traditional (Chữ Phồn thể)": "蹬", "Pinyin_Xie": "dēng", "Âm Hán Việt_Xie": "đăng, đặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ chỉ nơi chốn hoặc phương tiện để biểu thị hành động đạp hoặc giẫm lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dēng | / | đạp | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Phong trào I | HSK | HSK 6 | · | Sự chuyển động", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挛', '{"9000": "3344.0", "Chữ Trung Quốc": "挛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 挛 | loan | tuong hinh | buoc lai, co rut (chu doc lap) | 挛 la chu doc lap, khong co phan tich cau truc ro rang tu Wiktionary. Chi su co rut, buoc chat lai; bap thit bi co that.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": 挛 bap thit co rut loan lon — 痉挛 la co giat, co rut bat dieu kien. | Gương Hán-Việt | Loan trong co loan (痉挛 — co giat), loan rut (挛缩 — co rut lai) | Mở khoá kiến thức | Biet 挛 mo khoa: 痉挛 (co giat — spasm), 挛缩 (co rut lai), 孪生 (sinh doi — lien he den 挛 = buoc ket).", "Tự nguyên_Xie": "Tieu trieu | 挛 khong co glyph origin chi tiet tu Wiktionary. Nghia: buoc lai, ket lai; co rut (bap thit). Thuong gap trong 痉挛 (co giat, co rut) va 挛缩 (co rut lai). Chu tao muon. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buộc; co lại", "Hạng Tần Suất (Jun Da)": "3344.0", "Tần Suất % (Jun Da)": "99.455741534", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "挛", "Unihan_Traditional (Chữ Phồn thể)": "攣", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "luyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ chỉ sự co rút cơ thịt hoặc làm tính từ trong các thuật ngữ y học. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眺', '{"9000": "3345.0", "Chữ Trung Quốc": "眺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | muc | bieu nghia | mat | 兆 | trieu | bieu am | trieu, cuong (bieu am) | 眺 la chu hinh thanh: bo 目 (muc, mat — bieu nghia) + 兆 (trieu, bieu am). Chi hanh dong trong den xa, ngam nhin tu xa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thieu\": mat (目) trong den trieu xa (兆 bieu am) — 眺望 la ngam nhin canh troi dat xa xa. | Gương Hán-Việt | Thieu trong thieu vong (眺望 — trong ngong xa xa), vien thieu (远眺 — trong ra xa) | Mở khoá kiến thức | Biet 眺 mo khoa: 眺望 (trong ngong xa xa), 远眺 (trong ra xa tu tren cao), 纵目远眺 (buong tam mat trong xa).", "Tự nguyên_Xie": "Tieu trieu | 眺 la chu hinh thanh gom 目 (mat) lam bieu nghia va 兆 (trieu) lam bieu am. Nghia goc: lirc mat sang mot phia; trong den xa, ngam canh tu tren cao. Chu yeu dung trong tu 眺望 (trong ngong, ngam nhin tu xa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1228.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mục (091) Triệu (325)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mục (số 091 - con mắt/chỉ ý) ở bên trái chữ Triệu (số 325 - báo trước/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Triệu chỉ âm, bộ Mục chỉ ý. Thiếu (hay Diêu) là liếc mắt nhìn lườm, ngắm nhìn về phương xa (tiêu diêu, viễn thiếu).", "Nghĩa Tiếng Việt_Xie": "trông, ngắm từ xa; lườm; lễ họp chư hầu", "Hạng Tần Suất (Jun Da)": "3345.0", "Tần Suất % (Jun Da)": "99.4563771797", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 兆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目兆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眺", "Unihan_Traditional (Chữ Phồn thể)": "眺", "Pinyin_Xie": "tiào", "Âm Hán Việt_Xie": "thiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chính trong câu, kết hợp với các từ chỉ phương hướng để chỉ hành động quan sát từ trên cao. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袱', '{"9000": "3346.0", "Chữ Trung Quốc": "袱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 11 | nét | 衤 | y | biểu nghĩa | vải, áo | 伏 | phục | biểu âm | (cho âm fú) | 袱 = 衤(Y, biểu nghĩa: vải, quần áo) + 伏 (Phục, biểu âm); chữ hình thanh. Bộ y chỉ vật liệu vải; 伏 cho âm fú, đồng âm Hán-Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phục\": vải (衤) phục sát xuống gói đồ — phục bọc, mảnh vải gấp lại thành cái bọc mang đi. | Gương Hán-Việt | \"phục\" trong \"bao phục\" (包袱 — gánh nặng, vật gói); 伏 (phục) trong 埋伏 (mai phục) | Mở khoá kiến thức | Biết 袱 mở khoá 包袱 (gánh nặng; cái bọc vải), 卸包袱 (trút bỏ gánh nặng).", "Tự nguyên_Xie": "袱 là chữ hình thanh: bộ 衣 (rút thành 衤 — y, vải) biểu nghĩa; 伏 (phục) cho âm fú. Nghĩa gốc là mảnh vải dùng để gói đồ hoặc bọc đồ. Wiktionary xác nhận cấu trúc này. Hiện dùng chủ yếu trong 包袱 (gánh nặng, hoặc cái bọc vải). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khăn gói", "Hạng Tần Suất (Jun Da)": "3346.0", "Tần Suất % (Jun Da)": "99.4570112751", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 伏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤伏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袱", "Unihan_Traditional (Chữ Phồn thể)": "袱", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ tử để tạo thành danh từ phục tử chỉ cái khăn dùng để gói đồ đạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('陇', '{"9000": "3347.0", "Chữ Trung Quốc": "陇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 7 | nét | 阝 | phụ | biểu nghĩa | gò đất, đồi | 龍 | long | biểu âm | rồng | 陇 = 阝(Phụ, biểu nghĩa: gò đất) + 龍(Long, biểu âm); chữ hình thanh. Bộ phụ 阝chỉ địa hình đồi núi, 龍 cho âm đọc gần với lǒng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lũng\": gò đất (阝) cao như rồng (龍) uốn khúc — hình ảnh dãy núi Lũng Sơn hùng vĩ. | Gương Hán-Việt | lũng — trong \"Lũng Tây\" (vùng đất phía tây), \"Lũng Hải\" (tuyến đường sắt cổ) | Mở khoá kiến thức | Biết 陇 mở khoá các địa danh lịch sử: Lũng Tây (陇西), Lũng Hải (陇海), Cam Túc (甘肃陇).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 陇 (dạng đầy đủ 隴) là chữ hình thanh: 阝(阜, gò đất) biểu nghĩa + 龍 biểu âm. Nguyên nghĩa chỉ dãy núi Long Sơn (Lũng Sơn) ở vùng Cam Túc, sau dùng làm tên vùng đất tây bắc Trung Quốc cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên núi)", "Hạng Tần Suất (Jun Da)": "3347.0", "Tần Suất % (Jun Da)": "99.4576443369", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "陇", "Unihan_Traditional (Chữ Phồn thể)": "隴", "Pinyin_Xie": "lǒng", "Âm Hán Việt_Xie": "lũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng chỉ địa danh hoặc tên viết tắt của tỉnh Cam Túc, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殴', '{"9000": "3348.0", "Chữ Trung Quốc": "殴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 殳 | Số nét | 8 | nét | 区 | âu | biểu âm | (cho âm ōu) | 殳 | thù | biểu nghĩa | vũ khí dùi, hành động đánh | 殴 = 区 (Âu, biểu âm) + 殳 (Thù, biểu nghĩa: vũ khí, hành động đánh đập); chữ hình thanh. Bộ 殳 chỉ hành động đánh bằng vật cứng; 区 cho âm ōu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ẩu\": Âu (区) đánh bằng gậy (殳) — ẩu đả, đánh nhau hỗn loạn. | Gương Hán-Việt | \"ẩu\" trong \"ẩu đả\" (殴打 — đánh đập), \"hỗn chiến ẩu đả\" | Mở khoá kiến thức | Biết 殴 mở khoá 殴打 (đánh đập), 互殴 (ẩu đả lẫn nhau), 群殴 (đánh hội đồng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 殴 (phồn thể 毆) là chữ hình thanh: 區 (âu) cho âm ōu; 殳 (thù — vũ khí dùi, hành động đánh) biểu nghĩa. Theo Wiktionary, nghĩa là đánh nhau bằng tay hoặc đấm. Bộ 殳 ban đầu chỉ một loại vũ khí cán dài, sau dùng rộng cho hành động bạo lực. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh nhau bằng gậy", "Hạng Tần Suất (Jun Da)": "3348.0", "Tần Suất % (Jun Da)": "99.4582753315", "GavinGrover_Once (Chiết tự trực tiếp)": "区 + 殳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰区殳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "殳", "Unihan_Simplified (Chữ Giản thể)": "殴", "Unihan_Traditional (Chữ Phồn thể)": "毆", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "ẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đối tượng bị đánh hoặc kết hợp thành từ ghép như ẩu đả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('柿', '{"9000": "3349.0", "Chữ Trung Quốc": "柿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 木 | mộc | biểu nghĩa | cây | 市 | thị | biểu âm | gợi âm shì | 柿 = 木 (Mộc: cây) + 市 (Thị, biểu âm); chữ hình thanh. Bản gốc viết 柹 với 𠂔 biểu âm; nay viết 柿.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thị\": cây 木 mọc ở chợ 市 — cây hồng quả ngọt thường thấy ở chợ, đó là ''thị'' (cây hồng). | Gương Hán-Việt | thị trong \"thị tử\" 柿子, \"tây hồng thị\" 西紅柿 (cà chua) | Mở khoá kiến thức | Biết 柿 mở khoá từ về quả hồng và cà chua: 柿子, 西红柿.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chú 柿 vốn viết là 柹: 木 + 𠂔 (ls=psc, c1=s c2=p). Hiện đại viết 柿 = 木 + 市 (psc). Nghĩa: cây hồng, quả hồng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "396.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108) Thị (226)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mộc (số 79 - cây gỗ) và chữ Thị (số 197 - cái chợ) . Thị là tên một loại cây ăn quả (cây thị, quả hồng). Giải thích sự chuyển ý: Chữ Thị (cái chợ) chỉ âm, chữ Mộc (gỗ) chỉ ý. Tên một loài cây (Mộc) có quả thơm ngon thường được mang ra chợ (Thị) bán (cây Thị).", "Nghĩa Tiếng Việt_Xie": "cây hồng, quả hồng; cây thị", "Hạng Tần Suất (Jun Da)": "3349.0", "Tần Suất % (Jun Da)": "99.4589063262", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 市", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木市", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "市", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "柿", "Unihan_Traditional (Chữ Phồn thể)": "柹", "Pinyin_Xie": "shì", "Âm Hán Việt_Xie": "thị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ chỉ bộ phận của cây để chỉ cây hồng hoặc quả hồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梧', '{"9000": "3350.0", "Chữ Trung Quốc": "梧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | cây | 吾 | ngô | biểu âm | tôi (cổ) | 梧 = 木(Mộc, biểu nghĩa: cây) + 吾(Ngô, biểu âm); chữ hình thanh. Bộ mộc xác định loại thực vật, 吾 cho âm wú gần với ngô.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": cây (木) mang tên \"ngô\" (吾) — cây ngô đồng, nơi phượng hoàng đậu trong truyền thuyết. | Gương Hán-Việt | ngô — trong \"ngô đồng\" (梧桐, cây biểu tượng của mùa thu) | Mở khoá kiến thức | Biết 梧 mở khoá: 梧桐 (ngô đồng), xuất hiện nhiều trong thơ Đường và thành ngữ về mùa thu.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 梧 là chữ hình thanh: 木 biểu nghĩa (cây) + 吾 biểu âm. Chỉ cây ngô đồng (Sterculia platanifolia), loại cây rụng lá nổi tiếng trong thơ văn Trung Quốc vì phượng hoàng được cho là chỉ đậu trên cây này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "892.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Ngô (891)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối) ở bên trái chữ Ngô (số 891 - ta/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ngô chỉ âm, bộ Mộc chỉ ý. Ngô là cây ngô đồng.", "Nghĩa Tiếng Việt_Xie": "cây vông", "Hạng Tần Suất (Jun Da)": "3350.0", "Tần Suất % (Jun Da)": "99.4595357705", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 吾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木吾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梧", "Unihan_Traditional (Chữ Phồn thể)": "梧", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ đồng để tạo thành danh từ ngô đồng chỉ một loại cây thân gỗ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惺', '{"9000": "3351.0", "Chữ Trung Quốc": "惺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 惺 | tinh | tượng hình | trạng thái nửa tỉnh nửa ngủ, mắt lim dim | 惺 không có cấu trúc IDS rõ ràng trong dữ liệu hiện có. Theo hình dạng chữ, có thể phân tích gồm bộ 忄(tâm, tâm trạng) + 星(tinh, sao), có thể là chữ hình thanh với nghĩa trạng thái mơ màng của tâm trí, nhưng chưa có nguồn học thuật xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tinh\": trái tim (忄) nhìn thấy sao (星) — mắt lim dim mơ màng như nhìn sao đêm. | Gương Hán-Việt | tinh — trong \"tinh tú\" (星宿), gần âm với 星 (sao) | Mở khoá kiến thức | Biết 惺 mở khoá: 惺忪 (xīng sōng, mắt lờ đờ mới thức), 惺惺 (tỉnh táo, thông minh).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary xác định cấu trúc chính thức của 惺. Dựa vào hình dạng, chữ này nhiều khả năng gồm 忄(tâm) + 星(tinh), nếu là hình thanh thì 星 biểu âm, 忄biểu nghĩa trạng thái tâm lý. Nghĩa gốc: mắt lim dim, nửa tỉnh nửa mơ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt lim dim", "Hạng Tần Suất (Jun Da)": "3351.0", "Tần Suất % (Jun Da)": "99.4601641812", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 星", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄星", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "星", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惺", "Unihan_Traditional (Chữ Phồn thể)": "惺", "Pinyin_Xie": "xīng", "Âm Hán Việt_Xie": "tinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái tỉnh táo hoặc kết hợp lặp lại để biểu thị sự thông minh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弛', '{"9000": "3352.0", "Chữ Trung Quốc": "弛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 6 | nét | 弓 | cung | biểu nghĩa | cái cung | 也 | dã | biểu âm | cũng (hư từ) | 弛 = 弓(Cung, biểu nghĩa: cái cung) + 也(Dã, biểu âm); chữ hình thanh. Bộ cung gợi hành động buông dây cung ra, 也 cho âm đọc gốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thỉ\": cái cung (弓) được buông lỏng (也) — thỉ là thư giãn, nới dây cung ra sau trận chiến. | Gương Hán-Việt | thỉ — ít dùng độc lập, thường trong \"thỉ hoãn\" (弛缓, nới lỏng), \"phóng thỉ\" (放弛) | Mở khoá kiến thức | Biết 弛 mở khoá: 松弛 (thư giãn, yếu đi), 弛缓 (nới lỏng, giảm nhẹ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 弛 là chữ hình thanh: 弓 (cung) biểu nghĩa + 也 biểu âm. Nghĩa gốc: buông lỏng dây cung sau khi dùng — từ đó mở rộng nghĩa thư giãn, nới lỏng (như trong 松弛). Dạng tiểu triện và đại triện đã xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "buông dây cung", "Hạng Tần Suất (Jun Da)": "3352.0", "Tần Suất % (Jun Da)": "99.4607920751", "GavinGrover_Once (Chiết tự trực tiếp)": "弓 + 也", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰弓也", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "也", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弛", "Unihan_Traditional (Chữ Phồn thể)": "弛", "Pinyin_Xie": "chí", "Âm Hán Việt_Xie": "thỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ việc nới lỏng quy định hoặc làm tính từ chỉ trạng thái lơi lỏng, thiếu kỷ luật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侥', '{"9000": "3353.0", "Chữ Trung Quốc": "侥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 亻 | nhân | biểu nghĩa | người | 尧 | nghiêu | biểu âm | (cho âm jiǎo/yáo) | 侥 là dạng giản thể của 僥, ghép từ 亻(Nhân, biểu nghĩa: người) + 尧 (Nghiêu, biểu âm). Chữ hình thanh; nghĩa gốc liên quan đến may mắn tình cờ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểu\": người (亻) gặp được Nghiêu (尧 — vua hiền) — kiểu hạnh, may mắn tình cờ như gặp minh quân. | Gương Hán-Việt | \"kiểu\" trong \"kiểu hạnh\" (侥幸 — may mắn); \"nghiêu\" trong 侥 còn gặp ở Hán-Việt cổ | Mở khoá kiến thức | Biết 侥 mở khoá 侥幸 (may mắn không xứng đáng, ăn may), 侥幸心理 (tâm lý ỷ lại may mắn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 侥 (phồn thể 僥) là dạng đơn giản hóa, theo Wiktionary xem thêm mục 僥. Cấu trúc: 亻(nhân — người) + 尧 (nghiêu) cho âm. Nghĩa chính là gặp may, may mắn tình cờ, thường trong 侥幸 (may mắn không xứng đáng). Chữ tạo muộn, chưa có ghi chép trong giáp cốt hay kim văn rõ ràng. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tiêu nghiêu 僬僥,僬侥); (xem: nghiêu hãnh 僥倖,侥倖)", "Hạng Tần Suất (Jun Da)": "3353.0", "Tần Suất % (Jun Da)": "99.4614199691", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侥", "Unihan_Traditional (Chữ Phồn thể)": "僥", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "nghiêu, kiểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường kết hợp với chữ hạnh để làm tính từ hoặc phó từ chỉ sự may mắn ngoài mong đợi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琛', '{"9000": "3354.0", "Chữ Trung Quốc": "琛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 琛 | trâm | tượng hình | đồ quý báu, châu báu | 琛 không có cấu trúc IDS xác nhận trong dữ liệu. Theo hình dạng, có thể phân tích gồm 王(ngọc, bộ ngọc 玉 biến thể) + 深 (thâm, sâu) rút gọn, nhưng chưa có nguồn học thuật. Có thể là chữ hình thanh với bộ ngọc 玉/王 biểu nghĩa châu báu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trâm\": châu báu quý giá — 琛 thường xuất hiện trong tên người Việt Nam như một chữ đẹp mang nghĩa tài năng, quý báu. | Gương Hán-Việt | trâm — dùng trong tên người (琛), ít gặp trong từ ghép thông dụng | Mở khoá kiến thức | Biết 琛 mở khoá: 琛贝 (châu báu), xuất hiện trong tên riêng và thơ văn cổ về cống phẩm quý.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chưa có cấu trúc Wiktionary xác định cho 琛. Ngữ nghĩa gốc là châu báu, vật quý. Chữ này chủ yếu xuất hiện trong văn chương cổ và tên riêng. chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ quý báu", "Hạng Tần Suất (Jun Da)": "3354.0", "Tần Suất % (Jun Da)": "99.462047863", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 罙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王罙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琛", "Unihan_Traditional (Chữ Phồn thể)": "琛", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "sâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết cổ hoặc dùng đặt tên người để chỉ những thứ quý giá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捅', '{"9000": "3355.0", "Chữ Trung Quốc": "捅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 捅 | thòng | tượng hình | đâm, chọc, thúc | 捅 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 扌(thủ, tay) + 桶 rút gọn hoặc 甬, nhiều khả năng là hình thanh với bộ tay biểu nghĩa hành động, phần còn lại biểu âm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thòng\": bàn tay (扌) thòng xuống chọc — 捅 là đâm, chọc, thúc bằng tay. | Gương Hán-Việt | thòng — ít dùng trong Hán-Việt thuần, chủ yếu gặp trong từ hiện đại | Mở khoá kiến thức | Biết 捅 mở khoá: 捅破 (chọc thủng), 捅刀子 (đâm dao), 捅娄子 (gây rắc rối).", "Tự nguyên_Xie": "Wiktionary không có cấu trúc hình thành chính thức cho 捅. Theo cấu trúc hình dạng, bộ 扌(tay) gợi hành động dùng tay chọc/đâm vào. Nghĩa: dùng vật nhọn đâm hoặc thúc vào, cũng có nghĩa bóng là làm lộ bí mật (捅出去). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đâm, chọc, thúc, huých", "Hạng Tần Suất (Jun Da)": "3355.0", "Tần Suất % (Jun Da)": "99.4626736898", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捅", "Unihan_Traditional (Chữ Phồn thể)": "捅", "Pinyin_Xie": "tǒng", "Âm Hán Việt_Xie": "thống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường đứng trước tân ngữ để chỉ hành động đâm chọc vật lý hoặc làm lộ thông tin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tǒng | / | đâm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酝', '{"9000": "3356.0", "Chữ Trung Quốc": "酝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 11 | nét | 酉 | dậu | biểu nghĩa | bình rượu, men rượu | 云 | vân | biểu âm | (cho âm yùn) | 酝 = 酉 (Dậu, biểu nghĩa: bình rượu, ủ men) + 云 (Vân, biểu âm); chữ hình thanh. Bộ dậu (酉) trong chữ Hán thường chỉ các thứ liên quan đến rượu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uấn\": bình rượu (酉) và mây (云) — uấn kết như mây tụ, rượu ủ dần đến khi chín. | Gương Hán-Việt | \"uấn\" trong \"uấn nương\" (酝酿 — ủ, hình thành) | Mở khoá kiến thức | Biết 酝 mở khoá 酝酿 (đang ủ, đang hình thành), 佳酝 (rượu ngon, tốt đẹp).", "Tự nguyên_Xie": "酝 (phồn thể 醞) là chữ hình thanh: bộ 酉 (dậu — bình rượu) biểu nghĩa, chỉ quá trình ủ rượu; 云 (vân) cho âm yùn. Theo Wiktionary, nghĩa gốc là ủ rượu, lên men; nghĩa mở rộng là hình thành dần dần, ủ chín một ý tưởng. Dùng trong 酝酿 (đang ủ, đang hình thành). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ủ rượu, cất rượu", "Hạng Tần Suất (Jun Da)": "3356.0", "Tần Suất % (Jun Da)": "99.4632969327", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 云", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉云", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "云", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酝", "Unihan_Traditional (Chữ Phồn thể)": "醞", "Pinyin_Xie": "yùn", "Âm Hán Việt_Xie": "uấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong từ ghép để chỉ việc ủ rượu hoặc chuẩn bị, nhen nhóm ý tưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('薯', '{"9000": "3357.0", "Chữ Trung Quốc": "薯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 16 | nét | 薯 | thự | tượng hình | củ khoai, loài cây có củ | 薯 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 艹(thảo, cỏ/cây) ở trên + 署 bên dưới, khả năng là hình thanh với bộ thảo biểu nghĩa thực vật và 署 biểu âm. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thự\": cây (艹) có tên thự — khoai lang (红薯) hay khoai tây (薯条) đều là \"thự\". | Gương Hán-Việt | thự — trong \"thự dự\" (薯蓣, khoai mỡ), \"thự lang\" (薯莨) | Mở khoá kiến thức | Biết 薯 mở khoá: 薯条 (khoai tây chiên), 薯片 (khoai tây chiên lát), 红薯 (khoai lang), 土豆 so sánh với 薯.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp cấu trúc hình thành chính thức cho 薯. Theo hình dạng, bộ 艹(cỏ/thực vật) + 署 nhiều khả năng là hình thanh. Nghĩa gốc chỉ các loại cây có củ ăn được như khoai lang, khoai mỡ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thự lang 薯莨); (xem: thự dự 薯蕷,薯蓣); (xem: hương thự 香薯)", "Hạng Tần Suất (Jun Da)": "3357.0", "Tần Suất % (Jun Da)": "99.463919142", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 署", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹署", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "署", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "薯", "Unihan_Traditional (Chữ Phồn thể)": "薯", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "thự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng một mình hoặc kết hợp với các từ khác để chỉ các loại khoai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曳', '{"9000": "3358.0", "Chữ Trung Quốc": "曳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 曰 | Số nét | 6 | nét | 人 | nhân | biểu nghĩa | người bị kéo lê | 曳 là chữ hội ý. Theo Wiktionary, có thể gồm 𦥑 (hai bàn tay) + 人 (người): hai tay kéo lê một người. Cấu trúc mô tả hành động kéo, lôi kéo về mặt hình ảnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dấy\": bàn tay kéo người (人) lê lết — dấy là kéo, lôi kéo, cũng gợi hình ảnh vạt áo dài quét đất. | Gương Hán-Việt | dấy — ít gặp độc lập, trong \"bài huy\" (摇曳, lắc lư, uyển chuyển) | Mở khoá kiến thức | Biết 曳 mở khoá: 摇曳 (lắc lư, uyển chuyển như ngọn nến), 曳光弹 (đạn vạch đường).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 曳 có thể là chữ hội ý: 𦥑 (hai bàn tay) + 人 (người) — hình ảnh hai tay kéo lê một người. Dạng đại triện và tiểu triện đã xác nhận. Nghĩa gốc: kéo, dắt, lôi kéo; sau mở rộng sang nghĩa mệt mỏi, rung lắc. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo, dắt; mệt; rung", "Hạng Tần Suất (Jun Da)": "3358.0", "Tần Suất % (Jun Da)": "99.4645408345", "GavinGrover_Once (Chiết tự trực tiếp)": "㇂ + 日 + ㇒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "Ký hiệu: built", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "㇂日㇒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曳", "Unihan_Traditional (Chữ Phồn thể)": "曳", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết để tả hành động kéo lê hoặc lay động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澈', '{"9000": "3359.0", "Chữ Trung Quốc": "澈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thuỷ | biểu nghĩa | nước | 育 | dục | biểu nghĩa | (thành phần trung gian trong 徹) | 攵 | phộc | biểu âm | (rút từ 徹, cho âm chè) | 澈 = 氵(Thuỷ, biểu nghĩa: nước) + 徹 (Triệt, biểu âm, rút gọn thành 育+攵); chữ hình thanh. Nước trong vắt là nghĩa gốc; phần âm dẫn từ 徹 (triệt/chè).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triệt\": nước (氵) triệt để trong suốt — triệt để, không một vẩn đục. | Gương Hán-Việt | \"triệt\" trong \"thanh triệt\" (清澈 — trong suốt), \"triệt để\" (徹底) | Mở khoá kiến thức | Biết 澈 mở khoá 清澈 (trong suốt, limpid), 澄澈 (trong vắt, crystal clear), 明澈 (sáng trong).", "Tự nguyên_Xie": "澈 là chữ hình thanh: bộ 水 (rút thành 氵 — thuỷ) biểu nghĩa; 徹 (triệt, rút gọn) cho âm chè. Theo Wiktionary, nghĩa gốc là nước trong, limpid; còn là dạng cổ của 徹 (thorough — triệt để). Chữ dùng chủ yếu trong văn học, tả nước suối trong vắt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước trong; thấu suốt", "Hạng Tần Suất (Jun Da)": "3359.0", "Tần Suất % (Jun Da)": "99.4651620102", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "澈", "Unihan_Traditional (Chữ Phồn thể)": "澈", "Pinyin_Xie": "chè", "Âm Hán Việt_Xie": "triệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ chỉ nước hoặc trạng thái tinh thần rõ ràng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锈', '{"9000": "3360.0", "Chữ Trung Quốc": "锈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 钅 | kim | biểu nghĩa | kim loại | 秀 | tú | biểu âm | (cho âm xiù) | 锈 = 钅(Kim, biểu nghĩa: kim loại) + 秀 (Tú, biểu âm); chữ hình thanh. Bộ kim chỉ vật liệu kim loại; 秀 cho âm xiù và đồng âm Hán-Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tú\": kim loại (钅) tú mà ra gỉ — tú tú, đẹp đẽ ban đầu rồi hoen ố theo thời gian. | Gương Hán-Việt | \"tú\" trong 秀 (tú lệ), 绣 (thêu thùa); gỉ sét (锈) đồng âm nhưng nghĩa trái ngược | Mở khoá kiến thức | Biết 锈 mở khoá 生锈 (bị rỉ sét), 锈迹 (vết gỉ sét), 防锈 (chống gỉ).", "Tự nguyên_Xie": "锈 (phồn thể 鏽) là chữ hình thanh: bộ 金 (rút thành 钅 — kim) biểu nghĩa, chỉ kim loại; 肅 (trong phồn thể) hoặc 秀 cho âm. Theo Wiktionary, nghĩa là gỉ sét, sự oxy hóa trên bề mặt kim loại. Chữ giản thể dùng 秀 thay 肅 làm phần âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gỉ (kim loại)", "Hạng Tần Suất (Jun Da)": "3360.0", "Tần Suất % (Jun Da)": "99.4657811188", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 秀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅秀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "秀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锈", "Unihan_Traditional (Chữ Phồn thể)": "銹", "Pinyin_Xie": "xiù", "Âm Hán Việt_Xie": "tú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ lớp gỉ sét hoặc làm động từ chỉ quá trình kim loại bị oxy hóa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | xiù | / | gỉ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Hóa học và Sinh học II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稠', '{"9000": "3361.0", "Chữ Trung Quốc": "稠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 13 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 周 | chu | biểu âm | (cho âm chóu) | 稠 = 禾 (Hoà, biểu nghĩa: lúa, ngũ cốc) + 周 (Chu, biểu âm); chữ hình thanh. Bộ hoà gợi gốc nghĩa về hạt, cháo đặc; 周 cho âm chóu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trù\": lúa (禾) chu đáo (周) ken dày — trù mật, đặc sệt như cháo gạo mùa thu. | Gương Hán-Việt | \"trù\" trong \"trù mật\" (稠密 — đông đúc, dày đặc) | Mở khoá kiến thức | Biết 稠 mở khoá 稠密 (dày đặc, đông đúc), 粘稠 (dính nhớt), 黏稠 (đặc quánh).", "Tự nguyên_Xie": "Tiểu triện | 稠 là chữ hình thanh: bộ 禾 (hoà — lúa, ngũ cốc) biểu nghĩa, gợi hình ảnh cháo gạo đặc; 周 (chu) cho âm chóu. Wiktionary ghi nghĩa là thick/viscous (đặc sệt), dense (dày đặc). Không có ghi chú nguồn gốc cổ đại chi tiết hơn trong anchor. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đặc sệt, mau, sít, đông đúc", "Hạng Tần Suất (Jun Da)": "3361.0", "Tần Suất % (Jun Da)": "99.4663981603", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稠", "Unihan_Traditional (Chữ Phồn thể)": "稠", "Pinyin_Xie": "chóu", "Âm Hán Việt_Xie": "trù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả mật độ dày đặc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chóu | / | dày đặc | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Đặc điểm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眸', '{"9000": "3362.0", "Chữ Trung Quốc": "眸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 11 | nét | 目 | mục | biểu nghĩa | mắt | 牟 | mưu | biểu âm | 眸 = 目(Mục, biểu nghĩa: mắt) + 牟(Mưu, biểu âm); chữ hình thanh. Bộ mục xác định bộ phận cơ thể, 牟 cho âm móu gần với mâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mâu\": con mắt (目) sáng như sao — mâu là con ngươi mắt, đôi mắt trong veo. | Gương Hán-Việt | mâu — trong \"minh mâu\" (明眸, đôi mắt sáng đẹp) | Mở khoá kiến thức | Biết 眸 mở khoá: 眸子 (đồng tử, con ngươi), 明眸 (đôi mắt sáng đẹp), hay dùng trong văn học.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 眸 là chữ hình thanh: 目 (mắt) biểu nghĩa + 牟 biểu âm. Nghĩa gốc: con ngươi mắt, đồng tử. Trong thơ văn thường dùng chỉ đôi mắt đẹp, ánh mắt (眸子, 明眸). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngươi mắt", "Hạng Tần Suất (Jun Da)": "3362.0", "Tần Suất % (Jun Da)": "99.4670146849", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 牟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目牟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "牟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眸", "Unihan_Traditional (Chữ Phồn thể)": "眸", "Pinyin_Xie": "móu", "Âm Hán Việt_Xie": "mâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn thơ để chỉ đôi mắt hoặc ánh nhìn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咆', '{"9000": "3363.0", "Chữ Trung Quốc": "咆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 咆 | bàu | tượng hình | gầm thét, gầm gừ | 咆 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 口(khẩu, miệng) + 包(bao), nhiều khả năng là hình thanh với 口 biểu nghĩa âm thanh từ miệng và 包 biểu âm. Nghĩa: tiếng gầm thét dữ dội.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàu\": miệng (口) phát ra tiếng bào bào — bàu là gầm thét, tiếng hét giận dữ như sư tử. | Gương Hán-Việt | bàu — trong \"bàu hống\" (咆哮, gầm thét) hay gặp trong văn học | Mở khoá kiến thức | Biết 咆 mở khoá: 咆哮 (gầm thét, phẫn nộ), 咆哮而来 (đến với tiếng gầm thét).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp cấu trúc hình thành chính thức cho 咆. Theo hình dạng, 口 (miệng) + 包 (bao) gợi âm thanh mạnh phát ra từ miệng. Nghĩa gốc: gầm thét, tiếng gầm của thú dữ hoặc người tức giận. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầm thét, gầm gừ", "Hạng Tần Suất (Jun Da)": "3363.0", "Tần Suất % (Jun Da)": "99.467630176", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咆", "Unihan_Traditional (Chữ Phồn thể)": "咆", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp thành từ ghép để miêu tả tiếng gầm của thú dữ hoặc sóng gió. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簧', '{"9000": "3364.0", "Chữ Trung Quốc": "簧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 簧 | hoàng | tượng hình | lưỡi gà, vè đàn bằng kim loại hoặc tre | 簧 không có cấu trúc IDS xác nhận trong dữ liệu. Theo hình dạng gồm 竹(trúc, tre) ở trên + 黄(hoàng, vàng) bên dưới, nhiều khả năng là hình thanh với 竹 biểu nghĩa vật liệu tre và 黄 biểu âm. Kim văn và tiểu triện đã ghi nhận chữ này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": thanh tre (竹) vàng (黄) rung lên thành tiếng — hoàng là lưỡi gà đàn, lò xo. | Gương Hán-Việt | hoàng — trong \"hoàng quản\" (簧管, nhạc cụ hơi có lưỡi gà), ít dùng độc lập | Mở khoá kiến thức | Biết 簧 mở khoá: 簧管乐器 (nhạc cụ hơi có lưỡi gà), 弹簧 (lò xo), 口簧 (đàn môi).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Wiktionary không cung cấp cấu trúc hình thành chính thức cho 簧. Theo hình dạng, 竹(tre) + 黄(hoàng) nhiều khả năng là hình thanh. Nghĩa gốc: lưỡi gà trong nhạc cụ hơi (làm từ tre hoặc kim loại mỏng), bộ phận rung tạo âm thanh. Sau mở rộng sang nghĩa lò xo, chốt khóa. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái vè đồng (lấy đồng dát mỏng trong lỗ tiêu hay sáo để thổi cho kêu)", "Hạng Tần Suất (Jun Da)": "3364.0", "Tần Suất % (Jun Da)": "99.4682451503", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簧", "Unihan_Traditional (Chữ Phồn thể)": "簧", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận phát âm của nhạc cụ hoặc lò xo trong máy móc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸥', '{"9000": "3365.0", "Chữ Trung Quốc": "鸥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 9 | nét | 鸥 | âu | tượng hình | chim hải âu | 鸥 là chữ giản thể của 鷗. Theo Wiktionary, 鷗 gồm 區(khu) biểu âm + 鳥(điểu, chim) biểu nghĩa — chữ hình thanh. Dạng giản thể thay 區 bằng 区 và 鳥 bằng 鸟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"âu\": chim (鸟) kêu âu âu trên biển — âu là hải âu, biểu tượng của tự do. | Gương Hán-Việt | âu — trong \"hải âu\" (海鸥, chim hải âu), \"âu lộ\" (鸥鹭, hải âu và cò) | Mở khoá kiến thức | Biết 鸥 mở khoá: 海鸥 (hải âu), 沙鸥 (hải âu cát), xuất hiện nhiều trong thơ Đường.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 鸥 (giản thể của 鷗) là chữ hình thanh: 鳥(chim) biểu nghĩa + 區 biểu âm. Chỉ loài chim hải âu (seagull), sống ven biển và sông nước. Trong thơ văn cổ, hải âu tượng trưng cho sự tự do, phóng khoáng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hải âu, con cò biển", "Hạng Tần Suất (Jun Da)": "3365.0", "Tần Suất % (Jun Da)": "99.4688596079", "GavinGrover_Once (Chiết tự trực tiếp)": "区 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰区鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "区", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸥", "Unihan_Traditional (Chữ Phồn thể)": "鷗", "Pinyin_Xie": "ōu", "Âm Hán Việt_Xie": "âu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng một mình hoặc kết hợp để chỉ loài chim biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疡', '{"9000": "3366.0", "Chữ Trung Quốc": "疡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疡 | dương | tượng hình | mụn nhọt, vết thương lở loét | 疡 là chữ giản thể của 瘍. Theo cấu trúc hình dạng gồm 疒(nạch, bệnh tật) + 昜/𠃓 biểu âm, là chữ hình thanh chỉ bệnh da liễu, mụn nhọt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": bệnh (疒) sưng phồng lên như nắng dương — dương là mụn nhọt, lở loét. | Gương Hán-Việt | dương — trong \"ung dương\" (痈疡, áp xe mụn nhọt), \"thương dương\" (疮疡, vết thương) | Mở khoá kiến thức | Biết 疡 mở khoá: 疮疡 (vết thương, lở loét), 溃疡 (loét), 痈疡 (áp xe).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 疡 (giản thể của 瘍) là chữ hình thanh: 疒 (bộ bệnh) biểu nghĩa + 昜 biểu âm. Nghĩa gốc: vết thương lở loét, mụn nhọt, áp xe. Dùng trong y học cổ truyền Trung Hoa cho các bệnh ngoài da. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh mụn nhọt", "Hạng Tần Suất (Jun Da)": "3366.0", "Tần Suất % (Jun Da)": "99.4694740654", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 𠃓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒𠃓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠃓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疡", "Unihan_Traditional (Chữ Phồn thể)": "瘍", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong y học để chỉ các vết loét trên cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渎', '{"9000": "3367.0", "Chữ Trung Quốc": "渎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 渎 | độc | tượng hình | ngòi nước; xúc phạm, khinh nhờn | 渎 là chữ giản thể của 瀆. Theo Wiktionary, 瀆 gồm 氵(thủy, nước) biểu nghĩa + 賣(mại) biểu âm — chữ hình thanh. Dạng giản thể thay 賣 bằng 卖.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": nước (氵) chảy lộn xộn — độc là ngòi rãnh, cũng nghĩa xúc phạm, khinh nhờn. | Gương Hán-Việt | độc — trong \"tiết độc\" (亵渎, xúc phạm), \"độc thần\" (渎神, báng bổ thần thánh) | Mở khoá kiến thức | Biết 渎 mở khoá: 亵渎 (xúc phạm, báng bổ), 渎职 (lạm dụng chức quyền), 四渎 (bốn con sông lớn cổ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 渎 (giản thể của 瀆) là chữ hình thanh: 氵(nước) biểu nghĩa + 賣 biểu âm. Nghĩa gốc: ngòi nước, kênh thoát nước nhỏ. Nghĩa phái sinh: quấy nhiễu, khinh nhờn (như trong 亵渎 — xúc phạm thiêng liêng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ngòi; quấy nhiễu, quấy rầy; khinh nhờn", "Hạng Tần Suất (Jun Da)": "3367.0", "Tần Suất % (Jun Da)": "99.4700869726", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渎", "Unihan_Traditional (Chữ Phồn thể)": "瀆", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ với nghĩa khinh nhờn trong các từ ghép hoặc làm danh từ chỉ các con sông lớn thời cổ đại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汲', '{"9000": "3368.0", "Chữ Trung Quốc": "汲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 氵 | thủy | biểu nghĩa | nước | 及 | cập | biểu âm | kịp, đến | 汲 = 氵(Thủy, biểu nghĩa: nước) + 及(Cập, biểu âm); chữ hình thanh. Bộ thủy chỉ hành động liên quan đến nước, 及 cho âm jí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bập\": nước (氵) kéo lên bập bập — bập là múc nước, kéo nước từ giếng lên. | Gương Hán-Việt | bập — ít gặp độc lập, trong \"cấp thủ\" hay \"cấp tư\" (汲取, hấp thu) | Mở khoá kiến thức | Biết 汲 mở khoá: 汲取 (hấp thu, học hỏi), 汲水 (múc nước), 汲引 (kéo lên, đề bạt).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 汲 là chữ hình thanh: 氵(水, nước) biểu nghĩa + 及 biểu âm. Nghĩa gốc: múc nước từ giếng hoặc nguồn nước, kéo nước lên. Mở rộng sang nghĩa hút vào, tiếp thu (汲取 — hấp thu, học hỏi). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1254.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Cập (1253)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước/ 氵/chỉ ý) ở bên trái chữ Cập (số 1253 - theo kịp/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Cập chỉ âm, bộ Thủy chỉ ý. Cấp là múc nước từ giếng lên. Cũng có nghĩa là kéo lên, tiếp dẫn.", "Nghĩa Tiếng Việt_Xie": "múc nước", "Hạng Tần Suất (Jun Da)": "3368.0", "Tần Suất % (Jun Da)": "99.4706983294", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汲", "Unihan_Traditional (Chữ Phồn thể)": "汲", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ nước hoặc dùng trong các từ ghép chỉ sự nỗ lực, hấp thu kiến thức. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嬉', '{"9000": "3369.0", "Chữ Trung Quốc": "嬉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 15 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 喜 | hỷ | biểu âm | vui mừng | 嬉 = 女(Nữ, biểu nghĩa) + 喜(Hỷ, biểu âm); chữ hình thanh, đồng thời cũng có thể là hội ý vì 喜 mang nghĩa niềm vui. Bộ nữ và hỷ kết hợp gợi sự vui đùa, nô nghịch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\": người nữ (女) vui hỷ hả (喜) — hi là vui đùa, nô nghịch hồn nhiên. | Gương Hán-Việt | hi — trong \"hi tiếu\" (嬉笑, cười đùa), \"hi nhi\" (嬉戏, vui chơi) | Mở khoá kiến thức | Biết 嬉 mở khoá: 嬉笑 (cười đùa), 嬉戏 (vui chơi), 嬉皮士 (hippie).", "Tự nguyên_Xie": "Theo Wiktionary, 嬉 là chữ hình thanh: 女 biểu nghĩa + 喜 biểu âm. Đồng thời cũng có thể phân tích là hội ý vì 喜 mang nghĩa vui mừng. Nghĩa gốc: vui đùa, nô nghịch, chơi đùa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui đùa; vui chơi; nô đùa", "Hạng Tần Suất (Jun Da)": "3369.0", "Tần Suất % (Jun Da)": "99.4713096862", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 喜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女喜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嬉", "Unihan_Traditional (Chữ Phồn thể)": "嬉", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động vui chơi giải trí, hay đi kèm với các từ chỉ hoạt động chơi đùa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脓', '{"9000": "3370.0", "Chữ Trung Quốc": "脓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 脓 | nùng | tượng hình | mủ ở vết thương | 脓 là chữ giản thể của 膿. Theo hình dạng gồm 月/肉(nhục, thịt/cơ thể) biểu nghĩa + 农(nông) biểu âm, là chữ hình thanh chỉ chất dịch mủ sinh ra từ vết thương nhiễm trùng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nùng\": thịt (月) nùng nặng mưng mủ — nùng là mủ vết thương, vết thương có mủ. | Gương Hán-Việt | nùng — trong \"nùng thủy\" (脓水, nước mủ), \"hóa nùng\" (化脓, hóa mủ) | Mở khoá kiến thức | Biết 脓 mở khoá: 化脓 (hóa mủ, có mủ), 脓肿 (áp xe mủ), 脓水 (nước mủ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận 脓 (giản thể của 膿) nhưng không có cấu trúc hình thành chi tiết. Theo hình dạng, bộ 月/肉 (thịt/cơ thể) biểu nghĩa + 农 biểu âm, là hình thanh. Nghĩa: mủ, dịch mủ sinh ra từ vết thương nhiễm trùng. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mủ (ở vết thương)", "Hạng Tần Suất (Jun Da)": "3370.0", "Tần Suất % (Jun Da)": "99.4719194926", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 农", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月农", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "农", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脓", "Unihan_Traditional (Chữ Phồn thể)": "膿", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nùng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm tân ngữ cho động từ như chảy mủ, mưng mủ hoặc làm định ngữ trong y học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骡', '{"9000": "3371.0", "Chữ Trung Quốc": "骡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 14 | nét | 馬 | mã | biểu nghĩa | ngựa | 累 | luỵ | biểu âm | nặng nề, mệt mỏi | 骡 (dạng đầy đủ 騾) = 馬(Mã, biểu nghĩa: ngựa) + 累(Luỵ, biểu âm); chữ hình thanh. Bộ mã xác định loài vật, 累 cho âm luó gần với la.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"la\": con ngựa (馬) mang nặng (累) — la là con la, loài vật lai sức khỏe phi thường. | Gương Hán-Việt | la — trong \"la mã\" (骡马, la và ngựa), ít dùng độc lập hiện đại | Mở khoá kiến thức | Biết 骡 mở khoá: 骡子 (con la), 骡马 (la và ngựa), hiểu được các từ về súc vật kéo kéo.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 骡 (dạng đầy đủ 騾) là chữ hình thanh: 馬(ngựa) biểu nghĩa + 累 biểu âm. Chữ này xuất hiện trong Thuyết Văn Giải Tự dưới dạng 驘. Nghĩa: con la, con vật lai giữa ngựa đực và lừa cái, nổi tiếng khỏe mạnh và bướng bỉnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con la", "Hạng Tần Suất (Jun Da)": "3371.0", "Tần Suất % (Jun Da)": "99.4725282655", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 累", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马累", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "累", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骡", "Unihan_Traditional (Chữ Phồn thể)": "騾", "Pinyin_Xie": "luó", "Âm Hán Việt_Xie": "la", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ con vật, thường đứng sau lượng từ hoặc kết hợp với các danh từ khác để chỉ bộ phận của con la. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穗', '{"9000": "3372.0", "Chữ Trung Quốc": "穗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 17 | nét | 禾 | hòa | biểu nghĩa | lúa, cây ngũ cốc | 惠 | huệ | biểu âm | ân huệ | 穗 = 禾(Hòa, biểu nghĩa: lúa) + 惠(Huệ, biểu âm); chữ hình thanh. Bộ hòa gợi cây lúa, 惠 cho âm suì gần với tuệ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": cây lúa (禾) ân huệ (惠) với người — tuệ là bông lúa trĩu nặng, biểu tượng no ấm. | Gương Hán-Việt | tuệ — trong \"hoa tuệ\" (花穗, bông hoa), \"quảng tuệ\" (广穗, chỉ Quảng Châu) | Mở khoá kiến thức | Biết 穗 mở khoá: 穗子 (bông lúa, tua rua), 穗穗 (đầy bông), 广州/穗 (tên tắt Quảng Châu).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 穗 là chữ hình thanh: 禾(lúa) biểu nghĩa + 惠 biểu âm. Nghĩa gốc: bông lúa, bông hoa, tua rua ở đầu ngọn. Tên viết tắt của thành phố Quảng Châu (穗 = Quảng Châu/Tuệ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông lúa, bông hoa; tàn đuốc", "Hạng Tần Suất (Jun Da)": "3372.0", "Tần Suất % (Jun Da)": "99.4731370384", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 惠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾惠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "惠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "穗", "Unihan_Traditional (Chữ Phồn thể)": "穗", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ bông lúa hoặc làm lượng từ cho các vật có hình dạng giống bông lúa, tua rua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('槛', '{"9000": "3373.0", "Chữ Trung Quốc": "槛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 監 | giám | biểu âm | giám sát | 槛 (dạng đầy đủ 檻) = 木(Mộc, biểu nghĩa: gỗ) + 監(Giám, biểu âm); chữ hình thanh. Bộ mộc chỉ vật làm bằng gỗ, 監 cho âm kǎn/jiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giám\": gỗ (木) làm giám ngục — giám là chuồng nhốt thú, cũng là ngưỡng cửa gỗ. | Gương Hán-Việt | giám — trong \"môn giám\" (门槛, ngưỡng cửa, cũng nghĩa bóng rào cản) | Mở khoá kiến thức | Biết 槛 mở khoá: 门槛 (ngưỡng cửa; rào cản), 槛车 (xe chuồng tù), hiểu ngưỡng cửa vật chất và nghĩa bóng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 槛 (dạng đầy đủ 檻) là chữ hình thanh: 木(gỗ) biểu nghĩa + 監 biểu âm. Nghĩa gốc: chuồng nhốt thú, sau mở rộng sang nghĩa lan can, hiên nhà, bậu cửa. Đọc kǎn khi nghĩa ngưỡng cửa/bậu cửa; đọc jiàn khi nghĩa chuồng thú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hiên nhà", "Hạng Tần Suất (Jun Da)": "3373.0", "Tần Suất % (Jun Da)": "99.4737447777", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 监", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木监", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "监", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "槛", "Unihan_Traditional (Chữ Phồn thể)": "檻", "Pinyin_Xie": "kǎn", "Âm Hán Việt_Xie": "hạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận kiến trúc như ngưỡng cửa hoặc rào chắn thú dữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拎', '{"9000": "3374.0", "Chữ Trung Quốc": "拎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 手 | thủ | biểu nghĩa | tay | 令 | lệnh | biểu âm | lệnh, sai khiến | 拎 = 扌/手(Thủ, biểu nghĩa: tay) + 令(Lệnh, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động tay, 令 cho âm līn/līng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bàn tay (扌) theo lệnh (令) xách lên — linh là xách, nhấc lên bằng tay. | Gương Hán-Việt | linh — ít dùng trong Hán-Việt cổ, chủ yếu là từ khẩu ngữ hiện đại | Mở khoá kiến thức | Biết 拎 mở khoá: 拎包 (xách túi), 拎清楚 (nắm rõ, hiểu rõ — phương ngữ).", "Tự nguyên_Xie": "Theo Wiktionary, 拎 là chữ hình thanh: 扌(手, tay) biểu nghĩa + 令 biểu âm. Nghĩa: xách, nâng lên bằng tay, cầm bằng ngón tay hoặc cổ tay. Chủ yếu dùng trong khẩu ngữ miền Bắc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xốc lên, giương lên", "Hạng Tần Suất (Jun Da)": "3374.0", "Tần Suất % (Jun Da)": "99.4743525171", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拎", "Unihan_Traditional (Chữ Phồn thể)": "拎", "Pinyin_Xie": "līn", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động dùng tay xách hoặc nhấc vật gì đó lên, thường mang theo tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | līn | / | xách | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巳', '{"9000": "3375.0", "Chữ Trung Quốc": "巳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 己 | Số nét | 3 | nét | 巳 | tị | tượng hình | địa chi thứ sáu; hình thai nhi | 巳 là tượng hình, không có thành phần cấu tạo. Theo Wiktionary, có hai thuyết: (1) tượng hình thai nhi (thấy trong 包, 胞); (2) tượng hình con rắn. Đây là một trong 12 địa chi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tị\": con rắn cuộn tròn — tị là địa chi thứ sáu, ứng với năm con rắn, giờ 9-11 sáng. | Gương Hán-Việt | tị — trong \"tị thời\" (巳时, giờ Tị), \"Canh Tị\" (năm con rắn) | Mở khoá kiến thức | Biết 巳 mở khoá hệ thống 12 địa chi: 子丑寅卯辰巳午未申酉戌亥 — tị là vị trí thứ 6.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Theo Wiktionary, 巳 là chữ tượng hình với hai thuyết: (1) hình thai nhi nằm cuộn — thấy cấu trúc này trong các chữ 包, 胞; (2) hình con rắn — liên quan đến Tị trong thập nhị địa chi ứng với con rắn. Giáp cốt văn, kim văn và đại triện đều xác nhận. Giờ Tị: 9-11 giờ sáng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kỷ; tỵ (ngôi sao thứ sáu trong địa chi); tỵ; con rắn (trong 12 con giáp)", "Hạng Tần Suất (Jun Da)": "3375.0", "Tần Suất % (Jun Da)": "99.4749602564", "GavinGrover_Once (Chiết tự trực tiếp)": "尸 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱尸乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "尸", "Unihan_Simplified (Chữ Giản thể)": "巳", "Unihan_Traditional (Chữ Phồn thể)": "巳", "Pinyin_Xie": "sì", "Âm Hán Việt_Xie": "tị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ thời gian như giờ Tị hoặc vị trí thứ sáu trong hệ thống Địa Chi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邢', '{"9000": "3376.0", "Chữ Trung Quốc": "邢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 6 | nét | 邢 | hình | tượng hình | tên đất cổ ở Hà Bắc | 邢 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 开/刑 phần trái + 阝(phụ, đất) phần phải, có thể là hình thanh chỉ địa danh. Chỉ có dạng Lục thư thông, chưa tìm thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hình\": vùng đất (阝) mang tên nước Hình thời cổ —邢 là địa danh và họ người Trung Quốc. | Gương Hán-Việt | hình — trong \"Hình Đài\" (邢台, thành phố Hà Bắc), \"họ Hình\" (邢姓) | Mở khoá kiến thức | Biết 邢 mở khoá: 邢台 (Hình Đài, thành phố Hà Bắc), 邢姓 (họ Hình).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary không có cấu trúc hình thành chi tiết cho 邢. Chữ này chủ yếu là tên đất cổ (nước Hình/邢 thời Chu) ở vùng Hà Bắc ngày nay, và là họ người (họ Hình). chưa có nguồn học thuật xác nhận cấu trúc. Chỉ có hình ảnh Lục thư thông, chữ tạo muộn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "3376.0", "Tần Suất % (Jun Da)": "99.4755679957", "GavinGrover_Once (Chiết tự trực tiếp)": "开 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰开阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "开", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "邢", "Unihan_Traditional (Chữ Phồn thể)": "邢", "Pinyin_Xie": "xíng", "Âm Hán Việt_Xie": "hình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ họ người hoặc địa danh cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('廿', '{"9000": "3377.0", "Chữ Trung Quốc": "廿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 廾 | Số nét | 4 | nét | 廿 | niệm | tượng hình | hai mươi, 20 | 廿 là chữ tượng hình: hai chữ 十 (thập, mười) viết cạnh nhau với nét ngang dưới hợp nhất — biểu thị số 20. Đây là cách viết gọn của 二十.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niệm\": hai chữ thập (十+十) ghép lại — niệm là hai mươi, số 20 viết liền tay. | Gương Hán-Việt | niệm — trong \"nhị thập\" (二十) viết gọn thành 廿, ít dùng trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 廿 mở khoá hệ thống số Hán cổ: 廿(20), 卅(30), 卌(40) — các chữ số gộp đặc biệt.", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Theo Wiktionary, 廿 là chữ tượng hình: hai chữ 十 (mười) viết cạnh nhau, nét ngang dưới hợp thành một. Biểu thị số hai mươi (20). Kim văn, bạch thư và đại triện đều xác nhận hình dạng này. Dùng phổ biến trong lịch âm và văn bản ngày tháng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hai mươi, 20", "Hạng Tần Suất (Jun Da)": "3377.0", "Tần Suất % (Jun Da)": "99.4761752182", "GavinGrover_Once (Chiết tự trực tiếp)": "卄 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴卄一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "廿", "Unihan_Traditional (Chữ Phồn thể)": "廿", "Pinyin_Xie": "niàn", "Âm Hán Việt_Xie": "nhập", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Dùng như số từ để biểu thị số lượng hai mươi, thường xuất hiện trong văn viết cổ hoặc ghi ngày tháng. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搀', '{"9000": "3378.0", "Chữ Trung Quốc": "搀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 𫥎 | sàm | biểu âm | (cho âm chān) | 搀 là dạng giản thể của 攙: 扌(Thủ, biểu nghĩa: tay) + 𫥎 (Sàm, biểu âm); chữ hình thanh. Tay là bộ phận thực hiện hành động đỡ; phần âm cho âm chān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sam\": tay (扌) sam đỡ — sam thủ, đưa tay ra nâng đỡ người yếu. | Gương Hán-Việt | \"sam\" ít gặp độc lập; 搀 dùng trong 搀扶 (nâng đỡ dìu dắt) | Mở khoá kiến thức | Biết 搀 mở khoá 搀扶 (dìu đỡ, nâng đỡ), 搀杂 (pha trộn lẫn lộn), 搀和 (trộn lẫn).", "Tự nguyên_Xie": "Tiểu triện | 搀 (phồn thể 攙) là dạng giản hóa. Cấu trúc: 扌(thủ — tay) biểu nghĩa; phần âm cho âm chān. Nghĩa gốc là dùng tay đỡ người yếu hơn, nâng đỡ; nghĩa mở rộng là trộn lẫn, pha vào. Chưa có nguồn học thuật cổ đại xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nâng đỡ; để lẫn lộn", "Hạng Tần Suất (Jun Da)": "3378.0", "Tần Suất % (Jun Da)": "99.4767808904", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "搀", "Unihan_Traditional (Chữ Phồn thể)": "攙", "Pinyin_Xie": "chān", "Âm Hán Việt_Xie": "sam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động dìu người khác hoặc trộn lẫn các chất với nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chān | / | đỡ bằng tay | / | chān | / | trộn | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các mối quan hệ tôi | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曙', '{"9000": "3379.0", "Chữ Trung Quốc": "曙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 17 | nét | 日 | nhật | biểu nghĩa | mặt trời | 暑 | thử | biểu âm | nóng, mùa hè | 曙 = 日(Nhật, biểu nghĩa: mặt trời) + 暑(Thử, biểu âm); chữ hình thanh. Bộ nhật chỉ hiện tượng ánh sáng mặt trời, 暑 cho âm shǔ gần với thự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thự\": mặt trời (日) nóng ấm (暑) rạng lên — thự là ánh rạng đông, giờ khắc bình minh. | Gương Hán-Việt | thự — trong \"thự quang\" (曙光, ánh bình minh, tia hy vọng) | Mở khoá kiến thức | Biết 曙 mở khoá: 曙光 (ánh bình minh; tia hy vọng), 曙色 (sắc trời rạng sáng).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 曙 là chữ hình thanh: 日(mặt trời) biểu nghĩa + 暑 biểu âm. Nghĩa gốc: rạng sáng, lúc mặt trời mới mọc. Mở rộng nghĩa: ánh sáng ban mai, tia hy vọng (曙光 — tia sáng đầu tiên của ngày mới). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rạng sáng", "Hạng Tần Suất (Jun Da)": "3379.0", "Tần Suất % (Jun Da)": "99.4773860458", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 署", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日署", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "署", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曙", "Unihan_Traditional (Chữ Phồn thể)": "曙", "Pinyin_Xie": "shǔ", "Âm Hán Việt_Xie": "thự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng đầu câu hoặc kết hợp với các từ khác để chỉ thời điểm sáng sớm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('樵', '{"9000": "3380.0", "Chữ Trung Quốc": "樵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 樵 | tiều | tượng hình | củi; người đốn củi | 樵 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 木(mộc, gỗ/cây) + 焦(tiêu, cháy) hoặc 角/谯, nhiều khả năng là hình thanh với 木 biểu nghĩa vật liệu gỗ. Chưa có nguồn học thuật xác nhận cấu trúc chính xác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiều\": người vào rừng chặt cây (木) — tiều là tiều phu, người đốn củi trong truyện cổ. | Gương Hán-Việt | tiều — trong \"tiều phu\" (樵夫, người đốn củi), \"tiều tụy\" (khác chữ, dễ nhầm) | Mở khoá kiến thức | Biết 樵 mở khoá: 樵夫 (tiều phu), 渔樵 (người đánh cá và người đốn củi), hình ảnh ẩn dật cổ.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} cho 樵 mà không có cấu trúc chi tiết. Theo hình dạng, bộ 木(gỗ) + phần biểu âm, có thể là hình thanh. Nghĩa gốc: củi, gỗ chẻ; người đốn củi (tiều phu). Nhân vật tiều phu (樵夫) là hình ảnh quen thuộc trong thơ văn cổ. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "người đốn củi", "Hạng Tần Suất (Jun Da)": "3380.0", "Tần Suất % (Jun Da)": "99.4779901676", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "樵", "Unihan_Traditional (Chữ Phồn thể)": "樵", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "tiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ tiều phu hoặc động từ chỉ hành động kiếm củi trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('隅', '{"9000": "3381.0", "Chữ Trung Quốc": "隅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 11 | nét | 𨸏 | phụ | biểu nghĩa | gò đất, đồi | 禺 | ngung | biểu âm | 隅 = 𨸏/阝(Phụ, biểu nghĩa: gò đất) + 禺(Ngung, biểu âm); chữ hình thanh. Bộ phụ 阝chỉ địa hình, 禺 cho âm yú gần với ngung.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngung\": gò đất (阝) ở góc xa (禺) — ngung là góc khuất, nơi hẻo lánh. | Gương Hán-Việt | ngung — trong \"ngung lạc\" (隅落, góc khuất), \"tứ ngung\" (四隅, bốn góc) | Mở khoá kiến thức | Biết 隅 mở khoá: 一隅 (một góc), 负隅顽抗 (dựa góc tường kháng cự đến cùng), 四隅 (bốn góc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 隅 là chữ hình thanh: 𨸏(阜, gò đất) biểu nghĩa + 禺 biểu âm. Nghĩa gốc: góc của vùng đất, nơi ở xa trung tâm, nơi hẻo lánh. Cũng nghĩa góc tường, góc phòng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất ngoài ven; cạnh góc", "Hạng Tần Suất (Jun Da)": "3381.0", "Tần Suất % (Jun Da)": "99.4785932559", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 禺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝禺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "隅", "Unihan_Traditional (Chữ Phồn thể)": "隅", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "ngung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ chỉ phương vị | 方位词 | Thường làm danh từ chỉ vị trí góc khuất hoặc kết hợp làm từ chỉ phương vị. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ chỉ phương vị | 方位词 | Chỉ vị trí và đứng SAU danh từ — 桌子上, 家里 — chứ không đứng trước như ''trên bàn'', ''trong nhà''. Thường đi cùng 在.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筛', '{"9000": "3382.0", "Chữ Trung Quốc": "筛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, vật bằng tre | 师 | sư | biểu âm | (cho âm shāi) | 筛 = 竹 (Trúc, biểu nghĩa: tre) + 师 (Sư, biểu âm); chữ hình thanh. Bộ trúc chỉ vật liệu làm bằng tre; 师 cho âm shāi (gần sī).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"si\": tre (竹) dưới tay thầy (師) — si sàng, thầy dùng rây tre để sàng lọc học trò. | Gương Hán-Việt | \"si\" ít dùng độc lập trong tiếng Việt hiện đại; 筛 dùng trong 筛选 (sàng lọc) | Mở khoá kiến thức | Biết 筛 mở khoá 筛选 (sàng lọc, tuyển chọn), 筛子 (cái rây), 过筛 (lọc qua rây).", "Tự nguyên_Xie": "Lục thư thông | 筛 (phồn thể 篩) là chữ hình thanh: bộ 竹 (trúc — tre) biểu nghĩa, vì cái rây xưa làm bằng tre; 師 (sư) cho âm. Theo Wiktionary, nghĩa là cái rây, sàng, lọc; động từ là rây, sàng qua. Cũng dùng để chỉ việc lọc lựa (筛选 — sàng lọc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái dần, cái sàng", "Hạng Tần Suất (Jun Da)": "3382.0", "Tần Suất % (Jun Da)": "99.4791958273", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 师", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮师", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "师", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筛", "Unihan_Traditional (Chữ Phồn thể)": "篩", "Pinyin_Xie": "shāi", "Âm Hán Việt_Xie": "si, sư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ đứng trước danh từ chỉ vật cần lọc hoặc làm danh từ chỉ dụng cụ sàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shāi | / | rây | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谒', '{"9000": "3383.0", "Chữ Trung Quốc": "谒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 谒 | yết | tượng hình | yết kiến, vào hầu; danh thiếp | 谒 là chữ giản thể của 謁. Theo hình dạng gồm 讠(ngôn, lời nói) biểu nghĩa + 曷(hạt) biểu âm, là chữ hình thanh chỉ hành động lời nói trong giao tiếp chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yết\": lời nói (讠) trình diện — yết là yết kiến, vào hầu chuyện với người trên. | Gương Hán-Việt | yết — trong \"yết kiến\" (谒见, vào hầu), \"bái yết\" (拜谒, bái yết lăng mộ/người lớn) | Mở khoá kiến thức | Biết 谒 mở khoá: 谒见 (yết kiến), 拜谒 (bái yết), 谒陵 (viếng lăng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 谒 (giản thể của 謁) là chữ hình thanh: 讠(言, lời nói) biểu nghĩa + 曷 biểu âm. Đại triện và tiểu triện đã xác nhận. Nghĩa gốc: vào hầu, yết kiến bậc trên; cũng là danh thiếp hoặc thiệp trình diện thời cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yết kiến, hầu chuyện; bảo, cáo; danh thiếp; người canh cửa", "Hạng Tần Suất (Jun Da)": "3383.0", "Tần Suất % (Jun Da)": "99.4797968485", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谒", "Unihan_Traditional (Chữ Phồn thể)": "謁", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "yết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ người có địa vị cao hơn để thể hiện sự tôn kính. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倭', '{"9000": "3384.0", "Chữ Trung Quốc": "倭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 委 | uỷ | biểu âm | uỷ thác, cúi xuống | 倭 = 亻(Nhân, biểu nghĩa: người) + 委(Uỷ, biểu âm); chữ hình thanh. Bộ nhân chỉ con người, 委 cho âm wō.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oải\": người (亻) cúi khom (委) — oải/oa chỉ người lùn; tên cổ gọi người Nhật Bản trong sử cũ. | Gương Hán-Việt | oải/oa — trong \"Oa khấu\" (倭寇, giặc Nhật), \"Oa quốc\" (倭国, tên cổ của Nhật Bản) | Mở khoá kiến thức | Biết 倭 mở khoá: 倭寇 (Oa khấu, cướp biển Nhật cổ), 倭国 (Oa quốc, Nhật Bản cổ), ngữ cảnh lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 倭 là chữ hình thanh: 亻(人, người) biểu nghĩa + 委 biểu âm. Nghĩa gốc: lùn, thấp người. Sau dùng chỉ người Nhật Bản (theo cách gọi cổ của Trung Quốc — mang hàm ý miệt thị). Trong lịch sử Việt Nam, 倭寇 (Oa khấu) chỉ giặc Nhật. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lùn, thấp; người Nhật Bản", "Hạng Tần Suất (Jun Da)": "3384.0", "Tần Suất % (Jun Da)": "99.4803963192", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 委", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻委", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "委", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倭", "Unihan_Traditional (Chữ Phồn thể)": "倭", "Pinyin_Xie": "wō", "Âm Hán Việt_Xie": "oa, nụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ nước Nhật cổ hoặc làm định ngữ bổ nghĩa cho danh từ để chỉ tính chất lùn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痹', '{"9000": "3385.0", "Chữ Trung Quốc": "痹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 13 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 畀 | tý | biểu âm | (cho âm bì) | 痹 = 疒(Nạch, biểu nghĩa: bệnh tật) + 畀 (Tý, biểu âm); chữ hình thanh. Bộ nạch (疒) chỉ các loại bệnh; 畀 cho âm bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": bệnh (疒) tý liệt — tê cứng, không cảm giác, như bị tý đánh vào. | Gương Hán-Việt | \"tê\" trong \"tê liệt\" (麻痹 — mất cảm giác); \"tê\" còn dùng độc lập trong tiếng Việt | Mở khoá kiến thức | Biết 痹 mở khoá 麻痹 (tê liệt, thiếu cảnh giác), 风湿性关节炎引起的痹症 (chứng tê khớp do thấp khớp).", "Tự nguyên_Xie": "Tiểu triện | 痹 là chữ hình thanh: bộ 疒 (nạch — bệnh) biểu nghĩa; 畀 (tý) cho âm bì. Theo Wiktionary, 痹 là dạng thông thường của 痺, nghĩa là tê liệt, cứng khớp do bệnh, không cảm giác. Trong y học Trung Quốc cổ truyền, đây là chứng bệnh tê mỏi gân cốt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bị tê liệt", "Hạng Tần Suất (Jun Da)": "3385.0", "Tần Suất % (Jun Da)": "99.4809947564", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 畀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒畀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痹", "Unihan_Traditional (Chữ Phồn thể)": "痺", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ chứng bệnh tê liệt hoặc làm vị ngữ biểu thị trạng thái mất cảm giác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猖', '{"9000": "3386.0", "Chữ Trung Quốc": "猖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 犭 | khuyển | biểu nghĩa | chó, thú dữ | 昌 | xương | biểu âm | thịnh vượng | 猖 = 犭/犬(Khuyển, biểu nghĩa: chó/thú dữ) + 昌(Xương, biểu âm); chữ hình thanh. Bộ khuyển gợi sự hung dữ hoang dã, 昌 cho âm chāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xương\": thú dữ (犭) hung xương xương — xương là hung dữ, điên cuồng, ngang ngược. | Gương Hán-Việt | xương — trong \"xương cuồng\" (猖狂, điên cuồng ngang ngược) | Mở khoá kiến thức | Biết 猖 mở khoá: 猖狂 (điên cuồng, hoành hành), 猖獗 (ngang ngược hoành hành, bùng phát).", "Tự nguyên_Xie": "Theo Wiktionary, 猖 là chữ hình thanh: 犭(犬, chó) biểu nghĩa + 昌 biểu âm. Nghĩa gốc: hung dữ, điên cuồng, hoang loạn. Thường dùng trong tổ hợp 猖狂 (điên cuồng, hoành hành ngang ngược). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "độc, dữ", "Hạng Tần Suất (Jun Da)": "3386.0", "Tần Suất % (Jun Da)": "99.4815926768", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猖", "Unihan_Traditional (Chữ Phồn thể)": "猖", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "xương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước động từ để miêu tả trạng thái hoạt động dữ dội, ngang ngược. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佯', '{"9000": "3387.0", "Chữ Trung Quốc": "佯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 佯 | dương | tượng hình | giả vờ, làm bộ | 佯 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 亻(nhân, người) + 羊(dương, dê) hoặc 详 rút gọn, nhiều khả năng là hình thanh với 亻 biểu nghĩa người và phần còn lại biểu âm. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dương\": người (亻) hiền như dê (羊) mà thực ra giả vờ — dương là giả vờ, làm bộ. | Gương Hán-Việt | dương — trong \"giả dương\" (假佯, giả vờ), ít dùng độc lập | Mở khoá kiến thức | Biết 佯 mở khoá: 佯装 (giả vờ, giả trang), 佯攻 (tấn công giả, nghi binh), 佯死 (giả chết).", "Tự nguyên_Xie": "Wiktionary chỉ ghi {{Han etym}} cho 佯 mà không có cấu trúc chi tiết. Theo hình dạng, 亻(người) + 羊(dê) gợi người giả vờ hiền lành như dê. Nghĩa: giả vờ, làm bộ, giả trang. chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thảng dương 徜佯)", "Hạng Tần Suất (Jun Da)": "3387.0", "Tần Suất % (Jun Da)": "99.4821890468", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 羊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佯", "Unihan_Traditional (Chữ Phồn thể)": "佯", "Pinyin_Xie": "yáng", "Âm Hán Việt_Xie": "dương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm phó từ đứng trước động từ khác để chỉ hành động giả vờ làm việc gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肛', '{"9000": "3388.0", "Chữ Trung Quốc": "肛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 7 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 工 | công | biểu âm | công việc, thợ | 肛 = 肉/月(Nhục, biểu nghĩa: thịt/cơ thể) + 工(Công, biểu âm); chữ hình thanh. Bộ nhục xác định bộ phận cơ thể, 工 cho âm gāng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giang\": thịt (月) phần cuối cùng (工) của ống tiêu hóa — giang là hậu môn. | Gương Hán-Việt | giang — trong \"giang môn\" (肛门, hậu môn), \"trực giang\" (直肠肛管, trực tràng hậu môn) | Mở khoá kiến thức | Biết 肛 mở khoá: 肛门 (hậu môn), 肛肠 (hậu môn và trực tràng), từ vựng y học cơ bản.", "Tự nguyên_Xie": "Theo Wiktionary, 肛 là chữ hình thanh: 肉(thịt/cơ thể) biểu nghĩa + 工 biểu âm. Nghĩa: hậu môn, lỗ đít. Là từ y học chính thức chỉ phần cuối của đường tiêu hóa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lỗ đít, hậu môn", "Hạng Tần Suất (Jun Da)": "3388.0", "Tần Suất % (Jun Da)": "99.4827817994", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 工", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月工", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "工", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "肛", "Unihan_Traditional (Chữ Phồn thể)": "疘", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "giang, khang, xoang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các từ y học để chỉ bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奚', '{"9000": "3389.0", "Chữ Trung Quốc": "奚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 10 | nét | 奚 | hề | tượng hình | đứa ở, kẻ hầu; sao, tại sao (hư từ cổ) | 奚 là chữ hội ý. Theo Wiktionary: bàn tay (爪) nắm đầu tóc (幺) của người nô lệ (大) — hình ảnh tay chủ túm tóc kẻ hầu. Giáp cốt văn, kim văn, bạch thư và tiểu triện đều xác nhận cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hề\": bàn tay túm tóc kẻ hầu — hề là đứa ở, kẻ bị sai khiến; cũng là hư từ hỏi cổ. | Gương Hán-Việt | hề — trong \"hề lộ\" (奚落, chế nhạo), ít dùng độc lập hiện đại | Mở khoá kiến thức | Biết 奚 mở khoá: 奚落 (chế nhạo, mỉa mai), hiểu nguồn gốc chế độ nô lệ qua chữ Hán.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 奚 là chữ hội ý: bàn tay 爪 túm lấy đầu tóc 幺 của người nô lệ 大. Hình ảnh sinh động về chế độ nô lệ cổ đại. Nghĩa gốc: đứa ở, kẻ hầu hạ. Sau dùng làm hư từ hỏi: sao, tại sao (如...奚如). Giáp cốt văn xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "746.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (241) Yêu (014) Đại (017)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trảo (số 241 - bàn tay) ở trên chữ Yêu (số 014 - nhỏ) và chữ Đại (số 017 - to/người). Hình bàn tay (Trảo) đang sai khiến đứa đầy tớ nhỏ (Yêu) làm việc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Hề là đứa ở, đầy tớ gái (hoặc quan lại bị phạt làm nô lệ).", "Nghĩa Tiếng Việt_Xie": "đứa ở", "Hạng Tần Suất (Jun Da)": "3389.0", "Tần Suất % (Jun Da)": "99.4833745519", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + 𡗞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫𡗞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𡗞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "奚", "Unihan_Traditional (Chữ Phồn thể)": "奚", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Danh từ | 名词 | Thường làm đại từ nghi vấn đứng trước động từ trong văn ngôn cổ để hỏi lý do hoặc sự vật. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甭', '{"9000": "3390.0", "Chữ Trung Quốc": "甭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 用 | Số nét | 9 | nét | 不 | bất | biểu nghĩa | không, phủ định | 用 | dụng | biểu nghĩa | dùng, cần | 甭 là chữ hội ý ghép từ 不 (Bất — không) + 用 (Dụng — dùng); tổng hợp nghĩa thành \"không cần dùng\". Đây là chữ tạo muộn, xuất hiện trong khẩu ngữ Bắc Kinh, chưa thấy trong giáp cốt hay kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bằng\": bất (不) dụng (用) xếp chồng — bằng lòng không dùng, tức là không cần. | Gương Hán-Việt | \"bằng\" ít dùng trong văn cổ; 甭 là chữ khẩu ngữ Bắc Kinh, không có từ Hán-Việt tương ứng phổ biến | Mở khoá kiến thức | Biết 甭 mở khoá cách nói khẩu ngữ: 甭客气 (đừng khách khí), 甭管 (đừng bận tâm), 甭提了 (đừng nhắc nữa).", "Tự nguyên_Xie": "甭 là chữ hội ý được tạo muộn trong tiếng Quan Thoại Bắc Kinh (phương ngữ): 不 (bất — không) + 用 (dụng — cần/dùng) = không cần. Chữ này là dạng viết rút gọn ngữ âm của 不用 (bù yòng). Không có nguồn học thuật cổ đại; chưa thấy trong giáp cốt hay kim văn. Chữ tạo muộn, dùng trong khẩu ngữ, không có trong văn viết chính thức. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đừng, khỏi, không phải, không cần", "Hạng Tần Suất (Jun Da)": "3390.0", "Tần Suất % (Jun Da)": "99.4839667877", "GavinGrover_Once (Chiết tự trực tiếp)": "不 + 用", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱不用", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "用", "Unihan_Simplified (Chữ Giản thể)": "甭", "Unihan_Traditional (Chữ Phồn thể)": "甭", "Pinyin_Xie": "béng", "Âm Hán Việt_Xie": "bằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường làm phó từ đứng trước động từ hoặc tính từ để biểu thị sự phủ định hoặc khuyên ngăn. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | béng | / | đừng | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Các từ chức năng và bổ trợ", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抨', '{"9000": "3391.0", "Chữ Trung Quốc": "抨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 平 | bình | biểu âm | bằng phẳng | 抨 = 扌(Thủ, biểu nghĩa: tay) + 平(Bình, biểu âm); chữ hình thanh. Bộ thủ chỉ hành động tay, 平 cho âm pēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"banh\": bàn tay (扌) đánh banh ra — banh là công kích bằng lời, phê phán mạnh mẽ. | Gương Hán-Việt | banh — ít dùng trong Hán-Việt cổ, chủ yếu gặp trong 抨击 | Mở khoá kiến thức | Biết 抨 mở khoá: 抨击 (công kích, phê phán gay gắt), 抨弹 (phê phán, đàn hặc).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 抨 là chữ hình thanh: 扌(手, tay) biểu nghĩa + 平 biểu âm. Nghĩa gốc: bắt bẻ, phê phán mạnh, đánh bằng lời nói. Thường dùng trong 抨击 (công kích, chỉ trích gay gắt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt bẻ, công kích", "Hạng Tần Suất (Jun Da)": "3391.0", "Tần Suất % (Jun Da)": "99.4845590235", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抨", "Unihan_Traditional (Chữ Phồn thể)": "抨", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong các từ ghép để chỉ hành động công kích hoặc phê phán mạnh mẽ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛾', '{"9000": "3392.0", "Chữ Trung Quốc": "蛾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 我 | ngã | biểu âm | tôi | 蛾 = 虫(Trùng, biểu nghĩa: sâu/côn trùng) + 我(Ngã, biểu âm); chữ hình thanh. Bộ trùng xác định loài vật, 我 cho âm é gần với nga.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nga\": sâu (虫) tôi (我) hóa thành bướm đêm — nga là con ngài, cũng là lông mày cong đẹp. | Gương Hán-Việt | nga — trong \"nga mi\" (蛾眉, mày ngài — lông mày đẹp), \"phi nga\" (飞蛾, bướm đêm) | Mở khoá kiến thức | Biết 蛾 mở khoá: 飞蛾 (bướm đêm), 蛾眉 (mày ngài, mày đẹp trong thơ), 蚕蛾 (ngài tằm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 蛾 là chữ hình thanh: 虫(sâu/côn trùng) biểu nghĩa + 我 biểu âm. Nghĩa gốc: con ngài, bướm đêm (moth). Nghĩa mở rộng: lông mày cong đẹp như cánh ngài (蛾眉 — mày ngài, mày đẹp trong thơ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngài; lông mày", "Hạng Tần Suất (Jun Da)": "3392.0", "Tần Suất % (Jun Da)": "99.4851507425", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 我", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫我", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "我", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛾", "Unihan_Traditional (Chữ Phồn thể)": "蛾", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "nga, nghĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài côn trùng hoặc dùng trong văn thơ để tả lông mày đẹp của phụ nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唠', '{"9000": "3393.0", "Chữ Trung Quốc": "唠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 劳 | lao | biểu âm | (cho âm láo) | 唠 = 口 (Khẩu, biểu nghĩa: miệng) + 劳 (Lao, biểu âm); chữ hình thanh. Miệng là cơ quan nói; 劳 cho âm láo — nói mãi như lao động không ngừng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lao\": miệng (口) lao xao không nghỉ — lao khổ bằng miệng, nói lải nhải suốt ngày. | Gương Hán-Việt | \"lao\" trong \"lao đao\" (gian khó), nhưng 唠 chỉ hành động nói lắm; 劳 (lao) trong 劳动 (lao động) | Mở khoá kiến thức | Biết 唠 mở khoá 唠叨 (lải nhải, nói không ngừng), 嗯唠 (ừ hả, giao tiếp), 唠嗑 (nói chuyện tán gẫu — phương ngữ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 唠 (phồn thể 嘮) là chữ hình thanh: bộ 口 (khẩu — miệng) biểu nghĩa; 勞 (lao) cho âm. Theo Wiktionary, nghĩa chính là nói lải nhải, liên tục lặp đi lặp lại. Âm láo dùng cho nghĩa nói nhai nhải; âm lào (thanh 4) dùng cho nghĩa nói chuyện thân mật (phương ngữ bắc). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hót líu lo; nói nhiều", "Hạng Tần Suất (Jun Da)": "3393.0", "Tần Suất % (Jun Da)": "99.4857414279", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 劳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口劳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唠", "Unihan_Traditional (Chữ Phồn thể)": "嘮", "Pinyin_Xie": "láo", "Âm Hán Việt_Xie": "lao, lạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong khẩu ngữ để chỉ việc nói chuyện phiếm hoặc cằn nhằn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荧', '{"9000": "3394.0", "Chữ Trung Quốc": "荧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荧 | huỳnh | tượng hình | ánh sáng nhỏ, le lói; huỳnh quang | 荧 là chữ giản thể của 熒. Theo Wiktionary, 熒 là chữ tượng hình/chỉ sự: hình ảnh lửa đuốc cháy sáng trong bóng đêm — kim văn thể hiện ngọn lửa nhỏ. Dạng giản thể hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huỳnh\": ánh lửa (火) nhỏ le lói — huỳnh là ánh sáng huỳnh quang, ánh đèn mờ ảo. | Gương Hán-Việt | huỳnh — trong \"huỳnh quang\" (荧光, ánh sáng huỳnh quang), \"huỳnh bình\" (荧屏, màn hình) | Mở khoá kiến thức | Biết 荧 mở khoá: 荧屏 (màn hình TV), 荧光 (huỳnh quang), 荧光笔 (bút dạ quang).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 荧 (giản thể của 熒) ban đầu là chữ tượng hình mô tả ngọn lửa nhỏ le lói trong đêm. Kim văn có hình ảnh lửa đuốc cháy. Nghĩa gốc: ánh sáng nhỏ, ánh đèn le lói. Hiện dùng trong 荧屏 (màn hình TV) và 荧光 (huỳnh quang). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "soi sáng", "Hạng Tần Suất (Jun Da)": "3394.0", "Tần Suất % (Jun Da)": "99.4863315965", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "荧", "Unihan_Traditional (Chữ Phồn thể)": "熒", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ ánh sáng lung linh, mờ ảo hoặc làm danh từ trong các thuật ngữ khoa học. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵩', '{"9000": "3395.0", "Chữ Trung Quốc": "嵩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 13 | nét | 山 | sơn | biểu nghĩa | núi | 高 | cao | biểu nghĩa | cao | 嵩 = 山(Sơn) + 高(Cao); chữ hội ý. Núi (山) cao ngất (高) — hình ảnh ngọn núi Tung Sơn (Trung Nhạc) hùng vĩ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tung\": núi (山) cao (高) tung trời — tung là núi cao sừng sững, đặc biệt là Tung Sơn trong Ngũ Nhạc. | Gương Hán-Việt | tung — trong \"Tung Sơn\" (嵩山, Trung Nhạc), \"tung cao\" (嵩高, cao vút) | Mở khoá kiến thức | Biết 嵩 mở khoá: 嵩山 (Tung Sơn, nơi có Thiếu Lâm Tự), 五岳 (Ngũ Nhạc — 5 ngọn núi thiêng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 嵩 là chữ hội ý: 山(núi) + 高(cao), biểu thị núi cao sừng sững. Chỉ núi Tung Sơn (嵩山, Trung Nhạc), một trong Ngũ Nhạc của Trung Quốc, nằm ở Hà Nam. Đại triện và tiểu triện xác nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao sừng sững; núi Tung", "Hạng Tần Suất (Jun Da)": "3395.0", "Tần Suất % (Jun Da)": "99.4869217651", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 高", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山高", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "高", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵩", "Unihan_Traditional (Chữ Phồn thể)": "嵩", "Pinyin_Xie": "sōng", "Âm Hán Việt_Xie": "tung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ tả núi cao hoặc làm danh từ riêng chỉ núi Tung Sơn ở Trung Quốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漱', '{"9000": "3396.0", "Chữ Trung Quốc": "漱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 漱 | thấu | tượng hình | súc miệng; xói mòn | 漱 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 氵(thủy, nước) + 欶/束 hoặc phần biểu âm khác, nhiều khả năng là hình thanh với bộ thủy biểu nghĩa nước. Chưa có nguồn học thuật xác nhận cấu trúc chính xác.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thấu\": nước (氵) thấu vào miệng rồi nhổ ra — thấu là súc miệng, làm sạch răng miệng. | Gương Hán-Việt | thấu — ít gặp độc lập, trong \"thấu khẩu\" (漱口, súc miệng) | Mở khoá kiến thức | Biết 漱 mở khoá: 漱口 (súc miệng), 漱口水 (nước súc miệng), 含漱 (ngậm súc miệng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} cho 漱 mà không có cấu trúc chi tiết. Theo hình dạng, bộ 氵(nước) biểu nghĩa, nghĩa gốc: súc miệng, làm sạch miệng bằng nước. Cũng có nghĩa xói mòn (nước chảy mãi mòn đá). chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1655.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Sóc (1654)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Sóc (số 1654 - mút hút/ 欶 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Sóc chỉ âm, bộ Thủy chỉ ý. Sấu là dùng nước súc miệng cho sạch (sấu khẩu, sấu tẩy).", "Nghĩa Tiếng Việt_Xie": "súc miệng; xói mòn; giặt", "Hạng Tần Suất (Jun Da)": "3396.0", "Tần Suất % (Jun Da)": "99.4875103834", "GavinGrover_Once (Chiết tự trực tiếp)": "涑 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰涑欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "涑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "漱", "Unihan_Traditional (Chữ Phồn thể)": "漱", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "sấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động súc miệng hoặc rửa sạch bằng nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酋', '{"9000": "3397.0", "Chữ Trung Quốc": "酋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 9 | nét | 酋 | tù | tượng hình | rượu lâu năm; tù trưởng | 酋 là chữ tượng hình. Theo Wiktionary: chất lỏng (八, chỉ phần chất lỏng nổi lên) trên bình rượu (酉) — hình ảnh rượu đang ủ chín. Tiểu triện xác nhận cấu trúc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tù\": rượu (酉) chín muồi (八) — tù là thủ lĩnh, tù trưởng, cũng là rượu lâu năm. | Gương Hán-Việt | tù — trong \"tù trưởng\" (酋长, thủ lĩnh bộ lạc), ít dùng độc lập hiện đại | Mở khoá kiến thức | Biết 酋 mở khoá: 酋长 (tù trưởng, thủ lĩnh), 敌酋 (thủ lĩnh kẻ địch).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 酋 là chữ tượng hình: 八 (chỉ chất lỏng nổi) + 酉 (bình rượu) — hình ảnh rượu đang ủ chín trong bình. Nghĩa gốc: quan cai quản việc rượu; rượu lâu năm, chín muồi. Mở rộng sang nghĩa: tù trưởng, thủ lĩnh (người đứng đầu). Tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một chức quan coi về việc rượu; ông tướng", "Hạng Tần Suất (Jun Da)": "3397.0", "Tần Suất % (Jun Da)": "99.4880984849", "GavinGrover_Once (Chiết tự trực tiếp)": "丷 + 酉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丷酉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "酉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丷", "Unihan_Simplified (Chữ Giản thể)": "酋", "Unihan_Traditional (Chữ Phồn thể)": "酋", "Pinyin_Xie": "qiú", "Âm Hán Việt_Xie": "tù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ thủ lĩnh của các bộ tộc hoặc kẻ cầm đầu băng nhóm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攘', '{"9000": "3398.0", "Chữ Trung Quốc": "攘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 20 | nét | 攘 | nhường | tượng hình | trộm cắp; xô đẩy, hỗn loạn | 攘 không có cấu trúc IDS xác nhận. Theo hình dạng gồm 扌(thủ, tay) + 襄(tương) biểu âm, nhiều khả năng là hình thanh với bộ thủ biểu nghĩa hành động tay và 襄 biểu âm rǎng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhường\": bàn tay (扌) nhường nhịn hay xô đẩy — nhường/nhương là trộm cắp, hỗn loạn xô bồ. | Gương Hán-Việt | nhường — trong \"nhương nhương\" (攘攘, đông đúc, xô bồ), \"trừ nhương\" (除攘, dẹp loạn) | Mở khoá kiến thức | Biết 攘 mở khoá: 熙熙攘攘 (náo nhiệt đông đúc), 攘夷 (đuổi người ngoài), 攘臂 (xắn tay áo, sẵn sàng chiến đấu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi {{Han etym}} cho 攘 mà không có cấu trúc chi tiết. Theo hình dạng, bộ 扌(tay) + 襄 (biểu âm) nhiều khả năng là hình thanh. Nghĩa gốc: trộm cắp, lấy trộm; xô đẩy, ẩu đả. Gặp trong 熙熙攘攘 (náo nhiệt, đông đảo xô bồ). chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ăn trộm", "Hạng Tần Suất (Jun Da)": "3398.0", "Tần Suất % (Jun Da)": "99.4886865863", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 襄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌襄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "襄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攘", "Unihan_Traditional (Chữ Phồn thể)": "攘", "Pinyin_Xie": "rǎng", "Âm Hán Việt_Xie": "nhương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ trong các từ ghép mang nghĩa xua đuổi ngoại xâm hoặc chiếm đoạt tài sản. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诘', '{"9000": "3399.0", "Chữ Trung Quốc": "诘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 吉 | cát | biểu âm | 诘 là dạng giản thể của 詰. Bộ 讠(Ngôn, biểu nghĩa: lời nói) kết hợp với 吉 (Cát, biểu âm). Chữ hình thanh — phần 讠cho biết nghĩa liên quan đến ngôn ngữ, phần 吉gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cật\" (hỏi vặn): miệng 言 liên tục hỏi 吉 — tra vấn không ngừng, như thẩm vấn căng thẳng. | Gương Hán-Việt | cật vấn (詰問) — hỏi vặn, truy cứu trách nhiệm | Mở khoá kiến thức | Biết 诘 mở khoá: 诘问 (hỏi vặn), 诘责 (khiển trách), 反诘 (phản bác bằng câu hỏi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 诘 là giản thể của 詰. Chữ phồn thể 詰 gồm bộ 言 (lời nói) và 吉 (biểu âm). Nghĩa gốc là tra vấn, hỏi vặn — dùng lời nói để chất vấn kẻ khác. Chữ xuất hiện trong văn ngôn, thường dùng trong 詰問 (hỏi vặn), 詰責 (khiển trách)。 | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hỏi vặn", "Hạng Tần Suất (Jun Da)": "3399.0", "Tần Suất % (Jun Da)": "99.4892746878", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诘", "Unihan_Traditional (Chữ Phồn thể)": "詰", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các từ khác để chỉ việc tra hỏi hoặc chất vấn kỹ lưỡng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('篡', '{"9000": "3400.0", "Chữ Trung Quốc": "篡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 16 | nét | 算 | toán | biểu âm | 竹 | trúc | biểu nghĩa | tre, vật dụng quý | 篡 gồm 竹 (Trúc) ở trên và 算 (Toán) ở dưới. Tuy nhiên cấu trúc thực tế phức tạp hơn — nguồn gốc chữ chưa được phân tích rõ qua hình thanh hay hội ý. Chưa có nguồn học thuật xác định rõ ls-code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"choán\": như kẻ cầm que tre 竹 tính toán 算 mưu kế để cướp ngôi — choán đoạt ngai vàng bằng toan tính. | Gương Hán-Việt | choán vị (篡位) — cướp ngôi vua; choán đoạt (篡夺) — chiếm đoạt quyền lực | Mở khoá kiến thức | Biết 篡 mở khoá: 篡位 (cướp ngôi), 篡夺 (đoạt quyền), 篡改 (sửa đổi bất hợp pháp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 篡 (choán) mang nghĩa cướp ngôi, đoạt quyền bằng thủ đoạn bất chính. Chữ xuất hiện trong văn ngôn với nghĩa tiếm đoạt — kẻ dưới chiếm quyền của bậc trên. Dùng trong 篡位 (cướp ngôi), 篡夺 (đoạt quyền). Wiktionary ghi nhận âm Trung cổ và cổ đại nhưng không phân tích chi tiết cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cướp, đoạt", "Hạng Tần Suất (Jun Da)": "3400.0", "Tần Suất % (Jun Da)": "99.4898622725", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "篡", "Unihan_Traditional (Chữ Phồn thể)": "篡", "Pinyin_Xie": "cuàn", "Âm Hán Việt_Xie": "soán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành vi chiếm đoạt ngôi vị hoặc quyền lực một cách bất hợp pháp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睿', '{"9000": "3401.0", "Chữ Trung Quốc": "睿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 目 | mục | biểu nghĩa | mắt | 𠙾 | biểu âm | 睿 là dạng giản thể của 叡. Chữ phức tạp, gồm phần trên biểu thị sự quan sát tinh tường (liên quan đến 目 — mắt), phần dưới biểu âm. Chữ hình thanh, biểu ý sự nhìn thấu suốt, sáng suốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duệ\": mắt 目 nhìn thấu mọi sự — người có con mắt tinh tường, trí tuệ siêu việt, xứng danh duệ trí. | Gương Hán-Việt | duệ trí (睿智) — thông minh sáng suốt; duệ kiến (睿见) — kiến giải sâu sắc | Mở khoá kiến thức | Biết 睿 mở khoá: 睿智 (thông tuệ), 睿见 (kiến giải sâu sắc), 圣睿 (thánh minh).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 睿 giản thể của 叡, mang nghĩa sáng suốt, thông minh sâu sắc. Trong văn ngôn, 叡 dùng để chỉ sự thông tuệ bậc cao — thường dùng khi nói về vua chúa hoặc thánh nhân. Wiktionary ghi nhận âm Quảng Đông jeoi6, âm Mân Nam lōe, nguồn gốc từ âm Trung cổ và cổ đại. Chữ có dạng kim văn cổ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sáng suốt, hiểu thấu", "Hạng Tần Suất (Jun Da)": "3401.0", "Tần Suất % (Jun Da)": "99.4904483069", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "睿", "Unihan_Traditional (Chữ Phồn thể)": "叡", "Pinyin_Xie": "ruì", "Âm Hán Việt_Xie": "duệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị sự thông minh, sáng suốt và thường dùng trong văn viết hoặc tên người. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噩', '{"9000": "3402.0", "Chữ Trung Quốc": "噩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 16 | nét | 噩 | ngạc | tượng hình | kinh hãi, khủng khiếp | 噩 là chữ độc thể, có liên quan đến 咢 và 喪. Theo Wiktionary, 噩 và 咢 vốn là cùng một chữ, đều bắt nguồn từ 喪. Hình dạng hiện đại gồm bốn miệng 口 xếp xung quanh một trung tâm — tượng trưng cho tiếng kêu kinh hoàng từ nhiều phía. Chưa có nguồn học thuật phân tích rõ ls-code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": bốn miệng 口口口口 cùng thét lên kinh hoàng — âm thanh ngạc nhiên khiếp đảm vang khắp nơi. | Gương Hán-Việt | ngạc mộng (噩梦) — ác mộng; ngạc hao (噩耗) — tin buồn, hung tin | Mở khoá kiến thức | Biết 噩 mở khoá: 噩梦 (ác mộng), 噩耗 (hung tin), 噩运 (vận xui).", "Tự nguyên_Xie": "噩 (ngạc) mang nghĩa kinh hãi, khủng khiếp. Wiktionary ghi nhận đây là chữ cùng gốc với 咢 và 喪. Trong hiện đại, 噩 thường xuất hiện trong 噩梦 (ác mộng) và 噩耗 (tin xấu, tin buồn). Không có ảnh cổ văn được thu thập. Chưa có nguồn học thuật xác định rõ cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kinh hãi", "Hạng Tần Suất (Jun Da)": "3402.0", "Tần Suất % (Jun Da)": "99.4910338244", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 㗊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴王㗊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㗊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "噩", "Unihan_Traditional (Chữ Phồn thể)": "噩", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để mô tả những tin tức hoặc sự việc xấu gây kinh hoàng, chấn động. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怅', '{"9000": "3403.0", "Chữ Trung Quốc": "怅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 7 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 长 | trường | biểu âm | 怅 gồm bộ 忄(Tâm, biểu nghĩa: tâm trạng) và 长 (Trường, biểu âm). Chữ hình thanh — bộ 忄cho biết đây là trạng thái tâm lý, phần 长 gợi âm đọc. Chữ mô tả cảm giác chán nản, thất vọng trong lòng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trướng\" (trong trù trướng): lòng 忄kéo dài 长 mãi không nguôi — nỗi buồn trướng lên trong ngực, não lòng. | Gương Hán-Việt | trù trướng (惆怅) — buồn bã, não lòng; trướng nhiên (怅然) — thất vọng, bẽ bàng | Mở khoá kiến thức | Biết 怅 mở khoá: 惆怅 (buồn bã), 怅然 (thất vọng), 怅惘 (bơ vơ, lạc lõng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 怅 (trù trướng) mô tả tâm trạng thất vọng, không toại nguyện. Theo Wiktionary, âm Trung cổ là chàng (MC), dùng trong văn ngôn trong các cụm như 惆怅 (buồn bã, não lòng), 怅然 (thất vọng, bẽ bàng). Seal script cho thấy cấu trúc 忄+ 长 rõ ràng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: trù trướng 惆悵)", "Hạng Tần Suất (Jun Da)": "3403.0", "Tần Suất % (Jun Da)": "99.4916188252", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 长", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄长", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "长", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怅", "Unihan_Traditional (Chữ Phồn thể)": "悵", "Pinyin_Xie": "chàng", "Âm Hán Việt_Xie": "trướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ biểu thị trạng thái buồn bã, thất vọng, hay đi kèm trong từ ghép như trướng vọng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盎', '{"9000": "3404.0", "Chữ Trung Quốc": "盎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 10 | nét | 央 | ương | biểu âm | 皿 | mãnh | biểu nghĩa | đồ đựng, chén bát | 盎 = 央 (Ương, biểu âm) + 皿 (Mãnh, biểu nghĩa: đồ đựng). Chữ hình thanh — bộ 皿cho biết đây là vật dụng đựng chứa, phần 央 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áng\": đồ đựng 皿 trung tâm 央 — cái ang đặt giữa nhà, chứa đầy ắp nước, tràn 盎然 sức sống. | Gương Hán-Việt | áng nhiên (盎然) — tràn đầy, phong phú; xuân ý 盎然 — xuân tình phơi phới | Mở khoá kiến thức | Biết 盎 mở khoá: 盎然 (tràn đầy), 春意盎然 (xuân tình phơi phới), 生机盎然 (tràn đầy sinh khí).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 盎 (áng) từ hội ý hình thanh: 皿 (đồ đựng) + 央 (biểu âm). Nghĩa gốc là cái chậu sành, cái ang — vật dụng đựng nước hoặc ngũ cốc thời cổ. Wiktionary ghi nhận dạng seal script rõ ràng. Sau này nghĩa mở rộng sang 盎然 (tràn đầy, rào rạt) để chỉ khí thế hoặc sinh khí phong phú. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chậu sành, cái ang", "Hạng Tần Suất (Jun Da)": "3404.0", "Tần Suất % (Jun Da)": "99.4922033092", "GavinGrover_Once (Chiết tự trực tiếp)": "央 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱央皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盎", "Unihan_Traditional (Chữ Phồn thể)": "盎", "Pinyin_Xie": "àng", "Âm Hán Việt_Xie": "áng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ đồ đựng bằng đất nung hoặc ẩn dụ cho sự tràn đầy trong văn viết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('徙', '{"9000": "3405.0", "Chữ Trung Quốc": "徙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彳 | Số nét | 11 | nét | 彳 | xích | biểu nghĩa | bước đi, di chuyển | 止 | chỉ | biểu nghĩa | chân, dừng bước | 龰 | biểu nghĩa | (thành phần chân bước thứ hai trong 歨) | 徙 là chữ phức tạp về nguồn gốc (theo Wiktionary, lsCodes = ic, psc, psc — nhiều cách giải thích). Bộ 彳(Xích — bước đi) biểu nghĩa; phần còn lại (歨, gồm hai bộ chỉ) gợi hình ảnh hai chân bước đi. Shuowen Jiezi sai khi phân tích là psc với 止 biểu âm; thực tế hình thành phức tạp qua nhiều giai đoạn biến hóa chữ viết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỷ\": hai bước chân (歨) và đường (彳) — tỷ tê rời bước, di dời nơi ở sang chỗ mới. | Gương Hán-Việt | \"tỷ\" trong \"thiên tỷ\" (遷徙 — di cư); ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 徙 mở khoá 迁徙 (di cư, di dân), 流徙 (lưu lạc), 移徙 (di chuyển chỗ ở).", "Tự nguyên_Xie": "徙 có nguồn gốc phức tạp. Theo Wiktionary (nghiên cứu của Lý Thủ Khuê, 2015), thời Chu chữ 徙 dùng mượn âm 屎 (phân), sau thêm 辵 và 止 để phân biệt. Qua thời Chiến Quốc, phần âm biến đổi phức tạp: chữ Tần lược bỏ 尸, chỉ còn 少; chữ lệ thư lại biến 少 thành 止 nữa, tạo thành dạng hiện tại trông giống 歨+彳. Shuowen Jiezi sai khi phân tích là hình thanh với 止 biểu âm. Nghĩa là dời chỗ ở, di chuyển, di cư. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dời; di chuyển; dọn; chuyển", "Hạng Tần Suất (Jun Da)": "3405.0", "Tần Suất % (Jun Da)": "99.4927877932", "GavinGrover_Once (Chiết tự trực tiếp)": "彳 + 歨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰彳歨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "歨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "彳", "Unihan_Simplified (Chữ Giản thể)": "徙", "Unihan_Traditional (Chữ Phồn thể)": "徙", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ hành động di dời, chuyển dịch vị trí hoặc nơi cư trú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鞅', '{"9000": "3406.0", "Chữ Trung Quốc": "鞅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 14 | nét | 革 | cách | biểu nghĩa | da thuộc | 央 | ương | biểu âm | 鞅 gồm bộ 革 (Cách, biểu nghĩa: da thuộc) và 央 (Ương, biểu âm). Chữ hình thanh — bộ 革cho biết đây là vật dụng làm từ da, phần 央 gợi âm đọc. Nghĩa gốc là cái cổ dề — vòng da quàng cổ ngựa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"óng\": da 革 ở trung tâm 央 cổ ngựa — cái óng dây da buộc vào cổ ngựa để điều khiển. | Gương Hán-Việt | óng (鞅) — dây cổ ngựa; không có từ ghép phổ biến trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 鞅 mở khoá: 鞅掌 (bận rộn, tất bật), nghĩa phái sinh là không hài lòng (通 怏).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 鞅 (óng) nghĩa là cái martingale — dây da quàng quanh cổ ngựa để kiểm soát chuyển động. Chữ hình thanh: 革 (da thuộc) + 央 (biểu âm). Wiktionary ghi nhận nghĩa thứ hai là bất mãn, không hài lòng (相通 với 怏). Seal script thể hiện rõ cấu trúc da + âm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cổ dề (vòng da quàng cổ ngựa)", "Hạng Tần Suất (Jun Da)": "3406.0", "Tần Suất % (Jun Da)": "99.4933717604", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "鞅", "Unihan_Traditional (Chữ Phồn thể)": "鞅", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ưởng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ bộ phận dây da đeo vào cổ ngựa hoặc trâu bò khi kéo xe. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漓', '{"9000": "3407.0", "Chữ Trung Quốc": "漓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 离 | ly | biểu âm | 漓 = 水/氵 (Thủy, biểu nghĩa: nước) + 离 (Ly, biểu âm). Chữ hình thanh — bộ 氵cho biết đây liên quan đến nước, phần 离 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lầy\": nước 氵ly 离 ra từng giọt — ướt lầy đẫm, mồ hôi nhễ nhại rỉ ra. | Gương Hán-Việt | lầm lì (淋漓) — đầm đìa, nhễ nhại; sông Ly (漓江) — dòng sông huyền thoại Quảng Tây | Mở khoá kiến thức | Biết 漓 mở khoá: 淋漓 (đầm đìa), 淋漓尽致 (tận cùng, triệt để), 漓江 (sông Ly).", "Tự nguyên_Xie": "漓 (lầy) từ hình thanh: 水 (nước) + 离 (biểu âm). Nghĩa gốc mô tả nước nhỏ giọt lã chã, ướt đẫm. Trong hiện đại thường dùng trong 淋漓 (ướt đẫm, đầm đìa) — như mồ hôi hay máu tuôn trào. Cũng là tên sông Ly (漓江) ở Quảng Tây, Trung Quốc, nổi tiếng với phong cảnh kỳ vĩ. Chưa có ảnh cổ văn được thu thập. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhễ nhại; đầm đìa; vui vẻ", "Hạng Tần Suất (Jun Da)": "3407.0", "Tần Suất % (Jun Da)": "99.4939541772", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 离", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵离", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "离", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漓", "Unihan_Traditional (Chữ Phồn thể)": "漓", "Pinyin_Xie": "lí", "Âm Hán Việt_Xie": "li", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ mô tả trạng thái nước chảy nhỏ giọt hoặc sự bạc bẽo của tình cảm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祟', '{"9000": "3408.0", "Chữ Trung Quốc": "祟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 出 | xuất | biểu nghĩa | xuất hiện (biến thể của 木) | 示 | thị | biểu nghĩa | bàn thờ, thần linh | 祟 theo giáp cốt văn là hội ý: 木 (mộc, gỗ) + 示 (thị, bàn thờ) — đốt gỗ trên bàn thờ để cúng thần. Trong dạng hiện đại, 木 đã biến dạng thành 出, nhưng nghĩa gốc vẫn là hành động của ma quỷ hoặc lực lượng siêu nhiên xuất hiện quấy phá. Chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuy\" (trong tác tuy, quỷ tuy): thần linh 示 xuất 出 hiện trong đêm tối — ma quỷ tuy bí ẩn hiện ra quấy phá. | Gương Hán-Việt | quỷ tuy (鬼祟) — ma quái, lén lút; tác tuy (作祟) — quỷ quấy phá, gây rắc rối | Mở khoá kiến thức | Biết 祟 mở khoá: 作祟 (quấy phá), 鬼祟 (ma quái), 鬼鬼祟祟 (lén lút như ma).", "Tự nguyên_Xie": "Tiểu triện | 祟 (tuy) theo Wiktionary từ hội ý trong giáp cốt văn: 木 (gỗ) + 示 (bàn thờ) — đốt gỗ để thỉnh cầu thần linh. Ban đầu là chữ giống 奈. Trong dạng hiện đại 木 đã biến dạng thành 出, nên đôi khi được phân tích thêm là 出 + 示 (biểu âm giả). Nghĩa hiện đại: ma quỷ, điều xui xẻo, quấy phá bí ẩn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ma đói", "Hạng Tần Suất (Jun Da)": "3408.0", "Tần Suất % (Jun Da)": "99.4945365941", "GavinGrover_Once (Chiết tự trực tiếp)": "出 + 示", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱出示", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "出", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "示", "Unihan_Simplified (Chữ Giản thể)": "祟", "Unihan_Traditional (Chữ Phồn thể)": "祟", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "túy, trúy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ điềm xấu hoặc động từ chỉ việc gây rối, làm hại ngầm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睫', '{"9000": "3409.0", "Chữ Trung Quốc": "睫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 13 | nét | 目 | mục | biểu nghĩa | mắt | 疌 | biểu âm | 睫 = 目 (Mục, biểu nghĩa: mắt) + 疌 (biểu âm, không có Hán-Việt phổ biến). Chữ hình thanh — bộ 目cho biết liên quan đến mắt, phần 疌 gợi âm đọc jié.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiệp\": mắt 目 với những sợi lông mi 疌 — nháy tiệp một cái là cảm nhận được lông mi. | Gương Hán-Việt | tiệp mao (睫毛) — lông mi; thúc tiệp (属睫) — gần kề, ngay trước mắt | Mở khoá kiến thức | Biết 睫 mở khoá: 睫毛 (lông mi), 目不交睫 (không nhắm mắt, thức suốt đêm).", "Tự nguyên_Xie": "Lục thư thông | 睫 (tiệp) từ hình thanh: 目 (mắt) + 疌 (biểu âm). Nghĩa gốc là lông mi — những sợi lông mọc ở rìa mí mắt. Wiktionary ghi nhận âm Mân Nam chiap và chiah. Chữ tạo khá muộn, chỉ thấy dạng Lục thư thông, không có giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông my", "Hạng Tần Suất (Jun Da)": "3409.0", "Tần Suất % (Jun Da)": "99.4951184941", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 疌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目疌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睫", "Unihan_Traditional (Chữ Phồn thể)": "睫", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "tiệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ lông mi, thường xuất hiện trong các thành ngữ liên quan đến mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攸', '{"9000": "3410.0", "Chữ Trung Quốc": "攸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 7 | nét | 人 | nhân | biểu nghĩa | người | 攴 | phộc | biểu nghĩa | tay cầm gậy | 攸 là chữ hội ý: 人 (Nhân, người) + 攴 (tay cầm gậy ra hiệu). Theo Wiktionary, trong giáp cốt văn hình ảnh là người bị cảnh báo bởi bàn tay cầm gậy, hoặc người đang chảy mồ hôi (những chấm nhỏ thêm vào). Chữ hội ý, tượng trưng cho sự vụt qua, thoáng qua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": người 人 chạy vụt qua khi thấy gậy 攴 — du nhanh như chớp, thoáng cái đã mất dạng. | Gương Hán-Việt | du quan (攸关) — có liên quan trọng yếu; tính mạng 攸关 — quan hệ sinh tử | Mở khoá kiến thức | Biết 攸 mở khoá: 性命攸关 (quan hệ sinh tử), 攸往 (nơi đến), dùng nhiều trong thành ngữ văn ngôn.", "Tự nguyên_Xie": "Giáp cốt văn | 攸 (du) theo Wiktionary từ hội ý: người 人 + tay cầm gậy 攴. Trong giáp cốt văn có hai cách lý giải: người bị gậy cảnh báo (chỉ sự vụt chạy nhanh), hoặc người chảy mồ hôi (những chấm nước nhỏ thêm vào hình). Nghĩa văn ngôn: nơi chốn, sự thuộc về. Thường xuất hiện trong văn cổ như 性命攸关 (quan trọng sinh tử). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1087.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (008) Cổn (002) Phộc (044)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 008 - người), ở giữa là nét Sổ (số 002 - 丨), bên phải là bộ Phộc (số 044 - đánh khẽ/ 攵). Giải thích sự chuyển ý: Đây là chữ Hội ý. Du miêu tả dáng vẻ vụt qua, thoáng qua rất nhanh chóng.", "Nghĩa Tiếng Việt_Xie": "vụt, thoáng", "Hạng Tần Suất (Jun Da)": "3410.0", "Tần Suất % (Jun Da)": "99.4957003942", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "攸", "Unihan_Traditional (Chữ Phồn thể)": "攸", "Pinyin_Xie": "yōu", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Phó từ | 副词 | Thường dùng làm đại từ quan hệ trong văn ngôn cổ hoặc phó từ bổ nghĩa cho động từ. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翎', '{"9000": "3411.0", "Chữ Trung Quốc": "翎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 令 | lệnh | biểu âm | 羽 | vũ | biểu nghĩa | lông vũ | 翎 = 令 (Lệnh, biểu âm) + 羽 (Vũ, biểu nghĩa: lông vũ). Chữ hình thanh — bộ 羽 cho biết đây là loại lông chim, phần 令 gợi âm đọc líng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": lông vũ 羽 mang mệnh lệnh 令 của triều đình — hoa linh cắm trên mũ quan, biểu tượng quyền lực. | Gương Hán-Việt | hoa linh (花翎) — lông công trang trí mũ quan nhà Thanh; linh mao (翎毛) — lông chim | Mở khoá kiến thức | Biết 翎 mở khoá: 花翎 (lông mũ quan), 翎毛 (lông chim), 孔雀翎 (lông công).", "Tự nguyên_Xie": "Tiểu triện | 翎 (liếng/linh) từ hình thanh: 羽 (lông vũ) + 令 (biểu âm). Nghĩa gốc là lông cánh chim, đặc biệt là lông đuôi dài và đẹp. Wiktionary ghi nhận seal script rõ ràng. Trong văn hóa Trung Hoa, lông chim trĩ 翎 được cắm trên mũ quan lại (花翎) để thể hiện cấp bậc thời nhà Thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lông cánh chim", "Hạng Tần Suất (Jun Da)": "3411.0", "Tần Suất % (Jun Da)": "99.4962817775", "GavinGrover_Once (Chiết tự trực tiếp)": "令 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰令羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翎", "Unihan_Traditional (Chữ Phồn thể)": "翎", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ các loại lông vũ dài của chim, thường dùng trang trí mũ nón thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呛', '{"9000": "3412.0", "Chữ Trung Quốc": "呛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 倉 | thương | biểu âm | 呛 = 口 (Khẩu, biểu nghĩa: miệng) + 倉 (Thương, biểu âm). Chữ hình thanh — bộ 口 cho biết liên quan đến miệng hoặc đường hô hấp, phần 倉 gợi âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thương\": miệng 口 đột ngột bị kho thương 倉 — sặc nghẹn, ho sặc sụa. | Gương Hán-Việt | thương (呛) — sặc, nghẹn; không có từ ghép Hán-Việt phổ biến | Mở khoá kiến thức | Biết 呛 mở khoá: 够呛 (không chịu nổi), 呛咳 (ho sặc), 呛水 (uống phải nước).", "Tự nguyên_Xie": "呛 (thương/sặc) từ hình thanh: 口 (miệng) + 倉 (biểu âm). Nghĩa gốc là sặc, nghẹn — cảm giác khó chịu khi thức ăn hoặc khói lọt vào đường thở sai. Không có ảnh cổ văn được thu thập. Chữ khá muộn, không xuất hiện trong giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sặc, nghẹn", "Hạng Tần Suất (Jun Da)": "3412.0", "Tần Suất % (Jun Da)": "99.4968605768", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 仓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口仓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呛", "Unihan_Traditional (Chữ Phồn thể)": "嗆", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương, sang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ phản ứng sặc, ho do hít phải khói, bụi hoặc bị nghẹn nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qiāng | / | bị nghẹn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Bệnh I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筐', '{"9000": "3413.0", "Chữ Trung Quốc": "筐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, vật bằng tre | 匡 | khuông | biểu âm | (cho âm kuāng, đồng âm Hán-Việt) | 筐 = 竹 (Trúc, biểu nghĩa: tre) + 匡 (Khuông, biểu âm); chữ hình thanh. Bộ trúc chỉ vật liệu; 匡 cho âm kuāng và đồng âm Hán-Việt khuông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuông\": tre (竹) đan thành khuông — khuông khổ, chiếc giỏ tre vuông vắn đựng đồ. | Gương Hán-Việt | \"khuông\" trong 匡 (khuông phò — phò tá); 筐 là cái giỏ tre hình vuông | Mở khoá kiến thức | Biết 筐 mở khoá 菜筐 (giỏ rau), 竹筐 (giỏ tre), 筐子 (cái giỏ).", "Tự nguyên_Xie": "Tiểu triện | 筐 là chữ hình thanh: bộ 竹 (trúc — tre) biểu nghĩa, vì giỏ xưa làm bằng tre; 匡 (khuông) cho âm. Wiktionary không ghi chi tiết nguồn gốc cổ đại. Nghĩa là cái giỏ, cái rổ đan bằng tre. Chưa có nguồn học thuật xác nhận thêm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1422.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trúc (108) Khuông (1421)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trúc (số 108 - tre nứa/ 竹 /chỉ ý) ở trên chữ Khuông (số 1421 - cái khung/ 匡 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Khuông chỉ âm, bộ Trúc chỉ ý. Khuông là cái giỏ, cái thúng, cái sọt được đan từ tre trúc để đựng đồ.", "Nghĩa Tiếng Việt_Xie": "cái giỏ tre", "Hạng Tần Suất (Jun Da)": "3413.0", "Tần Suất % (Jun Da)": "99.4974388594", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 匡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮匡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筐", "Unihan_Traditional (Chữ Phồn thể)": "筐", "Pinyin_Xie": "kuāng", "Âm Hán Việt_Xie": "khuông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ chỉ đồ dùng tre nứa hoặc làm lượng từ cho vật đựng trong giỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kuāng | / | cái giỏ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I | HSK | HSK 6 | · | Căn nhà", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堑', '{"9000": "3414.0", "Chữ Trung Quốc": "堑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 斩 | trảm | biểu âm | 土 | thổ | biểu nghĩa | đất | 堑 = 斩 (Trảm, biểu âm) + 土 (Thổ, biểu nghĩa: đất). Chữ hình thanh — bộ 土 cho biết liên quan đến đất hoặc công trình đào đắp, phần 斩 gợi âm đọc qiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiệm\" (trong thiên tiệm): đất 土 bị chặt đứt 斩 ra — đào hào tiệm tiến, từng lớp đất bị cắt bỏ. | Gương Hán-Việt | hào tiệm (壕堑) — cái hào phòng thủ; tiệm trở (堑阻) — hào cản đường | Mở khoá kiến thức | Biết 堑 mở khoá: 吃一堑长一智 (thất bại là mẹ thành công), 天堑 (thiên tiệm — hào trời).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 堑 (tiệm/hào) từ hình thanh: 土 (đất) + 斩 (biểu âm). Nghĩa gốc là cái hào — rãnh đất đào sâu xung quanh thành trì để phòng thủ. Wiktionary ghi nhận seal script. Thành ngữ nổi tiếng: 吃一堑，长一智 (vấp ngã một lần, thêm một bài học khôn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tạc ra; hào vây quanh", "Hạng Tần Suất (Jun Da)": "3414.0", "Tần Suất % (Jun Da)": "99.4980171419", "GavinGrover_Once (Chiết tự trực tiếp)": "斩 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱斩土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斩", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堑", "Unihan_Traditional (Chữ Phồn thể)": "塹", "Pinyin_Xie": "qiàn", "Âm Hán Việt_Xie": "tiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ hào sâu bảo vệ thành trì hoặc các chướng ngại vật tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檀', '{"9000": "3415.0", "Chữ Trung Quốc": "檀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 亶 | đản | biểu âm | 檀 = 木 (Mộc, biểu nghĩa: cây gỗ) + 亶 (Đản, biểu âm). Chữ hình thanh — bộ 木 cho biết đây là loại cây, phần 亶 gợi âm đọc tán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đàn\": cây 木 mang âm đàn 亶 — cây đàn hương tỏa hương thơm, gỗ quý dùng tạc tượng Phật. | Gương Hán-Việt | đàn hương (檀香) — hương gỗ trầm; chiên đàn (旃檀) — cây đàn hương thiêng | Mở khoá kiến thức | Biết 檀 mở khoá: 檀香 (đàn hương), 旃檀 (chiên đàn), 檀越 (thí chủ Phật giáo).", "Tự nguyên_Xie": "Tiểu triện | 檀 (đàn) từ hình thanh: 木 (cây) + 亶 (biểu âm). Nghĩa gốc là cây đàn hương (sandalwood) hoặc cây bạch đàn — loại gỗ quý, thơm. Wiktionary ghi nhận seal script. Trong văn hóa Phật giáo, 旃檀 (chiên đàn) là cây đàn hương thiêng liêng. 檀越 là từ phiên âm từ tiếng Phạn, nghĩa là thí chủ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây đàn", "Hạng Tần Suất (Jun Da)": "3415.0", "Tần Suất % (Jun Da)": "99.4985954245", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 亶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木亶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檀", "Unihan_Traditional (Chữ Phồn thể)": "檀", "Pinyin_Xie": "tán", "Âm Hán Việt_Xie": "đàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ cây gỗ đàn hoặc các vật dụng làm từ loại gỗ quý này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寅', '{"9000": "3416.0", "Chữ Trung Quốc": "寅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 11 | nét | 寅 | dần | tượng hình | mũi tên với dấu phân biệt — chi thứ ba trong mười hai địa chi | 寅 là chữ tượng hình: ban đầu vẽ hình mũi tên 矢 với dấu phân biệt (nay là 日). Trong dạng hiện đại, phần đầu mũi tên đã biến dạng thành 宀 (mái nhà). Chen (2019) cho rằng đây là chữ gốc của 演 (tiến triển, mở rộng). Chữ độc thể tượng hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dần\": mũi tên 矢 nhọn bắn lên trời lúc rạng đông — giờ Dần hổ gầm, mặt trời bắt đầu mọc. | Gương Hán-Việt | dần thời (寅时) — giờ Dần (3–5 giờ sáng); canh dần (庚寅) — can chi năm | Mở khoá kiến thức | Biết 寅 mở khoá: 寅时 (giờ Dần), 寅年 (năm Dần/năm Hổ), hệ thống thập nhị địa chi.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | 寅 (dần) theo Wiktionary ban đầu là tượng hình: mũi tên 矢 có dấu phân biệt biểu thị sự tiến lên. Trong dạng hiện đại phần đầu mũi tên biến thành 宀. Là chi thứ ba trong thập nhị địa chi, ứng với con Hổ, giờ Dần (3–5 giờ sáng), tháng Giêng âm lịch. Giáp cốt văn, kim văn, đại triện và tiểu triện đều có dạng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1702.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Miên (040) Hoàng (201)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Miên (số 040 - mái nhà/ 宀) nằm ở trên chữ Hoàng (số 201 - màu vàng/ 黄) viết giản nét. Giải thích sự chuyển ý: Dần là tên ngôi thứ ba trong 12 Địa chi (Tý, Sửu, Dần...). Cổ nhân dùng địa chi để tính năm tháng, tháng Dần ứng với tháng Giêng âm lịch.", "Nghĩa Tiếng Việt_Xie": "Dần (chi thứ 3 hàng Chi)", "Hạng Tần Suất (Jun Da)": "3416.0", "Tần Suất % (Jun Da)": "99.4991726735", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寅", "Unihan_Traditional (Chữ Phồn thể)": "寅", "Pinyin_Xie": "yín", "Âm Hán Việt_Xie": "dần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ chi Dần trong hệ thống Can Chi hoặc phương hướng và thời gian tương ứng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磊', '{"9000": "3417.0", "Chữ Trung Quốc": "磊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 磊 | lối | tượng hình | ba tảng đá 石 xếp chồng — nhiều đá, cao lớn | 磊 là chữ lặp ba lần bộ 石 (Thạch, đá). Theo Wiktionary đây là chữ triple ideograph: 石+石+石 tượng trưng cho nhiều đá chồng cao. Chữ hội ý thuần túy — hình ảnh ba khối đá xếp thành tháp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lối\": ba tảng đá 石石石 xếp chồng cao — lối lạc quang minh, tâm hồn vững chắc như núi đá. | Gương Hán-Việt | lối lạc (磊落) — quang minh chính đại; quang minh lối lạc — tâm địa trong sạch | Mở khoá kiến thức | Biết 磊 mở khoá: 磊落 (quang minh chính đại), 光明磊落 (thành thật ngay thẳng), 磊磊 (nhiều đá).", "Tự nguyên_Xie": "Tiểu triện | 磊 (lối) từ hội ý ba chữ 石 (đá): 磊 = 石+石+石. Wiktionary ghi nhận đây là triple compound. Nghĩa gốc: nhiều đá, đống đá cao. Nghĩa phái sinh: quang minh chính đại (磊落) — tâm hồn trong sáng như đá tảng vững chắc. Seal script cho thấy ba khối đá xếp tam giác. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều đá; cao lớn", "Hạng Tần Suất (Jun Da)": "3417.0", "Tần Suất % (Jun Da)": "99.4997483722", "GavinGrover_Once (Chiết tự trực tiếp)": "石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "磊", "Unihan_Traditional (Chữ Phồn thể)": "磊", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong các từ ghép để tả tính cách ngay thẳng, rộng lượng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驭', '{"9000": "3418.0", "Chữ Trung Quốc": "驭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 5 | nét | 马 | mã | biểu nghĩa | ngựa | 又 | hựu | biểu nghĩa | tay | 驭 giản thể của 𩣓. Chữ gồm 马 (Mã, biểu nghĩa: ngựa) và 又 (Hựu, tay). Đây là hội ý: tay người cầm cương điều khiển ngựa — nghĩa là cầm cương, khống chế. Chưa có nguồn học thuật rõ ràng về ls-code của dạng giản thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngự\": tay 又 nắm cương ngựa 马 — ngự mã, điều khiển con ngựa thuần phục. | Gương Hán-Việt | ngự mã (驭马) — cầm cương ngựa; giá ngự (驾驭) — điều khiển, kiểm soát | Mở khoá kiến thức | Biết 驭 mở khoá: 驾驭 (điều khiển), 统驭 (lãnh đạo, quản lý), 驭手 (người điều khiển).", "Tự nguyên_Xie": "Tiểu triện | 驭 giản thể của 𩣓, theo Wiktionary. Nghĩa gốc: người điều khiển ngựa, cầm cương. Nghĩa mở rộng: khống chế, điều khiển kẻ dưới. Seal script cho thấy cấu trúc mã + tay. Trong hiện đại dùng trong 驾驭 (điều khiển, kiểm soát). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẻ cầm cương ngựa; khống chế, tiết chế kẻ dưới", "Hạng Tần Suất (Jun Da)": "3418.0", "Tần Suất % (Jun Da)": "99.5003240708", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "又", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驭", "Unihan_Traditional (Chữ Phồn thể)": "馭", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "ngự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước tân ngữ để chỉ việc điều khiển xe cộ hoặc khống chế cấp dưới. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惘', '{"9000": "3419.0", "Chữ Trung Quốc": "惘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 罔 | vóng | biểu âm | 惘 = 忄(Tâm, biểu nghĩa: tâm trạng) + 罔 (Vóng, biểu âm). Chữ hình thanh — bộ 忄cho biết đây là trạng thái tâm lý, phần 罔 gợi âm đọc wǎng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"võng\": lòng 忄rơi vào lưới 罔 không lối thoát — cảm giác võng vất, mê hoảng không định hướng. | Gương Hán-Việt | mê võng (迷惘) — mê hoảng, lạc lõng; trướng võng (怅惘) — chán nản bơ vơ | Mở khoá kiến thức | Biết 惘 mở khoá: 迷惘 (mê hoảng), 怅惘 (chán nản bơ vơ), 惘然 (thất vọng).", "Tự nguyên_Xie": "惘 (võng/hoảng) từ hình thanh: 忄(tâm) + 罔 (biểu âm). Nghĩa gốc là thất vọng, rã rời, bơ vơ lạc lõng. Wiktionary ghi nhận âm Trung cổ mong5 (Quảng Đông). Thường dùng trong 迷惘 (mê hoảng, lạc lõng) và 怅惘 (chán nản bơ vơ). Không có ảnh cổ văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chán nản", "Hạng Tần Suất (Jun Da)": "3419.0", "Tần Suất % (Jun Da)": "99.5008997694", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 罔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄罔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "罔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惘", "Unihan_Traditional (Chữ Phồn thể)": "惘", "Pinyin_Xie": "wǎng", "Âm Hán Việt_Xie": "võng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ để miêu tả trạng thái tâm lý hụt hẫng, mơ hồ hoặc không biết làm sao. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吠', '{"9000": "3420.0", "Chữ Trung Quốc": "吠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 犬 | khuyển | biểu nghĩa | chó | 吠 là chữ hội ý: 口 (Khẩu, miệng) + 犬 (Khuyển, chó). Chữ mô tả con chó há miệng phát ra tiếng — sủa. Hội ý rõ ràng, trực quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phệ\": miệng 口 chó 犬 há ra — tiếng phệ phệ của chó sủa vang làng. | Gương Hán-Việt | phệ (吠) — sủa; cuồng khuyển phệ nhật (狂犬吠日) — chó điên sủa mặt trời | Mở khoá kiến thức | Biết 吠 mở khoá: 狂吠 (sủa điên loạn), 吠影吠声 (học đòi sủa theo), 狗吠 (chó sủa).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 吠 (phệ) từ hội ý: 口 (miệng) + 犬 (chó) — con chó mở miệng sủa. Wiktionary ghi nhận giáp cốt văn và tiểu triện, cấu trúc hội ý rõ ràng từ thời cổ đại. Nghĩa duy nhất là tiếng sủa của chó. Thành ngữ 狂犬吠日 (chó điên sủa mặt trời) dùng để chỉ kẻ liều lĩnh thách thức quyền lực lớn hơn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sủa (chó); cắn (chó)", "Hạng Tần Suất (Jun Da)": "3420.0", "Tần Suất % (Jun Da)": "99.5014749513", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 犬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口犬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "犬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吠", "Unihan_Traditional (Chữ Phồn thể)": "吠", "Pinyin_Xie": "fèi", "Âm Hán Việt_Xie": "phệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ chỉ hành động sủa của loài chó hoặc ẩn dụ cho việc gào thét vô ích. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驮', '{"9000": "3421.0", "Chữ Trung Quốc": "驮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 6 | nét | 马 | mã | biểu nghĩa | ngựa | 大 | đại | biểu âm | 驮 giản thể của 馱. Chữ gồm 马 (Mã, biểu nghĩa: ngựa) và 大 (Đại, biểu âm). Chữ hình thanh — bộ 马 cho biết liên quan đến ngựa, phần 大 gợi âm đọc tuó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đà\": ngựa 马 to lớn 大 cõng hàng trên lưng — đà mã thồ hàng vượt núi non. | Gương Hán-Việt | đà (驮) — cõng, thồ; lạc đà (骆驼) liên quan đến thồ hàng | Mở khoá kiến thức | Biết 驮 mở khoá: 驮运 (chở hàng trên lưng thú), 驮队 (đoàn lạc đà hoặc ngựa thồ).", "Tự nguyên_Xie": "Tiểu triện | 驮 giản thể của 馱, theo Wiktionary. Nghĩa gốc: ngựa cõng, thồ hàng trên lưng. Seal script cho thấy cấu trúc mã + đại. Dùng chỉ hành động thồ hàng, cõng vác — đặc biệt trên lưng động vật như ngựa, lừa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa cõng, thồ", "Hạng Tần Suất (Jun Da)": "3421.0", "Tần Suất % (Jun Da)": "99.5020490996", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 大", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马大", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "大", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驮", "Unihan_Traditional (Chữ Phồn thể)": "䭾", "Pinyin_Xie": "tuó", "Âm Hán Việt_Xie": "đà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường dùng làm động từ chỉ việc súc vật chở đồ trên lưng hoặc làm lượng từ cho chuyến hàng thồ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | tuó | / | cõng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑙', '{"9000": "3422.0", "Chữ Trung Quốc": "瑙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 王 | vương | biểu nghĩa | ngọc, đá quý | 脑 | não | biểu âm | 瑙 gồm bộ 王/玉 (Vương/Ngọc, biểu nghĩa: đá quý) và thành phần biểu âm gợi âm nǎo. Chữ hình thanh — bộ 王旁 cho biết đây là loại đá quý hoặc khoáng vật, phần âm gợi cách đọc. Chưa có nguồn học thuật rõ ràng về cấu trúc đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"não\": ngọc 王 óng ánh như não não — mã não lấp lánh nhiều màu, đá quý của người xưa. | Gương Hán-Việt | mã não (瑪瑙) — agate, đá mã não nhiều màu | Mở khoá kiến thức | Biết 瑙 mở khoá: 瑪瑙 (mã não), 多瑙河 (sông Danube).", "Tự nguyên_Xie": "瑙 (não) chỉ dùng trong 瑪瑙 (mã não — agate, đá mã não) và một số địa danh như 多瑙河 (sông Danube). Theo Wiktionary chỉ xuất hiện trong từ ghép, không dùng độc lập. Không có ảnh cổ văn được thu thập. Chưa có nguồn học thuật xác định rõ cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: mã não 瑪瑙,碼碯)", "Hạng Tần Suất (Jun Da)": "3422.0", "Tần Suất % (Jun Da)": "99.5026216975", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瑙", "Unihan_Traditional (Chữ Phồn thể)": "瑙", "Pinyin_Xie": "nǎo", "Âm Hán Việt_Xie": "não", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép mã não để chỉ một loại đá quý tự nhiên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炬', '{"9000": "3423.0", "Chữ Trung Quốc": "炬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu nghĩa | lửa | 巨 | cự | biểu âm | 炬 = 火 (Hoả, biểu nghĩa: lửa) + 巨 (Cự, biểu âm). Chữ hình thanh — bộ 火 cho biết liên quan đến lửa, phần 巨 gợi âm đọc jù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\": lửa 火 to lớn 巨 bùng cháy — bó đuốc cự cự sáng rực, soi đường trong đêm tối. | Gương Hán-Việt | cự (炬) — bó đuốc; hỏa cự (火炬) — ngọn đuốc | Mở khoá kiến thức | Biết 炬 mở khoá: 火炬 (ngọn đuốc), 付之一炬 (đốt sạch), 目光如炬 (nhìn sắc như đuốc).", "Tự nguyên_Xie": "炬 (cự) từ hình thanh: 火 (lửa) + 巨 (biểu âm). Nghĩa gốc là bó đuốc — vật dụng cầm tay phát sáng bằng lửa. Wiktionary ghi nhận âm Mân Nam kū. Không có ảnh cổ văn được thu thập. Thành ngữ nổi tiếng: 付之一炬 (đốt sạch, thiêu hủy hoàn toàn); 目光如炬 (ánh mắt như đuốc — sắc sảo tinh tường). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bó đuốc", "Hạng Tần Suất (Jun Da)": "3423.0", "Tần Suất % (Jun Da)": "99.5031937786", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 巨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火巨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炬", "Unihan_Traditional (Chữ Phồn thể)": "炬", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng sau các từ chỉ chất liệu hoặc hành động để chỉ bó đuốc hay nguồn sáng mạnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痉', '{"9000": "3424.0", "Chữ Trung Quốc": "痉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 10 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 𢀖 | biểu âm | 痉 giản thể của 痙. Chữ gồm bộ 疒 (Nạch, biểu nghĩa: bệnh tật) và thành phần biểu âm. Chữ hình thanh — bộ 疒 cho biết đây là bệnh hoặc triệu chứng y tế, phần biểu âm gợi âm đọc jìng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kinh\": bệnh 疒 gân cứng kinh — co kinh giật cơ, cơ thể không tự chủ được. | Gương Hán-Việt | kinh loan (痉挛) — co cơ, chuột rút; kinh궐 (痉厥) — co giật ngất xỉu | Mở khoá kiến thức | Biết 痉 mở khoá: 痉挛 (co cơ, chuột rút), 热痉挛 (chuột rút do nóng), 破伤风痉挛 (co cứng do uốn ván).", "Tự nguyên_Xie": "Tiểu triện | 痉 giản thể của 痙, theo Wiktionary. Nghĩa: co cứng cơ, chuột rút, co giật. Bộ 疒 (bệnh tật) + 巠/𢀖 (biểu âm). Seal script cho thấy cấu trúc bệnh + âm. Dùng trong y học: 痉挛 (co cơ, chuột rút), 痉厥 (co giật bất tỉnh). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh co gân", "Hạng Tần Suất (Jun Da)": "3424.0", "Tần Suất % (Jun Da)": "99.503765343", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "痉", "Unihan_Traditional (Chữ Phồn thể)": "痙", "Pinyin_Xie": "jìng", "Âm Hán Việt_Xie": "kinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ bệnh co giật hoặc kết hợp thành động từ chỉ trạng thái cơ bắp bị co rút đột ngột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曝', '{"9000": "3425.0", "Chữ Trung Quốc": "曝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 19 | nét | 日 | nhật | biểu nghĩa | mặt trời | 暴 | bạo | biểu âm | (cho âm pù/bào) | 曝 = 日 (Nhật, biểu nghĩa: mặt trời) + 暴 (Bạo, biểu âm); chữ hình thanh. Mặt trời là nguồn nhiệt phơi; 暴 cho âm pù (hoặc bào trong một số từ). Theo Wiktionary, ban đầu 暴 tự nó mang nghĩa này; sau thêm 日 để phân biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bộc\": mặt trời (日) bộc lộ (暴) ánh sáng — bộc phơi, phơi thứ ra dưới nắng. | Gương Hán-Việt | \"bộc\" trong \"bộc lộ\" (曝光 — phơi sáng); 暴 (bạo) trong 暴力 (bạo lực) | Mở khoá kiến thức | Biết 曝 mở khoá 曝光 (phơi sáng; bị lộ), 曝晒 (phơi nắng gắt), 一曝十寒 (làm nhát gừng, không kiên trì).", "Tự nguyên_Xie": "曝 là chữ hình thanh: bộ 日 (nhật — mặt trời) biểu nghĩa; 暴 (bạo) cho âm. Theo Wiktionary, ban đầu chữ 暴 đã mang nghĩa phơi nắng; sau này thêm bộ 日 để tạo 曝 nhằm phân biệt. Dạng bảo tồn là 𣌑, sau được chuẩn hóa thành 曝. Nghĩa là phơi nắng, phơi khô, lộ ra. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phơi nắng, phơi cho khô", "Hạng Tần Suất (Jun Da)": "3425.0", "Tần Suất % (Jun Da)": "99.5043363906", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "曝", "Unihan_Traditional (Chữ Phồn thể)": "曝", "Pinyin_Xie": "pù", "Âm Hán Việt_Xie": "bộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ đứng trước tân ngữ để chỉ hành động phơi nắng hoặc làm lộ thông tin ra ngoài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恺', '{"9000": "3426.0", "Chữ Trung Quốc": "恺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 忄 | tâm | biểu nghĩa | tâm trạng, cảm xúc | 豈 | khải | biểu âm | trống khải hoàn | 恺 = 忄(Tâm, biểu nghĩa) + 豈 (Khải, biểu âm: trống khải hoàn). Wiktionary ghi ls=ic (hội ý) và ls2=psc (hình thanh) — chữ mang cả hai tính chất: lòng 忄vui như tiếng trống 豈 khải hoàn. Có khả năng liên quan đến 凱 (nhạc khải hoàn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\": lòng 忄vang lên như trống 豈 khải hoàn — tâm trạng khải hòa, vui mừng sau chiến thắng. | Gương Hán-Việt | khải lạc (恺乐) — vui vẻ an lạc; khải đễ (恺悌) — hòa nhã thân thiện với người | Mở khoá kiến thức | Biết 恺 mở khoá: 恺悌 (hòa nhã), 恺切 (chân thành tha thiết), liên hệ với 凯 (khải hoàn).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 恺 (khải) theo Wiktionary là hội ý/hình thanh: 忄(lòng) + 豈 (trống khải hoàn). Nghĩa gốc: vui vẻ, hòa thuận, an lạc. Likely liên quan đến 凱 (âm nhạc khải hoàn — nhạc mừng chiến thắng). Đại triện và tiểu triện đều có dạng cổ. Trong văn ngôn dùng để mô tả trạng thái thanh thản, vui sướng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui vẻ, vui sướng", "Hạng Tần Suất (Jun Da)": "3426.0", "Tần Suất % (Jun Da)": "99.5049074381", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恺", "Unihan_Traditional (Chữ Phồn thể)": "愷", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn viết hoặc tên riêng để biểu thị sự vui tươi, hòa nhã. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胺', '{"9000": "3427.0", "Chữ Trung Quốc": "胺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 月 | nguyệt | biểu nghĩa | thịt (bộ 肉) | 安 | an | biểu âm | 胺 = 月/肉 (bộ Nhục — thịt, biểu nghĩa: hợp chất hữu cơ từ sinh vật) + 安 (An, biểu âm). Chữ hình thanh — bộ 月旁 (thực chất là 肉) cho biết đây là hợp chất hóa học liên quan đến sinh học, phần 安 gợi âm đọc àn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ươn\": thịt 月 để lâu thành an yên 安 — thịt ươn phân hủy tạo ra amine, hợp chất có mùi đặc trưng. | Gương Hán-Việt | ươn (胺) — amine; không có từ Hán-Việt phổ biến trong tiếng Việt thông dụng | Mở khoá kiến thức | Biết 胺 mở khoá: 胺类 (các amin), 氨基 (nhóm amino), 苯胺 (aniline).", "Tự nguyên_Xie": "胺 (ươn) là chữ khoa học hiện đại: 肉 (hữu cơ) + 安 (biểu âm). Wiktionary ghi nhận đây là từ phiên âm trong hóa học: amine (a-min) — dẫn xuất của amoniac với nhóm –NH₂. Chữ tạo muộn trong thế kỷ 20 để dùng trong ngành hóa học. Không có ảnh cổ văn. Chưa có nguồn học thuật về cấu trúc. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "a-min", "Hạng Tần Suất (Jun Da)": "3427.0", "Tần Suất % (Jun Da)": "99.5054774522", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胺", "Unihan_Traditional (Chữ Phồn thể)": "胺", "Pinyin_Xie": "àn", "Âm Hán Việt_Xie": "át", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong hóa học để chỉ nhóm chức amin. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萤', '{"9000": "3428.0", "Chữ Trung Quốc": "萤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 荧 | huỳnh | biểu âm | 萤 giản thể của 螢. Dạng giản thể thay bộ 炏 (lửa kép) bằng 艹 (Thảo, cỏ). Chữ hình thanh — bộ 艹 gợi liên tưởng đến côn trùng sống trong cỏ cây, phần âm gợi âm đọc yíng. Chữ phồn thể 螢 dùng bộ 虫 (trùng) biểu nghĩa rõ hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huỳnh\": cỏ 艹 tối đêm lóe sáng — con đom đóm huỳnh hào leo lên ngọn cỏ, phát ánh sáng xanh lạnh. | Gương Hán-Việt | huỳnh hỏa (萤火) — lửa đom đóm; nang huỳnh (囊萤) — bỏ đom đóm vào túi để học | Mở khoá kiến thức | Biết 萤 mở khoá: 萤火虫 (con đom đóm), 囊萤映雪 (hiếu học dù nghèo khó).", "Tự nguyên_Xie": "萤 giản thể của 螢, theo Wiktionary. Nghĩa: đom đóm — loài côn trùng phát sáng trong đêm. Chữ phồn thể 螢 dùng bộ 虫 (trùng) + 荧 (biểu âm), hình thanh rõ ràng hơn. Không có ảnh cổ văn. Điển tích nổi tiếng: 囊萤映雪 (bỏ đom đóm vào túi để đọc sách đêm — hình ảnh người nghèo hiếu học). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đom đóm", "Hạng Tần Suất (Jun Da)": "3428.0", "Tần Suất % (Jun Da)": "99.5060474662", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "萤", "Unihan_Traditional (Chữ Phồn thể)": "螢", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "huỳnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con đom đóm hoặc dùng trong từ ghép chỉ ánh sáng yếu ớt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敕', '{"9000": "3429.0", "Chữ Trung Quốc": "敕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 11 | nét | 柬 | giản | biểu nghĩa | thư, văn bản | 攴 | phộc | biểu nghĩa | tay cầm gậy — quyền uy | 敕 là chữ hội ý: 柬 (Giản, văn bản/thư) + 攴 (tay cầm gậy biểu trưng quyền uy). Theo Wiktionary, thành phần trái là biến thể của 熏 (theo Zhang Shichao) hoặc 束 (trong tiểu triện). Hội ý: dùng quyền uy ban ra văn bản — sắc lệnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": tay 攴 cầm gậy ban thư lệnh 柬 — sắc chỉ của vua ban xuống, ai cũng phải tuân theo. | Gương Hán-Việt | sắc lệnh (敕令) — chiếu chỉ của hoàng đế; sắc phong (敕封) — vua phong tước | Mở khoá kiến thức | Biết 敕 mở khoá: 敕令 (sắc lệnh), 敕封 (sắc phong), 敕书 (sắc thư — văn bản vua ban).", "Tự nguyên_Xie": "Kim văn | Đại triện | 敕 (sắc) từ hội ý: 柬 (văn bản) + 攴 (quyền uy). Theo Wiktionary, Zhang Shichao cho rằng thành phần trái là biến thể của 熏; tiểu triện đôi khi viết 束 thay 柬. Nghĩa gốc: răn bảo, cảnh cáo. Nghĩa văn ngôn: sắc lệnh của hoàng đế — văn bản quyền uy nhất. Kim văn và đại triện có dạng cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1411.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thúc (220) Phác (104)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thúc (số 220 - bó lại/ 束) ở bên trái bộ Phác (số 104 - đánh khẽ/ 攵). Người nhận mệnh lệnh của vua thì giống như bị đánh đập, trói buộc tâm trí vào công việc. Giải thích sự chuyển ý: Đây là chữ Hội ý. Sắc vốn là răng dạy bề dưới. Về sau dùng để chỉ sắc lệnh, chiếu chỉ của vua ban ra cho quần thần thi hành (sắc phong).", "Nghĩa Tiếng Việt_Xie": "sắc lệnh; răn bảo", "Hạng Tần Suất (Jun Da)": "3429.0", "Tần Suất % (Jun Da)": "99.5066174802", "GavinGrover_Once (Chiết tự trực tiếp)": "束 + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺙", "Unihan_Simplified (Chữ Giản thể)": "敕", "Unihan_Traditional (Chữ Phồn thể)": "勅", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ sắc lệnh của hoàng đế hoặc động từ với nghĩa ban sắc phong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筝', '{"9000": "3430.0", "Chữ Trung Quốc": "筝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, nhạc cụ làm từ tre | 爭 | tranh | biểu âm | 筝 = 竹 (Trúc, biểu nghĩa: tre — nhạc cụ làm từ tre hoặc gỗ) + 爭 (Tranh, biểu âm). Chữ hình thanh — bộ 竹 cho biết đây là nhạc cụ, phần 爭 gợi âm đọc zhēng. Tên chữ chính là đàn tranh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": tre 竹 dây tranh 爭 nhau rung lên — đàn tranh, mỗi dây đua nhau cất tiếng. | Gương Hán-Việt | tranh (筝) — đàn tranh; phong tranh (风筝) — con diều | Mở khoá kiến thức | Biết 筝 mở khoá: 古筝 (đàn tranh cổ), 风筝 (diều), 筝曲 (khúc nhạc đàn tranh).", "Tự nguyên_Xie": "Tiểu triện | 筝 (tranh) từ hình thanh: 竹 (tre) + 爭 (biểu âm, cũng gợi nghĩa tranh giành — các dây đàn tranh nhau vang lên). Wiktionary ghi nhận seal script. Nghĩa gốc là đàn tranh — nhạc cụ dây nhiều dây của Trung Quốc. Cũng dùng trong 风筝 (diều — vật bay trên không gió tranh đưa). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đàn tranh (13 dây)", "Hạng Tần Suất (Jun Da)": "3430.0", "Tần Suất % (Jun Da)": "99.5071859438", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 争", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮争", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "争", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筝", "Unihan_Traditional (Chữ Phồn thể)": "箏", "Pinyin_Xie": "zhēng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép để chỉ các loại đàn tranh hoặc diều. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幡', '{"9000": "3431.0", "Chữ Trung Quốc": "幡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 15 | nét | 巾 | can | biểu nghĩa | vải, cờ | 番 | phan | biểu âm | 幡 = 巾 (Can, biểu nghĩa: vải, cờ) + 番 (Phan, biểu âm). Chữ hình thanh — bộ 巾 cho biết đây là vật dụng bằng vải, phần 番 gợi âm đọc fān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phan\": vải 巾 quay phan 番 phất phới — lá cờ phan bay trong gió, lật mình đột ngột đổi hướng. | Gương Hán-Việt | phan (幡) — cờ lệnh; phan nhiên (幡然) — thay đổi đột ngột, lật mặt | Mở khoá kiến thức | Biết 幡 mở khoá: 幡然悔悟 (đột ngột tỉnh ngộ hối hận), 幡旗 (cờ phướn Phật giáo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 幡 (phan) từ hình thanh: 巾 (vải) + 番 (biểu âm). Nghĩa gốc là cờ hiệu dài — loại cờ vải mỏng treo dọc, dùng trong nghi lễ Phật giáo hoặc quân sự. Wiktionary ghi nhận âm Mân Nam hoan, seal script và liushutong có dạng rõ. Nghĩa phái sinh: 幡然 (lật mặt, thay đổi đột ngột — như lật cờ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cờ hiệu; lật mặt", "Hạng Tần Suất (Jun Da)": "3431.0", "Tần Suất % (Jun Da)": "99.5077528571", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幡", "Unihan_Traditional (Chữ Phồn thể)": "幡", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ các loại cờ dài treo ở chùa hoặc động từ chỉ sự thay đổi nhanh chóng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霹', '{"9000": "3432.0", "Chữ Trung Quốc": "霹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 21 | nét | 雨 | vũ | biểu nghĩa | mưa, thời tiết | 辟 | tích | biểu âm | 霹 = 雨 (Vũ, biểu nghĩa: mưa, thời tiết) + 辟 (Tích, biểu âm). Chữ hình thanh — bộ 雨 cho biết đây là hiện tượng thời tiết, phần 辟 gợi âm đọc pī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": mưa 雨 tách 辟 bầu trời — sét tích lịch nổ vang, xé toạc bầu trời đêm. | Gương Hán-Việt | tích lịch (霹靂) — sét đánh bất ngờ; bình địa tích lịch (平地霹雳) — tin sét đánh | Mở khoá kiến thức | Biết 霹 mở khoá: 霹雳 (sét), 晴天霹雳 (trời quang sấm nổ — tin bất ngờ kinh hoàng).", "Tự nguyên_Xie": "霹 (tích/phích) từ hình thanh: 雨 (mưa) + 辟 (biểu âm). Nghĩa chỉ dùng trong 霹靂 (tích lịch — sấm sét đánh bất ngờ). Wiktionary ghi nhận âm Mân Nam phek. Không có ảnh cổ văn. Chữ gần như chỉ dùng trong từ ghép 霹靂, chưa có nghĩa độc lập. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tích lịch, phích lịch 霹靂)", "Hạng Tần Suất (Jun Da)": "3432.0", "Tần Suất % (Jun Da)": "99.5083187368", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霹", "Unihan_Traditional (Chữ Phồn thể)": "霹", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong từ ghép để mô tả tiếng sấm sét lớn hoặc sự kiện chấn động. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竺', '{"9000": "3433.0", "Chữ Trung Quốc": "竺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 8 | nét | 𥫗 | trúc | biểu âm | tre (biến thể) | 二 | nhị | biểu nghĩa | hai — dày, chắc | 竺 theo Shuowen: 𥫗 (biến thể của 竹, biểu âm) + 二 (Nhị, biểu nghĩa: dày). Chữ hình thanh theo Shuowen — gợi nghĩa dày, đặc. Trong thực tế, 竺 chủ yếu dùng như tên riêng (Thiên Trúc — tên cổ của Ấn Độ) và họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trúc\": như hai 二 cây tre 𥫗 mọc dày — Thiên Trúc (Ấn Độ), nơi Phật Pháp ra đời dày đặc như rừng tre. | Gương Hán-Việt | Thiên Trúc (天竺) — tên cổ của Ấn Độ; Trúc (竺) — họ người Trung Quốc | Mở khoá kiến thức | Biết 竺 mở khoá: 天竺 (Thiên Trúc — Ấn Độ trong Phật giáo), 竺法兰 (tên nhà sư Ấn Độ đầu tiên đến Trung Quốc).", "Tự nguyên_Xie": "竺 (trúc) theo Wiktionary trích Shuowen: 竹 (biến thể) + 二 (biểu nghĩa dày). Nghĩa cổ là dày, đặc — đồng nghĩa với 篤 (đốc). Trong lịch sử Phật giáo Trung Quốc, 竺 dùng trong 天竺 (Thiên Trúc — tên Trung cổ của Ấn Độ). Cũng là họ người. Không có ảnh cổ văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Trúc", "Hạng Tần Suất (Jun Da)": "3433.0", "Tần Suất % (Jun Da)": "99.5088846165", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 二", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮二", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "二", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "竺", "Unihan_Traditional (Chữ Phồn thể)": "竺", "Pinyin_Xie": "zhú", "Âm Hán Việt_Xie": "trúc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ nước Ấn Độ cổ hoặc làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烙', '{"9000": "3434.0", "Chữ Trung Quốc": "烙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 火 | hoả | biểu nghĩa | lửa | 各 | các | biểu âm | 烙 = 火 (Hoả, biểu nghĩa: lửa) + 各 (Các, biểu âm). Chữ hình thanh — bộ 火 cho biết liên quan đến nhiệt, phần 各 gợi âm đọc lào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\": lửa 火 ép vào từng 各 chỗ — bàn là lạc nóng ủi phẳng quần áo, để lại dấu lạc ấn. | Gương Hán-Việt | lạc ấn (烙印) — dấu ấn sâu đậm; lạc thiết (烙铁) — bàn là, mỏ hàn | Mở khoá kiến thức | Biết 烙 mở khoá: 烙印 (dấu ấn khó phai), 烙铁 (mỏ hàn, bàn là), 烙饼 (bánh tráng nướng).", "Tự nguyên_Xie": "烙 (lạc) từ hình thanh: 火 (lửa) + 各 (biểu âm). Nghĩa gốc: dùng vật nóng ép lên bề mặt — là, ủi quần áo; đóng dấu sắt nung (烙印). Không có ảnh cổ văn. Nghĩa phái sinh quan trọng: 烙印 (dấu ấn sâu đậm không phai — như dấu sắt nung vào da). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "là (quần áo)", "Hạng Tần Suất (Jun Da)": "3434.0", "Tần Suất % (Jun Da)": "99.5094494627", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烙", "Unihan_Traditional (Chữ Phồn thể)": "烙", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ thể hiện hành động nướng, là ủi hoặc đóng dấu sắt nung lên da thịt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毗', '{"9000": "3435.0", "Chữ Trung Quốc": "毗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 9 | nét | 囟 | tín | biểu nghĩa | thóp đầu (liền kề, gần) | 比 | tỷ | biểu âm | 毗 = 囟 (Tín, biểu nghĩa: thóp đầu — ý kề cận) + 比 (Tỷ, biểu âm). Chữ hình thanh — bộ 囟 gợi ý liền kề, phần 比 gợi âm đọc pí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỳ\": thóp đầu 囟 so sánh 比 kề nhau — hai vật tỳ vào nhau, kề cận tiếp giáp. | Gương Hán-Việt | tỳ lân (毗邻) — kề liền, tiếp giáp; tỳ liên (毗连) — liền kề nhau | Mở khoá kiến thức | Biết 毗 mở khoá: 毗邻 (kề liền), 毗连 (tiếp giáp), 毗沙门 (Tỳ Sa Môn — Phật giáo).", "Tự nguyên_Xie": "Lục thư thông | 毗 (tỳ) từ hình thanh: 囟 (thóp đầu — kề cận) + 比 (biểu âm). Nghĩa gốc: kề liền, tiếp giáp. Nghĩa mở rộng: giúp đỡ, hỗ trợ. Wiktionary ghi nhận Lục thư thông (liushutong). Dùng trong 毗邻 (kề liền), 毗连 (tiếp giáp). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giúp đỡ", "Hạng Tần Suất (Jun Da)": "3435.0", "Tần Suất % (Jun Da)": "99.5100143089", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "比", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "毗", "Unihan_Traditional (Chữ Phồn thể)": "毗", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "bì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ trong văn viết để chỉ sự tiếp giáp, liền kề về địa lý. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸠', '{"9000": "3436.0", "Chữ Trung Quốc": "鸠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 7 | nét | 九 | cửu | biểu âm | 鸟 | điểu | biểu nghĩa | chim | 鸠 giản thể của 鳩. Chữ gồm 九 (Cửu, biểu âm) + 鸟 (Điểu, biểu nghĩa: chim). Chữ hình thanh — bộ 鸟 cho biết đây là loài chim, phần 九 gợi âm đọc jiū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cưu\": chín 九 con chim 鸟 — đàn chim cưu gù gù kêu, kẻ kém cỏi chen vào chiếm chỗ người xứng đáng. | Gương Hán-Việt | cưu (鸠) — chim cu; cưu chiếm thước sào (鸠占鹊巢) — kẻ xấu chiếm chỗ người tốt | Mở khoá kiến thức | Biết 鸠 mở khoá: 鸠占鹊巢 (chiếm chỗ người khác), 鸠合 (tập hợp), 斑鸠 (chim cu gáy).", "Tự nguyên_Xie": "Đại triện | 鸠 giản thể của 鳩, theo Wiktionary. Nghĩa gốc: chim cu, chim bồ câu hoặc chim tu hú. Đại triện có dạng cổ. Dùng trong 鸠占鹊巢 (chim cu chiếm tổ quạ — ý kẻ xấu chiếm chỗ người tốt) và 鸠合 (tập hợp, chiêu mộ). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim tu hú", "Hạng Tần Suất (Jun Da)": "3436.0", "Tần Suất % (Jun Da)": "99.5105786382", "GavinGrover_Once (Chiết tự trực tiếp)": "九 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰九鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "九", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸠", "Unihan_Traditional (Chữ Phồn thể)": "鳩", "Pinyin_Xie": "jiū", "Âm Hán Việt_Xie": "cưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ loài chim hoặc động từ với nghĩa tập hợp, gom góp lại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('埠', '{"9000": "3437.0", "Chữ Trung Quốc": "埠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 11 | nét | 土 | thổ | biểu nghĩa | đất | 阜 | phụ | biểu âm | 埠 = 土 (Thổ, biểu nghĩa: đất, công trình đất) + 阜 (Phụ, biểu âm). Chữ hình thanh — bộ 土 cho biết liên quan đến mặt đất hoặc bến bờ, phần 阜 gợi âm đọc bù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": đất 土 gò cao phụ 阜 cạnh bờ nước — bến phụ cận, nơi thuyền bè tấp vào. | Gương Hán-Việt | phụ đầu (埠头) — bến tàu; bản phụ (本埠) — thành phố này, địa phương này | Mở khoá kiến thức | Biết 埠 mở khoá: 码头 (bến tàu), 本埠 (địa phương), 外埠 (nơi khác), 商埠 (thương cảng).", "Tự nguyên_Xie": "埠 (phụ) từ hình thanh: 土 (đất) + 阜 (biểu âm). Nghĩa gốc: bến đỗ cho tàu thuyền — mặt đất xây dựng cạnh nước. Dùng trong 码头 địa danh như 上海埠, 广州埠. Trong tiếng Quảng Đông, 埠 (bou6) rất phổ biến chỉ thành phố cảng, như 本埠 (thành phố này), 外埠 (thành phố khác). Không có ảnh cổ văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bến đỗ cho thuyền buôn", "Hạng Tần Suất (Jun Da)": "3437.0", "Tần Suất % (Jun Da)": "99.5111424508", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 阜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土阜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "埠", "Unihan_Traditional (Chữ Phồn thể)": "埠", "Pinyin_Xie": "bù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ bến cảng sông biển hoặc các đô thị thương mại lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蒜', '{"9000": "3438.0", "Chữ Trung Quốc": "蒜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蒜 | tỏi | tượng hình | cây tỏi — hai củ tỏi (biến thể của 示 hoặc 奈 ghép đôi) | 蒜 theo Wiktionary là sự lặp đôi của 奈 hoặc 祟 (theo Guo 2010, Su 2012). Chữ phức tạp, gồm bộ 艹 (Thảo, cây cỏ) ở trên và phần dưới là 示+示 hoặc 祘. Hội ý: cây tỏi mọc thành đôi củ. Chưa có nguồn học thuật thống nhất về ls-code.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỏi\": hai củ 示示 mọc dưới bộ cỏ 艹 — tỏi mọc thành đôi, mùi hăng cay xé mũi. | Gương Hán-Việt | tỏi (蒜) — củ tỏi; đại tỏi (大蒜) — tỏi ta; tiểu tỏi (小蒜) — tỏi tây | Mở khoá kiến thức | Biết 蒜 mở khoá: 大蒜 (tỏi ta), 蒜泥 (tỏi giã), 蒜苗 (hành tỏi non), 蒜蓉 (tỏi băm).", "Tự nguyên_Xie": "Tiểu triện | 蒜 (tỏi) theo Wiktionary là sự lặp đôi của 奈 hoặc 祟 (Guo 2010, Su 2012). Cũng liên hệ với 祘. Seal script có dạng rõ. Nghĩa gốc và duy nhất: củ tỏi — Allium sativum. Chữ tạo từ sự quan sát hình thái hai tép tỏi mọc thành cặp. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "củ tỏi", "Hạng Tần Suất (Jun Da)": "3438.0", "Tần Suất % (Jun Da)": "99.5117062634", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 祘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹祘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "祘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蒜", "Unihan_Traditional (Chữ Phồn thể)": "蒜", "Pinyin_Xie": "suàn", "Âm Hán Việt_Xie": "toán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc kết hợp để chỉ củ tỏi và các món ăn liên quan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | suàn | / | tỏi | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thực phẩm II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阜', '{"9000": "3439.0", "Chữ Trung Quốc": "阜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 8 | nét | 阜 | phụ | tượng hình | bậc thang trên gò đồi — gò đất cao, nhiều bậc | 阜 là chữ tượng hình: hình ảnh các bậc thang leo lên gò đồi (vẫn thấy rõ phần trên là 𠂤 — bậc thang). Chữ độc thể tượng hình thuần túy, là bộ thủ của các chữ địa danh như 阿, 院, 陈, 防.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phụ\": bậc thang 𠂤 leo lên gò cao — phụ địa, gò đất cao phụ vững chắc như nền móng. | Gương Hán-Việt | phụ dụ (阜盛) — phồn thịnh, dồi dào; vật phụ dân phong (物阜民丰) — vật chất dồi dào, dân no đủ | Mở khoá kiến thức | Biết 阜 mở khoá: 物阜民丰 (dân giàu vật đủ), bộ 阜 (阝bên trái) trong 阿院陈防队.", "Tự nguyên_Xie": "Giáp cốt văn | 阜 (phụ) theo Wiktionary là tượng hình: hàng bậc thang trên sườn đồi. Giáp cốt văn có dạng cổ rõ ràng. Nghĩa gốc: gò đồi, nền đất cao. Nghĩa mở rộng: to lớn, phồn thịnh (phụ dụ — giàu có). Là bộ thủ của rất nhiều chữ địa hình và địa lý trong tiếng Trung. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "579.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình dạng dãy núi được viết đứng. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Mô phỏng hình ảnh đồi núi chập chùng để tạo thành chữ Phụ.", "Nghĩa Tiếng Việt_Xie": "gò đất; to lớn; béo", "Hạng Tần Suất (Jun Da)": "3439.0", "Tần Suất % (Jun Da)": "99.5122690424", "GavinGrover_Once (Chiết tự trực tiếp)": "𠂤 + 十", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𠂤十", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𠂤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "十", "Unihan_Simplified (Chữ Giản thể)": "阜", "Unihan_Traditional (Chữ Phồn thể)": "阜", "Pinyin_Xie": "fù", "Âm Hán Việt_Xie": "phụ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường làm danh từ chỉ gò đất hoặc làm tính từ trong văn ngôn để chỉ sự trù phú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嘈', '{"9000": "3440.0", "Chữ Trung Quốc": "嘈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 14 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 曹 | tào | biểu âm | (cho âm cáo) | 嘈 = 口 (Khẩu, biểu nghĩa: âm thanh, miệng) + 曹 (Tào, biểu âm); chữ hình thanh. Bộ khẩu chỉ âm thanh; 曹 cho âm cáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tào\": miệng (口) tào lao — tào lao ồn ào, tiếng người tào lao vang lên khắp nơi. | Gương Hán-Việt | \"tào\" trong 曹 (tào — đám đông, bọn); 嘈 là tiếng ồn của đám đông | Mở khoá kiến thức | Biết 嘈 mở khoá 嘈杂 (ồn ào), 嘈闹 (náo nhiệt), 嘈嘈 (ầm ĩ liên tục).", "Tự nguyên_Xie": "嘈 là chữ hình thanh: bộ 口 (khẩu — miệng, âm thanh) biểu nghĩa; 曹 (tào) cho âm cáo. Theo Wiktionary, nghĩa là ồn ào, náo loạn. Tiếng Quảng thường dùng thêm nghĩa cãi nhau, phàn nàn. Trong Quan Thoại chủ yếu xuất hiện trong 嘈杂 (ồn ào, náo nhiệt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ầm ĩ, ồn ào", "Hạng Tần Suất (Jun Da)": "3440.0", "Tần Suất % (Jun Da)": "99.5128307878", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 曹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口曹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嘈", "Unihan_Traditional (Chữ Phồn thể)": "嘈", "Pinyin_Xie": "cáo", "Âm Hán Việt_Xie": "tào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả âm thanh ồn ào hoặc làm động từ trong các từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乒', '{"9000": "3441.0", "Chữ Trung Quốc": "乒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丿 | Số nét | 6 | nét | 乒 | binh | tượng thanh | chữ tượng thanh hiện đại, mô phỏng tiếng ''bộp'' | 乒 là chữ tượng thanh hiện đại — tạo bằng cách bớt một nét từ chữ 兵 (quân). Cùng với chữ chị em 乓 (cũng từ 兵 bớt một nét đối xứng), hai chữ ghép thành từ tượng thanh 乒乓 — tiếng bộp bộp khi đánh bóng bàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Binh\": bớt một chân của chữ 兵 (binh) — đó là ''binh'' 乒, mô phỏng tiếng đánh bóng bàn. | Gương Hán-Việt | ''Binh'' (乒) chủ yếu xuất hiện trong 乒乓 (binh bàng — tiếng bóng bàn). | Mở khoá kiến thức | Biết 乒 mở khoá 乒乓球 (binh bàng cầu, bóng bàn), 乒乓 (binh bàng, tiếng bóng).", "Tự nguyên_Xie": "Theo Wiktionary, 乒 là chữ tượng thanh tương đối mới, được tạo bằng cách bớt nét nghiêng bên trái của chữ 兵 (quân). Cùng với 乓 (bớt nét bên phải của 兵), hai chữ ghép thành từ tượng thanh 乒乓 — tiếng ''bộp bộp/bíng-bòng'' khi đánh bóng. Cả hai chữ chỉ xuất hiện trong từ ghép 乒乓 và các từ phái sinh như 乒乓球 (bóng bàn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đoành, đoàng, đùng, bộp, bịch (tiếng súng nố)", "Hạng Tần Suất (Jun Da)": "3441.0", "Tần Suất % (Jun Da)": "99.5133920165", "GavinGrover_Once (Chiết tự trực tiếp)": "丘 + 丿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丘丿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丿", "Unihan_Simplified (Chữ Giản thể)": "乒", "Unihan_Traditional (Chữ Phồn thể)": "乒", "Pinyin_Xie": "pīng", "Âm Hán Việt_Xie": "binh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng nổ, tiếng va đập hoặc kết hợp tạo thành từ chỉ môn bóng bàn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帷', '{"9000": "3442.0", "Chữ Trung Quốc": "帷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 11 | nét | 巾 | can | biểu nghĩa | vải, màn | 惟 | duy | biểu âm | 帷 gồm bộ 巾 (Can, biểu nghĩa: vải, màn vải) và thành phần biểu âm gợi âm wéi. Chữ hình thanh — bộ 巾 cho biết đây là đồ vật bằng vải, phần âm gợi âm đọc. Nghĩa gốc: cái màn, cái rèm vải che chắn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duy\": vải 巾 duy nhất 惟 che phủ — cái màn duy trướng che kín lều trại, nơi các tướng bàn mưu. | Gương Hán-Việt | duy ác (帷幄) — màn trướng (trung tâm chỉ huy); vận trù duy ác (运筹帷幄) — lên kế hoạch trong màn trướng | Mở khoá kiến thức | Biết 帷 mở khoá: 帷幄 (trung tâm chỉ huy), 运筹帷幄 (lập kế hoạch từ xa), 帷幕 (màn sân khấu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 帷 (duy) theo Wiktionary, dùng trong văn ngôn với nghĩa lều vải, màn che, rèm. Không có ảnh cổ văn cụ thể trong anchor. Seal script và liushutong có dạng. Thường xuất hiện trong 帷幄 (màn trướng — trung tâm chỉ huy) và 运筹帷幄 (mưu tính trong màn trướng — lên kế hoạch). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái màn", "Hạng Tần Suất (Jun Da)": "3442.0", "Tần Suất % (Jun Da)": "99.5139532451", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帷", "Unihan_Traditional (Chữ Phồn thể)": "帷", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "duy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu hoặc vị trí để chỉ các loại màn che. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啄', '{"9000": "3443.0", "Chữ Trung Quốc": "啄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 豖 | biểu âm | 啄 = 口 (Khẩu, biểu nghĩa: miệng) + 豖 (biểu âm, không có Hán-Việt phổ biến). Chữ hình thanh — bộ 口 cho biết liên quan đến hành động miệng/mỏ, phần 豖 gợi âm đọc zhuó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trốc\": mỏ 口 như dao nhọn trốc vào gỗ — chim trốc mổ liên hồi, âm thanh gõ gõ vang rừng. | Gương Hán-Việt | trốc mộc điểu (啄木鸟) — chim gõ kiến; trốc thực (啄食) — mổ thức ăn | Mở khoá kiến thức | Biết 啄 mở khoá: 啄木鸟 (chim gõ kiến), 啄食 (mổ ăn), 一啄一饮 (mọi việc có số phận).", "Tự nguyên_Xie": "Tiểu triện | 啄 (trốc) từ hình thanh: 口 (miệng/mỏ) + 豖 (biểu âm). Nghĩa gốc: mổ — hành động dùng mỏ nhọn chọc vào. Wiktionary ghi nhận seal script. Nghĩa duy nhất và rõ ràng: chim dùng mỏ mổ, chọc. Dùng trong 啄木鸟 (chim gõ kiến — mổ vào gỗ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mổ (chim)", "Hạng Tần Suất (Jun Da)": "3443.0", "Tần Suất % (Jun Da)": "99.5145134402", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 豖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口豖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啄", "Unihan_Traditional (Chữ Phồn thể)": "啄", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ thức ăn để diễn tả hành động mổ của loài chim. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳌', '{"9000": "3444.0", "Chữ Trung Quốc": "鳌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 18 | nét | 敖 | ngào | biểu âm | phiên âm cho áo | 魚 | ngư | biểu nghĩa | cá, sinh vật dưới nước | 鳌 là chữ hình thanh: 魚 (Ngư, biểu nghĩa: cá/sinh vật biển) + 敖 (Ngào, biểu âm). Chữ chỉ loài rùa biển khổng lồ trong thần thoại Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngao\": bộ 魚 (ngư: cá/thuỷ tộc) + 敖 (ngào: ngạo nghễ) — con rùa 鳌 khổng lồ ngự trị biển cả như bậc đứng đầu. | Gương Hán-Việt | \"ngao\" ít dùng trong tiếng Việt hiện đại; gặp trong thi ca cổ chỉ con rùa thần | Mở khoá kiến thức | Biết 鳌 mở khoá hình ảnh thần thoại: 鳌头 (đứng đầu bảng thi), 独占鳌头 (đứng nhất).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 魚 (ngư) biểu nghĩa chỉ loài sinh vật biển; 敖 (ngào) cho âm đọc. Trong thần thoại, 鳌 là con rùa biển khổng lồ đội ba hòn đảo tiên trên lưng. Biến thể phồn thể là 鰲. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngao, con trạch", "Hạng Tần Suất (Jun Da)": "3444.0", "Tần Suất % (Jun Da)": "99.5150731185", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳌", "Unihan_Traditional (Chữ Phồn thể)": "鰲", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc xuất hiện trong các điển tích, thành ngữ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('毡', '{"9000": "3445.0", "Chữ Trung Quốc": "毡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 毛 | Số nét | 9 | nét | 亶 | biểu âm | phiên âm cho zhān | 毛 | mao | biểu nghĩa | lông, tóc | 毡 là chữ hình thanh: 毛 (Mao, biểu nghĩa: lông/lông thú) + 亶 (biểu âm). Chữ chỉ nỉ, dạ — loại vải ép từ lông cừu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chiên\": tấm dạ 毡 được ép từ lông (毛 - mao) cừu — nghĩ đến tấm chăn chiên dày ấm. | Gương Hán-Việt | \"chiên\" trong \"chiên nỉ\" (vải dạ), gặp trong văn bản cổ chỉ vải len/nỉ | Mở khoá kiến thức | Biết 毡 mở khoá: 毡房 (lều nỉ của dân du mục), 毡帽 (mũ nỉ), 毡靴 (bốt nỉ).", "Tự nguyên_Xie": "Chữ hình thanh. 毛 (mao) biểu nghĩa chỉ lông thú — nguyên liệu làm nỉ/dạ; 亶 cho âm đọc zhān. Trong một số font chữ, phần dưới bên trái là 且 thay vì dạng chuẩn. Nỉ là sản phẩm ép lông cừu đặc trưng của vùng thảo nguyên Trung Á. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "467.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mao (38) Chiêm (106)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Mao (số 82 - lông thú) và chữ Chiêm (số 25 - bói toán) . Dùng lông thú (Mao) để làm ra đồ vật giữ ấm khi ngồi bái lạy bói toán (Chiêm) gọi là nệm lông (chiên). Giải thích sự chuyển ý: Chữ Chiêm (bói toán) chỉ âm, chữ Mao (lông thú) chỉ ý. Tấm thảm, đệm được dệt bện từ lông thú (Mao) gọi là chiên. *(Biến âm Hán Việt: Chiêm -> Chiên)*", "Nghĩa Tiếng Việt_Xie": "mền, chăn, giạ", "Hạng Tần Suất (Jun Da)": "3445.0", "Tần Suất % (Jun Da)": "99.51563228", "GavinGrover_Once (Chiết tự trực tiếp)": "毛 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴毛占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "毛", "Unihan_Simplified (Chữ Giản thể)": "毡", "Unihan_Traditional (Chữ Phồn thể)": "氈", "Pinyin_Xie": "zhān", "Âm Hán Việt_Xie": "chiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ chất liệu nỉ dạ hoặc các vật dụng làm từ chất liệu này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阙', '{"9000": "3446.0", "Chữ Trung Quốc": "阙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 13 | nét | 欮 | biểu âm | phiên âm | 門 | môn | biểu nghĩa | cửa, cổng | 阙 là chữ hình thanh: 門 (Môn, biểu nghĩa: cổng/cửa) + 欮 (biểu âm). Chữ chỉ tháp canh hai bên cổng cung điện, hoặc nghĩa phái sinh là khuyết thiếu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuyết\": cổng cung (門 - môn) có khoảng 阙 trống giữa — từ đó sinh nghĩa khuyết thiếu. | Gương Hán-Việt | \"khuyết\" trong \"khuyết điểm\" (điểm thiếu sót), \"khuyết tật\" (tật nguyền) | Mở khoá kiến thức | Biết 阙 mở khoá: 宫阙 (cung điện), 阙疑 (bỏ qua điều còn nghi ngờ), 连篇累阙 (sai lỗi liên tiếp).", "Tự nguyên_Xie": "Chữ hình thanh. 門 (môn) biểu nghĩa chỉ cổng/cửa; 欮 cho âm đọc. 阙 nguyên chỉ tháp canh dựng hai bên cổng cung điện thời cổ. Từ hình ảnh \"khoảng trống giữa hai tháp\", chữ mở rộng nghĩa thành \"khuyết thiếu, thiếu sót\". | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cửa hai lớp; cửa ngoài cung điện", "Hạng Tần Suất (Jun Da)": "3446.0", "Tần Suất % (Jun Da)": "99.5161914416", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 欮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门欮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阙", "Unihan_Traditional (Chữ Phồn thể)": "闕", "Pinyin_Xie": "quē", "Âm Hán Việt_Xie": "khuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Thường làm danh từ chỉ cổng cung điện hoặc làm tính từ chỉ sự thiếu sót, không hoàn chỉnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褥', '{"9000": "3447.0", "Chữ Trung Quốc": "褥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衣 | y | biểu nghĩa | quần áo, vải vóc | 辱 | nhục | biểu âm | phiên âm cho rù | 褥 là chữ hình thanh: 衣 (Y, biểu nghĩa: vải/đồ vải) + 辱 (Nhục, biểu âm). Chữ chỉ tấm đệm, chiếu hoặc chăn bông dùng trải/đắp khi ngủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhục\": tấm đệm 褥 làm bằng vải (衣 - y) — bộ 衣 biểu nghĩa vải vóc, 辱 (nhục) cho âm; đắp tấm đệm này mà ngủ ngon giấc đêm đông. | Gương Hán-Việt | \"nhục\" ít dùng với nghĩa đệm; thường gặp trong văn ngữ cổ chỉ tấm nệm/trải giường | Mở khoá kiến thức | Biết 褥 mở khoá: 褥子 (tấm đệm), 褥疮 (loét tì đè), 棉褥 (đệm bông).", "Tự nguyên_Xie": "Chữ hình thanh. 衣 (y) biểu nghĩa chỉ đồ vải — loại vật dụng bằng vải; 辱 (nhục) cho âm đọc rù. 褥 chỉ tấm đệm hoặc chăn bông dày dùng trong phòng ngủ. Không liên quan đến nghĩa của 辱 (nhục nhã). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "915.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Y (145) Nhục (914)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Y (số 145 - cái áo/ 衤) ở bên trái chữ Nhục (số 914 - xấu hổ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nhục (辱) chỉ âm, bộ Y chỉ ý. Nhục (褥) là cái đệm, cái nệm trải trên ghế, trên giường.", "Nghĩa Tiếng Việt_Xie": "cái đệm (để nằm)", "Hạng Tần Suất (Jun Da)": "3447.0", "Tần Suất % (Jun Da)": "99.5167500863", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 辱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤辱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褥", "Unihan_Traditional (Chữ Phồn thể)": "褥", "Pinyin_Xie": "rù", "Âm Hán Việt_Xie": "nhục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các lượng từ như điều, cái để chỉ tấm đệm nằm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搔', '{"9000": "3448.0", "Chữ Trung Quốc": "搔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 手 | thủ | biểu nghĩa | tay | 蚤 | tao | biểu âm | bọ chét | 搔 là chữ hình thanh: 手 (Thủ, biểu nghĩa: tay) + 蚤 (Tao, biểu âm: bọ chét). Chữ chỉ hành động gãi bằng tay — sinh động ở chỗ \"bọ chét cắn → tay gãi\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trao\": bọ chét (蚤 - tao) đốt, tay (手 - thủ) phải gãi 搔 — âm \"trao\" gợi hình ảnh trao đổi gãi qua lại. | Gương Hán-Việt | \"trao\" ít dùng đơn lẻ; gặp trong \"tao\" (bộ chét) liên quan âm | Mở khoá kiến thức | Biết 搔 mở khoá: 搔痒 (gãi ngứa), 搔头 (gãi đầu, ẩn dụ suy nghĩ), 隔靴搔痒 (thành ngữ: làm không đúng chỗ).", "Tự nguyên_Xie": "Chữ hình thanh. 手 (thủ) biểu nghĩa chỉ tay — dùng tay để gãi; 蚤 (tao) vừa cho âm đọc vừa gợi hình ảnh: bọ chét (蚤) đốt khiến phải dùng tay (手) gãi. Đây là chữ hình thanh với nội dung ngữ nghĩa bổ trợ rất trực quan. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gãi", "Hạng Tần Suất (Jun Da)": "3448.0", "Tần Suất % (Jun Da)": "99.5173082142", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 蚤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌蚤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蚤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搔", "Unihan_Traditional (Chữ Phồn thể)": "搔", "Pinyin_Xie": "sāo", "Âm Hán Việt_Xie": "tao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ bộ phận cơ thể để diễn tả hành động gãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笋', '{"9000": "3449.0", "Chữ Trung Quốc": "笋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 尹 | doãn | biểu âm | phiên âm | 笋 là dạng giản thể của 筍, chữ hình thanh: 竹 (Trúc, biểu nghĩa: tre/trúc) + phần biểu âm. Chữ chỉ măng — chồi non của cây tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuẫn\": măng 笋 là chồi non mọc lên từ gốc trúc (竹 - trúc) — vươn lên như người tuẫn tiết kiên cường. | Gương Hán-Việt | \"tuẫn\" ít dùng trong tiếng Việt hiện đại; măng được gọi là \"măng\" trong tiếng Việt thuần | Mở khoá kiến thức | Biết 笋 mở khoá: 竹笋 (măng tre), 笋干 (măng khô), 春笋 (măng xuân), 雨后春笋 (thành ngữ: mọc nhanh như măng sau mưa).", "Tự nguyên_Xie": "笋 là biến thể giản thể của 筍 (xem thêm mục 筍 trên Wiktionary). 竹 (trúc) biểu nghĩa chỉ cây tre — nguồn gốc của măng; phần còn lại cho âm đọc sǔn. Chưa có nguồn học thuật độc lập cho dạng giản thể này. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "măng tre", "Hạng Tần Suất (Jun Da)": "3449.0", "Tần Suất % (Jun Da)": "99.5178658254", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 尹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮尹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笋", "Unihan_Traditional (Chữ Phồn thể)": "筍", "Pinyin_Xie": "sǔn", "Âm Hán Việt_Xie": "duẩn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với các từ khác để chỉ các món ăn từ măng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冕', '{"9000": "3450.0", "Chữ Trung Quốc": "冕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冂 | Số nét | 11 | nét | 冕 | miện | tượng hình | vương miện, mũ miện của vua quan | 冕 là chữ hội ý/tượng hình phức hợp: phần trên là 冂 (mái che) kết hợp với yếu tố chỉ mặt và đầu người đội mũ. Chữ mô tả chiếc mũ miện của vua quan thời cổ đại Trung Hoa. Chưa có phân tích hình thanh/hội ý rõ ràng từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miện\": vương miện 冕 — chiếc mũ (có mái che 冂) trang nghiêm của vua quan; \"miện\" gợi âm \"miện\" trong \"vương miện\" tiếng Việt. | Gương Hán-Việt | \"miện\" trong \"vương miện\" (mũ vua), \"miện phục\" (lễ phục đội mũ nghi lễ) | Mở khoá kiến thức | Biết 冕 mở khoá: 王冕 (vương miện), 加冕 (đội mũ/lên ngôi), 冠冕堂皇 (thành ngữ: vẻ ngoài trang nghiêm nhưng rỗng tuếch).", "Tự nguyên_Xie": "Chưa có nguồn học thuật đầy đủ từ Wiktionary cho cấu trúc của 冕. Chữ mô tả vương miện — chiếc mũ nghi lễ của vua và quan chức cấp cao thời cổ đại. Hình dạng gốc trong kim văn cho thấy người quỳ đội mũ có mái che phía trước. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mũ miện", "Hạng Tần Suất (Jun Da)": "3450.0", "Tần Suất % (Jun Da)": "99.5184229198", "GavinGrover_Once (Chiết tự trực tiếp)": "冃 + 免", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冃免", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "免", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冃", "Unihan_Simplified (Chữ Giản thể)": "冕", "Unihan_Traditional (Chữ Phồn thể)": "冕", "Pinyin_Xie": "miǎn", "Âm Hán Việt_Xie": "miện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ mũ đội của hoàng đế thời xưa hoặc dùng trong các từ ghép chỉ sự đăng quang. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狞', '{"9000": "3451.0", "Chữ Trung Quốc": "狞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 犭 | khuyển | biểu nghĩa | chó, thú dữ | 宁 | ninh | biểu âm | phiên âm cho níng | 狞 là chữ hình thanh: 犭 (Khuyển, biểu nghĩa: thú/chó — chỉ tính hung dữ) + 宁 (Ninh, biểu âm). Chữ chỉ vẻ mặt hung dữ, đáng sợ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nịnh\": bộ 犭 (khuyển - thú dữ) + 宁 (ninh) — mặt 狞 hung dữ như chó hoang, khác hẳn nịnh hót dù cùng âm. | Gương Hán-Việt | \"nịnh\" trong tiếng Việt thường mang nghĩa nịnh hót — nhưng 狞 chỉ vẻ hung dữ, không liên quan | Mở khoá kiến thức | Biết 狞 mở khoá: 狞笑 (cười gian ác/đáng sợ), 面目狞恶 (mặt mũi hung dữ).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho cấu trúc 狞. Theo phân tích hình thể: 犭 (khuyển) biểu nghĩa chỉ thú hung dữ; 宁 (ninh) cho âm đọc níng. Chữ mô tả vẻ mặt hung tợn, dữ dằn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tranh ninh, tranh nanh 猙獰)", "Hạng Tần Suất (Jun Da)": "3451.0", "Tần Suất % (Jun Da)": "99.5189800142", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狞", "Unihan_Traditional (Chữ Phồn thể)": "獰", "Pinyin_Xie": "níng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp thành từ ghép như tranh nanh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韶', '{"9000": "3452.0", "Chữ Trung Quốc": "韶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 音 | Số nét | 14 | nét | 音 | âm | biểu nghĩa | âm thanh, nhạc | 召 | triệu | biểu âm | phiên âm cho sháo | 韶 là chữ hình thanh: 音 (Âm, biểu nghĩa: âm nhạc) + 召 (Triệu, biểu âm). Chữ chỉ nhạc lễ thời vua Thuấn (舜), tượng trưng cho âm nhạc thanh cao, mùa xuân tươi đẹp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiều\": nhạc 韶 thanh cao (âm - 音) của vua Thuấn vang vọng như tiếng nhạc thiều thiều — \"thiều quang\" là ánh sáng mùa xuân đẹp. | Gương Hán-Việt | \"thiều\" trong \"thiều quang\" (ánh xuân tươi đẹp), \"Thiều\" là tên riêng trong thơ văn Việt | Mở khoá kiến thức | Biết 韶 mở khoá: 韶光 (tuổi xuân/thời gian đẹp), 韶华 (tuổi thanh xuân), 韶乐 (nhạc Thiều của vua Thuấn).", "Tự nguyên_Xie": "Chưa có cấu trúc Wiktionary đầy đủ. Theo phân tích: 音 (âm) biểu nghĩa chỉ âm nhạc; 召 (triệu) cho âm đọc. 韶 là tên bản nhạc lễ nổi tiếng của vua Thuấn — Khổng Tử từng nghe và không biết vị thịt ba tháng. Sau chuyển nghĩa thành tươi đẹp, hài hòa. Chưa có nguồn học thuật rõ ràng hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tốt đẹp", "Hạng Tần Suất (Jun Da)": "3452.0", "Tần Suất % (Jun Da)": "99.5195371085", "GavinGrover_Once (Chiết tự trực tiếp)": "音 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰音召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "音", "Unihan_Simplified (Chữ Giản thể)": "韶", "Unihan_Traditional (Chữ Phồn thể)": "韶", "Pinyin_Xie": "sháo", "Âm Hán Việt_Xie": "thiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ mô tả vẻ đẹp thanh xuân hoặc làm danh từ chỉ một loại nhạc cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骼', '{"9000": "3453.0", "Chữ Trung Quốc": "骼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 15 | nét | 骨 | cốt | biểu nghĩa | xương | 各 | cac | biểu âm | phiên âm cho gé | 骼 là chữ hình thanh: 骨 (Cốt, biểu nghĩa: xương) + 各 (Cac, biểu âm). Chữ chỉ xương sườn, xương khung, cấu trúc xương của cơ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cách\": bộ xương (骨 - cốt) 骼 giống như khung cách ngăn (各 - cac) cơ thể — \"cốt cách\" là khung xương và phong thái. | Gương Hán-Việt | \"cách\" trong \"cốt cách\" (khí chất, phong thái), \"thể cách\" (hình thể) | Mở khoá kiến thức | Biết 骼 mở khoá: 骨骼 (bộ xương/hệ xương), 骨骼肌 (cơ xương), 骨骼系统 (hệ vận động).", "Tự nguyên_Xie": "Chữ hình thanh. 骨 (cốt) biểu nghĩa chỉ xương; 各 (cac) cho âm đọc gé. 骼 chỉ xương khung — thường dùng trong 骨骼 (bộ xương). Cấu trúc giống 格 và 各 nên dễ nhầm âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xương khô; bộ xương", "Hạng Tần Suất (Jun Da)": "3453.0", "Tần Suất % (Jun Da)": "99.5200942029", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骼", "Unihan_Traditional (Chữ Phồn thể)": "骼", "Pinyin_Xie": "gé", "Âm Hán Việt_Xie": "cách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ và thường kết hợp với cốt để chỉ bộ khung xương của cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔼', '{"9000": "3454.0", "Chữ Trung Quốc": "蔼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 谒 | yết | biểu âm | (rút từ 葛, cho âm ǎi) | 蔼 = 艹 (Thảo, biểu nghĩa: thực vật, sum sê) + 谒 (rút từ gốc âm 葛, biểu âm); chữ hình thanh. Theo Wiktionary, phồn thể 藹 ghép từ 言 (biểu nghĩa) + 葛 (biểu âm); giản thể hoá thành dạng hiện tại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": cây cối (艹) ái mộ tươi tốt — ái hòa, rậm rạp và ôn hoà như cánh rừng bình yên. | Gương Hán-Việt | \"ái\" trong \"hoà ái\" (和蔼 — hoà nhã); 爱 (ái — yêu) cùng âm nhưng khác chữ | Mở khoá kiến thức | Biết 蔼 mở khoá 和蔼 (hoà nhã, thân thiện), 和蔼可亲 (hoà nhã dễ gần), 蔼然 (um tùm, rậm rạp — nghĩa cũ).", "Tự nguyên_Xie": "Lục thư thông | 蔼 (phồn thể 藹) là chữ hình thanh. Theo Wiktionary, phồn thể ghép từ 言 (ngôn — lời nói) biểu nghĩa + 葛 (cát) cho âm. Dạng giản thể 蔼 dùng 艹+谒 nhưng vẫn giữ âm và nghĩa. Nghĩa gốc là um tùm (cây cối rậm rạp); nghĩa phổ biến hiện nay là hoà nhã, thân thiện (trong 和蔼). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cối rậm rạp; hoà nhã", "Hạng Tần Suất (Jun Da)": "3454.0", "Tần Suất % (Jun Da)": "99.5206497469", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 谒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹谒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "谒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔼", "Unihan_Traditional (Chữ Phồn thể)": "藹", "Pinyin_Xie": "ǎi", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị thái độ ôn hòa, thường dùng trong từ ghép hòa ái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烹', '{"9000": "3455.0", "Chữ Trung Quốc": "烹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 亨 | hanh | biểu âm | (cho âm pēng) | 灬 | hoả | biểu nghĩa | lửa (dạng biến thể ở dưới) | 烹 = 亨 (Hanh, biểu âm) + 灬 (Hoả, biểu nghĩa: lửa dưới đáy); chữ hình thanh. Lửa ở dưới chỉ việc đun nấu; 亨 cho âm pēng (biến từ hanh → phanh → pēng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phanh\": lửa (灬) phanh lên dưới nồi — phanh ra, nấu chín bằng lửa to. | Gương Hán-Việt | \"phanh\" trong \"phanh rán\" (烹饪 — nấu ăn), \"phanh trà\" (烹茶 — pha trà theo kiểu đun) | Mở khoá kiến thức | Biết 烹 mở khoá 烹饪 (nấu ăn, ẩm thực), 烹调 (chế biến thức ăn), 烹茶 (pha trà kiểu đun), 兔死狗烹 (thành ngữ: thỏ chết chó bị luộc — công cụ bị bỏ sau khi hết dùng).", "Tự nguyên_Xie": "Đại triện | 烹 là chữ hình thanh: 灬 (hoả — lửa, dạng biến thể viết dưới) biểu nghĩa; 亨 (hanh) cho âm pēng. Theo Wiktionary, nghĩa gốc là đun sôi, nấu chín; cũng có nghĩa xưa là luộc người sống (hình phạt thời cổ). Trong nấu ăn, còn chỉ kỹ thuật xào nhanh rồi thêm nước sốt (烹的烹调技法). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1553.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hanh (1552) Hỏa (085)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hanh (số 1552/ 亨 /chỉ âm) ở trên bộ Hỏa (số 085 - ngọn lửa/bốn chấm hỏa/ 灬 /chỉ ý). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Hanh chỉ âm, bộ Hỏa chỉ ý. Phanh là đun nấu thức ăn cho chín kỹ (phanh nhẫm - nấu nướng).", "Nghĩa Tiếng Việt_Xie": "đun, nấu chín", "Hạng Tần Suất (Jun Da)": "3455.0", "Tần Suất % (Jun Da)": "99.5212047742", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "烹", "Unihan_Traditional (Chữ Phồn thể)": "烹", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ nguyên liệu để biểu thị phương pháp nấu ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奄', '{"9000": "3456.0", "Chữ Trung Quốc": "奄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 8 | nét | 盍 | biểu nghĩa | che phủ, đậy lại | 甲 | giáp | biểu âm | phiên âm | 奄 là chữ hình thanh (và có yếu tố hội ý): 盍 (biểu nghĩa: che phủ) rút gọn + 甲 (Giáp, biểu âm). Theo học giả Chen (2021), gốc nghĩa là che phủ toàn bộ. Từ đó mở rộng thành \"bất ngờ\" và \"thở hắt ra/hấp hối\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\": 奄 vừa che phủ (盍 - đậy) vừa bất ngờ (甲 - giáp đánh úp) — \"奄奄一息\" là thở thoi thóp, gần chết. | Gương Hán-Việt | \"yêm\" trong \"yêm trợ\" (che chở/hỗ trợ), \"yêm\" ít dùng đơn lẻ trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 奄 mở khoá: 奄奄一息 (thở thoi thóp), 奄然 (đột nhiên yên tĩnh/tắt thở).", "Tự nguyên_Xie": "Theo Chen (2021): 奄 là hình thanh, 盍 (rút gọn) biểu nghĩa chỉ che đậy; 甲 (giáp) cho âm đọc. Nghĩa gốc là che phủ toàn bộ. Từ đó phát triển thành \"đột ngột\" (che kín bất ngờ) và \"hấp hối\" (sức lực tắt dần như ngọn nến sắp tắt). Wiktionary ghi nhận cả ls=psc và ls=ic. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1772.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Đại (037) Thân (072)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Đại (số 037 - to lớn/ 大) nằm trên chữ Thân (số 072 - vươn ra/ 申). Vật to lớn khi được mở rộng ra vươn ra thì có thể bao trùm lên vật khác. Giải thích sự chuyển ý: Đây là chữ Hội ý. Yểm là sự bao phủ, trùm lên. Cũng có nghĩa là sự yếu ớt, thoi thóp, tắt thở (yểm yểm, tức yểm).", "Nghĩa Tiếng Việt_Xie": "bao la; bị hoạn; bỗng, chợt", "Hạng Tần Suất (Jun Da)": "3456.0", "Tần Suất % (Jun Da)": "99.5217592846", "GavinGrover_Once (Chiết tự trực tiếp)": "大 + 电", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱大电", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "电", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "大", "Unihan_Simplified (Chữ Giản thể)": "奄", "Unihan_Traditional (Chữ Phồn thể)": "奄", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "yểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này thường làm phó từ chỉ sự đột ngột hoặc làm tính từ mô tả trạng thái yếu ớt. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫖', '{"9000": "3457.0", "Chữ Trung Quốc": "嫖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 票 | phiếu | biểu âm | phiên âm cho piáo | 嫖 là chữ hình thanh: 女 (Nữ, biểu nghĩa: phụ nữ) + 票 (Phiếu, biểu âm). Chữ chỉ hành vi mua dâm — cấu trúc phản ánh tư duy trọng nam của chữ Hán cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phếu\": bộ 女 (nữ) + 票 (phiếu) → phiếu đổi lấy nữ — nghĩa tiêu cực rõ ràng, dùng trong văn bản mô tả tệ nạn xã hội. | Gương Hán-Việt | \"phếu\" ít dùng trong tiếng Việt; gặp trong văn bản pháp luật, văn học cổ chỉ hành vi mua dâm | Mở khoá kiến thức | Biết 嫖 mở khoá: 嫖娼 (mua dâm), 嫖客 (người mua dâm).", "Tự nguyên_Xie": "Chữ hình thanh. 女 (nữ) biểu nghĩa chỉ phụ nữ; 票 (phiếu) cho âm đọc piáo. 嫖 chỉ hành vi mua dâm — một trong những chữ Hán thể hiện tư duy phân biệt giới tính trong cấu trúc ký tự cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhanh nhẹn; làm tình", "Hạng Tần Suất (Jun Da)": "3457.0", "Tần Suất % (Jun Da)": "99.5223137951", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫖", "Unihan_Traditional (Chữ Phồn thể)": "嫖", "Pinyin_Xie": "piáo", "Âm Hán Việt_Xie": "phiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành vi mua dâm và có thể mang tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沐', '{"9000": "3458.0", "Chữ Trung Quốc": "沐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 氵 | thuỷ | biểu nghĩa | nước | 木 | mộc | biểu âm | (cho âm mù) | 沐 = 氵(Thuỷ, biểu nghĩa: nước) + 木 (Mộc, biểu âm); chữ hình thanh. Nước là yếu tố nghĩa, gắn với việc tắm rửa; 木 cho âm mù và đồng âm Hán-Việt mộc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộc\": nước (氵) + mộc (木) — mộc mạc tắm rửa, gội đầu bằng nước sạch. | Gương Hán-Việt | \"mộc\" trong \"mộc dục\" (沐浴 — tắm), \"phong mộc\" (被沐春风 — đắm mình trong gió xuân) | Mở khoá kiến thức | Biết 沐 mở khoá 沐浴 (tắm), 沐浴露 (sữa tắm), 如沐春风 (như tắm trong gió xuân — cảm thấy dễ chịu), 沐恩 (đội ơn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 沐 là chữ hình thanh: bộ 水 (rút thành 氵 — thuỷ) biểu nghĩa; 木 (mộc) cho âm mù. Theo Wiktionary, nghĩa gốc là gội đầu, tắm; mở rộng sang nghĩa nhận ân huệ, đắm mình trong (như 如沐春风 — như được tắm trong gió xuân). Chữ cổ ghi rõ qua các dạng tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "858.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Mộc (075)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - nước) ở bên trái chữ Mộc (số 075 - cây gỗ/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Mộc chỉ âm, bộ Thủy chỉ ý. Mộc là gội đầu (mộc dục).", "Nghĩa Tiếng Việt_Xie": "gội đầu", "Hạng Tần Suất (Jun Da)": "3458.0", "Tần Suất % (Jun Da)": "99.5228677887", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "木", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沐", "Unihan_Traditional (Chữ Phồn thể)": "沐", "Pinyin_Xie": "mù", "Âm Hán Việt_Xie": "mộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hoạt động tắm gội hoặc tiếp nhận ân huệ, ánh sáng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噗', '{"9000": "3459.0", "Chữ Trung Quốc": "噗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng | 菐 | biểu âm | phiên âm cho pū | 噗 là chữ hình thanh, được coi là chữ tạo muộn (後起字): 口 (Khẩu, biểu nghĩa: miệng) + 菐 (biểu âm). Chữ mô tả âm thanh phát ra từ miệng — tiếng \"bốp\", \"phù\" như xịt khí hoặc cười bật ra.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bặc\": miệng (口 - khẩu) bật ra tiếng \"phù/bặc\" — 噗 là chữ tượng thanh chỉ tiếng xịt hoặc cười phá ra. | Gương Hán-Việt | \"bặc\" ít gặp; 噗 chủ yếu dùng trong văn viết hiện đại để diễn đạt tiếng cười bật ra hoặc xịt khí | Mở khoá kiến thức | Biết 噗 mở khoá: 噗哧 (tiếng cười bật ra), 噗嗤 (cười phá ra/sự bùng phát).", "Tự nguyên_Xie": "噗 là chữ tạo muộn (後起字). 口 (khẩu) biểu nghĩa chỉ miệng — nơi phát ra âm thanh; 菐 cho âm đọc pū. Đây là chữ tượng thanh (onomatopoeia) mô tả tiếng xịt, tiếng phù hoặc tiếng cười bật ra ngoài. Chưa thấy trong giáp cốt/kim văn — chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thổi phù, thổi phụt", "Hạng Tần Suất (Jun Da)": "3459.0", "Tần Suất % (Jun Da)": "99.5234207488", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噗", "Unihan_Traditional (Chữ Phồn thể)": "噗", "Pinyin_Xie": "pū", "Âm Hán Việt_Xie": "phốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô tả âm thanh cười phụt ra hoặc tiếng nước phun. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岑', '{"9000": "3460.0", "Chữ Trung Quốc": "岑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 岑 | sầm | tượng hình | ngọn núi nhỏ và nhọn | 岑 có cấu trúc gồm 山 (sơn: núi) ở dưới và yếu tố nhọn ở trên, gợi hình ngọn núi cao nhọn. Không có phân tích hình thanh/hội ý rõ ràng từ Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sầm\": ngọn núi 岑 nhỏ và nhọn — \"sầm\" gợi âm thanh sầm sập của đá núi rơi, núi 岑 hiểm trở. | Gương Hán-Việt | \"sầm\" trong \"sầm sập\" (ào ào, dữ dội); 岑 dùng chủ yếu làm họ người và trong thơ ca | Mở khoá kiến thức | Biết 岑 mở khoá: 岑寂 (tĩnh lặng như núi), 岑参 (nhà thơ Đường nổi tiếng với thơ biên tái).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho cấu trúc 岑. Theo hình dạng: chữ gợi hình ngọn núi nhỏ, cao và nhọn. 岑 cũng là họ người (岑参 — nhà thơ Đường). Chưa có nguồn học thuật rõ ràng hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi nhỏ nhưng cao", "Hạng Tần Suất (Jun Da)": "3460.0", "Tần Suất % (Jun Da)": "99.5239731921", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岑", "Unihan_Traditional (Chữ Phồn thể)": "岑", "Pinyin_Xie": "cén", "Âm Hán Việt_Xie": "sầm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ đỉnh núi hoặc làm tính từ mô tả sự cô tịch, cao vút. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛟', '{"9000": "3461.0", "Chữ Trung Quốc": "蛟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sinh vật, con vật | 交 | giao | biểu âm | phiên âm cho jiāo | 蛟 là chữ hình thanh: 虫 (Trùng, biểu nghĩa: sinh vật — chỉ loài bò sát/thủy tộc) + 交 (Giao, biểu âm). Chữ chỉ giao long — loài rồng nước trong thần thoại Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": 蛟 (giao long) là sinh vật biển (虫 - trùng) với âm giao (交) — giao long quấn quanh như hai thứ giao nhau. | Gương Hán-Việt | \"giao\" trong \"giao long\" (rồng nước), dùng trong thần thoại và thành ngữ | Mở khoá kiến thức | Biết 蛟 mở khoá: 蛟龙 (giao long/rồng nước), 蛟龙出海 (rồng nước ra biển — thành ngữ chỉ người tài xuất đầu lộ diện).", "Tự nguyên_Xie": "Chữ hình thanh. 虫 (trùng) biểu nghĩa chỉ loài sinh vật (trong tiếng Hán cổ, bộ 虫 chỉ nhiều loài bò sát và thủy tộc); 交 (giao) cho âm đọc. 蛟 chỉ \"giao long\" — loài rồng nước trong thần thoại, sống ở sông hồ, có thể gây lũ lụt và bay lên trời. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con thuồng luồng", "Hạng Tần Suất (Jun Da)": "3461.0", "Tần Suất % (Jun Da)": "99.5245256354", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛟", "Unihan_Traditional (Chữ Phồn thể)": "蛟", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài thủy quái trong truyền thuyết, thường làm chủ ngữ hoặc tân ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掳', '{"9000": "3462.0", "Chữ Trung Quốc": "掳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 虏 | lỗ | biểu âm | tù binh, bắt làm tù binh | 掳 là chữ hình thanh: 扌 (Thủ, biểu nghĩa: tay — hành động cầm bắt) + 虏 (Lỗ, biểu âm và biểu nghĩa gợi ý: tù binh). Cấu trúc trực quan: dùng tay bắt làm tù binh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\": tay (扌 - thủ) bắt tù binh (虏 - lỗ) — 掳 là hành động cướp/bắt người bằng vũ lực. | Gương Hán-Việt | \"lỗ\" liên hệ với 虏 (lỗ = tù binh); 掳 gặp trong văn học chiến tranh, lịch sử | Mở khoá kiến thức | Biết 掳 mở khoá: 掳掠 (cướp bóc, bắt giữ), 掳人勒赎 (bắt cóc tống tiền).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 掳. Theo phân tích hình thể: 扌 (thủ) biểu nghĩa chỉ tay — hành động cầm bắt; 虏 (lỗ) vừa cho âm đọc lǔ vừa gợi nghĩa (tù binh). Chữ chỉ hành vi cướp bóc, bắt giữ người trong chiến tranh hoặc cướp đoạt. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắt được", "Hạng Tần Suất (Jun Da)": "3462.0", "Tần Suất % (Jun Da)": "99.5250770452", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 虏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌虏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掳", "Unihan_Traditional (Chữ Phồn thể)": "擄", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ hành động, thường mang tân ngữ chỉ người hoặc tài sản bị bắt, cướp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咏', '{"9000": "3463.0", "Chữ Trung Quốc": "咏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 永 | vĩnh | biểu âm | mãi mãi, dài lâu | 咏 là dạng giản thể của 詠. Chữ hình thanh: 口 (Khẩu, biểu nghĩa: miệng — hát/ngâm) + 永 (Vĩnh, biểu âm). Hình ảnh miệng ngân dài mãi — 咏 nghĩa là hát ngâm, ngâm thơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vẳng\": miệng (口 - khẩu) cất tiếng ngâm vĩnh (永 - vĩnh) cửu — tiếng hát vẳng vẳng mãi không thôi. | Gương Hán-Việt | \"vẳng\" trong \"ngâm vẳng\", \"ca vẳng\" — tiếng hát ngân nga vọng mãi | Mở khoá kiến thức | Biết 咏 mở khoá: 歌咏 (ca hát), 吟咏 (ngâm thơ), 咏叹调 (aria trong opera), 咏物诗 (thơ vịnh vật).", "Tự nguyên_Xie": "咏 là giản thể của 詠 (xem Wiktionary). 口 (khẩu) biểu nghĩa chỉ miệng; 永 (vĩnh) cho âm đọc yǒng — đồng thời gợi hình ảnh âm thanh kéo dài mãi mãi như nước 永 chảy. Chữ chỉ hành động ngâm thơ, hát ca dài và sâu. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "358.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Khẩu (6) Vĩnh (308)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Vĩnh (số 308 - biến âm thành Vịnh) chỉ âm, chữ Khẩu (số 6) chỉ ý. Dùng miệng để ca hát, ngâm thơ. Giải thích sự chuyển ý: Chữ Vĩnh (mãi mãi) chỉ âm, chữ Khẩu (miệng) chỉ ý. Dùng miệng (Khẩu) để ngâm nga, ca hát (Vịnh) cho tiếng vang vọng mãi (Vĩnh). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Vĩnh và chữ Vịnh có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Vĩnh và Vịnh).*", "Nghĩa Tiếng Việt_Xie": "vịnh thơ", "Hạng Tần Suất (Jun Da)": "3463.0", "Tần Suất % (Jun Da)": "99.5256284549", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 永", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口永", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "永", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咏", "Unihan_Traditional (Chữ Phồn thể)": "詠", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "vịnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để chỉ hành động ngâm vịnh hoặc ca ngợi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弩', '{"9000": "3464.0", "Chữ Trung Quốc": "弩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 8 | nét | 奴 | nô | biểu âm | phiên âm cho nǔ | 弓 | cung | biểu nghĩa | cung, cung tên | 弩 là chữ hình thanh: 弓 (Cung, biểu nghĩa: cung tên) + 奴 (Nô, biểu âm). Chữ chỉ nỏ — loại cung có cò (khác với cung thông thường 弓).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nỏ\": cung (弓 - cung) + nô (奴 - nô) → chiếc nỏ 弩 — \"nỏ\" trong tiếng Việt cũng phát âm gần giống Hán-Việt, dễ nhớ. | Gương Hán-Việt | \"nỏ\" chính là từ tiếng Việt chỉ loại cung có cò — Hán-Việt và thuần Việt trùng âm | Mở khoá kiến thức | Biết 弩 mở khoá: 弩弓 (nỏ/cung nỏ), 强弩之末 (thành ngữ: mũi tên tận sức — hết sức mạnh).", "Tự nguyên_Xie": "Chữ hình thanh. 弓 (cung) biểu nghĩa chỉ cung tên — loại vũ khí; 奴 (nô) cho âm đọc nǔ. 弩 chỉ nỏ — loại vũ khí có cơ chế cò súng, bắn ra mũi tên khi căng dây. Khác với cung (弓) là nỏ dùng cơ chế tích năng và kích hoạt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nỏ", "Hạng Tần Suất (Jun Da)": "3464.0", "Tần Suất % (Jun Da)": "99.5261798646", "GavinGrover_Once (Chiết tự trực tiếp)": "奴 + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱奴弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弓", "Unihan_Simplified (Chữ Giản thể)": "弩", "Unihan_Traditional (Chữ Phồn thể)": "弩", "Pinyin_Xie": "nǔ", "Âm Hán Việt_Xie": "nỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ vũ khí bắn tên, thường kết hợp với lượng từ chỉ cái hoặc chiếc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捻', '{"9000": "3465.0", "Chữ Trung Quốc": "捻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | ⺘ | biểu nghĩa | tay (bộ thủ biến thể) | 念 | niệm | biểu âm | phiên âm cho niǎn | 捻 là chữ hình thanh: ⺘ (bộ thủ biến thể, biểu nghĩa: tay) + 念 (Niệm, biểu âm). Chữ chỉ hành động dùng ngón tay xoay vặn/nhào nặn — như se sợi chỉ hoặc vo tròn đất sét.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạm\": ngón tay (⺘ - thủ) niệm (念) — nhẩm tính trong khi xoay vặn hạt chuỗi, như tay se 捻 hạt chuỗi khi niệm Phật. | Gương Hán-Việt | \"nạm\" ít gặp đơn lẻ; 捻 dùng trong văn bản kỹ thuật và thơ ca | Mở khoá kiến thức | Biết 捻 mở khoá: 捻线 (se sợi chỉ), 捻转 (xoay/vặn), 捻灭 (dùng ngón tay dập tắt), 捻军 (quân Niệm — phong trào nổi dậy cuối Thanh).", "Tự nguyên_Xie": "Chữ hình thanh. ⺘ (bộ thủ) biểu nghĩa chỉ tay — hành động khéo léo của ngón tay; 念 (niệm) cho âm đọc niǎn. Nghĩa gốc: dùng ngón tay xoay vặn, nhào nặn, se sợi. Nguồn tham khảo: Digital Shinjigen 2017. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắn; rút lấy", "Hạng Tần Suất (Jun Da)": "3465.0", "Tần Suất % (Jun Da)": "99.5267307576", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 念", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌念", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "念", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捻", "Unihan_Traditional (Chữ Phồn thể)": "捻", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niệm, nẫm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ động tác vê, nhéo hoặc xoắn bằng đầu ngón tay. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圃', '{"9000": "3466.0", "Chữ Trung Quốc": "圃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 10 | nét | 囗 | biểu nghĩa | vùng đất rào, khu vực | 甫 | phủ | biểu âm | phiên âm cho pǔ | 圃 là chữ hình thanh: 囗 (biểu nghĩa: khu đất rào/vùng), + 甫 (Phủ, biểu âm). Chữ chỉ vườn rau — mảnh đất có rào trồng rau quả.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổ\": khu đất rào (囗) quanh vườn rau 圃 — \"bổ\" gần âm với pǔ, vườn rau bổ dưỡng cho sức khoẻ. | Gương Hán-Việt | \"bổ\" trong \"điền bổ\" (ruộng vườn), \"viên bổ\" (vườn rau) — dùng trong văn cổ | Mở khoá kiến thức | Biết 圃 mở khoá: 菜圃 (vườn rau), 花圃 (vườn hoa), 苗圃 (vườn ươm cây).", "Tự nguyên_Xie": "Chữ hình thanh. 囗 biểu nghĩa chỉ khu đất có ranh giới/rào; 甫 (phủ) cho âm đọc pǔ. 圃 chỉ vườn rau, nơi trồng trọt có rào xung quanh. Cấu trúc trực quan: đất rào (囗) + âm phủ (甫). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vườn trồng rau", "Hạng Tần Suất (Jun Da)": "3466.0", "Tần Suất % (Jun Da)": "99.5272816506", "GavinGrover_Once (Chiết tự trực tiếp)": "囗 + 甫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴囗甫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "囗", "Unihan_Simplified (Chữ Giản thể)": "圃", "Unihan_Traditional (Chữ Phồn thể)": "圃", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ khu vườn, thường kết hợp với các từ chỉ loại cây trồng như hoa, rau. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孚', '{"9000": "3467.0", "Chữ Trung Quốc": "孚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 7 | nét | 爪 | trảo | biểu nghĩa | tay, móng vuốt | 子 | tử | biểu nghĩa | con, đứa trẻ | 孚 là chữ hội ý: 爪 (Trảo, tay/móng vuốt) ở trên + 子 (Tử, đứa trẻ) ở dưới — hình ảnh tay bế/ấp con. Nghĩa gốc là bắt giữ/tóm lấy đứa trẻ, sau phát triển thành \"được tin tưởng\" và \"ấp trứng\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phu\": tay (爪 - trảo) ôm con (子 - tử) — người cha/mẹ ôm ấp con cái, xây dựng sự tin tưởng 孚. | Gương Hán-Việt | \"phu\" ít dùng đơn lẻ; 孚 gặp trong văn ngữ cổ và thành ngữ chỉ tín nghĩa | Mở khoá kiến thức | Biết 孚 mở khoá: 信孚 (uy tín, tín nhiệm), 孚众望 (được lòng tin của quần chúng), 孚望 (được tín nhiệm).", "Tự nguyên_Xie": "Chữ hội ý. 爪 (trảo) biểu nghĩa: tay cầm/vuốt; 子 (tử): đứa trẻ. Hình ảnh gốc: tay bắt/ôm đứa trẻ — tức bắt tù/chiếm giữ. 孚 là dạng gốc của 俘 (bắt tù binh). Từ nghĩa \"nắm giữ\" mở rộng sang \"tin tưởng\" (nắm chặt lòng người) và \"ấp trứng\" (tay ủ ấm trứng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1209.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trảo (087) Tử (039)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trảo (số 087 - móng vuốt/ 爫) ở trên bộ Tử (số 039 - đứa trẻ, con non). Hình ảnh gà mẹ dùng móng vuốt ấp ủ những quả trứng (Tử) nở thành con. Giải thích sự chuyển ý: Đây là chữ Hội ý. Phu là con chim non, ấp trứng cho nở. Sự sinh nở rất đúng kỳ hạn nên phu mang ý chỉ sự thành tín (tín phu).", "Nghĩa Tiếng Việt_Xie": "ti; (xem: phu giáp 孚甲)", "Hạng Tần Suất (Jun Da)": "3467.0", "Tần Suất % (Jun Da)": "99.5278325435", "GavinGrover_Once (Chiết tự trực tiếp)": "爫 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱爫子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "子", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "爫", "Unihan_Simplified (Chữ Giản thể)": "孚", "Unihan_Traditional (Chữ Phồn thể)": "孚", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng trong văn ngôn làm động từ mang nghĩa làm cho tin phục hoặc danh từ chỉ lòng tin. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悴', '{"9000": "3468.0", "Chữ Trung Quốc": "悴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | biểu nghĩa | tâm (bộ tim biến thể), cảm xúc tâm lý | 卒 | tốt | biểu âm | phiên âm cho cuì, lính tốt | 悴 là chữ hình thanh: 忄 (biểu nghĩa: tâm/nội tâm) + 卒 (Tốt, biểu âm). Chữ chỉ trạng thái tiều tụy, kiệt sức — thân tâm đều cạn kiệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xót\": lòng (忄 - tâm) xót xa (tốt - 卒) đến kiệt sức — 悴 là dáng vẻ tiều tụy do đau khổ hoặc bệnh tật. | Gương Hán-Việt | \"xót\" gợi cảm giác đau xót trong lòng; 悴 thường đi với 憔悴 (tiều tụy, hao gầy) | Mở khoá kiến thức | Biết 悴 mở khoá: 憔悴 (tiều tụy, hốc hác), 憔悴不堪 (tiều tụy không chịu nổi).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 悴. Theo phân tích hình thể: 忄 (tâm) biểu nghĩa chỉ trạng thái nội tâm/cơ thể; phần còn lại cho âm đọc cuì. 悴 chỉ trạng thái tiều tụy, hao gầy, kiệt sức cả thân lẫn tâm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bất ngờ", "Hạng Tần Suất (Jun Da)": "3468.0", "Tần Suất % (Jun Da)": "99.5283824029", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悴", "Unihan_Traditional (Chữ Phồn thể)": "悴", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả vẻ mặt tiều tụy, héo úa hoặc tâm trạng lo buồn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诣', '{"9000": "3469.0", "Chữ Trung Quốc": "诣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | ngôn | biểu nghĩa | lời nói, biểu đạt (bộ ngôn biến thể) | 旨 | chỉ | biểu âm | ý chỉ, mục đích | 诣 là giản thể của 詣, chữ hình thanh: 讠 (Ngôn biến thể, biểu nghĩa) + 旨 (Chỉ, biểu âm). Nghĩa gốc: đến gặp bậc tôn trưởng để trình bày. Nghĩa phái sinh: trình độ học vấn đạt được.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghệ\": bộ 讠 (ngôn) + 旨 (chỉ: ý chỉ/biểu âm) — đến (诣) gặp thầy trình bày theo ý chỉ, tức đạt trình độ nghề. | Gương Hán-Việt | \"nghệ\" trong 造诣 (tạo nghệ: thành tựu, trình độ đạt được); dùng trong văn học, học thuật | Mở khoá kiến thức | Biết 诣 mở khoá: 造诣 (trình độ/thành tựu học thuật), 诣阙 (vào cung bệ kiến), 深诣 (trình độ sâu sắc).", "Tự nguyên_Xie": "诣 là giản thể của 詣 (Wiktionary: {{Han simp|詣|f=言|t=讠}}). 言/讠 (ngôn) biểu nghĩa; 旨 (chỉ) cho âm yì. Nghĩa gốc: đến chỗ người tôn quý để trình bày. Từ đó mở rộng thành \"trình độ đạt được\" — như học giả đã \"đến được\" một cảnh giới cao. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đến tận nơi", "Hạng Tần Suất (Jun Da)": "3469.0", "Tần Suất % (Jun Da)": "99.5289317455", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 旨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠旨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诣", "Unihan_Traditional (Chữ Phồn thể)": "詣", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "nghệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ việc đi đến nơi nào đó hoặc danh từ chỉ trình độ học vấn, nghệ thuật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呱', '{"9000": "3470.0", "Chữ Trung Quốc": "呱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 瓜 | qua | biểu âm | phiên âm cho gū/guā | 呱 là chữ hình thanh tượng thanh: 口 (Khẩu, biểu nghĩa: miệng) + 瓜 (Qua, biểu âm). Chữ mô tả tiếng khóc của trẻ sơ sinh (呱呱坠地) hoặc tiếng kêu của ếch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": miệng (口 - khẩu) bật ra tiếng \"呱呱\" khi trẻ chào đời — \"oa oa\" chính là âm tượng thanh cho tiếng khóc em bé. | Gương Hán-Việt | \"oa\" trong \"oa oa\" (tiếng khóc trẻ sơ sinh), liên hệ với 蛙 (oa = ếch) | Mở khoá kiến thức | Biết 呱 mở khoá: 呱呱坠地 (tiếng khóc chào đời — đứa trẻ ra đời), 呱呱叫 (tuyệt vời, xuất sắc — tiếng lóng).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 呱. Theo phân tích: 口 (khẩu) biểu nghĩa chỉ miệng/âm thanh; 瓜 (qua) cho âm đọc. 呱 là từ tượng thanh chỉ tiếng khóc của trẻ sơ sinh (呱呱 = tiếng khóc đầu đời) hoặc tiếng ếch kêu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng trẻ khóc", "Hạng Tần Suất (Jun Da)": "3470.0", "Tần Suất % (Jun Da)": "99.5294810881", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瓜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呱", "Unihan_Traditional (Chữ Phồn thể)": "呱", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô, oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường làm từ tượng thanh mô tả tiếng khóc oa oa của trẻ nhỏ hoặc tiếng kêu của động vật. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祁', '{"9000": "3471.0", "Chữ Trung Quốc": "祁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 6 | nét | 示 | thị | biểu âm | phiên âm cho qí | 邑 | ấp | biểu nghĩa | làng/ấp/địa danh | 祁 là chữ hình thanh: 邑 (Ấp, biểu nghĩa: địa danh/làng) + 示 (Thị, biểu âm). Chữ vừa là họ người, vừa chỉ địa danh (huyện Kỳ — Qi), và mang nghĩa to lớn, hưng thịnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": đất ấp (邑 - ấp) thờ (示 - thị) thần — địa danh 祁 lớn mạnh và hưng thịnh như \"kỳ quan\". | Gương Hán-Việt | \"kỳ\" phổ biến trong tiếng Việt: 祁连山 (Kỳ Liên Sơn), 祁门红茶 (trà đen Kỳ Môn) | Mở khoá kiến thức | Biết 祁 mở khoá: 祁连山 (núi Kỳ Liên), 祁门红茶 (trà đỏ Kỳ Môn nổi tiếng), 祁县 (huyện Kỳ, Sơn Tây).", "Tự nguyên_Xie": "Chữ hình thanh. 邑 (ấp) biểu nghĩa chỉ địa danh; 示 (thị) cho âm đọc qí. 祁 nguyên là tên địa phương (huyện Kỳ ở Sơn Tây), sau phát triển thành họ người và có nghĩa \"to lớn, hưng thịnh\". Cũng gặp trong văn cổ với nghĩa thoang thoảng (mùi thơm). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kỳ Môn (tên huyện ở tỉnh An Huy, Trung Quốc); Kỳ Dương (ở tỉnh Hồ Nam, Trung Quốc); họ Kì", "Hạng Tần Suất (Jun Da)": "3471.0", "Tần Suất % (Jun Da)": "99.5300299139", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祁", "Unihan_Traditional (Chữ Phồn thể)": "祁", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng làm tính từ chỉ sự to lớn, đông đúc hoặc làm danh từ riêng chỉ họ người, địa danh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捶', '{"9000": "3472.0", "Chữ Trung Quốc": "捶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 手 | thủ | biểu nghĩa | tay | 垂 | thuỳ | biểu âm | phiên âm cho chuí | 捶 là chữ hình thanh: 手 (Thủ, biểu nghĩa: tay) + 垂 (Thuỳ, biểu âm). Chữ chỉ hành động đập/đánh xuống bằng tay nắm hoặc vật cứng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuỳ\": tay (手 - thủ) nắm đấm xuống thùm thụp — 捶 như tiếng thuỳ thuỳ của đòn đấm vào lưng. | Gương Hán-Việt | \"thuỳ\" ít dùng đơn lẻ; 捶 gặp trong văn mô tả hành động vật lý, thể dục | Mở khoá kiến thức | Biết 捶 mở khoá: 捶背 (đấm lưng), 捶打 (đập, đánh), 捶胸顿足 (đấm ngực giậm chân — thành ngữ: đau khổ tột độ).", "Tự nguyên_Xie": "Chữ hình thanh. 手 (thủ) biểu nghĩa chỉ tay — hành động đập bằng tay; 垂 (thuỳ) cho âm đọc chuí. 捶 chỉ hành động đập, đánh thùm thụp — như đấm lưng cho giãn cơ hoặc đập vải. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đấm; đập; nện; đánh; dọng", "Hạng Tần Suất (Jun Da)": "3472.0", "Tần Suất % (Jun Da)": "99.5305782229", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 垂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌垂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捶", "Unihan_Traditional (Chữ Phồn thể)": "捶", "Pinyin_Xie": "chuí", "Âm Hán Việt_Xie": "chuỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động đấm, nện hoặc gõ bằng tay hay dụng cụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chuí | / | đập | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钠', '{"9000": "3473.0", "Chữ Trung Quốc": "钠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 金 | kim | biểu nghĩa | kim loại | 內 | biểu âm | phiên âm cho nà | 钠 là chữ hình thanh tạo muộn (chữ hóa học hiện đại): 金 (Kim, biểu nghĩa: kim loại) + 內 (biểu âm). Chữ được tạo ra để phiên âm tên nguyên tố Natrium/Sodium trong hóa học hiện đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạp\": kim loại (金 - kim) nạp (nà - 内) vào cơ thể — muối ăn (NaCl) chứa natri cần nạp hằng ngày. | Gương Hán-Việt | \"nạp\" ít dùng cho natri; trong tiếng Việt khoa học gọi là \"natri\" hoặc \"sodium\" | Mở khoá kiến thức | Biết 钠 mở khoá: 钠盐 (muối natri), 氯化钠 (NaCl - muối ăn), 碳酸钠 (Na₂CO₃ - soda), 氢氧化钠 (NaOH - xút).", "Tự nguyên_Xie": "Chữ hình thanh tạo muộn trong hóa học cận đại Trung Quốc. 金 (kim) biểu nghĩa chỉ kim loại — natri là kim loại kiềm; 內 cho âm đọc nà phiên âm từ \"Na\" (ký hiệu hóa học). Đây là chữ được tạo riêng để dịch tên nguyên tố hóa học từ tiếng La-tinh Natrium. Chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố natri, Na", "Hạng Tần Suất (Jun Da)": "3473.0", "Tần Suất % (Jun Da)": "99.531126532", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钠", "Unihan_Traditional (Chữ Phồn thể)": "鈉", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nguyên tố hóa học natri, thường đứng độc lập hoặc trong thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袄', '{"9000": "3474.0", "Chữ Trung Quốc": "袄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衣 | y | biểu nghĩa | quần áo | 夭 | yêu | biểu âm | phiên âm cho ǎo | 袄 là chữ hình thanh: 衣/衤 (Y, biểu nghĩa: quần áo) + phần biểu âm. Chữ chỉ áo bông, áo có lót bông — loại áo ấm truyền thống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"áo\": bộ 衣 (y - quần áo) + âm \"áo\" — 袄 chính là chiếc áo (Hán-Việt trùng khớp với tiếng Việt \"áo\"). | Gương Hán-Việt | \"áo\" chính là từ tiếng Việt thông dụng nhất — Hán-Việt 袄 = \"áo\" trùng hoàn toàn với tiếng Việt thuần | Mở khoá kiến thức | Biết 袄 mở khoá: 棉袄 (áo bông), 皮袄 (áo da lông), 小袄 (áo ngắn lót bông).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 袄 (dạng giản thể). Wiktionary ghi nhận đây là biến thể của 襖 (phồn thể). 衣/衤 (y) biểu nghĩa chỉ quần áo; phần còn lại cho âm đọc ǎo. Chữ chỉ áo bông có lót — áo ấm truyền thống Trung Hoa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo ngắn, áo bông", "Hạng Tần Suất (Jun Da)": "3474.0", "Tần Suất % (Jun Da)": "99.5316727738", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 夭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤夭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袄", "Unihan_Traditional (Chữ Phồn thể)": "襖", "Pinyin_Xie": "ǎo", "Âm Hán Việt_Xie": "áo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại áo khoác ngắn hoặc áo bông ấm mặc trong mùa đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('澎', '{"9000": "3475.0", "Chữ Trung Quốc": "澎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 氵 | thủy | biểu nghĩa | nước | 彭 | bành | biểu âm | phiên âm cho pēng | 澎 là chữ hình thanh: 氵 (Thủy, biểu nghĩa: nước) + 彭 (Bành, biểu âm). Chữ mô tả tiếng sóng vỗ ầm ầm hoặc nước chảy mạnh — thường đi với 湃 thành 澎湃.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bành\": nước (氵 - thủy) ầm ầm (彭 - bành) như sóng vỗ — 澎湃 là cảm xúc dâng trào như sóng biển. | Gương Hán-Việt | \"bành\" ít dùng đơn lẻ; 澎 gặp trong địa danh 澎湖 (Bành Hồ) và từ ghép 澎湃 | Mở khoá kiến thức | Biết 澎 mở khoá: 澎湃 (sóng dâng trào, cảm xúc mãnh liệt), 澎湖 (quần đảo Bành Hồ, Đài Loan).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 澎. Theo phân tích: 氵 (thủy) biểu nghĩa chỉ nước; 彭 (bành) cho âm đọc pēng đồng thời gợi âm thanh lớn. 澎 chỉ tiếng sóng biển ầm ầm, nước chảy mạnh. Thường thấy trong 澎湃 (sóng dâng trào) và 澎湖 (đảo Bành Hồ của Đài Loan). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước mênh mông", "Hạng Tần Suất (Jun Da)": "3475.0", "Tần Suất % (Jun Da)": "99.5322184989", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 彭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵彭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "澎", "Unihan_Traditional (Chữ Phồn thể)": "澎", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "bành", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả sóng nước cuồn cuộn hoặc động từ chỉ nước vỗ mạnh trong từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氮', '{"9000": "3476.0", "Chữ Trung Quốc": "氮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 12 | nét | 气 | khí | biểu nghĩa | khí, chất khí | 淡 | đạm | biểu âm | nhạt, loãng | 氮 là chữ hình thanh tạo muộn (hóa học hiện đại): 气 (Khí, biểu nghĩa: chất khí) + 淡 (Đạm, biểu âm: nhạt/loãng — rút gọn). Chữ được tạo ra để dịch tên nguyên tố Nitrogen.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạm\": khí (气 - khí) đạm (淡 - đạm) — nitơ là \"đạm khí\" vì nhạt nhẽo (đạm), chiếm đầy không khí mà không thấy không ngửi. | Gương Hán-Việt | \"đạm\" trong \"đạm khí\" (nitơ), \"đạm bạc\" (nhạt nhẽo); hóa học Việt gọi là \"nitơ\" | Mở khoá kiến thức | Biết 氮 mở khoá: 氮气 (khí nitơ), 氮肥 (phân đạm), 液氮 (nitơ lỏng), 氮化物 (nitrit).", "Tự nguyên_Xie": "Chữ hình thanh tạo muộn trong hóa học cận đại Trung Quốc. 气 (khí) biểu nghĩa chỉ chất khí; 淡 (đạm, rút gọn) cho âm đọc dàn. Tên \"đạm khí\" (氮气) phản ánh đặc tính của nitơ: chiếm 78% khí quyển nhưng không màu, không mùi, tương đối \"nhạt\" (đạm). Ký hiệu hóa học: N. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất đạm, khí đạm, nitơ, nitrogen", "Hạng Tần Suất (Jun Da)": "3476.0", "Tần Suất % (Jun Da)": "99.5327637073", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 炎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气炎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "炎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氮", "Unihan_Traditional (Chữ Phồn thể)": "氮", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ trong các thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恪', '{"9000": "3477.0", "Chữ Trung Quốc": "恪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 忄 | biểu nghĩa | tâm (bộ tim), thái độ nội tâm | 各 | cac | biểu âm | phiên âm cho kè | 恪 là chữ hình thanh: 忄 (biểu nghĩa: tâm — thái độ tâm lý) + 各 (Cac, biểu âm). Chữ chỉ thái độ cẩn thận, tôn trọng và tuân thủ nghiêm túc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khác\": lòng (忄 - tâm) giữ đúng từng điều (各 - cac: mỗi) — 恪 là cẩn thận giữ đúng bổn phận, khác xa với lơ là. | Gương Hán-Việt | \"khác\" ít dùng với nghĩa này; 恪 gặp trong văn ngữ chính thức, chỉ thái độ nghiêm túc | Mở khoá kiến thức | Biết 恪 mở khoá: 恪守 (tuân thủ nghiêm túc), 恪尽职守 (tận tụy với bổn phận), 恪遵 (nghiêm chỉnh tuân theo).", "Tự nguyên_Xie": "Chữ hình thanh. 忄 (tâm) biểu nghĩa chỉ thái độ nội tâm — lòng kính cẩn; 各 (cac) cho âm đọc kè. 恪 chỉ sự nghiêm cẩn, tuân thủ đúng mực — đặc biệt trong việc giữ gìn bổn phận, đạo nghĩa. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kính cẩn", "Hạng Tần Suất (Jun Da)": "3477.0", "Tần Suất % (Jun Da)": "99.5333089156", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恪", "Unihan_Traditional (Chữ Phồn thể)": "恪", "Pinyin_Xie": "kè", "Âm Hán Việt_Xie": "khác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ thể hiện sự kính cẩn hoặc động từ tuân thủ trong các từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雏', '{"9000": "3478.0", "Chữ Trung Quốc": "雏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 隹 | Số nét | 13 | nét | 刍 | sô | biểu âm | phiên âm cho chú | 鸟 | điểu | biểu nghĩa | chim | 雏 là giản thể của 雛, chữ hình thanh: 鸟 (Điểu, biểu nghĩa: chim) + 刍 (Sô, biểu âm thay thế cho 芻 trong phồn thể). Chữ chỉ chim non, gà con chưa có đủ lông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sồ\": chim (鸟 - điểu) còn non 雏 như gà con sồ — bộ 鸟 + biểu âm 刍 (sô), chim non lông tơ chưa cứng cáp. | Gương Hán-Việt | \"sồ\" ít dùng đơn lẻ; gặp trong \"gà sồ\" (gà con) trong tiếng Việt dân gian | Mở khoá kiến thức | Biết 雏 mở khoá: 雏鸟 (chim non), 雏鸡 (gà con), 雏形 (hình dạng ban đầu/phôi thai), 雏儿 (non nớt).", "Tự nguyên_Xie": "雏 là giản thể của 雛 (Wiktionary: {{Han simp|雛|f=芻|t=刍}}). Trong phồn thể: 鳥 (điểu) biểu nghĩa chỉ chim; 芻 (sô) cho âm đọc chú. 雛/雏 chỉ chim non còn tơ/gà con mới nở. Mở rộng nghĩa thành \"non nớt, mới bắt đầu\". | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con chim non", "Hạng Tần Suất (Jun Da)": "3478.0", "Tần Suất % (Jun Da)": "99.5338525735", "GavinGrover_Once (Chiết tự trực tiếp)": "刍 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰刍隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "隹", "Unihan_Simplified (Chữ Giản thể)": "雏", "Unihan_Traditional (Chữ Phồn thể)": "雛", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ chim non hoặc làm định ngữ để chỉ trạng thái non nớt, mới sinh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撮', '{"9000": "3479.0", "Chữ Trung Quốc": "撮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | biểu nghĩa | tay (bộ thủ biến thể) | 最 | tối | biểu âm | phiên âm cho cuō | 撮 là chữ hình thanh: 扌 (biểu nghĩa: tay) + 最 (Tối, biểu âm). Chữ chỉ hành động nhặt/túm bằng đầu ngón tay, đồng thời là lượng từ chỉ một nhúm nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toát\": tay (扌 - thủ) toát ra (tối - 最) — nhúm một chút bằng đầu ngón tay, 撮 là hành động túm nhặt nhanh. | Gương Hán-Việt | \"toát\" ít dùng đơn lẻ; 撮 gặp trong văn học và ngôn ngữ thông thường như lượng từ | Mở khoá kiến thức | Biết 撮 mở khoá: 撮合 (mai mối/sắp xếp), 一撮盐 (một nhúm muối), 一小撮 (một nhóm nhỏ — khinh thường).", "Tự nguyên_Xie": "Chữ hình thanh. 扌 (thủ) biểu nghĩa chỉ tay — hành động ngón tay nhặt/túm; 最 (tối) cho âm đọc cuō. Nghĩa gốc: nhặt lên bằng ngón tay. Mở rộng thành lượng từ chỉ \"một nhúm\" (撮 = một nhúm muối, một nhúm bụi). Cũng dùng ẩn dụ chỉ nhóm nhỏ người (thường mang nghĩa khinh thường: \"một lũ\"). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dúm (đơn vị đo, bằng 256 hạt thóc); rút lại; tụ họp", "Hạng Tần Suất (Jun Da)": "3479.0", "Tần Suất % (Jun Da)": "99.5343946811", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 最", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌最", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "最", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撮", "Unihan_Traditional (Chữ Phồn thể)": "撮", "Pinyin_Xie": "cuō", "Âm Hán Việt_Xie": "toát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Lượng từ | 量词 | Thường làm động từ chỉ hành động thu gom hoặc làm lượng từ cho một nhúm vật chất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('堰', '{"9000": "3480.0", "Chữ Trung Quốc": "堰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 12 | nét | 土 | thổ | biểu nghĩa | đất | 匽 | biểu âm | phiên âm cho yàn | 堰 là chữ hình thanh: 土 (Thổ, biểu nghĩa: đất) + 匽 (biểu âm). Chữ chỉ đập nước, đê đập nhỏ hoặc đập tràn — công trình bằng đất ngăn/điều tiết nước.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yển\": đập đất (土 - thổ) 堰 ngăn nước — \"yển\" gợi âm trong 都江堰 (Đô Giang Yển) nổi tiếng. | Gương Hán-Việt | \"yển\" trong \"đê yển\" (đập nhỏ); đặc biệt 都江堰 là công trình thủy lợi cổ đại UNESCO | Mở khoá kiến thức | Biết 堰 mở khoá: 都江堰 (Đô Giang Yển), 堰塞湖 (hồ do lở đất chặn), 拦水堰 (đập tràn).", "Tự nguyên_Xie": "Chữ hình thanh. 土 (thổ) biểu nghĩa chỉ đất — vật liệu xây đập; 匽 cho âm đọc yàn. 堰 chỉ đập tràn nhỏ, đê đập điều tiết nước. Nổi tiếng nhất là 都江堰 (Đô Giang Yển) — công trình thủy lợi cổ đại của Lý Băng (256 TCN) tại Tứ Xuyên, vẫn hoạt động đến ngày nay. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đập đất", "Hạng Tần Suất (Jun Da)": "3480.0", "Tần Suất % (Jun Da)": "99.5349367888", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 匽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土匽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "匽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "堰", "Unihan_Traditional (Chữ Phồn thể)": "堰", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ công trình đập nước hoặc đê ngăn lũ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹦', '{"9000": "3481.0", "Chữ Trung Quốc": "鹦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 16 | nét | 嬰 | anh | biểu âm | phiên âm cho yīng | 鳥 | điểu | biểu nghĩa | chim | 鹦 là chữ hình thanh: 鳥 (Điểu, biểu nghĩa: chim) + 嬰 (Anh, biểu âm: trẻ sơ sinh). Chữ chỉ vẹt — loài chim biết bắt chước tiếng người, giống như trẻ sơ sinh học nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"anh\": chim (鳥 - điểu) học tiếng như em bé (嬰 - anh) — con vẹt 鹦 bắt chước tiếng người như trẻ sơ sinh học nói. | Gương Hán-Việt | \"anh\" trong \"anh vũ\" (鹦鹉 - con vẹt) — cách gọi tao nhã trong thơ văn Việt | Mở khoá kiến thức | Biết 鹦 mở khoá: 鹦鹉 (con vẹt), 鹦鹉学舌 (thành ngữ: vẹt học nói — nhắc lại không suy nghĩ).", "Tự nguyên_Xie": "Chữ hình thanh. 鳥 (điểu) biểu nghĩa chỉ chim; 嬰 (anh) cho âm đọc yīng. Vẹt (鹦鹉) là loài chim nổi tiếng vì bắt chước tiếng người — liên tưởng với 嬰 (trẻ sơ sinh) học nói là hình ảnh ghi nhớ thú vị dù không phải tự nguyên học thuật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: anh vũ 鸚鵡,鹦鹉)", "Hạng Tần Suất (Jun Da)": "3481.0", "Tần Suất % (Jun Da)": "99.536021004", "GavinGrover_Once (Chiết tự trực tiếp)": "婴 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰婴鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "婴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹦", "Unihan_Traditional (Chữ Phồn thể)": "鸚", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "anh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ và hầu như luôn kết hợp với chữ khác để chỉ loài chim vẹt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晖', '{"9000": "3482.0", "Chữ Trung Quốc": "晖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời | 军 | quân | biểu âm | phiên âm (thay thế 軍 trong phồn thể) | 晖 là giản thể của 暉, chữ hình thanh: 日 (Nhật, biểu nghĩa: mặt trời) + 军 (Quân, biểu âm — thay thế 軍 trong phồn thể 暉). Chữ chỉ ánh sáng mặt trời, ánh huy hoàng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huy\": mặt trời (日 - nhật) tỏa huy hoàng 晖 — \"huy hoàng\" trong tiếng Việt chứa âm \"huy\" của 晖. | Gương Hán-Việt | \"huy\" trong \"huy hoàng\" (rực rỡ, huy hoàng), \"nhật huy\" (ánh sáng mặt trời) | Mở khoá kiến thức | Biết 晖 mở khoá: 朝晖 (ánh sáng ban mai), 春晖 (ánh xuân — ơn cha mẹ), 晖映 (ánh sáng chiếu rọi).", "Tự nguyên_Xie": "晖 là giản thể của 暉 (Wiktionary: {{Han simp|暉|f=軍|t=军}}). Trong phồn thể: 日 (nhật) biểu nghĩa chỉ mặt trời; 軍 (quân) cho âm đọc huī. 暉/晖 chỉ ánh sáng mặt trời, ánh hào quang. Thường dùng trong tên riêng và văn thơ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bóng (tà huy: bóng chiều)", "Hạng Tần Suất (Jun Da)": "3482.0", "Tần Suất % (Jun Da)": "99.5365615612", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 军", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日军", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "军", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晖", "Unihan_Traditional (Chữ Phồn thể)": "暉", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "huy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ánh sáng mặt trời, đặc biệt là ánh nắng chiều tà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犀', '{"9000": "3483.0", "Chữ Trung Quốc": "犀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 12 | nét | 尾 | vĩ | biểu âm | phiên âm cho xī | 牛 | ngưu | biểu nghĩa | trâu/bò — động vật lớn | 犀 là chữ hình thanh: 牛 (Ngưu, biểu nghĩa: trâu/bò — chỉ loài thú lớn) + 尾 (Vĩ, biểu âm). Chữ chỉ con tê giác — loài thú lớn như trâu nhưng có sừng đặc biệt trên mũi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tê\": con trâu (牛 - ngưu) có đuôi (尾 - vĩ) dài và cái sừng 犀 — tê giác (tê = tê liệt/cứng như sừng tê). | Gương Hán-Việt | \"tê\" trong \"tê giác\" (con tê giác), \"tê tê\" (tê liệt) — âm Hán-Việt phổ biến trong tiếng Việt | Mở khoá kiến thức | Biết 犀 mở khoá: 犀牛 (tê giác), 犀角 (sừng tê giác), 犀利 (sắc bén, tinh tường).", "Tự nguyên_Xie": "Chữ hình thanh. 牛 (ngưu) biểu nghĩa chỉ trâu/bò — loài thú lớn; 尾 (vĩ) cho âm đọc. 犀 chỉ tê giác — loài thú lớn đặc biệt với sừng trên mũi. Sừng tê giác (犀角) từng được coi là linh dược trong y học cổ truyền, nay cấm buôn bán. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con tê giác", "Hạng Tần Suất (Jun Da)": "3483.0", "Tần Suất % (Jun Da)": "99.5371010849", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 牛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴牛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "犀", "Unihan_Traditional (Chữ Phồn thể)": "犀", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ loài tê giác hoặc làm tính từ miêu tả sự sắc bén của tư duy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腑', '{"9000": "3484.0", "Chữ Trung Quốc": "腑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 月 | nguyệt | biểu nghĩa | thịt/cơ thể (bộ nhục biến thể) | 府 | phủ | biểu âm | phiên âm cho fǔ; kho tàng | 腑 là chữ hình thanh: 月/肉 (Nhục biến thể, biểu nghĩa: thịt/cơ thể) + 府 (Phủ, biểu âm). Chữ chỉ lục phủ — sáu cơ quan rỗng của cơ thể (胃, 大肠, 小肠, 胆, 膀胱, 三焦) trong y học cổ truyền.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phủ\": cơ thể (月 - nhục) là phủ (府 - phủ) kho chứa — lục phủ 腑 là sáu \"kho\" bên trong cơ thể theo đông y. | Gương Hán-Việt | \"phủ\" trong \"lục phủ\" (sáu phủ tạng), \"tâm phủ\" (tâm can/lòng dạ) — y học cổ truyền | Mở khoá kiến thức | Biết 腑 mở khoá: 五脏六腑 (ngũ tạng lục phủ — toàn bộ nội tạng), 肺腑 (tâm phế — lòng dạ thật sự).", "Tự nguyên_Xie": "Chưa có nguồn Wiktionary đầy đủ cho 腑. Theo phân tích: 月 (nhục/thịt) biểu nghĩa chỉ cơ thể/nội tạng; 府 (phủ) cho âm đọc fǔ đồng thời gợi nghĩa \"kho tàng\" (các cơ quan như kho chứa). 腑 chỉ lục phủ trong y học cổ truyền — đối lập với 脏 (tạng, các cơ quan đặc). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phủ tạng (lục phủ gồm có: 中醫上指胃 trung y thượng chỉ vị; 膽,胆 đảm; 大腸,大肠 đại tràng; 小腸,小肠 tiểu tràng; 膀胱 bàng quang; 三焦 tam tiêu)", "Hạng Tần Suất (Jun Da)": "3484.0", "Tần Suất % (Jun Da)": "99.5376400918", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 府", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月府", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "府", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腑", "Unihan_Traditional (Chữ Phồn thể)": "腑", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các cơ quan nội tạng, hay dùng trong các thành ngữ chỉ tâm can. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沽', '{"9000": "3485.0", "Chữ Trung Quốc": "沽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước; chất lỏng (rượu) | 古 | cổ | biểu âm | phiên âm cho gū | 沽 là chữ hình thanh: 水/氵 (Thủy, biểu nghĩa: nước/chất lỏng — ám chỉ rượu) + 古 (Cổ, biểu âm). Chữ nguyên nghĩa là mua rượu/bán rượu, sau mở rộng thành đánh bóng danh tiếng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cô\": nước/rượu (水 - thủy) xưa cổ (古 - cổ) được mua bán 沽 — câu danh trong 沽名钓誉 như người bán rượu câu khách. | Gương Hán-Việt | \"cô\" ít dùng đơn lẻ với nghĩa mua rượu; 沽 gặp chủ yếu trong thành ngữ 沽名钓誉 | Mở khoá kiến thức | Biết 沽 mở khoá: 沽名钓誉 (câu danh lợi/đánh bóng tên tuổi), 沽酒 (mua rượu), 沽清 (tên địa danh cổ — vùng Thiên Tân).", "Tự nguyên_Xie": "Chữ hình thanh. 水 (thủy) biểu nghĩa chỉ chất lỏng — ám chỉ rượu; 古 (cổ) cho âm đọc gū. 沽 nghĩa gốc là mua/bán rượu. Từ đó phát triển thành nghĩa phái sinh: 沽名钓誉 (dùng hành động giả tạo để câu danh lợi) — như người bán rượu câu khách bằng màn trình diễn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Cô; bán; mua", "Hạng Tần Suất (Jun Da)": "3485.0", "Tần Suất % (Jun Da)": "99.5381790987", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沽", "Unihan_Traditional (Chữ Phồn thể)": "沽", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ việc mua bán rượu hoặc ẩn dụ cho việc mua chuộc danh tiếng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橄', '{"9000": "3486.0", "Chữ Trung Quốc": "橄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 15 | nét | 木 | mộc | biểu nghĩa | cây | 敢 | cảm | biểu âm | 橄 = 木 (Mộc, biểu nghĩa: cây) + 敢 (Cảm, biểu âm); chữ hình thanh. Bộ mộc chỉ loại thực vật, phần 敢 cho âm đọc gần với gǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảm\": tưởng tượng một cây (木) dám (敢) mọc trên đất khô — đó là cây trám 橄欖 với quả đắng mà ngon. | Gương Hán-Việt | Đọc Hán-Việt: cảm. 橄 xuất hiện hầu như chỉ trong 橄欖 (ô-liu, trám); không có từ Hán-Việt độc lập phổ biến. | Mở khoá kiến thức | Biết 橄 mở khoá từ 橄欖 (gǎnlǎn — quả ô-liu, trám xanh) dùng trong ẩm thực và y học cổ truyền.", "Tự nguyên_Xie": "Chữ hình thanh: 木 (cây) biểu nghĩa, 敢 (cảm) biểu âm. Chữ chỉ dùng trong từ 橄欖 (ô-liu / trám). Chưa có nguồn học thuật chi tiết hơn ngoài cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây quả trám", "Hạng Tần Suất (Jun Da)": "3486.0", "Tần Suất % (Jun Da)": "99.5387181056", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 敢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木敢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橄", "Unihan_Traditional (Chữ Phồn thể)": "橄", "Pinyin_Xie": "gǎn", "Âm Hán Việt_Xie": "cảm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ và xuất hiện trong các từ ghép như cảm lãm để chỉ quả trám hoặc cây ô liu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掐', '{"9000": "3487.0", "Chữ Trung Quốc": "掐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 臽 | hãm | biểu âm | (cho âm qiā) | 掐 = 扌(Thủ, biểu nghĩa: tay) + 臽 (Hãm, biểu âm); chữ hình thanh, hoặc có thể là hội ý (tay + hố = cấu vào). Theo Wiktionary, có thể đọc là cả psc lẫn ic.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kháp\": tay (扌) kháp chặt vào — kháp cấu, dùng móng tay cấu bóp mạnh. | Gương Hán-Việt | \"kháp\" ít dùng độc lập; 掐 dùng trong 掐指一算 (tính trên đầu ngón tay), 掐死 (bóp cổ chết) | Mở khoá kiến thức | Biết 掐 mở khoá 掐指一算 (đếm tính trên đầu ngón), 掐住 (bóp chặt, kẹp chặt), 掐断 (ngắt đứt).", "Tự nguyên_Xie": "掐 là chữ hình thanh (hoặc có yếu tố hội ý): bộ 手 (rút thành 扌 — thủ) biểu nghĩa; 臽 (hãm) cho âm qiā. Wiktionary ghi: có thể giải thích thay thế là hội ý — tay (手) + hố (臽) = cấu/kẹp vào. Nghĩa là cấu bằng móng tay, bóp cổ, ngắt (hoa), tắt (thuốc lá). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy móng tay bấm để hái hoa", "Hạng Tần Suất (Jun Da)": "3487.0", "Tần Suất % (Jun Da)": "99.5392565957", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掐", "Unihan_Traditional (Chữ Phồn thể)": "掐", "Pinyin_Xie": "qiā", "Âm Hán Việt_Xie": "kháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động dùng ngón tay bấm hoặc ngắt, thường mang tân ngữ phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qiā | / | cấu | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亵', '{"9000": "3488.0", "Chữ Trung Quốc": "亵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 亠 | Số nét | 12 | nét | 亵 | tiết | tượng hình | chữ giản thể của 褻 — áo lót, khinh nhờn, dâm ô | 亵 là giản thể của 褻. Dạng phồn thể 褻 gồm 衣 (y, áo) và 執 (chấp, cầm giữ), hàm ý mặc áo lót sát người → thân mật quá mức → khinh nhờn. Chữ giản thể không giữ lại cấu trúc đó nên xem như một đơn vị độc lập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": mặc áo lót (衣) mà bị nắm (執) — bị kẻ khác tiếp cận quá thân mật, mất thể diện → khinh tiết, dâm ô. | Gương Hán-Việt | 亵 xuất hiện trong 亵渎 (tiết độc — xúc phạm, báng bổ), 猥亵 (uỷ tiết — dâm ô). | Mở khoá kiến thức | Biết 亵 mở khoá 猥亵 (wěixiè — hành vi dâm ô, quấy rối) và 亵渎 (xièdú — báng bổ, xúc phạm).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 亵 là giản thể của 褻 (xuất hiện từ kim văn và tiểu triện). 褻 cấu tạo từ 衣 (áo) và 埶→執 (cầm): hình ảnh áo lót bó sát thân, nghĩa gốc là áo lót, sau mở rộng sang \"suồng sã, khinh thường, dâm ô\". Chưa có nguồn học thuật bổ sung cho dạng giản thể 亵. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áo lót mình; bẩn thỉu; khinh nhờn; dâm ô, suồng sã", "Hạng Tần Suất (Jun Da)": "3488.0", "Tần Suất % (Jun Da)": "99.5397950858", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 执", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣执", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "执", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "亵", "Unihan_Traditional (Chữ Phồn thể)": "褻", "Pinyin_Xie": "xiè", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ trong các từ ghép chỉ sự bất kính. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龋', '{"9000": "3489.0", "Chữ Trung Quốc": "龋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 17 | nét | 龋 | củ | tượng hình | chữ giản thể của 齲 — sâu răng | 龋 là giản thể của 齲. Dạng phồn thể 齲 gồm 齒 (xỉ, răng) và 禹 (vũ, biểu âm). Chữ giản thể giản lược 齒→齿. Cấu trúc hình thanh: bộ răng (齿) biểu nghĩa, phần còn lại biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"củ\": cái răng (齿) bị sâu củ — hình dung một chiếc răng bị khoét lỗ như củ khoai bị mọt. | Gương Hán-Việt | 龋 xuất hiện trong 龋齿 (củ xỉ — răng sâu), một thuật ngữ y học nha khoa phổ biến. | Mở khoá kiến thức | Biết 龋 mở khoá 龋齿 (qǔchǐ — sâu răng) và các từ nha khoa cơ bản.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | 龋 là giản thể của 齲 (xỉ — răng sâu). Dạng cổ xuất hiện từ giáp cốt văn và tiểu triện. 齲 = 齒 (răng) + 禹 (biểu âm). Nghĩa gốc: răng bị ăn mòn từ trong ra ngoài. Chữ tạo muộn hơn các chữ cơ bản, phản ánh quan sát y học dân gian về bệnh sâu răng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu răng, sún răng", "Hạng Tần Suất (Jun Da)": "3489.0", "Tần Suất % (Jun Da)": "99.5403325423", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 禹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿禹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龋", "Unihan_Traditional (Chữ Phồn thể)": "齲", "Pinyin_Xie": "qǔ", "Âm Hán Việt_Xie": "củ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng như danh từ hoặc tính từ trong y học để chỉ bệnh sâu răng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗒', '{"9000": "3490.0", "Chữ Trung Quốc": "嗒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 嗒 | đáp | tượng hình | chữ chỉ âm thanh lốc cốc, hoặc trạng thái thất vọng rũ xuống | 嗒 chưa có cấu trúc hình thanh/hội ý rõ ràng trong Wiktionary. Bộ khẩu (口) gợi liên quan đến miệng hoặc âm thanh, nhưng cấu trúc tổng thể của 嗒 không được phân tích thành hai phần rõ ràng. Xem như chữ tạo muộn hoặc chữ tượng thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": miệng (口) há ra không thốt được lời — trạng thái nản lòng 嗒然 (thất vọng, rũ xuống). | Gương Hán-Việt | Đọc Hán-Việt: đáp. 嗒 ít dùng độc lập; xuất hiện trong 嗒然 (đáp nhiên — thất vọng, não lòng) và từ tượng thanh 嗒嗒 (tiếng lốc cốc). | Mở khoá kiến thức | Biết 嗒 mở khoá 嗒然若失 (dā rán ruò shī — thất thần như mất đi thứ gì) và từ tượng thanh trong văn học.", "Tự nguyên_Xie": "嗒 có nhiều cách đọc: tà (tiếng lốc cốc, trạng thái thất thần), dā (tiếng lách cách). Chữ không có phân tích hình thanh/hội ý chuẩn từ Wiktionary. Có lẽ là chữ ký âm (dùng miệng 口 để ghi âm thanh). Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thất vọng", "Hạng Tần Suất (Jun Da)": "3490.0", "Tần Suất % (Jun Da)": "99.5408689653", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 荅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口荅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗒", "Unihan_Traditional (Chữ Phồn thể)": "嗒", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "đáp, tháp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Từ tượng thanh | 象声词 | Chữ này thường làm tính từ thể hiện vẻ mặt thất vọng hoặc làm từ tượng thanh mô tả tiếng động nhỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咀', '{"9000": "3491.0", "Chữ Trung Quốc": "咀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 且 | thả | biểu âm | (cho âm jǔ) | 咀 = 口 (Khẩu, biểu nghĩa: miệng) + 且 (Thả, biểu âm); chữ hình thanh. Miệng là cơ quan nhai; 且 cho âm jǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trớ\": miệng (口) thả (且) chậm rãi — trớ trêu, nhai từng miếng chậm chạp, ngẫm nghĩ. | Gương Hán-Việt | \"trớ\" ít dùng độc lập; 咀 dùng trong 咀嚼 (nhai kỹ, suy ngẫm) | Mở khoá kiến thức | Biết 咀 mở khoá 咀嚼 (nhai kỹ; nghiền ngẫm, suy nghĩ sâu), 反刍咀嚼 (nhai lại như trâu bò — suy nghĩ kỹ lưỡng).", "Tự nguyên_Xie": "咀 là chữ hình thanh: bộ 口 (khẩu — miệng) biểu nghĩa; 且 (thả) cho âm jǔ. Theo Wiktionary, nghĩa là nhai, ngậm, mút. Chủ yếu gặp trong từ 咀嚼 (nhai kỹ; suy ngẫm kỹ). Không có nguồn cổ đại chi tiết hơn trong anchor. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhấm, nhai", "Hạng Tần Suất (Jun Da)": "3491.0", "Tần Suất % (Jun Da)": "99.5414048715", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咀", "Unihan_Traditional (Chữ Phồn thể)": "咀", "Pinyin_Xie": "jǔ", "Âm Hán Việt_Xie": "trớ, tư, tứ, chuỷ, tữ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường kết hợp với chữ khác tạo thành từ ghép như trớ tước để chỉ việc nhai kỹ hay suy ngẫm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祺', '{"9000": "3492.0", "Chữ Trung Quốc": "祺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 12 | nét | 示 | thị | biểu nghĩa | thần linh, điềm lành | 其 | kỳ | biểu âm | 祺 = 示 (Thị, biểu nghĩa: thần linh, điều may mắn) + 其 (Kỳ, biểu âm); chữ hình thanh. Bộ thị (示) biểu thị sự liên quan đến thần linh và điềm lành; 其 cho âm đọc gần qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": thần linh (示) ban điều kỳ diệu (其) — 祺 là phước lành, may mắn đến từ trời. | Gương Hán-Việt | Đọc Hán-Việt: kỳ. 祺 hay dùng trong tên người: 祺 hàm ý may mắn, an khang. Thấy trong thư tín cổ điển 顺祺 (thuận kỳ — bình an thuận thảo). | Mở khoá kiến thức | Biết 祺 mở khoá cách đọc tên người Trung Hoa và các lời chúc mừng trang trọng trong thư tín cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: 示 (thần, điều lành) biểu nghĩa, 其 biểu âm. 祺 mang nghĩa may mắn, an lành — một chữ cầu chúc tốt đẹp. Thường dùng trong tên người. Không có nguồn Wiktionary chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điềm lành; tốt lành", "Hạng Tần Suất (Jun Da)": "3492.0", "Tần Suất % (Jun Da)": "99.5419392273", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 其", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻其", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "其", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祺", "Unihan_Traditional (Chữ Phồn thể)": "祺", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ trong thư từ để chúc tụng sự bình an, may mắn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锚', '{"9000": "3493.0", "Chữ Trung Quốc": "锚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 苗 | miêu | biểu âm | 锚 = 钅/金 (Kim, biểu nghĩa: kim loại) + 苗 (Miêu, biểu âm); chữ hình thanh. Bộ kim chỉ chất liệu sắt thép; 苗 cho âm đọc gần máo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miêu\": cái neo bằng kim loại (钅) hình như cây mầm (苗) cắm chặt xuống đáy — đó là 锚, chiếc mỏ neo. | Gương Hán-Việt | Đọc Hán-Việt: miêu. 锚 xuất hiện trong 抛锚 (phao miêu — thả neo; xe chết máy) và 起锚 (khởi miêu — nhổ neo). | Mở khoá kiến thức | Biết 锚 mở khoá 抛锚 (pāomáo — thả neo, xe hỏng dọc đường), 起锚 (qǐmáo — nhổ neo, khởi hành).", "Tự nguyên_Xie": "Chữ hình thanh: 金 (kim loại) biểu nghĩa, 苗 biểu âm. 锚 chỉ mỏ neo tàu thuyền — vật bằng kim loại nặng thả xuống đáy biển giữ tàu đứng yên. Chữ tương đối muộn, không thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái mỏ neo", "Hạng Tần Suất (Jun Da)": "3493.0", "Tần Suất % (Jun Da)": "99.5424730664", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 苗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅苗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "苗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锚", "Unihan_Traditional (Chữ Phồn thể)": "錨", "Pinyin_Xie": "máo", "Âm Hán Việt_Xie": "miêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ mỏ neo hoặc làm động từ với nghĩa thả neo trong hàng hải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匾', '{"9000": "3494.0", "Chữ Trung Quốc": "匾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匸 | Số nét | 11 | nét | 匾 | biển | tượng hình | tấm bảng phẳng, biển hiệu treo cao | 匾 chưa có phân tích hình thanh/hội ý rõ ràng trong Wiktionary. Bộ匚 (biểu thị vật chứa/khung) kết hợp với phần trong, gợi hình ảnh tấm bảng khung bao quanh chữ. Xem như chữ tạo muộn, chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biển\": tấm 匾 — khung (匚) đóng chữ lên gỗ phẳng, treo ngoài cửa cho mọi người thấy danh hiệu. | Gương Hán-Việt | 匾 xuất hiện trong 匾额 (biển ngạch — tấm biển đề chữ treo trên cửa), 牌匾 (bài biển — biển hiệu). | Mở khoá kiến thức | Biết 匾 mở khoá 匾额 (biǎn é — biển treo cửa), 牌匾 (páibiǎn — biển hiệu kiến trúc cổ).", "Tự nguyên_Xie": "匾 chưa có nguồn Wiktionary chi tiết về cấu trúc hình thanh hay hội ý. Chữ chỉ tấm biển gỗ phẳng, thường treo ở cửa đền chùa hay dinh thự, khắc chữ đề danh hiệu hoặc lời chúc. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tấm biển; bức hoành; băng vải; cái mành tre", "Hạng Tần Suất (Jun Da)": "3494.0", "Tần Suất % (Jun Da)": "99.5430069054", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匾", "Unihan_Traditional (Chữ Phồn thể)": "匾", "Pinyin_Xie": "biǎn", "Âm Hán Việt_Xie": "biển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tấm bảng gỗ treo trước cửa hoặc trong nhà để viết chữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('乓', '{"9000": "3495.0", "Chữ Trung Quốc": "乓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 丿 | Số nét | 6 | nét | 丘 | khâu | biểu nghĩa | gốc của chữ 兵, biến hình | 乓 là chữ tạo muộn, biến thể của 兵 (cây gậy) — chỉ thay đổi nét đầu — được dùng làm tượng thanh cho tiếng đập ''bang/pāng''. Chủ yếu dùng trong 乒乓 (bóng bàn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt ''Bàng'': nghe ''pang'' khi quả bóng đập vào bàn — đó là ''bàng'', tiếng tượng thanh trong 乒乓. | Gương Hán-Việt | ''Bàng'' (Hán-Việt cổ); trong tiếng Việt 乓 chỉ dùng trong 乒乓 (pīng pāng / bóng bàn). | Mở khoá kiến thức | Biết 乓 mở khóa 乒乓球 (bóng bàn), 乒乓 (tiếng đập).", "Tự nguyên_Xie": "Theo Wiktionary, 乓 là chữ tạo muộn từ thay nét của 兵 — vừa biểu thanh vừa hình tượng tiếng vỗ. Chỉ dùng trong 乒乓 (pīng pāng — onomatopoeia cho tiếng bóng bàn). Không có nguồn gốc cổ trong Giáp cốt văn. | Theo Wiktionary · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sầm (tiếng đóng cửa)", "Hạng Tần Suất (Jun Da)": "3495.0", "Tần Suất % (Jun Da)": "99.5435402277", "GavinGrover_Once (Chiết tự trực tiếp)": "丘 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱丘丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丶", "Unihan_Simplified (Chữ Giản thể)": "乓", "Unihan_Traditional (Chữ Phồn thể)": "乓", "Pinyin_Xie": "pāng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô tả tiếng va đập mạnh, thường dùng trong từ ghép chỉ môn bóng bàn. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萃', '{"9000": "3496.0", "Chữ Trung Quốc": "萃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 卒 | thốt | biểu âm | 萃 = 艹 (Thảo, biểu nghĩa: cây cỏ) + 卒 (Thốt, biểu âm); chữ hình thanh. Bộ thảo gợi liên quan đến thực vật; nghĩa mở rộng thành \"tụ họp\" (như cây cỏ mọc dày).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tụy\": cỏ (艹) mọc tụ lại (卒) — từ hình ảnh cỏ mọc thành bụi dày mà ra nghĩa tụ hội, tinh túy: 出类拔萃. | Gương Hán-Việt | Đọc Hán-Việt: tụy. 萃 xuất hiện trong 出类拔萃 (xuất loại bạt tụy — nổi trội hơn hẳn), 荟萃 (hội tụy — tập hợp tinh hoa). | Mở khoá kiến thức | Biết 萃 mở khoá 出类拔萃 (chūlèi bácuì — xuất sắc vượt trội) và 荟萃 (huìcuì — tụ hội tinh hoa).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: 艹 (cỏ) biểu nghĩa, 卒 biểu âm. Nghĩa gốc là cỏ mọc dày, sau mở rộng sang \"tụ tập, tinh túy\" — tinh hoa đông đảo tụ về một chỗ như cỏ mọc tập trung. Không có nguồn Wiktionary chi tiết hơn về cổ văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họp; đàn, nhóm; sắc cỏ", "Hạng Tần Suất (Jun Da)": "3496.0", "Tần Suất % (Jun Da)": "99.5440735499", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 卒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹卒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "萃", "Unihan_Traditional (Chữ Phồn thể)": "萃", "Pinyin_Xie": "cuì", "Âm Hán Việt_Xie": "tụy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ sự tụ họp của người hoặc vật, thường dùng trong văn viết cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贻', '{"9000": "3497.0", "Chữ Trung Quốc": "贻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 9 | nét | 贻 | di | tượng hình | chữ giản thể của 貽 — tặng, để lại | 贻 là giản thể của 貽. Dạng phồn thể 貽 = 貝 (bối, của cải) + 台 (thai, biểu âm) — hàm ý trao tặng của cải. Chữ giản thể thay 貝→贝, giữ cấu trúc hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": trao của cải (贝) để lại (台) — 贻 là biếu tặng, để lại di sản cho người sau. | Gương Hán-Việt | 贻 xuất hiện trong 贻笑大方 (di tiếu đại phương — để lại tiếng cười cho người thạo), 贻害 (di hại — để lại hậu quả). | Mở khoá kiến thức | Biết 贻 mở khoá 贻笑大方 (yíxiào dàfāng — bị người hiểu biết chê cười), 贻害无穷 (để lại họa vô tận).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 贻 là giản thể của 貽 (貝 + 台): bộ bối (của cải, tiền tệ) biểu nghĩa, 台 biểu âm. Nghĩa gốc: tặng, biếu; mở rộng sang \"để lại, lưu lại\" (遗贻 — để lại cho đời sau). Chữ tương đối cổ, xuất hiện trong văn học cổ điển. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "truyền lại, để lại cho đời sau", "Hạng Tần Suất (Jun Da)": "3497.0", "Tần Suất % (Jun Da)": "99.5446068722", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 台", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝台", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "台", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贻", "Unihan_Traditional (Chữ Phồn thể)": "貽", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động để lại hậu quả hoặc tặng quà cho người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揖', '{"9000": "3498.0", "Chữ Trung Quốc": "揖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 咠 | nghiện | biểu âm | 揖 = 扌 (Thủ, biểu nghĩa: tay) + 咠 (biểu âm); chữ hình thanh. Bộ tay chỉ hành động dùng tay; nghĩa là chắp tay vái chào — một nghi lễ tay phổ biến trong văn hoá cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ập\": hai tay (扌) khép lại ập vào nhau trước ngực — đó là động tác vái chào 揖, lễ nghi cổ điển. | Gương Hán-Việt | 揖 xuất hiện trong 作揖 (tác ập — vái chào chắp tay), 揖让 (ập nhượng — nhường nhịn lịch sự). | Mở khoá kiến thức | Biết 揖 mở khoá 作揖 (zuòyī — vái chào chắp tay) và hiểu nghi lễ chào hỏi cổ điển Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ hình thanh: 扌 (tay) biểu nghĩa, 咠 biểu âm. 揖 chỉ lễ vái chắp tay: hai tay nắm lại trước ngực, cúi đầu chào. Đây là hình thức chào hỏi lịch sự trong xã hội phong kiến Trung Hoa. Xuất hiện từ thời Chu Lễ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chắp tay vái", "Hạng Tần Suất (Jun Da)": "3498.0", "Tần Suất % (Jun Da)": "99.5451396777", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 咠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌咠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揖", "Unihan_Traditional (Chữ Phồn thể)": "揖", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "ấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn cổ hoặc các cụm từ cố định chỉ nghi thức chào hỏi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('觑', '{"9000": "3499.0", "Chữ Trung Quốc": "觑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 見 | Số nét | 15 | nét | 虛 | hư | biểu âm | 見 | kiến | biểu nghĩa | nhìn, thấy | 觑 = 虛 (Hư, biểu âm) + 見 (Kiến, biểu nghĩa: nhìn, thấy); chữ hình thanh. Bộ kiến chỉ hành động nhìn; 虛 cho âm gần qù. Hàm ý nhìn trộm, nhìn lén qua khe hở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khư\": mắt (見) nhìn qua chỗ hư không (虛) — ngó lén, rình mò qua khe cửa. | Gương Hán-Việt | Đọc Hán-Việt: khư. 觑 xuất hiện trong 觑觑 (lén nhìn), 打小觑 (dǎ xiǎo qù — coi thường), 相觑 (nhìn nhau ngơ ngác). | Mở khoá kiến thức | Biết 觑 mở khoá 打小觑 (coi thường) và cách diễn đạt \"nhìn nhau không nói\" trong văn học cổ điển.", "Tự nguyên_Xie": "Chữ hình thanh: 見 (nhìn) biểu nghĩa, 虛 biểu âm. 觑 chỉ việc rình xem, nhìn trộm qua khe nhỏ — nhìn \"lén\" chứ không nhìn thẳng. Dạng phồn thể 覷 dùng 目 thay 見. Không có cổ văn chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rình mò, xem trộm", "Hạng Tần Suất (Jun Da)": "3499.0", "Tần Suất % (Jun Da)": "99.5456724831", "GavinGrover_Once (Chiết tự trực tiếp)": "虚 + 见", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虚见", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "见", "Unihan_Simplified (Chữ Giản thể)": "觑", "Unihan_Traditional (Chữ Phồn thể)": "覷", "Pinyin_Xie": "qù", "Âm Hán Việt_Xie": "thứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ chỉ đối tượng bị nhìn trộm hoặc quan sát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吝', '{"9000": "3500.0", "Chữ Trung Quốc": "吝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 文 | văn | biểu nghĩa | văn, hoa văn (gợi ý của cải) | 口 | khẩu | biểu nghĩa | miệng | 吝 gồm 文 (Văn) + 口 (Khẩu). Wiktionary không ghi rõ ls code; tự dạng gợi người tiếc lời (văn tự/của cải) qua miệng — có thể là hội ý hoặc phức tạp về nguồn gốc. Chữ tạo sớm, chưa có nguồn học thuật xác nhận chính xác hơn trong anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\": văn chương (文) qua miệng (口) cũng không chịu nhả — lận lưng, keo kiệt từng chữ, từng đồng. | Gương Hán-Việt | \"lận\" trong \"lận sắc\" (吝啬 — keo kiệt); 吝 dùng độc lập với nghĩa tiếc rẻ | Mở khoá kiến thức | Biết 吝 mở khoá 吝啬 (keo kiệt), 吝惜 (tiếc rẻ, bủn xỉn), 不吝赐教 (sẵn lòng chỉ giáo — cách nói khiêm tốn).", "Tự nguyên_Xie": "Giáp cốt văn | Bạch thư | Đại triện | Tiểu triện | 吝 có cấu trúc gồm 文 (văn — hoa văn, chữ nghĩa, của cải) và 口 (khẩu — miệng). Wiktionary không ghi cụ thể ls code. Nghĩa là keo kiệt, tiếc rẻ, không muốn cho đi. Hình thức cổ xuất hiện trong giáp cốt văn, bạch thư, đại triện và tiểu triện (xem hình trong anchor). Chưa có nguồn học thuật xác nhận cấu trúc chính xác. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "223.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Văn (205) Khẩu (6)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Văn (số 222) ở trên chữ Khẩu (số 6) . Kẻ gian dối thường dùng lời nói hay, văn hoa để lừa gạt (khẩu). Lận cũng có nghĩa hối tiếc, keo kiệt.", "Nghĩa Tiếng Việt_Xie": "tiếc rẻ, keo kiệt", "Hạng Tần Suất (Jun Da)": "3500.0", "Tần Suất % (Jun Da)": "99.5462047718", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 口", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱文口", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "口", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "吝", "Unihan_Traditional (Chữ Phồn thể)": "吝", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "lận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc làm động từ đi kèm với tân ngữ chỉ sự vật bị tiếc rẻ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憔', '{"9000": "3501.0", "Chữ Trung Quốc": "憔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 憔 | tiều | tượng hình | mệt mỏi, tiều tụy, xác xơ | 憔 chưa có phân tích cấu trúc rõ trong Wiktionary. Bộ tâm (忄/心) gợi trạng thái nội tâm; phần còn lại gợi âm qiáo. Xem như chữ hình thanh với bộ tâm biểu nghĩa, nhưng thiếu xác nhận từ cổ văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiều\": lòng (心) như người tiều phu gầy gò — 憔悴 là tiều tuỵ, xác xơ vì mệt mỏi lo lắng. | Gương Hán-Việt | 憔 gần như chỉ dùng trong 憔悴 (tiều tuỵ — gầy mòn, hốc hác vì khổ sở). | Mở khoá kiến thức | Biết 憔 mở khoá 憔悴 (qiáocuì — tiều tuỵ, hốc hác) — cụm từ văn học rất phổ biến.", "Tự nguyên_Xie": "Tiểu triện | 憔 chưa có nguồn Wiktionary chi tiết về cấu trúc. Bộ心/忄 (tâm) có thể là biểu nghĩa — trạng thái tinh thần kiệt sức. Chữ thường đi kèm 悴 thành 憔悴 (tiều tuỵ). Hình ảnh tiểu triện còn giữ được. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mệt mỏi; tiều tuỵ, xác xơ", "Hạng Tần Suất (Jun Da)": "3501.0", "Tần Suất % (Jun Da)": "99.5467370605", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 焦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄焦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憔", "Unihan_Traditional (Chữ Phồn thể)": "憔", "Pinyin_Xie": "qiáo", "Âm Hán Việt_Xie": "tiều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với chữ khác để tạo tính từ ghép miêu tả vẻ mặt mệt mỏi, hốc hác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羌', '{"9000": "3502.0", "Chữ Trung Quốc": "羌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 7 | nét | 羌 | khương | tượng hình | người đàn ông đội sừng dê — tộc Khương phía tây | 羌 là chữ tượng hình/hội ý: hình người (人) đội hai sừng dê (羊) trên đầu — biểu trưng cho tộc người Khương sống ở tây bộ Trung Hoa cổ đại. Bộ 羊 cũng đồng thời gợi âm đọc, nên có yếu tố hình thanh xen lẫn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khương\": người (人) đội sừng dê (羊) — đó là tộc Khương (羌), dân du mục tây bộ Trung Hoa, tổ tiên của nhiều dân tộc thiểu số ngày nay. | Gương Hán-Việt | Đọc Hán-Việt: khương. 羌 xuất hiện trong 羌族 (Khương tộc — dân tộc Khương), 羌笛 (khương địch — sáo Khương, nhạc cụ dân gian). | Mở khoá kiến thức | Biết 羌 mở khoá 羌族 (Qiāngzú — tộc Khương) và hiểu tên gọi dân tộc thiểu số Trung Hoa trong văn học, lịch sử.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary: 羌 là hình ảnh người đàn ông (人) đội hai sừng dê (羊) — biểu trưng cho tộc Khương, dân du mục chăn cừu ở tây bắc Trung Quốc cổ. Chữ 羊 vừa biểu nghĩa (dê, súc vật nuôi) vừa gợi âm. Chữ này vừa tượng hình vừa có yếu tố hình thanh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rợ Khương, tộc Khương (phía Tây Trung Quốc)", "Hạng Tần Suất (Jun Da)": "3502.0", "Tần Suất % (Jun Da)": "99.5472688324", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 乚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊乚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羌", "Unihan_Traditional (Chữ Phồn thể)": "羌", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "khương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một dân tộc thiểu số ở vùng tây bắc Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诲', '{"9000": "3503.0", "Chữ Trung Quốc": "诲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 言 | ngôn | biểu nghĩa | lời nói | 每 | mỗi | biểu âm | 诲 = 言 (Ngôn, biểu nghĩa: lời nói, ngôn ngữ) + 每 (Mỗi, biểu âm); chữ hình thanh. Bộ ngôn chỉ hành động dùng lời; nghĩa là dạy bảo bằng lời nói.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hối\": lời (言) dạy mỗi ngày mỗi lần (每) — 诲 là sự dạy bảo kiên nhẫn, nhắc nhở không ngừng. | Gương Hán-Việt | 诲 xuất hiện trong 诲人不倦 (hối nhân bất quyện — dạy người không mệt mỏi), 教诲 (giáo hối — giáo huấn). | Mở khoá kiến thức | Biết 诲 mở khoá 诲人不倦 (huì rén bù juàn — tinh thần dạy học kiên nhẫn) và 教诲 (jiàohuì — lời dạy dỗ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh từ dạng phồn thể 誨: 言 (lời nói) biểu nghĩa, 每 biểu âm. 诲 nghĩa là dạy dỗ, khuyên nhủ — đặc biệt nhấn mạnh sự kiên nhẫn và lặp đi lặp lại của người dạy. Xuất hiện trong Luận Ngữ với cụm 诲人不倦 (dạy người không biết mệt). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răn dạy, dạy bảo", "Hạng Tần Suất (Jun Da)": "3503.0", "Tần Suất % (Jun Da)": "99.5478000875", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 每", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠每", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "每", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诲", "Unihan_Traditional (Chữ Phồn thể)": "誨", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc các từ ghép mang nghĩa giáo dục, dạy dỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('砾', '{"9000": "3504.0", "Chữ Trung Quốc": "砾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 10 | nét | 石 | thạch | biểu nghĩa | đá | 樂 | lạc | biểu âm | 砾 = 石 (Thạch, biểu nghĩa: đá) + 樂 (Lạc, biểu âm); chữ hình thanh. Bộ thạch chỉ chất liệu đá; 樂 cho âm gần lì. Nghĩa là đá vụn, sỏi nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": đá (石) vỡ vụn như tiếng nhạc lạc (樂) rơi xuống — 砾 là những viên sỏi đá vụn lăn lóc trên đường. | Gương Hán-Việt | 砾 xuất hiện trong 砾石 (lịch thạch — sỏi đá), 瓦砾 (ngoã lịch — gạch vụn, đổ nát). | Mở khoá kiến thức | Biết 砾 mở khoá 瓦砾 (wǎlì — gạch đá vụn, tàn tích đổ nát) và 砾石 (lìshí — sỏi đá địa chất).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh từ phồn thể 礫: 石 (đá) biểu nghĩa, 樂 biểu âm. 砾 chỉ những mảnh đá vỡ nhỏ, sỏi — vật liệu địa chất. Tiểu triện còn lưu giữ hình dạng. Không có ghi chép giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đá vụn, đá sỏi", "Hạng Tần Suất (Jun Da)": "3504.0", "Tần Suất % (Jun Da)": "99.5483313427", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 乐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石乐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "砾", "Unihan_Traditional (Chữ Phồn thể)": "礫", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp tạo từ ghép chỉ các loại đất đá vụn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蠕', '{"9000": "3505.0", "Chữ Trung Quốc": "蠕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 20 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 需 | nhu | biểu âm | 蠕 = 虫 (Trùng, biểu nghĩa: sâu, côn trùng) + 需 (Nhu, biểu âm); chữ hình thanh. Bộ trùng chỉ sinh vật bò; nghĩa là nhúc nhích, bò lăn — chuyển động từng bước nhỏ như sâu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhu\": con sâu (虫) bò nhẹ nhàng từng chút nhu mì (需) — 蠕动 là cử động nhúc nhích kiểu nhu động ruột. | Gương Hán-Việt | 蠕 xuất hiện trong 蠕动 (nhu động — nhu động, nhúc nhích), 蠕虫 (nhu trùng — giun sán). | Mở khoá kiến thức | Biết 蠕 mở khoá 蠕动 (rúdòng — nhu động ruột, bò nhúc nhích) và 蠕虫 (rúchóng — giun, sán).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 虫 (sâu) biểu nghĩa, 需 biểu âm. 蠕 chỉ chuyển động nhúc nhích, lết từng chút như sâu bò. Tiểu triện lưu lại hình dạng. Thường dùng trong 蠕动 (nhu động — nhu động ruột) và 蠕虫 (sâu giun). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhúc nhích", "Hạng Tần Suất (Jun Da)": "3505.0", "Tần Suất % (Jun Da)": "99.5488625978", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 需", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫需", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "需", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蠕", "Unihan_Traditional (Chữ Phồn thể)": "蝡", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ miêu tả động tác bò chậm chạp của các loài bò sát hoặc côn trùng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('肴', '{"9000": "3506.0", "Chữ Trung Quốc": "肴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 8 | nét | 爻 | hào | biểu âm | (cho âm yáo, hiện nay biến thành 㐅 ở trên) | 有 | hữu | biểu nghĩa | có, chứa (thay cho 肉 — thịt) | 肴 = 爻 (Hào, biểu âm, rút còn 㐅 ở trên) + 肉 (biểu nghĩa: thịt, hiện nay trông giống 有); chữ hình thanh. Theo Wiktionary, dạng hiện tại trông như ⿱乂有 vì phần dưới của 爻 đã dịch sang và xuống. Bộ nghĩa là thịt; hào cho âm yáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hào\": hào hoa hào phóng (爻/hào) + có đủ (有) — hào phóng đãi khách bằng mâm cỗ thức nhắm. | Gương Hán-Việt | \"hào\" trong \"giai hào\" (佳肴 — cao lương mỹ vị); 爻 (hào) trong bát quái | Mở khoá kiến thức | Biết 肴 mở khoá 佳肴 (cao lương mỹ vị), 酒肴 (rượu và thức nhắm), 肴核 (thức nhắm và hoa quả — văn cổ).", "Tự nguyên_Xie": "Tiểu triện | 肴 là chữ hình thanh: 爻 (hào) cho âm yáo; 肉 (nhục — thịt, rút thành ⺼) biểu nghĩa. Theo Wiktionary, dạng hiện tại trông giống ⿱乂有 vì nửa dưới của 爻 đã dịch sang bên tạo dáng hiện tại. Nghĩa là các món thịt nấu chín, thức nhắm. Dùng trong 佳肴 (cao lương mỹ vị) và 酒肴 (rượu và thức nhắm). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đồ nhắm, thức nhắm", "Hạng Tần Suất (Jun Da)": "3506.0", "Tần Suất % (Jun Da)": "99.5493928193", "GavinGrover_Once (Chiết tự trực tiếp)": "乂 + 有", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱乂有", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "有", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "乂", "Unihan_Simplified (Chữ Giản thể)": "肴", "Unihan_Traditional (Chữ Phồn thể)": "肴", "Pinyin_Xie": "yáo", "Âm Hán Việt_Xie": "hào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các món ăn ngon, đặc biệt là các món thịt dùng để nhắm rượu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撩', '{"9000": "3507.0", "Chữ Trung Quốc": "撩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 手 | thủ | biểu nghĩa | tay | 尞 | biểu âm | 撩 = 扌/手 (Thủ, biểu nghĩa: tay) + 尞 (biểu âm, đọc liáo); chữ hình thanh. Bộ tay chỉ hành động dùng tay; nghĩa gốc là vén lên, nhấc lên bằng tay.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lêu\": tay (手) vén lên lêu lêu — 撩 là vén, nhấc lên; hoặc trêu chọc khêu gợi như tay người lêu lổng. | Gương Hán-Việt | 撩 xuất hiện trong 撩起 (lêu khởi — vén lên), 撩拨 (lêu bát — khêu gợi, trêu chọc), 撩人 (lêu nhân — quyến rũ). | Mở khoá kiến thức | Biết 撩 mở khoá 撩拨 (liáobō — khêu gợi, trêu chọc) và 撩人 (liáorén — quyến rũ lòng người).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 手 (tay) biểu nghĩa, 尞 biểu âm. 撩 có hai nghĩa chính: (1) vén lên, nhấc lên (撩起裙子 — vén váy); (2) khêu gợi, trêu chọc (撩拨 — khêu gợi). Cả hai liên quan đến hành động tay tác động vào đối tượng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nâng lên, nhấc lên, vén lên", "Hạng Tần Suất (Jun Da)": "3507.0", "Tần Suất % (Jun Da)": "99.5499225241", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撩", "Unihan_Traditional (Chữ Phồn thể)": "撩", "Pinyin_Xie": "liāo", "Âm Hán Việt_Xie": "liêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đi kèm tân ngữ chỉ quần áo, rèm cửa hoặc tóc khi thực hiện động tác vén. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坍', '{"9000": "3508.0", "Chữ Trung Quốc": "坍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 丹 | đan | biểu âm | 坍 = 土 (Thổ, biểu nghĩa: đất) + 丹 (Đan, biểu âm); chữ hình thanh. Bộ thổ chỉ đất đai; 丹 cho âm gần tān. Nghĩa là đất lở, sụp đổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đam\": đất (土) đỏ đan (丹) màu sụp xuống — 坍塌 là sụp đổ, đất đai lở toan tính. | Gương Hán-Việt | 坍 xuất hiện trong 坍塌 (đam tháp — sụp đổ), 坍方 (đam phương — đất đá sạt lở). | Mở khoá kiến thức | Biết 坍 mở khoá 坍塌 (tāntā — sụp đổ, đổ ập), 坍方 (tānfāng — sạt lở đất).", "Tự nguyên_Xie": "Chữ hình thanh: 土 (đất) biểu nghĩa, 丹 biểu âm. 坍 chỉ sự sụp đổ do đất lún xuống — nhà cửa, bờ đê, đất đá đổ ập. Xuất hiện trong Thuỷ Hử với hình ảnh cột đình bị đổ sập. Không có ghi chép giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất lở", "Hạng Tần Suất (Jun Da)": "3508.0", "Tần Suất % (Jun Da)": "99.550447061", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 丹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土丹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坍", "Unihan_Traditional (Chữ Phồn thể)": "坍", "Pinyin_Xie": "tān", "Âm Hán Việt_Xie": "than", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ miêu tả hiện tượng sạt lở của đất đá hoặc sự sụp đổ của công trình xây dựng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酥', '{"9000": "3509.0", "Chữ Trung Quốc": "酥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酉 | dậu | biểu nghĩa | bình rượu, lên men | 穌 | biểu âm | 酥 = 酉 (Dậu, biểu nghĩa: bình rượu, lên men, sản phẩm từ sữa) + 穌 (biểu âm); chữ hình thanh. Bộ dậu gợi sản phẩm chế biến; nghĩa gốc là bơ sữa đặc, sau mở rộng sang xốp giòn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tô\": bình (酉) ủ ra thứ mềm tan tô tô — 酥 là bơ sữa, bánh xốp giòn, cảm giác mềm nhũn dễ chịu. | Gương Hán-Việt | 酥 xuất hiện trong 酥脆 (tô thuỵ — giòn xốp), 酥油 (tô du — bơ sữa), 酥胸 (ngực mềm mại, dùng trong thơ văn cổ). | Mở khoá kiến thức | Biết 酥 mở khoá 酥脆 (sūcuì — giòn tan), 酥油 (sūyóu — bơ yak/bơ sữa) và mô tả kết cấu ẩm thực.", "Tự nguyên_Xie": "Chữ hình thanh: 酉 (bình rượu/lên men) biểu nghĩa, 穌 (rút gọn) biểu âm. 酥 nghĩa gốc là bơ động vật (váng sữa); sau mở rộng sang mô tả kết cấu xốp giòn, mềm tan của bánh. Không có giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "váng sữa", "Hạng Tần Suất (Jun Da)": "3509.0", "Tần Suất % (Jun Da)": "99.5509710811", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 禾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉禾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "禾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酥", "Unihan_Traditional (Chữ Phồn thể)": "酥", "Pinyin_Xie": "sū", "Âm Hán Việt_Xie": "tô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ thực phẩm từ sữa hoặc làm tính từ miêu tả trạng thái giòn tan của bánh ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | sū | / | bơ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袅', '{"9000": "3510.0", "Chữ Trung Quốc": "袅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | nữ, mềm mại | 弱 | nhược | biểu âm | 袅 = 女 (Nữ, biểu nghĩa: mềm mại, yếu đuối) + 弱 (Nhược, biểu âm); chữ hình thanh. Bộ nữ gợi hình ảnh mềm mại, uyển chuyển; 弱 cho âm gần niǎo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nêu\": người nữ (女) yếu nhược (弱) như khói lên — 袅袅 là làn khói hương cuộn lên nhẹ nhàng uyển chuyển. | Gương Hán-Việt | 袅 xuất hiện trong 袅袅 (nêu nêu — khói cuộn nhẹ), 袅娜 (nêu noa — uyển chuyển, duyên dáng). | Mở khoá kiến thức | Biết 袅 mở khoá 袅袅炊烟 (làn khói bếp uốn lượn) và mô tả hình thể uyển chuyển trong văn học cổ.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ hình thanh: 女 (nữ) biểu nghĩa, 弱 biểu âm. 袅 miêu tả khói cuộn nhẹ, dáng điệu uyển chuyển, âm thanh vang mãi — tất cả gợi sự mềm mại, lơ lửng. Thường dùng trong 袅袅 (niǎoniǎo — khói cuộn nhẹ nhàng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xoáy vùng", "Hạng Tần Suất (Jun Da)": "3510.0", "Tần Suất % (Jun Da)": "99.5514940677", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 衣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱衣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "袅", "Unihan_Traditional (Chữ Phồn thể)": "嫋", "Pinyin_Xie": "niǎo", "Âm Hán Việt_Xie": "niễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả dáng điệu mềm mại hoặc làn khói bay lượn lờ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黝', '{"9000": "3511.0", "Chữ Trung Quốc": "黝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 17 | nét | 黝 | u | tượng hình | màu xanh đen, đen thẫm | 黝 chưa có phân tích hình thanh/hội ý rõ trong Wiktionary. Bộ 黑 (hắc, đen) có thể là biểu nghĩa; phần còn lại gợi âm yǒu. Xem như chữ hình thanh với bộ hắc biểu nghĩa, nhưng thiếu xác nhận từ cổ văn chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"u\": màu u tối (黑) ánh xanh — 黝黑 là làn da đen bóng khoẻ mạnh, không phải đen xỉn. | Gương Hán-Việt | 黝 xuất hiện trong 黝黑 (u hắc — đen bóng), 黑黝黝 (đen thẫm, mờ tối). | Mở khoá kiến thức | Biết 黝 mở khoá 黝黑 (yǒuhēi — đen bóng, đen khoẻ mạnh) — từ miêu tả màu da trong văn học hiện đại.", "Tự nguyên_Xie": "Tiểu triện | 黝 không có phân tích cấu trúc chi tiết trong Wiktionary. Bộ黑 (đen) gợi màu sắc tối; nghĩa là màu xanh đen, đen thẫm — màu da hoặc màu sắc có sắc tối. Xuất hiện trong tiểu triện. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu xanh đen", "Hạng Tần Suất (Jun Da)": "3511.0", "Tần Suất % (Jun Da)": "99.5520160207", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黝", "Unihan_Traditional (Chữ Phồn thể)": "黝", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "ửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ để miêu tả màu sắc đen sẫm của da hoặc cảnh vật tối tăm. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俾', '{"9000": "3512.0", "Chữ Trung Quốc": "俾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 俾 | tỉ | tượng hình | khiến cho, để cho — chữ cổ dùng trong văn ngôn và tiếng Quảng | 俾 không có nguồn Wiktionary chi tiết. Bộ nhân (亻) gợi hành động liên quan đến người; phần còn lại có thể biểu âm. Kim văn và tiểu triện còn lưu lại hình dạng. Cấu trúc chính xác chưa được xác nhận từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tỉ\": người (亻) làm cho kẻ khác — 俾 là khiến, làm cho, để cho; chữ văn ngôn thay thế 使 trong một số ngữ cảnh cổ. | Gương Hán-Việt | Đọc Hán-Việt: tỉ. 俾 xuất hiện trong văn ngôn cổ như 俾众周知 (tỉ chúng chu tri — để mọi người biết), và trong tiếng Quảng 俾佢 (cho anh ấy). | Mở khoá kiến thức | Biết 俾 mở khoá văn phong cổ điển và tiếng Quảng Đông — 俾 là 给 (cho/đưa) trong Quảng ngữ.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 俾 không có nguồn Wiktionary. Chữ có kim văn, tiểu triện và lục thư thông. Bộ nhân (亻) gợi liên quan đến con người; nghĩa là khiến cho, để cho, làm cho (tương đương 使 trong văn ngôn). Trong tiếng Quảng Đông hiện đại, 俾 còn nghĩa là cho/đưa. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khiến; để cho; làm; đến mức", "Hạng Tần Suất (Jun Da)": "3512.0", "Tần Suất % (Jun Da)": "99.5525364233", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 卑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻卑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俾", "Unihan_Traditional (Chữ Phồn thể)": "俾", "Pinyin_Xie": "bǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Liên từ | 连词 | Chữ này thường làm động từ hoặc liên từ trong văn viết để biểu thị mục đích hoặc kết quả. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫣', '{"9000": "3513.0", "Chữ Trung Quốc": "嫣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 嫣 | yên | tượng hình | quyến rũ, say đắm, duyên dáng | 嫣 chưa có phân tích cấu trúc rõ trong Wiktionary. Bộ nữ (女) gợi liên quan đến vẻ đẹp nữ tính; phần còn lại có thể biểu âm. Tiểu triện còn lưu lại. Cấu trúc chính xác chưa được xác nhận từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yên\": người nữ (女) đẹp như hoa yên chi — 嫣然一笑 là nụ cười tươi tắn duyên dáng. | Gương Hán-Việt | 嫣 xuất hiện trong 嫣然 (yên nhiên — nụ cười duyên dáng), 姹紫嫣红 (sắc hoa rực rỡ muôn màu). | Mở khoá kiến thức | Biết 嫣 mở khoá 嫣然一笑 (yānrán yī xiào — mỉm cười duyên dáng) và 姹紫嫣红 (chàzǐyānhóng — hoa lá rực rỡ).", "Tự nguyên_Xie": "Tiểu triện | 嫣 không có nguồn Wiktionary chi tiết về cấu trúc. Bộ 女 (nữ) biểu nghĩa — liên quan đến vẻ đẹp phụ nữ; phần còn lại biểu âm yān. Nghĩa: duyên dáng, say đắm, quyến rũ. Thường dùng trong 嫣然 (yên nhiên — nụ cười tươi tắn) và 姹紫嫣红. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say đắm, quyến rũ", "Hạng Tần Suất (Jun Da)": "3513.0", "Tần Suất % (Jun Da)": "99.5530557924", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 焉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女焉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "焉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫣", "Unihan_Traditional (Chữ Phồn thể)": "嫣", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để tả nụ cười đẹp hoặc vẻ rực rỡ của hoa. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('穹', '{"9000": "3514.0", "Chữ Trung Quốc": "穹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 8 | nét | 穴 | huyệt | biểu nghĩa | hang, vòm | 弓 | cung | biểu âm | 穹 = 穴 (Huyệt, biểu nghĩa: hang vòm, vòm trời) + 弓 (Cung, biểu âm); chữ hình thanh. Bộ huyệt gợi hình vòm cong; 弓 cho âm gần qióng. Nghĩa: bầu trời vòm cao rộng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khung\": hang vòm (穴) cong như cung (弓) — 穹 là bầu trời vòm cao, sương khói vẽ nên chiếc 穹隆 bao la. | Gương Hán-Việt | 穹 xuất hiện trong 蒼穹 (thương khung — bầu trời xanh), 穹隆 (khung lung — vòm mái, mái vòm kiến trúc). | Mở khoá kiến thức | Biết 穹 mở khoá 蒼穹 (cāngqióng — bầu trời xanh thẳm) và 穹隆 (qiónglóng — mái vòm) trong kiến trúc và thơ văn.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 穴 (vòm hang) biểu nghĩa, 弓 biểu âm. 穹 chỉ vòm trời cao rộng, bầu trời như chiếc lều vòm cong. Tiểu triện và lục thư thông lưu lại. Dùng nhiều trong thơ cổ điển: 蒼穹 (thương khung — bầu trời xanh), 穹隆 (vòm mái). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cao lớn và hình khum cong", "Hạng Tần Suất (Jun Da)": "3514.0", "Tần Suất % (Jun Da)": "99.5535746446", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 弓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴弓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "穹", "Unihan_Traditional (Chữ Phồn thể)": "穹", "Pinyin_Xie": "qióng", "Âm Hán Việt_Xie": "khung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ vòm trời hoặc tính từ chỉ hình dáng khum cong. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秧', '{"9000": "3515.0", "Chữ Trung Quốc": "秧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 禾 | biểu nghĩa | lúa, ngũ cốc | 央 | ương | biểu âm | 秧 = 禾 (biểu nghĩa: lúa, ngũ cốc) + 央 (Ương, biểu âm); chữ hình thanh. Bộ hoà/禾 chỉ loại cây ngũ cốc; 央 cho âm gần yāng. Nghĩa: mạ non, cây lúa mới gieo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": lúa (禾) ương (央) — 秧 là mạ, cây lúa non đang trong giai đoạn ương mầm chờ cấy. | Gương Hán-Việt | 秧 xuất hiện trong 秧苗 (ương miêu — mạ giống), 插秧 (sáp ương — cấy lúa), 育秧 (dục ương — ươm mạ). | Mở khoá kiến thức | Biết 秧 mở khoá 插秧 (chā yāng — cấy lúa), 秧苗 (yāngmiáo — mạ giống), và hiểu từ vựng nông nghiệp lúa nước.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 禾 (lúa) biểu nghĩa, 央 biểu âm. 秧 chỉ mạ lúa — cây lúa non vừa nảy mầm chưa cấy xuống ruộng. Tiểu triện lưu lại hình dạng. Mở rộng sang cây giống nói chung (秧苗 — cây giống). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1547.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Ương (1546)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾 /chỉ ý) ở bên trái chữ Ương (số 1546 - ở giữa/ 央 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Ương (央) chỉ âm, bộ Hòa chỉ ý. Ương vốn là mầm lúa non dùng để cấy xuống ruộng (cây mạ, mạ non). Từ đó chỉ việc ươm giống, gieo mầm để nó mọc lên lớn lên (ươm giống).", "Nghĩa Tiếng Việt_Xie": "gieo mạ; cây lúa non", "Hạng Tần Suất (Jun Da)": "3515.0", "Tần Suất % (Jun Da)": "99.5540929801", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秧", "Unihan_Traditional (Chữ Phồn thể)": "秧", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cây mạ non hoặc làm động từ với nghĩa gieo cấy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('妊', '{"9000": "3516.0", "Chữ Trung Quốc": "妊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 7 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 壬 | nhăm | biểu âm | 妊 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 壬 (Nhăm, biểu âm); chữ hình thanh. Bộ nữ chỉ sự liên quan đến phụ nữ; nghĩa là mang thai, có bầu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhậm\": người phụ nữ (女) mang trách nhiệm nhậm (壬) — 妊 là có thai, mang bầu, thụ nhận sự sống mới. | Gương Hán-Việt | 妊 xuất hiện trong 妊娠 (nhậm thần — thai kỳ, mang thai), 妊娠反应 (ốm nghén). | Mở khoá kiến thức | Biết 妊 mở khoá 妊娠 (rènshēn — thai kỳ, đang mang thai) và thuật ngữ sản khoa cơ bản.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Chữ hình thanh: 女 (phụ nữ) biểu nghĩa, 壬 biểu âm. 妊 chỉ trạng thái mang thai — xuất hiện từ giáp cốt văn với hình người phụ nữ mang bầu. Kim văn và tiểu triện còn lưu lại. Dùng trong thuật ngữ y tế: 妊娠 (nhăm thần — thai kỳ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "có mang, có bầu", "Hạng Tần Suất (Jun Da)": "3516.0", "Tần Suất % (Jun Da)": "99.554610282", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 壬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女壬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "妊", "Unihan_Traditional (Chữ Phồn thể)": "妊", "Pinyin_Xie": "rèn", "Âm Hán Việt_Xie": "nhâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc mang thai, thường kết hợp thành từ ghép như nhậm thần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溉', '{"9000": "3517.0", "Chữ Trung Quốc": "溉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 氵 | thuỷ | biểu nghĩa | nước | 既 | ký | biểu âm | (cho âm gài) | 溉 = 氵(Thuỷ, biểu nghĩa: nước) + 既 (Ký, biểu âm); chữ hình thanh. Nước là yếu tố nghĩa, liên quan đến tưới tiêu; 既 cho âm gài (gần ký → cải → gài).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khái\": nước (氵) đã (既) tưới — khái quát, tưới đẫm đồng ruộng cho cây lớn. | Gương Hán-Việt | \"khái\" trong \"quán khái\" (灌溉 — tưới tiêu) | Mở khoá kiến thức | Biết 溉 mở khoá 灌溉 (tưới tiêu, irrigate), 灌溉渠 (kênh tưới), 沾溉 (thấm tươi, được hưởng lợi — nghĩa bóng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 溉 là chữ hình thanh: bộ 水 (rút thành 氵 — thuỷ) biểu nghĩa; 既 (ký) cho âm gài. Wiktionary ghi nghĩa là tưới nước, tưới tiêu, rửa. Không có ghi chú cổ đại chi tiết hơn trong anchor. Dùng chủ yếu trong 灌溉 (tưới tiêu ruộng đồng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tưới, rót; giặt, rửa", "Hạng Tần Suất (Jun Da)": "3517.0", "Tần Suất % (Jun Da)": "99.5551270672", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 既", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵既", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "既", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溉", "Unihan_Traditional (Chữ Phồn thể)": "溉", "Pinyin_Xie": "gài", "Âm Hán Việt_Xie": "cái, khái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động tưới tiêu trong nông nghiệp hoặc rửa sạch. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹊', '{"9000": "3518.0", "Chữ Trung Quốc": "鹊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 鹊 | thước | tượng hình | chim hỉ thước (chim bồ các, chim khách) | 鹊 là giản thể của 鵲. Dạng phồn thể 鵲 = 昔 (tích, biểu âm) + 鳥 (điểu, biểu nghĩa: chim). Bộ điểu (鸟) chỉ loài chim; 昔 cho âm gần qué. Chữ giản thể rút gọn 鳥→鸟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thước\": chim (鸟) kêu tiếng thước thước — 鹊 là chim hỉ thước báo điềm lành, bắc nhịp cầu Ô Thước trong huyền thoại Ngưu Lang. | Gương Hán-Việt | 鹊 xuất hiện trong 喜鹊 (hỉ thước — chim hỉ thước, điềm lành), 乌鹊 (ô thước — chim quạ thước xây cầu trong thần thoại). | Mở khoá kiến thức | Biết 鹊 mở khoá 喜鹊 (xǐquè — chim hỉ thước, biểu tượng may mắn) và huyền thoại Thất Tịch trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 鵲 là chữ hình thanh: 鳥 (chim) biểu nghĩa, 昔 biểu âm. Chim hỉ thước (喜鹊 — xỉ thước) là loài chim được coi là điềm lành trong văn hoá Trung Hoa, thường gắn với truyền thuyết Ngưu Lang Chức Nữ (ô thước cầu). Không có ghi chép giáp cốt/kim văn chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hỉ thước, chim khách, chim bồ các", "Hạng Tần Suất (Jun Da)": "3518.0", "Tần Suất % (Jun Da)": "99.5556433355", "GavinGrover_Once (Chiết tự trực tiếp)": "昔 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰昔鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹊", "Unihan_Traditional (Chữ Phồn thể)": "鵲", "Pinyin_Xie": "què", "Âm Hán Việt_Xie": "thước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài chim khách, thường xuất hiện trong các câu chuyện dân gian. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聿', '{"9000": "3519.0", "Chữ Trung Quốc": "聿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 聿 | Số nét | 6 | nét | 聿 | duật | tượng hình | tay cầm bút viết — hình ảnh gốc của chữ bút | 聿 là chữ tượng hình hoặc hội ý: hình bàn tay (又) cầm cây bút (𰀁). Là dạng nguyên gốc của 筆 (bút). Sau dùng làm hư từ trong văn ngôn (bèn, thì). Không có hai thành phần rời biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duật\": tay cầm bút — 聿 là hình gốc của cây bút 筆, sau dùng làm hư từ văn ngôn (bèn, thì, liền đó). | Gương Hán-Việt | Đọc Hán-Việt: duật. 聿 xuất hiện trong văn ngôn cổ như hư từ: 歲聿其莫 (năm bèn sắp tàn). Là bộ thủ của nhiều chữ: 律, 建, 肃. | Mở khoá kiến thức | Biết 聿 mở khoá nguồn gốc của 筆 (bút), và các chữ có bộ thủ 聿: 律 (luật), 建 (kiến), 肃 (túc).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 聿 là tượng hình (hoặc hội ý) — bàn tay (又) cầm bút lông (𰀁). Là dạng cổ của 筆 (bút). Sau được dùng như ký âm (jiǎ jiè) cho hư từ 聿 (bèn, thereupon) trong văn ngôn cổ. Giáp cốt, kim văn, đại triện và tiểu triện đều lưu lại hình dạng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "548.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình bàn tay năm ngón đang nắm dọc, cầm lấy một cây cọ (bút) để viết. Giải thích sự chuyển ý: Khắc họa trực tiếp công cụ dùng để viết chữ. Duật chính là cây bút.", "Nghĩa Tiếng Việt_Xie": "bèn, bui; cái bút", "Hạng Tần Suất (Jun Da)": "3519.0", "Tần Suất % (Jun Da)": "99.5561596039", "GavinGrover_Once (Chiết tự trực tiếp)": "⺺ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "聿", "Unihan_Traditional (Chữ Phồn thể)": "聿", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "duật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Phó từ | 副词 | Trợ từ | 助词 | Chữ này làm danh từ chỉ cây bút trong văn ngôn hoặc làm phó từ mang nghĩa bèn, liền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疙', '{"9000": "3520.0", "Chữ Trung Quốc": "疙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 8 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 乞 | khất | biểu âm | (cho âm gē) | 疙 = 疒(Nạch, biểu nghĩa: bệnh tật) + 乞 (Khất, biểu âm); chữ hình thanh. Bộ nạch chỉ liên quan đến bệnh trên da; 乞 cho âm gē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": bệnh (疒) khất cầu (乞) — ngật ngưỡng như cục bướu sần sùi trên da, khó chịu không yên. | Gương Hán-Việt | \"ngật\" ít dùng độc lập; 疙 chỉ xuất hiện trong 疙瘩 (cục bướu, vết sần) | Mở khoá kiến thức | Biết 疙 mở khoá 疙瘩 (cục bướu; khó giải quyết), 鸡皮疙瘩 (nổi da gà), 解开疙瘩 (tháo gỡ vướng mắc).", "Tự nguyên_Xie": "疙 là chữ hình thanh: bộ 疒 (nạch — bệnh) biểu nghĩa; 乞 (khất) cho âm gē. Wiktionary ghi âm gốc là yì (nghĩa cổ là đần độn); âm gē hiện đại chỉ dùng trong từ ghép như 疙瘩 (cục bướu, vết sần). Chữ không dùng độc lập, chỉ xuất hiện trong 疙瘩. Không có nguồn cổ đại chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngật đáp 疙瘩)", "Hạng Tần Suất (Jun Da)": "3520.0", "Tần Suất % (Jun Da)": "99.5566753554", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疙", "Unihan_Traditional (Chữ Phồn thể)": "疙", "Pinyin_Xie": "gē", "Âm Hán Việt_Xie": "ngật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong từ ghép để chỉ mụn nhọt hoặc nút thắt khó giải quyết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘑', '{"9000": "3521.0", "Chữ Trung Quốc": "蘑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 19 | nét | 蘑 | ma | tượng hình | nấm ăn được (蘑菇) | 蘑 chưa có nguồn Wiktionary. Bộ thảo (艹) gợi thực vật; phần còn lại biểu âm mó. Cấu trúc hình thanh không được xác nhận chính thức. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ma\": cỏ (艹) mọc như ma mọc ra từ đất — 蘑菇 là nấm, thứ tự nhiên mọc bí ẩn sau mưa. | Gương Hán-Việt | Đọc Hán-Việt: ma. 蘑 gần như chỉ dùng trong 蘑菇 (ma cô — nấm); không có từ Hán-Việt độc lập phổ biến. | Mở khoá kiến thức | Biết 蘑 mở khoá 蘑菇 (mógū — nấm ăn) — từ thực phẩm và ẩm thực quan trọng.", "Tự nguyên_Xie": "蘑 không có nguồn Wiktionary chi tiết. Bộ 艹 (thảo) có thể biểu nghĩa — loài thực vật; phần còn lại biểu âm. Chữ tạo muộn, chuyên dùng trong 蘑菇 (nấm). Chưa có nguồn học thuật, chưa thấy trong cổ văn. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ma cô 蘑菰)", "Hạng Tần Suất (Jun Da)": "3521.0", "Tần Suất % (Jun Da)": "99.557191107", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 磨", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹磨", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "磨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘑", "Unihan_Traditional (Chữ Phồn thể)": "蘑", "Pinyin_Xie": "mó", "Âm Hán Việt_Xie": "ma", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại nấm ăn được, thường dùng trong từ ghép ma cô. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睾', '{"9000": "3522.0", "Chữ Trung Quốc": "睾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 睾 | cao | tượng hình | tinh hoàn — dạng biến thể của 皋 chịu ảnh hưởng của 睪 | 睾 là dạng biến dạng của 皋 (cao — bờ đầm, vùng đất cao) do ảnh hưởng của 睪. Không có phân tích hình thanh/hội ý rõ ràng. Tiểu triện và lục thư thông còn lưu lại dạng biến thể này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": chữ biến dạng từ 皋 (vùng đất cao) — 睾丸 là tinh hoàn, thuật ngữ y học sản khoa nam giới. | Gương Hán-Việt | Đọc Hán-Việt: cao. 睾 gần như chỉ dùng trong thuật ngữ y học 睾丸 (cao hoàn — tinh hoàn). | Mở khoá kiến thức | Biết 睾 mở khoá 睾丸 (gāowán — tinh hoàn) và 睾丸素 (testosterone) trong thuật ngữ y sinh học.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary: 睾 là dạng biến dạng của 皋 (cao — bờ đầm) dưới ảnh hưởng hình thức của 睪 (tinh hoàn). Chữ tạo muộn, chỉ dùng trong thuật ngữ y học 睾丸 (cao hoàn — tinh hoàn). Lục thư thông còn lưu lại. Chưa có cổ văn giáp cốt/kim văn chính thức. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mỡ màng, nhẵn bóng", "Hạng Tần Suất (Jun Da)": "3522.0", "Tần Suất % (Jun Da)": "99.557705825", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 幸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱幸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "睾", "Unihan_Traditional (Chữ Phồn thể)": "睾", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường dùng làm danh từ trong các thuật ngữ y học hoặc tính từ mô tả sự trơn bóng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楷', '{"9000": "3523.0", "Chữ Trung Quốc": "楷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 皆 | giai | biểu âm | 楷 = 木 (Mộc, biểu nghĩa: cây, gỗ) + 皆 (Giai, biểu âm); chữ hình thanh. Bộ mộc gốc chỉ một loại cây gỗ (Pistacia chinensis); nghĩa mở rộng sang khuôn mẫu, thể chữ ngay ngắn (楷书).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giai\": cây (木) mọc thẳng như tất cả (皆) đều ngay ngắn — 楷 là khuôn mẫu mực thước, 楷书 là thể chữ chuẩn nhất. | Gương Hán-Việt | 楷 xuất hiện trong 楷书 (giai thư — chữ khải, thể chữ ngay ngắn), 楷模 (giai mô — hình mẫu, tấm gương). | Mở khoá kiến thức | Biết 楷 mở khoá 楷书 (kǎishū — chữ khải thư), 楷模 (kǎimó — hình mẫu gương mực) và thuật ngữ thư pháp Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 木 (cây) biểu nghĩa, 皆 biểu âm. Nghĩa gốc: cây hoàng liên mộc (Pistacia chinensis) — loài cây thẳng ngay, dùng làm biểu tượng cho người ngay thẳng. Từ đó mở rộng sang khuôn mẫu, mô hình, và thể chữ Hán ngay ngắn nhất (楷书). Tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây giai; khuôn phép; chữ viết ngay ngắn", "Hạng Tần Suất (Jun Da)": "3523.0", "Tần Suất % (Jun Da)": "99.5582195094", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楷", "Unihan_Traditional (Chữ Phồn thể)": "楷", "Pinyin_Xie": "kǎi", "Âm Hán Việt_Xie": "giai, khải", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ khuôn mẫu hoặc tính từ chỉ kiểu chữ viết chuẩn mực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酵', '{"9000": "3524.0", "Chữ Trung Quốc": "酵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 14 | nét | 酉 | dậu | biểu nghĩa | bình rượu, lên men | 孝 | hiếu | biểu âm | 酵 = 酉 (Dậu, biểu nghĩa: bình rượu, ủ men) + 孝 (Hiếu, biểu âm); chữ hình thanh. Bộ dậu chỉ quá trình lên men; 孝 cho âm gần jiào. Theo Wiktionary, 孝 (già + trẻ) gợi thêm ý niệm \"ủ lâu, lên men theo thời gian\".", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiếu\": bình rượu (酉) ủ với lòng hiếu thuận (孝 — già trẻ cùng nhau) — 酵 là men, sự lên men theo thời gian như con cháu chăm sóc cha mẹ. | Gương Hán-Việt | Đọc Hán-Việt: hiếu. 酵 xuất hiện trong 发酵 (phát hiếu — lên men), 酵母 (hiếu mẫu — men nấm, yeast). | Mở khoá kiến thức | Biết 酵 mở khoá 发酵 (fājiào — lên men, fermentation) và 酵母 (jiàomǔ — men nấm, nấm men bánh mì).", "Tự nguyên_Xie": "Chữ hình thanh: 酉 (bình rượu/ủ men) biểu nghĩa, 孝 biểu âm. Theo Wiktionary: 孝 gồm \"già + trẻ\", hàm ý ủ chín theo thời gian — lên men trong bình, tạo rượu. 酵 chỉ men vi sinh, quá trình lên men. Dùng trong 发酵 (phát men — lên men). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "men rượu", "Hạng Tần Suất (Jun Da)": "3524.0", "Tần Suất % (Jun Da)": "99.5587321603", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 孝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉孝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酵", "Unihan_Traditional (Chữ Phồn thể)": "酵", "Pinyin_Xie": "jiào", "Âm Hán Việt_Xie": "diếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ chất men hoặc kết hợp tạo động từ chỉ quá trình lên men. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茹', '{"9000": "3525.0", "Chữ Trung Quốc": "茹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 如 | như | biểu âm | 茹 = 艹 (Thảo, biểu nghĩa: cỏ, thực vật) + 如 (Như, biểu âm); chữ hình thanh. Bộ thảo chỉ loài thực vật; 如 cho âm gần rú. Nghĩa gốc: rễ cây, phần ăn được của thực vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhà\": rễ cỏ (艹) ăn như (如) người nhà nghèo — 茹 là ăn, ngậm nuốt khổ cay; 含辛茹苦 là chịu đựng gian khổ. | Gương Hán-Việt | 茹 xuất hiện trong 含辛茹苦 (hàm tân nhà khổ — ngậm đắng nuốt cay), 茹素 (nhà tố — ăn chay). | Mở khoá kiến thức | Biết 茹 mở khoá 含辛茹苦 (hánxīn rúkǔ — chịu đựng gian khổ cực nhọc) và 茹素 (rúsù — ăn chay).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 艹 (cỏ) biểu nghĩa, 如 biểu âm. 茹 nghĩa gốc là rễ cây, phần thực vật có thể ăn được. Mở rộng sang ăn (含辛茹苦 — ngậm đắng cay), chịu đựng. Tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rễ quấn; ăn; thối nát", "Hạng Tần Suất (Jun Da)": "3525.0", "Tần Suất % (Jun Da)": "99.5592448111", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 如", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹如", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "如", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茹", "Unihan_Traditional (Chữ Phồn thể)": "茹", "Pinyin_Xie": "rú", "Âm Hán Việt_Xie": "như", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ trong văn viết cổ với nghĩa là ăn hoặc chịu đựng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锌', '{"9000": "3526.0", "Chữ Trung Quốc": "锌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锌 | tân | tượng hình | kim loại kẽm (Zn) — giản thể của 鋅 | 锌 là giản thể của 鋅. Dạng phồn thể 鋅 = 釒 (kim, biểu nghĩa: kim loại) + 辛 (tân, biểu âm). Bộ kim chỉ kim loại; 辛 cho âm gần xīn. Chữ giản thể thay 釒→钅.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": kim loại (钅) đứng thứ tân (辛) — 锌 là kẽm, nguyên tố kim loại quan trọng trong luyện kim và y học. | Gương Hán-Việt | 锌 xuất hiện trong 锌合金 (tân hợp kim — hợp kim kẽm), 补锌 (bổ tân — bổ sung kẽm). | Mở khoá kiến thức | Biết 锌 mở khoá 补锌 (bǔxīn — bổ sung kẽm), 锌合金 (xīn héjīn — hợp kim kẽm) trong hoá học và dinh dưỡng.", "Tự nguyên_Xie": "锌 là giản thể của 鋅 (kim + tân): bộ kim (kim loại) biểu nghĩa, 辛 biểu âm. 锌 là ký tự phiên âm cho nguyên tố Zinc (kẽm, Zn) — chữ tạo trong thời cận đại để phiên dịch thuật ngữ hoá học phương Tây. Chữ tạo muộn, không có cổ văn. Chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kẽm, Zn", "Hạng Tần Suất (Jun Da)": "3526.0", "Tần Suất % (Jun Da)": "99.559757462", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锌", "Unihan_Traditional (Chữ Phồn thể)": "鋅", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các hợp chất chứa kẽm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滇', '{"9000": "3527.0", "Chữ Trung Quốc": "滇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 水 | thủy | biểu nghĩa | nước | 真 | chân | biểu âm | 滇 = 氵/水 (Thủy, biểu nghĩa: nước) + 真 (Chân, biểu âm); chữ hình thanh. Bộ thủy gợi địa danh liên quan đến vùng nước; 真 cho âm gần diān. 滇 là tên cổ của tỉnh Vân Nam.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điền\": nước (水) chân thật (真) của đất Điền — 滇 là tên cũ của Vân Nam, vùng đất nhiều hồ nước. | Gương Hán-Việt | 滇 xuất hiện trong 滇池 (Điền Trì — hồ Điền lớn nhất Vân Nam), 滇军 (Điền quân — quân đội Vân Nam thời Dân Quốc). | Mở khoá kiến thức | Biết 滇 mở khoá cách gọi tắt 滇 cho Vân Nam trong văn học, lịch sử và địa lý Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 水 (nước) biểu nghĩa, 真 biểu âm. 滇 là tên gọi cổ của vương quốc Điền (滇国), nay là tỉnh Vân Nam. Khu vực này có hồ Điền Trì (滇池) lớn — bộ thủy phản ánh đặc điểm địa lý nhiều hồ. Tiểu triện và lục thư thông còn lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tỉnh Điền (tỉnh Vân Nam)", "Hạng Tần Suất (Jun Da)": "3527.0", "Tần Suất % (Jun Da)": "99.5602695961", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "滇", "Unihan_Traditional (Chữ Phồn thể)": "滇", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ riêng để chỉ địa danh hoặc các sự vật liên quan đến Vân Nam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辗', '{"9000": "3528.0", "Chữ Trung Quốc": "辗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 14 | nét | 車 | xa | biểu nghĩa | xe | 㞋 | biểu âm | 辗 = 車/车 (Xa, biểu nghĩa: xe) + 㞋 (biểu âm); chữ hình thanh. Bộ xa chỉ chuyển động bánh xe; nghĩa là lăn bánh, nghiền qua lại. Có hai từ nguyên: dạng cổ nhất từ 𨋚 (xe + 㞋), dạng thứ hai từ 車 + 展.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triển\": bánh xe (車) triển (展) khai lăn — 辗转 là trằn trọc, lăn qua lại không yên giấc. | Gương Hán-Việt | 辗 xuất hiện trong 辗转 (triển chuyển — trằn trọc, lăn qua lại), 辗转反侧 (trằn trọc không ngủ được). | Mở khoá kiến thức | Biết 辗 mở khoá 辗转反侧 (niǎnzhuǎn fǎncè — trằn trọc không ngủ) và 辗转 (niǎnzhuǎn — qua nhiều đường vòng).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh, hai từ nguyên: (1) Biến dạng từ 𨋚: 車 (xe) + 㞋 (biểu âm); (2) 車 + 展 (biểu âm). Nghĩa là nghiền/lăn bánh xe qua — như bánh xe lăn qua đất. 辗转 (辗轉 — lăn trở, trằn trọc) là cụm dùng phổ biến nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quay nghiêng, quay nửa vành", "Hạng Tần Suất (Jun Da)": "3528.0", "Tần Suất % (Jun Da)": "99.5607812133", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 展", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车展", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "展", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辗", "Unihan_Traditional (Chữ Phồn thể)": "輾", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ miêu tả hành động trằn trọc hoặc nghiền nát vật thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纂', '{"9000": "3529.0", "Chữ Trung Quốc": "纂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 20 | nét | 纂 | toản | tượng hình | biên soạn sách, búi tóc | 纂 chưa có phân tích hình thanh/hội ý rõ trong Wiktionary. Bộ 糸/纟 (mịch — tơ, sợi) gợi ý liên kết, tập hợp; phần trên gợi âm zuǎn. Tiểu triện còn lưu lại. Cấu trúc chính xác chưa được xác nhận từ nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\": sợi tơ (糸) kết lại thành cuộn — 纂 là biên soạn, kết hợp nhiều nguồn thành một bộ sách; cũng là búi tóc cuộn tròn. | Gương Hán-Việt | Đọc Hán-Việt: toản. 纂 xuất hiện trong 编纂 (biên toản — biên soạn), 纂修 (toản tu — tu chỉnh biên soạn), 纂辑 (toản tập — tập hợp biên soạn). | Mở khoá kiến thức | Biết 纂 mở khoá 编纂 (biānzuǎn — biên soạn, biên tập) và thuật ngữ học thuật xuất bản.", "Tự nguyên_Xie": "Tiểu triện | 纂 chưa có nguồn Wiktionary chi tiết. Bộ 糸 (tơ sợi) biểu nghĩa — tập hợp các sợi như tập hợp tài liệu. Nghĩa: biên soạn, tập hợp sách vở; cũng nghĩa là búi tóc. Tiểu triện lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây lụa đỏ; biên soạn sách", "Hạng Tần Suất (Jun Da)": "3529.0", "Tần Suất % (Jun Da)": "99.5612928306", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "纂", "Unihan_Traditional (Chữ Phồn thể)": "纂", "Pinyin_Xie": "zuǎn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chủ yếu dùng làm động từ chỉ hoạt động biên soạn sách vở hoặc tài liệu lịch sử. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('圭', '{"9000": "3530.0", "Chữ Trung Quốc": "圭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 6 | nét | 士 | sĩ | tượng hình | hình ngọc khuê — hai chiếc bảng lễ nghi chồng lên nhau | 士 | sĩ | tượng hình | 圭 = 士 + 士 (hai chữ sĩ chồng lên nhau); chữ tượng hình theo kiểu nhân gấp đôi (倍文). Hình ảnh hai tấm ngọc khuê (ritual jade tablet) xếp chồng — không liên quan đến 土 (thổ) dù hình dáng tương tự. Đây là chữ tượng hình không phải hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\": hai sĩ (士+士) chồng lên — 圭 là tấm ngọc khuê dài và nhọn đầu, vật phẩm lễ nghi quý giá của quan lại triều đình cổ. | Gương Hán-Việt | 圭 xuất hiện trong 圭臬 (khuê nghê — chuẩn tắc, quy tắc), 圭表 (khuê biểu — đồng hồ mặt trời cổ đại). | Mở khoá kiến thức | Biết 圭 mở khoá 圭臬 (guīniè — quy tắc chuẩn mực) và thuật ngữ thiên văn học, văn hoá lễ nghi cổ Trung Hoa.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary: 圭 = 士 + 士 — hai tấm ngọc lễ nghi (có thể là hai lưỡi rìu nghi lễ bằng ngọc) xếp chồng lên nhau. Không liên quan đến 土 dù dân gian hay hiểu vậy. 圭 là tấm ngọc khuê — công cụ thiên văn cổ đại và vật phẩm lễ nghi của quan lại. Giáp cốt, kim văn, bạch thư và tiểu triện đều lưu lại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "875.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thổ (032)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Thổ (số 032 - đất) viết chồng lên nhau. Thời cổ đại, thiên tử phong vua chư hầu thì ban cho Ngọc Khuê và đất đai cần cai quản. Chữ Khuê gồm hai chữ Thổ mang ý nghĩa cai quản đất đai. Giải thích sự chuyển ý: Đây là chữ Hội ý. Khuê là ngọc khuê.", "Nghĩa Tiếng Việt_Xie": "ngọc khuê; nguyên tố silic, Si", "Hạng Tần Suất (Jun Da)": "3530.0", "Tần Suất % (Jun Da)": "99.5618034143", "GavinGrover_Once (Chiết tự trực tiếp)": "土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "圭", "Unihan_Traditional (Chữ Phồn thể)": "圭", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại ngọc quý thời xưa hoặc dụng cụ đo lường cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('幔', '{"9000": "3531.0", "Chữ Trung Quốc": "幔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 14 | nét | 幔 | mạn | tượng hình | màn che, rèm, màn sân khấu | 幔 chưa có phân tích cấu trúc rõ trong Wiktionary. Bộ cân (巾 — vải) biểu nghĩa — vật bằng vải; phần còn lại biểu âm màn. Tiểu triện còn lưu lại hình dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": tấm vải (巾) rủ xuống mạn mạn — 幔 là màn che, rèm vải lớn treo trong phòng hoặc trên sân khấu. | Gương Hán-Việt | 幔 xuất hiện trong 帷幔 (vi mạn — màn rèm phòng the), 帐幔 (trướng mạn — màn trướng, rèm lều). | Mở khoá kiến thức | Biết 幔 mở khoá 帷幔 (wéimàn — màn rèm phòng ngủ) và 帐幔 (zhàngmàn — màn trướng quân sự/sân khấu).", "Tự nguyên_Xie": "Tiểu triện | 幔 không có nguồn Wiktionary chi tiết. Bộ 巾 (vải, khăn) có thể biểu nghĩa — đồ vật bằng vải; phần còn lại biểu âm màn. Nghĩa: màn che, rèm lớn, màn vải treo trong phòng hoặc trên sân khấu. Tiểu triện lưu lại. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màn che, rèm", "Hạng Tần Suất (Jun Da)": "3531.0", "Tần Suất % (Jun Da)": "99.562313998", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "幔", "Unihan_Traditional (Chữ Phồn thể)": "幔", "Pinyin_Xie": "màn", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại rèm cửa hoặc màn che trong nhà. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褒', '{"9000": "3532.0", "Chữ Trung Quốc": "褒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 15 | nét | 衣 | y | biểu nghĩa | áo, vải | 保 | bảo | biểu âm | 褒 = 衣 (Y, biểu nghĩa: áo rộng, vải) + 保 (Bảo, biểu âm); chữ hình thanh. Bộ y gợi ý nghĩa về áo rộng; 保 cho âm gần bāo. Nghĩa gốc là áo rộng, sau mở rộng sang khen ngợi, biểu dương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": áo rộng (衣) bao bọc (保) — 褒 là khen ngợi, che chở bằng lời khen; đối lập với 贬 (chê). | Gương Hán-Việt | 褒 xuất hiện trong 褒奖 (bao tưởng — khen thưởng), 褒贬 (bao biếm — khen chê), 褒义词 (bao nghĩa từ — từ khen ngợi). | Mở khoá kiến thức | Biết 褒 mở khoá 褒奖 (bāojiǎng — khen thưởng), 褒贬 (bāobian — khen chê) và từ ngữ học tiếng Trung.", "Tự nguyên_Xie": "Chữ hình thanh từ phồn thể 襃: 衣 (áo) biểu nghĩa, 保 biểu âm. Nghĩa gốc là áo rộng lớn — hình ảnh người mặc áo rộng được ưu ái. Từ đó mở rộng sang nghĩa khen ngợi, biểu dương (褒奖). Đối lập với 贬 (biếm — chê trách). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khen ngợi, biểu dương; áo rộng", "Hạng Tần Suất (Jun Da)": "3532.0", "Tần Suất % (Jun Da)": "99.562824065", "GavinGrover_Once (Chiết tự trực tiếp)": "衣 + 保", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴衣保", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "保", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衣", "Unihan_Simplified (Chữ Giản thể)": "褒", "Unihan_Traditional (Chữ Phồn thể)": "褒", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ chỉ sự khen ngợi hoặc tính từ chỉ trang phục rộng rãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揍', '{"9000": "3533.0", "Chữ Trung Quốc": "揍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 扌 | thủ | biểu nghĩa | tay | 奏 | tấu | biểu âm | (cho âm zòu) | 揍 = 扌(Thủ, biểu nghĩa: tay) + 奏 (Tấu, biểu âm); chữ hình thanh. Tay là công cụ đánh; 奏 cho âm zòu và đồng âm Hán-Việt tấu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tấu\": tay (扌) tấu nhạc bằng cú đấm — tấu nện, đánh cho một trận đau. | Gương Hán-Việt | \"tấu\" trong 奏 (tấu nhạc); 揍 mang nghĩa bạo lực hơn — đánh nện | Mở khoá kiến thức | Biết 揍 mở khoá 揍人 (đánh người), 被揍 (bị đánh), 揍得很惨 (bị đánh thảm).", "Tự nguyên_Xie": "揍 là chữ tạo muộn, không có ghi chép trong giáp cốt hay kim văn. Cấu trúc hình thanh: 扌(thủ — tay) biểu nghĩa; 奏 (tấu) cho âm zòu. Wiktionary không có mục riêng cho 揍. Nghĩa là đánh, đấm, nện; cũng có nghĩa đập vỡ. Chữ tạo muộn, chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh; nện; choảng (người); đánh vỡ; đập vỡ; làm vỡ", "Hạng Tần Suất (Jun Da)": "3533.0", "Tần Suất % (Jun Da)": "99.5633336151", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "揍", "Unihan_Traditional (Chữ Phồn thể)": "揍", "Pinyin_Xie": "zòu", "Âm Hán Việt_Xie": "thấu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ khẩu ngữ đứng trước tân ngữ chỉ người hoặc vật bị đánh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zòu | / | đánh, đấm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Chiến tranh và cuộc đấu tranh II | HSK | HSK 6 | · | Mối quan hệ II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诽', '{"9000": "3534.0", "Chữ Trung Quốc": "诽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 讠 | biểu nghĩa | ngôn ngữ, lời nói (bộ ngôn giản thể) | 非 | phi | biểu âm | (cho âm fěi, đồng âm Hán-Việt) | 诽 = 讠(bộ ngôn giản thể, biểu nghĩa: lời nói) + 非 (Phi, biểu âm); chữ hình thanh. Lời nói sai trái là lời nói xấu; 非 cho âm fěi và Hán-Việt phi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phỉ\": lời nói (讠) phi lý (非) — phỉ báng, nói những điều phi sự thật để hại người. | Gương Hán-Việt | \"phỉ\" trong \"phỉ báng\" (诽谤 — vu khống), \"phỉ thị\" (khinh bỉ) | Mở khoá kiến thức | Biết 诽 mở khoá 诽谤 (vu khống, phỉ báng), 诽谤罪 (tội vu khống).", "Tự nguyên_Xie": "Tiểu triện | 诽 là dạng giản thể của 誹; theo Wiktionary xem thêm mục 誹. Cấu trúc: bộ 言 (rút thành 讠 — ngôn) biểu nghĩa, chỉ loại lời nói; 非 (phi) cho âm fěi. Nghĩa là nói xấu, vu khống, phỉ báng. Dùng chủ yếu trong 诽谤 (vu khống, phỉ báng). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói xấu", "Hạng Tần Suất (Jun Da)": "3534.0", "Tần Suất % (Jun Da)": "99.5638426485", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诽", "Unihan_Traditional (Chữ Phồn thể)": "誹", "Pinyin_Xie": "fěi", "Âm Hán Việt_Xie": "phỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ để chỉ hành vi nói xấu hoặc bôi nhọ người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('倔', '{"9000": "3535.0", "Chữ Trung Quốc": "倔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 屈 | khuất | biểu âm | (cho âm jué) | 倔 = 亻(Nhân, biểu nghĩa: người) + 屈 (Khuất, biểu âm); chữ hình thanh. Người có tính cứng đầu; 屈 cho âm jué (hoặc juè — cứng nhắc, ngoan cố).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quật\": người (亻) không chịu khuất (屈) — quật cường, cứng đầu không chịu nhún. | Gương Hán-Việt | \"quật\" trong \"quật cường\" (倔强 — bướng bỉnh, kiên cường không khuất); 屈 (khuất) trong 屈服 (khuất phục) | Mở khoá kiến thức | Biết 倔 mở khoá 倔强 (bướng bỉnh, cứng đầu), 倔脾气 (tính bướng), 倔头倔脑 (đần đần, cứng nhắc).", "Tự nguyên_Xie": "倔 là chữ hình thanh: 人 (rút thành 亻 — nhân) biểu nghĩa; 屈 (khuất) cho âm jué. Theo Wiktionary, nghĩa là bướng bỉnh, ngoan cố. Lý thú là 屈 (khuất) có nghĩa là cúi xuống, chịu khuất — người 倔 ngược lại, không chịu khuất phục. Tiếng Quảng còn có nghĩa không nhọn (không sắc). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cứng cỏi, ương ngạnh", "Hạng Tần Suất (Jun Da)": "3535.0", "Tần Suất % (Jun Da)": "99.5643516818", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 屈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻屈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "倔", "Unihan_Traditional (Chữ Phồn thể)": "倔", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ hoặc sau phó từ chỉ mức độ để miêu tả tính cách ngang ngạnh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | juè | / | bướng bỉnh | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính cách tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腓', '{"9000": "3536.0", "Chữ Trung Quốc": "腓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt, cơ thể | 非 | phi | biểu âm | 腓 = 肉 (Nhục, biểu nghĩa: thịt/cơ thể) + 非 (Phi, biểu âm); chữ hình thanh. Phần 肉 cho biết nghĩa liên quan đến cơ thể, phần 非 cho âm đọc gần với féi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phì\" (hoặc \"phi\"): cơ 肉 ở phần chân sau — bắp chân phình ra như chữ 非 nằm ngang. | Gương Hán-Việt | phi trong các tên giải phẫu cổ điển như ''tứ phì'' (tứ chi) | Mở khoá kiến thức | Biết 腓 mở khoá các thuật ngữ y học cổ truyền về cơ bắp chân và bệnh tê liệt chi dưới.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 肉 (nhục) biểu nghĩa chỉ thịt/cơ thể, 非 (phi) biểu âm. Tiểu triện đã ghi nhận cấu trúc này. 腓 chỉ bắp chân — phần cơ sau cẳng chân. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bắp chân; đau ốm; lành", "Hạng Tần Suất (Jun Da)": "3536.0", "Tần Suất % (Jun Da)": "99.5648601984", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腓", "Unihan_Traditional (Chữ Phồn thể)": "腓", "Pinyin_Xie": "féi", "Âm Hán Việt_Xie": "phì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ trong y học để chỉ phần bắp chân hoặc làm động từ trong văn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颉', '{"9000": "3537.0", "Chữ Trung Quốc": "颉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 12 | nét | 吉 | cát | biểu âm | 頁 | hiệt | biểu nghĩa | đầu, trang | 颉 = 吉 (Cát, biểu âm) + 頁 (biểu nghĩa: đầu/cổ); chữ hình thanh. Phần 頁 chỉ đầu hoặc cổ, 吉 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiệt\": cái đầu 頁 ngẩng lên cao như chim bay — 颉 chỉ sự bay bổng, ngước lên. | Gương Hán-Việt | hiệt trong ''Thương Hiệt'' (倉頡) — nhân vật huyền thoại sáng tạo chữ Hán | Mở khoá kiến thức | Biết 颉 giúp nhận ra tên 倉頡 (Thương Hiệt) trong lịch sử chữ viết Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: 吉 (cát) biểu âm, 頁 biểu nghĩa chỉ đầu/cổ. Dạng cổ 頡 ghi nhận trong kim văn và tiểu triện. 颉 có nghĩa gốc là bay vút lên hoặc ngước đầu lên; thường gặp trong danh từ riêng Thương Hiệt (倉頡) — người được truyền thuyết cho là đã sáng tạo chữ Hán. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bay bổng lên", "Hạng Tần Suất (Jun Da)": "3537.0", "Tần Suất % (Jun Da)": "99.565368715", "GavinGrover_Once (Chiết tự trực tiếp)": "吉 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰吉页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颉", "Unihan_Traditional (Chữ Phồn thể)": "頡", "Pinyin_Xie": "jié", "Âm Hán Việt_Xie": "hiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chủ yếu xuất hiện trong các từ ghép cổ hoặc tên riêng chứ ít khi đứng độc lập làm vị ngữ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锄', '{"9000": "3538.0", "Chữ Trung Quốc": "锄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 12 | nét | 锄 | trừ | tượng hình | cái cuốc, công cụ làm đất bằng kim loại | 锄 là dạng giản thể của 鋤. Chữ gốc 鋤 gồm 釒 (kim loại) + phần biểu âm, là chữ hình thanh. Trong dạng giản thể, cấu trúc bị rút gọn nhưng vẫn có bộ 钅 (kim).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trừ\": cái cuốc bằng kim 钅 dùng để trừ (diệt) cỏ — 锄 vừa là cuốc vừa nghĩa là loại bỏ. | Gương Hán-Việt | trừ trong ''trừ hại'' (diệt trừ mầm hại), ''trừ bạo'' (diệt ác) | Mở khoá kiến thức | Biết 锄 mở khoá nghĩa động từ ''trừ khử, nhổ bỏ'' trong văn ngôn và tiếng Hán hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 锄 là giản thể của 鋤, vốn là chữ hình thanh với bộ 釒 (kim) biểu nghĩa chỉ đồ vật bằng kim loại. Chữ chỉ cái cuốc — công cụ làm đất nông nghiệp. Tiểu triện và lục thư thông đã ghi nhận nhiều dạng viết. Ngoài nghĩa công cụ, 锄 còn có nghĩa mở rộng là nhổ bỏ, diệt trừ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bừa", "Hạng Tần Suất (Jun Da)": "3538.0", "Tần Suất % (Jun Da)": "99.5658756812", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 助", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅助", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "助", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锄", "Unihan_Traditional (Chữ Phồn thể)": "鋤", "Pinyin_Xie": "chú", "Âm Hán Việt_Xie": "sừ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Có thể làm danh từ chỉ công cụ lao động hoặc làm động từ chỉ hành động làm cỏ và vun gốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗔', '{"9000": "3539.0", "Chữ Trung Quốc": "嗔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗔 | xin | tượng hình | miệng nổi giận, mặt phồng lên vì tức | 嗔 có bộ 口 (khẩu) bên trái và 真 bên phải — cấu trúc hình thanh: 口 biểu nghĩa chỉ miệng/lời nói, 真 gần âm. Wiktionary không ghi cấu trúc compound rõ ràng, nhưng phân tích tự dạng cho thấy đây là chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xin\": cái miệng 口 trương lên — 嗔 là vẻ mặt nổi cáu, mắng người khác. | Gương Hán-Việt | xin trong Phật học ''sân'' (嗔) — một trong tam độc tham-sân-si | Mở khoá kiến thức | Biết 嗔 mở khoá thuật ngữ Phật giáo về tam độc và mô tả cảm xúc tức giận trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 嗔 không có nguồn Wiktionary chi tiết về cấu trúc compound. Dựa vào tự dạng: bộ 口 (khẩu) biểu nghĩa chỉ lời nói/biểu đạt, phần còn lại gần với 真 (chân) gợi âm. Chữ chỉ trạng thái nổi giận, mắng nhiếc; trong tiếng Phật giáo còn nghĩa là sân (một trong tam độc: tham-sân-si). Chưa có nguồn học thuật rõ ràng về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nổi cáu", "Hạng Tần Suất (Jun Da)": "3539.0", "Tần Suất % (Jun Da)": "99.5663816138", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 真", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口真", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "真", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗔", "Unihan_Traditional (Chữ Phồn thể)": "嗔", "Pinyin_Xie": "chēn", "Âm Hán Việt_Xie": "sân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ thể hiện thái độ giận hờn hoặc trách móc người khác trong giao tiếp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磺', '{"9000": "3540.0", "Chữ Trung Quốc": "磺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 16 | nét | 石 | thạch | biểu nghĩa | đá, khoáng vật | 黃 | hoàng | biểu âm | 磺 = 石 (Thạch, biểu nghĩa: đá/khoáng vật) + 黃 (biểu âm); chữ hình thanh. Phần 石 cho biết đây là khoáng chất, phần 黃 (hoàng) cho âm đọc huáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàng\": khoáng thạch 石 màu vàng (黃) — 磺 là lưu huỳnh, chất khoáng màu vàng. | Gương Hán-Việt | hoàng trong ''lưu hoàng'' (硫磺) — lưu huỳnh; hoàng = vàng | Mở khoá kiến thức | Biết 磺 mở khoá tên hóa chất và khoáng chất có gốc ''hoàng'' trong tiếng Hán-Việt.", "Tự nguyên_Xie": "Chữ hình thanh: 石 (thạch) biểu nghĩa chỉ đá/khoáng vật, 黃 biểu âm. 磺 chỉ lưu huỳnh — nguyên tố hóa học màu vàng dạng bột, có mùi hắc đặc trưng. Tên tiếng Việt ''lưu huỳnh'' cũng phản ánh màu vàng (hoàng/huỳnh = vàng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lưu huỳnh", "Hạng Tần Suất (Jun Da)": "3540.0", "Tần Suất % (Jun Da)": "99.5668870297", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 黄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石黄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "黄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磺", "Unihan_Traditional (Chữ Phồn thể)": "磺", "Pinyin_Xie": "huáng", "Âm Hán Việt_Xie": "hoàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ liên kết trong các thuật ngữ hóa học và y học để chỉ hợp chất chứa lưu huỳnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攒', '{"9000": "3541.0", "Chữ Trung Quốc": "攒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 19 | nét | 扌 | thủ | biểu nghĩa | tay | 赞 | tán | biểu âm | (cho âm zǎn) | 攒 = 扌(Thủ, biểu nghĩa: tay) + 赞 (Tán, biểu âm); chữ hình thanh. Tay gom góp; 赞 cho âm zǎn. Phồn thể 攢 dùng 贊 thay vì 赞.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": tay (扌) tán tụ toàn bộ — toàn góp, tích lũy từng xu một cho đầy đủ. | Gương Hán-Việt | \"toàn\" ít dùng độc lập; 攒 dùng trong 攒钱 (dành dụm tiền), 攒劲 (tập trung sức) | Mở khoá kiến thức | Biết 攒 mở khoá 攒钱 (để dành tiền), 攒劲 (tập trung sức lực), 攒动 (cựa quậy đông đúc).", "Tự nguyên_Xie": "攒 (phồn thể 攢) là chữ hình thanh: 手 (rút thành 扌 — thủ) biểu nghĩa; 贊/赞 (tán) cho âm. Wiktionary không có ghi chú chi tiết về nguồn gốc. Nghĩa âm zǎn là tích góp, dành dụm (tiền bạc); nghĩa âm cuán là tụ lại, tập hợp đông. Chưa có nguồn học thuật xác nhận thêm. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họp lại, tích góp", "Hạng Tần Suất (Jun Da)": "3541.0", "Tần Suất % (Jun Da)": "99.5673919288", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 赞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌赞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攒", "Unihan_Traditional (Chữ Phồn thể)": "攢", "Pinyin_Xie": "zǎn", "Âm Hán Việt_Xie": "toản, toàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ tiền bạc hoặc đồ vật để biểu thị sự tích lũy dần dần. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zǎn | / | tích lũy | / | zǎn | / | tiết kiệm | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sự giàu có và nghèo đói | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘩', '{"9000": "3542.0", "Chữ Trung Quốc": "瘩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 14 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 荅 | đáp | biểu âm | (cho âm da/dá) | 瘩 = 疒(Nạch, biểu nghĩa: bệnh) + 荅 (Đáp, biểu âm); chữ hình thanh. Bộ nạch chỉ bệnh ngoài da; 荅 cho âm da. Chữ hậu khởi tự (tạo muộn), theo Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đáp\": bệnh (疒) đáp xuống da — đáp vào thành cục bướu, vết sần khó chịu. | Gương Hán-Việt | \"đáp\" trong \"ngật đáp\" (疙瘩 — cục bướu, vết sần); 荅 (đáp) liên quan đến đậu nhỏ | Mở khoá kiến thức | Biết 瘩 mở khoá 疙瘩 (cục bướu, vướng mắc), 麻疙瘩 (cục sần ngứa ngáy), 面疙瘩 (bánh bột ghẹo).", "Tự nguyên_Xie": "瘩 là chữ hậu khởi tự (後起字 — tạo muộn), theo Wiktionary. Cấu trúc hình thanh: bộ 疒 (nạch — bệnh) biểu nghĩa; 荅 (đáp) cho âm da. Nghĩa là mụn, cục sần trên da; chỉ dùng trong 疙瘩 (cục bướu, vết sần) và các từ ghép tương tự. Không có nguồn cổ đại; đây là chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngật đáp 疙瘩)", "Hạng Tần Suất (Jun Da)": "3542.0", "Tần Suất % (Jun Da)": "99.5678952775", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 荅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒荅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "荅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘩", "Unihan_Traditional (Chữ Phồn thể)": "瘩", "Pinyin_Xie": "da", "Âm Hán Việt_Xie": "đáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác tạo thành danh từ chỉ các nốt mụn trên da hoặc trạng thái lo âu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('雳', '{"9000": "3543.0", "Chữ Trung Quốc": "雳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 12 | nét | 雳 | lịch | tượng hình | tiếng sấm vang rền | 雳 là giản thể của 靂. Chữ gốc 靂 gồm 雨 (vũ: mưa) + 歷 biểu âm — chữ hình thanh chỉ tiếng sấm nổ lớn. Trong giản thể, 歷 được rút thành 历, vẫn giữ bộ 雨.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": mưa 雨 nổ như lịch — 雳 là tiếng sét vang trời trong cụm 霹雳. | Gương Hán-Việt | lịch trong ''phích lịch'' (霹雳) — sấm sét, tiếng nổ lớn | Mở khoá kiến thức | Biết 雳 mở khoá từ 霹雳 (phích lịch: sét đánh) và các thành ngữ về sấm sét.", "Tự nguyên_Xie": "雳 là giản thể của 靂, chữ hình thanh với bộ 雨 (vũ) biểu nghĩa chỉ hiện tượng thời tiết, và 歷/历 biểu âm. 雳 thường xuất hiện trong từ 霹雳 (phích lịch) — sấm sét. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phích lịch, tích lịch 霹靂,霹靋,霹雳)", "Hạng Tần Suất (Jun Da)": "3543.0", "Tần Suất % (Jun Da)": "99.5683986262", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "雳", "Unihan_Traditional (Chữ Phồn thể)": "靂", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ khác để làm danh từ chỉ tiếng sấm sét lớn hoặc sự việc xảy ra đột ngột. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吆', '{"9000": "3544.0", "Chữ Trung Quốc": "吆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 6 | nét | 吆 | yêu | tượng hình | miệng hét to, tiếng gào thét | 吆 có bộ 口 (khẩu: miệng) — chữ chỉ âm thanh phát ra từ miệng. Wiktionary không ghi cấu trúc compound; dựa vào tự dạng: 口 biểu nghĩa, phần còn lại (乃 hoặc 幺) gợi âm. Chữ tượng hình âm thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêu\": miệng 口 hét to — 吆 là tiếng quát tháo, gào thét hoặc hô hào. | Gương Hán-Việt | yêu trong ''hô yêu'' — tiếng hô to khi làm việc tập thể | Mở khoá kiến thức | Biết 吆 mở khoá từ 吆喝 (yāohe: rao hàng, hô hào) thường gặp trong văn miêu tả chợ búa.", "Tự nguyên_Xie": "吆 không có phân tích cấu trúc rõ ràng trong Wiktionary. Bộ 口 (khẩu) chỉ lời nói/tiếng hét. Chữ dùng để ghi tiếng hô hét, gào thét — đặc biệt trong các bài hát lao động hoặc tiếng rao hàng ngoài chợ. Chưa có nguồn học thuật về nguồn gốc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng quát tháo, tiếng gào thét", "Hạng Tần Suất (Jun Da)": "3544.0", "Tần Suất % (Jun Da)": "99.5689014582", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 幺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口幺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吆", "Unihan_Traditional (Chữ Phồn thể)": "吆", "Pinyin_Xie": "yāo", "Âm Hán Việt_Xie": "yêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước các từ chỉ hành động rao hàng hoặc quát mắng gia súc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悚', '{"9000": "3545.0", "Chữ Trung Quốc": "悚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 悚 | tủng | tượng hình | tâm trạng sợ hãi, kinh khiếp | 悚 có bộ 忄(tâm: tim/tâm trạng) bên trái — chữ chỉ cảm xúc sợ hãi. Phần bên phải gần với 束 gợi âm. Wiktionary liệt kê nhiều phát âm phương ngữ nhưng không ghi cấu trúc compound cụ thể. Chữ tạo muộn (lục thư thông).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tủng\": tâm trạng 忄 co rúm lại — 悚 là sợ đến nỗi mao cốc tủng nhiên (lông tóc dựng đứng). | Gương Hán-Việt | tủng trong ''mao cốc tủng nhiên'' (毛骨悚然) — kinh hoàng, rùng mình | Mở khoá kiến thức | Biết 悚 mở khoá thành ngữ 毛骨悚然 và các từ miêu tả kinh sợ trong văn học.", "Tự nguyên_Xie": "Lục thư thông | 悚 không có phân tích compound rõ ràng trong Wiktionary. Bộ 忄(tâm) biểu nghĩa chỉ cảm xúc/tâm lý. Phần còn lại gợi âm sǒng. Chữ chỉ trạng thái sợ hãi kinh khiếp, thường gặp trong thành ngữ 毛骨悚然 (lông tóc dựng đứng vì sợ). Chữ tạo muộn, chưa có trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ hãi, kinh khiếp", "Hạng Tần Suất (Jun Da)": "3545.0", "Tần Suất % (Jun Da)": "99.5694042901", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 束", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄束", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悚", "Unihan_Traditional (Chữ Phồn thể)": "悚", "Pinyin_Xie": "sǒng", "Âm Hán Việt_Xie": "tủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ hoặc động từ trong văn viết để miêu tả tâm trạng hoảng sợ trước sự việc đáng sợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('墩', '{"9000": "3546.0", "Chữ Trung Quốc": "墩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 15 | nét | 土 | thổ | biểu nghĩa | đất | 敦 | đôn | biểu âm | 墩 = 土 (Thổ, biểu nghĩa: đất) + 敦 (Đôn, biểu âm); chữ hình thanh. Phần 土 cho biết đây là vật thể liên quan đến đất/nền, phần 敦 cho âm đọc dūn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôn\": đất 土 đắp cao lên thành đôn — 墩 là ụ đất, cục đá vững chắc. | Gương Hán-Việt | đôn trong ''trụ đôn'' (桥墩: trụ cầu), ''thạch đôn'' (đôn đá) | Mở khoá kiến thức | Biết 墩 mở khoá từ 桥墩 (trụ cầu), 树墩 (gốc cây), 胖墩墩 (bụ bẫm).", "Tự nguyên_Xie": "Chữ hình thanh: 土 (thổ) biểu nghĩa chỉ đất/nền móng, 敦 biểu âm. 墩 chỉ một ụ đất, cục đá, hoặc khối gỗ/đá làm bệ đỡ. Cũng dùng làm lượng từ chỉ cụm cây mọc dày. Tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ụ đất", "Hạng Tần Suất (Jun Da)": "3546.0", "Tần Suất % (Jun Da)": "99.5699066052", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 敦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土敦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "墩", "Unihan_Traditional (Chữ Phồn thể)": "墩", "Pinyin_Xie": "dūn", "Âm Hán Việt_Xie": "đôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường làm danh từ chỉ các cấu trúc dạng bệ, ụ hoặc làm lượng từ cho các vật có hình dạng như vậy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彝', '{"9000": "3547.0", "Chữ Trung Quốc": "彝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彐 | Số nét | 18 | nét | 彑 | kí | biểu âm | đầu (theo Thuyết văn) | 米 | mễ | biểu nghĩa | gạo, ngũ cốc | 糸 | mịch | biểu nghĩa | tơ lụa | 廾 | trấp | biểu nghĩa | hai tay | 彝 là chữ hội ý (ic): 廾 (hai tay) nâng đỡ lễ vật — gồm thân vật/nô lệ (彑 biểu đầu, theo Thuyết văn cũng là biểu âm), 米 (gạo/thân), 糸 (dây/tơ trói buộc). Tổng thể miêu tả cảnh dâng tế vật bằng hai tay trong nghi lễ tổ tiên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"di\": hai tay 廾 dâng lễ vật buộc bằng tơ 糸 lên bàn thờ tổ tiên — 彝 là lễ khí thiêng liêng. | Gương Hán-Việt | di trong ''Di tộc'' (彝族) — dân tộc Di ở Tây Nam Trung Quốc; ''di khí'' (彝器) — đồ lễ cổ | Mở khoá kiến thức | Biết 彝 mở khoá tên dân tộc 彝族, thuật ngữ khảo cổ về đồ lễ đồng thau cổ đại, và khái niệm lễ pháp.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 彝 ban đầu miêu tả một con chim hoặc nô lệ bị trói hai tay, dâng làm lễ tế. 彑 là phần đầu (Thuyết văn cũng coi là biểu âm), 米 là thân (không liên quan đến nghĩa ''gạo''), 糸 là dây trói cánh/tay, 廾 là hai bàn tay dâng lên. Sau này 彝 chỉ chén/bình đồng cổ dùng trong thờ tự, rồi mở rộng nghĩa thành ''quy tắc, lễ pháp'' và tên dân tộc Di. Có hình trong giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chén uống rượu thời xưa; thường, hay; dân tộc Di, người Di", "Hạng Tần Suất (Jun Da)": "3547.0", "Tần Suất % (Jun Da)": "99.5704089204", "GavinGrover_Once (Chiết tự trực tiếp)": "彑 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彝", "Unihan_Traditional (Chữ Phồn thể)": "彞", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "di", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ đồ tế khí thời xưa hoặc tên gọi của dân tộc Di. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('囱', '{"9000": "3548.0", "Chữ Trung Quốc": "囱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 囗 | Số nét | 7 | nét | 囱 | song | tượng hình | ống khói, cửa sổ | 囱 là chữ tượng hình: hình vẽ cái ống khói. Dấu chấm trên là khói thoát ra, hình vuông là cửa sổ hay nhà, phần bên trong là người đi lại hoặc ánh sao nhìn qua ống khói. Có hình trong giáp cốt văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"song\": cái khung vuông 囗 có khói thoát ra — 囱 là ống khói, cũng là từ ''song'' trong ''song cửa''. | Gương Hán-Việt | song trong ''song cửa'' — cửa sổ; 烟囱 (yān cōng) ống khói | Mở khoá kiến thức | Biết 囱 mở khoá từ 烟囱 (ống khói) trong tiếng Hán hiện đại.", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary: 囱 là tượng hình vẽ cái ống khói. Dấu chấm ở trên biểu thị khói thoát ra, hình hộp là cửa sổ hoặc ngôi nhà, phần ký hiệu bên trong là ánh sao nhìn qua ống hoặc người đi trong nhà. Giáp cốt văn và đại triện đều có dạng sớm. 囱 gốc nghĩa là cửa sổ, sau chỉ ống thông khói (烟囱). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "574.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vi (132) Tịch (101)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Tịch (số 101 - ban đêm/tối) nằm trong chữ Vi (số 132 - bao quanh), bên trên có nét phẩy. Nét phẩy tượng trưng cho tia nắng mặt trời chiếu xuyên qua cái khung hình vuông. Giải thích sự chuyển ý: Tia nắng đi qua cửa sổ xóa tan đi sự tối tăm (Tịch) ở trong nhà. Thông là lỗ hở trên tường, cửa sổ để thông không khí (sau này dùng chỉ ống khói).", "Nghĩa Tiếng Việt_Xie": "cửa sổ; ống thông khói", "Hạng Tần Suất (Jun Da)": "3548.0", "Tần Suất % (Jun Da)": "99.5709091684", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 夂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Bao quanh toàn bộ)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴夂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "囱", "Unihan_Traditional (Chữ Phồn thể)": "囪", "Pinyin_Xie": "cōng", "Âm Hán Việt_Xie": "thông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường xuất hiện trong các danh từ ghép chỉ ống khói hoặc lỗ thông hơi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逍', '{"9000": "3549.0", "Chữ Trung Quốc": "逍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 10 | nét | 逍 | tiêu | tượng hình | đi dạo tự tại, không ràng buộc | 逍 có bộ 辶(辵: đi/chạy) — chỉ hoạt động di chuyển. Phần còn lại gần với 肖 gợi âm. Wiktionary không ghi cấu trúc compound; đây là chữ chủ yếu dùng trong cụm 逍遥. Chữ tạo muộn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\": bước đi 辶 nhẹ nhàng, tiêu dao — 逍 là tự do tự tại, không vướng bận. | Gương Hán-Việt | tiêu trong ''tiêu dao'' (逍遥) — tự do, phóng khoáng theo tư tưởng Trang Tử | Mở khoá kiến thức | Biết 逍 mở khoá từ 逍遥 và triết học Trang Tử về tự do tuyệt đối.", "Tự nguyên_Xie": "Tiểu triện | 逍 không có phân tích cấu trúc rõ ràng trong Wiktionary. Bộ 辶(辵) biểu nghĩa chỉ đi lại, di chuyển. Chữ gần như chỉ dùng trong từ 逍遥 (tiêu dao: tự do tự tại, dạo chơi không ràng buộc) — tiêu biểu cho tư tưởng Trang Tử. Tiểu triện có dạng sớm. Chưa có nguồn học thuật về nguồn gốc cụ thể. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cuộc dạo chơi", "Hạng Tần Suất (Jun Da)": "3549.0", "Tần Suất % (Jun Da)": "99.5714094164", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逍", "Unihan_Traditional (Chữ Phồn thể)": "逍", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chủ yếu kết hợp với chữ Dao thành từ ghép Tiêu Dao để chỉ trạng thái tự do tự tại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辄', '{"9000": "3550.0", "Chữ Trung Quốc": "辄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 11 | nét | 車 | xa | biểu nghĩa | xe | 耴 | biểu âm | 辄 = 車 (Xa, biểu nghĩa: xe) + 耴 (biểu âm); chữ hình thanh. Phần 車 cho biết nghĩa gốc liên quan đến xe (tấm chắn hông xe), phần 耴 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"triếp\": hông xe 車 luôn sẵn sàng — 辄 là phó từ ''ngay lập tức, mỗi khi'' trong văn ngôn. | Gương Hán-Việt | triếp trong ''động triếp đắc cữu'' (動輒得咎) — hễ động là bị phạt | Mở khoá kiến thức | Biết 辄 mở khoá thành ngữ 动辄得咎 và phó từ văn ngôn chỉ tần suất/tức thì.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 車 (xa) biểu nghĩa, 耴 biểu âm. Dạng cổ 輒/輖 chỉ tấm chắn hai bên hông xe ngựa — nơi để vũ khí. Từ nghĩa đó mở rộng thành phó từ ''ngay lập tức, mỗi khi'' (mỗi khi bước lên xe là sẵn có vũ khí ngay), rồi ''thường xuyên, tuỳ tiện''. Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chuyên quyền, quyết đoán; ngay tức thì; thường, luôn", "Hạng Tần Suất (Jun Da)": "3550.0", "Tần Suất % (Jun Da)": "99.5719091476", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 耴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车耴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辄", "Unihan_Traditional (Chữ Phồn thể)": "輒", "Pinyin_Xie": "zhé", "Âm Hán Việt_Xie": "triếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường đứng trước động từ trong văn ngôn để biểu thị hành động xảy ra ngay lập tức hoặc thường xuyên. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桅', '{"9000": "3551.0", "Chữ Trung Quốc": "桅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 危 | nguy | biểu âm | 桅 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 危 (Nguy, biểu âm); chữ hình thanh. Phần 木 chỉ đây là vật bằng gỗ, phần 危 cho âm đọc wéi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nguy\": cột gỗ 木 vươn cao nguy hiểm 危 trên tàu — 桅 là cột buồm. | Gương Hán-Việt | nguy trong ''nguy can'' (桅杆: cột buồm) — cột gỗ cao nguy nga trên thuyền | Mở khoá kiến thức | Biết 桅 mở khoá từ 桅杆 (cột buồm) và từ vựng hàng hải cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 木 (mộc) biểu nghĩa chỉ gỗ, 危 (nguy) biểu âm. 桅 chỉ cột buồm tàu thuyền — cột gỗ cao trên tàu để căng buồm. Tên gợi hình ảnh cột gỗ vươn cao nguy hiểm trên biển. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1287.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Nguy (1286)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - gỗ/chỉ ý) ở bên trái chữ Nguy (số 1286 - nguy hiểm/chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Nguy chỉ âm, bộ Mộc chỉ ý. Cây cột gỗ đứng thẳng dễ gãy đổ là cái cột buồm (cột ngôi/ngoa).", "Nghĩa Tiếng Việt_Xie": "cột buồm", "Hạng Tần Suất (Jun Da)": "3551.0", "Tần Suất % (Jun Da)": "99.5724083621", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 危", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木危", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "危", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桅", "Unihan_Traditional (Chữ Phồn thể)": "桅", "Pinyin_Xie": "wéi", "Âm Hán Việt_Xie": "ngôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp thành từ ghép để chỉ cột buồm của tàu thuyền. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俨', '{"9000": "3552.0", "Chữ Trung Quốc": "俨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 俨 | nghiễm | tượng hình | dáng vẻ nghiêm trang, kính cẩn | 俨 là giản thể của 儼. Chữ gốc 儼 gồm 亻(nhân: người) + 嚴 (nghiêm) biểu âm — chữ hình thanh. 俨 giản lược 嚴 thành 严. Kim văn và tiểu triện đã ghi nhận dạng cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghiễm\": người 亻đứng nghiêm — 俨 là dáng nghiêm trang, 俨然 là trông rõ ràng như thật. | Gương Hán-Việt | nghiễm trong ''nghiễm nhiên'' (俨然) — trông ra vẻ, như thật; nghiêm trang | Mở khoá kiến thức | Biết 俨 mở khoá từ 俨然 thường dùng trong văn miêu tả dáng vẻ hoặc so sánh.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 俨 là giản thể của 儼, chữ hình thanh: 亻(nhân) biểu nghĩa chỉ người, 嚴/严 biểu âm. 俨 miêu tả dáng vẻ nghiêm trang, đứng đắn, đàng hoàng. Thường dùng trong văn ngôn với nghĩa ''rõ ràng như thật'' (俨然: trông như thật). Kim văn và tiểu triện có dạng sớm. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kinh sợ", "Hạng Tần Suất (Jun Da)": "3552.0", "Tần Suất % (Jun Da)": "99.5729075765", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 严", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻严", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "严", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俨", "Unihan_Traditional (Chữ Phồn thể)": "儼", "Pinyin_Xie": "yǎn", "Âm Hán Việt_Xie": "nghiễm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường dùng làm tính từ mô tả vẻ trang nghiêm hoặc làm phó từ mang nghĩa giống hệt như. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('纶', '{"9000": "3553.0", "Chữ Trung Quốc": "纶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 7 | nét | 纶 | luân | tượng hình | sợi tơ xanh, dây câu cá | 纶 là giản thể của 綸. Chữ gốc 綸 gồm 糹(mịch: tơ lụa) + 侖/仑 biểu âm — chữ hình thanh. 纶 giản lược 糹 thành 纟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": tơ 纟 cuộn đều như bánh xe — 纶 là sợi tơ xanh triều quan, nay dùng cho dây câu hay nilon. | Gương Hán-Việt | luân trong ''luân lý'' gợi sợi dây buộc ràng — 纶 là sợi tơ, dây câu | Mở khoá kiến thức | Biết 纶 mở khoá từ 涤纶 (polyester), 钓纶 (dây câu) trong từ vựng vải sợi hiện đại.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 纶 là giản thể của 綸, chữ hình thanh: 糸/糹 biểu nghĩa chỉ tơ lụa/sợi chỉ, 侖/仑 biểu âm. 纶 gốc chỉ sợi tơ xanh dùng làm đầu mũ quan triều. Nghĩa mở rộng: dây câu cá (钓纶), sợi nilon (涤纶). Tiểu triện và lục thư thông ghi nhận nhiều dạng. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái quạt", "Hạng Tần Suất (Jun Da)": "3553.0", "Tần Suất % (Jun Da)": "99.5734062742", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 仑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟仑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "纶", "Unihan_Traditional (Chữ Phồn thể)": "綸", "Pinyin_Xie": "lún", "Âm Hán Việt_Xie": "luân, quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các từ ghép chỉ dây câu, tơ sợi hoặc các loại khăn đội đầu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悸', '{"9000": "3554.0", "Chữ Trung Quốc": "悸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tim, tâm trạng | 季 | quý | biểu âm | 悸 = 忄(Tâm, biểu nghĩa: tim/tâm trạng) + 季 (Quý, biểu âm); chữ hình thanh. Phần 忄chỉ cảm xúc liên quan đến tim, phần 季 cho âm đọc jì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quý\": tâm 忄đập loạn vì sợ — 悸 là tim đánh thình thịch, run rẩy bất an. | Gương Hán-Việt | quý trong ''tâm quý'' (心悸) — tim đập loạn, đánh trống ngực | Mở khoá kiến thức | Biết 悸 mở khoá từ 心悸, 余悸犹存 trong mô tả sức khỏe và trạng thái sau sợ hãi.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 心/忄(tâm) biểu nghĩa chỉ tim/tâm lý, 季 (quý) biểu âm. 悸 chỉ trạng thái tim đập loạn, lo lắng bất an — như tim đánh thình thịch vì sợ. Thường gặp trong từ 心悸 (đánh trống ngực) và thành ngữ 余悸犹存 (dư chấn còn đó). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sợ hãi, e ngại", "Hạng Tần Suất (Jun Da)": "3554.0", "Tần Suất % (Jun Da)": "99.573904455", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 季", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄季", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "季", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悸", "Unihan_Traditional (Chữ Phồn thể)": "悸", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "quý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ chỉ trạng thái tim đập nhanh do sợ hãi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殃', '{"9000": "3555.0", "Chữ Trung Quốc": "殃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 9 | nét | 歹 | tồi | biểu nghĩa | xấu, chết chóc, tai họa | 央 | ương | biểu âm | (cho âm yāng, đồng âm Hán-Việt) | 殃 = 歹 (Tồi, biểu nghĩa: tai họa, xấu ác) + 央 (Ương, biểu âm); chữ hình thanh. Bộ tồi (歹) chỉ điều xấu, tai ương; 央 cho âm yāng và đồng âm Hán-Việt ương.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": tai họa (歹) trung ương (央) ập xuống — ương ngạnh chịu đựng tai ương từ trên trời. | Gương Hán-Việt | \"ương\" trong \"tai ương\" (殃 — tai họa), \"ương ương\" (tự chuốc họa); 央 (ương) trong 中央 (trung ương) | Mở khoá kiến thức | Biết 殃 mở khoá 遭殃 (gặp tai vạ), 殃及池鱼 (vạ lây), 禍国殃民 (hại nước hại dân).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 殃 là chữ hình thanh: bộ 歹 (tồi — tai họa, xấu ác) biểu nghĩa; 央 (ương) cho âm yāng. Theo Wiktionary, nghĩa là tai vạ, thiên tai, tai họa; động từ là gây họa cho ai. Dùng trong 遭殃 (bị tai vạ), 殃及池鱼 (vạ lây cá trong ao — thành ngữ nổi tiếng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sự rủi ro, tai vạ", "Hạng Tần Suất (Jun Da)": "3555.0", "Tần Suất % (Jun Da)": "99.5744026359", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殃", "Unihan_Traditional (Chữ Phồn thể)": "殃", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ tai họa hoặc làm động từ mang nghĩa gây hại, làm tổn hại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帧', '{"9000": "3556.0", "Chữ Trung Quốc": "帧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 9 | nét | 巾 | can | biểu nghĩa | vải, khăn | 貞 | trinh | biểu âm | 帧 = 巾 (Can, biểu nghĩa: vải/tấm phủ) + 貞 (Trinh, biểu âm); chữ hình thanh. Phần 巾 gợi tấm vải/bức tranh căng trên vải, phần 貞 cho âm đọc zhèng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trinh\": tấm vải 巾 căng thẳng như trinh — 帧 là bức tranh cuộn; nay là ''frame'' (khung hình video). | Gương Hán-Việt | trinh trong ''trang trinh'' gợi tấm tranh phẳng đẹp — 帧 là bức họa, khung hình | Mở khoá kiến thức | Biết 帧 mở khoá từ 装帧 (đóng bìa sách), 掉帧 (drop frame), 关键帧 (keyframe) trong thiết kế và video.", "Tự nguyên_Xie": "Chữ hình thanh: 巾 (can) biểu nghĩa chỉ vải/khăn, 貞 biểu âm. Dạng cổ 幀 chỉ bức tranh căng trên vải/cuộn tranh. Nghĩa mở rộng hiện đại: khung hình trong phim/video (frame). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bức tranh", "Hạng Tần Suất (Jun Da)": "3556.0", "Tần Suất % (Jun Da)": "99.5748997832", "GavinGrover_Once (Chiết tự trực tiếp)": "巾 + 贞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰巾贞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "巾", "Unihan_Simplified (Chữ Giản thể)": "帧", "Unihan_Traditional (Chữ Phồn thể)": "幀", "Pinyin_Xie": "zhèng", "Âm Hán Việt_Xie": "tránh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ cho tranh vẽ, ảnh chụp hoặc các khung hình video. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俐', '{"9000": "3557.0", "Chữ Trung Quốc": "俐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | nhân | biểu nghĩa | người | 利 | lợi | biểu âm | sắc bén, lợi lộc | 俐 = 亻 (Nhân, biểu nghĩa: người) + 利 (Lợi, biểu âm). Không có dữ liệu lsCodes từ Wiktionary, nhưng cấu trúc phono-semantic là hợp lý: 亻 cho nghĩa (liên quan đến người), 利 cho âm (lì). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lợi\": người (亻) mang trong mình sự sắc bén, lợi lộc (利) — ắt là kẻ lanh lợi, nhanh nhẹn. | Gương Hán-Việt | \"lợi\" trong \"伶俐\" (linh lợi) — thường thấy trong văn nói về người thông minh hoạt bát | Mở khoá kiến thức | Biết 俐 mở khoá từ 伶俐 (lanh lợi, thông minh hoạt bát).", "Tự nguyên_Xie": "Chữ 俐 không có nguồn Wiktionary rõ ràng. Dựa trên cấu trúc IDS ⿰亻利: bộ 亻 (Nhân) biểu nghĩa chỉ người; 利 (Lợi) biểu âm cho âm đọc lì. Nghĩa gốc: người nhanh nhẹn, lanh lợi. Thường dùng trong 伶俐 (linh lợi). Chưa có nguồn học thuật từ Wiktionary xác nhận chi tiết hơn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "355.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Lợi (332)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Lợi (số 332) chỉ âm, chữ Nhân (số 12) chỉ ý. Lị là chỉ người nhanh nhẹn, sáng suốt, sắc bén (lanh lị). Giải thích sự chuyển ý: Chữ Lợi (sắc bén) chỉ âm, chữ Nhân (người) chỉ ý. Người (Nhân) có đầu óc sắc bén, nhanh nhạy (Lợi) gọi là người lanh lẹ (Lị). *(Biến âm Hán Việt: Trong Hán ngữ cổ, chữ Lợi và chữ Lị có cách phát âm tương đồng hoặc chung gốc phụ âm. Quá trình Việt hóa đã làm âm đọc bị chênh lệch thành Lợi và Lị).*", "Nghĩa Tiếng Việt_Xie": "nhanh nhẹn sáng suốt, lanh lợi", "Hạng Tần Suất (Jun Da)": "3557.0", "Tần Suất % (Jun Da)": "99.5753958969", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 利", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻利", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "利", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俐", "Unihan_Traditional (Chữ Phồn thể)": "俐", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường không đứng một mình mà kết hợp với chữ Lanh để tạo thành tính từ Lanh Lợi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绮', '{"9000": "3558.0", "Chữ Trung Quốc": "绮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 糸 | mịch | biểu nghĩa | tơ lụa | 奇 | cơ | biểu âm | 绮 = 糸/纟(Mịch, biểu nghĩa: tơ lụa) + 奇 (Cơ, biểu âm); chữ hình thanh. Phần 糸 chỉ đây là loại vải tơ, phần 奇 cho âm đọc qǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": tơ lụa 糸 dệt hoa văn kỳ ảo — 绮 là lụa đẹp, 绮丽 là cảnh sắc hoa lệ tráng lệ. | Gương Hán-Việt | kỳ trong ''kỳ lệ'' (绮丽) — hoa lệ, tráng lệ; ''kỳ la'' (绮罗) — lụa là | Mở khoá kiến thức | Biết 绮 mở khoá từ 绮丽 (tráng lệ), 绮罗 (lụa là) và ngôn ngữ thơ văn Hán-Việt.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 糸 (mịch) biểu nghĩa chỉ tơ lụa, 奇 (cơ) biểu âm. 绮 gốc chỉ loại lụa mỏng dệt hoa văn — lụa đẹp, sang trọng. Nghĩa mở rộng: đẹp, hoa lệ (绮丽: tráng lệ). Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vải lụa", "Hạng Tần Suất (Jun Da)": "3558.0", "Tần Suất % (Jun Da)": "99.5758909771", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 奇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟奇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绮", "Unihan_Traditional (Chữ Phồn thể)": "綺", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "khỉ, ỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ lụa đẹp hoặc tính từ đứng trước danh từ để miêu tả sự hoa lệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('袒', '{"9000": "3559.0", "Chữ Trung Quốc": "袒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 10 | nét | 衤 | y | biểu nghĩa | áo, quần áo | 旦 | đán | biểu âm | 袒 = 衤(Y, biểu nghĩa: quần áo) + 旦 (Đán, biểu âm); chữ hình thanh. Phần 衤chỉ liên quan đến quần áo, phần 旦 cho âm đọc tǎn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đản\": cởi áo 衤ra vào buổi sáng 旦 — 袒 là cởi trần; 袒护 là che chở như che ngực cho người thân. | Gương Hán-Việt | đản trong ''đản hộ'' (袒护) — bao che, thiên vị | Mở khoá kiến thức | Biết 袒 mở khoá từ 袒护 (bao che), 坦露 (phơi bày) và từ vựng pháp lý về thiên vị.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 衣/衤(y) biểu nghĩa chỉ quần áo, 旦 biểu âm. 袒 gốc nghĩa là cởi trần — tháo bỏ phần trên áo để lộ vai/lưng. Từ đó mở rộng: bao che, che chở cho ai (袒护: thiên vị, bênh vực). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cởi trần", "Hạng Tần Suất (Jun Da)": "3559.0", "Tần Suất % (Jun Da)": "99.5763855405", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "袒", "Unihan_Traditional (Chữ Phồn thể)": "袒", "Pinyin_Xie": "tǎn", "Âm Hán Việt_Xie": "đản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ chỉ bộ phận cơ thể được để lộ hoặc dùng trong từ ghép chỉ sự bao che. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('籽', '{"9000": "3560.0", "Chữ Trung Quốc": "籽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 9 | nét | 米 | mễ | biểu nghĩa | gạo, hạt ngũ cốc | 子 | tử | biểu âm | 籽 = 米 (Mễ, biểu nghĩa: hạt gạo/ngũ cốc) + 子 (Tử, biểu âm); chữ hình thanh. Phần 米 chỉ đây là hạt lương thực, phần 子 cho âm đọc zǐ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tử\": hạt gạo 米 nhỏ như đứa con 子 — 籽 là hạt giống, mầm sống bé nhỏ. | Gương Hán-Việt | tử trong ''hạt tử'' — hạt giống; 种籽 (hạt giống), 菜籽 (hạt rau) | Mở khoá kiến thức | Biết 籽 mở khoá từ 菜籽 (hạt rau), 棉籽 (hạt bông), 种籽 (hạt giống) trong nông nghiệp.", "Tự nguyên_Xie": "Chữ hình thanh: 米 (mễ) biểu nghĩa chỉ hạt gạo/ngũ cốc nhỏ, 子 (tử) biểu âm. 籽 chỉ hạt giống của cây — hạt nhỏ dùng để gieo trồng. Chữ khá mới về mặt lịch sử, chưa thấy trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt giống", "Hạng Tần Suất (Jun Da)": "3560.0", "Tần Suất % (Jun Da)": "99.5768801039", "GavinGrover_Once (Chiết tự trực tiếp)": "米 + 子", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰米子", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "子", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "米", "Unihan_Simplified (Chữ Giản thể)": "籽", "Unihan_Traditional (Chữ Phồn thể)": "籽", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "tử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau tên loại cây để chỉ hạt của cây đó như hoa sinh tử, thái tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('孰', '{"9000": "3561.0", "Chữ Trung Quốc": "孰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 子 | Số nét | 11 | nét | 丮 | biểu âm | tay nắm | 孰 là chữ hình thanh: phần 𦎫 (gốc biểu âm, nay biến thành 享) và 丮 (gốc biểu nghĩa: tay nắm, nay biến thành 丸). Trong chữ hiện đại, cả hai thành phần đều đã bị biến dạng so với dạng gốc. Wiktionary ghi nhận đây là hình thanh bị thay đổi qua thời gian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thục\": ai nắm tay 丮 — 孰 là đại từ văn ngôn hỏi ''ai, cái nào''; 孰优孰劣 là hỏi cái nào hơn. | Gương Hán-Việt | thục trong ''nhân thục'' (人孰) gợi hỏi người nào — 孰 là đại từ nghi vấn văn ngôn | Mở khoá kiến thức | Biết 孰 mở khoá đại từ nghi vấn văn ngôn và thành ngữ 孰优孰劣 (hơn kém nhau thế nào).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 孰 ban đầu là chữ hình thanh — 𦎫 biểu âm và 丮 biểu nghĩa (tay nắm). Trong chữ hiện đại, 𦎫 đã biến dạng thành hình dạng như 享, còn 丮 thành 丸. Kim văn và đại triện ghi nhận dạng sớm. 孰 là đại từ nghi vấn văn ngôn nghĩa ''ai, cái nào'' — tương tự 谁/哪. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1099.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hưởng (241) Hoàn (004)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Hưởng (số 241 - dâng cúng) ở bên trái chữ Hoàn (số 004 - viên đạn/vật hình tròn). Giải thích sự chuyển ý: Đây là chữ Hội ý. Thục mang ý nghĩa dùng để hỏi: ai, người nào, cái gì (thục thị thục phi - ai đúng ai sai).", "Nghĩa Tiếng Việt_Xie": "ai đó, cái gì đó", "Hạng Tần Suất (Jun Da)": "3561.0", "Tần Suất % (Jun Da)": "99.5773741504", "GavinGrover_Once (Chiết tự trực tiếp)": "享 + 丸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰享丸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "享", "Unihan_Simplified (Chữ Giản thể)": "孰", "Unihan_Traditional (Chữ Phồn thể)": "孰", "Pinyin_Xie": "shú", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Dùng làm đại từ nghi vấn trong văn ngôn, thường đứng đầu câu hoặc trước động từ để hỏi. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('愫', '{"9000": "3562.0", "Chữ Trung Quốc": "愫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 13 | nét | 愫 | tố | tượng hình | lòng chân thành, tình cảm thật | 愫 có bộ 忄(tâm: tim/cảm xúc). Phần bên phải gần với 素 gợi âm. Wiktionary không có entry cho 愫. Dựa vào cấu trúc: 忄biểu nghĩa, 素 gần biểu âm — chữ hình thanh dự đoán. Chưa có nguồn học thuật rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tố\": tâm 忄đơn giản thuần khiết như tố 素 — 愫 là lòng thành thật, tình cảm chân thật bên trong. | Gương Hán-Việt | tố trong ''tình tố'' (情愫) — tình cảm sâu lắng, chân thành | Mở khoá kiến thức | Biết 愫 mở khoá từ 情愫 (tình cảm chân thật) dùng trong thơ văn và văn học lãng mạn.", "Tự nguyên_Xie": "愫 không có entry trong Wiktionary. Dựa vào cấu trúc tự dạng: bộ 忄(tâm) biểu nghĩa chỉ tình cảm/lòng dạ, phần còn lại gần với 素 (tố: đơn giản, thuần khiết) gợi âm và nghĩa. 愫 chỉ lòng chân thành, tình cảm thật sự bên trong. Thường gặp trong từ 情愫 (tình cảm sâu lắng). Chưa có nguồn học thuật về nguồn gốc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lòng thành", "Hạng Tần Suất (Jun Da)": "3562.0", "Tần Suất % (Jun Da)": "99.5778661299", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 素", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄素", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "素", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "愫", "Unihan_Traditional (Chữ Phồn thể)": "愫", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn viết, kết hợp thành từ ghép như tình tố, tâm tố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拌', '{"9000": "3563.0", "Chữ Trung Quốc": "拌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 半 | bán | biểu âm | nửa, một nửa | 拌 = 扌 (Thủ, biểu nghĩa: tay) + 半 (Bán, biểu âm). Wiktionary cung cấp glyphOrigin nhưng không ghi lsCodes rõ; cấu trúc phono-semantic hợp lý: bộ 扌 chỉ hành động tay, 半 cho âm bàn. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạn\": bàn tay (扌) chia đôi (半) thức ăn ra rồi trộn đều — hành động trộn, khuấy. | Gương Hán-Việt | \"bạn\" trong \"搅拌\" (giảo bạn — khuấy trộn); cũng gặp trong \"拌嘴\" (bạn chủy — cãi nhau) | Mở khoá kiến thức | Biết 拌 mở khoá 搅拌 (khuấy trộn), 凉拌 (trộn nguội), 拌嘴 (cãi vã).", "Tự nguyên_Xie": "Chữ 拌 (bạn) gồm bộ 扌 (Thủ — tay) biểu nghĩa và 半 (Bán) biểu âm. Wiktionary xác nhận đây là chữ có nguồn gốc cổ (Middle Chinese và Old Chinese đều có). Nghĩa cơ bản là dùng tay khuấy trộn; nghĩa phụ là cãi vã (âm bàn, tiếng Hakka dùng nghĩa ném/quăng). Chữ phổ biến trong ẩm thực: 凉拌 (trộn nguội), 搅拌 (khuấy đều). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấy đều, nhào, trộn; món nộm; cãi nhau; vứt bỏ", "Hạng Tần Suất (Jun Da)": "3563.0", "Tần Suất % (Jun Da)": "99.5783570758", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 半", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌半", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "半", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拌", "Unihan_Traditional (Chữ Phồn thể)": "拌", "Pinyin_Xie": "bàn", "Âm Hán Việt_Xie": "bạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ tác động lên danh từ chỉ thức ăn hoặc dùng trong khẩu ngữ chỉ việc cãi nhau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | bàn | / | khuấy và trộn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橙', '{"9000": "3564.0", "Chữ Trung Quốc": "橙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 登 | đăng | biểu âm | leo lên | 橙 = 木 (Mộc, biểu nghĩa: cây) + 登 (Đăng, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 木 cho nghĩa (loài cây), 登 cho âm chéng. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tranh\": cây (木) leo lên (登) đầy quả tròn vàng — đó là cây cam 橙. | Gương Hán-Việt | \"tranh\" ít dùng độc lập; thường gặp 橙汁 (nước cam), 橙色 (màu cam) | Mở khoá kiến thức | Biết 橙 mở khoá 橙汁 (nước cam), 橙色 (màu cam), 脐橙 (cam rốn).", "Tự nguyên_Xie": "Tiểu triện | Chữ 橙 (tranh) là chữ hình thanh (ls=psc): bộ 木 (Mộc) biểu nghĩa chỉ loài cây; 登 (Đăng) biểu âm cho âm chéng. Nghĩa gốc chỉ cây cam, quả cam và màu cam. Hình tiểu triện đã được lưu lại tại hanziyuan.net. Trong tiếng Việt, Hán-Việt đọc là \"tranh\" nhưng hiện nay thường nhận ra qua màu cam. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây chanh; cái ghế, cái sập", "Hạng Tần Suất (Jun Da)": "3564.0", "Tần Suất % (Jun Da)": "99.5788459545", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 登", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木登", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "登", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橙", "Unihan_Traditional (Chữ Phồn thể)": "橙", "Pinyin_Xie": "chéng", "Âm Hán Việt_Xie": "tranh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ quả cam hoặc làm tính từ bổ nghĩa cho danh từ để chỉ màu sắc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chéng | / | quả cam; màu cam | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暨', '{"9000": "3565.0", "Chữ Trung Quốc": "暨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 14 | nét | 既 | ký | biểu âm | 旦 | đán | biểu nghĩa | bình minh, mặt trời mọc | 暨 = 既 (Ký, biểu âm) + 旦 (Đán, biểu nghĩa: bình minh/mặt trời); chữ hình thanh. Phần 旦 chỉ thời gian/bầu trời, phần 既 cho âm đọc jì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỵ\": mặt trời 旦 mọc lên và 既 — 暨 là liên từ trang trọng ''và/cùng với'' trong văn bản chính thức. | Gương Hán-Việt | kỵ trong văn ngôn ''kỵ'' — liên từ ''và, cùng với''; thường dùng trong tiêu đề hội nghị | Mở khoá kiến thức | Biết 暨 mở khoá liên từ văn ngôn và nghiêm trang trong văn bản hành chính, tiêu đề hội thảo.", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: 旦 (đán) biểu nghĩa chỉ bình minh/mặt trời mọc, 既 biểu âm. 暨 là liên từ văn ngôn nghĩa ''và; cùng với; đến tận''. Đại triện ghi nhận dạng sớm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "và; với", "Hạng Tần Suất (Jun Da)": "3565.0", "Tần Suất % (Jun Da)": "99.5793348332", "GavinGrover_Once (Chiết tự trực tiếp)": "既 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱既旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "既", "Unihan_Simplified (Chữ Giản thể)": "暨", "Unihan_Traditional (Chữ Phồn thể)": "暨", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Liên từ | 连词 | Giới từ | 介词 | Dùng làm liên từ nối các danh từ hoặc cụm danh từ trong văn phong trang trọng, hành chính. | Liên từ | 连词 | Nối từ, cụm từ hoặc mệnh đề: 和, 但是, 因为…所以…. Lưu ý 和 chỉ nối danh từ, không nối hai câu như ''và'' tiếng Việt. | Giới từ | 介词 | Ghép với danh từ hoặc đại từ thành cụm chỉ nơi chốn, thời gian, đối tượng: 在家, 跟他. Cụm giới từ đứng TRƯỚC động từ — 我在家吃饭 — ngược với trật tự tiếng Việt.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('敖', '{"9000": "3566.0", "Chữ Trung Quốc": "敖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 攴 | Số nét | 10 | nét | 出 | xuất | biểu nghĩa | ra ngoài | 放 | phóng | biểu nghĩa | phóng thích | 敖 là chữ hội ý (ic) theo cách diễn giải muộn của Thuyết văn — 出 (xuất: ra ngoài) + 放 (phóng: buông thả) gợi ý đi chơi tự do. Tuy nhiên Wiktionary ghi rõ: đây là chữ tượng hình gốc, Thuyết văn đã diễn giải sai. Dạng gốc mô tả người có mũ đội đầu, sau thêm 攴 gợi quyền uy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngào\": người ra ngoài 出 phóng thả 放 đi ngao du — 敖 là dạo chơi, ngao du tự tại. | Gương Hán-Việt | ngào trong ''ngao du'' (敖游/遨游) — du ngoạn tự do; họ Ngao trong lịch sử Trung Hoa | Mở khoá kiến thức | Biết 敖 mở khoá họ Ngao và từ gốc cho chữ 遨 (ngao du) và 熬 (nấu lâu).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary: 敖 gốc là tượng hình (𫠤) vẽ người đội mũ cao. Sau đó thêm 攴 (đánh đập/quyền lực), biến thành dạng hội ý/tượng hình pha trộn. Thuyết văn Giải Tự diễn giải sai là 出+放 (ra ngoài + phóng thích). Học giả Ji Xusheng đề xuất: người đi lang thang ngoài đồng, trên đầu có mầm cỏ 屮. Kim văn và tiểu triện ghi nhận dạng cổ. 敖 nghĩa gốc là đi lang thang, chơi ngao du. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chơi, ngao du", "Hạng Tần Suất (Jun Da)": "3566.0", "Tần Suất % (Jun Da)": "99.5798231952", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + ⺙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⺙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "敖", "Unihan_Traditional (Chữ Phồn thể)": "敖", "Pinyin_Xie": "áo", "Âm Hán Việt_Xie": "ngao, ngạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chủ yếu dùng làm động từ chỉ sự ngao du hoặc tính từ trong văn ngôn chỉ sự ngạo mạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赘', '{"9000": "3567.0", "Chữ Trung Quốc": "赘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 14 | nét | 赘 | trụy | tượng hình | thừa ra, rườm rà | 赘 là giản thể của 贅. Chữ gốc 贅 gồm 敖 (ngao: phần âm/nghĩa) + 貝 (bối: tiền/tài sản) — liên quan đến giao dịch tài sản thừa. Phần 貝 biểu nghĩa chỉ tài vật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trụy\": tài vật 贝 dư thừa — 赘 là rườm rà, dư thừa; 赘述 là nói dài dòng thừa lời. | Gương Hán-Việt | trụy trong ''trụy tế'' (赘婿) — ở rể; ''trụy thuật'' (赘述) — dài dòng thừa lời | Mở khoá kiến thức | Biết 赘 mở khoá từ 赘述 (nói dài dòng), 赘婿 (ở rể) trong giao tiếp và văn học.", "Tự nguyên_Xie": "赘 là giản thể của 贅. Chữ gốc có bộ 貝 (bối: tiền, tài sản) ở dưới — gợi ý đây liên quan đến tài vật dư thừa. 贅 gốc nghĩa là đặt cọc tài sản để làm rể ở nhà vợ (ở rể) — vì không có của hồi môn. Từ đó mở rộng: thừa thãi, rườm rà không cần thiết (赘述: nói dài dòng). Chưa thấy nguồn Wiktionary chi tiết. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thừa ra, rườm rà; ở rể, kén rể", "Hạng Tần Suất (Jun Da)": "3567.0", "Tần Suất % (Jun Da)": "99.5803115571", "GavinGrover_Once (Chiết tự trực tiếp)": "敖 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敖贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赘", "Unihan_Traditional (Chữ Phồn thể)": "贅", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "chuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Danh từ | 名词 | Làm tính từ chỉ sự dư thừa hoặc động từ chỉ việc đi ở rể trong gia đình nhà vợ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抉', '{"9000": "3568.0", "Chữ Trung Quốc": "抉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 抉 | khoét | tượng hình | tay móc ra, đào khoét | 抉 có bộ 扌(thủ: tay). Phần bên phải gần với 夬 gợi âm. Wiktionary không ghi cấu trúc compound cụ thể nhưng ghi nhiều nghĩa: móc khoét, lựa chọn, đâm xuyên. Chữ tạo muộn (tiểu triện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoét\": tay 扌móc khoét ra — 抉 là đào khoét hoặc lựa chọn chắt lọc. | Gương Hán-Việt | khoét trong ''khoét trích'' (抉剔) — chắt lọc tinh tế; ''khoét trạch'' (抉择) — lựa chọn | Mở khoá kiến thức | Biết 抉 mở khoá từ 抉择 (lựa chọn quan trọng) và văn ngôn về chắt lọc tinh hoa.", "Tự nguyên_Xie": "Tiểu triện | 抉 không có phân tích cấu trúc rõ ràng trong Wiktionary. Bộ 扌(thủ) biểu nghĩa chỉ hành động tay. Phần 夬 gần biểu âm jué. 抉 có hai nhóm nghĩa chính: (1) móc/khoét ra (bằng tay hoặc vật nhọn), (2) lựa chọn, chắt lọc. Trong Hán-Việt quen dùng ''khoét'' theo nghĩa đào khoét. Tiểu triện ghi nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chọn nhặt ra; móc ra", "Hạng Tần Suất (Jun Da)": "3568.0", "Tần Suất % (Jun Da)": "99.5807994023", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 夬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌夬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抉", "Unihan_Traditional (Chữ Phồn thể)": "抉", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thường kết hợp với trạch thành quyết trạch mang nghĩa lựa chọn quyết định. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淤', '{"9000": "3569.0", "Chữ Trung Quốc": "淤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước | 於 | ư | biểu âm | 淤 = 氵(Thủy, biểu nghĩa: nước) + 於 (Ư, biểu âm); chữ hình thanh. Phần 氵chỉ liên quan đến nước/chất lỏng, phần 於 cho âm đọc yū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ứa\": nước 氵ứa lại thành bùn — 淤 là phù sa, bùn đọng; 淤塞 là nghẹt tắc vì bùn. | Gương Hán-Việt | ứa trong ''ứa tắc'' (淤塞) — tắc nghẽn do bùn; ''ứa huyết'' (淤血) — máu ứ | Mở khoá kiến thức | Biết 淤 mở khoá từ 淤泥 (bùn), 淤血 (máu ứ), 淤塞 (tắc nghẽn) trong y học và thủy lợi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 水/氵(thủy) biểu nghĩa chỉ nước, 於 (ư) biểu âm. 淤 chỉ bùn phù sa đọng lại, cặn lắng trong lòng sông/kênh. Nghĩa mở rộng: ứ đọng, tắc nghẽn (淤血: máu ứ; 淤塞: bị tắc do bùn). Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đọng, ứ; phù sa, bùn", "Hạng Tần Suất (Jun Da)": "3569.0", "Tần Suất % (Jun Da)": "99.5812867307", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 於", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵於", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "於", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淤", "Unihan_Traditional (Chữ Phồn thể)": "淤", "Pinyin_Xie": "yū", "Âm Hán Việt_Xie": "ứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ sự ngưng trệ của dòng chảy, mạch máu hoặc làm danh từ chỉ bùn đất lắng đọng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('剌', '{"9000": "3570.0", "Chữ Trung Quốc": "剌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 9 | nét | 禾 | hòa | biểu nghĩa | cây lúa, ngũ cốc | 口 | khẩu | biểu nghĩa | miệng/túi (có thể là vật chứa) | 刀 | đao | biểu nghĩa | dao, lưỡi dao | 剌 là chữ hội ý (ic): 禾 (lúa) + 刀 (dao) + 口 (có thể là túi/bó). Theo học giả Ji Xusheng: vẽ cảnh cắt thu hoạch lúa — dao cắt cây lúa. Thuyết văn: 束 (bó thảo mộc) + 刀. Có hình trong giáp cốt văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạt\": dao 刀 cắt ngang lúa 禾 — 剌 là cắt trái chiều, ngang bướng, đi ngược lại. | Gương Hán-Việt | lạt trong ''bội lạt'' (悖剌) — ngang ngược, trái đạo | Mở khoá kiến thức | Biết 剌 mở khoá phân biệt 剌 (ngang ngược) với 刺 (đâm) — hai chữ thường bị nhầm.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary: 剌 ban đầu là hội ý mô tả cảnh cắt thu hoạch lúa: 禾 (lúa) + 口 (bó/túi) + 刀 (dao). Trên kim văn, chữ biến thành 柬 (bó thảo mộc) + 刀. Nghĩa gốc là cắt, thu hoạch; sau mở rộng thành ''cắt đôi, trái lẽ, ngang ngược''. 剌 ≠ 刺 (khác nhau: 剌 là ngang ngược, 刺 là đâm). Có hình từ giáp cốt văn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngang, trái; cắt, rạch", "Hạng Tần Suất (Jun Da)": "3570.0", "Tần Suất % (Jun Da)": "99.5817740591", "GavinGrover_Once (Chiết tự trực tiếp)": "束 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰束刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "束", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "剌", "Unihan_Traditional (Chữ Phồn thể)": "剌", "Pinyin_Xie": "lá", "Âm Hán Việt_Xie": "lạt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ với nghĩa cắt rạch hoặc làm tính từ trong các từ ghép chỉ sự ngang trái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娼', '{"9000": "3571.0", "Chữ Trung Quốc": "娼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 娼 | xướng | tượng hình | người hát xướng, ca kỹ | 娼 có bộ 女 (nữ) biểu nghĩa chỉ phụ nữ. Phần bên phải gần với 昌 gợi âm (chāng). Wiktionary không ghi cấu trúc chi tiết nhưng liên hệ với 菖. Đây là chữ hình thanh: 女 + 昌 biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xướng\": người phụ nữ 女 ca xướng 昌 — 娼 là ca kỹ, nay chỉ kỹ nữ. | Gương Hán-Việt | xướng trong ''ca xướng'' — ca kỹ; 妓娼 (kỹ xướng) — kỹ nữ | Mở khoá kiến thức | Biết 娼 mở khoá từ 娼妓 và hiểu nguồn gốc từ nghĩa ca hát sang nghĩa hiện đại.", "Tự nguyên_Xie": "娼 có bộ 女 (nữ) biểu nghĩa, phần còn lại gần với 昌 biểu âm — chữ hình thanh. Gốc nghĩa là ca kỹ, người hát xướng (女昌: người phụ nữ hát hay). Sau mở rộng nghĩa thành kỹ nữ, gái mại dâm. Chưa có nguồn Wiktionary chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hát", "Hạng Tần Suất (Jun Da)": "3571.0", "Tần Suất % (Jun Da)": "99.5822613875", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 昌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女昌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娼", "Unihan_Traditional (Chữ Phồn thể)": "娼", "Pinyin_Xie": "chāng", "Âm Hán Việt_Xie": "xướng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ người phụ nữ làm nghề ca hát hoặc mại dâm thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('顼', '{"9000": "3572.0", "Chữ Trung Quốc": "顼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 顼 | húc | tượng hình | lo lắng, buồn sầu | 顼 có bộ 頁 (trang/đầu) — Wiktionary ghi chữ này chủ yếu dùng trong tên riêng Chuyên Húc (颛顼), một trong Ngũ Đế huyền thoại. Cấu trúc chi tiết không rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"húc\": tên của Chuyên Húc (颛顼) — vị Đế cai quản phương Bắc trong thần thoại Trung Hoa. | Gương Hán-Việt | húc trong ''Chuyên Húc'' (颛顼) — một trong Ngũ Đế huyền thoại | Mở khoá kiến thức | Biết 顼 mở khoá tên Chuyên Húc (颛顼) trong thần thoại và lịch sử cổ đại Trung Hoa.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | 顼 không có phân tích cấu trúc rõ ràng trong Wiktionary. Bộ 頁 (hiệt) gợi liên quan đến đầu/mặt. 顼 chủ yếu dùng trong tên riêng Chuyên Húc (颛顼) — vị thần cai trị phương Bắc, một trong Ngũ Đế huyền thoại Trung Hoa. Có kim văn và tiểu triện. Chưa có nguồn học thuật rõ ràng về nguồn gốc nghĩa. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "3572.0", "Tần Suất % (Jun Da)": "99.5827481991", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "页", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "顼", "Unihan_Traditional (Chữ Phồn thể)": "頊", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "húc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong tên của vị vua cổ đại Chuyên Húc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葵', '{"9000": "3573.0", "Chữ Trung Quốc": "葵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 癸 | quý | biểu âm | 葵 = 艹(Thảo, biểu nghĩa: cỏ/thực vật) + 癸 (Quý, biểu âm); chữ hình thanh. Phần 艹 chỉ đây là loài thực vật, phần 癸 cho âm đọc kuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quỳ\": cỏ 艹 có họ quý giá 癸 — 葵 là hoa quỳ/cẩm quỳ; 向日葵 là hoa hướng dương luôn quay theo mặt trời. | Gương Hán-Việt | quỳ trong ''hướng nhật quỳ'' (向日葵) — hoa hướng dương; ''quỳ hoa'' trong thơ văn | Mở khoá kiến thức | Biết 葵 mở khoá từ 向日葵 (hoa hướng dương), 蜀葵 (cẩm quỳ), 秋葵 (đậu bắp).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 艸/艹(thảo) biểu nghĩa chỉ cỏ/cây, 癸 (quý) biểu âm. 葵 chỉ nhiều loại cây họ cẩm quỳ — đặc biệt 向日葵 (hoa hướng dương). Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoa quỳ", "Hạng Tần Suất (Jun Da)": "3573.0", "Tần Suất % (Jun Da)": "99.5832344939", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葵", "Unihan_Traditional (Chữ Phồn thể)": "葵", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ các loại cây thuộc họ quỳ hoặc hoa hướng dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哝', '{"9000": "3574.0", "Chữ Trung Quốc": "哝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng | 農 | nông | biểu âm | 哝 = 口 (Khẩu, biểu nghĩa: miệng) + 農 (Nông, biểu âm); chữ hình thanh. Phần 口 chỉ đây là âm thanh phát ra từ miệng, phần 農 cho âm đọc nóng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nông\": miệng 口 nông (nông cạn, nhỏ) — 哝 là nói lầm bầm thì thầm, giọng khe khẽ. | Gương Hán-Việt | nông trong ''thị thầm nông nông'' — tiếng lầm bầm khe khẽ | Mở khoá kiến thức | Biết 哝 mở khoá từ 咕哝 (lầm bầm), 嘟哝 (lầm bầm phàn nàn) thường gặp trong văn miêu tả.", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu) biểu nghĩa chỉ miệng/lời nói, 農 biểu âm. Dạng cổ 噥 cũng ghi nhận trong Wiktionary. 哝 chỉ tiếng nói lầm bầm, thì thầm không rõ lời. Thường gặp trong từ 咕哝 (lầm bầm) và các từ láy mô phỏng âm thanh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói lẩm bẩm", "Hạng Tần Suất (Jun Da)": "3574.0", "Tần Suất % (Jun Da)": "99.5837207887", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 农", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口农", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "农", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哝", "Unihan_Traditional (Chữ Phồn thể)": "噥", "Pinyin_Xie": "nóng", "Âm Hán Việt_Xie": "nông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong từ ghép để miêu tả hành động nói nhỏ hoặc lẩm bẩm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酣', '{"9000": "3575.0", "Chữ Trung Quốc": "酣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 12 | nét | 酉 | dấu | biểu nghĩa | rượu, men rượu | 甘 | cam | biểu âm | ngọt | 酣 = 酉 (Dậu, biểu nghĩa: rượu) + 甘 (Cam, biểu âm; cũng gợi nghĩa ngọt); chữ hình thanh. Wiktionary ghi ls=psc và ls2=ic — vừa hình thanh vừa có gợi ý nghĩa từ 甘 (ngọt = uống ngon). Phần 酉 chỉ rượu, 甘 cho âm đọc hān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": rượu 酉 ngọt ngào 甘 đến say mê — 酣 là uống thỏa thích, miệt mài say sưa trong công việc hay giải trí. | Gương Hán-Việt | hàm trong ''hàm thụy'' (酣睡) — ngủ say; ''hàm xướng'' (酣畅) — vui vẻ thỏa mãn | Mở khoá kiến thức | Biết 酣 mở khoá từ 酣睡 (ngủ say), 酣畅 (vui vẻ), 酣战 (chiến đấu dữ dội).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh (và hội ý phụ): 酉 (dậu) biểu nghĩa chỉ rượu, 甘 (cam) biểu âm — nhưng 甘 cũng gợi nghĩa ngọt ngào/thỏa mãn khi uống rượu. 酣 chỉ trạng thái uống rượu say sưa đến mức thỏa mãn, hoặc làm gì đó say mê miệt mài. Đại triện và tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "uống rượu say sưa; miệt mài, mải miết, ham", "Hạng Tần Suất (Jun Da)": "3575.0", "Tần Suất % (Jun Da)": "99.5842060499", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 甘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉甘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酣", "Unihan_Traditional (Chữ Phồn thể)": "酣", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Dùng làm tính từ hoặc phó từ để miêu tả trạng thái say sưa hoặc làm việc gì đó một cách say mê. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('麓', '{"9000": "3576.0", "Chữ Trung Quốc": "麓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鹿 | Số nét | 19 | nét | 林 | lâm | biểu nghĩa | rừng cây | 鹿 | lộc | biểu âm | 麓 = 林 (Lâm, biểu nghĩa: rừng) + 鹿 (Lộc, biểu âm); chữ hình thanh. Phần 林 chỉ đây là khu rừng/cây cỏ, phần 鹿 cho âm đọc lù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\": rừng 林 dưới chân núi — nơi hươu 鹿 dạo chơi là chỗ 麓 (chân núi). | Gương Hán-Việt | lộc trong ''sơn lộc'' (山麓) — chân núi; 岳麓 trong Nhạc Lộc Thư Viện | Mở khoá kiến thức | Biết 麓 mở khoá từ 山麓 (chân núi) và tên Nhạc Lộc Thư Viện (岳麓书院) nổi tiếng.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 林 (lâm) biểu nghĩa chỉ rừng cây, 鹿 (lộc) biểu âm. 麓 chỉ chân núi — nơi có rừng ở dưới chân núi, là nơi hươu nai thường lui tới. Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chân núi", "Hạng Tần Suất (Jun Da)": "3576.0", "Tần Suất % (Jun Da)": "99.5846913112", "GavinGrover_Once (Chiết tự trực tiếp)": "林 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱林鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "林", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鹿", "Unihan_Simplified (Chữ Giản thể)": "麓", "Unihan_Traditional (Chữ Phồn thể)": "麓", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ khu vực chân núi hoặc rừng rậm ở chân núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钵', '{"9000": "3577.0", "Chữ Trung Quốc": "钵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 钵 | bát | tượng hình | cái bát, chén đựng đồ ăn | 钵 là giản thể của 鉢. Chữ gốc 缽/鉢 gồm bộ kim loại 釒/钅+ phần biểu âm, là chữ hình thanh. 钵 chỉ loại bát/chén dùng trong tu hành Phật giáo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bát\": cái bát kim loại 钅— 钵 là bình bát của nhà sư đi khất thực. | Gương Hán-Việt | bát trong ''bát vu'' (钵盂) — bình bát khất thực; 衣钵 (y bát) — di sản tinh thần truyền lại | Mở khoá kiến thức | Biết 钵 mở khoá từ 衣钵 (y bát: kế thừa di sản tinh thần), 钵盂 trong Phật giáo.", "Tự nguyên_Xie": "Tiểu triện | 钵 là giản thể của 鉢/缽. Chữ hình thanh với bộ kim loại biểu nghĩa. Gốc chỉ bình bát của nhà sư Phật giáo — dụng cụ đi khất thực. Từ tiếng Phạn pātra (bình bát). Tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bát xin ăn của sư", "Hạng Tần Suất (Jun Da)": "3577.0", "Tần Suất % (Jun Da)": "99.5851760556", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 本", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅本", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "本", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钵", "Unihan_Traditional (Chữ Phồn thể)": "缽", "Pinyin_Xie": "bō", "Âm Hán Việt_Xie": "bát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ loại bát ăn hoặc bình khất thực của các nhà sư Phật giáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琅', '{"9000": "3578.0", "Chữ Trung Quốc": "琅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 11 | nét | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 良 | lương | biểu âm | 琅 = 玉/王 (Ngọc, biểu nghĩa: ngọc/đá quý) + 良 (Lương, biểu âm); chữ hình thanh. Phần 玉 chỉ đây là đá quý/ngọc, phần 良 cho âm đọc láng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": ngọc 玉 sáng và 良 lương thiện — 琅 là ngọc trắng tinh; 琅琅 là tiếng đọc sách vang lanh lảnh. | Gương Hán-Việt | lang trong ''lâm lang'' (琳琅) — ngọc quý đẹp; ''lang lang'' (琅琅) — tiếng vang | Mở khoá kiến thức | Biết 琅 mở khoá từ 琅琅上口 (dễ đọc, dễ thuộc), 琳琅满目 (ngập tràn đồ đẹp).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 玉 (ngọc) biểu nghĩa chỉ đá quý, 良 (lương) biểu âm. 琅 gốc chỉ loại ngọc bạch màu trắng tinh khiết. Nghĩa mở rộng: trong sáng, âm thanh lanh lảnh (琅琅: tiếng đọc sách vang). Đại triện và tiểu triện ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại đá giống như ngọc); tiếng kim loại chạm nhau loảng xoảng, tiếng lanh lảnh; trong sạch, thuần khiết; họ Lang", "Hạng Tần Suất (Jun Da)": "3578.0", "Tần Suất % (Jun Da)": "99.5856608001", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 良", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王良", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "良", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琅", "Unihan_Traditional (Chữ Phồn thể)": "琅", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ một loại đá đẹp giống ngọc hoặc làm tính từ mô tả âm thanh trong trẻo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簸', '{"9000": "3579.0", "Chữ Trung Quốc": "簸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 19 | nét | 竹 | trúc | biểu nghĩa | tre, vật làm bằng tre | 其 | kỳ | tham khảo hình thức | thành phần trung gian | 皮 | bì | biểu âm | da, vỏ | 簸 = 竹 (Trúc, biểu nghĩa: tre) + 𤿺 (gồm 其+皮). Wiktionary có glyphOrigin nhưng lsCodes rỗng — không xác định rõ hình thanh hay hội ý. Dựa trên cấu trúc: bộ 竹 gợi vật dụng làm bằng tre (nia, sàng); phần dưới gợi âm. Chữ chưa xác định rõ cấu trúc, chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bá\": cái nia (竹 — làm bằng tre) dùng để sảy thóc, lắc qua lắc lại (颠簸 — lắc lư). | Gương Hán-Việt | \"bá\" ít dùng độc lập; gặp trong 颠簸 (điên bá — lắc lư), 簸箕 (bá ki — cái nia/cái xẻng) | Mở khoá kiến thức | Biết 簸 mở khoá 颠簸 (lắc lư trên đường), 簸箕 (cái nia/cái xẻng hốt rác).", "Tự nguyên_Xie": "Chữ 簸 (bá) gồm bộ 竹 (Trúc) ở trên biểu nghĩa (vật làm bằng tre), phần dưới 𤿺 (phân tích thành 其 và 皮) có thể là biểu âm. Wiktionary xác nhận chữ cổ (Middle Chinese và Old Chinese), nghĩa gốc là sàng sảy lúa (winnow) và lắc lư (jolt). Chưa có nguồn học thuật xác định rõ cấu trúc ls. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sàng, cái nia", "Hạng Tần Suất (Jun Da)": "3579.0", "Tần Suất % (Jun Da)": "99.5861450277", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 𤿺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮𤿺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𤿺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簸", "Unihan_Traditional (Chữ Phồn thể)": "簸", "Pinyin_Xie": "bǒ", "Âm Hán Việt_Xie": "bá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Dùng làm động từ với nghĩa sàng sảy, rung lắc hoặc làm danh từ chỉ cái nia, cái sàng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('禾', '{"9000": "3580.0", "Chữ Trung Quốc": "禾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 5 | nét | 禾 | hòa | tượng hình | cây lúa, cây ngũ cốc đang mang hạt | 禾 là chữ tượng hình: vẽ cây lúa/ngũ cốc đang uốn cong đầu vì nặng hạt. Dạng cổ trong giáp cốt văn và kim văn rõ hình cây với bông hạt. Đây là bộ thủ của rất nhiều chữ liên quan đến lúa gạo và nông nghiệp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hòa\": cây lúa uốn cong đầu vì nặng hạt — 禾 là lúa, là bộ thủ của mọi chữ nông nghiệp. | Gương Hán-Việt | hòa trong ''hòa cốc'' (禾谷) — ngũ cốc; 禾苗 (hòa miêu) — mạ lúa | Mở khoá kiến thức | Biết 禾 mở khoá bộ thủ của hàng chục chữ: 种、科、程、稻、稳、积... tất cả liên quan nông nghiệp.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary: 禾 là tượng hình vẽ thân cây ngũ cốc (lúa, kê...) đang mang hạt, đầu hơi cúi xuống. Dạng cổ trong giáp cốt rõ ràng hơn. Sau đó phát sinh chữ 株 và 硃 từ 禾. Chú ý: hình dạng tương tự 來 nhưng không liên quan; cũng không liên quan đến 釆. Có giáp cốt văn, kim văn, đại triện, tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "117.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (108)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình cây lúa chín có bông nặng trĩu (nét phẩy trên chữ Mộc) khiến phần ngọn rủ xuống.", "Nghĩa Tiếng Việt_Xie": "lúa, mạ", "Hạng Tần Suất (Jun Da)": "3580.0", "Tần Suất % (Jun Da)": "99.5866287386", "GavinGrover_Once (Chiết tự trực tiếp)": "㇒ + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㇒木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "禾", "Unihan_Traditional (Chữ Phồn thể)": "禾", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hoà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ để chỉ cây lúa, mạ hoặc các loại cây lương thực nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铢', '{"9000": "3581.0", "Chữ Trung Quốc": "铢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 铢 | thù | tượng hình | đơn vị đo lường kim loại, bằng 1/24 lạng | 铢 là giản thể của 銖. Chữ gốc 銖 gồm 釒/钅(kim: kim loại) + 朱 biểu âm — chữ hình thanh. Phần 钅chỉ đây là đơn vị đo lường kim loại/tiền tệ, phần 朱 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thù\": kim loại 钅tính từng thù nhỏ — 铢 là đơn vị trọng lượng rất nhỏ; 锱铢必较 là kỹ tính đến từng xu. | Gương Hán-Việt | thù trong ''tư thù tất giảo'' (锱铢必较) — tính toán từng chút nhỏ nhặt | Mở khoá kiến thức | Biết 铢 mở khoá thành ngữ 锱铢必较 và hiểu hệ đo lường cổ Trung Hoa.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 铢 là giản thể của 銖, chữ hình thanh: 釒(kim) biểu nghĩa chỉ kim loại/trọng lượng, 朱 biểu âm. 铢 là đơn vị đo trọng lượng cổ của Trung Hoa, bằng 1/24 lạng (khoảng 0.65 gram). Thường gặp trong thành ngữ 锱铢必较 (kỹ tính từng chút). Tiểu triện và lục thư thông ghi nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thù (đơn vị đo, bằng 1/24 lạng)", "Hạng Tần Suất (Jun Da)": "3581.0", "Tần Suất % (Jun Da)": "99.5871124495", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铢", "Unihan_Traditional (Chữ Phồn thể)": "銖", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "thù", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Dùng làm danh từ hoặc lượng từ chỉ đơn vị đo trọng lượng rất nhỏ thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璧', '{"9000": "3582.0", "Chữ Trung Quốc": "璧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 18 | nét | 辟 | tích | biểu âm | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 璧 = 辟 (Tích, biểu âm) + 玉 (Ngọc, biểu nghĩa: ngọc quý); chữ hình thanh. Phần 玉 chỉ đây là đồ ngọc, phần 辟 cho âm đọc bì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bích\": ngọc 玉 tròn hoàn hảo — 璧 là viên ngọc bích tuyệt tác; 完璧归赵 là hoàn trả nguyên vẹn. | Gương Hán-Việt | bích trong ''hoàn bích quy Triệu'' (完璧归赵) — trả lại nguyên vẹn; ''Hòa Thị bích'' (和氏璧) — ngọc quý nhất | Mở khoá kiến thức | Biết 璧 mở khoá điển tích 完璧归赵, 珠联璧合 và toàn bộ từ vựng về ngọc quý trong thành ngữ.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Chữ hình thanh: 辟 biểu âm, 玉 (ngọc) biểu nghĩa. 璧 chỉ loại ngọc tròn có lỗ ở giữa — vật lễ nghi cao quý nhất trong văn hóa Trung Hoa cổ đại. Gắn với điển tích 和氏璧 (Ngọc Hòa Thị) và 完璧归赵 (hoàn ngọc về Triệu). Giáp cốt văn, kim văn, bạch thư, đại triện, tiểu triện đều ghi nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc bích", "Hạng Tần Suất (Jun Da)": "3582.0", "Tần Suất % (Jun Da)": "99.5875925429", "GavinGrover_Once (Chiết tự trực tiếp)": "辟 + 玉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱辟玉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "玉", "Unihan_Simplified (Chữ Giản thể)": "璧", "Unihan_Traditional (Chữ Phồn thể)": "璧", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ miếng ngọc tròn có lỗ hoặc làm thành phần trong các từ ghép chỉ đồ quý giá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娠', '{"9000": "3583.0", "Chữ Trung Quốc": "娠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 辰 | thìn | biểu âm | can chi thứ năm | 娠 = 女 (Nữ, biểu nghĩa: phụ nữ) + 辰 (Thìn, biểu âm); chữ hình thanh. Bộ 女 chỉ nghĩa liên quan đến phụ nữ, phần 辰 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thần\": người phụ nữ (女) mang con trong bụng như tinh tú (辰) ẩn trong lòng đất — thai nghén, ấp ủ. | Gương Hán-Việt | thần trong \"mang thần\" (mang thai) — ít dùng độc lập, thường gặp trong \"thai thần\" hay \"thụ thai\" | Mở khoá kiến thức | Biết 娠 mở khoá từ 妊娠 (nhâm thần — mang thai, thuật ngữ y học).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 娠 là chữ hình thanh: 女 (nữ, biểu nghĩa: phụ nữ) kết hợp với 辰 (thìn, biểu âm). Chữ chỉ trạng thái mang thai của người phụ nữ. Chỉ thấy dạng tiểu triện, chưa có giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đàn bà có chửa", "Hạng Tần Suất (Jun Da)": "3583.0", "Tần Suất % (Jun Da)": "99.5880721195", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 辰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女辰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娠", "Unihan_Traditional (Chữ Phồn thể)": "娠", "Pinyin_Xie": "shēn", "Âm Hán Việt_Xie": "thần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong các từ ghép y học hoặc văn viết để chỉ việc thụ thai và mang thai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('彗', '{"9000": "3584.0", "Chữ Trung Quốc": "彗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 彐 | Số nét | 11 | nét | 甡 | biểu nghĩa | cái chổi | 又 | hựu | biểu nghĩa | bàn tay | 彗 = 甡 (hình chổi tre, biểu nghĩa) + 又 (Hựu, biểu nghĩa: bàn tay); chữ hội ý. Hai phần kết hợp ý nghĩa: tay cầm chổi — hành động quét dọn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuệ\": tay (又) cầm chổi (甡) quét sạch — như trí tuệ (慧) quét sạch vô minh, hay sao chổi quét qua bầu trời đêm. | Gương Hán-Việt | tuệ trong \"tuệ tinh\" (sao chổi) — cùng âm đọc với 慧 (trí tuệ) | Mở khoá kiến thức | Biết 彗 mở khoá: 彗星 (tuệ tinh — sao chổi), phân biệt với 慧 (tuệ — thông minh).", "Tự nguyên_Xie": "Giáp cốt văn | Đại triện | Tiểu triện | Theo Wiktionary, 彗 là chữ hội ý: 甡 (hình cái chổi bằng tre) cộng với 又 (bàn tay cầm). Hình ảnh người cầm chổi để quét. Giáp cốt văn và đại triện đều cho thấy hình dạng chổi rõ ràng. Nghĩa mở rộng sang ''sao chổi'' vì đuôi sao chổi trông như cái chổi quét trên bầu trời. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "182.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Phong (78) Hựu (159)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hai chữ Phong (số 78) trên chữ Hựu (số 159 - biến thể) . Hình ảnh bàn tay cầm cái chổi làm từ rơm cỏ tươi tốt.", "Nghĩa Tiếng Việt_Xie": "sao chổi; cái chổi; quét", "Hạng Tần Suất (Jun Da)": "3584.0", "Tần Suất % (Jun Da)": "99.5885506626", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 彐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "彗", "Unihan_Traditional (Chữ Phồn thể)": "彗", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "tuệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường xuất hiện trong từ ghép để chỉ sao chổi hoặc hành động quét dọn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惋', '{"9000": "3585.0", "Chữ Trung Quốc": "惋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | trái tim, cảm xúc | 宛 | uyển | biểu âm | uyển chuyển, như thể | 惋 = 忄 (Tâm, biểu nghĩa: trái tim) + 宛 (Uyển, biểu âm). Wiktionary có glyphOrigin nhưng không ghi lsCodes; cấu trúc phono-semantic hợp lý: 忄 chỉ cảm xúc, 宛 gợi âm wǎn. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oản\": trái tim (忄) quặn thắt uyển chuyển (宛) — cảm giác tiếc nuối, xót xa trong lòng. | Gương Hán-Việt | \"oản\" trong 惋惜 (oản tích — tiếc nuối); Hán-Việt ít dùng độc lập | Mở khoá kiến thức | Biết 惋 mở khoá 惋惜 (tiếc nuối), 惆惋 (sầu muộn).", "Tự nguyên_Xie": "Chữ 惋 (oản) gồm bộ 忄 (Tâm — trái tim, cảm xúc) và 宛 (Uyển) biểu âm. Wiktionary xác nhận chữ cổ (mc=y, oc=y), nghĩa là thở dài tiếc nuối (sigh, regret) và buồn bã. Không có nguồn mô tả chi tiết hơn về cấu trúc ngoài danh sách hợp chất. Chưa có nguồn học thuật xác nhận ls. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đau tiếc, ân hận; hãi hùng, ghê sợ", "Hạng Tần Suất (Jun Da)": "3585.0", "Tần Suất % (Jun Da)": "99.5890286888", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惋", "Unihan_Traditional (Chữ Phồn thể)": "惋", "Pinyin_Xie": "wǎn", "Âm Hán Việt_Xie": "oản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với các từ khác để biểu thị trạng thái tiếc nuối hoặc đau buồn trước một sự việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('腋', '{"9000": "3586.0", "Chữ Trung Quốc": "腋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 12 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 夜 | dạ | biểu âm | đêm | 腋 = 肉/月 (Nhục, biểu nghĩa: thân thể) + 夜 (Dạ, biểu âm); chữ hình thanh. Bộ nhục (月) chỉ bộ phận cơ thể, phần 夜 cho âm đọc gần với yè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nách\": bộ nhục (月) bên cạnh chữ đêm (夜) — phần thân thể khuất lấp như bóng tối ban đêm, chính là nách. | Gương Hán-Việt | nách trong \"mùi nách\", \"hõm nách\" — từ Hán-Việt dùng trực tiếp làm từ thuần Việt | Mở khoá kiến thức | Biết 腋 mở khoá: 腋窝 (nách oa — hõm nách), 腋下 (nách hạ — vùng dưới nách).", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 腋 là chữ hình thanh từ 肉 (thịt/thân thể) và 夜 (biểu âm). Ban đầu chữ này được viết là 亦 — xem thêm ở mục đó. Dạng hiện tại thêm bộ nhục để chỉ rõ đây là bộ phận cơ thể. Chỉ thấy dạng lục thư thông, chưa có dạng cổ xưa hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nách", "Hạng Tần Suất (Jun Da)": "3586.0", "Tần Suất % (Jun Da)": "99.589506715", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 夜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月夜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "腋", "Unihan_Traditional (Chữ Phồn thể)": "腋", "Pinyin_Xie": "yè", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ bộ phận nách trên cơ thể người hoặc phần dưới cánh của loài chim. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螂', '{"9000": "3587.0", "Chữ Trung Quốc": "螂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 螂 | lang | tượng hình | chữ chỉ côn trùng, thường dùng trong tên ghép | 螂 là chữ dùng trong tên ghép chỉ các loài côn trùng: 螳螂 (bọ ngựa), 蟑螂 (gián), 蜣螂 (bọ hung). Cấu trúc phân tích không rõ ràng từ anchor, chữ chủ yếu là thành tố phiên âm trong hợp từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lang\": âm lang vang lên mỗi khi nhắc các loài côn trùng —螳螂 (đường lang, bọ ngựa), 蟑螂 (chương lang, gián), đều kết thúc bằng 螂. | Gương Hán-Việt | lang trong \"đường lang\" (螳螂 — bọ ngựa), \"chương lang\" (蟑螂 — gián) | Mở khoá kiến thức | Biết 螂 mở khoá: 螳螂 (đường lang — bọ ngựa), 蟑螂 (gián), 蜣螂 (bọ hung).", "Tự nguyên_Xie": "Tiểu triện | 螂 hầu như không dùng độc lập; chỉ xuất hiện trong các từ ghép chỉ côn trùng như 螳螂 (bọ ngựa), 蟑螂 (gián), 蜣螂 (bọ hung phân). Wiktionary không cung cấp phân tích nguồn gốc rõ ràng cho ký tự này. Chỉ thấy dạng tiểu triện. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đường lang 螳螂, khương lang 蜣蜋, chương lang 蟑螂)", "Hạng Tần Suất (Jun Da)": "3587.0", "Tần Suất % (Jun Da)": "99.5899847413", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 郎", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫郎", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "郎", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螂", "Unihan_Traditional (Chữ Phồn thể)": "蜋", "Pinyin_Xie": "láng", "Âm Hán Việt_Xie": "lang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này không đứng một mình mà làm hậu tố trong tên một số loài côn trùng như bọ ngựa hay con gián. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阪', '{"9000": "3588.0", "Chữ Trung Quốc": "阪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 阜 | Số nét | 6 | nét | 阝 | biểu nghĩa | đất cao, gò đồi | 反 | phản | biểu âm | ngược lại | 阪 = 阝(bộ phụ/阜, biểu nghĩa: đất cao, đồi gò) + 反 (Phản, biểu âm); chữ hình thanh. Bộ 阝bên trái (阜) chỉ địa hình cao, phần 反 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phản\": bộ đồi (阝) kết hợp phần âm phản (反) — sườn dốc ngược chiều mặt phẳng, như con đường đèo phản chiều lên cao. | Gương Hán-Việt | phản ít dùng độc lập; thường gặp trong địa danh như 大阪 (Đại Phản — Osaka, Nhật Bản) | Mở khoá kiến thức | Biết 阪 mở khoá địa danh: 大阪 (Osaka), 阪上走丸 (thành ngữ: lăn bi trên dốc — việc thuận chiều dễ dàng).", "Tự nguyên_Xie": "Bạch thư | Theo Wiktionary, 阪 là chữ hình thanh: 阜 (đất cao, rút gọn thành 阝) là phần biểu nghĩa, 反 là phần biểu âm. Nghĩa gốc là sườn đồi, dốc núi. Có dạng bạch thư (văn bản trên lụa). Xuất hiện trong Kinh Thi: \"trên sườn đồi có cây sơn, ở chỗ thấp ướt có cây hạt dẻ\". | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sườn núi", "Hạng Tần Suất (Jun Da)": "3588.0", "Tần Suất % (Jun Da)": "99.5904622508", "GavinGrover_Once (Chiết tự trực tiếp)": "阝 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰阝反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "阝", "Unihan_Simplified (Chữ Giản thể)": "阪", "Unihan_Traditional (Chữ Phồn thể)": "阪", "Pinyin_Xie": "bǎn", "Âm Hán Việt_Xie": "phản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh hoặc từ ghép để chỉ địa hình sườn dốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掣', '{"9000": "3589.0", "Chữ Trung Quốc": "掣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 制 | chế | biểu âm | chế độ, kiểm soát | 手 | thủ | biểu nghĩa | bàn tay | 掣 = 制 (Chế, biểu âm) + 手 (Thủ, biểu nghĩa: bàn tay); chữ hình thanh. Bộ thủ chỉ hành động của tay, phần 制 cho âm đọc gần với chè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xiết\": tay (手) xiết chặt theo kiểu kiểm soát (制) — kéo giật, cầm lại không cho thoát. | Gương Hán-Việt | xiết trong \"kiềm xiết\" (kiềm chế) — tay xiết chặt, giữ lại | Mở khoá kiến thức | Biết 掣 mở khoá: 掣肘 (xiết trụ — cản trở, kéo cùi chỏ), 风驰电掣 (thành ngữ: nhanh như chớp).", "Tự nguyên_Xie": "Theo Wiktionary, 掣 là chữ hình thanh: 手 (bàn tay) là phần biểu nghĩa, 制 là phần biểu âm. Nghĩa là kéo giật, lôi kéo, cản trở bằng cách giật lại. Không có ảnh etymology — chưa tìm được dạng tiền tiểu triện. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kéo, lôi", "Hạng Tần Suất (Jun Da)": "3589.0", "Tần Suất % (Jun Da)": "99.5909387267", "GavinGrover_Once (Chiết tự trực tiếp)": "制 + 手", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱制手", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "制", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "手", "Unihan_Simplified (Chữ Giản thể)": "掣", "Unihan_Traditional (Chữ Phồn thể)": "掣", "Pinyin_Xie": "chè", "Âm Hán Việt_Xie": "xiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong các từ ghép chỉ sự cản trở hoặc chuyển động nhanh như chớp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('劾', '{"9000": "3590.0", "Chữ Trung Quốc": "劾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 力 | Số nét | 8 | nét | 亥 | hợi | biểu âm | can chi thứ mười hai | 力 | lực | biểu nghĩa | sức lực, quyền lực | 劾 = 亥 (Hợi, biểu âm) + 力 (Lực, biểu nghĩa: sức mạnh, quyền lực); chữ hình thanh. Bộ lực chỉ hành động có quyền uy, phần 亥 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạch\": sức mạnh pháp quyền (力) buộc tội (亥 âm hạch) — dùng quyền lực để hạch sách, điều tra tội trạng. | Gương Hán-Việt | hạch trong \"đàn hạch\" (弹劾 — luận tội, bãi miễn), \"hạch tội\" — quen dùng trong văn bản pháp lý | Mở khoá kiến thức | Biết 劾 mở khoá: 弹劾 (đàn hạch — luận tội, impeach), 参劾 (tham hạch — tố giác, truy tố).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 劾 là chữ hình thanh: 力 (lực, sức mạnh/quyền lực) là phần biểu nghĩa, 亥 là phần biểu âm. Nghĩa là vạch tội, hạch tội, buộc tội người có chức vụ. Có dạng tiểu triện và lục thư thông. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạch tội", "Hạng Tần Suất (Jun Da)": "3590.0", "Tần Suất % (Jun Da)": "99.5914152026", "GavinGrover_Once (Chiết tự trực tiếp)": "亥 + 力", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亥力", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "力", "Unihan_Simplified (Chữ Giản thể)": "劾", "Unihan_Traditional (Chữ Phồn thể)": "劾", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong các từ ghép liên quan đến việc luận tội quan lại hoặc điều tra sai phạm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沥', '{"9000": "3591.0", "Chữ Trung Quốc": "沥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 水 | thủy | biểu nghĩa | nước | 歷 | lịch | biểu âm | trải qua | 沥 = 水/氵 (Thủy, biểu nghĩa: nước) + 歷 (Lịch, biểu âm); chữ hình thanh. Bộ tam thủy chỉ chất lỏng, phần 歷 cho âm đọc. Dạng phồn thể là 瀝.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lịch\": nước (氵) nhỏ từng giọt như thời gian trôi qua (歷 lịch) — từng giọt, từng giọt rỉ ra. | Gương Hán-Việt | lịch trong \"lịch thanh\" (沥青 — nhựa đường, nhựa than đá) | Mở khoá kiến thức | Biết 沥 mở khoá: 沥青 (lịch thanh — nhựa đường/asphalt), 淅沥 (tí tách — tiếng mưa rơi).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 瀝/沥 là chữ hình thanh: 水 (nước) là phần biểu nghĩa, 歷 là phần biểu âm. Nghĩa gốc là nhỏ giọt, rỉ ra từng giọt. Mở rộng sang nghĩa lọc, cặn bã. Có dạng tiểu triện. Từ 沥青 (nhựa đường) phổ biến trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ giọt, giỏ giọt; giọt nước; lọc", "Hạng Tần Suất (Jun Da)": "3591.0", "Tần Suất % (Jun Da)": "99.5918896113", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 历", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵历", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "历", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沥", "Unihan_Traditional (Chữ Phồn thể)": "瀝", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ chỉ sự nhỏ giọt, chảy ròng ròng hoặc biểu thị sự chân thành hết lòng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('粱', '{"9000": "3592.0", "Chữ Trung Quốc": "粱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 13 | nét | 粱 | lương | tượng hình | loại ngũ cốc tốt, cao lương | 粱 là chữ độc thể, không có cấu trúc hình thanh hay hội ý rõ ràng trong dữ liệu hiện có. Dạng tiểu triện cho thấy hình ảnh bông lúa miến. Chữ chỉ loại ngũ cốc chất lượng cao.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lương\": hạt lương thực (粱) cao cấp — 高粱 là cây cao lương (sorghum), nguyên liệu nấu rượu Mao Đài; 黄粱一梦 là giấc mộng đẹp tan như hơi. | Gương Hán-Việt | lương trong \"cao lương\" (高粱 — lúa miến, sorghum), \"lương thực\" — hạt ngũ cốc tốt | Mở khoá kiến thức | Biết 粱 mở khoá: 高粱 (cao lương — lúa miến), 黄粱一梦 (hoàng lương nhất mộng — giấc mộng phù du).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu tạo chữ rõ ràng cho 粱. Chỉ có dạng tiểu triện. Nghĩa gốc là loại kê/lúa miến tốt, lương thực cao cấp. 高粱 (cao lương) là từ phổ biến nhất. Thành ngữ 黄粱一梦 (giấc mộng hoàng lương) xuất phát từ truyện cổ về giấc ngủ trong lúc nấu cơm kê. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gạo lúa mạch", "Hạng Tần Suất (Jun Da)": "3592.0", "Tần Suất % (Jun Da)": "99.5923640201", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "粱", "Unihan_Traditional (Chữ Phồn thể)": "粱", "Pinyin_Xie": "liáng", "Âm Hán Việt_Xie": "lương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các loại ngũ cốc hạt mịn hoặc lương thực ngon nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚓', '{"9000": "3593.0", "Chữ Trung Quốc": "嚓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 17 | nét | 嚓 | xát | tượng hình | chữ tượng thanh mô phỏng âm thanh | 嚓 là chữ tượng thanh, không có cấu trúc hình thanh hay hội ý được ghi chép trong nguồn học thuật hiện có. Chữ miêu tả tiếng động khi vật gì đó gãy, vỡ hoặc tiếng cười khúc khích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xát\": âm đọc xát — như tiếng cọ xát, gãy vụn đột ngột (嚓 — tiếng động bộp, xoạc). | Gương Hán-Việt | xát ít gặp trong văn Hán-Việt; chữ chủ yếu dùng phiên âm tượng thanh như 喀嚓 (kā cā — tiếng gãy, click) | Mở khoá kiến thức | Biết 嚓 nhận ra âm tượng thanh: 喀嚓 (kā cā — tiếng gãy/click), 嚓嚓 (cā cā — tiếng cọ xát liên tục).", "Tự nguyên_Xie": "嚓 là chữ tượng thanh hiện đại, mô phỏng âm thanh cạo, vỡ, hoặc tiếng động đột ngột. Wiktionary không có phân tích nguồn gốc cho chữ này. Không có dạng cổ (giáp cốt, kim văn, tiểu triện) được ghi nhận. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tiếng động)", "Hạng Tần Suất (Jun Da)": "3593.0", "Tần Suất % (Jun Da)": "99.5928384288", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 察", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口察", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "察", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚓", "Unihan_Traditional (Chữ Phồn thể)": "嚓", "Pinyin_Xie": "cā", "Âm Hán Việt_Xie": "sát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh để mô tả âm thanh cọ xát, tiếng bước chân hoặc tiếng bẻ gãy. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惮', '{"9000": "3594.0", "Chữ Trung Quốc": "惮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | trái tim, cảm xúc | 单 | thiện | biểu âm | đơn, một mình | 惮 = 忄 (Tâm, biểu nghĩa: trái tim/cảm xúc) + 单 (Thiện, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 心 (忄) cho nghĩa, 單 cho âm dàn. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạn\": trái tim (忄) run lên khi đứng một mình (单) trước thứ đáng sợ — đó là nỗi sợ hãi kinh hoàng. | Gương Hán-Việt | \"đạn\" trong 忌惮 (kị đạn — kiêng sợ), 肆无忌惮 (tứ vô kị đạn — không kiêng nể gì) | Mở khoá kiến thức | Biết 惮 mở khoá 忌惮 (kiêng sợ), 肆无忌惮 (ngang ngược không kiêng ai).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | Chữ 惮 (đạn), dạng phồn thể 憚, là chữ hình thanh (ls=psc): bộ 心 (忄 — Tâm) biểu nghĩa chỉ cảm xúc/nội tâm; 單 (Thiện) biểu âm cho âm dàn. Nghĩa gốc: kinh sợ, run sợ, không dám làm việc gì. Kim văn, đại triện và tiểu triện đều được lưu lại. Thường gặp trong 肆无忌惮 (làm bừa không kiêng nể gì). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kinh sợ, run sợ", "Hạng Tần Suất (Jun Da)": "3594.0", "Tần Suất % (Jun Da)": "99.593311804", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惮", "Unihan_Traditional (Chữ Phồn thể)": "憚", "Pinyin_Xie": "dàn", "Âm Hán Việt_Xie": "đạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để biểu thị sự e ngại hoặc kiêng dè. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氖', '{"9000": "3595.0", "Chữ Trung Quốc": "氖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 6 | nét | 气 | khí | biểu nghĩa | khí, hơi | 乃 | nãi | biểu âm | bèn, mới | 氖 = 气 (Khí, biểu nghĩa: khí/hơi) + 乃 (Nãi, biểu âm); chữ hình thanh. Bộ 气 chỉ chất khí, phần 乃 cho âm đọc nǎi gần với nãi. Chữ hiện đại dùng để phiên âm tên nguyên tố neon (Ne).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nãi\": bộ khí (气) đọc âm nãi (乃) — khí neon phát sáng trong ống đèn neon quen thuộc trên bảng hiệu đường phố. | Gương Hán-Việt | nãi ít dùng độc lập; chữ chuyên dùng trong hoá học để chỉ neon (Ne, số nguyên tử 10) | Mở khoá kiến thức | Biết 氖 nhận ra ký hiệu hoá học: 氖气 (nãi khí — khí neon), gia đình chữ khí: 氧 (oxy), 氢 (hydro), 氮 (nitơ), 氖 (neon).", "Tự nguyên_Xie": "Theo Wiktionary, 氖 là chữ hình thanh hiện đại được tạo ra để phiên âm tên nguyên tố neon: 气 (khí, biểu nghĩa) + 乃 (nãi, biểu âm, không có âm cổ). Đây là chữ tạo muộn dùng trong hoá học, chưa thấy trong giáp cốt/kim văn. Neon là khí trơ, được đặt tên theo tiếng Hy Lạp néon (mới). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố neon, khí neon, Ne", "Hạng Tần Suất (Jun Da)": "3595.0", "Tần Suất % (Jun Da)": "99.5937846624", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 乃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气乃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氖", "Unihan_Traditional (Chữ Phồn thể)": "氖", "Pinyin_Xie": "nǎi", "Âm Hán Việt_Xie": "nãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ nguyên tố hóa học, thường dùng trong văn bản khoa học hoặc ghép thành từ chỉ đèn neon. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捎', '{"9000": "3596.0", "Chữ Trung Quốc": "捎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 10 | nét | 扌 | thủ | biểu nghĩa | tay | 肖 | tiêu | biểu âm | giống, nhỏ lại | 捎 = 扌 (Thủ, biểu nghĩa: tay) + 肖 (Tiêu, biểu âm). Wiktionary chỉ ghi {{Han etym}} không có chi tiết lsCodes; cấu trúc phono-semantic hợp lý: 扌 chỉ hành động tay, 肖 gợi âm shāo. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sao\": tay (扌) nhẹ nhàng như bóng nhỏ (肖) — nhặt lên và mang theo nhờ trên đường. | Gương Hán-Việt | \"sao\" ít dùng độc lập trong tiếng Việt; 捎 xuất hiện trong 捎带 (mang theo), 捎信 (nhờ chuyển thư) | Mở khoá kiến thức | Biết 捎 mở khoá 捎带 (tiện tay mang theo), 捎信 (nhờ người chuyển thư/tin).", "Tự nguyên_Xie": "Tiểu triện | Chữ 捎 (sao) gồm bộ 扌 (Thủ — tay) biểu nghĩa và 肖 (Tiêu) biểu âm. Wiktionary chỉ ghi {{Han etym}} chung, không mô tả chi tiết glyph origin. Tiểu triện được lưu tại wikimedia. Nghĩa cơ bản: dùng tay mang đi nhờ, đem theo trên đường; cũng nghĩa là lướt qua, phẩy nhẹ. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lướt qua, phẩy qua", "Hạng Tần Suất (Jun Da)": "3596.0", "Tần Suất % (Jun Da)": "99.5942564872", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 肖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌肖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捎", "Unihan_Traditional (Chữ Phồn thể)": "捎", "Pinyin_Xie": "shāo", "Âm Hán Việt_Xie": "siếu, sao, tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong khẩu ngữ để nhờ mang hộ đồ vật hoặc truyền đạt lời nhắn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | shāo | / | mang theo; đem theo | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Sự chuyển động | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羔', '{"9000": "3597.0", "Chữ Trung Quốc": "羔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 10 | nét | 羊 | dương | biểu nghĩa | dê, cừu | 灬 | biểu nghĩa | lửa | 羔 = 羊 (Dương, biểu nghĩa: dê/cừu) + 灬 (lửa, biểu nghĩa); chữ hội ý. Hình ảnh con dê non trên lửa — loài vật non trẻ thích hợp để nấu ăn. Thuyết Văn Giải Tự cũng ghi nhận cách đọc psc với 照 làm âm, nhưng giải thích hội ý phổ biến hơn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": dê (羊) nhỏ trên lửa (灬) — con dê non (羔羊) mềm mại, đáng thương như con cừu tế thần. | Gương Hán-Việt | cao trong \"cao dương\" (羔羊 — dê con, cừu non), \"đại tội cao dương\" (替罪羔羊 — vật tế thần, người chịu oan) | Mở khoá kiến thức | Biết 羔 mở khoá: 羔羊 (cao dương — dê/cừu non), 替罪羔羊 (thế tội cao dương — vật tế thần, người gánh oan).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 羔 là chữ hội ý: 羊 (dương — dê/cừu) + 火/灬 (lửa). Hình ảnh con dê non đang được nướng trên lửa — dê con vốn được coi là thức ăn ngon. Nghĩa mở rộng sang ''non trẻ'', ''vật nhỏ''. Có dạng tiểu triện. Thuyết Văn Giải Tự cũng có giải thích phiên thanh với 照 nhưng giải thích hội ý được chấp nhận rộng hơn. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con dê non", "Hạng Tần Suất (Jun Da)": "3597.0", "Tần Suất % (Jun Da)": "99.5947272785", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羔", "Unihan_Traditional (Chữ Phồn thể)": "羔", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ con non của loài dê hoặc cừu, thường kết hợp để chỉ thịt hoặc da của chúng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俟', '{"9000": "3598.0", "Chữ Trung Quốc": "俟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 9 | nét | 亻 | biểu nghĩa | người | 矣 | hĩ | biểu âm | trợ từ kết thúc câu | 俟 = 亻(bộ nhân, biểu nghĩa: người) + 矣 (Hĩ, biểu âm); chữ hình thanh. Bộ nhân chỉ hành động của người, phần 矣 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\": người (亻) đứng chờ cho đến khi xong (矣 hĩ) — chờ đợi kiên nhẫn như người quân tử đợi thời cơ. | Gương Hán-Việt | tứ trong \"俟机\" (tứ cơ — chờ thời cơ) — chủ yếu dùng trong văn ngôn cổ | Mở khoá kiến thức | Biết 俟 mở khoá văn ngôn: 俟机 (tứ cơ — chờ thời cơ), 俟命 (tứ mệnh — chờ lệnh/mệnh trời).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 俟 là chữ hình thanh: 人/亻 (người, biểu nghĩa) + 矣 (hĩ, biểu âm). Nghĩa là chờ đợi, đợi cho đến khi. Dùng nhiều trong văn ngôn với nghĩa ''chờ đến lúc'', ''khi mà''. Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1598.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (009) Hĩ (210)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Nhân đứng (số 009 - con người/ 亻/chỉ ý) ở bên trái chữ Hĩ (số 210 - ngưng nghỉ/ 矣 /chỉ âm). Hình ảnh người đang đứng ngưng nghỉ để đợi. Giải thích sự chuyển ý: Đây là chữ Hình thanh kiêm Hội ý. Chữ Hĩ chỉ âm, bộ Nhân chỉ ý. Sĩ là hành động mong đợi, chờ đợi (đẳng sĩ).", "Nghĩa Tiếng Việt_Xie": "chờ đợi", "Hạng Tần Suất (Jun Da)": "3598.0", "Tần Suất % (Jun Da)": "99.595197553", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 矣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻矣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俟", "Unihan_Traditional (Chữ Phồn thể)": "俟", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "sĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết cổ hoặc kết hợp thành liên từ chỉ thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渲', '{"9000": "3599.0", "Chữ Trung Quốc": "渲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 渲 | huyễn | tượng hình | kỹ thuật phủ màu loãng trong hội hoạ Trung Quốc | 渲 không có cấu trúc hình thanh hay hội ý được ghi nhận trong dữ liệu hiện có. Chữ chỉ kỹ thuật vẽ tranh thủy mặc — dùng mực loãng hoặc màu nhạt phủ lên để tăng hiệu ứng nghệ thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyễn\": màu nước loãng (氵nước) phủ nhẹ lên tranh — 渲染 (huyễn nhiễm) là tô màu phóng đại, như huyễn hoặc mắt người xem. | Gương Hán-Việt | huyễn trong \"huyễn nhiễm\" (渲染 — tô vẽ, phóng đại, render kỹ thuật số) | Mở khoá kiến thức | Biết 渲 mở khoá: 渲染 (huyễn nhiễm — tô màu/phóng đại/render), dùng cả trong mỹ thuật lẫn tin học (3D rendering).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu tạo cho 渲 (thiếu định nghĩa rfdef). Không có dữ liệu giáp cốt hay kim văn. Nghĩa chính là kỹ thuật hội hoạ: phủ lớp màu loãng lên tranh. Từ phổ biến nhất là 渲染 (tô vẽ, diễn đạt phóng đại). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phủ lên; tô lên (một hoạ pháp của hội hoạ Trung Quốc, dùng mực loãng hoặc màu nhạt tô phủ lên tranh đã vẽ để tăng hiệu quả nghệ thuật)", "Hạng Tần Suất (Jun Da)": "3599.0", "Tần Suất % (Jun Da)": "99.5956657603", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渲", "Unihan_Traditional (Chữ Phồn thể)": "渲", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "tuyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong hội họa hoặc ghép thành từ chỉ sự tô vẽ, thổi phồng sự việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榄', '{"9000": "3600.0", "Chữ Trung Quốc": "榄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 覽 | lãm | biểu âm | nhìn toàn cảnh | 榄 = 木 (Mộc, biểu nghĩa: cây) + 覽/览 (Lãm, biểu âm); chữ hình thanh. Dạng phồn thể là 欖. Bộ mộc chỉ loài cây, phần 覽 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãm\": cây (木) đọc theo âm lãm (覽) — cây 橄榄 (cảm lãm) cho quả olive xanh mướt, nhìn (覽) như viên ngọc trên cành. | Gương Hán-Việt | lãm trong \"cảm lãm\" (橄榄 — quả olive, cây olive) | Mở khoá kiến thức | Biết 榄 mở khoá: 橄榄 (cảm lãm — olive), 橄榄油 (cảm lãm du — dầu olive), 橄榄球 (bóng bầu dục).", "Tự nguyên_Xie": "Theo Wiktionary, 欖/榄 là chữ hình thanh: 木 (mộc, cây) là phần biểu nghĩa, 覽 (lãm) là phần biểu âm. Chữ chỉ cây olive (ô liu) trong tiếng Trung. Không có ảnh etymology. Thường dùng trong từ ghép 橄榄 (cảm lãm — quả olive). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: cảm lãm 橄欖,橄榄)", "Hạng Tần Suất (Jun Da)": "3600.0", "Tần Suất % (Jun Da)": "99.5961334508", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 览", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木览", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "览", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榄", "Unihan_Traditional (Chữ Phồn thể)": "欖", "Pinyin_Xie": "lǎn", "Âm Hán Việt_Xie": "lãm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ thực vật, hầu như luôn xuất hiện trong từ ghép để chỉ cây trám hoặc quả ô liu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茧', '{"9000": "3601.0", "Chữ Trung Quốc": "茧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 糸 | biểu nghĩa | tơ lụa | 虫 | trùng | biểu nghĩa | sâu bọ | 黹 | biểu nghĩa | thêu thùa | 茧 = 糸 (tơ, biểu nghĩa) + 虫 (Trùng, biểu nghĩa: sâu bọ) + 黹 (thêu, biểu nghĩa rút gọn); chữ hội ý. Dạng phồn thể là 繭. Ba thành tố cùng chỉ nghĩa: sâu tằm (虫) nhả tơ (糸) dệt thành kén. Ảnh tiểu triện xác nhận hình dạng này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiển\": sâu (虫) nhả tơ (糸) thành kén — tự bao bọc mình như người sợ thế giới bên ngoài tự nhốt trong vỏ kén (作茧自缚). | Gương Hán-Việt | kiển trong \"tàm kiển\" (蚕茧 — kén tằm), \"kiển phú\" (茧缚 — bị kén trói buộc) | Mở khoá kiến thức | Biết 茧 mở khoá: 蚕茧 (tàm kiển — kén tằm), 作茧自缚 (tác kiển tự phọc — tự mình làm khó mình), 老茧 (chai tay).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 繭/茧 là chữ hội ý: 糸 (tơ) + 虫 (sâu bọ) + 黹 (thêu/rút gọn). Hình ảnh con tằm nhả tơ tự bọc mình thành kén. Có dạng tiểu triện rõ ràng. Nghĩa mở rộng sang ''chai tay'', ''bọng da'' vì hình dạng giống kén tằm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kén tằm; mạng nhện; phồng da chân", "Hạng Tần Suất (Jun Da)": "3601.0", "Tần Suất % (Jun Da)": "99.5966006246", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 虫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹虫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茧", "Unihan_Traditional (Chữ Phồn thể)": "繭", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ kén của côn trùng hoặc vết chai sần trên da do lao động. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('霓', '{"9000": "3602.0", "Chữ Trung Quốc": "霓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 雨 | Số nét | 16 | nét | 兒 | biểu âm | đứa trẻ | 雨 | vũ | biểu nghĩa | mưa | 霓 = 兒 (biểu âm) + 雨 (Vũ, biểu nghĩa: mưa); chữ hình thanh. Bộ vũ chỉ hiện tượng khí quyển, phần 兒 cho âm đọc. Chữ chỉ cầu vồng phụ (ngoài cầu vồng chính 虹).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghi\": mưa (雨) tạo ra sắc màu nghi ngờ (兒 âm nghi) — cầu vồng phụ mờ ảo sau mưa, như nghi vấn chưa rõ ràng. | Gương Hán-Việt | nghi trong \"nghi hồng\" (霓虹 — neon, cầu vồng), \"vân nghi\" (雲霓 — mây và cầu vồng — điều mong đợi) | Mở khoá kiến thức | Biết 霓 mở khoá: 霓虹灯 (nghi hồng đăng — đèn neon), 云霓 (vân nghi — mong đợi thiết tha), 霓裳 (nghi thường — áo váy nhiều màu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 霓 là chữ hình thanh: 兒 (biểu âm) + 雨 (vũ, mưa, biểu nghĩa). Chỉ cầu vồng thứ hai (phụ), nhạt hơn và ngược màu so với cầu vồng chính 虹. Có dạng tiểu triện và lục thư thông. Từ 霓虹 (nghi hồng) được dùng để phiên âm ''neon''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhiều màu; cầu vồng", "Hạng Tần Suất (Jun Da)": "3602.0", "Tần Suất % (Jun Da)": "99.5970672816", "GavinGrover_Once (Chiết tự trực tiếp)": "雨 + 兒", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱雨兒", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兒", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "雨", "Unihan_Simplified (Chữ Giản thể)": "霓", "Unihan_Traditional (Chữ Phồn thể)": "蜺", "Pinyin_Xie": "ní", "Âm Hán Việt_Xie": "nghê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ hiện tượng tự nhiên, thường ghép với các từ khác để chỉ ánh đèn màu rực rỡ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹉', '{"9000": "3603.0", "Chữ Trung Quốc": "鹉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 13 | nét | 武 | võ | biểu âm | vũ lực, oai vệ | 鳥 | điểu | biểu nghĩa | chim | 鹉 = 武 (Võ, biểu âm) + 鳥/鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Dạng phồn thể là 鵡. Bộ điểu chỉ loài chim, phần 武 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vũ\": chim (鳥) đọc theo âm vũ (武) — con vẹt 鹦鹉 (anh vũ) oai vệ như võ sĩ, bắt chước lời người như học võ công. | Gương Hán-Việt | vũ trong \"anh vũ\" (鹦鹉 — con vẹt) | Mở khoá kiến thức | Biết 鹉 nhận ra: 鹦鹉 (anh vũ — con vẹt), 鹦鹉螺 (anh vũ loa — con ốc anh vũ, nautilus).", "Tự nguyên_Xie": "Theo Wiktionary, 鵡/鹉 là chữ hình thanh: 武 (võ, biểu âm) + 鳥 (điểu, chim, biểu nghĩa). Chữ chỉ loài vẹt, thường dùng trong từ ghép 鹦鹉 (anh vũ — con vẹt). Không có ảnh etymology hiện có. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vẹt", "Hạng Tần Suất (Jun Da)": "3603.0", "Tần Suất % (Jun Da)": "99.597532905", "GavinGrover_Once (Chiết tự trực tiếp)": "武 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰武鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "武", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹉", "Unihan_Traditional (Chữ Phồn thể)": "鵡", "Pinyin_Xie": "wǔ", "Âm Hán Việt_Xie": "vũ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ loài chim, hầu như chỉ dùng trong từ ghép để chỉ con vẹt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胥', '{"9000": "3604.0", "Chữ Trung Quốc": "胥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 疋 | sất | biểu âm | chân, đi bộ | 月 | nguyệt | biểu nghĩa | thịt (bộ nhục) | 胥 = 疋 (Sất, biểu âm) + 月/肉 (Nhục, biểu nghĩa: thịt/thân thể); chữ hình thanh. Bộ nhục (月) chỉ thân thể, phần 疋 cho âm đọc. Nghĩa mở rộng sang ''tất cả'', ''đồng lòng'' theo nghĩa văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\": thân (月nhục) của quan lại (疋 tư âm) — viên tư lại cấp thấp có mặt khắp nơi, tất cả đều qua tay anh ta. | Gương Hán-Việt | tư trong \"tư lại\" (胥吏 — quan lại cấp thấp), \"lâm tư\" (淪胥 — kéo nhau chìm xuống, văn ngôn) | Mở khoá kiến thức | Biết 胥 mở khoá: 胥吏 (tư lại — quan lại cấp thấp), 淪胥 (lân tư — cùng chìm đắm), văn ngôn 胥 (tư — tất cả, cùng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 胥 là chữ hình thanh: 疋 (sất, biểu âm) + 肉/月 (nhục, thịt, biểu nghĩa). Có dạng tiểu triện và nhiều dạng lục thư thông. Nghĩa lịch sử bao gồm: quan lại cấp thấp phụ trách bắt trộm, và nghĩa văn ngôn ''tất cả, cùng nhau''. Thấy trong văn Vương An Thạch và Bồ Tùng Linh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đều, cùng", "Hạng Tần Suất (Jun Da)": "3604.0", "Tần Suất % (Jun Da)": "99.5979985284", "GavinGrover_Once (Chiết tự trực tiếp)": "疋 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱疋月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "月", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疋", "Unihan_Simplified (Chữ Giản thể)": "胥", "Unihan_Traditional (Chữ Phồn thể)": "胥", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Danh từ | 名词 | Trong văn ngôn thường làm phó từ đứng trước động từ để chỉ hành động chung của mọi người. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琶', '{"9000": "3605.0", "Chữ Trung Quốc": "琶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 琶 | bà | tượng hình | nhạc cụ tỳ bà | 琶 là chữ độc thể không có cấu trúc hình thanh hay hội ý rõ ràng. Chỉ dùng trong từ ghép 琵琶 (tỳ bà), tên loại đàn dây truyền thống Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bà\": âm bà của tiếng đàn gảy vào (琶) — tiếng 琵琶 (tỳ bà) bật ra bật vào: pi-pa, tỳ-bà. | Gương Hán-Việt | bà trong \"tỳ bà\" (琵琶 — đàn tỳ bà), tên nhạc cụ dây truyền thống Trung Quốc | Mở khoá kiến thức | Biết 琶 nhận ra: 琵琶 (tỳ bà — đàn tỳ bà), 琶音 (bà âm — arpeggio trong âm nhạc).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu tạo cho 琶; chỉ ghi nhận dùng trong 琵琶. Có dạng tiểu triện và lục thư thông. 琵琶 là tên đàn dây có nguồn gốc từ Trung Á, được du nhập vào Trung Quốc qua Con đường Tơ lụa. Tên 琵琶 mô phỏng tiếng đàn: 琵 (bật ra — phi) và 琶 (gảy vào — bà). Chưa có nguồn học thuật xác nhận cấu tạo đơn lẻ của 琶. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tỳ bà 琵琶)", "Hạng Tần Suất (Jun Da)": "3605.0", "Tần Suất % (Jun Da)": "99.598463635", "GavinGrover_Once (Chiết tự trực tiếp)": "玨 + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱玨巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "玨", "Unihan_Simplified (Chữ Giản thể)": "琶", "Unihan_Traditional (Chữ Phồn thể)": "琶", "Pinyin_Xie": "pá", "Âm Hán Việt_Xie": "bà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Là danh từ chỉ nhạc cụ cổ truyền, luôn đi liền với chữ tỳ để tạo thành tên gọi cây đàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撬', '{"9000": "3606.0", "Chữ Trung Quốc": "撬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 撬 | kiều | tượng hình | cậy mở, nâng lên bằng đòn bẩy | 撬 không có cấu trúc hình thanh hay hội ý được ghi chép trong nguồn học thuật hiện có. Nhìn hình dạng có bộ 扌(tay) nhưng Wiktionary không xác nhận phân tích. Chữ chỉ hành động cậy,撬 mở bằng dụng cụ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": dùng sức tay (扌) kiều nhấc lên — cậy nắp, pry open bằng đòn bẩy. | Gương Hán-Việt | kiều ít dùng trong văn Hán-Việt; chữ phổ biến trong tiếng Trung hiện đại nghĩa cậy mở | Mở khoá kiến thức | Biết 撬 nhận ra: 撬锁 (kiều tỏa —撬开锁 phá khóa), 撬动 (kiều động — cậy, tác động/leverage).", "Tự nguyên_Xie": "Wiktionary ghi chú 撬 cần tra thêm nguồn gốc (rfe — request for etymology). Không có dạng cổ được ghi nhận. Về mặt hình dạng, chữ có bộ 扌(tay) gợi hành động của tay, nhưng cấu tạo chính thức chưa được xác nhận học thuật. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cất lên, nâng lên", "Hạng Tần Suất (Jun Da)": "3606.0", "Tần Suất % (Jun Da)": "99.5989287416", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 毳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌毳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撬", "Unihan_Traditional (Chữ Phồn thể)": "撬", "Pinyin_Xie": "qiào", "Âm Hán Việt_Xie": "khiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ vật bị cạy như cửa, hòm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | qiào | / | cậy mở | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橘', '{"9000": "3607.0", "Chữ Trung Quốc": "橘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 木 | mộc | biểu nghĩa | cây | 矞 | biểu âm | âm mạo | 橘 = 木 (Mộc, biểu nghĩa: cây) + 矞 (biểu âm); chữ hình thanh. Bộ mộc chỉ loài cây, phần 矞 cho âm đọc. Chữ chỉ cây quýt/quất và quả của nó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quất\": cây (木) quất thơm ngọt — 橘子 (quất tử) là quả quýt, màu cam rực rỡ ngày Tết. | Gương Hán-Việt | quất trong \"quất tử\" (橘子 — quả quýt), \"cầm quất\" (金橘 — quất vàng) | Mở khoá kiến thức | Biết 橘 mở khoá: 橘子 (quất tử — quả quýt), 金橘 (kim quất — quất vàng), 橘络 (quất lạc — xơ trắng trong múi quýt).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 橘 là chữ hình thanh: 木 (mộc, cây) là phần biểu nghĩa, 矞 là phần biểu âm. Chỉ cây quýt/quất (Citrus reticulata). Có dạng tiểu triện. Trong văn học cổ điển, 橘 được Khuất Nguyên ca ngợi trong bài phú Quất Tụng (橘颂) như biểu tượng của đức hạnh. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1882.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mộc (075) Duật (1881)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Mộc (số 075 - cây cối/ 木 /chỉ ý) ở bên trái chữ Duật (số 1881 - rực rỡ/ 矞 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Duật chỉ âm, bộ Mộc chỉ ý. Quất là cây quất, cây quýt có quả màu vàng rực rỡ (Duật) (cây quất, quất tử - quả quýt). Đây cũng chính là chữ cuối cùng khép lại 1882 chữ Nho!", "Nghĩa Tiếng Việt_Xie": "cây quít, cây quất", "Hạng Tần Suất (Jun Da)": "3607.0", "Tần Suất % (Jun Da)": "99.5993938482", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 矞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木矞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橘", "Unihan_Traditional (Chữ Phồn thể)": "橘", "Pinyin_Xie": "jú", "Âm Hán Việt_Xie": "quất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc kết hợp với các từ khác chỉ bộ phận của cây quýt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拈', '{"9000": "3608.0", "Chữ Trung Quốc": "拈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 拈 | chêm | tượng hình | nhón lấy bằng đầu ngón tay | 拈 nhìn hình dạng có bộ 扌(tay) gợi hành động của tay, nhưng Wiktionary chỉ ghi chú Han etym không có phân tích cấu tạo chi tiết. Chữ chỉ cử chỉ khéo léo: nhón lấy bằng ngón cái và ngón trỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chêm\": ngón tay (扌) nhẹ nhàng chêm vào — nhón lấy vật nhỏ như nhón hoa sen trong tích Phật 拈花一笑. | Gương Hán-Việt | chêm trong \"chêm hoa nhất tiếu\" (拈花一笑 — nhón hoa mỉm cười, tương truyền Phật Thích Ca truyền tâm ấn) | Mở khoá kiến thức | Biết 拈 mở khoá: 拈花一笑 (chêm hoa nhất tiếu — Thiền tông tâm ấn), 拈阄 (chêm cữu — bốc thăm).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận 拈 có dữ liệu Han etym nhưng không cung cấp phân tích cấu tạo. Không có ảnh etymology. Chữ chỉ hành động nhón nhẹ bằng đầu ngón tay — tinh tế, khéo léo. Thường dùng trong: 拈花一笑 (nhón hoa mỉm cười — Phật giáo), 拈阄 (bốc thăm). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhón lấy (dùng ngón tay lấy đồ)", "Hạng Tần Suất (Jun Da)": "3608.0", "Tần Suất % (Jun Da)": "99.6003225111", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "占", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拈", "Unihan_Traditional (Chữ Phồn thể)": "拈", "Pinyin_Xie": "niān", "Âm Hán Việt_Xie": "niêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường mang tân ngữ chỉ vật nhỏ nhẹ như hoa, lá, sợi tóc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笆', '{"9000": "3609.0", "Chữ Trung Quốc": "笆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 10 | nét | 𥫗 | biểu nghĩa | tre nứa | 巴 | ba | biểu âm | ba, vùng Tứ Xuyên | 笆 = 𥫗/竹 (bộ trúc, biểu nghĩa: tre) + 巴 (Ba, biểu âm); chữ hình thanh. Bộ trúc chỉ vật liệu làm từ tre, phần 巴 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ba\": tre (竹) đọc âm ba (巴) — hàng rào 篱笆 (lý ba) bằng tre bảo vệ nhà, phổ biến ở nông thôn. | Gương Hán-Việt | ba trong \"lý ba\" (篱笆 — hàng rào) — từ hay gặp trong văn học về nông thôn Trung Quốc | Mở khoá kiến thức | Biết 笆 nhận ra: 篱笆 (lý ba — hàng rào tre), 笆篓 (ba lâu — giỏ tre).", "Tự nguyên_Xie": "Theo Wiktionary, 笆 là chữ hình thanh: 竹/𥫗 (trúc, tre) là phần biểu nghĩa, 巴 là phần biểu âm. Nghĩa là hàng rào tre, bờ giậu bằng tre gai. Không có ảnh etymology hiện có. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tre gai; bờ giậu, hàng rào", "Hạng Tần Suất (Jun Da)": "3609.0", "Tần Suất % (Jun Da)": "99.6007855506", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 巴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮巴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笆", "Unihan_Traditional (Chữ Phồn thể)": "笆", "Pinyin_Xie": "bā", "Âm Hán Việt_Xie": "ba", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp thành từ ghép như ly ba để chỉ hàng rào. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痊', '{"9000": "3610.0", "Chữ Trung Quốc": "痊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 痊 | thuyên | tượng hình | khỏi bệnh, bình phục | 痊 nhìn hình dạng có bộ 疒(bệnh) gợi liên quan đến bệnh tật, nhưng Wiktionary không cung cấp phân tích cấu tạo chi tiết. Chữ chỉ sự hồi phục hoàn toàn sau bệnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": bộ bệnh (疒) được chữa thuyên giảm — khỏi hẳn, bình phục hoàn toàn như từ 痊愈 (thuyên du). | Gương Hán-Việt | thuyên trong \"thuyên du\" (痊愈 — khỏi bệnh hoàn toàn), \"thuyên giảm\" — chữ Hán-Việt quen thuộc trong y tế | Mở khoá kiến thức | Biết 痊 mở khoá: 痊愈 (thuyên du — bình phục hoàn toàn), 大痊 (đại thuyên — hồi phục tốt).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận 痊 có dữ liệu Han etym nhưng không phân tích cấu tạo. Không có ảnh etymology. Nghĩa là khỏi bệnh, hồi phục hoàn toàn. Từ phổ biến nhất là 痊愈 (thuyên du — bình phục). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khỏi bệnh", "Hạng Tần Suất (Jun Da)": "3610.0", "Tần Suất % (Jun Da)": "99.6012470397", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痊", "Unihan_Traditional (Chữ Phồn thể)": "痊", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ hoặc tính từ biểu thị trạng thái sức khỏe đã hồi phục. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亟', '{"9000": "3611.0", "Chữ Trung Quốc": "亟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 二 | Số nét | 8 | nét | 人 | nhân | biểu nghĩa | người | 二 | nhị | biểu nghĩa | hai đầu mút | 亟 = 人 (Nhân, biểu nghĩa: người) + 二 (Nhị, biểu nghĩa: hai đầu mút); chữ hội ý. Hình ảnh người đứng giữa hai đầu mút (trên/dưới) — vươn tới cực điểm, cấp bách. Sau đó được mượn âm để biểu thị nghĩa ''khẩn cấp''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cấc\": người (人) đứng giữa hai cực (二) — kéo căng đến cực điểm, việc gấp cấp cần giải quyết ngay. | Gương Hán-Việt | cấc trong \"cấc tốc\" (亟速 — gấp rút), \"cấc nhu\" (亟需 — rất cần, khẩn cấp cần) | Mở khoá kiến thức | Biết 亟 mở khoá: 亟需 (cấc nhu — rất cần gấp), 亟待 (cấc đãi — cần được giải quyết khẩn cấp), 亟亟 (cấc cấc — gấp gáp).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Đại triện | Tiểu triện | Theo Wiktionary (nghiên cứu của Vu Tỉnh Ngô), 亟 là chữ hội ý: 人 (người) + 二 (hai đầu mút/hai cực). Dạng ban đầu là chữ nguyên thể của 極 (cực đoan). Các bộ phận 口 và 攴 (sau rút gọn thành 又) được thêm vào sau. Có dữ liệu giáp cốt văn, kim văn, bạch thư, đại triện và tiểu triện. Sau được mượn âm để chỉ nghĩa ''khẩn cấp, gấp rút''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1519.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhị (007) Khẩu (030) Hựu (029) Nhân (009)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm bộ Nhị (số 007 - trên trời dưới đất/ 二), chữ Khẩu (số 030 - cái miệng/ 口), chữ Hựu (số 029 - cái tay/ 又) và một nét biến đổi từ chữ Nhân (số 009/ 人). Đứng giữa trời đất, miệng thì tính toán, tay thì vội vàng nắm bắt thời cơ. Giải thích sự chuyển ý: Đây là chữ Hội ý. Cức là sự vội vàng, gấp gáp, nhanh chóng. (Khí mang ý nghĩa là nhiều lần).", "Nghĩa Tiếng Việt_Xie": "gấp, kíp", "Hạng Tần Suất (Jun Da)": "3611.0", "Tần Suất % (Jun Da)": "99.6017085289", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "亟", "Unihan_Traditional (Chữ Phồn thể)": "亟", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cức, khí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Chữ này làm phó từ đứng trước động từ để biểu thị hành động cần thực hiện ngay lập tức. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渭', '{"9000": "3612.0", "Chữ Trung Quốc": "渭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước, sông | 胃 | vị | biểu âm | dạ dày | 渭 = 水/氵 (Thủy, biểu nghĩa: nước/sông) + 胃 (Vị, biểu âm); chữ hình thanh. Bộ tam thủy chỉ sông ngòi, phần 胃 cho âm đọc. Chữ chỉ sông Vị (Vị Hà) ở tỉnh Thiểm Tây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vấy\": nước (氵) sông Vị (胃 âm vị/vấy) — sông Vị nước trong, sông Kinh nước đục, gặp nhau rõ ràng như 泾渭分明. | Gương Hán-Việt | vấy/vị trong \"Vị Hà\" (渭河 — sông Vị), \"Vị Thành\" (渭城 — thành Vị) | Mở khoá kiến thức | Biết 渭 nhận ra: 渭河 (Vị Hà — sông Vị), 泾渭分明 (kinh vị phân minh — ranh giới rõ ràng), 渭城曲 (bài thơ Vị Thành nổi tiếng của Vương Duy).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 渭 là chữ hình thanh: 水 (nước, sông) là phần biểu nghĩa, 胃 (vị — dạ dày) là phần biểu âm. Chỉ sông Vị Hà (渭河), phụ lưu lớn của Hoàng Hà. Có dạng tiểu triện và lục thư thông. Thành ngữ 泾渭分明 (Kinh Vị phân minh) nổi tiếng: sông Kinh và sông Vị gặp nhau, nước đục nước trong rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Vị", "Hạng Tần Suất (Jun Da)": "3612.0", "Tần Suất % (Jun Da)": "99.6021695012", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 胃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵胃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "胃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渭", "Unihan_Traditional (Chữ Phồn thể)": "渭", "Pinyin_Xie": "wèi", "Âm Hán Việt_Xie": "vị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ tên sông, thường đi kèm với thủy để thành Vị Thủy. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('狙', '{"9000": "3613.0", "Chữ Trung Quốc": "狙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 8 | nét | 犭 | biểu nghĩa | chó, thú vật | 且 | thả | biểu âm | hơn nữa, vả lại | 狙 = 犭(bộ khuyển, biểu nghĩa: thú vật) + 且 (Thả, biểu âm); chữ hình thanh. Bộ khuyển (犬rút gọn) chỉ loài thú, phần 且 cho âm đọc. Nghĩa gốc là loài vượn; nghĩa mở rộng sang ''rình, phục kích''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thư\": thú (犭) ranh mãnh như vượn (且 âm thư) — con khỉ xảo quyệt rình rập, từ đó 狙击手 là tay bắn tỉa. | Gương Hán-Việt | thư trong \"thư kích\" (狙击 — bắn tỉa, phục kích) — chữ trong từ quân sự hiện đại | Mở khoá kiến thức | Biết 狙 mở khoá: 狙击手 (thư kích thủ — tay bắn tỉa/sniper), 狙击 (thư kích — phục kích bắn tỉa).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 狙 là chữ hình thanh: 犬/犭 (chó/thú, biểu nghĩa) + 且 (thả, biểu âm). Nghĩa gốc là loài vượn/khỉ ranh mãnh. Mở rộng sang nghĩa rình rập, nằm phục. Có dạng tiểu triện. Xuất hiện trong Liệt Tử với câu chuyện người nuôi khỉ (狙公). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một giống vượn rất xảo quyệt", "Hạng Tần Suất (Jun Da)": "3613.0", "Tần Suất % (Jun Da)": "99.6026299568", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 且", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭且", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "且", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "狙", "Unihan_Traditional (Chữ Phồn thể)": "狙", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "thư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm động từ trong các từ ghép chỉ hành động rình rập, phục kích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珂', '{"9000": "3614.0", "Chữ Trung Quốc": "珂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 𤣩 | biểu nghĩa | ngọc | 可 | khả | biểu âm | được, có thể | 珂 = 𤣩/玉 (bộ ngọc, biểu nghĩa: ngọc đá) + 可 (Khả, biểu âm); chữ hình thanh. Bộ ngọc (王rút gọn thành 𤣩) chỉ đá quý, phần 可 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": ngọc (𤣩) loại được chấp nhận (可 kha/khả) — đá trắng như ngọc, được dùng làm đồ trang trí. | Gương Hán-Việt | kha trong \"ngọc kha\" (玉珂 — ngọc kha, đồ trang trí bằng ngọc trên yên ngựa) | Mở khoá kiến thức | Biết 珂 nhận ra: 玉珂 (ngọc kha — đồ ngọc trang trí yên ngựa), 珂里 (kha lý — thôn xóm tốt lành — văn ngôn).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 珂 là chữ hình thanh: 玉/𤣩 (ngọc, biểu nghĩa) + 可 (khả, biểu âm). Nghĩa là loại đá trắng giống ngọc, kém phẩm chất hơn ngọc thật. Có dạng đại triện và tiểu triện. Thường dùng trong tên người, tên địa danh hơn là từ thường dùng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc kha", "Hạng Tần Suất (Jun Da)": "3614.0", "Tần Suất % (Jun Da)": "99.6030893787", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珂", "Unihan_Traditional (Chữ Phồn thể)": "珂", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "kha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong tên người hoặc tên các loại ngọc quý. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刨', '{"9000": "3615.0", "Chữ Trung Quốc": "刨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 7 | nét | 包 | bao | biểu âm | bọc lấy, gói | 刀 | đao | biểu nghĩa | dao | 刨 = 包 (Bao, biểu âm) + 刀/刂 (Đao, biểu nghĩa: dao); chữ hình thanh. Bộ đao chỉ dụng cụ cắt gọt, phần 包 cho âm đọc. Nghĩa là bào gọt, đào bới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bào\": dao (刂) bào theo kiểu bao (包) bọc gỗ — thợ mộc dùng bào gỗ gọt phẳng bề mặt. | Gương Hán-Việt | bào trong \"bào mộc\" (刨木 — bào gỗ), \"bào căn\" (刨根 — đào tận gốc) | Mở khoá kiến thức | Biết 刨 mở khoá: 刨床 (bào sàng — máy bào), 刨根问底 (bào căn vấn để — truy đến tận cùng).", "Tự nguyên_Xie": "Theo Wiktionary, 刨 là chữ hình thanh: 包 (bao, biểu âm) + 刀/刂 (đao, dao, biểu nghĩa). Nghĩa là bào gỗ (dụng cụ thợ mộc), và cũng nghĩa đào bới. Không có ảnh etymology hiện có. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đào, bới", "Hạng Tần Suất (Jun Da)": "3615.0", "Tần Suất % (Jun Da)": "99.6035482839", "GavinGrover_Once (Chiết tự trực tiếp)": "包 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰包刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刨", "Unihan_Traditional (Chữ Phồn thể)": "刨", "Pinyin_Xie": "páo", "Âm Hán Việt_Xie": "bào", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động đào đất hoặc bào gỗ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | páo | / | bào | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Nông nghiệp", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜕', '{"9000": "3616.0", "Chữ Trung Quốc": "蜕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蜕 | thoái | tượng hình | lột xác côn trùng | 蜕 nhìn hình dạng có bộ 虫 (sâu bọ) nhưng Wiktionary chỉ ghi nhận dạng phồn thể 蛻 không có phân tích cấu tạo chi tiết. Chỉ có dạng tiểu triện. Chữ chỉ hành động lột xác của côn trùng hay rắn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoái\": sâu bọ (虫) thoái (lột) ra khỏi xác cũ — lột xác để lớn lên, như 蜕变 là sự chuyển hoá triệt để. | Gương Hán-Việt | thoái trong \"thoái biến\" (蜕变 — biến đổi hoàn toàn, transformation) | Mở khoá kiến thức | Biết 蜕 mở khoá: 蜕变 (thoái biến — chuyển hoá triệt để), 蜕皮 (thoái bì — lột da/xác), 蛇蜕 (xà thoái — xác rắn lột).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi nhận 蛻/蜕 có Han etym không có phân tích cấu tạo. Có dạng tiểu triện. Nghĩa là lột xác, xác lột của côn trùng/rắn. Nghĩa mở rộng sang ''chuyển hoá, lột bỏ cái cũ''. Từ phổ biến: 蜕变 (thoái biến — biến đổi hoàn toàn), 金蝉脱壳 (dế vàng thoát vỏ). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xác (vỏ) của các loài côn trùng khi lột ra", "Hạng Tần Suất (Jun Da)": "3616.0", "Tần Suất % (Jun Da)": "99.6040061556", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 兑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫兑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜕", "Unihan_Traditional (Chữ Phồn thể)": "蛻", "Pinyin_Xie": "tuì", "Âm Hán Việt_Xie": "thuế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ quá trình lột xác của động vật hoặc sự biến chất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谚', '{"9000": "3617.0", "Chữ Trung Quốc": "谚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 谚 | ngạn | tượng hình | ngạn ngữ, câu tục ngữ | 谚 nhìn hình dạng có bộ 讠(言, lời nói) gợi liên quan đến ngôn ngữ, nhưng Wiktionary không cung cấp phân tích cấu tạo chi tiết. Dạng phồn thể là 諺. Chữ chỉ câu tục ngữ, ngạn ngữ lưu truyền trong dân gian.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạn\": lời nói (讠) của người ngạn (已故bậc tiền nhân) — câu nói qua miệng nhiều đời thành ngạn ngữ. | Gương Hán-Việt | ngạn trong \"ngạn ngữ\" (谚语 — tục ngữ), \"nông ngạn\" (农谚 — tục ngữ nông nghiệp) | Mở khoá kiến thức | Biết 谚 mở khoá: 谚语 (ngạn ngữ — tục ngữ), 农谚 (nông ngạn — câu nói về canh tác), 俗谚 (tục ngạn — thành ngữ dân gian).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu tạo cho 諺/谚. Có dạng tiểu triện và lục thư thông. Nghĩa là câu tục ngữ, ngạn ngữ — lời nói khôn ngoan lưu truyền trong dân gian. Từ phổ biến: 谚语 (ngạn ngữ), 农谚 (nông ngạn — câu tục ngữ về nông nghiệp). Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngạn ngữ, phương ngôn", "Hạng Tần Suất (Jun Da)": "3617.0", "Tần Suất % (Jun Da)": "99.6044629936", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 彦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠彦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谚", "Unihan_Traditional (Chữ Phồn thể)": "諺", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "ngạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ các câu tục ngữ, ngạn ngữ và thường kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憧', '{"9000": "3618.0", "Chữ Trung Quốc": "憧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 忄 | biểu nghĩa | tim, cảm xúc | 童 | đồng | biểu âm | trẻ em, đồng tử | 憧 = 忄(bộ tâm, biểu nghĩa: trái tim/cảm xúc) + 童 (Đồng, biểu âm); chữ hình thanh. Bộ tâm chỉ trạng thái cảm xúc, phần 童 cho âm đọc. Nghĩa chính là do dự, phân vân; từ phổ biến nhất là 憧憬 (mơ ước, khát vọng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": trái tim (忄) của đứa trẻ (童 đồng) đang mơ mộng — 憧憬 là nỗi khát vọng ngây thơ hướng về tương lai. | Gương Hán-Việt | đồng trong \"đồng cảnh\" (憧憬 — mơ ước, khát vọng hướng tới) | Mở khoá kiến thức | Biết 憧 mở khoá: 憧憬 (đồng cảnh — mơ ước, hướng về, aspire to), 憧憧 (đồng đồng — lung lay, chập chờn).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Digital Shinjigen 2017), 憧 là chữ hình thanh: 心/忄 (tâm, tim/cảm xúc) là phần biểu nghĩa, 童 là phần biểu âm. Nghĩa gốc là do dự, bất quyết. Từ phổ biến 憧憬 (chōngjǐng — mơ ước, khát vọng hướng về điều gì). Có dạng tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phân vân", "Hạng Tần Suất (Jun Da)": "3618.0", "Tần Suất % (Jun Da)": "99.6049193149", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憧", "Unihan_Traditional (Chữ Phồn thể)": "憧", "Pinyin_Xie": "chōng", "Âm Hán Việt_Xie": "sung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường dùng làm động từ hoặc tính từ trong các từ ghép để thể hiện sự mong mỏi hoặc trạng thái lay động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞟', '{"9000": "3619.0", "Chữ Trung Quốc": "瞟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 瞟 | phiêu | tượng hình | liếc nhìn, nhìn nghiêng | 瞟 không có cấu trúc hình thanh hay hội ý được ghi chép trong nguồn học thuật hiện có. Nhìn hình dạng có bộ 目 (mắt) gợi liên quan đến mắt nhìn, nhưng Wiktionary không xác nhận phân tích. Chữ chỉ cái nhìn liếc ngang, xem trộm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiêu\": mắt (目) phiêu lướt qua như cánh nhẹ — liếc trộm một cái, không nhìn thẳng. | Gương Hán-Việt | phiêu ít dùng trong văn Hán-Việt; 瞟 chủ yếu dùng trong tiếng Trung hiện đại | Mở khoá kiến thức | Biết 瞟 nhận ra: 瞟了一眼 (phiêu nhất nhãn — liếc một cái), phân biệt với 瞧 (nhìn), 瞥 (thoáng nhìn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi nhận 瞟 có Han etym không có phân tích cấu tạo. Có dạng tiểu triện. Nghĩa là liếc nhìn, nhìn nghiêng, nhìn trộm. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc", "Hạng Tần Suất (Jun Da)": "3619.0", "Tần Suất % (Jun Da)": "99.6053756362", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 票", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目票", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞟", "Unihan_Traditional (Chữ Phồn thể)": "瞟", "Pinyin_Xie": "piǎo", "Âm Hán Việt_Xie": "phiếu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động liếc mắt nhìn nhanh sang một bên và thường mang tân ngữ trực tiếp phía sau. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馒', '{"9000": "3620.0", "Chữ Trung Quốc": "馒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 14 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn (bộ thực giản thể) | 曼 | mạn | biểu âm | rộng, dài; cho âm ''mán'' | 馒 là chữ hình thanh (psc): 饣 (thực, bộ thức ăn giản thể của 食) biểu nghĩa — chỉ món ăn; 曼 (mạn) biểu âm cho âm ''mán''. Dạng phồn thể là 饅. Chữ chỉ bánh bao hấp không nhân (mantou), món ăn truyền thống Trung Hoa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"man\": bộ thực (饣 ăn uống) + 曼 biểu âm → 馒头 là bánh bao hấp tròn to phình như mặt người 曼 (rộng, đầy đặn). | Gương Hán-Việt | man trong ''man đầu'' (馒头 — bánh bao hấp); ít dùng độc lập | Mở khoá kiến thức | Biết 馒 (Man) hầu như chỉ dùng trong 馒头 (bánh bao hấp) ở HSK 5.", "Tự nguyên_Xie": "Theo Wiktionary, 馒 (dạng phồn thể 饅) cấu tạo hình thanh (psc): 食 biểu nghĩa (thức ăn), 曼 biểu âm (âm mán). Không có hình ảnh etymology trong dữ liệu. Chữ xuất hiện muộn trong lịch sử — bánh bao (馒头) vốn được truyền thuyết gán cho Gia Cát Lượng thời Tam Quốc. Chữ tạo muộn, chưa có trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: man đầu 饅頭,馒头)", "Hạng Tần Suất (Jun Da)": "3620.0", "Tần Suất % (Jun Da)": "99.6058309239", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馒", "Unihan_Traditional (Chữ Phồn thể)": "饅", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "man", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện làm danh từ trong từ ghép để chỉ loại bánh màn thầu truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('拗', '{"9000": "3621.0", "Chữ Trung Quốc": "拗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 拗 | húc | tượng hình | bẻ gãy, cứng đầu, cưỡng lại | 拗 không có cấu trúc hình thanh hay hội ý được xác nhận học thuật. Wiktionary chỉ ghi nhận Han etym. Nhìn hình dạng có bộ 扌(tay) và 幼 gợi tay bẻ cưỡng, nhưng không có xác nhận chính thức.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"húc\": tay húc (扌) bẻ cưỡng — bẻ gãy bằng sức; cũng chỉ tính cách cứng đầu, khó chịu (niù). | Gương Hán-Việt | húc trong một số trường hợp; chữ đa âm: 拗 (ǎo — bẻ), 拗 (niù — cứng đầu), 拗 (ào — không trơn trong thơ) | Mở khoá kiến thức | Biết 拗 nhận ra đa âm: 拗断 (ǎo — bẻ gãy), 拗口 (ào kǒu — khó đọc/nói), 执拗 (zhí niù — cứng đầu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary chỉ ghi nhận 拗 có Han etym không có phân tích cấu tạo. Có dạng tiểu triện và lục thư thông. Nghĩa là bẻ gãy (đọc ǎo), hoặc cứng đầu/ngoan cố (đọc niù), hoặc không trơn tru trong thi văn (đọc ào). Chữ đa âm. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bẻ gãy", "Hạng Tần Suất (Jun Da)": "3621.0", "Tần Suất % (Jun Da)": "99.6062862116", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 幼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌幼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "拗", "Unihan_Traditional (Chữ Phồn thể)": "抝", "Pinyin_Xie": "ǎo", "Âm Hán Việt_Xie": "áo, ảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ biểu thị hành động dùng lực bẻ gãy hoặc uốn cong một vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帚', '{"9000": "3622.0", "Chữ Trung Quốc": "帚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 帚 | trửu | tượng hình | cái chổi | 帚 là chữ tượng hình độc thể. Dạng hiện đại phân tích thành 肀 + 冖 + 巾 nhưng đây là sự phân rã hình dạng về sau. Giáp cốt văn và kim văn cho thấy hình ảnh cái chổi: phần lông/cọng ở trên, phần cán buộc ở dưới.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trửu\": chữ vẽ hình cái chổi — cọng cứng (肀) buộc gọn (冖) trên tấm vải (巾) — 扫帚 là cái chổi quét nhà. | Gương Hán-Việt | trửu trong \"tảo trửu\" (扫帚 — cái chổi), \"phệ trửu\" (敝帚 — chổi cũ rách — ví vật mình trân quý dù người khác thấy vô giá trị) | Mở khoá kiến thức | Biết 帚 mở khoá: 扫帚 (tảo trửu — cái chổi), 敝帚自珍 (phệ trửu tự trân — yêu quý đồ cũ của mình, khiêm tốn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 帚 là chữ tượng hình: hình ảnh cái chổi với lông/cọng ở trên và cán buộc ở dưới. Có dạng từ giáp cốt văn, kim văn, đại triện đến tiểu triện. Trong dạng hiện đại, đỉnh giống 聿/肀 (bút), phần giữa là 冖, đáy là 巾 — nhưng đây là sự biến dạng so với hình gốc. Chữ phổ biến nhất là 扫帚 (chổi quét). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "230.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hựu (159) Mịch Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Hựu (159) , bộ Mịch (trùm lên) và chữ Cân (225) . Bàn tay bó những mảnh vải vụn lại tạo thành cái chổi.", "Nghĩa Tiếng Việt_Xie": "cái chổi", "Hạng Tần Suất (Jun Da)": "3622.0", "Tần Suất % (Jun Da)": "99.6067399489", "GavinGrover_Once (Chiết tự trực tiếp)": "彐 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱彐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "帚", "Unihan_Traditional (Chữ Phồn thể)": "帚", "Pinyin_Xie": "zhǒu", "Âm Hán Việt_Xie": "trửu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái chổi quét nhà, thường kết hợp thành từ ghép hoặc đi kèm lượng từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钗', '{"9000": "3623.0", "Chữ Trung Quốc": "钗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 8 | nét | 钗 | thoa | tượng hình | thoa, trâm cài đầu | 钗 (phồn thể 釵) không có cấu trúc hình thanh hay hội ý được ghi chép chi tiết trong Wiktionary. Nhìn hình dạng có bộ 钅(kim loại) gợi đồ kim loại. Chữ chỉ đồ trang sức cài tóc hình nhánh đôi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thoa\": kim loại (钅) làm thoa cài đầu — 钗 là thoa/trâm, đồ trang sức quen thuộc của phụ nữ cổ đại; 薛宝钗 là nhân vật trong Hồng Lâu Mộng. | Gương Hán-Việt | thoa trong \"kim thoa\" (金钗 — thoa vàng), \"bảo thoa\" (宝钗 — thoa quý), từ Hán-Việt quen trong văn học cổ | Mở khoá kiến thức | Biết 钗 mở khoá: 金钗 (kim thoa — thoa vàng), 荆钗 (kinh thoa — thoa gai, biểu tượng đức hạnh khiêm tốn), 钗头凤 (điệu nhạc nổi tiếng của Lục Du).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu tạo cho 釵/钗. Có dạng tiểu triện. Nghĩa là thoa, trâm cài đầu dạng nhánh đôi bằng kim loại/ngọc. Thường xuất hiện trong thơ từ cổ điển như biểu tượng của phụ nữ. Từ nổi tiếng: 金钗 (kim thoa), 宝钗 (bảo thoa — tên nhân vật trong Hồng Lâu Mộng). Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thoa, trâm cài đầu", "Hạng Tần Suất (Jun Da)": "3623.0", "Tần Suất % (Jun Da)": "99.6071936863", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 叉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅叉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钗", "Unihan_Traditional (Chữ Phồn thể)": "釵", "Pinyin_Xie": "chāi", "Âm Hán Việt_Xie": "thoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ món trang sức cài tóc của phụ nữ thời xưa, thường xuất hiện trong văn thơ cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哧', '{"9000": "3624.0", "Chữ Trung Quốc": "哧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 赤 | xích | biểu âm | đỏ | 哧 = 口 (Khẩu, biểu nghĩa: miệng) + 赤 (Xích, biểu âm); chữ hình thanh. Bộ khẩu chỉ âm thanh phát ra từ miệng, phần 赤 cho âm đọc. Chữ tượng thanh chỉ tiếng cười khúc khích hoặc tiếng xé rách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sất\": miệng (口) phát âm xích (赤) — tiếng cười sất sất khúc khích, như tiếng vải xé xoạc nhẹ. | Gương Hán-Việt | sất ít gặp trong văn Hán-Việt; 哧 chủ yếu dùng tượng thanh trong tiếng Trung hiện đại | Mở khoá kiến thức | Biết 哧 nhận ra tượng thanh: 哧哧 (chī chī — khúc khích), 哧溜 (chī liū — tiếng trượt nhanh).", "Tự nguyên_Xie": "Theo Wiktionary (Han compound phân tích), 哧 là chữ hình thanh: 口 (miệng, biểu nghĩa) + 赤 (xích, biểu âm). Nghĩa là âm thanh phát ra từ miệng — tiếng cười khúc khích (哧哧笑) hoặc tiếng xé vải. Không có ảnh etymology. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng cười khúc khích", "Hạng Tần Suất (Jun Da)": "3624.0", "Tần Suất % (Jun Da)": "99.6076469068", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 赤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口赤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "赤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哧", "Unihan_Traditional (Chữ Phồn thể)": "哧", "Pinyin_Xie": "chī", "Âm Hán Việt_Xie": "xích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Chữ này làm từ tượng thanh mô phỏng tiếng cười khẽ hoặc tiếng xì hơi gas, thường đứng độc lập hoặc làm trạng ngữ. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喋', '{"9000": "3625.0", "Chữ Trung Quốc": "喋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 喋 | nhịp | tượng hình | nói lem lém, liên tục | 喋 không có cấu trúc hình thanh hay hội ý được ghi chép chi tiết trong Wiktionary. Nhìn hình dạng có bộ 口 (miệng) gợi liên quan đến lời nói. Chữ đa âm: dié (nói liên tục), dié (chảy máu), zhá (miệng mở đóng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhịp\": miệng (口) nhịp nhàng không ngừng — 喋喋不休 (nhịp nhịp bất hưu) là nói liên tu bất tận. | Gương Hán-Việt | nhịp trong \"nhịp nhịp bất hưu\" (喋喋不休 — nói mãi không thôi) — từ Hán-Việt trong văn học | Mở khoá kiến thức | Biết 喋 mở khoá: 喋喋不休 (nhịp nhịp bất hưu — nói không dứt), 喋血 (nhịp huyết — đẫm máu, lưu huyết).", "Tự nguyên_Xie": "Wiktionary ghi nhận 喋 có Han etym nhưng không phân tích cấu tạo. Có dạng tiểu triện. Chữ đa âm với ba âm đọc: 1) dié — nói lem lém, không ngừng (喋喋不休); 2) dié — chảy máu (喋血); 3) zhá — miệng mở đóng như cá. Chưa có nguồn học thuật xác nhận cấu tạo. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dòng chảy; láu lỉnh, nói lem lém", "Hạng Tần Suất (Jun Da)": "3625.0", "Tần Suất % (Jun Da)": "99.6081001274", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 枼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口枼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "枼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喋", "Unihan_Traditional (Chữ Phồn thể)": "啑", "Pinyin_Xie": "dié", "Âm Hán Việt_Xie": "điệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong dạng lặp để miêu tả hành động nói liên tục không ngừng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箫', '{"9000": "3626.0", "Chữ Trung Quốc": "箫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 肅 | túc | biểu âm | nghiêm trang | 箫 = 竹 (Trúc, biểu nghĩa: tre trúc) + 肅 (Túc, biểu âm); chữ hình thanh. Bộ trúc chỉ chất liệu làm nhạc cụ, 肅 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiêu\" (箫): ống TRÚc dọc thổi ra tiếng TIÊu — cây sáo dọc của người xưa. | Gương Hán-Việt | tiêu trong \"tiêu dao\" (逍遥) — tuy khác chữ nhưng cùng âm; nhạc cụ này thường gắn với hình ảnh tiêu dao tự tại. | Mở khoá kiến thức | Biết 箫 mở khoá: 洞箫 (sáo dọc), 排箫 (sáo ống), 吹箫 (thổi sáo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 竹 (trúc) biểu nghĩa — nhạc cụ làm bằng tre; 肅 biểu âm cho âm xiāo. Đây là loại sáo dọc thổi từ đầu, dùng trong nhạc truyền thống Trung Hoa từ thời cổ đại. Chữ phồn thể 簫 cùng cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tiêu (nhạc cụ, như sáo)", "Hạng Tần Suất (Jun Da)": "3626.0", "Tần Suất % (Jun Da)": "99.6085517976", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 肃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮肃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "肃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箫", "Unihan_Traditional (Chữ Phồn thể)": "簫", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "tiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ thổi dọc bằng tre, thường làm tân ngữ cho động từ thổi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刁', '{"9000": "3627.0", "Chữ Trung Quốc": "刁", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 2 | nét | 刁 | điêu | tượng hình | biến thể của 刀 (đao, con dao) | 刁 là biến thể đồ hình của 刀 (dao). Chữ độc thể, không phân tích thêm thành phần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\" (刁): kẻ ĐIÊU ngoa, miệng sắc như DAO (刀) — biến thể của 刀 mang nghĩa gian xảo. | Gương Hán-Việt | điêu trong \"điêu ngoa\" — gian xảo, quỷ quyệt; cùng âm với \"điêu\" (chim điêu, tượng điêu khắc) nhưng khác chữ. | Mở khoá kiến thức | Biết 刁 mở khoá: 刁难 (gây khó dễ), 刁钻 (gian xảo, hóc búa), 刁民 (dân gian ngoan cố).", "Tự nguyên_Xie": "刁 vốn là biến thể của 刀 (dao). Theo thời gian chữ mang thêm nghĩa bóng: kẻ gian xảo, điêu ngoa — như lưỡi dao sắc bén, hiểm hóc. Wiktionary xác nhận đây là dạng variant của 刀. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gian dối, điêu ngoa", "Hạng Tần Suất (Jun Da)": "3627.0", "Tần Suất % (Jun Da)": "99.6090019175", "GavinGrover_Once (Chiết tự trực tiếp)": "㇆ + ㇀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴㇆㇀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㇀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "㇆", "Unihan_Simplified (Chữ Giản thể)": "刁", "Unihan_Traditional (Chữ Phồn thể)": "刁", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả tính cách gian xảo, điêu ngoa của con người và có thể đứng trước danh từ để tu sức. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怦', '{"9000": "3628.0", "Chữ Trung Quốc": "怦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 心 | tâm | biểu nghĩa | tim, lòng | 平 | bình | biểu âm | bằng phẳng, yên | 怦 = 忄(Tâm, biểu nghĩa: tim) + 平 (Bình, biểu âm); chữ hình thanh. Bộ tâm chỉ cảm xúc trong lòng, 平 cho âm pēng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bừng\" (怦): TÂM (心) BÌNH (平) — tim đập BỪNG BỪNG khi hồi hộp, âm vang như PENG. | Gương Hán-Việt | bừng trong \"bừng bừng\" — tim đập hồi hộp; ít dùng độc lập trong tiếng Việt Hán-Việt. | Mở khoá kiến thức | Biết 怦 mở khoá: 怦怦 (tiếng tim đập), 怦然心动 (tim bỗng xao xuyến).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 心 (tâm) biểu nghĩa — cảm giác trong lòng; 平 (bình) biểu âm cho âm pēng. Chữ diễn tả tiếng tim đập mạnh hay cảm giác bồn chồn, lo lắng trong ngực. Wiktionary ghi nhận cấu trúc psc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "áy náy", "Hạng Tần Suất (Jun Da)": "3628.0", "Tần Suất % (Jun Da)": "99.6094510038", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "怦", "Unihan_Traditional (Chữ Phồn thể)": "怦", "Pinyin_Xie": "pēng", "Âm Hán Việt_Xie": "phanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ hoặc phó từ mô tả trạng thái tim đập mạnh do hồi hộp, thường dùng ở dạng lặp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缭', '{"9000": "3629.0", "Chữ Trung Quốc": "缭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 缭 | liêu | tượng hình | sợi vải quấn vòng — chữ độc thể trong dạng giản thể | 缭 là dạng giản thể của 繚. Chữ bộ 糸 (mịch — sợi chỉ) kết hợp thành phần biểu âm, diễn tả hành động quấn, vòng quanh bằng sợi chỉ hoặc dây.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\" (缭): sợi chỉ LIÊU XIÊU quấn vòng — 缭绕 là khói hay âm nhạc cuộn tròn bay lên. | Gương Hán-Việt | liêu trong \"liêu xiêu\" — gợi hình ảnh thứ gì đó uốn cong, vòng vèo; cũng trong 缭绕 (liêu nhiễu). | Mở khoá kiến thức | Biết 缭 mở khoá: 缭绕 (vấn vít, bay vòng), 眼花缭乱 (hoa mắt rối loạn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 缭 (phồn thể 繚) là chữ hình thanh thuộc bộ 糸 (sợi chỉ), biểu nghĩa chỉ hành động quấn, vòng quanh, khâu vắt. Wiktionary ghi nhận các nghĩa: to entwine, to wind around, to sew with slanting stitches. Chữ tạo muộn, chưa thấy cấu trúc rõ trong giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quấn, vòng quanh", "Hạng Tần Suất (Jun Da)": "3629.0", "Tần Suất % (Jun Da)": "99.6098990565", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缭", "Unihan_Traditional (Chữ Phồn thể)": "繚", "Pinyin_Xie": "liáo", "Âm Hán Việt_Xie": "liễu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước tân ngữ để tả làn khói hoặc sương bao quanh vật thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迥', '{"9000": "3630.0", "Chữ Trung Quốc": "迥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 迥 | quýnh | tượng hình | chữ độc thể — xa cách, cách biệt | 迥 là chữ độc thể trong dạng hiện đại. Bộ 辶 (sước — bước đi) kết hợp với phần âm, diễn tả ý xa cách, khác biệt hoàn toàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quýnh\" (迥): QUÝNH xa — 迥然不同 là khác BIỆT hoàn toàn, xa cách như hai thế giới. | Gương Hán-Việt | quýnh trong \"quýnh quáng\" gợi sự cách biệt, bỡ ngỡ; 迥 dùng trong văn viết để chỉ sự khác biệt rõ ràng. | Mở khoá kiến thức | Biết 迥 mở khoá: 迥然不同 (khác hẳn), 迥异 (rất khác biệt).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 迥 (jiǒng) mang nghĩa: xa, cách xa, khác biệt rõ rệt. Wiktionary ghi các nghĩa: distant, far; drastically different; far different. Trong văn viết dùng 迥异 (khác hẳn), 迥然不同 (hoàn toàn khác nhau). Nguồn gốc cổ chưa có phân tích hình thanh rõ ràng trong dữ liệu hiện có; chưa có nguồn học thuật chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khác xa; khác hẳn", "Hạng Tần Suất (Jun Da)": "3630.0", "Tần Suất % (Jun Da)": "99.6103465924", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 冋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶冋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迥", "Unihan_Traditional (Chữ Phồn thể)": "㢠", "Pinyin_Xie": "jiǒng", "Âm Hán Việt_Xie": "huýnh, quýnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ đứng trước các tính từ chỉ sự khác biệt để nhấn mạnh mức độ xa cách. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湄', '{"9000": "3631.0", "Chữ Trung Quốc": "湄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 湄 | mưa | tượng hình | chữ độc thể — bờ nước, mép sông | 湄 là chữ bộ 氵(thủy — nước) kết hợp với phần âm méi. Diễn tả vùng đất sát mép nước, bờ sông. Chữ độc lập, không phân tích thành phần rõ ràng trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mưa\" (湄): bờ sông ướt như MƯA — 湄 là mép nước, nơi đất gặp dòng chảy. | Gương Hán-Việt | mưa — âm đọc gợi nhớ hình ảnh bờ sông ẩm ướt; trong địa danh Mê Kông (湄公河) — sông Mẹ của vùng Đông Nam Á. | Mở khoá kiến thức | Biết 湄 mở khoá: 湄公河 (sông Mê Kông), 湄南河 (sông Chao Phraya).", "Tự nguyên_Xie": "Giáp cốt | Tiểu triện | Lục thư thông | 湄 (méi) nghĩa là bờ nước, mép sông, bờ bãi ven nước. Xuất hiện sớm trong thơ ca cổ điển Trung Hoa (Kinh Thi). Bộ 氵 (nước) chỉ liên quan đến sông nước. Hình ảnh glyph cổ (oracle, seal, liushutong) xác nhận chữ liên quan đến môi trường nước. Chưa có phân tích hình thanh chi tiết từ Wiktionary cho bản hiện có; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ nước; mép nước; bờ", "Hạng Tần Suất (Jun Da)": "3631.0", "Tần Suất % (Jun Da)": "99.6107941283", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湄", "Unihan_Traditional (Chữ Phồn thể)": "湄", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn thơ cổ hoặc dùng trong các địa danh chỉ vùng ven nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('磐', '{"9000": "3632.0", "Chữ Trung Quốc": "磐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 般 | ban | biểu âm | vận chuyển, quay vòng | 石 | thạch | biểu nghĩa | đá | 磐 = 般 (Ban, biểu âm) + 石 (Thạch, biểu nghĩa: đá); chữ hình thanh. Bộ thạch chỉ chất liệu đá tảng lớn, 般 cho âm pán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàn\" (磐): tảng ĐÁ (石) to như cái BÀN — 磐石 là nền tảng vững chắc không lay chuyển. | Gương Hán-Việt | bàn trong \"bàn thạch\" (磐石) — tảng đá vững như bàn; ít xuất hiện độc lập trong tiếng Việt. | Mở khoá kiến thức | Biết 磐 mở khoá: 磐石 (tảng đá, nền tảng vững chắc), 磐固 (vững như đá).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 石 (thạch) biểu nghĩa — đá; 般 biểu âm cho âm pán. 磐 chỉ tảng đá to, nặng, vững chắc. Hay dùng trong thành ngữ 磐石 (tảng đá vững chắc) để ví sự kiên định bất động. Wiktionary xác nhận cấu trúc psc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tảng đá lớn", "Hạng Tần Suất (Jun Da)": "3632.0", "Tần Suất % (Jun Da)": "99.6112406307", "GavinGrover_Once (Chiết tự trực tiếp)": "般 + 石", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱般石", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "般", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "磐", "Unihan_Traditional (Chữ Phồn thể)": "磐", "Pinyin_Xie": "pán", "Âm Hán Việt_Xie": "bàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ hoặc kết hợp tạo thành ngữ để ví với sự vững chãi, kiên cố. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渝', '{"9000": "3633.0", "Chữ Trung Quốc": "渝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 俞 | du | biểu âm | 渝 = 氵(Thủy, biểu nghĩa: nước) + 俞 (Du, biểu âm); chữ hình thanh. Bộ thủy chỉ liên quan sông nước, 俞 cho âm yú. 渝 là tên cũ của Trùng Khánh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\" (渝): NƯỚC (水) chảy thay ĐỔI — 渝 nghĩa là biến đổi, và là ký hiệu của Trùng Khánh trên biển số xe. | Gương Hán-Việt | du trong \"du lịch\" — nghĩa thay đổi, chuyển dịch; 渝 ít dùng trong tiếng Việt Hán-Việt hiện đại. | Mở khoá kiến thức | Biết 渝 mở khoá: 重庆简称渝 (Trùng Khánh viết tắt là 渝), 矢志不渝 (không đổi lòng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 氵(thủy) biểu nghĩa — liên quan đến nước, sông; 俞 biểu âm cho âm yú. 渝 có nghĩa gốc là thay đổi, đổi lòng (như nước chảy biến hình). Cũng là tên gọi tắt của Trùng Khánh (重庆) — thành phố nằm bên sông Trường Giang và Gia Lăng. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "biến đổi; châu Du", "Hạng Tần Suất (Jun Da)": "3633.0", "Tần Suất % (Jun Da)": "99.611687133", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 俞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵俞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "俞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渝", "Unihan_Traditional (Chữ Phồn thể)": "渝", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng trong văn viết, kết hợp với các từ phủ định để chỉ sự chung thủy không đổi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('冗', '{"9000": "3634.0", "Chữ Trung Quốc": "冗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冖 | Số nét | 4 | nét | 宀 | miên | biểu nghĩa | mái nhà | 儿 | nhân | biểu nghĩa | người | 冗 = 宀 (Miên, mái nhà) + 儿 (Nhân, người); chữ hội ý. Người ngồi dưới mái nhà không có việc làm — ý nghĩa: nhàn rỗi, thừa thãi, vô tích sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhũng\" (冗): người (儿) ngồi dưới MÁI NHÀ (宀) không làm gì — NHŨNG nhiễu, rườm rà, thừa thãi. | Gương Hán-Việt | nhũng trong \"tham nhũng\" — ý dư thừa, lạm dụng; 冗 diễn tả sự thừa thãi, không cần thiết. | Mở khoá kiến thức | Biết 冗 mở khoá: 冗长 (dài dòng), 冗余 (dư thừa), 冗员 (biên chế dư thừa).", "Tự nguyên_Xie": "Giáp cốt | Tiểu triện | Chữ hội ý: 宀 (miên — mái nhà) + 儿 (nhân — người): người ở nhà không có việc làm. Wiktionary ghi rõ: a person at home without work to do. Từ nghĩa gốc ''nhàn rỗi'' mở rộng sang ''thừa thãi, dài dòng, rườm rà''. Hình glyph cổ (oracle, seal) xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vô tích sự; phiền nhiễu", "Hạng Tần Suất (Jun Da)": "3634.0", "Tần Suất % (Jun Da)": "99.6121331186", "GavinGrover_Once (Chiết tự trực tiếp)": "冖 + 几", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱冖几", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "几", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冖", "Unihan_Simplified (Chữ Giản thể)": "冗", "Unihan_Traditional (Chữ Phồn thể)": "冗", "Pinyin_Xie": "rǒng", "Âm Hán Việt_Xie": "nhũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng trước danh từ để chỉ sự dư thừa, rườm rà trong công việc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('闵', '{"9000": "3635.0", "Chữ Trung Quốc": "闵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 7 | nét | 闵 | mẫn | tượng hình | chữ độc thể — bộ 門 với nét trong | 闵 là chữ bộ 門 (môn — cửa) với thành phần bên trong. Diễn tả lo âu, thương xót. Chữ độc lập, ít phân tích thêm trong tài liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mẫn\" (闵): qua CỬA (門) lo lắng MẪN cảm — 闵 diễn tả sự lo âu, thương cảm người khác. | Gương Hán-Việt | mẫn trong \"mẫn cảm\" — nhạy cảm, dễ xúc động; 闵 mang nét nghĩa lo âu, thương xót tương tự. | Mở khoá kiến thức | Biết 闵 mở khoá: 闵行 (tên quận Mẫn Hành ở Thượng Hải); họ 闵 (Mẫn).", "Tự nguyên_Xie": "Kim văn | 闵 (mǐn) nghĩa là lo lắng, thương xót, ốm đau; cũng là tên họ. Bộ 門 (môn — cửa) là bộ thủ. Hình glyph kim văn (bronze) xác nhận chữ có từ thời cổ. Chưa có phân tích hình thanh chi tiết từ Wiktionary trong dữ liệu hiện có; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo lắng; ốm đau, chết chóc; gắng gỏi; họ Mẫn", "Hạng Tần Suất (Jun Da)": "3635.0", "Tần Suất % (Jun Da)": "99.6125791042", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "闵", "Unihan_Traditional (Chữ Phồn thể)": "閔", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường dùng làm động từ thể hiện sự lo âu, thương cảm hoặc dùng làm danh từ riêng chỉ họ người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噶', '{"9000": "3636.0", "Chữ Trung Quốc": "噶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng | 葛 | cát | biểu âm | cây sắn dây | 噶 = 口 (Khẩu, biểu nghĩa: miệng) + 葛 (Cát, biểu âm); chữ hình thanh. Bộ khẩu chỉ âm thanh phát ra, 葛 cho âm gá — dùng chủ yếu để phiên âm địa danh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gắt\" (噶): MIỆNG (口) gắt gỏng — 噶 dùng để phiên âm địa danh Tạng, tiếng gắt gỏng trong họng. | Gương Hán-Việt | gắt trong \"gắt gỏng\" — ít dùng; 噶 chủ yếu là chữ phiên âm trong địa danh Tây Tạng. | Mở khoá kiến thức | Biết 噶 mở khoá: 噶厦 (chính phủ Tây Tạng cũ), 噶伦堡 (Kalimpong), 达赖喇嘛 liên quan đến 噶当派.", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu — miệng) biểu nghĩa, dùng để phiên âm; 葛 (cát) biểu âm cho âm gá. 噶 là chữ tạo ra để phiên âm tên địa danh và Tạng ngữ, ví dụ 噶厦 (chính phủ Tây Tạng cũ), 噶伦堡. Wiktionary xác nhận cấu trúc psc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên đất)", "Hạng Tần Suất (Jun Da)": "3636.0", "Tần Suất % (Jun Da)": "99.613024573", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 葛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口葛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "葛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噶", "Unihan_Traditional (Chữ Phồn thể)": "噶", "Pinyin_Xie": "gá", "Âm Hán Việt_Xie": "cát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Từ tượng thanh | 象声词 | Chủ yếu dùng làm danh từ trong các từ phiên âm tên người, địa danh hoặc dịch tiếng Tây Tạng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黏', '{"9000": "3637.0", "Chữ Trung Quốc": "黏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黍 | Số nét | 17 | nét | 黍 | thử | biểu nghĩa | lúa mì nếp, kê dính | 占 | chiêm | biểu âm | chiếm, bói | 黏 = 黍 (Thử, biểu nghĩa: kê/lúa nếp — loại ngũ cốc dính) + 占 (Chiêm, biểu âm); chữ hình thanh. Bộ thử chỉ tính chất dính của ngũ cốc nếp, 占 cho âm nián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niêm\" (黏): LÚA NẾP (黍) DÍNH bết — 黏 là dính, nhớt như gạo nếp nấu xong. | Gương Hán-Việt | niêm trong \"niêm yết\" — dán lên bảng; cùng gốc ý dính, gắn vào một chỗ. | Mở khoá kiến thức | Biết 黏 mở khoá: 黏性 (tính dính), 黏土 (đất sét), 黏液 (chất nhầy).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 黍 (thử — kê nếp, lúa nếp) biểu nghĩa, chỉ tính chất dính; 占 (chiêm) biểu âm cho âm nián. 黏 mang nghĩa dính, nhớt, có chất keo. Wiktionary xác nhận: sticky, glutinous; to adhere, to stick. Cấu trúc psc này được ghi nhận rõ ràng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất dính; dán vào", "Hạng Tần Suất (Jun Da)": "3637.0", "Tần Suất % (Jun Da)": "99.6134700417", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 占", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰占", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "黏", "Unihan_Traditional (Chữ Phồn thể)": "黏", "Pinyin_Xie": "nián", "Âm Hán Việt_Xie": "niêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ đứng trước danh từ hoặc làm vị ngữ để chỉ đặc tính kết dính của vật chất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | nián | / | dính | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính chất vật lý", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蕃', '{"9000": "3638.0", "Chữ Trung Quốc": "蕃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 15 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 番 | phan | biểu âm | lượt, phiên | 蕃 = 艹 (Tháu, biểu nghĩa: cỏ/thực vật) + 番 (Phan, biểu âm); chữ hình thanh. Bộ thảo chỉ thực vật sinh trưởng, 番 cho âm fān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phiên\" (蕃): CỎ (艹) PHIÊN phiên sinh sôi — 蕃 là thực vật mọc tươi tốt, phát triển rậm rạp. | Gương Hán-Việt | phiên trong \"phiên bang\" — vùng biên, man di; 蕃 xưa chỉ vùng đất ngoại tộc nơi cỏ mọc hoang. | Mở khoá kiến thức | Biết 蕃 mở khoá: 蕃殖 (sinh sản), 蕃茂 (cây cối tươi tốt).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: 艹 (tháu — cỏ) biểu nghĩa, chỉ cỏ cây sinh sôi; 番 (phan) biểu âm cho âm fān. 蕃 mang nghĩa: cỏ tốt, sinh sôi nảy nở, nghỉ ngơi (luân phiên ruộng đất). Cũng là từ cổ chỉ các dân tộc thiểu số / vùng biên. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ tốt; sinh sôi; nghỉ ngơi", "Hạng Tần Suất (Jun Da)": "3638.0", "Tần Suất % (Jun Da)": "99.613914477", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 番", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹番", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "番", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蕃", "Unihan_Traditional (Chữ Phồn thể)": "蕃", "Pinyin_Xie": "fān", "Âm Hán Việt_Xie": "phiên, phiền, phồn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ hoặc động từ trong văn viết để chỉ sự phát triển, sinh sôi nảy nở của cây cối. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('弼', '{"9000": "3639.0", "Chữ Trung Quốc": "弼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弓 | Số nét | 12 | nét | 弼 | bặt | tượng hình | chữ độc thể — dụng cụ chỉnh nỏ/cung, giúp đỡ | 弼 là chữ độc thể bộ 弓 (cung). Dạng cổ có hai bộ 弓 kẹp với nét chỉnh giữa — dụng cụ để nắn cung cho thẳng. Nghĩa mở rộng: giúp đỡ, phò tá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bặt\" (弼): cây CUNG (弓) được nắn THẲNG BẶT — 弼 là phò tá, giúp người trên đi thẳng đường. | Gương Hán-Việt | bặt trong \"im bặt\" — im lặng tuyệt đối; 弼 nghĩa phò tá ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 弼 mở khoá: 辅弼 (phụ tá, trợ giúp), 匡弼 (uốn nắn, phò tá).", "Tự nguyên_Xie": "Tiểu triện | 弼 (bì) theo Wiktionary: dụng cụ để chỉnh nỏ/cung cho thẳng (tool for rectifying crossbow); nghĩa văn học là phò tá, giúp đỡ. Chữ có từ thời cổ, liên quan đến nghề cung tên. Chưa có phân tích hình thanh rõ ràng trong dữ liệu hiện có; chưa có nguồn học thuật chi tiết. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lấy cho ngay, đồ để lấy cung cho ngay; giúp đỡ", "Hạng Tần Suất (Jun Da)": "3639.0", "Tần Suất % (Jun Da)": "99.6143578786", "GavinGrover_Once (Chiết tự trực tiếp)": "弜 + 百", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弜百", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "百", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "弜", "Unihan_Simplified (Chữ Giản thể)": "弼", "Unihan_Traditional (Chữ Phồn thể)": "弼", "Pinyin_Xie": "bì", "Âm Hán Việt_Xie": "bật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn ngôn để chỉ việc phò tá vua chúa hoặc giúp đỡ sửa chữa sai lầm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驿', '{"9000": "3640.0", "Chữ Trung Quốc": "驿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 驿 | dịch | tượng hình | ngựa trạm — dạng giản thể của 驛 | 驿 là dạng giản thể của 驛. Bộ 马 (mã — ngựa) kết hợp phần âm, chỉ ngựa chạy trạm dùng để đưa thư và truyền tin thời cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\" (驿): NGỰA (马) chạy trạm DỊCH truyền tin — 驿站 là trạm dừng ngựa, hệ thống bưu chính thời xưa. | Gương Hán-Việt | dịch trong \"bưu dịch\" — chuyển giao thông tin; 驿 là tiền thân của hệ thống bưu chính hiện đại. | Mở khoá kiến thức | Biết 驿 mở khoá: 驿站 (trạm dịch), 驿道 (đường trạm), 驿马 (ngựa trạm).", "Tự nguyên_Xie": "驿 (phồn thể 驛, yì) là dạng giản thể. Wiktionary ghi: 驿 zhee 驛 — cấu tạo: 馬 (mã, ngựa) + 睪 (âm). Nghĩa: ngựa trạm, trạm dịch (relay station for horses and messengers). Hệ thống trạm dịch cổ đại Trung Hoa là một trong những mạng truyền thông lớn nhất thế giới cổ đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa trạm (đưa thư, truyền chỉ dụ); việc quân đội", "Hạng Tần Suất (Jun Da)": "3640.0", "Tần Suất % (Jun Da)": "99.6148012803", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "驿", "Unihan_Traditional (Chữ Phồn thể)": "驛", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các danh từ khác để chỉ các sự vật liên quan đến hệ thống truyền tin thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淄', '{"9000": "3641.0", "Chữ Trung Quốc": "淄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 淄 | tri | tượng hình | tên sông Tri Hà ở Sơn Đông | 淄 là chữ bộ 氵(thủy — nước) kết hợp phần âm zī, chỉ tên sông Tri Hà (淄河) ở tỉnh Sơn Đông, Trung Quốc. Chữ địa danh, không phân tích thêm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tri\" (淄): con SÔNG (氵) TRI Hà ở Sơn Đông — 淄博 là thành phố nổi tiếng với đồ gốm sứ. | Gương Hán-Việt | tri trong \"tri thức\" — gợi sự hiểu biết; 淄 là địa danh lịch sử của văn minh Tề (齐) thời Xuân Thu. | Mở khoá kiến thức | Biết 淄 mở khoá: 淄博 (thành phố Truy Bác, Sơn Đông), 淄河 (sông Tri Hà).", "Tự nguyên_Xie": "Lục thư thông | 淄 (zī) là tên của sông Tri Hà (淄河, 淄水), một con sông lịch sử ở tỉnh Sơn Đông. Bộ 氵(nước) chỉ rõ đây là tên sông. Cũng là tên gọi ngắn của thành phố Truy (淄博, Zibo). Chưa có phân tích glyph chi tiết từ Wiktionary; chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Tri Hà (tên sông, ở tỉnh Sơn Đông, Trung Quốc.)", "Hạng Tần Suất (Jun Da)": "3641.0", "Tần Suất % (Jun Da)": "99.6152441651", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 甾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵甾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淄", "Unihan_Traditional (Chữ Phồn thể)": "淄", "Pinyin_Xie": "zī", "Âm Hán Việt_Xie": "truy, chuy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này chủ yếu làm danh từ riêng chỉ sông Tri hoặc làm tính từ chỉ màu đen trong văn ngôn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饺', '{"9000": "3642.0", "Chữ Trung Quốc": "饺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 9 | nét | 饣 | thực | biểu nghĩa | thức ăn (vốn 食) | 交 | giao | biểu âm | gợi âm jiǎo | 饺 = 饣 (Thực, biểu nghĩa: thức ăn) + 交 (Giao, biểu âm); là dạng giản thể của 餃, chữ hình thanh. Một loại thức ăn — ''sủi cảo, há cảo''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảo\": 饣 (thực) + 交 (giao) — món ăn gói lại, ấy là ''cảo''; nhớ 饺子 (sủi cảo/há cảo). | Gương Hán-Việt | ''cảo'' trong ''há cảo'' (饺), ''sủi cảo'' | Mở khoá kiến thức | Biết 饺 là mở 饺子, 水饺, 蒸饺 — nhóm danh từ về ẩm thực HSK 4-6.", "Tự nguyên_Xie": "Theo Wiktionary, 饺 là dạng giản thể của 餃 (rút 食 thành 饣). 餃 phồn thể là chữ hình thanh: 食 (biểu nghĩa: thức ăn) ghép với 交 (biểu âm). Nghĩa: bánh sủi cảo, bánh há cảo — món ăn bột bao nhân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bánh bao", "Hạng Tần Suất (Jun Da)": "3642.0", "Tần Suất % (Jun Da)": "99.6156865332", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "饺", "Unihan_Traditional (Chữ Phồn thể)": "餃", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ để chỉ các loại bánh làm từ bột mì có nhân. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踞', '{"9000": "3643.0", "Chữ Trung Quốc": "踞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 足 | túc | biểu nghĩa | chân, bàn chân | 居 | cư | biểu âm | ở, ngụ | 踞 = 足 (Túc, biểu nghĩa: chân) + 居 (Cư, biểu âm); chữ hình thanh. Bộ túc chỉ hành động của chân/bàn chân, 居 cho âm jù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cứ\" (踞): CHÂN (足) CƯ trú — 踞 là ngồi xổm chắn lối, hay chiếm cứ một nơi như hổ ngồi chồm hỗm. | Gương Hán-Việt | cứ trong \"cứ điểm\" — điểm chiếm giữ; 踞 gợi hình ảnh chiếm cứ, chốt giữ địa thế. | Mở khoá kiến thức | Biết 踞 mở khoá: 盘踞 (chiếm cứ lâu dài), 踞守 (giữ chặt vị trí).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 足 (túc — chân) biểu nghĩa, chỉ tư thế của chân; 居 (cư) biểu âm cho âm jù. 踞 mô tả tư thế ngồi xoạc chân, ngồi chồm hỗm, hoặc chiếm cứ (như con thú ngồi chắn). Wiktionary xác nhận cấu trúc psc, nghĩa: to crouch, to squat, to sit; to occupy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngồi xoạc chân chữ bát", "Hạng Tần Suất (Jun Da)": "3643.0", "Tần Suất % (Jun Da)": "99.6161278677", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 居", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊居", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "居", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踞", "Unihan_Traditional (Chữ Phồn thể)": "踞", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ tư thế ngồi xổm hoặc hành vi chiếm giữ một vùng đất. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('韬', '{"9000": "3644.0", "Chữ Trung Quốc": "韬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 韋 | Số nét | 14 | nét | 韬 | thao | tượng hình | túi đựng gươm/cung — chữ độc thể bộ 韦 | 韬 là chữ bộ 韦 (vi — da thuộc, vật bọc) kết hợp phần âm tāo. Nghĩa gốc là túi bọc gươm hay bao cung; nghĩa bóng là che giấu, ẩn nhẫn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thao\" (韬): cái BAO (韦) đựng GƯƠM — 韬光养晦 là giấu tài, ẩn sức mạnh như gươm trong vỏ. | Gương Hán-Việt | thao trong \"thao lược\" — mưu lược quân sự; 六韬 (Lục Thao) là binh thư nổi tiếng của Khương Thái Công. | Mở khoá kiến thức | Biết 韬 mở khoá: 韬光养晦 (giấu tài chờ thời), 六韬 (Lục Thao — binh thư), 韬略 (mưu lược).", "Tự nguyên_Xie": "Tiểu triện | 韬 (tāo) theo Wiktionary: sheath, scabbard, bow case; to hide, to conceal. Bộ 韦 (vi — da thuộc) chỉ chất liệu làm bao/túi. Thành ngữ 韬光养晦 (giấu sáng dưỡng tối) là cụm từ nổi tiếng trong chiến lược ngoại giao. Chữ tạo muộn, hình thái cổ trong seal script xác nhận qua hanziyuan. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "túi đựng gươm; phép dùng binh", "Hạng Tần Suất (Jun Da)": "3644.0", "Tần Suất % (Jun Da)": "99.6165692022", "GavinGrover_Once (Chiết tự trực tiếp)": "韦 + 舀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰韦舀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "韦", "Unihan_Simplified (Chữ Giản thể)": "韬", "Unihan_Traditional (Chữ Phồn thể)": "韜", "Pinyin_Xie": "tāo", "Âm Hán Việt_Xie": "thao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ binh pháp hoặc làm động từ với nghĩa che giấu tài năng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婷', '{"9000": "3645.0", "Chữ Trung Quốc": "婷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 12 | nét | 女 | nữ | biểu nghĩa | phụ nữ, con gái | 亭 | đình | biểu âm | đình, lầu | 婷 = 女 (Nữ, biểu nghĩa: phụ nữ) + 亭 (Đình, biểu âm); chữ hình thanh. Bộ nữ chỉ vẻ đẹp của phụ nữ, 亭 cho âm tíng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đình\" (婷): cô GÁI (女) đứng thẳng như ĐÌNH (亭) — 婷婷玉立 tả dáng đứng thướt tha như ngọc. | Gương Hán-Việt | đình trong \"đình đám\" — nổi bật, đẹp đẽ; 婷 gợi vẻ đẹp thanh tao, thướt tha. | Mở khoá kiến thức | Biết 婷 mở khoá: 婷婷 (thướt tha, mảnh mai), 婷婷玉立 (dáng đứng thướt tha như ngọc).", "Tự nguyên_Xie": "Chữ hình thanh: 女 (nữ) biểu nghĩa — vẻ đẹp của phụ nữ; 亭 (đình) biểu âm cho âm tíng. 婷 dùng trong 婷婷 hay 婷婷玉立 để tả dáng đứng thướt tha, đẹp đẽ của người con gái. Thường dùng trong tên người. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con gái đẹp", "Hạng Tần Suất (Jun Da)": "3645.0", "Tần Suất % (Jun Da)": "99.6170100199", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 亭", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女亭", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婷", "Unihan_Traditional (Chữ Phồn thể)": "婷", "Pinyin_Xie": "tíng", "Âm Hán Việt_Xie": "đình", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả dáng vẻ thanh cao, duyên dáng của người phụ nữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唆', '{"9000": "3646.0", "Chữ Trung Quốc": "唆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 夋 | biểu âm | thành phần phức hợp gồm 厶+八+夂, gợi âm suō | 唆 = 口 (Khẩu, biểu nghĩa: miệng) + 夋 (biểu âm, không có Hán-Việt riêng). Wiktionary ghi rõ ls=psc (hình thanh): 口 cho nghĩa (liên quan đến lời nói/miệng), 夋 cho âm suō. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toa\": miệng (口) không ngừng thì thầm lách cách — xúi giục người khác làm điều xấu. | Gương Hán-Việt | \"toa\" trong 教唆 (giáo toa — xúi giục); 啰唆 (la toa — dài dòng) | Mở khoá kiến thức | Biết 唆 mở khoá 教唆 (xúi giục, kích động phạm tội), 啰唆 (nói dài dòng), 唆使 (sai khiến, xúi bẩy).", "Tự nguyên_Xie": "Chữ 唆 (toa) là chữ hình thanh (ls=psc): bộ 口 (Khẩu — miệng) biểu nghĩa, chỉ hoạt động dùng lời nói; 夋 biểu âm cho âm suō. Nghĩa gốc: dùng lời xúi giục, kích động người khác làm việc xấu. Cũng có nghĩa bú mút (trong tiếng địa phương). Thường gặp trong 教唆 (xúi giục), 啰唆 (dài dòng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xui, xúi giục; bú, mút", "Hạng Tần Suất (Jun Da)": "3646.0", "Tần Suất % (Jun Da)": "99.6174503209", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唆", "Unihan_Traditional (Chữ Phồn thể)": "唆", "Pinyin_Xie": "suō", "Âm Hán Việt_Xie": "toa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành vi xúi giục người khác làm việc xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜒', '{"9000": "3647.0", "Chữ Trung Quốc": "蜒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 延 | diên | biểu âm | kéo dài, lan rộng | 蜒 = 虫 (Trùng, biểu nghĩa: côn trùng/sâu) + 延 (Diên, biểu âm); chữ hình thanh. Bộ trùng chỉ loài bò sát/côn trùng, 延 cho âm yán — gợi hình ảnh sinh vật bò dài ngoằn ngoèo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diên\" (蜒): SÂUN (虫) bò DIÊN dài — 蚰蜒 là con rết bò ngoằn ngoèo như kéo dài mãi. | Gương Hán-Việt | diên trong \"diên trì\" — kéo dài; 蜒 gợi hình ảnh sinh vật bò dài ngoằn ngoèo không dứt. | Mở khoá kiến thức | Biết 蜒 mở khoá: 蚰蜒 (con rết nhỏ), 蜒蚰 (con sên), 蜿蜒 (ngoằn ngoèo, quanh co).", "Tự nguyên_Xie": "Chữ hình thanh: 虫 (trùng) biểu nghĩa — côn trùng, sinh vật bò; 延 (diên) biểu âm cho âm yán. Wiktionary ghi 蜒 có cả ls=psc và ls=ic: to wriggle, slug, centipede. Xuất hiện trong từ ghép 蚰蜒 (con rết dài) và 蜒蚰 (con sên). Hình dạng sinh vật uốn khúc, kéo dài phù hợp với cả hai yếu tố. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: du diên 蚰蜒, diên du 蜒蚰)", "Hạng Tần Suất (Jun Da)": "3647.0", "Tần Suất % (Jun Da)": "99.6178906218", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜒", "Unihan_Traditional (Chữ Phồn thể)": "蜒", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ nhưng hầu như chỉ xuất hiện trong các từ ghép chỉ côn trùng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偎', '{"9000": "3648.0", "Chữ Trung Quốc": "偎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 人 | nhân | biểu nghĩa | người | 畏 | uý | biểu âm | sợ hãi | 偎 = 亻(Nhân, biểu nghĩa: người) + 畏 (Uý, biểu âm); chữ hình thanh. Bộ nhân chỉ hành động giữa người với người, 畏 cho âm wēi — gợi hình ảnh co rúm lại bên ai đó vì yêu thương hay sợ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủy\" (偎): NGƯỜI (亻) ÚY ÁP sát — 偎依 là dựa sát vào nhau, âu yếm bên nhau như trẻ con bên cha mẹ. | Gương Hán-Việt | ủy trong \"ủy mị\" — mềm yếu, âu yếm; 偎 gợi hình ảnh dịu dàng, nương tựa vào nhau. | Mở khoá kiến thức | Biết 偎 mở khoá: 偎依 (âu yếm dựa vào nhau), 偎抱 (ôm ấp).", "Tự nguyên_Xie": "Chữ hình thanh: 亻(nhân — người) biểu nghĩa, chỉ quan hệ giữa người; 畏 (uý) biểu âm cho âm wēi. 偎 mang nghĩa âu yếm, ôm sát, dựa vào — hành động của người thân thiết tựa vào nhau. Wiktionary xác nhận cấu trúc psc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "âu yếm, ôm ấp", "Hạng Tần Suất (Jun Da)": "3648.0", "Tần Suất % (Jun Da)": "99.6183298891", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 畏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻畏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偎", "Unihan_Traditional (Chữ Phồn thể)": "偎", "Pinyin_Xie": "wēi", "Âm Hán Việt_Xie": "ôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nép sát hoặc tựa vào ai đó một cách thân thiết. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榨', '{"9000": "3649.0", "Chữ Trung Quốc": "榨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 14 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 窄 | trách | biểu âm | hẹp, chật | 榨 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 窄 (Trách, biểu âm). Wiktionary ghi ls=psc và ls2=ic: chủ yếu là hình thanh (木 cho nghĩa — đồ làm bằng gỗ để ép; 窄 cho âm zhà); cũng có yếu tố hội ý (窄 nghĩa hẹp gợi ép chặt). Chữ hình thanh có yếu tố hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trá\": chiếc máy gỗ (木) ép chật (窄) trái cây — vắt kiệt từng giọt nước. | Gương Hán-Việt | \"trá\" trong 压榨 (áp trá — bóc lột, ép buộc); 榨汁 (trá trấp — vắt nước) | Mở khoá kiến thức | Biết 榨 mở khoá 压榨 (ép bóc lột), 榨汁 (vắt nước hoa quả), 榨汁机 (máy xay sinh tố).", "Tự nguyên_Xie": "Chữ 榨 (trá) là chữ hình thanh có yếu tố hội ý (ls=psc, ls2=ic): bộ 木 (Mộc) biểu nghĩa chỉ vật dụng làm bằng gỗ dùng để ép; 窄 (Trách, nghĩa hẹp/chật) vừa biểu âm zhà vừa gợi ý nghĩa ép chặt. Nghĩa gốc: dụng cụ gỗ ép dầu, ép nước; mở rộng nghĩa: vắt kiệt, bóc lột. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bàn ép dầu", "Hạng Tần Suất (Jun Da)": "3649.0", "Tần Suất % (Jun Da)": "99.6187686397", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 窄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木窄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榨", "Unihan_Traditional (Chữ Phồn thể)": "搾", "Pinyin_Xie": "zhà", "Âm Hán Việt_Xie": "trá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc ép lấy nước hoặc làm danh từ chỉ dụng cụ dùng để ép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhà | / | vắt | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漉', '{"9000": "3650.0", "Chữ Trung Quốc": "漉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 漉 | lộc | tượng hình | lọc nước — chữ bộ 氵 | 漉 là chữ bộ 氵(thủy — nước) kết hợp phần âm lù. Diễn tả hành động lọc nước qua vật liệu, hoặc ướt đẫm, nhỏ giọt. Chữ độc lập, phân tích glyph chi tiết còn hạn chế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\" (漉): NƯỚC (氵) LỌC qua bộ lộc — 漉 là lọc nước, nhỏ giọt cho đến cạn kiệt. | Gương Hán-Việt | lộc trong \"lộc tức\" — lọc lấy phần tinh; 漉 gợi hình ảnh lọc qua nhiều lần. | Mở khoá kiến thức | Biết 漉 mở khoá: 漉酒 (lọc rượu), 渗漉 (thấm qua, lọc qua).", "Tự nguyên_Xie": "Tiểu triện | 漉 (lù) theo Wiktionary: to filter, to strain; to drain; exhausted, drained. Bộ 氵(thủy) biểu nghĩa — liên quan đến nước. Hình glyph seal script xác nhận qua hanziyuan. Nghĩa ''cạn kiệt, hết sạch'' là nghĩa mở rộng từ hình ảnh nước nhỏ giọt qua bộ lọc cho đến khi cạn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lọc; hết, cạn kiệt", "Hạng Tần Suất (Jun Da)": "3650.0", "Tần Suất % (Jun Da)": "99.6192073903", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漉", "Unihan_Traditional (Chữ Phồn thể)": "漉", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động lọc chất lỏng hoặc làm cho ráo nước. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碉', '{"9000": "3651.0", "Chữ Trung Quốc": "碉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 碉 | điêu | tượng hình | tháp đá, lô cốt đá — chữ bộ 石 | 碉 là chữ bộ 石 (thạch — đá) kết hợp phần âm diāo. Diễn tả công trình xây bằng đá để phòng thủ quân sự — lô cốt, tháp canh đá. Chưa có glyph cổ trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\" (碉): tháp ĐÁ (石) ĐIÊU truy — 碉堡 là lô cốt đá kiên cố, vững như núi. | Gương Hán-Việt | điêu trong \"điêu khắc\" — tạo hình bằng đá; 碉 cũng liên quan đến đá, nhưng là kiến trúc phòng thủ. | Mở khoá kiến thức | Biết 碉 mở khoá: 碉堡 (lô cốt, pháo đài đá), 碉楼 (tháp pháo đài).", "Tự nguyên_Xie": "碉 (diāo) là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Bộ 石 (thạch) biểu nghĩa — xây bằng đá; phần âm cho âm diāo. 碉 chỉ loại tháp đá hoặc lô cốt kiên cố dùng để canh gác và phòng thủ, phổ biến ở vùng Tây Nam Trung Quốc (Tứ Xuyên, Tây Tạng). Thành ngữ 碉堡 (lô cốt) phổ biến trong văn học chiến tranh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhà xây bằng đá để đề phòng giặc cướp, cái lô-cốt", "Hạng Tần Suất (Jun Da)": "3651.0", "Tần Suất % (Jun Da)": "99.6196456241", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碉", "Unihan_Traditional (Chữ Phồn thể)": "碉", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các công trình kiến trúc bằng đá dùng để phòng thủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皈', '{"9000": "3652.0", "Chữ Trung Quốc": "皈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 9 | nét | 自 | tự | biểu nghĩa | tự thân, từ mình | 反 | phản | biểu nghĩa | quay lại, trở về | 皈 = 白 (biến dạng từ 自, Tự — tự thân) + 反 (Phản — quay trở về); chữ hội ý. Tự mình quay trở về (quy y) — 皈 chuyên dùng trong thuật ngữ Phật giáo 皈依 (quy y).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quy\" (皈): TỰ (自→白) mình PHẢN về nguồn — 皈依 là quy y, tự nguyện quay về nương tựa Phật pháp. | Gương Hán-Việt | quy trong \"quy y\" — trở về nương tựa; 皈 và 归 (quy) cùng nghĩa về/trở về, nhưng 皈 chuyên dùng trong Phật giáo. | Mở khoá kiến thức | Biết 皈 mở khoá: 皈依 (quy y, nương tựa Tam Bảo), 皈依三宝 (quy y Phật, Pháp, Tăng).", "Tự nguyên_Xie": "皈 vốn là 𦤇 — hội ý: 自 (tự — tự thân) + 反 (phản — quay lại/trở về): tự mình quay trở về. Sau đó 自 bị biến dạng thành 白 trong dạng hiện đại. Wiktionary ghi: considered a 後起字 (chữ tạo sau), variant của 歸 (quy). Chỉ dùng trong ngữ cảnh Phật giáo: 皈依 (quy y Tam Bảo — Phật, Pháp, Tăng). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "305.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bạch (88) Phản (304)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bạch (số 106 - màu trắng, trong sáng) và chữ Phản (số 304) . Bỏ chỗ tối quay trở lại (phản) chỗ sáng (bạch) gọi là quy.", "Nghĩa Tiếng Việt_Xie": "quy phục", "Hạng Tần Suất (Jun Da)": "3652.0", "Tần Suất % (Jun Da)": "99.6200838579", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皈", "Unihan_Traditional (Chữ Phồn thể)": "皈", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "quy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc quy thuận hoặc thành tâm hướng về tôn giáo. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('矜', '{"9000": "3653.0", "Chữ Trung Quốc": "矜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 矛 | Số nét | 9 | nét | 矛 | mâu | biểu nghĩa | cây giáo, mâu | 令 | lệnh | biểu âm | lệnh, ra lệnh | 矜 = 矛 (Mâu, biểu nghĩa: cây giáo) + 令 (Lệnh, biểu âm — tuy nhiên âm hiện đại jīn theo 今 do biến dạng); chữ hình thanh. Gốc là cán giáo, nghĩa mở rộng: tự kiêu, cẩn trọng, thương xót.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"căng\" (矜): cầm MÂU (矛) CĂNG ngực kiêu ngạo — 矜持 là đài các, tự giữ thể diện. | Gương Hán-Việt | căng trong \"căng thẳng\" — giữ thẳng người, tự tôn; 矜持 mô tả người giữ vẻ trang nghiêm, không để lộ cảm xúc. | Mở khoá kiến thức | Biết 矜 mở khoá: 矜持 (đài các, giữ thể diện), 矜夸 (khoe khoang), 矜怜 (thương xót).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | 矜 là dạng biến dạng từ 矝, hội hình thanh: 矛 (mâu — cây giáo) biểu nghĩa, 令 (lệnh) biểu âm. Wiktionary ghi: bị biến dạng, âm Mandarin hiện đại theo phần âm 今 (jīn) chứ không phải 令. Nghĩa ban đầu: cán giáo; nghĩa mở rộng: tự hào, khoe khoang, cẩn thận, thương xót. Bronze, silk, bigseal script xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoe khoang", "Hạng Tần Suất (Jun Da)": "3653.0", "Tần Suất % (Jun Da)": "99.6205220917", "GavinGrover_Once (Chiết tự trực tiếp)": "矛 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰矛今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "矛", "Unihan_Simplified (Chữ Giản thể)": "矜", "Unihan_Traditional (Chữ Phồn thể)": "矜", "Pinyin_Xie": "jīn", "Âm Hán Việt_Xie": "căng, quan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ thể hiện sự thương xót hoặc làm tính từ chỉ thái độ kiêu ngạo, tự phụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笈', '{"9000": "3654.0", "Chữ Trung Quốc": "笈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 9 | nét | 𥫗 | trúc | biểu nghĩa | tre, trúc | 及 | cập | biểu âm | kịp, đến | 笈 = 𥫗(Trúc, biểu nghĩa: tre) + 及 (Cập, biểu âm); chữ hình thanh. Bộ trúc chỉ chất liệu làm hòm sách (tre/mây), 及 cho âm jí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cặp\" (笈): CẶP sách TRÚc (𥫗) — 笈 là cái hòm sách làm bằng tre, học trò xưa mang đi học. | Gương Hán-Việt | cặp trong \"cặp sách\" — túi đựng sách học sinh; 笈 là tiền thân, hòm sách tre thời cổ đại. | Mở khoá kiến thức | Biết 笈 mở khoá: 负笈 (gánh sách đi học, ám chỉ du học), 笈中 (trong hòm sách).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 竹 (trúc — tre) biểu nghĩa, chỉ hòm/tráp làm từ tre để đựng sách; 及 (cập) biểu âm cho âm jí. 笈 là loại hòm sách nhỏ học trò xưa đeo sau lưng. Wiktionary xác nhận cấu trúc psc. Chữ tạo muộn, chỉ xuất hiện trong liushutong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hòm sách, tráp sách", "Hạng Tần Suất (Jun Da)": "3654.0", "Tần Suất % (Jun Da)": "99.6209598087", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 及", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮及", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "及", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笈", "Unihan_Traditional (Chữ Phồn thể)": "笈", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "cấp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cái tráp tre hoặc hòm gỗ nhỏ dùng để đựng sách vở thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枷', '{"9000": "3655.0", "Chữ Trung Quốc": "枷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 9 | nét | 枷 | da | tượng hình | cái gông — chữ bộ 木 | 枷 là chữ bộ 木 (mộc — gỗ) kết hợp phần âm jiā. Chỉ cái gông bằng gỗ dùng để cùm cổ phạm nhân thời phong kiến. Chưa có cây thành phần rõ ràng trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"da\" (枷): tấm GỖ (木) DA thịt — cái gông gỗ tra vào cổ phạm nhân như xiềng xích da thịt. | Gương Hán-Việt | da trong \"da diết\" — gợi cảm giác ràng buộc, không thoát được; 枷锁 là xiềng xích, gông cùm. | Mở khoá kiến thức | Biết 枷 mở khoá: 枷锁 (gông cùm, xiềng xích), 枷号 (đeo gông bêu xấu hổ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 枷 (jiā) theo Wiktionary: cangue — loại gông gỗ lớn đeo quanh cổ phạm nhân, là hình phạt phổ biến trong luật hình sự phong kiến Trung Hoa. Bộ 木 (mộc) biểu nghĩa — làm bằng gỗ. Hình glyph bigseal và seal xác nhận qua hanziyuan. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái gông (để cùm đầu phạm nhân)", "Hạng Tần Suất (Jun Da)": "3655.0", "Tần Suất % (Jun Da)": "99.6213964921", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 加", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木加", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "加", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "枷", "Unihan_Traditional (Chữ Phồn thể)": "枷", "Pinyin_Xie": "jiā", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ dụng cụ bằng gỗ dùng để khóa cổ phạm nhân thời xưa hoặc làm động từ với nghĩa đeo gông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鲨', '{"9000": "3656.0", "Chữ Trung Quốc": "鲨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 15 | nét | 沙 | sa | biểu âm | cát, cồn cát | 魚 | ngư | biểu nghĩa | cá | 鲨 = 沙 (Sa, biểu âm) + 鱼 (Ngư, biểu nghĩa: cá); chữ hình thanh. Bộ ngư chỉ loài cá, 沙 cho âm shā.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sa\" (鲨): CÁ (鱼) da nhám như CÁT SA (沙) — 鲨鱼 là cá mập, da ráp như cồn cát. | Gương Hán-Việt | sa trong \"sa mạc\" — cát; da cá mập ráp như cát sa mạc, nên 沙 làm thành phần biểu âm kiêm gợi hình. | Mở khoá kiến thức | Biết 鲨 mở khoá: 鲨鱼 (cá mập), 大白鲨 (cá mập trắng lớn), 鲨鱼皮 (da cá mập).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 鱼 (ngư — cá) biểu nghĩa; 沙 (sa) biểu âm cho âm shā. 鲨 là cá mập, cá nhám — loài cá lớn da nhám như cát (sa). Tên gọi khởi nguồn từ da cá nhám ráp như cát. Wiktionary xác nhận cấu trúc psc. Chữ tạo muộn, xuất hiện trong liushutong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cá nhám, cá mập", "Hạng Tần Suất (Jun Da)": "3656.0", "Tần Suất % (Jun Da)": "99.6218331756", "GavinGrover_Once (Chiết tự trực tiếp)": "沙 + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱沙鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "沙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鲨", "Unihan_Traditional (Chữ Phồn thể)": "鯊", "Pinyin_Xie": "shā", "Âm Hán Việt_Xie": "sa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ để chỉ các loài cá mập hoặc cá nhám dưới biển. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹑', '{"9000": "3657.0", "Chữ Trung Quốc": "蹑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 𧾷 | túc | biểu nghĩa | chân, bàn chân | 聶 | nhiếp | biểu âm | 蹑 = 𧾷(Túc, biểu nghĩa: chân) + 聶 (Nhiếp, biểu âm); chữ hình thanh. Bộ túc chỉ hành động của chân, 聶 cho âm niè — gợi hình ảnh bước đi nhẹ nhàng, rón rén.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhiếp\" (蹑): CHÂN (足) NHIẾP nhẹ — 蹑手蹑脚 là đi rón rén, nhẹ nhàng từng bước. | Gương Hán-Việt | nhiếp trong \"nhiếp ảnh\" — nắm bắt khoảnh khắc; 蹑 gợi hành động âm thầm, bước nhẹ để không bị phát hiện. | Mở khoá kiến thức | Biết 蹑 mở khoá: 蹑手蹑脚 (đi rón rén), 追蹑 (bám theo, truy đuổi).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 足 (túc — chân, dạng biến 𧾷) biểu nghĩa; 聶 (nhiếp) biểu âm cho âm niè. 蹑 mô tả cách đi rón rén, nhẹ nhàng và nhanh nhẹn — như rón rén theo dõi ai. Wiktionary xác nhận cấu trúc psc. Hình glyph seal xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rón bước, đi nhẹ và nhanh", "Hạng Tần Suất (Jun Da)": "3657.0", "Tần Suất % (Jun Da)": "99.6222693422", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 聂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊聂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "聂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹑", "Unihan_Traditional (Chữ Phồn thể)": "躡", "Pinyin_Xie": "niè", "Âm Hán Việt_Xie": "niếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đi nhẹ nhàng, rón rén hoặc dẫm chân lên vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瀚', '{"9000": "3658.0", "Chữ Trung Quốc": "瀚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 19 | nét | 氵 | thủy | biểu nghĩa | nước | 翰 | hàn | biểu âm | lông chim, bút lông | 瀚 = 氵(Thủy, biểu nghĩa: nước) + 翰 (Hàn, biểu âm); chữ hình thanh. Bộ thủy chỉ sự mênh mông như biển, 翰 cho âm hàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàn\" (瀚): NƯỚC (氵) MÊNH MÔNG HÀN — 浩瀚 là mênh mông bát ngát, như sa mạc 瀚海 rộng như biển. | Gương Hán-Việt | hàn trong \"hàn lâm\" (翰林) — quan viên chữ nghĩa; 瀚 gợi kiến thức mênh mông như biển. | Mở khoá kiến thức | Biết 瀚 mở khoá: 浩瀚 (mênh mông, bao la), 瀚海 (biển sa mạc), 瀚墨 (sách vở, văn chương).", "Tự nguyên_Xie": "Chữ hình thanh: 氵(thủy) biểu nghĩa — mênh mông như nước; 翰 (hàn) biểu âm cho âm hàn. 瀚 mang nghĩa mênh mông, rộng lớn. 瀚海 (hàn hải) là biển sa mạc — ám chỉ sa mạc Gobi rộng mênh mông như biển. 浩瀚 là thành ngữ tả sự rộng lớn vô bờ. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hãn hải 瀚海); (xem: hạo hãn 浩瀚)", "Hạng Tần Suất (Jun Da)": "3658.0", "Tần Suất % (Jun Da)": "99.6227044753", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 翰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵翰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "翰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "瀚", "Unihan_Traditional (Chữ Phồn thể)": "瀚", "Pinyin_Xie": "hàn", "Âm Hán Việt_Xie": "hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ mô tả sự rộng lớn, bao la của biển cả hoặc sa mạc trong các từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酪', '{"9000": "3659.0", "Chữ Trung Quốc": "酪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 各 | cac | biểu âm | mỗi, từng | 酉 | dấu | biểu nghĩa | rượu, đồ uống lên men | 酪 = 各 (Cac, biểu âm) + 酉 (Dấu, biểu nghĩa: rượu/đồ lên men); chữ hình thanh. Bộ dậu chỉ sản phẩm lên men hoặc chế biến từ sữa, 各 cho âm lào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lạc\" (酪): RƯỢU BÌNH (酉) LẠC đông — 酪 là sữa đông, phô mai, sản phẩm từ sữa lên men. | Gương Hán-Việt | lạc trong \"trà sữa\" — sữa; 酪 gợi sản phẩm sữa Mông Cổ hay Trung Á truyền thống. | Mở khoá kiến thức | Biết 酪 mở khoá: 奶酪 (pho mai, phô mai), 乳酪 (phô mai), 果冻酪 (thạch trái cây).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 酉 (dậu — bình rượu, đồ lên men) biểu nghĩa; 各 (cac) biểu âm cho âm lào. 酪 chỉ sản phẩm sữa cô đặc, pho mát, kem sữa — loại thực phẩm được ủ/lên men từ sữa. Wiktionary xác nhận cấu trúc psc. Hình glyph seal xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cô đặc sữa", "Hạng Tần Suất (Jun Da)": "3659.0", "Tần Suất % (Jun Da)": "99.6231385748", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 各", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉各", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "各", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酪", "Unihan_Traditional (Chữ Phồn thể)": "酪", "Pinyin_Xie": "lào", "Âm Hán Việt_Xie": "lạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các chế phẩm từ sữa như sữa chua, phô mai hoặc nước trái cây cô đặc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谑', '{"9000": "3660.0", "Chữ Trung Quốc": "谑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 谑 | hước | tượng hình | dạng giản thể của 謔 — bộ 讠(ngôn) với phần âm | 谑 là dạng giản thể của 謔. Bộ 讠(ngôn — lời nói) kết hợp phần âm xuè, diễn tả hành động nói đùa, châm chọc bằng lời.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hước\" (谑): MIỆNG (讠) NÓI HƯỚC hước — 谑 là nói đùa, trêu cợt bằng lời nói duyên dáng. | Gương Hán-Việt | hước trong \"hài hước\" — vui cười, đùa giỡn; 谑 gợi lối nói đùa tinh tế, khéo léo. | Mở khoá kiến thức | Biết 谑 mở khoá: 嘲谑 (chế giễu, chế nhạo), 戏谑 (đùa giỡn, trêu chọc).", "Tự nguyên_Xie": "Tiểu triện | 谑 (phồn thể 謔, xuè) dạng giản thể. Wiktionary: 谑 zhee 謔 — bộ 訁(ngôn) + phần âm. Nghĩa: nói đùa, đùa cợt, trêu chọc. 谑而不虐 là thành ngữ: đùa vui mà không độc ác. Hình glyph seal xác nhận qua hanziyuan. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói đùa, đùa cợt", "Hạng Tần Suất (Jun Da)": "3660.0", "Tần Suất % (Jun Da)": "99.6235726743", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 虐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠虐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "虐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谑", "Unihan_Traditional (Chữ Phồn thể)": "謔", "Pinyin_Xie": "xuè", "Âm Hán Việt_Xie": "hước", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động trêu chọc, đùa cợt hoặc làm tính từ chỉ tính chất khôi hài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('癖', '{"9000": "3661.0", "Chữ Trung Quốc": "癖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 18 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 辟 | tích | biểu âm | mở ra, loại bỏ | 癖 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 辟 (Tích, biểu âm); chữ hình thanh. Bộ nạch chỉ trạng thái bệnh lý, 辟 cho âm pǐ — ám chỉ thói quen bệnh lý, nghiện ngập.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\" (癖): BỆNH (疒) TÍCH tụ lâu ngày — 癖好 là thói quen đã ăn sâu như bệnh mãn tính. | Gương Hán-Việt | tích trong \"tích lũy\" — tích góp lâu ngày; 癖 là thứ tích tụ trở thành thói quen không bỏ được. | Mở khoá kiến thức | Biết 癖 mở khoá: 癖好 (sở thích, tật riêng), 洁癖 (ám ảnh sạch sẽ), 书癖 (mê sách).", "Tự nguyên_Xie": "Chữ hình thanh: 疒 (nạch — bệnh) biểu nghĩa; 辟 (tích) biểu âm cho âm pǐ. 癖 ban đầu chỉ bệnh tích (khối u trong bụng) trong y học cổ đại; nghĩa phổ biến hiện nay là tật xấu, thói quen khó bỏ, sở thích cực đoan (癖好). Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh hòn (tích thành hòn trong bụng)", "Hạng Tần Suất (Jun Da)": "3661.0", "Tần Suất % (Jun Da)": "99.6240067739", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 辟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒辟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "癖", "Unihan_Traditional (Chữ Phồn thể)": "癖", "Pinyin_Xie": "pǐ", "Âm Hán Việt_Xie": "phích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ sở thích đặc biệt, thói quen khó bỏ hoặc chứng bệnh tích tụ trong cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烬', '{"9000": "3662.0", "Chữ Trung Quốc": "烬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 10 | nét | 烬 | tận | tượng hình | dạng giản thể của 燼 — lửa tàn | 烬 là dạng giản thể của 燼. Bộ 火 (hỏa — lửa) kết hợp phần 尽 (tận), gợi ý lửa cháy đến tận cùng — chỉ còn tàn lửa. Cấu trúc ⿰火尽.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tận\" (烬): LỬA (火) cháy TẬN cùng — 灰烬 là tro tàn, những gì còn lại sau khi lửa đã thiêu rụi. | Gương Hán-Việt | tận trong \"tận thế\" — hết sạch; 烬 gợi hình ảnh sau cơn lửa dữ, chỉ còn tro tàn. | Mở khoá kiến thức | Biết 烬 mở khoá: 灰烬 (tro tàn), 余烬 (tàn lửa còn sót), 化为灰烬 (biến thành tro).", "Tự nguyên_Xie": "Giáp cốt | Tiểu triện | Lục thư thông | 烬 (phồn thể 燼, jìn) dạng giản thể. Wiktionary: cinders, ashes, embers; remnants. Bộ 火 (hỏa) biểu nghĩa — lửa; phần 尽 (tận — hết) gợi lửa cháy hết chỉ còn tàn. Hình glyph oracle, seal, liushutong xác nhận qua hanziyuan. 余烬 (tàn lửa còn sót) và 灰烬 (tro tàn) là từ phổ biến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lửa tàn", "Hạng Tần Suất (Jun Da)": "3662.0", "Tần Suất % (Jun Da)": "99.624439323", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 尽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火尽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烬", "Unihan_Traditional (Chữ Phồn thể)": "燼", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần tro bụi hoặc tàn dư còn sót lại sau khi lửa tắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('揩', '{"9000": "3663.0", "Chữ Trung Quốc": "揩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 揩 | khải | tượng hình | chữ bộ 扌(thủ) — lau, chùi | 揩 là chữ bộ 扌(thủ — tay) kết hợp phần âm kāi. Diễn tả hành động dùng tay lau sạch, chùi đi. Chữ độc lập, không phân tích thêm thành phần trong dữ liệu hiện có.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khải\" (揩): TAY (扌) KHẢI sạch — 揩 là dùng tay lau, chùi đi vết bẩn; 揩油 là ''lau dầu'' — ám chỉ kiếm chác. | Gương Hán-Việt | khải trong \"khải hoàn\" — gợi sự sạch sẽ, dứt khoát; 揩 mang nghĩa cụ thể hơn: lau chùi bằng tay. | Mở khoá kiến thức | Biết 揩 mở khoá: 揩油 (lau dầu mỡ; nghĩa bóng: kiếm chác lợi dụng), 揩拭 (lau chùi).", "Tự nguyên_Xie": "揩 (kāi) theo Wiktionary: to wipe, to clean. Bộ 扌(thủ — tay) biểu nghĩa, chỉ hành động tay chùi, lau. Wiktionary ghi âm Thượng Hải là 5kae với nghĩa riêng ''to wipe''. Chữ có từ thời Trung Cổ (mc=y, oc=y), xác nhận nguồn gốc cổ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lau, chùi", "Hạng Tần Suất (Jun Da)": "3663.0", "Tần Suất % (Jun Da)": "99.6248718722", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "揩", "Unihan_Traditional (Chữ Phồn thể)": "揩", "Pinyin_Xie": "kāi", "Âm Hán Việt_Xie": "khai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động lau, chùi hoặc quẹt sạch vết bẩn trên bề mặt vật thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炙', '{"9000": "3664.0", "Chữ Trung Quốc": "炙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 炙 | chích | tượng hình | thịt (月/肉) trên lửa (火) — tượng hình | 炙 là chữ hội ý/tượng hình: phần trên là 肉 (nhục — thịt, dạng biến thể) + phần dưới là 火 (hỏa — lửa) — thịt nướng trên lửa. Diễn tả hành động nướng chín trực tiếp trên lửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chích\" (炙): THỊT (月) trên LỬA (火) — 炙 là nướng trực tiếp; 脍炙人口 là câu nói/bài thơ được ''nướng'' vào miệng mọi người. | Gương Hán-Việt | chích trong \"châm chích\" — đốt, chích; 炙 gợi nhiệt, lửa nóng tác động trực tiếp. | Mở khoá kiến thức | Biết 炙 mở khoá: 脍炙人口 (được yêu thích rộng rãi), 炙热 (nóng như lửa thiêu), 炙烤 (nướng, quay).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 炙 (zhì) là chữ tượng hình/hội ý: phần trên 月/肉 (thịt) + phần dưới 火 (lửa) — hình ảnh miếng thịt đặt trên lửa để nướng. Nghĩa gốc: nướng chín. Nghĩa mở rộng: hơ nóng, phơi nắng; 脍炙人口 (ngon miệng khắp nơi — thành ngữ chỉ thứ được yêu thích rộng rãi). Hình glyph seal và liushutong xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "455.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (140) Nhục (130)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Nhục (số 130 - thịt) ở trên chữ Hỏa (số 86 - ngọn lửa) . Đem miếng thịt (Nhục) hơ trên ngọn lửa (Hỏa) gọi là nướng (chích/chá). Giải thích sự chuyển ý: Đây là chữ Hội ý. Hình ảnh miếng thịt (Nhục) được đặt trực tiếp trên ngọn lửa (Hỏa) để nấu chín, nghĩa là nướng (Chích).", "Nghĩa Tiếng Việt_Xie": "nướng chín", "Hạng Tần Suất (Jun Da)": "3664.0", "Tần Suất % (Jun Da)": "99.6253044213", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 火", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱月火", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "火", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "炙", "Unihan_Traditional (Chữ Phồn thể)": "炙", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "chích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động đặt thịt lên lửa để nướng chín hoặc chịu sự nung nấu, ảnh hưởng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜷', '{"9000": "3665.0", "Chữ Trung Quốc": "蜷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 卷 | cuộn | biểu âm | cuộn, cuốn | 蜷 = 虫 (Trùng, biểu nghĩa: côn trùng/sâu) + 卷 (Cuộn, biểu âm); chữ hình thanh. Bộ trùng chỉ sinh vật bò, 卷 cho âm quán — gợi hình ảnh sinh vật cuộn tròn lại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyền\" (蜷): SÂU (虫) CUỘN (卷) tròn — 蜷缩 là co quắp lại, thu mình như con giun uốn tròn. | Gương Hán-Việt | quyền trong \"quyền anh\" — co tay đấm; 蜷 gợi hành động co rút, cuộn người lại. | Mở khoá kiến thức | Biết 蜷 mở khoá: 蜷缩 (co quắp, thu mình), 蜷曲 (uốn cong, cuộn lại).", "Tự nguyên_Xie": "Chữ hình thanh: 虫 (trùng) biểu nghĩa — sinh vật nhỏ, sâu; 卷 (cuộn) biểu âm cho âm quán. 蜷 mô tả hành động cuộn tròn, co rút của cơ thể — như con giun cuộn lại hay người co quắp trong giá lạnh. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bò ngoằn nghoèo, bò uốn éo", "Hạng Tần Suất (Jun Da)": "3665.0", "Tần Suất % (Jun Da)": "99.6257369705", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 卷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫卷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜷", "Unihan_Traditional (Chữ Phồn thể)": "蜷", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "quyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước bổ ngữ xu hướng để chỉ tư thế co quắp của cơ thể. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('侏', '{"9000": "3666.0", "Chữ Trung Quốc": "侏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 人 | nhân | biểu nghĩa | người | 朱 | chu | biểu âm | đỏ son, họ Chu | 侏 = 亻(Nhân, biểu nghĩa: người) + 朱 (Chu, biểu âm); chữ hình thanh. Bộ nhân chỉ đặc điểm của người, 朱 cho âm zhū.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chu\" (侏): NGƯỜI (亻) CHU nhỏ — 侏儒 là người lùn; 侏罗纪 (Jura) là thời đại của khủng long nhỏ và lớn. | Gương Hán-Việt | chu trong \"Chu Du\" — người khéo léo; 侏 gợi hình ảnh người nhỏ bé nhưng có vị trí trong thần thoại. | Mở khoá kiến thức | Biết 侏 mở khoá: 侏儒 (người lùn, thần lùn), 侏罗纪 (kỷ Jura).", "Tự nguyên_Xie": "Chữ hình thanh: 亻(nhân — người) biểu nghĩa; 朱 (chu) biểu âm cho âm zhū. 侏 nghĩa là lùn, còi, nhỏ bé, chủ yếu dùng trong 侏儒 (người lùn, người nhỏ bé). 侏罗纪 (kỷ Jura) là tên thời kỳ địa chất nổi tiếng qua phim khủng long. Wiktionary xác nhận cấu trúc psc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lùn, còi, nhỏ bé", "Hạng Tần Suất (Jun Da)": "3666.0", "Tần Suất % (Jun Da)": "99.6261690029", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 朱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻朱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "侏", "Unihan_Traditional (Chữ Phồn thể)": "侏", "Pinyin_Xie": "zhū", "Âm Hán Việt_Xie": "chu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ bổ nghĩa cho danh từ hoặc kết hợp tạo thành từ ghép chỉ người lùn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('凋', '{"9000": "3667.0", "Chữ Trung Quốc": "凋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 冫 | Số nét | 10 | nét | 凋 | điêu | tượng hình | chữ bộ 冫— tàn rụng, héo | 凋 là chữ bộ 冫(băng — lạnh) kết hợp phần âm diāo. Bộ băng gợi lạnh lẽo làm cây héo tàn, rụng lá. Nghĩa: héo, tàn, rụng, suy tàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\" (凋): GIÁ LẠNH (冫) ĐIÊU tàn — 凋零 là điêu tàn, lá rụng trong gió lạnh. | Gương Hán-Việt | điêu trong \"điêu tàn\" — hư hỏng, tàn lụi; 凋谢 là hoa tàn rụng, 凋零 là cảnh điêu linh. | Mở khoá kiến thức | Biết 凋 mở khoá: 凋谢 (hoa tàn, rụng), 凋零 (điêu linh, tàn lụi), 凋落 (rụng xuống).", "Tự nguyên_Xie": "Tiểu triện | 凋 (diāo) theo Wiktionary: to wither, to fall; to exhaust, to fade; (of life and business) depressed, in decline. Bộ 冫(băng — lạnh) gợi cái lạnh khiến cây cối héo tàn. Nghĩa gốc: rụng, héo; nghĩa mở rộng: suy tàn, tiêu điều. 凋零 (tàn lụi, điêu linh) và 凋谢 (tàn rụng) là từ phổ biến. Hình glyph seal xác nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tàn rạc, héo rụng", "Hạng Tần Suất (Jun Da)": "3667.0", "Tần Suất % (Jun Da)": "99.6266005184", "GavinGrover_Once (Chiết tự trực tiếp)": "冫 + 周", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰冫周", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "周", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "冫", "Unihan_Simplified (Chữ Giản thể)": "凋", "Unihan_Traditional (Chữ Phồn thể)": "凋", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ hoặc tính từ miêu tả trạng thái tàn héo của hoa lá hoặc sự suy thoái. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漪', '{"9000": "3668.0", "Chữ Trung Quốc": "漪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 漪 | y | tượng hình | chữ bộ 氵— sóng lăn tăn | 漪 là chữ bộ 氵(thủy — nước) kết hợp phần âm yī. Diễn tả những gợn sóng nhỏ, lăn tăn trên mặt nước — hình ảnh thơ mộng trong thơ văn cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"y\" (漪): NƯỚC (氵) GỢN sóng Y — 涟漪 là những gợn sóng lăn tăn lan rộng như vòng tròn đồng tâm. | Gương Hán-Việt | y trong \"y áo\" — gần gũi, mềm mại; 漪 gợi vẻ đẹp dịu dàng, nhẹ nhàng của mặt nước phẳng lặng bị khuấy động. | Mở khoá kiến thức | Biết 漪 mở khoá: 涟漪 (gợn sóng lăn tăn), 漪澜 (sóng gợn), 清漪 (gợn nước trong).", "Tự nguyên_Xie": "漪 (yī) theo Wiktionary: ripple (on the surface of water). Bộ 氵(thủy) biểu nghĩa — nước; phần âm cho âm yī. 漪 chỉ những gợn sóng nhỏ, lăn tăn, mang vẻ đẹp tĩnh lặng, thơ mộng. Thường xuất hiện trong 涟漪 (gợn sóng liên tiếp). Chữ tạo muộn trong lịch sử chữ Hán. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sóng lăn tăn", "Hạng Tần Suất (Jun Da)": "3668.0", "Tần Suất % (Jun Da)": "99.6270310005", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 猗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵猗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "猗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漪", "Unihan_Traditional (Chữ Phồn thể)": "漪", "Pinyin_Xie": "yī", "Âm Hán Việt_Xie": "y", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường xuất hiện trong văn thơ hoặc kết hợp tạo từ ghép chỉ gợn nước lăn tăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('悻', '{"9000": "3669.0", "Chữ Trung Quốc": "悻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 悻 | hạnh | tượng hình | cáu kỉnh, bực tức | 悻 là chữ độc thể, bộ thủ 心 (tâm) gợi sắc thái tâm trạng, nhưng cấu trúc cụ thể không rõ ràng qua tài liệu hiện có. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạnh\": tâm (心) bực bội — người không được hạnh phúc thì cáu kỉnh suốt ngày. | Gương Hán-Việt | 悻 xuất hiện trong từ \"悻悻\" (hạnh hạnh) — bộ dáng bực bội, tức giận. | Mở khoá kiến thức | Biết 悻 giúp nhận ra các tính từ tâm trạng tiêu cực trong văn học cổ điển Trung Quốc.", "Tự nguyên_Xie": "Chữ 悻 không có nguồn Wiktionary glyph rõ ràng. Từ cấu trúc, phần bộ 心 gợi ý liên quan đến trạng thái tâm lý. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cáu giận", "Hạng Tần Suất (Jun Da)": "3669.0", "Tần Suất % (Jun Da)": "99.6274609657", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 幸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄幸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "幸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "悻", "Unihan_Traditional (Chữ Phồn thể)": "悻", "Pinyin_Xie": "xìng", "Âm Hán Việt_Xie": "hãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng ở dạng lặp lại hoặc kết hợp để miêu tả vẻ mặt tức giận, không vui. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹋', '{"9000": "3670.0", "Chữ Trung Quốc": "蹋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 口 | khẩu | tham khảo hình thức | thành phần của bộ 足 (𧾷) | 止 | chỉ | biểu nghĩa | bước chân, dừng lại — tạo thành bộ 足 | 日 | nhật | tham khảo hình thức | thành phần của phần biểu âm | 羽 | vũ | biểu âm | lông vũ — thành phần của 𦐇 | 蹋 = 𧾷 (bộ 足 biến thể, biểu nghĩa: chân) + 𦐇 (gồm 日+羽, biểu âm tà). Wiktionary không ghi lsCodes rõ; cấu trúc phono-semantic suy từ cấu trúc: 足 (chân) cho nghĩa, phần còn lại cho âm. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạp\": đôi chân (𧾷) giẫm mạnh xuống — đạp, giẫm; mở rộng: phá hỏng, lãng phí (糟蹋). | Gương Hán-Việt | \"đạp\" trong 糟蹋 (tao đạp — phá hoại, làm hỏng) | Mở khoá kiến thức | Biết 蹋 mở khoá 糟蹋 (phá phách, lãng phí), 蹋青 (đạp lên cỏ xanh mùa xuân).", "Tự nguyên_Xie": "Tiểu triện | Chữ 蹋 (đạp) là dạng thay thế của 踏 (đạp chân, giẫm lên). Wiktionary xác nhận đây là biến thể dị tự của 踏 (tread on, stamp). Bộ 足 (𧾷) biểu nghĩa chỉ chân; phần 𦐇 (日+羽) biểu âm tà. Tiểu triện được lưu lại. Thường gặp trong 糟蹋 (phá hoại, lãng phí). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm; đạp; đá", "Hạng Tần Suất (Jun Da)": "3670.0", "Tần Suất % (Jun Da)": "99.6278878302", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 𦐇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊𦐇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦐇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹋", "Unihan_Traditional (Chữ Phồn thể)": "蹋", "Pinyin_Xie": "tà", "Âm Hán Việt_Xie": "đạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động giẫm lên bằng chân hoặc hủy hoại, chà đạp thứ gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讪', '{"9000": "3671.0", "Chữ Trung Quốc": "讪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 5 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 山 | sơn | biểu âm | núi | 讪 = 讠(Ngôn, biểu nghĩa: lời nói) + 山 (Sơn, biểu âm). Chữ hình thanh: 讠 chỉ nghĩa liên quan đến lời nói, 山 cho âm đọc gần shàn. Đây là dạng giản thể của 訕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sán\": lời nói (讠) leo qua núi (山) — chê bai lan xa như tiếng vọng trên núi. | Gương Hán-Việt | 讪 ít dùng trong từ Hán-Việt hiện đại, thường thấy trong văn học cổ qua dạng 訕. | Mở khoá kiến thức | Biết 讪 mở khoá cụm 讪笑 (chê cười nhạo báng) và 讪讪 (ngượng ngùng lúng túng) trong văn học.", "Tự nguyên_Xie": "Tiểu triện | 讪 là dạng giản thể của 訕, thay bộ 訁 bằng 讠. Chữ hình thanh: bộ 言 (ngôn) biểu thị lời nói chê bai, phần 山 (sơn) cho âm. Nghĩa gốc là chê cười, nhạo báng bằng lời. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chê cười; quở trách", "Hạng Tần Suất (Jun Da)": "3671.0", "Tần Suất % (Jun Da)": "99.6283146947", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讪", "Unihan_Traditional (Chữ Phồn thể)": "訕", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "san, sán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ miêu tả trạng thái ngượng ngùng hoặc làm động từ chỉ việc chế giễu người khác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('搐', '{"9000": "3672.0", "Chữ Trung Quốc": "搐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 13 | nét | 搐 | súc | tượng hình | co giật, chuột rút | 搐 mang bộ 扌 (thủ — tay) gợi hành động của tay hoặc cơ thể, song cấu tạo chi tiết chưa được xác nhận qua nguồn học thuật. Đây có thể là chữ hình thanh với phần biểu nghĩa là 扌.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"súc\": bàn tay (扌) bị co rút (súc) lại — hình ảnh cơn co giật cơ bắp. | Gương Hán-Việt | súc gợi đến từ \"co súc\" — chân tay bị co rút trong cơn động kinh. | Mở khoá kiến thức | Biết 搐 giúp đọc hiểu văn bản y khoa về triệu chứng co giật (抽搐 chōuchù).", "Tự nguyên_Xie": "Chữ 搐 không có nguồn glyph Wiktionary rõ ràng. Từ ngữ cảnh, bộ 扌 (thủ) gợi động tác co rút của cơ thể. Chưa có nguồn học thuật xác nhận cấu tạo. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rút ra", "Hạng Tần Suất (Jun Da)": "3672.0", "Tần Suất % (Jun Da)": "99.6287400089", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 畜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌畜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "搐", "Unihan_Traditional (Chữ Phồn thể)": "搐", "Pinyin_Xie": "chù", "Âm Hán Việt_Xie": "súc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự co giật đột ngột của cơ bắp hoặc nét mặt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碘', '{"9000": "3673.0", "Chữ Trung Quốc": "碘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 13 | nét | 石 | thạch | biểu nghĩa | đá, khoáng chất | 典 | điển | biểu âm | 碘 = 石 (Thạch, biểu nghĩa: khoáng chất/phi kim) + 典 (Điển, biểu âm: đọc gần diǎn). Chữ hình thanh: 石 chỉ đây là nguyên tố/khoáng chất, 典 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêm\": khoáng chất (石) tên điển (典) — iốt là nguyên tố khoáng thiết yếu cho tuyến giáp. | Gương Hán-Việt | 碘 dùng trong \"碘酒\" (cồn iốt), \"碘盐\" (muối iốt) — thuật ngữ y tế và dinh dưỡng quen thuộc. | Mở khoá kiến thức | Biết 碘 giúp đọc nhãn muối iốt, thuốc sát trùng và tài liệu hoá học.", "Tự nguyên_Xie": "碘 là chữ tạo ra để phiên âm tên nguyên tố iodine (I). Chữ hình thanh: bộ 石 (thạch) biểu thị đây là khoáng chất/nguyên tố hoá học, phần 典 (điển, đọc diǎn) cho âm gần diǎn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất điển, iôt", "Hạng Tần Suất (Jun Da)": "3673.0", "Tần Suất % (Jun Da)": "99.6291653231", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 典", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石典", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "典", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碘", "Unihan_Traditional (Chữ Phồn thể)": "碘", "Pinyin_Xie": "diǎn", "Âm Hán Việt_Xie": "điển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nguyên tố hóa học i-ốt và thường đứng trước danh từ khác để làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('帛', '{"9000": "3674.0", "Chữ Trung Quốc": "帛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 巾 | Số nét | 8 | nét | 白 | bạch | biểu âm | 巾 | can | biểu nghĩa | vải, khăn | 帛 = 白 (Bạch, biểu âm: đọc gần bó) + 巾 (Can, biểu nghĩa: vải). Chữ hình thanh: 巾 chỉ đây là loại vải dệt, 白 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạch\": vải (巾) màu trắng (白) — lụa bạch là loại vải quý trong cổ đại. | Gương Hán-Việt | 帛 trong \"帛书\" (lụa thư — văn tự viết trên lụa), \"财帛\" (tiền của, của cải). | Mở khoá kiến thức | Biết 帛 mở khoá các từ về vải lụa cổ đại: 布帛 (vải vóc), 帛书 (thư viết trên lụa), 币帛 (lễ vật vải lụa).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Theo Wiktionary, 帛 là chữ hình thanh: 巾 (can — vải) biểu nghĩa, 白 (bạch) biểu âm. Nghĩa gốc là lụa, vải dệt quý. Trong giáp cốt văn và kim văn đã thấy chữ này, chỉ các loại vải lụa dùng trong lễ nghi và thương mại cổ đại. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "450.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Bạch (88) Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Bạch (số 106 - màu trắng) ở trên chữ Cân (số 50 - cái khăn) . Tấm khăn (Cân) màu trắng (Bạch) tinh khôi dệt bằng tơ tằm gọi là vải lụa (bạch). Giải thích sự chuyển ý: Chữ Bạch (màu trắng) chỉ âm, chữ Cân (khăn/vải) chỉ ý. Loại vải lụa (Cân) trắng cao cấp gọi chung là tơ lụa (Bạch).", "Nghĩa Tiếng Việt_Xie": "vải lụa", "Hạng Tần Suất (Jun Da)": "3674.0", "Tần Suất % (Jun Da)": "99.6295901204", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 巾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱白巾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "巾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "帛", "Unihan_Traditional (Chữ Phồn thể)": "帛", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại vải lụa thời xưa, thường dùng trong văn viết hoặc từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诠', '{"9000": "3675.0", "Chữ Trung Quốc": "诠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | ngôn | biểu nghĩa | lời nói, ngôn từ | 全 | toàn | biểu âm | 诠 = 讠(Ngôn, biểu nghĩa: lời nói) + 全 (Toàn, biểu âm: đọc gần quán). Chữ hình thanh, dạng giản thể của 詮: 讠 chỉ nghĩa liên quan đến lời giải thích.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thuyên\": lời (讠) trọn vẹn toàn (全) — diễn giải đầy đủ, không bỏ sót ý nào. | Gương Hán-Việt | 诠 trong \"诠释\" (thuyên thích — giải thích, chú giải), \"诠注\" (thuyên chú — ghi chú giải thích). | Mở khoá kiến thức | Biết 诠 giúp đọc hiểu các bài bình luận học thuật, chú giải kinh điển: 诠释 (giải thích), 诠注 (chú thích).", "Tự nguyên_Xie": "Tiểu triện | Lưu Thư Thông | 诠 là dạng giản thể của 詮, thay bộ 訁 bằng 讠. Chữ hình thanh: 言 (ngôn) biểu thị lời nói/giải thích, 全 (toàn) cho âm quán. Nghĩa gốc là giải thích đầy đủ, chú giải. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giải thích kỹ càng", "Hạng Tần Suất (Jun Da)": "3675.0", "Tần Suất % (Jun Da)": "99.630014401", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诠", "Unihan_Traditional (Chữ Phồn thể)": "詮", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn viết để giải thích chi tiết ý nghĩa của một khái niệm. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('碾', '{"9000": "3676.0", "Chữ Trung Quốc": "碾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 石 | Số nét | 15 | nét | 石 | thạch | biểu nghĩa | đá | 展 | triển | biểu âm | 碾 là dạng thay thế của 輾, dùng bộ 石 (thạch — đá) thay cho bộ 車 (xa — xe). Chữ hình thanh: đá (石) nghiền/cán; phần còn lại cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niễn\": hòn đá (石) lăn và nghiền — hình ảnh cối xay đá nghiền thóc lúa. | Gương Hán-Việt | 碾 trong \"碾压\" (niễn áp — cán ép, đè bẹp), \"碾碎\" (niễn toái — nghiền nát). | Mở khoá kiến thức | Biết 碾 giúp đọc hiểu văn bản nông nghiệp truyền thống và các từ chỉ nghiền, cán ép.", "Tự nguyên_Xie": "Theo Wiktionary, 碾 là dạng thay thế của 輾 — dùng bộ 石 (thạch) thay cho 車 (xa). Bộ 石 nhấn mạnh dụng cụ nghiền bằng đá (cối xay đá), phản ánh công cụ xay xát cổ truyền. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1817.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thạch (112) Triển (1816)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thạch (số 112 - hòn đá/ 石 /chỉ ý) ở bên trái chữ Triển (số 1816 - mở rộng/ 展 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Triển chỉ âm, bộ Thạch chỉ ý. Niễn là cái con lăn, cái cối xay làm bằng đá dùng để xay xát (niễn phòng). Cũng mang nghĩa là nghiền, xát (niễn mễ - xát gạo).", "Nghĩa Tiếng Việt_Xie": "con lăn (để tán thuốc); nghiền nhỏ", "Hạng Tần Suất (Jun Da)": "3676.0", "Tần Suất % (Jun Da)": "99.6304381649", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 展", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰石展", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "展", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "碾", "Unihan_Traditional (Chữ Phồn thể)": "碾", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ hành động nghiền nát bằng con lăn hoặc làm danh từ chỉ cối xay đá. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擂', '{"9000": "3677.0", "Chữ Trung Quốc": "擂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 手 | thủ | biểu nghĩa | tay | 雷 | lôi | biểu âm | 擂 = 手 (Thủ, biểu nghĩa: tay) + 雷 (Lôi, biểu âm: đọc gần léi). Chữ hình thanh: bàn tay (手) đánh liên hồi như sấm (雷).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lôi\": tay (手) đánh mạnh như sấm (雷) — tiếng trống vang như tiếng sấm rền. | Gương Hán-Việt | 擂 trong \"擂台\" (lôi đài — đài đấu võ), \"擂鼓\" (lôi cổ — đánh trống). | Mở khoá kiến thức | Biết 擂 mở khoá từ về võ thuật và biểu diễn: 擂台 (đài đấu), 擂鼓 (đánh trống), 打擂 (thi đấu).", "Tự nguyên_Xie": "Theo Wiktionary, 擂 là chữ hình thanh: 手 (thủ — tay) biểu nghĩa, 雷 (lôi — sấm) biểu âm. Nghĩa gốc là đánh trống liên hồi, sau mở rộng sang đấm đá, thi đấu võ thuật. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đập, đánh; nghiền", "Hạng Tần Suất (Jun Da)": "3677.0", "Tần Suất % (Jun Da)": "99.6308614119", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 雷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌雷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擂", "Unihan_Traditional (Chữ Phồn thể)": "擂", "Pinyin_Xie": "léi", "Âm Hán Việt_Xie": "lỗi, lôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ chỉ nhạc cụ hoặc vật liệu để diễn tả hành động đánh hoặc nghiền. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苯', '{"9000": "3678.0", "Chữ Trung Quốc": "苯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 本 | bản | biểu âm | 苯 = 艹 (Thảo, biểu nghĩa: hữu cơ/thực vật) + 本 (Bản, biểu âm: đọc gần běn). Chữ hình thanh tạo ra để phiên âm benzene — hợp chất hữu cơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bản\": cỏ (艹) gốc (本) — benzen là nền tảng (bản) của hoá học hữu cơ thơm. | Gương Hán-Việt | 苯 trong \"苯环\" (bản hoàn — vòng benzen), \"苯酚\" (bản phân — phenol), \"苯胺\" (bản amine — aniline). | Mở khoá kiến thức | Biết 苯 giúp đọc tài liệu hoá học hữu cơ: 苯环 (vòng benzen), 苯系物 (dẫn xuất benzen).", "Tự nguyên_Xie": "苯 là chữ tạo ra trong thời cận đại để đặt tên cho benzene (benzen). Chữ hình thanh: bộ 艹 (thảo) gợi tính chất hữu cơ, 本 (bản) cho âm đọc gần běn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chất benzen (công thức hoá học: C6H6)", "Hạng Tần Suất (Jun Da)": "3678.0", "Tần Suất % (Jun Da)": "99.6312831086", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 本", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹本", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "本", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苯", "Unihan_Traditional (Chữ Phồn thể)": "苯", "Pinyin_Xie": "běn", "Âm Hán Việt_Xie": "bản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ trong hóa học để chỉ hợp chất benzen hoặc cấu trúc vòng benzen. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诃', '{"9000": "3679.0", "Chữ Trung Quốc": "诃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 7 | nét | 讠 | ngôn | biểu nghĩa | lời nói | 可 | khả | biểu âm | 诃 = 讠(Ngôn, biểu nghĩa: lời nói) + 可 (Khả, biểu âm: đọc gần hē). Chữ hình thanh, dạng giản thể của 訶: dùng lời nói quở trách.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ha\": lời (讠) được phép (可) nói thẳng — quở trách thẳng thắn, không úp mở. | Gương Hán-Việt | 诃 trong \"诃斥\" (ha xích — quở trách, mắng mỏ), ít dùng trong tiếng Việt hiện đại. | Mở khoá kiến thức | Biết 诃 giúp đọc văn học cổ điển và kinh Phật dịch (诃梨勒 — cây chiêu liêu).", "Tự nguyên_Xie": "Kim văn | 诃 là dạng giản thể của 訶, thay bộ 訁 bằng 讠. Chữ hình thanh: 言 (ngôn) biểu nghĩa liên quan lời quở trách, 可 (khả) cho âm. Kim văn đã có dạng 訶. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quát mắng", "Hạng Tần Suất (Jun Da)": "3679.0", "Tần Suất % (Jun Da)": "99.6317037716", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诃", "Unihan_Traditional (Chữ Phồn thể)": "訶", "Pinyin_Xie": "hē", "Âm Hán Việt_Xie": "ha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn ngôn hoặc kết hợp thành từ ghép để chỉ hành động quở trách. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铎', '{"9000": "3680.0", "Chữ Trung Quốc": "铎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 铎 | đạc | tượng hình | chuông lớn có lưỡi | 铎 là dạng giản thể của 鐸, thay bộ 釒 bằng 钅 và giản hoá phần còn lại. Chữ gốc chỉ loại chuông lớn cán dài dùng trong nghi lễ. Cấu tạo chi tiết của dạng giản thể không còn rõ hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạc\": chuông đạc vang lên truyền lệnh — kim văn đã khắc hình cái chuông lớn này. | Gương Hán-Việt | 铎 trong \"木铎\" (mộc đạc — chuông gỗ của thầy giáo), biểu tượng giáo dục truyền thống. | Mở khoá kiến thức | Biết 铎 mở khoá từ văn hoá: 木铎 (chuông gỗ — biểu tượng giảng dạy), 铎声 (tiếng chuông đạc).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | 铎 là dạng giản thể của 鐸 (đạc). Trong kim văn, 鐸 mô tả loại chuông lớn có cán, dùng để truyền lệnh hoặc tổ chức nghi lễ thời cổ đại. Chữ tạo muộn theo dạng giản lược. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chuông lắc", "Hạng Tần Suất (Jun Da)": "3680.0", "Tần Suất % (Jun Da)": "99.632123918", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "铎", "Unihan_Traditional (Chữ Phồn thể)": "鐸", "Pinyin_Xie": "duó", "Âm Hán Việt_Xie": "đạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ cổ hoặc dùng trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戊', '{"9000": "3681.0", "Chữ Trung Quốc": "戊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 5 | nét | 戊 | mậu | tượng hình | cây kích, vũ khí cán dài | 戊 là chữ tượng hình độc thể, mô phỏng hình cây kích (halberd) — loại vũ khí cán dài thời cổ đại. Trong giáp cốt văn đã thấy dạng này rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mậu\": hình cây kích (戊) — can thứ năm Mậu, năm Mậu Tuất có hình ảnh vũ khí cổ đại. | Gương Hán-Việt | mậu trong \"Mậu Tuất\" (戊戌) — năm lịch sử cải cách Mậu Tuất 1898 và can chi Thiên Can. | Mở khoá kiến thức | Biết 戊 mở khoá hệ thống Thiên Can: 戊戌 (Mậu Tuất), 戊子 (Mậu Tý) — dùng trong lịch âm và lịch sử.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Tiểu triện | Theo Wiktionary, 戊 ({{liushu|p}}) là chữ tượng hình mô tả cây kích. Về sau được mượn dùng làm can thứ năm trong Thiên Can (Giáp, Ất, Bính, Đinh, Mậu...). Giáp cốt văn và kim văn đều thể hiện hình vũ khí. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "936.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Qua (084) Phiệt (004)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Phẩy (số 004) chèn vào bên cạnh bộ Qua (số 084 - vũ khí). Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Mậu là tên loại vũ khí thời cổ. Sau được dùng làm một trong 10 Thiên can (can Mậu).", "Nghĩa Tiếng Việt_Xie": "Mậu (ngôi thứ 5 hàng Can)", "Hạng Tần Suất (Jun Da)": "3681.0", "Tần Suất % (Jun Da)": "99.6325430307", "GavinGrover_Once (Chiết tự trực tiếp)": "厂 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰厂戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "厂", "Unihan_Simplified (Chữ Giản thể)": "戊", "Unihan_Traditional (Chữ Phồn thể)": "戊", "Pinyin_Xie": "wù", "Âm Hán Việt_Xie": "mậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Số từ | 数词 | Chữ này làm danh từ chỉ thiên can thứ năm hoặc dùng như số từ chỉ thứ tự trong các văn bản cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荀', '{"9000": "3682.0", "Chữ Trung Quốc": "荀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荀 | tuân | tượng hình | họ người, tên cổ | 荀 mang bộ 艹 (thảo) gợi hoa cỏ, nhưng chức năng chính là họ người và tên địa danh cổ. Cấu tạo chi tiết chưa được xác nhận rõ qua nguồn học thuật về hình thanh/hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuân\": họ Tuân nổi tiếng với Tuân Tử (荀子) — nhà Nho lớn đặt nền tảng lý thuyết tuân theo lễ pháp. | Gương Hán-Việt | 荀 chủ yếu là họ: Tuân Tử (荀子), Tuân Vực (荀彧 — mưu sĩ thời Tam Quốc). | Mở khoá kiến thức | Biết 荀 giúp nhận ra các nhân vật lịch sử họ Tuân: 荀子 (Tuân Tử), 荀彧 (Tuân Vực).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 荀 dùng chủ yếu làm họ người (ví dụ Tuân Tử — 荀子, triết gia Nho gia lớn thời Chiến Quốc) và tên nước cổ đại. Đại triện và tiểu triện đã có chữ này. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Tuân; họ Tuân; cỏ tuân", "Hạng Tần Suất (Jun Da)": "3682.0", "Tần Suất % (Jun Da)": "99.6329621435", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荀", "Unihan_Traditional (Chữ Phồn thể)": "荀", "Pinyin_Xie": "xún", "Âm Hán Việt_Xie": "tuân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng chỉ họ người hoặc tên nước thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('驹', '{"9000": "3683.0", "Chữ Trung Quốc": "驹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 8 | nét | 马 | mã | biểu nghĩa | ngựa | 句 | cú | biểu âm | 驹 = 马 (Mã, biểu nghĩa: ngựa) + 句 (Cú, biểu âm: đọc gần jū). Chữ hình thanh, dạng giản thể của 駒: 马 chỉ đây là loài ngựa, 句 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"câu\": ngựa (马) còn trẻ như câu chữ (句) ngắn — ngựa câu là ngựa tơ chưa thuần. | Gương Hán-Việt | 驹 trong \"千里驹\" (thiên lý câu — ngựa chạy nghìn dặm), \"白驹\" (bạch câu — ngựa trắng). | Mở khoá kiến thức | Biết 驹 mở khoá thành ngữ: 白驹过隙 (bạch câu qua kẽ — thời gian trôi nhanh), 千里驹 (ngựa tài năng).", "Tự nguyên_Xie": "Kim văn | Bạch thư | Đại triện | Tiểu triện | 驹 là dạng giản thể của 駒 (câu), thay bộ 馬 bằng 马. Chữ hình thanh: 馬 (mã) biểu nghĩa — ngựa, 句 biểu âm. Nghĩa gốc là ngựa non, ngựa tơ. Kim văn đã có dạng 駒. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa non; khoẻ", "Hạng Tần Suất (Jun Da)": "3683.0", "Tần Suất % (Jun Da)": "99.6333807394", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 句", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马句", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "句", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "驹", "Unihan_Traditional (Chữ Phồn thể)": "駒", "Pinyin_Xie": "jū", "Âm Hán Việt_Xie": "câu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ đứng độc lập hoặc kết hợp để chỉ ngựa con hoặc những người trẻ tuổi tài cao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攫', '{"9000": "3684.0", "Chữ Trung Quốc": "攫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 23 | nét | 扌 | thủ | biểu nghĩa | tay | 矍 | quắc | biểu âm | 攫 = 扌 (Thủ, biểu nghĩa: tay) + 矍 (Quắc, biểu âm: đọc gần jué). Chữ hình thanh: bàn tay (扌) chộp/vồ nhanh, 矍 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quặc\": tay (扌) quắc (矍) chộp mồi — hình ảnh chim ưng vồ con mồi. | Gương Hán-Việt | 攫 trong \"攫取\" (quặc thủ — chiếm đoạt, vơ vét), \"攫夺\" (quặc đoạt — cướp giật). | Mở khoá kiến thức | Biết 攫 giúp đọc văn học cổ điển và văn chính trị: 攫取利益 (vơ vét lợi ích), 攫夺资源 (cướp tài nguyên).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 攫 là chữ hình thanh: bộ 扌 (thủ — tay) biểu nghĩa hành động tay, 矍 cho âm jué. Nghĩa gốc là chộp, vồ, chụp lấy bằng tay — như móng vuốt chim ưng cắp mồi. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1578.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủ (064) Quắc (1577)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủ (số 064 - cái tay/ 扌/chỉ ý) ở bên trái chữ Quắc (số 1577 - hoảng sợ/ 矍 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Quắc chỉ âm, bộ Thủ chỉ ý. Quặc là lấy tay vồ lấy, chộp lấy, giành giật lấy (quặc thủ).", "Nghĩa Tiếng Việt_Xie": "vồ lấy", "Hạng Tần Suất (Jun Da)": "3684.0", "Tần Suất % (Jun Da)": "99.6337993354", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 矍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌矍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "矍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攫", "Unihan_Traditional (Chữ Phồn thể)": "攫", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quặc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ để diễn tả hành động vồ lấy hoặc chiếm đoạt một cách nhanh chóng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憬', '{"9000": "3685.0", "Chữ Trung Quốc": "憬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 忄 | tâm | biểu nghĩa | tâm, lòng | 景 | cảnh | biểu âm | 憬 = 忄 (Tâm, biểu nghĩa: lòng/tâm trí) + 景 (Cảnh, biểu âm: đọc gần jǐng). Chữ hình thanh: 忄 chỉ trạng thái tâm lý — bừng tỉnh nhận ra, 景 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cảnh\": lòng (忄) nhìn thấy cảnh vật (景) — bừng tỉnh trước một khung cảnh đẹp hay sự thật. | Gương Hán-Việt | 憬 trong \"憧憬\" (đồng cảnh — ao ước, mơ về tương lai), từ phổ biến trong văn học hiện đại. | Mở khoá kiến thức | Biết 憬 mở khoá từ 憧憬 (ao ước, hướng tới) — rất phổ biến trong văn học và bài hát.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (Digital Shinjigen 2017), 憬 là chữ hình thanh: bộ 忄 (tâm) biểu nghĩa trạng thái tâm lý bừng tỉnh, 景 (cảnh) biểu âm. Nghĩa gốc là nhận ra, tỉnh ngộ; về sau dùng trong \"憬憬\" chỉ sự ngây thơ hay tỉnh thức. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hiểu biết, tỉnh ngộ", "Hạng Tần Suất (Jun Da)": "3685.0", "Tần Suất % (Jun Da)": "99.6342174145", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 景", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄景", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "景", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "憬", "Unihan_Traditional (Chữ Phồn thể)": "憬", "Pinyin_Xie": "jǐng", "Âm Hán Việt_Xie": "cảnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường kết hợp với các từ khác để biểu thị sự thức tỉnh hoặc hướng tới tương lai. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哽', '{"9000": "3686.0", "Chữ Trung Quốc": "哽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng | 更 | canh | biểu âm | 哽 = 口 (Khẩu, biểu nghĩa: miệng/cổ họng) + 更 (Canh, biểu âm: đọc gần gěng). Chữ hình thanh: 口 chỉ hành động ở cổ họng — nghẹn ngào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạnh\": miệng (口) cứng ngạnh (更) — cổ họng nghẹn lại không nói được vì xúc động. | Gương Hán-Việt | 哽 trong \"哽咽\" (ngạnh yết — nghẹn ngào, khóc không thành tiếng). | Mở khoá kiến thức | Biết 哽 giúp đọc văn miêu tả cảm xúc: 哽咽 (nghẹn ngào), 哽住了 (nghẹn lại).", "Tự nguyên_Xie": "Tiểu triện | 哽 là chữ hình thanh: bộ 口 (khẩu — miệng) biểu nghĩa liên quan đến cổ họng và giọng nói, 更 (canh) cho âm. Nghĩa gốc là nuốt mạnh, bị tắc nghẹn, sau mở rộng sang nghẹn ngào vì xúc động. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghẹn, tắc", "Hạng Tần Suất (Jun Da)": "3686.0", "Tần Suất % (Jun Da)": "99.6346334266", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 更", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口更", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "更", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哽", "Unihan_Traditional (Chữ Phồn thể)": "哽", "Pinyin_Xie": "gěng", "Âm Hán Việt_Xie": "ngạnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ miêu tả trạng thái nghẹn ngào không nói nên lời do xúc động. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踵', '{"9000": "3687.0", "Chữ Trung Quốc": "踵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 足 | túc | biểu nghĩa | chân | 重 | trọng | biểu âm | 踵 = 足 (Túc, biểu nghĩa: chân) + 重 (Trọng, biểu âm: đọc gần zhǒng). Chữ hình thanh: 足 chỉ đây là phần của chân — gót chân; 重 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chủng\": chân (足) nặng (重) đi từng bước — gót chân phải chịu toàn bộ trọng lượng cơ thể. | Gương Hán-Việt | 踵 trong \"接踵\" (tiếp chủng — liên tiếp, đến từng đoàn), \"摩肩接踵\" (chen chúc đông đúc). | Mở khoá kiến thức | Biết 踵 mở khoá thành ngữ 摩肩接踵 (cọ vai tiếp gót — đám đông chen chúc) và 接踵而至 (liên tiếp kéo đến).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 踵 là chữ hình thanh: 足 (túc — chân) biểu nghĩa, 重 (trọng) biểu âm. Nghĩa gốc là gót chân. Sau mở rộng sang nghĩa đi theo, kế tiếp nhau (như gót bước theo gót). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gót chân; đến nơi; nối gót nhau đi", "Hạng Tần Suất (Jun Da)": "3687.0", "Tần Suất % (Jun Da)": "99.6350494386", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 重", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊重", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "重", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踵", "Unihan_Traditional (Chữ Phồn thể)": "踵", "Pinyin_Xie": "zhǒng", "Âm Hán Việt_Xie": "chủng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ gót chân hoặc làm động từ biểu thị hành động đi theo sau, nối gót. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟒', '{"9000": "3688.0", "Chữ Trung Quốc": "蟒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng, bò sát | 莽 | mãng | biểu âm | 蟒 = 虫 (Trùng, biểu nghĩa: bò sát/côn trùng) + 莽 (Mãng, biểu âm: đọc gần mǎng). Chữ hình thanh: 虫 chỉ đây là loài bò sát, 莽 cho âm. Chưa có nguồn học thuật xác nhận chi tiết cấu tạo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãng\": con trùng (虫) khổng lồ mãng mãng — trăn mãng xà cuộn mình trong rừng rậm. | Gương Hán-Việt | mãng trong \"mãng xà\" (蟒蛇 — trăn lớn), từ Hán-Việt quen thuộc trong truyện cổ và phim. | Mở khoá kiến thức | Biết 蟒 mở khoá từ 蟒蛇 (trăn lớn), 蟒袍 (áo rồng — trang phục hoàng cung có hoa văn trăn).", "Tự nguyên_Xie": "蟒 là chữ hình thanh chỉ loài trăn lớn (python/boa). Bộ 虫 (trùng) biểu nghĩa là bò sát, phần còn lại cho âm gần mǎng. Chưa có nguồn Wiktionary glyph chi tiết. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con trăn", "Hạng Tần Suất (Jun Da)": "3688.0", "Tần Suất % (Jun Da)": "99.6354649339", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 莽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫莽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟒", "Unihan_Traditional (Chữ Phồn thể)": "蟒", "Pinyin_Xie": "mǎng", "Âm Hán Việt_Xie": "mãng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài trăn lớn hoặc dùng trong các từ ghép chỉ trang phục thêu hình rồng trăn thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漾', '{"9000": "3689.0", "Chữ Trung Quốc": "漾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 水 | thủy | biểu nghĩa | nước | 羕 | biểu âm | 漾 = 水 (Thủy, biểu nghĩa: nước) + 羕 (biểu âm: đọc gần yàng). Chữ hình thanh: 水 chỉ đây là hiện tượng mặt nước, 羕 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dạng\": nước (水) lan ra từng vòng — mặt hồ gợn dạng sóng nhẹ nhàng. | Gương Hán-Việt | 漾 trong \"荡漾\" (đãng dạng — gợn sóng, dao động), \"飘漾\" (phiêu dạng — trôi nổi). | Mở khoá kiến thức | Biết 漾 mở khoá từ thơ văn: 荡漾 (gợn sóng), 漾漾 (lăn tăn sóng nước).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 漾 là chữ hình thanh: 水 (thủy) biểu nghĩa, 羕 biểu âm. Nghĩa gốc là sóng gợn, nước lan toả. Kim văn đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Dạng; nước sóng sánh", "Hạng Tần Suất (Jun Da)": "3689.0", "Tần Suất % (Jun Da)": "99.6358799123", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 羕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵羕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漾", "Unihan_Traditional (Chữ Phồn thể)": "漾", "Pinyin_Xie": "yàng", "Âm Hán Việt_Xie": "dạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ biểu thị trạng thái nước gợn sóng hoặc cảm xúc dâng trào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啧', '{"9000": "3690.0", "Chữ Trung Quốc": "啧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 責 | trách | biểu âm | 啧 = 口 (Khẩu, biểu nghĩa: miệng) + 責 (Trách, biểu âm: đọc gần zé). Chữ hình thanh: 口 chỉ âm thanh phát ra từ miệng — tiếng tặc lưỡi hoặc tiếng kêu trách móc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trách\": miệng (口) trách móc (責) — tiếng tặc lưỡi biểu hiện thán phục hay chê bai. | Gương Hán-Việt | 啧 trong \"啧啧\" (trách trách — tặc lưỡi), \"啧啧称赞\" (tặc lưỡi thán phục). | Mở khoá kiến thức | Biết 啧 giúp đọc văn miêu tả cảm xúc: 啧啧 (tặc lưỡi), 啧啧称赞 (tấm tắc khen ngợi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 啧 là chữ hình thanh: 口 (khẩu — miệng) biểu nghĩa, 責 (trách) biểu âm. Nghĩa gốc là tranh luận, cãi nhau; cũng là thán từ tặc lưỡi (tsk-tsk) thể hiện sự tán thưởng hoặc ngạc nhiên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cãi nhau", "Hạng Tần Suất (Jun Da)": "3690.0", "Tần Suất % (Jun Da)": "99.636294374", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啧", "Unihan_Traditional (Chữ Phồn thể)": "嘖", "Pinyin_Xie": "zé", "Âm Hán Việt_Xie": "trách", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Từ tượng thanh | 象声词 | Thường dùng làm động từ mô tả tiếng tặc lưỡi khen ngợi hoặc cảm thán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('吮', '{"9000": "3691.0", "Chữ Trung Quốc": "吮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng | 允 | doãn | biểu âm | 吮 = 口 (Khẩu, biểu nghĩa: miệng) + 允 (Doãn, biểu âm: đọc gần shǔn). Chữ hình thanh: 口 chỉ hành động miệng — mút, hút; 允 cho âm. Chưa có glyph Wiktionary chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"duẫn\": miệng (口) mút nhẹ nhàng — em bé mút tay là hình ảnh điển hình của 吮. | Gương Hán-Việt | 吮 trong \"吮吸\" (duẫn hấp — mút hút), \"吮指\" (mút ngón tay). | Mở khoá kiến thức | Biết 吮 giúp đọc mô tả hành động miệng: 吮吸 (mút hút), 吮血 (mút máu — thủ pháp y học cổ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 吮 là chữ hình thanh: 口 (khẩu) biểu nghĩa hành động miệng — mút, hút; phần còn lại cho âm. Đại triện và tiểu triện đã có dạng này. Nghĩa gốc là mút, hút bằng miệng. Chưa có nguồn học thuật xác nhận đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mút, hút", "Hạng Tần Suất (Jun Da)": "3691.0", "Tần Suất % (Jun Da)": "99.6367078021", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 允", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口允", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "允", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "吮", "Unihan_Traditional (Chữ Phồn thể)": "吮", "Pinyin_Xie": "shǔn", "Âm Hán Việt_Xie": "duyện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ vật được mút hoặc hút. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楠', '{"9000": "3692.0", "Chữ Trung Quốc": "楠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 南 | nam | biểu âm | 楠 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 南 (Nam, biểu âm: đọc gần nán). Chữ hình thanh, tục tự từ 枏: 木 chỉ đây là loài cây, 南 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nêm\": cây (木) phương nam (南) — gỗ楠 mọc ở phương nam, là loại gỗ hoàng gia quý hiếm. | Gương Hán-Việt | 楠 trong \"楠木\" (nêm mộc — gỗ nam mộc quý), dùng làm cột điện cung đình. | Mở khoá kiến thức | Biết 楠 giúp đọc sử liệu kiến trúc: 楠木 (gỗ nam mộc — vật liệu xây cung đình), 香楠 (gỗ楠 thơm).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 楠 là tục tự (dạng thông tục) từ 枏, cấu tạo hình thanh: 木 (mộc — gỗ) biểu nghĩa, 南 (nam) biểu âm. Chỉ cây nam mộc (nanmu) — loài gỗ quý dùng trong cung điện hoàng gia. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây nam, cây chò", "Hạng Tần Suất (Jun Da)": "3692.0", "Tần Suất % (Jun Da)": "99.6371212302", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 南", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木南", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "南", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楠", "Unihan_Traditional (Chữ Phồn thể)": "枏", "Pinyin_Xie": "nán", "Âm Hán Việt_Xie": "nam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loại cây hoặc loại gỗ nam quý hiếm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氟', '{"9000": "3693.0", "Chữ Trung Quốc": "氟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 9 | nét | 气 | khí | biểu nghĩa | khí, chất khí | 弗 | phất | biểu âm | 氟 = 气 (Khí, biểu nghĩa: chất khí) + 弗 (Phất, biểu âm: đọc gần fú). Chữ hình thanh tạo ra để đặt tên nguyên tố fluorine: 气 chỉ đây là khí phi kim, 弗 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phất\": khí (气) phất phơ — flo là khí độc màu vàng lợt, phất trong không khí nguy hiểm. | Gương Hán-Việt | 氟 trong \"氟化物\" (phất hoá vật — fluoride), \"氟利昂\" (freon), \"氟化钙\" (calcium fluoride). | Mở khoá kiến thức | Biết 氟 giúp đọc tài liệu hoá học và nha khoa: 氟化物 (fluoride), 含氟牙膏 (kem đánh răng chứa fluor).", "Tự nguyên_Xie": "氟 là chữ tạo trong thời cận đại để phiên âm fluorine (F). Chữ hình thanh: 气 (khí) biểu nghĩa — nguyên tố ở dạng khí, 弗 (phất) cho âm fú. Ghi chú: từ điển gốc tiếng Trung không có âm đọc cổ cho 弗 trong ngữ cảnh này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố flo, khí flo, F", "Hạng Tần Suất (Jun Da)": "3693.0", "Tần Suất % (Jun Da)": "99.6375346583", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 弗", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气弗", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氟", "Unihan_Traditional (Chữ Phồn thể)": "氟", "Pinyin_Xie": "fú", "Âm Hán Việt_Xie": "phất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong các thuật ngữ hóa học và công nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('怂', '{"9000": "3694.0", "Chữ Trung Quốc": "怂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 8 | nét | 从 | tùng | biểu nghĩa | theo đuôi, nghe lời | 心 | tâm | biểu nghĩa | lòng | 怂 là dạng giản thể của 慫, thay bộ 從 bằng 从. Cấu tạo gốc: 從 (tùng — đi theo) + 心 (tâm) — hội ý: lòng cứ đi theo người khác, không dám tự quyết — nhút nhát. Chữ hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tủng\": lòng (心) cứ theo (从) người — tủng tiêng là nhút nhát, sợ hãi không dám đứng ra. | Gương Hán-Việt | 怂 trong \"怂恿\" (tủng dũng — xúi giục, kích động), \"胆怂\" (nhát gan, hèn nhát). | Mở khoá kiến thức | Biết 怂 mở khoá từ 怂恿 (xúi bẩy, kích động) — thường dùng trong văn nói và văn học đương đại.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 怂 là dạng giản thể của 慫. Chữ gốc 慫 cấu tạo hội ý: 從 (tùng — đi theo) + 心 (tâm — lòng). Hàm ý: lòng (tâm) cứ đi theo (tùng) người khác — nhút nhát, không dám tự quyết. Sau mở rộng sang \"煽动\" (xúi giục, kích động). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyên, giục, thúc", "Hạng Tần Suất (Jun Da)": "3694.0", "Tần Suất % (Jun Da)": "99.6379475696", "GavinGrover_Once (Chiết tự trực tiếp)": "从 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱从心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "从", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "怂", "Unihan_Traditional (Chữ Phồn thể)": "慫", "Pinyin_Xie": "sǒng", "Âm Hán Việt_Xie": "túng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ mang tân ngữ với nghĩa xúi giục hoặc làm tính từ chỉ sự hèn nhát. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叼', '{"9000": "3695.0", "Chữ Trung Quốc": "叼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 5 | nét | 口 | khẩu | biểu nghĩa | miệng | 刁 | điêu | biểu âm | xảo quyệt | 叼 = 口 (Khẩu, biểu nghĩa: miệng) + 刁 (Điêu, biểu âm). Wiktionary không có glyphOrigin cho chữ này. Cấu trúc phono-semantic hợp lý: 口 chỉ hành động miệng (ngậm), 刁 gợi âm diāo. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điêu\": cái miệng (口) của con chim điêu (刁) đang ngậm chặt mồi — hành động ngậm, tha bằng mõm. | Gương Hán-Việt | \"điêu\" ít dùng trong tiếng Việt hiện đại; 叼 chủ yếu dùng trong văn miêu tả | Mở khoá kiến thức | Biết 叼 giúp mô tả hành động ngậm (chim, thú, người ngậm thuốc).", "Tự nguyên_Xie": "Chữ 叼 (điêu) gồm bộ 口 (Khẩu — miệng) biểu nghĩa và 刁 (Điêu) biểu âm. Không có glyphOrigin trong Wiktionary — đây là chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. Nghĩa gốc: ngậm trong miệng, cắp bằng mồm. Chưa có nguồn học thuật xác nhận ls. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngậm; tha, cắp bằng mồm", "Hạng Tần Suất (Jun Da)": "3695.0", "Tần Suất % (Jun Da)": "99.6383594474", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 刁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口刁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "刁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "叼", "Unihan_Traditional (Chữ Phồn thể)": "叼", "Pinyin_Xie": "diāo", "Âm Hán Việt_Xie": "điêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động dùng răng hoặc mỏ để giữ vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | diāo | / | ngậm | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ | New HSK | New HSK 7-9 | · | Words II", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('竣', '{"9000": "3696.0", "Chữ Trung Quốc": "竣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 立 | Số nét | 12 | nét | 立 | lập | biểu nghĩa | đứng, hoàn thành | 夋 | tuấn | biểu âm | 竣 = 立 (Lập, biểu nghĩa: đứng vững, hoàn thành) + 夋 (biểu âm: đọc gần jùn). Chữ hình thanh: 立 gợi ý công trình đứng vững hoàn chỉnh, 夋 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuấn\": lập (立) vững — công trình đứng thẳng hoàn tất là 竣công. | Gương Hán-Việt | 竣 trong \"竣工\" (tuấn công — hoàn thành công trình), \"竣事\" (tuấn sự — hoàn tất việc). | Mở khoá kiến thức | Biết 竣 giúp đọc thông báo xây dựng: 竣工 (hoàn công), 竣工验收 (nghiệm thu hoàn công).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 竣 là chữ hình thanh: 立 (lập — đứng vững) biểu nghĩa, 夋 biểu âm. Nghĩa gốc là hoàn thành, kết thúc — thường dùng với công trình xây dựng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thôi, xong việc", "Hạng Tần Suất (Jun Da)": "3696.0", "Tần Suất % (Jun Da)": "99.6387697748", "GavinGrover_Once (Chiết tự trực tiếp)": "立 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰立夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "立", "Unihan_Simplified (Chữ Giản thể)": "竣", "Unihan_Traditional (Chữ Phồn thể)": "竣", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "thuân, thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với công trình hoặc công việc để chỉ sự hoàn thành. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偕', '{"9000": "3697.0", "Chữ Trung Quốc": "偕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 人 | nhân | biểu nghĩa | người | 皆 | giai | biểu âm | 偕 = 人 (Nhân, biểu nghĩa: người) + 皆 (Giai, biểu âm: đọc gần xié). Chữ hình thanh: 人 chỉ đây là hành động của người — cùng nhau; 皆 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giai\": người (人) cùng nhau (皆) — giai nhân đi sóng đôi, cùng tiến cùng lui. | Gương Hán-Việt | 偕 trong \"偕同\" (giai đồng — cùng đi), \"偕老\" (giai lão — cùng nhau đến già), \"白头偕老\" (đầu bạc giai lão). | Mở khoá kiến thức | Biết 偕 mở khoá từ ngữ hôn nhân: 白头偕老 (đầu bạc giai lão — sống đến già cùng nhau).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 偕 là chữ hình thanh: 人 (nhân — người) biểu nghĩa, 皆 (giai) biểu âm. Nghĩa gốc là cùng nhau, đi đôi. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đều, cùng", "Hạng Tần Suất (Jun Da)": "3697.0", "Tần Suất % (Jun Da)": "99.6391801022", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 皆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻皆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偕", "Unihan_Traditional (Chữ Phồn thể)": "偕", "Pinyin_Xie": "xié", "Âm Hán Việt_Xie": "giai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước động từ để chỉ hành động cùng nhau thực hiện. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漩', '{"9000": "3698.0", "Chữ Trung Quốc": "漩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 氵 | thủy | biểu nghĩa | nước | 旋 | toàn | biểu âm | xoay | 漩 = 氵 (Thủy, biểu nghĩa: nước) + 旋 (Toàn, biểu âm: đọc gần xuán). Chữ hình thanh: 氵 chỉ đây là hiện tượng nước, 旋 (xoay) cho âm — gợi cả nghĩa nước xoay tròn. Chưa có glyph Wiktionary chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toàn\": nước (氵) xoay toàn (旋) vòng — xoáy nước hút mọi thứ vào giữa. | Gương Hán-Việt | 漩 trong \"漩涡\" (toàn oa — xoáy nước, vòng xoáy), \"陷入漩涡\" (sa vào vòng xoáy). | Mở khoá kiến thức | Biết 漩 giúp đọc mô tả thiên nhiên và ẩn dụ: 漩涡 (xoáy nước), 政治漩涡 (vòng xoáy chính trị).", "Tự nguyên_Xie": "Lục thư thông | 漩 là chữ hình thanh: bộ 氵 (thủy) biểu nghĩa, 旋 cho âm. Nghĩa gốc là xoáy nước, dòng nước chảy xoáy tròn. Chưa có nguồn học thuật xác nhận đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước xoáy", "Hạng Tần Suất (Jun Da)": "3698.0", "Tần Suất % (Jun Da)": "99.6395904296", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 旋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵旋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漩", "Unihan_Traditional (Chữ Phồn thể)": "漩", "Pinyin_Xie": "xuán", "Âm Hán Việt_Xie": "tuyền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ dòng nước xoáy hoặc động từ chỉ chuyển động xoay tròn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹭', '{"9000": "3699.0", "Chữ Trung Quốc": "蹭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 足 | túc | biểu nghĩa | chân | 曾 | tằng | biểu âm | 蹭 = 足 (Túc, biểu nghĩa: chân) + 曾 (Tằng, biểu âm: đọc gần cèng). Chữ hình thanh: 足 chỉ hành động của chân — cọ quẹt, đi lê; 曾 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tằng\": chân (足) cọ từng (曾) bước — lê la từng bữa ăn nhờ nhà người khác. | Gương Hán-Việt | 蹭 trong \"蹭饭\" (tằng phạn — ăn chực), \"蹭蹭\" (cọ quẹt). | Mở khoá kiến thức | Biết 蹭 giúp hiểu tiếng lóng đương đại: 蹭饭 (ăn chực), 蹭课 (nghe chui lớp học), 蹭网 (xài wifi chùa).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 蹭 là chữ hình thanh: 足 (túc — chân) biểu nghĩa, 曾 (tằng) biểu âm. Nghĩa gốc là cọ chân, đi lê thê. Nghĩa mở rộng (tiếng lóng): ăn chực, xin xỏ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bước từ từ; cọ xát", "Hạng Tần Suất (Jun Da)": "3699.0", "Tần Suất % (Jun Da)": "99.6400002402", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 曾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊曾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹭", "Unihan_Traditional (Chữ Phồn thể)": "蹭", "Pinyin_Xie": "cèng", "Âm Hán Việt_Xie": "thặng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động cọ xát bề mặt hoặc hưởng lợi từ người khác. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | cèng | / | xin xỏ | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Động từ tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翌', '{"9000": "3700.0", "Chữ Trung Quốc": "翌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 11 | nét | 羽 | vu | biểu âm | 昱 | dục | biểu nghĩa | ánh sáng ngày mai | 翌 = 羽 (Vu, biểu âm: đọc gần yì) + 昱 (biểu nghĩa: ánh sáng ngày — chỉ ngày tiếp theo). Chữ hình thanh: 昱 gợi ý ánh sáng của ngày hôm sau, 羽 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dực\": cánh (羽) đưa sang ngày mai (昱) — sáng mai ánh nắng mới lên, đó là 翌日. | Gương Hán-Việt | 翌 trong \"翌日\" (dực nhật — ngày hôm sau), \"翌年\" (dực niên — năm sau). | Mở khoá kiến thức | Biết 翌 giúp đọc văn bản trang trọng và lịch sử: 翌日 (ngày hôm sau), 翌年 (năm tới).", "Tự nguyên_Xie": "Theo Wiktionary, 翌 là chữ hình thanh: 羽 (vu) biểu âm, 昱 biểu nghĩa (ánh sáng ngày mai). Nghĩa gốc và duy nhất là ngày hôm sau, năm sau — thường dùng trong văn trang trọng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngày mai", "Hạng Tần Suất (Jun Da)": "3700.0", "Tần Suất % (Jun Da)": "99.6404100508", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 立", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽立", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "立", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翌", "Unihan_Traditional (Chữ Phồn thể)": "翌", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dực", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm định ngữ đứng trước danh từ chỉ thời gian như ngày, năm để chỉ thời điểm tiếp theo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('臆', '{"9000": "3701.0", "Chữ Trung Quốc": "臆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 肉 | nhục | biểu nghĩa | thân thể, cơ thể | 意 | ý | biểu âm | 臆 = 肉 (Nhục, biểu nghĩa: thân thể — bộ 月 viết tắt) + 意 (Ý, biểu âm: đọc gần yì). Chữ hình thanh: 肉 chỉ đây là phần cơ thể — ngực; 意 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ức\": thân (肉) chứa ý (意) — ngực là nơi giữ những suy nghĩ chủ quan nhất. | Gương Hán-Việt | 臆 trong \"臆测\" (ức trắc — phỏng đoán chủ quan), \"臆断\" (ức đoán — kết luận tùy tiện). | Mở khoá kiến thức | Biết 臆 giúp đọc văn phê bình: 臆测 (phỏng đoán vô căn cứ), 臆断 (kết luận tuỳ tiện), 臆想 (tưởng tượng chủ quan).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 臆 là chữ hình thanh: 肉 (nhục — thân thể) biểu nghĩa, 意 (ý) biểu âm. Nghĩa gốc là ngực, lồng ngực. Sau mở rộng sang nghĩa chủ quan, tùy tiện (xuất phát từ ngực = chỗ lưu giữ suy nghĩ riêng tư). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngực", "Hạng Tần Suất (Jun Da)": "3701.0", "Tần Suất % (Jun Da)": "99.6408193446", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 意", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月意", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "意", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "臆", "Unihan_Traditional (Chữ Phồn thể)": "臆", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ trong các từ ghép chỉ suy nghĩ chủ quan hoặc bộ phận ngực. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挝', '{"9000": "3702.0", "Chữ Trung Quốc": "挝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 挝 | oa | tượng hình | đánh, gõ; tên nước Lào | 挝 mang bộ 扌 (thủ — tay) gợi hành động đánh, gõ. Cấu tạo chi tiết không có nguồn học thuật xác nhận. Chữ cũng dùng để phiên âm tên nước Lào (老挝 Lǎowō).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oa\": tay (扌) đánh oa oa — tiếng trống vang, cũng là âm trong tên nước Lào (老挝). | Gương Hán-Việt | 挝 chủ yếu dùng trong 老挝 (Lào Oa — nước Lào) và văn học cổ chỉ hành động đánh trống. | Mở khoá kiến thức | Biết 挝 giúp nhận biết tên gọi Hán tự của nước Lào: 老挝 (Lǎowō — Lào).", "Tự nguyên_Xie": "Chữ 挝 không có nguồn glyph Wiktionary. Từ cấu trúc, bộ 扌 (thủ) gợi hành động tay — đánh, gõ. Chữ cũng dùng phiên âm trong 老挝 (Lào). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đánh (trống)", "Hạng Tần Suất (Jun Da)": "3702.0", "Tần Suất % (Jun Da)": "99.6412286385", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 过", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌过", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "过", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挝", "Unihan_Traditional (Chữ Phồn thể)": "撾", "Pinyin_Xie": "wō", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ biểu thị hành động gõ hoặc đánh vào vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绚', '{"9000": "3703.0", "Chữ Trung Quốc": "绚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 纟 | mịch | biểu nghĩa | tơ, sợi vải | 旬 | tuần | biểu âm | 绚 là dạng giản thể của 絢, thay bộ 糹 bằng 纟. Chữ hình thanh: 纟 (tơ lụa) biểu nghĩa — màu sắc rực rỡ của vải dệt; 旬 cho âm gần xuàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuần\": tơ (纟) dệt tuần tự từng màu rực (旬) — vải lụa nhiều màu xen kẽ tạo nên vẻ lộng lẫy. | Gương Hán-Việt | 绚 trong \"绚丽\" (tuần lệ — lộng lẫy, rực rỡ), \"绚烂\" (tuần lạn — chói lọi). | Mở khoá kiến thức | Biết 绚 mở khoá từ miêu tả vẻ đẹp: 绚丽 (lộng lẫy), 绚烂 (chói lọi), 绚丽多彩 (muôn màu rực rỡ).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | 绚 là dạng giản thể của 絢. Chữ hình thanh: bộ 糹 (tơ lụa) biểu nghĩa — màu sắc rực rỡ trên vải; 旬 biểu âm. Nghĩa gốc là màu sắc lụa rực rỡ; sau mở rộng sang nghĩa rực rỡ, lộng lẫy nói chung. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trang sức sặc sỡ", "Hạng Tần Suất (Jun Da)": "3703.0", "Tần Suất % (Jun Da)": "99.6416368987", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 旬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟旬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绚", "Unihan_Traditional (Chữ Phồn thể)": "絢", "Pinyin_Xie": "xuàn", "Âm Hán Việt_Xie": "huyến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để miêu tả màu sắc hoa văn lộng lẫy, rực rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('崽', '{"9000": "3704.0", "Chữ Trung Quốc": "崽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 山 | sơn | biểu nghĩa | núi | 思 | tư | biểu âm | 崽 = 山 (Sơn, biểu nghĩa: núi — gợi nguồn gốc từ vùng núi, hoặc từ ngữ phương ngữ) + 思 (Tư, biểu âm: đọc gần zǎi). Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tối\": con (崽) nhỏ từ vùng núi (山) — tiếng địa phương miền nam Trung Quốc gọi con thú non hay đứa trẻ. | Gương Hán-Việt | 崽 chủ yếu dùng trong phương ngữ: 崽崽 (con nhỏ), 牛崽 (bê con), thường nghe ở miền Nam Trung Quốc. | Mở khoá kiến thức | Biết 崽 giúp đọc văn học và phương ngữ miền Nam: 崽崽 (con nhỏ), 兔崽子 (thằng khốn — tiếng chửi thô).", "Tự nguyên_Xie": "Theo Wiktionary, 崽 là chữ hình thanh: 山 (sơn) biểu nghĩa, 思 (tư) biểu âm. Nghĩa gốc là con nhỏ của thú vật; trong phương ngữ phía Nam dùng chỉ đứa trẻ hoặc con cái. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con thú non", "Hạng Tần Suất (Jun Da)": "3704.0", "Tần Suất % (Jun Da)": "99.642045159", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "崽", "Unihan_Traditional (Chữ Phồn thể)": "崽", "Pinyin_Xie": "zǎi", "Âm Hán Việt_Xie": "tể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong khẩu ngữ để chỉ con non của động vật hoặc đứa trẻ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('糜', '{"9000": "3705.0", "Chữ Trung Quốc": "糜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 米 | Số nét | 17 | nét | 麻 | ma | biểu âm | 米 | mễ | biểu nghĩa | gạo, lúa | 糜 = 麻 (Ma, biểu âm: đọc gần mí) + 米 (Mễ, biểu nghĩa: gạo). Chữ hình thanh: 米 chỉ đây là loại thức ăn từ gạo — cháo nhuyễn; 麻 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"my\": gạo (米) nấu ma (麻) nhuyễn — cháo loãng my, ăn vào là tiêu hết dinh dưỡng (lãng phí). | Gương Hán-Việt | 糜 trong \"糜烂\" (my lạn — thối nát, hoang dâm), \"糜费\" (my phí — lãng phí), \"糜粥\" (cháo nhuyễn). | Mở khoá kiến thức | Biết 糜 giúp đọc văn chính luận: 糜烂 (thối nát, sa đoạ), 糜费 (tiêu hoang), 生活糜烂 (lối sống ăn chơi sa đoạ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 糜 là chữ hình thanh: 米 (mễ — gạo) biểu nghĩa, 麻 (ma) biểu âm. Nghĩa gốc là cháo gạo nấu nhuyễn, hoặc lúa mì nấu chín. Nghĩa mở rộng: lãng phí, tiêu xài hoang (\"奢靡\" lẫn với 靡). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháo; nhừ; nát; thối rữa; lãng phí; hoang phí; họ Mi", "Hạng Tần Suất (Jun Da)": "3705.0", "Tần Suất % (Jun Da)": "99.6424529025", "GavinGrover_Once (Chiết tự trực tiếp)": "麻 + 米", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴麻米", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "米", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "麻", "Unihan_Simplified (Chữ Giản thể)": "糜", "Unihan_Traditional (Chữ Phồn thể)": "糜", "Pinyin_Xie": "mí", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ cháo hoặc làm tính từ chỉ trạng thái nát nhừ, hoang phí. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘢', '{"9000": "3706.0", "Chữ Trung Quốc": "瘢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 疒 | nạch | biểu nghĩa | bệnh, thương tích | 般 | ban | biểu âm | 瘢 = 疒 (Nạch, biểu nghĩa: bệnh/thương tích) + 般 (Ban, biểu âm: đọc gần bān). Chữ hình thanh: 疒 chỉ đây là vết thương trên cơ thể — sẹo; 般 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ban\": bệnh (疒) để lại vết ban — sẹo là dấu tích bệnh tật hoặc thương tích. | Gương Hán-Việt | ban trong \"瘢痕\" (ban ngân — sẹo), \"刀瘢\" (đao ban — sẹo dao), \"烧瘢\" (thiêu ban — sẹo bỏng). | Mở khoá kiến thức | Biết 瘢 giúp đọc văn y khoa và văn học: 瘢痕 (sẹo), 瘢痕组织 (mô sẹo).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary (dựa trên định nghĩa), 瘢 là chữ hình thanh: 疒 (nạch — bệnh/thương tích) biểu nghĩa, 般 (ban) biểu âm. Nghĩa gốc là sẹo, vết sẹo để lại sau khi vết thương lành. Tiểu triện đã có dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết sẹo", "Hạng Tần Suất (Jun Da)": "3706.0", "Tần Suất % (Jun Da)": "99.6428601291", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 般", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒般", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "般", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘢", "Unihan_Traditional (Chữ Phồn thể)": "瘢", "Pinyin_Xie": "bān", "Âm Hán Việt_Xie": "ban", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các vết sẹo hoặc vết thâm trên da sau khi lành vết thương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跤', '{"9000": "3707.0", "Chữ Trung Quốc": "跤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 𧾷 | túc | biểu nghĩa | chân (dạng biến thể bộ 足) | 交 | giao | biểu âm | 跤 = 𧾷 (biến thể bộ 足 — túc, biểu nghĩa: chân) + 交 (Giao, biểu âm: đọc gần jiāo). Chữ hình thanh: bộ chân chỉ đây là hành động của chân — vấp ngã; 交 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giao\": chân (𧾷) giao (交) nhau — hai người giao chân vật lộn nhau trên võ đài. | Gương Hán-Việt | 跤 trong \"摔跤\" (suý giao — đấu vật, té ngã), \"跌跤\" (điệt giao — vấp ngã). | Mở khoá kiến thức | Biết 跤 mở khoá từ thể thao: 摔跤 (đấu vật), 跌跤 (vấp ngã).", "Tự nguyên_Xie": "Theo Wiktionary, 跤 là chữ hình thanh: bộ 足/𧾷 (túc — chân) biểu nghĩa, 交 (giao) biểu âm. Nghĩa gốc là vấp ngã, té ngã. Sau dùng trong 摔跤 (đấu vật — môn thể thao ngã nhau). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngã", "Hạng Tần Suất (Jun Da)": "3707.0", "Tần Suất % (Jun Da)": "99.643266839", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跤", "Unihan_Traditional (Chữ Phồn thể)": "跤", "Pinyin_Xie": "jiāo", "Âm Hán Việt_Xie": "giao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường kết hợp với động từ ngã để tạo thành cụm động tân chỉ hành động vấp ngã. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阑', '{"9000": "3708.0", "Chữ Trung Quốc": "阑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 12 | nét | 门 | môn | biểu nghĩa | cửa | 柬 | giản | biểu âm | 阑 là dạng giản thể của 闌, thay bộ 門 bằng 门. Chữ hình thanh: 门 (môn — cửa) biểu nghĩa — lan can, hàng rào; 柬 cho âm gần lán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\": cửa (门) có hàng rào (阑) — lan can ngăn không cho vượt qua, đêm đã về khuya. | Gương Hán-Việt | 阑 trong \"夜阑\" (dạ lan — đêm về khuya), \"阑珊\" (lan san — lụi tàn), \"阑干\" (lan can — tay vịn). | Mở khoá kiến thức | Biết 阑 mở khoá từ thơ ca: 夜阑 (đêm về khuya), 阑珊 (lụi tàn — trong thơ cổ), 阑干 (lan can).", "Tự nguyên_Xie": "Kim văn | Đại triện | Tiểu triện | 阑 là dạng giản thể của 闌. Chữ gốc hình thanh: 門 (môn — cửa) biểu nghĩa, 柬 (giản) biểu âm. Nghĩa gốc là lan can, hàng rào. Sau dùng nghĩa muộn màng, cuối đêm (夜阑 — đêm khuya). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sắp hết, sắp tàn; lẻn ra ngoài", "Hạng Tần Suất (Jun Da)": "3708.0", "Tần Suất % (Jun Da)": "99.6436730322", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 柬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门柬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阑", "Unihan_Traditional (Chữ Phồn thể)": "闌", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ trạng thái đêm muộn, sắp tàn hoặc làm danh từ chỉ hàng rào. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恬', '{"9000": "3709.0", "Chữ Trung Quốc": "恬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 心 | tâm | biểu nghĩa | lòng | 甜 | điềm | biểu âm | 恬 = 心 (Tâm, biểu nghĩa: lòng) + 甜 (Điềm, biểu âm: đọc gần tián). Chữ hình thanh: 心 chỉ đây là trạng thái tâm hồn — điềm tĩnh; phần rút gọn của 甜 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điềm\": lòng (心) ngọt điềm (甜) — tâm hồn ngọt ngào điềm đạm, không xao động. | Gương Hán-Việt | điềm trong \"恬静\" (điềm tĩnh — yên tĩnh điềm đạm), \"恬淡\" (điềm đạm — thản nhiên). | Mở khoá kiến thức | Biết 恬 mở khoá từ miêu tả tính cách: 恬静 (điềm tĩnh), 恬淡 (thản nhiên), 恬不知耻 (trơ trẽn, không biết xấu hổ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 恬 là chữ hình thanh: 心 (tâm) biểu nghĩa, 甜 (điềm) biểu âm (dạng rút gọn). Nghĩa gốc là điềm tĩnh, yên lặng, thản nhiên. Tiểu triện và Lưu Thư Thông đã có dạng này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bình tĩnh, lặng lẽ; yên ổn", "Hạng Tần Suất (Jun Da)": "3709.0", "Tần Suất % (Jun Da)": "99.6440792253", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 舌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄舌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "舌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恬", "Unihan_Traditional (Chữ Phồn thể)": "恬", "Pinyin_Xie": "tián", "Âm Hán Việt_Xie": "điềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ biểu thị trạng thái yên bình, tĩnh lặng hoặc thái độ điềm nhiên. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('豢', '{"9000": "3710.0", "Chữ Trung Quốc": "豢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 豕 | Số nét | 13 | nét | 豢 | hoạn | tượng hình | nuôi gia súc bằng lương thực | 豢 mang bộ 豕 (thỉ — lợn) và phần trên gợi hành động cho ăn. Chữ hội ý hoặc hình thanh chưa được xác nhận rõ qua nguồn Wiktionary glyph. Nghĩa cốt lõi: nuôi gia súc bằng ngũ cốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoạn\": nuôi (hoạn) gia súc — người hoạn quan là người được nuôi dưỡng trong hoàng cung. | Gương Hán-Việt | hoạn trong \"豢养\" (hoạn dưỡng — nuôi dưỡng, bao nuôi), \"豢化\" (thuần hoá, nuôi dưỡng). | Mở khoá kiến thức | Biết 豢 giúp đọc văn chính trị: 豢养 (bao nuôi, duy trì tay sai), 豢养走狗 (nuôi tay sai).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Chữ 豢 xuất hiện từ giáp cốt văn. Nghĩa gốc là nuôi gia súc (chủ yếu lợn và dê) bằng ngũ cốc. Sau mở rộng sang nghĩa nuôi dưỡng, bao nuôi (người). Về sau dùng nghĩa hối lộ/nuôi dưỡng kẻ phục vụ. Chưa có nguồn học thuật xác nhận cấu tạo chi tiết. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nuôi (súc vật) bằng thóc lúa", "Hạng Tần Suất (Jun Da)": "3710.0", "Tần Suất % (Jun Da)": "99.6444849016", "GavinGrover_Once (Chiết tự trực tiếp)": "龹 + 豕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龹豕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "豕", "Unihan_Simplified (Chữ Giản thể)": "豢", "Unihan_Traditional (Chữ Phồn thể)": "豢", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ việc nuôi dưỡng, vỗ béo gia súc hoặc nuôi dưỡng ý đồ xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汶', '{"9000": "3711.0", "Chữ Trung Quốc": "汶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 水 | thủy | biểu nghĩa | nước | 文 | văn | biểu âm | 汶 = 水 (Thủy, biểu nghĩa: nước) + 文 (Văn, biểu âm). Chữ hình thanh: bộ Thủy chỉ loại (sông nước), Văn cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Vấn\": dòng sông Vấn chảy qua đất Lỗ xưa — nước (水) mang theo văn chương (文) của Khổng Tử. | Gương Hán-Việt | Vấn — tên sông cổ (汶水, sông Vấn) | Mở khoá kiến thức | Biết 汶 mở khoá địa danh 汶川 (Vấn Xuyên — nơi động đất 2008) và 汶萊 (Brunei theo phiên âm Hán).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 水 (thủy) biểu nghĩa liên quan đến nước; 文 (văn) cho âm. Chỉ con sông Vấn ở tỉnh Sơn Đông, Trung Quốc. Ngoài ra còn có nghĩa thứ yếu: nước đục (phương ngữ Khách Gia), và có thể dùng làm họ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Vấn", "Hạng Tần Suất (Jun Da)": "3711.0", "Tần Suất % (Jun Da)": "99.6448895444", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 文", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵文", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "文", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汶", "Unihan_Traditional (Chữ Phồn thể)": "汶", "Pinyin_Xie": "wèn", "Âm Hán Việt_Xie": "vấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng dùng để chỉ tên sông hoặc địa danh cụ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跷', '{"9000": "3712.0", "Chữ Trung Quốc": "跷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 足 | túc | biểu nghĩa | chân | 尧 | nghiêu | biểu âm | 跷 = 足 (Túc, biểu nghĩa: chân) + 尧 (Nghiêu, biểu âm). Chữ hình thanh: bộ Túc chỉ hành động của chân, 尧 cho âm gần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kiều\": dùng chân (足) nhón lên cao như Nghiêu (尧) vương — nhón gót kiễng chân. | Gương Hán-Việt | Kiều — nhón chân, kiễng gót (高跷: cà kheo) | Mở khoá kiến thức | Biết 跷 mở khoá 高跷 (cà kheo), 跷跷板 (bập bênh), 跷脚 (nhón chân).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 足 (túc) biểu nghĩa liên quan đến chân và đi lại; 尧 cho âm. Nghĩa gốc là nhón chân, đi kiễng gót; mở rộng sang nghĩa đi trên cà kheo (高跷). Chưa có nguồn Wiktionary chi tiết về giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cất chân lên, giơ chân", "Hạng Tần Suất (Jun Da)": "3712.0", "Tần Suất % (Jun Da)": "99.6452941871", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 尧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊尧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跷", "Unihan_Traditional (Chữ Phồn thể)": "蹺", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "khiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động nhấc cao chân hoặc kiễng gót chân lên. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琵', '{"9000": "3713.0", "Chữ Trung Quốc": "琵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 12 | nét | 琵 | tì | tượng hình | nửa trên của tên nhạc cụ 琵琶 | 琵 là chữ tượng hình/ký hiệu cấu tạo, chỉ xuất hiện trong tên 琵琶 (tỳ bà). Hình dạng gợi ngón tay gảy dây đàn từ trên xuống.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tì\": chữ 琵 luôn xuất hiện cùng 琶 thành 琵琶 (tỳ bà) — cây đàn lute cổ tiếng Việt mượn thẳng âm này. | Gương Hán-Việt | Tì — trong 琵琶 (tỳ bà, đàn lute cổ) | Mở khoá kiến thức | Biết 琵 mở khoá 琵琶 (tỳ bà) — nhạc cụ dây truyền thống quan trọng trong âm nhạc Trung Hoa và Việt Nam.", "Tự nguyên_Xie": "Tiểu triện | Chữ 琵 chỉ dùng trong tổ hợp 琵琶. Wiktionary ghi nhận đây là chữ chỉ dùng trong tên nhạc cụ tỳ bà (đàn lute cổ Trung Hoa). Hình dạng liên quan đến ngón tay đánh đàn. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tỳ bà 琵琶)", "Hạng Tần Suất (Jun Da)": "3713.0", "Tần Suất % (Jun Da)": "99.6456977963", "GavinGrover_Once (Chiết tự trực tiếp)": "玨 + 比", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱玨比", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "玨", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "比", "Unihan_Simplified (Chữ Giản thể)": "琵", "Unihan_Traditional (Chữ Phồn thể)": "琵", "Pinyin_Xie": "pí", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường dùng làm danh từ trong từ ghép để chỉ một loại nhạc cụ dây. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('憨', '{"9000": "3714.0", "Chữ Trung Quốc": "憨", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 15 | nét | 憨 | hám | tượng hình | ngây thơ, khờ khạo | 憨 có phần dưới là 心 (tâm, tim/tâm trí); phần trên phức tạp hơn. Chưa có phân tích cấu trúc chi tiết trong nguồn tham khảo — chưa rõ hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hám\": tâm (心) trẻ thơ không toan tính — người hám (憨) là người ngây thơ dễ thương. | Gương Hán-Việt | Hám — ngây thơ, khờ khạo dễ thương (憨厚: chân thật thật thà) | Mở khoá kiến thức | Biết 憨 mở khoá 憨厚 (chân chất thật thà), 憨态 (vẻ ngây thơ), 憨笑 (cười ngây ngô).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu trúc chi tiết cho 憨. Từ thành phần có bộ 心 (tâm) phía dưới, gợi liên hệ đến tâm trí. Nghĩa chính là ngây thơ, khờ khạo, đơn giản — thường mang sắc thái đáng yêu hơn là chê bai. chưa có nguồn học thuật xác nhận cấu trúc đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngu si", "Hạng Tần Suất (Jun Da)": "3714.0", "Tần Suất % (Jun Da)": "99.6461008887", "GavinGrover_Once (Chiết tự trực tiếp)": "敢 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敢心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "憨", "Unihan_Traditional (Chữ Phồn thể)": "憨", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ đứng sau phó từ chỉ mức độ để miêu tả vẻ ngây thơ, thật thà. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜗', '{"9000": "3715.0", "Chữ Trung Quốc": "蜗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật nhỏ | 呙 | biểu âm | 蜗 là dạng giản thể của 蝸. Bộ 虫 (trùng) biểu nghĩa — loại sâu bọ/sinh vật nhỏ; 呙 cho âm. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Oa\": con trùng (虫) mang nhà trên lưng — ốc sên (蜗牛) chậm chạp như tiếng oa oa. | Gương Hán-Việt | Oa — trong 蜗牛 (ốc sên) | Mở khoá kiến thức | Biết 蜗 mở khoá 蜗牛 (ốc sên), 蜗居 (chỗ ở chật hẹp — nghĩa bóng), 蜗行 (đi chậm như ốc sên).", "Tự nguyên_Xie": "Tiểu triện | 蜗 là chữ giản thể của 蝸, phồn thể viết với 咼 thay vì 呙. Cả hai đều là chữ hình thanh: bộ 虫 (trùng) biểu nghĩa liên quan đến sinh vật nhỏ; thành phần bên phải cho âm đọc. Chỉ con ốc sên. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ốc sên", "Hạng Tần Suất (Jun Da)": "3715.0", "Tần Suất % (Jun Da)": "99.6465039811", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 呙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫呙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "呙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜗", "Unihan_Traditional (Chữ Phồn thể)": "蝸", "Pinyin_Xie": "wō", "Âm Hán Việt_Xie": "oa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước các từ khác để tạo thành tên gọi của loài ốc sên. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螅', '{"9000": "3716.0", "Chữ Trung Quốc": "螅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật nhỏ | 息 | tức | biểu âm | 螅 = 虫 (Trùng, biểu nghĩa: sinh vật nhỏ) + 息 (Tức, biểu âm). Chữ hình thanh. Thường chỉ thủy tức (水螅) — một loại sinh vật biển nhỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tức\": sinh vật (虫) thở (息) dưới nước — thủy tức (水螅) là con polyp nhỏ. | Gương Hán-Việt | Tức — trong 水螅 (thủy tức, hydra) | Mở khoá kiến thức | Biết 螅 mở khoá 水螅 (thủy tức — hydra nước ngọt) và 珊瑚螅 (sinh vật san hô).", "Tự nguyên_Xie": "Không có phân tích từ nguyên chi tiết trong Wiktionary cho chữ 螅. Từ cấu trúc: bộ 虫 (trùng) biểu nghĩa liên quan đến sinh vật nhỏ; 息 cho âm. Chủ yếu dùng trong từ 水螅 (thủy tức, hydra) — sinh vật sống dưới nước. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đỉa", "Hạng Tần Suất (Jun Da)": "3716.0", "Tần Suất % (Jun Da)": "99.6469065567", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 息", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫息", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "息", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螅", "Unihan_Traditional (Chữ Phồn thể)": "螅", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong các thuật ngữ sinh học để chỉ loài thủy tức. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惴', '{"9000": "3717.0", "Chữ Trung Quốc": "惴", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 12 | nét | 忄 | tâm | biểu nghĩa | lòng, tâm trí | 耑 | biểu âm | 惴 = 忄(Tâm, biểu nghĩa: lòng/tâm trí, dạng đứng của 心) + 耑 (biểu âm). Chữ hình thanh: bộ Tâm chỉ trạng thái tâm lý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Nhoai\": lòng (忄) co rúm — nhoai người lo sợ, như 惴惴不安 (tim đập thình thịch lo âu). | Gương Hán-Việt | Nhoai — lo lắng, sợ hãi (惴惴不安: bất an lo lắng) | Mở khoá kiến thức | Biết 惴 mở khoá 惴惴不安 (lo lắng bất an — thành ngữ thường dùng), 惴恐 (lo sợ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 忄(tâm) biểu nghĩa trạng thái tâm lý; 耑 cho âm. Nghĩa gốc là lo âu, sợ hãi. Thường dùng trong 惴惴不安 (lo lắng bất an) và 惴恐 (sợ hãi lo lắng). Wiktionary ghi nhận có cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lo sợ", "Hạng Tần Suất (Jun Da)": "3717.0", "Tần Suất % (Jun Da)": "99.6473080988", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惴", "Unihan_Traditional (Chữ Phồn thể)": "惴", "Pinyin_Xie": "zhuì", "Âm Hán Việt_Xie": "chuý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái tâm lý lo lắng, bất an trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戟', '{"9000": "3718.0", "Chữ Trung Quốc": "戟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 12 | nét | 榦 | biểu nghĩa | cán, thân cây — nay rút gọn thành phần trên | 戈 | qua | biểu nghĩa | giáo/dao khoét — vũ khí | 戟 là chữ hội ý: gốc từ 𢧢, gồm 榦 (cán, thân nhánh — đã giản lược) + 戈 (Qua: giáo rìu). Hai thành phần đều biểu nghĩa, kết hợp chỉ loại vũ khí có cán dài với lưỡi ngang.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Kích\": giáo (戈) gắn thêm cán dài (榦) — cây kích (戟) là vũ khí kép của tướng lĩnh cổ đại. | Gương Hán-Việt | Kích — trong 交戟 (giao kích), 刀戟 (đao kích), 戟门 (cổng cắm kích — biểu tượng quyền lực quan lại) | Mở khoá kiến thức | Biết 戟 mở khoá 刀枪剑戟 (thành ngữ chỉ các loại binh khí cổ), 戟门 (cổng nhà quan có cắm kích).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hội ý, giản lược từ 𢧢. Gồm 榦 (cán cây, đã rút gọn thành dạng 倝) + 戈 (Qua: loại vũ khí giáo rìu). Kết hợp hai yếu tố tả cây kích — vũ khí cán dài có lưỡi dao ngang, kết hợp giữa giáo (矛) và rìu (戈). Kim văn đã thể hiện hình dạng vũ khí này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái kích (một loại vũ khí)", "Hạng Tần Suất (Jun Da)": "3718.0", "Tần Suất % (Jun Da)": "99.6477086073", "GavinGrover_Once (Chiết tự trực tiếp)": "龺 + 戈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰龺戈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "戈", "Unihan_Simplified (Chữ Giản thể)": "戟", "Unihan_Traditional (Chữ Phồn thể)": "戟", "Pinyin_Xie": "jǐ", "Âm Hán Việt_Xie": "kích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ chỉ một loại binh khí cổ đại kết hợp giữa mác và rìu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('匮', '{"9000": "3719.0", "Chữ Trung Quốc": "匮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 匚 | Số nét | 11 | nét | 匚 | biểu nghĩa | hộp, tủ đựng đồ | 貴 | quý | biểu âm | quý giá | 匮 = 匚 (biểu nghĩa: hộp, tủ) + 貴 (Quý, biểu âm). Chữ hình thanh: 匚 chỉ đồ vật đựng; 貴 cho âm. Nghĩa gốc là tủ đựng đồ, sau chuyển thành thiếu hụt, cạn kiệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Quỹ\": cái tủ (匚) chứa đồ quý (貴) nay đã rỗng — 匮乏 (quỹ phạp) là thiếu thốn, cạn kiệt. | Gương Hán-Việt | Quỹ — trong 匮乏 (quỹ phạp: thiếu thốn, khan hiếm) | Mở khoá kiến thức | Biết 匮 mở khoá 匮乏 (thiếu thốn), 资源匮乏 (tài nguyên khan hiếm), 人才匮乏 (thiếu nhân tài).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh. 匚 (biểu nghĩa: hộp/tủ, vật đựng) + 貴 (Quý: quý giá, biểu âm). Nghĩa gốc là tủ đựng đồ quý; từ đó nghĩa mở rộng thành thiếu thốn, cạn kiệt (như tủ đồ đã rỗng). Đại triện và Tiểu triện đều ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái hòm, cái rương", "Hạng Tần Suất (Jun Da)": "3719.0", "Tần Suất % (Jun Da)": "99.6481080822", "GavinGrover_Once (Chiết tự trực tiếp)": "匚 + 贵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿷ (Bao quanh phía trái)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴匚贵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "匚", "Unihan_Simplified (Chữ Giản thể)": "匮", "Unihan_Traditional (Chữ Phồn thể)": "匱", "Pinyin_Xie": "kuì", "Âm Hán Việt_Xie": "quỹ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Trong tiếng Trung hiện đại thường dùng làm tính từ để chỉ sự thiếu thốn, cạn kiệt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恙', '{"9000": "3720.0", "Chữ Trung Quốc": "恙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 羊 | dương | biểu âm | con dê (cho âm) | 心 | tâm | biểu nghĩa | lòng, tâm trí | 恙 = 羊 (Dương, biểu âm) + 心 (Tâm, biểu nghĩa: lòng/trạng thái tâm lý). Chữ hình thanh: 心 chỉ đây là cảm xúc/trạng thái tâm lý; 羊 cho âm gần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Dạng\": lòng (心) bất ổn như dê (羊) kêu — 无恙 là không bệnh không lo, bình an vô sự. | Gương Hán-Việt | Dạng — trong 无恙 (vô dạng: bình an), 抱恙 (bào dạng: đang bệnh) | Mở khoá kiến thức | Biết 恙 mở khoá cụm 别来无恙 (lâu ngày không gặp, bình an chứ?) và 抱恙 (đang mắc bệnh — cách nói lịch sự).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 羊 (dương, biểu âm) + 心 (tâm, biểu nghĩa). Nghĩa gốc bao gồm lo lắng, tai họa, và bệnh tật. Nay dùng nhiều nhất trong câu hỏi lịch sự ''别来无恙'' (bình an không) và từ 抱恙 (đang có bệnh). Tiểu triện và Lục thư thông ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh xoàng, bệnh không nguy hiểm", "Hạng Tần Suất (Jun Da)": "3720.0", "Tần Suất % (Jun Da)": "99.6485070403", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "心", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "恙", "Unihan_Traditional (Chữ Phồn thể)": "恙", "Pinyin_Xie": "yàng", "Âm Hán Việt_Xie": "dạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xuất hiện trong các lời hỏi thăm sức khỏe hoặc cụm từ cố định. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抿', '{"9000": "3721.0", "Chữ Trung Quốc": "抿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 8 | nét | 扌 | thủ | biểu nghĩa | tay | 民 | dân | biểu âm | 抿 = 扌(Thủ, biểu nghĩa: tay) + 民 (Dân, biểu âm). Chữ hình thanh: bộ Thủ chỉ hành động dùng tay; 民 cho âm gần.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mẫn\": tay (扌) nhẹ nhàng vuốt như dân (民) gian chải tóc — 抿嘴 là mím môi, 抿一口 là nhấp một ngụm. | Gương Hán-Việt | Mẫn — vuốt nhẹ, mím môi (抿嘴: mím miệng) | Mở khoá kiến thức | Biết 抿 mở khoá 抿嘴 (mím môi), 抿一口 (nhấp một ngụm), 抿头发 (vuốt tóc).", "Tự nguyên_Xie": "Chữ hình thanh. Bộ 扌(thủ, tay) biểu nghĩa hành động dùng tay; 民 (dân) cho âm. Nghĩa gốc là vuốt nhẹ, chải (tóc), sau mở rộng sang ngậm môi lại, nhấp môi uống một chút. Wiktionary ghi nhận cấu trúc 扌+ 民. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chải tóc, chải đầu; chúm chím, cụp; nhắp, hớp", "Hạng Tần Suất (Jun Da)": "3721.0", "Tần Suất % (Jun Da)": "99.6489054816", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 民", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌民", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "民", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抿", "Unihan_Traditional (Chữ Phồn thể)": "抿", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Dùng làm động từ chỉ động tác mím môi, nhấp một chút nước hoặc vuốt tóc cho mượt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桢', '{"9000": "3722.0", "Chữ Trung Quốc": "桢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 贞 | trinh | biểu âm | 桢 = 木 (Mộc, biểu nghĩa: gỗ/cây) + 贞 (Trinh, biểu âm). Chữ hình thanh: bộ Mộc chỉ loại cây; 贞 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Trinh\": cây gỗ (木) trinh (贞) cứng làm trụ cột — 桢干 là người nòng cốt chống đỡ cơ nghiệp. | Gương Hán-Việt | Trinh — trong 桢干 (trinh cán: trụ cột, nòng cốt) | Mở khoá kiến thức | Biết 桢 mở khoá 桢干 (người trụ cột, nòng cốt) — thường dùng trong văn viết trang trọng.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh. 木 (mộc, biểu nghĩa: cây/gỗ) + 贞 (trinh, biểu âm). Chỉ loại cây gỗ cứng dùng làm cột chống, từ đó mang nghĩa bóng là người trụ cột, đầu tàu. Đại triện và Tiểu triện ghi nhận cấu trúc này. Thường gặp trong 桢干 (trụ cột). Chưa có nguồn học thuật đầy đủ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cột góc tường; cội, gốc", "Hạng Tần Suất (Jun Da)": "3722.0", "Tần Suất % (Jun Da)": "99.649303923", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 贞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木贞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桢", "Unihan_Traditional (Chữ Phồn thể)": "楨", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn viết để chỉ người hoặc vật đóng vai trò trụ cột quan trọng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笺', '{"9000": "3723.0", "Chữ Trung Quốc": "笺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre — vật liệu viết | 戔 | biểu âm | 笺 = 竹 (Trúc, biểu nghĩa: tre — vật liệu làm thẻ viết) + 戔 (biểu âm). Chữ hình thanh: ý tưởng thanh tre nhỏ dùng ghi chép, từ đó chỉ giấy tờ, thư từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tiên\": thẻ tre (竹) nhỏ (戔) dùng viết thư — 便笺 là tờ ghi chú, 笺纸 là giấy viết thư đẹp. | Gương Hán-Việt | Tiên — trong 便笺 (tiện tiên: ghi chú), 笺注 (tiên chú: chú thích văn cổ) | Mở khoá kiến thức | Biết 笺 mở khoá 便笺 (giấy ghi chú), 笺注 (chú giải văn cổ), 信笺 (giấy viết thư).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 竹 (trúc, biểu nghĩa: tre) + 戔 (biểu âm). Gốc chỉ thanh tre nhỏ dùng ghi chép; sau khi giấy ra đời, nghĩa mở rộng sang giấy viết thư, giấy trang trọng, ghi chú. Digital Shinjigen 2017 xác nhận ý nghĩa ''mảnh tre nhỏ'' mở rộng sang ''nhãn hiệu'' hay ''nhãn dán''. Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ghi chú", "Hạng Tần Suất (Jun Da)": "3723.0", "Tần Suất % (Jun Da)": "99.6497018475", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 戋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮戋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笺", "Unihan_Traditional (Chữ Phồn thể)": "椾", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại giấy viết thư có hoa văn hoặc phần ghi chú giải thích. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛤', '{"9000": "3724.0", "Chữ Trung Quốc": "蛤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 12 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, sinh vật nhỏ | 合 | cáp | biểu âm | 蛤 = 虫 (Trùng, biểu nghĩa: sinh vật) + 合 (Cáp, biểu âm). Chữ hình thanh: bộ Trùng chỉ loại động vật; 合 cho âm (cáp/há).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cáp\": sinh vật (虫) hai mảnh hợp (合) lại — con ngao, con trai biển (蛤蜊) hay con cóc (蛤蟆). | Gương Hán-Việt | Cáp — trong 蛤蜊 (cáp lãi: con ngao), 蛤蟆 (cáp ma: con cóc) | Mở khoá kiến thức | Biết 蛤 mở khoá 蛤蜊 (ngao, trai biển), 蛤蟆 (cóc/ếch), 蛤蚧 (tắc kè — vị thuốc).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 虫 (trùng, biểu nghĩa: sinh vật) + 合 (cáp, biểu âm). Đọc gé chỉ con trai, hàu (蛤蜊, nhuyễn thể); đọc há chỉ con cóc, ếch (蛤蟆). 合 gợi ý hai mảnh vỏ khép lại — phù hợp với hình ảnh con trai. Tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Nghêu", "Hạng Tần Suất (Jun Da)": "3724.0", "Tần Suất % (Jun Da)": "99.6500992553", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 合", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫合", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "合", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛤", "Unihan_Traditional (Chữ Phồn thể)": "蛤", "Pinyin_Xie": "há", "Âm Hán Việt_Xie": "cáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp để chỉ các loài động vật thân mềm hai mảnh vỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞳', '{"9000": "3725.0", "Chữ Trung Quốc": "瞳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 17 | nét | 目 | mục | biểu nghĩa | mắt | 童 | đồng | biểu âm | 瞳 = 目 (Mục, biểu nghĩa: mắt) + 童 (Đồng, biểu âm). Chữ hình thanh: bộ Mục chỉ bộ phận của mắt; 童 cho âm (đồng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đồng\": mắt (目) của đứa trẻ (童) trong veo — đồng tử (瞳孔) là con ngươi mắt. | Gương Hán-Việt | Đồng — trong 瞳孔 (đồng khổng: con ngươi mắt) | Mở khoá kiến thức | Biết 瞳 mở khoá 瞳孔 (con ngươi), 瞳仁 (lòng đen mắt), 瞳孔放大 (giãn đồng tử).", "Tự nguyên_Xie": "Chữ hình thanh. 目 (mục, biểu nghĩa: mắt) + 童 (đồng, biểu âm). Chỉ con ngươi của mắt — phần tối ở trung tâm mống mắt. Trong tiếng Việt mượn âm Hán-Việt: đồng tử (瞳孔). Tiểu triện ghi nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ngươi mắt", "Hạng Tần Suất (Jun Da)": "3725.0", "Tần Suất % (Jun Da)": "99.6504966631", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 童", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目童", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "童", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞳", "Unihan_Traditional (Chữ Phồn thể)": "瞳", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ bộ phận mắt như nhãn đồng hoặc đồng tử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓢', '{"9000": "3726.0", "Chữ Trung Quốc": "瓢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓜 | Số nét | 16 | nét | 票 | phiếu | biểu âm | 瓜 | qua | biểu nghĩa | quả bầu bí | 瓢 = 票 (Phiếu, biểu âm) + 瓜 (Qua, biểu nghĩa: quả bầu bí). Chữ hình thanh: bộ Qua chỉ loại quả; 票 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Bầu\": quả bầu (瓜) khô cắt đôi thành gáo múc nước — 水瓢 là chiếc gáo bầu quen thuộc ở làng quê. | Gương Hán-Việt | Bầu — trong 水瓢 (gáo múc nước), 瓢虫 (bầu trùng: con bọ rùa) | Mở khoá kiến thức | Biết 瓢 mở khoá 水瓢 (gáo nước), 瓢虫 (bọ rùa — hình tròn như quả bầu), 瓢泼大雨 (mưa như trút nước).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 票 (phiếu, biểu âm) + 瓜 (qua, biểu nghĩa: quả bầu/bí). Chỉ quả bầu khô được cắt đôi dùng làm muỗng múc nước. Tiểu triện và Lục thư thông ghi nhận cấu trúc. Trong tiếng Việt: bầu (瓢) là loại quả leo, và muỗng múc nước bằng bầu khô. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bầu", "Hạng Tần Suất (Jun Da)": "3726.0", "Tần Suất % (Jun Da)": "99.6512888947", "GavinGrover_Once (Chiết tự trực tiếp)": "票 + 瓜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰票瓜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "票", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓜", "Unihan_Simplified (Chữ Giản thể)": "瓢", "Unihan_Traditional (Chữ Phồn thể)": "瓢", "Pinyin_Xie": "piáo", "Âm Hán Việt_Xie": "biều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường làm danh từ chỉ cái gáo hoặc làm lượng từ cho nước, chất lỏng múc bằng gáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('衹', '{"9000": "3727.0", "Chữ Trung Quốc": "衹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 9 | nét | 衣 | y | biểu nghĩa | áo, vải | 氏 | thị | biểu âm | 衹 = 衣/衤(Y, biểu nghĩa: áo/vải) + 氏 (Thị, biểu âm). Chữ hình thanh. Nay dùng chủ yếu như biến thể của 只 (chỉ có, chỉ là).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Chi\": áo (衣) một mảnh (氏) — 衹 là ''chỉ có vậy thôi'', biến thể cổ của 只. | Gương Hán-Việt | Chi — biến thể của 只 trong văn ngôn (衹是: chỉ là) | Mở khoá kiến thức | Biết 衹 mở khoá văn ngôn Hán ngữ: 衹是 (chỉ là), 衹有 (chỉ có) — dạng cổ của 只是, 只有.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Gốc bộ 衣 + 氏. Trong văn ngôn, 衹 là biến thể của 只 mang nghĩa ''chỉ, duy nhất''. Tiểu triện ghi nhận hình dạng này. Nay ít dùng độc lập, thường gặp trong văn học cổ hoặc phương ngữ. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chỉ một", "Hạng Tần Suất (Jun Da)": "3727.0", "Tần Suất % (Jun Da)": "99.6516847521", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 氏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤氏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "氏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "衹", "Unihan_Traditional (Chữ Phồn thể)": "衹", "Pinyin_Xie": "zhǐ", "Âm Hán Việt_Xie": "chỉ, kỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Thường làm phó từ đứng trước động từ hoặc tính từ để giới hạn phạm vi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秤', '{"9000": "3728.0", "Chữ Trung Quốc": "秤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 10 | nét | 禾 | hoà | biểu nghĩa | lúa, ngũ cốc | 平 | bình | biểu âm | bằng phẳng, cân bằng | 秤 = 禾 (Hoà, biểu nghĩa: lúa/ngũ cốc) + 平 (Bình, biểu âm và biểu ý). Wiktionary không có glyphOrigin. Cấu trúc có thể là hội ý hoặc hình thanh: 禾 gợi việc cân đo nông sản; 平 gợi cân bằng và gợi âm chèng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xứng\": lúa gạo (禾) được cân thật bằng phẳng (平) — chiếc cân phải thật xứng đáng, cân bằng. | Gương Hán-Việt | \"xứng\" ít dùng độc lập; gặp trong 秤砣 (quả cân), 过秤 (cân hàng hóa) | Mở khoá kiến thức | Biết 秤 mở khoá 秤砣 (quả cân), 磅秤 (cân bàn), 过秤 (cân đo hàng hóa).", "Tự nguyên_Xie": "Chữ 秤 (xứng) không có glyphOrigin trong Wiktionary — chữ tạo muộn. Cấu trúc ⿰禾平: bộ 禾 (Hoà — lúa gạo) gợi việc cân đo nông sản, bộ 平 (Bình — bằng phẳng) vừa gợi ý cân bằng vừa có thể biểu âm. Nghĩa: cái cân (đặc biệt cân tiểu ly/cân đòn). Chưa có nguồn học thuật xác nhận ls. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1855.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hòa (115) Bình (051)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hòa (số 115 - cây lúa/ 禾) ở bên trái chữ Bình (số 051 - cân bằng/ 平). Dùng cái cân thăng bằng để cân đo lúa lúa gạo. Giải thích sự chuyển ý: Đây là chữ Hội ý. Xứng là cái cân, một vật dụng dùng để đo trọng lượng (xứng can - đòn cân, cân xứng).", "Nghĩa Tiếng Việt_Xie": "vừa, hợp với, xứng với; cái cân", "Hạng Tần Suất (Jun Da)": "3728.0", "Tần Suất % (Jun Da)": "99.6520800927", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 平", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾平", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "平", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秤", "Unihan_Traditional (Chữ Phồn thể)": "秤", "Pinyin_Xie": "chèng", "Âm Hán Việt_Xie": "xứng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ cái cân hoặc làm động từ với nghĩa cân đo trọng lượng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chèng | / | cân | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Căn nhà | New HSK | New HSK 7-9 | · | Ngôi nhà và cuộc sống hàng ngày I", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跺', '{"9000": "3729.0", "Chữ Trung Quốc": "跺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 13 | nét | 足 | túc | biểu nghĩa | chân | 朵 | đoá | biểu âm | 跺 = 足 (Túc, biểu nghĩa: chân) + 朵 (Đoá, biểu âm). Chữ hình thanh: bộ Túc chỉ hành động của chân; 朵 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đoá\": chân (足) giậm mạnh như bông hoa (朵) rơi xuống — 跺脚 là giậm chân tức giận. | Gương Hán-Việt | Đoá — giậm chân (跺脚: giậm chân) | Mở khoá kiến thức | Biết 跺 mở khoá 跺脚 (giậm chân), 跺足 (giậm chân — văn viết), 搓手跺脚 (sốt ruột bồn chồn).", "Tự nguyên_Xie": "Chữ hình thanh. 足 (túc, biểu nghĩa: chân) + 朵 (đoá, biểu âm). Nghĩa gốc là giậm chân (thể hiện tức giận hoặc nhịp điệu). Tiểu triện ghi nhận cấu trúc. Thường dùng trong 跺脚 (giậm chân), 搓手跺脚 (chà tay giậm chân — biểu lộ sốt ruột). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giậm chân; giẫm; đạp mạnh", "Hạng Tần Suất (Jun Da)": "3729.0", "Tần Suất % (Jun Da)": "99.6524754334", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 朵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊朵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跺", "Unihan_Traditional (Chữ Phồn thể)": "跥", "Pinyin_Xie": "duò", "Âm Hán Việt_Xie": "đóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ chỉ hành động giậm chân khi tức giận hoặc lạnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('潦', '{"9000": "3730.0", "Chữ Trung Quốc": "潦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 水 | thủy | biểu nghĩa | nước | 尞 | biểu âm | 潦 = 水 (Thủy, biểu nghĩa: nước) + 尞 (biểu âm). Chữ hình thanh: bộ Thủy liên quan đến nước; 尞 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lẻo\": nước (水) ngập lênh láng — 潦倒 (lẻo đảo: sa sút, thất thế), 潦草 (liáo cǎo: cẩu thả). | Gương Hán-Việt | Lẻo — trong 潦倒 (lẻo đảo: sa sút, thất thế), 潦草 (viết cẩu thả) | Mở khoá kiến thức | Biết 潦 mở khoá 潦倒 (sa sút, thất thế), 潦草 (cẩu thả, viết ẩu).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 水 (thủy, biểu nghĩa: nước) + 尞 (biểu âm). Đọc liáo trong 潦草 (cẩu thả, viết ẩu); đọc lǎo chỉ nước mưa đọng lại, lũ lụt. Hai cách đọc ứng với hai nghĩa khác nhau. Tiểu triện ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "viết ngoáy; viết ẩu; viết tháu", "Hạng Tần Suất (Jun Da)": "3730.0", "Tần Suất % (Jun Da)": "99.652870774", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 尞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵尞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "潦", "Unihan_Traditional (Chữ Phồn thể)": "潦", "Pinyin_Xie": "lǎo", "Âm Hán Việt_Xie": "lạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ trong từ ghép để chỉ sự cẩu thả, hời hợt hoặc viết ẩu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芹', '{"9000": "3731.0", "Chữ Trung Quốc": "芹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艹 | biểu nghĩa | cỏ, thảo mộc | 斤 | cân | biểu âm | 芹 = 艹 (thảo, biểu nghĩa: cỏ/thảo mộc) + 斤 (Cân, biểu âm). Chữ hình thanh: bộ Thảo chỉ loại thực vật; 斤 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Cần\": thảo mộc (艹) cần cắt bằng rìu cân (斤) — rau cần (芹菜) thân giòn cắt thành đoạn. | Gương Hán-Việt | Cần — trong 芹菜 (cần thái: rau cần tây), 水芹 (thủy cần: rau cần nước) | Mở khoá kiến thức | Biết 芹 mở khoá 芹菜 (rau cần tây), 水芹 (rau cần nước), 芹献 (cần hiến — lễ vật khiêm tốn, thành ngữ).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. Bộ 艸/艹 (thảo, biểu nghĩa: thảo mộc) + 斤 (cân, biểu âm). Chỉ cây cần tây (芹菜) và cần nước (水芹). Tiểu triện và Lục thư thông ghi nhận cấu trúc này. Trong tiếng Việt: cần (芹) tương ứng Hán-Việt ''cần'' — cần tây, rau cần. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "420.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (276) Cân (196)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thảo (số 80 - cỏ cây) và chữ Cân (số 195 - cái rìu) . Loài cỏ (Thảo) bị người ta dùng rìu (Cân) chặt về làm thức ăn gọi là rau cần. Giải thích sự chuyển ý: Chữ Cân (cái rìu) chỉ âm, chữ Thảo (cỏ) chỉ ý. Tên một loài thực vật (Thảo) dùng làm rau ăn (Cần). *(Biến âm Hán Việt: Cân -> Cần)*", "Nghĩa Tiếng Việt_Xie": "rau cần", "Hạng Tần Suất (Jun Da)": "3731.0", "Tần Suất % (Jun Da)": "99.6532661146", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芹", "Unihan_Traditional (Chữ Phồn thể)": "芹", "Pinyin_Xie": "qín", "Âm Hán Việt_Xie": "cần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loại rau cần hoặc dùng trong các tên món ăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('哒', '{"9000": "3732.0", "Chữ Trung Quốc": "哒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 9 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 达 | đạt | biểu âm | 哒 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 达 (Đạt, biểu âm). Chữ hình thanh: bộ Khẩu chỉ liên quan đến âm thanh/tiếng; 达 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đáp\": miệng (口) phát ra tiếng đạt đạt (达) — 哒 là âm thanh lộc cộc hay biểu tượng vui trong chat. | Gương Hán-Việt | Đáp — âm tượng thanh (哒哒: tiếng gõ lộc cộc) | Mở khoá kiến thức | Biết 哒 mở khoá ngôn ngữ mạng hiện đại: 哒哒 (tiếng gõ), hay hậu tố dễ thương 好哒 (được rồi~).", "Tự nguyên_Xie": "Không có phân tích từ nguyên chi tiết trong Wiktionary cho 哒. Từ cấu trúc: bộ 口 (khẩu) biểu nghĩa âm thanh; 达 (đạt) cho âm. Chủ yếu dùng trong tiếng lóng hiện đại: 哒哒 (tiếng gõ lộc cộc), hoặc ký hiệu vui trong tin nhắn (哒~). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng lọc cọc, tạch tạch, tí tách", "Hạng Tần Suất (Jun Da)": "3732.0", "Tần Suất % (Jun Da)": "99.6536609385", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 达", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口达", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "达", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "哒", "Unihan_Traditional (Chữ Phồn thể)": "噠", "Pinyin_Xie": "dā", "Âm Hán Việt_Xie": "đát", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Trợ từ | 助词 | Thường dùng làm từ tượng thanh mô phỏng tiếng vó ngựa, tiếng súng hoặc làm trợ từ ngữ khí ở cuối câu. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('饬', '{"9000": "3733.0", "Chữ Trung Quốc": "饬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 7 | nét | 飤 | biểu âm | 力 | lực | biểu nghĩa | sức mạnh, nỗ lực | 饬 = 飤 (biểu âm) + 力 (Lực, biểu nghĩa: sức mạnh). Chữ hình thanh: bộ Lực chỉ nỗ lực, sắp xếp; 飤 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Sức\": dùng sức (力) chỉnh đốn — 整饬 (chỉnh sức) là dọn dẹp quy củ, 申饬 là nhắc nhở nghiêm khắc. | Gương Hán-Việt | Sức — trong 整饬 (chỉnh sức: chỉnh đốn), 申饬 (thân sức: khiển trách) | Mở khoá kiến thức | Biết 饬 mở khoá 整饬 (chỉnh đốn, sắp xếp quy củ), 申饬 (nhắc nhở, khiển trách).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 飤 (biểu âm) + 力 (lực, biểu nghĩa: sức mạnh/nỗ lực). Nghĩa gốc là chỉnh đốn, sắp xếp ngăn nắp, ra lệnh. Dùng nhiều trong văn viết hành chính: 整饬 (chỉnh đốn), 申饬 (khiển trách, nhắc nhở). Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trang sức; mệnh lệnh", "Hạng Tần Suất (Jun Da)": "3733.0", "Tần Suất % (Jun Da)": "99.6540552455", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "饬", "Unihan_Traditional (Chữ Phồn thể)": "飭", "Pinyin_Xie": "chì", "Âm Hán Việt_Xie": "sức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn bản hành chính cổ để chỉ việc chỉnh đốn hoặc ban lệnh. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('栩', '{"9000": "3734.0", "Chữ Trung Quốc": "栩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 木 | mộc | biểu nghĩa | gỗ, cây | 羽 | vu | biểu âm | 栩 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 羽 (Vu, biểu âm). Chữ hình thanh: bộ Mộc chỉ loại cây; 羽 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hủ\": cây gỗ (木) rậm lá như lông chim (羽) — 栩栩如生 là sinh động như thật. | Gương Hán-Việt | Hủ — trong 栩栩如生 (hủ hủ như sinh: sinh động như thật) | Mở khoá kiến thức | Biết 栩 mở khoá thành ngữ 栩栩如生 (sinh động, sống như thật) — dùng để khen tranh, tượng, diễn xuất.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 木 (mộc, biểu nghĩa: cây/gỗ) + 羽 (vu, biểu âm). Chỉ loại cây sồi (栎/栩栎). Tiểu triện ghi nhận cấu trúc. Nay thường gặp nhất trong 栩栩如生 (sinh động như thật, sống động trước mắt) — thành ngữ phổ biến. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây hủ, cây lịch", "Hạng Tần Suất (Jun Da)": "3734.0", "Tần Suất % (Jun Da)": "99.6544490358", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "栩", "Unihan_Traditional (Chữ Phồn thể)": "栩", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "hủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ trong thành ngữ để mô tả trạng thái sống động như thật. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('曦', '{"9000": "3735.0", "Chữ Trung Quốc": "曦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 20 | nét | 日 | nhật | biểu nghĩa | mặt trời | 羲 | biểu âm | 曦 = 日 (Nhật, biểu nghĩa: mặt trời) + 羲 (biểu âm). Chữ hình thanh: bộ Nhật chỉ ánh sáng mặt trời; 羲 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Hi\": mặt trời (日) ló dạng buổi sáng — 晨曦 (thần hi) là ánh hồng bình minh. | Gương Hán-Việt | Hi — trong 晨曦 (thần hi: ánh bình minh), 朝曦 (triêu hi: ánh hồng sáng sớm) | Mở khoá kiến thức | Biết 曦 mở khoá 晨曦 (ánh bình minh), 朝曦 (ánh sáng buổi sáng) — từ thơ ca trang trọng.", "Tự nguyên_Xie": "Chữ hình thanh. 日 (nhật, biểu nghĩa: mặt trời) + 羲 (biểu âm). Chỉ ánh nắng bình minh, ánh hồng rạng đông. Thường dùng trong văn học: 晨曦 (ánh bình minh), 朝曦 (ánh hồng buổi sáng sớm). Tiểu triện ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ánh bình minh; ánh ban mai", "Hạng Tần Suất (Jun Da)": "3735.0", "Tần Suất % (Jun Da)": "99.6548423093", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 羲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日羲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "曦", "Unihan_Traditional (Chữ Phồn thể)": "曦", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ ánh sáng mặt trời buổi sớm, hay dùng trong văn chương hoặc đặt tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骷', '{"9000": "3736.0", "Chữ Trung Quốc": "骷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 14 | nét | 骨 | cốt | biểu nghĩa | xương | 古 | cổ | biểu âm | 骷 = 骨 (Cốt, biểu nghĩa: xương) + 古 (Cổ, biểu âm). Chữ hình thanh: bộ Cốt chỉ xương; 古 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khô\": xương (骨) cổ xưa (古) khô cứng — 骷髅 là đầu lâu hay bộ xương. | Gương Hán-Việt | Khô — trong 骷髅 (khô lâu: đầu lâu, bộ xương) | Mở khoá kiến thức | Biết 骷 mở khoá 骷髅 (đầu lâu, bộ xương) — thường thấy trong văn hóa, truyện ma, và biểu tượng cảnh báo.", "Tự nguyên_Xie": "Chữ hình thanh. 骨 (cốt, biểu nghĩa: xương) + 古 (cổ, biểu âm). 骷 luôn dùng cùng 髅 trong tổ hợp 骷髅 chỉ đầu lâu, bộ xương. Tiểu triện ghi nhận cấu trúc. Hình ảnh 骷髅 phổ biến trong văn hóa dân gian và y học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khô lâu 骷髏,骷髅)", "Hạng Tần Suất (Jun Da)": "3736.0", "Tần Suất % (Jun Da)": "99.655235066", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 古", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨古", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "古", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "骷", "Unihan_Traditional (Chữ Phồn thể)": "骷", "Pinyin_Xie": "kū", "Âm Hán Việt_Xie": "khô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ lâu để tạo thành danh từ chỉ xương đầu lâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫡', '{"9000": "3737.0", "Chữ Trung Quốc": "嫡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 14 | nét | 女 | nữ | biểu nghĩa | người phụ nữ | 啇 | biểu âm | 嫡 = 女 (Nữ, biểu nghĩa: người phụ nữ) + 啇 (biểu âm). Chữ hình thanh: bộ Nữ liên quan đến chế độ hôn nhân và dòng dõi; 啇 cho âm. Nghĩa gốc là vợ chính thức (chánh thê), con của vợ cả.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Đích\": người nữ (女) dòng chính — 嫡子 (đích tử) là con đích trưởng, được thừa kế. | Gương Hán-Việt | Đích — trong 嫡子 (đích tử: con vợ cả), 嫡传 (đích truyền: truyền thừa chính thống) | Mở khoá kiến thức | Biết 嫡 mở khoá 嫡子 (con vợ cả, con đích), 嫡传弟子 (học trò chính truyền), 嫡系 (hệ thống trực tiếp, cốt cán).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 女 (nữ, biểu nghĩa: người phụ nữ) + 啇 (biểu âm). Ý nghĩa gốc là vợ cả (chánh thê), khác với 庶 (thứ thiếp). Từ đó mở rộng: 嫡子 (con vợ cả), 嫡传 (truyền thống chính thống). Digital Shinjigen 2017 xác nhận ý nghĩa ''dòng huyết thống chính''. Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vợ cả", "Hạng Tần Suất (Jun Da)": "3737.0", "Tần Suất % (Jun Da)": "99.6556267891", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 啇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女啇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫡", "Unihan_Traditional (Chữ Phồn thể)": "嫡", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "đích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm định ngữ đứng trước danh từ để chỉ quan hệ huyết thống chính thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卤', '{"9000": "3738.0", "Chữ Trung Quốc": "卤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卜 | Số nét | 7 | nét | 卤 | lỗ | tượng hình | nước muối mặn, muối thô | 卤 là chữ tượng hình độc lập, gốc mô tả nước muối hay muối thô. Kim văn và Tiểu triện thể hiện hình ảnh hộp/bình đựng muối. Không phân tích thành các thành phần rõ ràng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lỗ\": hình bình muối cổ — 卤味 là thịt ướp nước muối gia vị, 卤素 là nguyên tố halogen. | Gương Hán-Việt | Lỗ — trong 卤味 (lỗ vị: thịt nước mắm/nước muối gia vị), 卤素 (lỗ tố: halogen) | Mở khoá kiến thức | Biết 卤 mở khoá 卤味 (món ăn ướp nước muối), 卤素 (halogen: flo, clo, brom...), 卤水 (nước muối đặc).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ tượng hình. Hình dạng cổ trong Kim văn gợi hình ảnh bình hoặc hộp đựng muối thô. Nghĩa gốc là nước muối đặc (nước brine), muối thô. Mở rộng: chỉ nhóm nguyên tố halogen trong hóa học (卤素), và kỹ thuật nấu thịt với nước muối gia vị (卤味). Kim văn và Tiểu triện ghi nhận hình dạng này. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đất mặn, ruộng muối", "Hạng Tần Suất (Jun Da)": "3738.0", "Tần Suất % (Jun Da)": "99.6560185122", "GavinGrover_Once (Chiết tự trực tiếp)": "⺊ + 龱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺊龱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺊", "Unihan_Simplified (Chữ Giản thể)": "卤", "Unihan_Traditional (Chữ Phồn thể)": "滷", "Pinyin_Xie": "lǔ", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ nước muối hoặc làm động từ trong phương pháp kho nấu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('丕', '{"9000": "3739.0", "Chữ Trung Quốc": "丕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 一 | Số nét | 5 | nét | 不 | bất | biểu âm | 一 | nhất | biểu nghĩa | một, nền tảng | 丕 = 不 (Bất, biểu âm) + 一 (Nhất, biểu nghĩa: nền tảng, đáy). Chữ hình thanh: 一 là nét nằm phía dưới 不, gợi ý nền tảng vững chắc; 不 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Vậy\": nền (一) đỡ lấy (不) — 丕基 (vậy cơ) là nền tảng to lớn của sự nghiệp. | Gương Hán-Việt | Vậy — trong 丕业 (vậy nghiệp: sự nghiệp vĩ đại), 丕基 (vậy cơ: nền tảng lớn) | Mở khoá kiến thức | Biết 丕 mở khoá văn ngôn cổ điển: 丕业 (sự nghiệp to lớn), 丕基 (nền tảng vĩ đại) — thường gặp trong sử liệu Hán Nôm.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh. 不 (bất, biểu âm) + 一 (nhất, biểu nghĩa: một/nền). Kim văn, Tiểu triện và Lục thư thông ghi nhận. Nghĩa gốc là vĩ đại, to lớn (丕业: sự nghiệp to lớn). Nay chủ yếu gặp trong văn ngôn và tên riêng. Trích dẫn cổ: 天下之壮观，王者之丕业 (sự nghiệp to lớn của vương giả). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lớn lao", "Hạng Tần Suất (Jun Da)": "3739.0", "Tần Suất % (Jun Da)": "99.6564102354", "GavinGrover_Once (Chiết tự trực tiếp)": "不 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱不一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "不", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "丕", "Unihan_Traditional (Chữ Phồn thể)": "丕", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong văn cổ để ca ngợi công đức hoặc sự nghiệp to lớn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鬓', '{"9000": "3740.0", "Chữ Trung Quốc": "鬓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 髟 | Số nét | 20 | nét | 髟 | biểu nghĩa | tóc dài rũ xuống | 賓 | tân | biểu âm | 鬓 = 髟 (biểu nghĩa: tóc dài, bộ tóc) + 賓 (Tân, biểu âm). Chữ hình thanh: bộ 髟 chỉ tóc; 賓 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Mấn\": tóc (髟) hai bên thái dương — 两鬓 (lưỡng mấn) là hai mái tóc, thường ám chỉ tuổi già khi bạc trắng. | Gương Hán-Việt | Mấn — trong 两鬓 (lưỡng mấn: hai mái tóc thái dương), 鬓发 (mấn phát: tóc thái dương) | Mở khoá kiến thức | Biết 鬓 mở khoá 两鬓飞霜 (tóc bạc hai bên), 鬓发 (tóc thái dương), 耳鬓厮磨 (thành ngữ chỉ gần gũi thân thiết từ nhỏ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 髟 (biểu nghĩa: tóc dài) + 賓 (tân, biểu âm). Chỉ mái tóc ở hai bên thái dương. Tiểu triện ghi nhận cấu trúc. Thường dùng trong thơ ca: 两鬓飞霜 (hai mái tóc trắng như sương), 潘鬓 (tóc bạc sớm — điển tích từ Phan Nhạc thời Tấn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tóc mai", "Hạng Tần Suất (Jun Da)": "3740.0", "Tần Suất % (Jun Da)": "99.6568019585", "GavinGrover_Once (Chiết tự trực tiếp)": "髟 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱髟宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "髟", "Unihan_Simplified (Chữ Giản thể)": "鬓", "Unihan_Traditional (Chữ Phồn thể)": "鬢", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các tính từ chỉ màu sắc để miêu tả mái tóc mai. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('梓', '{"9000": "3741.0", "Chữ Trung Quốc": "梓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 11 | nét | 木 | mộc | biểu nghĩa | cây/gỗ | 宰 | tể | biểu âm | 梓 = 木 (Mộc, biểu nghĩa: cây/gỗ) + 宰 (Tể, biểu âm rút gọn). Chữ hình thanh: bộ Mộc chỉ loài cây; 宰 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tử\": cây gỗ (木) quý — 桑梓 (tang tử) là quê hương, nơi cha mẹ trồng dâu và tử. | Gương Hán-Việt | Tử — trong 桑梓 (tang tử: quê hương), 梓里 (tử lý: làng quê) | Mở khoá kiến thức | Biết 梓 mở khoá 桑梓 (quê hương — thành ngữ thơ ca), 梓里 (làng quê), và hiểu nguồn gốc nhiều tên riêng tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 木 (mộc, biểu nghĩa: cây/gỗ) + 宰 (tể, biểu âm — rút gọn). Chỉ cây tử (梓树, Catalpa ovata) — loại cây gỗ quý. Theo truyền thống, cây tử (梓) thường trồng phía bắc sân nhà, còn cây tang (桑, dâu) trồng phía đông. Từ đó 桑梓 (tang tử) ám chỉ quê hương. Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây tử (dùng để đóng đàn; tượng trưng cho con); khắc chữ lên bản gỗ; quê cha đất tổ", "Hạng Tần Suất (Jun Da)": "3741.0", "Tần Suất % (Jun Da)": "99.6571921313", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 辛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木辛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "梓", "Unihan_Traditional (Chữ Phồn thể)": "梓", "Pinyin_Xie": "zǐ", "Âm Hán Việt_Xie": "tử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn chương để chỉ quê nhà hoặc bản khắc in. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗖', '{"9000": "3742.0", "Chữ Trung Quốc": "嗖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 叜 | biểu âm | 嗖 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 叜 (biểu âm). Chữ hình thanh: bộ Khẩu chỉ âm thanh phát ra; 叜 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tẩu\": miệng (口) phát tiếng vèo — 嗖 là âm tượng thanh khi vật bay vèo qua. | Gương Hán-Việt | Tẩu — âm tượng thanh (嗖的一声: tiếng vèo) | Mở khoá kiến thức | Biết 嗖 mở khoá ngôn ngữ mô tả chuyển động nhanh: 嗖的一声 (một tiếng vèo), 嗖嗖 (vèo vèo).", "Tự nguyên_Xie": "Không có phân tích từ nguyên chi tiết trong Wiktionary cho 嗖. Từ cấu trúc: bộ 口 (khẩu) biểu nghĩa âm thanh; 叜 cho âm. Chữ tượng thanh — mô tả âm thanh vèo vèo khi vật gì đó bay qua nhanh (như mũi tên, cơn gió). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vui cười; tiếng đuổi chim, tiếng xua chim; tiếng vèo vèo", "Hạng Tần Suất (Jun Da)": "3742.0", "Tần Suất % (Jun Da)": "99.6575812705", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 叟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口叟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗖", "Unihan_Traditional (Chữ Phồn thể)": "嗖", "Pinyin_Xie": "sōu", "Âm Hán Việt_Xie": "sưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Thường dùng làm từ tượng thanh mô tả âm thanh chuyển động nhanh của vật thể. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惦', '{"9000": "3743.0", "Chữ Trung Quốc": "惦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | trái tim, cảm xúc | 店 | điếm | biểu âm | cửa hàng, quán trọ | 惦 = 忄 (Tâm, biểu nghĩa: trái tim) + 店 (Điếm, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 心 (忄) cho nghĩa, 店 cho âm diàn. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"điếm\": trái tim (忄) như cửa hàng (店) luôn mở — lòng luôn nhớ, canh cánh không quên người thân. | Gương Hán-Việt | \"điếm\" trong 惦记 (điếm ký — nhớ nhung, canh cánh trong lòng) | Mở khoá kiến thức | Biết 惦 mở khoá 惦记 (nhớ nhung), 惦念 (nghĩ đến, lo lắng cho).", "Tự nguyên_Xie": "Chữ 惦 (điếm) là chữ hình thanh (ls=psc): bộ 忄 (Tâm — trái tim) biểu nghĩa chỉ cảm xúc nội tâm; 店 (Điếm) biểu âm cho âm diàn. Nghĩa gốc: nhớ nhung, luôn canh cánh trong lòng, không quên được. Thường dùng trong 惦记 (nhớ nhung, canh cánh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhớ", "Hạng Tần Suất (Jun Da)": "3743.0", "Tần Suất % (Jun Da)": "99.6579698929", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 店", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄店", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "店", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "惦", "Unihan_Traditional (Chữ Phồn thể)": "惦", "Pinyin_Xie": "diàn", "Âm Hán Việt_Xie": "điếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ mang tân ngữ chỉ người hoặc sự việc cần quan tâm, lo lắng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浚', '{"9000": "3744.0", "Chữ Trung Quốc": "浚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 水 | thủy | biểu nghĩa | nước | 夋 | biểu âm | 浚 = 水 (Thủy, biểu nghĩa: nước) + 夋 (biểu âm). Chữ hình thanh: bộ Thủy liên quan đến kênh rạch, sông ngòi; 夋 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tuấn\": đào sâu dưới nước (水) — 疏浚 (sơ tuấn) là nạo vét kênh rạch. | Gương Hán-Việt | Tuấn — trong 疏浚 (sơ tuấn: nạo vét kênh rạch), 浚河 (tuấn hà: nạo vét sông) | Mở khoá kiến thức | Biết 浚 mở khoá 疏浚 (nạo vét), 浚河 (nạo vét sông) — thuật ngữ xây dựng công trình thủy lợi.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. 水 (thủy, biểu nghĩa: nước) + 夋 (biểu âm). Nghĩa gốc là nạo vét, đào sâu kênh rạch hoặc giếng. Mở rộng sang nghĩa khai thác, vơ vét. Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nạo vét", "Hạng Tần Suất (Jun Da)": "3744.0", "Tần Suất % (Jun Da)": "99.6583585153", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 夋", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵夋", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夋", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浚", "Unihan_Traditional (Chữ Phồn thể)": "浚", "Pinyin_Xie": "jùn", "Âm Hán Việt_Xie": "tuấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ sông ngòi để chỉ việc khơi thông dòng chảy. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('咔', '{"9000": "3745.0", "Chữ Trung Quốc": "咔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 卡 | tạp | biểu âm | 咔 = 口 (Khẩu, biểu nghĩa: âm thanh) + 卡 (biểu âm). Chữ hình thanh: bộ Khẩu chỉ âm thanh; 卡 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khạp\": miệng (口) phát tiếng click — 咔嚓 là tiếng cắt gọn hay chụp ảnh. | Gương Hán-Việt | Khạp — âm tượng thanh (咔嚓: tiếng cắt/click) | Mở khoá kiến thức | Biết 咔 mở khoá 咔嚓 (tiếng cắt gọn, tiếng chụp ảnh), 咔哒 (tiếng click cơ khí).", "Tự nguyên_Xie": "Không có phân tích từ nguyên chi tiết trong Wiktionary cho 咔. Từ cấu trúc: bộ 口 (khẩu) biểu nghĩa âm thanh; 卡 cho âm. Chủ yếu là âm tượng thanh — tiếng click, tiếng gãy snap. Dùng trong 咔嚓 (tiếng cắt/gãy), 咔哒 (tiếng click). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ca ky 咔嘰,咔叽)", "Hạng Tần Suất (Jun Da)": "3745.0", "Tần Suất % (Jun Da)": "99.658746621", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 卡", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口卡", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "咔", "Unihan_Traditional (Chữ Phồn thể)": "咔", "Pinyin_Xie": "kā", "Âm Hán Việt_Xie": "ca", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Danh từ | 名词 | Thường dùng làm từ tượng thanh mô tả tiếng máy ảnh hoặc dùng trong từ phiên âm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藐', '{"9000": "3746.0", "Chữ Trung Quốc": "藐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 17 | nét | 艹 | thảo | biểu nghĩa | cỏ, thực vật | 貌 | mạo | biểu âm | diện mạo, bề ngoài | 藐 = 艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 貌 (Mạo, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 艸 (艹) cho nghĩa (liên quan đến cỏ cây, nhỏ bé như cỏ); 貌 cho âm miǎo. Nghĩa gốc: nhỏ bé, coi thường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miểu\": nhìn ai đó nhỏ bé như ngọn cỏ (艹) mà đánh giá qua bề ngoài (貌) — thái độ coi thường, khinh thị. | Gương Hán-Việt | \"miểu\" trong 藐视 (miểu thị — coi thường, khinh thường) | Mở khoá kiến thức | Biết 藐 mở khoá 藐视 (coi thường), 藐小 (nhỏ bé, tầm thường).", "Tự nguyên_Xie": "Chữ 藐 (miểu) là chữ hình thanh (ls=psc): bộ 艸 (艹 — Thảo) biểu nghĩa, gợi ý nhỏ bé như cỏ; 貌 (Mạo) biểu âm cho âm miǎo. Nghĩa cổ điển: nhỏ bé, trẻ con; sau mở rộng sang nghĩa coi thường, khinh thị. Tiếng Quảng Đông dùng thêm nghĩa nhún môi khinh thường. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhỏ; bé; coi thường; khinh thường; thờ ơ", "Hạng Tần Suất (Jun Da)": "3746.0", "Tần Suất % (Jun Da)": "99.6591342098", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 貌", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹貌", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "貌", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藐", "Unihan_Traditional (Chữ Phồn thể)": "藐", "Pinyin_Xie": "miǎo", "Âm Hán Việt_Xie": "miểu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước tân ngữ để biểu thị thái độ coi thường, khinh miệt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荃', '{"9000": "3747.0", "Chữ Trung Quốc": "荃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艹 | biểu nghĩa | cỏ, thảo mộc | 全 | toan | biểu âm | 荃 = 艹 (thảo, biểu nghĩa: cỏ/thảo mộc) + 全 (Toàn, biểu âm). Chữ hình thanh: bộ Thảo chỉ loại thực vật; 全 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Thuyên\": thảo mộc (艹) toàn vẹn (全) hương thơm — 荃 là cây thạch xương bồ thơm dùng trong thơ ca. | Gương Hán-Việt | Thuyên — trong 荃蹄 (thuyên đề — điển tích Trang Tử: khi đã đạt mục đích thì quên phương tiện) | Mở khoá kiến thức | Biết 荃 mở khoá điển cố 得鱼忘荃 (được cá quên nơm) từ Trang Tử — ý nghĩa sâu sắc trong triết học.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. Bộ 艸/艹 (thảo, biểu nghĩa: thảo mộc) + 全 (toàn, biểu âm). Chỉ cây thạch xương bồ (Acorus calamus) — loại cây thuốc có tác dụng kích thích nhẹ. Trong văn học cổ điển, 荃 dùng làm hình ảnh ẩn dụ (thường chỉ người hiền tài). Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ thơm; cái nơm; vải nhỏ", "Hạng Tần Suất (Jun Da)": "3747.0", "Tần Suất % (Jun Da)": "99.6595217987", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 全", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹全", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "全", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荃", "Unihan_Traditional (Chữ Phồn thể)": "荃", "Pinyin_Xie": "quán", "Âm Hán Việt_Xie": "thuyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để ẩn dụ cho người hiền tài. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唧', '{"9000": "3748.0", "Chữ Trung Quốc": "唧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 10 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 即 | tức | biểu âm | 唧 = 口 (Khẩu, biểu nghĩa: miệng/âm thanh) + 即 (Tức, biểu âm). Chữ hình thanh: bộ Khẩu chỉ loại âm thanh; 即 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tức\": miệng (口) phát tiếng chíp tức thì (即) — 唧唧喳喳 là tiếng chim huyên náo. | Gương Hán-Việt | Tức — trong 唧唧 (tức tức: tiếng chíp chíp), 唧筒 (tức thống: máy bơm) | Mở khoá kiến thức | Biết 唧 mở khoá 唧唧喳喳 (ríu rít huyên náo), 唧筒 (máy bơm piston), 唧唧复唧唧 (câu mở đầu bài Mộc Lan từ nổi tiếng).", "Tự nguyên_Xie": "Chữ hình thanh. 口 (khẩu, biểu nghĩa: âm thanh) + 即 (tức, biểu âm). Chủ yếu là âm tượng thanh: tiếng chim chíp, tiếng rít của máy bơm (唧筒). Tiểu triện ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói nỉ non", "Hạng Tần Suất (Jun Da)": "3748.0", "Tần Suất % (Jun Da)": "99.6599088707", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 即", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口即", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "即", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唧", "Unihan_Traditional (Chữ Phồn thể)": "唧", "Pinyin_Xie": "jī", "Âm Hán Việt_Xie": "tức", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Chữ này thường làm từ tượng thanh mô tả tiếng côn trùng kêu hoặc làm động từ chỉ việc nói lầm rầm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('玺', '{"9000": "3749.0", "Chữ Trung Quốc": "玺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 爾 | nhãi | biểu âm | 玉 | ngọc | biểu nghĩa | ngọc, đá quý | 玺 = 爾 (Nhãi, biểu âm) + 玉 (Ngọc, biểu nghĩa: ngọc đá quý). Chữ hình thanh: bộ Ngọc chỉ chất liệu quý; 爾 cho âm. Đây là ấn tín hoàng gia làm bằng ngọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Tỷ\": ngọc (玉) khắc ấn — 玺 là ấn ngọc tỷ của hoàng đế, biểu tượng quyền lực tối cao. | Gương Hán-Việt | Tỷ — trong 国玺 (quốc tỷ: quốc ấn), 传国玺 (truyền quốc tỷ: ấn truyền ngôi) | Mở khoá kiến thức | Biết 玺 mở khoá 国玺 (quốc ấn), 传国玺 (ấn truyền ngôi), 玺印 (ấn tín).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh. Phát triển từ 壐. 爾 (nhãi, biểu âm) + 玉 (ngọc, biểu nghĩa: ngọc đá quý). Chỉ ấn tín hoàng gia bằng ngọc. Từ thời Tần Thủy Hoàng, ấn vua gọi là 玺. Tiểu triện và Lục thư thông ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái ấn của vua; con dấu chính thức của quốc gia, quốc huy", "Hạng Tần Suất (Jun Da)": "3749.0", "Tần Suất % (Jun Da)": "99.6602959428", "GavinGrover_Once (Chiết tự trực tiếp)": "尔 + 玉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱尔玉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "玉", "Unihan_Simplified (Chữ Giản thể)": "玺", "Unihan_Traditional (Chữ Phồn thể)": "璽", "Pinyin_Xie": "xǐ", "Âm Hán Việt_Xie": "tỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ con dấu của hoàng đế, thường dùng trong các từ ghép như ngọc tỷ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汛', '{"9000": "3750.0", "Chữ Trung Quốc": "汛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 水 | thủy | biểu nghĩa | nước | 卂 | biểu âm | 汛 = 氵/水 (Thủy, biểu nghĩa: nước) + 卂 (biểu âm). Chữ hình thanh: bộ Thủy liên quan đến lũ lụt; phần còn lại cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Vàm\": nước (水) dâng mùa — 汛期 (vàm kỳ) là mùa lũ, 防汛 là phòng chống lũ. | Gương Hán-Việt | Vàm — trong 汛期 (vàm kỳ: mùa lũ), 防汛 (phòng vàm: phòng chống lũ) | Mở khoá kiến thức | Biết 汛 mở khoá 汛期 (mùa lũ), 防汛 (phòng chống lũ lụt), 洪汛 (lũ lớn).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. Bộ 水/氵(thủy) biểu nghĩa liên quan đến nước; phần biểu âm cho âm xùn. Nghĩa gốc là nước lũ theo mùa, lũ định kỳ. Còn có nghĩa cổ là vảy nước và đồn trú. Tiểu triện ghi nhận cấu trúc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước tràn; vẩy nước, té nước", "Hạng Tần Suất (Jun Da)": "3750.0", "Tần Suất % (Jun Da)": "99.6606824981", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汛", "Unihan_Traditional (Chữ Phồn thể)": "汛", "Pinyin_Xie": "xùn", "Âm Hán Việt_Xie": "tấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ mùa nước lũ dâng cao, thường đứng sau danh từ chỉ mùa như xuân tấn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('铐', '{"9000": "3751.0", "Chữ Trung Quốc": "铐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 11 | nét | 钅 | kim | biểu nghĩa | kim loại | 考 | khảo | biểu âm | 铐 = 钅(Kim, biểu nghĩa: kim loại) + 考 (Khảo, biểu âm). Chữ hình thanh: bộ Kim chỉ vật làm bằng kim loại; 考 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Khảo\": kim loại (钅) khảo tra (考) tội phạm — 手铐 (thủ khảo) là còng tay bắt tội phạm. | Gương Hán-Việt | Khảo — trong 手铐 (thủ khảo: còng tay), 脚铐 (cước khảo: còng chân) | Mở khoá kiến thức | Biết 铐 mở khoá 手铐 (còng tay), 脚铐 (còng chân), 铐住 (còng lại, xiềng lại).", "Tự nguyên_Xie": "Chữ hình thanh. 钅(kim, biểu nghĩa: kim loại) + 考 (khảo, biểu âm). Chỉ còng tay, xích tay. Tiểu triện ghi nhận cấu trúc. Dùng trong 手铐 (còng tay), 铐住 (còng lại). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái cùm, cái còng; cùm tay, khoá tay", "Hạng Tần Suất (Jun Da)": "3751.0", "Tần Suất % (Jun Da)": "99.6610690534", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 考", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅考", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "考", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "铐", "Unihan_Traditional (Chữ Phồn thể)": "銬", "Pinyin_Xie": "kào", "Âm Hán Việt_Xie": "khảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái còng tay hoặc làm động từ khi kết hợp với tân ngữ chỉ người bị còng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('髅', '{"9000": "3752.0", "Chữ Trung Quốc": "髅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 骨 | Số nét | 18 | nét | 骨 | cốt | biểu nghĩa | xương | 娄 | lâu | biểu âm | 髅 = 骨 (Cốt, biểu nghĩa: xương) + 娄 (Lâu, biểu âm). Chữ hình thanh: bộ Cốt chỉ xương; 娄 cho âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"Lâu\": xương (骨) lâu ngày — 骷髅 (khô lâu) là đầu lâu hay bộ xương người. | Gương Hán-Việt | Lâu — trong 骷髅 (khô lâu: đầu lâu, bộ xương), 髑髅 (độc lâu: đầu lâu văn ngôn) | Mở khoá kiến thức | Biết 髅 mở khoá 骷髅 (đầu lâu) — biểu tượng văn hóa đại chúng và cảnh báo nguy hiểm.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh. 骨 (cốt, biểu nghĩa: xương) + 娄 (lâu, biểu âm). 髅 luôn dùng trong tổ hợp 骷髅 (đầu lâu, bộ xương) và 髑髅 (đầu lâu). Tiểu triện ghi nhận cấu trúc. Hình ảnh 骷髅 xuất hiện phổ biến trong văn hóa và cảnh báo nguy hiểm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đầu lâu người chết", "Hạng Tần Suất (Jun Da)": "3752.0", "Tần Suất % (Jun Da)": "99.6614550919", "GavinGrover_Once (Chiết tự trực tiếp)": "骨 + 娄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰骨娄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "娄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "骨", "Unihan_Simplified (Chữ Giản thể)": "髅", "Unihan_Traditional (Chữ Phồn thể)": "髏", "Pinyin_Xie": "lóu", "Âm Hán Việt_Xie": "lâu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ xương đầu người chết, thường xuất hiện trong từ ghép khô lâu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渤', '{"9000": "3753.0", "Chữ Trung Quốc": "渤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 勃 | bột | biểu âm | 渤 = 水 (Thủy, biểu nghĩa: nước) + 勃 (Bột, biểu âm); chữ hình thanh. Bộ thủy chỉ liên quan đến nước, còn 勃 cho âm đọc gần với bó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bọt\": nước (水) sôi cuồn cuộn như bọt — đó chính là vịnh Bột Hải dậy sóng. | Gương Hán-Việt | bọt trong 渤海 (Bột Hải — Vịnh Bột Hải) | Mở khoá kiến thức | Biết 渤 mở khoá địa danh 渤海 (Vịnh Bột Hải) và tính từ văn chương ''sóng cuồn cuộn''.", "Tự nguyên_Xie": "Lục thư thông | Theo Wiktionary, 渤 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''nước'', còn 勃 biểu âm. Chữ dùng chủ yếu làm tên riêng cho Vịnh Bột Hải (渤海) ở phía bắc Trung Quốc, ngoài ra còn có nghĩa văn chương là ''sóng dâng cao, cuồn cuộn''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vịnh, chỗ biển chia ngành khác", "Hạng Tần Suất (Jun Da)": "3753.0", "Tần Suất % (Jun Da)": "99.6618400968", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 勃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵勃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "勃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渤", "Unihan_Traditional (Chữ Phồn thể)": "渤", "Pinyin_Xie": "bó", "Âm Hán Việt_Xie": "bột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ riêng chỉ vịnh Bột Hải hoặc làm tính từ mô tả trạng thái nước dâng cuồn cuộn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皿', '{"9000": "3754.0", "Chữ Trung Quốc": "皿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 5 | nét | 皿 | mãnh | tượng hình | cái mâm, đồ đựng | 皿 là chữ tượng hình độc lập — phác hoạ hình dáng một chiếc mâm hoặc chén rỗng nhìn từ trên, hai cạnh bên là thành bình, nét ngang trên là miệng, nét ngang dưới là đáy. Không có bộ phận biểu âm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mãnh\": hình vẽ cái mâm nhìn từ trên — hai thành bên, miệng trên, đáy dưới, giữa rỗng chứa đồ ăn. | Gương Hán-Việt | mãnh trong 器皿 (khí mãnh — đồ đựng, dụng cụ) | Mở khoá kiến thức | Biết 皿 mở khoá bộ 皿 — bộ thủ của hàng chục chữ liên quan đến đồ đựng: 益, 盘, 盖, 盛, 盟.", "Tự nguyên_Xie": "Theo Wiktionary, 皿 là chữ tượng hình (象形): vẽ hình một đồ đựng rỗng như chén hay đài rượu. Trong chữ hiện đại, hai tay cầm đã nhập vào thành một. Chữ cổ giáp cốt và kim văn đã có hình dạng tương tự. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "98.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Chữ đơn thể / Nét căn bản", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Hình cái dụng cụ đựng thức ăn hoặc nước uống.", "Nghĩa Tiếng Việt_Xie": "cái mâm", "Hạng Tần Suất (Jun Da)": "3754.0", "Tần Suất % (Jun Da)": "99.6622251017", "GavinGrover_Once (Chiết tự trực tiếp)": "𦉫 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱𦉫一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦉫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "皿", "Unihan_Traditional (Chữ Phồn thể)": "皿", "Pinyin_Xie": "mǐn", "Âm Hán Việt_Xie": "mãnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các loại đồ dùng để đựng thức ăn, nước uống nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箍', '{"9000": "3755.0", "Chữ Trung Quốc": "箍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 㧜 | biểu âm | 箍 = 竹 (Trúc, biểu nghĩa: tre) + 㧜 (biểu âm); chữ hình thanh. Bộ trúc chỉ vật liệu bằng tre, vì đai cạp thùng truyền thống thường làm bằng tre.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: hình dung bộ 竹 (tre) làm cái đai siết chặt cái thùng — đó là 箍, cái đai tre. | Gương Hán-Việt | cô trong các từ kỹ thuật 箍筋 (cốt đai trong xây dựng) | Mở khoá kiến thức | Biết 箍 mở khoá từ kỹ thuật xây dựng 箍筋 (cốt đai, stirrup) và từ dân gian về đồ vật bịt đai.", "Tự nguyên_Xie": "Theo Wiktionary, 箍 là chữ hình thanh: bộ 竹 (trúc) biểu nghĩa vật liệu tre, còn 㧜 biểu âm. Nghĩa gốc là cái đai, cái cạp làm bằng tre để buộc chặt thùng hoặc vật tròn. Mở rộng sang nghĩa động từ ''đai lại, buộc chặt''. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái đai tre, cạp tre", "Hạng Tần Suất (Jun Da)": "3755.0", "Tần Suất % (Jun Da)": "99.6626090731", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 㧜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮㧜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㧜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箍", "Unihan_Traditional (Chữ Phồn thể)": "箍", "Pinyin_Xie": "gū", "Âm Hán Việt_Xie": "cô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái đai niềng hoặc làm động từ chỉ hành động bó chặt vật gì đó. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馅', '{"9000": "3756.0", "Chữ Trung Quốc": "馅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 11 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn | 臽 | hãm | biểu âm | hầm, hố bẫy | 馅 = 饣 (Thực, biểu nghĩa: thức ăn) + 臽 (Hãm, biểu âm). Đây là dạng giản thể của 餡 (phồn thể). Wiktionary xác nhận là 馅 là giản thể của 餡 — không có phân tích ls riêng, nhưng cấu trúc phono-semantic rõ ràng: 食 (饣) cho nghĩa, 臽 cho âm xiàn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hãm\": thức ăn (饣) bị nhốt vào hầm bẫy (臽) — đó là phần nhân bánh được giấu bên trong. | Gương Hán-Việt | \"hãm\" trong 馅料 (hãm liệu — nguyên liệu làm nhân); 饺子馅 (nhân sủi cảo) | Mở khoá kiến thức | Biết 馅 mở khoá 馅料 (nhân bánh), 饺子馅 (nhân sủi cảo), 馅饼 (bánh nhân).", "Tự nguyên_Xie": "Chữ 馅 (hãm) là dạng giản thể của 餡, gồm bộ 食 (饣 — Thực) biểu nghĩa chỉ thức ăn; 臽 (Hãm) biểu âm cho âm xiàn. Nghĩa gốc: nhân bánh — phần thức ăn được nhét vào bên trong. Hình ảnh bộ 食 với phần nhân (臽 — cái hố/hầm) gợi ý thứ được bọc kín bên trong. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhân bánh", "Hạng Tần Suất (Jun Da)": "3756.0", "Tần Suất % (Jun Da)": "99.6629925276", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + 臽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣臽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "饣", "Unihan_Simplified (Chữ Giản thể)": "馅", "Unihan_Traditional (Chữ Phồn thể)": "餡", "Pinyin_Xie": "xiàn", "Âm Hán Việt_Xie": "hãm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ phần nhân bên trong các loại bánh hoặc sủi cảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汾', '{"9000": "3757.0", "Chữ Trung Quốc": "汾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 水 | thủy | biểu nghĩa | nước, sông | 分 | phân | biểu âm | chia | 汾 = 水 (Thủy, biểu nghĩa: nước/sông) + 分 (Phân, biểu âm); chữ hình thanh. Bộ thủy chỉ đây là tên sông, còn 分 cho âm đọc fén.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phần\": sông (水) mang âm 分 (phân) — sông Phần (汾河) chia đôi đất Sơn Tây. | Gương Hán-Việt | phần trong 汾河 (Phần Hà — sông Phần, Sơn Tây) | Mở khoá kiến thức | Biết 汾 mở khoá địa danh lịch sử 汾河, 汾阳, 汾酒 (rượu Phần nổi tiếng Trung Quốc).", "Tự nguyên_Xie": "Theo Wiktionary, 汾 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''sông'', còn 分 biểu âm. Chữ dùng làm tên riêng của sông Phần (汾河) chảy qua tỉnh Sơn Tây, Trung Quốc — một trong những con sông lịch sử quan trọng nhất của Hoa Bắc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Phần", "Hạng Tần Suất (Jun Da)": "3757.0", "Tần Suất % (Jun Da)": "99.6633754654", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 分", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵分", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "分", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汾", "Unihan_Traditional (Chữ Phồn thể)": "汾", "Pinyin_Xie": "fén", "Âm Hán Việt_Xie": "phần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng chỉ sông Phần Hà ở tỉnh Sơn Tây, Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戍', '{"9000": "3758.0", "Chữ Trung Quốc": "戍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 6 | nét | 人 | nhân | biểu nghĩa | người | 戈 | qua | biểu nghĩa | giáo, vũ khí | 戍 = 人 (Nhân: người) + 戈 (Qua: giáo); chữ hội ý. Hình ảnh người lính cầm giáo đứng gác — ý nghĩa ''canh giữ biên ải'' hiện ra rõ ràng qua sự kết hợp này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thú\": người (人) cầm giáo (戈) đứng thú (canh gác biên giới) — lính thú nơi xa. | Gương Hán-Việt | thú trong 戍边 (thú biên — lính canh biên cương), 戍守 (thú thủ — đóng giữ) | Mở khoá kiến thức | Biết 戍 mở khoá từ lịch sử/văn học 戍边, 戍卒, 边戍 thường gặp trong thơ Đường.", "Tự nguyên_Xie": "Theo Wiktionary, 戍 là chữ hội ý: 人 (nhân — người) kết hợp với 戈 (qua — vũ khí dạng giáo). Hình tượng người lính cầm vũ khí đứng canh gác. Nghĩa gốc là ''lính thú, canh giữ biên cương''; mở rộng sang ''đồn trú, đóng quân''. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lính thú", "Hạng Tần Suất (Jun Da)": "3758.0", "Tần Suất % (Jun Da)": "99.6637584032", "GavinGrover_Once (Chiết tự trực tiếp)": "戊 + 丶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戊丶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "丶", "Unihan_Simplified (Chữ Giản thể)": "戍", "Unihan_Traditional (Chữ Phồn thể)": "戍", "Pinyin_Xie": "shù", "Âm Hán Việt_Xie": "thú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ việc đi lính canh gác biên cương hoặc làm danh từ chỉ người lính thú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('痔', '{"9000": "3759.0", "Chữ Trung Quốc": "痔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 疒 | biểu nghĩa | bệnh tật | 寺 | tự | biểu âm | chùa | 痔 = 疒 (bộ chỉ bệnh tật, biểu nghĩa) + 寺 (Tự, biểu âm); chữ hình thanh. Bộ 疒 xác định đây là một loại bệnh, còn 寺 cung cấp âm đọc zhì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trĩ\": bộ bệnh (疒) cộng với chùa (寺 — tự) — nhớ câu đùa ''bệnh trĩ như ngồi trên tháp chùa''. | Gương Hán-Việt | trĩ trong 痔疮 (trĩ sang — bệnh trĩ), 内痔 (nội trĩ), 外痔 (ngoại trĩ) | Mở khoá kiến thức | Biết 痔 mở khoá từ y học 痔疮, 内痔, 外痔, 混合痔.", "Tự nguyên_Xie": "Theo Wiktionary, 痔 là chữ hình thanh: bộ 疒 biểu nghĩa ''bệnh'', còn 寺 (tự) biểu âm. Nghĩa duy nhất là bệnh trĩ (hemorrhoid) — các búi tĩnh mạch bị giãn nở ở hậu môn hoặc trực tràng. Âm zhì gần với 寺 (tự). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trĩ (bệnh loét ở hậu môn)", "Hạng Tần Suất (Jun Da)": "3759.0", "Tần Suất % (Jun Da)": "99.664141341", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 寺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒寺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "寺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "痔", "Unihan_Traditional (Chữ Phồn thể)": "痔", "Pinyin_Xie": "zhì", "Âm Hán Việt_Xie": "trĩ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bệnh trĩ ở vùng hậu môn của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褶', '{"9000": "3760.0", "Chữ Trung Quốc": "褶", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 16 | nét | 褶 | chấp | tượng hình | nếp gấp vải, nếp nhăn | 褶 thuộc bộ 衣 (áo) — anchor không cung cấp dữ liệu cấu trúc chi tiết. Dựa theo hình thức, đây là chữ hình thanh với bộ 衤 (áo, biểu nghĩa) và phần còn lại biểu âm, chỉ nếp gấp trên vải. Chưa có nguồn học thuật xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấp\": bộ áo (衤) nhăn nhúm — chữ 褶 vẽ đúng cái nếp gấp trên tà áo. | Gương Hán-Việt | chấp trong 褶皱 (chấp trứu — nếp nhăn, nếp gấp) | Mở khoá kiến thức | Biết 褶 mở khoá từ 褶皱 (nếp nhăn địa tầng trong địa chất và trên vải), 褶裥 (nếp gấp áo).", "Tự nguyên_Xie": "Anchor Wiktionary không có dữ liệu cấu trúc cho 褶. Dựa theo bộ 衤 (衣 — áo, vải), chữ liên quan đến trang phục. Nghĩa chính là nếp gấp, nếp nhăn trên vải hoặc quần áo; cũng dùng chỉ loại quần ngắn để cưỡi ngựa trong văn cổ. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quần để cưỡi ngựa", "Hạng Tần Suất (Jun Da)": "3760.0", "Tần Suất % (Jun Da)": "99.664523762", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 習", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤習", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "習", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褶", "Unihan_Traditional (Chữ Phồn thể)": "褶", "Pinyin_Xie": "zhě", "Âm Hán Việt_Xie": "triệp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ các nếp gấp trên trang phục hoặc địa chất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('聆', '{"9000": "3761.0", "Chữ Trung Quốc": "聆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 耳 | Số nét | 11 | nét | 聆 | linh | tượng hình | lắng nghe chăm chú | 聆 thuộc bộ 耳 (tai) — anchor không cung cấp cây cấu trúc. Chữ có bộ 耳 (nhĩ — tai, biểu nghĩa) kết hợp phần biểu âm, chỉ hành động lắng nghe chú tâm. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": tai (耳) tinh như chuông (linh — linh động, linh thiêng) — lắng nghe từng âm thanh nhỏ nhất. | Gương Hán-Việt | linh trong 聆听 (linh thính — lắng nghe chú tâm) | Mở khoá kiến thức | Biết 聆 mở khoá từ trang trọng 聆听, 聆教 (lắng nghe lời dạy).", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc chữ viết chi tiết cho 聆. Chữ thuộc bộ 耳 (nhĩ — tai), mang nghĩa ''lắng nghe cẩn thận, chú tâm tiếp nhận''. Đây là từ văn chương, trang trọng hơn 听 (tīng). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đã nghe, tiếp thu, lĩnh ý", "Hạng Tần Suất (Jun Da)": "3761.0", "Tần Suất % (Jun Da)": "99.6649056662", "GavinGrover_Once (Chiết tự trực tiếp)": "耳 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰耳令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "耳", "Unihan_Simplified (Chữ Giản thể)": "聆", "Unihan_Traditional (Chữ Phồn thể)": "聆", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ âm thanh hoặc lời nói để thể hiện sự lắng nghe. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涎', '{"9000": "3762.0", "Chữ Trung Quốc": "涎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 水 | thủy | biểu nghĩa | nước | 延 | diên | biểu âm | kéo dài | 涎 = 水 (Thủy, biểu nghĩa: nước, chất lỏng) + 延 (Diên, biểu âm); chữ hình thanh. Bộ thủy chỉ đây là chất lỏng, còn 延 cho âm xián.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: nước (水) kéo dài (延 — diên) chảy ra — đó là nước dãi 涎 khi thèm ăn. | Gương Hán-Việt | diên trong 垂涎 (thùy diên — chảy dãi, thèm muốn) | Mở khoá kiến thức | Biết 涎 mở khoá thành ngữ 垂涎三尺 (thèm đến chảy dãi dài ba thước), 垂涎欲滴.", "Tự nguyên_Xie": "Theo Wiktionary, 涎 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''chất lỏng'', còn 延 (diên) biểu âm. Nghĩa gốc là nước dãi, nước bọt chảy ra từ miệng. Thường dùng trong văn chương để chỉ thèm muốn (垂涎 — chảy dãi, thèm thuồng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1695.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (082) Diên (531)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thủy (số 082 - dòng nước/ 氵/chỉ ý) ở bên trái chữ Diên (số 531 - kéo dài/ 延 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Diên chỉ âm, bộ Thủy chỉ ý. Diên là nước miếng, nước dãi chảy ra từ miệng kéo dài ròng ròng (thùy diên - rỏ rãi). Biểu thị sự thèm thuồng tột độ.", "Nghĩa Tiếng Việt_Xie": "nước dãi, nước bọt", "Hạng Tần Suất (Jun Da)": "3762.0", "Tần Suất % (Jun Da)": "99.6652870536", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涎", "Unihan_Traditional (Chữ Phồn thể)": "㳄", "Pinyin_Xie": "xián", "Âm Hán Việt_Xie": "tiên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ nước bọt hoặc kết hợp thành động từ chỉ sự thèm luồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汞', '{"9000": "3763.0", "Chữ Trung Quốc": "汞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 工 | công | biểu âm | 水 | thủy | biểu nghĩa | nước, chất lỏng | 汞 = 工 (Công, biểu âm) + 水 (Thủy, biểu nghĩa: kim loại lỏng); chữ hình thanh. Bộ 水 chỉ đây là chất lỏng, còn 工 biểu âm. Đây là chữ chỉ thuỷ ngân — kim loại duy nhất ở dạng lỏng trong điều kiện thường.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: công (工) cộng nước (水) — thuỷ ngân, kim loại kỳ lạ chảy lỏng như nước dùng trong công nghiệp. | Gương Hán-Việt | cống trong 汞中毒 (cống trung độc — ngộ độc thuỷ ngân) | Mở khoá kiến thức | Biết 汞 mở khoá từ hoá học 汞中毒 (ngộ độc thuỷ ngân), 水银 (cách gọi dân gian), 汞灯 (đèn hơi thuỷ ngân).", "Tự nguyên_Xie": "Theo Wiktionary, 汞 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''chất lỏng'', còn 工 biểu âm. Nghĩa duy nhất là thuỷ ngân (mercury, Hg) — nguyên tố kim loại lỏng. Tên gọi 汞 phản ánh tính chất đặc biệt: kim loại (工 gợi ý tính kỹ thuật) nhưng lại ở dạng nước (水). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thuỷ ngân", "Hạng Tần Suất (Jun Da)": "3763.0", "Tần Suất % (Jun Da)": "99.6656684411", "GavinGrover_Once (Chiết tự trực tiếp)": "工 + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱工水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "水", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "工", "Unihan_Simplified (Chữ Giản thể)": "汞", "Unihan_Traditional (Chữ Phồn thể)": "汞", "Pinyin_Xie": "gǒng", "Âm Hán Việt_Xie": "cống", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nguyên tố hóa học thủy ngân, thường đứng độc lập hoặc làm định ngữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('渍', '{"9000": "3764.0", "Chữ Trung Quốc": "渍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 水 | thủy | biểu nghĩa | nước | 責 | trách | biểu âm | trách nhiệm | 渍 = 水 (Thủy, biểu nghĩa: nước/ngấm) + 責 (Trách, biểu âm); chữ hình thanh. Bộ 水 chỉ liên quan đến chất lỏng ngấm vào, còn 責 cho âm zì.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: nước (水) đòi trách nhiệm (責 — trách) — để áo ngấm nước mãi thành vết ố khó rửa. | Gương Hán-Việt | tí trong 污渍 (ô tí — vết bẩn, vết ố) | Mở khoá kiến thức | Biết 渍 mở khoá từ 污渍 (vết bẩn), 油渍 (vết dầu), 水渍 (vết nước).", "Tự nguyên_Xie": "Theo Wiktionary, 渍 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''nước'', còn 責 biểu âm. Đáng chú ý phần biểu âm 責 bản thân cũng có phần biểu âm 朿. Nghĩa gốc là thấm ướt, ngâm; mở rộng sang vết bẩn bám vào, vết ố. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thấm; ngấm; ngâm; bám; dính", "Hạng Tần Suất (Jun Da)": "3764.0", "Tần Suất % (Jun Da)": "99.6660493117", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 责", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵责", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "责", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "渍", "Unihan_Traditional (Chữ Phồn thể)": "漬", "Pinyin_Xie": "zì", "Âm Hán Việt_Xie": "tí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ việc ngâm, thấm nước hoặc làm danh từ chỉ vết bẩn đọng lại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('奂', '{"9000": "3765.0", "Chữ Trung Quốc": "奂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 大 | Số nét | 7 | nét | 夐 | biểu âm | 廾 | trấp | biểu nghĩa | hai tay | 奂 = 夐 (biểu âm, rút gọn) + 廾 (Trấp, biểu nghĩa: hai tay); chữ hình thanh. Phần trên vừa cho âm vừa gợi ý quyền uy (mắt + gậy cầm tay), hai tay ở dưới tượng trưng cho sự dâng cao, rực rỡ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: hai tay (廾 — trấp) nâng cao vẻ đẹp rực rỡ — chữ 奂 chỉ vẻ đẹp tráng lệ xuất sắc. | Gương Hán-Việt | hoán trong 美轮美奂 (mỹ luân mỹ hoán — tráng lệ, lộng lẫy) | Mở khoá kiến thức | Biết 奂 gần như chỉ dùng trong thành ngữ 美轮美奂 — mở khoá thành ngữ này dùng khi khen kiến trúc đẹp.", "Tự nguyên_Xie": "Theo Wiktionary, 奂 là chữ hình thanh rút gọn: phần trên từ 夐 (biểu âm, rút gọn) chứa hình ảnh mắt và gậy quyền uy; phần dưới là 廾 (hai tay). Tổng thể gợi ý sự cao quý, rực rỡ. Nghĩa là ''rực rỡ, thịnh vượng, xuất sắc''. Thường gặp trong thành ngữ 美轮美奂 (đẹp và tráng lệ). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rực rỡ; thịnh", "Hạng Tần Suất (Jun Da)": "3765.0", "Tần Suất % (Jun Da)": "99.6664301823", "GavinGrover_Once (Chiết tự trực tiếp)": "⺈ + 央", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺈央", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺈", "Unihan_Simplified (Chữ Giản thể)": "奂", "Unihan_Traditional (Chữ Phồn thể)": "奐", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường dùng làm tính từ trong các từ ghép văn học để miêu tả sự lộng lẫy, nguy nga. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('巅', '{"9000": "3766.0", "Chữ Trung Quốc": "巅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 19 | nét | 山 | sơn | biểu nghĩa | núi | 顛 | điên | biểu âm | 巅 = 山 (Sơn, biểu nghĩa: núi) + 顛 (Điên, biểu âm); chữ hình thanh. Bộ 山 xác định đây liên quan đến núi, còn 顛 cho âm diān.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: núi (山 — sơn) mà điên đảo (顛 — điên) tức là đầu trên cùng của núi — đỉnh 巅. | Gương Hán-Việt | điên trong 巅峰 (điên phong — đỉnh cao nhất, đỉnh peak) | Mở khoá kiến thức | Biết 巅 mở khoá từ phổ biến 巅峰 (đỉnh cao, đỉnh peak) dùng rộng rãi trong tiếng Trung hiện đại.", "Tự nguyên_Xie": "Theo Wiktionary, 巅 là chữ hình thanh: bộ 山 (sơn) biểu nghĩa ''núi'', còn 顛 biểu âm. Nghĩa là đỉnh núi, chỏm cao nhất của núi. Mở rộng nghĩa trừu tượng ''đỉnh cao nhất'' trong mọi lĩnh vực (巅峰 — đỉnh phong). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đỉnh núi, chỏm núi", "Hạng Tần Suất (Jun Da)": "3766.0", "Tần Suất % (Jun Da)": "99.666811053", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 颠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱山颠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "颠", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "巅", "Unihan_Traditional (Chữ Phồn thể)": "巔", "Pinyin_Xie": "diān", "Âm Hán Việt_Xie": "điên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ đỉnh núi hoặc điểm cao nhất, thường đứng sau danh từ chỉ núi non. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疣', '{"9000": "3767.0", "Chữ Trung Quốc": "疣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 9 | nét | 疒 | biểu nghĩa | bệnh tật | 尤 | vưu | biểu âm | đặc biệt, nổi bật | 疣 = 疒 (bộ bệnh tật, biểu nghĩa) + 尤 (Vưu, biểu âm); chữ hình thanh. Bộ 疒 xác định đây là bệnh, còn 尤 cho âm yóu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vưu\": bệnh (疒) mà vưu vít (尤 — vưu: đặc biệt) nổi lên — mụn cóc nhô lên nổi bật trên da. | Gương Hán-Việt | vưu trong 疣赘 (vưu trụy — mụn cóc, u thịt thừa) | Mở khoá kiến thức | Biết 疣 mở khoá từ y học 疣赘, 扁平疣 (mụn cóc phẳng), 跖疣 (mụn cóc gan bàn chân).", "Tự nguyên_Xie": "Theo Wiktionary, 疣 là chữ hình thanh: bộ 疒 biểu nghĩa ''bệnh'', còn 尤 (vưu) biểu âm. Nghĩa là cục u nhỏ, mụn cóc (wart) — khối thịt nhô ra trên da do virus gây ra. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bướu", "Hạng Tần Suất (Jun Da)": "3767.0", "Tần Suất % (Jun Da)": "99.6671919236", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 尤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒尤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疣", "Unihan_Traditional (Chữ Phồn thể)": "疣", "Pinyin_Xie": "yóu", "Âm Hán Việt_Xie": "vưu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các nốt mụn, bướu lồi trên da. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傩', '{"9000": "3768.0", "Chữ Trung Quốc": "傩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 亻 | biểu nghĩa | người | 難 | nan | biểu âm | khó khăn | 傩 = 亻(bộ người, biểu nghĩa) + 難 (Nan, biểu âm); chữ hình thanh. Bộ người chỉ đây là nghi lễ do người thực hiện, còn 難 cho âm nuó.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: người (亻) múa nan giải (難 — nan) những điều khó khăn — lễ傩xua đuổi bệnh tật tai ương. | Gương Hán-Việt | noa trong 傩戏 (noa hí — hí kịch trừ tà), 傩舞 (noa vũ — điệu múa trừ tà) | Mở khoá kiến thức | Biết 傩 mở khoá từ văn hoá dân gian 傩戏, 傩舞, 傩面具 (mặt nạ傩).", "Tự nguyên_Xie": "Theo Wiktionary, 傩 là chữ hình thanh: bộ 亻 (nhân — người) biểu nghĩa, còn 難 (nan) biểu âm. Nghĩa là nghi lễ đuổi tà khí, cầu bình an — một loại nghi thức cổ đại Trung Quốc trong đó người mặc mặt nạ múa nhảy để xua đuổi dịch bệnh và tà ma. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lễ cầu mát", "Hạng Tần Suất (Jun Da)": "3768.0", "Tần Suất % (Jun Da)": "99.6675722775", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 难", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻难", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "难", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傩", "Unihan_Traditional (Chữ Phồn thể)": "儺", "Pinyin_Xie": "nuó", "Âm Hán Việt_Xie": "na", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các nghi lễ hoặc điệu múa dân gian xua đuổi tà ma. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('逵', '{"9000": "3769.0", "Chữ Trung Quốc": "逵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 11 | nét | 辵 | biểu nghĩa | đi lại | 坴 | biểu âm | 逵 = 辵 (bộ đi lại, biểu nghĩa) + 坴 (biểu âm); chữ hình thanh. Bộ 辵 (chạc — đi lại, đường xá) chỉ đây liên quan đến đường, còn 坴 cho âm kuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: đường (辵) thông mọi hướng — 逵 là đường cái lớn nối nhiều nơi. | Gương Hán-Việt | quỳ trong 九逵 (cửu quỳ — chín con đường lớn, chỉ kinh đô) | Mở khoá kiến thức | Biết 逵 mở khoá thành ngữ văn cổ 九逵 (đường lớn kinh đô) và tên riêng Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 逵 là chữ hình thanh: bộ 辵 biểu nghĩa ''đường đi, di chuyển'', còn 坴 biểu âm. Nghĩa là con đường lớn thông ra nhiều hướng, ngã năm ngã chín. Chữ văn chương, ít dùng trong tiếng Trung hiện đại. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con đường lớn thông ra mọi hướng", "Hạng Tần Suất (Jun Da)": "3769.0", "Tần Suất % (Jun Da)": "99.6679526314", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 坴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶坴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "坴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "逵", "Unihan_Traditional (Chữ Phồn thể)": "逵", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "quỳ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ ngã đường lớn thông suốt nhiều ngả, thường dùng trong văn viết hoặc tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('耆', '{"9000": "3770.0", "Chữ Trung Quốc": "耆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 老 | Số nét | 10 | nét | 老 | lão | biểu nghĩa | già | 旨 | chỉ | biểu âm | ý chỉ | 耆 = 老 (Lão, biểu nghĩa: già) + 旨 (Chỉ, biểu âm); chữ hình thanh. Bộ 老 xác định liên quan đến người già, còn 旨 cho âm qí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: già (老 — lão) mang chỉ dụ (旨 — chỉ) — bậc耆là người già đáng kính, lời nói như chiếu chỉ. | Gương Hán-Việt | kỳ trong 耆老 (kỳ lão — bô lão, bậc lão thành) | Mở khoá kiến thức | Biết 耆 mở khoá từ trang trọng 耆老, 耆宿 (lão thành có kinh nghiệm lâu năm).", "Tự nguyên_Xie": "Theo Wiktionary, 耆 là chữ hình thanh: bộ 老 (lão) biểu nghĩa ''già'', còn 旨 (chỉ) biểu âm. Nghĩa là bô lão, người cao tuổi (trên sáu mươi tuổi). Chữ văn chương, dùng trong 耆老 (bô lão), 耆宿 (bậc lão thành). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bô lão (người trên sáu mươi tuổi)", "Hạng Tần Suất (Jun Da)": "3770.0", "Tần Suất % (Jun Da)": "99.6683324684", "GavinGrover_Once (Chiết tự trực tiếp)": "老 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱老日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "老", "Unihan_Simplified (Chữ Giản thể)": "耆", "Unihan_Traditional (Chữ Phồn thể)": "耆", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ người cao tuổi hoặc tính từ chỉ sự già cả, tôn kính. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟋', '{"9000": "3771.0", "Chữ Trung Quốc": "蟋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 蟋 | tất | tượng hình | một phần của tên côn trùng 蟋蟀 (dế mèn) | 蟋 không có cấu trúc compound trong anchor. Chữ thuộc bộ 虫 (trùng — côn trùng) và chỉ dùng trong tổ hợp 蟋蟀 (dế mèn). Anchor không cung cấp cây thành phần chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tất\": 蟋 chỉ sống trong cặp với 蟀 — cùng nhau họp thành 蟋蟀 (dế mèn kêu tất tất). | Gương Hán-Việt | tất trong 蟋蟀 (tất suất — dế mèn) | Mở khoá kiến thức | Biết 蟋 mở khoá từ 蟋蟀 — con dế, biểu tượng văn hoá thu tàn trong thơ Trung Quốc.", "Tự nguyên_Xie": "Anchor Wiktionary không có dữ liệu nguồn gốc chữ viết chi tiết cho 蟋. Chữ chỉ dùng trong tổ hợp 蟋蟀 (xī shuài — dế mèn). Chưa thấy hình trong giáp cốt/kim văn; đây là chữ tạo muộn trong hệ thống chữ Hán. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1667.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (142) Tất (1666)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 142 - côn trùng/ 虫 /chỉ ý) ở bên trái chữ Tất (số 1666 - rõ ràng/ 悉 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tất chỉ âm, bộ Trùng chỉ ý. Tất là tên một loài côn trùng (tất xuất).", "Nghĩa Tiếng Việt_Xie": "(xem: tất suất 蟋蟀)", "Hạng Tần Suất (Jun Da)": "3771.0", "Tần Suất % (Jun Da)": "99.6687117887", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 悉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫悉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "悉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟋", "Unihan_Traditional (Chữ Phồn thể)": "蟋", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "tất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ dùng làm danh từ khi kết hợp với chữ khác để chỉ con dế mèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳄', '{"9000": "3772.0", "Chữ Trung Quốc": "鳄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 魚 | ngư | biểu nghĩa | cá, loài thuỷ sinh | 噩 | biểu âm | 鳄 = 魚 (Ngư, biểu nghĩa: loài thuỷ sinh/bò sát dưới nước) + 噩 (biểu âm); chữ hình thanh. Bộ 魚 chỉ đây là sinh vật sống dưới nước, còn 噩 cho âm è.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: bộ cá (魚 — ngư) với âm噩 — 鳄 là loài ''cá'' dữ nhất: cá sấu. | Gương Hán-Việt | ngạc trong 鳄鱼 (ngạc ngư — cá sấu) | Mở khoá kiến thức | Biết 鳄 mở khoá từ 鳄鱼 (cá sấu), 眼泪 鳄鱼的眼泪 (nước mắt cá sấu — giả tạo).", "Tự nguyên_Xie": "Theo Wiktionary, 鳄 là chữ hình thanh: bộ 魚 (ngư) biểu nghĩa ''cá/loài thuỷ sinh'', còn 噩 biểu âm. Nghĩa là cá sấu (crocodile/alligator). Trong tiếng Trung hiện đại dùng phổ biến trong 鳄鱼 (cá sấu). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con cá sấu", "Hạng Tần Suất (Jun Da)": "3772.0", "Tần Suất % (Jun Da)": "99.669091109", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 咢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼咢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳄", "Unihan_Traditional (Chữ Phồn thể)": "鰐", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ loài cá sấu hoặc kết hợp thành từ ghép như cá sấu hoa nam. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讹', '{"9000": "3773.0", "Chữ Trung Quốc": "讹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讹 | ngoa | tượng hình | sai, nhầm, gian lận | 讹 là chữ giản thể của 訛, thuộc bộ 讠(言 — lời nói). Anchor cho biết đây là dạng giản của 訛 (f=訁→讠). Bộ 言 chỉ liên quan đến lời nói sai lệch.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngoa\": lời nói (言/讠) ngoa ngoắt — 讹 là lời sai, lời bịa đặt để lừa đảo. | Gương Hán-Việt | ngoa trong 讹诈 (ngoa trá — tống tiền, lừa đảo), 讹传 (ngoa truyền — tin đồn sai) | Mở khoá kiến thức | Biết 讹 mở khoá từ pháp lý 讹诈 (tống tiền) và báo chí 讹传 (tin đồn sai sự thật).", "Tự nguyên_Xie": "Theo Wiktionary, 讹 là dạng giản thể của 訛: bộ 言 (ngôn — lời nói) biểu nghĩa, còn phần biểu âm cung cấp âm é. Nghĩa gốc là nói sai, nhầm; mở rộng sang ''gian trá, bịa đặt'' và ''tống tiền, ép buộc'' (讹诈). Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn cổ đại. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "làm bậy; sai, nhầm", "Hạng Tần Suất (Jun Da)": "3773.0", "Tần Suất % (Jun Da)": "99.6694678454", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 化", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠化", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "化", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讹", "Unihan_Traditional (Chữ Phồn thể)": "訛", "Pinyin_Xie": "é", "Âm Hán Việt_Xie": "ngoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ chỉ sự sai lệch hoặc động từ với nghĩa tống tiền, lừa bịp. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('膺', '{"9000": "3774.0", "Chữ Trung Quốc": "膺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 17 | nét | 肉 | nhục | biểu âm | thịt, cơ thể | 膺 = 𤸰 (biểu âm) + 肉 (Nhục, biểu nghĩa: thịt/cơ thể); chữ hình thanh. Bộ 肉/月 chỉ đây liên quan đến cơ thể, còn 𤸰 cung cấp âm yīng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: bộ thịt (肉 — nhục) ở ngực — 膺 là lồng ngực, nơi gánh chịu trách nhiệm. | Gương Hán-Việt | ưng trong 膺选 (ưng tuyển — được tuyển chọn), 胸膺 (hung ưng — ngực) | Mở khoá kiến thức | Biết 膺 mở khoá từ văn chương/trang trọng 膺选 (được vinh dự chọn), 胸膺 (ngực lòng).", "Tự nguyên_Xie": "Theo Wiktionary, 膺 là chữ hình thanh: bộ 肉 (nhục — thịt, cơ thể) biểu nghĩa, còn 𤸰 biểu âm. Nghĩa gốc là ngực, lồng ngực. Mở rộng sang nghĩa ''gánh chịu, đón nhận'' (膺选 — được chọn/được bầu) và ''đánh dẹp kẻ thù'' trong văn cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngực; chịu, đương lấy; đánh; cương ngựa, đai ngựa", "Hạng Tần Suất (Jun Da)": "3774.0", "Tần Suất % (Jun Da)": "99.6698430314", "GavinGrover_Once (Chiết tự trực tiếp)": "䧹 + 月", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴䧹月", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "䧹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "膺", "Unihan_Traditional (Chữ Phồn thể)": "膺", "Pinyin_Xie": "yīng", "Âm Hán Việt_Xie": "ưng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong các kết hợp trang trọng như nhận chức, nhận nhiệm vụ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹿', '{"9000": "3775.0", "Chữ Trung Quốc": "蹿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 19 | nét | 蹿 | toán | tượng hình | nhảy tót lên, vụt lên cao | 蹿 thuộc bộ 足 (chân). Anchor không cung cấp cây cấu trúc. Chữ có bộ 足 (túc — chân, biểu nghĩa) và phần còn lại biểu âm cuān, chỉ hành động nhảy vụt lên bằng chân. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: chân (足 — túc) toán lên cao — 蹿 là cú nhảy vọt bất ngờ. | Gương Hán-Việt | toán trong 蹿升 (toán thăng — vụt tăng lên nhanh), 蹿红 (toán hồng — nổi tiếng vụt nhanh) | Mở khoá kiến thức | Biết 蹿 mở khoá từ hiện đại 蹿红 (nổi tiếng nhanh), 蹿升 (tăng vọt nhanh).", "Tự nguyên_Xie": "Anchor Wiktionary không có nguồn gốc chữ viết chi tiết cho 蹿. Chữ thuộc bộ 足 (túc — chân). Nghĩa chính là nhảy tót lên, vụt lên cao; cũng dùng nghĩa khẩu ngữ ''thăng tiến nhanh'' hay ''phọt ra''. Chưa thấy trong giáp cốt/kim văn; chữ tạo muộn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy tót, vụt lên; ộc ra, phọt ra; được thăng chức", "Hạng Tần Suất (Jun Da)": "3775.0", "Tần Suất % (Jun Da)": "99.6702171838", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 窜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊窜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "窜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹿", "Unihan_Traditional (Chữ Phồn thể)": "躥", "Pinyin_Xie": "cuān", "Âm Hán Việt_Xie": "thoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động nhảy vọt lên cao hoặc lao nhanh ra ngoài của người hoặc động vật. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筏', '{"9000": "3776.0", "Chữ Trung Quốc": "筏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 筏 | phẹt | tượng hình | cái bè, thuyền bè làm bằng tre hoặc gỗ | 筏 thuộc bộ 竹 (trúc — tre). Anchor không cung cấp cây cấu trúc chi tiết. Chữ có bộ 竹 (trúc, biểu nghĩa: tre — vật liệu làm bè) và phần còn lại biểu âm fá. Chưa có nguồn học thuật chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẹt\": bộ tre (竹 — trúc) ghép lại phẹt phẹt — cái bè 筏 trôi trên sông. | Gương Hán-Việt | phẹt trong 木筏 (mộc phẹt — bè gỗ), 竹筏 (trúc phẹt — bè tre) | Mở khoá kiến thức | Biết 筏 mở khoá từ 木筏 (bè gỗ), 竹筏 (bè tre), 救生筏 (bè cứu sinh).", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc cấu trúc chi tiết cho 筏. Chữ thuộc bộ 竹 (trúc — tre), gợi ý bè được làm từ tre. Nghĩa là cái bè — phương tiện di chuyển trên nước làm bằng tre hoặc gỗ buộc ghép lại. Chưa thấy trong giáp cốt/kim văn; chữ tạo tương đối muộn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bè (thuyền bè)", "Hạng Tần Suất (Jun Da)": "3776.0", "Tần Suất % (Jun Da)": "99.6705903027", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 伐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮伐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "伐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筏", "Unihan_Traditional (Chữ Phồn thể)": "栰", "Pinyin_Xie": "fá", "Âm Hán Việt_Xie": "phiệt", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các loại bè tre, bè gỗ dùng để di chuyển trên sông nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('釜', '{"9000": "3777.0", "Chữ Trung Quốc": "釜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 父 | phụ | biểu âm | cha | 金 | kim | biểu nghĩa | kim loại | 釜 = 父 (Phụ, biểu âm) + 金 (Kim, biểu nghĩa: kim loại); chữ hình thanh. Bộ kim chỉ đây là đồ vật bằng kim loại, còn 父 cho âm fǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: kim loại (金 — kim) + phụ (父) — cái nồi kim loại của cha — 釜 là nồi, chảo thời cổ. | Gương Hán-Việt | phủ trong 破釜沉舟 (phá phủ trầm chu — đập vỡ nồi chìm thuyền — quyết tâm không lui) | Mở khoá kiến thức | Biết 釜 mở khoá thành ngữ nổi tiếng 破釜沉舟 — quyết chiến không bỏ cuộc.", "Tự nguyên_Xie": "Theo Wiktionary, 釜 là chữ hình thanh: bộ 金 (kim — kim loại) biểu nghĩa, còn 父 (phụ) biểu âm. Nghĩa là cái chảo, nồi đun — dụng cụ nấu ăn bằng đồng hoặc sắt thời xưa. Thường gặp trong thành ngữ 破釜沉舟 (đập vỡ nồi chìm thuyền — quyết tâm không lui). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái nồi, chảo", "Hạng Tần Suất (Jun Da)": "3777.0", "Tần Suất % (Jun Da)": "99.6709634215", "GavinGrover_Once (Chiết tự trực tiếp)": "父 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱父金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "金", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "父", "Unihan_Simplified (Chữ Giản thể)": "釜", "Unihan_Traditional (Chữ Phồn thể)": "釜", "Pinyin_Xie": "fǔ", "Âm Hán Việt_Xie": "phủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong văn ngôn hoặc xuất hiện trong các thành ngữ cổ như nồi đắm thuyền chìm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沂', '{"9000": "3778.0", "Chữ Trung Quốc": "沂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 7 | nét | 水 | thủy | biểu nghĩa | sông, nước | 斤 | cân | biểu âm | cái rìu | 沂 = 水 (Thủy, biểu nghĩa: sông/nước) + 斤 (Cân, biểu âm); chữ hình thanh. Bộ 水 xác định đây là tên sông, còn 斤 cho âm yí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nghi\": sông (水) nặng như cân (斤 — cân) — sông Nghi (沂) ở Sơn Đông, nơi học trò Khổng Tử tắm mát. | Gương Hán-Việt | nghi trong 沂河 (Nghi Hà — sông Nghi, Sơn Đông), 临沂 (Lâm Nghi) | Mở khoá kiến thức | Biết 沂 mở khoá địa danh 临沂 (thành phố Lâm Nghi, Sơn Đông) và điển tích văn hoá 浴沂 (tắm sông Nghi — điển Luận Ngữ).", "Tự nguyên_Xie": "Theo Wiktionary, 沂 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''sông'', còn 斤 (cân) biểu âm. Nghĩa duy nhất là tên sông Nghi (沂河) ở đông nam tỉnh Sơn Đông — con sông gắn liền với Khổng Tử và văn hoá Nho gia (沂水 trong Luận Ngữ). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên sông)", "Hạng Tần Suất (Jun Da)": "3778.0", "Tần Suất % (Jun Da)": "99.6713365404", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "沂", "Unihan_Traditional (Chữ Phồn thể)": "沂", "Pinyin_Xie": "yí", "Âm Hán Việt_Xie": "nghi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng chỉ tên sông hoặc địa danh cổ ở tỉnh Sơn Đông. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坯', '{"9000": "3779.0", "Chữ Trung Quốc": "坯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 丕 | vậy | biểu âm | lớn | 坯 = 土 (Thổ, biểu nghĩa: đất, vật liệu đất) + 丕 (Vậy, biểu âm); chữ hình thanh. Bộ 土 chỉ đây liên quan đến đất sét hoặc vật liệu thô, còn 丕 cho âm pī.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: đất (土 — thổ) thành phôi sơ bộ — 坯 là miếng đất sét chưa nung, phôi gạch mộc. | Gương Hán-Việt | phi trong 毛坯 (mao phi — phôi thô, bán thành phẩm) | Mở khoá kiến thức | Biết 坯 mở khoá từ xây dựng 毛坯房 (nhà thô, chưa hoàn thiện), 坯料 (phôi vật liệu).", "Tự nguyên_Xie": "Theo Wiktionary, 坯 là chữ hình thanh: bộ 土 (thổ) biểu nghĩa ''đất'', còn 丕 biểu âm. Nghĩa là phôi đất — vật liệu thô chưa qua nung hay gia công lần cuối, như gạch mộc, phôi gốm sứ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phôi (gạch ngói, đồ sứ chưa nung); phôi đất; bán thành phẩm", "Hạng Tần Suất (Jun Da)": "3779.0", "Tần Suất % (Jun Da)": "99.6717086257", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坯", "Unihan_Traditional (Chữ Phồn thể)": "坯", "Pinyin_Xie": "pī", "Âm Hán Việt_Xie": "bôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ vật liệu thô hoặc sản phẩm chưa hoàn thiện trước khi nung hay gia công. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('峦', '{"9000": "3780.0", "Chữ Trung Quốc": "峦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 9 | nét | 峦 | loan | tượng hình | dãy núi quanh co liên tiếp | 峦 là chữ giản thể của 巒, thuộc bộ 山 (núi). Anchor cho biết đây là dạng giản của 巒 (f=龻→𰁜). Bộ 山 chỉ liên quan đến núi non. Chưa có dữ liệu cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": núi (山) uốn loan (loan — cong, lượn) — 峦 là dãy núi liên tiếp uốn lượn như dải ruy băng. | Gương Hán-Việt | loan trong 山峦 (sơn loan — dãy núi), 峦嶂 (loan chướng — núi non trùng điệp) | Mở khoá kiến thức | Biết 峦 mở khoá từ thơ ca 山峦 (dãy núi), 重峦叠嶂 (núi non trùng điệp — thành ngữ).", "Tự nguyên_Xie": "Theo Wiktionary, 峦 là dạng giản thể của 巒. Chữ thuộc bộ 山 (sơn — núi). Nghĩa là dãy núi quanh co, uốn lượn liên tiếp nhau — khác với 峰 (chỉ một đỉnh riêng lẻ). Thường gặp trong văn thơ tả cảnh núi non trùng điệp. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "núi quanh co nối liền nhau", "Hạng Tần Suất (Jun Da)": "3780.0", "Tần Suất % (Jun Da)": "99.6720796774", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "峦", "Unihan_Traditional (Chữ Phồn thể)": "巒", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ các dãy núi nối liền nhau, hay xuất hiện trong thơ ca và từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('茬', '{"9000": "3781.0", "Chữ Trung Quốc": "茬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 茬 | tra | tượng hình | gốc rạ, cọng rạ còn lại sau gặt | 茬 thuộc bộ 艹 (thảo — cây cỏ). Anchor không cung cấp cấu trúc chi tiết. Chữ có bộ 艹 biểu nghĩa liên quan đến thực vật, còn phần còn lại biểu âm chá. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tra\": cây (艹 — thảo) bị tra vào đất — gốc rạ 茬 còn sót lại sau khi gặt. | Gương Hán-Việt | tra trong 头茬 (đầu tra — vụ đầu tiên), 换茬 (hoán tra — luân canh) | Mở khoá kiến thức | Biết 茬 mở khoá từ nông nghiệp 茬口 (luân canh), 换茬 (thay đổi cây trồng), 头茬 (vụ đầu).", "Tự nguyên_Xie": "Anchor Wiktionary không có nguồn gốc chữ viết chi tiết cho 茬. Chữ thuộc bộ 艹 (thảo — cây cỏ). Nghĩa gốc là gốc rạ, cọng cứng còn lại sau khi gặt lúa; mở rộng sang ''vụ, lứa'' (một 茬 lúa — một vụ lúa) và tóc, râu ngắn cứng. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cọng, gốc rạ; vụ, lứa; tóc, râu ngắn và cứng", "Hạng Tần Suất (Jun Da)": "3781.0", "Tần Suất % (Jun Da)": "99.6724502124", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 在", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹在", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "在", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "茬", "Unihan_Traditional (Chữ Phồn thể)": "茬", "Pinyin_Xie": "chá", "Âm Hán Việt_Xie": "tra", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Danh từ | 名词 | Thường dùng làm lượng từ để chỉ vụ mùa, lứa cây trồng hoặc đợt công việc liên tiếp. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('摒', '{"9000": "3782.0", "Chữ Trung Quốc": "摒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 12 | nét | 摒 | bính | tượng hình | bỏ đi, loại bỏ, dẹp sang một bên | 摒 thuộc bộ 扌 (thủ — tay). Anchor không cung cấp cấu trúc chi tiết nhưng cho biết dạng thay thế là 屏/偋. Chữ có bộ 扌 (tay, biểu nghĩa) và phần còn lại biểu âm bǐng. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bính\": tay (扌 — thủ) gạt bính — 摒 là cử chỉ tay gạt bỏ, loại trừ điều không cần thiết. | Gương Hán-Việt | bính trong 摒弃 (bính khí — loại bỏ, từ bỏ hoàn toàn) | Mở khoá kiến thức | Biết 摒 mở khoá từ 摒弃 (loại bỏ dứt khoát), 摒除 (gạt bỏ, loại trừ).", "Tự nguyên_Xie": "Anchor Wiktionary không có nguồn gốc chữ viết chi tiết cho 摒. Chữ thuộc bộ 扌 (thủ — tay), gợi ý hành động dùng tay đẩy ra, gạt bỏ. Nghĩa là loại bỏ, dẹp bỏ, gạt sang một bên. Dạng thay thế là 屏 và 偋. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bỏ, ruồng đuổi", "Hạng Tần Suất (Jun Da)": "3782.0", "Tần Suất % (Jun Da)": "99.6728207473", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 屏", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌屏", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屏", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "摒", "Unihan_Traditional (Chữ Phồn thể)": "摒", "Pinyin_Xie": "bǐng", "Âm Hán Việt_Xie": "bính", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thể hiện hành động vứt bỏ hoặc gạt bỏ những suy nghĩ, thói quen xấu. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟀', '{"9000": "3783.0", "Chữ Trung Quốc": "蟀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 17 | nét | 虫 | trùng | biểu nghĩa | côn trùng | 率 | luật | biểu âm | tỷ lệ, dẫn đầu | 蟀 = 虫 (Trùng, biểu nghĩa: côn trùng) + 率 (Luật, biểu âm); chữ hình thanh. Bộ 虫 xác định đây là côn trùng, còn 率 cho âm shuài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"suất\": trùng (虫) dẫn đầu theo luật (率 — luật) âm nhạc mùa thu — 蟀 là nửa sau của 蟋蟀 (dế mèn). | Gương Hán-Việt | suất trong 蟋蟀 (tất suất — dế mèn) | Mở khoá kiến thức | Biết 蟀 mở khoá từ 蟋蟀 — con dế, biểu tượng mùa thu trong thi ca Hán ngữ.", "Tự nguyên_Xie": "Theo Wiktionary, 蟀 là chữ hình thanh: bộ 虫 (trùng) biểu nghĩa ''côn trùng'', còn 率 (luật) biểu âm. Nghĩa là con dế — chỉ dùng trong tổ hợp 蟋蟀 (dế mèn). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1668.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Trùng (142) Suất (095)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Trùng (số 142 - côn trùng/ 虫 /chỉ ý) ở bên trái chữ Suất (số 095 - cầm đầu/ 率 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Suất chỉ âm, bộ Trùng chỉ ý. Suất là tên một loài côn trùng. Từ Tất Suất (蟋蟀) dùng để chỉ con dế mèn.", "Nghĩa Tiếng Việt_Xie": "(xem: tất suất 蟋蟀)", "Hạng Tần Suất (Jun Da)": "3783.0", "Tần Suất % (Jun Da)": "99.6731912823", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 率", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫率", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "率", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟀", "Unihan_Traditional (Chữ Phồn thể)": "蟀", "Pinyin_Xie": "shuài", "Âm Hán Việt_Xie": "suất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường không đứng một mình mà kết hợp làm danh từ liên kết để chỉ con dế mèn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撵', '{"9000": "3784.0", "Chữ Trung Quốc": "撵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 撵 | niễn | tượng hình | đuổi đi, xua đuổi | 撵 thuộc bộ 扌 (thủ — tay). Anchor không cung cấp cấu trúc chi tiết. Chữ có bộ 扌 (tay, biểu nghĩa: hành động) và phần còn lại biểu âm niǎn. Nghĩa là dùng tay (hoặc hành động) để đuổi đi, xua ra khỏi. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"niễn\": tay (扌) đuổi niễn — 撵 là cử chỉ dùng tay đuổi ai đó ra đi. | Gương Hán-Việt | niễn trong 撵走 (niễn tẩu — đuổi đi), 撵出去 (đuổi ra ngoài) | Mở khoá kiến thức | Biết 撵 mở khoá từ khẩu ngữ 撵走, 撵出去 thường dùng trong văn nói tiếng Trung phổ thông.", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc chi tiết cho 撵. Chữ thuộc bộ 扌 (thủ — tay), gợi ý hành động vật lý. Nghĩa là đuổi đi, xua ra ngoài. Chủ yếu dùng trong khẩu ngữ và phương ngữ miền Bắc Trung Quốc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đuổi đi", "Hạng Tần Suất (Jun Da)": "3784.0", "Tần Suất % (Jun Da)": "99.6735613004", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 辇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌辇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "辇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撵", "Unihan_Traditional (Chữ Phồn thể)": "攆", "Pinyin_Xie": "niǎn", "Âm Hán Việt_Xie": "niện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ vị ngữ trong câu để biểu thị hành động xua đuổi ai đó đi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('浒', '{"9000": "3785.0", "Chữ Trung Quốc": "浒", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 水 | thủy | biểu nghĩa | nước, bến nước | 許 | hứa | biểu âm | cho phép | 浒 = 水 (Thủy, biểu nghĩa: nước/bến sông) + 許 (Hứa, biểu âm); chữ hình thanh. Bộ 水 chỉ liên quan đến nước, còn 許 cho âm hǔ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hứa\": nước (水 — thủy) hứa hẹn bến đỗ — 浒 là bến nước, nơi các anh hùng Lương Sơn hội tụ trong Thủy Hử. | Gương Hán-Việt | hứa trong 水浒 (thủy hứa — bến nước, tên tác phẩm cổ điển) | Mở khoá kiến thức | Biết 浒 mở khoá tên tác phẩm kinh điển 水浒传 (Thủy Hử Truyện — 108 anh hùng Lương Sơn).", "Tự nguyên_Xie": "Theo Wiktionary, 浒 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa ''nước'', còn 許 (hứa) biểu âm. Nghĩa là bến nước, bờ sông. Nổi tiếng nhờ tên tác phẩm 《水浒传》(Thủy hử truyện — Truyện Thủy Hử) của Thi Nại Am. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bến nước", "Hạng Tần Suất (Jun Da)": "3785.0", "Tần Suất % (Jun Da)": "99.6739308018", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 许", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵许", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "许", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "浒", "Unihan_Traditional (Chữ Phồn thể)": "滸", "Pinyin_Xie": "hǔ", "Âm Hán Việt_Xie": "hử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ địa danh hoặc xuất hiện trong tác phẩm Thủy Hử. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缤', '{"9000": "3786.0", "Chữ Trung Quốc": "缤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 13 | nét | 缤 | tân | tượng hình | hỗn loạn, rực rỡ, nhiều màu sắc | 缤 là chữ giản thể của 繽, thuộc bộ 纟(糸 — tơ lụa). Anchor cho biết đây là dạng giản của 繽 (f=糹→纟, f2=賓→宾). Bộ 纟 gợi ý liên quan đến vải, màu sắc rực rỡ. Chưa có dữ liệu cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\": tơ (纟) rực rỡ tân tiến — 缤 gợi tả màu sắc cờ hoa tung rơi ngập tràn. | Gương Hán-Việt | tân trong 缤纷 (tân phân — rực rỡ, muôn màu) | Mở khoá kiến thức | Biết 缤 gần như chỉ dùng trong 缤纷 — mở khoá từ thơ văn tả cảnh hoa lá rơi rực rỡ, 五彩缤纷.", "Tự nguyên_Xie": "Theo Wiktionary, 缤 là dạng giản thể của 繽. Chữ thuộc bộ 纟(糸 — tơ lụa, vải). Nghĩa là rực rỡ nhiều màu, lộn xộn đông đúc. Thường gặp trong 缤纷 (tân phân — rực rỡ muôn màu, phồn thịnh). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hỗn loạn, rối loạn; nhầm lẫn", "Hạng Tần Suất (Jun Da)": "3786.0", "Tần Suất % (Jun Da)": "99.6743003032", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缤", "Unihan_Traditional (Chữ Phồn thể)": "繽", "Pinyin_Xie": "bīn", "Âm Hán Việt_Xie": "tân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường kết hợp với các từ khác để tạo thành từ ghép mô tả sự rực rỡ hoặc hỗn loạn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嵋', '{"9000": "3787.0", "Chữ Trung Quốc": "嵋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 12 | nét | 嵋 | mi | tượng hình | tên núi Nga Mi | 嵋 thuộc bộ 山 (núi). Anchor không cung cấp cấu trúc chi tiết. Chữ chỉ dùng trong địa danh 峨嵋 (Nga Mi) — tên ngọn núi nổi tiếng ở Tứ Xuyên, Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mi\": núi (山) có cặp chân mày mi (mi — lông mày) cong đẹp — 嵋 trong 峨嵋 gợi dáng núi cong như lông mày. | Gương Hán-Việt | mi trong 峨嵋山 (Nga Mi Sơn — núi Nga Mi, Tứ Xuyên) | Mở khoá kiến thức | Biết 嵋 mở khoá địa danh 峨嵋山 — ngọn núi Phật giáo Tứ Xuyên, Di sản Thế giới UNESCO.", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc chữ viết chi tiết cho 嵋. Chữ thuộc bộ 山 (sơn — núi). Chỉ dùng trong tên riêng 峨嵋山 (Nga Mi Sơn) — ngọn núi Phật giáo nổi tiếng ở tỉnh Tứ Xuyên, một trong Tứ Đại Danh Sơn Phật Giáo Trung Quốc. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nga my 峨嵋)", "Hạng Tần Suất (Jun Da)": "3787.0", "Tần Suất % (Jun Da)": "99.674668771", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 眉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山眉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "眉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "嵋", "Unihan_Traditional (Chữ Phồn thể)": "嵋", "Pinyin_Xie": "méi", "Âm Hán Việt_Xie": "mi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ riêng trong tên núi Nga Mi của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珑', '{"9000": "3788.0", "Chữ Trung Quốc": "珑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 9 | nét | 珑 | lung | tượng hình | một loại ngọc, dùng trong 玲珑 | 珑 là chữ giản thể của 瓏, thuộc bộ 王/玉 (ngọc). Anchor cho biết đây là dạng giản của 瓏 (f=龍→龙). Bộ ngọc chỉ đây là loại đá quý. Chưa có dữ liệu cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lung\": ngọc (王/玉) như tiếng chuông trong suốt — 珑 trong 玲珑 gợi vẻ đẹp tinh tế như ngọc. | Gương Hán-Việt | lung trong 玲珑 (linh lung — tinh xảo, khéo léo, xinh đẹp) | Mở khoá kiến thức | Biết 珑 mở khoá tính từ đẹp 玲珑 thường dùng khi tả vật tinh xảo hoặc người khéo léo duyên dáng.", "Tự nguyên_Xie": "Theo Wiktionary, 珑 là dạng giản thể của 瓏: bộ 王/玉 (ngọc) biểu nghĩa, còn 龍/龙 biểu âm. Chỉ dùng trong tổ hợp 玲珑 (linh lung) — nghĩa là tinh xảo, khéo léo, xinh xắn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh lung 玲瓏,玲珑)", "Hạng Tần Suất (Jun Da)": "3788.0", "Tần Suất % (Jun Da)": "99.6750372388", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 龙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王龙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "龙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珑", "Unihan_Traditional (Chữ Phồn thể)": "瓏", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường dùng trong từ ghép để mô tả vẻ đẹp tinh xảo hoặc trong sáng của ngọc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('苞', '{"9000": "3789.0", "Chữ Trung Quốc": "苞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 8 | nét | 艹 | biểu nghĩa | cây cỏ | 包 | bao | biểu âm | gói | 苞 = 艹 (bộ thảo, biểu nghĩa: cây cỏ) + 包 (Bao, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây liên quan đến thực vật, còn 包 cho âm bāo.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bao\": cây cỏ (艹) bao (包 — bao) bọc quanh — 苞 là đài hoa bao phủ nụ hoa chưa nở. | Gương Hán-Việt | bao trong 花苞 (hoa bao — nụ hoa, đài hoa), 含苞待放 (hàm bao đãi phóng) | Mở khoá kiến thức | Biết 苞 mở khoá từ thơ văn 含苞待放 (nụ hoa chứa đầy sắp nở — ví người trẻ tài năng sắp toả sáng).", "Tự nguyên_Xie": "Theo Wiktionary, 苞 là chữ hình thanh: bộ 艸/艹 biểu nghĩa ''cây cỏ'', còn 包 biểu âm. Nghĩa gốc là đài hoa, lá bắc bao bọc quanh hoa khi chưa nở; mở rộng sang loại cỏ bao dùng đan lát, và rậm rạp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ bao (dùng đan dép, dệt chiếu); đài hoa; bụi cỏ", "Hạng Tần Suất (Jun Da)": "3789.0", "Tần Suất % (Jun Da)": "99.6754051898", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 包", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹包", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "包", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "苞", "Unihan_Traditional (Chữ Phồn thể)": "苞", "Pinyin_Xie": "bāo", "Âm Hán Việt_Xie": "bao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ bộ phận của hoa hoặc làm động từ với nghĩa bao bọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑾', '{"9000": "3790.0", "Chữ Trung Quốc": "瑾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 15 | nét | 瑾 | cẩn | tượng hình | một loại ngọc quý | 瑾 thuộc bộ 王/玉 (ngọc). Anchor không cung cấp cấu trúc chi tiết. Chữ có bộ 王/玉 (ngọc, biểu nghĩa: đá quý) và phần còn lại biểu âm jǐn. Nghĩa là một loại ngọc quý đẹp. Chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cẩn\": bộ ngọc (王/玉) quý cẩn thận — 瑾 là thứ ngọc đẹp, xứng đáng được cẩn thận trân trọng. | Gương Hán-Việt | cẩn trong 懷瑾握瑜 (hoài cẩn ác du — ôm ngọc cầm ngọc đẹp — có tài đức) | Mở khoá kiến thức | Biết 瑾 mở khoá thành ngữ 懷瑾握瑜 — tả người có tài năng và phẩm hạnh tốt đẹp.", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc chi tiết cho 瑾. Chữ thuộc bộ 王/玉 (ngọc). Nghĩa là một loại ngọc quý, đẹp. Thường dùng làm tên người (đặc biệt tên nữ) tại Trung Quốc và Việt Nam. Gặp trong thành ngữ 懷瑾握瑜 (ôm ngọc cầm ngọc — có đức hạnh tài năng). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một thứ ngọc)", "Hạng Tần Suất (Jun Da)": "3790.0", "Tần Suất % (Jun Da)": "99.6757721072", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 堇", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王堇", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "堇", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑾", "Unihan_Traditional (Chữ Phồn thể)": "瑾", "Pinyin_Xie": "jǐn", "Âm Hán Việt_Xie": "cẩn, cấn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ ngọc quý hoặc dùng trong tên người để chỉ phẩm chất tốt đẹp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泵', '{"9000": "3791.0", "Chữ Trung Quốc": "泵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 9 | nét | 石 | thạch | đá | 水 | thủy | nước | 泵 = 石 (Thạch) + 水 (Thủy); chữ hội ý. Hình ảnh đá đẩy nước — gợi tả nguyên lý máy bơm: dùng lực cơ học đẩy nước chuyển động. Đây là chữ tạo mới trong tiếng Trung hiện đại để dịch từ ''pump'' (tiếng Anh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt không phổ biến: đá (石 — thạch) ép nước (水 — thủy) ra — 泵 là máy bơm, mô phỏng nguyên lý pittông đẩy nước. | Gương Hán-Việt | bổng trong 水泵 (thủy bổng — máy bơm nước), 泵站 (bổng trạm — trạm bơm) | Mở khoá kiến thức | Biết 泵 mở khoá từ kỹ thuật 水泵 (máy bơm nước), 离心泵 (máy bơm ly tâm), 泵站 (trạm bơm).", "Tự nguyên_Xie": "Theo Wiktionary, 泵 là chữ hội ý: 石 (thạch — đá) + 水 (thủy — nước). Đây là chữ tạo ra tương đối muộn, dùng để phiên âm/dịch nghĩa từ ''pump'' trong tiếng Anh. Nghĩa là máy bơm, ống bơm — thiết bị cơ học để di chuyển chất lỏng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ống bơm, ống thụt", "Hạng Tần Suất (Jun Da)": "3791.0", "Tần Suất % (Jun Da)": "99.6761385079", "GavinGrover_Once (Chiết tự trực tiếp)": "石 + 水", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱石水", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "水", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "石", "Unihan_Simplified (Chữ Giản thể)": "泵", "Unihan_Traditional (Chữ Phồn thể)": "泵", "Pinyin_Xie": "bèng", "Âm Hán Việt_Xie": "bơm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ thiết bị bơm hoặc làm động từ chỉ hành động bơm chất lỏng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钾', '{"9000": "3792.0", "Chữ Trung Quốc": "钾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 10 | nét | 金 | kim | biểu nghĩa | kim loại | 甲 | giáp | biểu âm | giáp trụ, can thứ nhất | 钾 = 金 (Kim, biểu nghĩa: kim loại) + 甲 (Giáp, biểu âm); chữ hình thanh với cả hai khía cạnh. Bộ 金 chỉ đây là nguyên tố kim loại, còn 甲 cho âm jiǎ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáp\": kim loại (金 — kim) số một (甲 — giáp: đứng đầu) — Kali là khoáng chất giáp hạng đầu cần thiết cho cây trồng. | Gương Hán-Việt | giáp trong 钾肥 (giáp phí — phân kali), 氯化钾 (lục hoá giáp — kali clorua) | Mở khoá kiến thức | Biết 钾 mở khoá từ hoá học/nông nghiệp 钾肥 (phân kali), 氯化钾, 硫酸钾.", "Tự nguyên_Xie": "Theo Wiktionary, 钾 là chữ hình thanh: bộ 金 (kim) biểu nghĩa ''kim loại'', còn 甲 biểu âm. Là chữ tạo mới trong tiếng Trung hiện đại để đặt tên cho nguyên tố hoá học Kali (K, potassium) — kim loại kiềm quan trọng trong sinh học và nông nghiệp. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố kali, K", "Hạng Tần Suất (Jun Da)": "3792.0", "Tần Suất % (Jun Da)": "99.6765049085", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 甲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅甲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钾", "Unihan_Traditional (Chữ Phồn thể)": "鉀", "Pinyin_Xie": "jiǎ", "Âm Hán Việt_Xie": "giáp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong các thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暧', '{"9000": "3793.0", "Chữ Trung Quốc": "暧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 14 | nét | 日 | nhật | biểu nghĩa | mặt trời, ánh sáng | 爱 | ái | biểu âm | tình yêu | 暧 = 日 (Nhật, biểu nghĩa: mặt trời/ánh sáng) + 爱 (Ái, biểu âm). Đây là dạng giản thể của 曖 (phồn thể 曖 = 日+愛). Wiktionary ghi là giản thể của 曖, không có phân tích ls riêng. Cấu trúc phono-semantic: 日 gợi ánh sáng mờ mịt; 爱/愛 biểu âm ài.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\": ánh mặt trời (日) bị che mờ bởi tình ái (爱) — mọi thứ trở nên mơ hồ, không rõ ràng như quan hệ 暧昧. | Gương Hán-Việt | \"ái\" trong 暧昧 (ái muội — mơ hồ, quan hệ không rõ ràng) | Mở khoá kiến thức | Biết 暧 mở khoá 暧昧 (mơ hồ, nhập nhằng trong quan hệ).", "Tự nguyên_Xie": "Chữ 暧 (ái) là dạng giản thể của 曖 (曖昧), gồm bộ 日 (Nhật — mặt trời) biểu nghĩa và 愛/爱 (Ái) biểu âm ài. Nghĩa gốc: ánh sáng mờ mịt, u ám; mở rộng sang nghĩa mơ hồ, không rõ ràng. Thường gặp trong 暧昧 (mơ hồ, quan hệ không rõ ràng). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "u ám, mờ mịt; việc gì không rõ ràng", "Hạng Tần Suất (Jun Da)": "3793.0", "Tần Suất % (Jun Da)": "99.6768713092", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 爱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日爱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暧", "Unihan_Traditional (Chữ Phồn thể)": "曖", "Pinyin_Xie": "ài", "Âm Hán Việt_Xie": "ái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ bổ nghĩa cho danh từ để chỉ sự mờ ám hoặc không rõ ràng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赓', '{"9000": "3794.0", "Chữ Trung Quốc": "赓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 广 | Số nét | 12 | nét | 赓 | canh | tượng hình | tiếp tục, duy trì, kế thừa | 赓 thuộc nhóm chữ ít gặp, anchor không cung cấp cây cấu trúc. Chữ văn chương chỉ hành động ''tiếp tục, kế thừa, duy trì''. Chưa có nguồn học thuật xác nhận cấu trúc chi tiết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": canh giữ, duy trì liên tục — 赓 là hành động tiếp nối không dứt, như ca 更 canh trực thâu đêm. | Gương Hán-Việt | canh trong 赓续 (canh tục — tiếp tục duy trì), 赓扬 (canh dương — tiếp tục phát huy) | Mở khoá kiến thức | Biết 赓 mở khoá từ trang trọng 赓续 (tiếp tục kế thừa), 赓韵 (hoạ vần — nối tiếp vần thơ người khác).", "Tự nguyên_Xie": "Anchor Wiktionary không cung cấp nguồn gốc chữ viết chi tiết cho 赓. Nghĩa là tiếp tục, duy trì, kế thừa; cũng dùng nghĩa ''bù đắp, bù lại''. Chữ văn chương trang trọng, thường gặp trong văn bản hành chính và thơ văn cổ Trung Hoa. Chưa thấy trong giáp cốt văn; chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếp tục, duy trì", "Hạng Tần Suất (Jun Da)": "3794.0", "Tần Suất % (Jun Da)": "99.6772361595", "GavinGrover_Once (Chiết tự trực tiếp)": "庚 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴庚贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赓", "Unihan_Traditional (Chữ Phồn thể)": "賡", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong văn viết cổ hoặc trang trọng để chỉ sự kế thừa, nối tiếp. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('叟', '{"9000": "3795.0", "Chữ Trung Quốc": "叟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 又 | Số nét | 9 | nét | 宀 | miên | biểu nghĩa | mái nhà, nhà | 火 | hoả | biểu nghĩa | lửa | 又 | hựu | biểu nghĩa | bàn tay | 叟 là chữ hội ý (ic): tay (又) cầm đuốc lửa (火) trong nhà (宀) — hình ảnh người già dò dẫm soi đường trong nhà tối. Từ lệ thư trở đi, 宀 và 火 nhập thành dạng 𦥔 không liên quan.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\" (ông già): hình ảnh ông lão tay cầm đuốc (火) soi trong nhà (宀) ban đêm — người già vẫn còn tìm kiếm, dò dẫm. | Gương Hán-Việt | tẩu không phổ biến trong từ ghép tiếng Việt hiện đại, thường dùng trong văn chương cổ chỉ ông già. | Mở khoá kiến thức | Biết 叟 mở khoá chữ 搜 (tìm kiếm) và 艘 (lượng từ chỉ tàu thuyền) — cùng âm tẩu/sou.", "Tự nguyên_Xie": "Giáp cốt văn | 叟 vốn là dạng cổ của 叜. Theo Wiktionary, đây là chữ hội ý: tay (又) cầm đuốc (火) soi trong nhà (宀) — hình ảnh người đang lục lọc, tìm kiếm. Đây là dạng gốc của chữ 搜 (tìm kiếm). Từ lệ thư về sau, 宀 và 火 hợp lại thành bộ 𦥔 khác hoàn toàn, làm mờ nghĩa gốc. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ông già", "Hạng Tần Suất (Jun Da)": "3795.0", "Tần Suất % (Jun Da)": "99.6775994595", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 又", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱又", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "叟", "Unihan_Traditional (Chữ Phồn thể)": "叟", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ xưng hô hoặc chỉ người già trong văn ngôn cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佚', '{"9000": "3796.0", "Chữ Trung Quốc": "佚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 7 | nét | 人 | nhân | biểu nghĩa | người | 失 | thất | biểu âm | mất | 佚 là chữ hình thanh (psc): 人 (nhân, biểu nghĩa: người) + 失 (thất, biểu âm). Người mất đi, trốn thoát — nghĩa: nhàn rỗi, ẩn dật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dật\" (nhàn rỗi, ẩn dật): người (人) đã mất (失) dấu vào chốn ẩn — hình ảnh ẩn sĩ rời bỏ thế sự. | Gương Hán-Việt | dật trong ''dật dĩnh'' (nhàn hạ, xa lánh), ''dật lạc'' (vui thú nhàn rỗi), ''tản dật'' (sống ẩn dật). | Mở khoá kiến thức | Biết 佚 mở khoá 逸 (dật, trốn chạy, thoát) và 溢 (dật, tràn đầy) — cùng âm Hán-Việt.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 佚 là chữ hình thanh: bộ 人 (người) biểu nghĩa, 失 biểu âm. Nghĩa gốc chỉ người lẩn trốn, ẩn dật, sau mở rộng sang nghĩa nhàn rỗi, hưởng thụ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "43.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhân (42) Thất (5)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm chữ Nhân đứng (số 12) và chữ Thất (số 35) . Người đã mất hình dáng (biến mất khỏi thế tục) ấy là người đi ở ẩn.", "Nghĩa Tiếng Việt_Xie": "nhàn rỗi; ẩn, trốn", "Hạng Tần Suất (Jun Da)": "3796.0", "Tần Suất % (Jun Da)": "99.6779622426", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 失", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻失", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "失", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佚", "Unihan_Traditional (Chữ Phồn thể)": "佚", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "dật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ để chỉ trạng thái nhàn nhã hoặc động từ chỉ sự thất lạc, ẩn trốn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('沓', '{"9000": "3797.0", "Chữ Trung Quốc": "沓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 水 | thủy | biểu nghĩa | nước | 曰 | viết | biểu nghĩa | nói, miệng | 沓 là chữ hội ý (ic): 水 (nước) + 曰 (miệng). Hình ảnh nước chồng chất, tuôn trào — biểu thị sự lặp đi lặp lại, chồng chất. Ngoài ra 沓 còn dùng làm lượng từ chỉ xấp giấy (một 沓 = một xấp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đạp\" (chồng chất, nhiều): nước (水) tuôn vào miệng (曰) liên tiếp — lặp đi lặp lại, tụ hội đông đúc. | Gương Hán-Việt | đạp trong ''tạp沓'' (lộn xộn, chồng chất), ''phân đạp nhi lai'' (đổ xô mà đến, 紛至沓來 — thành ngữ phổ biến). | Mở khoá kiến thức | Biết 沓 mở khoá thành ngữ 紛至沓來 (phân chí đạp lai — kéo đến tấp nập) và 拖沓 (trì hoãn, luộm thuộm).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Theo Wiktionary, 沓 là chữ hội ý: 水 (nước) + 曰 (miệng/lời). Ý nghĩa kết hợp: lời nói chồng chất như nước — nhiều lần, liên tục. Chữ có nhiều nghĩa: nói nhiều/lắm lời, chồng chất, tụ hội, và dùng như lượng từ chỉ xấp tờ giấy. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1671.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thủy (085) Viết (073)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thủy (số 085 - dòng nước/ 水) ở trên chữ Viết (số 073 - miệng nói/ 曰). Cái miệng mở ra nói liên hồi như dòng nước chảy dào dạt không ngừng. Giải thích sự chuyển ý: Đây là chữ Hội ý. Đạp là nhiều lời, nói lải nhải dông dài (ngữ đạp). Mở rộng chỉ sự lộn xộn, hỗn tạp (tạp đạp).", "Nghĩa Tiếng Việt_Xie": "chồng chất; nhiều", "Hạng Tần Suất (Jun Da)": "3797.0", "Tần Suất % (Jun Da)": "99.6783234754", "GavinGrover_Once (Chiết tự trực tiếp)": "水 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱水日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "日", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "水", "Unihan_Simplified (Chữ Giản thể)": "沓", "Unihan_Traditional (Chữ Phồn thể)": "沓", "Pinyin_Xie": "dá", "Âm Hán Việt_Xie": "đạp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Lượng từ | 量词 | Tính từ | 形容词 | Thường làm lượng từ cho xấp giấy, tập tài liệu hoặc tính từ chỉ sự chồng chất, rườm rà. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撂', '{"9000": "3798.0", "Chữ Trung Quốc": "撂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 14 | nét | 撂 | liêu | tượng hình | quêu lấy, quẳng xuống | Cấu trúc nội bộ của 撂 chưa được ghi nhận đầy đủ trong nguồn học thuật hiện có. Bộ 扌 (tay) ở bên trái gợi ý liên quan đến hành động của tay, nhưng chưa có phân tích hình thanh/hội ý xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêu\" (quẳng xuống, bỏ ra): bộ 扌 (tay) — dùng tay quẳng vật gì đó xuống đất hoặc sang một bên. | Gương Hán-Việt | liêu ít xuất hiện trong từ ghép Hán-Việt, chủ yếu dùng trong tiếng Trung hiện đại: 撂倒 (đánh ngã), 撂挑子 (bỏ việc). | Mở khoá kiến thức | Biết 撂 giúp hiểu các từ 撂倒 (quật ngã), 撂摊子 (bỏ dở công việc), 按撂 (ấn xuống).", "Tự nguyên_Xie": "Không có nguồn học thuật ghi nhận cấu trúc nguồn gốc của 撂. Bộ 扌 (tay) gợi ý đây là chữ liên quan đến hành động tay (quẳng xuống, gạt ra). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quều lấy, khêu ra, gạt ra", "Hạng Tần Suất (Jun Da)": "3798.0", "Tần Suất % (Jun Da)": "99.6786841915", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 畧", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌畧", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畧", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撂", "Unihan_Traditional (Chữ Phồn thể)": "撂", "Pinyin_Xie": "liào", "Âm Hán Việt_Xie": "lược", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ đứng trước tân ngữ để chỉ hành động đặt xuống hoặc bỏ mặc công việc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛊', '{"9000": "3799.0", "Chữ Trung Quốc": "蛊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 蟲 | trùng | biểu nghĩa | côn trùng, sâu bọ | 皿 | mãnh | biểu nghĩa | đồ đựng, bình chứa | 蛊 là chữ hội ý (ic): 蟲 (trùng, côn trùng) + 皿 (mãnh, đồ đựng) — hình ảnh nuôi sâu độc trong bình kín để tạo ra thuốc độc ''cổ''. Đây là hình ảnh của tục phù thủy cổ đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cổ\" (độc, bùa mê): sâu bọ (蟲) nhốt trong bình (皿) — phù thuật cổ đại luyện độc. | Gương Hán-Việt | cổ trong ''cổ độc'' (蛊毒, độc dược bùa chú), ''mê cổ'' (mê hoặc, bùa mê), ''truyền cổ'' (lan truyền độc hại). | Mở khoá kiến thức | Biết 蛊 mở khoá 蛊惑 (cổ hoặc — mê hoặc, lừa bịp) và 蛊毒 (cổ độc — độc bùa phép).", "Tự nguyên_Xie": "Giáp cốt văn | Theo Wiktionary, 蛊 (dạng phồn thể 蠱) là chữ hội ý: 蟲 (côn trùng) + 皿 (đồ đựng) — nuôi côn trùng độc trong bình để tạo ra độc dược. Trong văn hóa Trung Hoa cổ, ''cổ độc'' (蛊毒) là loại phép thuật luyện độc bằng cách nhốt nhiều sinh vật độc vào bình và con cuối cùng còn sống sẽ thành thuốc độc mạnh nhất. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vật độc hại", "Hạng Tần Suất (Jun Da)": "3799.0", "Tần Suất % (Jun Da)": "99.6790438739", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱虫皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛊", "Unihan_Traditional (Chữ Phồn thể)": "蠱", "Pinyin_Xie": "gǔ", "Âm Hán Việt_Xie": "cổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Làm danh từ chỉ loài sâu độc hoặc động từ chỉ việc đầu độc, mê hoặc người khác. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甥', '{"9000": "3800.0", "Chữ Trung Quốc": "甥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 生 | Số nét | 12 | nét | 甥 | sanh | tượng hình | cháu ngoại, con của chị/em gái | 甥 là chữ độc lập, cấu trúc nội bộ không được phân tích rõ trong Wiktionary. Bề ngoài có thể thấy 生 (sinh) bên trên và 男 (nam) bên dưới, gợi ý ''người sinh ra từ phía bên kia họ — cháu ngoại''. Tuy nhiên đây là suy đoán về hình thức, chưa có nguồn học thuật xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sanh\" (cháu ngoại): người con trai (男) sinh ra từ bên phía ngoại — cháu gọi bằng cậu/dì. | Gương Hán-Việt | sanh trong ''ngoại sanh'' (甥, cháu ngoại), ''ngoại sanh nữ'' (cháu gái con chị/em gái). | Mở khoá kiến thức | Biết 甥 mở khoá 外甥 (ngoại sanh — cháu gọi bằng cậu), 甥女 (sanh nữ — cháu gái ngoại).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Nguồn Wiktionary chỉ ghi nhận hình thức chữ, không phân tích cấu trúc hình thanh hay hội ý. Nhìn vào dạng 大/小 triện, 甥 có vẻ ghép từ 生 (sinh, biểu âm?) và 男 (nam giới), gợi nghĩa ''nam giới sinh ra ngoài họ mình''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cháu ngoại", "Hạng Tần Suất (Jun Da)": "3800.0", "Tần Suất % (Jun Da)": "99.6794035564", "GavinGrover_Once (Chiết tự trực tiếp)": "生 + 男", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰生男", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "男", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "生", "Unihan_Simplified (Chữ Giản thể)": "甥", "Unihan_Traditional (Chữ Phồn thể)": "甥", "Pinyin_Xie": "shēng", "Âm Hán Việt_Xie": "sanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ quan hệ họ hàng, thường kết hợp với các từ chỉ giới tính hoặc thế hệ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璐', '{"9000": "3801.0", "Chữ Trung Quốc": "璐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 17 | nét | 璐 | lộ | tượng hình | loại ngọc quý đẹp | Cấu trúc 璐 gồm bộ 玉 (ngọc) bên trái và 路 (lộ, đường) bên phải. Nhiều khả năng là chữ hình thanh: 玉 biểu nghĩa (ngọc), 路 biểu âm — nhưng Wiktionary không cung cấp phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộ\" (ngọc lộ): viên ngọc (玉) sáng như con đường (路) dẫn ánh sáng — dùng đặt tên người mang nghĩa quý giá. | Gương Hán-Việt | lộ trong tên người ''璐'' thường gặp trong văn học và tên nhân vật tiểu thuyết Trung Quốc. | Mở khoá kiến thức | Biết 璐 mở khoá họ ngọc quý: 珞 (lạc — chuỗi hạt), 琳 (lâm — ngọc đẹp), 琉 (lưu — ngọc lưu ly).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích nguồn gốc cấu trúc cho 璐. Nhìn vào hình thức: bộ 玉 (ngọc) biểu nghĩa + 路 (lộ) biểu âm là khả năng cao. 璐 chỉ một loại ngọc đẹp, thường dùng trong tên người. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc lộ", "Hạng Tần Suất (Jun Da)": "3801.0", "Tần Suất % (Jun Da)": "99.6797632388", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 路", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王路", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "路", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璐", "Unihan_Traditional (Chữ Phồn thể)": "璐", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loại ngọc quý, chủ yếu dùng trong danh từ riêng hoặc tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晏', '{"9000": "3802.0", "Chữ Trung Quốc": "晏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 10 | nét | 日 | nhật | biểu nghĩa | mặt trời, ngày | 安 | an | biểu âm | yên, bình an | 晏 là chữ hình thanh (psc): 日 (nhật, biểu nghĩa: mặt trời) + 安 (an, biểu âm). Nghĩa: trời trong xanh, yên bình, muộn — mặt trời đã yên vị cuối ngày.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yến\" (trời trong, yên bình, muộn): mặt trời (日) đã an (安) vị — buổi chiều muộn, trời trong lặng. | Gương Hán-Việt | yến trong ''hải yến hà thanh'' (biển lặng sông trong, thiên hạ thái bình), ''yến nhiên'' (yên tĩnh, thư thái). | Mở khoá kiến thức | Biết 晏 mở khoá thành ngữ 河清海晏 (hà thanh hải yến — thiên hạ thái bình) và tên 晏殊 (Yến Thù — nhà thơ Tống).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 晏 là chữ hình thanh: 日 (mặt trời) biểu nghĩa, 安 (an) biểu âm. Nghĩa gốc: trời quang, yên tĩnh; mở rộng sang nghĩa ''muộn trong ngày'', ''bình yên''. Thành ngữ 河清海晏 (hà thanh hải yến — sông trong biển lặng) dùng 晏 theo nghĩa yên bình. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trời trong; muộn; yên; rực rỡ, tươi tốt", "Hạng Tần Suất (Jun Da)": "3802.0", "Tần Suất % (Jun Da)": "99.6801229213", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 安", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日安", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "安", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晏", "Unihan_Traditional (Chữ Phồn thể)": "晏", "Pinyin_Xie": "yàn", "Âm Hán Việt_Xie": "yến", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ chỉ thời gian hoặc trạng thái yên bình. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘪', '{"9000": "3803.0", "Chữ Trung Quốc": "瘪", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 瘪 | biết | tượng hình | lép, óp, teo lại | Cấu trúc 瘪 gồm bộ 疒 (bệnh) và phần 敝 (phế, rách nát). Có thể là chữ hình thanh: 疒 biểu nghĩa (bệnh tật, hao mòn), 敝 biểu âm — nhưng Wiktionary không có phân tích nguồn gốc xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biết\" (lép, teo lại): bộ bệnh (疒) + rách nát (敝) — thứ gì đó bị bệnh teo lại, lép kẹp. | Gương Hán-Việt | biết trong ''biết bĩnh'' ít dùng; tiếng Trung hiện đại có 瘪三 (kẻ xẹp rỗng — người nghèo hèn), 干瘪 (khô héo, lép kẹp). | Mở khoá kiến thức | Biết 瘪 mở khoá 干瘪 (khô héo), 瘪三 (kẻ hèn mọn), 瘪嘴 (miệng móm, tẹt).", "Tự nguyên_Xie": "Không có nguồn học thuật ghi nhận nguồn gốc cấu trúc của 瘪. Bộ 疒 (bệnh tật) gợi ý trạng thái hao mòn, héo tóp. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lép, óp, tẹp; móm, tẹt; bẹp, tóp lại; khẳng khiu", "Hạng Tần Suất (Jun Da)": "3803.0", "Tần Suất % (Jun Da)": "99.6804815702", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 仑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴仑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "瘪", "Unihan_Traditional (Chữ Phồn thể)": "㿜", "Pinyin_Xie": "biě", "Âm Hán Việt_Xie": "biết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Làm tính từ miêu tả trạng thái xẹp lép hoặc động từ chỉ hành động làm cho xẹp đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('漳', '{"9000": "3804.0", "Chữ Trung Quốc": "漳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 14 | nét | 水 | thủy | biểu nghĩa | nước, sông | 章 | chương | biểu âm | chương, bài | 漳 là chữ hình thanh (psc): 水 (thủy, biểu nghĩa: nước) + 章 (chương, biểu âm). Chữ dùng đặt tên sông Chương (漳河, 漳江) tại Trung Quốc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chương\" (sông Chương): nước (水) mang âm chương (章) — con sông nổi tiếng của đất Trung Hoa. | Gương Hán-Việt | chương trong ''漳州'' (Chương Châu — thành phố Phúc Kiến), ''漳河'' (Chương Hà). | Mở khoá kiến thức | Biết 漳 mở khoá địa danh 漳州 (Chương Châu), 漳河 (Chương Hà), 漳浦 (Chương Phố).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 漳 là chữ hình thanh: 水 (nước) biểu nghĩa, 章 biểu âm. Đây là địa danh chuyên dùng chỉ tên các con sông: 漳河 (chảy qua Sơn Tây, Hà Bắc) và 漳江 (chảy qua Phúc Kiến), cũng là tên viết tắt của thành phố 漳州. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sông Chương", "Hạng Tần Suất (Jun Da)": "3804.0", "Tần Suất % (Jun Da)": "99.680840219", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 章", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵章", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "章", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "漳", "Unihan_Traditional (Chữ Phồn thể)": "漳", "Pinyin_Xie": "zhāng", "Âm Hán Việt_Xie": "chương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ riêng chỉ tên sông hoặc địa danh ở Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阉', '{"9000": "3805.0", "Chữ Trung Quốc": "阉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 11 | nét | 阉 | yêm | tượng hình | hoạn, thiến; thái giám | 阉 (dạng phồn thể 閹) cấu trúc gồm bộ 門 (môn, cửa) bao ngoài và 奄 (yêm) bên trong. Nhiều khả năng là chữ hình thanh: 門 biểu nghĩa (kín đáo, bị giam cầm trong cung), 奄 biểu âm. Wiktionary không cung cấp phân tích cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"yêm\" (hoạn, thái giám): người bị nhốt sau cửa cung (門) — kẻ hầu cận trong cung cấm đã bị thiến. | Gương Hán-Việt | yêm trong ''thái yêm'' (thái giám — hoạn quan), ''yêm cát'' (hoạn, thiến gia súc), ''yêm đảng'' (phe cánh thái giám). | Mở khoá kiến thức | Biết 阉 mở khoá 阉割 (yêm cát — thiến, cắt bỏ), 阉人 (yêm nhân — thái giám), 阉党 (yêm đảng — phe thái giám).", "Tự nguyên_Xie": "Wiktionary không phân tích nguồn gốc cấu trúc chi tiết cho 閹/阉. Nhìn hình thức: bộ 門 (cửa) bao 奄 (yêm) bên trong — gợi ý người bị giam trong cung cấm. Nghĩa: hoạn, thiến; thái giám. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hoạn, thiến", "Hạng Tần Suất (Jun Da)": "3805.0", "Tần Suất % (Jun Da)": "99.6811978344", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 奄", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门奄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奄", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阉", "Unihan_Traditional (Chữ Phồn thể)": "閹", "Pinyin_Xie": "yān", "Âm Hán Việt_Xie": "yêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Làm động từ chỉ việc thiến hoạn động vật hoặc danh từ chỉ kẻ bị hoạn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹂', '{"9000": "3806.0", "Chữ Trung Quốc": "蹂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 16 | nét | 蹂 | nhạu | tượng hình | giẫm, xéo, vò lúa | Cấu trúc 蹂 gồm bộ 足 (túc, chân) bên trái và 柔 (nhu) bên phải. Có thể là chữ hình thanh: 足 biểu nghĩa (chân, giẫm), 柔 biểu âm — nhưng Wiktionary không cung cấp phân tích xác nhận ngoài hình thức chữ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhạu\" (giẫm xéo): chân (足) giẫm mềm (柔) nát — hành động chà đạp, áp bức. | Gương Hán-Việt | nhạu trong ''nhạu lận'' (蹂躏 — chà đạp, tàn phá), thường dùng kép. | Mở khoá kiến thức | Biết 蹂 mở khoá 蹂躏 (nhạu lận — chà đạp, giày xéo, tàn phá không thương tiếc).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 蹂. Bộ 足 (chân) gợi ý hành động giẫm, xéo; phần 柔 (nhu) có thể là biểu âm. Nghĩa: giẫm đạp, vò nát. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm, xéo; vò lúa, đạp lúa", "Hạng Tần Suất (Jun Da)": "3806.0", "Tần Suất % (Jun Da)": "99.6815549329", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 柔", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊柔", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "柔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹂", "Unihan_Traditional (Chữ Phồn thể)": "蹂", "Pinyin_Xie": "róu", "Âm Hán Việt_Xie": "nhu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ thường đi kèm với chữ Lận để chỉ hành động chà đạp, tàn hại. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳃', '{"9000": "3807.0", "Chữ Trung Quốc": "鳃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 17 | nét | 鱼 | ngư | biểu nghĩa | cá | 思 | tư | biểu âm | suy nghĩ | 鳃 là dạng giản thể của 鰓. 鰓 là chữ hình thanh: 魚 (ngư, biểu nghĩa: cá) + 思 (tư, biểu âm). Nghĩa: mang cá — cơ quan hô hấp của cá.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tư\" (mang cá): bộ phận của cá (魚) dùng để thở — như mang cá lọc nước như ta lọc suy nghĩ (思). | Gương Hán-Việt | tư ít dùng trong tiếng Việt, thường gặp trong ngữ cảnh sinh học: 鳃 chỉ mang của cá, tôm, cua. | Mở khoá kiến thức | Biết 鳃 mở khoá 鳃盖 (tư cái — nắp mang cá), 腮 (tư — má, quai hàm — đồng âm nhưng khác nghĩa).", "Tự nguyên_Xie": "鳃 là dạng giản thể của 鰓 (phồn thể). 鰓 là chữ hình thanh: 魚 (cá) biểu nghĩa, 思 (tư) biểu âm. Nghĩa: mang cá — bộ phận hô hấp của cá và các loài thủy sinh. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mang cá", "Hạng Tần Suất (Jun Da)": "3807.0", "Tần Suất % (Jun Da)": "99.6819115146", "GavinGrover_Once (Chiết tự trực tiếp)": "鱼 + 思", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鱼思", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "思", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳃", "Unihan_Traditional (Chữ Phồn thể)": "鰓", "Pinyin_Xie": "sāi", "Âm Hán Việt_Xie": "tai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ cơ quan hô hấp của cá và một số động vật dưới nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('琏', '{"9000": "3808.0", "Chữ Trung Quốc": "琏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 11 | nét | 琏 | liễn | tượng hình | bát ngọc đựng lương thực tế lễ | 琏 (dạng phồn thể 璉) cấu trúc gồm bộ 玉 (ngọc) và 连 (liên). Có thể là chữ hình thanh: 玉 biểu nghĩa (ngọc, đồ ngọc), 连 biểu âm — nhưng Wiktionary không phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liễn\" (bát ngọc tế lễ): ngọc (玉) liên kết (连) với nghi lễ — chiếc bát quý đựng thực phẩm dâng cúng trong đền miếu. | Gương Hán-Việt | liễn ít dùng trong tiếng Việt hiện đại, gặp trong văn ngôn: 瑚琏 (hồ liễn — bộ đồ tế lễ cao quý). | Mở khoá kiến thức | Biết 琏 mở khoá 瑚琏 (hồ liễn — đồ tế quý giá, dùng chỉ người tài đức).", "Tự nguyên_Xie": "Lục thư thông | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 璉/琏. Bộ 玉 (ngọc) gợi ý đây là đồ vật bằng ngọc hoặc trang trí ngọc. Nghĩa: bát ngọc dùng đựng xôi trong nghi lễ tế tự thời cổ đại. Chỉ gặp trong văn ngôn và khảo cổ học. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bát đựng xôi cúng", "Hạng Tần Suất (Jun Da)": "3808.0", "Tần Suất % (Jun Da)": "99.6822680964", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 连", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王连", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "连", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "琏", "Unihan_Traditional (Chữ Phồn thể)": "璉", "Pinyin_Xie": "liǎn", "Âm Hán Việt_Xie": "liễn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại bát ngọc dùng trong tế lễ thời xưa, nay ít dùng độc lập. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湃', '{"9000": "3809.0", "Chữ Trung Quốc": "湃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 湃 | bái | tượng hình | tiếng sóng vỗ, nước cuộn trào | Cấu trúc 湃 gồm bộ 水 (thủy, nước) bên trái và 拜 (bái) bên phải. Có thể là chữ hình thanh: 水 biểu nghĩa, 拜 biểu âm — nhưng Wiktionary không cung cấp phân tích xác nhận. 湃 hầu như chỉ dùng trong từ ghép 澎湃.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\" (sóng cuộn): nước (水) vỗ bái bái (拜) — như ngàn sóng dập dồn, cuồn cuộn không ngừng. | Gương Hán-Việt | bái trong 澎湃 (bành bái — cuồn cuộn, sóng vỗ mạnh), thường dùng trong văn học mô tả biển cả. | Mở khoá kiến thức | Biết 湃 mở khoá 澎湃 (bành bái — cuồn cuộn dâng trào), 心潮澎湃 (tâm triều bành bái — lòng dâng trào cảm xúc).", "Tự nguyên_Xie": "Wiktionary ghi nhận hình thức nhưng không phân tích nguồn gốc cấu trúc của 湃. Chữ này hầu như chỉ xuất hiện trong từ kép 澎湃 (âm vang, cuồn cuộn) — dùng tả tiếng sóng mạnh. Bộ 水 gợi ý liên quan đến nước. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước cuộn trào", "Hạng Tần Suất (Jun Da)": "3809.0", "Tần Suất % (Jun Da)": "99.6826241613", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 拜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵拜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "拜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湃", "Unihan_Traditional (Chữ Phồn thể)": "湃", "Pinyin_Xie": "pài", "Âm Hán Việt_Xie": "phái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng làm tính từ miêu tả trạng thái nước chảy mạnh mẽ, phổ biến trong từ ghép như bành bái. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辘', '{"9000": "3810.0", "Chữ Trung Quốc": "辘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 15 | nét | 辘 | lộc | tượng hình | guồng xe, ròng rọc kéo nước | 辘 (dạng phồn thể 轆) cấu trúc gồm bộ 車 (xa, xe) và 录 (lục). Có thể là chữ hình thanh: 車 biểu nghĩa (xe, bánh xe, ròng rọc), 录 biểu âm — nhưng Wiktionary không phân tích xác nhận. Chữ này hầu như chỉ dùng trong từ kép 辘轳.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lộc\" (ròng rọc, guồng xe): bộ xe (車) quay vòng như guồng nước — chiếc 辘轳 kéo nước từ giếng. | Gương Hán-Việt | lộc trong ''辘轳'' (lộc lô — ròng rọc kéo nước, cũng là kỹ thuật thơ từng câu nối đuôi nhau). | Mở khoá kiến thức | Biết 辘 mở khoá 辘轳 (lộc lô — ròng rọc giếng; thể thơ liên hoàn).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận hình thức chữ 轆 (phồn thể). Bộ 車 (xe) gợi ý liên quan đến bánh xe, guồng quay. Nghĩa chính: 辘轳 — ròng rọc kéo nước từ giếng, hoặc bánh xe quay. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lộc lô 轆轤,辘轳)", "Hạng Tần Suất (Jun Da)": "3810.0", "Tần Suất % (Jun Da)": "99.6829802263", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 鹿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车鹿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鹿", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辘", "Unihan_Traditional (Chữ Phồn thể)": "轆", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lộc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ trong các từ ghép liên quan đến trục quay hoặc tiếng bánh xe lăn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('僭', '{"9000": "3811.0", "Chữ Trung Quốc": "僭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 14 | nét | 僭 | tiếm | tượng hình | tiếm đoạt, vượt phận, cướp ngôi | Cấu trúc 僭 gồm bộ 人 (nhân, người) bên trái và 朁 (tán) bên phải. Có thể là chữ hình thanh: 人 biểu nghĩa, 朁 biểu âm — nhưng Wiktionary không phân tích xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiếm\" (tiếm đoạt, cướp ngôi): người (人) tiếm quyền — hành động vượt phận, cướp danh vị không thuộc về mình. | Gương Hán-Việt | tiếm trong ''tiếm ngôi'' (cướp ngôi), ''tiếm quyền'' (cướp quyền), ''僭越'' (tiếm việt — vượt lễ phận). | Mở khoá kiến thức | Biết 僭 mở khoá 僭越 (tiếm việt — vượt lễ phận), 僭称 (tiếm xưng — tự xưng danh hiệu không có quyền), 僭建 (xây dựng trái phép — dùng ở Hồng Kông).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 僭. Bộ 人 (người) gợi ý liên quan đến hành vi con người. Nghĩa: tiếm đoạt, vượt qua lễ phận mà chiếm đoạt quyền bính. Trong tiếng Việt dùng trong từ ''tiếm ngôi'', ''tiếm quyền''. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chiếm đoạt, cướp", "Hạng Tần Suất (Jun Da)": "3811.0", "Tần Suất % (Jun Da)": "99.6833357745", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 朁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻朁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "僭", "Unihan_Traditional (Chữ Phồn thể)": "僭", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "tiếm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Làm động từ thể hiện hành vi vượt quá bổn phận hoặc quyền hạn của mình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('躏', '{"9000": "3812.0", "Chữ Trung Quốc": "躏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 21 | nét | 躏 | lận | tượng hình | giẫm nát, phá hủy | 躏 (dạng phồn thể 躪) cấu trúc gồm bộ 足 (túc, chân) và 粦 (lân). Có thể là chữ hình thanh: 足 biểu nghĩa (chân, giẫm đạp), 粦 biểu âm — nhưng Wiktionary không cung cấp phân tích xác nhận. Hầu như chỉ dùng trong từ kép 蹂躏.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lận\" (giẫm nát): chân (足) giẫm không ngừng — phá tan, chà đạp. Luôn đi cặp với 蹂 thành 蹂躏. | Gương Hán-Việt | lận trong ''蹂躏'' (nhạu lận — chà đạp, giày xéo không thương tiếc). | Mở khoá kiến thức | Biết 躏 mở khoá 蹂躏 (nhạu lận — giày xéo, tàn phá dã man).", "Tự nguyên_Xie": "Wiktionary ghi nhận hình thức nhưng không phân tích nguồn gốc cấu trúc của 躪/躏. Bộ 足 (chân) gợi ý hành động giẫm đạp mạnh. Nghĩa: giẫm nát, chà đạp, tàn phá. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giẫm nát, phá huỷ", "Hạng Tần Suất (Jun Da)": "3812.0", "Tần Suất % (Jun Da)": "99.6836913226", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 蔺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊蔺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蔺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "躏", "Unihan_Traditional (Chữ Phồn thể)": "躪", "Pinyin_Xie": "lìn", "Âm Hán Việt_Xie": "lận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ mang nghĩa chà đạp hoặc tàn phá, thường đi kèm với chữ tàn tạo thành tàn lận. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鼾', '{"9000": "3813.0", "Chữ Trung Quốc": "鼾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鼻 | Số nét | 17 | nét | 鼻 | tỵ | biểu nghĩa | mũi | 干 | can | biểu âm | can, khô | 鼾 là chữ hình thanh (psc): 鼻 (tỵ, biểu nghĩa: mũi) + 干 (can, biểu âm). Nghĩa: tiếng ngáy khi ngủ — âm thanh phát ra từ mũi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạn\" (ngáy): mũi (鼻) kêu to khi khô (干) giấc ngủ — tiếng ngáy ầm ầm lúc ngủ say. | Gương Hán-Việt | hạn trong ''鼾声'' (hạn thanh — tiếng ngáy), ''鼾睡'' (hạn thụy — ngủ ngáy). | Mở khoá kiến thức | Biết 鼾 mở khoá 鼾声如雷 (hạn thanh như lôi — tiếng ngáy như sấm), 打鼾 (đả hạn — ngáy ngủ).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 鼾 là chữ hình thanh: 鼻 (mũi) biểu nghĩa, 干 (can) biểu âm. Nghĩa: ngáy khi ngủ — tiếng thở mạnh qua mũi và họng khi ngủ say. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngáy khi ngủ", "Hạng Tần Suất (Jun Da)": "3813.0", "Tần Suất % (Jun Da)": "99.6840468708", "GavinGrover_Once (Chiết tự trực tiếp)": "鼻 + 干", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰鼻干", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "干", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鼻", "Unihan_Simplified (Chữ Giản thể)": "鼾", "Unihan_Traditional (Chữ Phồn thể)": "鼾", "Pinyin_Xie": "hān", "Âm Hán Việt_Xie": "han, hãn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ tiếng ngáy hoặc động từ chỉ hành động ngáy khi ngủ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('懵', '{"9000": "3814.0", "Chữ Trung Quốc": "懵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 18 | nét | 心 | tâm | biểu nghĩa | tim, tâm trí | 瞢 | mộng | biểu âm | mờ mịt, tối tăm | 懵 là chữ hình thanh (psc): 心 (tâm, biểu nghĩa: tâm trí) + 瞢 (mộng, biểu âm). Nghĩa: tâm trí mờ mịt, hồ đồ, ngây ngơ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mộng\" (hồ đồ, ngây ngơ): tâm trí (心) mờ như trong giấc mộng (瞢) — người không hiểu gì, đờ đẫn. | Gương Hán-Việt | mộng trong ''懵懂'' (mộng đổng — ngây thơ, chưa hiểu biết), ''懵然'' (mộng nhiên — ngơ ngác, không hay biết). | Mở khoá kiến thức | Biết 懵 mở khoá 懵懂 (mộng đổng — ngây thơ vô tư), 一脸懵 (mặt ngây ngô) — thường dùng trong tiếng lóng.", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 懵 là chữ hình thanh: 心 (tâm trí) biểu nghĩa, 瞢 biểu âm. Nghĩa: đần độn, hồ đồ, ngây ngơ không biết gì. Dùng trong 懵懂 (hồ đồ, chưa hiểu biết) và 懵然 (mơ màng, không biết gì). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngu muội; hồ đồ", "Hạng Tần Suất (Jun Da)": "3814.0", "Tần Suất % (Jun Da)": "99.6844008686", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 瞢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄瞢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "瞢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "懵", "Unihan_Traditional (Chữ Phồn thể)": "懵", "Pinyin_Xie": "měng", "Âm Hán Việt_Xie": "mộng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả trạng thái đầu óc mơ hồ, không tỉnh táo hoặc chưa hiểu biết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镰', '{"9000": "3815.0", "Chữ Trung Quốc": "镰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 廉 | liêm | biểu âm | liêm, trong sạch | 镰 là chữ hình thanh (psc): 金 (kim, biểu nghĩa: kim loại) + 廉 (liêm, biểu âm). Nghĩa: lưỡi liềm — công cụ cắt lúa bằng kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liêm\" (lưỡi liềm): kim loại (金) + liêm (廉) — lưỡi liềm cong làm bằng kim loại để gặt lúa. | Gương Hán-Việt | liêm trong ''镰刀'' (liêm đao — lưỡi liềm), ''锤镰'' (chuỳ liêm — búa liềm biểu tượng cộng sản). | Mở khoá kiến thức | Biết 镰 mở khoá 镰刀 (liêm đao — lưỡi liềm), 锤镰 (chuỳ liêm — búa liềm).", "Tự nguyên_Xie": "Tiểu triện | Theo Wiktionary, 镰 (phồn thể 鐮) là chữ hình thanh: 金 (kim loại) biểu nghĩa, 廉 biểu âm. Nghĩa: lưỡi liềm — dụng cụ gặt lúa và cỏ bằng kim loại, có lưỡi cong. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái liềm, lưỡi liềm", "Hạng Tần Suất (Jun Da)": "3815.0", "Tần Suất % (Jun Da)": "99.6847543496", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 廉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅廉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "廉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镰", "Unihan_Traditional (Chữ Phồn thể)": "䥥", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liêm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ công cụ lao động dùng để cắt lúa hoặc cỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寐', '{"9000": "3816.0", "Chữ Trung Quốc": "寐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 12 | nét | 㝱 | mộng | biểu nghĩa | giấc mơ (dạng viết tắt) | 未 | vị | biểu âm | chưa, mùi | 寐 là chữ hình thanh (psc): 㝱 (mộng, dạng tắt của 夢, biểu nghĩa: giấc mơ) + 未 (vị, biểu âm). Dạng gốc có thể là hội ý: nhà (宀) + giường (爿) + người (人) — người ngủ trên giường trong nhà, tương tự cấu trúc cổ của chữ 夢.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mị\" (ngủ say): giấc mộng (㝱) chưa (未) tan — người đang chìm sâu vào giấc ngủ. | Gương Hán-Việt | mị trong ''梦寐'' (mộng mị — trong giấc mơ), ''寤寐'' (ngộ mị — thức và ngủ), ''寐语'' (mị ngữ — nói mê). | Mở khoá kiến thức | Biết 寐 mở khoá 梦寐以求 (mộng mị dĩ cầu — mong mỏi cả trong giấc mơ), 辗转难寐 (nằm trăn trở khó ngủ).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 寐 là chữ hình thanh: 㝱 (dạng tắt của 夢, giấc mơ) biểu nghĩa, 未 biểu âm. Dạng gốc có thể là hội ý: người (人) nằm trên giường (爿) trong nhà (宀) — người ngủ trong phòng. So sánh với dạng cổ của 夢. Nghĩa: ngủ, đang ngủ say. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngủ say", "Hạng Tần Suất (Jun Da)": "3816.0", "Tần Suất % (Jun Da)": "99.6851078307", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "寐", "Unihan_Traditional (Chữ Phồn thể)": "寐", "Pinyin_Xie": "mèi", "Âm Hán Việt_Xie": "mị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ trạng thái ngủ, thường xuất hiện trong các thành ngữ hoặc văn viết cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('褚', '{"9000": "3817.0", "Chữ Trung Quốc": "褚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 衣 | Số nét | 13 | nét | 衣 | y | biểu nghĩa | áo, quần áo | 者 | giả | biểu âm | người, kẻ | 褚 là chữ hình thanh (psc): 衣 (y, biểu nghĩa: quần áo) + 者 (giả, biểu âm). Nghĩa: bông độn trong áo, đồ chứa; cũng dùng làm họ người.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trữ\" (bông áo, lưu trữ): áo (衣) của kẻ (者) lưu trữ — bông độn trong áo để giữ ấm; họ 褚 cũng phổ biến. | Gương Hán-Việt | trữ trong họ ''褚'' (Trữ — họ người Trung Quốc), ''褚衣'' (trữ y — áo bông). | Mở khoá kiến thức | Biết 褚 mở khoá 储 (trữ — cất giữ), 贮 (trữ — dự trữ) — cùng âm, cùng nghĩa ''lưu trữ''.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 褚 là chữ hình thanh: 衣 (quần áo) biểu nghĩa, 者 biểu âm. Nghĩa gốc: bông tơ độn trong áo mùa đông; mở rộng sang nghĩa ''túi, đồ chứa''. Cũng dùng làm họ người (Bộ Trữ). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bông; áo bông; túi áo; cái túi", "Hạng Tần Suất (Jun Da)": "3817.0", "Tần Suất % (Jun Da)": "99.6854613117", "GavinGrover_Once (Chiết tự trực tiếp)": "衤 + 者", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰衤者", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "者", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "衤", "Unihan_Simplified (Chữ Giản thể)": "褚", "Unihan_Traditional (Chữ Phồn thể)": "褚", "Pinyin_Xie": "chǔ", "Âm Hán Việt_Xie": "trử", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ trang phục lót bông, túi đựng đồ hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('攥', '{"9000": "3818.0", "Chữ Trung Quốc": "攥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 23 | nét | 攥 | toản | tượng hình | nắm chặt, giữ chặt | Cấu trúc 攥 gồm bộ 扌 (thủ, tay) bên trái và phần còn lại bên phải. Wiktionary ghi nhận hình thức nhưng không phân tích rõ cấu trúc hình thanh hay hội ý.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toản\" (nắm chặt): bộ tay (扌) nắm thật chặt — không buông tay, giữ chặt không rời. | Gương Hán-Việt | toản ít dùng trong Hán-Việt; tiếng Trung hiện đại có 攥拳头 (toản quyền đầu — nắm chặt nắm đấm), 攥住 (nắm chặt). | Mở khoá kiến thức | Biết 攥 mở khoá 攥拳头 (nắm chặt nắm đấm), 攥在手中 (nắm trong tay).", "Tự nguyên_Xie": "Wiktionary ghi nhận hình thức của 攥 nhưng không phân tích nguồn gốc cấu trúc. Bộ 扌 (tay) biểu nghĩa hành động nắm. Nghĩa: nắm chặt, giữ chặt trong lòng bàn tay. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cầm, nắm, giữ", "Hạng Tần Suất (Jun Da)": "3818.0", "Tần Suất % (Jun Da)": "99.685814276", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 纂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌纂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "纂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "攥", "Unihan_Traditional (Chữ Phồn thể)": "攥", "Pinyin_Xie": "zuàn", "Âm Hán Việt_Xie": "toản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động dùng tay nắm chặt lấy một vật gì đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涧', '{"9000": "3819.0", "Chữ Trung Quốc": "涧", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 水 | thủy | biểu nghĩa | nước | 閒 | nhàn | biểu âm | nhàn, khoảng hở | 涧 là chữ hình thanh (psc): 水 (thủy, biểu nghĩa: nước) + 閒 (nhàn, biểu âm). Nghĩa: khe suối, dòng nước nhỏ chảy giữa núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giản\" (khe suối): nước (水) chảy trong khoảng hở (閒) giữa núi — dòng khe suối yên tĩnh. | Gương Hán-Việt | giản trong ''溪涧'' (khê giản — khe suối), ''山涧'' (sơn giản — suối núi). | Mở khoá kiến thức | Biết 涧 mở khoá 山涧 (sơn giản — khe suối núi), 溪涧 (khê giản — suối khe).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 涧 (phồn thể 澗) là chữ hình thanh: 水 (nước) biểu nghĩa, 閒 biểu âm. Nghĩa: khe suối núi — dòng nước nhỏ chảy giữa các vách đá hay thung lũng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khe suối", "Hạng Tần Suất (Jun Da)": "3819.0", "Tần Suất % (Jun Da)": "99.6861662066", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 间", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵间", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "间", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涧", "Unihan_Traditional (Chữ Phồn thể)": "㵎", "Pinyin_Xie": "jiàn", "Âm Hán Việt_Xie": "giản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ địa hình khe suối nhỏ ở vùng núi rừng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝙', '{"9000": "3820.0", "Chữ Trung Quốc": "蝙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝙 | biên | tượng hình | con dơi (trong từ 蝙蝠) | Cấu trúc 蝙 gồm bộ 虫 (trùng, côn trùng) và 扁 (biển). Có thể là chữ hình thanh: 虫 biểu nghĩa (sinh vật), 扁 biểu âm — nhưng Wiktionary không phân tích xác nhận. 蝙 gần như chỉ xuất hiện trong từ 蝙蝠 (con dơi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"biên\" (con dơi — trong 蝙蝠): sinh vật (虫) dẹp mỏng (扁) bay trong đêm — con dơi dẹp người nhưng biết bay. | Gương Hán-Việt | biên trong ''蝙蝠'' (biên bức — con dơi), ''蝙蝠侠'' (biên bức hiệp — Batman). | Mở khoá kiến thức | Biết 蝙 mở khoá 蝙蝠 (biên bức — con dơi), 蝙蝠侠 (Batman — Người Dơi).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 蝙. Bộ 虫 (sinh vật) gợi ý đây là sinh vật. 蝙 hầu như chỉ dùng trong từ 蝙蝠 (biên bức — con dơi). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: biển bức 蝙蝠)", "Hạng Tần Suất (Jun Da)": "3820.0", "Tần Suất % (Jun Da)": "99.6865171037", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 扁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫扁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "扁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝙", "Unihan_Traditional (Chữ Phồn thể)": "蝙", "Pinyin_Xie": "biān", "Âm Hán Việt_Xie": "biên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ khi kết hợp thành từ ghép để chỉ loài dơi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('脐', '{"9000": "3821.0", "Chữ Trung Quốc": "脐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 肉 | nhục | biểu nghĩa | thịt, thân thể | 齊 | tề | biểu âm | đều, tề chỉnh | 脐 là chữ hình thanh (psc): 肉 (nhục, biểu nghĩa: thịt/thân thể) + 齊 (tề, biểu âm). Nghĩa: rốn, cuống rốn; cũng chỉ yếm con cua.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tề\" (rốn): thịt (肉) tề (齊) trung tâm — cái rốn ở điểm chính giữa bụng người. | Gương Hán-Việt | tề trong ''肚脐'' (độ tề — rốn), ''脐带'' (tề đới — cuống rốn). | Mở khoá kiến thức | Biết 脐 mở khoá 肚脐 (độ tề — cái rốn), 脐带 (tề đới — cuống rốn), 脐橙 (tề trành — cam rốn lồi).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Theo Wiktionary, 脐 (phồn thể 臍) là chữ hình thanh: 肉 (thịt/thân thể) biểu nghĩa, 齊 biểu âm. Nghĩa: rốn — điểm trung tâm bụng nơi cuống rốn được nối; cũng dùng chỉ yếm con cua. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rốn, cuống rốn; yếm con cua", "Hạng Tần Suất (Jun Da)": "3821.0", "Tần Suất % (Jun Da)": "99.6868669673", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 齐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月齐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "齐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "脐", "Unihan_Traditional (Chữ Phồn thể)": "臍", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "tề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau định ngữ hoặc kết hợp tạo từ ghép chỉ bộ phận cơ thể. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('辕', '{"9000": "3822.0", "Chữ Trung Quốc": "辕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 14 | nét | 车 | xa | biểu nghĩa | xe | 袁 | viên | biểu âm | họ Viên | 辕 = 车 (Xa, biểu nghĩa: xe) + 袁 (Viên, biểu âm). Đây là dạng giản thể của 轅 (phồn thể). Wiktionary ghi là giản thể của 轅, không có phân tích ls riêng. Cấu trúc phono-semantic: 车 chỉ xe cộ, 袁 biểu âm yuán.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"viên\": chiếc xe (车) mang họ Viên (袁) kéo đi — đó là những cái càng xe dài phía trước. | Gương Hán-Việt | \"viên\" trong 辕门 (viên môn — cổng doanh trại xưa), 辕马 (viên mã — ngựa kéo xe) | Mở khoá kiến thức | Biết 辕 mở khoá 辕门 (cổng doanh trại), 南辕北辙 (thành ngữ: đi ngược hướng mục tiêu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 辕 (viên) là dạng giản thể của 轅, gồm bộ 车 (Xa — xe) biểu nghĩa và 袁 (Viên) biểu âm yuán. Nghĩa gốc: càng xe — hai thanh gỗ song song gắn vào xe ngựa để điều khiển. Mở rộng nghĩa: dinh quan (ngày xưa quan lại dùng xe có càng). Hình tiểu triện và lục thư thông được lưu tại hanziyuan.net. Chỉ có các giai đoạn muộn (tiểu triện, lục thư thông). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "càng xe, tay xe", "Hạng Tần Suất (Jun Da)": "3822.0", "Tần Suất % (Jun Da)": "99.6872157972", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 袁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车袁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "袁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "辕", "Unihan_Traditional (Chữ Phồn thể)": "轅", "Pinyin_Xie": "yuán", "Âm Hán Việt_Xie": "viên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ bộ phận của xe cổ hoặc dùng trong các từ ghép liên quan đến xe cộ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涣', '{"9000": "3823.0", "Chữ Trung Quốc": "涣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 涣 | hoán | tượng hình | tan tác, phân tán | Cấu trúc 涣 gồm bộ 水 (thủy, nước) bên trái và 奂 (hoán) bên phải. Có thể là chữ hình thanh: 水 biểu nghĩa (nước chảy lan), 奂 biểu âm — nhưng Wiktionary không cung cấp phân tích cấu trúc xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoán\" (tan tác, rã rời): nước (水) lan hoán (奂) tứ phía — mọi thứ tan chảy, phân tán không gom lại được. | Gương Hán-Việt | hoán trong ''涣散'' (hoán tán — rã rời, mất đoàn kết), ''涣然冰释'' (hoán nhiên băng thích — như băng tan — giải tỏa hết lo ngại). | Mở khoá kiến thức | Biết 涣 mở khoá 涣散 (hoán tán — rã rời), 涣然冰释 (tan như băng — hết lo lắng), 人心涣散 (lòng người ly tán).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 渙/涣. Bộ 水 (nước) gợi ý nghĩa liên quan đến nước tan chảy, phân tán. Nghĩa: tan tác, rã rời; cũng có nghĩa ''tràn lan''. Quẻ số 59 trong Kinh Dịch. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tan tác", "Hạng Tần Suất (Jun Da)": "3823.0", "Tần Suất % (Jun Da)": "99.6875641104", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 奂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵奂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涣", "Unihan_Traditional (Chữ Phồn thể)": "渙", "Pinyin_Xie": "huàn", "Âm Hán Việt_Xie": "hoán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho danh từ hoặc động từ để chỉ trạng thái tan rã, suy yếu. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('杞', '{"9000": "3824.0", "Chữ Trung Quốc": "杞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 7 | nét | 杞 | kỷ | tượng hình | cây kỷ liễu, cây câu kỷ; nước Khởi | Cấu trúc 杞 gồm bộ 木 (mộc, cây) bên trái và 己 (kỷ) bên phải. Có thể là chữ hình thanh: 木 biểu nghĩa (cây), 己 biểu âm — nhưng Wiktionary không phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỷ\" (cây kỷ, nước Kỷ): cây (木) kỷ (己) — cây liễu, cũng là nước Kỷ nổi tiếng vì lo sợ trời sập (杞人忧天). | Gương Hán-Việt | kỷ trong ''杞人忧天'' (kỷ nhân ưu thiên — người nước Kỷ lo trời sập — lo xa vô ích), ''枸杞'' (câu kỷ — cây câu kỷ). | Mở khoá kiến thức | Biết 杞 mở khoá thành ngữ 杞人忧天 (lo xa vô lý), 枸杞 (câu kỷ tử — kỷ tử bổ dưỡng).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Tiểu triện | Lục thư thông | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 杞. Bộ 木 (cây) gợi ý đây là loài cây. Nghĩa: một loài liễu (Salix integra), cây câu kỷ (wolfberry). Cũng là tên nước Khởi thời Chu. Nổi tiếng qua thành ngữ 杞人忧天 (Người nước Kỷ lo trời sập). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước Khởi (tên nước thời nhà Chu, Trung Quốc); họ Khởi", "Hạng Tần Suất (Jun Da)": "3824.0", "Tần Suất % (Jun Da)": "99.6879124236", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 己", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木己", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "己", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "杞", "Unihan_Traditional (Chữ Phồn thể)": "杞", "Pinyin_Xie": "qǐ", "Âm Hán Việt_Xie": "kỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ riêng chỉ tên nước cổ, họ người hoặc tên một loại cây dược liệu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('煜', '{"9000": "3825.0", "Chữ Trung Quốc": "煜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 13 | nét | 煜 | dục | tượng hình | rực rỡ, sáng chói | Cấu trúc 煜 gồm bộ 火 (hoả, lửa) bên trái và 昱 (dục) bên phải. Có thể là chữ hình thanh: 火 biểu nghĩa (ánh sáng, lửa), 昱 biểu âm — nhưng Wiktionary không phân tích xác nhận cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dục\" (rực rỡ): lửa (火) sáng rực (昱) — ánh sáng rực rỡ chói lòa; thường dùng đặt tên người. | Gương Hán-Việt | dục trong tên người ''李煜'' (Lý Dục — hoàng đế nhà Nam Đường, nhà thơ nổi tiếng), ''煜煜'' (dục dục — sáng rực). | Mở khoá kiến thức | Biết 煜 mở khoá 煜煜 (dục dục — sáng chói), tên Lý Dục (李煜) — nhà thơ Nam Đường lừng danh.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 煜. Bộ 火 (lửa) gợi ý liên quan đến ánh sáng rực rỡ. Nghĩa: sáng chói, rực rỡ. Thường dùng trong tên người. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọn lửa", "Hạng Tần Suất (Jun Da)": "3825.0", "Tần Suất % (Jun Da)": "99.6882607368", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 昱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火昱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "昱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "煜", "Unihan_Traditional (Chữ Phồn thể)": "煜", "Pinyin_Xie": "yù", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ miêu tả trạng thái sáng sủa, rực rỡ hoặc dùng trong tên riêng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('骥', '{"9000": "3826.0", "Chữ Trung Quốc": "骥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 馬 | Số nét | 19 | nét | 骥 | ký | tượng hình | ngựa chiến tốt, tuấn mã | 骥 là dạng giản thể của 驥. 驥 là chữ hình thanh: 馬 (mã, biểu nghĩa: ngựa) + 冀 (ký, biểu âm). Nghĩa: ngựa hay, tuấn mã — ngựa chạy một ngàn dặm một ngày; ẩn dụ người tài kiệt xuất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ký\" (tuấn mã, ngựa hay): bộ ngựa (马) + ký (冀, mong ước) — con ngựa mà ai cũng mong muốn, vượt ngàn dặm một ngày. | Gương Hán-Việt | ký trong ''千里骥'' (thiên lý ký — ngựa ngàn dặm), ''老骥伏枥'' (lão ký phục lịch — ngựa già nằm máng, vẫn chí khí ngàn dặm). | Mở khoá kiến thức | Biết 骥 mở khoá 老骥伏枥 (lão ký phục lịch — già nhưng chí không sờn), 骥尾 (ký vĩ — đứng sau người tài — khiêm tốn).", "Tự nguyên_Xie": "Tiểu triện | 骥 là dạng giản thể của 驥 (phồn thể). 驥 là chữ hình thanh: 馬 (ngựa) biểu nghĩa, 冀 (ký) biểu âm. Nghĩa: ngựa hay, tuấn mã — giống ngựa chạy nhanh ngàn dặm. Trong văn học Trung Quốc, 骥 thường dùng ẩn dụ chỉ người có tài năng xuất chúng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa tốt; tuấn mã; hiền tài; người tài; người có tài đặc biệt", "Hạng Tần Suất (Jun Da)": "3826.0", "Tần Suất % (Jun Da)": "99.68860905", "GavinGrover_Once (Chiết tự trực tiếp)": "马 + 冀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰马冀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "马", "Unihan_Simplified (Chữ Giản thể)": "骥", "Unihan_Traditional (Chữ Phồn thể)": "驥", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "kí", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ làm chủ ngữ hoặc tân ngữ trong văn viết để ví với người có tài năng xuất chúng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傣', '{"9000": "3827.0", "Chữ Trung Quốc": "傣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 12 | nét | 傣 | thái | tượng hình | người Thái, dân tộc Thái Vân Nam | Cấu trúc 傣 gồm bộ 人 (nhân, người) bên trái và 泰 (thái) bên phải. Có thể là chữ hình thanh: 人 biểu nghĩa, 泰 biểu âm — chữ tạo ra để phiên âm tên dân tộc Thái. Không có phân tích Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thái\" (dân tộc Thái): bộ người (人) + thái (泰) — người Thái, dân tộc thiểu số miền tây nam Trung Quốc, liên quan đến dân tộc Thái ở Đông Nam Á. | Gương Hán-Việt | thái trong ''傣族'' (Thái tộc — dân tộc Thái), ''傣语'' (Thái ngữ — tiếng Thái). | Mở khoá kiến thức | Biết 傣 mở khoá 傣族 (Thái tộc), 傣历 (Thái lịch — lịch của người Thái), 傣语 (tiếng Thái).", "Tự nguyên_Xie": "傣 là chữ mới tạo để ghi tên dân tộc Thái (Dai people) sống ở tỉnh Vân Nam, Trung Quốc và vùng Đông Nam Á. Bộ 人 (người) + 泰 (thái) biểu âm — tên phiên âm của dân tộc Thái. Đây là chữ tạo muộn, chưa có giáp cốt hay kim văn. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dân tộc Thái ở tỉnh Vân Nam của Trung Quốc", "Hạng Tần Suất (Jun Da)": "3827.0", "Tần Suất % (Jun Da)": "99.6889563296", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 泰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻泰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "泰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傣", "Unihan_Traditional (Chữ Phồn thể)": "傣", "Pinyin_Xie": "dǎi", "Âm Hán Việt_Xie": "thái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ tộc người hoặc làm định ngữ đứng trước danh từ khác để chỉ thuộc tính dân tộc này. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗳', '{"9000": "3828.0", "Chữ Trung Quốc": "嗳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 13 | nét | 嗳 | ái | tượng hình | thán từ: ôi, ớ, ơ | Cấu trúc 嗳 gồm bộ 口 (khẩu, miệng) bên trái và 爱 (ái, yêu) bên phải. Có thể là chữ hình thanh: 口 biểu nghĩa (miệng — dùng miệng phát âm), 爱 biểu âm. Đây là chữ thuần ngữ âm — ghi tiếng thán từ. Không có phân tích Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ái\" (thán từ ngạc nhiên): miệng (口) phát ra tiếng ái! — tiếng kêu ngạc nhiên, không đồng ý hoặc thở dài. | Gương Hán-Việt | ái ít dùng trong Hán-Việt; 嗳 là thán từ trong tiếng Trung: 嗳 (āi — ôi, ớ), 嗳 (ài — thở dài). | Mở khoá kiến thức | Biết 嗳 mở khoá các thán từ: 嗳 (āi — ôi trời), 哎 (āi — ôi, ái), 嗯 (ń — ừ, hm).", "Tự nguyên_Xie": "嗳 không có nguồn học thuật ghi nhận nguồn gốc cấu trúc. Bộ 口 (miệng) biểu nghĩa — dùng miệng phát ra thán từ. Đây là từ ngữ âm thuần túy, ghi tiếng kêu ngạc nhiên, không tán đồng hoặc thở dài. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ôi, ớ, ơ (thán từ chỉ sự ngạc nhiên)", "Hạng Tần Suất (Jun Da)": "3828.0", "Tần Suất % (Jun Da)": "99.6893036092", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 爱", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口爱", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "爱", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗳", "Unihan_Traditional (Chữ Phồn thể)": "噯", "Pinyin_Xie": "āi", "Âm Hán Việt_Xie": "ái, ai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng đầu câu làm thán từ để biểu thị sự ngạc nhiên, hối tiếc hoặc không đồng ý. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('祯', '{"9000": "3829.0", "Chữ Trung Quốc": "祯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 示 | Số nét | 10 | nét | 祯 | trinh | tượng hình | điềm lành, may mắn | Cấu trúc 祯 gồm bộ 示 (thị, thần linh/lễ) bên trái và 贞 (trinh) bên phải. Có thể là chữ hình thanh: 示 biểu nghĩa (thần linh, điềm trời), 贞 biểu âm — nhưng Wiktionary không phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trinh\" (điều tốt lành): thần linh (示) ban trinh (贞, chính trực) — điềm lành từ trời ban, thường đặt tên người. | Gương Hán-Việt | trinh trong ''祯祥'' (trinh tường — điềm lành, may mắn), ''崇祯'' (Sùng Trinh — niên hiệu cuối nhà Minh). | Mở khoá kiến thức | Biết 祯 mở khoá 祯祥 (trinh tường — may mắn tốt lành), 崇祯 (Sùng Trinh — hoàng đế cuối Minh).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 禎/祯. Bộ 示 (thần linh, lễ nghi) gợi ý liên quan đến điềm trời, thần linh ban phúc. Nghĩa: may mắn, điều tốt lành. Thường dùng trong tên người. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "điều tốt lành", "Hạng Tần Suất (Jun Da)": "3829.0", "Tần Suất % (Jun Da)": "99.6896508888", "GavinGrover_Once (Chiết tự trực tiếp)": "礻 + 贞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰礻贞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "礻", "Unihan_Simplified (Chữ Giản thể)": "祯", "Unihan_Traditional (Chữ Phồn thể)": "禎", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "trinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ điềm lành hoặc tính từ trong văn viết cổ và tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酉', '{"9000": "3830.0", "Chữ Trung Quốc": "酉", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 7 | nét | 酉 | dậu | tượng hình | bình rượu đáy nhọn; chi Dậu (thứ 10 trong 12 địa chi) | 酉 là chữ tượng hình (p): hình vẽ bình rượu có đáy nhọn. Đây là dạng gốc của chữ 酒 (rượu). So sánh với 酋 (thêm nét chỉ rượu ủ lâu) và 尊 (hai tay nâng bình rượu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dậu\" (Dậu, bình rượu): hình bình rượu đáy nhọn — dạng gốc của 酒 (rượu). Con Gà (Dậu) giữ cái bình rượu thiêng liêng. | Gương Hán-Việt | dậu trong ''giờ Dậu'' (17-19h — giờ con Gà), ''năm Dậu'' (năm con Gà), bộ 酉 trong 酒 (tửu — rượu), 酸 (toán — chua). | Mở khoá kiến thức | Biết 酉 mở khoá cả bộ rượu: 酒 (tửu), 醉 (túy — say), 酸 (toán — chua), 配 (phối — pha trộn).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 酉 là chữ tượng hình: hình vẽ bình rượu có đáy nhọn. Đây là dạng gốc của 酒 (rượu). So sánh với 酋 (bình rượu với nét thêm biểu thị rượu ủ lâu hoặc trang trí) và 尊 (hai tay nâng bình rượu). Về hình thức giống 西 (tây) nhưng hoàn toàn khác nguồn gốc (西 vốn vẽ tổ chim). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1217.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Nhất (001) Tây (185)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Nhất (一) gạch ở bên trong chữ Tây (số 185 / 西). Hình ảnh cái vỏ bình rượu có nước rượu bên trong. Giải thích sự chuyển ý: Đây là chữ Tượng hình. Dậu vốn chỉ rượu. Nó cũng được dùng làm một trong 12 Địa Chi (năm Dậu).", "Nghĩa Tiếng Việt_Xie": "Dậu (ngôi thứ 10 hàng Chi)", "Hạng Tần Suất (Jun Da)": "3830.0", "Tần Suất % (Jun Da)": "99.6899976516", "GavinGrover_Once (Chiết tự trực tiếp)": "兀 + 日", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱兀日", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "兀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "酉", "Unihan_Traditional (Chữ Phồn thể)": "酉", "Pinyin_Xie": "yǒu", "Âm Hán Việt_Xie": "dậu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ thời gian như giờ Dậu, năm Dậu hoặc phương hướng trong hệ chi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('秸', '{"9000": "3831.0", "Chữ Trung Quốc": "秸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 11 | nét | 秸 | gặt | tượng hình | cọng rơm sau khi đập lúa | Cấu trúc 秸 gồm bộ 禾 (hoà, lúa) bên trái và 吉 (cát) bên phải. Có thể là chữ hình thanh: 禾 biểu nghĩa (lúa, ngũ cốc), 吉 biểu âm — nhưng Wiktionary không phân tích xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"gặt\" (cọng rơm): lúa (禾) còn lại cát (吉) sau gặt — những cọng rơm khô sau mùa thu hoạch. | Gương Hán-Việt | gặt ít dùng trong Hán-Việt hiện đại; tiếng Trung có 秸秆 (gặt cán — thân rơm rạ), 麦秸 (mạch gặt — rơm lúa mì). | Mở khoá kiến thức | Biết 秸 mở khoá 秸秆 (thân rơm rạ), 麦秸 (rơm lúa mì), 秸秆还田 (cày rơm vào đất).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận hình thức nhưng không phân tích cấu trúc nguồn gốc của 秸. Bộ 禾 (lúa) gợi ý liên quan đến ngũ cốc. Nghĩa: cọng rơm còn lại sau khi đập lúa — phần thân cây lúa, kê, bắp sau thu hoạch. Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lõi của cọng rơm", "Hạng Tần Suất (Jun Da)": "3831.0", "Tần Suất % (Jun Da)": "99.6903438977", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 吉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾吉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "秸", "Unihan_Traditional (Chữ Phồn thể)": "秸", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "kiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp với tên cây trồng để chỉ phần thân sau khi thu hoạch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('捺', '{"9000": "3832.0", "Chữ Trung Quốc": "捺", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 奈 | nại | biểu âm | sao, thế nào | 捺 là chữ hình thanh (psc): 扌 (thủ, biểu nghĩa: tay) + 奈 (nại, biểu âm). Nghĩa: đè ấn mạnh bằng tay; trong thư pháp chỉ nét phảy đổ xuống bên phải (㇏).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nài\" (đè ấn, nét phảy): tay (扌) đè nài (奈) xuống — ấn mạnh, cũng là nét phảy (捺) đổ xuống phải trong thư pháp. | Gương Hán-Việt | nài trong ''按捺'' (án nài — kìm nén, không để lộ cảm xúc), ''捺印'' (nài ấn — đóng dấu ngón tay). | Mở khoá kiến thức | Biết 捺 mở khoá 按捺不住 (không kìm được — cảm xúc bùng phát), 捺印 (đóng dấu vân tay).", "Tự nguyên_Xie": "Theo Wiktionary, 捺 là chữ hình thanh: bộ 手/扌 (tay) biểu nghĩa, 奈 biểu âm. Nghĩa gốc: đè ấn bằng tay, đóng dấu. Trong thư pháp Hán tự, 捺 chỉ nét chính đổ xuống bên phải (㇏) — một trong tám nét cơ bản. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đè ép, ấn; nét phảy", "Hạng Tần Suất (Jun Da)": "3832.0", "Tần Suất % (Jun Da)": "99.6906901437", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 奈", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌奈", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奈", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "捺", "Unihan_Traditional (Chữ Phồn thể)": "捺", "Pinyin_Xie": "nà", "Âm Hán Việt_Xie": "nại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ chỉ hành động đè nén hoặc làm danh từ chỉ nét mác trong bút họa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瑕', '{"9000": "3833.0", "Chữ Trung Quốc": "瑕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 13 | nét | 𤣩 | ngọc | biểu nghĩa | ngọc (dạng viết bên cạnh của 玉) | 叚 | hà | biểu âm | giả, mượn | 瑕 là chữ hình thanh (psc): 𤣩 (bộ bên cạnh của 玉, biểu nghĩa: ngọc) + 叚 (hà, biểu âm). Nghĩa: vết trên ngọc, khuyết điểm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\" (vết ngọc, khuyết điểm): ngọc (𤣩) có vết (叚) — vết tì bợn trong viên ngọc quý, ẩn dụ cho lỗi lầm nhỏ. | Gương Hán-Việt | hà trong ''瑕疵'' (hà tì — khuyết điểm, lỗi), ''瑕不掩瑜'' (hà bất yểm du — tốt nhiều hơn xấu), ''无瑕'' (vô hà — không tì vết, hoàn hảo). | Mở khoá kiến thức | Biết 瑕 mở khoá 瑕疵 (hà tì — khuyết điểm), 无瑕 (vô hà — hoàn hảo), 瑕不掩瑜 (ưu điểm lớn hơn nhược điểm).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Theo Wiktionary, 瑕 là chữ hình thanh: 玉 (bộ 𤣩, ngọc) biểu nghĩa, 叚 biểu âm. Nghĩa gốc: vết tì trên viên ngọc. Mở rộng sang nghĩa khuyết điểm, lỗi lầm. Thành ngữ 瑕不掩瑜 (hà bất yểm du — vết nhỏ không che lấp được vẻ đẹp lớn). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vết trên viên ngọc", "Hạng Tần Suất (Jun Da)": "3833.0", "Tần Suất % (Jun Da)": "99.6910363897", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "瑕", "Unihan_Traditional (Chữ Phồn thể)": "瑕", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng sau các từ chỉ ngọc hoặc dùng để chỉ khuyết điểm nói chung. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鑫', '{"9000": "3834.0", "Chữ Trung Quốc": "鑫", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 24 | nét | 金 | kim | biểu nghĩa | vàng, kim loại (x3) | 金 | kim | biểu nghĩa | vàng, kim loại (x3) | 金 | kim | biểu nghĩa | vàng, kim loại (x3) | 鑫 là chữ đặc biệt — ba chữ 金 (vàng) xếp theo dạng kim tự tháp (上下结构). Giống cách 森 (ba cây = rừng) hay 淼 (ba nước = mênh mông), ba chữ 金 biểu thị sự giàu có dồi dào.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hân\" (giàu thịnh): ba chữ vàng (金金金) chồng lên nhau — giàu có gấp ba, sung túc tột bậc. | Gương Hán-Việt | hân trong tên công ty ''鑫'' (Hân — thịnh vượng), tên người ''鑫'' thường đặt cho con cái với mong ước giàu sang. | Mở khoá kiến thức | Biết 鑫 mở khoá cấu trúc ''ba giống nhau'' của Hán tự: 森 (ba 木 — rừng), 淼 (ba 水 — mênh mông), 晶 (ba 日 — sáng ngời).", "Tự nguyên_Xie": "Theo Wiktionary, 鑫 được tạo bằng cách viết ba chữ 金 (vàng) — một cách tạo chữ đặc trưng của Hán tự: nhân ba yếu tố cùng loại để cực đại hóa nghĩa. Giống 森 (ba 木 = rừng), 淼 (ba 水 = mênh mông). Nghĩa: sung túc, giàu có, thịnh vượng. Chủ yếu dùng trong tên người và tên công ty. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "giàu, thịnh vượng", "Hạng Tần Suất (Jun Da)": "3834.0", "Tần Suất % (Jun Da)": "99.6913826358", "GavinGrover_Once (Chiết tự trực tiếp)": "金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "品 (Kiến trúc tam giác)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "鑫", "Unihan_Traditional (Chữ Phồn thể)": "鑫", "Pinyin_Xie": "xīn", "Âm Hán Việt_Xie": "hâm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường dùng làm tính từ mang nghĩa cát tường hoặc dùng trong tên riêng để cầu tài lộc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('馋', '{"9000": "3835.0", "Chữ Trung Quốc": "馋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 食 | Số nét | 12 | nét | 饣 | thực | biểu nghĩa | ăn, thức ăn | 𫥎 | sàm | biểu âm | thành phần biểu âm chán | 馋 = 饣 (Thực, biểu nghĩa: thức ăn) + 𫥎 (Sàm, biểu âm). Dạng phồn thể 饞 = 飠(食) + 毚 (ls=psc). Wiktionary ghi rõ ls=psc (hình thanh): 食 (饣) cho nghĩa, 毚 cho âm chán. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sàm\": thức ăn (饣) cứ lởn vởn trong đầu — háu ăn, thèm ăn không dứt. | Gương Hán-Việt | \"sàm\" ít dùng trong tiếng Việt hiện đại; 馋 chủ yếu dùng mô tả người háu ăn, thèm ăn | Mở khoá kiến thức | Biết 馋 mở khoá 馋嘴 (miệng thèm ăn), 嘴馋 (hay thèm ăn vặt), 馋猫 (người thèm ăn — kiểu mèo thèm).", "Tự nguyên_Xie": "Chữ 馋 (sàm), phồn thể 饞, là chữ hình thanh (ls=psc): bộ 食 (饣 — Thực) biểu nghĩa chỉ ăn uống, thức ăn; 毚 biểu âm cho âm chán. Nghĩa gốc: háu ăn, thèm thuồng quá mức. Mở rộng sang nghĩa ham muốn, thèm khát nói chung. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thèm thuồng; tham ăn", "Hạng Tần Suất (Jun Da)": "3835.0", "Tần Suất % (Jun Da)": "99.691728365", "GavinGrover_Once (Chiết tự trực tiếp)": "饣 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰饣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "馋", "Unihan_Traditional (Chữ Phồn thể)": "饞", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "sàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho người hoặc làm động từ thể hiện sự thèm khát đồ ăn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | chán | / | háu ăn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Tính cách tôi | HSK | HSK 6 | · | Thức ăn và đồ uống", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('窿', '{"9000": "3836.0", "Chữ Trung Quốc": "窿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 穴 | Số nét | 16 | nét | 穴 | huyệt | biểu nghĩa | hang, hố | 隆 | long | biểu âm | long, to lớn | 窿 là chữ hình thanh (psc): 穴 (huyệt, biểu nghĩa: hang hố) + 隆 (long, biểu âm). Nghĩa: hầm mỏ, hố trũng; dùng trong 窟窿 (lỗ thủng, nợ nần).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"long\" (hầm hố, lỗ thủng): hang hố (穴) + long (隆) — hầm sâu to tướng; trong 窟窿 chỉ cái lỗ hay nợ nần. | Gương Hán-Việt | long trong ''窟窿'' (quật long — lỗ thủng, nợ chưa trả), thường dùng trong khẩu ngữ. | Mở khoá kiến thức | Biết 窿 mở khoá 窟窿 (quật long — lỗ thủng; khẩu ngữ: nợ tiền, thâm hụt).", "Tự nguyên_Xie": "Theo Wiktionary, 窿 là chữ hình thanh: 穴 (hang, hố) biểu nghĩa, 隆 biểu âm. Nghĩa: hầm mỏ, hố đào; chủ yếu dùng trong từ kép 窟窿 (lỗ thủng, nợ nần, thâm hụt). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lõm, trũng; cái hố", "Hạng Tần Suất (Jun Da)": "3836.0", "Tần Suất % (Jun Da)": "99.6920735775", "GavinGrover_Once (Chiết tự trực tiếp)": "穴 + 隆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱穴隆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "窿", "Unihan_Traditional (Chữ Phồn thể)": "窿", "Pinyin_Xie": "lóng", "Âm Hán Việt_Xie": "lung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này thường kết hợp với các từ khác để chỉ hang động hoặc hình dáng khum vòm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('楔', '{"9000": "3837.0", "Chữ Trung Quốc": "楔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 楔 | tiết | tượng hình | cái nêm bằng gỗ | 楔 là chữ hình thanh, gồm bộ 木 (mộc, biểu nghĩa: gỗ) và thành phần biểu âm; tuy nhiên cấu trúc nội bộ không còn rõ ràng trong dạng tiểu triện. Chữ chỉ vật bằng gỗ có dạng nêm, dùng để chêm vào khe hở.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tiết\": cái nêm 楔 bằng gỗ 木 — tiết chế, chêm chặt từng \"tiết\" một. | Gương Hán-Việt | 楔 trong 楔形 (hình nêm — chữ viết hình nêm của người Sumer) | Mở khoá kiến thức | Biết 楔 mở khoá 楔子 (cái nêm, lời mở đầu), 楔形文字 (chữ hình nêm).", "Tự nguyên_Xie": "Tiểu triện | Theo dạng tiểu triện còn lưu lại, 楔 là chữ hình thanh thuộc bộ 木 (mộc), chỉ cái nêm bằng gỗ dùng để chêm chặt. Gốc chữ liên quan đến vật liệu gỗ và hành động chêm giữ. Chưa có nguồn học thuật Wiktionary đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái bạo cửa, cái ngạch cửa; chống đỡ; cái nêm", "Hạng Tần Suất (Jun Da)": "3837.0", "Tần Suất % (Jun Da)": "99.6924182732", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 契", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木契", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "契", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "楔", "Unihan_Traditional (Chữ Phồn thể)": "楔", "Pinyin_Xie": "xiē", "Âm Hán Việt_Xie": "tiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường làm danh từ chỉ cái nêm gỗ hoặc làm động từ chỉ hành động đóng nêm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胱', '{"9000": "3838.0", "Chữ Trung Quốc": "胱", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 10 | nét | 胱 | choáng | tượng hình | bàng quang, túi nước tiểu | 胱 thuộc bộ 月/肉 (nhục, thịt/cơ thể), chỉ bộ phận trong cơ thể. Không có dữ liệu glyph-origin đầy đủ; khả năng là chữ hình thanh với 光 (quang) làm thành phần âm. Chưa có nguồn học thuật Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"choáng\": bộ 月 (nhục = thịt) + âm 光 (quang/choáng) — cái túi trong cơ thể \"choáng\" đầy nước tiểu. | Gương Hán-Việt | 胱 trong 膀胱 (bàng quang — bàng 膀 + choáng 胱) | Mở khoá kiến thức | Biết 胱 mở khoá từ y khoa 膀胱 (bàng quang), 膀胱炎 (viêm bàng quang).", "Tự nguyên_Xie": "胱 là chữ hình thanh, bộ 月/肉 (nhục) chỉ bộ phận thân thể, thành phần âm có thể là 光 (quang). Chữ hầu như chỉ xuất hiện trong từ ghép 膀胱 (bàng quang). Chưa có nguồn học thuật Wiktionary đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàng quang 膀胱)", "Hạng Tần Suất (Jun Da)": "3838.0", "Tần Suất % (Jun Da)": "99.6927629689", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 光", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月光", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "光", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "胱", "Unihan_Traditional (Chữ Phồn thể)": "胱", "Pinyin_Xie": "guāng", "Âm Hán Việt_Xie": "quang", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này hầu như chỉ xuất hiện trong danh từ ghép bàng quang để chỉ bộ phận chứa nước tiểu. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荔', '{"9000": "3839.0", "Chữ Trung Quốc": "荔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 艸 | tháu | biểu nghĩa | cỏ, thực vật | 劦 | hiệp | biểu âm | hợp lực | 荔 là chữ hình thanh: bộ 艸 (tháu, biểu nghĩa: thực vật) + 劦 (hiệp, biểu âm). Phần âm 劦 gợi đọc lệ/lì. Chữ chỉ cây lệ chi (vải thiều).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lệ\": bộ cỏ 艸 trên mái 劦 — trái \"lệ\" chi (vải thiều) tươi đỏ treo trên cành. | Gương Hán-Việt | 荔 trong 荔枝 (lệ chi — quả vải thiều) | Mở khoá kiến thức | Biết 荔 mở khoá 荔枝 (lệ chi/vải thiều), 薜荔 (bích lệ — loài cây leo).", "Tự nguyên_Xie": "Theo Wiktionary, 荔 là chữ hình thanh (psc): bộ 艸 (tháu) biểu nghĩa chỉ thực vật, 劦 (hiệp) biểu âm. Chữ vốn chỉ một loài thực vật có liên quan đến iris hoặc mã lặc, nay gắn chặt với từ ghép 荔枝 (lệ chi — vải thiều). Cách đọc Hán-Việt lệ phản ánh đọc Trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: lệ chi 荔枝)", "Hạng Tần Suất (Jun Da)": "3839.0", "Tần Suất % (Jun Da)": "99.693106631", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 劦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹劦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "劦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荔", "Unihan_Traditional (Chữ Phồn thể)": "茘", "Pinyin_Xie": "lì", "Âm Hán Việt_Xie": "lệ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ đứng trước chữ chi để tạo thành từ chỉ quả vải. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟆', '{"9000": "3840.0", "Chữ Trung Quốc": "蟆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 莫 | mạc | biểu âm | không, chớ | 蟆 là chữ hình thanh: bộ 虫 (trùng, biểu nghĩa: côn trùng/động vật nhỏ) + 莫 (mạc, biểu âm, gợi đọc má). Chữ chỉ con ếch/cóc, thường dùng trong từ ghép 蝦蟆 (hà mô — con ếch).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạc\": bộ 虫 (trùng = con vật) + 莫 (mạc) — con vật \"mạc mạc\" nhảy dưới ao, đó là con cóc 蟆. | Gương Hán-Việt | 蟆 trong 蝦蟆/蛤蟆 (hà mô — con ếch/cóc) | Mở khoá kiến thức | Biết 蟆 mở khoá 蝦蟆 (hà mô), 蛤蟆 (con ếch/cóc) trong thành ngữ dân gian Trung Quốc.", "Tự nguyên_Xie": "Theo Wiktionary, 蟆 là chữ hình thanh: bộ 虫 (trùng) biểu nghĩa chỉ loài vật nhỏ, 莫 (mạc) biểu âm. Chữ dùng để ghi loài ếch/cóc, gần như chỉ xuất hiện trong từ ghép 蝦蟆 hay 蛤蟆 (hà mô, cóc/ếch). Cách đọc má là đọc văn học. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: hà mô 蝦蟆)", "Hạng Tần Suất (Jun Da)": "3840.0", "Tần Suất % (Jun Da)": "99.6934497763", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 莫", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫莫", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "莫", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟆", "Unihan_Traditional (Chữ Phồn thể)": "蟆", "Pinyin_Xie": "má", "Âm Hán Việt_Xie": "mô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường kết hợp với chữ hà để tạo thành danh từ chỉ con cóc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('湍', '{"9000": "3841.0", "Chữ Trung Quốc": "湍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 水 | thủy | biểu nghĩa | nước | 耑 | đoan | biểu âm | đầu, bắt đầu | 湍 là chữ hình thanh: bộ 水 (thủy, biểu nghĩa: nước) + 耑 (đoan, biểu âm, gợi đọc tuān). Chữ miêu tả nước chảy xiết, ào ạt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đoan\": bộ 水 (thủy) + 耑 (đoan = đầu dòng) — từ đầu nguồn nước \"đoan\" chảy xiết, đó là dòng 湍. | Gương Hán-Việt | 湍 trong 湍急 (đoan cấp — dòng chảy xiết), 湍流 (đoan lưu — chảy xiết) | Mở khoá kiến thức | Biết 湍 mở khoá 湍急 (dòng nước xiết), 湍流 (dòng chảy hỗn loạn), 急湍 (suối nhanh).", "Tự nguyên_Xie": "Theo Wiktionary, 湍 là chữ hình thanh: bộ 氵/水 (thủy) biểu nghĩa chỉ nước, 耑 (đoan) biểu âm. Chữ dùng chỉ dòng nước chảy nhanh, mạnh, thường thấy trong thơ văn cổ tả cảnh thiên nhiên. Cách đọc tuān trong tiếng Hán hiện đại bảo lưu đọc trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước chảy xiết", "Hạng Tần Suất (Jun Da)": "3841.0", "Tần Suất % (Jun Da)": "99.6937924049", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 耑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵耑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "湍", "Unihan_Traditional (Chữ Phồn thể)": "湍", "Pinyin_Xie": "tuān", "Âm Hán Việt_Xie": "thoan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ đứng trước danh từ để miêu tả dòng nước chảy rất nhanh. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('屹', '{"9000": "3842.0", "Chữ Trung Quốc": "屹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 6 | nét | 屹 | ngật | tượng hình | núi đứng vững, cao vút | 屹 thuộc bộ 山 (sơn), không có dữ liệu cây thành phần đầy đủ từ anchor. Chữ mô tả dáng núi đứng vững, kiên cường, thẳng đứng. Đây là chữ chỉ vẻ hùng tráng của núi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngật\": núi 山 đứng \"ngật ngưỡng\" không lay chuyển — 屹立 là đứng vững như núi. | Gương Hán-Việt | 屹 trong 屹立 (ngật lập — đứng vững, đứng thẳng) | Mở khoá kiến thức | Biết 屹 mở khoá 屹立 (đứng vững), 巍然屹立 (sừng sững, uy nghi).", "Tự nguyên_Xie": "Không có nguồn glyph-origin đầy đủ từ Wiktionary cho 屹. Chữ thuộc bộ 山 (sơn), dùng trong văn học để chỉ núi non đứng vững, không lay chuyển. Cách đọc ngật trong Hán-Việt phản ánh âm trung cổ yì. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "440.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Sơn (44) Khất (21)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Sơn (số 46 - ngọn núi) và chữ Khất (số 5 - ăn xin) . Người ăn xin (Khất) ngước nhìn ngọn núi (Sơn) cao sừng sững, đứng thẳng vươn lên gọi là cao ngật. Giải thích sự chuyển ý: Chữ Khất (ăn xin) chỉ âm, chữ Sơn (núi) chỉ ý. Ngọn núi (Sơn) cao sừng sững, đứng hiên ngang (Ngật). *(Biến âm Hán Việt: Khất -> Ngật)*", "Nghĩa Tiếng Việt_Xie": "cao chót vót", "Hạng Tần Suất (Jun Da)": "3842.0", "Tần Suất % (Jun Da)": "99.6941350334", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 乞", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山乞", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "乞", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "屹", "Unihan_Traditional (Chữ Phồn thể)": "屹", "Pinyin_Xie": "yì", "Âm Hán Việt_Xie": "ngật", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này thường làm tính từ miêu tả tư thế đứng vững vàng, không lay chuyển của núi non. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遐', '{"9000": "3843.0", "Chữ Trung Quốc": "遐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 12 | nét | 遐 | hà | tượng hình | xa xôi, cách trở | 遐 thuộc bộ 辶/辵 (sước — đi đường), không có dữ liệu cây thành phần từ anchor. Chữ chỉ khoảng cách xa xôi, thường dùng trong thơ văn cổ để tả cảnh xa cách. Glyph origin không có trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hà\": bộ 辶 (đường xa) — đường \"hà\" đó xa tít tắp, 遐想 là mơ về nơi xa. | Gương Hán-Việt | 遐 trong 遐想 (hà tưởng — mơ mộng xa xôi), 遐迩 (hà nhĩ — gần xa) | Mở khoá kiến thức | Biết 遐 mở khoá 遐想 (mơ xa), 遐迩闻名 (nổi tiếng gần xa), 天高地迥，觉宇宙之无穷.", "Tự nguyên_Xie": "遐 thuộc bộ 辶 (sước, đi đường), chỉ nơi xa cách không thể tới. Không có nguồn glyph-origin đầy đủ từ Wiktionary. Cách đọc hà trong Hán-Việt phản ánh âm trung cổ xiá. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa cách", "Hạng Tần Suất (Jun Da)": "3843.0", "Tần Suất % (Jun Da)": "99.694477662", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 叚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶叚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遐", "Unihan_Traditional (Chữ Phồn thể)": "遐", "Pinyin_Xie": "xiá", "Âm Hán Việt_Xie": "hà", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này thường làm tính từ chỉ khoảng cách xa hoặc làm phó từ trong các thành ngữ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('轲', '{"9000": "3844.0", "Chữ Trung Quốc": "轲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 車 | Số nét | 9 | nét | 轲 | kha | tượng hình | trục xe; tên người (Mạnh Kha) | 轲 thuộc bộ 车/車 (xa, xe), không có dữ liệu cây thành phần đầy đủ từ anchor. Chữ vốn chỉ trục xe, nhưng nổi tiếng nhất qua tên hiệu của Mạnh Tử — Mạnh Kha (孟轲).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kha\": bộ xe 车 đi trên đường \"kha\" — Mạnh Kha (孟轲) tức Mạnh Tử, bánh xe tư tưởng lăn mãi ngàn năm. | Gương Hán-Việt | 轲 trong 孟轲 (Mạnh Kha — tên của Mạnh Tử), 轗轲 (khảm kha — lận đận) | Mở khoá kiến thức | Biết 轲 mở khoá 孟轲 (Mạnh Kha), 轗轲 (đường đời gập ghềnh) trong văn học cổ.", "Tự nguyên_Xie": "轲 thuộc bộ 车 (xa, xe), chỉ trục xe hoặc xe khó đi. Không có nguồn glyph-origin đầy đủ từ Wiktionary. Chữ nổi tiếng qua tên húy Mạnh Kha (孟轲) — tức Mạnh Tử. Thành ngữ 轗轲 (khảm kha) chỉ đường đời lận đận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trục xe", "Hạng Tần Suất (Jun Da)": "3844.0", "Tần Suất % (Jun Da)": "99.6948202905", "GavinGrover_Once (Chiết tự trực tiếp)": "车 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰车可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "车", "Unihan_Simplified (Chữ Giản thể)": "轲", "Unihan_Traditional (Chữ Phồn thể)": "軻", "Pinyin_Xie": "kē", "Âm Hán Việt_Xie": "kha", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ chỉ trục xe thời cổ hoặc dùng trong tên riêng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镯', '{"9000": "3845.0", "Chữ Trung Quốc": "镯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 18 | nét | 金 | kim | biểu nghĩa | kim loại | 蜀 | thục | biểu âm | nước Thục, tằm | 镯 là chữ hình thanh: bộ 金 (kim, biểu nghĩa: kim loại) + 蜀 (thục, biểu âm, gợi đọc zhuó). Chữ chỉ vòng đeo tay bằng kim loại (thường bằng vàng hoặc ngọc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trạc\": bộ 金 (kim = vàng) + 蜀 (thục = Thục Địa) — vòng vàng 镯 từ xứ Thục, \"trạc\" tay hoàng hậu. | Gương Hán-Việt | 镯 trong 手镯 (thủ trạc — vòng đeo tay), 金镯 (kim trạc — vòng vàng) | Mở khoá kiến thức | Biết 镯 mở khoá 手镯 (vòng tay), 玉镯 (vòng ngọc), 金镯 (vòng vàng).", "Tự nguyên_Xie": "Theo Wiktionary, 镯 (phồn thể 鐲) là chữ hình thanh: bộ 金 (kim) biểu nghĩa chỉ kim loại, 蜀 (thục) biểu âm. Nguyên nghĩa còn bao gồm cái chuông nhỏ dùng để điều chỉnh nhịp hành quân của quân đội thời cổ. Nay chủ yếu dùng chỉ vòng đeo tay cứng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiêng; cái vòng tay", "Hạng Tần Suất (Jun Da)": "3845.0", "Tần Suất % (Jun Da)": "99.6951624023", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 蜀", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅蜀", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蜀", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镯", "Unihan_Traditional (Chữ Phồn thể)": "鐲", "Pinyin_Xie": "zhuó", "Âm Hán Việt_Xie": "trạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng sau các từ chỉ chất liệu để tạo thành tên các loại vòng tay. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缰', '{"9000": "3846.0", "Chữ Trung Quốc": "缰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 16 | nét | 缰 | cương | tượng hình | dây cương ngựa | 缰 thuộc bộ 纟 (mịch, sợi dây), chỉ dây cương dùng để điều khiển ngựa. Glyph origin từ Wiktionary chỉ dẫn đến chữ phồn thể 韁. Không có cây thành phần đầy đủ từ anchor.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": bộ sợi 纟 buộc vào ngựa — dây \"cương\" nắm trong tay người cưỡi. | Gương Hán-Việt | 缰 trong 缰绳 (cương thằng — dây cương), 脱缰 (thoát cương — mất kiểm soát) | Mở khoá kiến thức | Biết 缰 mở khoá 缰绳 (dây cương), 脱缰之马 (ngựa sổ cương — mất kiểm soát).", "Tự nguyên_Xie": "缰 là dạng giản thể của 韁, thuộc bộ 纟 (mịch, sợi). Wiktionary chỉ dẫn xem chữ phồn thể 韁 để tra glyph-origin. Chữ chỉ dây cương ngựa — vật dụng bằng vải/da để điều khiển ngựa. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dây cương ngựa", "Hạng Tần Suất (Jun Da)": "3846.0", "Tần Suất % (Jun Da)": "99.6955039972", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 畺", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟畺", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畺", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缰", "Unihan_Traditional (Chữ Phồn thể)": "繮", "Pinyin_Xie": "jiāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ làm tân ngữ cho động từ hoặc kết hợp tạo từ ghép chỉ sự ràng buộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('桦', '{"9000": "3847.0", "Chữ Trung Quốc": "桦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 10 | nét | 桦 | hoa | tượng hình | cây bạch dương, cây hoa mộc | 桦 thuộc bộ 木 (mộc, gỗ), chỉ cây bạch dương (birch). Glyph origin từ Wiktionary chỉ là {{Han etym}} không có nội dung. Khả năng là hình thanh với 华/華 (hoa) làm âm phần. Chưa có nguồn học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoa\": bộ 木 (cây) + âm 华 (hoa) — cây \"hoa\" mộc (bạch dương) vỏ trắng như hoa tuyết. | Gương Hán-Việt | 桦 trong 桦树 (hoa thụ — cây bạch dương), 白桦 (bạch hoa — cây bạch dương trắng) | Mở khoá kiến thức | Biết 桦 mở khoá 桦树 (cây bạch dương), 白桦林 (rừng bạch dương) thường gặp trong thơ Nga.", "Tự nguyên_Xie": "桦 thuộc bộ 木 (mộc), chỉ cây bạch dương (birch) có vỏ trắng mịn. Không có nguồn glyph-origin đầy đủ từ Wiktionary. Khả năng là chữ hình thanh với 华 (hoa) làm thành phần âm. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(một loại hoa)", "Hạng Tần Suất (Jun Da)": "3847.0", "Tần Suất % (Jun Da)": "99.6958450754", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 华", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木华", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "华", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "桦", "Unihan_Traditional (Chữ Phồn thể)": "樺", "Pinyin_Xie": "huà", "Âm Hán Việt_Xie": "hoa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trước chữ thụ để chỉ cây bạch dương hoặc đứng một mình trong ngữ cảnh lâm nghiệp. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('炖', '{"9000": "3848.0", "Chữ Trung Quốc": "炖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 8 | nét | 火 | hoả | biểu nghĩa | lửa | 敦 | đôn | biểu âm | thành thật, dày dặn | 炖 là chữ hình thanh: bộ 火 (hoả, biểu nghĩa: lửa, nấu) + 敦 (đôn, biểu âm, gợi đọc dùn). Chữ chỉ phương pháp nấu ăn hầm nhỏ lửa trong nước lâu giờ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đôn\": bộ 火 (hoả = lửa) + 敦 (đôn = thành thật, dày) — lửa \"đôn\" nhỏ sôi âm ỉ, hầm từ tốn, 炖 là hầm chậm. | Gương Hán-Việt | 炖 trong 炖肉 (đôn nhục — thịt hầm), 清炖 (thanh đôn — hầm trong) | Mở khoá kiến thức | Biết 炖 mở khoá 炖鸡 (gà hầm), 炖汤 (canh hầm), 清炖排骨 (sườn hầm trong).", "Tự nguyên_Xie": "Theo Wiktionary, 炖 là chữ hình thanh: bộ 火 (hoả) biểu nghĩa chỉ lửa/nấu nướng, 敦 (đôn) biểu âm. Cách nấu 炖 là nấu nhỏ lửa hoặc cách thuỷ trong thời gian dài để thức ăn chín mềm. Cách đọc dùn/đôn phản ánh mối liên hệ âm với 敦. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đun cách thuỷ", "Hạng Tần Suất (Jun Da)": "3848.0", "Tần Suất % (Jun Da)": "99.6961861536", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 屯", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火屯", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "屯", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "炖", "Unihan_Traditional (Chữ Phồn thể)": "燉", "Pinyin_Xie": "dùn", "Âm Hán Việt_Xie": "đôn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ vị ngữ trong câu để chỉ phương pháp nấu ăn bằng cách hầm nhỏ lửa. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | dùn | / | hầm | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Thức ăn tôi", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('钡', '{"9000": "3849.0", "Chữ Trung Quốc": "钡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 9 | nét | 钡 | bội | tượng hình | nguyên tố bari (Ba), kim loại kiềm thổ | 钡 thuộc bộ 钅/金 (kim, kim loại), là chữ tạo mới trong thời hiện đại để phiên âm nguyên tố hóa học Barium (Ba). Không có cấu trúc hình thanh cổ điển.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bội\": bộ 钅 (kim = kim loại) — nguyên tố kim loại \"bội\" (barium) trắng bạc, ký hiệu Ba. | Gương Hán-Việt | 钡 trong 氯化钡 (lục hóa bội — barium chloride), 硫酸钡 (lưu toan bội — barium sulfate) | Mở khoá kiến thức | Biết 钡 mở khoá thuật ngữ hóa học 硫酸钡 (BaSO₄, cản quang X-quang), 碳酸钡 (BaCO₃).", "Tự nguyên_Xie": "钡 là chữ tạo mới trong hóa học hiện đại để ghi tên nguyên tố Barium (Ba, số nguyên tử 56). Bộ 钅/金 (kim) chỉ kim loại. Không có glyph-origin cổ điển. Cách đọc bèi và Hán-Việt bội được đặt theo phiên âm. Chưa có nguồn học thuật cổ điển. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố bari, Ba", "Hạng Tần Suất (Jun Da)": "3849.0", "Tần Suất % (Jun Da)": "99.696526715", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "钡", "Unihan_Traditional (Chữ Phồn thể)": "鋇", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bối", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ nguyên tố hóa học, thường dùng trong thuật ngữ khoa học hoặc y khoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羚', '{"9000": "3850.0", "Chữ Trung Quốc": "羚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 11 | nét | 羚 | linh | tượng hình | linh dương, antelope | 羚 thuộc bộ 羊 (dương, dê/cừu), chỉ linh dương — loài thú họ dê sống trên núi cao. Không có dữ liệu cây thành phần đầy đủ từ anchor; bộ 羊 biểu nghĩa chỉ loài thú họ dê.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"linh\": bộ 羊 (dê/cừu) + linh hoạt — linh dương 羚 \"linh\" lẹ nhảy qua vách đá. | Gương Hán-Việt | 羚 trong 羚羊 (linh dương — antelope), 藏羚羊 (tạng linh dương) | Mở khoá kiến thức | Biết 羚 mở khoá 羚羊 (linh dương), 羚羊掛角 (thành ngữ: bút pháp siêu thoát).", "Tự nguyên_Xie": "羚 thuộc bộ 羊 (dương, dê/cừu), chỉ linh dương (antelope/gazelle). Không có glyph-origin đầy đủ từ Wiktionary. Cách đọc Hán-Việt linh phản ánh âm trung cổ líng. Chữ hầu như chỉ dùng trong từ ghép 羚羊 (linh dương). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: linh dương 羚羊)", "Hạng Tần Suất (Jun Da)": "3850.0", "Tần Suất % (Jun Da)": "99.6968672764", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + 令", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰羊令", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "令", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羊", "Unihan_Simplified (Chữ Giản thể)": "羚", "Unihan_Traditional (Chữ Phồn thể)": "羚", "Pinyin_Xie": "líng", "Âm Hán Việt_Xie": "linh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ dương để tạo thành danh từ chỉ loài linh dương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啬', '{"9000": "3851.0", "Chữ Trung Quốc": "啬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 十 | Số nét | 11 | nét | 來 | lai | biểu ý | lúa mì (dạng cổ của 来) | 㐭 | biểu ý | kho lúa, nơi cất giữ lương thực | 啬 (phồn thể 嗇) = 來 + 㐭, ls=ic (hội ý). Wiktionary ghi rõ: 來 (lúa mì cổ) + 㐭 (kho lúa) kết hợp hội ý — hình ảnh cất lúa vào kho. Nghĩa: tiết kiệm đến mức keo kiệt. Chữ hội ý điển hình. Hiện dạng giản thể 啬 có hình khác (⿱⿻土丷回) nhưng nghĩa không đổi.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sắc\": cất lúa (來) vào kho (㐭) khóa kỹ — người keo kiệt không chịu chia sẻ gì cả. | Gương Hán-Việt | \"sắc\" trong 吝啬 (lận sắc — keo kiệt), 啬鬼 (sắc quỷ — tên kẻ keo kiệt) | Mở khoá kiến thức | Biết 啬 mở khoá 吝啬 (keo kiệt), 啬鬼 (kẻ bủn xỉn), 节啬 (tiết kiệm).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Đại triện | Chữ 啬 (sắc), phồn thể 嗇, là chữ hội ý (ls=ic): 來 (lúa mì, dạng cổ) + 㐭 (kho lương thực) — hình ảnh cất giữ lúa thóc cẩn thận vào kho. Nghĩa gốc: tiết kiệm lương thực; mở rộng sang nghĩa keo kiệt, bủn xỉn. Giáp cốt văn, kim văn và đại triện đều được lưu lại, cho thấy chữ xuất hiện từ rất sớm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "dè sẻn, keo kiệt, bủn xỉn", "Hạng Tần Suất (Jun Da)": "3851.0", "Tần Suất % (Jun Da)": "99.6972078378", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 回", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱回", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "啬", "Unihan_Traditional (Chữ Phồn thể)": "嗇", "Pinyin_Xie": "sè", "Âm Hán Việt_Xie": "sắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ hoặc làm vị ngữ để miêu tả tính cách tiết kiệm quá mức. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诩', '{"9000": "3852.0", "Chữ Trung Quốc": "诩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 诩 | hủ | tượng hình | khoe khoang, tự phụ | 诩 là dạng giản thể của 詡, thuộc bộ 讠/言 (ngôn, lời nói). Chữ phồn thể 詡 gồm 言 (biểu nghĩa: nói) + 羽 (biểu âm: lông vũ). Chữ chỉ hành động nói khoác, tự cao tự đại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hủ\": bộ 言 (nói) + 羽 (lông chim) — lời \"hủ\" khoang như chim xòe lông, 诩 là tự phụ, khoe khoang. | Gương Hán-Việt | 诩 trong 自诩 (tự hủ — tự khen mình), 诩诩 (hủ hủ — dáng khoe khoang) | Mở khoá kiến thức | Biết 诩 mở khoá 自诩 (tự phụ, tự khen), 夸诩 (khoác lác), thường gặp trong văn nói phê bình.", "Tự nguyên_Xie": "诩 là dạng giản thể của 詡 (言 + 羽). Bộ 言 (ngôn) biểu nghĩa chỉ ngôn từ; 羽 (vũ, lông vũ) biểu âm. Hình ảnh con chim xòe lông — lời nói khoa trương như lông vũ phô trương. Không có glyph-origin đầy đủ từ Wiktionary. Cách đọc hủ trong Hán-Việt phản ánh âm trung cổ xǔ. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoe khoang; to, lớn", "Hạng Tần Suất (Jun Da)": "3852.0", "Tần Suất % (Jun Da)": "99.6975483992", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 羽", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠羽", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "羽", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诩", "Unihan_Traditional (Chữ Phồn thể)": "詡", "Pinyin_Xie": "xǔ", "Âm Hán Việt_Xie": "hủ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp với tự để chỉ hành động tự khoe khoang về bản thân. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绯', '{"9000": "3853.0", "Chữ Trung Quốc": "绯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 11 | nét | 绯 | phi | tượng hình | lụa đỏ, màu đỏ hồng | 绯 là dạng giản thể của 緋, thuộc bộ 纟/糸 (mịch, sợi vải). Chữ phồn thể 緋 gồm 糸 (biểu nghĩa: vải sợi) + 非 (biểu âm). Chữ chỉ màu đỏ hồng của lụa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phi\": bộ 纟 (vải lụa) + 非 (phi = không phải thường) — lụa \"phi\" thường, màu đỏ hồng quý giá của triều đình. | Gương Hán-Việt | 绯 trong 绯红 (phi hồng — đỏ thắm), 绯闻 (phi văn — tin đồn tình ái) | Mở khoá kiến thức | Biết 绯 mở khoá 绯红 (màu đỏ thắm), 绯闻 (scandal tình cảm), từ thông dụng trong truyền thông.", "Tự nguyên_Xie": "绯 là dạng giản thể của 緋 (糸 + 非). Bộ 糸 (mịch) biểu nghĩa chỉ vải/lụa; 非 (phi) biểu âm. Chữ vốn chỉ lụa màu đỏ hồng — màu sắc dùng trong trang phục quan lại thời phong kiến. Cách đọc phi trong Hán-Việt phản ánh âm trung cổ fēi. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lụa đào, lụa đỏ", "Hạng Tần Suất (Jun Da)": "3853.0", "Tần Suất % (Jun Da)": "99.6978884438", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 非", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟非", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "非", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绯", "Unihan_Traditional (Chữ Phồn thể)": "緋", "Pinyin_Xie": "fēi", "Âm Hán Việt_Xie": "phi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Làm tính từ bổ nghĩa cho danh từ để chỉ màu sắc đỏ hồng hoặc làm danh từ chỉ lụa đỏ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('掖', '{"9000": "3854.0", "Chữ Trung Quốc": "掖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 11 | nét | 扌 | thủ | biểu nghĩa | tay | 夜 | dạ | biểu âm | đêm | 掖 là chữ hình thanh: bộ 扌 (thủ, biểu nghĩa: tay) + 夜 (dạ, biểu âm, gợi đọc yē/yè). Chữ chỉ hành động kẹp vào nách, đỡ bằng tay, hoặc giấu vào bên sườn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dịch\": bộ tay 扌 + 夜 (dạ = đêm) — ban \"dạ\" đêm khuya, tay kẹp nhau đỡ người té, đó là 掖 (đỡ, kẹp nách). | Gương Hán-Việt | 掖 trong 掖庭 (dịch đình — cung điện bên hông), 扶掖 (phù dịch — nâng đỡ, giúp đỡ) | Mở khoá kiến thức | Biết 掖 mở khoá 扶掖 (nâng đỡ người dưới), 掖庭 (cung điện hậu cung) trong văn học cổ.", "Tự nguyên_Xie": "Theo Wiktionary, 掖 là chữ hình thanh: bộ 扌/手 (thủ) biểu nghĩa chỉ hành động của tay, 夜 (dạ) biểu âm. Nguyên nghĩa liên quan đến vùng nách — kẹp vào nách, đỡ bằng cánh tay. Cũng dùng chỉ cung điện hai bên (biên cung). Cách đọc Hán-Việt dịch phản ánh âm trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nách; giúp; ở bên", "Hạng Tần Suất (Jun Da)": "3854.0", "Tần Suất % (Jun Da)": "99.6982274549", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 夜", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌夜", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "掖", "Unihan_Traditional (Chữ Phồn thể)": "掖", "Pinyin_Xie": "yē", "Âm Hán Việt_Xie": "dịch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ biểu thị hành động nhét đồ vật vào thắt lưng hoặc nâng đỡ ai đó. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('箓', '{"9000": "3855.0", "Chữ Trung Quốc": "箓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 14 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 彔 | lục | biểu âm | 箓 là chữ hình thanh: bộ 竹 (trúc, biểu nghĩa: tre) + 彔 (lục, biểu âm). Chữ vốn chỉ sách/thẻ tre, nay thường dùng chỉ bùa chú đạo giáo (đồ lục/phù lục).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lục\": bộ 竹 (trúc = tre) + 彔 (lục) — sách tre \"lục\" chép phép thuật, đó là phù lục 箓 của đạo sĩ. | Gương Hán-Việt | 箓 trong 符箓 (phù lục — bùa chú đạo giáo), 道箓 (đạo lục — phép thuật đạo gia) | Mở khoá kiến thức | Biết 箓 mở khoá 符箓 (phù lục — bùa chú), 箓书 (lục thư — sách bùa chú) trong văn hóa đạo giáo.", "Tự nguyên_Xie": "Theo Wiktionary, 箓 (biến thể của 簏/籙) là chữ hình thanh: bộ 竹 (trúc) biểu nghĩa chỉ tre/vật phẩm bằng tre, 彔 (lục) biểu âm. Nguyên nghĩa là hòm tre đựng sách hoặc thẻ tre ghi chép. Nay 箓 thường dùng chỉ phù lục — văn bản bùa chú của đạo giáo viết trên tre/giấy. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: đồ lục 圖籙,图箓)", "Hạng Tần Suất (Jun Da)": "3855.0", "Tần Suất % (Jun Da)": "99.6985664659", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 录", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮录", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "录", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "箓", "Unihan_Traditional (Chữ Phồn thể)": "籙", "Pinyin_Xie": "lù", "Âm Hán Việt_Xie": "lục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các loại sổ sách ghi chép điềm báo hoặc bùa chú trong tôn giáo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涸', '{"9000": "3856.0", "Chữ Trung Quốc": "涸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 氵 | thủy | biểu nghĩa | nước | 固 | cố | biểu âm | cứng, vững chắc | 涸 là chữ hình thanh: bộ 氵 (thủy, biểu nghĩa: nước) + 固 (cố, biểu âm, gợi đọc hé). Chữ chỉ trạng thái nước cạn kiệt, ao hồ khô hạn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạt\": bộ 氵 (nước) + 固 (cố = cứng) — nước \"hạt\" cạn kiệt, ao bị cứng đặc khô khốc. | Gương Hán-Việt | 涸 trong 干涸 (can hạt — khô cạn), 涸辙之鱼 (hạt triệt chi ngư — cá trên vũng cạn) | Mở khoá kiến thức | Biết 涸 mở khoá 干涸 (khô cạn), 枯涸 (khô kiệt), thành ngữ 涸辙之鱼 (cảnh khốn cùng).", "Tự nguyên_Xie": "Theo Wiktionary, 涸 là chữ hình thanh: bộ 氵/水 (thủy) biểu nghĩa chỉ nước, 固 (cố) biểu âm. Chữ chỉ nước bị cạn kiệt — ao hồ hoặc sông suối khô hạn. Cách đọc hạt trong Hán-Việt phản ánh âm trung cổ. Thành ngữ 涸辙之鱼 (cá trên đường cạn) chỉ người lâm vào cảnh khổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cạn hết, khô", "Hạng Tần Suất (Jun Da)": "3856.0", "Tần Suất % (Jun Da)": "99.6989049602", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涸", "Unihan_Traditional (Chữ Phồn thể)": "涸", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "hạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ bổ nghĩa cho nguồn nước hoặc động từ chỉ sự cạn kiệt nguồn nước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸳', '{"9000": "3857.0", "Chữ Trung Quốc": "鸳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 夗 | uyển | biểu âm | nằm nghiêng, uốn cong | 鳥 | điểu | biểu nghĩa | chim | 鸳 là chữ hình thanh: bộ 鳥/鸟 (điểu, biểu nghĩa: chim) + 夗 (uyển, biểu âm, gợi đọc yuān). Chữ chỉ con uyên ương đực (鸳鸯 — đôi chim trống-mái sống thành cặp).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyên\": bộ chim 鳥 + 夗 (uyển cong) — đôi chim \"uyên\" ương quấn quýt, biểu tượng tình yêu. | Gương Hán-Việt | 鸳 trong 鸳鸯 (uyên ương — đôi chim trời, biểu tượng tình yêu) | Mở khoá kiến thức | Biết 鸳 mở khoá 鸳鸯 (uyên ương), 鸳鸯浴 (tắm đôi), 鸳鸯戏水 (uyên ương đùa giỡn).", "Tự nguyên_Xie": "Theo Wiktionary, 鸳 là chữ hình thanh: bộ 鳥 (điểu) biểu nghĩa chỉ chim, 夗 (uyển/yuān) biểu âm. Chữ chỉ con uyên ương đực — loài chim nước sống thành đôi biểu trưng cho tình yêu chung thủy trong văn hóa Trung Hoa. 鸳鸯 (uyên ương) được dùng như ẩn dụ cho đôi tình nhân. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt đực", "Hạng Tần Suất (Jun Da)": "3857.0", "Tần Suất % (Jun Da)": "99.6992429377", "GavinGrover_Once (Chiết tự trực tiếp)": "夗 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱夗鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夗", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸳", "Unihan_Traditional (Chữ Phồn thể)": "鴛", "Pinyin_Xie": "yuān", "Âm Hán Việt_Xie": "uyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường kết hợp với ương để chỉ chim uyên ương hoặc cặp đôi nam nữ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('塾', '{"9000": "3858.0", "Chữ Trung Quốc": "塾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 14 | nét | 孰 | thục | biểu âm | ai, cái nào; chín mùi | 土 | thổ | biểu nghĩa | đất | 塾 là chữ hình thanh: bộ 土 (thổ, biểu nghĩa: đất/nơi chốn) + 孰 (thục, biểu âm, gợi đọc shú). Chữ chỉ trường học tư gia — trường học cạnh cổng nhà hoặc tại nhà thầy đồ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thục\": bộ 土 (đất = nơi chốn) + 孰 (thục = ai, chín mùi) — \"thục\" nơi \"chín mùi\" tri thức, đó là trường 塾 của thầy đồ. | Gương Hán-Việt | 塾 trong 私塾 (tư thục — trường học tư gia), 塾师 (thục sư — thầy đồ dạy tư thục) | Mở khoá kiến thức | Biết 塾 mở khoá 私塾 (trường tư thục), 塾师 (thầy đồ), 学塾 (học thục).", "Tự nguyên_Xie": "Theo Wiktionary, 塾 là chữ hình thanh: 孰 (thục) biểu âm, 土 (thổ) biểu nghĩa chỉ nơi chốn trên đất. Nguyên nghĩa liên quan đến buồng học cạnh cổng nhà trong kiến trúc cổ Trung Hoa — nơi thầy đồ dạy học trò. 私塾 (tư thục) là trường học tư gia đặc trưng thời phong kiến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lớp học tại nhà", "Hạng Tần Suất (Jun Da)": "3858.0", "Tần Suất % (Jun Da)": "99.6995809152", "GavinGrover_Once (Chiết tự trực tiếp)": "孰 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱孰土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "孰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "塾", "Unihan_Traditional (Chữ Phồn thể)": "塾", "Pinyin_Xie": "shú", "Âm Hán Việt_Xie": "thục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ nơi học tập tư nhân thời phong kiến, thường ghép thành tư thục. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呸', '{"9000": "3859.0", "Chữ Trung Quốc": "呸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 8 | nét | 口 | khẩu | biểu nghĩa | miệng | 丕 | bỉ | biểu âm | to lớn, vĩ đại | 呸 là chữ hình thanh: bộ 口 (khẩu, biểu nghĩa: miệng) + 丕 (bỉ, biểu âm, gợi đọc pēi). Chữ là thán từ miệng thể hiện sự khinh miệt, phủ nhận — tương đương \"xì\" hay \"phì\" trong tiếng Việt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bậy\": bộ 口 (miệng) + 丕 (bỉ) — miệng thốt ra tiếng \"bậy\", phì miệng khinh thường. | Gương Hán-Việt | 呸 là thán từ riêng biệt, dùng trực tiếp để bày tỏ khinh miệt | Mở khoá kiến thức | Biết 呸 giúp đọc hiểu hội thoại phim và văn học đương đại khi nhân vật bày tỏ sự khinh miệt.", "Tự nguyên_Xie": "Theo Wiktionary, 呸 là chữ hình thanh (psc): bộ 口 (khẩu) biểu nghĩa chỉ âm thanh từ miệng, 丕 (bỉ) biểu âm (no_och2=1 — không dùng âm cổ). Chữ ghi lại tiếng thán từ khinh miệt — dùng khi phủ nhận hoặc bày tỏ sự bực bội. Cách đọc bậy trong Hán-Việt là đặc biệt, phản ánh ngữ nghĩa hơn âm. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hừ; xí; úi chà; ô hay (thán từ, biểu thị sự trách móc, khinh miệt)", "Hạng Tần Suất (Jun Da)": "3859.0", "Tần Suất % (Jun Da)": "99.6999183759", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 丕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口丕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呸", "Unihan_Traditional (Chữ Phồn thể)": "呸", "Pinyin_Xie": "pēi", "Âm Hán Việt_Xie": "phôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Chữ này làm thán từ đứng đầu câu để biểu thị sự khinh bỉ, phản đối hoặc không tin tưởng. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('抡', '{"9000": "3860.0", "Chữ Trung Quốc": "抡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 7 | nét | 抡 | luân | tượng hình | kén chọn; vung (tay) | 抡 là dạng giản thể của 掄 (扌 + 侖), thuộc bộ 扌 (thủ, tay). Phần âm cũ là 侖 (luân). Chữ có hai nghĩa: (1) kén chọn/lựa chọn (đọc lún); (2) vung mạnh (đọc lūn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"luân\": bộ tay 扌 + 侖 (luân = sắp xếp theo thứ tự) — tay \"luân\" chuyển kén chọn, hoặc vung một vòng mạnh mẽ. | Gương Hán-Việt | 抡 trong 抡才 (luân tài — kén chọn nhân tài), 抡起 (luân khởi — vung lên) | Mở khoá kiến thức | Biết 抡 mở khoá 抡起斧头 (vung rìu lên), 抡才大典 (kỳ thi kén chọn nhân tài).", "Tự nguyên_Xie": "抡 là dạng giản thể của 掄, gồm 扌 (thủ, biểu nghĩa: tay) và 侖 (luân, biểu âm). Không có glyph-origin đầy đủ từ Wiktionary. Chữ có hai nghĩa: lựa chọn (đọc lún) và vung mạnh như vung búa/dao (đọc lūn). Cách đọc Hán-Việt luân phản ánh 侖 là gốc âm. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "kén chọn", "Hạng Tần Suất (Jun Da)": "3860.0", "Tần Suất % (Jun Da)": "99.7002553198", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 仑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌仑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "仑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "抡", "Unihan_Traditional (Chữ Phồn thể)": "掄", "Pinyin_Xie": "lūn", "Âm Hán Việt_Xie": "luân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ hành động vung cánh tay hoặc quay tròn một vật nặng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | lún | / | lựa chọn | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('擞', '{"9000": "3861.0", "Chữ Trung Quốc": "擞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 16 | nét | 擞 | tẩu | tượng hình | rũ bỏ, phấn chấn, chống lò | 擞 thuộc bộ 扌 (thủ, tay), chỉ hành động rũ mạnh hoặc khuấy động. Không có glyph-origin đầy đủ từ Wiktionary. Chữ nổi tiếng nhất qua thành ngữ 抖擞精神 (phấn chấn tinh thần).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tẩu\": bộ 扌 (tay) rũ mạnh — \"tẩu\" rũ người cho tỉnh táo, 抖擞精神 là phấn chấn lên! | Gương Hán-Việt | 擞 trong 抖擞 (đẩu tẩu — phấn chấn, rũ bỏ), 擞火 (tẩu hoả — chọc lò) | Mở khoá kiến thức | Biết 擞 mở khoá 抖擞精神 (thành ngữ: tinh thần hăng hái), 精神抖擞 (tinh thần phấn chấn).", "Tự nguyên_Xie": "擞 thuộc bộ 扌 (thủ), chỉ hành động rũ, lắc, hoặc chọc bằng tay. Không có glyph-origin đầy đủ từ Wiktionary. Cách đọc tẩu/sấu trong Hán-Việt phản ánh âm trung cổ sǒu. Thường dùng trong thành ngữ 抖擞 (rũ bỏ uể oải, phấn chấn) và 擞火 (chọc lò). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phấn chấn", "Hạng Tần Suất (Jun Da)": "3861.0", "Tần Suất % (Jun Da)": "99.7005922637", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 数", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌数", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "数", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "擞", "Unihan_Traditional (Chữ Phồn thể)": "擻", "Pinyin_Xie": "sǒu", "Âm Hán Việt_Xie": "tẩu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ, thường dùng trong từ ghép để chỉ sự phấn chấn tinh thần hoặc hành động rũ bụi. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('熹', '{"9000": "3862.0", "Chữ Trung Quốc": "熹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 16 | nét | 喜 | hỷ | biểu âm | vui mừng | 灬 | hoả | biểu nghĩa | lửa, hơi nóng | 熹 là chữ hình thanh: bộ 灬 (hoả, biểu nghĩa: lửa/ánh sáng) ở dưới + 喜 (hỷ, biểu âm, gợi đọc xī). Chữ chỉ ánh sáng lờ mờ khi rạng đông hoặc ánh lửa ấm áp.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\": bộ 灬 (lửa) dưới chân chữ 喜 (vui) — ánh \"hi\" vi rạng đông, lửa vui le lói như 熹 — ánh sáng ấm áp đầu ngày. | Gương Hán-Việt | 熹 trong 熹微 (hi vi — ánh sáng lờ mờ), trong tên 朱熹 (Chu Hi — nhà Nho học) | Mở khoá kiến thức | Biết 熹 mở khoá 熹微 (ánh bình minh le lói), 火熹微 (ánh lửa mờ), tên riêng 朱熹.", "Tự nguyên_Xie": "Theo Wiktionary, 熹 là chữ hình thanh: 喜 (hỷ) biểu âm, 灬/火 (hoả) biểu nghĩa chỉ lửa/ánh sáng. Chữ chỉ ánh sáng mờ ảo — ánh bình minh le lói hoặc ánh lửa ấm. Thường thấy trong văn học cổ qua 熹微 (hi vi — ánh sáng lờ mờ buổi sớm). Chữ cũng là tên Chu Hi (朱熹), nhà Nho học nổi tiếng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trời sáng; sáng sủa; rạng sáng", "Hạng Tần Suất (Jun Da)": "3862.0", "Tần Suất % (Jun Da)": "99.7009292076", "GavinGrover_Once (Chiết tự trực tiếp)": "喜 + 灬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱喜灬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "喜", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "灬", "Unihan_Simplified (Chữ Giản thể)": "熹", "Unihan_Traditional (Chữ Phồn thể)": "熹", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả ánh sáng ban mai dịu nhẹ hoặc sự ấm áp của mặt trời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坷', '{"9000": "3863.0", "Chữ Trung Quốc": "坷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 8 | nét | 土 | thổ | biểu nghĩa | đất | 可 | khả | biểu âm | có thể, chấp nhận | 坷 là chữ hình thanh: bộ 土 (thổ, biểu nghĩa: đất) + 可 (khả, biểu âm, gợi đọc kě/kē). Chữ chỉ mặt đất gồ ghề, không bằng phẳng — hầu như chỉ dùng trong từ ghép 坎坷 (khảm khả).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khả\": bộ 土 (đất) + 可 (khả) — đất \"khả\" gồ ghề, không \"khả\" đi được — 坎坷 là đường đời gập ghềnh. | Gương Hán-Việt | 坷 trong 坎坷 (khảm khả — đường gập ghềnh, cuộc đời lận đận) | Mở khoá kiến thức | Biết 坷 mở khoá thành ngữ 坎坷 (lận đận), 坷垃 (cục đất), thường gặp khi tả cuộc đời.", "Tự nguyên_Xie": "Theo Wiktionary, 坷 là chữ hình thanh: bộ 土 (thổ) biểu nghĩa chỉ đất/địa hình, 可 (khả) biểu âm. Chữ chỉ đất gồ ghề, mấp mô. Hầu như chỉ dùng trong thành ngữ 坎坷 (khảm khả) — đường đời gập ghềnh, lận đận. Cách đọc Hán-Việt khả phản ánh âm trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: khảm khả 坎坷)", "Hạng Tần Suất (Jun Da)": "3863.0", "Tần Suất % (Jun Da)": "99.7012646011", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 可", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土可", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "可", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坷", "Unihan_Traditional (Chữ Phồn thể)": "坷", "Pinyin_Xie": "kě", "Âm Hán Việt_Xie": "khả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ, hầu như chỉ dùng trong từ ghép để miêu tả đường sá gồ ghề hoặc cuộc đời trắc trở. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瓮', '{"9000": "3864.0", "Chữ Trung Quốc": "瓮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 8 | nét | 瓮 | ủng | tượng hình | vò, chum, hũ đựng rượu/nước | 瓮 là dạng biến thể/giản thể của 甕, chỉ vật dụng chứa đựng bằng đất nung — vò, chum, hũ. Không có cây thành phần đầy đủ từ anchor. Wiktionary chỉ dẫn xem 甕.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ủng\": cái chum \"ủng\" úp — 瓮中捉鳖 là bắt kẻ thù trong chum, chắc thắng. | Gương Hán-Việt | 瓮 trong 瓮中捉鳖 (ủng trung tróc miết — chắc thắng), 酒瓮 (tửu ủng — vò rượu) | Mở khoá kiến thức | Biết 瓮 mở khoá 瓮中捉鳖 (thành ngữ: nắm chắc trong tay), 瓮声瓮气 (giọng ồm ồm trong chum).", "Tự nguyên_Xie": "瓮 là biến thể của 甕 (chum/vò). Không có glyph-origin đầy đủ từ Wiktionary. Chữ chỉ đồ vật bằng đất nung dùng để đựng rượu, nước hoặc lương thực. Thành ngữ 瓮中捉鳖 (chum trong bắt ba ba — nắm chắc trong tay) rất phổ biến. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vò, chum, vại, hũ", "Hạng Tần Suất (Jun Da)": "3864.0", "Tần Suất % (Jun Da)": "99.7015994779", "GavinGrover_Once (Chiết tự trực tiếp)": "公 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱公瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "公", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "瓮", "Unihan_Traditional (Chữ Phồn thể)": "瓮", "Pinyin_Xie": "wèng", "Âm Hán Việt_Xie": "úng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ đồ đựng bằng đất nung miệng nhỏ bụng to. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('亘', '{"9000": "3865.0", "Chữ Trung Quốc": "亘", "Bộ thủ & thành phần_Xie": "Bộ thủ | 二 | Số nét | 6 | nét | 二 | nhị | hình ảnh | hai đường ngang (trời và đất) | 囘 | hồi | hình ảnh | xoáy, quay vòng | 亘 là chữ hội ý: 二 (nhị, hai đường ngang) + 囘 (hồi, xoáy vòng) — hình ảnh vật xuyên suốt từ trên xuống dưới, từ đầu đến cuối. Chữ chỉ tính liên tục, trải dài xuyên suốt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cán\": trời 二 đất xuyên suốt bởi 囘 xoáy vòng — \"cán\" cổ bất biến, 亘古 trải dài từ thuở khai thiên. | Gương Hán-Việt | 亘 trong 亘古 (cán cổ — từ ngàn xưa đến nay), 连亘 (liên cán — kéo dài liên tục) | Mở khoá kiến thức | Biết 亘 mở khoá 亘古未有 (chưa từng có từ cổ xưa), 横亘 (kéo dài ngang qua).", "Tự nguyên_Xie": "Theo Wiktionary, 亘 là chữ hội ý (ic): 二 (nhị, hai đường ngang biểu trưng trời đất) + 囘 (hồi, xoáy vòng). Nguyên chữ là 𠄢, chỉ hành động xoay vòng liên tục, kéo dài xuyên suốt. Cách đọc Hán-Việt cán/hằng phản ánh âm gèn. Chữ thường thấy trong 亘古 (cán cổ — từ cổ xưa đến nay, trường tồn). | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phô bày", "Hạng Tần Suất (Jun Da)": "3865.0", "Tần Suất % (Jun Da)": "99.7019343547", "GavinGrover_Once (Chiết tự trực tiếp)": "一 + 旦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱一旦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "亘", "Unihan_Traditional (Chữ Phồn thể)": "亙", "Pinyin_Xie": "gèn", "Âm Hán Việt_Xie": "cắng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ chỉ sự kéo dài liên tục về không gian hoặc thời gian. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嗟', '{"9000": "3866.0", "Chữ Trung Quốc": "嗟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng, lời nói | 差 | sai | biểu âm | sai lệch, bai sai | 嗟 là chữ hình thanh: ban đầu dùng bộ 言 (ngôn), sau trong chữ khải thể đổi thành 口 (khẩu, biểu nghĩa: miệng). Phần âm 差 (sai, biểu âm) gợi đọc jiē. Chữ là thán từ biểu thị thương tiếc, ngạc nhiên.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ta\": bộ 口 (miệng) + 差 (sai) — miệng thốt lên \"ta ôi\", tiếng thở dài khi mọi thứ đi \"sai\" đường. | Gương Hán-Việt | 嗟 trong 嗟叹 (ta thán — than thở), 嗟来之食 (ta lai chi thực — cơm bố thí) | Mở khoá kiến thức | Biết 嗟 mở khoá 嗟叹 (than thở), 嗟乎 (than ôi!), thành ngữ 嗟来之食 (không ăn cơm bố thí — tự trọng).", "Tự nguyên_Xie": "Theo Wiktionary, 嗟 ban đầu viết 𧪘 là chữ hình thanh trong tiểu triện: 言 (ngôn, biểu nghĩa: lời nói) + 差 (sai, biểu âm). Khi chuyển sang khải thư, 言 rút gọn thành 口. Chữ là thán từ cổ điển dùng để thở dài, tiếc nuối hoặc than thở. Cách đọc ta trong Hán-Việt phản ánh âm trung cổ jiē. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thương xót", "Hạng Tần Suất (Jun Da)": "3866.0", "Tần Suất % (Jun Da)": "99.7022692314", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 差", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口差", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "差", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嗟", "Unihan_Traditional (Chữ Phồn thể)": "嗟", "Pinyin_Xie": "jiē", "Âm Hán Việt_Xie": "ta", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thán từ | 叹词 | Chữ này làm động từ chỉ sự than thở hoặc làm thán từ biểu thị sự cảm thán, thương tiếc. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('筵', '{"9000": "3867.0", "Chữ Trung Quốc": "筵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 12 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 延 | diên | biểu âm | kéo dài, trải dài | 筵 là chữ hình thanh: bộ 竹 (trúc, biểu nghĩa: tre) + 延 (diên, biểu âm, gợi đọc yán). Nguyên nghĩa là chiếu trúc — tấm chiếu bằng tre trải ra để ngồi dự tiệc; nay dùng nghĩa rộng hơn chỉ bữa tiệc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diên\": bộ 竹 (chiếu trúc) + 延 (diên = kéo dài) — chiếu \"diên\" trải dài, mời khách ngồi tiệc 筵. | Gương Hán-Việt | 筵 trong 筵席 (diên tịch — bữa tiệc), 酒筵 (tửu diên — tiệc rượu) | Mở khoá kiến thức | Biết 筵 mở khoá 筵席 (yến tiệc), 盛筵 (tiệc thịnh soạn), 几筵 (bàn thờ).", "Tự nguyên_Xie": "Theo Wiktionary, 筵 là chữ hình thanh: bộ 竹 (trúc) biểu nghĩa chỉ tre/vật liệu trúc, 延 (diên) biểu âm. Nguyên nghĩa là tấm chiếu bằng tre trải trước chỗ ngồi trong lễ nghi cổ. Từ đó mở rộng chỉ chỗ ngồi, sau là bữa tiệc. 筵席 (diên tịch) là từ ghép phổ biến nhất. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái chiếu trúc; bữa tiệc", "Hạng Tần Suất (Jun Da)": "3867.0", "Tần Suất % (Jun Da)": "99.7026041082", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 延", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮延", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "延", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "筵", "Unihan_Traditional (Chữ Phồn thể)": "筵", "Pinyin_Xie": "yán", "Âm Hán Việt_Xie": "diên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ chiếu trải ngồi thời xưa hoặc bữa tiệc chiêu đãi khách. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跛', '{"9000": "3868.0", "Chữ Trung Quốc": "跛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 足 | túc | biểu nghĩa | chân | 皮 | bì | biểu âm | da | 跛 là chữ hình thanh: bộ 足 (túc, biểu nghĩa: chân) + 皮 (bì, biểu âm, gợi đọc bǒ). Chữ chỉ trạng thái chân bị khuyết tật — đi khập khiễng, thọt chân.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bả\": bộ 足 (chân) + 皮 (bì = da) — chân \"bả\" lết da, đi khập khiễng vì thọt. | Gương Hán-Việt | 跛 trong 跛行 (bả hành — đi khập khiễng), 跛足 (bả túc — chân thọt) | Mở khoá kiến thức | Biết 跛 mở khoá 跛行 (đi khập khiễng), 跛足 (chân thọt), từ ghép hay gặp khi miêu tả thể chất.", "Tự nguyên_Xie": "Theo Wiktionary, 跛 là chữ hình thanh: bộ 足 (túc) biểu nghĩa chỉ chân, 皮 (bì) biểu âm. Chữ chỉ tật thọt chân — chân không đều, đi khập khiễng. Từ ghép 跛足 hoặc 跛行 mô tả dáng đi này. Cách đọc bả trong Hán-Việt phản ánh âm trung cổ bǒ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "què chân, thọt chân", "Hạng Tần Suất (Jun Da)": "3868.0", "Tần Suất % (Jun Da)": "99.702938985", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 皮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊皮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "皮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跛", "Unihan_Traditional (Chữ Phồn thể)": "跛", "Pinyin_Xie": "bǒ", "Âm Hán Việt_Xie": "bả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này thường làm động từ chỉ hành động đi khập khiễng hoặc làm tính từ mô tả trạng thái chân bị què. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('汕', '{"9000": "3869.0", "Chữ Trung Quốc": "汕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 6 | nét | 水 | thủy | biểu nghĩa | nước | 山 | sơn | biểu âm | núi | 汕 là chữ hình thanh: bộ 水 (thủy, biểu nghĩa: nước) + 山 (sơn, biểu âm, gợi đọc shàn). Chữ chỉ cái sán — lưỡng tán/rổ tre để đuổi cá; nay nổi tiếng nhất qua địa danh汕头 (Sán Đầu).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sán\": bộ 水 (thủy) + 山 (núi) — \"sán\" chài lưới trên sông dưới chân núi, Sán Đầu (汕头) là thành phố cảng biển nổi tiếng. | Gương Hán-Việt | 汕 trong 汕头 (Sán Đầu — thành phố ở Quảng Đông), 汕尾 (Sán Vỹ) | Mở khoá kiến thức | Biết 汕 mở khoá địa danh Quảng Đông: 汕头 (Shantou), 汕尾.", "Tự nguyên_Xie": "Theo Wiktionary, 汕 là chữ hình thanh: bộ 水 (thủy) biểu nghĩa chỉ nước, 山 (sơn) biểu âm. Nguyên nghĩa chỉ dụng cụ đánh cá bằng tre trên nước. Ngày nay chủ yếu dùng trong địa danh汕头 (Sán Đầu) và 汕尾 (Sán Vỹ) ở tỉnh Quảng Đông. Cách đọc sán trong Hán-Việt phản ánh âm trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái sán", "Hạng Tần Suất (Jun Da)": "3869.0", "Tần Suất % (Jun Da)": "99.7032733449", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 山", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵山", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "山", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "汕", "Unihan_Traditional (Chữ Phồn thể)": "汕", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "sán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này thường dùng làm danh từ trong địa danh hoặc làm động từ chỉ việc dùng lưới bắt cá. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('欤', '{"9000": "3870.0", "Chữ Trung Quốc": "欤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 欠 | Số nét | 7 | nét | 欤 | dư | tượng hình | trợ từ hỏi (vậy ư, phải không) | 欤 là dạng giản thể của 歟 (與+欠), thuộc bộ 欠 (khiếm, hơi thở/thở ra). Chữ phồn thể 歟 gồm 與 (biểu âm) + 欠 (biểu nghĩa: hơi thở = âm thanh miệng). Chữ là trợ từ nghi vấn trong văn ngôn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dư\": bộ 欠 (hơi thở) + 与 (dư = cùng nhau) — thở ra hỏi \"vậy ư?\", đó là 欤 — trợ từ nghi vấn văn ngôn. | Gương Hán-Việt | 欤 là trợ từ độc lập trong văn ngôn, tương đương \"vậy ư\", \"phải không\" | Mở khoá kiến thức | Biết 欤 giúp đọc hiểu văn ngôn, kinh điển Nho gia — trợ từ câu hỏi cuối câu.", "Tự nguyên_Xie": "欤 là dạng giản thể của 歟 (與 + 欠). Bộ 欠 (khiếm) biểu nghĩa chỉ hơi thở, âm thanh từ miệng; 與 (dữ) biểu âm. Chữ là trợ từ dùng cuối câu hỏi trong văn ngôn — tương đương 吗/呢 trong tiếng Trung hiện đại. Cách đọc dư trong Hán-Việt phản ánh âm trung cổ yú. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vậy ư (câu hỏi)", "Hạng Tần Suất (Jun Da)": "3870.0", "Tần Suất % (Jun Da)": "99.7036071881", "GavinGrover_Once (Chiết tự trực tiếp)": "与 + 欠", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰与欠", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "与", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "欠", "Unihan_Simplified (Chữ Giản thể)": "欤", "Unihan_Traditional (Chữ Phồn thể)": "歟", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "dư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Chữ này làm trợ từ ngữ khí đặt ở cuối câu hỏi hoặc câu cảm thán trong văn ngôn cổ. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí).", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('壑', '{"9000": "3871.0", "Chữ Trung Quốc": "壑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 17 | nét | 壑 | hác | tượng hình | hẻm núi, hang hốc, ngòi ao sâu | 壑 không có dữ liệu glyph-origin đầy đủ. Thuộc bộ 土 (thổ), chỉ hẻm núi sâu, hang hốc tự nhiên. Thường dùng trong văn học cổ tả cảnh thiên nhiên hùng vĩ hoặc lòng tham vô đáy.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hác\": cái \"hác\" sâu không đáy — 欲壑难填 lòng tham như vực sâu không thể lấp đầy. | Gương Hán-Việt | 壑 trong 欲壑难填 (dục hác nan điền — lòng tham vô đáy), 沟壑 (câu hác — hẻm sâu) | Mở khoá kiến thức | Biết 壑 mở khoá 欲壑难填 (thành ngữ: tham lam vô đáy), 沟壑 (hẻm sâu, vực).", "Tự nguyên_Xie": "壑 thuộc bộ 土 (thổ), chỉ hẻm núi sâu hoặc ngòi trũng sâu. Không có glyph-origin đầy đủ từ Wiktionary. Cách đọc hác trong Hán-Việt phản ánh âm trung cổ hè. Thành ngữ 欲壑难填 (dục hác nan điền — lòng tham không đáy) rất phổ biến. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hang hốc; cái ngòi, cái ao", "Hạng Tần Suất (Jun Da)": "3871.0", "Tần Suất % (Jun Da)": "99.703939481", "GavinGrover_Once (Chiết tự trực tiếp)": "㕡 + 土", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱㕡土", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "㕡", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "壑", "Unihan_Traditional (Chữ Phồn thể)": "壑", "Pinyin_Xie": "hè", "Âm Hán Việt_Xie": "hác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ các khe núi sâu hoặc rãnh nước lớn, thường xuất hiện trong văn chương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颍', '{"9000": "3872.0", "Chữ Trung Quốc": "颍", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 12 | nét | 颍 | dĩnh | tượng hình | sông Dĩnh (Toánh) ở Hà Nam, Trung Quốc | 颍 là dạng giản thể của 潁 (氵 + 頁/页). Bộ gốc 氵 (thủy) chỉ sông nước. Chữ hầu như chỉ dùng làm địa danh sông Dĩnh (颍河) ở tỉnh Hà Nam.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dĩnh\": bộ 氵 (sông nước) + 页 (trang = đầu người) — con sông \"dĩnh\" (颍河) đổ đầu nguồn qua đất Hà Nam. | Gương Hán-Việt | 颍 trong 颍河 (Dĩnh Hà — sông Dĩnh), 颍上 (Dĩnh Thượng — huyện ở Hà Nam) | Mở khoá kiến thức | Biết 颍 mở khoá địa danh lịch sử Trung Hoa: 颍河 (sông Dĩnh), 颍川 (vùng đất cổ Hà Nam).", "Tự nguyên_Xie": "颍 là dạng giản thể của 潁, Wiktionary chỉ dẫn xem 潁 để tra glyph-origin. Chữ chỉ tên riêng địa lý — sông Dĩnh (颍河) chảy qua Hà Nam và An Huy. Không có glyph-origin cổ điển trong Wiktionary. Cách đọc dĩnh trong Hán-Việt phản ánh âm trung cổ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "song Toánh", "Hạng Tần Suất (Jun Da)": "3872.0", "Tần Suất % (Jun Da)": "99.704271257", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "颍", "Unihan_Traditional (Chữ Phồn thể)": "潁", "Pinyin_Xie": "yǐng", "Âm Hán Việt_Xie": "dĩnh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này chủ yếu làm danh từ riêng chỉ sông Dĩnh hoặc dùng trong tên địa danh, tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('溥', '{"9000": "3873.0", "Chữ Trung Quốc": "溥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 13 | nét | 氵 | thủy | biểu nghĩa | nước | 尃 | phổ | biểu âm | rộng khắp, phân tán | 溥 là chữ hình thanh: bộ 氵 (thủy, biểu nghĩa: nước) + 尃 (phổ, biểu âm, gợi đọc pǔ). Chữ chỉ tính rộng lớn, bao trùm khắp nơi — như nước trải dài vô tận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phổ\": bộ 氵 (nước) + 尃 (phổ = lan toả) — nước \"phổ\" lan khắp bốn bề, 溥天 là khắp gầm trời. | Gương Hán-Việt | 溥 trong 溥天 (phổ thiên — khắp bầu trời), 溥仪 (Phổ Nghi — tên hoàng đế cuối Thanh) | Mở khoá kiến thức | Biết 溥 mở khoá 溥天同庆 (khắp nơi đều ăn mừng), tên riêng 溥仪 (Phổ Nghi).", "Tự nguyên_Xie": "Theo Wiktionary, 溥 là chữ hình thanh: bộ 氵/水 (thủy) biểu nghĩa chỉ nước/rộng lớn, 尃 (phổ/phủ) biểu âm. Chữ chỉ sự rộng lớn, phổ khắp — thường dùng trong văn học cổ. Tên Phổ Nghi (溥仪 — vua cuối nhà Thanh) dùng chữ này. Cách đọc phổ trong Hán-Việt phản ánh âm trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "to lớn; khắp nơi", "Hạng Tần Suất (Jun Da)": "3873.0", "Tần Suất % (Jun Da)": "99.7046019995", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 尃", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵尃", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尃", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "溥", "Unihan_Traditional (Chữ Phồn thể)": "溥", "Pinyin_Xie": "pǔ", "Âm Hán Việt_Xie": "phổ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Chữ này làm tính từ chỉ sự rộng lớn hoặc làm phó từ bổ nghĩa cho động từ với nghĩa là khắp nơi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('姗', '{"9000": "3874.0", "Chữ Trung Quốc": "姗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 8 | nét | 女 | nữ | biểu nghĩa | nữ, phụ nữ | 刪 | san | biểu âm | xoá, cắt bỏ | 姗 là chữ hình thanh: bộ 女 (nữ, biểu nghĩa: phụ nữ) + 刪 (san, biểu âm viết tắt, gợi đọc shān). Chữ chỉ dáng đi thướt tha, uyển chuyển của phụ nữ — thường thấy trong 姗姗来迟.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": bộ 女 (phụ nữ) + 刪 (san = cắt từng bước) — bước chân \"san\" từng bước thướt tha, 姗姗来迟 là đến muộn mà vẫn duyên. | Gương Hán-Việt | 姗 trong 姗姗来迟 (san san lai trì — đến chậm một cách duyên dáng) | Mở khoá kiến thức | Biết 姗 mở khoá 姗姗来迟 (thành ngữ: đến muộn), 媻姗 (đi khó khăn), hay gặp trong văn học.", "Tự nguyên_Xie": "Theo Wiktionary, 姗 (姍) là chữ hình thanh: bộ 女 (nữ) biểu nghĩa chỉ phụ nữ, 刪 (san) biểu âm (viết tắt). Chữ vốn chỉ dáng đi uyển chuyển, thướt tha; cũng có nghĩa phụ là chê bai/phỉ báng (nghĩa cổ). Thành ngữ 姗姗来迟 (san san lai trì — đến chậm như dáng thướt tha) rất phổ biến. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chê cười; dáng đi thướt tha", "Hạng Tần Suất (Jun Da)": "3874.0", "Tần Suất % (Jun Da)": "99.704932742", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "姗", "Unihan_Traditional (Chữ Phồn thể)": "姍", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường làm tính từ mô tả dáng đi uyển chuyển hoặc làm động từ mang nghĩa chê bai, phỉ báng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踊', '{"9000": "3875.0", "Chữ Trung Quốc": "踊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 14 | nét | 𧾷 | biểu nghĩa | bộ 足 biến thể — đôi chân | 甬 | dũng | biểu âm | đường hẹp có mái che | 踊 = 𧾷 (bộ 足 biến thể, biểu nghĩa: chân) + 甬 (Dũng, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 足 (𧾷) cho nghĩa (liên quan chân), 甬 cho âm yǒng. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũng\": đôi chân (𧾷) dũng cảm (甬-dũng) bật lên — nhảy vọt, hăng hái. | Gương Hán-Việt | \"dũng\" trong 踊跃 (dũng dược — hăng hái, nhiệt tình) | Mở khoá kiến thức | Biết 踊 mở khoá 踊跃 (hăng hái tham gia, đua nhau làm), 踊现 (xuất hiện ồ ạt).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ 踊 (dũng) là chữ hình thanh (ls=psc): bộ 足 (𧾷 — chân) biểu nghĩa; 甬 (Dũng) biểu âm cho âm yǒng. Nghĩa gốc: nhảy lên, bật cao. Hình tiểu triện và lục thư thông đều được lưu lại tại hanziyuan.net. Thường gặp trong 踊跃 (hăng hái, nhiệt tình tham gia). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhảy nhót; hăng hái làm việc", "Hạng Tần Suất (Jun Da)": "3875.0", "Tần Suất % (Jun Da)": "99.7052629677", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踊", "Unihan_Traditional (Chữ Phồn thể)": "踊", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động nhảy vọt lên hoặc làm tính từ thể hiện sự hăng hái, nhiệt tình. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('枭', '{"9000": "3876.0", "Chữ Trung Quốc": "枭", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 8 | nét | 枭 | kiêu | tượng hình | con cú mèo; kẻ dũng mãnh; hình phạt bêu đầu | 枭 là dạng giản thể của 梟 (chim cú trên cây gỗ). Không có dữ liệu cây thành phần đầy đủ từ anchor. Glyph origin chỉ ghi {{Han etym}}. Chữ mang hai nghĩa: (1) con cú mèo; (2) kẻ hung hãn, dũng mãnh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiêu\": cú mèo trên cây — \"kiêu\" hùng như cú dữ canh đêm, 枭雄 là hào kiệt hung mãnh. | Gương Hán-Việt | 枭 trong 枭雄 (kiêu hùng — anh hùng hung bạo), 毒枭 (độc kiêu — trùm ma túy) | Mở khoá kiến thức | Biết 枭 mở khoá 枭雄 (kiêu hùng), 毒枭 (trùm ma tuý), từ thường gặp trong tin tức và văn học.", "Tự nguyên_Xie": "枭 (phồn thể 梟) là tượng hình chỉ con cú mèo — chim ăn đêm hung ác. Không có glyph-origin đầy đủ từ Wiktionary (chỉ {{Han etym}}). Chữ còn chỉ hình phạt bêu đầu lên cây (kiêu thủ). Nghĩa phổ biến hiện nay: 枭雄 (kiêu hùng — anh hùng hung bạo, thủ lĩnh mạnh mẽ). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim kiêu; hình kiêu (chém đầu rồi bêu lên cây)", "Hạng Tần Suất (Jun Da)": "3876.0", "Tần Suất % (Jun Da)": "99.7055926766", "GavinGrover_Once (Chiết tự trực tiếp)": "No glyph available + 木", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴木", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "枭", "Unihan_Traditional (Chữ Phồn thể)": "梟", "Pinyin_Xie": "xiāo", "Âm Hán Việt_Xie": "kiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm danh từ chỉ chim cú hoặc kẻ cầm đầu, làm động từ chỉ việc chém đầu bêu cột, và làm tính từ chỉ sự dũng mãnh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('暄', '{"9000": "3877.0", "Chữ Trung Quốc": "暄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 13 | nét | 日 | nhật | biểu nghĩa | mặt trời | 宣 | tuyên | biểu âm | tuyên bố, rộng rãi | 暄 = 日 (Nhật, biểu nghĩa: mặt trời) + 宣 (Tuyên, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 日 (mặt trời) cho nghĩa, 宣 cho âm xuān. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huyên\": mặt trời (日) tuyên bố (宣) ngày đẹp trời — nắng ấm, dịu dàng. 寒暄 là hỏi han nhau về nóng lạnh. | Gương Hán-Việt | \"huyên\" trong 寒暄 (hàn huyên — chào hỏi, hỏi thăm thời tiết nóng lạnh) | Mở khoá kiến thức | Biết 暄 mở khoá 寒暄 (chào hỏi xã giao), 暄暖 (ấm áp dễ chịu).", "Tự nguyên_Xie": "Chữ 暄 (huyên) là chữ hình thanh (ls=psc): bộ 日 (Nhật — mặt trời) biểu nghĩa; 宣 (Tuyên) biểu âm cho âm xuān. Nghĩa gốc: ánh nắng ấm áp, mặt trời dịu dàng. Wiktionary xác nhận chữ cổ (mc=y, oc=y). Thường gặp trong 寒暄 (chào hỏi xã giao — bàn chuyện thời tiết nóng lạnh). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nắng ấm", "Hạng Tần Suất (Jun Da)": "3877.0", "Tần Suất % (Jun Da)": "99.7059223855", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 宣", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日宣", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宣", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "暄", "Unihan_Traditional (Chữ Phồn thể)": "暄", "Pinyin_Xie": "xuān", "Âm Hán Việt_Xie": "huyên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ thời tiết ấm áp hoặc làm danh từ chỉ hơi ấm của ánh mặt trời. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('稷', '{"9000": "3878.0", "Chữ Trung Quốc": "稷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 禾 | Số nét | 15 | nét | 稷 | tắc | tượng hình | lúa tắc (kê), thần lúa | 稷 thuộc bộ 禾 (hoà, lúa), chỉ loại lương thực kê/cao lương quan trọng nhất trong ngũ cốc. Không có dữ liệu cây thành phần đầy đủ từ anchor (glyph origin chỉ {{Han etym}}). Chữ còn chỉ thần lúa và được dùng trong từ 社稷 (xã tắc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tắc\": bộ 禾 (lúa) + thần nông — \"tắc\" là hạt giống thần thánh, 社稷 là giang sơn xã \"tắc\" của đất nước. | Gương Hán-Việt | 稷 trong 社稷 (xã tắc — đất nước, giang sơn), 后稷 (Hậu Tắc — thần nông nghiệp) | Mở khoá kiến thức | Biết 稷 mở khoá 社稷 (xã tắc — đất nước), 后稷 (Hậu Tắc — tổ tiên nhà Chu và thần nông).", "Tự nguyên_Xie": "稷 thuộc bộ 禾 (hoà, lúa), chỉ cây lúa kê/cao lương — loại lúa được coi trọng nhất trong ngũ cốc cổ đại Trung Hoa. Không có glyph-origin đầy đủ từ Wiktionary. Hậu Tắc (后稷) là thần nông nghiệp và tổ tiên nhà Chu. 社稷 (xã tắc — xã = thần đất, tắc = thần lúa) là ẩn dụ cho quốc gia. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lúa tắc (giống lúa quý nhất); thần lúa", "Hạng Tần Suất (Jun Da)": "3878.0", "Tần Suất % (Jun Da)": "99.7062520945", "GavinGrover_Once (Chiết tự trực tiếp)": "禾 + 畟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰禾畟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畟", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "禾", "Unihan_Simplified (Chữ Giản thể)": "稷", "Unihan_Traditional (Chữ Phồn thể)": "稷", "Pinyin_Xie": "jì", "Âm Hán Việt_Xie": "tắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây lúa kê hoặc vị thần cai quản nông nghiệp thời cổ đại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('跚', '{"9000": "3879.0", "Chữ Trung Quốc": "跚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 12 | nét | 跚 | san | tượng hình | đi khập khiễng, bước chân loạng choạng | 跚 thuộc bộ 足 (túc, chân), chỉ dáng đi khó khăn, loạng choạng. Không có dữ liệu cây thành phần đầy đủ từ anchor. Chữ hầu như chỉ dùng trong từ ghép 蹒跚 (bàn san — đi lảo đảo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"san\": bộ 足 (chân) đi \"san\" từng bước loạng choạng — 蹒跚 là bước chân chập chờn của người già hay say. | Gương Hán-Việt | 跚 trong 蹒跚 (bàn san — đi lảo đảo), 蹒跚学步 (tập đi chập chững) | Mở khoá kiến thức | Biết 跚 mở khoá 蹒跚 (đi lảo đảo), 蹒跚学步 (chập chững tập đi), từ hay gặp khi tả người già/trẻ nhỏ.", "Tự nguyên_Xie": "跚 thuộc bộ 足 (túc, chân), chỉ dáng đi lảo đảo, khó khăn. Không có glyph-origin đầy đủ từ Wiktionary. Cách đọc san trong Hán-Việt phản ánh âm trung cổ shān. Chữ xuất hiện gần như chỉ trong từ ghép 蹒跚 (đi lảo đảo, chân không vững). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàn san 蹣跚,蹒跚)", "Hạng Tần Suất (Jun Da)": "3879.0", "Tần Suất % (Jun Da)": "99.7065818034", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 册", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊册", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "册", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "跚", "Unihan_Traditional (Chữ Phồn thể)": "跚", "Pinyin_Xie": "shān", "Âm Hán Việt_Xie": "san", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này chủ yếu làm động từ hoặc tính từ khi kết hợp thành từ láy để tả dáng đi không vững. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('涟', '{"9000": "3880.0", "Chữ Trung Quốc": "涟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 10 | nét | 氵 | thủy | biểu nghĩa | nước | 連 | liên | biểu âm | liên tục | 涟 = 氵(Thủy, biểu nghĩa: nước) + 連 (Liên, biểu âm); chữ hình thanh. Bộ nước gợi nghĩa mặt nước gợn sóng, 連 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"liên\": nước (氵) chảy liên tục (連) thành từng gợn sóng lăn tăn — mặt hồ khi gió thổi nhẹ. | Gương Hán-Việt | liên trong 涟漪 (liên y — gợn sóng) | Mở khoá kiến thức | Biết 涟 (liên) giúp đọc 涟漪 (gợn sóng), 涟涟 (nước mắt rơi liên tục).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 水 (氵) biểu nghĩa nước, 連 biểu âm. Dạng chính thể là 漣. Nghĩa gốc: sóng lăn tăn trên mặt nước, mở rộng sang hình ảnh nước mắt rơi liên tục (涟涟). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lăn tăn, gió thổi mặt nước lăn tăn; rơm rớm nước mắt", "Hạng Tần Suất (Jun Da)": "3880.0", "Tần Suất % (Jun Da)": "99.7069104787", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 连", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵连", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "连", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "涟", "Unihan_Traditional (Chữ Phồn thể)": "漣", "Pinyin_Xie": "lián", "Âm Hán Việt_Xie": "liên", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này thường làm tính từ miêu tả trạng thái mặt nước gợn sóng hoặc nước mắt tuôn rơi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瀛', '{"9000": "3881.0", "Chữ Trung Quốc": "瀛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 19 | nét | 水 | thủy | biểu nghĩa | nước | 嬴 | doanh | biểu âm | 瀛 = 水 (Thủy, biểu nghĩa: nước) + 嬴 (Doanh, biểu âm); chữ hình thanh. Bộ nước gợi nghĩa biển lớn, 嬴 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"doanh\": biển (水) rộng mênh mông như tài sản (嬴) vô tận — đại dương bao la trong thơ cổ. | Gương Hán-Việt | doanh trong 瀛洲 (doanh châu — đảo tiên trên biển) | Mở khoá kiến thức | Biết 瀛 (doanh) giúp đọc 东瀛 (Đông Doanh — Nhật Bản), 瀛寰 (hoàn cầu).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: bộ 水 biểu nghĩa nước biển, 嬴 biểu âm. Nghĩa gốc chỉ đại dương rộng lớn, dùng nhiều trong văn thơ cổ điển (东瀛 — biển phía đông, tức Nhật Bản). Có dạng kim văn và tiểu triện. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đại dương, biển lớn", "Hạng Tần Suất (Jun Da)": "3881.0", "Tần Suất % (Jun Da)": "99.7072391541", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 嬴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵嬴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "嬴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "瀛", "Unihan_Traditional (Chữ Phồn thể)": "瀛", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "doanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ biển cả hoặc dùng trong địa danh và tên người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('笙', '{"9000": "3882.0", "Chữ Trung Quốc": "笙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 11 | nét | 竹 | trúc | biểu nghĩa | tre, trúc | 生 | sinh | biểu âm | 笙 = 竹 (Trúc, biểu nghĩa: tre) + 生 (Sinh, biểu âm); chữ hình thanh. Bộ trúc gợi nhạc cụ làm bằng ống tre, 生 cho âm đọc đồng thời gợi sự sinh động.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"sanh\": ống trúc (竹) thổi lên tiếng nhạc sinh động (生) — cây sênh bát bửu trong lễ nhạc cung đình. | Gương Hán-Việt | sanh trong 笙歌 (sanh ca — tiếng đàn sênh và ca hát) | Mở khoá kiến thức | Biết 笙 (sanh) giúp đọc 笙歌 (tiếng nhạc và ca), 笙箫 (sênh và tiêu).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 竹 biểu nghĩa nhạc cụ làm từ tre, 生 biểu âm. Sinh (笙) là nhạc cụ hơi cổ truyền Trung Hoa gồm nhiều ống tre xếp tròn, thổi bằng miệng. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sinh (một nhạc cụ như sáo); cái sênh; cái chiếu", "Hạng Tần Suất (Jun Da)": "3882.0", "Tần Suất % (Jun Da)": "99.7075678294", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 生", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮生", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "生", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "笙", "Unihan_Traditional (Chữ Phồn thể)": "笙", "Pinyin_Xie": "shēng", "Âm Hán Việt_Xie": "sanh, sinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loại nhạc cụ hơi truyền thống của Trung Quốc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('滕', '{"9000": "3883.0", "Chữ Trung Quốc": "滕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 15 | nét | 朕 | trẫm | biểu âm | 水 | thủy | biểu nghĩa | nước | 滕 = 朕 (Trẫm, biểu âm) + 水 (Thủy, biểu nghĩa: nước); chữ hình thanh. Bộ nước gợi nghĩa nước vọt lên, 朕 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đằng\": nước (水) phun vọt như bệ rồng (朕 — bệ hạ) — đây cũng là tên nước Đằng thời Chiến Quốc. | Gương Hán-Việt | đằng trong 滕州 (Đằng Châu — thành phố ở Sơn Đông) | Mở khoá kiến thức | Biết 滕 (đằng) giúp nhận ra họ Đằng và địa danh 滕州 trong lịch sử Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 朕 biểu âm, 水 biểu nghĩa nước. Nghĩa gốc là nước phun vọt lên mạnh mẽ. Về sau dùng chủ yếu làm tên nước cổ (nước Đằng) và họ người. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nước nhảy vọt lên; nước Đằng", "Hạng Tần Suất (Jun Da)": "3883.0", "Tần Suất % (Jun Da)": "99.707895988", "GavinGrover_Once (Chiết tự trực tiếp)": "月 + 𣳾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰月𣳾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𣳾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "月", "Unihan_Simplified (Chữ Giản thể)": "滕", "Unihan_Traditional (Chữ Phồn thể)": "滕", "Pinyin_Xie": "téng", "Âm Hán Việt_Xie": "đằng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này làm động từ chỉ nước phun lên hoặc làm danh từ riêng chỉ tên nước cổ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('踝', '{"9000": "3884.0", "Chữ Trung Quốc": "踝", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 15 | nét | 𧾷 | túc | biểu nghĩa | bàn chân | 果 | quả | biểu âm | 踝 = 𧾷 (Túc, biểu nghĩa: bàn chân) + 果 (Quả, biểu âm); chữ hình thanh. Bộ bàn chân gợi vị trí khớp mắt cá, 果 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khỏa\": bàn chân (𧾷) có khớp tròn như quả (果) — đó là mắt cá chân. | Gương Hán-Việt | khỏa trong 踝骨 (khỏa cốt — xương mắt cá) | Mở khoá kiến thức | Biết 踝 (khỏa) giúp đọc 脚踝 (mắt cá chân), 踝关节 (khớp cổ chân).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 足 (𧾷) biểu nghĩa bàn chân, 果 biểu âm. Nghĩa duy nhất là mắt cá chân (khớp nối bàn chân và cẳng chân). Từ ghép phổ biến: 脚踝 (mắt cá chân), 踝骨 (xương mắt cá). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mắt cá", "Hạng Tần Suất (Jun Da)": "3884.0", "Tần Suất % (Jun Da)": "99.7082241465", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "踝", "Unihan_Traditional (Chữ Phồn thể)": "踝", "Pinyin_Xie": "huái", "Âm Hán Việt_Xie": "hoã", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mắt cá chân, thường kết hợp thành từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('贰', '{"9000": "3885.0", "Chữ Trung Quốc": "贰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 弋 | Số nét | 9 | nét | 貝 | bối | biểu nghĩa | tiền, của cải | 弍 | nhị | biểu âm | hai | 贰 = 貝 (Bối, biểu nghĩa: tiền của) + 弍 (Nhị, biểu âm: hai); chữ hình thanh. Bối gợi nghĩa tài chính (viết số tiền trang trọng), 弍 cho âm đọc và nghĩa số hai.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhị\": đồng tiền (貝) ghi số hai (弍) theo lối chính thức chống làm giả — chữ 贰 dùng trên giấy tờ pháp lý. | Gương Hán-Việt | nhị trong 贰心 (nhị tâm — lòng dạ phản trắc) | Mở khoá kiến thức | Biết 贰 (nhị) giúp đọc số tiền trang trọng trên hóa đơn, hợp đồng Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Chữ hình thanh dạng phồn thể là 貳: bộ 貝 (tiền, của cải) + 弍 (nhị — hai) biểu âm. Kim văn và tiểu triện còn lưu. Nghĩa chính trong tài chính là số hai dạng chính thức (như chữ 贰 trên hợp đồng, séc). Nghĩa phụ trong cổ văn: phụ tá, hoặc không trung thành (có lòng dạ hai chiều). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chức phó; 2, hai, (như: 二, dùng để viết văn tự)", "Hạng Tần Suất (Jun Da)": "3885.0", "Tần Suất % (Jun Da)": "99.7085517883", "GavinGrover_Once (Chiết tự trực tiếp)": "弍 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴弍贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "弍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "贰", "Unihan_Traditional (Chữ Phồn thể)": "貳", "Pinyin_Xie": "èr", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Số từ | 数词 | Động từ | 动词 | Chữ này làm số từ trong văn bản tài chính hoặc làm động từ với nghĩa phản bội, nghi ngờ. | Số từ | 数词 | Chỉ số lượng hoặc thứ tự. Hầu như không đứng thẳng trước danh từ mà phải chèn lượng từ ở giữa: 两个人. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瞰', '{"9000": "3886.0", "Chữ Trung Quốc": "瞰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 16 | nét | 目 | mục | biểu nghĩa | mắt | 敢 | cảm | biểu âm | 瞰 = 目 (Mục, biểu nghĩa: mắt) + 敢 (Cảm, biểu âm); chữ hình thanh. Bộ mắt gợi hành động nhìn từ trên cao xuống, 敢 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khám\": đôi mắt (目) dám (敢) nhìn thẳng từ trên xuống — cái nhìn bao quát từ đỉnh cao. | Gương Hán-Việt | khám trong 俯瞰 (phủ khám — nhìn từ trên cao) | Mở khoá kiến thức | Biết 瞰 (khám) giúp đọc 俯瞰 (phủ khám), 鸟瞰 (điểu khám — toàn cảnh từ trên).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 目 biểu nghĩa ánh mắt quan sát, 敢 biểu âm. Nghĩa gốc là nhìn từ trên xuống, nhìn xuống bên dưới. Từ ghép phổ biến: 俯瞰 (nhìn từ trên cao xuống), 鸟瞰 (nhìn từ góc độ chim bay — toàn cảnh). Chưa có nguồn học thuật rõ ràng ngoài cấu trúc hình thanh. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhìn, xem, dòm", "Hạng Tần Suất (Jun Da)": "3886.0", "Tần Suất % (Jun Da)": "99.7088794301", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 敢", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目敢", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "瞰", "Unihan_Traditional (Chữ Phồn thể)": "瞰", "Pinyin_Xie": "kàn", "Âm Hán Việt_Xie": "khám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước tân ngữ chỉ nơi chốn để biểu thị hành động nhìn từ trên cao xuống. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恻', '{"9000": "3887.0", "Chữ Trung Quốc": "恻", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 9 | nét | 恻 | trắc | tượng hình | lòng xót thương, đau lòng | 恻 là chữ hình thanh, dạng phồn thể 惻 gồm bộ 忄(tâm — lòng) + 則 (tắc — biểu âm). Bộ lòng gợi cảm xúc xót xa, 則 cho âm đọc. Dạng giản thể 恻 không hiển thị rõ cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trắc\": lòng (忄) đau trắc ẩn khi thấy người khổ — 恻隐之心 là hạt nhân của nhân trong Nho giáo. | Gương Hán-Việt | trắc trong 恻隐 (trắc ẩn — lòng xót thương) | Mở khoá kiến thức | Biết 恻 (trắc) giúp đọc 恻隐之心 (trắc ẩn chi tâm — lòng trắc ẩn), 悱恻 (bi trắc — não nùng).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Dạng phồn thể 惻 là chữ hình thanh: bộ 忄(心) biểu nghĩa cảm xúc, 則 biểu âm. Nghĩa gốc là đau lòng, xót xa, thương cảm sâu sắc. Thường gặp trong 恻隐之心 (lòng trắc ẩn) — khái niệm Nho giáo về lòng thương người bẩm sinh. Tiểu triện còn lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xót xa, bùi ngùi", "Hạng Tần Suất (Jun Da)": "3887.0", "Tần Suất % (Jun Da)": "99.7092060383", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + 则", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄则", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "则", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "忄", "Unihan_Simplified (Chữ Giản thể)": "恻", "Unihan_Traditional (Chữ Phồn thể)": "惻", "Pinyin_Xie": "cè", "Âm Hán Việt_Xie": "trắc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ biểu thị tâm trạng đau buồn, thường dùng trong các từ ghép như trắc ẩn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嚏', '{"9000": "3888.0", "Chữ Trung Quốc": "嚏", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 17 | nét | 口 | khẩu | biểu nghĩa | miệng | 疐 | chí | biểu âm | vấp ngã; cho âm ''tì'' | 嚏 là chữ hình thanh (psc): 口 (khẩu, miệng) biểu nghĩa — âm thanh phát ra từ miệng mũi; 疐 (chí) biểu âm cho âm ''tì''. Chữ chỉ hành động hắt xì hơi, thường dùng trong từ 打喷嚏.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xì\": miệng (口) kết hợp với 疐 biểu âm → tiếng bật ra như \"xì\" — hắt xì hơi (打喷嚏). | Gương Hán-Việt | xì trong ''hắt xì''; ít dùng độc lập trong tiếng Việt hiện đại | Mở khoá kiến thức | Biết 嚏 (Xì) mở khoá: hắt hơi (打喷嚏) — từ duy nhất dùng trong HSK 5.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Theo Wiktionary, 嚏 cấu tạo hình thanh (psc): 口 biểu nghĩa (miệng), 疐 biểu âm. Tiểu triện và Lục thư thông lưu dấu hình này. Nghĩa: hắt xì hơi — một phản xạ của miệng mũi khi tiếp xúc với tác nhân kích thích. Chữ xuất hiện trong văn ngôn cổ; hiện đại dùng chủ yếu qua 打喷嚏. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hắt xì hơi", "Hạng Tần Suất (Jun Da)": "3888.0", "Tần Suất % (Jun Da)": "99.7095321297", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 疐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口疐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "疐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "嚏", "Unihan_Traditional (Chữ Phồn thể)": "嚏", "Pinyin_Xie": "tì", "Âm Hán Việt_Xie": "đế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Chữ này làm danh từ chỉ cái hắt hơi, thường đi sau động từ để tạo thành cụm động từ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('迢', '{"9000": "3889.0", "Chữ Trung Quốc": "迢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 8 | nét | 辵 | xước | biểu nghĩa | đi, bước | 召 | thiệu | biểu âm | 迢 = 辵 (Xước, biểu nghĩa: đi bước) + 召 (Thiệu, biểu âm); chữ hình thanh. Bộ đi gợi con đường dài, 召 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"diệu\": bước chân (辵) theo tiếng gọi (召) mãi từ xa — 千里迢迢 ngàn dặm xa xôi. | Gương Hán-Việt | diệu trong 迢迢 (diệu diệu — xa tít tắp) | Mở khoá kiến thức | Biết 迢 (diệu) giúp đọc 迢迢 (xa xôi), 千里迢迢 (ngàn dặm xa xôi).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 辵 biểu nghĩa hành trình, 召 biểu âm. Nghĩa gốc là xa xôi, con đường xa. Dùng chủ yếu trong văn thơ qua 迢迢 (diệu diệu — xa tít tắp) và 千里迢迢 (ngàn dặm xa xôi). Tiểu triện và lục thư thông còn lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xa xôi", "Hạng Tần Suất (Jun Da)": "3889.0", "Tần Suất % (Jun Da)": "99.7098571876", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 召", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶召", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "召", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "迢", "Unihan_Traditional (Chữ Phồn thể)": "迢", "Pinyin_Xie": "tiáo", "Âm Hán Việt_Xie": "điều", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả khoảng cách xa xôi, thường dùng lặp lại hoặc trong từ ghép. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('獗', '{"9000": "3890.0", "Chữ Trung Quốc": "獗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 15 | nét | 獗 | quyết | tượng hình | hung hăng, tung hoành | 獗 là chữ có bộ 犭(khuyển — chó, thú dữ) gợi tính hung bạo. Cấu trúc chi tiết không rõ từ nguồn Wiktionary; chưa có phân tích hình thanh hay hội ý đầy đủ. Chữ chủ yếu dùng trong 猖獗 (xương quyết).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quyết\": thú dữ (犭) hung hăng quyết liệt — 猖獗 chỉ tình trạng kẻ xấu tung hoành ngang ngược. | Gương Hán-Việt | quyết trong 猖獗 (xương quyết — hung hăng hoành hành) | Mở khoá kiến thức | Biết 獗 (quyết) giúp đọc 猖獗 (xương quyết) — từ hay gặp trong báo chí khi nói về tội phạm tung hoành.", "Tự nguyên_Xie": "Nguồn Wiktionary chỉ ghi nhận 獗 dùng trong 猖獗 (hung hăng, tung hoành) mà không cung cấp phân tích cấu tạo chi tiết. Bộ 犭(khuyển) gợi sự hung bạo như thú dữ. Chưa có nguồn học thuật rõ ràng về gốc tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thế giặc tung hoành", "Hạng Tần Suất (Jun Da)": "3890.0", "Tần Suất % (Jun Da)": "99.7101822454", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 厥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭厥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "厥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "獗", "Unihan_Traditional (Chữ Phồn thể)": "獗", "Pinyin_Xie": "jué", "Âm Hán Việt_Xie": "quyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ miêu tả sự hung bạo, thường kết hợp thành từ ghép để chỉ thế lực hoành hành. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邯', '{"9000": "3891.0", "Chữ Trung Quốc": "邯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 邑 | Số nét | 7 | nét | 甘 | cam | biểu âm | 阝 | ấp | biểu nghĩa | thành ấp, khu vực | 邯 = 甘 (Cam, biểu âm) + 阝(邑, Ấp, biểu nghĩa: thành ấp); chữ hình thanh. Bộ ấp gợi địa danh, 甘 cho âm đọc. Đây là tên địa danh (Hàm Đan — thành phố ở Hà Bắc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hàm\": ấp (阝) ngọt ngào (甘) như kinh đô Hàm Đan — nơi xuất phát thành ngữ 邯郸学步. | Gương Hán-Việt | hàm trong 邯郸 (Hàm Đan — thành phố cổ) | Mở khoá kiến thức | Biết 邯 (hàm) giúp đọc địa danh 邯郸 và thành ngữ 邯郸学步 (bắt chước vụng về).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 甘 biểu âm, bộ 邑 (阝) biểu nghĩa khu vực hành chính. Đại triện và tiểu triện còn lưu. Chủ yếu dùng trong địa danh 邯郸 (Hàm Đan — thành phố cổ ở Hà Bắc, kinh đô nước Triệu thời Chiến Quốc). Thành ngữ 邯郸学步 (học đi như người Hàm Đan — mô phỏng vụng về mất cả bản thân) xuất phát từ đây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(tên riêng)", "Hạng Tần Suất (Jun Da)": "3891.0", "Tần Suất % (Jun Da)": "99.7105067865", "GavinGrover_Once (Chiết tự trực tiếp)": "甘 + 阝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰甘阝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "甘", "Unihan_Simplified (Chữ Giản thể)": "邯", "Unihan_Traditional (Chữ Phồn thể)": "邯", "Pinyin_Xie": "hán", "Âm Hán Việt_Xie": "hàm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ riêng, hầu như chỉ dùng trong địa danh cổ Hàm Đan. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睑', '{"9000": "3892.0", "Chữ Trung Quốc": "睑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 睑 | kiểm | tượng hình | mí mắt | 睑 là dạng giản thể của 瞼. Dạng phồn thể 瞼 gồm bộ 目 (mục — mắt, biểu nghĩa) + 僉 (thiêm — biểu âm); chữ hình thanh. Bộ mắt gợi vị trí mí mắt, phần da bao che mắt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểm\": mắt (目) có mí che như tấm kiểm soát — 眼睑 là mí mắt trong y học. | Gương Hán-Việt | kiểm trong 眼睑 (nhãn kiểm — mí mắt) | Mở khoá kiến thức | Biết 睑 (kiểm) giúp đọc 眼睑 (mí mắt) trong văn bản y tế, 睑腺炎 (lẹo mắt).", "Tự nguyên_Xie": "Tiểu triện | Dạng phồn thể 瞼 là chữ hình thanh: bộ 目 biểu nghĩa mắt, 僉 biểu âm. Tiểu triện còn lưu. Nghĩa duy nhất là mí mắt (phần da trên và dưới che nhãn cầu). Từ ghép: 眼睑 (nhãn kiểm — mí mắt), 眼皮 là từ dân dã cùng nghĩa. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mí mắt", "Hạng Tần Suất (Jun Da)": "3892.0", "Tần Suất % (Jun Da)": "99.7108313275", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 佥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目佥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "佥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睑", "Unihan_Traditional (Chữ Phồn thể)": "瞼", "Pinyin_Xie": "jiǎn", "Âm Hán Việt_Xie": "kiểm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng trong y học hoặc kết hợp thành từ ghép chỉ mí mắt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('赡', '{"9000": "3893.0", "Chữ Trung Quốc": "赡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 貝 | Số nét | 17 | nét | 赡 | thiệm | tượng hình | cấp dưỡng, phong phú | 赡 là dạng giản thể của 贍. Dạng phồn thể 贍 gồm bộ 貝 (bối — tiền của, biểu nghĩa) + 詹 (chiêm — biểu âm); chữ hình thanh. Bộ tiền của gợi ý nghĩa cấp dưỡng, chu cấp vật chất.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiệm\": của cải (貝) đủ đầy để nuôi dưỡng — 赡养 là nghĩa vụ pháp lý phụng dưỡng cha mẹ ở Trung Quốc. | Gương Hán-Việt | thiệm trong 赡养 (thiệm dưỡng — phụng dưỡng) | Mở khoá kiến thức | Biết 赡 (thiệm) giúp đọc 赡养 (phụng dưỡng), 赡养费 (tiền cấp dưỡng).", "Tự nguyên_Xie": "Đại triện | Dạng phồn thể 贍 là chữ hình thanh: bộ 貝 biểu nghĩa tài chính, vật chất, 詹 biểu âm. Đại triện còn lưu. Nghĩa chính là chu cấp, cấp dưỡng (赡养 — phụng dưỡng cha mẹ). Nghĩa phụ trong cổ văn: đầy đủ, phong phú (văn từ phong phú). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cấp giúp; phong phú, đầy đủ", "Hạng Tần Suất (Jun Da)": "3893.0", "Tần Suất % (Jun Da)": "99.7111553518", "GavinGrover_Once (Chiết tự trực tiếp)": "贝 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰贝詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "贝", "Unihan_Simplified (Chữ Giản thể)": "赡", "Unihan_Traditional (Chữ Phồn thể)": "贍", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiệm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ trong từ ghép chỉ việc cấp dưỡng hoặc làm tính từ chỉ sự phong phú. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('萦', '{"9000": "3894.0", "Chữ Trung Quốc": "萦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 11 | nét | 萦 | oanh | tượng hình | vương vấn, quấn quanh | 萦 là dạng giản thể của 縈. Dạng phồn thể 縈 gồm bộ 糸 (mịch — tơ sợi, biểu nghĩa) + 熒 lược thể (biểu âm); chữ hình thanh. Bộ tơ gợi hình ảnh sợi dây quấn vòng, mở rộng sang nghĩa vương vấn trong tâm trí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"oanh\": sợi tơ (糸) cuộn vòng như tâm trí bị vương vấn — 魂牵梦萦 là nỗi nhớ quấn chặt hồn mộng. | Gương Hán-Việt | oanh trong 萦绕 (oanh nhiễu — vương vấn, ám ảnh) | Mở khoá kiến thức | Biết 萦 (oanh) giúp đọc 萦绕 (vương vấn), 魂牵梦萦 (nhớ nhung ám ảnh).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Dạng phồn thể 縈 là chữ hình thanh: bộ 糸 biểu nghĩa sợi tơ quấn vòng, phần biểu âm cho âm đọc. Kim văn và tiểu triện còn lưu. Nghĩa gốc là cuộn, quấn; nghĩa mở rộng là vương vấn, ám ảnh trong tâm trí (魂牵梦萦 — hồn bị kéo, mộng bị vấn). Dùng chủ yếu trong văn học. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quay quanh, vòng quanh", "Hạng Tần Suất (Jun Da)": "3894.0", "Tần Suất % (Jun Da)": "99.7114793761", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "萦", "Unihan_Traditional (Chữ Phồn thể)": "縈", "Pinyin_Xie": "yíng", "Âm Hán Việt_Xie": "oanh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ thể hiện sự quanh co, vương vấn trong lòng hoặc quấn quýt không rời. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('珥', '{"9000": "3895.0", "Chữ Trung Quốc": "珥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 10 | nét | 玉 | ngọc | biểu nghĩa | ngọc quý | 耳 | nhĩ | biểu âm | tai | 珥 = 玉 (Ngọc, biểu nghĩa: ngọc quý) + 耳 (Nhĩ, biểu âm); chữ hình thanh. Bộ ngọc gợi chất liệu quý giá, 耳 vừa cho âm vừa gợi vị trí đeo (tai).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lẹ\": ngọc (玉) đeo trên tai (耳) — cái khuyên tai ngọc của phụ nữ quý tộc thời xưa. | Gương Hán-Việt | lẹ trong 珥笔 (lẹ bút — tra bút vào tai, sẵn sàng chép) | Mở khoá kiến thức | Biết 珥 (lẹ) giúp đọc tên trang sức cổ, đặc biệt trong văn học và khảo cổ.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 玉 biểu nghĩa đồ trang sức bằng ngọc, 耳 biểu âm. Tiểu triện còn lưu. Nghĩa gốc là khuyên tai, đồ trang sức ngọc cài vào tai. Nghĩa mở rộng: cắm, tra vào (như trong 珥笔 — tra bút vào tai, tức sẵn sàng ghi chép). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cái khuyên tai", "Hạng Tần Suất (Jun Da)": "3895.0", "Tần Suất % (Jun Da)": "99.7118034004", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 耳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王耳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "珥", "Unihan_Traditional (Chữ Phồn thể)": "珥", "Pinyin_Xie": "ěr", "Âm Hán Việt_Xie": "nhị", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ đồ trang sức đeo tai của phụ nữ thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('酮', '{"9000": "3896.0", "Chữ Trung Quốc": "酮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 酉 | Số nét | 13 | nét | 酮 | đồng | tượng hình | xêton (hợp chất hóa học) | 酮 là thuật ngữ hóa học hiện đại. Bộ 酉 (dậu — rượu, biểu nghĩa chất hóa học hữu cơ) + phần biểu âm. Cấu tạo chi tiết không có trong nguồn Wiktionary truyền thống vì đây là chữ tạo muộn cho thuật ngữ khoa học.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đồng\": bộ rượu (酉) + âm đồng — xêton là nhóm hóa chất hữu cơ có nhóm C=O, quan trọng trong sinh hóa (thể xêton trong chế độ keto). | Gương Hán-Việt | đồng trong 酮体 (đồng thể — thể xêton) | Mở khoá kiến thức | Biết 酮 (đồng) giúp đọc các thuật ngữ hóa học: 酮体 (thể xêton), 丙酮 (acêtôn).", "Tự nguyên_Xie": "酮 là chữ tạo muộn dùng cho thuật ngữ hóa học xêton (ketone — R₂C=O). Bộ 酉 gợi nhóm hợp chất hữu cơ. Không có nguồn gốc chữ cổ (giáp cốt, kim văn) vì đây là chữ đặt ra thời cận đại để phiên âm thuật ngữ phương Tây. Chưa có nguồn học thuật về gốc tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xêton (công thức hoá học: R2CO)", "Hạng Tần Suất (Jun Da)": "3896.0", "Tần Suất % (Jun Da)": "99.7121269079", "GavinGrover_Once (Chiết tự trực tiếp)": "酉 + 同", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰酉同", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "同", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "酉", "Unihan_Simplified (Chữ Giản thể)": "酮", "Unihan_Traditional (Chữ Phồn thể)": "酮", "Pinyin_Xie": "tóng", "Âm Hán Việt_Xie": "đồng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Dùng làm danh từ trong hóa học để chỉ nhóm hợp chất hữu cơ chứa nhóm carbonyl. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('璞', '{"9000": "3897.0", "Chữ Trung Quốc": "璞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 玉 | Số nét | 16 | nét | 玉 | ngọc | biểu nghĩa | ngọc quý | 菐 | bộc | biểu âm | 璞 = 玉 (Ngọc, biểu nghĩa: ngọc quý) + 菐 (Bộc, biểu âm); chữ hình thanh. Bộ ngọc gợi chất liệu quý, 菐 cho âm đọc. Nghĩa là viên ngọc còn trong đá chưa mài giũa — gợi tài năng chưa được phát hiện.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phác\": ngọc (玉) ẩn trong đá thô (菐 — bộc phác) — 璞玉 là ẩn dụ cho nhân tài chưa được phát hiện. | Gương Hán-Việt | phác trong 璞玉 (phác ngọc — ngọc thô, nhân tài tiềm ẩn) | Mở khoá kiến thức | Biết 璞 (phác) giúp đọc 璞玉 (ngọc thô), 返璞归真 (trở về bản chất thuần phác).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 玉 biểu nghĩa ngọc quý, 菐 biểu âm. Nghĩa gốc là ngọc thô chưa mài, còn trong khối đá. Nghĩa mở rộng: tài năng thuần phác chưa được trau dồi (璞玉 — ngọc thô, tài năng tiềm ẩn). Câu chuyện Hòa Thị Bích (和氏璧) nổi tiếng liên quan đến việc nhận ra ngọc quý trong đá thô. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngọc ở trong đá; chân thực", "Hạng Tần Suất (Jun Da)": "3897.0", "Tần Suất % (Jun Da)": "99.7124498986", "GavinGrover_Once (Chiết tự trực tiếp)": "王 + 菐", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰王菐", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "菐", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "王", "Unihan_Simplified (Chữ Giản thể)": "璞", "Unihan_Traditional (Chữ Phồn thể)": "璞", "Pinyin_Xie": "pú", "Âm Hán Việt_Xie": "phác", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Làm danh từ chỉ khối ngọc thô hoặc làm tính từ chỉ sự giản dị, chân thật. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羹', '{"9000": "3898.0", "Chữ Trung Quốc": "羹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 19 | nét | 羹 | canh | tượng hình | món canh, súp | 羹 là chữ hội ý hoặc chỉ sự kết hợp: phần trên 羔 (cao — con dê non, thịt) + phần dưới 美 (mỹ — ngon). Hai thành phần cùng gợi ý về món ăn ngon làm từ thịt. Cấu tạo chi tiết không rõ từ Wiktionary; chưa có phân tích hình thanh đầy đủ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"canh\": thịt dê (羔) ngon lành (美) nấu thành món canh bổ dưỡng — 羹 là canh đặc kiểu cổ điển. | Gương Hán-Việt | canh trong 羹汤 (canh thang — canh, súp) | Mở khoá kiến thức | Biết 羹 (canh) giúp đọc 羹汤 (canh), 菜羹 (canh rau), và các tên món ăn Trung Hoa cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary chỉ ghi {{Han etym}} mà không cung cấp phân tích cụ thể. Từ hình dạng chữ: phần trên gợi nhớ 羔 (thịt dê) và 美 (ngon). Tiểu triện còn lưu. Nghĩa gốc là món canh thịt, súp đặc. Hiện dùng rộng cho các loại canh ăn kèm cơm. Chưa có nguồn học thuật về gốc tự dạng chính xác. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "canh (ăn cơm)", "Hạng Tần Suất (Jun Da)": "3898.0", "Tần Suất % (Jun Da)": "99.7127723725", "GavinGrover_Once (Chiết tự trực tiếp)": "羔 + 美", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羔美", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "美", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羔", "Unihan_Simplified (Chữ Giản thể)": "羹", "Unihan_Traditional (Chữ Phồn thể)": "羹", "Pinyin_Xie": "gēng", "Âm Hán Việt_Xie": "canh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ các món canh sệt hoặc cháo loãng trong ẩm thực truyền thống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缄', '{"9000": "3899.0", "Chữ Trung Quốc": "缄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 12 | nét | 缄 | giam | tượng hình | phong bì, niêm phong, im lặng | 缄 là dạng giản thể của 緘. Dạng phồn thể 緘 gồm bộ 糸 (mịch — tơ sợi, biểu nghĩa) + 咸 (hàm — biểu âm); chữ hình thanh. Bộ tơ gợi hành động buộc, niêm phong, 咸 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giam\": sợi tơ (糸) buộc kín miệng bao — 缄口不言 là thành ngữ về người ngậm tăm không nói. | Gương Hán-Việt | giam trong 缄默 (giam mặc — im lặng, ngậm miệng) | Mở khoá kiến thức | Biết 缄 (giam) giúp đọc 缄口不言 (ngậm miệng), 缄默 (im lặng), 三缄其口 (ba lần niêm miệng).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Dạng phồn thể 緘 là chữ hình thanh: bộ 糸 biểu nghĩa buộc, trói bằng sợi, 咸 biểu âm. Kim văn, tiểu triện và lục thư thông còn lưu. Nghĩa gốc là niêm phong, đóng kín. Mở rộng sang im lặng (缄口不言 — ngậm miệng không nói). Trong cổ văn còn dùng chỉ thư tín. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "phong, bịt, ngậm", "Hạng Tần Suất (Jun Da)": "3899.0", "Tần Suất % (Jun Da)": "99.7130943296", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 咸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟咸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缄", "Unihan_Traditional (Chữ Phồn thể)": "椷", "Pinyin_Xie": "jiān", "Âm Hán Việt_Xie": "giam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động niêm phong thư từ hoặc giữ im lặng không nói. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('晾', '{"9000": "3900.0", "Chữ Trung Quốc": "晾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 12 | nét | 日 | nhật | biểu nghĩa | mặt trời | 京 | kinh | biểu âm | kinh đô | 晾 = 日 (Nhật, biểu nghĩa: mặt trời) + 京 (Kinh, biểu âm). Wiktionary không có glyphOrigin. Cấu trúc phono-semantic suy từ IDS: 日 gợi dùng nắng/gió để làm khô, 京 gợi âm liàng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lượng\": đưa ra dưới mặt trời (日) của kinh đô (京) cho khô — phơi, hong khô. | Gương Hán-Việt | \"lượng\" ít dùng độc lập; 晾 gặp trong 晾干 (phơi khô), 晾衣服 (phơi quần áo) | Mở khoá kiến thức | Biết 晾 mở khoá 晾干 (phơi khô), 晾衣架 (giá phơi quần áo), 晒晾 (phơi nắng).", "Tự nguyên_Xie": "Chữ 晾 (lượng) không có glyphOrigin trong Wiktionary — chữ tạo muộn. Cấu trúc ⿰日京: bộ 日 (Nhật — mặt trời) biểu nghĩa gợi phơi nắng; 京 (Kinh) biểu âm liàng. Nghĩa: phơi, hong khô dưới nắng hoặc gió; cũng nghĩa mở rộng là bỏ rơi người (phơi mặc cho ai đó). Chưa có nguồn học thuật xác nhận ls. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hong; phơi; hong cho khô; phơi; bỏ rơi; gạt (ra); cho ra rìa; để nguội; làm mát", "Hạng Tần Suất (Jun Da)": "3900.0", "Tần Suất % (Jun Da)": "99.71341577", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 京", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰日京", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "京", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "晾", "Unihan_Traditional (Chữ Phồn thể)": "晾", "Pinyin_Xie": "liàng", "Âm Hán Việt_Xie": "lượng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động phơi quần áo nơi râm mát hoặc để đồ ăn nguội bớt. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | liàng | / | phơi | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('俸', '{"9000": "3901.0", "Chữ Trung Quốc": "俸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 亻 | nhân | biểu nghĩa | người | 奉 | phụng | biểu âm | 俸 = 亻(Nhân, biểu nghĩa: người) + 奉 (Phụng, biểu âm); chữ hình thanh. Bộ người gợi khoản tiền dành cho người làm việc, 奉 cho âm đọc đồng thời gợi sắc thái phụng sự.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bổng\": người (亻) phụng sự (奉) nhà vua được ban bổng lộc — 俸禄 là tiền lương của quan lại thời phong kiến. | Gương Hán-Việt | bổng trong 俸禄 (bổng lộc — lương bổng quan lại) | Mở khoá kiến thức | Biết 俸 (bổng) giúp đọc 俸禄 (bổng lộc), 薪俸 (lương bổng), 月俸 (lương tháng).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 亻(人) biểu nghĩa người nhận lương, 奉 biểu âm. Nghĩa gốc là bổng lộc, lương bổng của quan lại. Hiện dùng trong 俸禄 (bổng lộc — lương quan), 薪俸 (tân bổng — lương). Chưa có nguồn học thuật về gốc tự dạng chi tiết hơn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bổng lộc", "Hạng Tần Suất (Jun Da)": "3901.0", "Tần Suất % (Jun Da)": "99.7137372104", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 奉", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻奉", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奉", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "俸", "Unihan_Traditional (Chữ Phồn thể)": "俸", "Pinyin_Xie": "fèng", "Âm Hán Việt_Xie": "bổng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ khoản tiền lương hoặc bổng lộc nhận được từ triều đình hay nhà nước. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('媲', '{"9000": "3902.0", "Chữ Trung Quốc": "媲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | người nữ | 𣬉 | biểu âm | 媲 = 女 (Nữ, biểu nghĩa: người nữ) + 𣬉 (biểu âm); chữ hình thanh. Bộ nữ gợi nguồn gốc từ phong tục hôn nhân (gả đôi, sánh đôi), 𣬉 cho âm đọc. Nghĩa gốc: gả, sánh đôi; mở rộng sang so sánh ngang bằng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bí\": người nữ (女) được sánh đôi ngang hàng — 媲美 là so sánh ngang tầm với cái đẹp. | Gương Hán-Việt | bí trong 媲美 (bí mỹ — sánh ngang vẻ đẹp) | Mở khoá kiến thức | Biết 媲 (bí) giúp đọc 媲美 (sánh kịp, không thua kém) — từ hay gặp trong văn quảng cáo.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 女 biểu nghĩa liên quan đến hôn nhân và sánh đôi, 𣬉 biểu âm. Tiểu triện còn lưu. Nghĩa gốc là gả vợ, phối đôi; nghĩa mở rộng là sánh ngang bằng, so bì (媲美 — sánh kịp vẻ đẹp). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sánh ngang cùng", "Hạng Tần Suất (Jun Da)": "3902.0", "Tần Suất % (Jun Da)": "99.7140586507", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "媲", "Unihan_Traditional (Chữ Phồn thể)": "媲", "Pinyin_Xie": "pì", "Âm Hán Việt_Xie": "bễ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ trong cấu trúc so sánh để chỉ sự ngang hàng, tương đương. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸾', '{"9000": "3903.0", "Chữ Trung Quốc": "鸾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 11 | nét | 鸾 | loan | tượng hình | chim loan, chim phượng huyền thoại | 鸾 là dạng giản thể của 鸞. Dạng phồn thể 鸞 gồm phần trên gợi âm + bộ 鳥 (điểu — chim, biểu nghĩa); chữ hình thanh. Bộ chim gợi loài chim thần thoại, phần trên cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"loan\": chim thần (鳥) bay cùng phượng — 鸾凤和鸣 là hình ảnh vợ chồng hòa thuận trong văn học Trung Hoa. | Gương Hán-Việt | loan trong 鸾凤 (loan phượng — chim loan và phượng, biểu tượng hôn nhân) | Mở khoá kiến thức | Biết 鸾 (loan) giúp đọc 鸾凤和鸣 (loan phượng hòa minh), 鸾镜 (gương loan), văn thơ cổ điển.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Dạng phồn thể 鸞 là chữ hình thanh với bộ 鳥 biểu nghĩa chim. Tiểu triện và lục thư thông còn lưu. 鸾 là loài chim thần thoại họ hàng với phượng hoàng (凤凰), tượng trưng cho vẻ đẹp, sự linh thiêng và hạnh phúc vợ chồng. Cũng dùng chỉ chuông nhỏ trên hàm thiết bị ngựa hoàng gia. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim phượng cái; cái chuông nhỏ", "Hạng Tần Suất (Jun Da)": "3903.0", "Tần Suất % (Jun Da)": "99.7143800911", "GavinGrover_Once (Chiết tự trực tiếp)": "亦 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱亦鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸾", "Unihan_Traditional (Chữ Phồn thể)": "鸞", "Pinyin_Xie": "luán", "Âm Hán Việt_Xie": "loan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài chim thần thoại thuộc họ phượng hoàng hoặc chiếc chuông nhỏ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恿', '{"9000": "3904.0", "Chữ Trung Quốc": "恿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 甬 | dũng | biểu âm | 心 | tâm | biểu nghĩa | lòng, tâm trí | 恿 = 甬 (Dũng, biểu âm) + 心 (Tâm, biểu nghĩa: lòng); chữ hình thanh. Bộ lòng gợi cảm xúc thúc đẩy từ bên trong, 甬 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dũng\": lòng (心) thúc đẩy như dòng nước (甬 — ống dẫn) — 怂恿 là lời xúi giục làm liều. | Gương Hán-Việt | dũng trong 怂恿 (tùng dũng — xúi giục) | Mở khoá kiến thức | Biết 恿 (dũng) giúp đọc 怂恿 (xúi giục, cổ vũ làm điều không nên).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 甬 biểu âm, bộ 心 biểu nghĩa lòng người. Tiểu triện còn lưu. Nghĩa gốc là thúc giục, xúi giục ai đó làm điều gì. Chủ yếu dùng trong 怂恿 (tùng dũng — xúi giục, cổ vũ làm điều xấu). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "xúi giục, khuyên", "Hạng Tần Suất (Jun Da)": "3904.0", "Tần Suất % (Jun Da)": "99.7147010146", "GavinGrover_Once (Chiết tự trực tiếp)": "龴 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱龴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "恿", "Unihan_Traditional (Chữ Phồn thể)": "恿", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ trong các từ ghép như túng dũng hoặc cổ dũng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜿', '{"9000": "3905.0", "Chữ Trung Quốc": "蜿", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 14 | nét | 蜿 | uyển | tượng hình | uốn lượn, ngoằn ngoèo | 蜿 là chữ hình thanh với bộ 虫 (trùng — sâu bọ, biểu nghĩa) + 宛 (uyển — biểu âm). Bộ trùng gợi chuyển động uốn lượn của sâu bọ, 宛 cho âm đọc. Dùng chủ yếu trong 蜿蜒 (uyển duyên — uốn khúc ngoằn ngoèo).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"uyển\": sâu bọ (虫) uốn lượn uyển chuyển — 蜿蜒 là hình ảnh con đường hoặc dòng sông ngoằn ngoèo. | Gương Hán-Việt | uyển trong 蜿蜒 (uyển duyên — ngoằn ngoèo) | Mở khoá kiến thức | Biết 蜿 (uyển) giúp đọc 蜿蜒 (ngoằn ngoèo, uốn khúc) — tính từ thường dùng tả cảnh thiên nhiên.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 虫 biểu nghĩa loài bò sát, sâu bọ uốn lượn, 宛 biểu âm. Nghĩa gốc là bò, uốn lượn. Dùng chủ yếu trong 蜿蜒 (uyển duyên — ngoằn ngoèo, quanh co) miêu tả con đường, dòng sông, rắn bò. Chưa có nguồn học thuật chi tiết hơn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: uyển duyên 蜿蜒)", "Hạng Tần Suất (Jun Da)": "3905.0", "Tần Suất % (Jun Da)": "99.7150219382", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 宛", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫宛", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宛", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜿", "Unihan_Traditional (Chữ Phồn thể)": "蜿", "Pinyin_Xie": "wān", "Âm Hán Việt_Xie": "uyển", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng làm động từ hoặc tính từ trong từ ghép uyển diên để tả dáng uốn lượn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('犊', '{"9000": "3906.0", "Chữ Trung Quốc": "犊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 牛 | Số nét | 12 | nét | 犊 | độc | tượng hình | con nghé, bê non | 犊 là dạng giản thể của 犢. Dạng phồn thể 犢 gồm bộ 牛 (ngưu — trâu bò, biểu nghĩa) + 賣 (mại — biểu âm); chữ hình thanh. Bộ trâu bò gợi con vật còn non, 賣 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độc\": con trâu (牛) non bé nhỏ — 初生牛犊不怕虎 là hình ảnh tuổi trẻ liều lĩnh dũng cảm. | Gương Hán-Việt | độc trong 牛犊 (ngưu độc — con bê, con nghé) | Mở khoá kiến thức | Biết 犊 (độc) giúp đọc 初生牛犊不怕虎 (bê non không sợ cọp — người trẻ dũng cảm).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Dạng phồn thể 犢 là chữ hình thanh: bộ 牛 biểu nghĩa trâu bò, 賣 biểu âm. Đại triện và tiểu triện còn lưu. Nghĩa gốc là con bê, con nghé non. Thành ngữ 初生牛犊不怕虎 (bê non chưa sợ cọp) ví người trẻ dũng cảm vì chưa biết hiểm nguy. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nghé, con trâu non", "Hạng Tần Suất (Jun Da)": "3906.0", "Tần Suất % (Jun Da)": "99.715342345", "GavinGrover_Once (Chiết tự trực tiếp)": "牛 + 卖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰牛卖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "牛", "Unihan_Simplified (Chữ Giản thể)": "犊", "Unihan_Traditional (Chữ Phồn thể)": "犢", "Pinyin_Xie": "dú", "Âm Hán Việt_Xie": "độc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc kết hợp trong thành ngữ như lão ngưu liếm độc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('讷', '{"9000": "3907.0", "Chữ Trung Quốc": "讷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 6 | nét | 讷 | nột | tượng hình | nói chậm, nói ít | 讷 là dạng giản thể của 訥. Dạng phồn thể 訥 gồm bộ 言 (ngôn — lời nói, biểu nghĩa) + 内 (nội — biểu âm); chữ hình thanh. Bộ lời nói gợi cách nói năng, 内 cho âm đọc và gợi nghĩa giữ lời ở bên trong.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nột\": lời (言) giữ ở bên trong (内) — người quân tử chậm nói (讷), mau làm theo lời Khổng Tử. | Gương Hán-Việt | nột trong 木讷 (mộc nột — chất phác, ít lời) | Mở khoá kiến thức | Biết 讷 (nột) giúp đọc 木讷 (ít lời, chất phác), 讷言 (nói ít, thận trọng lời nói).", "Tự nguyên_Xie": "Tiểu triện | Dạng phồn thể 訥 là chữ hình thanh: bộ 言 biểu nghĩa lời nói, 内 biểu âm. Tiểu triện còn lưu. Nghĩa gốc là nói chậm, nói ít, từ tốn trong lời nói. Khổng Tử dạy 讷于言而敏于行 (chậm nói nhưng nhanh làm). Trái nghĩa với 辩 (hùng biện). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nói từ từ, nói thận trọng", "Hạng Tần Suất (Jun Da)": "3907.0", "Tần Suất % (Jun Da)": "99.7156627518", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 内", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠内", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "内", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "讷", "Unihan_Traditional (Chữ Phồn thể)": "訥", "Pinyin_Xie": "nè", "Âm Hán Việt_Xie": "nột", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm tính từ bổ nghĩa cho hành vi nói năng như trong từ mộc nột. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('扈', '{"9000": "3908.0", "Chữ Trung Quốc": "扈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戶 | Số nét | 11 | nét | 戸 | hộ | biểu âm | 邑 | ấp | biểu nghĩa | khu vực hành chính, thành ấp | 扈 = 戸 (Hộ, biểu âm) + 邑 (Ấp, biểu nghĩa: khu vực); chữ hình thanh. Bộ ấp gợi nghĩa đoàn tùy tùng theo hộ vệ, 戸 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hộ\": đoàn người (邑) theo hộ vệ (戸) — 跋扈 là kẻ không cần ai theo hộ vệ, tự cao tự đại. | Gương Hán-Việt | hộ trong 扈从 (hộ tòng — đoàn tùy tùng hộ vệ) | Mở khoá kiến thức | Biết 扈 (hộ) giúp đọc 扈从 (tùy tùng), 跋扈 (bá hộ — hung hăng ngang ngược).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 戸 biểu âm, bộ 邑 biểu nghĩa khu vực theo sau. Tiểu triện và lục thư thông còn lưu. Nghĩa gốc là tùy tùng, đoàn hộ tống theo sau bậc quý tộc. Nghĩa phụ: kiêu ngạo, ngang ngược (thường trong 跋扈 — bá hộ — hung hăng ngang ngược). Từ ghép: 扈从 (hộ tòng — đoàn tùy tùng). | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim hỗ (loài chim báo mùa trồng dâu)", "Hạng Tần Suất (Jun Da)": "3908.0", "Tần Suất % (Jun Da)": "99.7159831586", "GavinGrover_Once (Chiết tự trực tiếp)": "户 + 邑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴户邑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "邑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "户", "Unihan_Simplified (Chữ Giản thể)": "扈", "Unihan_Traditional (Chữ Phồn thể)": "扈", "Pinyin_Xie": "hù", "Âm Hán Việt_Xie": "hỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc đi theo bảo vệ hoặc làm danh từ chỉ đoàn tùy tùng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蜈', '{"9000": "3909.0", "Chữ Trung Quốc": "蜈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 虫 | trùng | biểu nghĩa | sâu bọ, côn trùng | 吳 | ngô | biểu âm | 蜈 = 虫 (Trùng, biểu nghĩa: sâu bọ) + 吳 (Ngô, biểu âm); chữ hình thanh. Bộ sâu bọ gợi loài chân đốt có nhiều chân, 吳 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngô\": sâu bọ (虫) mang cái tên Ngô — 蜈蚣 là con rết nhiều chân đáng sợ trong ngũ độc. | Gương Hán-Việt | ngô trong 蜈蚣 (ngô công — con rết) | Mở khoá kiến thức | Biết 蜈 (ngô) giúp đọc 蜈蚣 (con rết) trong văn bản y học cổ truyền và sách về côn trùng.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 虫 biểu nghĩa loài sâu bọ, 吳 biểu âm. Nghĩa gốc chỉ dùng trong 蜈蚣 (ngô công — con rết, con cuốn chiếu nhiều chân). Rết là loài chân đốt có độc, dùng trong Đông y làm thuốc. Trong ngũ độc (五毒) của Trung Hoa, rết là một trong năm loài. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ngô công 蜈蚣)", "Hạng Tần Suất (Jun Da)": "3909.0", "Tần Suất % (Jun Da)": "99.7163035653", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 吴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫吴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "吴", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蜈", "Unihan_Traditional (Chữ Phồn thể)": "蜈", "Pinyin_Xie": "wú", "Âm Hán Việt_Xie": "ngô", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Hầu như chỉ xuất hiện làm danh từ liên kết trong từ ghép ngô công để chỉ con rết. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('翟', '{"9000": "3910.0", "Chữ Trung Quốc": "翟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羽 | Số nét | 14 | nét | 羽 | vũ | lông vũ | 隹 | chuy | chim | 翟 = 羽 (Vũ: lông vũ) + 隹 (Chuy: chim); chữ hội ý. Lông vũ (羽) của chim (隹) kết hợp gợi ý chim trĩ có bộ lông đuôi dài sặc sỡ. Giáp cốt văn và kim văn còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"địch\": lông vũ (羽) của loài chim (隹) — 翟 là chim trĩ đuôi dài trong lễ nhạc cổ đại, cũng là họ người. | Gương Hán-Việt | địch trong họ 翟 (Địch — họ người) | Mở khoá kiến thức | Biết 翟 (địch) giúp nhận ra họ người Địch và tên chim trĩ trong văn học cổ điển.", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Chữ hội ý: 羽 (lông vũ) + 隹 (chim) kết hợp tạo thành hình ảnh chim có bộ lông đuôi dài. Giáp cốt văn và kim văn còn lưu, cho thấy chữ rất cổ. Nghĩa gốc là chim trĩ (pheasant) có đuôi dài đẹp. Sau dùng làm họ người (họ Địch) và địa danh cổ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1396.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Vũ (124) Truy (034)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Vũ (số 124 - lông chim/ 羽) ở trên bộ Truy (số 034 - con chim/ 隹). Giải thích sự chuyển ý: Đây là chữ Hội ý. Địch là cái lông đuôi rất dài của con chim trĩ. Nó cũng được dùng làm một họ của người (họ Địch).", "Nghĩa Tiếng Việt_Xie": "lông đuôi chim trĩ", "Hạng Tần Suất (Jun Da)": "3910.0", "Tần Suất % (Jun Da)": "99.7166234553", "GavinGrover_Once (Chiết tự trực tiếp)": "羽 + 隹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羽隹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "隹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "羽", "Unihan_Simplified (Chữ Giản thể)": "翟", "Unihan_Traditional (Chữ Phồn thể)": "翟", "Pinyin_Xie": "dí", "Âm Hán Việt_Xie": "địch, trạch", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ chỉ loài chim trĩ hoặc dùng làm họ của người. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('藕', '{"9000": "3911.0", "Chữ Trung Quốc": "藕", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 18 | nét | 艸 | tháo | biểu nghĩa | cây cỏ, thực vật | 耦 | ngẫu | biểu âm | 藕 = 艸 (Tháo, biểu nghĩa: thực vật) + 耦 (Ngẫu, biểu âm); chữ hình thanh. Bộ thực vật gợi nguồn gốc từ cây sen, 耦 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngó\": cây sen (艸) có ngó (耦 — ghép đôi) — 藕断丝连 ví tình duyên đứt mà lòng chưa dứt. | Gương Hán-Việt | ngó trong 莲藕 (liên ngó — ngó sen) | Mở khoá kiến thức | Biết 藕 (ngó) giúp đọc 莲藕 (ngó sen), 藕断丝连 (tình cảm dứt không đành).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 艸 biểu nghĩa thực vật, 耦 biểu âm. Nghĩa gốc là ngó sen (phần thân rễ dưới nước của cây sen). Ngó sen có nhiều lỗ thông nhau, gợi hình ảnh liên kết (ngẫu). Từ ghép: 藕断丝连 (ngó sen đứt nhưng tơ vẫn nối — tình cảm dứt không đành). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngó sen", "Hạng Tần Suất (Jun Da)": "3911.0", "Tần Suất % (Jun Da)": "99.7169433453", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 耦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹耦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "藕", "Unihan_Traditional (Chữ Phồn thể)": "藕", "Pinyin_Xie": "ǒu", "Âm Hán Việt_Xie": "ngẫu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ bộ phận của cây sen, thường làm tân ngữ hoặc kết hợp trong từ ghép. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('戌', '{"9000": "3912.0", "Chữ Trung Quốc": "戌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 戈 | Số nét | 6 | nét | 戌 | tuất | tượng hình | hình vẽ cây búa hoặc kích | 戌 là chữ tượng hình mô phỏng hình dạng cây búa hoặc cây kích, tương tự 戊 và 戈. Không có cấu trúc hình thanh hay hội ý. Được dùng làm địa chi thứ 11, ứng với giờ Tuất (19-21h) và con chó (犬).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tuất\": hình vũ khí (kích 戈) được mượn làm địa chi thứ 11 — Tuất là năm con Chó, giờ 19-21h. | Gương Hán-Việt | tuất trong 戌时 (tuất thời — giờ Tuất, 19-21h) | Mở khoá kiến thức | Biết 戌 (tuất) giúp đọc can chi: 戊戌 (Mậu Tuất), 庚戌 (Canh Tuất), 戌时 (giờ Tuất).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Theo Wiktionary, 戌 là chữ tượng hình mô phỏng cây búa hoặc kích, gần với 戊 và 戈. Kim văn và tiểu triện còn lưu. Nghĩa gốc là vũ khí; nghĩa hiện dùng: địa chi thứ 11 trong hệ thập nhị địa chi, ứng với giờ Tuất (19-21h), năm Tuất (Canh Tuất, Nhâm Tuất,...) và con chó. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "991.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mậu (936) Nhất (001)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Nét Nhất (số 001) nằm ngang ở trong chữ Mậu (số 936 - vũ khí). Giải thích sự chuyển ý: Đây là chữ Chỉ sự. Tuất là tên một địa chi (chi Tuất, giờ Tuất).", "Nghĩa Tiếng Việt_Xie": "Tuất (ngôi thứ 11 hàng Chi)", "Hạng Tần Suất (Jun Da)": "3912.0", "Tần Suất % (Jun Da)": "99.7172632353", "GavinGrover_Once (Chiết tự trực tiếp)": "戊 + 一", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴戊一", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "一", "Unihan_Simplified (Chữ Giản thể)": "戌", "Unihan_Traditional (Chữ Phồn thể)": "戌", "Pinyin_Xie": "xū", "Âm Hán Việt_Xie": "tuất", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ thời gian như giờ Tuất, năm Tuất trong hệ thống lịch Can Chi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蓓', '{"9000": "3913.0", "Chữ Trung Quốc": "蓓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 13 | nét | 蓓 | bụi | tượng hình | nụ hoa | 蓓 là chữ hình thanh với bộ 艸 (tháo — thực vật, biểu nghĩa) + 倍 lược thể (biểu âm). Bộ thực vật gợi nguồn gốc từ cây cỏ, phần biểu âm cho âm đọc. Dùng chủ yếu trong 蓓蕾 (nụ hoa chưa nở).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bụi\": chồi cây (艸) đang khép (倍 — gấp đôi, ủ kín) — 蓓蕾 là nụ hoa còn e ấp chưa nở. | Gương Hán-Việt | bụi trong 蓓蕾 (bụi lỗi — nụ hoa) | Mở khoá kiến thức | Biết 蓓 (bụi) giúp đọc 蓓蕾 (nụ hoa), 蓓蕾初开 (nụ hoa vừa hé nở).", "Tự nguyên_Xie": "Wiktionary chỉ ghi nhận 蓓 dùng trong 蓓蕾 mà không cung cấp phân tích cấu tạo chi tiết. Bộ 艸 gợi nguồn gốc thực vật. Nghĩa gốc là nụ hoa chưa nở — trạng thái hoa còn đang ủ trong vỏ. Dùng ẩn dụ cho tài năng chưa phát triển. Chưa có nguồn học thuật về gốc tự dạng. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nụ hoa", "Hạng Tần Suất (Jun Da)": "3913.0", "Tần Suất % (Jun Da)": "99.7175831253", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 倍", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹倍", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "倍", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蓓", "Unihan_Traditional (Chữ Phồn thể)": "蓓", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bội", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ ghép với lôi thành bội lôi để chỉ nụ hoa chưa nở. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鋆', '{"9000": "3914.0", "Chữ Trung Quốc": "鋆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 15 | nét | 鋆 | quân | tượng hình | vàng, dùng đặt tên | 鋆 là chữ gồm bộ 金 (kim — vàng/kim loại, biểu nghĩa) + phần biểu âm không rõ. Cấu tạo chi tiết không có trong Wiktionary vì đây là chữ hiếm, chủ yếu dùng đặt tên người. Chưa có nguồn học thuật về gốc tự dạng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quân\": bộ vàng (金) mang âm quân — chữ hiếm dùng trong tên người với ý nghĩa quý giá như vàng. | Gương Hán-Việt | quân trong tên người chứa 鋆 (quân — vàng) | Mở khoá kiến thức | Biết 鋆 (quân) giúp nhận ra chữ này khi gặp trong tên người Trung Quốc.", "Tự nguyên_Xie": "鋆 là chữ rất hiếm, không có trang Wiktionary riêng. Bộ 金 gợi liên quan đến vàng hoặc kim loại quý. Dùng chủ yếu trong tên người vì mang nghĩa vàng, quý giá. Chưa có nguồn học thuật rõ ràng. Chữ tạo muộn, chưa thấy trong giáp cốt/kim văn. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vàng", "Hạng Tần Suất (Jun Da)": "3914.0", "Tần Suất % (Jun Da)": "99.7179030153", "GavinGrover_Once (Chiết tự trực tiếp)": "均 + 金", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱均金", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "均", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "金", "Unihan_Simplified (Chữ Giản thể)": "鋆", "Unihan_Traditional (Chữ Phồn thể)": "鋆", "Pinyin_Xie": "yún", "Âm Hán Việt_Xie": "quân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chủ yếu dùng làm danh từ trong tên người hoặc trong văn bản cổ để chỉ vàng ròng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谩', '{"9000": "3915.0", "Chữ Trung Quốc": "谩", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 13 | nét | 谩 | mạn | tượng hình | lừa dối, khinh mạn | 谩 là dạng giản thể của 謾. Dạng phồn thể 謾 gồm bộ 言 (ngôn — lời nói, biểu nghĩa) + 曼 (mạn — biểu âm); chữ hình thanh. Bộ lời nói gợi hành vi lừa dối bằng ngôn ngữ, 曼 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mạn\": lời nói (言) kéo dài buông thả (曼 — mạn, kéo dài) thành lời chửi bới — 谩骂 là nguyền rủa thô lỗ. | Gương Hán-Việt | mạn trong 谩骂 (mạn mạ — chửi bới) | Mở khoá kiến thức | Biết 谩 (mạn) giúp đọc 谩骂 (chửi bới), 欺谩 (lừa dối khinh thường).", "Tự nguyên_Xie": "Tiểu triện | Dạng phồn thể 謾 là chữ hình thanh: bộ 言 biểu nghĩa lời nói, 曼 biểu âm. Tiểu triện còn lưu. Hai âm đọc: mán (lừa dối, sỉ nhục) và màn (kiêu ngạo, thô lỗ). Từ ghép: 谩骂 (mạn mạ — chửi bới, nguyền rủa), 欺谩 (khi mạn — lừa dối khinh thường). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "coi thường", "Hạng Tần Suất (Jun Da)": "3915.0", "Tần Suất % (Jun Da)": "99.7182223885", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 曼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠曼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谩", "Unihan_Traditional (Chữ Phồn thể)": "謾", "Pinyin_Xie": "mán", "Âm Hán Việt_Xie": "mạn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Phó từ | 副词 | Thường làm động từ chỉ hành vi lừa dối hoặc phó từ bổ nghĩa cho hành động nói năng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谀', '{"9000": "3916.0", "Chữ Trung Quốc": "谀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 10 | nét | 谀 | du | tượng hình | nịnh hót, ton hót | 谀 là dạng giản thể của 諛. Dạng phồn thể 諛 gồm bộ 言 (ngôn — lời nói, biểu nghĩa) + 臾 (dư — biểu âm); chữ hình thanh. Bộ lời nói gợi hành vi nịnh hót bằng lời, 臾 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"du\": lời nói (言) ngọt ngào thái quá (臾) để nịnh bợ — 阿谀奉承 là kẻ ton hót nịnh bợ điển hình. | Gương Hán-Việt | du trong 谄谀 (siểm du — ton hót nịnh bợ) | Mở khoá kiến thức | Biết 谀 (du) giúp đọc 阿谀 (a du — nịnh hót), 谀词 (lời khen giả dối).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Dạng phồn thể 諛 là chữ hình thanh: bộ 言 biểu nghĩa lời nói, 臾 biểu âm. Tiểu triện và lục thư thông còn lưu. Nghĩa gốc là nịnh hót, ton hót bằng lời. Từ ghép: 谄谀 (siểm du — nịnh hót), 阿谀奉承 (a du phụng thừa — ton hót nịnh bợ). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nịnh hót", "Hạng Tần Suất (Jun Da)": "3916.0", "Tần Suất % (Jun Da)": "99.7185417618", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 臾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠臾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "臾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谀", "Unihan_Traditional (Chữ Phồn thể)": "諛", "Pinyin_Xie": "yú", "Âm Hán Việt_Xie": "du", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng làm động từ trong văn viết cổ hoặc kết hợp thành từ ghép như a du. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('卯', '{"9000": "3917.0", "Chữ Trung Quốc": "卯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 卩 | Số nét | 5 | nét | 卯 | mão | tượng hình | cặp đôi dao, sau dùng làm địa chi | 卯 là chữ tượng hình, mô phỏng cặp dao dùng để mổ thịt tế lễ, gần giống với 門 (cửa) nhưng khác. Không có cấu trúc hình thanh hay hội ý. Được mượn dùng làm địa chi thứ 4, ứng với giờ Mão (5-7h sáng) và con Mèo/Thỏ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mão\": hình dao chẻ đôi được mượn làm địa chi thứ 4 — Mão là năm con Mèo, giờ 5-7h sáng. | Gương Hán-Việt | mão trong 卯时 (mão thời — giờ Mão, 5-7h sáng) | Mở khoá kiến thức | Biết 卯 (mão) giúp đọc can chi: 丁卯 (Đinh Mão), 癸卯 (Quý Mão), 卯时 (giờ Mão).", "Tự nguyên_Xie": "Giáp cốt văn | Kim văn | Bạch thư | Tiểu triện | Theo Wiktionary, 卯 là tượng hình mô phỏng cặp dao để mổ thịt tế lễ thời Thương (Shang dynasty). Giáp cốt văn còn lưu hình ảnh con người hoặc thú bị chẻ đôi trong lễ tế. Kim văn, bạch thư và tiểu triện đều còn lưu. Nghĩa gốc chìm vào quên lãng; hiện dùng làm địa chi thứ 4 (Mão). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1075.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tiết (026)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Gồm hai chữ Tiết (số 026 - đốt tre, cái thẻ) đặt đối diện nhau. Hình ảnh hai cái thẻ tre ghép lại. Ngày xưa vào giờ Mão, các quan vào chầu vua phải ghép hai thẻ tre xem có khớp nhau để chứng thực thân phận. Giải thích sự chuyển ý: Đây là chữ Hội ý. Mão là tên một địa chi (chi Mão, giờ Mão - từ 5h đến 7h sáng).", "Nghĩa Tiếng Việt_Xie": "Mão (ngôi thứ 4 hàng Chi)", "Hạng Tần Suất (Jun Da)": "3917.0", "Tần Suất % (Jun Da)": "99.7188606182", "GavinGrover_Once (Chiết tự trực tiếp)": "卩", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴卩", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "卯", "Unihan_Traditional (Chữ Phồn thể)": "卯", "Pinyin_Xie": "mǎo", "Âm Hán Việt_Xie": "mão", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ chi thứ tư trong Địa chi hoặc giờ Mão trong âm lịch. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('谙', '{"9000": "3918.0", "Chữ Trung Quốc": "谙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 11 | nét | 言 | ngôn | biểu nghĩa | lời nói | 音 | âm | biểu âm | 谙 = 言 (Ngôn, biểu nghĩa: lời nói) + 音 (Âm, biểu âm); chữ hình thanh. Bộ lời nói gợi việc am hiểu sâu, 音 cho âm đọc đồng thời gợi việc học thuộc lòng (nhớ âm).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"am\": lời (言) qua âm thanh (音) ngấm sâu vào trí nhớ — 熟谙 là am hiểu thấu đáo từng chi tiết. | Gương Hán-Việt | am trong 熟谙 (thục am — am tường thành thạo) | Mở khoá kiến thức | Biết 谙 (am) giúp đọc 熟谙 (am tường), 不谙世故 (chưa am hiểu lẽ đời).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Dạng phồn thể 諳 là chữ hình thanh: bộ 言 biểu nghĩa lời nói, tri thức, 音 biểu âm. Đại triện và tiểu triện còn lưu. Nghĩa gốc là học thuộc lòng, am tường sâu sắc. Từ ghép: 熟谙 (thục am — am tường), 不谙 (bất am — không thạo). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "am tường, thấu hiểu; thành thạo", "Hạng Tần Suất (Jun Da)": "3918.0", "Tần Suất % (Jun Da)": "99.7191794746", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 音", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠音", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "音", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "谙", "Unihan_Traditional (Chữ Phồn thể)": "諳", "Pinyin_Xie": "ān", "Âm Hán Việt_Xie": "am", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường làm động từ đứng trước tân ngữ để chỉ sự thông thạo, am tường một lĩnh vực. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('岐', '{"9000": "3919.0", "Chữ Trung Quốc": "岐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 山 | Số nét | 7 | nét | 山 | sơn | biểu nghĩa | núi | 支 | chi | biểu âm | 岐 = 山 (Sơn, biểu nghĩa: núi) + 支 (Chi, biểu âm); chữ hình thanh. Bộ núi gợi địa hình cao, 支 cho âm đọc và gợi sắc thái phân nhánh (支 — nhánh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kỳ\": núi (山) có nhánh rẽ (支) — 岐山 là ngọn núi linh thiêng nơi nhà Chu phát tích, cũng là nơi có đường rẽ. | Gương Hán-Việt | kỳ trong 岐山 (Kỳ Sơn — địa danh) | Mở khoá kiến thức | Biết 岐 (kỳ) giúp đọc địa danh 岐山 (Kỳ Sơn) và nhận ra 歧 (kỳ — ngã rẽ, phân kỳ) là biến thể.", "Tự nguyên_Xie": "Đại triện | Chữ hình thanh: bộ 山 biểu nghĩa núi non, 支 biểu âm. Đại triện còn lưu. Nghĩa gốc là núi cao hoặc đường rẽ trên núi. Dùng chủ yếu làm địa danh: 岐山 (Kỳ Sơn — huyện ở Thiểm Tây, nơi khởi đầu nhà Chu). Cũng dùng làm họ người. Biến thể 歧 (kỳ — ngã rẽ) phổ biến hơn trong nghĩa đường rẽ. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "Kỳ sơn (tên một huyện ở tỉnh Thiểm Tây, Trung Quốc); đường rẽ; ngã rẽ; họ Kỳ", "Hạng Tần Suất (Jun Da)": "3919.0", "Tần Suất % (Jun Da)": "99.719498331", "GavinGrover_Once (Chiết tự trực tiếp)": "山 + 支", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰山支", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "支", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "山", "Unihan_Simplified (Chữ Giản thể)": "岐", "Unihan_Traditional (Chữ Phồn thể)": "岐", "Pinyin_Xie": "qí", "Âm Hán Việt_Xie": "kì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng làm danh từ chỉ lối rẽ hoặc tính từ chỉ sự phân nhánh, bất đồng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蝎', '{"9000": "3920.0", "Chữ Trung Quốc": "蝎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 15 | nét | 蝎 | rết | tượng hình | con bọ cạp, con hiết | 蝎 là chữ hình thanh với bộ 虫 (trùng — sâu bọ, biểu nghĩa) + 曷 (hạt — biểu âm). Bộ sâu bọ gợi loài côn trùng có độc, 曷 cho âm đọc. Tiểu triện còn lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hiết\": sâu bọ (虫) có độc mang âm hạt/hiết — 全蝎 (toàn hiết) là vị thuốc Đông y làm từ bọ cạp. | Gương Hán-Việt | rết trong 蝎子 (rết tử — con bọ cạp) | Mở khoá kiến thức | Biết 蝎 (rết) giúp đọc 蝎子 (bọ cạp), 全蝎 (bọ cạp dùng làm thuốc Đông y).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 虫 biểu nghĩa loài sâu bọ, 曷 biểu âm. Tiểu triện còn lưu. Nghĩa gốc là con bọ cạp (hoặc con rết theo một số nguồn). Trong ngũ độc (五毒) của Trung Hoa, bọ cạp là một trong năm loài độc gồm rắn, rết, bọ cạp, thằn lằn, cóc. Dùng trong Đông y. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con hiết, con bọ cạp", "Hạng Tần Suất (Jun Da)": "3920.0", "Tần Suất % (Jun Da)": "99.7198166707", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 曷", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫曷", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "曷", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蝎", "Unihan_Traditional (Chữ Phồn thể)": "蝎", "Pinyin_Xie": "xiē", "Âm Hán Việt_Xie": "hiết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ để chỉ con bọ cạp, hay đi kèm trong từ ghép chỉ côn trùng độc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荼', '{"9000": "3921.0", "Chữ Trung Quốc": "荼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 10 | nét | 艸 | tháo | biểu nghĩa | cây cỏ, thực vật | 余 | dư | biểu âm | 荼 = 艸 (Tháo, biểu nghĩa: thực vật) + 余 (Dư, biểu âm); chữ hình thanh. Bộ thực vật gợi nguồn gốc cây cỏ, 余 cho âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dưa\": cây cỏ (艸) đắng thừa (余 — dư thừa) — 荼毒 là nỗi khổ đắng cay cùng cực; 如火如荼 là cảnh sôi động như lửa như bông lau. | Gương Hán-Việt | dưa trong 荼毒 (dưa độc — hại người, độc hại) | Mở khoá kiến thức | Biết 荼 (dưa) giúp đọc 荼毒 (hại người), 如火如荼 (mãnh liệt sôi nổi), 荼蘼 (tên hoa).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 艸 biểu nghĩa thực vật, 余 biểu âm. Tiểu triện còn lưu. Nghĩa gốc là loại rau đắng (có thể là cây chua me đất hoặc rau đắng thuộc họ Cúc). Nghĩa mở rộng: đau khổ (như vị đắng), và màu trắng (bông lau trắng). Thành ngữ 如火如荼 (đỏ như lửa, trắng như bông lau — sôi động mãnh liệt). Cũng là dạng cổ của 茶 (trà). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rau đồ (một loại rau đắng); một thứ cỏ có hoa trắng như bông lau; hại", "Hạng Tần Suất (Jun Da)": "3921.0", "Tần Suất % (Jun Da)": "99.7201350103", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 余", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹余", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "余", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荼", "Unihan_Traditional (Chữ Phồn thể)": "荼", "Pinyin_Xie": "tú", "Âm Hán Việt_Xie": "đồ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường dùng trong văn cổ làm danh từ chỉ rau đắng hoặc tính từ chỉ sự khổ cực, tàn hại. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('镀', '{"9000": "3922.0", "Chữ Trung Quốc": "镀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 金 | kim | biểu nghĩa | kim loại | 度 | độ | biểu âm | đo lường, mức độ | 镀 = 金 (Kim, biểu nghĩa: kim loại) + 度 (Độ, biểu âm); chữ hình thanh. Bộ 金 chỉ vật liệu kim loại, 度 cho âm đọc gần với dù.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"độ\" (lớp mạ): tưởng tượng đo đúng một lớp vàng mỏng (金) phủ lên vật — đó là mạ (镀). | Gương Hán-Việt | độ — chữ 镀 xuất hiện trong 电镀 (điện độ: mạ điện) | Mở khoá kiến thức | Biết 镀 mở khoá: 电镀 (mạ điện), 镀金 (mạ vàng), 镀银 (mạ bạc).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 金 (kim loại) biểu nghĩa, 度 biểu âm. Nghĩa gốc là phủ một lớp kim loại mỏng lên bề mặt vật khác — tức mạ điện, mạ vàng. Dạng phồn thể 鍍 giữ nguyên cấu trúc này. Chưa có nguồn giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mạ kim loại", "Hạng Tần Suất (Jun Da)": "3922.0", "Tần Suất % (Jun Da)": "99.7204528332", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 度", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅度", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "度", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "镀", "Unihan_Traditional (Chữ Phồn thể)": "鍍", "Pinyin_Xie": "dù", "Âm Hán Việt_Xie": "độ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ kim loại để biểu thị việc mạ một lớp bên ngoài. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('椰', '{"9000": "3923.0", "Chữ Trung Quốc": "椰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 12 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 耶 | gia | biểu âm | thán từ, trợ từ | 椰 = 木 (Mộc, biểu nghĩa: cây) + 耶 (Gia, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là một loài cây, 耶 cho âm gần với yē.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"da\" (dừa): bộ 木 (cây) + 耶 (gia — âm la lên như tiếng kêu ngạc nhiên) — cây dừa 椰 cao vút khiến ai nhìn cũng phải thốt lên 耶! | Gương Hán-Việt | da — chữ 椰 xuất hiện trong 椰子 (da tử: quả dừa) | Mở khoá kiến thức | Biết 椰 mở khoá: 椰子 (dừa), 椰汁 (nước dừa), 椰树 (cây dừa).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 木 (cây) biểu nghĩa, 耶 biểu âm. Nghĩa là cây dừa (椰子). Không có dạng giáp cốt hay kim văn — đây là chữ tạo muộn để ghi tên loài cây nhiệt đới du nhập từ phương Nam. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây dừa, quả dừa", "Hạng Tần Suất (Jun Da)": "3923.0", "Tần Suất % (Jun Da)": "99.720770656", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 耶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木耶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "耶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "椰", "Unihan_Traditional (Chữ Phồn thể)": "椰", "Pinyin_Xie": "yē", "Âm Hán Việt_Xie": "gia", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng trước các từ chỉ bộ phận của cây dừa như da tử, da du. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('甄', '{"9000": "3924.0", "Chữ Trung Quốc": "甄", "Bộ thủ & thành phần_Xie": "Bộ thủ | 瓦 | Số nét | 13 | nét | 垔 | biểu âm | thành phần biểu âm, ít dùng độc lập | 瓦 | ngoã | biểu nghĩa | ngói, đồ gốm | 甄 = 垔 (biểu âm) + 瓦 (Ngoã, biểu nghĩa: đồ gốm); chữ hình thanh. Bộ 瓦 chỉ liên quan đến gốm sứ, 垔 cho âm gần với zhēn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chân\" (xem xét): bộ 瓦 (gốm) — thợ gốm (瓦) luôn phải xem xét từng sản phẩm kỹ càng — 甄 nghĩa là soi xét, chân thực. | Gương Hán-Việt | chân — 甄 xuất hiện trong 甄别 (chân biệt: phân biệt kỹ lưỡng) | Mở khoá kiến thức | Biết 甄 mở khoá: 甄别 (phân biệt kỹ lưỡng), 甄选 (tuyển chọn), 甄陶 (đào tạo).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 瓦 (đồ gốm) biểu nghĩa, 垔 biểu âm. Nghĩa gốc là làm đồ gốm trên bàn xoay — từ đó mở rộng sang nghĩa xem xét, soi xét (như thợ gốm kiểm tra sản phẩm). Dạng tiểu triện còn lưu hình dáng. Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thợ gốm; soi xét, phân biệt; nêu tỏ; sáng", "Hạng Tần Suất (Jun Da)": "3924.0", "Tần Suất % (Jun Da)": "99.7210884789", "GavinGrover_Once (Chiết tự trực tiếp)": "垔 + 瓦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰垔瓦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "垔", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "瓦", "Unihan_Simplified (Chữ Giản thể)": "甄", "Unihan_Traditional (Chữ Phồn thể)": "甄", "Pinyin_Xie": "zhēn", "Âm Hán Việt_Xie": "chân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ trong văn viết với nghĩa tuyển chọn, phân biệt tài năng của con người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蟾', '{"9000": "3925.0", "Chữ Trung Quốc": "蟾", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 19 | nét | 蟾 | thiềm | tượng hình | con cóc; trong thơ cổ chỉ mặt trăng | 蟾 không có phân tích hình-thanh hay hội-ý từ nguồn Wiktionary có cấu trúc. Chữ thuộc bộ 虫. Cấu trúc chính xác chưa được xác nhận; chữ tự thân đại diện cho con cóc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiềm\" (cóc): 蟾蜍 (thiềm thừ) là con cóc sống trên cung trăng trong thần thoại — 蟾 vừa là cóc, vừa là biểu tượng mặt trăng trong thơ cổ. | Gương Hán-Việt | thiềm — xuất hiện trong 蟾蜍 (thiềm thừ: con cóc) | Mở khoá kiến thức | Biết 蟾 mở khoá: 蟾蜍 (con cóc), 蟾宫 (cung trăng trong thơ cổ), 金蟾 (cóc vàng — biểu tượng tài lộc).", "Tự nguyên_Xie": "Không có nguồn phân tích cấu trúc học thuật rõ ràng cho 蟾. Chữ dùng trong 蟾蜍 (thiềm thừ — con cóc), và trong thơ ca cổ 蟾 còn chỉ mặt trăng (theo tích con cóc sống trên cung trăng). Chưa có nguồn học thuật xác nhận cấu trúc hình-thanh. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thiềm thừ 蟾蜍)", "Hạng Tần Suất (Jun Da)": "3925.0", "Tần Suất % (Jun Da)": "99.7214063018", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 詹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫詹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "詹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蟾", "Unihan_Traditional (Chữ Phồn thể)": "蟾", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "thiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong văn học cổ để chỉ con cóc hoặc ẩn dụ cho mặt trăng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹊', '{"9000": "3926.0", "Chữ Trung Quốc": "蹊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 17 | nét | 蹊 | khê | tượng hình | lối đi mòn — cấu trúc nội bộ không xác nhận được từ nguồn học thuật | 蹊 không có phân tích hình-thanh từ Wiktionary có cấu trúc rõ ràng. Chữ chứa bộ 足 (chân), gợi liên quan đến việc đi lại, tạo lối đường. Chưa xác nhận được cấu trúc cụ thể.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khê\" (lối mòn): đôi chân (足) giẫm mãi thành con đường mòn 蹊 xuyên qua khe núi. | Gương Hán-Việt | khê — 蹊 xuất hiện trong 蹊径 (khê kính: lối đi, con đường nhỏ) | Mở khoá kiến thức | Biết 蹊 mở khoá: 蹊径 (lối đi riêng), 别开蹊径 (khai phá đường mới), 蹊蹺 (kỳ lạ, đáng ngờ).", "Tự nguyên_Xie": "Không có nguồn Wiktionary phân tích cấu trúc 蹊 rõ ràng. Chữ thuộc bộ 足 (chân). 蹊 có hai âm đọc: xī (lối mòn, dẫm lên) và qī (dùng trong 蹊蹺 — kỳ lạ, đáng ngờ). Chưa có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lối người đi, lối đi; đi tắt qua", "Hạng Tần Suất (Jun Da)": "3926.0", "Tần Suất % (Jun Da)": "99.7217241246", "GavinGrover_Once (Chiết tự trực tiếp)": "⻊ + 奚", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰⻊奚", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "奚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⻊", "Unihan_Simplified (Chữ Giản thể)": "蹊", "Unihan_Traditional (Chữ Phồn thể)": "蹊", "Pinyin_Xie": "qī", "Âm Hán Việt_Xie": "hề", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ lối đi nhỏ ở chân núi hoặc động từ chỉ việc đi tắt qua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('泞', '{"9000": "3927.0", "Chữ Trung Quốc": "泞", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 8 | nét | 泞 | nính | tượng hình | bùn lầy — cấu trúc nội bộ không xác nhận được từ nguồn học thuật | 泞 thuộc bộ 水 (氵 — nước). Phần còn lại chưa được Wiktionary phân tích rõ. Chữ tự thân đại diện cho khái niệm bùn lầy, nước đọng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nính\" (bùn): bộ 氵 (nước) ngấm vào đất — vũng bùn lún sụt 泞 hút cả giày người đi. | Gương Hán-Việt | nính — 泞 xuất hiện trong 泥泞 (nê nính: bùn lầy) | Mở khoá kiến thức | Biết 泞 mở khoá: 泥泞 (đường bùn lầy), 泞淖 (vũng bùn sâu).", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu trúc cho 泞/濘. Chữ thuộc bộ 氵 (nước), gợi liên quan đến nước và bùn lầy. Dạng giáp cốt văn và tiểu triện còn được lưu trong nguồn hình ảnh. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bùn lầy", "Hạng Tần Suất (Jun Da)": "3927.0", "Tần Suất % (Jun Da)": "99.7220414307", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 宁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵宁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "泞", "Unihan_Traditional (Chữ Phồn thể)": "濘", "Pinyin_Xie": "nìng", "Âm Hán Việt_Xie": "ninh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Thường làm tính từ miêu tả đường sá lầy lội sau cơn mưa hoặc ghép thành danh từ chỉ bùn đất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('撸', '{"9000": "3928.0", "Chữ Trung Quốc": "撸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 15 | nét | 扌 | biểu nghĩa | tay, hành động bằng tay | 魯 | lỗ | biểu âm | thô lỗ, chậm chạp | 撸 = 扌 (biểu nghĩa: tay) + 魯 (Lỗ, biểu âm); chữ hình thanh. Bộ 扌 chỉ hành động dùng tay, 魯 cho âm lū/lǔ. Dạng phồn thể 擼 giữ nguyên cấu trúc này.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗ\" (thô): bàn tay (扌) tuốt thô (魯) dọc theo vật — 撸 nghĩa là vuốt, tuốt, hoặc cách chức một cách thô bạo. | Gương Hán-Việt | lỗ — 撸 xuất hiện trong 撸起袖子 (xắn tay áo — ý nghĩa bóng: xắn tay vào việc) | Mở khoá kiến thức | Biết 撸 mở khoá: 撸猫 (vuốt mèo), 撸起袖子 (xắn tay áo), 撸铁 (tập tạ).", "Tự nguyên_Xie": "Kim văn | Chữ hình thanh: bộ 扌 (tay) biểu nghĩa, 魯 biểu âm. Nghĩa gốc là di chuyển, vuốt dọc bằng tay. Từ đó phái sinh: tuốt tay dọc theo vật (撸起袖子 — xắn tay áo), cách chức (撸掉职务), và trong tiếng lóng hiện đại: vuốt ve mèo (撸猫). Kim văn của dạng phồn thể còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "lột; bóc; tuốt ra; truất; phế; cách (chức vụ); trách mắng; răn dạy; trách; trỏ; như \"chỉ trỏ\" (vhn) lỗ; như \"lỗ lược (cướp bóc)\" (btcn) nhổ; như \"nhổ mạ\" (btcn) trổ; như \"trổ tường (đào khoét)\" (btcn) trỗ; như \"lúa trỗ\" (btcn) chỏ; như \"chỉ chỏ\" (gdhn) dổ; như \"dổ cỏ (nhổ cỏ); dổ răng (nhổ răng)\" (gdhn) rổ; như \"rổ cây (nhổ cây)\" (gdhn)", "Hạng Tần Suất (Jun Da)": "3928.0", "Tần Suất % (Jun Da)": "99.7223587368", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 鲁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌鲁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鲁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "撸", "Unihan_Traditional (Chữ Phồn thể)": "擼", "Pinyin_Xie": "lū", "Âm Hán Việt_Xie": "lỗ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước danh từ để chỉ hành động vuốt, tuốt hoặc thu vén. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('螃', '{"9000": "3929.0", "Chữ Trung Quốc": "螃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 16 | nét | 螃 | bàng | tượng hình | con cua — cấu trúc nội bộ không xác nhận được từ Wiktionary | 螃 không có phân tích cấu trúc từ Wiktionary ({{Han etym}} rỗng). Chữ thuộc bộ 虫, phần còn lại liên quan đến âm đọc páng/bàng. Chưa xác nhận được cấu trúc học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bàng\" (cua): con cua 螃 đi ngang bàng bạo — 螃蟹 (bàng giải) là cái tên hai chữ cố định chỉ con cua. | Gương Hán-Việt | bàng — 螃 xuất hiện trong 螃蟹 (bàng giải: con cua) | Mở khoá kiến thức | Biết 螃 mở khoá: 螃蟹 (con cua), 螃蜞 (cua nhỏ ven biển).", "Tự nguyên_Xie": "Wiktionary không cung cấp phân tích cấu trúc cho 螃. Chữ dùng trong 螃蟹 (bàng giải — con cua) và 螃蜞 (một loài cua nhỏ). Bộ 虫 chỉ liên quan đến sinh vật nhỏ bé. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bàng kỳ 螃蜞)", "Hạng Tần Suất (Jun Da)": "3929.0", "Tần Suất % (Jun Da)": "99.7226760428", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 旁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫旁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "旁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "螃", "Unihan_Traditional (Chữ Phồn thể)": "螃", "Pinyin_Xie": "páng", "Âm Hán Việt_Xie": "bàng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này thường làm danh từ liên kết trong các từ ghép chỉ các loài cua. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('檬', '{"9000": "3930.0", "Chữ Trung Quốc": "檬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 17 | nét | 木 | mộc | biểu nghĩa | cây, gỗ | 蒙 | mông | biểu âm | che phủ, mờ tối | 檬 = 木 (Mộc, biểu nghĩa: cây) + 蒙 (Mông, biểu âm); chữ hình thanh. Bộ 木 chỉ đây là một loài cây, 蒙 cho âm méng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"mông\" (mờ): cây (木) có hương thơm mờ ảo như sương mông (蒙) — đó là cây chanh 檬 trong 柠檬. | Gương Hán-Việt | mông — 檬 xuất hiện trong 柠檬 (nình mông: quả chanh vàng) | Mở khoá kiến thức | Biết 檬 mở khoá: 柠檬 (chanh vàng), 柠檬水 (nước chanh), 柠檬茶 (trà chanh).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 木 (cây) biểu nghĩa, 蒙 biểu âm. 檬 dùng chủ yếu trong 柠檬 (nình mông — chanh vàng). Chữ tạo muộn để phiên âm tên loài cây ngoại lai, không có dạng giáp cốt hay kim văn. Chưa có nguồn học thuật cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: nịnh mông)", "Hạng Tần Suất (Jun Da)": "3930.0", "Tần Suất % (Jun Da)": "99.7229928321", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 蒙", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木蒙", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "蒙", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "檬", "Unihan_Traditional (Chữ Phồn thể)": "檬", "Pinyin_Xie": "méng", "Âm Hán Việt_Xie": "mông", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường xuất hiện trong từ ghép nịnh mông để chỉ quả chanh. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('猓', '{"9000": "3931.0", "Chữ Trung Quốc": "猓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 犬 | Số nét | 11 | nét | 犬 | khuyển | biểu nghĩa | chó, thú vật | 果 | quả | biểu âm | quả, kết quả | 猓 = 犬 (Khuyển, biểu nghĩa: thú vật) + 果 (Quả, biểu âm); chữ hình thanh. Bộ 犬 chỉ đây là một loài thú, 果 cho âm guǒ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quả\" (kết quả): thú (犬) ăn quả (果) trên cây — con vượn 猓 đu cây hái quả trong rừng sâu. | Gương Hán-Việt | quả — 猓 là chữ hiếm, xuất hiện trong 猓然 (loài vượn đuôi dài trong văn cổ) | Mở khoá kiến thức | Biết 猓 mở khoá ngữ cảnh: 猓然 (loài vượn cổ), 猓玀 (tên cũ dân tộc Lô Lô trong lịch sử).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 犬 (thú) biểu nghĩa, 果 biểu âm. 猓 là chữ cổ dùng để chỉ một loài vượn đuôi dài (猓然), và từng dùng để phiên âm tên các dân tộc thiểu số (猓玀 — Lô Lô, Lahu) trong văn bản cổ. Hiện gần như chỉ xuất hiện trong tự điển. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một loài vượn màu đỏ xanh có vằn và đuôi dài", "Hạng Tần Suất (Jun Da)": "3931.0", "Tần Suất % (Jun Da)": "99.7233091046", "GavinGrover_Once (Chiết tự trực tiếp)": "犭 + 果", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰犭果", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "果", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "犭", "Unihan_Simplified (Chữ Giản thể)": "猓", "Unihan_Traditional (Chữ Phồn thể)": "猓", "Pinyin_Xie": "guǒ", "Âm Hán Việt_Xie": "quả", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ một loài vượn đuôi dài thời cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔷', '{"9000": "3932.0", "Chữ Trung Quốc": "蔷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艸 | tháu | biểu nghĩa | cỏ, cây cỏ | 牆 | tường | biểu âm | bức tường | 蔷 = 艸/艹 (Tháu, biểu nghĩa: cây cỏ) + 牆 (Tường, biểu âm, viết tắt); chữ hình thanh. Bộ 艹 chỉ đây là thực vật, 牆 cho âm qiáng. Dùng trong 薔薇 (tường vi — hoa hồng dại).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tường\" (bức tường): cây cỏ (艹) leo lên bức tường (tường — 牆) — đó là dây hoa hồng 蔷 trong 薔薇. | Gương Hán-Việt | tường — 蔷 xuất hiện trong 薔薇 (tường vi: hoa hồng dại) | Mở khoá kiến thức | Biết 蔷 mở khoá: 薔薇 (hoa hồng dại), 蔷薇科 (họ hoa hồng Rosaceae).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 艸 (cây cỏ) biểu nghĩa, 牆 (tường) biểu âm (rút gọn). Wiktionary ghi hai etymology: một với 牆 cho âm, một với 嗇 cho âm. Nghĩa gốc là cây hoa hồng dại leo tường (薔薇). Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: tường vi 薔薇)", "Hạng Tần Suất (Jun Da)": "3932.0", "Tần Suất % (Jun Da)": "99.7236248603", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 啬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹啬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "啬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔷", "Unihan_Traditional (Chữ Phồn thể)": "薔", "Pinyin_Xie": "qiáng", "Âm Hán Việt_Xie": "tường", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, chủ yếu dùng trong từ ghép tường vi để chỉ loài hoa hồng leo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('羲', '{"9000": "3933.0", "Chữ Trung Quốc": "羲", "Bộ thủ & thành phần_Xie": "Bộ thủ | 羊 | Số nét | 16 | nét | 𫤫 | biểu nghĩa | thành phần ngữ nghĩa cổ, ít thấy trong văn bản hiện đại | 義 | nghĩa | biểu âm | nghĩa lý, chính nghĩa | 羲 = 𫤫 (biểu nghĩa, thành phần cổ) + 義 (Nghĩa, biểu âm); chữ hình thanh theo nghiên cứu mới nhất (Xie Mingwen 2023). 義 cho âm xī gần với nghĩa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hi\" (hơi thở): 羲 mang tên Phục Hy (伏羲) — vị thần tổ dạy con người; âm hi như hơi thở nhẹ nhàng của trời đất. | Gương Hán-Việt | hi — 羲 xuất hiện trong 伏羲 (Phục Hi: vua huyền thoại Trung Hoa) | Mở khoá kiến thức | Biết 羲 mở khoá: 伏羲 (Phục Hi), 羲和 (Hi Hòa — thần mặt trời), 王羲之 (Vương Hi Chi — thư pháp gia nổi tiếng).", "Tự nguyên_Xie": "Kim văn | Đại triện | Theo nghiên cứu của Xie Mingwen (2023) dẫn trong Wiktionary: 羲 là chữ hình thanh gồm 𫤫 biểu nghĩa và 義 biểu âm. Chữ dùng chủ yếu như tên riêng (Phục Hy 伏羲 — hoàng đế huyền thoại), chỉ hơi thở, khí. Dạng kim văn và đại triện còn được lưu. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "họ Hi; hoàng đế Phục Hy; gas", "Hạng Tần Suất (Jun Da)": "3933.0", "Tần Suất % (Jun Da)": "99.7239406161", "GavinGrover_Once (Chiết tự trực tiếp)": "羊 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱羊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "羲", "Unihan_Traditional (Chữ Phồn thể)": "羲", "Pinyin_Xie": "xī", "Âm Hán Việt_Xie": "hy", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ, thường dùng làm tên riêng của các nhân vật huyền thoại Trung Hoa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘸', '{"9000": "3934.0", "Chữ Trung Quốc": "瘸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 16 | nét | 疒 | nạch | biểu nghĩa | bệnh tật | 加 | gia | biểu âm | thêm vào | 肉 | nhục | biểu ý phụ | thịt, thân thể | 瘸 = 疒 (Nạch, biểu nghĩa: bệnh tật) + 加 (Gia, biểu âm) + 肉 (Nhục, biểu ý phụ: thân thể). Wiktionary ghi ls=psc (hình thanh): 疒 cho nghĩa (bệnh), 加 cho âm qué, 肉 là thành phần ý nghĩa bổ sung. Chữ hình thanh.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"qua\": căn bệnh (疒) làm đôi chân thịt (肉) thêm (加) bất lực — đi cà nhắc, tật nguyền. | Gương Hán-Việt | \"qua\" ít dùng độc lập trong tiếng Việt; 瘸 gặp trong 瘸子 (người đi cà nhắc), 一瘸一拐 (đi khập khiễng) | Mở khoá kiến thức | Biết 瘸 mở khoá 瘸子 (người tật nguyền chân), 一瘸一拐 (đi khập khiễng), 瘸腿 (chân khập khiễng).", "Tự nguyên_Xie": "Chữ 瘸 (qua) là chữ hình thanh (ls=psc): bộ 疒 (Nạch — bệnh tật) biểu nghĩa; 加 (Gia) biểu âm qué; 肉 (Nhục — thịt/thân thể) là thành phần ý nghĩa bổ sung. Wiktionary xác nhận chữ cổ (mc=y, oc=y), nghĩa: bị liệt, đi cà nhắc. Thú vị là đây là một trong số ít chữ có âm -üe trong quan thoại mà không xuất phát từ âm nhập thanh (entering tone) trong tiếng Hán trung cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bệnh khoèo", "Hạng Tần Suất (Jun Da)": "3934.0", "Tần Suất % (Jun Da)": "99.7242553382", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 𦙲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒𦙲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "𦙲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘸", "Unihan_Traditional (Chữ Phồn thể)": "瘸", "Pinyin_Xie": "qué", "Âm Hán Việt_Xie": "qua", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Chữ này làm tính từ miêu tả trạng thái chân bị đi khập khiễng hoặc làm động từ chỉ việc đi thọt. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蘸', '{"9000": "3935.0", "Chữ Trung Quốc": "蘸", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 22 | nét | 蘸 | trám | tượng hình | nhúng xuống — cấu trúc nội bộ không xác nhận được từ nguồn học thuật | 蘸 không có nguồn phân tích cấu trúc học thuật. Wiktionary ghi nguồn gốc là ''Unknown.'' Chữ thuộc bộ 艹 (cây cỏ). Đây là chữ tạo muộn ghi hành động nhúng, chấm vào chất lỏng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trám\" (nhúng chấm): tay nhúng đầu bút (hay thức ăn) vào mực hay nước chấm — 蘸 là động tác chấm, nhúng nhẹ. | Gương Hán-Việt | trám — 蘸 xuất hiện trong 蘸酱 (trám tương: chấm tương) | Mở khoá kiến thức | Biết 蘸 mở khoá: 蘸酱 (chấm tương), 蘸水 (nhúng nước), 蘸墨 (chấm mực).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi ''Unknown'' cho nguồn gốc 蘸. Chữ thuộc bộ 艹, nhưng cấu trúc nội bộ không xác nhận được. Dạng tiểu triện còn được lưu trong nguồn hình ảnh. Chưa có nguồn học thuật xác nhận. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1285.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Thảo (028) Tiếu (1284)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Thảo (số 028 - cỏ/hoa/chỉ ý) ở trên chữ Tiếu (số 1284 - tế lễ/chỉ âm). Hoa dùng cúng tế phải được nhúng ngâm nước cho hết dơ bẩn. Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Tiếu chỉ âm, bộ Thảo chỉ ý. Trạm là nhúng vào nước, ngâm, chấm vào.", "Nghĩa Tiếng Việt_Xie": "nhúng xuống nước", "Hạng Tần Suất (Jun Da)": "3935.0", "Tần Suất % (Jun Da)": "99.7245700603", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 醮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹醮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "醮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蘸", "Unihan_Traditional (Chữ Phồn thể)": "蘸", "Pinyin_Xie": "zhàn", "Âm Hán Việt_Xie": "trám", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ đứng trước danh từ chỉ chất lỏng để diễn tả hành động chấm hoặc nhúng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | zhàn | / | nhúng | Xuất hiện trong lộ trình | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蔗', '{"9000": "3936.0", "Chữ Trung Quốc": "蔗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 14 | nét | 艹 | biểu nghĩa | cây cỏ | 庶 | thứ | biểu âm | thứ dân, nhiều | 蔗 = 艹 (biểu nghĩa: cây cỏ) + 庶 (Thứ, biểu âm); chữ hình thanh. Bộ 艹 chỉ đây là thực vật, 庶 cho âm zhè.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giá\" (mía): cây cỏ (艹) + thứ (庶 — thứ dân đông đúc) — mía (蔗) là cây của người thường, ngọt ngào mà bình dị. | Gương Hán-Việt | giá — 蔗 xuất hiện trong 甘蔗 (cam giá: cây mía), 蔗糖 (giá đường: đường mía) | Mở khoá kiến thức | Biết 蔗 mở khoá: 甘蔗 (cây mía), 蔗糖 (đường mía), 蔗汁 (nước mía).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 艹 (cây cỏ) biểu nghĩa, 庶 biểu âm. Nghĩa là cây mía (蔗糖 — đường mía). Dạng tiểu triện còn được lưu. Không có dạng giáp cốt — đây là chữ tạo muộn để ghi tên loài cây. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây mía", "Hạng Tần Suất (Jun Da)": "3936.0", "Tần Suất % (Jun Da)": "99.7248837489", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 庶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹庶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "庶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "蔗", "Unihan_Traditional (Chữ Phồn thể)": "蔗", "Pinyin_Xie": "zhè", "Âm Hán Việt_Xie": "giá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ cây mía, thường kết hợp với các từ khác để chỉ sản phẩm từ mía. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('傀', '{"9000": "3937.0", "Chữ Trung Quốc": "傀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 11 | nét | 亻 | biểu nghĩa | người (dạng rút gọn của 人) | 鬼 | quỷ | biểu âm | ma quỷ | 傀 = 亻 (biểu nghĩa: người) + 鬼 (Quỷ, biểu âm); chữ hình thanh. Bộ 亻 chỉ liên quan đến người, 鬼 cho âm guī. Nghĩa gốc là to lớn, kỳ dị; cũng chỉ hình nộm (傀儡 — con rối).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\" (kỳ lớn): người (亻) mang dáng quỷ (鬼) khổng lồ kỳ dị — 傀 gốc là to lớn, kỳ quái; nay phổ biến trong 傀儡 (khôi lỗi: bù nhìn). | Gương Hán-Việt | khôi — 傀 xuất hiện trong 傀儡 (khôi lỗi: bù nhìn, con rối) | Mở khoá kiến thức | Biết 傀 mở khoá: 傀儡 (bù nhìn, người bị giật dây), 傀儡政府 (chính phủ bù nhìn).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 亻 (người) biểu nghĩa, 鬼 biểu âm. Dạng tiểu triện còn được lưu. Nghĩa gốc là to lớn, kỳ dị, một mình. Mở rộng sang 傀儡 — hình nộm điều khiển bằng dây, chỉ người bị giật dây (bù nhìn). Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "quái dị; kỳ quái; một mình", "Hạng Tần Suất (Jun Da)": "3937.0", "Tần Suất % (Jun Da)": "99.7251969207", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 鬼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻鬼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "鬼", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "傀", "Unihan_Traditional (Chữ Phồn thể)": "傀", "Pinyin_Xie": "guī", "Âm Hán Việt_Xie": "khôi, quỷ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ sự to lớn, kỳ quái hoặc làm danh từ trong từ ghép khôi lỗi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蚌', '{"9000": "3938.0", "Chữ Trung Quốc": "蚌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 10 | nét | 蚌 | bạng | tượng hình | con trai, con hàu — cấu trúc nội bộ không xác nhận được từ Wiktionary | 蚌 không có phân tích cấu trúc từ Wiktionary ({{Han etym}} rỗng). Chữ thuộc bộ 虫, gợi liên quan đến sinh vật. Cấu trúc chính xác chưa được xác nhận.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bạng\" (con trai): chữ 蚌 có bộ 虫 (sinh vật) — con trai (bạng) ngậm cát tạo ngọc trai, như cái tên bạng — ngậm chặt. | Gương Hán-Việt | bạng — 蚌 xuất hiện trong 河蚌 (hà bạng: con trai sông), 蚌珠 (bạng châu: ngọc trai) | Mở khoá kiến thức | Biết 蚌 mở khoá: 河蚌 (con trai sông), 蚌壳 (vỏ trai), 蚌珠 (ngọc trai).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc cho 蚌. Chữ thuộc bộ 虫 (sinh vật). Dạng tiểu triện còn được lưu trong nguồn hình ảnh. 蚌 chỉ con trai nước ngọt, con hàu — sinh vật có vỏ hai mảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con trai", "Hạng Tần Suất (Jun Da)": "3938.0", "Tần Suất % (Jun Da)": "99.7255095757", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 丰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫丰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蚌", "Unihan_Traditional (Chữ Phồn thể)": "蚌", "Pinyin_Xie": "bàng", "Âm Hán Việt_Xie": "bạng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ loài trai sông hoặc sò hến sinh ngọc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锢', '{"9000": "3939.0", "Chữ Trung Quốc": "锢", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 13 | nét | 金 | kim | biểu nghĩa | kim loại | 固 | cố | biểu âm | cứng, bền chặt | 锢 = 金 (Kim, biểu nghĩa: kim loại) + 固 (Cố, biểu âm); chữ hình thanh. Bộ 金 chỉ vật liệu kim loại, 固 cho âm gù. Nghĩa gốc là nhét kim loại nóng chảy vào vết nứt để hàn gắn; mở rộng sang nghĩa giam cầm, cố định.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cố\" (cứng): kim loại (金) + cứng chắc (固) — 锢 là hàn kim loại chặt lại, cũng nghĩa là giam cố không thoát. | Gương Hán-Việt | cố — 锢 xuất hiện trong 禁锢 (cấm cố: giam cầm, hạn chế) | Mở khoá kiến thức | Biết 锢 mở khoá: 禁锢 (giam cầm, hạn chế tư tưởng), 锢漏 (hàn vết nứt), 党锢 (đảng cố — cổ văn: cấm đoán một phe phái).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 金 (kim loại) biểu nghĩa, 固 biểu âm. Dạng phồn thể 錮. Nghĩa gốc là đổ kim loại nóng chảy vào vết nứt để hàn kín. Từ đó mở rộng sang: giam cầm (禁錮 — cấm cố), cố định chặt. Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàn (gắn bằng kim loại)", "Hạng Tần Suất (Jun Da)": "3939.0", "Tần Suất % (Jun Da)": "99.7258222307", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 固", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅固", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "固", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锢", "Unihan_Traditional (Chữ Phồn thể)": "錮", "Pinyin_Xie": "gù", "Âm Hán Việt_Xie": "cố", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Chữ này làm động từ chỉ hành động hàn gắn kim loại hoặc giam lỏng, cấm đoán. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('遽', '{"9000": "3940.0", "Chữ Trung Quốc": "遽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 16 | nét | 辵 | biểu nghĩa | đi, chạy (bộ辶) | 豦 | biểu âm | thành phần biểu âm | 遽 = 辵/辶 (biểu nghĩa: đi, di chuyển) + 豦 (biểu âm); chữ hình thanh. Bộ 辶 chỉ hành động di chuyển, 豦 cho âm jù. Nghĩa là bất ngờ, đột ngột.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cự\" (vội): chân bước (辶) vội vã đột ngột — 遽 là bỗng nhiên, đột ngột rời đi không kịp chuẩn bị. | Gương Hán-Việt | cự — 遽 xuất hiện trong 仓遽 (thương cự: vội vã, luống cuống) | Mở khoá kiến thức | Biết 遽 mở khoá: 仓遽 (vội vàng), 遽然 (đột ngột, bỗng nhiên), 遽变 (biến đổi đột ngột).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 辵 (辶 — đi, chạy) biểu nghĩa, 豦 biểu âm. Dạng kim văn và tiểu triện còn được lưu. Nghĩa gốc là xe ngựa chạy nhanh để truyền tin; từ đó phái sinh nghĩa đột ngột, vội vàng, kinh hoảng. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "rời xa", "Hạng Tần Suất (Jun Da)": "3940.0", "Tần Suất % (Jun Da)": "99.726134369", "GavinGrover_Once (Chiết tự trực tiếp)": "辶 + 豦", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴辶豦", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "豦", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "辶", "Unihan_Simplified (Chữ Giản thể)": "遽", "Unihan_Traditional (Chữ Phồn thể)": "遽", "Pinyin_Xie": "jù", "Âm Hán Việt_Xie": "cự", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Tính từ | 形容词 | Thường làm phó từ đứng trước động từ để chỉ hành động xảy ra đột ngột hoặc vội vã. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('邃', '{"9000": "3941.0", "Chữ Trung Quốc": "邃", "Bộ thủ & thành phần_Xie": "Bộ thủ | 辵 | Số nét | 17 | nét | 穴 | huyệt | biểu nghĩa | hang động, hốc sâu | 遂 | toại | biểu âm | thực hiện, đạt được | 邃 = 穴 (Huyệt, biểu nghĩa: hang sâu) + 遂 (Toại, biểu âm); chữ hình thanh. Bộ 穴 chỉ sự sâu kín, 遂 cho âm suì. Nghĩa là sâu xa, uyên thâm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"toại\" (sâu): hang (穴) sâu thẳm + toại (遂 — đi xuyên) — 邃 là sâu xa tuyệt đỉnh, như hang động không đáy. | Gương Hán-Việt | toại — 邃 xuất hiện trong 深邃 (thâm toại: sâu xa, thâm sâu) | Mở khoá kiến thức | Biết 邃 mở khoá: 深邃 (sâu xa), 幽邃 (u tối sâu kín), 邃密 (thâm mật — uyên thâm cẩn mật).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: bộ 穴 (hang động) biểu nghĩa, 遂 biểu âm. Nghĩa gốc là nơi ở xa xôi, sâu kín (1000 lý xung quanh kinh đô — theo Wiktionary). Từ đó phái sinh nghĩa sâu xa, uyên thâm, huyền bí. Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sâu xa, uyên thâm", "Hạng Tần Suất (Jun Da)": "3941.0", "Tần Suất % (Jun Da)": "99.7264465072", "GavinGrover_Once (Chiết tự trực tiếp)": "遂 + 穴", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴遂穴", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "遂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "穴", "Unihan_Simplified (Chữ Giản thể)": "邃", "Unihan_Traditional (Chữ Phồn thể)": "邃", "Pinyin_Xie": "suì", "Âm Hán Việt_Xie": "thuý", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ bổ nghĩa cho danh từ hoặc đứng sau phó từ chỉ mức độ để tả độ sâu hoặc sự uyên bác. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恚', '{"9000": "3942.0", "Chữ Trung Quốc": "恚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 恚 | huệ | tượng hình | tức giận — cấu trúc nội bộ không xác nhận được từ Wiktionary | 恚 không có phân tích cấu trúc từ Wiktionary. Chữ thuộc bộ 心 (tâm — lòng, cảm xúc), gợi liên quan đến cảm xúc tức giận. Dạng tiểu triện còn được lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"huệ\" (giận): bộ 心 (lòng) — lòng (心) bùng lên như lửa — 恚 là sự tức giận trong văn học cổ. | Gương Hán-Việt | huệ — 恚 xuất hiện trong 恚怒 (huệ nộ: tức giận), 忿恚 (phẫn huệ: tức giận, phẫn nộ) | Mở khoá kiến thức | Biết 恚 mở khoá: 恚怒 (tức giận), 忿恚 (phẫn nộ), 瞋恚 (sân hận — trong Phật giáo: một trong ba độc).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc cho 恚. Chữ thuộc bộ 心 (lòng). Nghĩa là tức giận, phẫn nộ. Dạng tiểu triện còn được lưu trong nguồn hình ảnh. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tức giận", "Hạng Tần Suất (Jun Da)": "3942.0", "Tần Suất % (Jun Da)": "99.7267586454", "GavinGrover_Once (Chiết tự trực tiếp)": "圭 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱圭心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "圭", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "恚", "Unihan_Traditional (Chữ Phồn thể)": "恚", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "khuể", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ trạng thái tâm lý giận dữ hoặc kết hợp thành từ ghép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皑', '{"9000": "3943.0", "Chữ Trung Quốc": "皑", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 11 | nét | 白 | bạch | biểu nghĩa | trắng | 豈 | khải | biểu âm | há, lẽ nào | 皑 = 白 (Bạch, biểu nghĩa: trắng) + 豈 (Khải, biểu âm); chữ hình thanh. Bộ 白 chỉ màu trắng, 豈 cho âm ái. Dạng phồn thể 皚. Nghĩa là trắng tinh, trắng bóng như tuyết.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngai\" (trắng tinh): bộ 白 (trắng) — 皑皑白雪 (tuyết trắng tinh ngai ngái) — 皑 tả màu trắng tinh khôi của tuyết trên núi. | Gương Hán-Việt | ngai — 皑 xuất hiện trong 皑皑白雪 (ngai ngai bạch tuyết: tuyết trắng tinh tinh) | Mở khoá kiến thức | Biết 皑 mở khoá: 皑皑 (trắng tinh), 白皑皑 (trắng tinh tinh — thường tả tuyết hoặc muối).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 白 (trắng) biểu nghĩa, 豈 biểu âm. Nghĩa là thuần trắng, trắng như tuyết. Thường dùng trong 白皑皑 (trắng tinh tinh — tả tuyết) và 皑皑 (trắng bóng). Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trắng bóng", "Hạng Tần Suất (Jun Da)": "3943.0", "Tần Suất % (Jun Da)": "99.72706975", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 岂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰白岂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "岂", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皑", "Unihan_Traditional (Chữ Phồn thể)": "皚", "Pinyin_Xie": "ái", "Âm Hán Việt_Xie": "ngai", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Làm tính từ miêu tả màu trắng của tuyết hoặc sương, thường dùng trong văn viết. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('锵', '{"9000": "3944.0", "Chữ Trung Quốc": "锵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 金 | Số nét | 14 | nét | 锵 | tương | tượng hình | tiếng ngọc kêu — là chữ giản thể của 鏘, cấu trúc đầy đủ chưa xác nhận | 锵 là chữ giản thể của 鏘 (钅替代釒, 将替代將). Dạng phồn thể 鏘 gồm 釒 (Kim, biểu nghĩa: kim loại, đồ vật kim loại) + 將 (biểu âm). Chữ hình thanh tượng âm thanh kim loại.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tương\" (tiếng chuông): bộ 钅 (kim loại) — tiếng kim loại (钅) rung lên tương tương — 锵 là âm thanh vang trong của chuông ngọc. | Gương Hán-Việt | tương — 锵 xuất hiện trong 锵锵 (tương tương: tiếng kim loại vang trong) | Mở khoá kiến thức | Biết 锵 mở khoá: 锵锵 (tiếng vang trong), 铿锵 (khanh tương: tiếng kim loại vang mạnh), 铿锵有力 (vang vọng đanh thép).", "Tự nguyên_Xie": "Lục thư thông | 锵 là chữ giản thể của 鏘. Dạng phồn thể gồm bộ 釒 (kim loại) biểu nghĩa và 將 biểu âm. Nghĩa là tiếng ngọc hay kim loại kêu — âm thanh vang trong, leng keng. Dùng để tả âm thanh: 锵锵 (tương tương — tiếng kim loại vang). Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tiếng ngọc kêu; tiếng chuông", "Hạng Tần Suất (Jun Da)": "3944.0", "Tần Suất % (Jun Da)": "99.7273808547", "GavinGrover_Once (Chiết tự trực tiếp)": "钅 + 将", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰钅将", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "将", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "钅", "Unihan_Simplified (Chữ Giản thể)": "锵", "Unihan_Traditional (Chữ Phồn thể)": "鏘", "Pinyin_Xie": "qiāng", "Âm Hán Việt_Xie": "thương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Động từ | 动词 | Thường dùng làm từ tượng thanh mô tả âm thanh của kim khí hoặc ngọc va chạm. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('簌', '{"9000": "3945.0", "Chữ Trung Quốc": "簌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 竹 | Số nét | 17 | nét | 𥫗 | biểu nghĩa | tre, nứa (dạng rút gọn của 竹) | 欶 | biểu âm | thành phần biểu âm | 簌 = 𥫗/竹 (biểu nghĩa: tre, nứa) + 欶 (biểu âm); chữ hình thanh. Bộ 竹 chỉ liên quan đến âm thanh của tre, lá; 欶 cho âm sù. Nghĩa là tiếng vi vu, rì rào (gió thổi, lá rơi).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\" (rào rào): bộ 竹 (tre) — gió thổi qua bụi tre 竹 tạo tiếng túc túc rào rào — 簌 là âm thanh vi vu, xào xạc đó. | Gương Hán-Việt | túc — 簌 xuất hiện trong 簌簌 (túc túc: rào rào, xào xạc) | Mở khoá kiến thức | Biết 簌 mở khoá: 簌簌 (tiếng lá rơi rào rào), 撲簌 (tiếng rơi nhẹ), 急簌簌 (ào ạt, rào rào).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 竹 (tre) biểu nghĩa, 欶 biểu âm. Nghĩa là tiếng lá rơi, tiếng gió thổi qua tre. Thường dùng trong 簌簌 (sù sù — rì rào, rào rào). Chưa có nguồn giáp cốt hay kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "vi vu; rì rào (tiếng gió thổi)", "Hạng Tần Suất (Jun Da)": "3945.0", "Tần Suất % (Jun Da)": "99.7276919593", "GavinGrover_Once (Chiết tự trực tiếp)": "⺮ + 欶", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱⺮欶", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "欶", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "⺮", "Unihan_Simplified (Chữ Giản thể)": "簌", "Unihan_Traditional (Chữ Phồn thể)": "簌", "Pinyin_Xie": "sù", "Âm Hán Việt_Xie": "tốc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Từ tượng thanh | 象声词 | Tính từ | 形容词 | Thường dùng lặp lại làm từ tượng thanh mô tả tiếng lá rụng hoặc nước mắt rơi lã chã. | Từ tượng thanh | 象声词 | Mô phỏng âm thanh: 哗哗, 汪汪. Có thể làm định ngữ, trạng ngữ hoặc đứng độc lập. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('焙', '{"9000": "3946.0", "Chữ Trung Quốc": "焙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 12 | nét | 火 | hoả | biểu nghĩa | lửa, nhiệt | 咅 | biểu âm | thành phần biểu âm | 焙 = 火 (Hoả, biểu nghĩa: lửa) + 咅 (biểu âm); chữ hình thanh. Bộ 火 chỉ liên quan đến nhiệt, 咅 cho âm bèi. Nghĩa là sấy khô bằng lửa nhỏ, hơ lửa.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vùi\" (sấy vùi): bộ 火 (lửa nhỏ) — vùi nhẹ trong lửa (火) để sấy khô — 焙 là sấy, nướng nhẹ nhàng bằng nhiệt độ thấp. | Gương Hán-Việt | vùi — 焙 xuất hiện trong 烘焙 (hồng vùi: nướng bánh) | Mở khoá kiến thức | Biết 焙 mở khoá: 烘焙 (làm bánh nướng), 焙茶 (sấy trà), 焙干 (sấy khô), 焙烤 (sao nướng).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 火 (lửa) biểu nghĩa, 咅 biểu âm. Nghĩa gốc là hơ, sấy bằng nhiệt độ thấp. Dùng trong 烘焙 (sao nướng — baking), 焙茶 (sấy trà). Không có dạng giáp cốt hay kim văn — chữ tạo muộn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "1413.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Hỏa (085) Phẫu (101)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Bộ Hỏa (số 085 - ngọn lửa/ 火 /chỉ ý) ở bên trái chữ Phẫu (số 101 - nhổ nước bọt/ 咅 /chỉ âm). Giải thích sự chuyển ý: Đây là chữ Hình thanh. Chữ Phẫu chỉ âm, bộ Hỏa chỉ ý. Bồi là dùng lửa nhỏ để rang, sao, sấy cho khô vật (bồi trà - sấy trà).", "Nghĩa Tiếng Việt_Xie": "sấy, hơ lửa", "Hạng Tần Suất (Jun Da)": "3946.0", "Tần Suất % (Jun Da)": "99.7280025472", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 咅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火咅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "焙", "Unihan_Traditional (Chữ Phồn thể)": "焙", "Pinyin_Xie": "bèi", "Âm Hán Việt_Xie": "bồi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động sấy khô trà, thuốc bắc hoặc sấy thực phẩm bằng lửa nhỏ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('昊', '{"9000": "3947.0", "Chữ Trung Quốc": "昊", "Bộ thủ & thành phần_Xie": "Bộ thủ | 日 | Số nét | 8 | nét | 日 | nhật | mặt trời | 天 | thiên | trời | 昊 = 日 (Nhật: mặt trời) + 天 (Thiên: trời); chữ hội ý. Hai thành phần kết hợp theo nghĩa: mặt trời (日) trên bầu trời rộng lớn (天) — tạo hình ảnh bầu trời bao la sáng rực. Ghi chú: trong tiểu triện, 昊 cũng có thể phân tích là hình thanh (日 + 夰), nhưng dạng phổ biến nhất là hội ý 日+天.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hạo\" (bầu trời): mặt trời (日) trên bầu trời rộng (天) — 昊 là bầu trời hạo nhiên bao la, sáng rực mùa hè. | Gương Hán-Việt | hạo — 昊 xuất hiện trong 昊天 (hạo thiên: bầu trời bao la) | Mở khoá kiến thức | Biết 昊 mở khoá: 昊天 (bầu trời bao la trong văn học cổ), 昊穹 (vòm trời rộng lớn).", "Tự nguyên_Xie": "Wiktionary ghi 昊 là chữ hội ý: 日 (mặt trời) + 天 (trời) — bầu trời bao la. Trong tiểu triện cũng tìm thấy dạng 昦 với cấu trúc hình thanh 日+夰 (夰=tung ra). Nghĩa gốc là bầu trời rộng lớn, sáng rực; cũng dùng như tên riêng. Thường thấy trong 昊天 (hạo thiên — bầu trời bao la). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "trời xanh; mùa hè", "Hạng Tần Suất (Jun Da)": "3947.0", "Tần Suất % (Jun Da)": "99.7283131351", "GavinGrover_Once (Chiết tự trực tiếp)": "日 + 天", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱日天", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "天", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "日", "Unihan_Simplified (Chữ Giản thể)": "昊", "Unihan_Traditional (Chữ Phồn thể)": "昊", "Pinyin_Xie": "hào", "Âm Hán Việt_Xie": "hạo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ bầu trời hoặc dùng trong tên người để chỉ sự rộng lớn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鹳', '{"9000": "3948.0", "Chữ Trung Quốc": "鹳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 22 | nét | 雚 | biểu âm | dạng cổ của chim cò/hạc | 鳥 | điểu | biểu nghĩa | chim | 鹳 = 雚 (biểu âm) + 鳥/鸟 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鸟 chỉ đây là một loài chim, 雚 cho âm guàn. Chữ gốc là 雚 — về sau thêm bộ 鳥 để phân biệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"quán\" (chim cò): bộ 鸟 (chim) + 雚 (âm) — con chim quán 鹳 đứng sừng sững như quán quân bên bờ nước. | Gương Hán-Việt | quán — 鹳 xuất hiện trong 白鹳 (bạch quán: cò trắng/hạc trắng) | Mở khoá kiến thức | Biết 鹳 mở khoá: 白鹳 (cò trắng), 鹳雀楼 (Quán Tước Lâu — lầu cò nổi tiếng), 鹳鸟 (chim hạc).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 鳥 (chim) biểu nghĩa, 雚 biểu âm. Chữ gốc viết là 雚. Sau thêm bộ 鳥 để làm rõ đây là loài chim. Nghĩa là con cò trắng, chim hạc (Ciconia). Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chim khoang, chim quán", "Hạng Tần Suất (Jun Da)": "3948.0", "Tần Suất % (Jun Da)": "99.7286237229", "GavinGrover_Once (Chiết tự trực tiếp)": "雚 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰雚鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "雚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鹳", "Unihan_Traditional (Chữ Phồn thể)": "鸛", "Pinyin_Xie": "guàn", "Âm Hán Việt_Xie": "quán", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ một loài chim lội nước giống như cò hoặc vạc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睽', '{"9000": "3949.0", "Chữ Trung Quốc": "睽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 14 | nét | 䀠 | biểu nghĩa | hai mắt (dạng cổ của bộ 目) | 癸 | quý | biểu âm | thiên can thứ mười | 睽 = 䀠 (biểu nghĩa: hai mắt) + 癸 (Quý, biểu âm); chữ hình thanh. Thành phần 䀠 sau này được đơn giản hóa thành 目. Bộ mắt chỉ hành động nhìn, 癸 cho âm kuí.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khuê\" (mâu thuẫn): hai mắt (䀠) mở to như quý nhân (癸) nhìn trừng — 睽 là cái nhìn trừng trừng, chia cắt, mâu thuẫn. | Gương Hán-Việt | khuê — 睽 xuất hiện trong 众目睽睽 (chúng mục khuê khuê: trăm mắt nhìn chằm chằm) | Mở khoá kiến thức | Biết 睽 mở khoá: 众目睽睽 (dưới mắt mọi người), 睽违 (xa cách, chia cắt lâu ngày), 睽异 (bất đồng, khác biệt).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hình thanh: 䀠 (hai mắt) biểu nghĩa, 癸 biểu âm. Thành phần 䀠 sau trở thành 目. Nghĩa gốc là nhìn chằm chằm, mắt mở to. Từ đó phái sinh nghĩa mâu thuẫn, trái chiều (睽违 — chia cắt lâu ngày), và là quẻ 睽 trong Kinh Dịch (quẻ 38 — sự đối lập). Dạng kim văn và tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngang trái, mâu thuẫn nhau", "Hạng Tần Suất (Jun Da)": "3949.0", "Tần Suất % (Jun Da)": "99.728933794", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 癸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目癸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "癸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睽", "Unihan_Traditional (Chữ Phồn thể)": "睽", "Pinyin_Xie": "kuí", "Âm Hán Việt_Xie": "khuê", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường dùng trong các từ ghép cố định để chỉ việc mọi người cùng chú ý nhìn vào. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('刽', '{"9000": "3950.0", "Chữ Trung Quốc": "刽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 刀 | Số nét | 8 | nét | 刽 | khoái | tượng hình | chặt, chém — là chữ giản thể của 劊, cấu trúc đầy đủ chưa xác nhận rõ | 刽 là chữ giản thể của 劊. Dạng phồn thể 劊 chứa bộ 刀 (dao), gợi hành động chặt chém. Cấu trúc đầy đủ không có {{Han compound}} rõ ràng trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoái\" (đao phủ): dao (刀) chém khoái — 刽子手 (khoái tử thủ) là đao phủ, kẻ hành quyết. | Gương Hán-Việt | khoái — 刽 xuất hiện trong 刽子手 (khoái tử thủ: đao phủ) | Mở khoá kiến thức | Biết 刽 mở khoá: 刽子手 (đao phủ), 刽伍 (đội đao phủ — cổ văn).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích cấu trúc cho 刽/劊. Chữ liên quan đến bộ 刀 (dao), gợi hành động cắt, chém. Nghĩa là chặt, chém (văn học). Chủ yếu dùng trong 刽子手 (khoái tử thủ — đao phủ). Dạng tiểu triện còn được lưu. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "chặt, chém", "Hạng Tần Suất (Jun Da)": "3950.0", "Tần Suất % (Jun Da)": "99.7292433483", "GavinGrover_Once (Chiết tự trực tiếp)": "会 + 刂", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰会刂", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "刂", "Unihan_Simplified (Chữ Giản thể)": "刽", "Unihan_Traditional (Chữ Phồn thể)": "劊", "Pinyin_Xie": "guì", "Âm Hán Việt_Xie": "quái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Làm động từ chỉ hành động chém giết, thường xuất hiện trong từ ghép chỉ đao phủ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鳖', '{"9000": "3951.0", "Chữ Trung Quốc": "鳖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 魚 | Số nét | 19 | nét | 鳖 | miết | tượng hình | con ba ba — là chữ giản thể của 鱉, cấu trúc đầy đủ chưa xác nhận | 鳖 là chữ giản thể của 鱉. Dạng phồn thể 鱉 chứa bộ 魚 (cá, thủy sinh), gợi liên quan đến sinh vật dưới nước. Cấu trúc đầy đủ không có {{Han compound}} rõ ràng trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"miết\" (ba ba): bộ 鱼 (cá) — con ba ba 鳖 sống dưới nước như cá nhưng là bò sát — miết là tên Hán-Việt của loài mai mỏng ẩn mình dưới bùn. | Gương Hán-Việt | miết — 鳖 xuất hiện trong 甲鱼 (giáp ngư: ba ba) hay 鳖鱼 (miết ngư) | Mở khoá kiến thức | Biết 鳖 mở khoá: 甲鱼/鳖 (con ba ba), 鳖裙 (phần thịt viền mai ba ba — đặc sản).", "Tự nguyên_Xie": "Tiểu triện | 鳖 là chữ giản thể của 鱉. Chữ liên quan đến bộ 魚 (cá, thủy sinh). Nghĩa là con ba ba — loài bò sát thủy sinh có mai mỏng. Dạng tiểu triện còn được lưu trong nguồn hình ảnh. Chưa có nguồn học thuật xác nhận cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con ba ba", "Hạng Tần Suất (Jun Da)": "3951.0", "Tần Suất % (Jun Da)": "99.7295523858", "GavinGrover_Once (Chiết tự trực tiếp)": "敝 + 鱼", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱敝鱼", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "敝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鱼", "Unihan_Simplified (Chữ Giản thể)": "鳖", "Unihan_Traditional (Chữ Phồn thể)": "鱉", "Pinyin_Xie": "biē", "Âm Hán Việt_Xie": "biết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Làm danh từ chỉ loài ba ba sống ở nước ngọt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('噎', '{"9000": "3952.0", "Chữ Trung Quốc": "噎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 15 | nét | 口 | khẩu | biểu nghĩa | miệng | 壹 | nhất | biểu âm | một (dạng phồn thể) | 噎 = 口 (Khẩu, biểu nghĩa: miệng) + 壹 (Nhất, biểu âm); chữ hình thanh. Bộ 口 chỉ liên quan đến miệng, 壹 cho âm yī gần với yē. Nghĩa là nghẹn, nghẹt cổ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ế\" (nghẹn): miệng (口) bị bít lại như một (壹 — kín chặt) — 噎 là nghẹn cổ, không nói không nuốt được. | Gương Hán-Việt | ế — 噎 xuất hiện trong 因噎废食 (nhân ế phế thực: vì nghẹn mà bỏ ăn) | Mở khoá kiến thức | Biết 噎 mở khoá: 因噎废食 (thành ngữ: vì sự cố nhỏ mà từ bỏ kế hoạch lớn), 哽噎 (nghẹn ngào).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 口 (miệng) biểu nghĩa, 壹 biểu âm. Nghĩa gốc là bị nghẹn ở cổ họng — không thể nuốt, không thể thở. Dùng trong 因噎废食 (vì nghẹn mà bỏ ăn — ý: vì sợ thất bại nhỏ mà từ bỏ cả việc lớn). Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nghẹn; ngạt thở", "Hạng Tần Suất (Jun Da)": "3952.0", "Tần Suất % (Jun Da)": "99.7298614233", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 壹", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口壹", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "壹", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "噎", "Unihan_Traditional (Chữ Phồn thể)": "噎", "Pinyin_Xie": "yē", "Âm Hán Việt_Xie": "ế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này thường làm động từ đứng trước tân ngữ hoặc đứng độc lập để chỉ hành động bị nghẹn thức ăn. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('呗', '{"9000": "3953.0", "Chữ Trung Quốc": "呗", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 7 | nét | 口 | khẩu | biểu nghĩa | miệng, âm thanh | 貝 | buổi | biểu âm | vỏ sò (dùng làm tiền) | 呗 = 口 (Khẩu, biểu nghĩa: miệng) + 貝 (Bối/Buổi, biểu âm); chữ hình thanh. Bộ 口 chỉ âm thanh phát ra từ miệng, 貝 cho âm bei. Nguồn gốc là rút gọn phiên âm chữ Phạn 唄匿 (bái-toku/pāthaka — người tụng kinh).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bái\" (tụng): miệng (口) tụng kinh bái (貝 — âm bái/bối) — 呗 gốc là tiếng tụng kinh Phật, nay dùng như trợ từ cuối câu. | Gương Hán-Việt | bái — 呗 xuất hiện trong tụng kinh và là hạt từ khẩu ngữ 呗 (thôi, vậy đó) | Mở khoá kiến thức | Biết 呗 mở khoá: 唄 (bái — tụng kinh, dạng phồn thể), dùng 呗 như trợ từ cuối câu trong khẩu ngữ.", "Tự nguyên_Xie": "Chữ hình thanh: bộ 口 (miệng) biểu nghĩa, 貝 biểu âm. 呗 là rút gọn của 唄匿 — phiên âm chữ Phạn ''pathaka'', nghĩa là người tụng kinh. Về sau trong tiếng Trung hiện đại, 呗 trở thành hạt từ khẩu ngữ (bei — dùng ở cuối câu để nhấn, tương tự ''thôi'', ''vậy thôi''). Không có dạng giáp cốt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tụng kinh", "Hạng Tần Suất (Jun Da)": "3953.0", "Tần Suất % (Jun Da)": "99.7301704609", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 贝", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口贝", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "贝", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "呗", "Unihan_Traditional (Chữ Phồn thể)": "唄", "Pinyin_Xie": "bei", "Âm Hán Việt_Xie": "bối, bái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Trợ từ | 助词 | Danh từ | 名词 | Thường dùng làm trợ từ ngữ khí ở cuối câu trong khẩu ngữ hoặc làm danh từ chỉ nhạc Phật giáo. | Trợ từ | 助词 | Không mang nghĩa riêng, gắn vào câu để đánh dấu ngữ pháp hoặc ngữ khí: 的 / 地 / 得 (kết cấu), 了 / 着 / 过 (thể), 吗 / 呢 / 吧 (nghi vấn, ngữ khí). | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('寰', '{"9000": "3954.0", "Chữ Trung Quốc": "寰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 宀 | Số nét | 16 | nét | 宀 | biểu nghĩa | mái nhà, cõi trời (bộ miên) | 睘 | biểu âm | thành phần biểu âm | 寰 = 宀 (biểu nghĩa: mái nhà, lãnh thổ bao phủ) + 睘 (biểu âm); chữ hình thanh. Bộ 宀 chỉ không gian bao phủ như bờ cõi, 睘 cho âm huán. Nghĩa là cõi đất rộng lớn, lãnh thổ hoàng đế.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hoàn\" (cõi đất): mái che (宀) bao phủ khắp hoàn vũ — 寰宇 (hoàn vũ) là cõi trời đất rộng bao la mà con người sống trong đó. | Gương Hán-Việt | hoàn — 寰 xuất hiện trong 寰宇 (hoàn vũ: vũ trụ), 人寰 (nhân hoàn: cõi người) | Mở khoá kiến thức | Biết 寰 mở khoá: 寰宇 (vũ trụ), 人寰 (cõi người), 威震寰宇 (uy danh chấn động thiên hạ).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 宀 (mái nhà, lãnh thổ) biểu nghĩa, 睘 biểu âm. Nghĩa gốc là vùng rộng lớn — lãnh thổ hoàng gia 1000 lý xung quanh kinh đô. Mở rộng sang toàn cõi đất, thế giới. Dùng trong 寰宇 (hoàn vũ — vũ trụ), 人寰 (nhân hoàn — cõi người). Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ cõi rộng lớn", "Hạng Tần Suất (Jun Da)": "3954.0", "Tần Suất % (Jun Da)": "99.7304794984", "GavinGrover_Once (Chiết tự trực tiếp)": "宀 + 睘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱宀睘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "睘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "宀", "Unihan_Simplified (Chữ Giản thể)": "寰", "Unihan_Traditional (Chữ Phồn thể)": "寰", "Pinyin_Xie": "huán", "Âm Hán Việt_Xie": "hoàn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ kết hợp với các từ khác để chỉ thế giới hoặc vũ trụ như trong hoàn cầu, trần hoàn. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('唷', '{"9000": "3955.0", "Chữ Trung Quốc": "唷", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 唷 | dóc | tượng hình | thán từ — chữ không có nguồn gốc Wiktionary | 唷 không có dữ liệu nguồn gốc trong Wiktionary (usedForm null, glyphOrigin null). Chữ thuộc bộ 口 (miệng), gợi liên quan đến âm thanh, thán từ. Đây là chữ ghi âm cho thán từ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dóc\" (thán từ): bộ 口 (miệng) — miệng thốt lên 唷! — tiếng kêu ngạc nhiên hay đau nhói. | Gương Hán-Việt | dóc — 唷 là thán từ tiếng Trung, tương đương 哟 hoặc 哎唷 | Mở khoá kiến thức | Biết 唷 mở khoá ngữ cảnh: thán từ trong văn xuôi và thơ, tương tự 哟 (yō — ồ, ái chà).", "Tự nguyên_Xie": "Không có nguồn gốc học thuật cho 唷. Chữ thuộc bộ 口 (miệng), dùng để ghi thán từ thể hiện ngạc nhiên, đau, hoặc nhấn mạnh (tương tự 哟). Không có dạng giáp cốt, kim văn hay tiểu triện — chữ tạo muộn. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(thán từ)", "Hạng Tần Suất (Jun Da)": "3955.0", "Tần Suất % (Jun Da)": "99.7307880191", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 育", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口育", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "育", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "唷", "Unihan_Traditional (Chữ Phồn thể)": "唷", "Pinyin_Xie": "yō", "Âm Hán Việt_Xie": "dục", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Thán từ | 叹词 | Thường đứng đầu câu làm thán từ biểu thị sự ngạc nhiên hoặc đau đớn. | Thán từ | 叹词 | Bộc lộ cảm xúc hoặc dùng để gọi đáp: 啊, 哦, 喂. Đứng tách riêng ở đầu câu, không làm thành phần câu.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('殡', '{"9000": "3956.0", "Chữ Trung Quốc": "殡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 歹 | Số nét | 14 | nét | 歹 | tồi | biểu nghĩa | xương tàn, chết chóc | 賓 | tân | biểu âm | khách, tiếp đón | 殡 = 歹 (Tồi, biểu nghĩa: cái chết, xương tàn) + 賓 (Tân, biểu âm); chữ hình thanh. Bộ 歹 chỉ liên quan đến cái chết, 賓 cho âm bìn. Nghĩa là an táng tạm thời (quan tài chưa chôn).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tân\" (khách tang): bộ 歹 (chết) + tân (賓 — khách) — khách người chết (歹) được tiếp đón (賓) theo lễ nghi — 殡 là lễ tang. | Gương Hán-Việt | tân — 殡 xuất hiện trong 出殡 (xuất tân: đưa đám tang), 殡仪馆 (nhà tang lễ) | Mở khoá kiến thức | Biết 殡 mở khoá: 出殡 (đưa đám), 殡仪馆 (nhà tang lễ), 殡葬 (tang lễ và an táng).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: bộ 歹 (cái chết) biểu nghĩa, 賓 biểu âm. Dạng phồn thể 殯. Nghĩa gốc là đặt quan tài (chưa chôn) — chờ đợi đủ lễ nghi mới an táng. Mở rộng sang tang lễ chung. Dùng trong 出殡 (xuất tân — đưa đám), 殡仪馆 (nhà tang lễ). Dạng tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "yên cữu (xác chết nhập quan chưa chôn); vùi lấp", "Hạng Tần Suất (Jun Da)": "3956.0", "Tần Suất % (Jun Da)": "99.7310965398", "GavinGrover_Once (Chiết tự trực tiếp)": "歹 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰歹宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "歹", "Unihan_Simplified (Chữ Giản thể)": "殡", "Unihan_Traditional (Chữ Phồn thể)": "殯", "Pinyin_Xie": "bìn", "Âm Hán Việt_Xie": "tẫn", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ việc đặt xác vào quan tài chờ chôn cất hoặc làm danh từ chỉ tang lễ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('淖', '{"9000": "3957.0", "Chữ Trung Quốc": "淖", "Bộ thủ & thành phần_Xie": "Bộ thủ | 水 | Số nét | 11 | nét | 淖 | nạo | tượng hình | bùn đất — cấu trúc nội bộ không xác nhận được từ Wiktionary | 淖 không có phân tích cấu trúc từ Wiktionary ({{Han etym}} rỗng). Chữ thuộc bộ 水 (氵 — nước), gợi liên quan đến nước và bùn. Dạng tiểu triện và lục thư thông còn được lưu.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nạo\" (bùn): bộ 氵 (nước) — nước (氵) ngập sình tạo vũng bùn 淖 — nạo lên toàn bùn sình lầy lội. | Gương Hán-Việt | nạo — 淖 xuất hiện trong 泥淖 (nê nạo: vũng bùn sâu) | Mở khoá kiến thức | Biết 淖 mở khoá: 泥淖 (vũng bùn), 淖泥 (bùn sình), 淖滞 (tù đọng, lầy lội).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích cấu trúc cho 淖. Chữ thuộc bộ 氵 (nước), nghĩa là bùn sình. Thường dùng trong 淖泥 (bùn sình) và 泥淖 (vũng bùn sâu). Dạng tiểu triện còn được lưu trong nguồn hình ảnh. Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bùn đất", "Hạng Tần Suất (Jun Da)": "3957.0", "Tần Suất % (Jun Da)": "99.7314045438", "GavinGrover_Once (Chiết tự trực tiếp)": "氵 + 卓", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰氵卓", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "卓", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "氵", "Unihan_Simplified (Chữ Giản thể)": "淖", "Unihan_Traditional (Chữ Phồn thể)": "淖", "Pinyin_Xie": "nào", "Âm Hán Việt_Xie": "náo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ bùn lầy hoặc làm tính từ mô tả trạng thái ẩm ướt, mềm nhão. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诰', '{"9000": "3958.0", "Chữ Trung Quốc": "诰", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 9 | nét | 诰 | cáo | tượng hình | ban sắc lệnh — là chữ giản thể của 誥, cấu trúc đầy đủ không xác nhận được | 诰 là chữ giản thể của 誥. Dạng phồn thể 誥 chứa bộ 言 (lời nói, văn bản), gợi liên quan đến lời ban bố. Cấu trúc đầy đủ không có {{Han compound}} trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cáo\" (ban sắc): lời vua (言) ban xuống — 诰命 (cáo mệnh) là sắc phong cao quý, 诰 là văn bản sắc lệnh hoàng gia. | Gương Hán-Việt | cáo — 诰 xuất hiện trong 诰命 (cáo mệnh: sắc phong của vua), 制诰 (chiếu chỉ) | Mở khoá kiến thức | Biết 诰 mở khoá: 诰命 (sắc phong), 制诰 (chiếu chỉ hoàng gia), 封诰 (phong tặng sắc phong).", "Tự nguyên_Xie": "Tiểu triện | 诰/誥 liên quan đến bộ 言 (lời nói, văn bản). Nghĩa là ban sắc lệnh, lời vua răn dạy. Dùng trong 誥命 (cáo mệnh — sắc phong của vua), 制誥 (chế cáo — chiếu chỉ). Dạng tiểu triện còn được lưu. Wiktionary không có {{Han compound}} chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "răn bảo; ban sắc mệnh", "Hạng Tần Suất (Jun Da)": "3958.0", "Tần Suất % (Jun Da)": "99.7317125477", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 告", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠告", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "告", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诰", "Unihan_Traditional (Chữ Phồn thể)": "誥", "Pinyin_Xie": "gào", "Âm Hán Việt_Xie": "cáo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường làm danh từ chỉ văn bản sắc phong của vua chúa hoặc làm động từ ban lệnh, răn bảo. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('恣', '{"9000": "3959.0", "Chữ Trung Quốc": "恣", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 10 | nét | 次 | thứ | biểu âm | thứ, lần | 心 | tâm | biểu nghĩa | lòng, cảm xúc | 恣 = 次 (Thứ, biểu âm) + 心 (Tâm, biểu nghĩa: lòng); chữ hình thanh. Bộ 心 chỉ liên quan đến cảm xúc, ý chí; 次 cho âm zì. Nghĩa là phóng túng, buông thả theo ý muốn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tứ\" (tùy ý): lòng (心) không kìm chế — thứ/tứ (次) — 恣 là phóng túng theo ý thích, không giới hạn. | Gương Hán-Việt | tứ — 恣 xuất hiện trong 恣意 (tứ ý: tùy tiện, theo ý muốn) | Mở khoá kiến thức | Biết 恣 mở khoá: 恣意 (tùy tiện), 恣意妄为 (tùy tiện làm bừa), 放恣 (phóng túng).", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: bộ 心 (lòng) biểu nghĩa, 次 biểu âm. Nghĩa gốc là tùy ý, buông thả, không kìm hãm. Dùng trong 恣意 (tứ ý — tùy tiện), 放恣 (phóng túng). Dạng đại triện và tiểu triện còn được lưu. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "377.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Tâm (148) Thứ (30)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Thứ (số 30 - kế tiếp) ở trên chữ Tâm (số 148) . Tứ là sự phóng túng, bừa bãi trong tâm trí. Giải thích sự chuyển ý: Chữ Thứ (kế tiếp) chỉ âm, chữ Tâm (tấm lòng) chỉ ý. Tấm lòng (Tâm) buông thả, mặc sức làm càn, hết ý niệm này đến ý niệm khác (Thứ) gọi là phóng túng (Tứ). *(Biến âm Hán Việt: Thứ -> Tứ)*", "Nghĩa Tiếng Việt_Xie": "phóng túng", "Hạng Tần Suất (Jun Da)": "3959.0", "Tần Suất % (Jun Da)": "99.7320205516", "GavinGrover_Once (Chiết tự trực tiếp)": "次 + 心", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱次心", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "次", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "心", "Unihan_Simplified (Chữ Giản thể)": "恣", "Unihan_Traditional (Chữ Phồn thể)": "恣", "Pinyin_Xie": "zì", "Âm Hán Việt_Xie": "tứ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Phó từ | 副词 | Động từ | 动词 | Thường làm phó từ đứng trước động từ để chỉ hành vi làm một cách thỏa thích, không kiêng nể. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('睐', '{"9000": "3960.0", "Chữ Trung Quốc": "睐", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 12 | nét | 目 | mục | biểu nghĩa | mắt | 來 | lai | biểu âm | đến, tới | 睐 = 目 (Mục, biểu nghĩa: mắt) + 來/来 (Lai, biểu âm); chữ hình thanh. Bộ 目 chỉ hành động nhìn, 來 cho âm lài. Dạng phồn thể 睞. Nghĩa là liếc mắt sang bên, nhìn nghiêng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lãi\" (liếc): mắt (目) liếc sang khi có ai đến (來) — 睐 là cái liếc mắt ý nhị, duyên dáng. | Gương Hán-Việt | lãi — 睐 xuất hiện trong 青睐 (thanh lãi: sự ưu ái, chú ý) | Mở khoá kiến thức | Biết 睐 mở khoá: 青睐 (ưu ái, chú ý đặc biệt), 眄睐 (nhìn liếc xéo), 明眸善睐 (mắt đẹp liếc hay).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 目 (mắt) biểu nghĩa, 來 biểu âm. Nghĩa gốc là liếc mắt về phía ai đó — cái nhìn nghiêng, ý nhị. Dùng trong 青睐 (thanh lãi — sự ưu ái, chú ý của người trên) và 明眸善睐 (mắt sáng liếc hay — tả người đẹp). Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "liếc mắt trông", "Hạng Tần Suất (Jun Da)": "3960.0", "Tần Suất % (Jun Da)": "99.7323285556", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 来", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目来", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "来", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "睐", "Unihan_Traditional (Chữ Phồn thể)": "睞", "Pinyin_Xie": "lài", "Âm Hán Việt_Xie": "lãi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ kết hợp trong các từ ghép như thanh lãi để chỉ sự chú ý, yêu mến. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('婵', '{"9000": "3961.0", "Chữ Trung Quốc": "婵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 11 | nét | 女 | nữ | biểu nghĩa | nữ, phụ nữ | 單 | đơn | biểu âm | đơn, một mình | 婵 = 女 (Nữ, biểu nghĩa: phụ nữ) + 單/单 (Đơn, biểu âm); chữ hình thanh. Bộ 女 chỉ liên quan đến nữ giới, 單 cho âm chán. Nghĩa là đẹp đẽ, duyên dáng.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiền\" (duyên dáng): phụ nữ (女) đơn độc (單) mà đẹp như trăng — 婵娟 (thiền quyên) là vẻ đẹp dịu dàng, cũng chỉ mặt trăng trong thơ. | Gương Hán-Việt | thiền — 婵 xuất hiện trong 婵娟 (thiền quyên: vẻ đẹp dịu dàng, mặt trăng trong thơ) | Mở khoá kiến thức | Biết 婵 mở khoá: 婵娟 (vẻ đẹp duyên dáng, mặt trăng), 嬋媛 (xinh đẹp).", "Tự nguyên_Xie": "Chữ hình thanh: bộ 女 (phụ nữ) biểu nghĩa, 單 biểu âm. Dạng phồn thể 嬋. Nghĩa là xinh đẹp, duyên dáng. Chủ yếu dùng trong 嬋娟/婵娟 — chỉ người đẹp duyên dáng, cũng chỉ mặt trăng đẹp trong thơ cổ. Chưa có nguồn giáp cốt. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thiền quyên 嬋娟,婵娟)", "Hạng Tần Suất (Jun Da)": "3961.0", "Tần Suất % (Jun Da)": "99.7326360427", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 单", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女单", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "单", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "婵", "Unihan_Traditional (Chữ Phồn thể)": "嬋", "Pinyin_Xie": "chán", "Âm Hán Việt_Xie": "thiền", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ ghép trong từ thiền quyên để tả vẻ đẹp thanh tao của người phụ nữ hoặc vầng trăng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('榈', '{"9000": "3962.0", "Chữ Trung Quốc": "榈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 13 | nét | 榈 | lư | tượng hình | cây lư (cọ, gỗ gụ) — là chữ giản thể của 櫚, cấu trúc chưa xác nhận | 榈 là chữ giản thể của 櫚. Dạng phồn thể 櫚 chứa bộ 木 (cây), gợi đây là một loài cây. Cấu trúc đầy đủ không có {{Han compound}} trong Wiktionary.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lư\" (cây cọ): bộ 木 (cây) — 棕榈 (tông lư) là cây cọ rậm tán — lư như lùm cây rậm rạp. | Gương Hán-Việt | lư — 榈 xuất hiện trong 棕榈 (tông lư: cây cọ) | Mở khoá kiến thức | Biết 榈 mở khoá: 棕榈 (cây cọ), 棕榈油 (dầu cọ), 棕榈树 (cây cọ rừng).", "Tự nguyên_Xie": "榈/櫚 liên quan đến bộ 木 (cây). Nghĩa là cây cọ, cây gỗ gụ (棕榈 — cọ dầu). Chủ yếu dùng trong 棕榈 (tông lư — cây cọ) và 棕榈油 (dầu cọ). Wiktionary không có {{Han compound}} chi tiết. Chưa có nguồn học thuật đầy đủ. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây lư, cây gỗ gụ", "Hạng Tần Suất (Jun Da)": "3962.0", "Tần Suất % (Jun Da)": "99.7329435299", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 闾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木闾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "闾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "榈", "Unihan_Traditional (Chữ Phồn thể)": "櫚", "Pinyin_Xie": "lǘ", "Âm Hán Việt_Xie": "lư", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng trong các từ ghép chỉ tên loài cây như tòng lư, lư mộc. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('氦', '{"9000": "3963.0", "Chữ Trung Quốc": "氦", "Bộ thủ & thành phần_Xie": "Bộ thủ | 气 | Số nét | 10 | nét | 气 | khí | biểu nghĩa | khí, hơi | 亥 | hợi | biểu âm | (địa chi thứ 12, phát âm hài) | 氦 = 气 (Khí, biểu nghĩa: khí/hơi) + 亥 (Hợi, biểu âm); chữ hình thanh. Bộ 气 cho biết đây là một loại khí, còn 亥 chỉ âm đọc (hài → hé).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hài\" (không dùng phổ biến): khí (气) mang âm Hợi (亥) — đây là khí helium nhẹ nhất, làm bóng bay lên trời. | Gương Hán-Việt | hài — ít dùng trong tiếng Việt; tên nguyên tố heli (He). | Mở khoá kiến thức | Biết 氦 giúp đọc các tên nguyên tố hoá học hiện đại trong tiếng Trung: 氦气 (khí helium).", "Tự nguyên_Xie": "Chữ hình thanh: 气 (khí/hơi) là thành phần biểu nghĩa, 亥 là thành phần biểu âm (âm hài). Đây là chữ hiện đại, được tạo ra vào cuối thế kỷ 19–đầu thế kỷ 20 để phiên âm tên nguyên tố hoá học helium (He) sang chữ Hán. Chưa thấy trong giáp cốt văn hay kim văn. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nguyên tố hêli, khí hêli, He", "Hạng Tần Suất (Jun Da)": "3963.0", "Tần Suất % (Jun Da)": "99.7332505003", "GavinGrover_Once (Chiết tự trực tiếp)": "气 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴气亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "气", "Unihan_Simplified (Chữ Giản thể)": "氦", "Unihan_Traditional (Chữ Phồn thể)": "氦", "Pinyin_Xie": "hài", "Âm Hán Việt_Xie": "hợi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường làm danh từ đứng độc lập hoặc làm định ngữ trong các thuật ngữ hóa học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('靳', '{"9000": "3964.0", "Chữ Trung Quốc": "靳", "Bộ thủ & thành phần_Xie": "Bộ thủ | 革 | Số nét | 13 | nét | 靳 | cận | tượng hình | dây cương ngựa, bụng ngựa | 靳 là chữ độc lập, không phân tích rõ ràng thành các thành phần trong Wiktionary. Có thể liên quan đến 革 (da) và 斤 (rìu) nhưng nguồn học thuật không xác nhận. Dùng chủ yếu làm họ người và có nghĩa văn ngữ là keo kiệt.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cận\": chữ mang nghĩa gần (cận) mà lại keo kiệt — không chịu cho ai đến gần tài sản của mình. | Gương Hán-Việt | cận — ít dùng riêng lẻ trong tiếng Việt; chủ yếu gặp trong tên người họ Jìn. | Mở khoá kiến thức | Biết 靳 giúp nhận diện họ người Trung Quốc: 靳 (Jìn) là một họ hiếm nhưng có thực.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích hình thanh hoặc hội ý rõ ràng cho 靳. Theo phát âm cổ (Trung Cổ âm: gin3), đây có thể là chữ hình thanh nhưng không có nguồn học thuật xác nhận cấu trúc. Chữ tạo muộn, chưa thấy phân tích trong giáp cốt/kim văn. Dùng chủ yếu làm họ và có nghĩa bổ trợ là ''keo kiệt'', ''dây ngực ngựa''. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ngựa cận (2 con ngựa chạy trong ở xe 4 ngựa)", "Hạng Tần Suất (Jun Da)": "3964.0", "Tần Suất % (Jun Da)": "99.7335564371", "GavinGrover_Once (Chiết tự trực tiếp)": "革 + 斤", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰革斤", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "斤", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "革", "Unihan_Simplified (Chữ Giản thể)": "靳", "Unihan_Traditional (Chữ Phồn thể)": "靳", "Pinyin_Xie": "jìn", "Âm Hán Việt_Xie": "cận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Động từ | 动词 | Chữ này thường dùng làm họ người hoặc xuất hiện trong các từ ghép chỉ sự keo kiệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛹', '{"9000": "3965.0", "Chữ Trung Quốc": "蛹", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 13 | nét | 蛹 | nhộng | tượng hình | nhộng, dạng sâu trước khi hoá bướm | 蛹 không có phân tích thành phần rõ ràng từ nguồn Wiktionary. Chữ tạo muộn để chỉ giai đoạn nhộng trong vòng đời côn trùng. Có thể chứa bộ 虫 (trùng) ẩn trong cấu trúc nhưng không được xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhộng\": con nhộng (蛹) cuộn tròn bất động — giống như chữ 蛹 trông khép kín, chờ ngày hoá bướm. | Gương Hán-Việt | nhộng — tiếng Việt dùng từ này trực tiếp: con nhộng tằm, nhộng bướm. | Mở khoá kiến thức | Biết 蛹 giúp hiểu vòng đời côn trùng: 卵 (trứng) → 幼虫 (sâu non) → 蛹 (nhộng) → 成虫 (trưởng thành).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình thanh hay hội ý cho 蛹. Đây là chữ chỉ sinh vật (nhộng — giai đoạn giữa sâu và bướm/ngài). Chưa thấy phân tích trong giáp cốt/kim văn. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con nhộng", "Hạng Tần Suất (Jun Da)": "3965.0", "Tần Suất % (Jun Da)": "99.7338623739", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 甬", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫甬", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "甬", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛹", "Unihan_Traditional (Chữ Phồn thể)": "蛹", "Pinyin_Xie": "yǒng", "Âm Hán Việt_Xie": "dũng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ đứng độc lập hoặc làm định ngữ để chỉ con nhộng. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('鸯', '{"9000": "3966.0", "Chữ Trung Quốc": "鸯", "Bộ thủ & thành phần_Xie": "Bộ thủ | 鳥 | Số nét | 10 | nét | 央 | ương | biểu âm | (biểu âm: yāng) | 鳥 | điểu | biểu nghĩa | chim | 鸯 = 央 (Ương, biểu âm) + 鳥 (Điểu, biểu nghĩa: chim); chữ hình thanh. Bộ 鳥 cho biết đây là loài chim, còn 央 chỉ âm đọc (yāng).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ương\": con chim (鳥) mang âm Ương (央) — nửa kia của đôi uyên ương (鸳鸯), biểu tượng tình yêu bền chặt trong văn hoá Hán. | Gương Hán-Việt | ương — trong tiếng Việt: ''uyên ương'' (鸳鸯) là cặp đôi chung thuỷ. | Mở khoá kiến thức | Biết 鸯 giúp hiểu từ 鸳鸯 (uyên ương) — cặp vịt trời, biểu tượng hôn nhân hạnh phúc trong thơ ca Hán.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 鳥 (chim) là thành phần biểu nghĩa, 央 là thành phần biểu âm (yāng). 鸯 chỉ xuất hiện trong từ ghép 鸳鸯 (uyên ương — loài vịt trời biểu tượng cho tình yêu chung thuỷ). Glyph tiểu triện được xác nhận. Chữ dùng độc lập rất hạn chế. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con vịt cái", "Hạng Tần Suất (Jun Da)": "3966.0", "Tần Suất % (Jun Da)": "99.7341677939", "GavinGrover_Once (Chiết tự trực tiếp)": "央 + 鸟", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱央鸟", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "央", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "鸟", "Unihan_Simplified (Chữ Giản thể)": "鸯", "Unihan_Traditional (Chữ Phồn thể)": "鴦", "Pinyin_Xie": "yāng", "Âm Hán Việt_Xie": "ương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường kết hợp với chữ ương để tạo thành từ ghép chỉ đôi chim uyên ương. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('惬', '{"9000": "3967.0", "Chữ Trung Quốc": "惬", "Bộ thủ & thành phần_Xie": "Bộ thủ | 心 | Số nét | 11 | nét | 忄 | tâm | biểu nghĩa | tâm, trái tim (bộ đứng) | 匧 | khiếp | biểu âm | (biểu âm: qiè) | 惬 = 忄 (Tâm, biểu nghĩa: trái tim, cảm xúc) + 匧 (Khiếp, biểu âm: qiè); chữ hình thanh. Bộ 忄 cho biết liên quan đến cảm xúc, 匧 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khiếp\" (biến âm): trái tim (忄) cảm thấy vừa vặn khiếp phục (匧) trước vẻ đẹp — đó là cảm giác 惬意 (hài lòng, dễ chịu). | Gương Hán-Việt | khiếp — ít dùng riêng trong tiếng Việt; nghĩa là hài lòng, thoả mãn. | Mở khoá kiến thức | Biết 惬 giúp hiểu 惬意 (qièyì) — cảm giác dễ chịu, hài lòng; thường gặp trong văn học Trung Quốc.", "Tự nguyên_Xie": "Chữ hình thanh: 心/忄 (tâm — trái tim) là thành phần biểu nghĩa, 匧 là thành phần biểu âm (qiè). 惬 mang nghĩa hài lòng, thoải mái, dễ chịu — trạng thái tâm lý tích cực. Wiktionary xác nhận cấu trúc psc. Chưa có glyph giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "thích, thoả lòng", "Hạng Tần Suất (Jun Da)": "3967.0", "Tần Suất % (Jun Da)": "99.7344732139", "GavinGrover_Once (Chiết tự trực tiếp)": "忄 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰忄", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "惬", "Unihan_Traditional (Chữ Phồn thể)": "㥦", "Pinyin_Xie": "qiè", "Âm Hán Việt_Xie": "khiếp", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường làm vị ngữ hoặc bổ ngữ để biểu thị trạng thái tâm lý thỏa mãn. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蹙', '{"9000": "3968.0", "Chữ Trung Quốc": "蹙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 足 | Số nét | 18 | nét | 蹙 | túc | tượng hình | nhíu lại, co rúm, dồn ép | 蹙 không có phân tích thành phần rõ ràng từ Wiktionary. Nhìn tổng thể, chữ có thể chứa 足 (túc, chân) và một thành phần trên, nhưng không có nguồn học thuật xác nhận cấu trúc hội ý hay hình thanh. Dùng chủ yếu với nghĩa nhíu mày, co rút, dồn ép.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"túc\" (bộ chân): bước chân (túc) bị dồn ép, co rúm lại — hình ảnh của 蹙眉 (nhíu mày lo lắng). | Gương Hán-Việt | túc — ít dùng riêng trong tiếng Việt; gặp trong văn ngữ với nghĩa co rút, nhíu lại. | Mở khoá kiến thức | Biết 蹙 giúp đọc thành ngữ văn học: 蹙眉 (nhíu mày), 蹙额 (chau mày lo lắng).", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hình thanh hay hội ý cho 蹙. Đây là chữ cổ dùng trong văn học với nghĩa nhíu mày (蹙眉), gấp bước, hoặc dồn ép. Glyph tiểu triện được ghi nhận. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gấp rút, cấp bách; nhăn, nheo, nhíu, cau, chau; buồn rầu; đá; bước theo sau", "Hạng Tần Suất (Jun Da)": "3968.0", "Tần Suất % (Jun Da)": "99.7347786339", "GavinGrover_Once (Chiết tự trực tiếp)": "戚 + 足", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱戚足", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "戚", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "足", "Unihan_Simplified (Chữ Giản thể)": "蹙", "Unihan_Traditional (Chữ Phồn thể)": "蹙", "Pinyin_Xie": "cù", "Âm Hán Việt_Xie": "túc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Tính từ | 形容词 | Thường kết hợp với các bộ phận trên mặt để diễn tả động tác nhăn mặt, cau mày. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('诙', '{"9000": "3969.0", "Chữ Trung Quốc": "诙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 言 | Số nét | 8 | nét | 讠 | ngôn | biểu nghĩa | lời nói (bộ đứng giản thể) | 诙 | khôi | tượng hình | hài hước, vui vẻ | 诙 là giản thể của 詼. Chữ gốc 詼 = 言 (Ngôn, biểu nghĩa: lời nói) + âm phần biểu âm; chữ hình thanh. Bộ 言/讠 cho biết liên quan đến lời nói, tiếng cười.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khôi\": lời nói (讠) khôi hài — 诙谐 là phong cách nói chuyện dí dỏm, làm người nghe bật cười. | Gương Hán-Việt | khôi — trong tiếng Việt: ''khôi hài'' (诙谐) là từ mượn Hán-Việt chỉ sự hài hước. | Mở khoá kiến thức | Biết 诙 giúp hiểu 诙谐 (khôi hài) — tính hài hước, dí dỏm; từ hay gặp trong văn học và báo chí Trung Quốc.", "Tự nguyên_Xie": "诙 là giản thể của 詼. Chữ phồn thể 詼 chứa bộ 言 (ngôn — lời nói) là thành phần biểu nghĩa. 诙 mang nghĩa hài hước, vui vẻ, bông đùa — thường gặp trong từ 诙谐 (khôi hài, hài hước). Nguồn Wiktionary xác nhận 诙 là dạng giản thể của 詼. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đùa cợt, trêu đùa", "Hạng Tần Suất (Jun Da)": "3969.0", "Tần Suất % (Jun Da)": "99.7350835371", "GavinGrover_Once (Chiết tự trực tiếp)": "讠 + 灰", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰讠灰", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "灰", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "讠", "Unihan_Simplified (Chữ Giản thể)": "诙", "Unihan_Traditional (Chữ Phồn thể)": "詼", "Pinyin_Xie": "huī", "Âm Hán Việt_Xie": "khôi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường kết hợp với chữ hài để tạo thành từ ghép chỉ tính chất hài hước. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('眈', '{"9000": "3970.0", "Chữ Trung Quốc": "眈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 目 | Số nét | 9 | nét | 目 | mục | biểu nghĩa | mắt | 冘 | đem | biểu âm | (biểu âm: dān) | 眈 = 目 (Mục, biểu nghĩa: mắt) + 冘 (Đem, biểu âm: dān); chữ hình thanh. Bộ 目 cho biết liên quan đến mắt/nhìn, 冘 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xẩm\": đôi mắt (目) nhìn xẩm tối, chằm chằm như hổ rình mồi — đó là 虎视眈眈 (hổ thị xẩm xẩm). | Gương Hán-Việt | xẩm — ít dùng riêng trong tiếng Việt; nổi tiếng qua thành ngữ 虎视眈眈 (hổ nhìn chăm chú, chờ cơ hội). | Mở khoá kiến thức | Biết 眈 giúp hiểu thành ngữ 虎视眈眈 — mắt hổ nhìn chằm chằm, ẩn dụ cho người rình chờ cơ hội tấn công.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 目 (mục — mắt) là thành phần biểu nghĩa, 冘 là thành phần biểu âm (dān). 眈 mang nghĩa nhìn chằm chằm, thường dùng trong từ ghép 眈眈 hoặc thành ngữ 虎视眈眈 (hổ nhìn chằm chằm, chờ thời cơ). Glyph tiểu triện được xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "mê mải, đắm đuối", "Hạng Tần Suất (Jun Da)": "3970.0", "Tần Suất % (Jun Da)": "99.7353884404", "GavinGrover_Once (Chiết tự trực tiếp)": "目 + 冘", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰目冘", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "冘", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "目", "Unihan_Simplified (Chữ Giản thể)": "眈", "Unihan_Traditional (Chữ Phồn thể)": "眈", "Pinyin_Xie": "dān", "Âm Hán Việt_Xie": "đam", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường dùng trong cấu trúc lặp để miêu tả ánh mắt nhìn chăm chú hoặc rình rập. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('罡', '{"9000": "3971.0", "Chữ Trung Quốc": "罡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 网 | Số nét | 10 | nét | 罡 | cương | tượng hình | sao cương (Bắc Đẩu), khí cương mạnh | 罡 không có glyph origin trong Wiktionary. Chữ gồm bộ 网/罒 (lưới) ở trên và 正 (chính) ở dưới, nhưng không có phân tích học thuật xác nhận. Dùng chủ yếu trong đạo giáo và văn học cổ với nghĩa sao Bắc Đẩu, khí thiêng mạnh mẽ.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cương\": khí cương mạnh (罡) từ trời xuống — chữ này gắn với 天罡 (thiên cương), khí lực mạnh nhất trong vũ trụ Đạo giáo. | Gương Hán-Việt | cương — trong tiếng Việt: 天罡 (thiên cương) là từ Đạo giáo chỉ khí thiêng sao Bắc Đẩu. | Mở khoá kiến thức | Biết 罡 giúp hiểu thuật ngữ Đạo giáo: 天罡 (thiên cương), 罡气 (cương khí — khí mạnh, dữ tợn).", "Tự nguyên_Xie": "Wiktionary không cung cấp glyph origin cho 罡. Chữ cổ dùng trong Đạo giáo để chỉ ''thiên罡'' — khí thiêng của sao Bắc Đẩu. Có thể gồm 网 (lưới trời) + 正 (chính), nhưng không có nguồn học thuật xác nhận. chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: thiên cương 天罡)", "Hạng Tần Suất (Jun Da)": "3971.0", "Tần Suất % (Jun Da)": "99.7356933436", "GavinGrover_Once (Chiết tự trực tiếp)": "罒 + 正", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱罒正", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "正", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "罒", "Unihan_Simplified (Chữ Giản thể)": "罡", "Unihan_Traditional (Chữ Phồn thể)": "罡", "Pinyin_Xie": "gāng", "Âm Hán Việt_Xie": "cương", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng trong thuật ngữ đạo giáo hoặc thiên văn cổ để chỉ các chòm sao. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('缮', '{"9000": "3972.0", "Chữ Trung Quốc": "缮", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 15 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, vải | 善 | thiện | biểu âm | tốt lành (biểu âm: shàn) | 缮 = 糸 (Mịch, biểu nghĩa: sợi tơ, vải) + 善 (Thiện, biểu âm: shàn); chủ yếu là chữ hình thanh. Bộ 糸 liên quan đến vải vóc, ám chỉ hành động vá víu, sửa chữa; 善 chỉ âm đọc. Ngoài ra có thể hiểu theo hội ý: ''làm cho tốt lại'' (善 = tốt).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"thiện\": sợi tơ (糸) cần được thiện (善) — tu sửa lại cho tốt, như 修缮 (tu bổ công trình) hay 缮写 (chép lại văn bản). | Gương Hán-Việt | thiện — trong tiếng Việt: 修缮 (tu thiện/tu bổ) là từ Hán-Việt chỉ sửa chữa, bảo trì. | Mở khoá kiến thức | Biết 缮 giúp hiểu 修缮 (tu bổ, sửa chữa công trình) và 缮写 (chép lại, sao chép văn bản).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 糸 (sợi tơ/vải) là thành phần biểu nghĩa, 善 (thiện — tốt) là thành phần biểu âm (shàn). Wiktionary cũng ghi nhận khả năng hội ý: ''tu sửa, làm cho tốt lại''. 缮 mang nghĩa tu bổ, sửa chữa, chép lại (văn bản). Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sửa chữa", "Hạng Tần Suất (Jun Da)": "3972.0", "Tần Suất % (Jun Da)": "99.73599773", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 善", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟善", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "善", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "缮", "Unihan_Traditional (Chữ Phồn thể)": "繕", "Pinyin_Xie": "shàn", "Âm Hán Việt_Xie": "thiện", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ làm tân ngữ để chỉ việc sửa sang hoặc sao chép. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('胤', '{"9000": "3973.0", "Chữ Trung Quốc": "胤", "Bộ thủ & thành phần_Xie": "Bộ thủ | 肉 | Số nét | 9 | nét | 八 | bát | hội ý | chia tách, phân ra | 幺 | yêu | hội ý | sợi chỉ, nối tiếp | 肉 | nhục | hội ý | thịt, máu huyết | 胤 = 八 (Bát: chia tách) + 幺 (Yêu: sợi chỉ nối tiếp) + 肉 (Nhục: thịt/huyết mạch); chữ hội ý. 肉 tượng trưng huyết thống, 幺 tượng trưng sự kéo dài, 八 tượng trưng sự phân nhánh — hợp lại chỉ dòng dõi được truyền nối.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"dận\": huyết nhục (肉) được sợi chỉ (幺) kéo dài, phân nhánh (八) — đó là 胤 (dận), dòng dõi con cháu nối tiếp mãi mãi. | Gương Hán-Việt | dận — ít dùng trong tiếng Việt hiện đại; gặp trong tên người và văn học cổ với nghĩa dòng dõi, hậu duệ. | Mở khoá kiến thức | Biết 胤 giúp hiểu từ văn học: 胤嗣 (dận tự — con cái nối dõi), 后胤 (hậu duệ).", "Tự nguyên_Xie": "Kim văn | Tiểu triện | Lục thư thông | Chữ hội ý: 肉 (nhục — máu huyết) đại diện huyết thống, 幺 (sợi chỉ) đại diện sự nối dài, 八 (chia tách) đại diện sự phân nhánh dòng họ. Ba thành phần kết hợp chỉ con cháu, dòng dõi được truyền nối. Kim văn và tiểu triện đều xác nhận cấu trúc này. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nối dõi", "Hạng Tần Suất (Jun Da)": "3973.0", "Tần Suất % (Jun Da)": "99.7363021165", "GavinGrover_Once (Chiết tự trực tiếp)": "儿 + No glyph available", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴儿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "", "Unihan_Simplified (Chữ Giản thể)": "胤", "Unihan_Traditional (Chữ Phồn thể)": "胤", "Pinyin_Xie": "yìn", "Âm Hán Việt_Xie": "dận", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng trong văn viết cổ để chỉ dòng dõi hậu duệ hoặc việc kế thừa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('皋', '{"9000": "3974.0", "Chữ Trung Quốc": "皋", "Bộ thủ & thành phần_Xie": "Bộ thủ | 白 | Số nét | 10 | nét | 白 | bạch | hội ý | trắng, sáng | 夲 | thao | hội ý | tiến tới, tiến lên | 皋 = 白 (Bạch: trắng/sáng) + 夲 (Thao: tiến tới); chữ hội ý, tuy nhiên Wiktionary ghi nhận kết nối với nghĩa hiện đại không rõ ràng. 皋 có nghĩa bờ đầm lầy cao ráo, đất cao bên sông.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"cao\": bờ cao (皋) trắng sáng (白) bên sông — hình ảnh bờ đầm lầy cao ráo, nơi cỏ trắng mọc dày. | Gương Hán-Việt | cao — trong tiếng Việt: 皋 ít gặp riêng lẻ; biết qua tên 皋陶 (Cao Dao) — vị thần luật pháp huyền thoại Trung Quốc. | Mở khoá kiến thức | Biết 皋 giúp nhận diện địa danh: 皋兰 (Cao Lan), và tên người lịch sử 皋陶 (Cao Dao).", "Tự nguyên_Xie": "Tiểu triện | Chữ hội ý: 白 (bạch — trắng, sáng) + 夲 (tiến tới), nhưng Wiktionary thừa nhận kết nối với nghĩa hiện đại (bờ cao bên sông/đầm lầy) không rõ ràng. Glyph tiểu triện xác nhận. 皋 thường gặp trong địa danh và tên người, đặc biệt nổi tiếng qua 皋陶 (Cao Dao — nhân vật huyền thoại). | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khấn, vái; bờ, bãi", "Hạng Tần Suất (Jun Da)": "3974.0", "Tần Suất % (Jun Da)": "99.7366059861", "GavinGrover_Once (Chiết tự trực tiếp)": "白 + 夲", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱白夲", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夲", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "白", "Unihan_Simplified (Chữ Giản thể)": "皋", "Unihan_Traditional (Chữ Phồn thể)": "皋", "Pinyin_Xie": "gāo", "Âm Hán Việt_Xie": "cao", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Động từ | 动词 | Thường dùng làm danh từ chỉ địa hình ven nước hoặc dùng trong tên người cổ. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('蛀', '{"9000": "3975.0", "Chữ Trung Quốc": "蛀", "Bộ thủ & thành phần_Xie": "Bộ thủ | 虫 | Số nét | 11 | nét | 虫 | trùng | biểu nghĩa | sâu, côn trùng | 主 | chủ | biểu âm | (biểu âm: zhù) | 蛀 = 虫 (Trùng, biểu nghĩa: sâu/côn trùng) + 主 (Chủ, biểu âm: zhù); chữ hình thanh. Bộ 虫 cho biết đây là loài sâu bọ, 主 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"chấu\": con trùng (虫) làm chủ (主) — sâu chấu đục khoét, chiếm lĩnh bên trong; 蛀虫 là sâu mọt ăn gỗ. | Gương Hán-Việt | chấu — tiếng Việt: ''sâu chấu'' hay ''sâu mọt''; 蛀虫 dịch là sâu đục khoét. | Mở khoá kiến thức | Biết 蛀 giúp hiểu 蛀虫 (sâu mọt), 蛀牙 (sâu răng — răng bị sâu đục), 防蛀 (chống sâu mọt).", "Tự nguyên_Xie": "Chữ hình thanh: 虫 (trùng — sâu, côn trùng) là thành phần biểu nghĩa, 主 (chủ — chủ nhân) là thành phần biểu âm (zhù). 蛀 chỉ loài sâu đục khoét gỗ, vải, lương thực; cũng dùng theo nghĩa bóng chỉ kẻ ăn bám, tham nhũng. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "con mọt; vật bị mọt", "Hạng Tần Suất (Jun Da)": "3975.0", "Tần Suất % (Jun Da)": "99.7369098558", "GavinGrover_Once (Chiết tự trực tiếp)": "虫 + 主", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰虫主", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "主", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "虫", "Unihan_Simplified (Chữ Giản thể)": "蛀", "Unihan_Traditional (Chữ Phồn thể)": "蛀", "Pinyin_Xie": "zhù", "Âm Hán Việt_Xie": "chú", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường làm động từ chỉ hành động côn trùng đục khoét gỗ hoặc làm danh từ. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('偌', '{"9000": "3976.0", "Chữ Trung Quốc": "偌", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 10 | nét | 人 | nhân | biểu nghĩa | người | 若 | nhược | biểu âm | (biểu âm: ruò → nuò) | 偌 = 人/亻 (Nhân, biểu nghĩa: người) + 若 (Nhược, biểu âm: ruò); chữ hình thanh. Bộ 人 liên quan đến người/hành động người, 若 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"nhược\": người (人) làm theo như nhược (若) — 偌大 là ''lớn như vậy'', nhấn mạnh mức độ lớn khó ngờ. | Gương Hán-Việt | nhược — ít dùng riêng trong tiếng Việt; nghĩa ''như thế, như vậy'' trong văn ngữ. | Mở khoá kiến thức | Biết 偌 giúp hiểu 偌大 (ruòdà) — to như vậy, lớn đến thế; dùng để nhấn mạnh kích thước ấn tượng.", "Tự nguyên_Xie": "Chữ hình thanh: 人 (nhân — người) là thành phần biểu nghĩa, 若 (nhược — như thế nào) là thành phần biểu âm (ruò → nuò). 偌 mang nghĩa ''như vậy'', ''như thế'', dùng trong văn ngữ và một số phương ngữ. Thường gặp trong 偌大 (to như vậy, lớn đến thế). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "như thế", "Hạng Tần Suất (Jun Da)": "3976.0", "Tần Suất % (Jun Da)": "99.7372132087", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 若", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻若", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "若", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "偌", "Unihan_Traditional (Chữ Phồn thể)": "偌", "Pinyin_Xie": "ruò", "Âm Hán Việt_Xie": "nhạ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Đại từ | 代词 | Chữ này làm đại từ chỉ thị thường đứng trước tính từ để biểu thị mức độ to lớn hoặc nhiều. | Đại từ | 代词 | Thay cho người hoặc vật đã nhắc tới (我, 这, 谁). Dùng đúng ở vị trí của danh từ. Chỉ người thì thêm 们 để thành số nhiều: 我们.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('疵', '{"9000": "3977.0", "Chữ Trung Quốc": "疵", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 11 | nét | 疵 | tì | tượng hình | vết nứt nhỏ, tì vết | 疵 không có phân tích thành phần rõ ràng từ Wiktionary. Nhìn tổng thể có bộ 疒 (bệnh tật) và một thành phần phía dưới, nhưng cấu trúc không được xác nhận học thuật. Dùng với nghĩa vết nứt nhỏ, tì vết, khuyết điểm.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tì\": tì vết (疵) nhỏ xíu — như hạt cát trong ngọc quý, đủ phá vỡ sự hoàn hảo. 瑕疵 là vết nứt trên ngọc. | Gương Hán-Việt | tì — trong tiếng Việt: ''tì vết'' là từ Hán-Việt mượn từ 疵, chỉ khuyết điểm nhỏ. | Mở khoá kiến thức | Biết 疵 giúp hiểu 瑕疵 (hà tì — khuyết điểm nhỏ) và thành ngữ 吹毛求疵 (bới lông tìm vết).", "Tự nguyên_Xie": "Bạch thư | Tiểu triện | Wiktionary không cung cấp phân tích hội ý hay hình thanh rõ ràng cho 疵. Glyph bạch thư và tiểu triện được xác nhận. 疵 có nghĩa tì vết nhỏ, khuyết điểm nhỏ; thường gặp trong 瑕疵 (vết trầy trên ngọc — khuyết điểm), 吹毛求疵 (thổi lông tìm sẹo — bới lông tìm vết). Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khuyết điểm; tì vết; thiếu sót; lỗi; tỳ vết", "Hạng Tần Suất (Jun Da)": "3977.0", "Tần Suất % (Jun Da)": "99.7375160448", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 此", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒此", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "此", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "疵", "Unihan_Traditional (Chữ Phồn thể)": "疵", "Pinyin_Xie": "cī", "Âm Hán Việt_Xie": "tì", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường kết hợp để tạo thành các từ ghép chỉ lỗi lầm hoặc khuyết điểm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('绛', '{"9000": "3978.0", "Chữ Trung Quốc": "绛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 糸 | Số nét | 9 | nét | 糸 | mịch | biểu nghĩa | sợi tơ, lụa | 夅 | giáng | biểu âm | (biểu âm: jiàng) | 绛 = 糸 (Mịch, biểu nghĩa: sợi tơ/lụa) + 夅 (Giáng, biểu âm: jiàng); chữ hình thanh. Bộ 糸 cho biết liên quan đến vải lụa, màu sắc vải; 夅 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giáng\": lụa (糸) nhuộm màu giáng (xuống đậm) — 绛红 là màu đỏ thẫm, màu máu đậm, sang trọng trong cung đình xưa. | Gương Hán-Việt | giáng — ít dùng riêng trong tiếng Việt; nghĩa là màu đỏ thẫm, đỏ sẫm. | Mở khoá kiến thức | Biết 绛 giúp hiểu 绛红 (đỏ thẫm), 绛紫 (tím đỏ) — các tên màu trong văn học và thời trang Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 糸 (sợi tơ/lụa) là thành phần biểu nghĩa, 夅 là thành phần biểu âm (jiàng). 绛 mang nghĩa màu đỏ thẫm, đỏ sẫm — màu của lụa nhuộm đỏ. Cũng là tên cổ kinh đô nhà Tấn (绛都). Glyph tiểu triện và lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "màu đỏ", "Hạng Tần Suất (Jun Da)": "3978.0", "Tần Suất % (Jun Da)": "99.7378188808", "GavinGrover_Once (Chiết tự trực tiếp)": "纟 + 夅", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰纟夅", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夅", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "纟", "Unihan_Simplified (Chữ Giản thể)": "绛", "Unihan_Traditional (Chữ Phồn thể)": "絳", "Pinyin_Xie": "jiàng", "Âm Hán Việt_Xie": "giáng", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ màu sắc đỏ thẫm hoặc làm danh từ chỉ sắc đỏ trong văn viết cổ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('葆', '{"9000": "3979.0", "Chữ Trung Quốc": "葆", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 12 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 保 | bảo | biểu âm | (biểu âm: bǎo) | 葆 = 艸/艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 保 (Bảo, biểu âm: bǎo); chữ hình thanh. Bộ 艹 cho biết liên quan đến thực vật, 保 chỉ âm đọc. Nghĩa gốc là cỏ um tùm, rậm rạp; nghĩa mở rộng là giữ gìn, bảo tồn.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"bảo\": cỏ (艹) cần được bảo (保) — 葆 là giữ gìn, bảo tồn; 永葆青春 là mãi giữ được tuổi trẻ. | Gương Hán-Việt | bảo — trong tiếng Việt: 葆 dùng trong văn học cao cấp với nghĩa bảo tồn, giữ gìn; 永葆 (vĩnh bảo) = giữ mãi. | Mở khoá kiến thức | Biết 葆 giúp đọc văn học và khẩu hiệu: 永葆青春 (vĩnh viễn giữ được tuổi trẻ), 葆真 (giữ gìn sự chân thật).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Chữ hình thanh: 艸 (thảo — cỏ) là thành phần biểu nghĩa, 保 (bảo — giữ gìn) là thành phần biểu âm (bǎo). 葆 có nghĩa gốc là đám cỏ rậm; nghĩa mở rộng (thường dùng hơn) là bảo tồn, giữ gìn (thay cho 保). Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cỏ mọc um tùm; giấu kỹ; rộng lớn", "Hạng Tần Suất (Jun Da)": "3979.0", "Tần Suất % (Jun Da)": "99.7381201666", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 保", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹保", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "保", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "葆", "Unihan_Traditional (Chữ Phồn thể)": "葆", "Pinyin_Xie": "bǎo", "Âm Hán Việt_Xie": "bảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Chữ này làm động từ thường dùng trong văn viết với nghĩa bảo tồn hoặc giữ gìn sức khỏe. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('黔', '{"9000": "3980.0", "Chữ Trung Quốc": "黔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 黑 | Số nét | 16 | nét | 黑 | hắc | biểu nghĩa | màu đen | 今 | kim | biểu âm | (biểu âm: jīn → qián) | 黔 = 黑 (Hắc, biểu nghĩa: đen) + 今 (Kim, biểu âm: jīn → qián); chữ hình thanh. Bộ 黑 cho biết liên quan đến màu đen, 今 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiềm\": đen (黑) như cái kim (今) cắm vào đất đen — 黔 là tên tỉnh Quý Châu, vùng đất tối màu trong sử Trung Quốc. | Gương Hán-Việt | kiềm — trong tiếng Việt: 黔 (kiềm) ít dùng riêng; biết qua 黔驴技穷 (lừa Quý Châu cạn mưu). | Mở khoá kiến thức | Biết 黔 giúp hiểu tên tắt tỉnh Quý Châu (黔) và thành ngữ 黔驴技穷 (cạn mưu, đuối lý).", "Tự nguyên_Xie": "Chữ hình thanh: 黑 (hắc — đen) là thành phần biểu nghĩa, 今 (kim) là thành phần biểu âm. 黔 có nghĩa đen, đen sẫm; cũng là tên tắt của tỉnh Quý Châu (贵州). Thành ngữ nổi tiếng: 黔驴技穷 (lừa Quý Châu cạn mưu — ví kẻ tài hèn bị lộ). Chưa có glyph giáp cốt/kim văn. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đen; họ Kiềm", "Hạng Tần Suất (Jun Da)": "3980.0", "Tần Suất % (Jun Da)": "99.7384209355", "GavinGrover_Once (Chiết tự trực tiếp)": "黑 + 今", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰黑今", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "今", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "黑", "Unihan_Simplified (Chữ Giản thể)": "黔", "Unihan_Traditional (Chữ Phồn thể)": "黔", "Pinyin_Xie": "qián", "Âm Hán Việt_Xie": "kiềm", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Danh từ | 名词 | Chữ này làm tính từ chỉ màu đen hoặc làm danh từ riêng chỉ tỉnh Quý Châu của Trung Quốc. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('喙', '{"9000": "3981.0", "Chữ Trung Quốc": "喙", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 12 | nét | 口 | khẩu | biểu nghĩa | miệng | 彖 | đoán | biểu âm | (biểu âm: tuàn → huì) | 喙 = 口 (Khẩu, biểu nghĩa: miệng) + 彖 (Đoán, biểu âm: tuàn); chữ hình thanh. Bộ 口 cho biết liên quan đến miệng/mỏ, 彖 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trác\": miệng (口) nhọn như cái trác — 喙 là mỏ chim nhọn sắc, hoặc bóng nghĩa là ''chen miệng vào'' trong thành ngữ. | Gương Hán-Việt | trác — ít dùng riêng trong tiếng Việt; gặp trong văn học với nghĩa mỏ nhọn, chen miệng. | Mở khoá kiến thức | Biết 喙 giúp hiểu thành ngữ 无从置喙 (không thể chen miệng, không có lời bàn) và 鸟喙 (mỏ chim).", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 口 (khẩu — miệng) là thành phần biểu nghĩa, 彖 là thành phần biểu âm. 喙 có nghĩa mỏ (của chim, thú), miệng nhọn; thành ngữ 无从置喙 (không có chỗ chen miệng vào — không thể xen vào) rất phổ biến. Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "miệng; bàn nói; thở ngắn hơi, thở gấp, thở hổn hển", "Hạng Tần Suất (Jun Da)": "3981.0", "Tần Suất % (Jun Da)": "99.7387217045", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 彖", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口彖", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "彖", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "喙", "Unihan_Traditional (Chữ Phồn thể)": "喙", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "uế", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận mỏ của loài chim hoặc miệng của loài thú. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('烽', '{"9000": "3982.0", "Chữ Trung Quốc": "烽", "Bộ thủ & thành phần_Xie": "Bộ thủ | 火 | Số nét | 11 | nét | 火 | hoả | biểu nghĩa | lửa | 夆 | phùng | biểu âm | (biểu âm: féng → fēng) | 烽 = 火 (Hoả, biểu nghĩa: lửa) + 夆 (Phùng, biểu âm: fēng); chữ hình thanh. Bộ 火 cho biết đây là lửa, cụ thể là lửa hiệu, 夆 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phong\": lửa (火) phong trào (夆) — 烽火 là lửa chiến tranh bùng lên khắp nơi, như đốm lửa hiệu lan rộng. | Gương Hán-Việt | phong — trong tiếng Việt: 烽火 (phong hoả) là từ Hán-Việt chỉ chiến tranh, lửa binh. | Mở khoá kiến thức | Biết 烽 giúp hiểu 烽火 (phong hoả — lửa chiến tranh), 烽烟 (khói lửa binh đao), 烽火台 (đài lửa hiệu trên Vạn Lý Trường Thành).", "Tự nguyên_Xie": "Chữ hình thanh: 火 (hoả — lửa) là thành phần biểu nghĩa, 夆 là thành phần biểu âm (fēng). 烽 chỉ lửa hiệu trên đài cao — phương tiện thông tin liên lạc quân sự thời cổ đại. Khi giặc đến, đốt lửa trên tháp canh để truyền tín hiệu. Gặp trong 烽火 (phong hoả — lửa chiến tranh) và 烽烟 (khói lửa chiến trận). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đốt lửa làm hiệu", "Hạng Tần Suất (Jun Da)": "3982.0", "Tần Suất % (Jun Da)": "99.7390219566", "GavinGrover_Once (Chiết tự trực tiếp)": "火 + 夆", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰火夆", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夆", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "火", "Unihan_Simplified (Chữ Giản thể)": "烽", "Unihan_Traditional (Chữ Phồn thể)": "烽", "Pinyin_Xie": "fēng", "Âm Hán Việt_Xie": "phong", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ thường dùng trong các từ ghép liên quan đến chiến tranh hoặc lửa báo hiệu thời xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('儡', '{"9000": "3983.0", "Chữ Trung Quốc": "儡", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 17 | nét | 亻 | nhân | biểu nghĩa | người | 畾 | lôi | biểu âm | (biểu âm: léi → lěi) | 儡 = 亻 (Nhân, biểu nghĩa: người) + 畾 (Lôi, biểu âm: léi); chữ hình thanh. Bộ 亻 cho biết liên quan đến người, 畾 chỉ âm đọc. 儡 chỉ xuất hiện trong 傀儡 (bù nhìn, người bị điều khiển).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lỗi\": người (亻) bị điều khiển như búp bê lỗi (畾) — 傀儡 là bù nhìn, kẻ không có thực quyền. | Gương Hán-Việt | lỗi — trong tiếng Việt: 傀儡 (quỷ lỗi) là từ mượn chỉ chính phủ bù nhìn, con rối. | Mở khoá kiến thức | Biết 儡 giúp hiểu 傀儡 (quỷ lỗi/bù nhìn) — từ chính trị và văn học quan trọng, chỉ người/chính quyền bị điều khiển.", "Tự nguyên_Xie": "Tiểu triện | Chữ hình thanh: 亻 (nhân — người) là thành phần biểu nghĩa, 畾 là thành phần biểu âm (lěi). 儡 chỉ dùng trong từ ghép 傀儡 — con bù nhìn, người/chính phủ bị điều khiển bởi thế lực khác. Glyph tiểu triện xác nhận. Dùng độc lập rất hiếm. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "tượng gỗ", "Hạng Tần Suất (Jun Da)": "3983.0", "Tần Suất % (Jun Da)": "99.7393222088", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 畾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻畾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "畾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "儡", "Unihan_Traditional (Chữ Phồn thể)": "儡", "Pinyin_Xie": "lěi", "Âm Hán Việt_Xie": "lỗi", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Chữ này làm danh từ thường xuất hiện trong từ ghép chỉ con rối gỗ hoặc làm tính từ chỉ sự mệt mỏi rã rời. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('佼', '{"9000": "3984.0", "Chữ Trung Quốc": "佼", "Bộ thủ & thành phần_Xie": "Bộ thủ | 人 | Số nét | 8 | nét | 佼 | kiểu | tượng hình | đẹp đẽ, xuất sắc | 佼 không có phân tích thành phần rõ ràng từ Wiktionary. Có thể chứa bộ 人 (nhân) và một thành phần khác, nhưng không được xác nhận học thuật. Dùng với nghĩa đẹp đẽ, xuất sắc, nổi bật — thường gặp trong 佼佼者 (người xuất sắc).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiểu\": dáng kiều (kiểu) diễm — 佼佼者 là người xuất sắc, đứng cao hơn đám đông như cây cao giữa rừng. | Gương Hán-Việt | kiểu — ít dùng riêng trong tiếng Việt; gặp trong 佼佼者 (người xuất sắc). | Mở khoá kiến thức | Biết 佼 giúp hiểu 佼佼者 (kẻ xuất sắc hơn người) — từ hay dùng trong văn học và diễn thuyết Trung Quốc.", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | Wiktionary không cung cấp phân tích hình thanh hay hội ý cho 佼. Glyph tiểu triện và lục thư thông được xác nhận. 佼 có nghĩa đẹp đẽ, xuất sắc; từ ghép 佼佼者 chỉ người nổi trội, xuất sắc hơn người. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "đẹp, quyến rũ, duyên dáng; nổi bật", "Hạng Tần Suất (Jun Da)": "3984.0", "Tần Suất % (Jun Da)": "99.739622461", "GavinGrover_Once (Chiết tự trực tiếp)": "亻 + 交", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰亻交", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "交", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "亻", "Unihan_Simplified (Chữ Giản thể)": "佼", "Unihan_Traditional (Chữ Phồn thể)": "佼", "Pinyin_Xie": "jiǎo", "Âm Hán Việt_Xie": "giảo", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường dùng để miêu tả vẻ đẹp của con người hoặc sự nổi bật, xuất chúng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('斓', '{"9000": "3985.0", "Chữ Trung Quốc": "斓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 文 | Số nét | 16 | nét | 斓 | lan | tượng hình | sặc sỡ, nhiều màu rực rỡ | 斓 là giản thể của 斕. Chữ gốc 斕 có cấu trúc phức tạp nhưng Wiktionary không cung cấp phân tích thành phần. Dùng với nghĩa sặc sỡ, nhiều màu rực rỡ — thường trong 斑斓 (ban lan: rực rỡ sặc sỡ).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"lan\": màu sắc lan (lan toả) rực rỡ — 斑斓 là sắc màu đan xen tươi sáng, như cầu vồng sau mưa. | Gương Hán-Việt | lan — ít dùng riêng trong tiếng Việt; gặp qua 斑斓 (ban lan — sặc sỡ). | Mở khoá kiến thức | Biết 斓 giúp hiểu 斑斓 (ban lan) — sặc sỡ, nhiều màu rực rỡ; từ hay dùng trong văn học và mô tả thiên nhiên.", "Tự nguyên_Xie": "斓 là giản thể của 斕. Chữ phồn thể 斕 không có phân tích hội ý hay hình thanh rõ ràng từ Wiktionary. 斓 thường xuất hiện trong từ ghép 斑斓 (ban lan) với nghĩa sặc sỡ, nhiều màu đan xen rực rỡ. Chưa có nguồn học thuật phân tích cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: ban lan 斒斕)", "Hạng Tần Suất (Jun Da)": "3985.0", "Tần Suất % (Jun Da)": "99.7399227131", "GavinGrover_Once (Chiết tự trực tiếp)": "文 + 阑", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰文阑", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "阑", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "文", "Unihan_Simplified (Chữ Giản thể)": "斓", "Unihan_Traditional (Chữ Phồn thể)": "斕", "Pinyin_Xie": "lán", "Âm Hán Việt_Xie": "lan", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Chữ này làm tính từ thường kết hợp trong từ ghép để miêu tả màu sắc sặc sỡ, rực rỡ. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('嫔', '{"9000": "3986.0", "Chữ Trung Quốc": "嫔", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 13 | nét | 女 | nữ | biểu nghĩa | phụ nữ | 賓 | tân | biểu âm | (biểu âm: bīn → pín) | 嫔 = 女 (Nữ, biểu nghĩa: phụ nữ) + 賓 (Tân, biểu âm: bīn); chữ hình thanh. Bộ 女 cho biết đây là loại phụ nữ trong cung đình, 賓 chỉ âm đọc và cũng gợi ý ''quy thuận, phục tùng''.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tần\": người nữ (女) quy thuận như khách tân (賓) trong cung — 嫔妃 là phi tần, cung nữ bậc cao trong hoàng cung. | Gương Hán-Việt | tần — trong tiếng Việt: 嫔妃 (tần phi) là từ Hán-Việt chỉ phi tần trong hoàng cung. | Mở khoá kiến thức | Biết 嫔 giúp hiểu cấp bậc hậu cung: 皇后 (hoàng hậu) → 贵妃 (quý phi) → 嫔 (tần) → 贵人.", "Tự nguyên_Xie": "Giáp cốt văn | Tiểu triện | Lục thư thông | Chữ hình thanh: 女 (nữ — phụ nữ) là thành phần biểu nghĩa, 賓 (tân — khách, quy thuận) là thành phần biểu âm. Wiktionary ghi nhận 賓 cũng có nghĩa ''quy thuận, phục tùng'', nên 嫔 ám chỉ ''người phụ nữ quy phục trong cung''. Giáp cốt văn, tiểu triện, lục thư thông đều xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: phi tần 妃嬪)", "Hạng Tần Suất (Jun Da)": "3986.0", "Tần Suất % (Jun Da)": "99.7402219317", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 宾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女宾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "宾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "嫔", "Unihan_Traditional (Chữ Phồn thể)": "嬪", "Pinyin_Xie": "pín", "Âm Hán Việt_Xie": "tần", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ tước vị của các cung phi trong cung đình phong kiến xưa. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('颚', '{"9000": "3987.0", "Chữ Trung Quốc": "颚", "Bộ thủ & thành phần_Xie": "Bộ thủ | 頁 | Số nét | 15 | nét | 颚 | ngạc | tượng hình | hàm, xương hàm | 颚 là giản thể của 顎. Chữ phồn thể 顎 = 咢 (biểu âm: è) + 頁 (Hiệt, biểu nghĩa: đầu/mặt); chữ hình thanh. Bộ 頁/页 cho biết liên quan đến đầu mặt, 咢 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngạc\": xương ngạc (hàm) — 颚 là xương hàm, phần cứng nhất của khuôn mặt; 上颚 là hàm trên, 下颚 là hàm dưới. | Gương Hán-Việt | ngạc — trong tiếng Việt: ''hàm ngạc'' hay ''上颚'' (thượng ngạc) là thuật ngữ y học chỉ vòm miệng cứng. | Mở khoá kiến thức | Biết 颚 giúp đọc thuật ngữ y/nha khoa: 上颚 (hàm trên), 下颚 (hàm dưới), 颚骨 (xương hàm).", "Tự nguyên_Xie": "颚 là giản thể của 顎. Chữ phồn thể 顎 = 咢 (biểu âm: è) + 頁 (hiệt — đầu/mặt), chữ hình thanh. 颚 chỉ xương hàm, răng hàm — phần xương ở hàm trên và hàm dưới. Thường gặp trong thuật ngữ y học: 上颚 (hàm trên), 下颚 (hàm dưới). Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy trung bình", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hàm, quai hàm", "Hạng Tần Suất (Jun Da)": "3987.0", "Tần Suất % (Jun Da)": "99.7405211503", "GavinGrover_Once (Chiết tự trực tiếp)": "咢 + 页", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰咢页", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "咢", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "页", "Unihan_Simplified (Chữ Giản thể)": "颚", "Unihan_Traditional (Chữ Phồn thể)": "顎", "Pinyin_Xie": "è", "Âm Hán Việt_Xie": "ngạc", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Chữ này làm danh từ chỉ bộ phận xương hàm của người hoặc động vật trong giải phẫu học. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('龈', '{"9000": "3988.0", "Chữ Trung Quốc": "龈", "Bộ thủ & thành phần_Xie": "Bộ thủ | 齒 | Số nét | 14 | nét | 龈 | ngân | tượng hình | lợi răng, nướu | 龈 là giản thể của 齦. Chữ phồn thể 齦 = 齒 (Xỉ, biểu nghĩa: răng) + 斤 (Cân, biểu âm: jīn → yín); chữ hình thanh. Bộ 齒/齿 cho biết liên quan đến răng, 斤 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngân\": nướu ngân (ngân — bạc trắng) bao quanh chân răng — 牙龈 là lợi răng, dễ bị viêm khi không vệ sinh tốt. | Gương Hán-Việt | ngân — ít dùng riêng trong tiếng Việt; gặp trong thuật ngữ y tế qua 牙龈 (nướu răng). | Mở khoá kiến thức | Biết 龈 giúp đọc thuật ngữ nha khoa: 牙龈 (nướu/lợi răng), 龈炎 (viêm lợi), 牙龈出血 (chảy máu nướu).", "Tự nguyên_Xie": "Tiểu triện | Lục thư thông | 龈 là giản thể của 齦. Chữ phồn thể 齦 = 齒 (xỉ — răng) là thành phần biểu nghĩa, 斤 (cân — chiếc rìu) là thành phần biểu âm. 龈 chỉ lợi răng (nướu) — phần mô mềm bao quanh chân răng. Thường gặp trong thuật ngữ nha khoa: 牙龈 (lợi/nướu răng). Glyph tiểu triện và lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy trung bình · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "nhằn xương, gặm xương", "Hạng Tần Suất (Jun Da)": "3988.0", "Tần Suất % (Jun Da)": "99.7408203689", "GavinGrover_Once (Chiết tự trực tiếp)": "齿 + 艮", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰齿艮", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "艮", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "齿", "Unihan_Simplified (Chữ Giản thể)": "龈", "Unihan_Traditional (Chữ Phồn thể)": "齦", "Pinyin_Xie": "kěn", "Âm Hán Việt_Xie": "ngân", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Chữ này thường làm động từ biểu thị hành động gặm nhằn hoặc làm danh từ chỉ lợi răng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('盅', '{"9000": "3989.0", "Chữ Trung Quốc": "盅", "Bộ thủ & thành phần_Xie": "Bộ thủ | 皿 | Số nét | 9 | nét | 中 | trung | biểu âm | (biểu âm: zhōng → zhōng) | 皿 | mãnh | biểu nghĩa | đĩa, đồ đựng | 盅 = 中 (Trung, biểu âm: zhōng) + 皿 (Mãnh, biểu nghĩa: đồ đựng, chén bát); chữ hình thanh. Bộ 皿 cho biết đây là đồ dùng để đựng thức ăn/đồ uống, 中 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"trung\": đồ đựng (皿) ở giữa (中) — 盅 là chén nhỏ tròn đựng trà hay rượu, đặt ngay ngắn giữa bàn trà. | Gương Hán-Việt | trung — ít dùng riêng trong tiếng Việt; 盅 chỉ chén nhỏ trong văn hoá uống trà Trung Quốc. | Mở khoá kiến thức | Biết 盅 giúp hiểu 酒盅 (chén rượu nhỏ), 茶盅 (chén trà) — đồ dùng quan trọng trong văn hoá trà đạo Trung Quốc.", "Tự nguyên_Xie": "Kim văn | Chữ hình thanh: 皿 (mãnh — đồ đựng, chén bát) là thành phần biểu nghĩa, 中 (trung) là thành phần biểu âm. 盅 chỉ chén nhỏ, cốc nhỏ không tay cầm dùng để uống trà hoặc rượu. Thường dùng trong văn học và văn hoá uống trà truyền thống. Kim văn xác nhận glyph. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "463.0", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "Mãnh (98) Trung (171)", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "Chữ Trung (số 10 - ở giữa) ở trên chữ Mãnh (số 108 - bát đĩa) . Vật dụng bằng gốm sứ bát đĩa (Mãnh) thường được đặt ở giữa (Trung) bàn uống trà gọi là cái chén (chung). Giải thích sự chuyển ý: Chữ Trung (ở giữa) chỉ âm, chữ Mãnh (bát đĩa sứ) chỉ ý. Đồ dùng nhỏ bằng gốm sứ để đựng nước, rượu (Mãnh) gọi là chén (Chung). *(Biến âm Hán Việt: Trung -> Chung)*", "Nghĩa Tiếng Việt_Xie": "đồ chưa đựng gì; cái chén nhỏ", "Hạng Tần Suất (Jun Da)": "3989.0", "Tần Suất % (Jun Da)": "99.7411190707", "GavinGrover_Once (Chiết tự trực tiếp)": "中 + 皿", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱中皿", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "中", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "皿", "Unihan_Simplified (Chữ Giản thể)": "盅", "Unihan_Traditional (Chữ Phồn thể)": "盅", "Pinyin_Xie": "zhōng", "Âm Hán Việt_Xie": "chung", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ cái chén nhỏ hoặc làm lượng từ cho đồ uống. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('娓', '{"9000": "3990.0", "Chữ Trung Quốc": "娓", "Bộ thủ & thành phần_Xie": "Bộ thủ | 女 | Số nét | 10 | nét | 娓 | vãi | tượng hình | nhẹ nhàng, uyển chuyển, không ngừng nghỉ | 娓 không có phân tích thành phần rõ ràng từ Wiktionary. Có thể chứa bộ 女 (nữ) nhưng không được xác nhận học thuật. Dùng chủ yếu trong 娓娓 (không ngừng, uyển chuyển, cuốn hút khi nói chuyện).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"vãi\": kể chuyện vãi không hết — 娓娓道来 là kể chuyện từ từ, uyển chuyển, cuốn hút người nghe. | Gương Hán-Việt | vãi — ít dùng riêng trong tiếng Việt; gặp qua 娓娓 trong văn học. | Mở khoá kiến thức | Biết 娓 giúp hiểu 娓娓道来 (kể chuyện uyển chuyển, không ngừng) — thành ngữ mô tả cách nói chuyện cuốn hút.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 娓 có nghĩa cổ là tuân theo, quy thuận; và 娓娓 (wěiwěi) có nghĩa kể chuyện không ngừng nghỉ, uyển chuyển cuốn hút. Glyph tiểu triện xác nhận. Chưa có phân tích học thuật rõ ràng về cấu trúc. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "say sưa không dứt", "Hạng Tần Suất (Jun Da)": "3990.0", "Tần Suất % (Jun Da)": "99.7414177725", "GavinGrover_Once (Chiết tự trực tiếp)": "女 + 尾", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰女尾", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "尾", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "女", "Unihan_Simplified (Chữ Giản thể)": "娓", "Unihan_Traditional (Chữ Phồn thể)": "娓", "Pinyin_Xie": "wěi", "Âm Hán Việt_Xie": "vỉ", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Phó từ | 副词 | Thường dùng lặp lại thành vĩ vĩ để làm phó từ miêu tả cách nói chuyện sinh động, không chán. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Phó từ | 副词 | Bổ nghĩa cho động từ hoặc tính từ và luôn đứng TRƯỚC chúng — 都是, 很好. Không đứng sau như tiếng Việt và không bổ nghĩa cho danh từ.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('坂', '{"9000": "3991.0", "Chữ Trung Quốc": "坂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 7 | nét | 土 | thổ | biểu nghĩa | đất | 反 | phản | biểu âm | (biểu âm: fǎn → bǎn) | 坂 = 土 (Thổ, biểu nghĩa: đất) + 反 (Phản, biểu âm: fǎn); chữ hình thanh. Bộ 土 cho biết liên quan đến địa hình đất, 反 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"phẳng\" (nghịch nghĩa thú vị): đất (土) phản (反) lại chiều nằm ngang — tức là dốc, nghiêng; 坂 là sườn dốc. | Gương Hán-Việt | phẳng — ít dùng trong tiếng Việt; 坂 hay gặp trong địa danh Nhật Bản: 大阪 (Osaka/Đại Phản). | Mở khoá kiến thức | Biết 坂 giúp đọc địa danh: 大阪 (Osaka — Nhật Bản), và từ văn học cổ 坂路 (đường dốc).", "Tự nguyên_Xie": "Chữ hình thanh: 土 (thổ — đất) là thành phần biểu nghĩa, 反 (phản — ngược lại) là thành phần biểu âm (bǎn). 坂 có nghĩa dốc, sườn dốc — vùng đất nghiêng. Dùng trong địa danh Nhật Bản (大阪 — Osaka) và văn học Trung Quốc cổ. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "sườn núi", "Hạng Tần Suất (Jun Da)": "3991.0", "Tần Suất % (Jun Da)": "99.7417154408", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 反", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土反", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "反", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "坂", "Unihan_Traditional (Chữ Phồn thể)": "坂", "Pinyin_Xie": "bǎn", "Âm Hán Việt_Xie": "bản", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ trong địa danh để chỉ sườn dốc hoặc đường núi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('町', '{"9000": "3992.0", "Chữ Trung Quốc": "町", "Bộ thủ & thành phần_Xie": "Bộ thủ | 田 | Số nét | 7 | nét | 田 | điền | biểu nghĩa | ruộng, đồng ruộng | 丁 | đinh | biểu âm | (biểu âm: dīng → tǐng/zhèng) | 町 = 田 (Điền, biểu nghĩa: ruộng) + 丁 (Đinh, biểu âm: dīng); chữ hình thanh. Bộ 田 cho biết liên quan đến ruộng đồng, 丁 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đinh\": ruộng (田) của nhà đinh (丁) — 町 là bờ ranh chia ruộng; trong địa danh Nhật là đơn vị hành chính làng/phố. | Gương Hán-Việt | đinh — ít dùng riêng trong tiếng Việt; gặp trong địa danh Nhật Bản như 京町 (Kyōmachi). | Mở khoá kiến thức | Biết 町 giúp đọc địa danh Nhật Bản: 町 (machi) là đơn vị hành chính nhỏ hơn thị trấn, và 田町 (Tamachi) là ga tàu nổi tiếng ở Tokyo.", "Tự nguyên_Xie": "Đại triện | Tiểu triện | Chữ hình thanh: 田 (điền — ruộng) là thành phần biểu nghĩa, 丁 là thành phần biểu âm. 町 có nghĩa bờ ranh giới giữa các thửa ruộng, đường bờ giữa đồng. Cũng mượn âm chỉ đơn vị hành chính Nhật Bản (町 — machi/chō). Đại triện và tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "bờ ruộng; đinh (đơn vị đo, bằng 100 mẫu)", "Hạng Tần Suất (Jun Da)": "3992.0", "Tần Suất % (Jun Da)": "99.742013109", "GavinGrover_Once (Chiết tự trực tiếp)": "田 + 丁", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰田丁", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "丁", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "田", "Unihan_Simplified (Chữ Giản thể)": "町", "Unihan_Traditional (Chữ Phồn thể)": "町", "Pinyin_Xie": "tīng", "Âm Hán Việt_Xie": "đỉnh, đinh", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Thường dùng làm danh từ chỉ bờ ruộng hoặc làm lượng từ đo diện tích ruộng đất. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('芥', '{"9000": "3993.0", "Chữ Trung Quốc": "芥", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 7 | nét | 艸 | thảo | biểu nghĩa | cỏ, thực vật | 介 | giới | biểu âm | (biểu âm: jiè) | 芥 = 艸/艹 (Thảo, biểu nghĩa: cỏ/thực vật) + 介 (Giới, biểu âm: jiè); chữ hình thanh. Bộ 艹 cho biết đây là loại cây/cỏ, 介 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"giới\": cây (艹) cải giới (芥) — 芥末 là mù tạt vàng cay nồng; 草芥 là cỏ rác, thứ nhỏ nhặt không đáng kể. | Gương Hán-Việt | giới — trong tiếng Việt: 芥末 (giới mạt) là từ Hán-Việt chỉ mù tạt; 草芥 (thảo giới) là cỏ rác. | Mở khoá kiến thức | Biết 芥 giúp hiểu 芥末 (mù tạt/wasabi), 草芥 (cỏ rác, thứ vô nghĩa) và thành ngữ 视如草芥 (coi như cỏ rác).", "Tự nguyên_Xie": "Chữ hình thanh: 艸 (thảo — cỏ) là thành phần biểu nghĩa, 介 (giới) là thành phần biểu âm (jiè). 芥 chỉ cây cải, mù tạt (mustard). Từ nổi tiếng: 芥末 (mù tạt), 草芥 (cỏ rác — thứ nhỏ nhặt vô giá trị), 九牛一毛 类的 沧海一粟 hay được so sánh với 沧海一粟, thành ngữ có 芥 như 视如草芥 (coi như cỏ rác). | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "hạt cải; nhỏ bé", "Hạng Tần Suất (Jun Da)": "3993.0", "Tần Suất % (Jun Da)": "99.7423102605", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 介", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹介", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "介", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "芥", "Unihan_Traditional (Chữ Phồn thể)": "芥", "Pinyin_Xie": "jiè", "Âm Hán Việt_Xie": "giới", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Tính từ | 形容词 | Thường làm danh từ chỉ cây cải hoặc làm tính từ chỉ sự nhỏ nhặt, tầm thường. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('瘠', '{"9000": "3994.0", "Chữ Trung Quốc": "瘠", "Bộ thủ & thành phần_Xie": "Bộ thủ | 疒 | Số nét | 15 | nét | 疒 | nạch | biểu nghĩa | bệnh tật, ốm yếu | 脊 | tích | biểu âm | (biểu âm: jǐ → jí) | 瘠 = 疒 (Nạch, biểu nghĩa: bệnh/ốm yếu) + 脊 (Tích, biểu âm: jǐ); chữ hình thanh. Bộ 疒 cho biết liên quan đến thể trạng ốm yếu, 脊 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"tích\": bệnh (疒) của xương tích (脊) — người gầy trơ xương sống; 瘠薄 là đất cằn cỗi không nuôi được cây. | Gương Hán-Việt | tích — ít dùng riêng trong tiếng Việt; nghĩa là gầy còm, cằn cỗi. | Mở khoá kiến thức | Biết 瘠 giúp hiểu 瘠薄 (đất cằn nghèo), 骨瘠 (gầy trơ xương), 贫瘠 (nghèo nàn cằn cỗi — đất hay vùng thiếu tài nguyên).", "Tự nguyên_Xie": "Lục thư thông | Chữ hình thanh: 疒 (ốm yếu, bệnh tật) là thành phần biểu nghĩa, 脊 (tích — xương sống) là thành phần biểu âm (jí). 瘠 có nghĩa gầy còm, ốm yếu, cằn cỗi; thường dùng cho đất đai cằn cỗi (瘠薄 — đất nghèo dinh dưỡng). Glyph lục thư thông xác nhận. | Theo Wiktionary · độ tin cậy cao · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "gầy, còm", "Hạng Tần Suất (Jun Da)": "3994.0", "Tần Suất % (Jun Da)": "99.7426074119", "GavinGrover_Once (Chiết tự trực tiếp)": "疒 + 脊", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿴ (Cấu trúc Bao quanh/Phức hợp)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴疒脊", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "脊", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "疒", "Unihan_Simplified (Chữ Giản thể)": "瘠", "Unihan_Traditional (Chữ Phồn thể)": "瘠", "Pinyin_Xie": "jí", "Âm Hán Việt_Xie": "tích", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Thường làm tính từ miêu tả người gầy gò hoặc đất đai cằn cỗi, thiếu dưỡng chất. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('阂', '{"9000": "3995.0", "Chữ Trung Quốc": "阂", "Bộ thủ & thành phần_Xie": "Bộ thủ | 門 | Số nét | 9 | nét | 门 | môn | biểu nghĩa | cổng, cửa | 亥 | hợi | biểu âm | giờ Hợi (giờ cuối cùng) | 阂 = 门 (Môn, biểu nghĩa: cổng) + 亥 (Hợi, biểu âm). Dạng phồn thể 閡 = 門+亥. Wiktionary ghi rõ ls=psc (hình thanh): 門 cho nghĩa (ngăn cách bởi cánh cửa), 亥 cho âm hé. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"ngại\": cánh cổng (门) đóng chặt vào giờ Hợi (亥) — ngăn cách, không thể qua lại. | Gương Hán-Việt | \"ngại\" trong 隔阂 (cách ngại — sự xa cách, rào cản tâm lý) | Mở khoá kiến thức | Biết 阂 mở khoá 隔阂 (rào cản tâm lý, sự xa cách), 语言隔阂 (hàng rào ngôn ngữ).", "Tự nguyên_Xie": "Tiểu triện | Chữ 阂 (ngại), phồn thể 閡, là chữ hình thanh (ls=psc): bộ 門 (Môn — cổng, cánh cửa) biểu nghĩa, gợi ý sự ngăn cách; 亥 (Hợi) biểu âm hé. Nghĩa gốc: bị ngăn cách, bị chia cắt. Tiểu triện được lưu lại. Thường gặp trong 隔阂 (sự xa cách, rào cản giữa người với người). | Theo Wiktionary · độ tin cậy cao · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khác biệt; ngăn chặn; vùi lấp", "Hạng Tần Suất (Jun Da)": "3995.0", "Tần Suất % (Jun Da)": "99.7429040466", "GavinGrover_Once (Chiết tự trực tiếp)": "门 + 亥", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿵ (Bao quanh phía trên)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿴门亥", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "亥", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "门", "Unihan_Simplified (Chữ Giản thể)": "阂", "Unihan_Traditional (Chữ Phồn thể)": "閡", "Pinyin_Xie": "hé", "Âm Hán Việt_Xie": "ngại", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Danh từ | 名词 | Thường kết hợp với các chữ khác để tạo thành danh từ chỉ sự ngăn cách, bất đồng. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('挎', '{"9000": "3996.0", "Chữ Trung Quốc": "挎", "Bộ thủ & thành phần_Xie": "Bộ thủ | 手 | Số nét | 9 | nét | 扌 | thủ | biểu nghĩa | tay | 夸 | khoa | biểu âm | khoác lác, khoe khoang | 挎 = 扌 (Thủ, biểu nghĩa: tay) + 夸 (Khoa, biểu âm). Wiktionary ghi rõ ls=psc (hình thanh): 手 (扌) cho nghĩa, 夸 cho âm kuà. Chữ hình thanh điển hình.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"khoá\": dùng tay (扌) khoác (夸-khoa) túi lên vai — hành động đeo, mang theo bên người. | Gương Hán-Việt | \"khoá\" ít dùng độc lập; 挎 gặp trong 挎包 (túi đeo vai), 挎篮子 (xách giỏ) | Mở khoá kiến thức | Biết 挎 mở khoá 挎包 (túi đeo vai), 挎篮 (xách giỏ), 挎枪 (mang súng bên hông).", "Tự nguyên_Xie": "Chữ 挎 (khoá) là chữ hình thanh (ls=psc): bộ 手 (扌 — Thủ) biểu nghĩa chỉ hành động tay; 夸 (Khoa) biểu âm kuà. Nghĩa gốc: khoác túi/đồ lên cánh tay, đeo ngang hông. Chưa tìm thấy hình giáp cốt hay kim văn — chữ xuất hiện muộn hơn trong lịch sử. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "khoác, đeo, mang theo", "Hạng Tần Suất (Jun Da)": "3996.0", "Tần Suất % (Jun Da)": "99.7432006812", "GavinGrover_Once (Chiết tự trực tiếp)": "扌 + 夸", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰扌夸", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "夸", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "扌", "Unihan_Simplified (Chữ Giản thể)": "挎", "Unihan_Traditional (Chữ Phồn thể)": "挎", "Pinyin_Xie": "kuà", "Âm Hán Việt_Xie": "khoá", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ đứng trước danh từ chỉ đồ vật được đeo hoặc khoác trên người. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "Nghĩa & cách dùng như một từ | / | kuà | / | mang trên cánh tay | Xuất hiện trong lộ trình | HSK | HSK 6 | · | Động từ hàng ngày | New HSK | New HSK 7-9 | · | Từ III", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('橇', '{"9000": "3997.0", "Chữ Trung Quốc": "橇", "Bộ thủ & thành phần_Xie": "Bộ thủ | 木 | Số nét | 16 | nét | 橇 | kiều | tượng hình | xe trượt tuyết, xe trượt bùn | 橇 không có phân tích thành phần rõ ràng từ Wiktionary. Nhìn tổng thể có thể chứa bộ 木 (mộc — gỗ), phù hợp với nghĩa xe gỗ trượt; nhưng cấu trúc không được xác nhận học thuật.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"kiều\": cầu kiều — xe (橇) như chiếc cầu (kiều) nối qua tuyết trắng; 雪橇 là xe trượt tuyết kéo bởi tuần lộc. | Gương Hán-Việt | kiều — ít dùng riêng trong tiếng Việt; biết qua 雪橇 (tuyết kiều — xe trượt tuyết). | Mở khoá kiến thức | Biết 橇 giúp hiểu 雪橇 (xe trượt tuyết — xuất hiện nhiều trong văn học mùa đông và dịch thuật).", "Tự nguyên_Xie": "Wiktionary ghi nhận 橇 có nghĩa xe trượt bùn (lịch sử) và xe trượt tuyết (hiện đại). Có thể chứa bộ 木 (gỗ) là biểu nghĩa — xe làm bằng gỗ để trượt trên tuyết hay bùn. Chưa có nguồn học thuật xác nhận cấu trúc. Từ phổ biến: 雪橇 (xe trượt tuyết). | Suy từ bộ phận cấu thành · độ tin cậy thấp", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "một thứ đồ đi trên bùn, hình như cái sọt, hai đầu vểnh lên, một chân quỳ vào trong, một chân đẩy đi", "Hạng Tần Suất (Jun Da)": "3997.0", "Tần Suất % (Jun Da)": "99.7434973159", "GavinGrover_Once (Chiết tự trực tiếp)": "木 + 毳", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰木毳", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "毳", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "木", "Unihan_Simplified (Chữ Giản thể)": "橇", "Unihan_Traditional (Chữ Phồn thể)": "橇", "Pinyin_Xie": "qiāo", "Âm Hán Việt_Xie": "khiêu", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Thường dùng làm danh từ chỉ các loại xe trượt tuyết hoặc công cụ di chuyển đặc biệt. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('荟', '{"9000": "3998.0", "Chữ Trung Quốc": "荟", "Bộ thủ & thành phần_Xie": "Bộ thủ | 艸 | Số nét | 9 | nét | 荟 | hội | tượng hình | sum họp, tụ tập um tùm | 荟 không có phân tích thành phần rõ ràng từ Wiktionary. Có bộ 艹 (thảo — cỏ/thực vật) nhưng cấu trúc đầy đủ không được xác nhận học thuật. Dùng với nghĩa sum họp, tụ hội, cây cỏ um tùm; thường gặp trong 荟萃 (hội tụ tinh hoa).", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"hội\": cỏ cây (艹) hội (hội) tụ rậm rạp — 荟萃 là tinh hoa hội tụ, tài năng sum vầy từ khắp nơi. | Gương Hán-Việt | hội — trong tiếng Việt: 荟萃 (hội tụy) là từ Hán-Việt chỉ sự tập hợp tinh hoa, nhân tài. | Mở khoá kiến thức | Biết 荟 giúp hiểu 荟萃 (hội tụy/hội tụ tinh hoa) — từ hay dùng trong văn học, diễn thuyết và tên sự kiện.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary không cung cấp phân tích hội ý hay hình thanh rõ ràng cho 荟. Glyph tiểu triện xác nhận. 荟 có nghĩa cây cỏ tươi tốt um tùm (văn ngữ) và hội tụ (phổ biến hơn). Từ quan trọng: 荟萃 (hội tụ tinh hoa — người tài từ khắp nơi tụ họp). Chưa có nguồn học thuật. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Hán tự nguyên", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "cây cỏ um tùm", "Hạng Tần Suất (Jun Da)": "3998.0", "Tần Suất % (Jun Da)": "99.7437939506", "GavinGrover_Once (Chiết tự trực tiếp)": "艹 + 会", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿱ (Trên - Dưới)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿱艹会", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "会", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "艹", "Unihan_Simplified (Chữ Giản thể)": "荟", "Unihan_Traditional (Chữ Phồn thể)": "薈", "Pinyin_Xie": "huì", "Âm Hán Việt_Xie": "hội, oái", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Tính từ | 形容词 | Động từ | 动词 | Thường dùng trong từ ghép để chỉ sự quy tụ của những người hoặc vật xuất chúng. | Tính từ | 形容词 | Miêu tả tính chất. Làm vị ngữ thì KHÔNG cần 是 — 他很高, không nói 他是高. Thường đi với 很 / 非常 / 太. Làm định ngữ thì thêm 的: 漂亮的花. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('啜', '{"9000": "3999.0", "Chữ Trung Quốc": "啜", "Bộ thủ & thành phần_Xie": "Bộ thủ | 口 | Số nét | 11 | nét | 口 | khẩu | biểu nghĩa | miệng | 叕 | xuất | biểu âm | (biểu âm: zhuó → chuò) | 啜 = 口 (Khẩu, biểu nghĩa: miệng) + 叕 (biểu âm: zhuó); chữ hình thanh. Bộ 口 cho biết liên quan đến hành động miệng, 叕 chỉ âm đọc.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"xuýt\": miệng (口) xuýt xoa (叕) từng ngụm nhỏ — 啜 là nhấp từng hớp trà nóng, hay 啜泣 là nức nở khóc thầm. | Gương Hán-Việt | xuýt — ít dùng riêng trong tiếng Việt; nghĩa nhấp nhỏ, húp, nức nở. | Mở khoá kiến thức | Biết 啜 giúp hiểu 啜泣 (nức nở khóc thầm) và 啜饮 (nhấp từng ngụm) — cả hai đều gặp trong văn học.", "Tự nguyên_Xie": "Chữ hình thanh: 口 (khẩu — miệng) là thành phần biểu nghĩa, 叕 là thành phần biểu âm. 啜 có nghĩa nhấp từng ngụm nhỏ, húp (canh, trà); cũng có nghĩa văn ngữ là khóc nức nở (啜泣). Glyph tiểu triện xác nhận. | Theo Wiktionary · độ tin cậy cao", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "(xem: bô xuyết 餔啜)", "Hạng Tần Suất (Jun Da)": "3999.0", "Tần Suất % (Jun Da)": "99.7440905852", "GavinGrover_Once (Chiết tự trực tiếp)": "口 + 叕", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰口叕", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "叕", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "口", "Unihan_Simplified (Chữ Giản thể)": "啜", "Unihan_Traditional (Chữ Phồn thể)": "啜", "Pinyin_Xie": "chuài", "Âm Hán Việt_Xie": "xuyết", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Động từ | 动词 | Thường làm động từ biểu thị hành động ăn uống hoặc khóc nức nở. | Động từ | 动词 | Chỉ hành động hoặc trạng thái, làm vị ngữ. Phủ định bằng 不 (thói quen, ý muốn) hoặc 没 (đã xảy ra). Không chia thì — dùng 了 / 着 / 过 để diễn đạt. Lặp lại (看看) làm ngữ khí nhẹ đi.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
INSERT INTO characters (char, data) VALUES ('垛', '{"9000": "4000.0", "Chữ Trung Quốc": "垛", "Bộ thủ & thành phần_Xie": "Bộ thủ | 土 | Số nét | 9 | nét | 垛 | đóa | tượng hình | chồng đống, lô cốt bắn | 垛 không có phân tích thành phần rõ ràng từ Wiktionary. Có bộ 土 (thổ — đất) có thể là biểu nghĩa, nhưng cấu trúc đầy đủ không được xác nhận. Dùng với nghĩa chồng/xếp đống, và lô cốt bắn trên tường thành.", "Hán Việt_Xie": "Mẹo nhớ | Hán-Việt \"đóa\": đóng (đóa) chồng lên nhau — 垛 là đống chất liệu xếp cao, hay lô cốt bắn nhô ra trên tường thành cổ. | Gương Hán-Việt | đóa — ít dùng riêng trong tiếng Việt; nghĩa chồng đống, xếp chất. | Mở khoá kiến thức | Biết 垛 giúp hiểu 垛子 (lô cốt trên tường thành), 垛积 (chất đống) và đơn vị đếm đống chất liệu trong tiếng Trung.", "Tự nguyên_Xie": "Tiểu triện | Wiktionary ghi nhận 垛 có nghĩa chồng đống (xếp lên nhau), đống (chất liệu), và lô cốt bắn trên tường thành. Glyph tiểu triện xác nhận. Có thể chứa bộ 土 (đất) là biểu nghĩa nhưng không có nguồn học thuật xác nhận. | Suy từ bộ phận cấu thành · độ tin cậy thấp · ảnh từ Wikimedia", "ChuNhoTongHop_STT (Giáo trình Chữ Nho)": "", "ChuNhoTongHop_LinhKien (Cấu tạo linh kiện)": "", "ChuNhoTongHop_Chietyu_Giaithich (Chiết tự & Giải thích)": "", "Nghĩa Tiếng Việt_Xie": "ụ đất, gò, đống", "Hạng Tần Suất (Jun Da)": "4000.0", "Tần Suất % (Jun Da)": "99.7443867031", "GavinGrover_Once (Chiết tự trực tiếp)": "土 + 朵", "GavinGrover_IDC (Ký hiệu & Cấu trúc không gian)": "⿰ (Trái - Phải)", "CHISE_IDS (Chuỗi Chiết tự Không gian Unicode)": "⿰土朵", "CHISE_Phonetic_Component (Thanh phù - Chỉ Âm)": "朵", "CHISE_Semantic_Component (Hình phù - Chỉ Ý)": "土", "Unihan_Simplified (Chữ Giản thể)": "垛", "Unihan_Traditional (Chữ Phồn thể)": "垛", "Pinyin_Xie": "duǒ", "Âm Hán Việt_Xie": "đóa", "Loại từ & Cách dùng_Xie": "Loại từ & cách dùng | Danh từ | 名词 | Lượng từ | 量词 | Chữ này thường làm danh từ chỉ ụ đất hoặc làm lượng từ cho các vật chất thành đống như củi, rơm. | Danh từ | 名词 | Chỉ người, sự vật, nơi chốn. Làm chủ ngữ hoặc tân ngữ. Muốn đếm phải có số từ kèm lượng từ đứng trước — 三本书, không nói 三书. | Lượng từ | 量词 | Đứng giữa số từ (hoặc 这/那) và danh từ: 一杯茶, 这本书. Mỗi danh từ đi với lượng từ riêng; 个 là lượng từ dùng chung phổ biến nhất.", "Nghĩa & Cách dùng như một từ_Xie": "", "App_Mnemonic": "", "App_Comp_1": "", "App_Comp_2": "", "App_Comp_3": "", "App_Comp_4": "", "App_Comp_5": "", "App_Comp_6": "", "App_Comp_7": "", "App_Comp_8": "", "App_Comp_9": "", "App_Comp_10": "", "App_Comp_11": "", "App_Comp_12": ""}');
